%% cocolog -- library(reasoning/translate): a language lesson as a knowledge
%% base, and a translation as a proof over it.
%%
%%     :- use_module(library(reasoning/translate)).
%%
%%     ?- reason_learn('Spanish is a language.
%%                      The noun "casa" means "house". The adjective "grande" means "big".
%%                      The verb "es" means "is". The feminine article "la" means "the".
%%                      Every noun that ends in "a" is feminine.
%%                      Every adjective follows the noun.
%%                      Every noun that ends in a vowel takes "s" in the plural.
%%                      Every article that ends in a vowel takes "s" in the plural.
%%                      Every adjective that ends in a vowel takes "s" in the plural.
%%                      "son" is the plural of "es". "era" is the past of "es".
%%                      The word "no" means "not".'),
%%        reason_translate('The houses were not big.', S),
%%        reason_translate(S, E).
%%     S = 'Las casas no eran grandes.',
%%     E = 'The houses were not big.'
%%
%% TIER 2, clauses only, over library(reasoning/reason). NOTHING HERE KNOWS
%% A WORD OF SPANISH. The lesson is the controlled English -- a word in
%% quotation marks is MENTIONED and stands for itself, `the noun "casa"'
%% says what it is, `every noun that ends in "a" is feminine' is a rule --
%% read by reason_text/2 and asserted by reason_learn/1; and what this
%% library knows is WHAT TO ASK. The questions, and the lesson's facts and
%% rules answer them however the lesson put them:
%%
%%     mean(W, E)                      the lesson's word W means the English word E,
%%                                     a verb in the third person singular (`eats')
%%     noun(W)  adjective(W)  verb(W)  article(W)  possessive(W)  pronoun(W)
%%     preposition(W)  adverb(W)  number(W)  conjunction(W)  auxiliary(W)
%%                                     what a word is (`The noun "casa" means "house"')
%%     feminine(W)  masculine(W)       its gender, said of it or ruled
%%     follow(A, noun)                 the adjective A stands after its noun
%%     precede(P, verb)                the object pronoun P stands before the verb
%%     plural_of(P, W)                 P is the plural of W, said (`"los" is the plural of "el"')
%%     take_in(W, E, plural)           or ruled: W takes the ending E in the plural
%%     past_of(P, F)  future_of(P, F)  P is the past, the future, of the form F, said
%%     take_in(F, E, past)  take_in(F, E, future)      or ruled by an ending
%%     participle_of(P, F)             the participle, for the perfect (`"comido" is the participle of "come"')
%%     person_of(P, F)  first(P)  second(P)   the first and the second person of the form F
%%                                     (`"como" is the first person of "come"'); the third is the form
%%     mean(N, not)  follow(N, verb)   the word that denies, and whether it stands after the verb
%%     precede(W, person)  person(N)   the word that stands before a person as the object
%%                                     (`The word "a" precedes the person'), and which nouns
%%                                     are persons (`"amigo" is a person'); a name is one
%%     contraction_of(C, W)            a contraction and its words (`"al" is the contraction of "a el"')
%%     conditional_of(C, F)            the conditional of the form F (`"comería" is the conditional of "come"');
%%                                     English's is `would' and the base, `could', `might'
%%     infinitive_of(I, F)  gerund_of(G, F)   the infinitive and the gerund of F (`"comer" is the
%%                                     infinitive of "come"', `"comiendo" is the gerund of "come"');
%%                                     English's are `to' and the base, and the base and -ing
%%     modal(M)  mean(M, can)          a modal and the English one it means (`The modal "puede"
%%                                     means "can"'): a base form follows it bare
%%     auxiliary(A)  mean(A, is)       the auxiliary of the progressive (`The auxiliary "está"
%%                                     means "is"'), with a gerund after it; the one that means
%%                                     `has' is the perfect's
%%     demonstrative(D)  determiner(D)  `The masculine demonstrative "este" means "this"', `The
%%                                     determiner "cada" means "each"': a word in the article's
%%                                     place, agreeing like one; English's own are this and these,
%%                                     that and those, another and other, much and many
%%     pronoun(P)  mean(P, this)       a pronoun that stands alone (`The pronoun "esto" means
%%                                     "this"', `... "nadie" means "nobody"'): a subject or an
%%                                     object of the third person, after the verb
%%     mean(H, 'there is')             the verb of `there is' (`The verb "hay" means "there is"')
%%     mean(Q, what)  mean(Q, who)  mean(Q, where)  mean(Q, when)  mean(Q, which)   the question words
%%     begin(M, question)              the mark a question begins with (`The mark "¿" begins the question')
%%     elision_of(E, W)                the form W wears before a vowel (`"l'" is the elision of
%%                                     "lo"'): read as W wherever it stands, and written in
%%                                     W's place, joined to the word after it
%%     impersonal(P)  pronoun(P)  mean(P, one)     the pronoun of a sentence that names nobody
%%                                     (`The impersonal pronoun "si" means "one"'): a subject
%%                                     of the third person singular, which English writes `one'
%%     imperative_of(I, F)  negative(I)   the imperative of the form F (`"come" is the
%%                                     imperative of "come"'), and the NEGATIVE one said
%%                                     with the adjective (`"comas" is the negative
%%                                     imperative of "come"'): every language that has
%%                                     both builds the second on a different form --
%%                                     Spanish on its subjunctive, Italian on its
%%                                     infinitive -- and this asks for it by name
%%     subjunctive_of(S, F)  past(S)  the subjunctive of the form F (`"domini" is the
%%                                     subjunctive of "domina"'), the past one said with
%%                                     the adjective (`"dominasse" is the past subjunctive
%%                                     of "domina"', which is subjunctive_of and past both):
%%                                     read as the tense it stands for, and written back
%%                                     as the indicative
%%     intransitive(W)                 the verb takes no object (`"domina" is intransitive'),
%%                                     which is what lets a fronted adjunct put the subject
%%                                     after the verb (`Qui dominava il coprifuoco')
%%     remark(J)                       the two words that comment on a clause after a comma
%%                                     (`"lo que" is a remark.', `"il che" is a remark.'):
%%                                     English's `which'
%%     mean_as(V, E, clausal)          what a verb means before a clause of `that', its first
%%                                     meaning being another (`The clausal verb "supone" means
%%                                     "supposes".': `supongo que', and `represents' anywhere
%%                                     else, the first meaning the lesson gives)
%%     mean_as(V, E, infinitival)      what a verb means before an infinitive, its first meaning
%%                                     being another (`The infinitival verb "trata" means
%%                                     "tries".': `trata de comer' tries to eat)
%%     mean_as(A, E, adjectival)       what an adverb means before an adjective or a participle
%%                                     (`The adjectival adverb "justamente" means "justly".':
%%                                     `justamente retribuidos', and `precisely' anywhere else)
%%     take_before(V, P, phrase)       the word a verb takes before a phrase it governs
%%                                     (`"depende" takes "de" before the phrase', Italian's
%%                                     `"dipende" takes "da" before the phrase'), each language
%%                                     writing its own for the other's: `dipende da', `depende de'
%%     city(N)  institution(W)         a name that is a city (`"Tarragona" is a city'), which
%%                                     a language that says `a' for a city and `in' for a
%%                                     country writes with the word for `to' where English
%%                                     says `in'; and a noun a newspaper capitalises with no
%%                                     article after a preposition (`"estado" is an
%%                                     institution'), a common noun there and no name
%%     conjunction(C)  mean(C, that)   the word that opens a subordinate clause
%%                                     (`The conjunction "che" means "that"')
%%     relative(R)  follow(R, preposition)   a relative word (`"que" is a relative'), and the
%%                                     one that stands after a preposition (`The word "cui"
%%                                     follows the preposition'); where none does, the
%%                                     preposition and the article that agrees (`al que')
%%     begin(M, moment)                the word that says, with an infinitive, WHEN a thing was
%%                                     done (`The word "al" begins the moment'); a language with
%%                                     no such word writes the gerund
%%     begin(M, infinitive)            the word that stands before a verb's infinitive where
%%                                     English puts `to' (`The word "di" begins the infinitive');
%%                                     a language with no such word reads a bare infinitive only
%%     replace(A, noun)                the article that stands for a noun the sentence left out
%%                                     (`The word "el" replaces the noun': `el de los chicos');
%%                                     where no article does, the pronoun that means `that'
%%     come_before(A, P)               the article's form before a word that begins with P or a
%%                                     vowel (`The article "lo" comes before "sc"')
%%     take(A, possessive)             the article a possessive is written with (`The article
%%                                     "il" takes the possessive': `il suo')
%%     auxiliary_of(A, V)              the perfect's auxiliary where it is not the one meaning
%%                                     `has': of a verb (`"è" is the auxiliary of "esce"'), of
%%                                     the reflexive, of the copula (`"ha" is the auxiliary of
%%                                     "es"'); after a copula the participle agrees
%%     reflexive(V)                    the verb's reflexive word is its own (`"equivoca" is
%%                                     reflexive'), so `se' before it names no subject
%%     follow(I, pronoun)              the impersonal word stands after the object pronouns
%%                                     (`The word "si" follows the pronoun': `li si chiamerà')
%%     language(L)                     the language, `Spanish is a language'
%%
%% A WORD OF SEVERAL WORDS IS ONE WORD wherever a lesson says so -- `The
%% preposition "junto a" means "along with"', `The masculine noun "lavado de
%% cerebro" means "brainwashing"' -- read as one on the lesson's side, the
%% longest first. And a meaning is kept WITH ITS CLASS (mean_as/3, derived
%% as the lesson is learned), so `culpable' is `guilty' where an adjective
%% stands and `culprit' where a noun does.
%%
%% So a lesson in Italian, or one whose rule is `Every adjective precedes
%% the noun', is read by the same clauses -- and a lesson written as Prolog
%% facts in those shapes works with no sentence of English at all. What
%% the translator knows on its own is ENGLISH, the library's language: its
%% articles, possessives and pronouns, the copula in every person and
%% tense (`am', `are', `was', `were'), `does', `do', `did', `will', `has',
%% `have' and `had' as the words that front a question and carry a denial
%% or a tense, `not', `an' before a vowel and no `a' in the plural, a
%% plural noun by -s, -es or -ies and a past by -ed unless the lesson says
%% otherwise (`"children" is the plural of "child"', `"ate" is the past of
%% "eats"', `"eaten" is the participle of "eats"'), and its question words.
%%
%% ---- THE SURFACE ------------------------------------------------------
%%
%%     reason_translate(+Text, -Translation)
%%         SIMPLE sentences, each a subject, a verb, and after it an object,
%%         an adjective, a place or a time (`in the house', `with Omar'),
%%         an adverb, an infinitive (`wants to sleep', `can sleep'), or
%%         nothing. A subject or an object is a name, a pronoun, a phrase
%%         -- an article, a possessive, a demonstrative or a determiner,
%%         a number, adjectives, a noun -- or two of those joined by
%%         `and'. The verb is in the present, the past, the future or the
%%         conditional (`would eat'), simple, perfect (`has eaten', `had
%%         eaten') or progressive (`is eating', `was eating'), a modal
%%         (`can', `could', `may', `must', `should') with its verb after
%%         it, denied or not, in any person; and `there is' and `there
%%         are' with what there is (`There is a dog in the house', `There
%%         are no dogs'). A
%%         statement, or a QUESTION when the sentence ends in `?': yes or
%%         no, `what' asking for the object, `who' for the subject, `whom'
%%         for a person as the object, `where' and `when' for a place or a
%%         time, `which' with its noun for either. From English into the
%%         language a lesson teaches, or
%%         from it into English: which way, and which language when several
%%         lessons are loaded, the words say. Translation is an atom, a
%%         sentence capitalised and ending as it ended. FAILS for a
%%         sentence it cannot translate, whole and never half: a word the
%%         lesson gives no meaning (a capitalised one is a name and passes
%%         through), no verb, a form the lesson gives no rule or fact for,
%%         a number in digits, a word in quotation marks, or two languages
%%         the English words fit equally; reason_untranslated/2 names the
%%         words.
%%
%%     reason_translate(+Text, +Into, -Translation)
%%         The same, Into naming the language: english, or the name the
%%         lesson gave its own (`Spanish is a language.' is language(spanish),
%%         so `spanish') or was learned under (reason_learn/3). Any other
%%         name is a domain_error.
%%
%%     reason_translate(+Text, +From, +Into, -Translation)
%%         BETWEEN TWO LANGUAGES, through the intermediate representation:
%%         Italian into Spanish with no English sentence written and none
%%         read. From and Into are languages as Into is above, `english'
%%         among them, and From may be `any' to let the words vote for
%%         one. Both lessons must be in the knowledge base this proves
%%         against, each learned under its own name.
%%
%%     reason_languages(-Languages)
%%         Every language this process can read or write: `english', the
%%         pivot, and each lesson learned under a name -- with `none' for
%%         a lesson learned plain. ADDING A LANGUAGE IS ADDING ITS LESSON;
%%         nothing here is written per pair.
%%
%%     reason_ir(+Text, -IRs)
%%     reason_ir(+Text, +From, -IRs)
%%         The text into the intermediate representation, sentence by
%%         sentence: a list of ir(Sentence, Stop) where Sentence is the
%%         term below and Stop the code the sentence ended on. Fails on a
%%         sentence it cannot read.
%%
%%     reason_ir_text(+IRs, +Into, -Text)
%%         And back out of it, into any language. So one reading serves
%%         every target, and a page read once is written as many times as
%%         there are languages.
%%
%%     reason_translate_page(+Text, +From, +Into, -Lines)
%%         A page between two languages, each sentence its own as
%%         reason_translate_page/2,3 gives it.
%%
%%     reason_untranslated(+Text, -Words)
%%     reason_untranslated(+Text, +From, -Words)
%%         The words of the text no lesson gives a meaning, names and
%%         English's own function words left out; [] when every word is
%%         known.
%%
%%     reason_translate_page(+Text, -Lines)
%%     reason_translate_page(+Text, +Into, -Lines)
%%         A page: every sentence of the text on its own, as a list of
%%         Sentence-Translation, or Sentence-refused(Words) for one this
%%         does not translate, Words as reason_untranslated/2 names them.
%%         The page is never refused whole for one sentence in it.
%%
%%     reason_learn(+Text, +Language, -Terms)
%%         reason_text/2, and every term asserted UNDER THE LANGUAGE: the
%%         translator proves them as if they were plain, and two lessons
%%         so learned share nothing -- `casa' may be feminine in one and
%%         its plural `case' in the other. A lesson learned plain
%%         (reason_learn/1) is the language with no name, and
%%         reason_ask/2 can question it; a lesson learned under a name is
%%         the translator's alone.
%%
%%         A FACT IS HELD IN THE LANGUAGE'S OWN NAMESPACE --
%%         'spanish:mean'(casa, house) -- and a rule in lesson/2, because
%%         a rule's body must be proved through the lesson rather than by
%%         the engine. Nothing outside this file should name either
%%         shape: reason_lesson/2 reads and reason_unlearn/1 forgets.
%%
%%     reason_lesson(?Language, ?Term)
%%         What a named lesson holds, term by term, as reason_learn/3 was
%%         given them. Nondeterministic in both arguments.
%%
%%     reason_unlearn(+Language)
%%         Take a named lesson out again, whole. A lesson learned plain is
%%         not one, and is untouched.
%%
%% ---- THE INTERMEDIATE REPRESENTATION -------------------------------------
%%
%% EVERY LANGUAGE HAS TWO HALVES AND NO PAIR HAS ANY: a sentence is read
%% INTO the IR on its own language's side and written FROM the IR into
%% whichever language is asked for, so three languages are three lessons
%% and not six paths, and a fourth is a fourth lesson.
%%
%%     ir(s(Asked, Subject, g(Lexeme, Tense, Aspect, Denied), Complements), Stop)
%%
%% is the whole of it -- the same term the reader builds, with the words
%% in it ENGLISH. `Il cane non mangia il pane.' reads as
%%
%%     s(none, np(det(article, the, w(the, lower)), none, [], w(dog, lower), singular),
%%       g(eats, present, simple, yes),
%%       [obj(np(det(article, the, w(the, lower)), none, [], w(bread, lower), singular))])
%%
%% and that one term writes as `Il cane non mangia il pane.', `The dog
%% does not eat the bread.' and `El perro no come el pan.'
%%
%% WHAT TRAVELS EXACTLY IS THE SHAPE: the tense, the aspect, the denial,
%% the person, the number, what a question asks for, and every complement
%% in its place. What travels THROUGH ENGLISH is the vocabulary, and it
%% can be nothing else -- a lesson says what a word means only as
%% mean(Word, EnglishWord), so English is the one language every lesson
%% is written against. A sense English does not separate is a sense the
%% IR cannot separate, and a word one lesson gives that the other does
%% not refuses the sentence with that word named, as ever.
%%
%% ENGLISH IS THEREFORE ALREADY THE IR, which is what a pivot means: a
%% sentence read on the English side needs no crossing at all, and its
%% words stay as the text wrote them (`houses') where a crossed word is
%% the lexeme its meaning gave (`house', with the number beside it).
%% Both are English words and both write out the same, because every
%% consumer takes the lexeme first.
%%
%% The two halves are tr_into_ir/4 and tr_from_ir/5, and the crossing
%% walk tr_cross/3 between them makes exactly the lookups the writer
%% into English makes -- over the term, once, rather than over the words
%% coming out of it.
%%
%% ---- HOW A SENTENCE IS TRANSLATED ----------------------------------------
%%
%% A sentence is READ to one shape and WRITTEN from it: a subject, a verb
%% group (the lexeme, its tense, simple or perfect or progressive, passive,
%% a gerund or an imperative, denied or not), and the complements in order -- an object, a
%% predicative adjective, what the verb predicates OF its object
%% (`definire illegale la decisione', which the lesson's language writes
%% before the object and English after it), a prepositional phrase, the
%% agent of a passive, an infinitive, an infinitive of purpose, a
%% subordinate clause after the word that means `that', an object
%% pronoun, an adverb, a gerund that says how the thing was done, and
%% the lesson's word for the moment with an infinitive (`al acusar').
%% Several clauses in one sentence are a join, a comma, a semicolon or a
%% connecting word between two of these.
%%
%% A PHRASE CARRIES WHAT HANGS ON IT: a relative clause with its own
%% pronoun, for the subject, the object or a preposition's object (`el
%% grupo al que pertenece', rc(Phrase, Role, Clause)); two or more
%% phrases joined, a comma between the first ones (`pan, caldo y sopa');
%% a name between commas after it (`el ministro, Jean-Pierre
%% Chevènement,'); an adverb before one of its adjectives (`tan
%% pacífica'); and an adjective the source set BEFORE its noun where the
%% lesson's rule puts it after, which keeps its place in a language with
%% the same rule (`una paradossale educazione'). A phrase whose noun was
%% LEFT OUT is an article with adjectives (`el más débil') or with a `de'
%% phrase (`el de los chicos'), the article's gender standing for the
%% noun's. What has no verb reads in two places only: an exclamation
%% (`¡Atención al veneno!'), and after a semicolon the clause that leaves
%% out the verb of the one before it (`el gato, la sopa').
%%
%% AN IMPERATIVE HAS NO SUBJECT AND NAMES ONE ANYWAY -- the person spoken
%% to. It is read LAST, so a bare third person that was refused before is
%% all that changes, and only a form the lesson CALLS an imperative reads
%% as one: `Come el pan.' is `Eat the bread.' where `Comía el pan.' is a
%% subject nobody named (below). The cost of that is the other half of the same rule --
%% where a language spells the imperative like its third person the
%% sentence is genuinely ambiguous, and the imperative is the reading
%% taken, because it is the one that names its subject. A pronoun JOINED
%% to an affirmative command is the clitic it is (`correggetemi',
%% `Comelo.') and is written back joined; the accent Spanish puts where the
%% stress moves (`Cómelo') is no rule a lesson states, so none is written.
%%
%% THREE SHAPES PUT THE SUBJECT SOMEWHERE ELSE, or leave it out. A verb
%% the lesson calls INTRANSITIVE, with an adverb or a prepositional
%% phrase before it and nothing else, takes the phrase after it as its
%% SUBJECT (`Qui dominava il coprifuoco'); a PARTICIPLE at the head with
%% a phrase after it is a headline, read as the passive it leaves the
%% copula out of (`Evacuata la Tate Gallery.'); and a GERUND at the head
%% is a clause with no subject of its own, hung off the clause before it
%% by the comma join (`..., escludendo che il militare voleva ...').
%% Every one of them is written back in the statement's own order, with
%% the copula put back: what is lost is an emphasis or a typography, and
%% never a claim. A question is first
%% put in the statement's order: English's fronted `does', `did', `will',
%% `has' or copula goes back behind the subject, and in the lesson's
%% language a verb that came first takes the subject after it (`¿Come el
%% perro el pan?', `¿Es grande la casa?'); the question word is kept
%% aside with what it asks for, and `which' takes its noun phrase with it.
%%
%% Each word is looked up, mean(W, E) read from whichever side the word is
%% on, and a form is taken apart into its LEXEME -- the form the lesson
%% gave -- and what was done to it: the number (a stated plural, or the
%% ending its rule gives; in English -s, -es, -ies), the tense (a stated
%% past or future, or an ending; in English -ed, `was', `were', `had'),
%% the person (a stated first or second person of that form). Going the
%% other way the same steps are taken in turn -- number, tense, person --
%% and a form no fact or rule gives refuses the sentence. The perfect is
%% the auxiliary the lesson names (`The auxiliary "ha" means "has"') in
%% the subject's person and number and the participle the lesson stated;
%% English's is `has', `have' or `had' and a stated participle or the
%% regular past.
%%
%% The subject sets the person and the number: a name is third singular,
%% a pronoun what it is, two subjects joined are plural. A phrase is an
%% article, a possessive or a number -- a possessive AFTER an article
%% being the determiner, which a lesson that says `The article "il" takes
%% the possessive' writes with the article back in front (`la sua casa',
%% `su casa') -- then its content: the noun is the
%% word the lesson calls one (failing that the last word in English and,
%% where adjectives follow the noun, the first), and every other word is
%% an adjective; the noun's number is the phrase's. A phrase whose content
%% is CAPITALISED WORDS NO LESSON KNOWS is a name -- `la Tate Gallery', `la
%% Sidoti', which Italian writes far more often than English does -- and
%% there the ARTICLE says what the name cannot: its number, and its gender,
%% which travels in the IR so the other language agrees with it. Where the target is
%% the lesson's language the article, the possessive and each adjective
%% are chosen among the words the lesson gives for the English one by the
%% gender of the noun -- one of the noun's gender first, one with no
%% gender next, the first otherwise -- and put in the number; an
%% adjective goes after its noun when follow(A, noun) proves; an object
%% pronoun goes before the verb when precede(P, verb) proves, English's
%% own object pronouns after it. The word the lesson puts before a person
%% (`The word "a" precedes the person') goes before an object that is one
%% -- a name, a phrase whose noun the lesson calls a person, `whom' --
%% and read on the lesson's side, that word with a person after it and no
%% object before it IS the object (`Maria ve a Omar'), after an object
%% the preposition it is (`da el libro a Omar'); `whom' is `who' asked for
%% as the object, and a lesson need give no word for it. A contraction
%% the lesson states (`"al" is the contraction of "a el"') is read as its
%% words and written back as itself. A sentence of the lesson's language
%% with no subject takes the pronoun its verb says -- I, you, we, they;
%% and a third person SINGULAR is a subject nobody named, null(third,
%% singular), which the lesson's language writes as it came and English,
%% which must choose he, she or it, refuses --
%% and the denial's word goes before the verb, or after it when
%% follow(N, verb) proves. A capitalised word no lesson knows is a name
%% and passes through; the head of a sentence goes lower when it is a
%% word the lesson knows, because a question moves it.
%%
%% ---- WHAT IT IS NOT ---------------------------------------------------
%%
%% It is not a translator of prose. What it has is one clause with one
%% verb and its complements, several such joined by a comma or a
%% connecting word, a passive with its agent, a reduced relative (a
%% participle after a noun), an infinitive of purpose, an adjective in
%% the comparative or the superlative, a subordinate clause after `that',
%% a subject after its verb, a headline with the copula left out, a gerund
%% clause, an article before a name and an imperative -- and, since
%% 1.6.14, what stands BESIDE the sentence: an adverb wherever its
%% language puts one (inside the verb group, at the head, after the verb),
%% a connector at the head with no left clause in the sentence, a fronted
%% adjunct before the subject, a bare time phrase the lesson calls one, a
%% preposition whose object is an adverb or an infinitive, a conjunction
%% between two complements, and a participle predicated of the subject.
%% Since 1.6.15 it has a relative clause with its own pronoun, `how', a
%% list, a phrase whose noun was left out and the two verbless shapes
%% above; since 1.6.21 a percentage, a date, a heading that ends in its
%% colon, a sentence that is one phrase with its relative clause, a list
%% that is the subject, and a reporting clause between two dashes, between
%% two commas or after a quotation that closes inside its sentence -- the
%% last three written AFTER the sentence, whatever place the source gave
%% them. A QUOTATION THAT OPENS ON ITS VERB LOSES ITS OPENING MARK: the
%% mark travels on the word, and a verb is written from its lexeme. Since
%% 1.7.0 it has the plain quotation mark over two sentences, read by the
%% character after it; a verb's meaning by whether its clause has an object
%% (`The intransitive verb "destaca" means "stands out".'); a name after a
%% participle; a year aside, and the article a lesson says a year takes; the
%% copula of a state with a participle, as a passive; a noun's own clause
%% (`prueba de que ...', `The word "de" begins the clause.'); a number after
%% its noun as its label; a comparative that is a word of its own (`"mejor"
%% is the comparative of "bueno".'); and a partitive whose head agrees with
%% the noun it is taken from. Since 1.7.2 it has a dateline (`Roma - ...');
%% a headline colon with no verb on either side; a relative clause set off
%% after a comma; the passive of a verb a lesson says marks one (`The verb
%% "viene" marks the passive.'), what must be done (`The verb "va" marks the
%% duty.') and a passive's subject after it; and a comma kept before a
%% subordinating word. Since 1.8.0 it has a comparison of two things (`más
%% grande que el perro', `idénticos condicionantes que la ronda anterior')
%% and more than an adjective (`más que cuestionable'); the preposition a
%% verb puts before its infinitive where the lesson says so (`"confía"
%% takes "en" before the infinitive.'); `ni ... ni' before its verb and
%% after it; the impersonal modal (`The impersonal modal "hay que" means
%% "must".'); an intransitive verb with a dative before it and its subject
%% after it (`le gusta el buen fútbol'); two pronouns joined to an
%% infinitive (`jugárselo'); a clause in parentheses; a denying adverb kept
%% before its verb; a comment between two commas (`como parece probable'),
%% written after the sentence; a phrase whose noun was left out with a
%% relative clause (`el que sufrió el Madrid'); and a subordinate clause at
%% the head with an insertion after its word.
%% Since 1.8.25 it has `why' (`The word "perché" means "why".'), not only
%% ... but (`"sino" is the partner of "sólo".'), as when, a comparison whose
%% second term is an infinitive, a name set at the end of its clause or
%% between two clauses, and a quotation that opens and does not close.
%% Since 1.8.26 it has what happened to somebody by accident (`"olvida"
%% takes the accident.': `que se les olvidó' is that they forgot), the
%% reflexive passive with adjuncts before its subject, a main clause that
%% shares the subject of the time clause before it, a second person at the
%% head that is a noun's plural too read as the noun where a later place
%% reads, and a plural the lesson says is feminine giving its phrase the
%% gender (`le braccia').
%% What it has NOT is a fragment with no verb beyond the shapes named, the
%% preposition a verb puts before its infinitive where no lesson says it
%% (`propone di punire' comes out `propone punire'), the imperfect apart from
%% the preterite (both are the past), and any idiom -- a word
%% means a word, and `is' is whichever word the lesson gave for it first
%% (a lesson with `es' and `está' for `is' gets `es', and the progressive
%% takes the AUXILIARY that means `is'). `There is' has the tenses a lesson
%% states of it (`"había" is the past of "hay".').
%% A past that spells like a present form (`read') is read as the present.
%% A SUBJUNCTIVE IS READ AND NOT WRITTEN: English marks none where `che
%% il militare volesse' wants one and no lesson says which verbs take
%% one, so the mood is dropped and the form comes back as the indicative.
%% AN IMPERATIVE'S PRONOUN stands before a DENIED one (`No lo comas.') and
%% is joined to an affirmative one (`Comelo.', `Dame eso.'), which is read
%% since 1.8.14 with the accent taken away: no lesson states a stress, so
%% the writer joins the pronoun back and writes `Comelo' where Spanish
%% writes `Cómelo'. The plural imperative is the builder's since 1.8.2.
%%
%% A NAME DOES NOT INFLECT and nothing crosses it, so a plural article
%% before one writes the article's plural and the name as it stands (`Le
%% Gallery' is `The Gallery', never `The Galleries'); and several
%% capitalised words are ONE name only after a determiner, because bare
%% there is nothing to say where one name ends and the next begins.
%% And it decides nothing about a word a lesson left out: a sentence with
%% one is refused whole, never half translated, and reason_untranslated/2
%% says which word to teach.

:- use_module(library(reasoning/reason)).
:- dynamic lesson/2.
:- dynamic lesson_language/1.
:- dynamic lesson_predicate/3.
%% the language and the generation every lookup reads are made with the library,
%% so that the lookup layer reads them with no catch/3 to turn a missing global
%% into `none' and 0 (tr_memo_reset/0 makes them too, whatever loaded the library)
:- nb_setval('$tr_language', none), nb_setval('$tr_gen', 0), nb_setval('$tr_lessons', 0).
%% (and how many times a lesson was learned or unlearned, which a list of words made from the lessons is kept for:
%% tr_gen_words/2, tr_euphonic_form/3 -- the generation moves at every reading, and each list was made again there)
tr_lessons_moved :- nb_getval('$tr_lessons', V0), V is V0 + 1, nb_setval('$tr_lessons', V).
%% (the two notes tr_into_ir/4 makes of a sentence's words, before its readers ask them: a reader that runs
%% before the first sentence has been through it, or in the pre-processing of the next, finds them made)
:- nb_setval('$tr_front_coord', yes), nb_setval('$tr_rel_two_verbs', yes), nb_setval('$tr_pron_copula', yes), nb_setval('$tr_ptc_agent', yes), nb_setval('$tr_where_co', yes), nb_setval('$tr_among', yes), nb_setval('$tr_comma_rel', yes), nb_setval('$tr_second_rel', yes), nb_setval('$tr_replacer', yes), nb_setval('$tr_adj_rel', yes), nb_setval('$tr_ger', []), nb_setval('$tr_read_side', none), nb_setval('$tr_seem_lexemes', []), nb_setval('$tr_count_lexemes', []), nb_setval('$tr_a_lexemes', []), nb_setval('$tr_personal', []), nb_setval('$tr_fem_persons', []), nb_setval('$tr_xnames', []), nb_setval('$tr_kind', statement), nb_setval('$tr_free_rel', yes), nb_setval('$tr_who_word', yes), nb_setval('$tr_what_word', yes), nb_setval('$tr_month', yes), nb_setval('$tr_numbered', yes), nb_setval('$tr_rc_head', none), nb_setval('$tr_focusnoun', any).

%% ---- the surface -----------------------------------------------------------

%% A PAGE, sentence by sentence: what translates is translated and what
%% does not is named with the words no lesson knows, so a page is never
%% refused whole for one sentence in it. Lines is a list of Sentence-Out
%% where Out is the translation, or refused(Words) -- Words as
%% reason_untranslated/2 gives them, [] when every word was known and the
%% shape was not one this translates. Into is as in reason_translate/3,
%% or `any'.
reason_translate_page(Text, Lines) :- reason_translate_page(Text, any, Lines).
reason_translate_page(Text, Into, Lines) :-
    ( Into == any -> Way = any ; tr_into(Into, Way) ),
    tr_pieces(Text, Pieces),
    findall(Sentence-Out, ( member(Piece-Stop, Pieces), atom_codes(P0, Piece), tr_trim(P0, P1),
                            tr_stop_text(P1, Stop, Sentence),
                            tr_page_one(Piece, Stop, Way, Out) ),
            Lines).

tr_page_one(Piece, Stop, Way, Out) :-
    (   catch(tr_each([Piece-Stop], Way, [Out0]), _, fail) -> Out = Out0
    ;   atom_codes(A, Piece), reason_untranslated(A, Words), Out = refused(Words)
    ).

tr_trim(A, T) :- atom_codes(A, Cs), tr_trim_codes(Cs, Ds), atom_codes(T, Ds).
tr_trim_codes(Cs, Ds) :- append(Sp, Rest, Cs), \+ ( Sp = [C|_], C > 32 ), Rest = [C0|_], C0 > 32, !, tr_trim_end(Rest, Ds).
tr_trim_codes(Cs, Cs).
tr_trim_end(Cs, Ds) :- append(Ds, Sp, Cs), \+ ( member(C, Sp), C > 32 ), ( Ds = [] ; last(Ds, L), L > 32 ), !.

reason_translate(Text, Out) :-
    tr_pieces(Text, Pieces), Pieces \== [],
    tr_each(Pieces, any, Outs),
    atomic_list_concat(Outs, ' ', Out).

reason_translate(Text, Into, Out) :-
    tr_into(Into, Way),
    tr_pieces(Text, Pieces), Pieces \== [],
    tr_each(Pieces, Way, Outs),
    atomic_list_concat(Outs, ' ', Out).

%% ---- the IR, as a program reaches it -------------------------------------------

%% THE LANGUAGES: `english', the pivot, and every lesson learned under a
%% name -- plus `none' where a lesson was learned plain. Adding one is
%% adding its lesson: nothing here is written per pair.
reason_languages([english|Ls]) :- tr_languages(Ls).

%% a text into the IR, sentence by sentence: IRs is a list of ir(S, Stop)
%% where S is the sentence term with English words in it and Stop the
%% code the sentence ended on. From is a language, or `any' to let the
%% words vote for one. It FAILS on a sentence it cannot read -- use
%% reason_translate_page/4 for a page.
reason_ir(Text, IRs) :- reason_ir(Text, any, IRs).
reason_ir(Text, From, IRs) :-
    tr_pieces(Text, Pieces), Pieces \== [],
    nb_setval('$tr_xnames', []),
    tr_each_ir(Pieces, From, IRs).

%% and back out of it, into any language
reason_ir_text(IRs, Into, Text) :-
    tr_side_of(Into, _),
    tr_each_out(IRs, Into, Outs),
    atomic_list_concat(Outs, ' ', Text).

%% a text from one language into another, through the IR: no English
%% sentence is written and none is read, so `Il cane mangia il pane' goes
%% to `El perro come el pan' and the two lessons never meet.
%% THE TARGET'S LESSON IS SET BEFORE THE TEXT IS READ, because an English
%% source is read against a lesson -- what English words the reader knows
%% is what some lesson gives a meaning for -- and when the source is
%% English the only lesson that matters is the target's.
reason_translate(Text, From, Into, Out) :-
    tr_side_of(Into, _),
    reason_ir(Text, From, IRs),
    reason_ir_text(IRs, Into, Out).

%% ... a page of it: what translates is translated and what does not is
%% named, as reason_translate_page/2,3 does
reason_translate_page(Text, From, Into, Lines) :-
    tr_side_of(Into, _),
    tr_pieces(Text, Pieces),
    findall(Sentence-Out, ( member(Piece-Stop, Pieces), atom_codes(P0, Piece), tr_trim(P0, P1),
                            tr_stop_text(P1, Stop, Sentence),
                            tr_ir_page_one(Piece, Stop, From, Into, Out) ),
            Lines).

tr_ir_page_one(Piece, Stop, From, Into, Out) :-
    nb_setval('$tr_xnames', []),
    (   catch(( tr_read_ir(Piece, Stop, From, S, Stop1), tr_write_ir(Into, S, Stop1, Out0) ), _, fail) -> Out = Out0
    ;   atom_codes(A, Piece), reason_untranslated(A, From, Words), Out = refused(Words)
    ).

tr_each_ir([], _, []).
%% a piece with no word in it is no sentence and is passed over, never
%% refused: a stray mark between two stops (`!.') has nothing to translate
tr_each_ir([Piece-_|Ps], From, Ss) :- tr_piece_words(Piece, []), !, tr_each_ir(Ps, From, Ss).
tr_each_ir([Piece-Stop0|Ps], From, [ir(S, Stop)|Ss]) :-
    tr_read_ir(Piece, Stop0, From, S, Stop),
    tr_each_ir(Ps, From, Ss).

%% AN OPENING MARK ON THE FIRST WORD IS THE SENTENCE'S. The mark travels on
%% its word's case, and a word the reader makes a verb carries no case into
%% the IR: `"Hay que tomar precauciones", dijo.' came out `Bisogna prendere
%% precauzioni", disse.', and after a pronoun the capital went -- `"gli ho
%% dato riposo'. At the head of the sentence the mark is taken off the word
%% and put before the sentence, where tr_join/5 writes the marks a
%% quotation over several sentences already had.
tr_read_ir(Piece0, Stop0, From, S, Stop) :-
    tr_caps_piece(Piece0, Piece),
    tr_piece_words(Piece, Words00), Words00 \== [],
    tr_from_side(From, Words00, Side),                 % (first: the head mark asks the lesson)
    tr_head_mark(Words00, Stop0, Words0t, Stop1),
    tr_tail_mark(Side, Words0t, Stop1, Words0c, Stop),
    tr_caps_names(Side, Words0c, Words0q),
    tr_quote_names(Side, Words0q, Words0r),
    tr_quote_comma(Side, Words0r, Words0n),
    tr_letter_runs(Side, Words0n, Words0),
    tr_elision_names(Side, Words0, Words0e1),
    tr_dash_names(Side, Words0e1, Words0e),
    tr_particle_names(Side, first, Words0e, Words0p),
    tr_stated_names(Side, Words0p, Words0a00),
    tr_name_numbers(Side, Words0a00, Words0a0),
    tr_title_lower(Side, Words0a0, Words0a),
    tr_month_lower(Side, Words0a, Words0b0),
    tr_colon_lower(Side, Words0b0, Words0b1),
    tr_demonstrative_copula(Side, Words0b1, Words0b),
    tr_small_head_note(Side, Words0b),
    tr_head_lower(Side, Words0b, Words1),
    tr_kind(Stop, Kind), tr_exclaim(Stop),
    (   tr_adjective_head(Side, Words0b, WordsN)
    ->  Words0b = [w(HW, _)|_], nb_setval('$tr_head_adjective', HW),
        (   tr_joined_words(Side, Words1, Words), tr_into_ir(Side, Kind, Words, S)
        ;   \+ ( tr_joined_words(Side, Words1, Words), tr_into_ir(Side, Kind, Words, _) ),
            tr_joined_words(Side, WordsN, WordsJ), tr_into_ir(Side, Kind, WordsJ, S)
        )
    ;   nb_setval('$tr_head_adjective', none),
        tr_joined_words(Side, Words1, Words),
        (   tr_into_ir(Side, Kind, Words, S)
        ;   tr_byline(Side, Words, Words2), tr_into_ir(Side, Kind, Words2, S)
        %% ... AND A PIECE QUOTED WHOLE THAT NOTHING ELSE READS IS A TITLE
        ;   tr_quoted_whole(Stop), length(Words, TN), TN =< 8, tr_as_title(tr_into_ir(Side, Kind, Words, S))
        )
    ).

%% A PIECE IN QUOTATION MARKS FROM ITS FIRST WORD TO ITS LAST, with no verb
%% to read, is a title the paper quotes: `"verdetto casareccio".' is a
%% homespun verdict, a headline standing alone in the quotation of what a
%% verdict was called. A bare noun in the singular begins no sentence, and a
%% title is no sentence: it is read as a heading is (tr_as_heading/2), and
%% only after the plain reading found nothing. The marks are the stop's
%% (tr_tail_mark/5 put both there), so the piece is the one they enclose
tr_quoted_whole(Stop) :- tr_stop_parts(Stop, [_|_], [34], _, _).
tr_as_title(Goal) :-
    nb_setval('$tr_title', yes),
    (   call(Goal) -> nb_setval('$tr_title', no)
    ;   nb_setval('$tr_title', no), fail
    ).
%% A BYLINE GLUED TO THE LINE AFTER IT: `di Rita Celi rap per comunicare.' is
%% a headline and the name of the one who signs it, with no stop between them
%% in the text. The phrase of `di' and a name of two capitalised words no
%% lesson knows, at the head of the piece and followed by a small word, is
%% read with a comma after the name -- the way it reads when the paper
%% prints one -- and only where the plain reading found nothing
tr_byline(foreign, [P, N1, N2, W3|Ws], [P, N1, N2, comma, W3|Ws]) :-
    P = w(PW, lower), atom(PW), ( tr_means_of(foreign, P) ; tr_means_by(foreign, P) ),
    N1 = w(A, upper), N2 = w(B, upper), W3 = w(R, lower), atom(A), atom(B), atom(R),
    tr_name_word(foreign, N1), tr_name_word(foreign, N2).
%% ... AND A BYLINE BEFORE ITS DATELINE: `Dal nostro inviato Giacomo Pellicciotti Perugia - passeggiando di sera ...'
%% is the correspondent who signs the report and the city it comes from, with no comma between them in the text, and
%% the city was read as the name's third word, so nothing read. A city the lesson names, right before the dash and
%% after a name's capitalised word, in a piece that opens on a preposition, is read with a comma before it
tr_byline(foreign, [P|Ws0], [P|Ws]) :-
    P = w(PW, _), atom(PW), ( tr_is(foreign, P, preposition) -> true ; tr_solve(contraction_of(PW, _)) ),
    append(Pre, [N, C, dash|Post], Ws0), N = w(NW, upper), C = w(CW, upper), atom(NW), atom(CW),
    tr_city_name(CW), tr_name_word(foreign, N), \+ memberchk(dash, Pre), !,
    append(Pre, [N, comma, C, dash|Post], Ws).

%% A SURNAME THE LESSON KNOWS AS AN ADJECTIVE: `Redondo declaró a Europa
%% Press que ...', `Redondo se movió así ...'. The head of a sentence goes
%% lower when the lesson knows the word (tr_head_lower/3), and `redondo' is
%% round to the vocabulary, so the subject was an adjective describing
%% nothing and the sentence was refused. An adjective alone is no subject:
%% a word the lesson knows ONLY as one, capitalised at the head and followed
%% by a verb or a pronoun, is read as a name -- and only where the plain
%% reading failed, so a sentence the head's adjective can open keeps the
%% reading it had.
tr_adjective_head(foreign, [w(W, upper), N|Ws], [w(Name, upper), N|Ws]) :-
    atom(W), tr_is(foreign, w(W, lower), adjective),
    \+ ( member(C, [noun, verb, determiner, pronoun, adverb, preposition, conjunction, number]),
         tr_is(foreign, w(W, lower), C) ),
    ( tr_verb_next(foreign, [N|Ws]) -> true ; N = w(P, _), tr_clitic(any, P) ), !,
    tr_cap(W, Name).

%% A HEADING IN CAPITALS: `COMPACTO CONTRA CASETE.' A newspaper sets a
%% section's title in capitals, and the tokeniser keeps only the FIRST
%% letter's case, so every word of it came through capitalised: `Casete',
%% a capital no lesson knows, passed through as a name, and `compacto' --
%% which is also what `compactar' says of oneself -- read as the verb, `I
%% compact Against Casete'. A piece with no small letter in it and three
%% capitals at least is a heading: its codes are lowered before a word is
%% read, and the reading with no verb is tried FIRST (tr_read0/4), because
%% the capitals are what says the piece has none. An ACRONYM in a sentence
%% of small letters -- `la consultora DBK' -- is the other case, and a name
%% spelled as the text spelled it (tr_hyphen_name/4).
tr_caps_piece(Piece0, Piece) :-
    \+ ( append(_, [C|Rest], Piece0), tr_small_code(C, Rest) ),
    tr_capitals(Piece0, 0, N), N >= 3, !,
    tr_lower_codes(Piece0, Piece), nb_setval('$tr_caps', yes).
tr_caps_piece(Piece, Piece) :- nb_setval('$tr_caps', no).

%% ... AND A WORD NO LESSON KNOWS IN SUCH A HEADING IS A NAME, spelled with
%% its capital: `LEMERRE RENDIDO.' is the French coach, beaten, and lowered
%% `lemerre' was a word no lesson knows and the heading was refused
tr_caps_names(Side, Ws0, Ws) :-
    (   Side == foreign, tr_global('$tr_caps', yes) -> maplist(tr_caps_name, Ws0, Ws) ; Ws = Ws0 ).
tr_caps_name(w(W, lower), w(N, upper)) :-
    atom(W), \+ tr_digits(W), \+ tr_known_word(foreign, W), !, tr_cap(W, N).
tr_caps_name(X, X).

tr_small_code(C, _) :- C >= 0'a, C =< 0'z, !.
tr_small_code(195, [B|_]) :- B >= 159, B =< 191.
tr_small_code(C, _) :- C >= 223, C =< 255, rt_chars.            % U+00DF..U+00FF as a code point

tr_capitals([], N, N).
tr_capitals([C|Cs], N0, N) :- C >= 0'A, C =< 0'Z, !, N1 is N0 + 1, tr_capitals(Cs, N1, N).
tr_capitals([195, B|Cs], N0, N) :- B >= 128, B =< 158, B =\= 151, !, N1 is N0 + 1, tr_capitals(Cs, N1, N).
tr_capitals([C|Cs], N0, N) :- rt_upper_cp(C), rt_chars, !, N1 is N0 + 1, tr_capitals(Cs, N1, N).
tr_capitals([_|Cs], N0, N) :- tr_capitals(Cs, N0, N).

tr_lower_codes([], []).
tr_lower_codes([C|Cs], [L|Ls]) :- C >= 0'A, C =< 0'Z, !, L is C + 32, tr_lower_codes(Cs, Ls).
tr_lower_codes([195, B|Cs], [195, L|Ls]) :- B >= 128, B =< 158, B =\= 151, !, L is B + 32, tr_lower_codes(Cs, Ls).
tr_lower_codes([C|Cs], [L|Ls]) :- rt_upper_cp(C), rt_chars, !, L is C + 32, tr_lower_codes(Cs, Ls).
tr_lower_codes([C|Cs], [C|Ls]) :- tr_lower_codes(Cs, Ls).

%% A NAME MAY BEGIN WITH A SMALL WORD: `ni De la Peña', `De la Peña, en
%% cambio, es baja'. Read as words it was `of the cliff' -- `peña' is a
%% noun -- and came out `Del Dirupo'. A capital on `De' where no sentence
%% begins, or on the word after its article, says the run is one name: `De',
%% an article and a capitalised word, anywhere; `De' or `Del' and a
%% capitalised word, anywhere but the head, where `De Madrid llegó' is a
%% preposition. The name keeps its capitals and passes through as a name.
%% A NAME OF SEVERAL WORDS THE LESSON STATES IS ONE WORD, spelled as the text
%% spells it: `dal Corriere della Sera', `un albergo di Porto Cervo' -- a
%% paper and a place made of words every lesson knows (`The Messenger of the
%% Evening', `Harbour Deer'), where `"Porto Cervo" is a name.' says what
%% they are. A run of two to four words that opens on a capital and that
%% the lesson names goes through as one name, its words with the capitals the
%% text gave them, and no lesson's word crosses it.
tr_stated_names(foreign, Ws0, Ws) :-
    memberchk(w(_, upper), Ws0), tr_stated_names0(Ws0, Ws), !.
tr_stated_names(_, Ws, Ws).
tr_stated_names0([], []).
tr_stated_names0([w(W, upper)|Ws0], [w(Name, upper)|Ws]) :-
    atom(W), tr_stated_run(Ws0, 3, Run0, Rest), Run0 \== [],
    findall(X, member(w(X, _), [w(W, upper)|Run0]), Parts),
    atomic_list_concat(Parts, ' ', Key), tr_solve(name(Key)), !,
    tr_name_spelling([w(W, upper)|Run0], Name),
    tr_stated_names0(Rest, Ws).
%% ... AND A NAME OF ONE WORD THE LESSON KNOWS AS NO NOUN: `la Meridiana' is
%% the avenue and `meridiana' the feminine of meridian to the vocabulary
%% (`"meridiana" is a name.'), where read with its noun left out it came out
%% `la Meridiano'. A capital word the lesson says is a name goes through as
%% one, spelled as the text spelled it, which no lesson knows -- so every
%% reading of a name has it, `entre Meridiana y Aragó' as `entre Barcelona y
%% Aragó'. A noun keeps the readings it has (`Salvador', `Margherita': made
%% a word no lesson knows it cost one sentence of the controls 12 % more, for
%% the same text); and at the head of a sentence a known word is lowered
%% before this
tr_stated_names0([w(W, upper)|Ws0], [w(Name, upper)|Ws]) :-
    atom(W), tr_solve(name(W)), \+ tr_is(foreign, w(W, lower), noun), !,
    tr_name_spelling([w(W, upper)], Name),
    tr_stated_names0(Ws0, Ws).
%% ... AND A STREET'S NAME: a word the lesson says begins one, with its
%% capital, and a capitalised word after it. `e Via Krupp, resa più agibile
%% dopo il restauro, è frequentata come mai' is the street, and read as
%% words `Via' was the adverb `away' (`y Fuera Krupp'). `The word "via"
%% begins the name.' says it; the name keeps the text's spelling and passes
%% through as one
tr_stated_names0([w(W, upper), w(N, upper)|Ws0], [w(Name, upper)|Ws]) :-
    atom(W), atom(N), downcase_atom(W, L), tr_solve(begin(L, name)), !,
    tr_name_spelling([w(W, upper), w(N, upper)], Name),
    tr_stated_names0(Ws0, Ws).
%% ... AND THE NAME AFTER A STREET'S NOUN AND ITS `OF': `en la esquina de la calle de la Cadena con Sant Rafael' is the
%% street called that, and `cadena' is a chain to the lesson -- `the street of the Chain', `della Catena'. After a noun
%% the lesson calls a street (`"calle" is a street.'), the preposition of `of' and an article, a capitalised word the
%% lesson knows is the name's, spelled as the text spelled it (a word it does not know was one already, and with no
%% article a capitalised word after a preposition is a name already)
tr_stated_names0([S, P, D, w(N, upper)|Ws0], [S, P, D, w(Name, upper)|Ws]) :-
    S = w(SW, _), atom(SW), atom(N), tr_solve(street(SW)), tr_means_of(foreign, P),
    D = w(DW, _), atom(DW), tr_determiner(foreign, D, _, article), tr_known_word(foreign, N), !,
    tr_name_spelling([w(N, upper)], Name),
    tr_stated_names0(Ws0, Ws).
%% ... AND A CAPITALISED WORD AFTER A TITLE, though the lesson knows it: `il dottor Lombardi' is the doctor called
%% that, and `lombardi' is the plural of the adjective `lombardo' -- `the Lombard doctor', `el médico Lombardo'. After a
%% word the lesson calls a title (`"dottore" is a title.'), the capitalised word is the name's, spelled as the text
%% spelled it
tr_stated_names0([T, w(N, upper)|Ws0], [T, w(Name, upper)|Ws]) :-
    T = w(TW, _), atom(TW), atom(N), tr_title_word(foreign, TW), tr_known_word(foreign, N), !,
    tr_name_spelling([w(N, upper)], Name),
    tr_stated_names0(Ws0, Ws).
%% ... AND ONE WHOSE FIRST WORD THE PAPER WRITES SMALL, RIGHT AFTER A PREPOSITION: `passeggiando di sera per corso
%% Vannucci' is the street called that, and read as words `corso' was the course, `for course Vannucci'. With no article
%% between them, the word that begins a street's name begins this one too
tr_stated_names0([P, w(W, lower), w(N, upper)|Ws0], [P, w(Name, upper)|Ws]) :-
    P = w(PW, _), atom(PW), atom(W), atom(N), tr_solve(begin(W, name)),
    tr_is(foreign, P, preposition), \+ tr_determiner(foreign, P, _, _), !,
    tr_name_spelling([w(W, upper), w(N, upper)], Name),
    tr_stated_names0(Ws0, Ws).
%% ... AND ONE IN SMALL LETTERS RIGHT AFTER A COMMON NOUN: `Tre recital ... al teatro morlacchi' is the theatre called
%% that, which the paper writes small, and with `"morlacchi" is a name.' it was still a word no reader placed after the
%% noun. A word in small letters that the lesson says is a name and knows as nothing else, after a noun, takes its
%% capital, and the noun has the name apposed to it as `al teatro Morlacchi' has
tr_stated_names0([N, w(W, lower)|Ws0], [N, w(Name, upper)|Ws]) :-
    N = w(NW, _), atom(NW), atom(W), tr_solve(name(W)), \+ tr_known_word(foreign, W), tr_is(foreign, w(NW, lower), noun), !,
    tr_cap(W, Name), tr_stated_names0(Ws0, Ws).
tr_stated_names0([X|Ws0], [X|Ws]) :- tr_stated_names0(Ws0, Ws).
%% A TITLE IN CAPITALS BEFORE A NAME IS A COMMON NOUN: `il suo Avvocato
%% Francesco Assumma' is his lawyer, and the three capitalised words were one
%% name no determiner could take. A word the lesson knows as a noun, with a
%% capital where it stands after a determiner and before a capitalised word the
%% lesson does not know and another capitalised word after it (a first name
%% and a surname), is written small: the phrase is then a noun and the name
%% that names it. (`il Monte Livata' is one name, a place: a title is before a
%% person's two names)
tr_title_lower(foreign, Ws0, Ws) :-
    memberchk(w(_, upper), Ws0), tr_title_lower0(Ws0, Ws), !.
tr_title_lower(_, Ws, Ws).
tr_title_lower0([], []).
tr_title_lower0([D, w(T, upper), N|Ws0], [D, w(T, lower)|Ws]) :-
    D = w(DW, _), atom(DW), tr_determiner(foreign, D, _, _),
    N = w(NW, upper), atom(NW), \+ tr_known_word(foreign, NW),
    tr_two_names(NW, Ws0),
    atom(T), tr_known_word(foreign, T), tr_name_head(foreign, T), !,
    tr_title_lower0([N|Ws0], Ws).
tr_title_lower0([X|Ws0], [X|Ws]) :- tr_title_lower0(Ws0, Ws).
%% a name of two words: one the particle rule joined (`Mario la Casa'), or a
%% capitalised word after it
tr_two_names(NW, _) :- sub_atom(NW, _, 1, _, ' '), !.
tr_two_names(_, [w(N2W, upper)|_]) :- atom(N2W).
%% the longest run first, up to N more words, each a plain word of the text
%% (a mark between words is no word: `forall(member(w(X, C), Run), ...)'
%% asked it of the words only, so a run of one mark was a run, and the
%% name before a comma took the comma with it -- `Mario Fini, il cane
%% dorme.', with `"fini" is a name.', came out with no comma and was refused)
tr_stated_run(Ws, N, Run, Rest) :-
    numlist(1, N, Ks0), reverse(Ks0, Ks), member(K, Ks),
    length(Run, K), append(Run, Rest, Ws),
    forall(member(R, Run), ( R = w(X, C), atom(X), memberchk(C, [upper, lower]) )).
tr_name_spelling(Ws, Name) :-
    findall(S, ( member(w(X, C), Ws), ( C == upper -> tr_cap(X, S) ; S = X ) ), Ss),
    atomic_list_concat(Ss, ' ', Name).
%% A COMMA AFTER THE QUOTATION BEFORE ITS REPORTING VERB: `"In ogni caso"
%% puntualizza lui, "comincerò ..."' is `"In ogni caso", puntualizza lui, ...'
%% -- Italian leaves the comma out where it stands between a closing mark and
%% the verb that says it, and read so the quoted words were an adjunct of the
%% reporting verb inside its marks. The comma is put back where a word closes
%% a quotation that began with the piece (no mark opens before it: the opening
%% one went with the piece's first word) and a form of a verb of saying follows
%% it -- unless the report is the end of what the piece says with an apposition
%% after it, which a comma before the report made unreadable: `"Il cane dorme"
%% dice Carolyn, giornalista e critica' is read as it always was, and so is a
%% quotation inside the clause, `Il cane mangia "il pane" dice Maria'.
tr_quote_comma(foreign, Ws0, Ws) :- tr_quote_comma0(Ws0, [], Ws), !.
tr_quote_comma(_, Ws, Ws).
tr_quote_comma0([], _, []).
tr_quote_comma0([W0, w(V, lower)|Ws0], Seen, [W0, comma, w(V, lower)|Ws]) :-
    tr_quote_reports(Seen, W0, V, Ws0), !,
    tr_quote_comma0(Ws0, [w(V, lower), W0|Seen], Ws).
tr_quote_comma0([W|Ws0], Seen, [W|Ws]) :- tr_quote_comma0(Ws0, [W|Seen], Ws).
tr_quote_reports(Seen, W0, V, Rest) :-
    tr_closes_quote(W0), W0 = w(_, C0), \+ tr_opens_quote(C0),
    atom(V), tr_form(V, L, _, _, third), tr_saying_verb(L),
    \+ ( member(w(_, C), Seen), tr_opens_quote(C) ),
    (   member(w(_, C2), Rest), tr_opens_quote(C2) -> true
    ;   \+ memberchk(comma, Rest)
    ), !.
tr_particle_names(english, _, Ws, Ws) :- !.
tr_particle_names(_, _, [], []) :- !.
tr_particle_names(Side, _, [w(de, C), w(A, lower), w(N, upper)|Ws0], [w(Name, upper)|Ws]) :-
    memberchk(C, [upper, qopen]), memberchk(A, [la, las, los, el]), !,
    tr_cap(N, NC), atomic_list_concat(['De', A, NC], ' ', Name),
    tr_particle_names(Side, later, Ws0, Ws).
%% ... AND ITALIAN'S: `il dott Di Pietro', a doctor whose name begins with
%% `Di', read as a preposition and a name, `el médico De Pietro'
tr_particle_names(Side, later, [w(P, upper), w(N, upper)|Ws0], [w(Name, upper)|Ws]) :-
    ( memberchk(P, [de, del, di, da]) -> true ; atom(P), tr_solve(contraction_of(P, _)) ), !,
    tr_cap(P, PC), tr_cap(N, NC), atomic_list_concat([PC, NC], ' ', Name),
    tr_particle_names(Side, later, Ws0, Ws).
%% ... AND A CONTRACTION WITH ITS CAPITAL AFTER A FIRST NAME IS THE SURNAME:
%% `Lucio Dalla mi ha invitato a Napoli' is the singer, and read as words
%% `Dalla' was `da la', from the -- a preposition with nothing after it, and
%% the sentence was refused. A capitalised word the lesson states as a
%% contraction, right after a name's capitalised word and before no other
%% capital, is the name's last word (before a capital it begins the surname,
%% the clause above: `Della Valle')
tr_particle_names(Side, _, [w(F, upper), w(P, upper)|Ws0], [w(Name, upper)|Ws]) :-
    atom(F), atom(P), tr_solve(contraction_of(P, _)), tr_name_word(Side, w(F, upper)),
    \+ Ws0 = [w(_, upper)|_], !,
    tr_cap(F, FC), tr_cap(P, PC), atomic_list_concat([FC, PC], ' ', Name),
    tr_particle_names(Side, later, Ws0, Ws).
%% ... AND A SMALL WORD BETWEEN TWO NAMES IS THE NAME'S: `Bertrand de
%% Billy', `Lucia di Lammermoor' -- a conductor and an opera. Read as words,
%% `de' and `di' were prepositions and the name came out in two, `Bertrand
%% di Billy'. Both sides are words no lesson knows, and the small word is
%% one names are made with; the run passes through as one name.
%% (but not a contraction with an article before a name that goes on in a
%% small word no lesson knows: `La salida de Puigbó del Telenotícies migdia
%% le permitiría ...' is the man and the programme he leaves, and joined as
%% one name, `Puigbó del Telenotícies', the programme's `migdia' was left
%% a word no lesson knows; after an article it is the name's, below)
%% ... AND ENGLISH'S `of' AND `of the' IN AN ENGLISH NAME: `i Prophets of the
%% City' is a group, and `of' and `the' are words of neither lesson. Tried
%% before the clause for a small word after a name, which took `Prophets of'
%% for the name and left `the City' behind it
tr_particle_names(Side, _, Ws0, [w(Name, upper)|Ws]) :-
    tr_english_of_name(Side, Ws0, Name, Ws1), !,
    tr_particle_names(Side, later, Ws1, Ws).
tr_particle_names(Side, _, [D|Ws0], [D, w(Name, upper)|Ws]) :-
    D = w(DW, _), atom(DW), tr_article_word(Side, DW),
    tr_english_of_name(Side, Ws0, Name, Ws1), !,
    tr_particle_names(Side, later, Ws1, Ws).
%% (`del' after a first name and a surname, before an acronym, is the preposition and its
%% article: `Roberto Zonta del Cnr e Mario Scattolin del comune' are of the Cnr and of the town
%% council, and joined it was `Roberto Zonta del Cnr'; before a word with a vowel after its
%% capital it is the name's own, `Joseph Guarnerius del Gesù')
tr_particle_names(Side, _, [w(F, upper), w(A, upper), w(del, lower), w(B, upper)|Ws0], [w(F, upper), w(A, upper)|Ws]) :-
    atom(F), atom(A), tr_name_word(Side, w(F, upper)), tr_name_word(Side, w(A, upper)), tr_acronym_word(B), !,
    tr_particle_names(Side, later, [w(del, lower), w(B, upper)|Ws0], Ws).
%% (not before a city the lesson names, where it is the place a thing is from:
%% `Ruggisce Rosi da Perugia' is Rosi roaring from Perugia, no `Rosi da Perugia')
%% (nor after a code with digits in it: `el vuelo UX-9482 de Air Europa' is Air Europa's
%% flight, and joined it was one name, `UX-9482 de Air Europa', with its `de' untranslated)
tr_particle_names(Side, _, [w(A, upper), w(P, lower), w(B, upper)|Ws0], [w(Name, upper)|Ws]) :-
    memberchk(P, [de, di, da, del, van, von, du, der]),
    \+ ( memberchk(P, [de, di, da, del]), tr_city_name(B) ),
    \+ ( atom(A), sub_atom(A, _, 1, _, D), char_type(D, digit(_)) ),
    %% (nor after a word the lesson calls an acronym: `ai laboratori nazionali Infn di Legnaro' are the INFN's at
    %% Legnaro, and joined it was one name, `Infn di Legnaro', with its `di' untranslated)
    \+ ( atom(A), downcase_atom(A, AD), tr_solve(acronym(AD)) ),
    tr_name_word(Side, w(A, upper)), tr_name_word(Side, w(B, upper)),
    \+ ( tr_article_word(Side, P), Ws0 = [w(B2, lower)|_], atom(B2), \+ tr_digits(B2),
         \+ tr_known_word(Side, B2) ), !,
    tr_cap(A, AC), tr_cap(B, BC), atomic_list_concat([AC, P, BC], ' ', Name0),
    %% ... AND A SECOND PARTICLE AND NAME ARE THE NAME'S TOO: `Consell de
    %% Col.legis d'Advocats de Catalunya' is one name, and its last `de' was
    %% written `di' (the run is read again with the name as its head)
    (   Ws0 = [w(P2, lower), w(B2, upper)|_], memberchk(P2, [de, di, da, del, van, von, du, der]),
        tr_name_word(Side, w(B2, upper))
    ->  tr_particle_names(Side, later, [w(Name0, upper)|Ws0], [w(Name, upper)|Ws])
    ;   Name = Name0, tr_particle_names(Side, later, Ws0, Ws)
    ).
%% ... AND A SMALL ARTICLE BEFORE A SURNAME THE LESSON KNOWS AS A WORD: `il
%% direttore Gabriele la Porta' has the director's name, `La Porta', typed with
%% a small article, and `porta' is a door and a verb's form. The run is a name
%% where the first word is one no lesson knows and the article is Italian's
%% `la', `lo' or `le' between it and a capitalised word
tr_particle_names(foreign, _, [w(A, upper), w(P, lower), w(B, upper)|Ws0], [w(Name, upper)|Ws]) :-
    memberchk(P, [la, lo, le]), atom(A), atom(B),
    tr_name_word(foreign, w(A, upper)), \+ tr_digits(B), !,
    tr_cap(A, AC), tr_cap(B, BC), atomic_list_concat([AC, P, BC], ' ', Name),
    tr_particle_names(foreign, later, Ws0, Ws).
%% ... AND A SMALL WORD NO LESSON KNOWS AFTER A NAME, AFTER AN ARTICLE: `el
%% editor del Telenotícies migdia de TV-3' names a news programme with a
%% Catalan word in small letters in its name. Read alone, `migdia' was a
%% word no lesson knows and the sentence was refused for it; after an
%% article and a name no lesson knows, it is the name's, and passes through
%% with it as the text spelled it. Only there: after a bare name, a word no
%% lesson knows is as often the verb a lesson lacks, and a refusal that
%% names it is worth more than a name it disappears into.
tr_particle_names(Side, _, [D, w(A, upper), w(B, lower)|Ws0], [D, w(Name, upper)|Ws]) :-
    D = w(DW, _), atom(DW), tr_article_word(Side, DW),
    atom(B), \+ tr_digits(B), tr_name_word(Side, w(A, upper)), \+ tr_known_word(Side, B), !,
    tr_cap(A, AC), atomic_list_concat([AC, B], ' ', Name),
    tr_particle_names(Side, later, Ws0, Ws).
%% ... AND A NAME WHOSE FIRST WORD THE LESSON KNOWS, AFTER A BARE PREPOSITION:
%% `il commento di Marco Taradash', `la cronaca ... di Marina Ripa Di Meana'.
%% `marco' is a frame and `marina' a navy to the vocabulary, so the run was a
%% noun with adjectives, and `Di' a preposition inside it; the Spanish came
%% out right for `Marco' by the chance that its word for frame is `marco',
%% and was refused for the other. After a preposition with no article, a run
%% of capitalised words with a word no lesson knows in it is one name, a
%% capitalised small word inside it included. With an article, `della Regione
%% Lazio', it stays a noun with the name apposed to it (1.6.17); a time stays
%% a time, `Sabato Mladic'; and a word with a digit ends the run, `a Sky
%% Tg24 Tornaboni' being a channel and a speaker.
tr_particle_names(Side, later, [P, W1|Ws0], [P, w(Name, upper)|Ws]) :-
    P = w(PW, lower), tr_is(Side, P, preposition), \+ tr_solve(contraction_of(PW, _)),
    W1 = w(X1, upper), \+ tr_digit_word(W1), tr_known_word(Side, X1),
    \+ ( tr_lexeme(Side, X1, L1, _), ( tr_holds(month(L1)) ; tr_holds(time(L1)) ) ),
    tr_cap_run(Ws0, Run, Ws1), Run \== [],
    once(( member(W, Run), tr_name_word(Side, W) )), !,
    findall(C, ( member(w(X, _), [W1|Run]), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', Name),
    tr_particle_names(Side, later, Ws1, Ws).
%% ... AND A CAPITALISED WORD WITH ITS NUMBER, where no sentence begins: `un
%% programa de Canal 33' names a channel. Read as words it was a channel and
%% a count after it, and with no article before it the phrase had no
%% reading; with one it crossed as `Canale 33'. Only a word the lesson knows
%% as a noun, which a capital where no sentence begins makes a name: a name
%% no lesson knows is a name already, and the number after it is a count --
%% `Il cane dà a Maria 3 pani', which joined as `Maria 3' was refused. Not a
%% month or a time, which the source may capitalise before a year.
tr_particle_names(Side, later, [w(A, upper), w(D, lower)|Ws0], [w(Name, upper)|Ws]) :-
    atom(D), tr_digits(D), \+ tr_year(D), tr_is(Side, w(A, lower), noun),
    \+ ( tr_lexeme(Side, A, L, _), ( tr_holds(month(L)) ; tr_holds(time(L)) ) ), !,
    tr_cap(A, AC), atomic_list_concat([AC, D], ' ', Name),
    tr_particle_names(Side, later, Ws0, Ws).
%% ... AND AN ARTICLE WITH ITS CAPITAL WHERE NO SENTENCE BEGINS, BEFORE A
%% NAME, IS THE NAME'S: `en Figueres, Gandesa, Tortosa, El Vendrell, Vic'
%% -- a town whose name begins with its article. After `en' the name was one
%% already (the clause below); after a comma `El' was an article and Italian
%% wrote `Il Vendrell'
tr_particle_names(Side, later, [w(A, upper), w(N, upper)|Ws0], [w(Name, upper)|Ws]) :-
    tr_determiner(Side, w(A, lower), _, article), tr_name_word(Side, w(N, upper)), !,
    tr_cap(A, AC), tr_cap(N, NC), atomic_list_concat([AC, NC], ' ', Name),
    tr_particle_names(Side, later, Ws0, Ws).
%% ... AND AFTER A NOUN OR A PREPOSITION, BEFORE WORDS THE LESSON KNOWS:
%% `presso la "scuola di ingegneria aerospaziale" dell'università La
%% Sapienza' names the university, and read as words it was `the wisdom', an
%% object of its own, which came out `La Cordura'. An article with its
%% capital inside a phrase can only be a name's; after a comma or a dash it
%% may begin a clause (`Roma - La scuola ...') and stays an article
tr_particle_names(Side, later, [P, w(A, upper), W1|Ws0], [P, w(Name, upper)|Ws]) :-
    P = w(PW, _), atom(PW), ( tr_is(Side, P, preposition) ; tr_is(Side, P, noun) ),
    tr_determiner(Side, w(A, lower), _, article),
    W1 = w(_, upper), \+ tr_digit_word(W1),
    tr_cap_run([W1|Ws0], Run, Ws1), Run \== [], !,
    findall(C, ( member(w(X, _), [w(A, upper)|Run]), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', Name),
    tr_particle_names(Side, later, Ws1, Ws).
%% (but a contraction between two common nouns, all three with their capital, is the
%% contraction of a title the paper writes in capitals: `il Presidente Della Repubblica' is
%% the president of the Republic, and joined `Della Repubblica' was a name -- the
%% clause above, which `il generale Dalla Chiesa' needs)
tr_particle_names(Side, _, [W, P, N|Ws0], [W, P, N|Ws]) :-
    W = w(WW, upper), P = w(PW, upper), N = w(NW, upper), atom(WW), atom(PW), atom(NW),
    \+ memberchk(PW, [de, del, di, da]), tr_solve(contraction_of(PW, _)),
    tr_is(Side, w(WW, lower), noun), tr_is(Side, w(NW, lower), noun), !,
    tr_particle_names(Side, later, Ws0, Ws).
tr_particle_names(Side, _, [W|Ws0], [W|Ws]) :- tr_particle_names(Side, later, Ws0, Ws).
tr_english_of_name(Side, [w(A, upper), w(of, lower), w(the, lower), w(B, upper)|Rest], Name, Rest) :-
    atom(A), atom(B), tr_name_word(Side, w(A, upper)), tr_name_word(Side, w(B, upper)),
    \+ tr_known_word(Side, of), \+ tr_known_word(Side, the),
    tr_cap(A, AC), tr_cap(B, BC), atomic_list_concat([AC, 'of the', BC], ' ', Name).
tr_english_of_name(Side, [w(A, upper), w(of, lower), w(B, upper)|Rest], Name, Rest) :-
    atom(A), atom(B), tr_name_word(Side, w(A, upper)), tr_name_word(Side, w(B, upper)),
    \+ tr_known_word(Side, of),
    tr_cap(A, AC), tr_cap(B, BC), atomic_list_concat([AC, of, BC], ' ', Name).
tr_acronym_word(B) :-
    atom(B), atom_chars(B, [_|Cs]), Cs \== [], \+ ( member(C, Cs), memberchk(C, [a, e, i, o, u, y, 'A', 'E', 'I', 'O', 'U']) ).

%% an article, or a contraction that ends in one: `el', `del', `al'
tr_article_word(Side, W) :- tr_determiner(Side, w(W, lower), _, article), !.
tr_article_word(foreign, W) :-
    tr_solve(contraction_of(W, J)), atomic_list_concat(Ps, ' ', J), last(Ps, A),
    tr_determiner(foreign, w(A, lower), _, article), !.

%% the capitalised words after a name's first, a word with a digit ending
%% them, and a small word only between two of them: the FIRST answer. For a
%% caller that needs more -- a run that is not empty, a word in it that no
%% lesson knows -- backtracking goes on past the word that ended the run, over
%% every capitalised word from there (the last clause): `con Marco Tg24
%% Tornaboni' is one name, where the first answer is empty because `Tg24'
%% ends it. These were two definitions 7 000 lines apart, and the second's
%% last clause repeated the first's, so that every answer came twice.
tr_cap_run([w(S, upper), W|Ws0], [w(S, upper)|Run], Ws) :-
    memberchk(S, [di, de, da, del, van, von, du, der]), W = w(_, upper), \+ tr_digit_word(W), !,
    tr_cap_run([W|Ws0], Run, Ws).
tr_cap_run([W|Ws0], [W|Run], Ws) :-
    W = w(S, upper), \+ memberchk(S, [di, de, da, del, van, von, du, der]), \+ tr_digit_word(W), !,
    tr_cap_run(Ws0, Run, Ws).
tr_cap_run(Ws, [], Ws).
tr_cap_run([w(W, upper)|Ws], [w(W, upper)|Run], Rest) :- !, tr_cap_run(Ws, Run, Rest).

%% A MONTH IS WRITTEN SMALL IN BOTH LANGUAGES, and a capital on one is the
%% writer's slip, not a name: `un mes de Febrero muy apretado' came out
%% `un mese di Febrero', the Spanish word passed through as somebody's name
%% -- AND A DAY, which is a time to the lesson: `la cumbre europea de
%% Colonia, que comienza el Jueves' came out `il Giovedì', the capital kept
tr_month_lower(english, Ws, Ws) :- !.
tr_month_lower(_, [], []).
%% (the SINGULAR only, which is what a date or a day names: `di Massimo
%% Lugli Roma - parla piangendo' is by Massimo Lugli, and `lugli' is the
%% plural of `luglio' to the lesson, so the surname lost its capital and the
%% byline was refused)
tr_month_lower(Side, [w(W, upper)|Ws0], [w(W, lower)|Ws]) :-
    tr_lexeme(Side, W, L, singular), ( tr_holds(month(L)) ; tr_holds(time(L)) ), !, tr_month_lower(Side, Ws0, Ws).
tr_month_lower(Side, [W|Ws0], [W|Ws]) :- tr_month_lower(Side, Ws0, Ws).

%% THE WORD AFTER A COLON IS A HEAD, and a known word goes lower as the head
%% of a sentence does (tr_head_lower/3): `Provengono studiosi, operatori, autori
%% di diverse espressioni: Rap, graffiti, teatro di strada, Grunge.' lists
%% what the experts work in, and the capital kept on `Rap' made it the first
%% of a list of names -- which three items cannot follow
tr_colon_lower(foreign, Ws0, Ws) :-
    append(A, [colon|B0], Ws0), !,
    tr_head_lower(foreign, B0, B1),
    tr_colon_lower(foreign, B1, B),
    append(A, [colon|B], Ws).
tr_colon_lower(_, Ws, Ws).

%% (never a quotation that closes inside the sentence before a determiner: `"cinici e diseducativi" i film' quotes the
%% two adjectives, and with the mark taken for the sentence's it came out `"The films are cynical and miseducative".'
%% A quotation the speaker's verb follows keeps it: `"in ogni caso" puntualizza lui, "comincerò ...')
%% A NAME AND A NUMBER OF ONE OR TWO DIGITS ARE ONE NAME: `Wargames di rai 1' is the channel Rai 1, as `Formula 1' and
%% `Canale 5' are names; read apart, the number was a count with no noun and the headline was refused. A name the lesson
%% states, in small letters too, or a capital word the lesson does not know
tr_name_numbers(foreign, [w(N, C), w(D, lower)|Ws0], [w(Name, upper)|Ws]) :-
    atom(D), atom_length(D, DL), DL =< 2, tr_digits_start(D), tr_digits(D), atom(N), \+ tr_digits(N),
    ( tr_solve(name(N)) -> true ; C == upper, \+ tr_known_word(foreign, N) ),
    \+ ( Ws0 = [w(NW, _)|_], atom(NW), tr_is(foreign, w(NW, lower), noun) ), !,       % a count: `a Roma 24 anni fa'
    tr_cap(N, NC), atomic_list_concat([NC, D], ' ', Name),
    tr_name_numbers(foreign, Ws0, Ws).
tr_name_numbers(Side, [W|Ws0], [W|Ws]) :- !, tr_name_numbers(Side, Ws0, Ws).
tr_name_numbers(_, [], []).
tr_head_mark([w(W, Q)|Ws], Stop0, [w(W, upper)|Ws], Stop) :-
    memberchk(Q, [qopen, qopenu]),
    \+ ( append(_, [w(_, C), D|_], Ws), memberchk(C, [qclose, qcloseu]), D = w(_, _), tr_determiner(foreign, D, _, _) ), !,
    tr_stop_open(Stop0, Stop).
tr_head_mark(Ws, Stop, Ws, Stop).
%% ... AND A CLOSING MARK ON THE LAST WORD OF A QUOTATION THAT OPENED AT THE
%% HEAD IS THE SENTENCE'S TOO: `"servono nove miliardi, ma prima il
%% tribunale potrebbe cancellare il Napoli".' The mark took the word's
%% capital with it, so `Napoli' was no name and the sentence was refused.
%% Taken off, the word is a name where no lesson knows it and a plain word
%% where one does, and the mark goes back before the stop.
tr_tail_mark(Side, Ws0, Stop0, Ws, Stop) :-
    tr_stop_parts(Stop0, [_|_], [], _, _),
    append(Front, [w(W, Q)], Ws0), memberchk(Q, [qclose, qcloseu]), !,
    %% (a capital word the lesson knows as a name and as nothing else keeps its capital, as in tr_quote_names/3:
    %% `potrebbe cancellare il Napoli".' was `could erase the naples', read as a common noun)
    ( tr_known_word(Side, W), \+ ( Q == qcloseu, tr_only_name(Side, W) ) -> C = lower ; C = upper ),
    append(Front, [w(W, C)], Ws),
    tr_stop_parts(Stop0, B, [], S, A), Stop = marks(B, [34], S, A).
tr_tail_mark(_, Ws, Stop, Ws, Stop).
%% ... AND A CAPITAL ON THE EDGE OF A QUOTATION INSIDE THE SENTENCE IS A
%% NAME WHERE THE LESSON DOES NOT KNOW THE WORD: `que "España ve con
%% simpatía la candidatura"'. The name is spelled with its mark, as a name
%% of several words in marks already is (`dal "Washington Post"'), which no
%% lesson knows and every writer puts back as it stood; a word the lesson
%% knows is the plain word with its mark, as it was.
%% ... AND ONE CAPITALISED WORD IN QUOTATION MARKS WHERE NO SENTENCE BEGINS
%% IS A NAME WHETHER OR NOT THE LESSON KNOWS THE WORD: `l'autopsia che verrà
%% effettuata al "Gemelli"' is the Gemelli hospital, and read as the word
%% it was `a los "gemelos"', the twins. Both marks on the one word say it is
%% quoted whole, and the capital no sentence gave it says it is a name; at
%% the head the capital may be the sentence's, and the rule above stands.
%% ... UNLESS THE WORD CAN BE THE NOUN OF THE DETERMINER BEFORE IT: `la
%% "Bastiglia"' is the Bastille, a noun the lesson knows in the number of
%% its article, and read as a name it went through untranslated, `la
%% "Bastiglia"', in three sentences of an old control. `al "Gemelli"' is a
%% name still: `il' is singular and `gemelli' the twins
tr_quote_names(Side, Ws0, Ws) :- tr_quote_names(Side, head, none, Ws0, Ws).
tr_quote_names(_, _, _, [], []).
tr_quote_names(Side, Where, Prev, [w(W, C)|Ws0], [w(W1, C1)|Ws]) :-
    tr_name_edge(C, Plain, Pre, Post), !,
    (   tr_known_word(Side, W), \+ tr_only_name(Side, W),
        \+ ( Where == later, C == qbothu, \+ tr_quoted_noun_fits(Side, Prev, W) )
    ->  W1 = W, C1 = Plain
    ;   tr_cap(W, WC), atomic_list_concat([Pre, WC, Post], W1), C1 = upper
    ),
    tr_quote_names(Side, later, w(W, C), Ws0, Ws).
%% ... AND A WORD IN SMALL LETTERS ALONE IN QUOTATION MARKS THAT NO LESSON
%% KNOWS IS KEPT AS IT STANDS: `Los "botiguers" prevén ...' is Catalan's
%% shopkeepers in the marks that set a word of another language apart, and
%% the whole sentence was refused for the one word. It is spelled with its
%% marks, as a name is, and every writer puts it back as it stood. (A number
%% in marks is no word to keep.)
tr_quote_names(Side, _, _, [w(W, qboth)|Ws0], [w(W1, upper)|Ws]) :-
    atom(W), \+ tr_known_word(Side, W), \+ tr_digits(W),
    atomic_list_concat(['"', W, '"'], W1), !,
    tr_quote_names(Side, later, w(W, qboth), Ws0, Ws).
tr_quote_names(Side, _, _, [X|Ws0], [X|Ws]) :- tr_quote_names(Side, later, X, Ws0, Ws).
%% (a word the lesson knows as a name and as nothing else is a name still: `señaló que "España ve con
%% simpatía la candidatura"' -- once `The name "españa" means "Spain".' made it a word the lesson knows,
%% it was read in small letters, as a common word is, and the sentence was refused)
tr_only_name(foreign, W) :- atom(W), tr_solve(name(W)), \+ tr_class_of(W, _), !.
%% the word is a noun of the lesson's in the number of the determiner or
%% the contraction before it
tr_quoted_noun_fits(Side, w(P, _), W) :-
    atom(P), atom(W),
    (   tr_determiner(Side, w(P, lower), DL, _) -> D = w(P, lower)
    ;   Side == foreign, tr_solve(contraction_of(P, J)), atomic_list_concat(Parts, ' ', J),
        last(Parts, A), D = w(A, lower), tr_determiner(Side, D, DL, _)
    ),
    tr_det_gender(Side, D, DL, _, Number), tr_noun_in_number(Side, W, Number), !.
tr_name_edge(qopenu, qopen, '"', '').
tr_name_edge(qcloseu, qclose, '', '"').
tr_name_edge(qbothu, qboth, '"', '"').
tr_stop_open(marks(B, S, A), marks([34|B], S, A)) :- !.
tr_stop_open(marks(B, I, S, A), marks([34|B], I, S, A)) :- !.
tr_stop_open(S, marks([34], [], S, [])).

tr_each_out([], _, []).
tr_each_out([ir(S, Stop)|Ss], Into, [Out|Outs]) :-
    tr_write_ir(Into, S, Stop, Out),
    tr_each_out(Ss, Into, Outs).

%% the target's lesson is set for EVERY sentence, because reading the one
%% before it may have set the source's
tr_write_ir(Into, S, Stop, Out) :-
    tr_side_of(Into, Side),
    tr_kind(Stop, Kind),
    tr_from_ir(Side, Kind, S, Stop, Out).

%% the side a language is read and written on: English is the IR's own,
%% and a lesson's language is the foreign side with that lesson set
tr_side_of(english, english) :- !.
tr_side_of(L, foreign) :- tr_into(L, from_english(L1)), tr_set_language(L1).

%% ... and the side a text is read on when the language was not named:
%% the words vote, as they do for reason_translate/2
tr_from_side(any, Words, Side) :- !, tr_way(any, Words, Side, _).
tr_from_side(english, Words, english) :- !, tr_english_language(Words).
tr_from_side(L, _, Side) :- tr_side_of(L, Side).

%% READING ENGLISH NEEDS A LESSON NAMED, because the English words the
%% reader knows are the ones some lesson gives a meaning for. The words
%% choose it, as they do for reason_translate/2; a text that fits two
%% lessons equally keeps whichever language is already set, which is what
%% makes reason_translate/4 exact -- it sets the target's first.
tr_english_language(Words) :-
    tr_language(L0),
    tr_languages(Ls),
    findall(v(L, F, E), ( member(L, Ls), tr_votes_in(L, Words, F, E) ), Vs),
    ( tr_winner(Vs, into, L1) -> tr_set_language(L1) ; tr_set_language(L0) ).

reason_learn(Text, Language, Terms) :-
    reason_text(Text, Terms), tr_lessons_moved,
    assert_once(lesson_language(Language)),
    forall(member(T, Terms), tr_learn_term(Language, T)),
    tr_mean_links(Terms, Links0),
    tr_gender_links(Language, Links0, Links),
    forall(member(T, Links), tr_learn_term(Language, T)),
    forall(tr_hyphen_link(Terms, T), tr_learn_term(Language, T)).

%% A NOUN THE LESSON STATES IN BOTH GENDERS KEEPS EACH MEANING WITH ITS
%% GENDER. `la final de copa' is the cup final and `el final' the end: the
%% vocabulary says `The masculine noun "final" means "end".' (for `al
%% final') and `The feminine noun "final" means "final".', and a lesson
%% says a word's gender and what it means but never which meaning goes with
%% which gender -- so `La final de copa entre Inglaterra y Alemania' came out
%% `The end of cup'. The sentence DID say it, as it says the class
%% (tr_mean_links/2), and the link is kept as mean_gender(Word, Meaning,
%% Gender) -- only where the store already states the word in the OTHER
%% gender, because every noun of a vocabulary names one and a link for each
%% would be twenty thousand rows for one word. So of two such sentences the
%% later is linked and the earlier is the word's first meaning, which the
%% other gender takes by leaving out what is linked (tr_gendered_noun/4).
tr_gender_links(_, [], []).
tr_gender_links(Language, [gender_candidate(W, E, G)|Ls0], Ls) :- !,
    (   tr_other_gender(G, G2), tr_lesson_fact(Language, G2, W)
    ->  Ls = [mean_gender(W, E, G)|Ls1]
    ;   Ls = Ls1
    ),
    tr_gender_links(Language, Ls0, Ls1).
tr_gender_links(Language, [L|Ls0], [L|Ls]) :- tr_gender_links(Language, Ls0, Ls).

tr_other_gender(masculine, feminine).
tr_other_gender(feminine, masculine).

%% a fact the named lesson STATES, never one its rules prove: `Every noun
%% that ends in "a" is feminine' would make every masculine noun in `-a' a
%% word of both genders
tr_lesson_fact(Language, Name, W) :-
    G =.. [Name, W], tr_namespaced(Language, G, F), functor(F, N, A),
    tr_solve_plain(lesson_predicate(N, Language, A)), tr_solve_plain(F), !.

%% A WORD WITH A HYPHEN IS FOUND BY THE WORDS THE TOKENISER READS IN IT. `a
%% corto-medio plazo' is in the short to medium term, and the tokeniser reads
%% the hyphen between two letters as a blank, so the text's words are `a',
%% `corto', `medio' and `plazo' -- which no join of them spells as the lesson
%% does. The lesson spells the word as the text does, and each such word is
%% kept under the spelling a join makes of it as well, hyphen_spelling(Blank,
%% Word), which tr_join_word/2 asks when the plain join is no word.
tr_hyphen_link(Terms, hyphen_spelling(B, W)) :-
    member(T, Terms), ( T = mean(W, _) ; T = plural_of(W, _) ),
    atom(W), sub_atom(W, _, 1, _, '-'), !,
    atomic_list_concat(Parts, '-', W), atomic_list_concat(Parts, ' ', B), B \== W.

%% A MEANING KEEPS THE CLASS ITS SENTENCE GAVE IT. `The noun "culpable"
%% means "culprit".' and `The adjective "culpable" means "guilty".' say two
%% things each, and the terms keep them apart -- noun(culpable),
%% mean(culpable, culprit), adjective(culpable), mean(culpable, guilty) --
%% so a lesson could say what a word means and what classes it has and never
%% which meaning belongs to which class, and the first meaning won wherever
%% one had to be chosen: `Los hombres son culpables' came out `The men are
%% culprit'. The sentence DID say it; the reader's terms come in sentence
%% order with the class before the meaning, so the class fact nearest before
%% a mean/2 of the same word is the class of that meaning, and it is kept
%% as mean_as(Word, Meaning, Class). tr_meanings_of/4 asks it first.
%%
%% AND A VERB'S MEANING THE SENTENCE CALLS INTRANSITIVE IS LINKED UNDER THAT
%% NAME TOO: `The intransitive verb "destaca" means "stands out".' is what the
%% verb means when its clause has no object. The adjective is the SENTENCE's,
%% as the class is -- the reader gives verb(destaca), intransitive(destaca),
%% mean(destaca, 'stands out'), the class, its adjectives, the claim -- so it
%% is kept with the class and spent on the one meaning after it. 1.7.0 linked
%% every verb meaning of a word some sentence of the same text called
%% intransitive, so `The verb "destaca" means "highlights".' beside it was
%% intransitive too, and what a store held depended on which 400 lines a
%% teach had read together.
tr_mean_links(Terms, Links) :- tr_mean_links(Terms, none, Links).
tr_mean_links([], _, []).
tr_mean_links([mean(W, E)|Ts], W0-C-As, [mean_as(W, E, C)|Ls0]) :- W == W0, !,
    (   C == verb, memberchk(intransitive, As) -> Ls0 = [mean_as(W, E, intransitive)|Ls]
    %% ... and one the sentence calls TRANSITIVE is what the verb means with a
    %% phrase for its object, kept under the MEANING so that the writer, which
    %% has the meaning in hand, finds it by an indexed lookup
    ;   C == verb, memberchk(transitive, As) -> Ls0 = [transitive_sense(E, W)|Ls]
    %% ... and one it calls PROGRESSIVE is what the verb means before a
    %% gerund (tr_verb_across/5)
    ;   C == verb, memberchk(progressive, As) -> Ls0 = [mean_as(W, E, progressive)|Ls]
    %% ... and one it calls CLAUSAL is what the verb means before a clause of
    %% `that' (tr_verb_across/5)
    ;   C == verb, memberchk(clausal, As) -> Ls0 = [mean_as(W, E, clausal)|Ls]
    %% ... and one it calls DURATIVE is what the verb means with a span of
    %% time and an object (tr_verb_across/5): `esperó siete horas la salida'
    %% waited seven hours for it
    ;   C == verb, memberchk(durative, As) -> Ls0 = [mean_as(W, E, durative)|Ls]
    %% ... and one it calls INFINITIVAL is what the verb means before an
    %% infinitive (tr_verb_across/5)
    ;   C == verb, memberchk(infinitival, As) -> Ls0 = [mean_as(W, E, infinitival)|Ls]
    %% ... and an adverb it calls ADJECTIVAL is what it means before an
    %% adjective or a participle (tr_cross_comps/2)
    ;   C == adverb, memberchk(adjectival, As) -> Ls0 = [mean_as(W, E, adjectival)|Ls]
    %% ... and a verb it calls REFLEXIVE is what the verb means with its own
    %% pronoun (tr_verb_across/5): `se ha convertido en' has become
    ;   C == verb, memberchk(reflexive, As) -> Ls0 = [mean_as(W, E, reflexive)|Ls]
    %% ... and a verb it calls PERSONAL is what the verb means with a person
    %% for its object (tr_verb_across/5): `ha investito la ragazza' ran her over
    ;   C == verb, memberchk(personal, As) -> Ls0 = [mean_as(W, E, personal)|Ls]
    %% ... and a noun's GENDER, as a candidate reason_learn/3 keeps only for a
    %% word the lesson states in both genders (tr_gender_links/3)
    ;   C == noun, member(G, [masculine, feminine]), memberchk(G, As) -> Ls0 = [gender_candidate(W, E, G)|Ls]
    %% ... and a noun it calls COLLECTIVE is what the noun means where its
    %% phrase does something (tr_cross_np/2): `el pasaje destiló tanta
    %% indignación' is the passengers, `el pasaje de Vintró' the passage
    ;   C == noun, memberchk(collective, As) -> Ls0 = [mean_as(W, E, collective)|Ls]
    ;   Ls0 = Ls
    ),
    tr_mean_links(Ts, W0-C-[], Ls).
tr_mean_links([T|Ts], _, Ls) :-
    T =.. [C, W], atom(W), tr_link_class(C), !, tr_mean_links(Ts, W-C-[], Ls).
tr_mean_links([T|Ts], W0-C-As, Ls) :-
    T =.. [A, W], W == W0, !, tr_mean_links(Ts, W0-C-[A|As], Ls).
tr_mean_links([_|Ts], Last, Ls) :- tr_mean_links(Ts, Last, Ls).

tr_link_class(C) :- memberchk(C, [noun, adjective, verb, adverb, preposition, pronoun, conjunction, article,
                                  possessive, demonstrative, determiner, modal, auxiliary, number, name]).

%% A FACT GOES IN THE LANGUAGE'S OWN NAMESPACE, AND A RULE STAYS IN
%% lesson/2. `lesson(Language, Term)' put the language atom in the first
%% argument of every row, and cocolog's first-argument index keys on that
%% -- so with a vocabulary in the store every mean(casa, X) lookup walked
%% the whole language. Measured on 280 933 terms, Italian and Spanish in
%% one store: one sentence took over FOUR MINUTES of user CPU against
%% 0.348 s on a plain single-language store of the same vocabulary. A
%% fact is asserted as 'spanish:mean'(casa, house) instead, so the index
%% keys on `casa' exactly as a plain lesson's does. The rules are few --
%% a few dozen a lesson against a hundred thousand facts -- and they must
%% NOT become real clauses, because the engine would then resolve their
%% BODIES against the plain knowledge base rather than through
%% tr_body/2; so they stay as they were, and lesson/2 now holds nothing
%% else.
tr_learn_term(L, (H :- B)) :- !, assertz(lesson(L, (H :- B))).
tr_learn_term(L, T) :-
    tr_namespaced(L, T, F),
    functor(F, N, A), assert_once(lesson_predicate(N, L, A)),
    assertz(F).

%% a goal of a named lesson, under the language's own name -- the same
%% arguments, so the index sees what it saw when the lesson was plain
tr_namespaced(L, G, F) :-
    G =.. [Name|Args],
    tr_prefix(L, P), atom_concat(P, Name, N),
    F =.. [N|Args].

%% the prefix on and off: atom_concat/3 has the (+,-,+) mode that takes
%% it off, where atomic_list_concat/2 cannot split at all
tr_prefix(L, P) :- atom_concat(L, ':', P).

assert_once(G) :- ( tr_solve_plain(G) -> true ; assertz(G) ).

%% what a named lesson holds, and how to forget one: nothing outside this
%% file names a row's shape, which is what let the shape change
reason_lesson(L, T) :- tr_solve_plain(lesson_language(L)), tr_lesson_term(L, T).

tr_lesson_term(L, (H :- B)) :- tr_solve_plain(lesson(L, (H :- B))).
tr_lesson_term(L, T) :-
    tr_solve_plain(lesson_predicate(N, L, A)),
    functor(F, N, A), tr_solve_plain(F),
    tr_plain_term(L, F, T).

tr_plain_term(L, F, T) :-
    F =.. [N|Args],
    tr_prefix(L, P), atom_concat(P, Name, N), !,
    T =.. [Name|Args].

reason_unlearn(L) :-
    tr_lessons_moved,
    forall(tr_solve_plain(lesson_predicate(N, L, A)),
           ( functor(F, N, A), retractall(F) )),
    retractall(lesson_predicate(_, L, _)),
    retractall(lesson(L, _)),
    retractall(lesson_language(L)).

reason_untranslated(Text, Words) :- reason_untranslated(Text, any, Words).

%% AND NAMING THE LANGUAGE SKIPS THE VOTE AND THE ENGLISH SIDE WITH IT.
%% With `any' the words must settle a language, and settling one asks
%% tr_known_word(english, W) -- which is mean(_, W), the UNBOUND
%% direction, where the index keys 0 and skips nothing. Named, every
%% question is asked with the lesson's word bound, and the walk is gone.
%% The page path knows the language it was given, so it says so.
reason_untranslated(Text, From, Words) :-
    tr_pieces(Text, Pieces),
    findall(W, ( member(Piece0-_, Pieces), tr_caps_piece(Piece0, Piece), tr_piece_words(Piece, Ws0c),
                 tr_uncomma(Ws0c, Ws), tr_unknown_in(From, Ws, W) ),
            Ws0),
    list_to_set(Ws0, Words).

%% THE SIDE THE WORDS SETTLE IS WORKED OUT ONCE FOR THE PIECE, not once
%% per word. tr_way/4 runs the VOTE -- every language against every word,
%% both sides -- and asking it inside the per-word loop made this
%% quadratic in the words with the languages on top: measured over a
%% vocabulary of two languages, ONE four-word sentence cost 84 383 344
%% inferences and 64 SECONDS. The vote is one pass now, and the language
%% it settled is put back before each word is tested, because the
%% fallback below sets its own while it walks the languages.
tr_unknown_in(From, Ws, W) :-
    (   From \== any, catch(tr_side_of(From, S0), _, fail)
    ->  Side = S0, tr_language(Voted)
    ;   tr_way(any, Ws, F0, _)
    ->  Side = F0, tr_language(Voted)
    ;   Side = none, Voted = none
    ),
    tr_languages(Ls),
    %% (a name the reader joins is no word to report: `del Telenotícies
    %% migdia' named `migdia', which the reader reads as the name's)
    (   Side == foreign
    ->  once(tr_particle_names(foreign, first, Ws, WsN)), tr_joined_words(foreign, WsN, Ws1)
    ;   Ws1 = Ws
    ),
    member(w(W, Case), Ws1),
    ( \+ memberchk(Case, [upper, qopenu, qcloseu, qbothu]) ; en_question(W, _) ),
    tr_set_language(Voted),
    \+ tr_known_anywhere(Side, Ls, W).

%% known on the side the words settle, or, when they settle nothing, on
%% any side of any lesson; English's own function words are known
tr_known_anywhere(_, _, W) :- en_function(W), !.
tr_known_anywhere(Side, _, W) :- Side \== none, !, tr_known_word(Side, W).
tr_known_anywhere(_, Ls, W) :-
    member(L, Ls), tr_set_language(L),
    ( tr_known_word(foreign, W) ; tr_known_word(english, W) ), !.

%% into English, or into a language: one learned under that name, or the
%% plain lesson when it named itself so (`Spanish is a language')
tr_into(english, to_english) :- !.
tr_into(L, from_english(L)) :- atom(L), tr_solve_plain(lesson_language(L)), !.
tr_into(L, from_english(none)) :- atom(L), tr_solve_plain(language(L)), !.
tr_into(L, _) :- throw(error(domain_error(language, L), reason_translate/3)).

tr_each([], _, []).
tr_each([Piece-_|Ps], Way, Outs) :- tr_piece_words(Piece, []), !, tr_each(Ps, Way, Outs).
tr_each([Piece0-Stop|Ps], Way, [Out|Outs]) :-
    nb_setval('$tr_xnames', []),
    tr_caps_piece(Piece0, Piece),
    tr_piece_words(Piece, Words0), Words0 \== [],
    tr_way(Way, Words0, From, To),
    tr_quote_names(From, Words0, Words0n),
    tr_letter_runs(From, Words0n, Words0l),
    tr_small_head_note(From, Words0l),
    tr_head_lower(From, Words0l, Words1),
    tr_joined_words(From, Words1, Words),
    tr_translate(Words, From, To, Stop, Out),
    tr_each(Ps, Way, Outs).

%% LETTERS THE SOURCE SPACED OUT ARE AN ACRONYM: `il c s m aveva espresso' is
%% the CSM, the Consiglio superiore della magistratura, and read letter by
%% letter it was three words no lesson knows and the sentence was refused. A
%% run of two letters or more, none of them a word of the lesson's, is one
%% name in capitals, spelled as written.
tr_letter_runs(english, Ws, Ws) :- !.
tr_letter_runs(foreign, [], []).
%% (a bracket of letters and nothing else stays as it stood: `(r c)' is the
%% province, Reggio Calabria, written back by letters/1)
tr_letter_runs(foreign, [lparen|Ws0], Out) :-
    tr_letter_run(Ws0, [rparen|Rest], Letters), Letters = [_|_], !,
    append([lparen|Letters], [rparen|Out1], Out), tr_letter_runs(foreign, Rest, Out1).
tr_letter_runs(foreign, [W|Ws0], Out) :-
    tr_lone_letter(W), tr_letter_run(Ws0, Rest, More), More = [_|_], !,
    findall(U, ( member(w(L, _), [W|More]), upcase_atom(L, U) ), Us), atomic_list_concat(Us, A),
    Out = [w(A, upper)|Out1], tr_letter_runs(foreign, Rest, Out1).
tr_letter_runs(foreign, [W|Ws0], [W|Ws]) :- tr_letter_runs(foreign, Ws0, Ws).
tr_letter_run([W|Ws], Rest, [W|More]) :- tr_lone_letter(W), !, tr_letter_run(Ws, Rest, More).
tr_letter_run(Ws, Ws, []).
tr_lone_letter(w(L, lower)) :-
    atom(L), atom_codes(L, [C]), C < 128, tr_letter_code(C), \+ tr_known_word(foreign, L).

%% THE WORDS A SENTENCE IS READ IN: a word of several words joined, the
%% contractions expanded, and the joins made again. A word of several words
%% may CONTAIN a contraction -- `vigili del fuoco' (firefighters),
%% `dall'alto' (from above) -- and then it is only found before `del' is
%% `di il'; or it may be made of what a contraction expands to -- `fin
%% dalle prime ore' is `fin da' and `le' -- and then it is only found after.
%% Once each way, the longest join first both times.
tr_joined_words(Side, Words0, Words) :-
    tr_multi(Side, Words0, Words1),
    tr_expand(Side, Words1, Words2),
    tr_multi(Side, Words2, Words3),
    tr_enclitics(Side, Words3, Words4),
    tr_enclitic_multi(Side, Words4, Words5),
    tr_particles(Side, Words5, Words6),
    tr_name_links(Side, Words6, Words7),
    tr_number_ranges(Side, Words7, Words7t),
    tr_than_split(Side, Words7t, Words7u),
    tr_expletive_off(Side, Words7u, Words8),
    tr_unjoin_relative(Side, Words8, Words8b),
    tr_unjoin_when(Side, Words8b, Words9a),
    tr_unjoin_demonstrative(Side, Words9a, Words9c),
    tr_unjoin_ordinal(Side, Words9c, Words9d),
    tr_unjoin_pronoun_adj(Side, Words9d, Words9b),
    tr_first_days(Side, Words9b, Words9),
    tr_a_que_inf(Side, Words9, Words9q),
    tr_drop_contrast_yes(Side, Words9q, Words).

%% A PERSON, `a que' AND A SUBJUNCTIVE STRAIGHT AFTER IT ARE THE PERSON AND WHAT IT IS MOVED TO DO: `la coalición
%% radical animó al PNV a que acepte los reproches de ETA' encouraged the PNV to accept them, and read as the PNV's
%% relative clause, `a que' to which, the sentence had no reading in either language. The subjunctive is its verb's
%% infinitive after the word for `to', as `animó al PNV a aceptar' is read: after a name or a person's noun only, and
%% only where the verb stands straight after `que', so that a clause with its own subject keeps its verb
%% (the words for `that' a list made once for the lessons and the language, asked first at each place: the lexicon
%% asked of every word, and the words before it walked, cost every sentence of the controls some 1 300 inferences)
tr_a_que_inf(foreign, Ws0, Ws) :-
    tr_a_que_match(Ws0, Pre, AW, IW, Post), !,
    append(Pre, [AW, IW|Post], Ws).
tr_a_que_inf(_, Ws, Ws).
tr_a_que_match(Ws0, Pre, w(A, AC), w(I, VC), Post) :-
    tr_gen_words(that, Ts), member(Q, Ts), memberchk(w(Q, _), Ws0),
    append(Pre1, [w(Q, _), w(V, VC)|Post], Ws0), atom(V), tr_solve(subjunctive_of(V, L)),
    append(Pre, [w(A, AC)], Pre1), atom(A), tr_means_to(A), last(Pre, w(D, DC)), atom(D),
    tr_solve(infinitive_of(I, L)),
    ( DC == upper -> true ; tr_doer_noun(w(D, DC)) ), !.
%% (a list of words made once for the lessons and the language: the conjunctions for `that', and the degree words)
tr_gen_words(K, Ts) :-
    nb_getval('$tr_lessons', G0), tr_language(To), G = G0/To, atom_concat('$tr_words_', K, Key),
    (   tr_global(Key, G-Ts) -> true
    ;   findall(Q, tr_gen_word(K, Q), Ts0), sort(Ts0, Ts), nb_setval(Key, G-Ts)
    ).
tr_gen_word(that, Q) :- tr_solve(mean(Q, that)), tr_class_of(Q, conjunction).
tr_gen_word(degree, Q) :- tr_solve(begin(Q, comparative)).
tr_gen_word(focusnoun, Q) :-
    member(E, [also, even]), tr_solve(mean(Q, E)), atom(Q),
    tr_is(foreign, w(Q, lower), adverb), tr_is(foreign, w(Q, lower), noun), \+ tr_is(foreign, w(Q, lower), adjective).

%% THE FIRST OF A MONTH IS ITS DAY ONE: `dal primo luglio al 31 agosto' is
%% from July 1 to August 31 -- Italian writes the first day with the ordinal,
%% and read as an adjective of the month it was `from the first July' (`desde
%% el primer julio'). The word the lesson says means `first' right before a
%% month, or before the word for `of' and a month (Spanish's `el primero de
%% julio'), is the count 1, as `31' is in the date after it
tr_first_days(foreign, Ws0, Ws) :-
    %% (the months looked up once, and each word against them: asked as a lexeme of every word it was
    %% six hundred inferences a sentence of the controls)
    findall(M, tr_solve(month(M)), Ms), Ms \== [],
    once(( member(w(W, _), Ws0), atom(W), memberchk(W, Ms) )), !, tr_first_days0(Ws0, Ws).
tr_first_days(_, Ws, Ws).
tr_first_days0([], []).
tr_first_days0([w(F, C), M|Ws0], [w('1', C), M|Ws]) :-
    atom(F), M = w(_, _), tr_first_word(F), tr_month(foreign, M), !, tr_first_days0(Ws0, Ws).
tr_first_days0([w(F, C), w(D, DC), M|Ws0], [w('1', C), w(D, DC), M|Ws]) :-
    atom(F), atom(D), M = w(_, _), tr_first_word(F), tr_means_of(D), tr_month(foreign, M), !, tr_first_days0(Ws0, Ws).
tr_first_days0([W|Ws0], [W|Ws]) :- tr_first_days0(Ws0, Ws).
tr_first_word(F) :- tr_lexeme(foreign, F, L, _), tr_class_of(L, adjective), tr_solve(mean(L, first)), !.
%% AN ARTICLE AND THE WORD FOR `FIRST' BEFORE THE RELATIVE ARE A PHRASE AND ITS CLAUSE: `è stata la prima che ho
%% sentito' is the first one I heard, and `prima che' is the lesson's `before', a connector of two words, which read
%% so made `la' a pronoun and the rest a clause of `before' (`la ha sido antes de que haya sentido'). After an
%% article the two words are taken apart again
tr_unjoin_ordinal(foreign, Ws0, Ws) :-
    once(( member(w(J, _), Ws0), atom(J), atomic_list_concat([_, _], ' ', J) )), !, tr_unjoin_ordinal0(Ws0, Ws).
tr_unjoin_ordinal(_, Ws, Ws).
tr_unjoin_ordinal0([], []).
tr_unjoin_ordinal0([A, w(J, JC)|Ws0], [A, w(F, JC), w(R, lower)|Ws]) :-
    A = w(AW, _), atom(AW), atom(J), tr_determiner(foreign, A, _, article),
    atomic_list_concat([F, R], ' ', J), tr_first_word(F), tr_relative_word(foreign, R), !,
    tr_unjoin_ordinal0(Ws0, Ws).
tr_unjoin_ordinal0([W|Ws0], [W|Ws]) :- tr_unjoin_ordinal0(Ws0, Ws).
%% A PRONOUN OF QUANTITY AND AN ADJECTIVE ARE ONE PHRASE, WITH THE WORD THE LESSON PUTS BETWEEN THEM: `C'è qualcosa di
%% nuovo nella sala riunioni' is something new -- `di nuovo' is the lesson's `again', an adverb of two words the reader
%% joins wherever they stand, and `There is something again' was written. After a pronoun that takes the word before
%% an adjective (`"qualcosa" takes "di" before the adjective.') the two words are taken apart again
tr_unjoin_pronoun_adj(foreign, Ws0, Ws) :-
    once(( append(_, [w(W, _), w(J, _)|_], Ws0), atom(W), atom(J), atomic_list_concat([P, _], ' ', J),
           tr_solve(take_before(W, P, adjective)) )), !,
    tr_unjoin_padj0(Ws0, Ws).
tr_unjoin_pronoun_adj(_, Ws, Ws).
tr_unjoin_padj0([], []).
tr_unjoin_padj0([w(W, C), w(J, JC)|Ws0], [w(W, C), w(P, JC), w(A, lower)|Ws]) :-
    atom(W), atom(J), atomic_list_concat([P, A], ' ', J), tr_solve(take_before(W, P, adjective)),
    tr_is(foreign, w(A, lower), adjective), !,
    tr_unjoin_padj0(Ws0, Ws).
tr_unjoin_padj0([W|Ws0], [W|Ws]) :- tr_unjoin_padj0(Ws0, Ws).

%% A PREPOSITION AND A DEMONSTRATIVE THE LESSON JOINS INTO AN ADVERB ARE THE
%% PREPOSITION AND ITS PHRASE'S DETERMINER BEFORE A NOUN: `per chi ha scelto
%% Cortina per questo fine settimana' is for this weekend -- `per questo' is
%% for that reason only where no noun follows it. Read as the adverb, the
%% weekend was a bare noun the verb chose, and the sentence's left half had
%% no reading (`ha escogido a Cortina por eso fin de semana para quién')
tr_unjoin_demonstrative(foreign, Ws0, Ws) :-
    once(( member(w(J, _), Ws0), atom(J), atomic_list_concat([_, _|_], ' ', J) )), !, tr_unjoin_dem0(Ws0, Ws).
tr_unjoin_demonstrative(_, Ws, Ws).
tr_unjoin_dem0([], []).
tr_unjoin_dem0([w(J, C), N|Ws0], [w(P, C), w(D, lower), N|Ws]) :-
    atom(J), atomic_list_concat([P, D], ' ', J),
    tr_determiner(foreign, w(D, lower), _, demonstrative), tr_is(foreign, w(P, lower), preposition),
    N = w(NW, _), atom(NW), tr_is(foreign, N, noun), \+ tr_determiner(foreign, N, _, _),
    tr_lexeme(foreign, J, L, _), tr_class_of(L, adverb), !,
    tr_unjoin_dem0(Ws0, Ws).
tr_unjoin_dem0([W|Ws0], [W|Ws]) :- tr_unjoin_dem0(Ws0, Ws).

%% `MORE THAN' BEFORE A COUNT AND THE COMPARISON ANYWHERE ELSE: `nessuno abbia
%% più di una rete' is more than one network and `basta assai meno del 50,1%'
%% less than 50.1% -- read as the adverb and a phrase of `of', English wrote
%% `has of a net more', and in a denied clause `anymore'. The lesson states the
%% two words as one adverb (`The adverb "più di" means "more than".', as
%% Spanish's `más de'), which the reader joins wherever they stand; but where
%% the second word is also the lesson's word for `than' (`The word "di" means
%% "than".', Italian's and not Spanish's) the pair is the comparison too:
%% `mangia più di me', `dorme più di prima'. So the adverb is taken apart
%% again unless a count follows it: a number, an indefinite article, or an
%% article and a number or a percentage
tr_than_split(foreign, Ws0, Ws) :-
    once(( member(w(J, _), Ws0), atom(J), tr_than_adverb(J, _, _) )), !,
    tr_than_split0(Ws0, Ws).
tr_than_split(_, Ws, Ws).
tr_than_split0([], []).
tr_than_split0([w(J, C)|Ws0], [w(A, C), w(D, lower)|Ws]) :-
    atom(J), tr_than_adverb(J, A, D), \+ tr_count_next(Ws0), !,
    tr_than_split0(Ws0, Ws).
tr_than_split0([W|Ws0], [W|Ws]) :- tr_than_split0(Ws0, Ws).
%% an adverb of two words that means `more than' or `less than' and ends on
%% the lesson's word for `than'
tr_than_adverb(J, A, D) :-
    sub_atom(J, _, 1, _, ' '), atomic_list_concat([A, D], ' ', J),
    tr_lexeme(foreign, J, L, _), tr_class_of(L, adverb),
    ( tr_solve(mean(L, 'more than')) ; tr_solve(mean(L, 'less than')) ),
    tr_lexeme(foreign, D, DL, _), tr_solve(mean(DL, than)), !.
tr_count_next([N|_]) :- tr_count_word(foreign, N), !.
tr_count_next([N|_]) :- tr_indefinite(foreign, N), !.
tr_count_next([D, N|_]) :- tr_determiner(foreign, D, _, article), tr_count_word(foreign, N), !.

%% THE DENIAL RIGHT AFTER `UNLESS' DENIES NOTHING: `non possa essere membro del
%% governo a meno che non si liberi entro un anno' is unless he frees himself --
%% Italian's `a meno che' takes the `non' its clause does not mean, and read as a
%% denial it was `unless one does not release'. A connector of several words that
%% means `unless', and the word for `not' before its clause's first verb
tr_expletive_off(foreign, Ws0, Ws) :-
    once(( member(w(K, _), Ws0), atom(K), sub_atom(K, _, 1, _, ' '), tr_unless_word(K) )), !,
    tr_expletive_off0(Ws0, Ws).
tr_expletive_off(_, Ws, Ws).
tr_expletive_off0([], []).
tr_expletive_off0([w(K, C)|Ws0], [w(K, C)|Ws]) :-
    atom(K), tr_unless_word(K),
    %% (after the clause's subject too: `a meno che il gatto non mangi', the
    %% denial before the clause's first verb)
    append(Pre, [w(N, _)|Post], Ws0), atom(N), tr_negation_word(N),
    \+ ( member(w(V, _), Pre), atom(V), tr_verb_form_word(V) ), \+ memberchk(comma, Pre), !,
    append(Pre, Post, Ws1), tr_expletive_off0(Ws1, Ws).
tr_expletive_off0([W|Ws0], [W|Ws]) :- tr_expletive_off0(Ws0, Ws).
%% (and `until': `hasta que no se haya resuelto el caso' is until it has been solved, Spanish's `hasta que' taking the
%% `no' as `a meno che' does)
tr_unless_word(K) :- tr_lexeme(foreign, K, L, _), ( tr_solve(mean(L, unless)) ; tr_solve(mean(L, until)) ), !.

%% `PERO SÍ' BEFORE A PREPOSITION IS A CONTRAST AND NOTHING ELSE: `no convence con lo que dice,
%% pero sí con lo que hace' is but with what he does -- `sí' there is the stress the verb left
%% out would have carried, and read as a word it was `itself' or `yes'. Dropped after `but'
%% when a preposition follows; before a verb (`pero sí duerme') it is the adverb of the clause
tr_drop_contrast_yes(foreign, Ws0, Ws) :-
    ( memberchk(w('sí', _), Ws0) ; memberchk(w('sì', _), Ws0) ), !,
    tr_drop_contrast_yes0(Ws0, Ws).
tr_drop_contrast_yes(_, Ws, Ws).
tr_drop_contrast_yes0([], []).
tr_drop_contrast_yes0([w(B, BC), w(Y, _), P|Ws0], [w(B, BC)|Ws]) :-
    atom(B), memberchk(B, [pero, sino, ma]), memberchk(Y, ['sí', 'sì']),
    tr_is(foreign, P, preposition), !,
    tr_drop_contrast_yes0([P|Ws0], Ws).
tr_drop_contrast_yes0([W|Ws0], [W|Ws]) :- tr_drop_contrast_yes0(Ws0, Ws).

%% A CONNECTOR OF THREE WORDS THAT NO COMMA OPENS IS A PREPOSITION AND ITS RELATIVE:
%% `no convence a nadie con lo que dice' is with what he says, and joined it was
%% `so he says'. `, con lo que ha aumentado el prestigio' is the connector, the
%% consequence a comma parts from its clause; with none before it, and at the head
%% of a piece (`Por lo que sé') it is the three words, and the phrase `lo que' is
%% read as the relative it is
tr_unjoin_relative(foreign, Ws0, Ws) :-
    once(( tr_comma_connector(J), memberchk(w(J, _), Ws0) )), !,
    tr_unjoin_relative0(none, Ws0, Ws).
tr_unjoin_relative(_, Ws, Ws).
tr_unjoin_relative0(_, [], []).
tr_unjoin_relative0(Prev, [w(J, C)|Ws0], Out) :-
    Prev \== comma, atom(J), J \== 'de lo que', tr_comma_connector(J),
    Ws0 = [w(V, _)|_], atom(V), tr_verb_form_word(V), !,
    atomic_list_concat([P1|Parts], ' ', J), tr_join_case(C, lower, C1),
    findall(w(P, lower), member(P, Parts), Ps),
    Out = [w(P1, C1)|Out1], append(Ps, Rest, Out1),
    tr_unjoin_relative0(w(J, C), Ws0, Rest).
%% ... AND `DE LO QUE' AFTER A WORD THAT SAYS HOW MUCH OF IT: `nada de lo que hoy es el equipo' is
%% nothing of what the team is today, and joined it was the `than what' of `más de lo que recibe'
tr_unjoin_relative0(w(Q, _), [w('de lo que', C)|Ws0], Out) :-
    atom(Q), tr_quantity_word(Q), !,
    tr_join_case(C, lower, C1),
    Out = [w(de, C1), w(lo, lower), w(que, lower)|Rest],
    tr_unjoin_relative0(w('de lo que', C), Ws0, Rest).
tr_unjoin_relative0(_, [W|Ws0], [W|Ws]) :- tr_unjoin_relative0(W, Ws0, Ws).
%% A CONNECTOR THAT IS A PHRASE AND ITS RELATIVE IS THE PHRASE AFTER A VERB: `Il giorno in cui Dini
%% si dimetterà, tutti ...' is when he resigns, and `Sembra ancora lontano, comunque, il giorno in
%% cui si potrà tornare a fare il bagno' is the day on which one can -- the subject of `sembra', and
%% joined it was the connector, `Still seem, far anyway when one will be able'. A joined word of an
%% article, a noun, a preposition and the relative (`il giorno in cui', `el día en que') is taken
%% apart after a verb, never at the head of a clause or after a conjunction
tr_unjoin_when(foreign, Ws0, Ws) :-
    once(( member(w(J, _), Ws0), tr_np_connector(J) )), !,
    tr_unjoin_when0(no, none, Ws0, Ws).
tr_unjoin_when(_, Ws, Ws).
tr_unjoin_when0(_, _, [], []).
tr_unjoin_when0(yes, Prev, [w(J, C)|Ws0], Out) :-
    atom(J), tr_np_connector(J), \+ ( Prev = w(P, _), atom(P), tr_is(foreign, Prev, conjunction) ), !,
    atomic_list_concat([P1|Parts], ' ', J), tr_join_case(C, lower, C1),
    findall(w(P, lower), member(P, Parts), Ps),
    Out = [w(P1, C1)|Out1], append(Ps, Rest, Out1),
    tr_unjoin_when0(yes, w(J, C), Ws0, Rest).
tr_unjoin_when0(V0, _, [W|Ws0], [W|Ws]) :-
    ( V0 == yes -> V = yes ; W = w(X, _), atom(X), tr_verb_form_any(X) -> V = yes ; V = no ),
    tr_unjoin_when0(V, W, Ws0, Ws).
tr_np_connector(J) :- atomic_list_concat([A, _, _, R], ' ', J), memberchk(A, [il, el, la, lo]), memberchk(R, [cui, que]), !.
tr_comma_connector('con lo que').
tr_comma_connector('por lo que').
tr_comma_connector('de lo que').

%% TWO NEXT NUMBERS WITH A DASH BETWEEN THEM ARE EITHER: `una delle quattro -
%% cinque squadre' is one of the four or five teams, and the dash says what the
%% lesson's word for `or' says. Only a count and the next one (`4 - 5', `quattro
%% - cinque'): `10 - 15 persone' is a range, which `or' would not be
tr_number_ranges(foreign, Ws0, Ws) :- memberchk(dash, Ws0), tr_number_ranges0(Ws0, Ws), !.
tr_number_ranges(_, Ws, Ws).
tr_number_ranges0([], []).
tr_number_ranges0([w(A, AC), dash, w(B, BC)|Ws0], [w(A, AC), w(O, lower)|Ws]) :-
    tr_range_value(A, VA), tr_range_value(B, VB), VB =:= VA + 1,
    once(( tr_solve(mean(O, or)), tr_class_of(O, conjunction) )), !,
    tr_number_ranges0([w(B, BC)|Ws0], Ws).
tr_number_ranges0([W|Ws0], [W|Ws]) :- tr_number_ranges0(Ws0, Ws).
tr_range_value(W, V) :- atom(W), tr_digits(W), atom_number(W, V), !.
tr_range_value(W, V) :-
    atom(W), tr_is(foreign, w(W, lower), number), tr_lexeme(foreign, W, L, _),
    tr_solve(mean(L, E)), nth0(V, [zero, one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve,
                                   thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty], E), !.

%% A CATALAN ELISION BETWEEN TWO CAPITALISED WORDS IS PART OF A NAME: `el
%% decano del Col.legi d'Advocats de Barcelona' is a bar association, and
%% `d'' is a word no lesson knows (Spanish has no such elision). The tokeniser
%% leaves it a word of its own, the rule for a small word no lesson knows
%% after a name took `Col.legi d'' for the name, and `Advocats de Barcelona'
%% was another beside it -- two names side by side, which no phrase reads.
%% The elision is joined to the capitalised word after it, as the text
%% spelled them, and the name goes on through the particle rule (`de
%% Barcelona')
tr_elision_names(foreign, Ws0, Ws) :-
    memberchk(w(_, upper), Ws0), tr_elision_names0(Ws0, Ws), !.
tr_elision_names(_, Ws, Ws).
tr_elision_names0([], []).
tr_elision_names0([w(A, upper), w(E, lower), w(B, upper)|Ws0], Ws) :-
    atom(A), atom(E), atom(B), sub_atom(E, _, 1, 0, '\''), \+ tr_known_word(foreign, E),
    tr_name_word(foreign, w(A, upper)), tr_name_word(foreign, w(B, upper)), !,
    tr_cap(A, AC), tr_cap(B, BC), atomic_list_concat([AC, ' ', E, BC], Name),
    tr_elision_names0([w(Name, upper)|Ws0], Ws).
%% ... AND A CAPITALISED `D'' BEFORE A CAPITALISED WORD IS A SURNAME'S
%% PARTICLE: `Massimo D'Alema', `D'Onofrio'. `d'' is the elision of `di' to
%% the lesson, and the two words were a preposition and a name -- `De Alema'
%% in Spanish, or the name with a blank in it, `D' Alema'. The small `d''
%% before a capital word is the preposition (`il governo d'Alema'); the
%% capital one is the surname's, and it goes on as one word
tr_elision_names0([w(E, upper), w(B, upper)|Ws0], [w(Name, upper)|Ws]) :-
    E == 'd''', atom(B), !,
    tr_cap(B, BC), atom_concat('D''', BC, Name),
    tr_elision_names0(Ws0, Ws).
tr_elision_names0([W|Ws0], [W|Ws]) :- tr_elision_names0(Ws0, Ws).

%% A DEMONSTRATIVE AND AN ARTICLE AT THE HEAD OF A PIECE HAVE THEIR COPULA
%% LEFT OUT: `Questo il testo del documento che ...', `Questi i risultati' --
%% a headline leaves the verb out as `Incerto il futuro' does, and nothing
%% was said of what `questo' stands for. The copula is read in, `Questo è il
%% testo', in the number of the demonstrative, and every writer writes it:
%% the sentence is the one the source would have been with its verb. Italian
%% only; the forms are the demonstrative's own
tr_demonstrative_copula(foreign, [w(D, DC), A|Ws], [w(D, DC), w(Cop, lower), A|Ws]) :-
    tr_language(italian), atom(D), tr_demonstrative_form(D, Cop),
    A = w(AW, _), atom(AW), tr_determiner(foreign, A, _, article), !.
%% ... AND AT THE HEAD OF THE SIDE AFTER A COLON: `un'iniziativa "cinica e diseducativa": questo il giudizio dei
%% deputati progressisti' -- this IS the deputies' judgement; read without its verb, the demonstrative was an
%% object pronoun and English wrote `this the judgement'
tr_demonstrative_copula(foreign, Ws0, Ws) :-
    memberchk(colon, Ws0), tr_language(italian),
    append(Pre, [colon, w(D, DC), A|Rest], Ws0), atom(D), tr_demonstrative_form(D, Cop),
    A = w(AW, _), atom(AW), tr_determiner(foreign, A, _, article), !,
    append(Pre, [colon, w(D, DC), w(Cop, lower), A|Rest], Ws).
tr_demonstrative_copula(_, Ws, Ws).
tr_demonstrative_form(D, 'è') :- memberchk(D, [questo, questa, quello, quella]).
tr_demonstrative_form(D, sono) :- memberchk(D, [questi, queste, quelli, quelle]).

%% TWO NAMES WITH A DASH BETWEEN THEM, AFTER A NOUN, ARE ONE NAME: `Colloquio
%% Berlusconi - D'Alema' is the talk of two men, as `la partita Inter - Roma'
%% is the match of two clubs. `Prodi-Berlusconi' with no blanks is a word the
%% tokeniser keeps; with them the dash is a token of its own, and a phrase
%% had a name, a dash and a name, which nothing reads. The noun before the
%% pair is what says it is one (a dash after a place at the head of a piece
%% is the dateline's, `Roma - Prodi ha detto'), and no other dash follows,
%% so that the two dashes of an aside close nothing here. It goes on as the
%% source spelled it, the blanks and the hyphen among the words of the name
tr_dash_names(foreign, Ws0, Ws) :-
    memberchk(dash, Ws0), tr_dash_names0(Ws0, Ws), !.
tr_dash_names(_, Ws, Ws).
tr_dash_names0([], []).
tr_dash_names0([N, w(A, upper), dash, w(B, upper)|Ws0], [N, w(Name, upper)|Ws]) :-
    N = w(NW, NC), memberchk(NC, [lower, upper]), atom(NW), atom(A), atom(B), \+ memberchk(dash, Ws0),
    tr_is(foreign, w(NW, lower), noun),
    %% (never a word that is a verb's third person too, which is who says so: `l'Egibren - conferma
    %% Casotto - Rosi sapeva del farmaco' is Casotto confirming, and with `conferma' a noun as well the
    %% two names were one, `Casotto - Rosi', and the sentence was refused)
    \+ ( tr_form(NW, L3, _, _, third), atom(L3), tr_class_of(L3, verb) ),
    tr_name_word(foreign, w(A, upper)), tr_name_word(foreign, w(B, upper)), !,
    tr_cap(A, AC), tr_cap(B, BC), atomic_list_concat([AC, ' - ', BC], Name),
    tr_dash_names0(Ws0, Ws).
tr_dash_names0([W|Ws0], [W|Ws]) :- tr_dash_names0(Ws0, Ws).

%% A CATALAN `i' BETWEEN TWO CAPITALISED WORDS IS PART OF A NAME: `Font i
%% Sagué' is one square, two surnames joined, and `i' is a word of neither
%% lesson (Italian's is the article, which a lesson knows, and is no name's
%% link) -- read apart it was an unknown word and the sentence was refused.
%% The three join as one name, written as the source spelled them
tr_name_links(english, Ws, Ws) :- !.
tr_name_links(foreign, [], []) :- !.
tr_name_links(foreign, [w(A, upper), w(i, lower), w(B, upper)|Ws0], Ws) :-
    atom(A), atom(B), \+ tr_known_word(foreign, i), !,
    tr_cap(A, CA), tr_cap(B, CB), atomic_list_concat([CA, i, CB], ' ', J),
    tr_name_links(foreign, [w(J, upper)|Ws0], Ws).
tr_name_links(foreign, [W|Ws0], [W|Ws]) :- tr_name_links(foreign, Ws0, Ws).

%% A PARTICLE A VERB TAKES BEFORE ITS PRONOUNS SAYS NOTHING OF ITS OWN: `Io la
%% risposta non ce l'ho' is I do not have the answer, and `ce' is the `ci'
%% Italian's `avere' takes before a pronoun, which no other language has a
%% word for. The lesson says which verb takes it -- `"ce" is the particle of
%% "ha".' -- and it goes where pronouns and then a form of that verb follow
%% it; nothing writes it back, and `l'ho' is Italian too.
tr_particles(english, Ws, Ws) :- !.
tr_particles(foreign, [], []) :- !.
tr_particles(foreign, [w(P, _)|Ws0], Ws) :-
    tr_solve(particle_of(P, V)), tr_particle_before(Ws0, V), !,
    tr_particles(foreign, Ws0, Ws).
tr_particles(foreign, [W|Ws0], [W|Ws]) :- tr_particles(foreign, Ws0, Ws).

tr_particle_before([w(C, _)|Ws], V) :-
    ( tr_object_pronoun(foreign, C, _) ; tr_solve(elision_of(C, F)), tr_object_pronoun(foreign, F, _) ), !,
    Ws = [W2|Ws2],
    (   W2 = w(X, _), once(tr_form(X, V, _, _, _)) -> true
    ;   tr_particle_before([W2|Ws2], V)
    ).

%% A VERB OF SEVERAL WORDS CARRIES ITS PRONOUN ON THE FIRST OF THEM: `senza
%% rendersi conto che ...' is without realizing that -- `rendere conto' is
%% one verb the lesson states (`The verb "rende conto" means "realizes".'),
%% and the reflexive cut off `rendersi' (tr_enclitics/3) stands between its
%% words, so the join, made before the pronoun came off, never saw them
%% together. Read apart, `conto che non importa loro ...' was an account that
%% did not matter to them. They are joined here, and the pronouns follow the
%% verb they belong to, as a one-word infinitive's do.
tr_enclitic_multi(english, Ws, Ws) :- !.
tr_enclitic_multi(foreign, [], []) :- !.
tr_enclitic_multi(foreign, [w(A, C), E1|Ws0], Out) :-
    E1 = w(_, enclitic),
    ( Ws0 = [E2|Ws1], E2 = w(_, enclitic) -> Es = [E1, E2] ; Es = [E1], Ws1 = Ws0 ),
    member(N, [3, 2, 1]), length(Ns, N), append(Ns, Rest, Ws1),
    forall(member(X, Ns), ( X = w(_, XC), memberchk(XC, [lower, upper]) )),
    tr_join_word([w(A, lower)|Ns], J), !,
    append([w(J, C)|Es], Out1, Out),
    tr_enclitic_multi(foreign, Rest, Out1).
tr_enclitic_multi(foreign, [W|Ws0], [W|Ws]) :- tr_enclitic_multi(foreign, Ws0, Ws).

%% AN INFINITIVE CARRIES ITS PRONOUNS JOINED TO IT: `riprenderli' is
%% `riprendere' and `li', `ritrovarsi' is `ritrovare' and `si', `essersi' is
%% `essere' and `si', and Spanish's `recuperarlos' is `recuperar' and `los'.
%% A word the lesson does not know is cut into an infinitive -- the front of
%% it, or the front with the `e' Italian drops before a pronoun put back --
%% and a pronoun the lesson lets stand before a verb, or its reflexive one.
%% The pronoun travels as w(Pronoun, enclitic), so the complement reader
%% knows whose it is. Spanish's infinitives end in `r', so the same two
%% tries read both languages and neither is named here.
tr_enclitics(english, Ws, Ws) :- !.
tr_enclitics(foreign, [], []).
tr_enclitics(foreign, [w(W, C)|Ws0], Out) :-
    %% (a word a quotation mark opens or closes too: `"... no pienso hacerlo", sostiene Rebeca López' -- the mark
    %% the last word carries kept it whole, and `hacerlo' was a word no lesson knows)
    memberchk(C, [lower, upper, qopen, qopenu, qclose, qboth, qbothu]), \+ tr_known_word(foreign, W),
    tr_enclitic_parts(W, C, Out, Ws), !,
    tr_enclitics(foreign, Ws0, Ws).
tr_enclitics(foreign, [W|Ws0], [W|Ws]) :- tr_enclitics(foreign, Ws0, Ws).

%% THE KNOWN-WORD TEST IS ASKED ONCE A WORD, and the ways to cut the word
%% are tried after it. Written as a clause of tr_enclitics/3 each, every way
%% asked it again, so a word the lesson knows paid it once for each way --
%% and the third way, the gerund's, cost Tatoeba's 400 sentences 302 000
%% inferences of 35.1 million. Asked once, they cost 363 000 fewer, every
%% text the same.
tr_enclitic_parts(W, C, [w(Inf, C), w(Cl, enclitic)|Ws], Ws) :- tr_enclitic_split(W, Inf, Cl), !.
%% ... AND TWO OF THEM, the stem accented where the pair moved its stress:
%% `jugárselo' is `jugar', `se' and `lo', and Spanish writes the accent the
%% longer word needs. The accent comes off before the infinitive is looked
%% for.
tr_enclitic_parts(W, C, [w(Inf, C), w(Cl1, enclitic), w(Cl2, enclitic)|Ws], Ws) :-
    atom(W), member(N2, [2, 3]), sub_atom(W, B2, N2, 0, Cl2), B2 > 1, sub_atom(W, 0, B2, _, W1),
    tr_enclitic_word(Cl2),
    member(N1, [2, 3]), sub_atom(W1, B1, N1, 0, Cl1), B1 > 1, sub_atom(W1, 0, B1, _, Stem0),
    tr_enclitic_word(Cl1),
    tr_unaccent(Stem0, Stem),
    ( Inf = Stem ; atom_concat(Stem, e, Inf) ),
    tr_solve(infinitive_of(Inf, F)), tr_known(foreign, F), !.
%% ... AND ITALIAN'S TWO, THE FIRST IN THE FORM IT TAKES BEFORE ANOTHER: `occuparmene'
%% is `occupare', `mi' and `ne', `portarsela' `portare', `si' and `la',
%% `dirglielo' `dire', `gli' and `lo' -- `mi', `ti', `si', `ci', `vi' and `gli'
%% are `me', `te', `se', `ce', `ve' and `glie' there, and the pronoun comes
%% out in the lesson's own word
tr_enclitic_parts(W, C, [w(Inf, C), w(Cl1, enclitic), w(Cl2, enclitic)|Ws], Ws) :-
    atom(W), member(N2, [2, 3]), sub_atom(W, B2, N2, 0, Cl2), B2 > 1, sub_atom(W, 0, B2, _, W1),
    tr_enclitic_word(Cl2),
    member(N1, [2, 4]), sub_atom(W1, B1, N1, 0, Allo), B1 > 1, sub_atom(W1, 0, B1, _, Stem0),
    memberchk(Allo-Cl1, [me-mi, te-ti, se-si, ce-ci, ve-vi, glie-gli]), tr_enclitic_word(Cl1),
    tr_unaccent(Stem0, Stem),
    ( Inf = Stem ; atom_concat(Stem, e, Inf) ),
    tr_solve(infinitive_of(Inf, F)), tr_known(foreign, F), !.
%% ... AND A GERUND CARRIES ITS PRONOUN JOINED TO IT TOO: `fue entonándose'
%% is `entonando' and `se', the stem accented where the longer word moved
%% its stress, as `jugárselo' is
tr_enclitic_parts(W, C, [w(Stem, C), w(Cl, enclitic)|Ws], Ws) :-
    atom(W), member(N, [2, 3]), sub_atom(W, B, N, 0, Cl), B > 3, sub_atom(W, 0, B, _, Stem0),
    tr_enclitic_word(Cl), tr_unaccent(Stem0, Stem),
    tr_solve(gerund_of(Stem, F)), tr_known(foreign, F), !.
%% ... AND A PARTICIPLE CARRIES THE REFLEXIVE `si' JOINED TO IT: `la vittima
%% del reato costituitosi parte civile' is the victim who joined the
%% proceedings as a civil party, `costituito' and `si'. The participle of a
%% reflexive verb has no pronoun in the other languages the lessons cover,
%% so it is read and not written: the participle alone, agreeing as it does.
tr_enclitic_parts(W, C, [w(Stem, C)|Ws], Ws) :-
    atom(W), sub_atom(W, B, 2, 0, si), B > 3, sub_atom(W, 0, B, _, Stem),
    tr_solve(participle_of(Stem, F)), tr_known(foreign, F), !.
%% ... AND AN AFFIRMATIVE IMPERATIVE CARRIES ITS PRONOUN JOINED TO IT: `Se
%% sbaglio correggetemi' is `correggete' and `mi', correct me. Both languages
%% join a pronoun to a command and put it before only a denied one (`non mi
%% correggete', `no me corrijáis'), so the stem is a form the lesson calls
%% an imperative and not a negative one -- the stem accented where the longer
%% word moved its stress, as `jugárselo' is.
%% -- AND SO DOES THE COMMAND OF THE FIRST PERSON PLURAL: `Finiamola di
%% considerare ...' is `finiamo' and `la', let us stop it, the form the
%% lesson calls a hortative (`"finiamo" is the hortative of "finisce".')
tr_enclitic_parts(W, C, [w(Stem, C), w(Cl, enclitic)|Ws], Ws) :-
    atom(W), member(N, [2, 3]), sub_atom(W, B, N, 0, Cl), B > 1, sub_atom(W, 0, B, _, Stem0),
    tr_enclitic_word(Cl), tr_unaccent(Stem0, Stem),
    (   tr_solve(imperative_of(Stem, F)), \+ tr_holds(negative(Stem)), tr_imperative_known(F)
    ;   tr_solve(hortative_of(Stem, F)), tr_known(foreign, F)
    ), !.

%% the vowels a written accent marks, back to plain: á é í ó ú, the UTF-8
%% bytes 195 and 161, 169, 173, 179, 186
tr_unaccent(W, P) :-
    atom_codes(W, Cs), tr_unaccent_codes(Cs, Ps), atom_codes(P, Ps).
tr_unaccent_codes([], []).
tr_unaccent_codes([195, B|Cs], [V|Ps]) :- memberchk(B-V, [161-0'a, 169-0'e, 173-0'i, 179-0'o, 186-0'u]), !,
    tr_unaccent_codes(Cs, Ps).
tr_unaccent_codes([C|Cs], [V|Ps]) :- memberchk(C-V, [225-0'a, 233-0'e, 237-0'i, 243-0'o, 250-0'u]), rt_chars, !,
    tr_unaccent_codes(Cs, Ps).
tr_unaccent_codes([C|Cs], [C|Ps]) :- tr_unaccent_codes(Cs, Ps).

%% (atom_concat/3 has no mode that splits an atom here: sub_atom/5 does, the
%% pronoun two or three letters long)
%% ... and a verb in `-rre' drops both letters: `porsi la stessa domanda'
%% is `porre' and `si', to ask oneself the question
tr_enclitic_split(W, Inf, Cl) :-
    atom(W), member(N, [2, 3]), sub_atom(W, B, N, 0, Cl), B > 1, sub_atom(W, 0, B, _, Stem),
    tr_enclitic_word(Cl),
    ( Inf = Stem ; atom_concat(Stem, e, Inf) ; sub_atom(Stem, _, 1, 0, r), atom_concat(Stem, re, Inf) ),
    tr_solve(infinitive_of(Inf, F)), tr_known(foreign, F), !.

tr_enclitic_word(Cl) :- tr_reflexive_word(Cl), !.
tr_enclitic_word(Cl) :- tr_object_pronoun(foreign, Cl, _), \+ tr_tonic_word(Cl), tr_holds(precede(Cl, verb)), !.

%% a contraction the lesson states -- `"al" is the contraction of "a el"' --
%% is read as its words, and written back as itself (tr_contract/3)
tr_expand(english, Ws, Ws) :- !.
tr_expand(foreign, [], []).
%% a comma is carried through untouched: it is no word and has nothing to
%% expand, and the clause splitter still needs to see it
tr_expand(foreign, [comma|Ws], [comma|Out]) :- !, tr_expand(foreign, Ws, Out).
tr_expand(foreign, [semicolon|Ws], [semicolon|Out]) :- !, tr_expand(foreign, Ws, Out).
%% AN ELIDED CONTRACTION IS UN-ELIDED FIRST: `dell'' is `della', which is
%% then read as its two words. Which of the forms an elision stands for is
%% taken as the first stated -- `dell'' elides `dello' and `della' alike --
%% because the two expand to the same preposition and the NOUN decides the
%% gender on the way out.
%% ... AND ITS ARTICLE STAYS ELIDED WHERE THE LESSON ELIDES IT: `dall'altra'
%% is `da' and `l'', never `da lo', because `lo' standing before `altra' is
%% the pronoun `him' -- measured, `è andata dall'altra' came out `ha ido
%% desde él otros'. The elided article is the lesson's word for both.
tr_expand(foreign, [w(W, C)|Ws], Out) :-
    tr_solve(elision_of(W, F)), tr_solve(contraction_of(F, J)),
    atomic_list_concat([P1, A], ' ', J), tr_solve(elision_of(E, A)), !,
    tr_expand(foreign, Ws, Out1),
    Out = [w(P1, C), w(E, lower)|Out1].
tr_expand(foreign, [w(W, C)|Ws], Out) :-
    tr_solve(elision_of(W, F)), tr_solve(contraction_of(F, _)), !,
    tr_expand(foreign, [w(F, C)|Ws], Out).
tr_expand(foreign, [w(W, C)|Ws], Out) :-
    tr_solve(contraction_of(W, J)), atomic_list_concat([P1|Ps], ' ', J), Ps \== [], !,
    findall(w(P, lower), member(P, Ps), Rest), tr_expand(foreign, Ws, Out1),
    append([w(P1, C)|Rest], Out1, Out).
%% A PAIR OF CLITICS THE LESSON WRITES JOINED IS TWO CLITICS WHERE A VERB
%% FOLLOWS: `te lo dico' is `ti lo dico' and `se lo doy' is `le lo doy'. The
%% contraction is stated for the writer, and a key with a blank is no word, so
%% the reader never joined it -- `te' alone is the tonic pronoun, `ce' a name,
%% and the sentence was refused or read with the wrong words. The verb is what
%% tells the pair from `se la casa è grande', where a noun follows: only a
%% second word that is a clitic of the object, and a verb group after it.
tr_expand(foreign, [w(A, C), w(B, _), w(V, VC)|Ws], Out) :-
    memberchk(B, [lo, la, li, le, ne, los, las]), atom_length(A, 2),
    atomic_list_concat([A, B], ' ', K), tr_solve(contraction_of(K, J)),
    tr_group_at(foreign, [w(V, lower)|Ws], G, _),
    %% (... BUT NOT THE REFLEXIVE OF A VERB THE LESSON GIVES A MEANING WITH ITS OWN PRONOUN: `Un camión de reparto
    %% apuró el giro y se los cargó' -- it wrecked them, `cargarse'; read as `le los', a dative and its object, it
    %% came out `loaded them to him')
    \+ ( G = g(GL, _, _, _, _), atom(GL), tr_reflexive_word(A), tr_solve(mean_as(GL, _, reflexive)) ), !,
    atomic_list_concat([P1, P2], ' ', J),
    tr_expand(foreign, [w(V, VC)|Ws], Out1),
    Out = [w(P1, C), w(P2, lower)|Out1].
%% AN ABSOLUTE SUPERLATIVE IS THE LESSON'S WORD FOR `very' AND THE PLAIN
%% FORM: `le pesantissime accuse' is the very heavy accusations. The
%% lesson states it -- `"pesantissime" is the superlative of "pesanti".',
%% the builder's line -- and read as two words it is the intensifier a
%% phrase already carries (`una familia tan pacífica'), so every writer
%% has it: `muy pesadas' and `very heavy'. English has no such form.
tr_expand(foreign, [w(W, C)|Ws], Out) :-
    tr_solve(superlative_of(W, B)), tr_solve(mean(V, very)), tr_solve(adverb(V)), !,
    tr_expand(foreign, Ws, Out1),
    Out = [w(V, C), w(B, lower)|Out1].
%% AN ELIDED VERB FORM OR QUESTION WORD IS UN-ELIDED: `Il bagnino
%% dev'essere lì per legge' is `deve essere', `non so com'è andata' is `come
%% è', `Cos'è?' is `cosa è' and `Dov'è?' `dove è'. The lesson states the
%% elision (`"dev'" is the elision of "deve".'), but a group is found by the
%% forms of a verb and a question word at the head by its meaning, and
%% neither asks an elision: `dev'' began no group, `com'' was a preposition,
%% and the writers wrote `¿Dov' es?'. Where the full form is a verb's or asks
%% a question it stands for the elision; the articles, the pronouns and the
%% prepositions keep theirs, which their readers ask for (`l'', `c'', `d'').
tr_expand(foreign, [w(W, C)|Ws], Out) :-
    atom_concat(_, '''', W), tr_solve(elision_of(W, F)), tr_unelided_word(F), !,
    tr_expand(foreign, [w(F, C)|Ws], Out).
tr_expand(foreign, [W|Ws], [W|Out]) :- tr_expand(foreign, Ws, Out).

%% A WORD OF SEVERAL WORDS IS ONE WORD WHEN THE LESSON KNOWS IT AS ONE:
%% `junto a' (along with), `lavado de cerebro' (brainwashing), `tiene que'
%% (must), `c'è'. A lesson could always STATE one -- `The masculine noun
%% "toque de queda" means "curfew".' -- and the writer wrote it, but the
%% reader cut the text into single words and never put them back together,
%% so a multi-word word was write-only. Adjacent plain words are joined,
%% the LONGEST first (five, four, three, two -- `al fin y al cabo', after
%% all, is five), wherever the lesson knows the
%% joined form as a word; after a contraction is expanded, so `junto al'
%% is `junto a' and `el'. A word ending in an apostrophe joins with no space
%% (`c'' and `è' are `c'è'). Only on the lesson's side: English's own
%% multi-word forms (`there is') have readers of their own.
tr_multi(english, Ws, Ws) :- !.
tr_multi(foreign, [], []) :- !.
%% ... A VERB AND ITS PREPOSITION, A WORD OF TWO, WITH AN ADVERB BETWEEN THEM:
%% `risente invece del punto di vista di AN' is `risente di' and `invece'.
%% The longest join from the adverb took `invece di' for the preposition it
%% is before an infinitive (`parla invece di ascoltare'), and the verb had
%% none of its own. Only before a phrase: what follows the `di' is no
%% infinitive. The adverb stays after the verb.
tr_multi(foreign, [w(V, C1), w(A, lower), w(K, _)|Rest0], [w(J, C1)|Ws]) :-
    atom(V), atom(A), tr_plain_adverb_word(A), atom(K),
    (   K == di -> Rest = Rest0
    ;   tr_solve(contraction_of(K, KJ)), atomic_list_concat([di, Ar], ' ', KJ) -> Rest = [w(Ar, lower)|Rest0]
    ),
    tr_join_word([w(V, C1), w(di, lower)], J), tr_class_of(J, verb),
    \+ ( Rest = [w(N, _)|_], tr_infinitive_ahead(N) ), !,
    tr_multi(foreign, [w(A, lower)|Rest], Ws).
tr_multi(foreign, Ws0, [w(J, C)|Ws]) :-
    Ws0 = [w(_, C0)|_],
    member(N, [5, 4, 3, 2]), length(Ns, N), append(Ns, Rest, Ws0),
    tr_multi_cases(Ns),
    tr_join_word(Ns, J), \+ tr_purpose_only_join(J, Rest), !,
    last(Ns, w(_, CL)), tr_join_case(C0, CL, C),
    tr_multi(foreign, Rest, Ws).
%% ... AND ONE WHOSE LAST WORD CAME CONTRACTED WITH THE ARTICLE AFTER IT:
%% `alla luce della struttura' is `alla luce di' and `la struttura'. Before
%% the contractions are expanded the last word is `della', and after it the
%% first is `a la' -- so neither pass found the word, and the phrase was read
%% as `a la luz de ella'. Here the last word alone is expanded.
tr_multi(foreign, Ws0, [w(J, C), w(A, lower)|Ws]) :-
    Ws0 = [w(_, C)|_],
    member(N, [4, 3, 2]), length(Ns, N), append(Ns, Rest, Ws0),
    forall(member(X, Ns), ( X = w(_, XC), memberchk(XC, [lower, upper]) )),
    append(Front, [w(K, _)], Ns), tr_solve(contraction_of(K, KJ)), atomic_list_concat([P, A], ' ', KJ),
    append(Front, [w(P, lower)], Ns1), tr_join_word(Ns1, J), !,
    tr_multi(foreign, Rest, Ws).
tr_multi(foreign, [W|Ws0], [W|Ws]) :- tr_multi(foreign, Ws0, Ws).

%% (the adverbs that may stand between a verb and its preposition, tr_multi/2 above)
tr_plain_adverb_word(A) :- memberchk(A, [invece, anche, ancora, poi, 'già', sempre, spesso, quindi, dunque, allora]).
%% ... BUT A WORD THE LESSON STATES ONLY AS BEGINNING THE PURPOSE JOINS ONLY
%% BEFORE AN INFINITIVE, which is the purpose's own shape: `tanto per citarne
%% alcuni' is to name a few, and `non mi dispiace tanto per lei, che adesso
%% non c'è più' is not so sorry for her. Joined there, the purpose had no
%% infinitive after it and the Fregene report's forty-fourth sentence, which
%% 1.8.30 reads on its own store, was refused on the store taught with the
%% line -- by 1.8.30 as much as by this version, which only the data column
%% could show. An infinitive may carry its pronoun joined (`citarne').
tr_purpose_only_join(J, Rest) :-
    tr_solve(begin(J, purpose)), \+ tr_solve(mean(J, _)),
    \+ ( Rest = [w(V, _)|_], tr_infinitive_ahead(V) ).

tr_infinitive_ahead(V) :- tr_solve(infinitive_of(V, _)), !.
tr_infinitive_ahead(V) :-
    atom(V), tr_enclitic_parts(V, lower, [w(I, _)|_], []), tr_solve(infinitive_of(I, _)), !.

%% a pronoun joined to the word before it, that word an infinitive -- in a
%% phrase, which opens on a determiner: Òmnium's `Para demostrarlo, esgrimió
%% ...' offered words that open on `para' as a subject, and with its `lo'
%% let through the reading ran on, 1.4 million inferences of the sentence's
%% 17.9 for nothing
tr_infinitive_pronoun(Before, enclitic) :-
    last(Before, w(I, _)), tr_solve(infinitive_of(I, _)), Before = [D|_], tr_determiner(foreign, D, _, _), !.

%% the words of a join are plain words -- and the FIRST may open a quotation,
%% whose mark the join then carries: `"Hay que tomar precauciones", dijo.'
%% -- and the LAST may close one: `"personajes singulares que representan a
%% otros muchos"' ends on the pronoun of two words, and with the mark on
%% `muchos' the join was not made
tr_multi_cases([w(_, C)|Ns]) :-
    memberchk(C, [lower, upper, qopen]),
    ( append(Mid, [w(_, CL)], Ns) -> true ; Mid = [], CL = lower ),
    memberchk(CL, [lower, upper, qclose]),
    forall(member(X, Mid), ( X = w(_, XC), memberchk(XC, [lower, upper]) )).

%% the words joined into a word the lesson states: as the join spells it, or
%% as the lesson spells it with a hyphen where the join has a blank
tr_join_word(Ns, J) :-
    tr_joined(Ns, J0),
    ( tr_stated_word(J0) -> J = J0 ; tr_solve(hyphen_spelling(J0, J)) ).

%% A WORD OF SEVERAL WORDS IS ALWAYS STATED -- its meaning, and each form
%% of it (`"lavados de cerebro" is the plural of "lavado de cerebro"'),
%% because no ending rule makes the plural of a phrase -- so the join asks
%% the relations a form is stated in and nothing else. Asked through
%% tr_known_word/2, every join that is NO word walked the ending rules and
%% the tenses too, and the joins cost a Tatoeba run 1.8 s of its 26. A word
%% the lesson says BEGINS something is stated too: `The word "in modo da"
%% begins the purpose.' is the whole of what `in modo da poter utilizzare'
%% needs, and read apart it was `en modo para poder'.
%% ... BUT NOT BY A CONTRACTION WHOSE KEY HAS A BLANK: `"me lo" is the
%% contraction of "mi lo".' is for the writer, which joins two clitics it
%% writes side by side; read, Italian `se la' is also `if the', and joined and
%% expanded `se la casa è grande' would be a reflexive pair (tr_expand/2 takes
%% a pair apart where a verb follows it)
%% ... AND ASKED ONCE A SENTENCE, as a word's lexemes are (tr_memo/4): the
%% joins of the same words come back at every reading, and nearly all of them
%% are no word -- fifteen questions to the lesson for each. Kept, the check
%% costs the controls 1.1 % less than it did, and 0.5 % less than the version
%% before the contractions and the imperfect
tr_stated_word(J) :-
    (   atom(J)
    ->  tr_language(Lang), tr_memo(sw(Lang, J), stated, tr_stated_word0(J), Sols), Sols \== []
    ;   tr_stated_word0(J)
    ).
tr_stated_word0(J) :-
    member(G, [mean(J, _), plural_of(J, _), person_of(J, _), past_of(J, _), imperfect_of(J, _), future_of(J, _),
               participle_of(J, _), gerund_of(J, _), infinitive_of(J, _), conditional_of(J, _),
               subjunctive_of(J, _), imperative_of(J, _), elision_of(J, _), begin(J, _)]),
    tr_solve(G), !.
tr_stated_word0(J) :-
    tr_solve(contraction_of(J, _)), atom_codes(J, Cs), \+ memberchk(32, Cs), !.

tr_joined([w(A, _)], A) :- !.
tr_joined([w(A, _)|Ws], J) :-
    tr_joined(Ws, J1),
    ( sub_atom(A, _, 1, 0, '\'') -> atom_concat(A, J1, J) ; atomic_list_concat([A, ' ', J1], J) ).

tr_contract(english, Os0, Os) :- !, en_another(Os0, Os).
%% A WORD THE LESSON SAYS DOES NOT FOLLOW AN ARTICLE TAKES ITS PLACE: `un altro campione' is `otro campeón', and the
%% Spanish writer wrote `un otro', which no Spanish page prints (`"otro" does not follow "un".'); Italian states nothing
%% and keeps `un altro'. The word takes the article's case, a capital at the head of the sentence
tr_contract(foreign, [o(W1, C1), o(W2, _)|Os], Out) :-
    atom(W1), atom(W2), tr_solve(neg(follow(W2, W1))), !,
    tr_contract(foreign, [o(W2, C1)|Os], Out).
tr_contract(foreign, [o(W1, C1), o(W2, C2)|Os], Out) :-
    atomic_list_concat([W1, W2], ' ', J), tr_solve(contraction_of(K, J)), !,
    tr_join_case(C1, C2, C),
    tr_contract(foreign, [o(K, C)|Os], Out).
%% ... and a word of several words contracts by its LAST word: `junto a el
%% Rescate Alpino' is `junto al Rescate Alpino'
tr_contract(foreign, [o(W1, C1), o(W2, C2)|Os], Out) :-
    atom(W1), sub_atom(W1, B, 1, A, ' '), sub_atom(W1, _, A, 0, Last), \+ sub_atom(Last, _, _, _, ' '),
    atomic_list_concat([Last, W2], ' ', J), tr_solve(contraction_of(K, J)), !,
    sub_atom(W1, 0, B, _, Pre), atomic_list_concat([Pre, K], ' ', W),
    tr_join_case(C1, C2, C),
    tr_contract(foreign, [o(W, C)|Os], Out).
%% AND AN ELIDED FORM IS WRITTEN WHEN A VOWEL FOLLOWS, joined to the word
%% after it: `la incolumita' is `l'incolumita'. It comes AFTER the
%% contraction above, so `di la' is `della' first and `dell'' second --
%% which is why the lesson states the elision of the contracted forms
%% (`"dell'" is the elision of "della"') and not of their parts.
%% ... AND A CAPITAL AFTER THE ELISION IS KEPT: the joined word takes the
%% elided word's case, so `de Adjaria' came out `d'adjaria' and `a la Unión'
%% `all'unione'
%% ... AND A WORD THAT IS NO PREPOSITION NEVER BEFORE AN ARTICLE, which opens
%% another phrase: `por ello los bobalicones comentarios' is `per questo i
%% tonti commenti', and the pronoun joined to the article came out `per
%% quest'i'. A preposition is elided before one: `d'un buon stradivari'
%% ... NOR BEFORE A PREPOSITION: `además de la antecesora de éste en Sant
%% Cugat' is `di questo in Sant Cugat', and the pronoun standing alone was
%% joined to the preposition of the next phrase, `di quest'in'
%% ... AND A PRONOUN'S ONLY WHERE THE LESSON SAYS IT GOES: `s'innamora' is
%% read as `si innamora' (`"s'" is the elision of "si".'), and written before
%% every vowel that line made `S'aumentarono le vendite' and `come s'era
%% annunciato' of four old controls, where the prose they are written in
%% says `si'. An elision whose word is a pronoun and no determiner is written
%% only before what the lesson says the elided form comes before (`"s'" comes
%% before "i".' would write `s'innamora'); an article's and any other word's
%% before every vowel, as before
%% THE EUPHONIC FORM: a preposition or a conjunction that the lesson gives another word of its class and meaning, which
%% comes before what the next word begins with -- `The preposition "ad" comes before "a".', `The conjunction "ed" comes
%% before "e".' -- is that word: `animó al PNV a que acepte' is `incoraggiò il PNV ad accettare', where it was `a
%% accettare'
tr_contract(foreign, [o(W1, C1), o(W2, C2)|Os], Out) :-
    atom(W1), atom(W2), tr_euphonic_form(W1, W2, F), !,
    tr_contract(foreign, [o(F, C1), o(W2, C2)|Os], Out).
tr_contract(foreign, [o(W1, C1), o(W2, C2)|Os], Out) :-
    tr_solve(elision_of(E, W1)), tr_language(To), tr_starts_vowel(To, W2),
    \+ tr_opens_next(W1, W2), tr_elision_written(E, W1, W2), !,
    ( C2 == upper -> tr_cap(W2, W2C) ; W2C = W2 ),
    tr_elided_join(E, W2C, C1, C2, J, C),
    tr_contract(foreign, [o(J, C)|Os], Out).
%% ... AND A WORD OF SEVERAL WORDS ELIDES BY ITS LAST WORD, as it contracts
%% by it: `además del antecesor' is `oltre a' and `lo', which contract to
%% `oltre allo' and elide to `oltre all'antenato' -- the elision looked for
%% the whole of `oltre allo' and wrote `oltre allo antenato'
tr_contract(foreign, [o(W1, C1), o(W2, C2)|Os], Out) :-
    atom(W1), atom_codes(W1, Cs1), memberchk(32, Cs1), tr_language(To), tr_starts_vowel(To, W2),
    sub_atom(W1, B, 1, A, ' '), sub_atom(W1, _, A, 0, Last), \+ sub_atom(Last, _, _, _, ' '),
    tr_solve(elision_of(E, Last)), \+ tr_opens_next(Last, W2), !,
    sub_atom(W1, 0, B, _, Pre), ( C2 == upper -> tr_cap(W2, W2C) ; W2C = W2 ),
    tr_elided_join(E, W2C, C1, C2, J0, C), atomic_list_concat([Pre, ' ', J0], J),
    tr_contract(foreign, [o(J, C)|Os], Out).
tr_contract(foreign, [O|Os], [O|Out]) :- tr_contract(foreign, Os, Out).
tr_contract(foreign, [], []).
%% (the forms looked up once for the lessons and the language: asked of the lesson at every pair of words it was a walk of every
%% come_before/2 fact, the articles' among them)
tr_euphonic_form(W1, W2, F) :-
    nb_getval('$tr_lessons', G0), tr_language(To), G = G0/To,
    (   tr_global('$tr_euph', G-Es) -> true
    ;   findall(F0-W0-P0, ( tr_solve(come_before(F0, P0)), member(K, [preposition, conjunction]), tr_class_of(F0, K),
                            tr_solve(mean(F0, M)), tr_solve(mean(W0, M)), W0 \== F0, tr_class_of(W0, K) ), Es0),
        sort(Es0, Es), nb_setval('$tr_euph', G-Es)
    ),
    Es \== [], memberchk(_-W1-_, Es), downcase_atom(W2, D2), member(F-W1-P, Es), tr_begin_with(D2, P), !.
%% ... AND ENGLISH'S `AN OTHER' IS `ANOTHER': `Aggiunge una prova su un altro campione' adds a test on another sample,
%% and the article and the adjective came out as two words, `an other'
en_another([o(an, C), o(other, _)|Os0], [o(another, C)|Os]) :- !, en_another(Os0, Os).
en_another([O|Os0], [O|Os]) :- !, en_another(Os0, Os).
en_another([], []).

%% the elided form joined to the word after it -- and a quotation mark that
%% opened on that word stays on it, inside the join: `la "única
%% preocupación"' is `l'"unica preoccupazione"', where the joined word took
%% the article's case and the mark was lost, `l'unica preoccupazione"'
tr_elided_join(E, W2, C1, C2, J, C) :-
    (   C2 == qopen -> atomic_list_concat([E, '"', W2], J), C = C1
    ;   C2 == qboth -> atomic_list_concat([E, '"', W2], J), ( C1 == qopen -> C = qboth ; C = qclose )
    ;   atom_concat(E, W2, J), tr_join_case(C1, C2, C)
    ).

%% A NUMBER BEGINS WITH THE SOUND OF ITS FIRST WORD, not with its digit:
%% `l'80%' (ottanta), `l'8', `l'11' (undici), `l'1,4' (uno) and `gli 80 anni',
%% and `il 18' (diciotto), `il 25%' and `il 1.200' (milleduecento); English
%% says `an 80%', `an 18 per cent' and `a 1,200'. A letter is a vowel by
%% begin_with/2 and a digit is none, so `el 80%' was `il 80%'. The whole part
%% of the number is read for its first word: its first group of digits (one
%% to three, the thousands separators out) and how many groups follow it.
tr_starts_vowel(_, W) :- begin_with(W, vowel), !.
%% ... AND A WORD THAT OPENS ON A SILENT `h' BEGINS WITH THE SOUND AFTER IT:
%% `l'hotel', `dell'hotel' -- the lesson's languages that elide write `h' and
%% say nothing (an `h' before a consonant is `hr' no word of theirs has)
tr_starts_vowel(To, W) :- To \== english, tr_silent_h(W), !.
tr_starts_vowel(To, W) :-
    atom(W), atom_codes(W, [D|Cs]), tr_digit_code(D),
    ( To == english -> Sep = 0', ; Sep = 0'. ),
    tr_whole_run(Sep, [D|Cs], Ds), Ds \== [],
    length(Ds, N), G is ((N - 1) mod 3) + 1, M is (N - 1) // 3,
    length(Lead, G), append(Lead, _, Ds), number_codes(V, Lead),
    tr_number_vowel(To, V, M), !.
%% the first group's value and the thousands after it (1.000 is `mille', one
%% million `un milione')
tr_number_vowel(english, V, _) :- ( V =:= 8 ; V =:= 11 ; V =:= 18 ; V >= 80, V =< 89 ; V >= 800, V =< 899 ).
tr_number_vowel(To, V, M) :-
    To \== english,
    (   V =:= 8 ; V =:= 11 ; V >= 80, V =< 89 ; V >= 800, V =< 899
    ;   V =:= 1, ( M =:= 0 ; M >= 2 )
    ).
tr_whole_run(Sep, [D|Cs], [D|Ds]) :- tr_digit_code(D), !, tr_whole_run(Sep, Cs, Ds).
tr_whole_run(Sep, [Sep, A, B, C|Cs], [A, B, C|Ds]) :-
    tr_digit_code(A), tr_digit_code(B), tr_digit_code(C), \+ ( Cs = [E|_], tr_digit_code(E) ), !,
    tr_whole_run(Sep, Cs, Ds).
tr_whole_run(_, _, []).
tr_digit_code(C) :- C >= 0'0, C =< 0'9.
%% a letter or a number against the beginnings a lesson states (`The article
%% "lo" comes before a vowel.'): a number is a vowel by its sound
tr_begin_with(W, P) :-
    P == vowel, !,
    (   begin_with(W, vowel) -> true
    ;   tr_language(To), To \== english, tr_silent_h(W) -> true
    ;   tr_digits_start(W), tr_language(To), tr_starts_vowel(To, W)
    ).
tr_begin_with(W, P) :- begin_with(W, P).
tr_silent_h(W) :-
    atom(W), sub_atom(W, 0, 1, _, H), memberchk(H, [h, 'H']), sub_atom(W, 1, 1, _, V), memberchk(V, [a, e, i, o, u]).
tr_digits_start(W) :- atom(W), atom_codes(W, [D|_]), tr_digit_code(D).

%% an elided form is written before W2: always for an article, a determiner
%% and any word that is no pronoun; for a pronoun, only before what the
%% lesson says the elided form comes before
%% ... AND SO IS THE ELISION OF A VERB FORM OR A QUESTION WORD, which the
%% reader takes apart (tr_expand/3): `dev'essere' and `com'è andata' are read,
%% and written elided before every vowel they were `com'assicurano i
%% palestinesi', `paesi com'Alemania' and `considerato com'il Van Gogh', in
%% ten sentences of the controls. Written only where the lesson says what
%% the elided form comes before (`"com'" comes before "è".')
tr_elision_written(E, W1, W2) :-
    (   atom(W1), tr_lexeme(foreign, W1, L, _), tr_class_of(L, pronoun),
        \+ tr_determiner(foreign, w(W1, lower), _, _)
    ->  tr_solve(come_before(E, P)), begin_with(W2, P), !
    ;   atom(W1), tr_unelided_word(W1)
    ->  tr_solve(come_before(E, P)), begin_with(W2, P), !
    ;   true
    ).
tr_unelided_word(W) :- tr_verb_form_word(W), !.
tr_unelided_word(W) :- tr_solve(mean(W, E)), en_question(E, _), !.

%% a word after one that could be elided that opens another phrase: an
%% article or a preposition, unless the elided word is a preposition itself
%% -- and A COORDINATOR, whatever the elided word is: `para merecer todo esto
%% y puede ser' is `tutto questo e può essere', and `questo' is a determiner
%% as well as a pronoun, so it was joined to the conjunction, `tutto quest'e'.
%% Nothing an elided word belongs to begins with one.
tr_opens_next(_, W2) :- tr_coord(foreign, w(W2, lower)), !.
%% ... AND A PREPOSITION IS NEVER ELIDED BEFORE A DEFINITE ARTICLE: `sin el
%% gato' is `senza il gatto', and `"senz'" is the elision of "senza".' wrote
%% `senz'il gatto' -- before an indefinite one it is, `d'un buon stradivari'
tr_opens_next(_, W2) :- tr_determiner(foreign, w(W2, lower), L, article), tr_solve(mean(L, the)), !.
tr_opens_next(W1, W2) :-
    ( tr_determiner(foreign, w(W2, lower), _, article) -> true ; tr_is(foreign, w(W2, lower), preposition) ),
    \+ tr_is(foreign, w(W1, lower), preposition),
    \+ tr_the_before_one(W1, W2).
%% (but the definite article, or a preposition contracted with it, before the article `a' is one o'clock, and is
%% elided as before a noun: `a la una' is `all'una', which came out `alla una')
tr_the_before_one(W1, W2) :-
    tr_determiner(foreign, w(W2, lower), L2, article), tr_solve(mean(L2, a)),
    (   tr_determiner(foreign, w(W1, lower), L1, article) -> true
    ;   tr_solve(contraction_of(W1, J)), atomic_list_concat(Ps, ' ', J), last(Ps, A1),
        tr_determiner(foreign, w(A1, lower), L1, article)
    ), tr_solve(mean(L1, the)), !.

%% TWO WORDS JOINED KEEP THE MARK THE SECOND ONE CLOSED: a quotation mark
%% travels in a word's case (tr_word_text/4), and the join kept the first
%% word's alone -- `"Procesad al obispo".' came out `"Processate
%% l'alfiere.', the elided article taking the noun that closed the quote
tr_join_case(qopen, C2, qboth) :- memberchk(C2, [qclose, qboth]), !.
tr_join_case(_, qclose, qclose) :- !.
tr_join_case(C1, _, C1).

%% the first word's capital is the sentence's, not the word's: a known
%% word at the head goes lower, so that when a question moves it it is
%% not `Es'; a name keeps its case
%% ... but not the first word of a NAME: `Monte Livata, ritrovati vivi' --
%% a capitalised NOUN the lesson knows before a word it does not is a
%% place's name, and lowered it was a mountain with a stranger's name after
%% it. A noun and nothing a verb: `¿Come Maria el pan?' is a verb and a
%% name, and kept capitalised the verb could not start the group.
%% NOR A TIME: `Sabato Mladic aveva spedito un fax' is a day and a surname,
%% and kept capitalised `Sabato' took `Mladic' for the name apposed to it
%% (tr_apposed_name/3), so the sentence read as a time phrase `Saturday
%% Mladic' and a subject nobody named. A day is lower case inside an
%% Italian or a Spanish sentence, so the capital at the head is the
%% sentence's -- and the lesson's `"sabato" is a time.' is what says so.
tr_head_lower(From, [w(W, upper)|Ws], [w(W, lower)|Ws]) :-
    ( tr_known_word(From, W) ; en_function(W) ; tr_head_joins(From, W, Ws) ),
    \+ ( Ws = [w(N, upper)|_], \+ tr_known_word(From, N), tr_name_head(From, W) ),
    \+ ( From == foreign, tr_name_head(From, W), tr_lone_head_subject(W, Ws) ),
    %% ... NOR A WORD THE LESSON SAYS IS A NAME: `Quartieri è stato realizzato
    %% dall'associazione' is the festival, and lowered `quartieri' were
    %% the neighbourhoods, plural, for a verb in the singular
    \+ ( From == foreign, atom(W), tr_solve(name(W)) ), !.
tr_head_lower(_, Ws, Ws).
%% (whether the source began the sentence in small letters with a verb of saying, tr_into_ir/4's command)
tr_small_head_note(Side, [w(W, lower)|_]) :-
    Side == foreign, atom(W), tr_lexeme(foreign, W, L, _), atom(L), tr_saying_verb(L), !, nb_setval('$tr_small_head', yes).
tr_small_head_note(_, _) :- nb_setval('$tr_small_head', no).

%% ... NOR A NOUN STANDING ALONE BEFORE ITS VERB: `Margherita non sapeva
%% nuotare' is the babysitter, and lowered `margherita' was a daisy, a bare
%% noun in the singular for the subject -- which the lesson's languages do
%% not have: a singular subject takes a determiner. A noun the lesson knows
%% in the singular, and as no adjective, right before the word for `not' or
%% a verb's own form, keeps its capital, and a capital there is a name's
%% (tr_np/3)
tr_lone_head_subject(W, [N|_]) :-
    tr_lexeme(foreign, W, _, singular), \+ tr_is(foreign, w(W, lower), adjective),
    N = w(NW, lower), atom(NW),
    ( tr_solve(mean(NW, not)) -> true ; tr_verb_form_word(NW) ), !.

%% ... AND A HEAD WORD THE LESSON KNOWS ONLY AS PART OF A WORD: `Ne fa testo
%% la stampa' begins with the first word of `ne fa testo' (testifies to it),
%% and `Correggetemi' is a command with its pronoun joined to it. Neither is
%% a word the lesson states, so the capital stayed: the join kept the first
%% word's case and the verb it made was a name's, and the command's verb was
%% refused for the same reason.
tr_head_joins(foreign, W, Ws) :-
    member(N, [4, 3, 2, 1]), length(Ns, N), append(Ns, _, Ws),
    forall(member(X, Ns), X = w(_, lower)),
    tr_join_word([w(W, lower)|Ns], _), !.
tr_head_joins(foreign, W, _) :- atom(W), tr_enclitic_parts(W, lower, _, []), !.

tr_name_head(From, W) :-
    tr_lexeme(From, W, L, _), tr_class(From, L, noun), \+ tr_class(From, L, verb),
    \+ tr_time_lexeme(From, L), !.

%% a lexeme the lesson calls a time: its own word, or on the English side a
%% word of the lesson's that means it
tr_time_lexeme(foreign, L) :- tr_holds(time(L)), !.
tr_time_lexeme(english, E) :- tr_solve(mean(W, E)), tr_holds(time(W)), !.

%% ---- the sentences, and their words ------------------------------------------

%% the text cut at `.', `!' and `?', each piece with the stop it ended on
%% (`.' when it had none), the blank ones dropped
tr_pieces(Text, Pieces) :-
    tr_memo_reset,
    tr_codes(Text, Codes0), tr_single_quotes(Codes0, Codes),
    tr_split(Codes, Pieces0), tr_quote_pieces(Pieces0, Pieces1),
    tr_speech_pieces(Pieces1, Pieces2), tr_caps_heads(Pieces2, Pieces).

%% A HEADING IN CAPITALS BEFORE A SENTENCE IS A PIECE OF ITS OWN: `EL ENCARGO La historia de estos plafones es
%% genuinamente kafkiana.' -- a paper sets a section's title in capitals at the head of its first sentence, with no
%% stop after it, and the tokeniser keeps only a word's first letter's case, so the title was read as the sentence's
%% first words and the sentence was refused. Two words of capitals at least, each of two letters at least, then a
%% word with a capital and a small letter: the title is cut off as a piece that ends on a full stop, which every
%% heading in capitals already is (tr_caps_piece/2), and the sentence after it is read as it stands
tr_caps_heads([], []).
tr_caps_heads([P-S|Ps], [H-46, R-S|Out]) :- tr_caps_head(P, H, R), !, tr_caps_heads(Ps, Out).
tr_caps_heads([X|Ps], [X|Out]) :- tr_caps_heads(Ps, Out).

tr_caps_head(Codes, Head, Rest) :-
    tr_skip_blank(Codes, C0), C0 = [A, B|_], tr_capital_start([A, B]),
    append(Head, [32|Rest], C0), Head \== [], memberchk(32, Head),
    tr_capital_start(Rest), tr_first_word_codes(Rest, FW), tr_has_small(FW), !,
    \+ tr_has_small(Head), forall(member(C, Head), ( C == 32 ; tr_letter_code(C) )),
    tr_cut_at(Head, 32, Words), forall(member(W, Words), W = [_, _|_]),
    tr_capitals(Head, 0, N), N >= 3.
tr_first_word_codes([], []).
tr_first_word_codes([C|_], []) :- \+ tr_letter_code(C), !.
tr_first_word_codes([C|Cs], [C|Ws]) :- tr_first_word_codes(Cs, Ws).

%% A WORD OR TWO IN SINGLE QUOTATION MARKS IS QUOTED, as in double ones: `Los
%% 'botiguers' prevén que la relación con los fabricantes empeorará' (the
%% press quotes a Catalan word so). The tokeniser keeps an apostrophe only
%% between letters, and these marks went with the punctuation: the word lost
%% them, and where no lesson knew it the sentence was refused. A single mark
%% opens at the start of the text, after a blank or a bracket, before a
%% letter; it closes after a letter or a digit, before a blank, a stop, a
%% comma, a bracket or the end, three words on at most and with no stop
%% between. Both become the plain double mark, which the clauses for a
%% quoted word read. An elision (`l'altro': a letter before the apostrophe),
%% a clipped word (`un po' di': no mark open) and a year (`'68': no letter
%% after the mark) are no marks.
tr_single_quotes(Cs0, Cs) :- tr_sq(Cs0, 32, Cs).

tr_sq([], _, []).
tr_sq([39, N|Cs], Prev, [34|Out]) :-
    tr_sq_opens(Prev), rt_alpha(N),
    tr_sq_close([N|Cs], Inside, Rest), !,
    append(Inside, [34|Out1], Out),
    tr_sq(Rest, 34, Out1).
tr_sq([C|Cs], _, [C|Out]) :- tr_sq(Cs, C, Out).

tr_sq_opens(P) :- ( P =< 32 ; P == 40 ; P == 91 ), !.          % a blank, `(' or `['

tr_sq_close(Cs, Inside, Rest) :-
    append(Inside, [39|Rest], Cs), Inside \== [],
    last(Inside, L), ( rt_alpha(L) ; rt_digit(L) ),
    ( Rest == [] ; Rest = [R|_], \+ rt_alpha(R), \+ rt_digit(R) ),
    \+ ( member(S, Inside), memberchk(S, [46, 33, 63]) ),
    tr_sq_blanks(Inside, NB), NB =< 2, !.

tr_sq_blanks([], 0).
tr_sq_blanks([C|Cs], N) :- tr_sq_blanks(Cs, N0), ( C =< 32 -> N is N0 + 1 ; N = N0 ).

%% A SENTENCE IN QUOTATION MARKS: `"¿Cómo ha podido salir así?".' The mark
%% opens before the sentence and closes after its stop, so the splitter cut
%% `"¿Cómo ... así' with `?' and then `"' with `.' -- and the first piece read
%% as ONE quoted token, `¿' and all, while the second had no word at all.
%% The marks belong to the SENTENCE: they come off before its words are read
%% and go back round the translation, carried in the stop as
%% marks(Before, Stop, After), which tr_kind/2 and tr_join/5 look through.
tr_quote_pieces([], []).
tr_quote_pieces([P0-S0, P1-S1|Ps], [P-marks(Open, S0, Close)|Out]) :-
    integer(S0), tr_opening_mark(P0, Open, P), tr_closing_only(P1, Close0), !,
    append(Close0, [S1], Close),
    tr_quote_pieces(Ps, Out).
%% ... AND ONE THAT CLOSES BEFORE THE CLAUSE THAT SAYS IT: `¿"Cómo podrán conocer
%% nuestra personalidad?", se preguntaba Michaela.' The mark that closes the
%% question stands at the head of the piece after it, with a comma and the
%% reporting clause (the comma is not always there), and was read as the
%% OPENING mark of that clause's first word -- `"How will they know?
%% "Michaela asked.' The question is the sentence in its marks, and the clause
%% after it a sentence of its own
tr_quote_pieces([P0-S0, P1-S1|Ps], [P-marks(Open, S0, Close), P2-S1|Out]) :-
    integer(S0), memberchk(S0, [63, 33]), tr_opening_mark(P0, Open, P), tr_closing_comma(P1, Close, P2), !,
    tr_quote_pieces(Ps, Out).
tr_quote_pieces([P-S|Ps], [P-S|Out]) :- tr_quote_pieces(Ps, Out).

%% a piece that opens with a quotation mark (after the inverted mark of a
%% question, `¿"Cómo ...') and never closes it
tr_opening_mark(Codes, Mark, Rest) :-
    tr_skip_blank(Codes, C0), tr_skip_inverted(C0, C1), tr_quote_mark(open, Mark, C1, Rest), Rest \== [],
    \+ ( append(_, Tail, Rest), tr_quote_mark(close, _, Tail, _) ).
tr_skip_inverted([194, B|Cs], Cs) :- memberchk(B, [191, 161]), !.      % `¿' and `¡', in bytes
tr_skip_inverted([B|Cs], Cs) :- memberchk(B, [191, 161]), rt_chars, !.   % ... and as code points
tr_skip_inverted(Cs, Cs).
%% a piece that is nothing but the closing mark
tr_closing_only(Codes, Mark) :-
    tr_skip_blank(Codes, C1), tr_quote_mark(close, Mark, C1, Rest), tr_blank(Rest).
%% a piece that begins with the closing mark, a comma if there is one, and then words
tr_closing_comma(Codes, Mark, Rest) :-
    tr_skip_blank(Codes, C1), tr_quote_mark(close, Mark, C1, C2),
    tr_skip_blank(C2, C3), ( C3 = [44|C4] -> true ; C4 = C3 ), tr_skip_blank(C4, Rest), Rest = [_|_].

tr_skip_blank([C|Cs], Out) :- C =< 32, !, tr_skip_blank(Cs, Out).
tr_skip_blank(Cs, Cs).

%% the marks: the plain one either way, the typographic pair (U+201C and
%% U+201D, three bytes each in UTF-8) and the angled pair (U+00AB, U+00BB)
tr_quote_mark(_, [34], [34|Rest], Rest).
tr_quote_mark(open, [226, 128, 156], [226, 128, 156|Rest], Rest).
tr_quote_mark(close, [226, 128, 157], [226, 128, 157|Rest], Rest).
tr_quote_mark(open, [194, 171], [194, 171|Rest], Rest).
tr_quote_mark(close, [194, 187], [194, 187|Rest], Rest).
tr_quote_mark(open, [8220], [8220|Rest], Rest).
tr_quote_mark(close, [8221], [8221|Rest], Rest).
tr_quote_mark(open, [171], [171|Rest], Rest) :- rt_chars.
tr_quote_mark(close, [187], [187|Rest], Rest) :- rt_chars.

%% the sentence's text with its stop, and its marks when it carries any
tr_stop_text(P, Stop, Sentence) :-
    tr_stop_parts(Stop, Before, Inner, S, After),
    atom_codes(P, Cs), append(Before, Cs, C1), append(C1, Inner, C1b), append(C1b, [S|After], C2),
    atom_codes(Sentence, C2).

%% the marks: Before the text, Inner between the text and its stop -- an
%% Italian quotation closes BEFORE the full stop, `funziona”.' -- and After
tr_stop_parts(marks(Before, S, After), Before, [], S, After) :- !.
tr_stop_parts(marks(Before, Inner, S, After), Before, Inner, S, After) :- !.
tr_stop_parts(S, [], [], S, []).

%% DIRECT SPEECH RUNS OVER SENTENCES, AND ITS MARKS ARE THE SENTENCES'.
%% `“Due bambini ... sono due eroi. È stato difficile riprenderli perché
%% erano incastrati in un dirupo” ha raccontato a Sky Tg24 Tornaboni.' opens
%% a quotation in one sentence and closes it in the next, and the tokeniser
%% saw neither half: an opening mark with no closing one in its piece ran as
%% ONE quoted token to the end of the piece -- commas stuck to their words,
%% `anni,' and `condizioni,' refused as unknown -- and a closing mark with
%% no opening one was dropped as punctuation, so the reporting clause after
%% it ran on into the quotation and nothing could read either.
%%
%% So the marks are taken off the piece before a word is read, and each
%% goes where it belongs. An opening mark at the HEAD of a piece goes in
%% front of the sentence, and a closing mark at its END between the text
%% and its stop, as the source had it (`funziona”.') -- both carried in the
%% stop, as tr_quote_pieces/2 carries a quoted question's. A closing mark
%% in the MIDDLE is where the quotation ends and a reporting clause begins,
%% a boundary the clause reader divides at (code 1, read as `endquote'). An
%% opening mark in the middle whose quotation does not close in the piece
%% (`spiegando che “si sono adoperate ...') marks the word after it (code
%% 2). A pair of marks inside one piece -- `parla di “miracolo”', `"dal
%% punto di vista tattico"' -- is left to the tokeniser as the quoted words
%% it always was. The plain mark opens and closes alike, so where it stands
%% says which (tr_speech_mark/4), and its closing one is code 7, read as
%% `endquote_plain' and written back as itself.
%%
%% A DASH BETWEEN WORDS IS A BOUNDARY TOO: `bisognerebbe sapere come sono
%% finiti lì – ha spiegato un soccorritore -.' sets its reporting clause
%% off with dashes, and the tokeniser dropped them as punctuation. An en or
%% em dash, and a hyphen with a blank before it and none of a word after
%% it, is code 3, read as `dash'. And a COLON divides a sentence's clauses
%% as a semicolon does -- `Le condizioni generali sono ottime: ridono,
%% scherzano, raccontano.' -- where the tokeniser dropped it too: code 4,
%% read as `colon'.
tr_speech_pieces([], []).
tr_speech_pieces([P0-S0|Ps], [P-S|Out]) :-
    %% (the marks in the MIDDLE are the text's whatever its stop: a piece
    %% that ends in `...' carries marks/4 for a stop, and `Tutta una serie di
    %% problemi (privatizzazioni, ...) vengono del tutto trascurati ...' lost
    %% its parentheses -- `una serie de privatizaciones problemas')
    ( integer(S0) -> tr_speech_piece(P0, S0, P, S) ; tr_mid_marks(P0, P), S = S0 ),
    tr_speech_pieces(Ps, Out).

%% A WHOLE SENTENCE IN THE PLAIN MARK WITH A REPORTING CLAUSE BETWEEN DASHES:
%% `"vedremo - aggiunge Ciro Riviezzo - su quali aspetti il capo ha puntato la
%% sua attenzione".' The pair is the piece's, and the marks are the sentence's
%% -- but a plain mark at the head is taken off only when nothing in the
%% piece closes it (tr_head_open/3), and this one is closed by the mark at
%% its end, so both stayed in the text, the piece was cut at its dashes, and
%% each part was tokenised by itself: `"Il cane' was a quotation that closed
%% at the end of the part, the mark on `cane', and the last part's mark
%% went with `dorme'. A pair that is the whole piece and has a dash in it
%% gives its two marks to the sentence, as a pair of the typographic marks
%% always did.
%% ... AND ONE WITH A SEMICOLON IN IT: `"No sé qué gran pecado he hecho para
%% merecer todo esto y puede ser que me decapite yo mismo; así, trabajo
%% hecho".' The piece is cut at its semicolon too, each part tokenised by
%% itself, and the first part's mark was closed on its own last word:
%% `... io stesso"; così, lavoro fatto.'
tr_speech_piece(P0, S0, P, S) :-
    tr_whole_pair(P0, Mark, P1), ( tr_has_dash(P1) -> true ; memberchk(59, P1) ), !,   % 59 is `;'
    tr_mid_marks(P1, P),
    S = marks(Mark, Mark, S0, []).
tr_speech_piece(P0, S0, P, S) :-
    tr_head_open(P0, Before, P1),
    tr_tail_close(P1, Inner, P2),
    tr_mid_marks(P2, P),
    ( Before == [], Inner == [] -> S = S0 ; S = marks(Before, Inner, S0, []) ).

%% a plain pair that is the whole piece: the mark at the head with a word
%% right after it, the mark at the end, and none between
tr_whole_pair(P0, [34], P1) :-
    tr_skip_blank(P0, [34|R0]), R0 = [C|_], tr_word_code(C),
    tr_trim_blank_end(R0, R1), append(P1, [34], R1), P1 \== [],
    \+ memberchk(34, P1).
%% a dash in the codes: a blank before it and no letter or digit after it, or an
%% en or em dash
tr_has_dash(Cs) :- append(_, [C0, 45|Cs1], Cs), C0 =< 32, \+ ( Cs1 = [D|_], D > 32, D \== 0',, D \== 0'. ), !.
tr_has_dash(Cs) :- append(_, [226, 128, D|_], Cs), ( D == 147 ; D == 148 ), !.
tr_has_dash(Cs) :- ( memberchk(8211, Cs) ; memberchk(8212, Cs) ), !.        % U+2013 and U+2014 as code points
%% an opening mark at the head of the piece, and the piece without it --
%% a plain one only when nothing in the piece closes it, or a pair at the
%% head (`"Hola", dijo Tom') would lose its first mark and keep its second
tr_head_open(P0, Mark, P) :-
    tr_skip_blank(P0, C1), tr_speech_mark(open, Mark, C1, P),
    \+ ( Mark == [34], append(_, R, P), tr_speech_mark(close, [34], R, _) ), !.
%% ... and a CLOSING mark at the head, which closes nothing in its piece: a
%% text cut into sentences after each stop hands the mark that ends one
%% quotation to the sentence after it (`” Aspetto questo giorno ...'), and
%% read as a boundary in the middle it left nothing before it to be a
%% clause. It goes back where it stood, in front of the sentence.
tr_head_open(P0, Mark, P) :-
    tr_skip_blank(P0, C1), tr_speech_mark(close, Mark, C1, P), !.
tr_head_open(P, [], P).

%% a closing mark at its end, with no opening mark before it that it closes
tr_tail_close(P0, Mark, P) :-
    tr_trim_blank_end(P0, P1),
    append(P, M, P1), tr_speech_mark(close, Mark, M, []),
    \+ tr_opens_unclosed(P), !.
tr_tail_close(P, [], P).

tr_trim_blank_end(Cs, Ds) :- append(Ds, Sp, Cs), \+ ( member(C, Sp), C > 32 ), ( Ds = [] ; last(Ds, L), L > 32 ), !.

%% an opening mark in these codes that no closing mark after it closes
tr_opens_unclosed(Cs) :-
    append(_, Rest, Cs), tr_speech_mark(open, _, Rest, After),
    \+ ( append(_, R2, After), tr_speech_mark(close, _, R2, _) ), !.

%% the marks and dashes in the middle, each as its code: a closing mark
%% nothing before it opened, an opening mark nothing after it closes, a
%% dash; a pair of marks is left as it stands
tr_mid_marks([], []).
tr_mid_marks(Cs, Out) :-
    tr_speech_mark(close, M, Cs, Rest), !,
    ( M == [34] -> K = 7 ; K = 1 ), Out = [K|More], tr_mid_marks(Rest, More).
tr_mid_marks(Cs, Out) :-
    tr_speech_mark(open, M, Cs, Rest), !,
    (   append(Mid, R2, Rest), tr_speech_mark(close, C, R2, R3)
    ->  append(M, Mid, O1), append(O1, C, O2), append(O2, More, Out), tr_mid_marks(R3, More)
    ;   Out = [2|More], tr_mid_marks(Rest, More)
    ).
tr_mid_marks([226, 128, D|Cs], [3|More]) :- ( D == 147 ; D == 148 ), !, tr_mid_marks(Cs, More).
tr_mid_marks([8211|Cs], [3|More]) :- !, tr_mid_marks(Cs, More).
tr_mid_marks([8212|Cs], [3|More]) :- !, tr_mid_marks(Cs, More).
%% (a dash has a space before it and no letter or digit after it: `"no - mi
%% ha risposto -, a me piace ...' closes its clause with a comma straight
%% after the dash, which read as a hyphen)
tr_mid_marks([C0, 45|Cs], [C0, 3|More]) :- C0 =< 32, \+ ( Cs = [D|_], ( D > 32, D \== 0',, D \== 0'. ) ), !, tr_mid_marks(Cs, More).
tr_mid_marks([D1, 58, D2|Cs], [D1, 58|More]) :- rt_digit(D1), rt_digit(D2), !, tr_mid_marks([D2|Cs], More).   % `20:45'
tr_mid_marks([58|Cs], [4|More]) :- !, tr_mid_marks(Cs, More).                  % 58 is `:'
tr_mid_marks([46, 46, 46|Cs], [8|More]) :- tr_skip_blank(Cs, [41|_]), !, tr_mid_marks(Cs, More).   % `...)'
tr_mid_marks([40|Cs], [5|More]) :- !, tr_mid_marks(Cs, More).                  % 40 is `('
tr_mid_marks([41|Cs], [6|More]) :- !, tr_mid_marks(Cs, More).                  % 41 is `)'
%% ... AND A PLAIN MARK WITH ITS BLANK ON THE WRONG SIDE: `sul tema" spazio
%% al tuo futuro "' -- the title is `spazio al tuo futuro', and the mark that
%% opens it stands against `tema' with the blank after it, so it read as a
%% closing mark, and the next one closed too: two boundaries, and a title
%% with no verb between them read as a clause of its own. Two plain closing
%% marks in a row, the first straight after a word, is a pair whose first
%% mark lost its place: it opens, and the blank goes before it.
tr_mid_marks([C, 34, B|Cs], [C, B|More]) :-
    B =< 32, tr_word_code(C), tr_skip_blank(Cs, Cs1), Cs1 = [W|_], tr_word_code(W),
    tr_next_plain_closes(Cs1), !,
    tr_mid_marks([34|Cs1], More).
tr_mid_marks([C|Cs], [C|More]) :- tr_mid_marks(Cs, More).

%% the next plain mark in these codes closes
tr_next_plain_closes(Cs) :- append(_, [34|R], Cs), !, tr_speech_mark(close, [34], [34|R], _).

%% the marks this reads: the typographic pair and the angled pair
tr_speech_mark(open, [226, 128, 156], [226, 128, 156|Rest], Rest).
tr_speech_mark(close, [226, 128, 157], [226, 128, 157|Rest], Rest).
tr_speech_mark(open, [194, 171], [194, 171|Rest], Rest).
tr_speech_mark(close, [194, 187], [194, 187|Rest], Rest).
tr_speech_mark(open, [8220], [8220|Rest], Rest).
tr_speech_mark(close, [8221], [8221|Rest], Rest).
tr_speech_mark(open, [171], [171|Rest], Rest) :- rt_chars.
tr_speech_mark(close, [187], [187|Rest], Rest) :- rt_chars.
%% ... AND THE PLAIN ONE, WHICH OPENS AND CLOSES ALIKE, SO WHERE IT STANDS
%% SAYS WHICH. El Periódico writes `"No es posible hacer una réplica ...
%% sin que un experto lo note.' and, a sentence later, `son únicos ", dijo
%% Claude Lebet' -- a quotation over two sentences in the mark a keyboard
%% has, with a blank before the closing one. A mark with a word right after
%% it opens; one with a blank, a stop, a comma or nothing after it closes.
%% The blank BEFORE a mark says nothing, because this source puts one on
%% both sides. Read as the typographic pair is read, the opening one goes
%% in front of its sentence and the closing one divides the quotation from
%% the clause that reports it; a pair inside one piece is left as it stood.
tr_speech_mark(open, [34], [34|Rest], Rest) :- Rest = [C|_], tr_word_code(C).
tr_speech_mark(close, [34], [34|Rest], Rest) :- \+ ( Rest = [C|_], tr_word_code(C) ).

%% a code a word can begin with: anything but a blank, a closing
%% punctuation mark or another quotation mark (`¿' and `¡' are 194, 191 and
%% 194, 161, so their first byte passes)
tr_word_code(C) :- C > 32, \+ memberchk(C, [33, 34, 41, 44, 46, 58, 59, 63]).

%% A PIECE'S WORDS, AND WHAT THE TOKENISER WOULD HAVE THROWN AWAY. Two
%% marks carry structure the reader needs and reason_tokens/2 drops:
%%
%% A SEMICOLON divides a sentence's clauses more strongly than a comma --
%% `se les llamará muchachos conflictivos; en los de clase media, chicos
%% difíciles' -- and the tokeniser drops it with no trace, so the clause
%% boundary went with it. The piece is cut at each `;' and the parts'
%% words joined by the atom `semicolon', which the clause splitter reads
%% as it reads a comma and the writer puts back.
%%
%% A HYPHEN INSIDE A CAPITALISED NAME is part of the name: `Jean-Pierre
%% Chevènement'. The tokeniser cut it into `jean' and `pierre' and lowered
%% both, so the name came back `Jean Pierre' at best. A capitalised run
%% with a hyphen between two letters is ONE word, spelled as the text
%% spelled it, which no lesson knows -- so it is a name, crosses as itself
%% and is written back whole. A lower-case hyphenated word is left to the
%% tokeniser, as before.
tr_piece_words(Piece, Words) :-
    tr_cut_seps(Piece, Parts),
    tr_parts_words(Parts, Words).

%% the piece cut at every boundary the tokeniser would drop, Codes, Sep,
%% Codes, ...: a semicolon, and the codes tr_speech_pieces/2 put in
tr_cut_seps(Codes, Parts) :-
    (   append(Before, [C|After], Codes), tr_sep_code(C, Sep), \+ tr_pair_semicolon(C, Before)
    ->  Parts = [Before, Sep|More], tr_cut_seps(After, More)
    ;   Parts = [Codes]
    ).

%% A SEMICOLON INSIDE A PAIR OF MARKS IS THE QUOTATION'S, NOT THE PIECE'S:
%% `"Escucho las reivindicaciones; me lo apunto", se limitó a decir el
%% presidente'. The plain pair stays in its piece (tr_mid_marks/2 leaves a
%% pair as it stands), and cut at its semicolon the first part held an
%% opening mark with no closing one and the second a closing mark with no
%% opening one: the closing mark read as a word, `,' with a quotation mark,
%% and the sentence was refused. A semicolon with an opening mark before it
%% that nothing before it closes stays in the piece (the pair's closing mark
%% is after it: tr_mid_marks/2 left the pair only where one was), and
%% tr_inside_words/2 cuts the quotation at it.
tr_pair_semicolon(59, Before) :-                                         % 59 is `;'
    tr_opens_unclosed(Before), !.

tr_sep_code(59, semicolon).                                            % 59 is `;'
tr_sep_code(1, endquote).
tr_sep_code(7, endquote_plain).
tr_sep_code(3, dash).
tr_sep_code(4, colon).
tr_sep_code(5, lparen).
tr_sep_code(6, rparen).
tr_sep_code(8, ellipsis).

%% a semicolon with nothing on one side of it is nothing; every other
%% boundary is kept where it stood, a dash that closes a clause included
%% -- and TWO DASHES WITH NOTHING BETWEEN THEM ARE ONE: AnCora spells an em
%% dash as two hyphens, `una inmensa luna - - el personaje principal ... - -
%% son dos de los elementos', and each pair is the one dash an editor wrote
tr_parts_words([P], Ws) :- !, tr_part_words(P, Ws).
tr_parts_words([P, Sep|Ps], Ws) :-
    tr_part_words(P, W1), tr_parts_words(Ps, W2),
    (   Sep == semicolon, W1 == [] -> Ws = W2
    ;   Sep == semicolon, W2 == [] -> Ws = W1
    ;   Sep == dash, W2 = [dash|_] -> append(W1, W2, Ws)
    ;   append(W1, [Sep|W2], Ws)
    ).

%% an opening mark whose quotation runs on past the piece marks the word
%% after it, which the writer gives the mark back
tr_part_words(Codes, Ws) :-
    append(Pre, [2|Post], Codes), !,
    tr_part_words(Pre, W1), tr_part_words(Post, W2),
    ( W2 = [w(W, C)|W3] -> tr_edge_case(C, qopen, Q), W2q = [w(W, Q)|W3] ; W2q = W2 ),
    append(W1, W2q, Ws).
%% A QUOTATION INSIDE A PIECE IS WORDS OF THE SENTENCE, READ AS WORDS. A
%% pair of marks was left to reason_tokens/2, which reads what stands
%% between them as ONE mentioned token -- the right reading for a lesson's
%% `"casa"' and the wrong one for newspaper prose, which quotes a whole
%% clause: `del 100% di Chrysler “ci permetterà di realizzare ... un
%% bagaglio di esperienze, punti di vista e competenze unico al mondo”'.
%% The token was then cut at its blanks and nothing else, so `esperienze,'
%% was a word with its comma on it and the sentence was refused for it; an
%% apostrophe, a written number and a hyphenated name inside the marks
%% were never read either. So the text between the marks is read by these
%% same clauses, as any other part of the piece is, and the marks go back
%% on its first and last words, which is the shape a quoted run already
%% had: qboth for one word, qopen and qclose round several.
tr_part_words(Codes, Ws) :-
    append(Pre, Rest, Codes), tr_quote_mark(open, OM, Rest, In0),
    append(Inside, Rest2, In0), tr_quote_mark(close, CM, Rest2, Post), !,
    tr_pre_words(Pre, W1), tr_inside_words(Inside, WI0), tr_part_words(Post, W2),
    %% A NAME IN QUOTATION MARKS IS ONE NAME: `dal "Washington Post"'. The
    %% marks on the run's edges took the place of its words' capitals, which
    %% were what said it was a name, and the sentence was refused for two
    %% unknown words. Every word capitalised, two at least: one token, the
    %% name spelled as the text spelled it, marks and all, which no lesson
    %% knows and every writer puts back as it stood. One capitalised word is
    %% left a word: `la "Bastiglia"' is a word the lesson may know.
    %% (a NUMBER may stand between its capitalised words: `collabora a "Flash
    %% Art" e il "Sole 24 Ore"' is the newspaper, and read as words it came
    %% out `las 24 "soles horas"')
    (   WI0 = [w(_, upper), _|_], last(WI0, w(_, upper)),
        forall(member(X, WI0), ( X = w(_, upper) -> true ; X = w(D, _), atom(D), tr_digits(D) ))
    ->  tr_trim_blank_end(Inside, In1), tr_skip_blank(In1, In2),
        append([OM, In2, CM], NCs), atom_codes(Name, NCs), WI = [w(Name, upper)]
    ;   tr_quote_edges(WI0, WI)
    ),
    append(W1, WI, W12), append(W12, W2, Ws).

%% A NUMBER IS WRITTEN BACK AS THE SOURCE WROTE IT. The tokeniser reads
%% `1.400' as the decimal 1.4 and drops the sign of `-10', which is right
%% for a sentence the reasoner reads and wrong for one a translator writes
%% back: Italian and Spanish both write a thousand and four hundred as
%% `1.400', and the sign of `-10 gradi' is the temperature. So a number with
%% a separator or a sign is taken out before the tokeniser sees it and
%% travels as ONE word, spelled as the text spelled it, which tr_digits/1
%% knows for a number. A bare run of digits is the tokeniser's, as before.
%% ... AND AN ELIDED WORD BEFORE IT KEEPS ITS APOSTROPHE: `noi siamo solo
%% all'1,4' elides the article before the number, and the words before a
%% number taken out end in the apostrophe, which the tokeniser drops when no
%% letter follows -- `all', a word no lesson knows
tr_part_words(Codes, Ws) :-
    tr_ampersand_name(Codes, Pre, Name, Post), !,
    tr_pre_words(Pre, W1), tr_part_words(Post, W2),
    append(W1, [w(Name, upper)|W2], Ws).
tr_part_words(Codes, Ws) :-
    tr_written_number(Codes, Pre, Num, Post), !,
    tr_pre_words(Pre, W1), tr_part_words(Post, W2),
    append(W1, [w(Num, lower)|W2], Ws).
tr_part_words(Codes, Ws) :-
    (   ( memberchk(0'-, Codes) ; tr_inner_capital(Codes) ; tr_inner_point(Codes)
        ; tr_two_capitals(Codes), ( tr_has_small(Codes) ; tr_acronym_part(Codes) ) ),
        tr_hyphen_name(Codes, Pre, Name, Post)
    ->  reason_tokens(Pre, T1), tr_words(T1, W1), tr_part_words(Post, W2),
        %% (a Roman numeral in capitals is a number, which travels in small
        %% letters as digits do and is written as the source spelled it)
        ( tr_digits(Name) -> NC = lower ; NC = upper ),
        append(W1, [w(Name, NC)|W2], Ws)
    ;   reason_tokens(Codes, Tokens), tr_words(Tokens, Ws)
    ).
%% ... AND A BRACKET INSIDE A PAIR IS AN ASIDE OF THE QUOTED CLAUSE, as it is
%% outside one: `"se va con el chollo que le han dado (una cátedra en Nueva
%% York), como si se le hubiéramos echado"'. The pair is left verbatim by
%% tr_mid_marks/2, so its brackets reached the tokeniser as they stood and
%% were dropped as punctuation -- the bracket's words ran on into the clause
%% as one more object of `han dado', and the sentence came out `con el
%% chollo que le han dado una cátedra en Nueva York'. The brackets inside the
%% pair are read as the marks they are, which tr_asides/2 turns into the
%% aside.
%% ... AND A DASH INSIDE A PAIR IS A DASH: `"La peatonalización - - añade - -
%% complementará el uso lúdico del pasaje", en el que ...' -- the pair is not
%% the whole piece, so it stays in the text with its hyphens in it, which
%% tr_whole_pair/3 turns into dashes when the same words are alone in the
%% pair; read as hyphens the reporting clause between them was refused, with
%% every word known. Only the dashes: a colon in a quoted title is its own
%% ... AND A SEMICOLON INSIDE A PAIR IS A SEMICOLON: `"Escucho las
%% reivindicaciones; me lo apunto", se limitó a decir el presidente' -- the
%% piece was not cut at it (tr_pair_semicolon/2), and the quotation is read
%% here as a piece of its own, which cuts it and joins the parts with the
%% atom `semicolon'; the tokeniser alone dropped it
tr_inside_words(Inside, Ws) :-
    (   ( memberchk(40, Inside) ; memberchk(41, Inside) ; memberchk(59, Inside) ; tr_has_dash(Inside) )
    ->  tr_bracket_codes(Inside, Inside0), tr_inside_dashes(Inside0, Inside1), tr_piece_words(Inside1, Ws)
    ;   tr_part_words(Inside, Ws)
    ).
tr_inside_dashes([], []).
tr_inside_dashes([226, 128, D|Cs], [3|More]) :- ( D == 147 ; D == 148 ), !, tr_inside_dashes(Cs, More).
tr_inside_dashes([8211|Cs], [3|More]) :- !, tr_inside_dashes(Cs, More).
tr_inside_dashes([8212|Cs], [3|More]) :- !, tr_inside_dashes(Cs, More).
tr_inside_dashes([C0, 45|Cs], [C0, 3|More]) :- C0 =< 32, \+ ( Cs = [D|_], ( D > 32, D \== 0',, D \== 0'. ) ), !, tr_inside_dashes(Cs, More).
tr_inside_dashes([C|Cs], [C|More]) :- tr_inside_dashes(Cs, More).
tr_bracket_codes([], []).
tr_bracket_codes([40|Cs], [5|Ds]) :- !, tr_bracket_codes(Cs, Ds).              % 40 is `(', code 5 `lparen'
tr_bracket_codes([41|Cs], [6|Ds]) :- !, tr_bracket_codes(Cs, Ds).              % 41 is `)', code 6 `rparen'
tr_bracket_codes([C|Cs], [C|Ds]) :- tr_bracket_codes(Cs, Ds).

%% ... AND AN ELIDED WORD BEFORE THE MARK KEEPS ITS APOSTROPHE: `nella
%% cronaca dell'"Assalto a Palazzo Farnese"' elides the article before a
%% title in marks. Cut at the mark, the words before it ended in the
%% apostrophe, which ends a word only when a letter follows it, so the
%% tokeniser dropped it and left `dell', a word no lesson knows
tr_pre_words(Pre, Ws) :-
    ( append(Pre0, [39], Pre) ; append(Pre0, [226, 128, 153], Pre) ; append(Pre0, [8217], Pre) ),
    last(Pre0, C), rt_alpha(C), !,
    tr_part_words(Pre0, Ws0),
    (   append(Ws1, [w(W, WC)], Ws0)
    ->  atom_concat(W, '\'', WA), append(Ws1, [w(WA, WC)], Ws)
    ;   Ws = Ws0
    ).
tr_pre_words(Pre, Ws) :- tr_part_words(Pre, Ws).

%% AN AMPERSAND BETWEEN TWO CAPITALISED WORDS IS PART OF A NAME: `Havoc &
%% Prodeje Common Sense', `Procter & Gamble'. The tokeniser drops a symbol,
%% and the two words came out side by side -- `Procter Gamble', and `Rock &
%% Roll' written back `Roll Rock'. The word before the sign, the sign and the
%% word after it are ONE word, spelled as the text spelled them: a word no
%% lesson knows, which is a name
tr_ampersand_name(Codes, Pre, Name, Post) :-
    append(Pre0, [32, 38, 32|Rest], Codes),
    tr_word_before(Pre0, Pre, W1), W1 = [C1|_], C1 >= 0'A, C1 =< 0'Z,
    Rest = [C2|_], C2 >= 0'A, C2 =< 0'Z,
    tr_word_after(Rest, W2, Post),
    append([W1, [32, 38, 32], W2], NCs), atom_codes(Name, NCs).
tr_word_before(Codes, Pre, Word) :-
    append(Pre, Word, Codes), Word \== [], forall(member(C, Word), tr_letter_code(C)),
    ( Pre == [] ; last(Pre, B), \+ tr_letter_code(B) ), !.
tr_word_after(Codes, Word, Post) :-
    append(Word, Post, Codes), Word \== [], forall(member(C, Word), tr_letter_code(C)),
    ( Post == [] ; Post = [A|_], \+ tr_letter_code(A) ), !.

%% the first number that carries a sign or a separator: a minus straight
%% before a digit where no letter or digit stands before it, then digits
%% with single points or commas between them
%%
%% A PERCENTAGE IS ONE WORD WITH ITS SIGN. `il restante 41,46% di Chrysler'
%% lost the sign: this clause took `41,46' out and the tokeniser dropped the
%% `%' after it as punctuation, so the sentence said forty-one of Chrysler.
%% And a bare `100%' went to the tokeniser as the number and the word
%% `percent', which no lesson of the lesson's language gives -- so `del
%% 100% di Chrysler' refused for a word the text never wrote. Italian,
%% Spanish and English all write the sign after the digits, so a number
%% with its `%' travels as ONE word, spelled as the text spelled it, and
%% tr_digits/1 knows it for a number.
tr_written_number(Codes, Pre, Num, Post) :-
    append(Pre, Rest, Codes),
    ( Pre == [] -> true ; last(Pre, B), \+ tr_letter_code(B), \+ rt_digit(B), B \== 0'., B \== 0', ),
    tr_number_run(Rest, NCs0, Post0),
    tr_number_written(NCs0, Post0, NCs, Post), !,
    atom_codes(Num, NCs).

%% ... AND A BARE NUMBER AFTER AN ELIDED WORD IS TAKEN OUT TOO: `sono soltanto
%% l'1 per cento' elides the article before the digit, and with no sign and
%% no separator the number stayed with the tokeniser, which drops an
%% apostrophe that no letter follows -- `l', a word no lesson knows -- and the
%% sentence was refused (`l'11,5' had a separator and was taken out already).
%% The word before it keeps its apostrophe, tr_pre_words/2. A year after a
%% blank (`gli anni '60') and a digit before the apostrophe are not elisions.
tr_written_number(Codes, Pre, Num, Post) :-
    append(Pre, [D|Rest], Codes), rt_digit(D),
    ( append(Pre0, [39], Pre) ; append(Pre0, [226, 128, 153], Pre) ; append(Pre0, [8217], Pre) ),
    last(Pre0, C), rt_alpha(C),
    tr_number_run([D|Rest], NCs, Post), !,
    atom_codes(Num, NCs).

tr_number_written(NCs0, [37|Post], NCs, Post) :- !, append(NCs0, [37], NCs).      % 37 is `%'
%% ... AND AN ORDINAL IS ONE WORD WITH ITS SIGN: `el 50º aniversario' lost
%% the `º' to the tokeniser, which drops a sign, so the fiftieth anniversary
%% was fifty anniversaries' worth of words, `il 50 anniversario'. The sign
%% is U+00BA or U+00AA, the bytes 194 186 and 194 170, after digits alone.
tr_number_written(NCs0, [194, S|Post], NCs, Post) :-
    ( S == 186 ; S == 170 ), forall(member(D, NCs0), rt_digit(D)), !, append(NCs0, [194, S], NCs).
tr_number_written(NCs0, [186|Post], NCs, Post) :-
    rt_chars, forall(member(D, NCs0), rt_digit(D)), !, append(NCs0, [186], NCs).        % U+00BA as a code point
tr_number_written(NCs0, [170|Post], NCs, Post) :-
    rt_chars, forall(member(D, NCs0), rt_digit(D)), !, append(NCs0, [170], NCs).        % U+00AA
%% ... AND ITALIAN'S ORDINAL IN DIGITS, the number and the ending of its gender, with a hyphen or none: `la
%% 38-ma edizione del festival' is the 38th edition, and the tokeniser dropped the hyphen and left `ma', the
%% word for `but' (`el 38 pero edición'). It travels as the ordinal with its sign, `38ª' (`-mo', `-mi' are
%% `º'), which every writer knows (tr_ordinal/2); the sign's codes are the atom's own in either unit
tr_number_written(NCs0, Post0, NCs, Post) :-
    forall(member(D, NCs0), rt_digit(D)),
    ( Post0 = [0'-, 0'm, V|Post] ; Post0 = [0'm, V|Post] ),
    ( memberchk(V, [0'a, 0'e]) -> Sign = 'ª' ; memberchk(V, [0'o, 0'i]) -> Sign = 'º' ),
    \+ ( Post = [C|_], tr_letter_code(C) ), !,
    atom_codes(Sign, SCs), append(NCs0, SCs, NCs).
tr_number_written(NCs, Post, NCs, Post) :- ( memberchk(0'-, NCs) ; memberchk(0'., NCs) ; memberchk(0',, NCs) ; memberchk(0'/, NCs) ; memberchk(0':, NCs) ), !.

tr_number_run([0'-, D|Cs], [0'-, D|Ns], Post) :- rt_digit(D), !, tr_digit_run(Cs, Ns, Post).
tr_number_run([D|Cs], [D|Ns], Post) :- rt_digit(D), tr_digit_run(Cs, Ns, Post).
tr_digit_run([D|Cs], [D|Ns], Post) :- rt_digit(D), !, tr_digit_run(Cs, Ns, Post).
tr_digit_run([S, D|Cs], [S, D|Ns], Post) :- ( S == 0'. ; S == 0', ), rt_digit(D), !, tr_digit_run(Cs, Ns, Post).
%% ... and a RANGE, two numbers with a hyphen between them: `el bienio
%% 2000-2001' was two numbers and a lost hyphen, and no phrase has two
%% counts after its noun, so the sentence was refused
tr_digit_run([0'-, D|Cs], [0'-, D|Ns], Post) :- rt_digit(D), !, tr_digit_run(Cs, Ns, Post).
%% ... and two numbers with a SLASH between them: `via lo 0/2' was `el 0
%% 2', the slash dropped as punctuation and one thing named twice
tr_digit_run([0'/, D|Cs], [0'/, D|Ns], Post) :- rt_digit(D), !, tr_digit_run(Cs, Ns, Post).
%% ... and a TIME OF DAY, hours and minutes with a colon between them: `la
%% messa delle ore 9:30' was `9', a colon that ended the piece as a heading's
%% and `30', and nothing read either half
tr_digit_run([0':, D1, D2|Cs], [0':, D1, D2|Ns], Post) :- rt_digit(D1), rt_digit(D2), \+ ( Cs = [D3|_], rt_digit(D3) ), !, tr_digit_run(Cs, Ns, Post).
tr_digit_run(Post, [], Post).

tr_cut_at(Codes, Sep, Parts) :-
    (   append(Before, [Sep|After], Codes) -> Parts = [Before|More], tr_cut_at(After, Sep, More)
    ;   Parts = [Codes]
    ).

%% the first capitalised word with a hyphen between two of its letters --
%% or with a CAPITAL after a small letter, which the tokeniser lowered too:
%% `un violín llamado Ex Von Szerdahely VieuxTemps' came back `Vieuxtemps'.
%% And a word ALL in capitals among small letters, an acronym: `la
%% consultora DBK' came back `Dbk'. A piece all in capitals is a heading,
%% lowered before this is asked (tr_caps_piece/2).
tr_hyphen_name(Codes, Pre, Name, Post) :-
    append(Pre, Rest, Codes),
    ( Pre == [] -> true ; last(Pre, B), \+ tr_letter_code(B) ),
    tr_capital_start(Rest),
    tr_name_codes(Rest, NameCodes, Post),
    ( memberchk(0'-, NameCodes) ; tr_inner_capital(NameCodes) ; tr_acronym(NameCodes) ; memberchk(0'., NameCodes) ), !,
    atom_codes(Name, NameCodes).

%% a point with a letter on either side of it: `Paral.lel'
tr_inner_point(Codes) :- append(_, [L1, 0'., L2|_], Codes), tr_letter_code(L1), tr_letter_code(L2), !.

%% two capitals side by side, and a word of capitals alone: `DBK'
tr_two_capitals(Codes) :- append(_, [U1, U2|_], Codes), U1 >= 0'A, U1 =< 0'Z, U2 >= 0'A, U2 =< 0'Z, !.
tr_acronym(Codes) :- Codes = [_, _|_], \+ ( member(C, Codes), \+ ( C >= 0'A, C =< 0'Z ) ).
%% ... and a part that is ONE such word, which a bracket cut out of its
%% sentence: `la Unión Europea (UE)' -- its small letters are outside the
%% bracket, so the part had none and `UE' came back `Ue'. A piece all in
%% capitals was lowered before this (tr_caps_piece/2), so what is left is
%% an acronym
tr_acronym_part(Codes) :- tr_skip_blank(Codes, C1), tr_trim_blank_end(C1, C2), tr_acronym(C2).
tr_has_small(Codes) :- append(_, [C|Rest], Codes), tr_small_code(C, Rest), !.

%% a small letter with a capital straight after it
tr_inner_capital(Codes) :- append(_, [L, U|_], Codes), L >= 0'a, L =< 0'z, U >= 0'A, U =< 0'Z, !.

tr_name_codes([C|Cs], [C|Ns], Post) :- tr_letter_code(C), !, tr_name_codes(Cs, Ns, Post).
tr_name_codes([0'-, C|Cs], [0'-|Ns], Post) :- tr_letter_code(C), !, tr_name_codes([C|Cs], Ns, Post).
%% ... a point between two of its letters, `Paral.lel' (tr_upto/4 above)
tr_name_codes([0'., C|Cs], [0'.|Ns], Post) :- tr_letter_code(C), !, tr_name_codes([C|Cs], Ns, Post).
%% ... AND A HYPHEN AND DIGITS: `el Telenotícies migdia de TV-3' names a
%% channel, and cut at the hyphen it was the name `TV' and the number -3,
%% which the number rule reads as a temperature below nought
tr_name_codes([0'-, D|Cs], [0'-, D|Ns], Post) :- rt_digit(D), !, tr_digit_codes(Cs, Ns, Post).
tr_name_codes(Post, [], Post).

tr_digit_codes([D|Cs], [D|Ns], Post) :- rt_digit(D), !, tr_digit_codes(Cs, Ns, Post).
tr_digit_codes(Post, [], Post).

tr_letter_code(C) :- ( C >= 0'a, C =< 0'z ; C >= 0'A, C =< 0'Z ; C >= 128 ), !.
tr_capital_start([C|_]) :- C >= 0'A, C =< 0'Z, !.
tr_capital_start([195, C|_]) :- C >= 128, C =< 158.
tr_capital_start([C|_]) :- rt_upper_cp(C), rt_chars.

tr_codes(T, Cs) :- is_list(T), !, Cs = T.
tr_codes(T, Cs) :- atom(T), !, atom_codes(T, Cs).
tr_codes(T, Cs) :- string(T), !, string_codes(T, Cs).
tr_codes(T, _)  :- throw(error(type_error(text, T), reason_translate/2)).

tr_split(Codes0, Pieces) :-
    tr_bracket_marks(Codes0, 0, Codes),
    tr_split0(Codes, Pieces0), tr_merge_abbreviations(Pieces0, Pieces).
%% AN EXCLAMATION OR A QUESTION MARK THAT CLOSES A BRACKET ENDS NO SENTENCE: `l'augusto compleanno del professore
%% (settant anni!) sorprende tutti' -- the paper's aside cries out, and cut at its mark the sentence was two pieces,
%% `... (settant anni' and `) sorprende tutti ...', neither of them one. The mark right before the closing bracket,
%% inside an open one, is dropped, and the bracket's words are read and written without it
tr_bracket_marks([], _, []).
tr_bracket_marks([40|Cs], D, [40|Out]) :- !, D1 is D + 1, tr_bracket_marks(Cs, D1, Out).
tr_bracket_marks([41|Cs], D, [41|Out]) :- !, D1 is max(0, D - 1), tr_bracket_marks(Cs, D1, Out).
tr_bracket_marks([C, 41|Cs], D, Out) :- D > 0, ( C == 33 ; C == 63 ), !, tr_bracket_marks([41|Cs], D, Out).
tr_bracket_marks([C|Cs], D, [C|Out]) :- tr_bracket_marks(Cs, D, Out).
tr_split0([], []) :- !.
tr_split0(Codes, Pieces) :-
    tr_upto(Codes, Piece, Stop, Rest),
    ( tr_blank(Piece) -> Pieces = More ; Pieces = [Piece-Stop|More] ),
    tr_split0(Rest, More).

%% A POINT AFTER AN ABBREVIATION AND BEFORE A NUMBER ENDS NO SENTENCE: `in
%% palese contrasto con quanto stabilito dall'art. 111 della costituzione'
%% is article 111, and cut at the point it was two pieces, `... dall'art' and
%% `111 della costituzione ...', neither of them a sentence. The piece that
%% ends in the abbreviation and the one that opens on the number are one, the
%% point dropped -- `art' is a word the lesson knows (`"art" is the apocope of
%% "articolo".'), as `gran' is one of `grande'.
tr_merge_abbreviations([], []).
tr_merge_abbreviations([P0-46, P1-S1|Ps], Out) :-
    tr_abbreviation_end(P0), tr_skip_blank(P1, [D|_]), rt_digit(D), !,
    append(P0, [32|P1], P),
    tr_merge_abbreviations([P-S1|Ps], Out).
tr_merge_abbreviations([P|Ps], [P|Out]) :- tr_merge_abbreviations(Ps, Out).

%% a piece that ends in one of the abbreviations a number follows: `art',
%% `artt', `n', `nn', `pag', `sig', `cfr', `dott', `prof'
tr_abbreviation_end(Codes) :-
    tr_trim_blank_end(Codes, Cs), append(Before, Word, Cs), Word = [_|_],
    \+ ( member(C, Word), \+ tr_letter_code(C) ),
    ( Before == [] ; last(Before, B), \+ tr_letter_code(B) ), !,
    atom_codes(W0, Word), downcase_atom(W0, W),
    memberchk(W, [art, artt, n, nn, pag, pagg, sig, sigg, cfr, dott, prof, ing, avv, dr, tel, num, 'pág', 'núm']).

tr_upto([], [], 46, []).                                                % 46 is `.'
%% A POINT BETWEEN TWO DIGITS ENDS NO SENTENCE: `a 1.400 metri' is a
%% thousand and four hundred metres in Italian and Spanish alike, and cut
%% there it was two pieces, `... a 1' and `400 metri ...', neither of them
%% a sentence
tr_upto([D1, 46, D2|Cs], [D1, 46|P], Stop, Rest) :- rt_digit(D1), rt_digit(D2), !, tr_upto([D2|Cs], P, Stop, Rest).
%% ... NOR DOES A POINT BETWEEN TWO LETTERS: Catalan writes its `l·l' as
%% `l.l' where the middle dot is not to hand, and `Paral.lel', the name of a
%% television programme, was cut there into `... si Paral' and `lel
%% continuará ...', and `lel' was a word no lesson knows
tr_upto([L1, 46, L2|Cs], [L1, 46|P], Stop, Rest) :- tr_letter_code(L1), tr_letter_code(L2), !, tr_upto([L2|Cs], P, Stop, Rest).
%% THREE POINTS ARE ONE STOP, and they are written back: `non era nemmeno
%% in grado di riconoscere i suoi amici ...' trails off, and cut at its
%% first point it ended in a full stop and two empty pieces
%% ... BUT THREE POINTS BEFORE A CLOSING BRACKET END NO SENTENCE: `sintonías
%% (De España para los españoles, Elena Francis, Fantasía, Protagonistas
%% nosotros...) y hasta anuncios' trails its list off inside the bracket,
%% and cut there the bracket never closed and was dropped
tr_upto([46, 46, 46|Cs], [46, 46, 46|P], Stop, Rest) :- tr_skip_blank(Cs, [41|_]), !, tr_upto(Cs, P, Stop, Rest).
tr_upto([46, 46, 46|Cs], [], marks([], [], 46, [46, 46]), Cs) :- !.
tr_upto([C|Cs], [], C, Cs) :- memberchk(C, [46, 33, 63]), !.            % . ! ?
%% A COLON BEFORE AN OPENING QUOTATION MARK ENDS THE SENTENCE: `Il presente:
%% "servono nove miliardi, ma prima il tribunale potrebbe cancellare il
%% Napoli".' -- what the heading announces is said in its own marks, and
%% read inside one piece the marks went on its first and last words, where
%% `Napoli' lost its capital with the closing one and was no name. Cut
%% there, the heading ends in its colon (and takes no full stop) and the
%% quotation is a sentence whose marks are the sentence's own.
tr_upto([58|Cs], [58], 46, Cs) :-                                        % 58 is `:'
    tr_skip_blank(Cs, C1), tr_quote_mark(open, _, C1, [C|_]), tr_word_code(C), !.
tr_upto([C|Cs], [C|P], Stop, Rest) :- tr_upto(Cs, P, Stop, Rest).

tr_blank(Cs) :- \+ ( member(C, Cs), C > 32 ).

%% the words with their case, w(Word, upper|lower); a comma is nothing, and
%% a number in digits or a quoted word is not a sentence this translates
%% A COMMA IS KEPT, because it is where a sentence's clauses divide and it
%% was dropped here before anything could see it. It travels as the atom
%% `comma' among the w/2 terms, and `tr_uncomma/2' takes them out again --
%% everything below the clause splitter expects a list of w/2 and nothing
%% else, so the commas are stripped the moment the split has read them.
%% A NUMBER IN DIGITS AND A WORD IN QUOTATION MARKS ARE WORDS HERE, and
%% neither was: tr_words/2 had a clause for word/2 and a comma and nothing
%% else, so a token of any other kind made it FAIL and the sentence produced
%% no words at all -- which is why `il premio da 200 milioni' and every
%% sentence carrying scare quotes refused before a word of grammar ran.
%%
%% They are the two tokens that pass through UNTRANSLATED. A number is the
%% same in every language and writes back as its digits; a word in quotation
%% marks is quoted in the text rather than mentioned -- newspaper prose puts
%% scare quotes round an ordinary word -- so it is read as the word it is
%% and the marks are written back round it. The case field carries them:
%% `qboth' for a single word, `qopen' and `qclose' round a run, which
%% tr_word_text/4 turns back into the marks and nothing else looks at.
tr_words([], []).
tr_words([word(W, C)|Ts], [w(W, C)|Ws]) :- !, tr_words(Ts, Ws).
tr_words([','|Ts], [comma|Ws]) :- !, tr_words(Ts, Ws).
tr_words([num(N)|Ts], [w(A, lower)|Ws]) :- !, format(atom(A), "~w", [N]), tr_words(Ts, Ws).
tr_words([quoted(Q)|Ts], Out) :- !,
    tr_quoted_words(Q, Qs), append(Qs, Ws, Out), tr_words(Ts, Ws).

%% a quoted token as its words, the marks kept on the run's edges
tr_quoted_words(Q, Qs) :-
    atom_string(Q, S), split_string(S, " ", " ", Parts0),
    findall(A, ( member(P, Parts0), P \== "", atom_string(A, P) ), As),
    tr_quoted_mark(As, Qs).
tr_quoted_mark([A], [w(A, qboth)]) :- !.
tr_quoted_mark(As, Qs) :-
    append([First|Mid0], [Last], As), !,
    findall(w(M, lower), member(M, Mid0), Mid),
    append([w(First, qopen)|Mid], [w(Last, qclose)], Qs).
tr_quoted_mark([], []).

%% the marks on the edges of a quoted run of words: both on its only word,
%% the opening one on its first and the closing one on its last; what is
%% not a word -- a comma -- carries no mark
tr_quote_edges(Ws0, Ws) :-
    findall(I, nth0(I, Ws0, w(_, _)), Is),
    (   Is = [I]
    ->  tr_mark_at(Ws0, I, qboth, Ws)
    ;   Is = [F|_], last(Is, L)
    ->  tr_mark_at(Ws0, F, qopen, Ws1), tr_mark_at(Ws1, L, qclose, Ws)
    ;   Ws = Ws0
    ).
tr_mark_at(Ws0, I, M, Ws) :- nth0(I, Ws0, w(W, C), Rest), tr_edge_case(C, M, M1), nth0(I, Ws, w(W, M1), Rest).
%% A CAPITAL ON A QUOTED RUN'S EDGE IS KEPT BESIDE ITS MARK until the side
%% is known (tr_quote_names/3): `señaló que "España ve con simpatía la
%% candidatura"' put the mark where the capital was, and `España' was no
%% name and no word, and the sentence was refused for it
tr_edge_case(upper, qopen, qopenu) :- !.
tr_edge_case(upper, qclose, qcloseu) :- !.
tr_edge_case(upper, qboth, qbothu) :- !.
tr_edge_case(_, M, M).

tr_uncomma([], []).
tr_uncomma([comma|Ws], Out) :- !, tr_uncomma(Ws, Out).
tr_uncomma([semicolon|Ws], Out) :- !, tr_uncomma(Ws, Out).
tr_uncomma([W|Ws], [W|Out]) :- tr_uncomma(Ws, Out).

%% ---- the languages, and which way --------------------------------------------
%%
%% A lesson learned plain is the language with no name; one learned under
%% a name is proved through lesson/2. The words vote: a word whose form
%% the lesson gives is the lesson's, its meaning is English, a word on
%% both sides says nothing. The language whose words the text uses most
%% is the one it is in; failing that the text is English, and goes into
%% the one language whose meanings it uses most -- two that fit equally
%% refuse it, and reason_translate/3 names one.

tr_way(any, Words, From, To) :-
    tr_languages(Ls), Ls \== [],
    findall(v(L, F, E), ( member(L, Ls), tr_votes_in(L, Words, F, E) ), Vs),
    (   tr_winner(Vs, from, L1) -> tr_set_language(L1), From = foreign, To = english
    ;   tr_winner(Vs, into, L2) -> tr_set_language(L2), From = english, To = foreign
    ).
tr_way(to_english, Words, foreign, english) :-
    tr_languages(Ls), Ls \== [],
    findall(v(L, F, E), ( member(L, Ls), tr_votes_in(L, Words, F, E) ), Vs),
    ( tr_winner(Vs, from, L1) -> true ; Ls = [L1] ),
    tr_set_language(L1).
tr_way(from_english(L), _, english, foreign) :- tr_set_language(L).

tr_languages(Ls) :-
    findall(L, tr_solve_plain(lesson_language(L)), L0), list_to_set(L0, L1),
    ( tr_solve_plain(mean(_, _)) -> Ls = [none|L1] ; Ls = L1 ).

tr_votes_in(L, Words, F, E) :- tr_set_language(L), tr_votes(Words, 0, 0, F, E).

tr_votes([], F, E, F, E).
%% a comma or a semicolon votes for nobody -- and with no clause for it the
%% vote FAILED, so a sentence with a comma was refused whenever the
%% language had to be voted for rather than named
tr_votes([M|Ws], F0, E0, F, E) :- atom(M), !, tr_votes(Ws, F0, E0, F, E).
tr_votes([w(W, _)|Ws], F0, E0, F, E) :-
    ( tr_known_word(foreign, W) -> Kf = 1 ; Kf = 0 ),
    ( tr_known_word(english, W) -> Ke = 1 ; Ke = 0 ),
    (   Kf =:= 1, Ke =:= 1
    ->  ( tr_lessons_own(W) -> F1 is F0 + 1, E1 = E0 ; F1 = F0, E1 = E0 )
    ;   F1 is F0 + Kf, E1 is E0 + Ke
    ),
    tr_votes(Ws, F1, E1, F, E).

%% a word the lesson gives that English knows only by inflecting it --
%% `ha', which the inflector reads as the base of `has' -- is the lesson's
tr_lessons_own(W) :- tr_lexeme(foreign, W, _, _), \+ tr_lexeme(english, W, _, _), \+ en_function(W), \+ en_own(W).

%% one clear winner among the languages, or none
tr_winner(Vs, Which, L) :-
    findall(K-L0, ( member(v(L0, F, E), Vs), ( Which == from -> F > E, K = F ; E > F, K = E ) ), Cs),
    Cs \== [], keysort(Cs, S), last(S, K-L),
    \+ ( member(K-L2, S), L2 \== L ).

tr_set_language(L) :- nb_setval('$tr_language', L).
tr_language(L) :- ( catch(nb_getval('$tr_language', L0), _, fail) -> L = L0 ; L = none ).

%% ---- the whole sentence -----------------------------------------------------------

tr_translate(Words, From, To, Stop, Out) :-
    tr_kind(Stop, Kind), tr_exclaim(Stop),
    tr_into_ir(From, Kind, Words, S),
    tr_from_ir(To, Kind, S, Stop, Out).

tr_kind(marks(_, S, _), K) :- !, tr_kind(S, K).
tr_kind(marks(_, _, S, _), K) :- !, tr_kind(S, K).
tr_kind(63, question) :- !.                                               % 63 is `?'
tr_kind(_, statement).

%% whether a piece ended on `!': a sentence with no verb reads only then
tr_exclaim(Stop) :- ( ( Stop == 33 ; Stop = marks(_, 33, _) ; Stop = marks(_, _, 33, _) ) -> nb_setval('$tr_exclaim', yes) ; nb_setval('$tr_exclaim', no) ).

%% ---- the intermediate representation ---------------------------------------------
%%
%% THE IR IS THE SENTENCE TERM WITH ENGLISH WORDS IN IT, and every
%% language has the two halves over it: tr_into_ir/4 reads a sentence on
%% that language's own side and crosses its words, tr_from_ir/5 writes
%% one out. So a language is added by giving its lesson, not by giving a
%% pair of languages a path of their own, and any two of them translate:
%% Italian into the IR, the IR into Spanish, with no English sentence
%% assembled and none re-parsed.
%%
%% What travels exactly is the SHAPE -- s(Asked, Subject, Group,
%% Complements): the tense, the aspect, the denial, the person, the
%% number, what a question asks for, and every complement in its place.
%% What travels through English is the VOCABULARY, and it can be nothing
%% else: a lesson says what a word means only as mean(Word, EnglishWord),
%% so English is the one language every lesson is written against. A
%% sense English does not separate is a sense the IR cannot separate.
%%
%% ENGLISH IS THEREFORE ALREADY THE IR, which is what a pivot means: a
%% sentence read on the English side needs no crossing, and its words
%% stay as the text wrote them (`houses'), where a crossed word is the
%% lexeme its meaning gave (`house' with the number beside it). Both are
%% English words and both write out the same, because every consumer
%% takes the lexeme first -- tr_noun_lexeme/5 reads either.

%% into the IR: read on this side, then cross every word into English
tr_into_ir(Side, Kind, Words0, S) :-
    nb_setval('$tr_from', Side), nb_setval('$tr_read_side', Side), tr_number_source(Side), tr_future_protasis_note(Side),
    nb_setval('$tr_kind', Kind),
    %% (and whether a word the lesson says begins the relative is in it, `chi': the two readers of a
    %% free relative after a preposition, in front of a clause and in a heading, ask it first)
    (   Side == foreign, findall(FRL, tr_solve(begin(FRL, relative)), FRLs), FRLs \== [],
        member(w(FR, _), Words0), atom(FR), memberchk(FR, FRLs)
    ->  nb_setval('$tr_free_rel', yes) ; nb_setval('$tr_free_rel', no) ),
    %% (and whether a word for `who' is in it, `quién', `chi': the readers of who after a preposition ask it first)
    (   Side == foreign, findall(WL, tr_solve(mean(WL, who)), WLs), WLs \== [],
        member(w(WX, _), Words0), atom(WX), memberchk(WX, WLs)
    ->  nb_setval('$tr_who_word', yes) ; nb_setval('$tr_who_word', no) ),
    %% (and a word that asks `what', `qué': the reader of what after a preposition asks it first)
    (   Side == foreign, findall(QL, tr_solve(mean(QL, what)), QLs), QLs \== [],
        member(w(WQ, WQC), Words0), atom(WQ), memberchk(WQ, QLs), tr_question_word(w(WQ, WQC), what)
    ->  nb_setval('$tr_what_word', yes) ; nb_setval('$tr_what_word', no) ),
    empty_assoc(NoFailures), nb_setval('$tr_failed', NoFailures), tr_memo_reset, nb_setval('$tr_fem_persons', []),
    %% A SENTENCE THE SOURCE BEGINS IN SMALL LETTERS IS NO COMMAND: it is what is
    %% left of one, the clause that reports a question after its closing mark --
    %% `"¿Por Qué AENA no hace nada en estos casos?", pregunta Camp' is Camp asking,
    %% and the present `pregunta' read as the command it is too, `Ask Camp'. The
    %% caller says so, from the words as the source wrote them, before the capital of
    %% a sentence's first word is taken off ('$tr_small_head', tr_small_head_note/2):
    %% a verb of saying in small letters, the clause that reports, and no other word
    %% (`"mettiamola la così: noi crediamo ...', a source's sentence in small letters,
    %% is the command it was)
    ( Side == foreign, tr_global('$tr_small_head', yes) -> nb_setval('$tr_no_command', yes) ; nb_setval('$tr_no_command', no) ),
    %% (whether the sentence has a joined relative at all -- `per cui' -- is
    %% asked once here, on its words before the asides are taken out, so the
    %% phrase reader asks it of a word only where the answer can be yes)
    ( member(JW, Words0), tr_joined_relative(Side, JW, _, _) -> nb_setval('$tr_joined', yes) ; nb_setval('$tr_joined', no) ),
    %% (and whether it names the first person, for the present subjunctive
    %% that is spelled as its third: tr_form0/5)
    (   Side == foreign, member(w(YW, _), Words0), atom(YW), tr_subject_pronoun(foreign, YW, first, singular)
    ->  nb_setval('$tr_first', yes)
    ;   nb_setval('$tr_first', no)
    ),
    %% (and whether it has a word meaning `by' with a participle soon after
    %% it, the agent before its participle, which the phrase readers asked at
    %% every phrase by walking every word for its meanings: the largest part
    %% of what the new rules cost the controls)
    (   Side == foreign, \+ tr_agent_first_note(Words0) -> nb_setval('$tr_agent_first', no) ; nb_setval('$tr_agent_first', yes) ),
    %% (and three words the readers asked after at every phrase and every
    %% complement, each rare in a sentence: a participle after a determiner,
    %% before its noun (tr_np/3), which cost the controls more than
    %% everything else this version added; a relative meaning `whose'
    %% (tr_relative_clause/4); and a word the lesson calls exclamative
    %% (tr_complements0/4))
    (   Side == foreign, \+ tr_pptc_note(Words0) -> nb_setval('$tr_pptc', no) ; nb_setval('$tr_pptc', yes) ),
    (   Side == foreign, \+ ( member(w(XW, _), Words0), tr_whose_word(XW) )
    ->  nb_setval('$tr_whose', no) ; nb_setval('$tr_whose', yes) ),
    (   Side == foreign, \+ ( member(w(EW, _), Words0), atom(EW), tr_solve(exclamative(EW)) )
    ->  nb_setval('$tr_exclamative', no) ; nb_setval('$tr_exclamative', yes) ),
    %% (and a coordinator with an adjunct right after it, where a relative clause
    %% with two verbs could divide: tr_relative_clause/4, which asked every
    %% word of every relative clause whether it was a coordinator)
    (   Side == foreign, \+ tr_front_coord_note(Words0) -> nb_setval('$tr_front_coord', no) ; nb_setval('$tr_front_coord', yes) ),
    %% (and a relative word, its verb, and later a coordinator and a verb in that verb's tense, person and number, where
    %% a relative clause has two verbs: tr_relative_clause/4)
    (   Side == foreign, \+ tr_rel_two_verbs_note(Words0) -> nb_setval('$tr_rel_two_verbs', no) ; nb_setval('$tr_rel_two_verbs', yes) ),
    %% (and a comma with a relative word right after it, where a phrase can have a
    %% second relative clause: tr_np/3)
    (   Side == foreign, \+ tr_comma_rel_note(Words0) -> nb_setval('$tr_comma_rel', no) ; nb_setval('$tr_comma_rel', yes) ),
    %% (and a coordinator, a relative word and the doer after its verb, where a phrase can have a second relative
    %% clause joined to the first: tr_np/3)
    (   Side == foreign, \+ tr_second_rel_note(Words0) -> nb_setval('$tr_second_rel', no) ; nb_setval('$tr_second_rel', yes) ),
    %% (and a word that replaces a noun with a relative word or a degree word right after it, `lo que', `lo más', where a
    %% phrase can be `all that', `nothing of what' or `the most ... thing': tr_np/3 and tr_subject_shape/4, whose clauses for
    %% them each asked the lexicon first at every phrase, the largest part of what they cost the controls)
    (   Side == foreign, \+ tr_replacer_note(Words0) -> nb_setval('$tr_replacer', no) ; nb_setval('$tr_replacer', yes) ),
    %% (and the word for `number' with digits after it, `la puerta de embarque número 24', where a phrase can be a noun
    %% and its number: tr_np/3, whose clause for it was nine tenths of what the new code cost 23 sentences of the controls)
    (   Side == foreign, \+ tr_numbered_note(Words0) -> nb_setval('$tr_numbered', no) ; nb_setval('$tr_numbered', yes) ),
    %% (and the word for `also' or `even' that is a noun too, `ragioni anche generazionali', where a phrase can go on over
    %% it: tr_focus_ints/3 and tr_focus_adj_start/2, whose list asked at every word of every phrase cost a long Spanish
    %% sentence, with no such word in the language, 1 % of its inferences: the note is the sentence's own such words)
    (   Side == foreign -> tr_focusnoun_note(Words0, FNs), nb_setval('$tr_focusnoun', FNs) ; nb_setval('$tr_focusnoun', []) ),
    %% (and an adjective, a preposition, an article and a relative word, `similar al que', where the adjective's
    %% phrase can be the one that: tr_np/3, whose clause for it walked every phrase it was asked, 7.4 million
    %% inferences of the 7.4 the first cut cost seven of the heaviest sentences of the controls)
    (   Side == foreign, \+ tr_adj_rel_note(Words0) -> nb_setval('$tr_adj_rel', no) ; nb_setval('$tr_adj_rel', yes) ),
    %% (and a participle with the word for `by' right after it, where a participle and its agent can follow a noun
    %% and a phrase of the noun's own: tr_np/3)
    (   Side == foreign, \+ tr_ptc_agent_note(Words0) -> nb_setval('$tr_ptc_agent', no) ; nb_setval('$tr_ptc_agent', yes) ),
    %% (and the copula, a pronoun of the first or the second person and a determiner, where the pronoun can be the
    %% subject said after the copula, `Ero io il re': tr_read_statement0/4, whose clause for it walked every piece it
    %% was asked, nine tenths of what the new code cost thirteen sentences of the controls)
    (   Side == foreign, \+ tr_pron_copula_note(Words0) -> nb_setval('$tr_pron_copula', no) ; nb_setval('$tr_pron_copula', yes) ),
    %% (and a word for `where', a coordinator and a determiner after it, and the end of the words or another word for
    %% `where' four words on at most: two phrases with their clauses of `where', tr_complements0/4)
    (   Side == foreign, \+ tr_where_co_note(Words0) -> nb_setval('$tr_where_co', no) ; nb_setval('$tr_where_co', yes) ),
    %% (and a word for `among', where a coordinator after it joins the two it takes: tr_conjunction_split/5)
    (   Side == foreign, \+ tr_among_note(Words0) -> nb_setval('$tr_among', no) ; nb_setval('$tr_among', yes) ),
    %% (and the lesson's verbs of seeming and its adverbs that say how many, found by their meanings once a sentence:
    %% the statement reader's clause for a verb of seeming asked tr_form/5 of the first word of every piece, and
    %% tr_complements0/4's two clauses for `ben' and a count asked at every complement, a third of what the new
    %% rules cost the controls; a word's lexeme is asked against the list first)
    (   Side == foreign
    ->  findall(L1, ( tr_solve(mean(L1, seems)) ; tr_solve(mean(L1, appears)) ), SLs), nb_setval('$tr_seem_lexemes', SLs),
        findall(L2, ( tr_solve(mean(L2, well)) ; tr_solve(mean(L2, 'as many as')) ), CLs), nb_setval('$tr_count_lexemes', CLs),
        %% (and the words that mean the article `a', whose feminine after the definite article is one o'clock, `la
        %% una': tr_np/3's clause for it asked the determiner of the second word of every phrase of two)
        findall(L3, tr_solve(mean(L3, a)), ALs), nb_setval('$tr_a_lexemes', ALs),
        %% (and the verbs that mean another thing with a person for their object, `investe': tr_personal_here/3)
        findall(L4, tr_solve(mean_as(L4, _, personal)), PLs), nb_setval('$tr_personal', PLs)
    ;   nb_setval('$tr_a_lexemes', []), nb_setval('$tr_personal', [])
    ),
    %% (and a gerund, which after a subject's phrase is a relative clause on it: tr_subject/6)
    (   Side == foreign, tr_gerunds_of(Words0, Gs), Gs = [_|_] -> nb_setval('$tr_ger', Gs) ; nb_setval('$tr_ger', []) ),
    %% (and a name in small letters, `superquark', which the name readers
    %% asked the store after for every word in small letters they met)
    (   Side == foreign, \+ ( member(w(NW, lower), Words0), atom(NW), tr_solve(name(NW)) )
    ->  nb_setval('$tr_small_name', no) ; nb_setval('$tr_small_name', yes) ),
    %% (and whether a month is among the words, which a date in front of a relative clause's verb needs:
    %% tr_relative_clause/4 and tr_rel_time_comma/3. Asked as a lexeme of the six words after every relative word that
    %% an article follows, it cost Tempi's `... convinto che l'apertura dell'Olivo fosse solo un modo per prendere
    %% tempo' 1.8 million inferences, the text the same)
    (   Side == foreign, findall(M, tr_solve(month(M)), Ms), Ms \== [],
        once(( member(w(MW, _), Words0), atom(MW), memberchk(MW, Ms) ))
    ->  nb_setval('$tr_month', yes) ; nb_setval('$tr_month', no) ),
    tr_rel_time_comma(Side, Words0, Words0c),
    tr_adj_lists(Side, Words0c, WordsL),
    tr_head_per(Side, WordsL, WordsLP),
    tr_asides(Side, WordsLP, WordsA0),
    tr_clause_mids(Side, no, WordsA0, WordsA),
    tr_list_commas(Side, WordsA, Words),
    nb_setval('$tr_piece', Words),
    ( catch(nb_getval('$tr_title', yes), _, fail) -> nb_setval('$tr_heading', Words) ; nb_setval('$tr_heading', none) ),
    (   tr_read(Side, Kind, Words, S00)
    ;   tr_that_fragment(Side, Kind, Words, S00)
    ),
    tr_split_subject_quote(Side, S00, S0x),
    tr_focus_subject(Side, S0x, S0a),
    tr_polite_wish(Side, Words, S0a, S0b1),
    tr_copula_goes(Side, Words, S0b1, S0b2),
    tr_accusative_dative(Side, Words, S0b2, S0b3),
    tr_near_future(Side, S0b3, S0b),
    tr_as_inf_pass(Side, S0b, S0),
    tr_cross(Side, S0, S1a),
    tr_counterfactual(Side, S1a, S1),
    tr_city_in(Side, S1, S2),
    tr_carries_time(Side, S2, S).

%% A COMMA BETWEEN A DATE AND THE VERB AFTER A RELATIVE WORD IS NONE OF THE CLAUSE'S: `Dieci ergastoli per i componenti
%% della banda che il 7 novembre del settantasette, rapì il duca' -- the paper's slip, a comma that parts the clause from
%% its verb. With it the heading's relative clause had no verb, and the sentence was refused. An article opens the
%% date, a month is among its words, and the verb follows the comma
tr_rel_time_comma(foreign, Ws0, Ws) :-
    tr_global('$tr_month', yes), memberchk(comma, Ws0),
    append(Pre, [w(R, RC)|Post0], Ws0), atom(R), tr_relative_word(foreign, R),
    append(T, [comma, V|Post], Post0), T = [D, _|_], \+ memberchk(comma, T), length(T, TL), TL =< 6,
    D = w(_, _), tr_determiner(foreign, D, _, article),
    once(( member(w(MW, _), T), atom(MW), tr_lexeme(foreign, MW, ML, _), tr_holds(month(ML)) )),
    V = w(VW, _), atom(VW), tr_verb_form_word(VW), !,
    append([Pre, [w(R, RC)|T], [V|Post]], Ws).
tr_rel_time_comma(_, Ws, Ws).

%% THE WORD FOR `even', `also' OR `only' THAT ENDS THE FRONT, RIGHT BEFORE THE SUBJECT, IS SAID OF THE SUBJECT: `Ante el
%% pobre despliegue, incluso representantes municipales que seguían en la plaza a las dos mostraron su desaprobación'
%% -- even they showed it; read as the last of the fronts, English wrote it between commas of its own, `In front of
%% the poor deployment, even, municipal representatives'. A subject with no determiner, which the subject reader does
%% not take the word with (with one, `incluso los perros', it does: advp/2)
tr_focus_subject(foreign, s(A, Su, G, Cs0), s(A, advp(W, Su), G, Cs)) :-
    append(Fr, [fr(adv(W))|Cs1], Cs0), Fr = [_|_], last(Fr, fr(sep)), \+ memberchk(fr(_), Cs1),
    ( Su = np(none, _, _, _, _) -> true ; Su = rc(np(none, _, _, _, _), _, _) ),
    tr_focus_front(W), !,
    append(Fr, Cs1, Cs).
tr_focus_subject(_, S, S).

%% THE PAST SUBJUNCTIVE OF THE VERB OF WANTING, AS A SENTENCE'S OWN VERB, IS A POLITE WISH: `quisiera saber qué
%% hacer' is I would like to know -- the conditional, which the lesson's languages and English say it with (`vorrei
%% sapere'); read as the imperfect it stands for after `si', it was `voleva sapere', he wanted to. Its first person is
%% spelled as its third, and it is the first where the sentence names the first person by another word: a verb in
%% the first person (`pues siento que'), or `yo' (tr_first). Only the clauses of the sentence itself, the halves of a
%% join, never a clause inside one
tr_polite_wish(foreign, Words, join(C, S1, S2), join(C, T1, T2)) :- !,
    tr_polite_wish(foreign, Words, S1, T1), tr_polite_wish(foreign, Words, S2, T2).
tr_polite_wish(foreign, Words, s(A, Su0, g(L, imperfect, simple, Neg), Cs), s(A, Su, g(L, conditional, simple, Neg), Cs)) :-
    atom(L), tr_solve(mean(L, wants)),
    append(Before, [w(W, _)|_], Words), atom(W), tr_solve(subjunctive_of(W, _)), tr_holds(past(W)), tr_form(W, L, singular, _, _),
    %% (never after a word that opens a clause: `Si quisiera dormir' is if he wanted, the imperfect it stands for)
    \+ ( member(X, Before), X = w(XW, _), atom(XW), ( tr_is(foreign, X, conjunction) ; tr_relative_word(foreign, XW) ) ), !,
    (   Su0 = null(third, singular),
        (   tr_global('$tr_first', yes) -> true
        ;   member(w(W2, _), Words), atom(W2), W2 \== W, tr_form(W2, L2, singular, _, first), atom(L2), tr_class_of(L2, verb)
        )
    ->  Su = null(first, singular)
    ;   Su = Su0
    ).
tr_polite_wish(_, _, S, S).

%% A CONDITION IN THE PLUPERFECT BEFORE A MAIN CLAUSE IN THE PLUPERFECT IS COUNTERFACTUAL, the main clause the
%% conditional perfect: `"Si se hubiera advertido a la gente ..., no hubiera muerto aquel anciano"' -- that old
%% man WOULD NOT HAVE DIED, the second pluperfect subjunctive standing for the conditional, and read as the
%% indicative it is written as it was `had not died' and `non era morto'. The main clause after the condition's
%% comma, or the first clause of what follows it (a quotation's before its reporting clause); asked of the IR
tr_counterfactual(foreign, join(K, J, S2), join(K, J, T2)) :-
    J = join(C, none, S1), ( C = w(if, _) ; C = wc(w(if, _)) ), tr_pluperfect(S1),
    tr_pluperfect_main(S2, T2), !.
tr_counterfactual(_, S, S).
tr_pluperfect(s(_, _, g(_, imperfect, Asp, _), _)) :- memberchk(Asp, [perfect, passive_perfect]).
tr_pluperfect_main(s(A, Su, g(L, imperfect, perfect, N), Cs), s(A, Su, g(L, conditional, perfect, N), Cs)) :- !.
tr_pluperfect_main(join(K, X0, Y), join(K, X, Y)) :- tr_pluperfect_main(X0, X).

%% `LLEVA' AND A COUNT OF TIME IS HOW LONG ONE HAS BEEN SOMEWHERE: `Blackefer lleva tres años en la Red' has been on
%% the Net for three years -- the lesson's `lleva' is `carries', and English wrote `Blackefer carries three years in
%% the Net', Italian `porta tre anni nella Rete'. The verb is the copula and the count the time it has gone on for,
%% the phrase of `for the past' that `desde hace' already crosses to, which English writes with the perfect and the
%% lesson's language as its own (`è nella Rete da tre anni'). Nothing done after it: `lleva tres años trabajando'
%% is the gerund's, and `lleva tres años la casa' an object
tr_carries_time(Side, join(C, S1, S2), join(C, T1, T2)) :- !, tr_carries_time(Side, S1, T1), tr_carries_time(Side, S2, T2).
tr_carries_time(foreign, s(A, Su, g(carries, present, simple, Neg), [at_time(NP)|Rest]), s(A, Su, g(is, present, simple, Neg), Cs)) :-
    NP = np(none, Num, [], w(U, _), _), Num \== none, atom(U), memberchk(U, [year, month, week, day, hour, minute]),
    \+ ( member(X, Rest), ( tr_object_comp(X) ; X = ger(_, _) ; tr_infinitive_comp_any(X) ) ), !,
    append(Rest, [pp(w('for the past', lower), NP)], Cs).
tr_carries_time(_, S, S).

%% A PHRASE OF `to' BEFORE A CITY THE LESSON NAMES, AFTER A VERB THAT DOES NOT
%% GO, IS A PHRASE OF `in': `al termine del match mondiale ... a Perugia' took
%% place in Perugia, and `a' is the word the lesson gives for both, so it was
%% written `to Perugia'. A verb of going keeps it (`va a Roma'). The IR is
%% English by now, and so is the verb
tr_city_in(Side, join(C, S1, S2), join(C, T1, T2)) :- !, tr_city_in(Side, S1, T1), tr_city_in(Side, S2, T2).
tr_city_in(foreign, gap(Front, Cs0), gap(Front, Cs)) :- !, tr_cities_in(Cs0, Cs).
tr_city_in(foreign, s(A, Su, g(L, T, Asp, Neg), Cs0), s(A, Su, g(L, T, Asp, Neg), Cs)) :- !,
    (   tr_motion_verb(L) -> tr_cities_nested(Cs0, Cs)
    ;   tr_cities_in(Cs0, Cs)
    ).
tr_city_in(_, S, S).
%% (a clause of `that' is a clause of its own: `ha accettato che l'Egibren non è
%% stato consumato quella sera a Perugia' took place in Perugia too)
tr_cities_in([], []).
tr_cities_in([pp(w(to, C), name(N))|Cs0], [pp(w(in, C), name(N))|Cs]) :- tr_city_name(N), !, tr_cities_in(Cs0, Cs).
%% (and two of them joined: `a Linate e Malpensa si aspettano 80 mila partenze' are awaited IN
%% Linate and Malpensa, where it was `to Linate and Malpensa')
tr_cities_in([pp(w(to, C), co(K, name(N1), name(N2)))|Cs0], [pp(w(in, C), co(K, name(N1), name(N2)))|Cs]) :-
    tr_city_name(N1), tr_city_name(N2), !, tr_cities_in(Cs0, Cs).
tr_cities_in([that(S0)|Cs0], [that(S)|Cs]) :- !, tr_city_in(foreign, S0, S), tr_cities_in(Cs0, Cs).
tr_cities_in([fr(X0)|Cs0], [fr(X)|Cs]) :- !, tr_cities_in([X0], [X]), tr_cities_in(Cs0, Cs).   % a front's city
tr_cities_in([X|Cs0], [X|Cs]) :- tr_cities_in(Cs0, Cs).
tr_cities_nested([], []).
tr_cities_nested([that(S0)|Cs0], [that(S)|Cs]) :- !, tr_city_in(foreign, S0, S), tr_cities_nested(Cs0, Cs).
tr_cities_nested([X|Cs0], [X|Cs]) :- tr_cities_nested(Cs0, Cs).
%% (tr_write/4's `does': the question asks for the object, or the clitic `lo' or
%% a word for nothing is all the verb takes)
tr_makes_does(object(_), Cs, Cs) :- \+ ( member(C, Cs), tr_makes_made(C) ), !.
%% (in a statement, and in a question that asks why, when, where or how: `"¿Por Qué AENA no hace nada en estos
%% casos?"' is why does AENA not DO anything, where it was `make anything')
tr_makes_does(A, [opron(w(him, C))|Cs], [opron(w(it, C))|Cs]) :- tr_makes_asks_no_thing(A), \+ ( member(X, Cs), tr_makes_made(X) ), !.
tr_makes_does(A, [opron(w(W, C))|Cs], [opron(w(W, C))|Cs]) :- tr_makes_asks_no_thing(A),
    memberchk(W, [nothing, everything, something, anything]), \+ ( member(X, Cs), tr_makes_made(X) ), !.
tr_makes_made(C) :- functor(C, F, _), memberchk(F, [obj, opron, inf, pred, adj, that, purpose, ger, part]).
tr_makes_asks_no_thing(none) :- !.
tr_makes_asks_no_thing(A) :- A =.. [K, _], memberchk(K, [reason, time, place, manner]).
%% (tr_write/4's `ends': where or how a thing ends up)
tr_ends_up_where(C) :- functor(C, F, _), memberchk(F, [pp, pp2, pred, adj, ger, part, obj, that]), !.
tr_ends_up_where(adv(w(W, _))) :-
    atom(W), atomic_list_concat([P, _|_], ' ', W), memberchk(P, [in, at, on, into, under, behind, inside, among]).
%% (tr_write/4's copula of `it is easy to')
en_copula_lexeme(is).
%% the English verbs of going and sending, and of taking and bringing somewhere
tr_motion_verb(L) :- atom(L), memberchk(L, [goes, comes, arrives, returns, travels, leaves, flies, moves, runs, drives, walks, heads, sends, brings, takes, carries, transfers, emigrates, reaches, departs, goes_back, drives_up]).

%% A PIECE THAT IS A CLAUSE OF `THAT' AND NOTHING ELSE, what a sentence the line
%% before left open goes on with: `diciamo che ...' and then, as a line of its
%% own, `che è stato un incidente di percorso.' -- that it was a mishap. The
%% clause stands alone as a fragment does, and every writer puts its word in
%% front of it. Asked for the whole piece only and after every other reading,
%% never for a half of one: read by tr_read0/4 it took the first half of
%% `Che poi il cane dorma, guardate che ...', which has a main clause
tr_that_fragment(foreign, statement, [W|Ws], gap([], [that(S1)])) :-
    tr_that_here(foreign, W), Ws = [_|_],
    tr_that_clause(foreign, Ws, S1), !.

%% A QUOTATION THAT OPENS ON THE SUBJECT AND GOES ON AFTER THE REPORTING
%% CLAUSE: `"questa trattativa con la Fininvest" dice Cecchi Paone, "ha
%% scatenato voci"' is `"esta negociación ...", dice Cecchi Paone, "ha
%% desatado ..."'. Read as one clause with the subject inside the first marks
%% and the second quotation opening on its verb (vq), the report after it,
%% the writers put the report at the end of the clause, and the marks were
%% round words that were no quotation. The report goes between the two parts
%% as cmid/1 puts one between two quotations: the subject alone before it,
%% and the verb after it with nobody named.
tr_split_subject_quote(foreign, join(comma, s(A, Su, G, Cs), Rep), join(cmid(Rep), gap([], Front), s(A, null(third, N), G, Cs))) :-
    Rep = s(_, _, g(RL, _, _, _), RCs), memberchk(subj_here, RCs), atom(RL), tr_saying_verb(RL),
    memberchk(vq, Cs), tr_subject_number(Su, N), tr_term_closes_quote(Su),
    ( Su = with(NP, PPs) -> Front = [obj(NP)|PPs] ; Front = [obj(Su)] ), !.
%% ... AND WITH A PRONOUN FOR THE REPORT: `"questa trattativa" dice lui, "ha
%% scatenato voci"' read the phrase for the subject of `dice' and `lui' for its
%% object, `lo dice'. A subject pronoun that never stands before a verb
%% (`"lui" does not precede the verb.') is who says it
tr_split_subject_quote(foreign, join(aside, s(_, Su, g(RL, T, Asp, Neg), [scomma, opron(w(X, C))|Rest]), S2),
                       join(cmid(Rep), gap([], Front), S2)) :-
    atom(RL), tr_saying_verb(RL), atom(X), tr_term_closes_quote(Su),
    tr_subject_pronoun(foreign, X, third, N), tr_solve(neg(precede(X, verb))),
    S2 = s(_, null(third, _), _, Cs2), memberchk(vq, Cs2), !,
    delete(Rest, sep, Rest1),
    Rep = s(none, pronoun(third, N, w(X, C)), g(RL, T, Asp, Neg), [subj_here|Rest1]),
    ( Su = with(NP, PPs) -> Front = [obj(NP)|PPs] ; Front = [obj(Su)] ).
tr_split_subject_quote(_, S, S).
tr_term_closes_quote(T) :-
    compound(T),
    (   T = w(_, _) -> tr_closes_quote(T)
    ;   T =.. [_|As], member(A, As), tr_term_closes_quote(A)
    ), !.

%% out of the IR: the IR's side IS English, so the writer crosses from it
%% -- into the lesson's language as it always did, and into English by
%% the identity above
%% EVERY SENTENCE STARTS WITH NO SUBJECT'S GENDER: a piece with no subject
%% sets none, and its participle agreed with the sentence BEFORE it -- the
%% Washington Post's last line, `estratto brano dell'articolo', came out
%% `extraído' after a masculine subject and `extraída' after `La Italia
%% actual', the same words translated two ways by where they stood
tr_from_ir(To, Kind, S0, Stop, Out) :-
    nb_setval('$tr_from', english), tr_memo_reset, nb_setval('$tr_subject_gender', masculine),
    ( To == foreign -> tr_country_articles(S0, S) ; S = S0 ),
    tr_write(To, Kind, S, Outs),
    tr_join(To, Kind, Outs, Stop, Out).

%% WHAT STANDS ASIDE FROM THE SENTENCE: a phrase in brackets -- `due
%% bambini (la figlia di 4 anni e il figlio del compagno di 5)', `vicino
%% Subiaco (Roma)' -- and an age between commas after a noun, `La donna, 36
%% anni, soccorsa dai carabinieri'. The tokeniser dropped the brackets and
%% their words ran into the sentence, and the age read as a list's third
%% item. Each is ONE item among the words, w(Key, paren) or w(Key, aside),
%% its words kept under Key until the crossing reads them on their own: the
%% phrase before takes it as the last thing it has (app/3), a bracket where
%% a complement may stand is one (paren/1), and every writer puts it back in
%% its marks. A bracket that never closes is dropped.
tr_asides(_, [], []).
%% ... AND WHO SAID SO RIGHT AFTER THE BRACKET: `ha ganado la subasta (288,4
%% millones de euros), según informó ayer la agencia Efe, que cita fuentes'.
%% The comment between commas (w(Key, per), below) is taken after the word
%% before its comma, and the bracket had taken that word: the comment stood
%% down, `según informó ...' was the sentence's last comment only where
%% nothing followed it, and the relative clause after it left the sentence
%% refused with every word known. The bracket is the word it hangs on.
tr_asides(foreign, [lparen|Ws0], Out) :-
    append(In, [rparen, comma, w(C, CC)|Ws1], Ws0), \+ memberchk(lparen, In), \+ memberchk(rparen, In), In \== [],
    tr_per_comment(C, Ws1, In1, Rest), !,
    tr_aside_key(K, In), tr_aside_key(K2, [w(C, CC)|In1]),
    (   Rest == [] -> Out = [w(K, paren), w(K2, per)]
    ;   tr_asides(foreign, Rest, Ws), Out = [w(K, paren), w(K2, per), comma|Ws]
    ).
tr_asides(Side, [lparen|Ws0], [w(K, paren)|Ws]) :-
    append(In, [rparen|Rest], Ws0), \+ memberchk(lparen, In), In \== [], !,
    tr_aside_key(K, In), tr_asides(Side, Rest, Ws).
tr_asides(Side, [lparen|Ws0], Ws) :- !, tr_asides(Side, Ws0, Ws).
tr_asides(Side, [rparen|Ws0], Ws) :- !, tr_asides(Side, Ws0, Ws).
%% ... AND AN EXAMPLE AFTER A CLOSING DASH, to its comma: `Ma i primi dati di
%% quest'anno - precisano al Ministero dell'Università - per esempio quelli
%% di Perugia e della Federico II di Napoli, suggerirebbero una tendenza al
%% ribasso' -- the first figures, for example Perugia's, would suggest. The
%% adverb that means `for example' opens it and the comma closes it, where
%% the dash closed the clause before it; read as the sentence's own, the
%% figures became a verb, `datan', for the words to have one
tr_asides(foreign, [dash, A|Ws0], [dash, w(K, aside)|Ws]) :-
    A = w(AW, _), atom(AW), tr_lexeme(foreign, AW, AL, _), tr_solve(mean(AL, 'for example')),
    append(In0, [comma|Rest], Ws0), In0 \== [], \+ memberchk(comma, In0), \+ memberchk(dash, In0),
    Rest = [w(_, _)|_], \+ ( member(X, In0), atom(X) ), !,
    tr_aside_key(K, [A|In0]), tr_asides(foreign, Rest, Ws).
%% (after a NAME too, and with a participle of its own: `Giorgio Salvini,
%% ..., 75 anni ben portati, ha l'aria' is seventy-five years well carried,
%% and read as the clause's, the years were its subject)
%% ... AND A SECOND ASIDE, AN ADJECTIVE, RIGHT AFTER THE AGE: `Stefano Makula,
%% 40 anni, romano, l'acqua delle piscine la conosce bene' -- his age, and then
%% where he is from. The comma that closes the age opens the second aside, so
%% the adjective had no comma before it for the rule that sets one off after a
%% name (tr_list_commas/5) and the sentence was refused. Each is an aside of
%% its own, w(Key, aside), and the phrase takes both (app/3 in app/3)
tr_asides(Side, [W, comma, w(N, NC)|Ws0], [W, w(K, aside), w(K2, aside)|Ws]) :-
    W = w(_, _), tr_digits(N), ( tr_is(Side, W, noun) -> true ; tr_name_word(Side, W) ),
    append(In0, [comma, w(A, lower), comma|Rest], Ws0), In = [w(N, NC)|In0], length(In, L), L =< 4,
    \+ memberchk(comma, In0),
    tr_np(Side, In, _),
    tr_is(Side, w(A, lower), adjective), \+ tr_is(Side, w(A, lower), verb), !,
    tr_aside_key(K, In), tr_aside_key(K2, [w(A, lower)]), tr_asides(Side, Rest, Ws).
%% ... AND WHAT HE IS, AND HOW MANY CHILDREN HE HAS, AFTER THE AGE: `il lavoro di Marino Maglietta, 64 anni, docente
%% di fisica all'università di Firenze, due figli' -- his age, his post and his two children, a paper's way of saying
%% who a man is. The comma that closes the age opens the post, a phrase with no article to the next comma or the end;
%% read as the clause's own, it was refused. A count and its noun after the post, to the end, is one more aside
tr_asides(foreign, [W, comma, w(N, NC)|Ws0], [W, w(K, aside), w(K2, aside)|Ws]) :-
    W = w(_, upper), tr_digits(N), tr_name_word(foreign, W),
    append(In0, [comma|Rest0], Ws0), In = [w(N, NC)|In0], length(In, L), L =< 4, \+ memberchk(comma, In0),
    tr_np(foreign, In, _),
    Rest0 = [A|_], A = w(_, lower), \+ tr_determiner(foreign, A, _, _), tr_is(foreign, A, noun),
    ( append(In2, [comma|Rest2], Rest0), \+ memberchk(comma, In2) -> true ; In2 = Rest0, Rest2 = [] ),
    In2 = [_, _|_], \+ ( member(X, In2), atom(X) ),
    tr_apposition(In2), !,
    tr_aside_key(K, In), tr_aside_key(K2, In2), tr_count_tail(Rest2, Ws).
tr_asides(Side, [W, comma, w(N, NC)|Ws0], [W, w(K, aside)|Ws]) :-
    W = w(_, _), tr_digits(N), ( tr_is(Side, W, noun) -> true ; tr_name_word(Side, W) ),
    append(In0, [comma|Rest], Ws0), In = [w(N, NC)|In0], length(In, L), L =< 4,
    tr_np(Side, In, _), !,
    tr_aside_key(K, In), tr_asides(Side, Rest, Ws).
%% ... and a YEAR between a comma and the end of the sentence, or another
%% comma: `destaca un violín llamado Ex Von Szerdahely VieuxTemps, de
%% 1736.', `un stradivarius conocido como Golden Bell, de 1686.' It is the
%% date of the thing before it, not the clause's, and it goes back there.
%% (of a THING before it, a noun or a name: `ex ministro que, en 1974,
%% como señal de aperturismo, se puso una barretina' is the minister putting
%% it on in 1974, and taken for an aside of `que' the year left the relative
%% clause with a mark where its front was)
tr_asides(Side, [W, comma, P, w(Y, YC)|Ws0], [W, w(K, aside)|Ws]) :-
    W = w(_, _), tr_year(Y), tr_is(Side, P, preposition),
    ( tr_is(Side, W, noun) -> true ; tr_name_word(Side, W) ),
    ( Ws0 == [] -> Rest = [] ; Ws0 = [comma|Rest] ), !,
    tr_aside_key(K, [P, w(Y, YC)]), tr_asides(Side, Rest, Ws).
%% ... AND A PHRASE OF `AMONG' WITH A PRONOUN, after a noun and its comma: `cuatro
%% palestinos, entre ellos un niño de 10 años, y dos israelís, perdieron la vida'
%% -- the boy is one of the four. `entre' is the subjunctive of `entrar' too,
%% and read as the clause's own words it was that verb, `li entra un bimbo',
%% the boy its subject. The preposition, its pronoun and what they have after
%% them, to the next comma or the end, are read as the phrase of a preposition
%% is (tr_complements/3), and the phrase hangs on the noun before the comma
tr_asides(foreign, [W, comma, P, Pr|Ws0], [W, w(K, aside)|Ws]) :-
    W = w(_, _), tr_is(foreign, W, noun),
    P = w(PW, _), atom(PW), tr_is(foreign, P, preposition), tr_lexeme(foreign, PW, PL, _), tr_solve(mean(PL, among)),
    Pr = w(_, _), tr_is(foreign, Pr, pronoun),
    ( append(In0, [comma|Rest], Ws0) -> true ; In0 = Ws0, Rest = [] ),
    In0 \== [], In = [P, Pr|In0],
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, In, [pp(_, _)|_]), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... AND A PHRASE WITH NO ARTICLE THAT OPENS ON A FOCUS ADVERB, between
%% two commas after a noun or a name: `il boss della compagnia discografica
%% Paramount, anche produttore cinematografico, decise ...' is the boss,
%% also a film producer. With the adverb first no aside below opened on it:
%% `anche' went to the clause, and the phrase was the boss's adjectives --
%% `producing cinematographic hips', `anche' being the plural of `anca' too.
%% The adverb stays at the head of the aside (tr_aside_inner0/2)
tr_asides(foreign, [W, comma, F, A|Ws0], [W, w(K, aside)|Ws]) :-
    W = w(WW, _), atom(WW), F = w(FW, lower), atom(FW), A = w(AW, lower), atom(AW),
    tr_focus_adverb(FW), ( tr_is(foreign, W, noun) -> true ; tr_name_word(foreign, W) ),
    tr_is(foreign, A, noun),
    append(In, [comma|Rest], [A|Ws0]), \+ memberchk(comma, In), Rest = [w(_, _)|_],
    \+ ( member(X, In), atom(X) ),
    \+ ( member(X, In), X = w(_, _), tr_coord(foreign, X) ),
    tr_np(foreign, In, np(none, none, _, w(_, _), _)), !,
    tr_aside_key(K, [F|In]), tr_asides(foreign, Rest, Ws).
%% ... AND AN ADJECTIVE PHRASE BETWEEN TWO COMMAS AFTER THE PHRASE IT
%% DESCRIBES: `una versión estilizada, conservadora en el mejor sentido del
%% término, y permite ...', `el éxito, discreto pero al fin y al cabo éxito,
%% de esta Lucia'. Read as the clause's own complements, its adjective
%% agreed with the SUBJECT -- `il risultato è una versione stilizzata,
%% conservatore' -- where it is the version's. It opens on an adjective in
%% the gender and the number of the word before the comma, a noun or an
%% adjective of that phrase, and reads as complements that open on it; it
%% goes back after the phrase, between its commas.
tr_asides(foreign, [W, comma, A|Ws0], [W, w(K, aside)|Ws]) :-
    W = w(_, _), A = w(_, _),
    ( tr_is(foreign, W, noun) ; tr_is(foreign, W, adjective) ), tr_is(foreign, A, adjective),
    append(In, [comma|Rest0], [A|Ws0]), \+ memberchk(comma, In), Rest0 = [w(_, _)|_],
    \+ ( member(X, In), atom(X) ),
    tr_aside_agrees(W, A),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, In, [adj(_)|_]), !,
    %% ... AND A COORDINATOR, ADVERBS AND AN ADJECTIVE AFTER ITS COMMA SAY MORE
    %% OF THE SAME NOUN: `un governo stabile, rispettoso delle esigenze del
    %% mondo dell'imprenditoria, ma anche molto attento verso i soggetti ...'
    %% is the government, attentive too -- the aside's own, to its next comma
    %% or the end, and agreeing with the noun as the aside does. Read as the
    %% clause's, the adjective agreed with the subject, or with nobody:
    %% `una casa grande, stanca del pane, ma anche molto stanca' came out
    %% `pero también muy cansado'
    (   Rest0 = [C|R1], C = w(_, _), tr_coord(foreign, C), tr_adverbs_adjective(foreign, R1),
        ( append(Cont, [comma|Rest1], R1), \+ memberchk(comma, Cont) -> Rest = Rest1, Rest \== [] ; Cont = R1, Rest = [] ),
        \+ ( member(Y, Cont), atom(Y) ),
        once(( member(J, Cont), J = w(_, _), \+ tr_is(foreign, J, adverb), tr_is(foreign, J, adjective) )),
        tr_aside_agrees(W, J)
    ->  append(In, [comma, C|Cont], InW), tr_aside_key(K, InW),
        tr_asides(foreign, Rest, Ws)
    ;   tr_aside_key(K, In), tr_part_more_aside(Rest0, Ws)
    ).
%% ... AND A PHRASE WITH NO ARTICLE BETWEEN TWO COMMAS AFTER A NAME, which
%% says who the name is: `La candidatura de Solana, actual secretario
%% general de la OTAN, ha sido promovida ...', `a Carlos Westendorp, Alto
%% Representante Civil en Bosnia, explicó ...'. Read as the clause's own,
%% `actual' and `secretario' were adjectives of `Solana' -- a sunny slope,
%% to the vocabulary -- and with a name no lesson knows the sentence
%% divided at the comma and its participle agreed with the apposition. It
%% goes back after the name, between its commas -- and the comma that
%% closes it stays among the words, as the participle's above does:
%% `... a Carlos Westendorp, Alto Representante Civil en Bosnia, explicó
%% ayer el ministro' is divided there from the clause that reports it. Not
%% a run of names alone: `la ministra de Justicia, Janet Reno,' is a name
%% apposed to a phrase (tr_list_commas/3), and stays one.
%% ... AND ONE WITH AN ARTICLE, WHERE THE CLAUSE'S VERB FOLLOWS ITS CLOSING
%% COMMA: `Cesare Pietroiusti, il padre di Sofia, è un uomo alto' -- read as
%% a verbless piece and a clause, the man was the subject after `è' and
%% English said `a tall man is'. The verb after the comma is what says the
%% phrase belongs to the name before it and is no list's item -- and so does
%% the absence of a coordinator: `los Beatles, los hooligans y la oleada de
%% histeria ... de Lady Di, seguirá' is a list's last items and a verb, and
%% read as what the Beatles are it cost a third of a million inferences for
%% no text.
%% ... AND ONE WITH AN ARTICLE THAT ENDS ON A NAME, AFTER A NOUN OR AN ADJECTIVE:
%% `El presidente francés, el gaullista Jacques Chirac, lanzó ayer una seria
%% advertencia' -- the president is the Gaullist Jacques Chirac. After a word
%% in small letters the reader took the phrase before the first comma for a
%% heading and left the clause nobody named, which English refuses; the name
%% at the end of the phrase is what says it is the person the noun before it
%% names
tr_asides(foreign, [W, comma, A|Ws0], [W, w(K, aside), comma|Ws]) :-
    W = w(WW, WC), atom(WW), A = w(_, _),
    (   WC == upper
    ->  true
    ;   tr_determiner(foreign, A, _, article),
        once(( tr_is(foreign, W, noun) ; tr_is(foreign, W, adjective) ))
    ),
    (   tr_determiner(foreign, A, _, article)
    ->  append(In, [comma|Rest], [A|Ws0]), \+ memberchk(comma, In),
        ( WC == upper -> true ; last(In, w(_, upper)) ),
        Rest = [w(V, _)|_], atom(V), tr_verb_form_word(V),
        \+ ( member(X, In), X = w(_, _), tr_coord(foreign, X) )
    ;   \+ tr_determiner(foreign, A, _, _),
        %% (and it opens on a noun or an adjective, as `actual secretario' and
        %% `Alto Representante' do: after `Parlamento de Tbilisi, en una
        %% consulta que servirá ...' the whole clause up to the next comma was
        %% read as a phrase and refused, for 1.1 million inferences a sentence)
        once(( tr_is(foreign, A, noun) ; tr_is(foreign, A, adjective) )),
        append(In, [comma|Rest], [A|Ws0]), \+ memberchk(comma, In), Rest = [w(_, _)|_]
    ),
    \+ ( member(X, In), atom(X) ),
    \+ forall(member(X, In), tr_name_word(foreign, X)),
    %% (and not all in capitals: `Capri, Procida, Ischia, Giglio, Eolie e
    %% Ponza' -- `giglio' is a lily to the lesson, and `, Giglio,' was taken
    %% for what Ischia is, which broke the list and refused the sentence)
    \+ forall(member(X, In), X = w(_, upper)),
    once(( member(N, In), tr_is(foreign, N, noun) )),
    ( tr_apposition(In) -> true ; WC == upper, tr_roles_apposition(In) ), !,
    tr_aside_key(K, In), tr_more_asides(Rest, Ws).
%% ... AND ONE WITH AN ARTICLE AFTER ANY PHRASE, WHERE A RELATIVE CLAUSE
%% FOLLOWS ITS CLOSING COMMA: `partirà ... con il corso "missioni umane nello
%% spazio", il primo del genere in Europa, che sarà tenuto dall'astronauta
%% Roberto Vittori' -- the course, the first of its kind, which will be
%% held. Read as the clause's own, the first one was a second object of
%% `partirà', with the word before a person in front of it (`al primero'),
%% and the relative clause hung on `Europa'. The relative word after the
%% comma is what says the phrase says more of the one before it and is no
%% list's item; the comma stays, so the clause hangs on the phrase before it
%% as a relative clause after a comma does
tr_asides(foreign, [W, comma, A|Ws0], [W, w(K, aside), comma|Ws]) :-
    W = w(WW, _), atom(WW), A = w(_, _), tr_determiner(foreign, A, _, article),
    ( tr_is(foreign, W, noun) -> true ; tr_name_word(foreign, W) ),
    %% (and no adverb, which is a noun in the lesson too: `Pujol vio, ayer, el
    %% pan, que duerme' set `el pan' off as what `ayer' is -- the yesterday, the
    %% bread -- and the sentence was refused)
    \+ tr_is(foreign, W, adverb),
    append(In, [comma|Rest], [A|Ws0]), \+ memberchk(comma, In),
    tr_relative_start(foreign, Rest),
    \+ ( member(X, In), atom(X) ),
    \+ ( member(X, In), X = w(_, _), tr_coord(foreign, X) ),
    %% (and it holds no relative word of its own, asked before it is read as
    %% a phrase: Livata's `fa sapere, in una nota, la Regione Lazio spiegando
    %% che "si sono adoperate 37 associazioni di protezione civile, di cui
    %% tre ...' offered the Region with its gerund and its clause, and reading
    %% that as a phrase to be refused cost a third of a million inferences)
    \+ ( member(w(X, _), In), atom(X), tr_relative_word(foreign, X) ),
    tr_apposition(In), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).

%% ... AND AN ADVERB BEFORE THE PARTICIPLE: `Jaume Barberà, recientemente
%% fichado por TVE,' -- recently signed by it. The two clauses below open on
%% the participle, so the aside was read as the clause's own words, the
%% adverb went to the end and the agent was a phrase of `for', `ingaggiato
%% per TVE'. It goes back between its commas, the adverb before the
%% participle (padv/1, as a reduced relative's).
%% -- and at the end of the sentence, where the stop closes it: `... dirigía
%% Jaume Barberà, recientemente fichado por TVE.'
tr_asides(foreign, [W, comma, A, w(P, PC)|Ws0], [W, w(K, aside)|Out]) :-
    W = w(_, _), A = w(_, _), ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ),
    tr_plain_adverb(foreign, A), tr_participle_here(foreign, P, _),
    (   append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_], Out = [comma|Ws]
    ;   \+ memberchk(comma, Ws0), In0 = Ws0, Rest = [], Out = Ws
    ),
    \+ ( member(X, In0), atom(X) ),
    ( In0 == [] -> true ; tr_reduced_agent(foreign, In0, _) -> true ; tr_participle_adjuncts(In0, _) ), !,
    tr_aside_key(K, [A, w(P, PC)|In0]), tr_asides(foreign, Rest, Ws).
%% ... AND A PARTICIPLE WITH ITS AGENT BETWEEN TWO COMMAS AFTER A NAME OR A
%% NOUN: `la descripción visual de lord Arturo Bucklaw, interpretado por
%% Carlos Cosías, se permite Vick ...' -- the character, played by the
%% singer. The phrase it says it of is inside another (`la descripción ...
%% de lord ...'), where the complement reader's aside (tr_phrase_aside/4)
%% cannot reach, and read as the clause's own the sentence had no reading.
%% It goes back after that phrase between its commas, agreeing with it --
%% and the comma that closes it stays among the words, because it closes
%% the sentence's front as well: without it `Sólo en la descripción ...' was
%% written after the verb (the writer drops a comma after another)
%% -- after an adjective too, and with an aside of its own inside it: `La
%% cadena catalana, capitaneada por el empresario gerundense Bartomeu
%% Espadalé - - próximo a Convergència - - y Puigbó, consiguió ...' is the
%% network, captained by the two. After `catalana' the clause stood down,
%% and with the dashes still in its words it stood down again; read as the
%% subject's own reduced relative, both commas were lost. The words inside
%% have their asides read first.
tr_asides(foreign, [W, comma, w(P, PC)|Ws0], [W, w(K, aside), comma|Ws]) :-
    W = w(_, _),
    (   ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ) -> After = noun
    ;   tr_is(foreign, W, adjective) -> After = adjective
    ),
    tr_participle_here(foreign, P, _), \+ tr_is(foreign, w(P, lower), noun), \+ tr_is(foreign, w(P, lower), adjective),
    append(In0r, [comma|Rest], Ws0), \+ memberchk(comma, In0r), Rest = [w(_, _)|_],
    ( memberchk(dash, In0r) -> tr_asides(foreign, In0r, In0) ; In0 = In0r ),
    \+ ( member(X, In0), atom(X) ),
    %% (after an adjective only with its agent: a participle alone there is
    %% one more of a list -- `un parco "blindato", "mummificato", dove ...'
    %% -- and set off as an aside it lost its quotation marks)
    ( In0 == [] -> After == noun ; tr_reduced_agent(foreign, In0, _) ), !,
    tr_aside_key(K, [w(P, PC)|In0]), tr_asides(foreign, Rest, Ws).
%% ... AND A PARTICIPLE WITH ADJUNCTS OF ITS OWN: `El nombramiento del
%% primer responsable de la política exterior y de seguridad, conocido en
%% el argot comunitario como Mister PESC, está previsto que ...' -- known,
%% in the jargon, as Mister CFSP. `conocido' is an adjective and a noun as
%% well, which the clause above leaves alone, and read as the sentence's
%% own the commas were lost and the participle agreed with nothing. It
%% opens on a preposition after the participle, which an adjective phrase
%% of the kind above does not, and it goes back between its commas, the
%% closing one kept as the participle's above is.
tr_asides(foreign, [W, comma, w(P, PC)|Ws0], [W, w(K, aside), comma|Ws]) :-
    W = w(_, _), ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ),
    tr_participle_here(foreign, P, _),
    append(In0, [comma|Rest], Ws0), In0 = [Pr|_], \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ), tr_is(foreign, Pr, preposition),
    tr_participle_adjuncts(In0, _), !,
    tr_aside_key(K, [w(P, PC)|In0]), tr_asides(foreign, Rest, Ws).
%% ... AND A PARTICIPLE WITH THE ADJECTIVE IT MAKES OF ITS NOUN: `Via
%% Krupp, resa più agibile dopo il restauro, è frequentata come mai' -- the
%% street made more accessible after the restoration. The two clauses above
%% take a participle with its agent or with adjuncts, and read as the
%% sentence's own the street was set apart from its verb, whose subject was
%% then nobody, and English refused it. The words after the participle open
%% on an adjective or its degree, and read as complements they are the
%% adjective first and adjuncts after it. The participle may be a noun as
%% well (`la resa', a surrender): an adjective straight after it, with no
%% article before it, says it is the participle. It goes back between its
%% commas, the closing one kept
tr_asides(foreign, [W, comma, w(P, PC)|Ws0], [W, w(K, aside), comma|Ws]) :-
    W = w(_, _), ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ),
    tr_participle_here(foreign, P, _), \+ tr_is(foreign, w(P, lower), adjective),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    In0 = [A0|_], A0 = w(AW, _), ( atom(AW), tr_degree_word(AW) ; tr_is(foreign, A0, adjective) ),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, In0, [adj(_)|CR]), forall(member(X, CR), tr_adjunct(X)), !,
    tr_aside_key(K, [w(P, PC)|In0]), tr_asides(foreign, Rest, Ws).
%% ... AND A PARTICIPLE WITH ITS DEGREE: `Países como Alemania o Estados
%% Unidos, más modernizados desde todos los puntos de vista, han tardado más
%% que nosotros' -- more modernised from every point of view. `más' is no
%% participle, so the two clauses above let the commas go, and read as the
%% sentence's own the words before the verb were a clause with no verb of
%% their own and the verb's subject nobody. It goes back where it stood, the
%% lesson's word for `more' before the participle (part/2 with pdeg/1), and
%% after a word the lesson calls an adjective as well: `Estados Unidos'.
tr_asides(foreign, [W, comma, w(M, MC), w(P, PC)|Ws0], [W, w(K, aside), comma|Ws]) :-
    W = w(_, _), tr_degree_word(M),
    ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ; tr_is(foreign, W, adjective) ),
    tr_participle_here(foreign, P, _), \+ tr_is(foreign, w(P, lower), noun), \+ tr_is(foreign, w(P, lower), adjective),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    (   In0 == [] -> true
    ;   In0 = [Pr|_], tr_is(foreign, Pr, preposition),
        ( tr_reduced_agent(foreign, In0, _) -> true ; tr_participle_adjuncts(In0, _) )
    ), !,
    tr_aside_key(K, [w(M, MC), w(P, PC)|In0]), tr_asides(foreign, Rest, Ws).
%% ... AND A PHRASE BETWEEN TWO COMMAS THAT OPENS ON A WORD THAT REPLACES
%% THE NOUN, after a noun or a pronoun: `di cui solo uno, QUELLO GUIDATO DAL
%% MAGNATE TELEVISIVO SILVIO BERLUSCONI, uscito da elezioni generali' -- the
%% one it is, said again. Read as the clause's own, `quello' was the pronoun
%% `that' and the participle a predicate of nobody. It goes back after the
%% phrase between its commas.
tr_asides(foreign, [W, comma, Q|Ws0], [W, w(K, aside)|Ws]) :-
    W = w(_, _), Q = w(_, _), tr_noun_replacer(foreign, Q),
    ( tr_is(foreign, W, noun) ; tr_is(foreign, W, pronoun) ; tr_name_word(foreign, W) ),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    tr_np(foreign, [Q|In0], _), !,
    tr_aside_key(K, [Q|In0]), tr_asides(foreign, Rest, Ws).
%% ... AND WHO SAID SO, BETWEEN TWO COMMAS: `En él, según manifestó Redondo
%% Terreros a Europa Press, no se abordó el plan de paz' -- as Redondo
%% Terreros told Europa Press. `según' before a reporting clause is the
%% comment tr_read0/4 reads at the end of a sentence (1.8.9); inside one it
%% divided the sentence at its commas and nothing read. It stands where it
%% stood, w(Key, per), and the comma that closes it is kept for whatever it
%% closes -- the front, here -- and every writer puts the comment back with
%% its word for `as'. At the head of a sentence (tr_head_per/3) it has no
%% comma before it, w(Key, perh).
tr_asides(foreign, [W, comma, w(C, CC)|Ws0], Out) :-
    W = w(_, _), tr_per_comment(C, Ws0, In0, Rest), !,
    tr_aside_key(K, [w(C, CC)|In0]),
    (   Rest == [] -> Out = [W, w(K, per)]                       % (the relative clause it took in ends the piece)
    ;   tr_asides(foreign, Rest, Ws), Out = [W, w(K, per), comma|Ws]
    ).
%% ... AND THE WRITER'S OWN COMMENT BETWEEN TWO COMMAS, a clause whose verb
%% is in the first person singular: `Quest'Uomo ... ha osato, sottolineo
%% "osato", dire che ...' -- I stress the word. Read as the sentence's own
%% clauses, the comment divided it, `ha osato' a clause of its own and
%% `dire che ...' what I stress. It stands where it stood, w(Key, comment),
%% and every writer puts it back there between its commas.
%% A VERB FORM AND NOTHING ELSE, after a word that opens no clause: Spanish's
%% `como' is I eat and `like', and `Al margen de que, como todos, han comido
%% pan' is an insertion after its connector (tr_read0/4), which the comment
%% took and refused the sentence.
%% -- AND SHORT, three words at most: `Sono una piccola imprenditrice di 29
%% anni, pacifista convinta, odio anche solo l'idea della guerra, della
%% violenza e della distruzione ...' is the sentence's own second clause, I
%% hate even the idea of war, and read as a comment it closed at the list's
%% comma and refused the letter's third sentence
%% (never the copula: `in un certo senso sono troppi, sono d'accordo, ma
%% non pensate ...' says what the speaker is, a clause of the sentence's
%% own, and taken for a comment it left `sono troppi' and `ma non pensate'
%% with no comma between them and the sentence was refused)
%% ... AFTER A PHRASE it is the phrase's aside, as an age is, and not a
%% complement of a verb that has not come: `Questo, devo dire, gli piaceva'
%% -- the pronoun, then what I must say, then the clause. A comment is read
%% where a verb's complements are, and with the verb after it the sentence
%% was refused with every word known.
tr_asides(foreign, [W, comma, w(V, VC)|Ws0], [W, w(K, Kind)|Ws]) :-
    W = w(_, _), \+ tr_opens_clause(W), tr_form(V, L, singular, _, first), atom(L),
    ( tr_class_of(L, verb) ; tr_class_of(L, modal) ), \+ tr_copula_group(L),
    \+ ( member(Cl, [preposition, conjunction, adverb]), tr_is(foreign, w(V, lower), Cl) ),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    length(In0, NIn), NIn =< 2,
    \+ ( member(X, In0), atom(X) ),
    In = [w(V, VC)|In0], tr_aside_reads(foreign, In), !,
    ( tr_comment_after_phrase(W, Rest) -> Kind = aside ; Kind = comment ),
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... AND A CLAUSE THAT OPENS ON A COORDINATOR AND ITS VERB, set between
%% two commas inside a clause: `Ci sono, invece, ed è un problema grave e che
%% mi tormenta, enormi differenze economiche' -- there are, and it is a
%% serious problem, enormous differences. The clause says something of the
%% sentence it interrupts and belongs to none of its phrases, and read as the
%% sentence's own clauses it left `enormi differenze economiche' with no verb
%% at all. It is the writer's comment in another shape, w(Key, comment), and
%% goes back where it stood between its commas. Only where what follows it,
%% up to the next comma, has no verb of its own: `Il cane mangia, e dorme, e
%% poi corre' is three clauses joined.
tr_asides(foreign, [W, comma, w(C, CC)|Ws0], [W, w(K, comment)|Ws]) :-
    W = w(_, _), tr_coord(foreign, w(C, CC)),
    Ws0 = [w(V, _)|_], atom(V), tr_verb_form_word(V),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(R1, _)|_],
    \+ tr_connector(foreign, R1),
    ( append(RestC, [comma|_], Rest) -> true ; RestC = Rest ),
    \+ ( member(w(X, _), RestC), atom(X), tr_verb_form_word(X) ),
    \+ ( member(X, In0), atom(X) ),
    \+ tr_copula_and_pronoun(In0),
    In = [w(C, CC)|In0], tr_aside_reads(foreign, In), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... AND WHO SAID SO BETWEEN TWO DASHES: `Era che - come ha mostrato bene la
%% trasmissione di Angela - i suoi avversari avevano fatto calcoli più
%% precisi dei suoi' -- as Angela's programme has shown well. The comment of
%% who said so (w(Key, per)) set off by dashes, w(Key, perd); every writer
%% puts it back where it stood, with its word for `as', between its dashes.
%% (before the clause below, which took `come' for the question word `how')
tr_asides(foreign, [W, dash, w(C, CC)|Ws0], [W, w(K, perd)|Ws]) :-
    W = w(_, _), atom(C), tr_per_comment_dashed(C, Ws0, In0, Rest), !,
    tr_aside_key(K, [w(C, CC)|In0]), tr_asides(foreign, Rest, Ws).
%% ... and a clause between two DASHES that opens on a relative or a
%% question word: `E il Giglio - dove l'afflusso dei veicoli ... è vietato
%% dal 24 luglio al 25 agosto - ritorna alla dimensione dell'oasi'. It is
%% the island's, where the traffic is banned, and read as the sentence's
%% own clauses it was nothing; it goes back after the phrase between its
%% dashes, w(Key, dashed).
%% ... AND THE CLOSING DASH MAY END THE SENTENCE: `las antiguas galerías
%% comerciales de Sogo - - que ahora albergan la sede del Casino de Barcelona
%% - -.' -- read with the dash for the join of two clauses (tr_read0/4), the
%% relative clause was a clause of its own with `sede' for its verb, `che
%% albergano adesso la calma del Casino'
%% A NOUN OR A NAME, ONE DASH AND A NOUN ARE ONE PHRASE: `Eco è un intellettuale - puzzle: nessuna tessera, da sola,
%% lo definisce' is an intellectual-puzzle, and `alcune tessere dell'Eco - puzzle' the cards of the Eco-puzzle -- the
%% paper's coinage. Read as the dash that joins two pieces, the second was a noun alone, and the sentence was cut in
%% two or refused. The piece's one dash, a bare noun after it and nothing after that but the piece's end, a comma, a
%% colon or a verb (never an adjective, which makes the noun a headline's: `Calcio - dichiarazioni varie del
%% giocatore'); it goes on after the phrase it is said of with its one dash, w(Key, dash1)
tr_asides(foreign, [W, dash, A|Ws0], [W, w(K, dash1)|Ws]) :-
    W = w(_, _), ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ),
    A = w(AW, lower), atom(AW), \+ tr_determiner(foreign, A, _, _), tr_is(foreign, A, noun),
    \+ memberchk(dash, Ws0),
    ( Ws0 == [] ; Ws0 = [X|_], memberchk(X, [colon, comma])
    ; Ws0 = [w(V, _)|_], atom(V), tr_verb_form_word(V), \+ tr_is(foreign, w(V, lower), adjective) ),
    tr_apposition([A]), !,
    tr_aside_key(K, [A]), tr_asides(foreign, Ws0, Ws).
tr_asides(Side, [W, dash, w(R, RC)|Ws0], [W, w(K, dashed)|Ws]) :-
    W = w(_, _), ( tr_relative_word(Side, R) ; tr_indirect_word(Side, R, _) ),
    append(In0, [dash|Rest], Ws0), \+ memberchk(dash, In0), !,
    tr_aside_key(K, [w(R, RC)|In0]), tr_asides(Side, Rest, Ws).
%% ... AND AN ADJECTIVE PHRASE BETWEEN TWO DASHES AFTER A NAME OR A NOUN:
%% `el empresario gerundense Bartomeu Espadalé - - próximo a Convergència -
%% - y Puigbó' -- close to the party. The clause below wants a clause, and
%% an adjective with its phrase is none, so the sentence was refused with
%% every word known. It goes back between its dashes, w(Key, dashed), after
%% the phrase it says something of.
tr_asides(foreign, [W, dash, A|Ws0], [W, w(K, dashed)|Ws]) :-
    W = w(_, _), ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ),
    A = w(_, _), tr_is(foreign, A, adjective),
    append(In0, [dash|Rest], Ws0), \+ memberchk(dash, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    In = [A|In0],
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, In, [adj(_)|Cs]), Cs \== [], forall(member(C, Cs), tr_adjunct(C)),
    %% (never a verb with the place it was said at: `i primi dati -
    %% precisano al Ministero -' is who says so, and `precisano' is the
    %% adjective `precisa' only by the form it shares with the verb)
    \+ tr_read_reporting(foreign, In, _), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... AND A PARTICIPLE OR AN ADJECTIVE ALONE BETWEEN TWO DASHES: `destacó que la Guardia Urbana - -
%% desbordada - - solicitó en vano la presencia de la policía' -- the Urban Guard, overwhelmed, asked in
%% vain. The clause above wants the adjective's phrase, and the one word between the dashes had no
%% reading, so the sentence was refused with every word known
%% (never a verb's own form: `Gallo - continua - mi ha lasciato' is who says so, and `continua' an adjective only by the
%% form it shares with the verb -- tr_read_reporting/3's)
tr_asides(foreign, [W, dash, A, dash|Rest], [W, w(K, dashed)|Ws]) :-
    W = w(_, _), tr_dash_phrase_end(W),
    A = w(AW, _), atom(AW), \+ tr_determiner(foreign, A, _, _),
    ( tr_participle_here(foreign, AW, _) ; tr_is(foreign, A, adjective) ),
    \+ tr_form(AW, _, _, _, _),
    Rest = [w(_, _)|_], !,
    tr_aside_key(K, [A]), tr_asides(foreign, Rest, Ws).
%% ... AND ONE A DASH OPENS AND A COMMA CLOSES, where the sentence has no other dash: `c'è da
%% giurare che Capri - off limits per i "motorizzati" dal 10 marzo al 31 ottobre, non subirà alcun
%% calo' -- the paper's comma stands for the closing dash. Inside the clause of `che' the words had
%% no reading, and on its own the dash was the join of a heading and a clause whose subject was the
%% off-limits one. It goes back between its dashes, w(Key, dashed), as the one with two does
tr_asides(foreign, [W, dash, A|Ws0], [W, w(K, dashed)|Ws]) :-
    W = w(_, _), ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ),
    A = w(_, _), tr_is(foreign, A, adjective),
    \+ memberchk(dash, Ws0),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    In = [A|In0],
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, In, [adj(_)|Cs]), Cs \== [], forall(member(C, Cs), tr_adjunct(C)),
    \+ tr_read_reporting(foreign, In, _), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... AND A PHRASE WITH NO ARTICLE BETWEEN TWO DASHES, after a name or a
%% noun, which says what it is: `la empresa R-C Spain SL - - filial de la
%% cadena hotelera internacional Ritz-Carlton - - hasta el 2019' -- the
%% chain's subsidiary. `filial' is an adjective too, and the clause above
%% wants one with an adjective's complements; between commas the same words
%% were an apposition (tr_apposition/1), between dashes they were nothing
%% and the sentence was refused with every word known. It goes back between
%% its dashes, w(Key, dashed), after the phrase it says something of.
%% (A COMMA RIGHT AFTER THE CLOSING DASH IS NOT LET THROUGH: `el fondo - -
%% Strategic - -, aliado con un consorcio, duerme' with it read the fund
%% and the participle phrase as a piece with no verb, and `duerme' as the
%% imperative that follows it -- `dormi' -- where the sentence was refused)
%% ... AND AFTER AN ADVERB WHERE THE CLOSING DASH ENDS THE SENTENCE: `de forma que
%% se abran las oficinas por las tardes - - iniciativa que consiguió pactar con la
%% dirección - -' -- the initiative is what the clause says, and `por las tardes' is
%% one adverb, so no phrase stood before the dashes for the aside to say it of. It
%% stays where it stood, at the end (dsh/1)
tr_asides(foreign, [W, dash, A|Ws0], [W, w(K, dashed)|Ws]) :-
    W = w(_, _), ( tr_name_word(foreign, W) ; tr_is(foreign, W, noun) ; tr_is(foreign, W, adverb), last(Ws0, dash) ),
    A = w(AW, _), atom(AW), \+ tr_determiner(foreign, A, _, _),
    ( tr_is(foreign, A, noun) ; tr_name_word(foreign, A) ),
    append(In0r, [dash|Rest], Ws0), \+ memberchk(dash, In0r),
    ( Rest == [] ; Rest = [w(_, _)|_] ),
    tr_asides(foreign, In0r, In0),                           % (a bracket inside it: `Strategic Hotel Capital (SHC)')
    \+ ( member(X, In0), atom(X) ),
    In = [A|In0],
    tr_apposition(In), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... AND ADJUNCTS BETWEEN TWO DASHES: `può essere peggiore la qualità dei
%% servizi - almeno in alcuni campi - ma non quella degli insegnanti' -- at
%% least in some fields. An adverb or a phrase of a preposition's and no
%% verb, so no clause, and read as the sentence's own complements the dashes
%% were nothing and the sentence was refused. It goes back between its
%% dashes, w(Key, dashed), after the phrase it says something of (app/3).
%% ... AFTER A WORD THAT ENDS NO PHRASE they are commas, and read as the
%% adjuncts of the clause they stand in, as a pair of commas has always been:
%% `Mi piaceva, ma - di nuovo - non potevo dirglielo' -- the dashes after a
%% coordinator, a pronoun or a verb were an aside no phrase could take (app/3
%% is the phrase's), and the sentence was refused with every word known. The
%% writers put commas where the dashes stood.
tr_asides(foreign, [W, dash, A|Ws0], [W, comma|Ws]) :-
    W = w(_, _), A = w(_, _), ( tr_plain_adverb(foreign, A) ; tr_is(foreign, A, preposition) ),
    \+ tr_dash_phrase_end(W),
    append(In0, [dash|Rest], Ws0), \+ memberchk(dash, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    \+ ( member(w(V, _), In0), atom(V), tr_verb_form_word(V) ),
    In = [A|In0],
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_joined_words(foreign, In, InJ),
    tr_complements(foreign, InJ, Cs), Cs \== [], forall(member(C, Cs), tr_adjunct(C)), !,
    append(In, [comma|Rest1], Ws1), tr_asides(foreign, Rest, Rest1), Ws = Ws1.
%% ... AND A COORDINATOR AND A PHRASE OF A PREPOSITION BETWEEN TWO DASHES, in
%% the middle of a phrase: `dall'avventura - e dallo spettacolare naufragio -
%% della "voce"' -- from the adventure and from the shipwreck of the voice.
%% The words are the phrase's second half, and the `di' phrase after them is
%% both halves'; as an aside (app/3) they must stand at the end of the phrase,
%% and as two commas they read, as `dall'avventura, e dal naufragio, della
%% voce' always has
tr_asides(foreign, [W, dash, C|Ws0], [W, comma|Ws]) :-
    W = w(_, _), C = w(_, _), tr_coord(foreign, C),
    append(In0, [dash|Rest], Ws0), In0 = [_|_], \+ memberchk(dash, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    \+ ( member(w(V, _), In0), atom(V), tr_verb_form_word(V) ),
    In = [C|In0], tr_joined_words(foreign, In, InJ), InJ = [_, P1|_], P1 = w(_, _), tr_is(foreign, P1, preposition),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, InJ, Cs), Cs \== [], forall(member(C1, Cs), tr_adjunct(C1)), !,
    append(In, [comma|Rest1], Ws1), tr_asides(foreign, Rest, Rest1), Ws = Ws1.
%% ... AND A PHRASE OF A PREPOSITION BETWEEN TWO DASHES BEFORE A COORDINATOR,
%% in the middle of a pair: `para la circulación - - en las circunstancias en
%% que esté permitida - - y la carga y descarga' -- the aside stands between
%% the first half of the pair and its `y', and as an aside after the phrase
%% (app/3) the pair's split had no first half to take. As two commas it
%% reads, as the same words with commas always have; the verb is its
%% relative clause's, which the check on the words of the clause above would
%% have taken for a clause of its own
tr_asides(foreign, [W, dash, A|Ws0], [W, comma|Ws]) :-
    W = w(_, _), A = w(_, _), tr_is(foreign, A, preposition),
    append(In0, [dash|Rest], Ws0), \+ memberchk(dash, In0), Rest = [C|_], C = w(_, _), tr_coord(foreign, C),
    \+ ( member(X, In0), atom(X) ),
    In = [A|In0],
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_joined_words(foreign, In, InJ),
    tr_complements(foreign, InJ, Cs), Cs \== [], forall(member(C1, Cs), tr_adjunct(C1)), !,
    append(In, [comma|Rest1], Ws1), tr_asides(foreign, Rest, Rest1), Ws = Ws1.
tr_asides(foreign, [W, dash, A|Ws0], [W, w(K, dashed)|Ws]) :-
    W = w(_, _), A = w(_, _), ( tr_plain_adverb(foreign, A) ; tr_is(foreign, A, preposition) ),
    append(In0, [dash|Rest], Ws0), \+ memberchk(dash, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    \+ ( member(w(V, _), In0), atom(V), tr_verb_form_word(V) ),
    In = [A|In0],
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, In, Cs), Cs \== [], forall(member(C, Cs), tr_adjunct(C)), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... AND A WHOLE CLAUSE BETWEEN TWO DASHES, after a phrase and before the
%% rest of its sentence: `Un roble devastado y una inmensa luna - - el
%% personaje principal, Lucia, es el arquetipo de la locura operística - -
%% son dos de los elementos capitales ...'. It says something of the moon
%% and of nothing else in the sentence, and read as the sentence's own
%% clauses it was refused with every word known. It stands where it stood,
%% between its dashes -- but only a clause that reads as one, and never
%% one that reads as a REPORTING clause, `Sarò per sempre grato – aggiunge
%% Marchionne – al team', which the reader takes on its own and writes
%% after the sentence.
tr_asides(Side, [W, dash|Ws0], [W, w(K, dashed)|Ws]) :-
    W = w(_, _), Ws0 = [w(_, _)|_],
    %% (a comma may follow the closing dash: `"no - mi ha risposto -, a me
    %% piace ...', the answer, who gave it, and the rest)
    append(In0, [dash|Rest], Ws0), \+ memberchk(dash, In0), ( Rest = [w(_, _)|_] ; Rest = [comma, w(_, _)|_] ),
    In0 = [_, _|_], \+ memberchk(dash, Rest),
    tr_clause_words(In0, In1), tr_list_commas(Side, In1, In),     % `principal, Lucia,' is an apposition
    \+ tr_read_reporting(Side, In, _),
    tr_aside_reads(Side, In), !,
    tr_aside_key(K, In), tr_asides(Side, Rest, Ws).
tr_asides(Side, [W|Ws0], [W|Ws]) :- tr_asides(Side, Ws0, Ws).
%% ... AND A PARTICIPLE WITH ITS AGENT AFTER IT: `Si la FIFA, convaleciente
%% de una cruenta batalla interna, salpicada por la plaga de la corrupción,
%% hubiera buscado un escenario mejor no lo habría encontrado' -- tainted by
%% the plague, besides what it is convalescent of. The clause above takes
%% the comma that closes the adjective's aside, so the participle stood
%% after no comma the participle's own clause could see, and read as the
%% subject's reduced relative the comma that closes it was lost. It is a
%% second aside on the adjective's terms, its closing comma taken as well:
%% the writer puts both back around every aside
tr_part_more_aside([w(P, PC)|Ws0], [w(K, aside)|Ws]) :-
    atom(P), tr_participle_here(foreign, P, _),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    tr_reduced_agent(foreign, In0, _), !,
    tr_aside_key(K, [w(P, PC)|In0]), tr_asides(foreign, Rest, Ws).
tr_part_more_aside(Rest, Ws) :- tr_asides(foreign, Rest, Ws).
%% ... AND A SECOND ONE AFTER IT: `Josep Puigbó, editor del Telenotícies
%% migdia de TV-3, noticiario que copresenta con Montse Jené, está
%% negociando ...' -- the programme he edits, and what that programme is.
%% The clause above takes the comma that closes the first, so the second
%% stood after no comma the reader could see, and the sentence was refused
%% with every word known. It is one more aside on the same terms -- a noun
%% of the lesson's that is no verb's form first, a phrase to the next
%% comma -- and its closing comma is kept as the first one's is.
tr_more_asides([A|Ws0], [w(K, aside), comma|Ws]) :-
    A = w(_, lower), \+ tr_determiner(foreign, A, _, _),
    tr_is(foreign, A, noun), A = w(AW, _), \+ tr_verb_form_word(AW),
    append(In, [comma|Rest], [A|Ws0]), \+ memberchk(comma, In), Rest = [w(_, _)|_],
    \+ ( member(X, In), atom(X) ),
    tr_apposition(In), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... OR A COUNT: `Giorgio Salvini, responsabile del Ministero Per
%% l'Università E la Ricerca Scientifica, 75 anni ben portati, ha l'aria' --
%% his age, after what he is, as `una donna, 36 anni,' has one after the
%% noun. Its opening comma was the first aside's closing one, so read as the
%% clause's own, the years were an adjunct and the clause had nobody named
tr_more_asides([w(N, NC)|Ws0], [w(K, aside), comma|Ws]) :-
    atom(N), tr_digits(N),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    In = [w(N, NC)|In0], length(In, L), L =< 4, \+ ( member(X, In), atom(X) ),
    tr_np(foreign, In, _), !,
    tr_aside_key(K, In), tr_asides(foreign, Rest, Ws).
%% ... OR A PARTICIPLE WITH ITS AGENT, as after an adjective's aside
%% (tr_part_more_aside/2): `Si la FIFA, convaleciente de una cruenta batalla
%% interna, salpicada por la plaga de la corrupción, hubiera buscado ...'
tr_more_asides([w(P, PC)|Ws0], [w(K, aside), comma|Ws]) :-
    atom(P), tr_participle_here(foreign, P, _),
    append(In0, [comma|Rest], Ws0), \+ memberchk(comma, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    tr_reduced_agent(foreign, In0, _), !,
    tr_aside_key(K, [w(P, PC)|In0]), tr_asides(foreign, Rest, Ws).
tr_more_asides(Rest, Ws) :- tr_asides(foreign, Rest, Ws).
%% (a count and its noun to the end, after the post that follows an age: tr_asides/3)
tr_count_tail([w(C, CC)|Ws0], [w(K, aside)]) :-
    atom(C), ( tr_digits(C) -> true ; tr_is(foreign, w(C, lower), number) ),
    \+ memberchk(comma, Ws0), \+ ( member(X, Ws0), atom(X) ), Ws0 = [_|_],
    tr_np(foreign, [w(C, CC)|Ws0], _), !,
    tr_aside_key(K, [w(C, CC)|Ws0]).
tr_count_tail(Ws0, Ws) :- tr_asides(foreign, Ws0, Ws).
%% (nor a verb of several words that begins with the copula: `sono d'accordo'
%% is `"è d'accordo" means "is in agreement"', and says what the speaker is as
%% `sono felice' does -- `in un certo senso sono troppi, sono d'accordo, ma non
%% pensate ...' was refused again once the lesson stated that verb)
tr_copula_group(L) :- tr_copula_lexeme(L), !.
tr_copula_group(L) :- atomic_list_concat([F, _|_], ' ', L), tr_copula_lexeme(F), !.
%% a phrase's end with a verb group after it: a pronoun or a noun, and then
%% the clitics and the verb
tr_comment_after_phrase(W, Rest) :-
    ( tr_is(foreign, W, pronoun) ; tr_is(foreign, W, noun) ; tr_name_word(foreign, W) ),
    \+ tr_is(foreign, W, verb),
    tr_gap_verb_next(foreign, Rest).
%% (not the copula and a subject pronoun alone: `Caetano Veloso è tornato per la terza volta a Umbria Jazz, ed è lui,
%% senza dubbio, il trionfatore incontrastato del festival' says who the victor is, the phrase after the aside is the
%% copula's own, and read as a comment the clause had no predicate and nobody named, which English refused)
tr_copula_and_pronoun([w(V, _), w(P, _)]) :-
    atom(V), atom(P), tr_form(V, L, _, _, _), atom(L), tr_copula_lexeme(L), tr_subject_pronoun(foreign, P, _, _), !.
%% a word a phrase can end on, which an aside after it hangs on
tr_dash_phrase_end(W) :- ( tr_is(foreign, W, noun) ; tr_name_word(foreign, W) ; tr_is(foreign, W, adjective) ), !.

%% the adjuncts after a participle: complements with no object in them,
%% read with no verb group around them
tr_participle_adjuncts(Ws, Cs) :-
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    (   tr_complements(foreign, Ws, Cs0), \+ memberchk(obj(_), Cs0)
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), Cs = Cs0
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).

%% ... AND TWO THINGS A PERSON IS, JOINED, AFTER THE NAME: `Secondo Enrico Finzi, sociologo e presidente della società
%% Astra, è così' -- according to him, a sociologist and president, it is so. Read as the clause's own, the two were its
%% subject and the copula plural, `son así'. Two phrases with no determiner, joined by the word for `and'
tr_roles_apposition(In) :-
    tr_subject(foreign, none, In, third, plural, co(_, A, B)),
    tr_role_np(A), tr_role_np(B), !.
tr_role_np(np(none, none, _, w(_, _), singular)) :- !.
tr_role_np(with(NP, _)) :- tr_role_np(NP).
%% a phrase, or a phrase and the prepositional phrases after it
tr_apposition(In) :- tr_np(foreign, In, _), !.
tr_apposition(In) :- tr_subject(foreign, none, In, third, singular, with(_, _)), !.

%% two words in one gender and one number: a word with no gender of its own
%% agrees with either
tr_aside_agrees(w(W, _), w(A, _)) :-
    tr_lexeme(foreign, W, WL, N), tr_lexeme(foreign, A, AL, N),
    tr_gender(WL, GW), tr_gender(AL, GA),
    ( GW == none ; GA == none ; GW == GA ), !.

%% a decade's number, as digits: ten to ninety
tr_decade(N) :- atom(N), atom_length(N, 2), atom_number(N, V), integer(V), V >= 10, V =< 90, 0 =:= V mod 10.
%% a year, as digits: four of them, from 1100 to 2100
tr_year(Y) :- atom(Y), atom_length(Y, 4), atom_number(Y, N), integer(N), N >= 1100, N =< 2100.
%% the English names of the days, as the IR carries them
tr_weekday(D) :- memberchk(D, [monday, tuesday, wednesday, thursday, friday, saturday, sunday,
                               'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']).

tr_aside_key(K, Words) :-
    catch(nb_getval('$tr_aside_n', N0), _, N0 = 0), N is N0 + 1, nb_setval('$tr_aside_n', N),
    atom_concat('$aside', N, K), nb_setval(K, Words).

%% the comment of who said so: a word meaning `as' or `according to', a
%% reporting clause that names its speaker, and a comma after it
tr_per_comment(C, Ws0, In0, Rest) :-
    once(( tr_solve(mean(C, 'according to')) ; tr_solve(mean(C, as)) )),
    append(In1, [comma|Rest1], Ws0), In1 = [_|_], \+ memberchk(comma, In1), Rest1 = [w(_, _)|_],
    \+ ( member(X, In1), atom(X) ),
    tr_per_read(In1, S), S = s(_, Sub, _, _), Sub \= null(_, _), !,
    %% ... AND THE RELATIVE CLAUSE AFTER ITS COMMA IS THE SPEAKER'S: `según
    %% informó ayer la agencia Efe, que cita fuentes del sector' -- the agency
    %% cites them. Outside the comment it was a clause of `that' with nobody
    %% named, which English refuses (`quotes ...' with no subject), so the
    %% comment takes it in, up to the next comma or the end of the piece, where
    %% the comment still reads with it
    (   tr_relative_start(foreign, Rest1),
        (   append(RelWs, [comma|Rest2], Rest1), RelWs \== [], \+ memberchk(comma, RelWs) -> true
        ;   RelWs = Rest1, Rest2 = []
        ),
        \+ ( member(X2, RelWs), atom(X2) ),
        append(In1, [comma|RelWs], In2),
        tr_per_read(In2, S2), S2 = s(_, Sub2, _, _), Sub2 \= null(_, _)
    ->  In0 = In2, Rest = Rest2
    ;   In0 = In1, Rest = Rest1
    ).
tr_per_comment_dashed(C, Ws0, In0, Rest) :-
    once(( tr_solve(mean(C, 'according to')) ; tr_solve(mean(C, as)) )),
    append(In0, [dash|Rest], Ws0), In0 = [_|_], \+ memberchk(dash, In0), Rest = [w(_, _)|_],
    \+ ( member(X, In0), atom(X) ),
    tr_per_read(In0, S), S = s(_, Sub, _, _), Sub \= null(_, _), !.
tr_head_per(foreign, [w(C, CC)|Ws0], [w(K, perh), comma|Rest]) :-
    tr_per_comment(C, Ws0, In0, Rest), !,
    tr_aside_key(K, [w(C, CC)|In0]).
tr_head_per(_, Ws, Ws).

%% the reporting clause of it, read with no verb of the sentence's around it
tr_per_read(Ws, S) :-
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_group', none), nb_setval('$tr_read_aspect', simple),
    (   tr_said_to(tr_read_reporting(foreign, Ws, S0))
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), S = S0
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).

%% AN ADJUNCT BETWEEN TWO COMMAS BEFORE THE VERB OF A CLAUSE INSIDE A
%% SENTENCE: `per il semplice motivo che la "Bastiglia", qui da noi, non mi
%% risulta ...' -- here among us. The clause stands in a phrase, and a
%% comma ends a phrase's words, so the clause was cut at the first comma
%% and the sentence refused. After a word that opens a clause, the adjunct
%% goes as one item among the words, w(Key, mid), and the clause reads it as
%% the aside between its subject and its verb that tr_insertion_off/4 reads
%% at the head of a sentence (`Monsignor Cassisa, secondo l'accusa,
%% avrebbe'), where the words are left as they were.
%% ... AND ONLY WHILE THE CLAUSE HAS NO VERB YET: `Cuando el mundo había
%% girado su vista hacia Seúl, en el primer día del Mundial ..., llegaron les
%% lions de Bruno Metsu' -- the time clause is whole at its comma, and the
%% adjunct after it is the MAIN clause's front. Taken as an aside set in the
%% time clause, the words had no comma left to divide at and the sentence
%% was refused. The words since the opener are asked whether they read as a
%% clause of their own (tr_mid_after_clause/2), last, where the rest held.
tr_clause_mids(english, _, Ws, Ws) :- !.
tr_clause_mids(_, _, [], []) :- !.
tr_clause_mids(Side, yes(Since), [W, comma|Ws0], [W, w(K, mid)|Ws]) :-
    W = w(_, _), \+ tr_is(Side, W, preposition),
    %% (never after a relative word, `que' among them: the aside after it is
    %% the relative clause's own, read with its commas as frc/1 -- `Dijo que el
    %% perro duerme, lo que, en su opinión, es bueno' set it aside in the clause
    %% of the first `que', where the relative clause had lost it, and so did
    %% `la casa que, en la ciudad, duerme' inside one -- or the front of the
    %% clause that `que' opens: `Dijo que ve que, en la casa, duerme el gato')
    \+ ( W = w(WW, _), atom(WW), tr_relative_word(Side, WW) ),
    %% (never after a coordinator, whose comma opens the NEXT clause's
    %% insertion: `El perro sabe que el gato come, pero, además, duerme' is
    %% the division's, wc/1, and taken for an aside of the clause of `que'
    %% the second clause opened on it and nothing read the sentence)
    \+ tr_coord(Side, W),
    append(In, [comma|Rest], Ws0), In = [P|_], \+ ( member(X, In), atom(X) ),
    ( tr_is(Side, P, preposition) ; tr_plain_adverb(Side, P) ),
    %% (never before a purpose: `se reunieron el Martes por la noche, en las
    %% Reales Atarazanas, para celebrar ...' -- `para' is also what `parar'
    %% says, and after a relative clause far back the aside was taken for one
    %% set in a clause whose verb came next, and nothing read the purpose)
    \+ ( Rest = [w(PW, _)|R1], atom(PW), tr_purpose_word(PW), tr_starts_infinitive(Side, R1) ),
    tr_gap_verb_next(Side, Rest),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, In, Cs), Cs \== [], forall(member(C, Cs), tr_adjunct(C)),
    reverse([W|Since], SinceWs0), tr_drop_open(SinceWs0, SinceWs), \+ tr_mid_after_clause(Side, SinceWs),
    %% (the word right after the opener, where nothing stands before the verb that follows the commas
    %% but the clause's own gap, is tried set aside first and, if the sentence then reads nothing, left
    %% as it stands: `la gestión que ahora, con su noveno proyecto, parece estar en el buen camino' is
    %% the relative clause's front, tr_relative_clause/4's two fronts, and set aside the phrase was the
    %% sentence's -- but `Quest'Uomo che una volta, a fianco di Marco Pannella, si batteva' reads set
    %% aside, and better)
    ( Since == [open] -> true ; ! ),
    tr_aside_key(K, In), tr_clause_mids(Side, yes([w(K, mid), W|Since]), Rest, Ws).
tr_clause_mids(Side, Open0, [W|Ws0], [W|Ws]) :-
    (   W = w(_, _), tr_opens_clause(W) -> Open = yes([open])
    ;   Open0 = yes(Since) -> Open = yes([W|Since])
    ;   Open = Open0
    ),
    tr_clause_mids(Side, Open, Ws0, Ws).
%% (the mark of an opener among the words since it)
tr_drop_open([], []).
tr_drop_open([open|Ws], Out) :- !, tr_drop_open(Ws, Out).
tr_drop_open([W|Ws], [W|Out]) :- tr_drop_open(Ws, Out).
%% the words since a clause's opener read as a clause of their own, with no
%% verb of the sentence's around them and at no piece's head
%% (a verb form among them first: read whole, `che i precedenti della corte
%% costituzionale in materia di parità tra accusa e difesa' cost Ciampi's
%% thirteenth 0.44 million inferences to find no clause)
tr_mid_after_clause(Side, Ws) :-
    \+ memberchk(comma, Ws),
    once(( member(w(V, _), Ws), atom(V), tr_verb_form_word(V) )),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0), tr_global('$tr_piece', P0),
    nb_setval('$tr_read_group', none), nb_setval('$tr_read_aspect', simple), nb_setval('$tr_piece', []),
    ( tr_read_nested(Side, Ws, none, _) -> R = yes ; R = no ),
    nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), nb_setval('$tr_piece', P0),
    R == yes.

%% the words aside, read on the side they were written on and crossed: a
%% phrase if they are one, and otherwise complements
%% -- and a whole clause in brackets is read as one: `(los octavos de final
%% ya se disputarán a doble partido)' says something of its own
%% (the words have no verb of their own until a clause reads them: the
%% readings below run with none, where they ran under whatever group the
%% reading of the sentence had left last)
tr_aside_inner(K, Inner) :-
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_group', none), nb_setval('$tr_read_aspect', simple),
    (   tr_aside_inner0(K, Inner)
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).
tr_aside_inner0(K, Inner) :-
    nb_getval(K, Ws0), tr_side_here(Side),
    %% (the points a list trails off with are the titles' alone, below)
    ( append(Ws, [ellipsis], Ws0) -> E = yes ; Ws = Ws0, E = no ),
    \+ memberchk(ellipsis, Ws),
    (   %% TITLES, EACH AS IT STOOD: `sintonías (De España para los
        %% españoles, Elena Francis, Fantasía, Protagonistas nosotros...)'
        %% names the programmes whose theme tunes they were, and a title is
        %% written as it was titled -- read as words, `De España' was a name
        %% and `para los españoles' a phrase of the sentence's, and
        %% `Protagonistas nosotros' lost its pronoun. Two items at least
        %% between commas, each opening on a capital; the list may trail off
        tr_comma_items(Ws, Items), Items = [_, _|_],
        forall(member(I, Items), I = [w(_, upper)|_])
    ->  Inner = titles(Items, E)
    ;   E == yes -> fail
    ;   %% LETTERS NO LESSON KNOWS, AND NOTHING ELSE: `Giuseppe Iaconis
        %% Bovalino (r c)' -- the province, Reggio Calabria, by its
        %% initials. A letter alone is no word of any lesson's, and the
        %% bracket was refused for two words it could not know; it is
        %% written back as it stood, letters/1
        forall(member(X, Ws), ( X = w(L1, lower), atom(L1), atom_length(L1, 1), \+ tr_known_word(Side, L1) ))
    ->  findall(L1, member(w(L1, _), Ws), Ls), atomic_list_concat(Ls, ' ', T), Inner = letters(T)
    ;   %% a participle and its agent: part(Lexeme, Complements)
        Side == foreign, Ws = [w(P, _)|PR], tr_participle_here(foreign, P, L),
        \+ tr_is(foreign, w(P, lower), noun), \+ tr_is(foreign, w(P, lower), adjective),
        ( PR == [] -> Cs0 = [] ; tr_reduced_agent(foreign, PR, Cs0) )
    ->  tr_lexeme_across(L, english, LT), tr_cross_comps(Cs0, Cs), Inner = part(LT, Cs)
    %% ... and a participle with adjuncts of its own (tr_asides/3), in the
    %% gender and the number the source gave its form: `conocido' is the
    %% man in charge's, never the security's before the comma
    %% (and its agent after them: `Córcega, sacudida desde hace años por los atentados nacionalistas, ...' was shaken
    %% BY them -- `sacudida' is a noun too, so the branch above passed it by, and read as an adjunct the agent was
    %% `for the attacks', `per gli attentati')
    ;   Side == foreign, Ws = [w(P, _), Pr|PR], tr_participle_here(foreign, P, L),
        tr_is(foreign, Pr, preposition),
        ( tr_reduced_agent(foreign, [Pr|PR], Cs0), memberchk(by(_), Cs0) -> true ; tr_participle_adjuncts([Pr|PR], Cs0) )
    ->  tr_lexeme_across(L, english, LT), tr_cross_comps(Cs0, Cs1),
        ( tr_holds(feminine(P)) -> G = feminine ; G = masculine ), tr_participle_number(P, N),
        Inner = part(LT, [agr(G), agrn(N)|Cs1])
    %% ... and a participle with an adverb before it: `recientemente fichado
    %% por TVE', padv/1 among its complements
    ;   Side == foreign, Ws = [A, w(P, _)|PR], tr_plain_adverb(foreign, A), tr_participle_here(foreign, P, L),
        (   PR == [] -> Cs0 = []
        ;   tr_reduced_agent(foreign, PR, Cs0) -> true
        ;   tr_participle_adjuncts(PR, Cs0)
        )
    ->  tr_lexeme_across(L, english, LT), tr_cross_comps([padv(A)|Cs0], Cs1),
        ( tr_holds(feminine(P)) -> G = feminine ; G = masculine ), tr_participle_number(P, N),
        Inner = part(LT, [agr(G), agrn(N)|Cs1])
    %% ... and a participle with its degree: `más modernizados desde ...'
    ;   Side == foreign, Ws = [w(M, _), w(P, _)|PR], tr_degree_word(M), tr_participle_here(foreign, P, L),
        (   PR == [] -> Cs0 = []
        ;   tr_reduced_agent(foreign, PR, Cs0) -> true
        ;   tr_participle_adjuncts(PR, Cs0)
        )
    ->  tr_lexeme_across(L, english, LT), tr_cross_comps(Cs0, Cs1),
        ( tr_holds(feminine(P)) -> G = feminine ; G = masculine ), tr_participle_number(P, N),
        Inner = part(LT, [pdeg(comparative), agr(G), agrn(N)|Cs1])
    %% ... and a participle with the adjective it makes of its noun, and its
    %% adjuncts after it: `Via Krupp, resa più agibile dopo il restauro, è
    %% frequentata come mai' is the street made more accessible. Read as a
    %% clause of its own with nobody named, the street was set apart from its
    %% verb, and English, having nobody to say `is frequented' of, refused
    %% the sentence. The adjective is the first complement (adj/1, with its
    %% degree), anything after it an adjunct
    ;   Side == foreign, Ws = [w(P, _)|PR], PR = [_|_], tr_participle_here(foreign, P, L),
        tr_complements(foreign, PR, Cs0), Cs0 = [adj(_)|CR], forall(member(X, CR), tr_adjunct(X))
    ->  tr_lexeme_across(L, english, LT), tr_cross_comps(Cs0, Cs1),
        ( tr_holds(feminine(P)) -> G = feminine ; G = masculine ), tr_participle_number(P, N),
        Inner = part(LT, [agr(G), agrn(N)|Cs1])
    %% ... and a PREPOSITION'S PHRASE, where the words open on a preposition:
    %% `nell'inchiesta per omicidio colposo (contro ignoti)' -- against persons
    %% unknown. Read as a phrase first, `contro' was the noun (the cons of a
    %% thing) with `ignoti' for its adjective, which Spanish has no word for,
    %% and the sentence had no text
    ;   Ws = [P|_], P = w(_, _), tr_is(Side, P, preposition),
        tr_complements(Side, Ws, Cs00), Cs00 = [pp(_, _)|_]
    ->  tr_relative_wh1(Cs00, Cs0), tr_cross_comps(Cs0, Cs), Inner = comps(Cs)
    %% ... AND A RELATIVE CLAUSE WHOSE SUBJECT IS A PART OF WHAT IT STANDS
    %% FOR: `los actuales miembros de la junta directiva - - la mitad de los
    %% cuales deberán ser renovados ... - -' -- half of whom. Read as a phrase
    %% and a relative clause on it, the half was what `de los cuales' hung
    %% on and the clause had nobody for its subject, `la metà di cui dovranno
    %% esser rinnovati'. The part, its `of' and the relative clause with the
    %% subject left out, prel(Part, Preposition, Clause), and every writer
    %% puts its own relative after the preposition, agreeing with the phrase
    %% the aside stands after: `la metà dei quali', `half of which'
    ;   Side == foreign, append(HW, [P, w(R, _)|Rest], Ws), HW \== [], Rest \== [],
        tr_means_of(Side, P), atom(R), tr_relative_word(Side, R),
        tr_np(Side, HW, NP0), tr_partitive_head(NP0),
        tr_read_nested(Side, Rest, subject(rel), S0), S0 = s(_, asked(Q), G, Comps0)
    ->  ( Q = rel(QP, QN) -> Gap = gap(QP, QN) ; Gap = gap ),
        tr_cross_np(NP0, NP), P = w(PW, PC), tr_prep_across(PW, PT),
        tr_cross(Side, s(none, Gap, G, Comps0), S),
        %% (the relative's own gender and number travel with it: the aside
        %% hangs on the last phrase before it, `de la junta directiva', and
        %% `los cuales' are the members, which a board is not)
        ( sub_atom(R, B, 1, _, ' '), sub_atom(R, 0, B, _, RA), tr_determiner(foreign, w(RA, lower), RAL, article),
          tr_det_gender(foreign, w(RA, lower), RAL, RG, RN) -> true ; RG = none, RN = none ),
        Inner = prel(NP, w(PT, PC), S, RG, RN)
    %% ... and a phrase after a focus adverb (tr_asides/3): `, anche
    %% produttore cinematografico,' is also a film producer, the adverb at
    %% its head in every language, advnp(Adverb, Phrase)
    ;   Side == foreign, Ws = [w(FW, FC)|Ws1], atom(FW), tr_focus_adverb(FW), Ws1 \== [],
        tr_np(Side, Ws1, NP0), NP0 = np(none, none, _, w(_, _), _)
    ->  tr_cross_np(NP0, NP), tr_cross_comps([adv(w(FW, FC))], [adv(AdvT)]), Inner = advnp(AdvT, NP)
    ;   tr_np(Side, Ws, NP0) -> tr_cross_np(NP0, NP), Inner = np(NP)
    %% (a question word in an aside is a relative one: it hangs on a phrase)
    ;   tr_complements(Side, Ws, Cs00) -> tr_relative_wh1(Cs00, Cs0), tr_cross_comps(Cs0, Cs), Inner = comps(Cs)
    %% ... and an aside may open on its own coordinator: `in nome di una
    %% "pace" (ma la pace di chi e per chi)' -- but whose peace, and for whom
    ;   Ws = [C|Ws1], tr_coord(Side, C), tr_complements(Side, Ws1, Cs10)
    ->  tr_relative_wh1(Cs10, Cs1), tr_cross_comps([cnj(C)|Cs1], Cs), Inner = comps(Cs)
    %% ... and a REPORTING clause with a clause of its own after it:
    %% `"professore - gli ha chiesto un signore mentre eravamo nel bar -,
    %% se vincerà ...' -- a gentleman asked him, while we were in the bar.
    %% Read as a clause with nobody named, the gentleman was what was
    %% asked; he is the speaker after the verb (tr_reporting/3), and the
    %% clause after the connector joins the reporting clause
    ;   Side == foreign, tr_aside_reporting(Ws, S) -> Inner = clause(S)
    ;   tr_aside_clause(Side, Ws, S) -> Inner = clause(S)
    %% ... and a QUESTION with no mark of its own: `(ma chi avrebbe potuto
    %% pensare di "mediare" con Hitler)' asks who could have, and read as a
    %% statement `chi' was nobody's subject. It is written back as the
    %% words were, the question word first and no mark added
    ;   tr_aside_question(Side, Ws, S) -> Inner = clause(S)
    ), !.
%% a part of a whole: a count, or a word that means one
tr_partitive_head(np(_, M, _, _, _)) :- M \== none, !.
tr_partitive_head(np(_, _, _, w(W, _), _)) :-
    atom(W), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)),
    memberchk(E, [half, part, majority, minority, rest, most, some, many, several, one, none, each]), !.
%% the relative after a partitive's preposition: English's `which', and
%% the lesson's relative with its article, agreeing with what it stands for
%% -- written as two words, so the preposition contracts with the article
%% (`di i quali' is `dei quali')
tr_prel_relative(english, w(P, C), _, _, [o(P, C), o(which, lower)]) :- !.
tr_prel_relative(foreign, w(P, C), Noun, Number, [o(PT, C), o(A, lower), o(Q, lower)]) :-
    tr_word_across(w(P, lower), foreign, preposition, PT),
    (   Noun = elided(G1), atom(G1), G1 \== none -> G = G1
    ;   Noun \== none, atom(Noun), tr_gender(Noun, G0), G0 \== none -> G = G0
    ;   G = masculine
    ),
    once(( tr_solve(relative(R)), atom(R), atomic_list_concat([A, Q], ' ', R),
           tr_determiner(foreign, w(A, lower), AL, article), tr_det_gender(foreign, w(A, lower), AL, AG, AN),
           AN == Number, ( AG == G ; AG == none ) )).

%% the items of a list between its commas
tr_comma_items(Ws, [I|Is]) :-
    ( append(I, [comma|Rest], Ws) -> I \== [], tr_comma_items(Rest, Is) ; I = Ws, I \== [], Is = [] ).
%% the words of a clause set aside read as a statement, and leave the
%% reading of the words around them as they were
tr_aside_reads(Side, Ws) :-
    tr_global('$tr_piece', P0), nb_setval('$tr_piece', Ws),
    (   tr_aside_clause_read(Side, Ws) -> nb_setval('$tr_piece', P0)
    ;   nb_setval('$tr_piece', P0), fail
    ).
tr_aside_clause_read(Side, Ws) :-
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    (   tr_read(Side, statement, Ws, _)
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).
tr_aside_question(Side, Ws, S) :-
    ( Ws = [C|Ws1], tr_coord(Side, C) -> true ; Ws1 = Ws ),
    Ws1 = [w(Q, _)|_], tr_asks(Side, Q),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    (   tr_read(Side, question, Ws, S0), tr_cross(Side, S0, S1)
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), S = S1
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).
tr_asks(english, Q) :- !, en_question(Q, _).
tr_asks(foreign, Q) :- tr_solve(mean(Q, E)), en_question(E, _), !.
%% ... A WHOLE PIECE OF ITS OWN, WITH ITS COMMAS READ AS A PIECE'S ARE: `(...
%% per consentire a lupi, volpi e topi di fogna di circolare liberamente)'
%% -- the wolves, the foxes and the rats, and read with the list's commas
%% left bare the foxes were an adjective of the wolves, `a zorros lobos'.
%% The words set aside were kept before the sentence's commas were read, so
%% the steps tr_into_ir/4 takes over a sentence are taken here over them.
tr_aside_clause(Side, Ws0, S) :-
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0), tr_global('$tr_piece', P0),
    tr_clause_mids(Side, no, Ws0, Ws1), tr_list_commas(Side, Ws1, Ws),
    nb_setval('$tr_piece', Ws),
    (   tr_read(Side, statement, Ws, S0), tr_cross(Side, S0, S1)
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), nb_setval('$tr_piece', P0), S = S1
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), nb_setval('$tr_piece', P0), fail
    ).

%% the reporting clause and the clause after its connector, each read with
%% the piece its own
tr_aside_reporting(Ws, S) :-
    append(RW, [w(C, CC)|SW], Ws), RW = [_, _|_], SW = [_|_],
    atom(C), tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
    tr_read_reporting(foreign, RW, S1), S1 = s(_, Sub, _, _), Sub \= null(_, _),
    tr_global('$tr_piece', P0), nb_setval('$tr_piece', SW),
    (   tr_read(foreign, statement, SW, S2) -> nb_setval('$tr_piece', P0)
    ;   nb_setval('$tr_piece', P0), fail
    ), !,
    tr_cross(foreign, join(w(C, CC), S1, S2), S).

%% ... and written back in its marks -- an adjective in it agreeing with the
%% phrase it stands after, where there is one
tr_aside_out(To, Kind, Inner, Outs) :- tr_aside_out(To, Kind, Inner, none, singular, Outs).
tr_aside_out(To, Kind, Inner, Noun, Number, Outs) :-
    tr_global('$tr_verb', V0), nb_setval('$tr_verb', none),      % no verb in it: no marker before a person
    (   %% (a bare noun and its participle alone in a bracket are said in English noun first: `(baby sitter esclusa)'
        %% is babysitter excluded, where the participle before its noun came out `(excluded babysitter)')
        To == english, Kind == paren, Inner = np(rel(np(none, none, [], N, Nb), L, Cs)),
        forall(member(X, Cs), ( X = agr(_) ; X = agrn(_) ))
    ->  tr_np_out(english, np(none, none, [], N, Nb), NO, _, _),
        tr_lexeme_across(L, english, LT), en_reduced_participle(LT, PP), append(NO, [o(PP, lower)], IO)
    ;   Inner = np(NP) -> tr_np_out(To, NP, IO, _, _)
    ;   Inner = prel(NP, P, S, RG, RN)
    ->  tr_np_out(To, NP, NO, _, _),
        (   RN == none -> N1 = Number, Noun1 = Noun
        ;   RN == Number -> N1 = Number, Noun1 = Noun
        ;   N1 = RN, Noun1 = elided(RG)
        ),
        tr_prel_relative(To, P, Noun1, N1, RO),
        tr_write_nested(To, S, SO), append([NO, RO, SO], IO)
    ;   Inner = part(L, Cs0)
    ->  ( select(agr(GA), Cs0, Cs1) -> true ; Cs1 = Cs0, GA = none ),
        ( select(agrn(NA), Cs1, Cs2) -> true ; Cs2 = Cs1, NA = Number ),
        (   select(pdeg(D), Cs2, Cs3)
        ->  ( To == english -> ( D == superlative -> DW = most ; DW = more ) ; tr_degree_out(DW) ), Deg = [o(DW, lower)]
        ;   Cs3 = Cs2, Deg = []
        ),
        %% (the adverb that stood before the participle, before it again)
        (   select(padv(w(A, AC)), Cs3, Cs)
        ->  tr_word_across(w(A, lower), To, adverb, AT0),
            %% (English's `ever' before a participle that stands alone is `never': nothing in
            %% an aside denies it or ranks it -- `come quella dell'estate scorsa (mai passata)'
            %% was `(ever happened)')
            ( To == english, AT0 == ever -> AT = never ; AT = AT0 ),
            Adv = [o(AT, AC)]
        ;   Cs = Cs3, Adv = []
        ),
        (   To == english
        ->  tr_lexeme_across(L, english, LT), en_participle_of(LT, PP)
        ;   tr_lexeme_across(L, foreign, LT),
            ( GA \== none -> G = GA ; tr_gender(Noun, G0), G0 \== none -> G = G0 ; G = masculine ),
            tr_with_gender(G, tr_participle_agreeing(LT, NA, PP))
        ),
        tr_comps_out(To, Cs, Noun, Number, _, CO, CA), append([Adv, Deg, [o(PP, lower)], CO, CA], IO)
    ;   Inner = clause(S) -> tr_write(To, statement, S, IO)
    ;   Inner = advnp(w(A, AC), NP) -> tr_word_across(w(A, lower), To, adverb, AT), tr_np_out(To, NP, NO, _, _), IO = [o(AT, AC)|NO]
    ;   Inner = letters(T) -> IO = [o(T, lower)]
    ;   Inner = titles(Items, E) -> tr_titles_out(Items, E, IO)
    ;   Inner = comps(Cs), tr_comps_out(To, Cs, Noun, Number, _, CO, CA), append(CO, CA, IO)
    ),
    nb_setval('$tr_verb', V0),
    (   Kind == paren -> append([o('(', lower)|IO], [o(')', lower)], Outs)
    ;   Kind == dashed -> append([o('–', lower)|IO], [o('–', lower)], Outs)
    ;   Kind == dash1 -> Outs = [o('–', lower)|IO]
    ;   append([o(',', comma)|IO], [o(',', comma)], Outs)
    ), !.

%% titles out as they stood, with their commas, and the points they trail
%% off with
tr_titles_out([T], E, Os) :- !,
    findall(o(W, C), member(w(W, C), T), Os0),
    ( E == yes -> append(Os0, [o('...', lower)], Os) ; Os = Os0 ).
tr_titles_out([T|Ts], E, Os) :-
    findall(o(W, C), member(w(W, C), T), O1), tr_titles_out(Ts, E, O2),
    append([O1, [o(',', comma)], O2], Os).

%% A COMMA INSIDE A LIST IS THE LIST'S, NOT THE CLAUSE'S. `contra compañeros
%% y vecinos, emigrantes y minorías', `la violencia gratuita juvenil,
%% anárquica o xenófoba': the comma stands where a coordinator could, and
%% the plain reading -- which reads with the commas taken out -- read the
%% first as neighbours who are migrants. A comma is the list's when the word
%% before it is a noun or an adjective and after it come phrase words, a
%% coordinator and phrase words again, and then no verb: `En la casa, el
%% perro y el gato duermen' is a fronted phrase and a subject, and the verb
%% after the list says so. Such a comma travels as w(',', lcomma), which
%% tr_coord/2 takes for a coordinator, so a phrase splits at it and an
%% adjective list keeps it, and every writer puts back a comma.
%% ... AND A LIST AT THE HEAD OF THE SENTENCE IS ITS SUBJECT, whatever
%% follows it: `Il lavoro, l'impegno e i risultati raggiunti da Chrysler
%% ... sono qualcosa di eccezionale'. The rule above wants no verb after the
%% list, which is what keeps `En la casa, el perro y el gato duermen' a
%% front and a subject -- and there a preposition stands before the comma.
%% So while every word from the head of the piece is a phrase's word (Head
%% is `yes'), the list's own tail decides alone.
tr_list_commas(Side, Ws0, Ws) :- tr_list_commas(Side, none, yes, Ws0, Ws1), tr_list_back(Side, Ws1, Ws).
tr_list_commas(_, _, _, [], []).
%% NAMES WITH COMMAS BETWEEN THEM TO THE END OF THE PIECE, OR TO A DASH,
%% ARE ONE LIST THAT NEEDS NO COORDINATOR: `ma persino Pitagora, Parmenide,
%% Eudosso, Platone, Aristotele, Euclide, Aristarco, Archimede - e gli
%% unici ...' -- the list rule (this predicate's last comma clause) wants a
%% coordinator before the last item, and with its commas the clause's the
%% list had no reading. Three names at least, one word each, and every
%% comma of the run is marked at its first. An adverb after the last one closes
%% it as well (tr_list_closer/2).
%% (FIRST, before the apposition below: with three names that end the
%% piece, `ma persino Pitagora, Parmenide, Eudosso.', no comma follows the
%% last name, so the apposition took `Parmenide' for what Pitagora is and
%% the list was lost)
tr_list_commas(Side, Prev, _, [comma|Ws0], [w(',', lcomma)|Ws]) :-
    Prev = w(_, upper), tr_name_word(Side, Prev),
    tr_name_run(Side, Ws0, Run, Rest), Run = [_, _|_], ( Rest == [] ; Rest = [dash|_] ; tr_list_closer(Side, Rest) ), !,
    tr_lcomma_run(Run, RunL), last(Run, LastN), append(RunL, RestOut, Ws),
    tr_list_commas(Side, LastN, no, Rest, RestOut).
%% ... BUT NOT WHEN WHAT STANDS AFTER IT SAYS WHAT THE PERSON IS, to the end of
%% the piece with no verb in it: `Dalla testimonianza del primario di Perugia,
%% Alessandro Casotto, medico di Rosi fino al match con Phillips.' -- the
%% second comma parts the name from the noun, a line of a heading (tr_verbless0/3
%% splits at it), where taken in with the name the noun stood after the
%% apposition with nothing to be said of, and the sentence was refused. The
%% comma stays a comma after the name's word
tr_list_commas(Side, Prev, _, [comma|Ws0], [w(A, appos), comma|Rest]) :-
    Prev = w(_, _), ( tr_list_item(Side, Prev) -> true ; tr_name_word(Side, Prev) ),
    append(Ns, [comma|Rest], Ws0), Ns = [N1|Ns1], N1 = w(_, _), tr_name_word(Side, N1),
    forall(member(N, Ns1), N = w(_, upper)),
    Rest = [w(X, lower)|_], atom(X), \+ memberchk(comma, Rest), tr_is(Side, w(X, lower), noun),
    \+ ( member(w(Y, YC), Rest), atom(Y), tr_verb_form_word(Y), \+ tr_also_nominal(Side, w(Y, YC)) ),
    \+ tr_group_at(Side, Rest, _, _), !,
    findall(C, ( member(w(N, _), Ns), tr_cap(N, C) ), Cs), atomic_list_concat(Cs, ' ', A).
%% A NAME BETWEEN TWO COMMAS AFTER A PHRASE IS AN APPOSITION: `El ministro del
%% Interior francés, Jean-Pierre Chevènement, ha provocado'. The commas and
%% the name travel as ONE word, w(Name, appos), which the phrase before it
%% takes where a name apposed to its noun goes and every writer puts back,
%% commas and all, after the noun.
%% ... but not in a list of names: `si chiamano Giglio, Eolie, Ustica e
%% Ponza' -- `giglio' is a lily to the lesson, so the island before the
%% first comma was a noun with `Eolie' apposed to it, and the list was lost.
%% Names that go on after the second comma, to another comma or to a
%% coordinator, carry the list on.
tr_list_commas(Side, Prev, _, [comma|Ws0], [w(A, appos)|Ws]) :-
    %% (after a noun, an adjective -- or a NAME: `tuvo en Josep Bros, Edgardo,
    %% otro brillante jalón' is the singer and the role he sang, and read as
    %% the verb's object the role came out after `in', `Edgardo, altro')
    Prev = w(_, _), ( tr_list_item(Side, Prev) -> true ; tr_name_word(Side, Prev) ),
    %% (a name OPENS on a word no lesson knows and goes on through capitalised
    %% words, known or not: `la ministra de Justicia, Janet Reno, pidiéndole'
    %% -- `reno' is a reindeer to the lesson, and the name was lost)
    append(Ns, [comma|Rest], Ws0), Ns = [N1|Ns1], N1 = w(_, _), tr_name_word(Side, N1),
    forall(member(N, Ns1), N = w(_, upper)),
    \+ tr_names_go_on(Side, Rest), !,
    findall(C, ( member(w(N, _), Ns), tr_cap(N, C) ), Cs), atomic_list_concat(Cs, ' ', A),
    tr_list_commas(Side, w(A, appos), no, Rest, Ws).
%% ... AND ONE A SEMICOLON CLOSES, in a list whose items are set off by
%% semicolons because they have commas of their own: `políticos como Enrique
%% Lacalle; el conseller de Presidència de la Generalitat, Xavier Trias; el
%% ministro Josep Piqué ...' -- the conseller IS Xavier Trias. With the
%% semicolon after the name the comma stayed the clause's, and the part read
%% as a clause that leaves its verb out, the conseller seeing Xavier Trias.
%% The semicolon stays where it stood.
tr_list_commas(Side, Prev, _, [comma|Ws0], [w(A, appos), semicolon|Ws]) :-
    memberchk(semicolon, Ws0),
    Prev = w(_, _), ( tr_list_item(Side, Prev) -> true ; tr_name_word(Side, Prev) ),
    append(Ns, [semicolon|Rest], Ws0), Ns = [N1|Ns1], N1 = w(_, _), tr_name_word(Side, N1),
    forall(member(N, Ns1), N = w(_, upper)), !,
    findall(C, ( member(w(N, _), Ns), tr_cap(N, C) ), Cs), atomic_list_concat(Cs, ' ', A),
    tr_list_commas(Side, semicolon, no, Rest, Ws).
%% ... AND ONE THAT ENDS THE PIECE, where the stop closes it: `explicó ayer el
%% ministro de Asuntos Exteriores, Abel Matutes.' With no comma after the
%% name, the clause before the name's comma read as a reporting clause SET IN
%% the sentence, and the name was left to the first clause as an object of
%% `mantendrá'. Two words at least, the first one no lesson knows: a single
%% name at the end is as likely the last of a list (`Giglio, Eolie, Ustica,
%% Capri') as an apposition.
tr_list_commas(Side, Prev, _, [comma|Ns], [w(A, appos)]) :-
    Prev = w(_, _), ( tr_list_item(Side, Prev) -> true ; tr_name_word(Side, Prev) ),
    Ns = [N1, _|_], N1 = w(_, _), tr_name_word(Side, N1),
    forall(member(N, Ns), N = w(_, upper)), !,
    findall(C, ( member(w(N, _), Ns), tr_cap(N, C) ), Cs), atomic_list_concat(Cs, ' ', A).
%% ... and a name of ONE word that ends the piece after a noun in small letters:
%% `continuaron ayer los ataques ... sobre la capital, Grozni.' is the capital that
%% is Grozni, and with the comma the clause's the city was an object of the verb
%% of its own. A word no lesson knows; a list's items before it are names
%% (`Giglio, Eolie, Ustica, Capri'), never a noun the lesson has in small letters
tr_list_commas(Side, Prev, _, [comma, N1], [w(A, appos)]) :-
    Prev = w(P, lower), atom(P), tr_is(Side, Prev, noun), \+ tr_is(Side, Prev, verb),
    N1 = w(X, upper), atom(X), tr_name_word(Side, N1), \+ tr_is(Side, w(X, lower), noun),
    %% (a name the lesson states, a place's: `Non chiede il pane, Carolyn' has the speaker set at
    %% the end, the clause's subject, and apposed to the bread it was `the bread, Carolyn')
    downcase_atom(X, XL), tr_solve(name(XL)), !,
    tr_cap(X, A).
%% ... AND AN ADJECTIVE BETWEEN TWO COMMAS AFTER A PRONOUN OR A NAME IS SAID
%% OF IT: `i magistrati ... che egli, latitante, si permette di chiamare
%% fuorilegge' -- he, a fugitive. The word travels as w(A, pappos) with its
%% commas, so the phrase the relative clause stands in runs on through them
%% (a comma ends a phrase's words), and the clause reads it as an aside
%% between its subject and its verb (tr_insertion_off/4).
tr_list_commas(Side, Prev, _, [comma, w(A, lower), comma|Ws0], [w(A, pappos)|Ws]) :-
    Prev = w(P, _), ( tr_subject_pronoun(Side, P, _, _) ; tr_name_word(Side, Prev) ),
    tr_is(Side, w(A, lower), adjective), \+ tr_is(Side, w(A, lower), verb), !,
    tr_list_commas(Side, w(A, pappos), no, Ws0, Ws).
%% ... AND A LIST OF BARE NOUNS RIGHT AFTER A PREPOSITION, whatever follows
%% it: `la proibizione per auto, moto e motorini resta valida' is the ban on
%% cars, motorbikes and mopeds -- the rule below wants no verb after a list,
%% and with the comma the clause's the first two items were one noun and its
%% modifier (`motorbike car', `coche moto'). Each item a noun with no
%% determiner, commas between them and a coordinator before the last; a
%% front's phrase has its article (`En la casa, el perro y el gato duermen')
tr_list_commas(Side, Prev, _, [N1, comma|Ws0], [N1, w(',', lcomma)|Ws]) :-
    Prev = w(_, _), tr_is(Side, Prev, preposition), \+ tr_determiner(Side, Prev, _, _),
    tr_bare_item(Side, N1), tr_bare_tail(Side, Ws0, Tail, Rest), !,
    last(Tail, LastN), append(Tail, RestOut, Ws),
    tr_list_commas(Side, LastN, no, Rest, RestOut).
tr_list_commas(Side, Prev, Head, [comma|Ws0], [X|Ws]) :- !,
    %% (an item's bracket, where a name follows its comma: tr_list_word/2. Never before a phrase: `17 nuevos fichajes,
    %% entre ellos el portugués Conceiçao (Parma), los argentinos Guglielminpietro (Milan) y Vivas (Arsenal), los turcos
    %% ...' -- with the comma after `(Parma)' the list's, the sentence was 178 million inferences and refused)
    (   Prev = w(_, _), ( tr_list_item(Side, Prev) -> true ; Prev = w(_, paren), Ws0 = [N0|_], N0 = w(_, upper), \+ tr_determiner(Side, N0, _, _) ),
        ( tr_list_tail(Side, Ws0) ; Head == yes, tr_list_tail_head(Side, Ws0) ),
        tr_list_after_name(Side, Prev, Ws0),
        \+ tr_adjectives_after_noun(Side, Prev, Ws0)
    ->  X = w(',', lcomma), Head1 = Head
    ;   X = comma, Head1 = no
    ),
    tr_list_commas(Side, X, Head1, Ws0, Ws).
%% ... and so does a list at the head of a CLAUSE, after the word that opens
%% it: `Amene località dove le auto, le moto e i ciclomotori sono banditi'
%% -- the vehicles are the subject of `sono banditi', and with a verb after
%% the list the comma was the clause's
tr_list_commas(Side, _, Head, [W|Ws0], [W|Ws]) :-
    (   Head == yes, tr_list_word(Side, W) -> Head1 = yes
    ;   W = w(X, _), ( tr_relative_word(Side, X) ; tr_indirect_word(Side, X, _) ) -> Head1 = yes
    ;   Head1 = no
    ),
    tr_list_commas(Side, W, Head1, Ws0, Ws).

%% ... AND A COMMA BEFORE AN ITEM OF A LIST WHOSE LATER COMMAS ARE ALREADY THE
%% LIST'S IS ONE TOO, when the words on either side of it are each a
%% subject's phrase: `Voces de un ayer que marcó época y estrellas de las
%% ondas de hoy, políticos de ese centro que se disputan desde todas
%% direcciones, deportistas, artistas y altos ejecutivos de medios de
%% comunicación se reunieron'. The rule above wants every word of the tail a
%% phrase's word, which a phrase with a `de' phrase and a relative clause is
%% not, so that one comma stayed the clause's; with the subject read without
%% its commas, `de hoy políticos' was of politicians, and the sentence was
%% refused. It is asked only where a list comma follows a plain one, and a
%% front's comma stays -- `En la casa' is no subject's phrase.
%% (and only before an item that opens on a bare plural noun, as a crowd's
%% items do: `Inglaterra, el país que ha producido la minifalda, los
%% Beatles, los hooligans y la oleada ..., seguirá' is England and what it
%% is, and the list commas after `el país' are its relative clause's; taken
%% for the list's, England and the country were two, `continueranno')
tr_list_back(Side, Ws0, Ws) :-
    memberchk(comma, Ws0), memberchk(w(',', lcomma), Ws0),
    append(Pre, [comma|Post], Ws0),
    once(append(Item, [w(',', lcomma)|_], Post)), Item = [I1|_], \+ memberchk(comma, Item),
    I1 = w(_, _), tr_bare_plural_start(Side, Item),
    tr_last_item(Pre, Before), Before = [_|_], last(Before, B), B = w(_, _),
    ( tr_list_item(Side, B) -> true ; tr_is(Side, B, adverb), append(_, [P, B], Before), tr_is(Side, P, preposition) ),
    tr_subject(Side, half, Item, third, singular, _),
    tr_subject(Side, half, Before, third, singular, _), !,
    append(Pre, [w(',', lcomma)|Post], Ws1),
    tr_list_back(Side, Ws1, Ws).
tr_list_back(_, Ws, Ws).

%% the words after the last comma of a run, or all of them
tr_last_item(Ws, Item) :-
    (   append(_, [X|Item], Ws), ( X == comma ; X = w(',', lcomma) ; X == semicolon ), \+ memberchk(comma, Item), \+ member(w(',', lcomma), Item)
    ->  true
    ;   Item = Ws
    ).

tr_list_item(Side, W) :- ( tr_is(Side, W, noun) ; tr_is(Side, W, adjective) ), !.
%% ... AND A NAME: `si unisce a Ferrara, Sgarbi, Previti e Andreotti' is ONE
%% list of four people. With the comma after a name left the clause's, the
%% reading with the commas taken out made one name of three, `a Ferrara
%% Sgarbi Previti y Andreotti', and `Pannella parla con Ferrara, Sgarbi,
%% Previti e Andreotti' read the other three as objects of `parla' -- `habla
%% con Ferrara, a Sgarbi, a Previti y Andreotti'
tr_list_item(Side, W) :- tr_name_word(Side, W), !.
%% a bare noun of a list, and the rest of the list: items with commas between
%% them, a coordinator and the last item (the commas marked the list's)
tr_bare_item(Side, N) :- N = w(_, _), tr_is(Side, N, noun), \+ tr_determiner(Side, N, _, _), \+ tr_coord(Side, N), !.
tr_bare_item(Side, N) :- N = w(_, upper), tr_name_word(Side, N), !.
%% (... names too, to the end of the piece with no coordinator before the last, where they are three
%% or more: `nelle isole di Capri, Procida, Ischia, Giglio, Eolie' -- the islands of the five, and read
%% one by one the names after the first were objects of the verb, which Spanish wrote with the `a' of
%% a person, `a Procida, a Ischia')
tr_bare_tail(Side, [N, comma, L], [N, w(',', lcomma), L], []) :-
    N = w(_, upper), tr_bare_item(Side, N), L = w(_, upper), tr_bare_item(Side, L), !.   % (`Giglio' is the lily too)
tr_bare_tail(Side, [N, comma|Ws0], [N, w(',', lcomma)|Tail], Rest) :- tr_bare_item(Side, N), !, tr_bare_tail(Side, Ws0, Tail, Rest).
tr_bare_tail(Side, [N, C, L|Rest], [N, C, L], Rest) :- tr_bare_item(Side, N), C = w(_, _), tr_coord(Side, C), tr_bare_item(Side, L).
%% (an item with its bracket: `las playas de Tarragona, Salou (Tarragonès) y Cambrils (Baix Camp)' -- the towns and
%% their districts, and with the bracket the list had no reading and the sentence was refused)
tr_bare_tail(Side, [N, B|Ws0], [N, B|Tail], Rest) :-
    B = w(_, paren), N = w(_, upper), tr_bare_item(Side, N), Ws0 = [X|_], ( X == comma ; X = w(_, _), tr_coord(Side, X) ),
    tr_bare_tail(Side, [N|Ws0], [N|Tail], Rest).
%% ... A NOUN AND THEN ADJECTIVES ALONE ARE NO LIST: `Volaron bombas contra un
%% espectáculo, vulgar y degradante' is a show, vulgar and degrading, the
%% adjectives said of the noun before the comma -- read as a list of three
%% (the noun and its two adjectives, each an item), the comma was a list's
%% and nothing read. The noun is no adjective, and what follows its comma is a
%% run of adjectives that are no nouns and the coordinators between them, to
%% the end of the piece, a comma or a word that is no noun
tr_adjectives_after_noun(Side, Prev, Ws) :-
    Prev = w(_, _), tr_is(Side, Prev, noun), \+ tr_is(Side, Prev, adjective), \+ tr_name_word(Side, Prev),
    Ws = [A|_], A = w(_, _), tr_is(Side, A, adjective), \+ tr_is(Side, A, noun),
    tr_adjective_run(Side, Ws, Rest),
    (   Rest == [] -> true
    ;   Rest = [N|_], \+ ( N = w(_, _), tr_is(Side, N, noun) )
    ), !.
tr_adjective_run(Side, [W|Ws], Rest) :-
    W = w(_, _), ( tr_is(Side, W, adjective), \+ tr_is(Side, W, noun) ; tr_coord(Side, W) ), !,
    tr_adjective_run(Side, Ws, Rest).
tr_adjective_run(_, Rest, Rest).
%% one-word names with commas between them, and what follows the last
tr_name_run(Side, [N|Ws], [N|Ns], Rest) :-
    N = w(_, upper), tr_name_word(Side, N),
    (   Ws = [comma, N2|_], N2 = w(_, upper), tr_name_word(Side, N2), Ws = [comma|Ws1]
    ->  tr_name_run(Side, Ws1, Ns, Rest)
    ;   Ns = [], Rest = Ws
    ).
%% ... OR TO AN ADVERB THAT CLOSES IT, `eccetera': `Stoichkov, Baggio, Lombardo
%% eccetera' -- the last item of a list is a name with no comma after it
tr_list_closer(Side, [A|R]) :- A = w(_, _), tr_is(Side, A, adverb), ( R == [] ; R = [comma|_] ), !.
tr_lcomma_run([N], [N]) :- !.
tr_lcomma_run([N|Ns], [N, w(',', lcomma)|Ls]) :- tr_lcomma_run(Ns, Ls).
%% after a NAME the list goes on in names, or in phrases that open on a
%% determiner: `dice Carolyn Christov Bakargev, giornalista e critica' is the
%% speaker and her two trades, and read as a list of three the apposition was
%% lost and the sentence refused. A bare noun after a name's comma is what
%% the name is.
tr_list_after_name(Side, Prev, _) :- ( tr_is(Side, Prev, noun) ; tr_is(Side, Prev, adjective) ), !.
tr_list_after_name(Side, _, [W|_]) :- W = w(_, _), ( W = w(_, upper) ; tr_determiner(Side, W, _, _) ), !.

%% A COMMA BETWEEN TWO ADJECTIVES BEFORE THEIR NOUN IS THE PHRASE'S: `con i
%% nuovi, piccoli, meschini, Hitler di questa fine secolo', the new, small,
%% petty Hitlers, was refused whole -- `, piccoli,' was taken for an aside
%% of `nuovi' (tr_asides/3), and a plain comma ends a phrase besides. After
%% a determiner, adjectives with commas between them and then a noun or a
%% name, a comma before it included, are one phrase, and each comma is the
%% ADJECTIVES' (w(',', acomma)): a coordinator to the adjectives, which keep
%% it and every writer puts back where the source had it, and never one a
%% phrase is divided at (tr_conjunction_split/5) -- the list's own comma
%% (lcomma) divides one. It is read before the asides are, so that none of
%% them sees a comma there.
tr_adj_lists(_, [], []).
%% ... AND A DETERMINER SAID TWICE WITH A COMMA BETWEEN IS SAID ONCE, with
%% the repetition kept in its case: `ma soltanto tante, tante persone
%% comuni' -- so many, so many common people. The comma divided the
%% sentence there, and neither half read. The word travels as w(D, rep), and
%% every writer spells it twice with the comma between (tr_word_text/4).
tr_adj_lists(Side, [w(X, _), comma, w(X, _)|Ws0], [w(X, rep)|Ws]) :-
    atom(X), tr_determiner(Side, w(X, lower), _, _),
    Ws0 = [N|_], N = w(_, _), ( tr_is(Side, N, noun) ; tr_is(Side, N, adjective) ), !,
    tr_adj_lists(Side, Ws0, Ws).
tr_adj_lists(Side, [D|Ws0], [D|Ws]) :-
    D = w(_, _), tr_determiner(Side, D, _, _),
    tr_adj_commas(Side, Ws0, As, [N|Rest]),
    N = w(_, _), ( tr_is(Side, N, noun) ; tr_name_word(Side, N) ), !,
    append(As, [N|Ws1], Ws),
    tr_adj_lists(Side, Rest, Ws1).
%% ... AND ADJECTIVES AFTER THEIR NOUN, WITH COMMAS BETWEEN THEM: `è un uomo
%% alto, snello, scuro, un pò mediorientale nei lineamenti' -- tall,
%% slender, dark, a bit Middle Eastern. Each comma is the adjectives' as it
%% is before the noun, and an item may carry its adverb; read as the
%% clause's, `snello' was a clause of its own and the sentence was refused.
%% Three items at least: `un uomo alto, snello' may be a phrase and more.
tr_adj_lists(Side, [D, N|Ws0], [D, N|Ws]) :-
    ( Ws0 = [_, comma|_] ; Ws0 = [_, _, comma|_] ),            % the first item and its comma, first
    D = w(_, _), tr_determiner(Side, D, _, _), N = w(_, lower), tr_is(Side, N, noun),
    tr_post_adjs(Side, Ws0, As, Rest), findall(x, member(w(',', acomma), As), [_, _|_]), !,
    append(As, Ws1, Ws), tr_adj_lists(Side, Rest, Ws1).
%% ... AND A COMMA BETWEEN TWO NUMBERS BEFORE THEIR NOUN: `hanno bisogno di
%% altri due, tre anni' -- two or three years, a count of either. Divided at
%% the comma, `altri due' was another two and the years a time of their own,
%% `otro dos, tres años'. The comma is the count's, as the coordinator of `4
%% e 5 anni' is (nums/3) -- never after a year, which a count may follow:
%% `nel 2001, 5 persone'
tr_adj_lists(Side, [M1, comma, M2, N|Ws0], [M1, w(',', acomma), M2|Ws]) :-
    M1 = w(M1W, _), atom(M1W), \+ tr_year(M1W), M2 = w(_, _),
    tr_is(Side, M1, number), tr_is(Side, M2, number),
    N = w(_, _), tr_is(Side, N, noun), !,
    tr_adj_lists(Side, [N|Ws0], Ws).
tr_adj_lists(Side, [W|Ws0], [W|Ws]) :- tr_adj_lists(Side, Ws0, Ws).

tr_post_adjs(Side, Ws0, Out, Rest) :-
    tr_post_adj_item(Side, Ws0, Item, Ws1),
    (   Ws1 = [comma|Ws2], tr_post_adj_item(Side, Ws2, _, _)
    ->  tr_post_adjs(Side, Ws2, Out1, Rest), append(Item, [w(',', acomma)|Out1], Out)
    ;   Out = Item, Rest = Ws1
    ).
tr_post_adj_item(Side, [A|Ws], [A], Ws) :- tr_comma_adj(Side, A), \+ tr_is(Side, A, verb), !.
tr_post_adj_item(Side, [V, A|Ws], [V, A], Ws) :-
    V = w(_, _), tr_plain_adverb(Side, V), tr_comma_adj(Side, A), \+ tr_is(Side, A, verb), !.

%% two adjectives or more with a comma between each two, and perhaps one after
%% the last: the commas come back as the list's
tr_adj_commas(Side, [A, comma, B|Ws], [A, w(',', acomma)|Os], Rest) :-
    tr_comma_adj(Side, A), tr_comma_adj(Side, B), !,
    tr_adj_commas1(Side, [B|Ws], Os, Rest).
tr_adj_commas1(Side, [A, comma, B|Ws], [A, w(',', acomma)|Os], Rest) :-
    tr_comma_adj(Side, A), tr_comma_adj(Side, B), !,
    tr_adj_commas1(Side, [B|Ws], Os, Rest).
%% ... AND THE LAST TWO JOINED BY A COORDINATOR: `la hermosa, joven y
%% cautivadora Senegal' -- beautiful, young and captivating. The list
%% stopped at `y', `joven' was a youngster, and the three were three
%% phrases of their own
tr_adj_commas1(Side, [A, C, B|Ws], [A, C, B], Ws) :-
    C = w(_, _), tr_coord(Side, C), tr_comma_adj(Side, A), tr_comma_adj(Side, B), !.
tr_adj_commas1(_, [A, comma|Ws], [A, w(',', acomma)], Ws) :- !.
tr_adj_commas1(_, [A|Ws], [A], Ws).

tr_comma_adj(Side, A) :- A = w(_, lower), tr_is(Side, A, adjective), tr_adj_word(Side, A), !.

%% (a name may carry its bracket on: `per Antonio Montegrande, Giorgio Paradisi, Marcello Colafigli, Emidio
%% Castelletti (tutti della banda della Magliana), Enrico Mariotti, ...' -- with the bracket after the fourth name the
%% names did not go on, the second took the third for what it is, and the list of eleven was refused)
tr_names_go_on(Side, Ws) :-
    append(Ns, [X|After], Ws), Ns \== [], forall(member(N, Ns), N = w(_, upper)),
    (   X == comma -> true ; X = w(_, paren) -> After = [Y|_], ( Y == comma -> true ; Y = w(_, _), tr_coord(Side, Y) )
    ;   X = w(_, _), tr_coord(Side, X)
    ), !.

tr_list_tail(Side, Ws) :-
    append(S, [C|Rest0], Ws), S \== [], C = w(_, _), tr_coord(Side, C), tr_list_items(Side, S, Rest0), !,
    append(T, Rest, Rest0), T \== [], forall(member(X, T), tr_list_word(Side, X)),
    ( Rest == [] ; Rest = [N|_], \+ tr_list_word(Side, N), \+ tr_verb_next(Side, Rest) ), !.

%% a verb next, or after a denial: `Han comido pan, Rivaldo y Overmars NO
%% ESTUVIERON en Gandía' -- the two names are the subject of a clause of
%% their own, and taken for the end of a list of what was eaten, the
%% bread, Rivaldo and Overmars, the sentence was divided at the `y'
tr_verb_next(Side, [N|Ns]) :-
    N = w(W, _),
    %% (a word the lesson calls a PREPOSITION too, before a determiner, is the
    %% preposition: `el rastro de litronas, altercados y temor ENTRE la
    %% tranquila población' -- `entre' is also the subjunctive of `entrar', and
    %% read as a verb after the list it left the comma to the clause, and the
    %% bottles were a phrase `altercados' was a participle of)
    \+ ( tr_is(Side, N, preposition), Ns = [D|_], D = w(_, _), tr_determiner(Side, D, _, _) ),
    (   ( tr_is(Side, N, verb) ; Side == foreign, tr_verb_form_word(W) ) -> true
    ;   ( tr_negation_word(W) ; tr_denying_adverb(Side, N) ), tr_verb_next(Side, Ns)
    ).

%% the list's tail with anything after it: phrase words, a coordinator,
%% phrase words, and then something that is no phrase's word
tr_list_tail_head(Side, Ws) :-
    append(S, [C|Rest0], Ws), S \== [], C = w(_, _), tr_coord(Side, C), tr_list_items(Side, S, Rest0), !,
    append(T, Rest, Rest0), T \== [], forall(member(X, T), tr_list_word(Side, X)),
    ( Rest == [] ; Rest = [N|_], \+ tr_list_word(Side, N) ), !.

%% THE ITEMS BEFORE THE COORDINATOR MAY HAVE COMMAS BETWEEN THEM: `i cani, i
%% gatti, i topi e i conigli' is one list of four. Held to words with no
%% comma, the tail after the FIRST comma was no list's, that comma stayed
%% the clause's, and the dogs became an object of their own beside a list
%% of three -- and at the head of a sentence, `Il cane, il gatto, il topo e
%% il coniglio mangiano il pane' read as a verbless piece, `the dog, the
%% cat', joined to a clause whose subject was the mouse and the rabbit.
%% A comma between two items, never at either end, never two together.
%% ... AND AN ITEM MAY HAVE A PHRASE OF `OF' IN IT: `debatirán la pasantía, los
%% honorarios, la normalización del catalán y otros temas' -- the `del' was no
%% phrase's word, that comma stayed the clause's, and a front put before the
%% first of them (`durante tres días') landed between two items. Only in a
%% list with commas, or before an item that is a phrase of its own: `el
%% espejo del fútbol moderno e invencible' is no list of two, and read as
%% one it cost the Senegal report's twenty-second 3.5 %, a reading that
%% failed after it -- while `..., la normalización del catalán y otros
%% temas' is the last item of its list, with no comma left in it
tr_list_items(Side, S, After) :-
    S = [X0|_], X0 \== comma, last(S, XL), XL \== comma,
    \+ append(_, [comma, comma|_], S),
    forall(member(X, S), ( X == comma ; tr_list_word(Side, X) ; X = w(_, _), tr_means_of(Side, X), tr_item_of(Side, S, After) )),
    tr_list_word(Side, XL).

tr_item_of(_, S, _) :- memberchk(comma, S), !.
tr_item_of(Side, _, [N|_]) :- N = w(_, _), ( tr_determiner(Side, N, _, _) ; N = w(_, upper) ; tr_is(Side, N, noun) ), !.

tr_list_word(Side, W) :-
    W = w(_, _), \+ tr_coord(Side, W),
    ( tr_is(Side, W, noun) ; tr_is(Side, W, adjective) ; tr_determiner(Side, W, _, _) ; tr_is(Side, W, number) ; W = w(_, upper) ), !.
%% (and an item's bracket: `per Antonio Montegrande, ..., Emidio Castelletti (tutti della banda della Magliana), Enrico
%% Mariotti, ...' -- with the bracket no phrase's word the commas after the first four names stayed the clause's, and
%% the names were the verb's objects, `para Antonio Montegrande, a Giorgio Paradisi, a Marcello Colafigli')
tr_list_word(_, w(_, paren)) :- !.
%% (and the word for `all' before a phrase: `Pinelli, Flaiano, Zavattini e tutti gli sceneggiatori di quei film' is one
%% list of four, and with `tutti' no phrase's word its commas stayed the clause's and the list had no reading)
tr_list_word(foreign, W) :-
    W = w(X, _), atom(X), tr_lexeme(foreign, X, L, _), tr_class_of(L, pronoun), tr_solve(mean(L, all)), !.

%% ---- into the IR: the crossing walk ----------------------------------------------

%% the same lookups the writer into English makes, made once over the
%% term rather than over the words coming out of it -- so a sentence read
%% on the lesson's side becomes the same term an English sentence reads
%% as, and anything that can write one can write the other
%% two clauses joined: the connector crosses to English as the word it is,
%% and each side crosses as the sentence it is
tr_cross(_, none, none) :- !.
tr_cross(_, gap(F0, B0), gap(F, B)) :-
    append(F1, [obj(NP0)], F0), B0 = [PP|_], tr_relational_np(NP0, PP, NP), !,
    tr_cross_comps(F1, Fa), append(Fa, [obj(NP)], F), tr_cross_comps(B0, B).
tr_cross(_, gap(F0, B0), gap(F, B)) :- !, tr_cross_comps(F0, F), tr_cross_comps(B0, B).
tr_cross(Side, q(S0), q(S)) :- !, tr_cross(Side, S0, S).
tr_cross(Side, qh(S0), qh(S)) :- !, tr_cross(Side, S0, S).
tr_cross(Side, join(C0, A0, B0), join(C, A, B)) :- !,
    tr_cross_connector(Side, C0, C), tr_cross(Side, A0, A), tr_cross(Side, B0, B1), tr_count_gap(A, B1, B).
tr_cross(english, S0, S) :- !, tr_cross_which(S0, S).
tr_cross(foreign, s(Asked0, Subject0, g(L0, T, A, Neg), Comps0), s(Asked, Subject, g(L, T, A, Neg), Comps)) :-
    tr_global('$tr_obj_gap', Gap), nb_setval('$tr_obj_gap', no),
    (   A == simple, tr_state_lexeme(L0) -> tr_lexeme_across(L0, english, L1), L = state(L1)
    ;   tr_verb_across(L0, A, Comps0, Gap, L)
    ),
    tr_cross_asked(Asked0, Asked),
    tr_global('$tr_poss', Poss0), ( Poss0 == her -> true ; nb_setval('$tr_poss', none) ),
    ( L0 = reflexive(_) -> tr_as_doer_not(tr_cross_subject(Asked, Subject0, Subject)) ; tr_as_doer(tr_cross_subject(Asked, Subject0, Subject)) ),
    %% ... AND THE POSSESSIVE OF A PLURAL SUBJECT'S COMPLEMENTS IS THEIRS: see
    %% tr_cross_det/2. The subject's own phrase is crossed first, so a
    %% possessive inside it (`el presidente y sus ministros') is not.
    %% ... AND A WOMAN'S IS `her': `La mujer asegura que ha cambiado sus hábitos' changed HER habits, and `Otra
    %% vecina manifiesta que su comportamiento no ha variado' her behaviour -- in her clause, in a clause of hers
    %% with nobody named and in the subject of a clause inside hers; a subject of its own takes it back
    ( tr_plural_possessor(Subject0) -> nb_setval('$tr_poss', their)
    %% (never after a copula, whose phrase is no thing the subject owns: `El diálogo fue su receta' was HIS recipe,
    %% Ibarretxe's, and it came out `The dialogue was its prescription')
    ; tr_thing_possessor(Subject0, Comps0), \+ ( atom(L0), tr_copula_lexeme(L0) ) -> nb_setval('$tr_poss', its)
    ; tr_female_possessor(Subject0) -> nb_setval('$tr_poss', her)
    ; Subject0 = gap(third, singular), tr_global('$tr_rc_head', RH), RH \== none, tr_thing_possessor(RH, Comps0) -> nb_setval('$tr_poss', its)
    ; Subject0 = null(third, singular) -> true
    ; nb_setval('$tr_poss', none) ),
    %% (and the phrase a verb of a reflexive sense governs is that sense's:
    %% `se ha convertido en el elemento' governs `en' as BECOMES, which English
    %% writes with no preposition -- read as the verb's own lexeme, `converts')
    tr_global('$tr_gov_sense', GS0),
    ( L0 = reflexive(R0), atom(R0), atom(L), \+ L = reflexive(_) -> nb_setval('$tr_gov_sense', R0-L) ; nb_setval('$tr_gov_sense', none) ),
    %% (a partitive pronoun beside a subject that is a quantity is said once, as beside an object that is one:
    %% `Oggi non ce n'è rimasto più nessuno' is today nobody is left, and `ne' crossed as `it')
    (   Subject0 = pronoun(_, _, w(QW, _)), atom(QW), tr_quantity_word(QW),
        select(opron(w(PW, _)), Comps0, CompsQ), atom(PW),
        ( tr_solve(partitive(PW)) -> true ; tr_solve(elision_of(PW, PB)), tr_solve(partitive(PB)) )
    ->  Comps00 = CompsQ
    ;   Comps00 = Comps0
    ),
    (   tr_as_doer_not(tr_cross_inf_comps(L0, Comps00, Comps1)) -> nb_setval('$tr_gov_sense', GS0)
    ;   nb_setval('$tr_gov_sense', GS0), fail
    ),
    tr_abs_first(Comps1, Comps2),
    tr_result_clause(Subject0, Subject, Comps2, Comps3),
    tr_linking_pred(L, Comps3, Comps),
    nb_setval('$tr_poss', Poss0).
%% A CLAUSE OF `que' AFTER A PHRASE OF `so much' OR `so many' IS WHAT CAME OF IT: `el
%% pasaje destiló tanta indignación que se amotinó' is so much indignation that THEY
%% mutinied, and read as a relative clause on the indignation the indignation
%% mutinied -- `that mutinied' in English. The clause's subject is the main clause's,
%% in its number, and the pronoun English names it by, `he' for a person and `it' for a
%% thing (res/2, tr_comp_out/7)
tr_result_clause(Su0, Su, Cs0, Cs) :-
    append(Pre, [obj(rc(NP, subject, s(A, gap(third, _), G, Cs2)))|Post], Cs0),
    NP = np(det(determiner, D, _), _, _, _, _), memberchk(D, ['so much', 'so many']), !,
    tr_ir_number(Su, N),
    ( tr_of_class(Su0, person) -> P = he ; P = it ),
    append(Pre, [obj(NP), res(s(A, null(third, N), G, Cs2), P)|Post], Cs).
tr_result_clause(_, _, Cs, Cs).
%% A VERB OF BECOMING WITH NO PREDICATE TAKES THE ADJECTIVE THAT ENDS ITS LAST PHRASE: `I suoi rimbalzi ... sono
%% diventati in certi casi proverbiali' have become proverbial in some cases, and read into the phrase before it the
%% adjective came out `have become in some proverbial cases' -- the predicate goes before the phrase, where both
%% languages put it. A verb that says what its subject comes to be or stays,
%% never the copula (`è in una casa grande' is in a big house), no predicate or object of its own, and an adjective the
%% source put after the phrase's noun
tr_linking_pred(L, Cs0, Cs) :-
    atom(L), memberchk(L, [becomes, remains, seems, appears]),
    \+ ( member(C, Cs0), ( C = adj(_) ; C = pred(_) ; C = obj(_) ) ),
    append(Pre, [pp(P, np(Det, Num, Adjs0, N, Nb))], Cs0), N = w(_, _),
    %% (never the phrase of `like', whose adjective is its own: `sin que la ornamentación final aparecieran por allí como
    %% fuegos fatuos' is like fatuous fires, and it came out `fatuous as fires')
    \+ ( P = w(PW, _), memberchk(PW, [like, as]) ),
    append(Adjs, [w(A, AC)], Adjs0), atom(A), !,
    append(Pre, [adj([w(A, AC)]), pp(P, np(Det, Num, Adjs, N, Nb))], Cs).
tr_linking_pred(_, Cs, Cs).
tr_ir_number(np(_, _, _, _, N), N) :- !.
tr_ir_number(pronoun(_, N, _), N) :- !.
tr_ir_number(null(_, N), N) :- !.
tr_ir_number(with(NP, _), N) :- !, tr_ir_number(NP, N).
tr_ir_number(rc(NP, _, _), N) :- !, tr_ir_number(NP, N).
tr_ir_number(_, singular).

%% a clause joined after a subject a round count made plural (tr_cross_np/2), with
%% nobody named, is the plural's: `una veintena de viajeros rodeó a una azafata y
%% estuvo a punto de lincharla' -- about twenty travellers WERE on the verge, and
%% with the singular the source's verb has, English kept no subject it could elide
tr_count_gap(A, s(Q, null(third, singular), G, Cs), s(Q, null(third, plural), G, Cs)) :-
    tr_last_statement(A, s(_, Su, _, _)), tr_count_subject(Su), !.
tr_count_gap(_, B, B).
tr_count_subject(np(_, adv_num(_, w(N, _)), _, _, plural)) :- en_round_count(N), !.
tr_count_subject(np(det(article, the, _), w(N, _), _, _, plural)) :- en_round_count(N), !.
tr_count_subject(with(NP, _)) :- tr_count_subject(NP).
en_round_count(ten). en_round_count(twenty). en_round_count(hundred). en_round_count(thousand).
%% the doer the crossing of a phrase is told of (tr_cross_np/2's collective
%% meaning): a goal run with '$tr_doer' set, and one run with it put out
tr_as_doer(G) :- tr_global('$tr_doer', D0), nb_setval('$tr_doer', yes), ( call(G) -> nb_setval('$tr_doer', D0) ; nb_setval('$tr_doer', D0), fail ).
tr_as_doer_not(G) :- tr_global('$tr_doer', D0), nb_setval('$tr_doer', no), ( call(G) -> nb_setval('$tr_doer', D0) ; nb_setval('$tr_doer', D0), fail ).

%% A PARTICIPLE AND ITS PHRASE RIGHT AFTER THE VERB SAY HOW THE VERB LEAVES THE
%% PHRASE: `el elemento negociador que mantiene bloqueado el convenio colectivo'
%% keeps the collective agreement blocked, and `una estatua tiene levantado el
%% brazo izquierdo' has the left arm raised. The clause's first complement only
%% (abso/2, which English writes phrase first, tr_comp_out/7): after another
%% complement it is an absolute clause of its own, the participle first in every
%% language -- `que el lehendakari adelante las elecciones en Euskadi dada la
%% situación' is given the situation, and written phrase first in the first cut
%% it was `the situation given'
tr_abs_first([abs(L, NP)|Cs], [abso(L, NP)|Cs]) :- !.
tr_abs_first(Cs, Cs).

tr_female_possessor(Subject) :-
    tr_possessor_head(Subject, np(_, _, _, w(W, _), singular)), atom(W),
    tr_lexeme(foreign, W, L, singular), atom(L), tr_holds(person(L)), tr_stated_gender(L, feminine),
    \+ tr_fact(animate(L)), !.
tr_plural_possessor(np(_, _, _, _, plural)).
tr_plural_possessor(co(_, _, _)).
%% (the subject's own phrase with a phrase of `of' or a relative clause on it:
%% `los abogados del turno de oficio cobran por sus servicios')
tr_plural_possessor(with(NP, _)) :- tr_plural_possessor(NP).
tr_plural_possessor(rc(NP, _, _)) :- tr_plural_possessor(NP).
tr_plural_possessor(nrc(NP, _, _)) :- tr_plural_possessor(NP).
tr_plural_possessor(app(NP, _, _)) :- tr_plural_possessor(NP).
tr_plural_possessor(all(_, NP)) :- tr_plural_possessor(NP).
tr_plural_possessor(advp(_, NP)) :- tr_plural_possessor(NP).      % (`incluso representantes municipales ... su desaprobación')
tr_plural_possessor(null(third, plural)).
tr_plural_possessor(pronoun(third, plural, _)).
%% ... and a relative clause's own, the plural phrase it hangs on: `organizaciones luciferinas que tienen sus propias
%% páginas oficiales' have THEIR own pages, and the lesson's first meaning wrote `his own official pages'
tr_plural_possessor(gap(third, plural)).
%% ... AND A SINGULAR SUBJECT THAT IS NO PERSON OWNS WHAT ITS COMPLEMENTS' POSSESSIVE NAMES, `its': `la vida
%% política en Moscú continúa su curso' continues ITS course, and with the lesson's first meaning it came out `his
%% course'. A phrase with a noun or a named thing (`el Kremlin'), never a name alone, which is a person as often;
%% and not where a person or a name stands among the clause's complements, whose own the possessive may be (`la
%% empresa despidió a Juan por su conducta')
tr_thing_possessor(Subject, Comps) :-
    tr_possessor_head(Subject, NP), NP = np(_, _, _, W, singular), ( W = w(_, _) ; W = named(_, _) ),
    \+ tr_of_class(NP, person),
    \+ ( member(C, Comps), tr_comp_phrase(C, CNP), ( CNP = name(_) ; tr_of_class(CNP, person) ) ),
    %% (nor a pronoun that stands for a person: `El viento le voló su sombrero' blew HIS hat, and
    %% `avisó a Ibarretxe de que a su Gobierno el tiempo se le acaba' is his Government)
    \+ ( member(opron(P), Comps), tr_person_clitic(P) ), !.
tr_person_clitic(dat(_)).
tr_person_clitic(w(W, _)) :-
    atom(W), ( memberchk(W, [him, her, me, us, you, them]) -> true ; tr_solve(mean(W, P)), memberchk(P, [him, her, me, us, you, them]) ), !.
tr_possessor_head(np(A, B, C, D, E), np(A, B, C, D, E)).
tr_possessor_head(with(NP, _), H) :- tr_possessor_head(NP, H).
tr_possessor_head(rc(NP, _, _), H) :- tr_possessor_head(NP, H).
tr_possessor_head(nrc(NP, _, _), H) :- tr_possessor_head(NP, H).
tr_possessor_head(app(NP, _, _), H) :- tr_possessor_head(NP, H).
tr_comp_phrase(obj(NP), NP).
tr_comp_phrase(pp(_, NP), NP).

%% THE INFINITIVE AFTER A MODAL TAKES ITS SENSE BY THE CLAUSE'S OBJECT, as
%% the verb itself does (tr_verb_across/5): `deve finire in tribunale' has
%% none, so `finire' is the intransitive `ends up' and never `finishes'
%% ... and after the copula, whose phrase before the infinitive is the copula's own: `Es una locura bajar a la playa'
%% is madness to GO DOWN to the beach, and with `una locura' taken for the infinitive's object it was `to drop'
tr_cross_inf_comps(L0, Comps0, Comps) :-
    append(Pre0, [inf(IL)|Post0], Comps0), atom(IL), tr_intransitive_meanings(IL, [IM|_]),
    \+ ( member(C, Post0), tr_object_comp(C) ),
    ( \+ ( member(C, Pre0), tr_object_comp(C) ) -> true ; atom(L0), tr_copula_lexeme(L0) ), !,
    tr_cross_comps(Pre0, Pre), tr_cross_comps(Post0, Post), append(Pre, [inf(IM)|Post], Comps).
tr_cross_inf_comps(_, Comps0, Comps) :- tr_cross_comps(Comps0, Comps).

%% A VERB'S MEANING BY WHETHER ITS CLAUSE HAS AN OBJECT. `De la amplia
%% gama de instrumentos ..., destaca un violín' is a violin that STANDS
%% OUT, and `El constructor destacó algunas de las diferencias' a builder
%% who HIGHLIGHTED them: one verb, and what tells the senses apart is the
%% object, which nothing but the clause can say. A lesson gives the first
%% sense as the verb's intransitive one -- `The intransitive verb "destaca"
%% means "stands out".', which is also what lets the phrase after it be its
%% subject -- and a clause with no object takes it, where a clause with one
%% takes the first meaning that is not it. A relative clause whose relative
%% word IS the object has one (`el violín que destacó el experto'), which
%% the phrase that carries it says through '$tr_obj_gap', and a passive
%% has one by what it is. Everywhere else -- a reduced relative, a
%% participle, a verb with no such meaning -- tr_lexeme_across/3 passes the
%% intransitive meaning over, so the verb crosses as it always did.
%% -- AND A PRONOUN BEFORE AN INTRANSITIVE VERB WHOSE SUBJECT STANDS AFTER
%% IT IS WHO IT PLEASES: `Me gusta la escuela' has no object, and with `me'
%% counted as one `gusta' took the transitive `likes' and the school liked
%% me. The reader put the subject there (subj_here) because the lesson calls
%% the verb intransitive, so a pronoun before it can only be the dative.
%% A VERB WITH ITS OWN PRONOUN CROSSES BY THE MEANING THE LESSON GIVES IT SO:
%% `la apertura se ha convertido en el elemento negociador' has BECOME it, and
%% `convierte' is `converts' -- `has converted in the negotiating element'.
%% `The reflexive verb "convierte" means "becomes".' is the line (it also says
%% the verb takes `se' as its own pronoun, as `"equivoca" is reflexive.' does),
%% and every form of the verb with its pronoun reads so: the perfect, the
%% infinitive, the gerund. The meaning is no reflexive one, and the phrase
%% the verb governs is that meaning's (tr_cross/3, '$tr_gov_sense')
tr_verb_across(reflexive(L0), _, _, _, L) :-
    atom(L0), tr_solve(mean_as(L0, L1, reflexive)), !,
    %% (a meaning English too says of oneself keeps the reflexive: `il sindaco si è dato ai servizi'
    %% has dedicated HIMSELF to them, tr_write/4)
    ( en_true_reflexive(L1) -> L = reflexive(L1) ; L = L1 ).
tr_verb_across(L0, A, Comps, Gap, L) :-
    atom(L0), tr_intransitive_meanings(L0, Is), !,
    (   ( Gap == yes ; memberchk(A, [passive, passive_perfect])
        ; member(C, Comps), tr_object_comp(C), \+ tr_dative_here(L0, C, Comps) )
    ->  tr_lexeme_across(L0, english, L)
    ;   Is = [L|_]
    ).
%% A VERB THE LESSON ALSO CALLS A MODAL IS THE MODAL BEFORE AN INFINITIVE:
%% `deve' is `owes' and `must', and `La terapia deve essere attivata' owed
%% where it must -- a meaning shaped like a third person comes first in a
%% verb's place (tr_english_shaped/3), and no modal's ever is.
%% ... AND BEFORE A PERFECT INFINITIVE: `las huellas de los pasos que debían
%% haber dado anteriormente' are the steps they MUST have taken, and read as
%% `owes' English said that owed to have given
%% ... AND WITH AN ADVERB BETWEEN THEM: `gli astronauti devono poi
%% concludere la preparazione' must then finish it -- the infinitive was
%% the first complement only with nothing before it, and English said the
%% astronauts owed to conclude
tr_verb_across(L0, _, Comps, _, L) :-
    tr_inf_after_advs(Comps, I0), ( I0 = inf(_) ; I0 = infx(_, _, _) ),
    atom(L0), tr_class_of(L0, modal), tr_meanings_of(L0, english, modal, Ms),
    member(L, Ms), en_modal_out(L, _, _), !.
%% A VERB BEFORE A GERUND CROSSES BY THE MEANING THE LESSON GIVES IT THERE:
%% `Inglaterra ... seguirá describiéndose como ...' will go on describing
%% itself, and `sigue' is `follows' first -- `will follow describing itself'
%% in English and `seguirà descrivendosi' in Italian, which says nothing.
%% `The progressive verb "sigue" means "continues".' is the line, the shape
%% `The intransitive verb ...' has, and the meaning is kept as mean_as(Word,
%% Meaning, progressive) (tr_mean_links/2)
tr_verb_across(L0, _, Comps, _, L) :-
    atom(L0), tr_first_comp(Comps, ger(_, _)), tr_solve(mean_as(L0, L, progressive)), !.
%% A VERB BEFORE A CLAUSE OF `THAT' CROSSES BY THE MEANING THE LESSON GIVES IT
%% THERE: `los tributos suponen el 50%' is what they represent, and `supongo
%% que viene', `se supone que ...' what is supposed -- the dictionary's first
%% meaning for `suponer', which is the minority one in a newspaper: eleven of
%% the twelve sentences with it in the treebank's development part are
%% `supone una limitación' or `no supone la adición aritmética', represents or
%% entails. `The clausal verb "supone" means "supposes".' is the line, and the
%% first meaning the lesson gives is the one anywhere else
tr_verb_across(L0, _, Comps, _, L) :-
    atom(L0), memberchk(that(_), Comps), tr_solve(mean_as(L0, L, clausal)), !.
%% A VERB WITH A SPAN OF TIME AND AN OBJECT CROSSES BY THE MEANING THE LESSON GIVES
%% IT THERE: `Un centenar de pasajeros esperó siete horas la salida de un avión' waited
%% seven hours for it, and `espera' is `expects' first -- `expected seven hours the
%% departure'. `The durative verb "espera" means "waits for".' is the line, and English
%% writes the span after the object, `waited for the departure ... for seven hours'
%% (tr_comps_out/7)
tr_verb_across(L0, _, Comps, _, L) :-
    atom(L0), memberchk(at_time(Sp), Comps), tr_span_source(Sp), memberchk(obj(_), Comps), tr_solve(mean_as(L0, L, durative)), !.
%% A VERB BEFORE AN INFINITIVE CROSSES BY THE MEANING THE LESSON GIVES IT THERE:
%% `trata de convencer' tries to convince, and `trata' is `treats' first -- `treats
%% to convince' in English, and Italian's `tratta convincere'. `The infinitival
%% verb "trata" means "tries".' is the line, and the verb takes its `de' before the
%% infinitive as `"trata" takes "de" before the infinitive.' says
%% (and before an infinitive with the word the verb takes before it: `han renunciado a visitar las playas' have GIVEN
%% UP visiting them, where it was `have renounced to visit')
tr_verb_across(L0, _, Comps, _, L) :-
    atom(L0), tr_first_comp(Comps, I), ( I = inf(_) ; I = infx(_, _, _) ; I = ainf(_, _) ), tr_solve(mean_as(L0, L, infinitival)), !.
%% A VERB WITH A PERSON FOR ITS OBJECT CROSSES BY THE MEANING THE LESSON GIVES IT THERE: `la Bx ha investito la
%% ragazza' ran the girl over, and `investe' is `invests' first, the money's -- `has invested the girl' in English, and
%% Spanish's `ha invertido la niña'. `The personal verb "investe" means "runs over".' is the line (tr_mean_links/3), and
%% the participle said of a person crosses so too (`la ragazza investita a Torvaianica', tr_cross_np/2)
tr_verb_across(L0, _, Comps, _, L) :-
    tr_personal_obj(Comps, NP), tr_personal_here(L0, NP, L1), !, L = L1.
tr_verb_across(L0, _, _, _, L) :- tr_lexeme_across(L0, english, L).
tr_dative_here(L0, opron(_), Comps) :- memberchk(subj_here, Comps), tr_solve(intransitive(L0)), !.

%% the object a verb's personal meaning asks for: the first complement, or the one after a second participle joined to
%% the verb, which they share -- `ha investito e ucciso Sara Folino' ran her over and killed her
tr_personal_obj(Comps, NP) :- tr_first_comp(Comps, obj(NP)), !.
tr_personal_obj([cnj(_), pred(_), obj(NP)|_], NP).
%% ... AND AN INFINITIVE, A PERFECT ONE OR A SECOND PARTICIPLE WITH A PERSON AFTER IT CROSSES SO TOO: `vuole investire
%% la ragazza' wants to run her over, `accusato di aver investito e ucciso Sara Folino' of having run her over and
%% killed her -- crossed by the first meaning they were `invertir a la niña' and `invested and killed'
tr_personal_comp(inf(L0), Cs, inf(L)) :- tr_personal_obj(Cs, NP), tr_personal_here(L0, NP, L).
tr_personal_comp(infx(L0, A, []), Cs, infx(L, A, [])) :- tr_personal_obj(Cs, NP), tr_personal_here(L0, NP, L).
tr_personal_comp(pred(L0), [obj(NP)|_], pred(L)) :- tr_personal_here(L0, NP, L).
%% (in a front too, whose complements travel as fr/1: `Per difendere il fratello, Said, accusato di aver investito e
%% ucciso Sara Folino a Torvajanica, ...')
tr_personal_comp(fr(C0), Cs, fr(C)) :- C0 \= fr(_), tr_unfronted(Cs, Us), tr_personal_comp(C0, Us, C).
tr_unfronted([], []).
tr_unfronted([X|Xs], [Y|Ys]) :- ( X = fr(Y) -> true ; Y = X ), tr_unfronted(Xs, Ys).
tr_personal_here(L0, NP, L) :-
    atom(L0), nb_getval('$tr_personal', PLs), memberchk(L0, PLs),
    tr_person_object(NP), tr_solve(mean_as(L0, L, personal)), !.
%% a person: a name, or a noun the lesson calls a person or animate, with what a phrase hangs on it
tr_person_object(name(_)).
tr_person_object(rel(NP, _, _)) :- tr_person_object(NP).
tr_person_object(rc(NP, _, _)) :- tr_person_object(NP).
tr_person_object(with(NP, _)) :- tr_person_object(NP).
tr_person_object(np(_, _, _, w(W, _), _)) :-
    atom(W), tr_lexeme(foreign, W, L, _), ( tr_holds(person(L)) ; tr_holds(animate(L)) ), !.

tr_intransitive_meanings(L, Is) :- findall(M, tr_solve(mean_as(L, M, intransitive)), Is), Is \== [].

%% the first complement past the adverbs and what stands in front -- and past the mark of a
%% quotation that opens on the verb (vq, vqp): `las medidas "deben respetar los principios"' must
%% respect them, and with the mark first English said the measures owed to respect them
tr_inf_after_advs([C|Cs], I) :- ( C = adv(_) ; tr_front_comp(C) ; C == vq ; C == vqp ), !, tr_inf_after_advs(Cs, I).
tr_inf_after_advs([I|_], I).

%% the first complement after the verb, past what stands in front of the
%% clause and the verb's own pronouns
tr_first_comp([C|Cs], F) :- ( tr_front_comp(C) -> tr_first_comp(Cs, F) ; F = C ).
tr_front_comp(fr(_)).
tr_front_comp(frn(_)).
tr_front_comp(frc(_)).
tr_front_comp(opron(_)).
tr_front_comp(scomma).
%% (and the marks of a quotation the clause carries: `"No pienso hacerlo", dice Pedro' is I do not INTEND to do it,
%% and with qe first the infinitive was no first complement, `I do not think to make him')
tr_front_comp(qs).
tr_front_comp(qe).
tr_front_comp(vq).
tr_front_comp(vqc).

%% a complement that is the verb's object -- never a pronoun the reader
%% marked as the dative
tr_object_comp(obj(_)).
tr_object_comp(opron(W)) :- W \= dat(_).
tr_object_comp(oc(_, _)).
tr_object_comp(that(_)).
tr_object_comp(fr(C)) :- tr_object_comp(C).
tr_object_comp(frc(C)) :- tr_object_comp(C).
tr_object_comp(frn(C)) :- tr_object_comp(C).

%% THE COPULA OF A STATE IS NOT THE COPULA, and the IR keeps them apart:
%% `Stiamo a pezzi' is Spanish's `Estamos destrozados' and never `Somos'.
%% Both languages mean `is' by two words, and the one the lesson calls the
%% AUXILIARY (the progressive's `sta', `está') is the state's when it has no
%% gerund after it. The lexeme travels as state(is): English writes `is',
%% and a lesson writes the word it says marks the state (`The auxiliary
%% "está" marks the state.') or, saying nothing, its plain copula -- which
%% is Italian's `sono distrutti' for Spanish's `están destrozados'.
tr_state_lexeme(L) :- atom(L), tr_solve(auxiliary(L)), tr_solve(mean(L, is)), !.

tr_state_word(W) :- tr_solve(mark(W, state)), !.
%% ... AND IT STANDS FOR THE PLAIN COPULA only where the lesson gives it a
%% plural and a past, so that a clause in any number and tense can be written
%% with it: a lesson that names the word and nothing else of it would refuse
%% what the copula wrote, `mentre eravamo nella casa'
tr_state_plain(W) :-
    tr_state_word(W), tr_solve(plural_of(_, W)), tr_solve(past_of(_, W)), !.

%% the connector of a join, across: a comma as itself, a word by its meaning
tr_cross_connector(_, comma, comma) :- !.
tr_cross_connector(_, nonlyj(Also, C), nonlyj(Also, C)) :- !.
tr_cross_connector(_, w(',', lcomma), w(',', lcomma)) :- !.
tr_cross_connector(_, w(',', acomma), w(',', acomma)) :- !.
tr_cross_connector(_, M, M) :- atom(M), memberchk(M, [semicolon, colon, endquote, endquote_comma, endquote_plain, endquote_plain_comma, endquote_name_comma, dash, dashes, reported, aside]), !.
tr_cross_connector(Side, w(W, C), w(T, C)) :-
    ( Side == english -> T = W ; tr_lexeme(foreign, W, L, _), tr_meanings_of(L, english, conjunction, [T|_]) ), !.
tr_cross_connector(Side, wc(W0), wc(W)) :- !, tr_cross_connector(Side, W0, W).
%% the adverb of a clause set off after a subject (tr_insertion_off/4), `thus'
tr_cross_connector(_, so(w(_, C)), so(w(thus, C))) :- !.
%% ... and a reporting clause between two dashes, between the clauses it stands in
tr_cross_connector(Side, dmid(R0), dmid(R)) :- !, tr_cross(Side, R0, R).
%% ... or between two commas, between two quotations
tr_cross_connector(Side, cmid(R0), cmid(R)) :- !, tr_cross(Side, R0, R).
tr_cross_connector(_, subj(w(_, C)), w('so that', C)) :- !.
%% the clause an infinitive and its phrase of `of' made (tr_as_inf_fix/3), `as'
tr_cross_connector(_, asinf(C), w(as, C)) :- !.
%% the word that opens a comment between commas crosses as what it was read
%% as: `come si dice a Napoli' is as they say in Naples, and by `come''s
%% first meaning it was `how', which Spanish wrote `cómo se dice'
tr_cross_connector(_, cmt(w(_, C)), cmt(w(as, C))) :- !.

%% the English side crosses nothing, and normalises one thing: a `which'
%% question carries the words of its phrase, and the IR carries the phrase
tr_cross_which(s(Asked0, Subject0, G, Comps), s(Asked, Subject, G, Comps)) :-
    tr_cross_which_asked(Asked0, Asked),
    (   Subject0 = asked(_), Asked = subject(Q) -> Subject = asked(Q)
    ;   Subject = Subject0
    ).

tr_cross_which_asked(none, none) :- !.
tr_cross_which_asked(pp(P, which(Ws, C)), pp(P, which_np(NP, C))) :- !, tr_which_phrase(english, Ws, NP).
tr_cross_which_asked(A0, A) :- A0 =.. [Kind, which(Ws, C)], !, tr_which_phrase(english, Ws, NP), A =.. [Kind, which_np(NP, C)].
tr_cross_which_asked(A, A).

%% what is asked, across: the question word by what it asks for, or the
%% phrase of a `which' read and crossed
tr_cross_asked(none, none) :- !.
tr_cross_asked(pp(w(P, PC), Q0), pp(w(PT, PC), Q)) :- !, tr_prep_across(P, PT), tr_cross_q(pp, Q0, Q).
tr_cross_asked(A0, A) :- A0 =.. [Kind, Q0], tr_cross_q(Kind, Q0, Q), A =.. [Kind, Q].

tr_cross_q(_, which(Ws, C), which_np(NP, C)) :- !, tr_side_here(Side), tr_which_phrase(Side, Ws, NP0), tr_cross_which_np(NP0, NP).
tr_cross_q(_, whichp(N, C), whichp(N, C)) :- !.
tr_cross_q(Kind, w(Q, C), w(QT, C)) :- tr_question_across(english, Kind, Q, QT).

%% THE PHRASE A `which' ASKS WITH MAY CARRY ITS OWN `di' PHRASES: `in che
%% razza di mondo' is what kind of world, and read as a phrase with no
%% preposition in it the question was refused -- the subject reader's
%% with/2, crossed and written as a subject's is
tr_which_phrase(Side, Ws, NP) :- tr_np(Side, Ws, NP), !.
tr_which_phrase(Side, Ws, with(NP, PPs)) :- tr_subject(Side, none, Ws, _, _, with(NP, PPs)).
tr_cross_which_np(with(NP0, PPs0), with(NP, PPs)) :- !, tr_cross_np(NP0, NP), tr_cross_comps(PPs0, PPs).
tr_cross_which_np(NP0, NP) :- tr_cross_np(NP0, NP).
tr_which_np_out(To, with(NP, PPs), Outs, Noun, Number) :- !, tr_subject_out(To, with(NP, PPs), Outs, _, Number, Noun).
tr_which_np_out(To, NP, Outs, Noun, Number) :- tr_np_out(To, NP, Outs, Noun, Number).

%% the subject, across: the question word when the subject is what is
%% asked (already crossed), `there' as itself, a name as itself, and the
%% person and number of a pronoun or of nobody kept as they were read
tr_cross_subject(subject(Q), asked(_), asked(Q)) :- !.
tr_cross_subject(_, none, none) :- !.
tr_cross_subject(_, gap, gap) :- !.
tr_cross_subject(_, gap(P, N), gap(P, N)) :- !.
tr_cross_subject(_, there, there) :- !.
tr_cross_subject(_, name(W0), name(W)) :- !, ( tr_name_across(W0, W1) -> W = W1 ; W = W0 ).    % (a name's meaning: tr_cross_np/2)
tr_cross_subject(_, adjs(As0), adjs(As)) :- !, tr_cross_adjectives(As0, As).
tr_cross_subject(_, null(P, N), null(P, N)) :- !.
tr_cross_subject(_, addressee(N), addressee(N)) :- !.
tr_cross_subject(_, impersonal, impersonal) :- !.
tr_cross_subject(_, pronoun(P, N, w(W, C)), pronoun(P, N, w(T, C))) :- !, tr_pronoun_across(english, subject, w(W, C), P, N, T).
tr_cross_subject(_, every(w(_, C)), pronoun(third, singular, w(everything, C))) :- !.   % (tr_all_copula_fix/3)
tr_cross_subject(A, nei(Co0), nei(Co)) :- !, tr_cross_subject(A, Co0, Co).
tr_cross_subject(A, advp(w(W, C), S0), advp(w(T, C), S)) :- !, tr_word_across(w(W, lower), english, adverb, T), tr_cross_subject(A, S0, S).
tr_cross_subject(A, one(Co0), one(Co)) :- !, tr_cross_subject(A, Co0, Co).
tr_cross_subject(A, co(both, S1, S2), co(both, T1, T2)) :- !, tr_cross_subject(A, S1, T1), tr_cross_subject(A, S2, T2).
tr_cross_subject(A, co(C0, S1, S2), co(C, T1, T2)) :- !,
    tr_side_here(Side), tr_cross_connector(Side, C0, C), tr_cross_subject(A, S1, T1), tr_cross_subject(A, S2, T2).
tr_cross_subject(_, with(NP0, PPs0), NP) :- !, tr_cross_np(with(NP0, PPs0), NP).
tr_cross_subject(_, infs(L0, Cs0), infs(state(L), Cs)) :- tr_state_lexeme(L0), !,    % `stare in mezzo alla gente'
    tr_lexeme_across(L0, english, L), tr_cross_comps(Cs0, Cs).
tr_cross_subject(_, infs(cl(L0, Cls0), Cs0), infs(cl(L, Cls), Cs)) :- !,
    tr_lexeme_across(L0, english, L), tr_cross_comps(Cs0, Cs),
    findall(X, ( member(Cl, Cls0), tr_cross_comp(opron(Cl), opron(X)) ), Cls).
tr_cross_subject(_, infs(L0, Cs0), infs(L, Cs)) :- !, tr_lexeme_across(L0, english, L), tr_cross_comps(Cs0, Cs).
tr_cross_subject(_, infs(L0, Cs0, C), infs(L, Cs, C)) :- !, tr_lexeme_across(L0, english, L), tr_cross_comps(Cs0, Cs).
tr_cross_subject(_, NP0, NP) :- tr_cross_np(NP0, NP).

%% a phrase, across: the noun's lexeme in English, the determiner as the
%% word of its kind (never the form -- the number inflects it on the way
%% out), a number word, and each adjective's first meaning
tr_cross_np(gov(V0, NP0), gov(V, NP)) :- !,
    ( tr_global('$tr_gov_sense', V0-V1) -> V = V1 ; tr_lexeme_across(V0, english, V) ),
    tr_cross_np(NP0, NP).
%% A NOUN OF A ROUND COUNT BEFORE `de' AND A BARE PLURAL IS ABOUT THAT MANY: `Un
%% centenar de pasajeros esperó siete horas' is about a hundred passengers, as
%% `unos cien pasajeros' is (adv_num/2, which tr_np/3 reads it as), and crossed
%% as the noun and its phrase of `of' it was `A hundred of passengers' and `a
%% twenty of travellers ... was on the verge'. The noun's English meaning is a
%% round number (en_round_count/1); after `the' it is the count itself (`el
%% centenar de reclamaciones' is the hundred complaints); and the phrase is the
%% plural's, so each writer agrees with the plural (and a clause joined after
%% it with nobody named is the plural's too, tr_count_gap/3)
tr_cross_np(with(np(det(article, A0, w(_, AC)), none, [], w(NW, NC), singular), [pp(w(P, _), PNP0)|More0]), NP) :-
    tr_count_head(PNP0, np(none, none, _, _, plural), _, _),
    atom(NW), atom(A0), atom(P), tr_side_here(foreign), tr_means_of(P),
    tr_noun_lexeme(english, NW, singular, _, N), en_round_count(N),
    tr_word_across(w(A0, lower), english, article, AT), memberchk(AT, [a, the]), !,
    (   AT == a -> Det = none, Num = adv_num(w(about, lower), w(N, NC))
    ;   Det = det(article, the, w(the, AC)), Num = w(N, NC)
    ),
    tr_cross_np(PNP0, PNP),
    tr_count_head(PNP, np(none, none, Adjs, Noun, plural), np(Det, Num, Adjs, Noun, plural), NP1),
    ( More0 == [] -> NP = NP1 ; tr_cross_comps(More0, More), NP = with(NP1, More) ).
%% (a share of a GROUP that does something is a share of the people it is:
%% `Parte del pasaje volaba por placer', tr_part_of_group/1, and the group's
%% collective meaning is the one crossed)
tr_cross_np(with(NP0, PPs0), with(NP, PPs)) :- !,
    ( PPs0 = [PP|_], tr_relational_np(NP0, PP, NP) -> true ; tr_cross_np(NP0, NP) ),
    ( tr_global('$tr_doer', yes), tr_partitive_head(NP0), PPs0 = [pp(_, _)|_] -> tr_cross_comps(PPs0, PPs)
    ; tr_as_doer_not(tr_cross_comps(PPs0, PPs)) ).
tr_cross_np(ncl(NP0, S0), ncl(NP, S)) :- !,
    tr_cross_np(NP0, NP), tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_np(nrc(NP0, ro(Co0, Role0), S0), nrc(NP, ro(Co, Role), S)) :- !,
    tr_side_here(Side), tr_cross_connector(Side, Co0, Co),
    tr_cross_np(rc(NP0, Role0, S0), rc(NP, Role, S)).
tr_cross_np(nrc(NP0, Role0, S0), nrc(NP, Role, S)) :- !, tr_cross_np(rc(NP0, Role0, S0), rc(NP, Role, S)).
tr_cross_np(what_np(NP0), what_np(NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_np(ninf(F0), ninf(F)) :- !, tr_lexeme_across(F0, english, F).
tr_cross_np(nq(Det0, w(W, C)), nq(Det, w(T, C))) :- !,
    tr_cross_det(Det0, Det), tr_word_across(w(W, lower), english, adverb, T).
tr_cross_np(rc(NP0, Role0, S0), rc(NP, Role, S)) :- !,
    tr_cross_np(NP0, NP), tr_side_here(Side),
    (   Role0 = pp(w(P, C)) -> tr_word_across(w(P, lower), english, preposition, PT), Role = pp(w(PT, C))
    ;   Role = Role0
    ),
    %% a relative word that is the object is the clause's object
    (   Role0 == object
    ->  nb_setval('$tr_obj_gap', yes),
        ( tr_cross(Side, S0, S1) -> nb_setval('$tr_obj_gap', no) ; nb_setval('$tr_obj_gap', no), fail )
    %% (the phrase a subject's relative clause hangs on owns what its possessives name, as a subject does: `un tema che
    %% riveste un'enorme importanza anche per le sue notevoli ricadute' is ITS spin-offs, where `his' was written)
    ;   Role0 == subject
    ->  tr_global('$tr_rc_head', H0), nb_setval('$tr_rc_head', NP0),
        ( tr_cross(Side, S0, S1) -> nb_setval('$tr_rc_head', H0) ; nb_setval('$tr_rc_head', H0), fail )
    ;   tr_cross(Side, S0, S1)
    ),
    tr_unresume(Role, S1, S2),
    tr_quantity_gap(NP, Role, S2, S).
%% (and a month with no day, its year after it, takes no article: `nel gennaio 1980' is in January 1980, and `nel
%% settembre del settantanove' in September '79 -- the lesson's languages say such a month with its article, and it
%% came out `in the January 1980' and `en el enero de 1980')
tr_cross_np(app(NP0, K, Y0), app(NP, K, Y)) :-
    memberchk(K, [year, yearw]), NP0 = np(det(article, _, _), none, Adjs0, N0, Nb), tr_month(foreign, N0), !,
    tr_cross_np(app(np(none, none, Adjs0, N0, Nb), K, Y0), app(NP, K, Y)).
tr_cross_np(app(NP0, year, Y), app(NP, year, Y)) :- !, tr_cross_np(NP0, NP).     % a year is its digits everywhere
tr_cross_np(app(NP0, label, N), app(NP, label, N)) :- !, tr_cross_np(NP0, NP).    % and so is a label
tr_cross_np(app(NP0, apposed, N), app(NP, apposed, N)) :- !, tr_cross_np(NP0, NP).  % and a name
tr_cross_np(app(NP0, numbered, N), app(NP, numbered, N)) :- !, tr_cross_np(NP0, NP).  % and a noun's number
tr_cross_np(app(NP10, part, NP20), app(NP1, part, NP2)) :- !, tr_cross_np(NP10, NP1), tr_cross_np(NP20, NP2).   % a day and its part
tr_cross_np(app(NP10, wdate, NP20), app(NP1, wdate, NP2)) :- !, tr_cross_np(NP10, NP1), tr_cross_np(NP20, NP2).  % a day and its date
tr_cross_np(app(NP0, yearw, w(Y0, C)), app(NP, yearw, w(Y, C))) :- !,                  % a year in words
    tr_cross_np(NP0, NP), tr_word_across(w(Y0, lower), english, number, Y).
tr_cross_np(app(NP0, title, Cs0), app(NP, title, Cs)) :- !, tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
tr_cross_np(app(NP0, Kind, K), app(NP, Kind, Inner)) :- !,
    tr_cross_np(NP0, NP), tr_aside_inner(K, Inner0), tr_aside_participle(NP0, Inner0, Inner).
%% A BARE NOUN THAT IS ITS OWN PLURAL TAKES THE NUMBER OF THE PARTICIPLE AFTER IT: `un ciclo di film dedicati' is a
%% cycle of FILMS dedicated -- `"film" is the plural of "film".', and read in the singular the phrase came out
%% `un ciclo de película dedicadas', the participle's own plural beside it (agrn/1, tr_rel_number/5)
tr_cross_np(rel(np(none, Q, A, w(W, C), singular), L0, Cs0), NP) :-
    select(agrn(plural), Cs0, Cs1), atom(W), tr_lexeme(foreign, W, _, plural), !,
    tr_cross_np(rel(np(none, Q, A, w(W, C), plural), L0, Cs1), NP).
tr_cross_np(rel(NP0, L0, Cs0), rel(NP, L, Cs)) :- !,
    tr_cross_np(NP0, NP),
    ( tr_personal_here(L0, NP0, L1) -> L = L1 ; tr_lexeme_across(L0, english, L) ),     % (tr_verb_across/5)
    tr_cross_comps(Cs0, Cs).
tr_cross_np(adv(w(A, C)), adv(w(AT, C))) :- !, tr_word_across(w(A, lower), english, adverb, AT).
tr_cross_np(pp(w(P, C), NP0), pp(w(PT, C), NP)) :- !, tr_prep_across(P, PT), tr_cross_np(NP0, NP).  % `come in tutti i parchi'
%% A NAME THE LESSON GIVES A MEANING CROSSES BY IT, and every language writes its own: `la vida
%% política en Moscú' is in Moscow, and Italian's `a Mosca' (`The name "moscú" means "Moscow".',
%% `The name "mosca" means "Moscow".', mean_as/3 under the class name). A name with none is
%% itself in every language, as it always was: `Boris Yeltsin', `Cheri Leberknight'
tr_cross_np(name(W0), name(W)) :- !, ( tr_name_across(W0, W1) -> W = W1 ; W = W0 ).
tr_cross_np(all(w(_, C), NP0), all(w(all, C), NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_np(nform(NP0), nform(NP)) :- !, tr_cross_np(NP0, NP).          % (tr_form_of_phrase/2)
tr_cross_np(np(Det0, Num0, Adjs0, elided(G), Number), np(Det, Num, Adjs, elided(G), Number)) :- !,
    tr_cross_det(Det0, Det), tr_cross_num(Num0, Num), tr_cross_adjectives(Adjs0, Adjs).
tr_cross_np(ago(NP0, w(A, C)), ago(NP, w(AT, C))) :- !,
    tr_cross_np(NP0, NP), tr_word_across(w(A, lower), english, adverb, AT).
%% (`well' before a count is how many: `ben 11 veleni', as many as 11 poisons)
tr_cross_np(advp(w(A, C), NP0), advp(w('as many as', C), NP)) :-
    NP0 = np(_, Num, _, _, _), Num \== none, atom(A), tr_count_adverb(A), !, tr_cross_np(NP0, NP).
tr_cross_np(advp(w(A, C), NP0), advp(w(AT, C), NP)) :- !,
    tr_word_across(w(A, lower), english, adverb, AT), tr_cross_np(NP0, NP).
tr_cross_np(ell(Det0, G, Number, none), ell(Det, G, Number, none)) :- !, tr_cross_det(Det0, Det).
tr_cross_np(ell(Det0, G, Number, rel(Role0, S0)), ell(Det, G, Number, rel(Role, S))) :- !,
    tr_cross_det(Det0, Det),
    tr_cross_np(rc(np(none, none, [], elided(G), Number), Role0, S0), rc(_, Role, S)).
tr_cross_np(ell(Det0, G, Number, PP0), ell(Det, G, Number, PP)) :- !,
    tr_cross_det(Det0, Det), tr_cross_comp(PP0, PP).
tr_cross_np(pronoun(w(W, C)), pronoun(w(T, C))) :- !, tr_pronoun_across(english, oblique, w(W, C), _, _, T).
tr_cross_np(padj(P0, A0), padj(P, A)) :- !, tr_cross_np(P0, P), tr_cross_adjective(A0, A).
tr_cross_np(nonly(A0, B0, Also), nonly(A, B, Also)) :- !,
    tr_cross_subject(none, A0, A), tr_cross_subject(none, B0, B).
tr_cross_np(co(C0, N1, N2), co(C, T1, T2)) :- !,
    tr_side_here(Side), tr_cross_connector(Side, C0, C), tr_cross_np(N1, T1), tr_cross_np(N2, T2).
%% the article a lesson puts before a year is its language's, and comes off
tr_cross_np(np(det(article, _, _), none, [], w(Y, C), singular), np(none, none, [], w(Y, C), singular)) :-
    tr_year(Y), once(tr_solve(take(_, year))), !.
%% a name crosses as itself, gender and all: nothing in it is a word of any
%% language, so there is nothing to look up
tr_cross_np(np(Det0, Num0, Adjs0, named(G, Ws0), Number), np(Det, Num, Adjs, named(G, Ws), Number)) :- !,
    %% (a named thing of one word crosses by the meaning the lesson gives the name, as a name does:
    %% `el Kremlin' is `il Cremlino')
    %% ... never a CITY'S name after an article, which is the club named after it: `contro il Napoli' is
    %% the football club, and crossed by the city's name it was `against the Naples', `contra el Nápoles'
    %% (a country keeps its article in the lesson's languages and crosses: `la Francia' is France)
    (   Ws0 = [w(W0, WC)], \+ ( Det0 = det(article, _, _), tr_city_name(W0) ), tr_name_across(W0, E)
    ->  Ws = [w(E, WC)]
    ;   Ws = Ws0
    ),
    tr_cross_det(Det0, Det), tr_cross_num(Num0, Num), tr_cross_adjectives(Adjs0, Adjs).
%% A TIME IN DIGITS AND THE NOUN FOR HOURS AFTER IT ARE THE HOUR: `tenía previsto
%% despegar ayer a las 11.10 horas' took off at 11.10, as `a las cinco' is at
%% five, and crossed with the noun it was `to the 11.10 hours' and `alle 11.10
%% ore'. The noun is left out as it is after a count of the clock (elided/1),
%% and each writer writes its own hour
tr_cross_np(np(det(article, A0, W0), w(MW, MC), [], w(NW, _), plural), np(Det, w(M, MC), [], elided(feminine), plural)) :-
    atom(NW), tr_side_here(foreign), tr_noun_lexeme(english, NW, plural, _, hour),
    tr_cross_num(w(MW, MC), w(M, _)), en_clock_digits(M), !,
    tr_cross_det(det(article, A0, W0), Det).
%% A GROUP NOUN THAT DOES SOMETHING IS THE PEOPLE IT IS: `el pasaje destiló tanta
%% indignación', `Parte del pasaje volaba por placer' and `reclamaciones cursadas
%% por el pasaje' are the passengers, where `el pasaje se humanizará cerrándolo
%% al tráfico' and `el pasaje de Vintró' are a passage. The lesson states the
%% people as the noun's collective meaning (`The collective noun "pasaje" means
%% "passengers".'), the plural of an English noun, and the phrase crosses as that
%% noun in the plural: a subject of a verb that is no reflexive, the agent of a
%% participle and the whole a share of such a subject is of ('$tr_doer',
%% tr_as_doer/1)
tr_cross_np(np(Det0, Num0, Adjs0, w(NW, NC), singular), np(Det, Num, Adjs, w(Noun, NC), plural)) :-
    tr_global('$tr_doer', yes), atom(NW), tr_side_here(foreign),
    tr_lexeme(foreign, NW, L, singular), atom(L), tr_solve(mean_as(L, E, collective)),
    ( en_plural_pair(Noun, E) -> true ; atom_concat(Noun, s, E), en_plural_noun(Noun, E) ), !,
    tr_cross_det(Det0, Det), tr_cross_num(Num0, Num),
    tr_cross_adjectives(Adjs0, Adjs1), tr_carry_agreement(Adjs0, Adjs1, plural, Adjs).
tr_cross_np(np(Det0, Num0, Adjs0, w(NW, NC), Number), np(Det, Num, Adjs, w(Noun, NC), Number)) :-
    (   tr_gendered_noun(Det0, NW, Number, Noun0) -> Noun = Noun0
    ;   tr_det_gendered_noun(Det0, NW, Number, Noun1) -> Noun = Noun1
    ;   tr_adj_gendered_noun(Det0, Adjs0, NW, Number, Noun2) -> Noun = Noun2
    ;   Det0 == none, Number == plural, tr_sample_noun(NW) -> Noun = sample
    ;   tr_noun_lexeme(english, NW, Number, _, Noun)
    ),
    %% the article before a day of the week comes off where the lesson gives
    %% it one (`The article "el" takes the day.'), as a year's does: the
    %% writer puts the language's own back (tr_np_out/5)
    (   Det0 = det(article, _, _), Number == singular, tr_weekday(Noun), once(tr_solve(take(_, day)))
    ->  Det = none
    %% (a husband's possessive is a woman's: `Marta Toledo, ..., y su marido, John Ross' is HER husband, and the
    %% lesson's first meaning of `su' wrote `his husband')
    ;   Noun == husband, Det0 = det(possessive, DL, w(_, DC)), tr_side_here(foreign), tr_solve(mean(DL, her))
    ->  Det = det(possessive, her, w(her, DC))
    ;   tr_cross_det(Det0, Det)
    ),
    tr_cross_num(Num0, Num),
    tr_cross_adjectives(Adjs0, Adjs1),
    tr_carry_agreement(Adjs0, Adjs1, Number, Adjs),
    tr_fem_person_note(Det0, NW, Number, Noun).
%% the head phrase of a phrase with its participle or relative clause, and the
%% same with another head
tr_count_head(np(D, M, A, N, B), np(D, M, A, N, B), H, H) :- !.
tr_count_head(rel(NP0, L, Cs), H0, H, rel(NP, L, Cs)) :- !, tr_count_head(NP0, H0, H, NP).
tr_count_head(rc(NP0, R, S), H0, H, rc(NP, R, S)) :- tr_count_head(NP0, H0, H, NP).
%% A NOUN THAT CAN SAY A SAMPLE SAYS IT IN THE PLURAL WITH NO DETERMINER: `Ningún deportista español ... envía muestras a
%% su laboratorio', `El IMIM sólo controla muestras remitidas por el COI' -- samples, where `muestra' is the newspaper's
%% exhibition first (`las 10 piezas más relevantes de la muestra', which keeps it: a determiner says which show)
tr_sample_noun(NW) :-
    atom(NW), tr_side_here(foreign), tr_lexeme(foreign, NW, L, _), atom(L), tr_solve(mean(L, sample)),   % (asked first: few nouns have it)
    tr_meanings_of(L, english, noun, [M1|Ms]), M1 \== sample, memberchk(sample, Ms), !.
%% ... AND `MANY OF WHICH' IS ITS CLAUSE'S SUBJECT: `lo scavo dei rii, molti dei quali non venivano
%% ripuliti da trent'anni' -- many of which were not cleaned, and with nobody named in the clause
%% English wrote `many of which they were not cleaned'. A word of quantity whose phrase of `of' is the
%% relative, and a clause in its number with no subject of its own
tr_quantity_gap(pronoun(w(Q, _)), pp(w(of, _)), s(A, null(third, N), G, Cs), s(A, gap(third, N), G, Cs)) :-
    memberchk(Q, [many, some, few, several, all, most, none, both, each]), !.
tr_quantity_gap(_, _, S, S).
%% ... AND `TO WHOM' NEEDS NO PRONOUN FOR THE SAME PERSON IN ITS CLAUSE:
%% Spanish says `los abogados, a quienes se les retiene el 20%' with the
%% pronoun taken up again, and Italian wrote `a cui gli si trattiene'; the
%% person is the relative word, and a verb has one dative
tr_unresume(pp(w(to, _)), s(A, Su, G, Cs0), s(A, Su, G, Cs)) :- !,
    findall(C, ( member(C, Cs0), C \= opron(dat(_)) ), Cs).
tr_unresume(_, S, S).
%% A PARTICIPLE IN AN ASIDE THAT AGREES WITH THE PHRASE BEFORE IT IS SAID OF
%% THE NOUN AS WRITTEN: `esta obra, presupuestada en 60 millones' is `questo
%% lavoro, preventivato' -- the source's feminine is not the Italian noun's,
%% and agreeing with it it came out `preventivata'. Where the source form
%% agrees with another noun (`conocido', the man in charge's, after `la
%% seguridad') its gender stays, agr/1, and the writer agrees with that.
tr_aside_participle(np(_, _, _, w(NW, _), N), part(L, [agr(G), agrn(N)|Cs]), part(L, [agrn(N)|Cs])) :-
    atom(NW), tr_lexeme(foreign, NW, NL, _), tr_gender(NL, G), !.
tr_aside_participle(_, Inner, Inner).
%% the name's meaning, for tr_cross_np/2 above
%% (its quotation marks kept: `"España ve con simpatía la candidatura"' is `"Spain sees ...', tr_quote_names/3)
tr_name_across(W0, E) :-
    tr_side_here(foreign), atom(W0), tr_downcase_units(W0, L0), tr_unmark(L0, Pre, L, Post),
    tr_solve(mean_as(L, E0, name)), !,
    nb_getval('$tr_xnames', Xs), ( memberchk(E0, Xs) -> true ; nb_setval('$tr_xnames', [E0|Xs]) ),
    ( Pre == '', Post == '', \+ sub_atom(E0, _, _, _, ' ') -> E = E0 ; tr_name_caps(E0, EC), atomic_list_concat([Pre, EC, Post], E) ).
%% (a name in small letters in either text unit: downcase_atom/2 leaves an accented capital alone under
%% bytes, and `África' found no `"áfrica"' there -- tr_lower_codes/2 has the twin)
tr_downcase_units(W, L) :- downcase_atom(W, L0), atom_codes(L0, Cs0), tr_lower_codes(Cs0, Cs), atom_codes(L, Cs).
%% ... AND THE LESSON'S LANGUAGE WRITES ITS OWN WORD ONLY FOR A NAME THE SOURCE CROSSED, or for one an
%% English text named: `los argentinos Guglielminpietro (Milan)' is the club, a name the Spanish lesson does
%% not state (it says `Milán'), and the IR's `Milan', spelled as the English city is, came out `(Milano)'.
%% The names a sentence crossed are noted as it is read ('$tr_xnames', a page's piece at a time), and a
%% name's quotation marks come off for the lesson and go back on its word
tr_name_word_out(W, N) :-
    atom(W), tr_unmark(W, Pre, Core0, Post), downcase_atom(Core0, Core),
    ( nb_getval('$tr_read_side', english) -> true ; nb_getval('$tr_xnames', Xs), memberchk(Core, Xs) ),
    tr_solve(mean_as(N0, Core, name)), !,
    ( Pre == '', Post == '', \+ sub_atom(N0, _, _, _, ' ') -> N = N0 ; tr_name_caps(N0, NC), atomic_list_concat([Pre, NC, Post], N) ).
%% (each word of a name of several with its capital: `(New York, 1991)' was `(New york, 1991)', the capital
%% the writer gives a name set on its first word alone -- but a small word after the first stays small:
%% `durante la reunión del Consejo de Ministros' is the Council of Ministers, and every word with its
%% capital it was `Council Of Ministers' and `Consiglio Dei Ministri')
tr_cap_words(A, C) :-
    atomic_list_concat([W1|Ws], ' ', A), tr_cap(W1, C1),
    findall(WC, ( member(W, Ws), ( tr_name_small_word(W) -> WC = W ; tr_cap(W, WC) ) ), WCs),
    atomic_list_concat([C1|WCs], ' ', C).
%% (a name the lesson calls an acronym goes in capitals, its quotation mark too: `el COI"' is `the IOC"', and with
%% the capital of a name's first letter it was `the Ioc"')
tr_name_caps(N0, NC) :- tr_solve(acronym(N0)), !, upcase_atom(N0, NC).
tr_name_caps(N0, NC) :- tr_cap_words(N0, NC).
tr_name_small_word(W) :-
    memberchk(W, [of, the, and, for, de, del, la, las, los, el, y, e, di, dei, degli, della, delle, dello, del, il, lo, le, gli, da, a, al, en, in]).

tr_unmark(W, Pre, Core, Post) :-
    ( atom_concat('"', W1, W) -> Pre = '"' ; Pre = '', W1 = W ),
    ( W1 \== '', atom_concat(Core, '"', W1) -> Post = '"' ; Post = '', Core = W1 ).
%% A PERSON THE SOURCE NAMES IN THE FEMININE IS ONE IN THE OTHER LANGUAGE TOO: `la diplomática
%% norteamericana Cheri Leberknight' is a woman, and with one English word for both, `diplomat',
%% Italian wrote `il diplomatico americano'. The English noun of a person the lesson states
%% feminine is noted for the sentence ('$tr_fem_persons'), and the writer takes its language's
%% feminine noun for it (tr_noun_lexeme0/5)
tr_fem_person_note(Det0, NW, Number, Noun) :-
    tr_side_here(foreign), atom(NW), atom(Noun),
    tr_lexeme(foreign, NW, L, Number), atom(L), tr_holds(person(L)),
    %% (... and one with no gender of its own after a feminine article: `la versione di una cantante' is a woman
    %% who sings, and Spanish wrote `un cantante', the article of a noun with no gender stated)
    (   tr_stated_gender(L, feminine) -> true
    ;   tr_stated_gender(L, none), Det0 = det(_, DL, w(DW, _)), atom(DW), tr_det_gender(foreign, w(DW, lower), DL, feminine, _)
    ),
    %% (never an animal, whose gender is its word's and says no sex: `è come cavalcare una tigre' rides a
    %% tiger, and as a woman it was `cabalgar a una tigresa')
    \+ tr_fact(animate(L)), !,
    %% (the noun in its number: `dai 70 studenti iscritti ...: una studentessa che indossa la tuta' has the
    %% students and one female student, and noted by the noun alone the 70 were `las 70 alumnas inscritas')
    nb_getval('$tr_fem_persons', Fs), ( memberchk(Noun-Number, Fs) -> true ; nb_setval('$tr_fem_persons', [Noun-Number|Fs]) ).
tr_fem_person_note(_, _, _, _).
%% (a decade after a preposition: tr_cross_comp/2)
tr_cross_decade(np(Det0, w(N, NC), [], elided(_), plural), app(np(Det, none, [], w(year, lower), plural), label, w(N, NC))) :-
    Det0 = det(article, _, _), tr_decade(N), tr_cross_det(Det0, Det).
%% ... AND ONE NAMED IN WORDS: `Alla fine degli anni cinquanta' is at the end of the 50s, and read as the years and an
%% adjective `fifty' it was `the fifty years', which Spanish has no adjective for -- the sentence was refused
tr_cross_decade(np(Det0, none, [w(W, WC)], w(Y, _), plural), app(np(Det, none, [], w(year, lower), plural), label, w(D, WC))) :-
    Det0 = det(article, _, _), atom(W), atom(Y),
    tr_lexeme(foreign, Y, YL, _), tr_solve(mean(YL, year)),
    tr_lexeme(foreign, W, WL, _), tr_solve(mean(WL, E)), en_decade_word(E, D), !, tr_cross_det(Det0, Det).
en_decade_word(twenty, '20'). en_decade_word(thirty, '30'). en_decade_word(forty, '40'). en_decade_word(fifty, '50').
en_decade_word(sixty, '60').  en_decade_word(seventy, '70'). en_decade_word(eighty, '80'). en_decade_word(ninety, '90').
%% a year of two digits said in words, as English writes it: `seventy-nine' is '79, `seventy' '70
en_short_year(W, Y) :-
    atom(W), atomic_list_concat([T, U], '-', W), en_decade_word(T, TD), en_unit_word(U, UD), !,
    sub_atom(TD, 0, 1, _, T1), atomic_list_concat(['\'', T1, UD], Y).
en_short_year(W, Y) :- atom(W), en_decade_word(W, D), !, atomic_list_concat(['\'', D], Y).
%% the nouns English says with `to' and the infinitive after them
en_noun_to_inf(N) :- memberchk(N, [attempt, effort, decision, plan, intention, chance, ability, wish, desire, need, freedom,
                                   permission, willingness, refusal, opportunity, tendency, capacity, promise, obligation,
                                   proposal, temptation, readiness]).
en_unit_word(one, '1'). en_unit_word(two, '2'). en_unit_word(three, '3'). en_unit_word(four, '4'). en_unit_word(five, '5').
en_unit_word(six, '6'). en_unit_word(seven, '7'). en_unit_word(eight, '8'). en_unit_word(nine, '9').

%% AN ADJECTIVE THAT DOES NOT AGREE WITH ITS NOUN IN NUMBER AGREES WITH
%% SOMETHING ELSE, and the writer must keep the number it has: `fuentes del
%% sector conocedoras de la operación' are aware sources, and the reader hangs
%% the adjective on `sector', the nearest noun, so written in the number of
%% THAT noun it was `fonti del settore consapevole'; `un espacio de oficinas
%% anexo' is a space annexed, and `uffici annessi' a plural. The IR carries the
%% adjective's own gender and number, agrd(Gender, Number, Adjective), where
%% the lesson states the form's number outright -- a plural it lists, or a
%% singular that has a plural listed -- and never for an invariable form
%% (`gratis' fits every noun), the writer agreeing it with them
tr_carry_agreement([], [], _, []).
tr_carry_agreement([A0|As0], [A1|As1], NounN, [A|As]) :-
    (   A0 = w(AW, AC), A1 = w(_, AC), AC \== upper, AC \== appos, tr_own_agreement(AW, NounN, G, AN)
    ->  A = agrd(G, AN, A1)
    ;   A = A1
    ),
    tr_carry_agreement(As0, As1, NounN, As).

tr_own_agreement(AW, NounN, G, AN) :-
    tr_side_here(foreign), atom(AW), ( NounN == singular ; NounN == plural ),
    tr_lexeme(foreign, AW, AL, _), atom(AL),
    (   tr_solve(plural_of(AW, AL)), AL \== AW -> AN = plural
    ;   AW == AL, tr_solve(plural_of(PW, AL)), PW \== AL -> AN = singular
    ),
    AN \== NounN,
    ( tr_stated_gender(AL, G0), G0 \== none -> G = G0 ; G = none ), !.

%% the meaning a noun has in the gender its determiner says, where the lesson
%% states the noun in both genders (tr_gender_links/3): the linked meaning
%% of that gender, or else the first meaning linked to no gender -- `la
%% final' is the final and `el final' the end
tr_gendered_noun(det(_, DL, _), NW, Number, Noun) :-
    tr_side_here(foreign),
    tr_lexeme(foreign, NW, L, Number), atom(L), tr_solve(mean_gender(L, _, _)),
    tr_gender(DL, G), G \== none,
    (   tr_solve(mean_gender(L, Noun, G)) -> true
    ;   tr_meanings_of(L, english, noun, Ms), member(Noun, Ms), \+ tr_solve(mean_gender(L, Noun, _))
    ), !.

%% THE LEXEME WHOSE GENDER IS THE DETERMINER'S, where a form is the plural of
%% two: `le posizioni delle parti nel processo' -- `parti' is the plural of
%% `parto', a birth, first in the vocabulary, and of `parte', which is what a
%% party to a case is, and read as the first the parties came out `partos'.
%% `le' is feminine and `parto' is not. Only where the determiner has a gender
%% and a lexeme of the word has the same: nothing else moves.
tr_det_gendered_noun(det(_, DL, _), NW, Number, Noun) :-
    tr_side_here(foreign), atom(DL), tr_gender(DL, G), G \== none,
    tr_lexeme(foreign, NW, L, Number), atom(L), tr_gender(L, G),
    tr_meanings_of(L, english, noun, [Noun|_]), !.
%% ... AND WITH NO DETERMINER, THE GENDER OF THE ADJECTIVE AFTER THE NOUN:
%% `Teatro, arti visive' -- `arti' is the plural of `arto', a limb, first in
%% the vocabulary, and of `arte', and `visive' is feminine; read as the limb
%% the phrase had no word in the other language. A noun of a gender the
%% adjective agrees with, where the lesson gives the adjective one
tr_adj_gendered_noun(none, Adjs, NW, Number, Noun) :-
    tr_side_here(foreign),
    member(A, Adjs), ( A = pre(w(AW, _)) ; A = w(AW, _) ), atom(AW),
    tr_lexeme(foreign, AW, AL, Number), atom(AL), tr_gender(AL, G), G \== none,
    tr_lexeme(foreign, NW, L, Number), atom(L), tr_gender(L, G),
    tr_meanings_of(L, english, noun, [Noun|_]), !.

tr_cross_det(none, none) :- !.
%% a possessive crosses by the meaning that IS a possessive: `loro' is they,
%% them and their, and `le loro condizioni' came out `they conditions'
%% ... AND A PLURAL SUBJECT'S IS `their' where the lesson gives the word that
%% meaning: Spanish's `su' is his, her, its and their, the first of them the
%% lesson's, and `Los abogados cobran por sus servicios' crossed as `his
%% services', Italian's `i suoi servizi'. The possessor of a possessive in
%% the complements is the subject more often than any other thing
tr_cross_det(det(possessive, DL, w(_, C)), det(possessive, their, w(their, C))) :-
    tr_side_here(foreign), tr_global('$tr_poss', their), tr_solve(mean(DL, their)), !.
tr_cross_det(det(possessive, DL, w(_, C)), det(possessive, its, w(its, C))) :-
    tr_side_here(foreign), tr_global('$tr_poss', its), tr_solve(mean(DL, its)), !.
tr_cross_det(det(possessive, DL, w(_, C)), det(possessive, her, w(her, C))) :-
    tr_side_here(foreign), tr_global('$tr_poss', her), tr_solve(mean(DL, her)), !.
tr_cross_det(det(possessive, DL, w(_, C)), det(possessive, T, w(T, C))) :-
    tr_side_here(foreign), tr_solve(mean(DL, T)), en_possessive(T), !.
%% (the article of `lo que', what, is no word of any lesson: tr_np/3)
tr_cross_det(det(article, what, w(_, C)), det(article, what, w(what, C))) :- !.
tr_cross_det(det(Kind, DL, w(_, C)), det(Kind, T, w(T, C))) :- tr_word_across(w(DL, lower), english, Kind, T).

tr_cross_num(none, none) :- !.
tr_cross_num(one(w(_, C)), w(one, C)) :- !.
tr_cross_num(w(MW, MC), w(MT, MC)) :- !, tr_word_across(w(MW, MC), english, number, MT).
tr_cross_num(adv_num(w(A, C), M0), adv_num(w(AT, C), M)) :- !,
    tr_word_across(w(A, lower), english, adverb, AT), tr_cross_num(M0, M).
tr_cross_num(nums(M10, C0, M20), nums(M1, C, M2)) :-
    tr_cross_num(M10, M1), tr_side_here(Side), tr_cross_connector(Side, C0, C), tr_cross_num(M20, M2).
tr_cross_num(numw(M10, M20), numw(M1, M2)) :- tr_cross_num(M10, M1), tr_cross_num(M20, M2).

tr_cross_adjectives([], []).
tr_cross_adjectives([A0|As0], [A|As]) :- tr_cross_adjective(A0, A), tr_cross_adjectives(As0, As).

tr_cross_adjective(deg(D, A0), deg(D, A)) :- !, tr_cross_adjective(A0, A).
tr_cross_adjective(degt(D, A0, As0), degt(D, A, As)) :- !, tr_cross_adjective(A0, A), tr_cross_adjectives(As0, As).
tr_cross_adjective(pre(A0), pre(A)) :- !, tr_cross_adjective(A0, A).
tr_cross_adjective(pptc(L0), pptc(L)) :- !, tr_lexeme_across(L0, english, L).
tr_cross_adjective(mti(A0), mti(A)) :- !, tr_cross_adjective(A0, A).
tr_cross_adjective(advn(w(W, C)), advn(w(T, C))) :- !, tr_word_across(w(W, lower), english, adverb, T).
%% a noun that says what kind the noun is (nmod/1) crosses by its meaning as
%% a noun
tr_cross_adjective(nmod(w(W, C)), nmod(w(T, C))) :- !,
    tr_lexeme_here(W, WL), tr_meanings_of(WL, english, noun, [T|_]).
tr_cross_adjective(nmodp(w(W, C)), nmodp(w(T, C))) :- !,
    tr_lexeme_here(W, WL), tr_meanings_of(WL, english, noun, [T|_]).
%% (a name apposed to a noun crosses by its meaning too: `sobre la capital, Grozni' is the capital, Grozny)
tr_cross_adjective(w(W0, appos), w(W, appos)) :- !, ( tr_name_across(W0, W1) -> W = W1 ; W = W0 ).
tr_cross_adjective(int(w(A0, C), J0), int(w(A, C), J)) :- !,
    (   tr_intensifier_meaning(A0, A1) -> true
    ;   tr_adjectival_meaning(A0, A1) -> true
    ;   tr_word_across(w(A0, lower), english, adverb, A1)
    ),
    ( J0 = deg(comparative, _) -> tr_much_before(A1, more, A) ; A = A1 ),   % (`molto più grande', much bigger)
    tr_cross_adjective(J0, J).
tr_cross_adjective(w(W, C), T) :- tr_side_here(Side), tr_coord(Side, w(W, C)), !, tr_cross_coord(Side, w(W, C), T).
%% A NAME APPOSED TO A NOUN CROSSES AS ITSELF -- `il presidente Scalfaro' --
%% which is what being a name means, and without it the phrase read and the
%% crossing failed, so the sentence was refused with no shape missing.
tr_cross_adjective(w(W, upper), w(W, upper)) :- tr_side_here(Side), tr_name_word(Side, w(W, upper)), !,
    tr_kept_name_note(Side, W).
%% (by the reading of the word that IS an adjective: `un bel giorno' is the
%% apocope of `bello', and `bel' is also the unit, a noun, whose meaning it
%% crossed by first -- `un belio día')
tr_cross_adjective(w(W, C), w(T, C)) :-
    (   tr_side_here(Side), tr_lexeme(Side, W, WL, _), atom(WL), tr_class_of(WL, adjective) -> true
    ;   tr_lexeme_here(W, WL)
    ),
    tr_meanings_of(WL, english, adjective, [T|_]).
%% ... AND THE LESSON'S WRITER WRITES IT AS IT STOOD, though English knows
%% the word: `il boss della compagnia discografica Paramount' is the record
%% company of that name, and the Spanish writer, finding the IR's
%% `paramount' an English adjective, wrote `la compañía discográfica
%% Primordial'. A name a lesson's text kept as itself is noted as it
%% crosses ('$tr_xnames', as kept/1), and tr_adjective_out/5 writes it so.
tr_kept_name_note(foreign, W) :- !,
    nb_getval('$tr_xnames', Xs), ( memberchk(kept(W), Xs) -> true ; nb_setval('$tr_xnames', [kept(W)|Xs]) ).
tr_kept_name_note(_, _).

%% AN INTENSIFIER CROSSES BY THE MEANING THAT SAYS A DEGREE, where the word
%% has one: `così' is `thus' first, because standing alone -- `La chiamavamo
%% così' -- that is what it says, and Spanish writes the dictionary's `so' as
%% `tan', which cannot stand alone; before an adjective it is `so', `così
%% bella', `tan bella'
tr_intensifier_meaning(W, A) :-
    tr_side_here(foreign), tr_lexeme(foreign, W, L, _),
    tr_solve(mean(L, A)), en_degree_adverb(A), tr_solve(adverb(L)), !.
en_degree_adverb(E) :- memberchk(E, [very, so, too, quite, rather, extremely, really, as, how]).
%% ... AND BY THE MEANING THE LESSON GIVES AN ADVERB BEFORE AN ADJECTIVE OR A
%% PARTICIPLE: `justamente retribuidos' is justly remunerated, and `justamente'
%% anywhere else is precisely, the dictionary's one meaning (`The adjectival
%% adverb "justamente" means "justly".')
tr_adjectival_meaning(W, A) :-
    tr_side_here(foreign), atom(W), tr_lexeme(foreign, W, L, _), tr_solve(mean_as(L, A, adjectival)), !.

%% A COORDINATOR AMONG ADJECTIVES CROSSES AS ONE -- English's `and', `or',
%% `nor' or `but', the meaning by which tr_coord_word/1 took the word for a
%% coordinator at all: `no habría sido prudente ni serio' is careful NOR
%% serious, and by `ni''s first meaning, `neither', the list had one more
%% adjective in its middle, which Italian wrote `prudente neanche serio'
tr_cross_coord(foreign, w(W, C), w(T, C)) :-
    W \== ',', tr_lexeme(foreign, W, L, _), tr_meanings_of(L, english, conjunction, Ms),
    member(T, Ms), en_coordinator(T), !.
tr_cross_coord(Side, W, T) :- tr_cross_connector(Side, W, T).
%% English's coordinators -- and `or rather', which joins two phrases as `or'
%% does and corrects the first: `È Margherita o meglio Malgorzata Dworak' is
%% the babysitter by the name she went by and then her own, and read as `o'
%% and the adverb `meglio' the adverb went to the end of the clause, `de la
%% pareja mejor'
en_coordinator(E) :- memberchk(E, [and, or, nor, but, 'or rather']).

%% the complements, across, each in its place
tr_cross_comps([], []).
%% A MONTH AND THE YEAR AFTER ITS `of' ARE ONE DATE: `nel settembre del settantanove' is in September '79, and read as
%% two phrases it was `in the September of the seventy-nine'. The year in words, or in digits, is the month's own,
%% app(Phrase, yearw, Word), as the year of a date with its day is (tr_date_year/2)
tr_cross_comps([pp(P, NP0), pp(w(O, _), np(det(article, _, _), none, [], w(Y, YC), singular))|Cs0], Cs) :-
    NP0 = np(_, _, _, N0, singular), tr_month(foreign, N0),
    atom(O), tr_lexeme(foreign, O, OL, _), tr_solve(mean(OL, of)),
    atom(Y), ( tr_digits(Y) -> K = year ; tr_is(foreign, w(Y, lower), number), K = yearw ), !,
    tr_cross_comps([pp(P, app(NP0, K, w(Y, YC)))|Cs0], Cs).
%% A COMPARATIVE IN AN INDEFINITE OBJECT COMPARES WITH THE PHRASE OF `di' AFTER IT: `alcune tessere dell'Eco - puzzle
%% hanno una rilevanza maggiore di altre' have a greater relevance than others, and read as a phrase of `of' it was
%% `a bigger relevance of others'. Italian's `di' after a comparative is the word for `than', as after a predicate
%% (cmp/2); after the definite article the reader makes the adjective a superlative, and its `di' is `of', `la casa più
%% grande di Roma'
tr_cross_comps([obj(NP0), pp(w(O, _), X0)|Cs0], Cs) :-
    NP0 = np(_, _, Adjs, _, _), memberchk(deg(comparative, _), Adjs), tr_language(italian),
    atom(O), tr_lexeme(foreign, O, OL, _), tr_solve(mean(OL, of)), !,
    tr_cross_comps([obj(NP0), cmp(more, X0)|Cs0], Cs).
%% `da' AND A BARE PERSON AFTER AN OBJECT SAY WHOSE KIND IT IS: `Ma non sono vezzi da intellettuale affermato' are not
%% the affectations of an established intellectual, and crossed as `from', or as the role after a verb (`fa da madre'
%% acts as a mother), it was `affectations from established intellectual'. Italian's `da', and a singular person's noun
%% with no determiner: the phrase of `of' with the indefinite article
tr_cross_comps([obj(NP0), pp(w(P, PC), NPD0)|Cs0], [obj(NP), pp(w(of, PC), NPD)|Cs]) :-
    NPD0 = np(none, none, _, w(_, _), singular), tr_language(italian),
    atom(P), tr_lexeme(foreign, P, PL, _), tr_solve(mean(PL, from)), tr_of_class(NPD0, person),
    tr_cross_np(NPD0, np(none, none, Adjs, N, singular)), !,
    NPD = np(det(article, a, w(a, lower)), none, Adjs, N, singular),
    tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
%% A PARTITIVE PRONOUN BESIDE A QUANTITY IS SAID ONCE. `tanto per citarne
%% alcuni' is to cite some (of them), and `ne sapevano tanto quanto Colombo'
%% knew as much (of it) as Columbus: the pronoun says `of it' and the
%% quantity how much, and Spanish and English say the quantity alone --
%% crossed as `it', they came out `para citarlo algunos' and `lo conocieron'.
%% The lesson says which pronoun is partitive (`"ne" is partitive.'), and it
%% goes where the next complement is a quantity: a word of quantity alone,
%% or as much as (asmuch/1) -- as the pronoun that doubles `todo' goes
%% (tr_undouble/3)
tr_cross_comps([opron(w(W, _)), Q|Cs0], Cs) :-
    atom(W), tr_quantity_comp(Q), tr_solve(partitive(W)), !, tr_cross_comps([Q|Cs0], Cs).
%% (an adverb between them too: `Ne citerei almeno tre' is I would cite at least three, and it was `I would cite it at
%% least three')
tr_cross_comps([opron(w(W, _)), adv(A), Q|Cs0], Cs) :-
    atom(W), tr_quantity_comp(Q), tr_solve(partitive(W)), !, tr_cross_comps([adv(A), Q|Cs0], Cs).
tr_cross_comps([C0, Q|Cs0], [C|Cs]) :-
    tr_partitive_off(C0, C1), tr_quantity_comp(Q), !,
    tr_cross_comp(C1, C), tr_cross_comps([Q|Cs0], Cs).
tr_cross_comps([C0|Cs0], [C|Cs]) :- tr_personal_comp(C0, Cs0, C), !, tr_cross_comps(Cs0, Cs).   % (tr_personal_comp/3)
%% AN HOUR AND THE ADVERB OF A PART OF THE DAY RIGHT AFTER IT: `Alle 9 di mattina' is at 9 in the morning -- `di
%% mattina' is the lesson's `in the mornings', an adverb of two words, and after an hour it says which part of that day.
%% It crosses as the part's phrase of `of', as a Spanish hour has it (`a las 9 de la mañana'; English's `in the
%% morning', en_day_part/2), where it was `At 9 in the mornings' and `A las 9 por las mañanas'
tr_cross_comps([C0, A0|Cs0], [C, A|Cs]) :-
    tr_side_here(foreign), ( A0 = fr(adv(w(W, AC))) -> F = yes ; A0 = adv(w(W, AC)), F = no ), atom(W),
    %% (an adverb of two words or more and the hour's shape first, a phrase with its article and no adjectives, or two
    %% of them joined: asked of every complement an adverb follows, the adverb's meaning was 45 % of what the sample's
    %% code cost twelve controls)
    atomic_list_concat([_, _|_], ' ', W), tr_clock_shape(C0),
    tr_word_across(w(W, lower), english, adverb, E), en_part_adverb(E, D),
    tr_cross_comp(C0, C), ( C = fr(PP1) -> true ; PP1 = C ), en_clock_pp(PP1), !,
    PP = pp(w(of, AC), np(det(article, the, w(the, lower)), none, [], w(D, lower), singular)),
    ( F == yes -> A = fr(PP) ; A = PP ),
    tr_cross_comps(Cs0, Cs).
%% AN INTERVIEW IS WITH SOMEBODY: `Intervista alle televisioni danese e svedese', `In un'intervista a una tv danese'
%% -- the Italian and the Spanish say the one interviewed with `to', and English wrote `Interview to the Danish and
%% Swedish televisions'. The phrase of `to' right after the noun is `with' (the Spanish writer's `con')
tr_cross_comps([C0, P0|Cs0], [C, P|Cs]) :-
    tr_side_here(foreign), ( P0 = pp(_, _) ; P0 = fr(pp(_, _)) ), tr_to_phrase(P0, W, Mk), tr_interview_comp(C0), !,
    tr_cross_comp(C0, C), tr_cross_comp(P0, P1), tr_to_phrase(P1, _, Mk), tr_with_phrase(P1, W, P),
    tr_cross_comps(Cs0, Cs).
%% A RANGE OF ROLES IS NO ROLE: `da giudice di legittimità a giudice di merito'
%% is from judge of legitimacy to judge of merit, and the role of tr_cross_comp/2
%% made the first end `as judge' -- `como juez de legitimidad a juez de mérito'.
%% The first phrase is a bare person and a phrase of `to' with another bare
%% person comes after it, through the phrases of `of' that belong to the first
tr_cross_comps([pp(w(P, C), NP0)|Cs0], [pp(w(PT, C), NP)|Cs]) :-
    tr_side_here(foreign), NP0 = np(none, none, [], N, singular), N = w(_, _), tr_person_word(N),
    tr_role_range(Cs0), !,
    tr_prep_across(P, PT), tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
%% ... NOR A RANGE OF DATES SINCE: `vietato dal 24 luglio al 25 agosto' is forbidden from July 24 to
%% August 25, and the first phrase, a month or a year, is no `since' for a phrase of `to' after it
tr_cross_comps([pp(w(P, C), NP0)|Cs0], [pp(w(PT, C), NP)|Cs]) :-
    tr_side_here(foreign), tr_since_phrase(NP0), tr_date_range(Cs0), !,
    tr_prep_across(P, PT), tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
%% ... and so between two commas: `i cui tecnici per dieci anni, dal 1994 al 2004, hanno scavato'
%% dug from 1994 to 2004, and it was `since 1994 to 2004'
tr_cross_comps([mid(pp(w(P, C), NP0))|Cs0], [mid(pp(w(PT, C), NP))|Cs]) :-
    tr_side_here(foreign), tr_since_phrase(NP0), tr_mid_items(Cs0, Us), tr_date_range(Us), !,
    tr_prep_across(P, PT), tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
%% ... and in front of the clause, with a comma after it: `Dal 14 aprile al 30 settembre, il cane
%% dorme' is From April 14 to September 30, and each front crossed on its own it was `Since April 14'
tr_cross_comps([fr(pp(w(P, C), NP0))|Cs0], [fr(pp(w(PT, C), NP))|Cs]) :-
    tr_side_here(foreign), tr_since_phrase(NP0), tr_fr_items(Cs0, Us), tr_date_range(Us), !,
    tr_prep_across(P, PT), tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
%% AN ADVERB BEFORE AN ADJECTIVE OR A PARTICIPLE IS WHAT THE LESSON SAYS IT MEANS
%% THERE: `justamente retribuidos' is justly remunerated, and `justamente' is
%% precisely anywhere else, the one meaning the dictionary gives (`The
%% adjectival adverb "justamente" means "justly".')
tr_cross_comps([adv(w(A, C)), P|Cs0], [adv(w(E, C))|Cs]) :-
    ( P = pred(_) ; P = adj(_) ), tr_adjectival_meaning(A, E), !,
    tr_cross_comps([P|Cs0], Cs).
%% ... AND AN INTENSIFIER BEFORE A COMPARATIVE IS THE COMPARATIVE'S, `much':
%% `il cane è molto più grande' is much bigger, where the adverb stood apart
%% and came out `bigger very', `muy mayor' (tr_much_before/3)
tr_cross_comps([adv(w(A, C)), adj([deg(comparative, W)|Js])|Cs0], Cs) :-
    tr_side_here(foreign), atom(A), tr_intensifier_meaning(A, very), !,
    tr_cross_comps([adj([int(w(A, C), deg(comparative, W))|Js])|Cs0], Cs).
%% A NOUN THAT CAN SAY A RELATION SAYS ONE BEFORE `BETWEEN' OR `WITH':
%% `il rapporto tra il cane e il gatto' is the relationship between them, and
%% `rapporto' is a report first -- `el informe entre el perro y el gato'. A
%% noun whose first meaning is no relation and that has one among its others
%% (tr_relational_np/3) crosses by it before such a phrase, in the
%% complements, in a phrase with its phrases (tr_cross_np/2's with/2) and in
%% a headline's two halves (tr_cross/3's gap/2)
tr_cross_comps([obj(NP0), PP|Cs0], [obj(NP)|Cs]) :-
    tr_relational_np(NP0, PP, NP), !, tr_cross_comps([PP|Cs0], Cs).
%% ... and an object that is a round count and its phrase of `of', which the
%% reader leaves apart: `esgrimiendo el centenar de reclamaciones' is the
%% hundred complaints (tr_cross_np/2's with/2, which the subject's are)
tr_cross_comps([obj(NP0), PP|Cs0], [obj(NP)|Cs]) :-
    NP0 = np(det(article, _, _), none, [], w(_, _), singular), PP = pp(_, PNP), tr_count_head(PNP, np(none, none, _, _, plural), _, _),
    tr_cross_np(with(NP0, [PP]), NP), NP \= with(_, _), !, tr_cross_comps(Cs0, Cs).
%% ... and `almost' before it says how many in its place: `casi un millar de sellos discográficos' is almost a
%% thousand record labels, and with the count's own word it was `almost about a thousand'
tr_cross_comps([adv(A0)|Cs0], [obj(NP)|Cs]) :-
    Cs0 = [obj(np(det(article, _, _), none, [], _, singular)), pp(_, _)|_],     % (the count's shape, asked first)
    A0 = w(AW, _), atom(AW), tr_cross_comp(adv(A0), adv(w(A, AC))), memberchk(A, [almost, nearly]),
    tr_cross_comps(Cs0, [obj(np(D, adv_num(w(about, _), N), Adjs, Nn, Nb))|Cs]), !,
    NP = np(D, adv_num(w(A, AC), N), Adjs, Nn, Nb).
%% (and inside the phrase of a preposition, which the reader took for the adverb alone: `se compone de casi un millar
%% de sellos' is of almost a thousand)
tr_cross_comps([pp(w(P, PC), adv(A0))|Cs0], [pp(w(PT, PC), NP)|Cs]) :-
    Cs0 = [obj(np(det(article, _, _), none, [], _, singular)), pp(_, _)|_],
    A0 = w(AW, _), atom(AW), atom(P), tr_cross_comp(adv(A0), adv(w(A, AC))), memberchk(A, [almost, nearly]),
    tr_cross_comps(Cs0, [obj(np(D, adv_num(w(about, _), N), Adjs, Nn, Nb))|Cs]), !,
    tr_prep_across(P, PT), NP = np(D, adv_num(w(A, AC), N), Adjs, Nn, Nb).
%% ... and in the phrase of `of' of a phrase whose noun is left out, the next phrase of `of' after it:
%% `la superficie è quella del fondo dei rii' is that of the bottom of the canals
tr_cross_comps([obj(ell(Det0, G, Number, pp(Q0, NP0))), PP|Cs0], [obj(ell(Det, G, Number, pp(Q, NP)))|Cs]) :-
    NP0 = np(_, _, _, _, _), tr_relational_np(NP0, PP, NP), !,
    tr_cross_det(Det0, Det), Q0 = w(QW, QC), tr_prep_across(QW, QT), Q = w(QT, QC),
    tr_cross_comps([PP|Cs0], Cs).
%% ... and in the phrase of a preposition before it: `sul fondo dei canali' is ON
%% THE BOTTOM of the canals, `con il rapporto tra il cane e il gatto' with the
%% relationship between them -- the phrase crossed as any (tr_cross_comp/2) and
%% its noun's word the one tr_relational_np/3 says
tr_cross_comps([pp(W0, NP0), PP|Cs0], [pp(W, NP)|Cs]) :-
    NP0 = np(_, _, _, _, _), tr_relational_np(NP0, PP, NP),
    tr_cross_comp(pp(W0, NP0), pp(W, NP1)), NP1 = np(_, _, _, _, _), !,
    tr_cross_comps([PP|Cs0], Cs).
tr_cross_comps([C0|Cs0], [C|Cs]) :- tr_cross_comp(C0, C), tr_cross_comps(Cs0, Cs).
%% (the phrase of `to', bare or in front, and the complement whose noun is an interview)
tr_to_phrase(pp(w(P, C), _), w(P, C), pp) :- atom(P), tr_means_to(foreign, P), !.
tr_to_phrase(fr(pp(w(P, C), _)), w(P, C), fr) :- atom(P), tr_means_to(foreign, P), !.
tr_to_phrase(pp(w(to, C), _), w(to, C), pp) :- !.
tr_to_phrase(fr(pp(w(to, C), _)), w(to, C), fr).
tr_interview_comp(C) :-
    ( C = obj(NP) ; C = pp(_, NP) ; C = fr(pp(_, NP)) ), NP = np(_, _, _, w(N, _), _), atom(N),
    tr_lexeme(foreign, N, L, _), tr_solve(mean(L, interview)), !.
tr_with_phrase(pp(w(_, C), NP), _, pp(w(with, C), NP)).
tr_with_phrase(fr(pp(w(_, C), NP)), _, fr(pp(w(with, C), NP))).

tr_relational_np(NP0, pp(w(P, _), _), NP) :-
    NP0 = np(_, _, _, w(NW, _), _), atom(NW), atom(P), tr_side_here(foreign),
    tr_prep_across(P, PT), memberchk(PT, [among, between, with]),
    tr_lexeme(foreign, NW, L, _), atom(L), tr_meanings_of(L, english, noun, [M1|Ms]),
    \+ en_relational_noun(M1), member(E, Ms), en_relational_noun(E), !,
    tr_cross_np(NP0, NP1), NP1 = np(D, N, A, w(_, NC), Nb), NP = np(D, N, A, w(E, NC), Nb).
%% A NOUN THAT CAN SAY THE BOTTOM OF A THING SAYS IT BEFORE A PHRASE OF `of' WITH A
%% DETERMINER: `il tesoro giace sul fondo dei canali' rests on the bottom of the
%% canals, `en el fondo del hoyo' is at the bottom of the hole -- `fondo' is a fund
%% first in both lessons (`un fondo nazionale', the controls' `i fondi necessari'),
%% and with no determiner the phrase says what fund it is (`il fondo di
%% investimento')
tr_relational_np(NP0, pp(w(P, _), PNP), NP) :-
    NP0 = np(_, _, _, w(NW, _), _), atom(NW), atom(P), tr_side_here(foreign),
    tr_prep_across(P, of), tr_lexeme(foreign, NW, L, _), atom(L), tr_solve(mean(L, bottom)),   % (asked first: few nouns have it)
    tr_head_definite(PNP), tr_meanings_of(L, english, noun, [M1|Ms]),
    M1 \== bottom, memberchk(bottom, Ms), !,
    tr_cross_np(NP0, NP1), NP1 = np(D, N, A, w(_, NC), Nb), NP = np(D, N, A, w(bottom, NC), Nb).
%% ... AND A NOUN THAT CAN SAY A LACK SAYS IT BEFORE A PHRASE OF `of' WITH NO DETERMINER: `La falta de agentes hasta
%% última hora propició disputas' -- the lack of agents, where `falta' is a fault first and a foul (`seis supuestas
%% faltas graves'). What is lacking is named with no determiner
tr_relational_np(NP0, pp(w(P, _), PNP), NP) :-
    NP0 = np(_, _, _, w(NW, _), _), atom(NW), atom(P), tr_side_here(foreign),
    PNP = np(none, _, _, w(_, _), _), tr_prep_across(P, of),
    tr_lexeme(foreign, NW, L, _), atom(L), tr_solve(mean(L, lack)),   % (asked first: few nouns have it)
    tr_meanings_of(L, english, noun, [M1|Ms]),
    M1 \== lack, memberchk(lack, Ms), !,
    tr_cross_np(NP0, NP1), NP1 = np(D, N, A, w(_, NC), Nb), NP = np(D, N, A, w(lack, NC), Nb).
%% ... AND A NOUN THAT CAN SAY A MEMBER SAYS IT BEFORE A PHRASE OF `of' WHOSE NOUN IS A GROUP: `i componenti della
%% banda che rapì il duca' are the gang's members, where `componente' is a component first (`le componenti
%% politiche', `un componente elettronico')
tr_relational_np(NP0, pp(w(P, _), PNP), NP) :-
    NP0 = np(_, _, _, w(NW, _), _), atom(NW), atom(P), tr_side_here(foreign),
    tr_prep_across(P, of), tr_lexeme(foreign, NW, L, _), atom(L), tr_solve(mean(L, member)),   % (asked first: few nouns have it)
    tr_group_head(PNP), tr_meanings_of(L, english, noun, [M1|Ms]),
    M1 \== member, memberchk(member, Ms), !,
    tr_cross_np(NP0, NP1), NP1 = np(D, N, A, w(_, NC), Nb), NP = np(D, N, A, w(member, NC), Nb).
tr_group_head(rc(NP, _, _)) :- !, tr_group_head(NP).
tr_group_head(nrc(NP, _, _)) :- !, tr_group_head(NP).
tr_group_head(with(NP, _)) :- !, tr_group_head(NP).
tr_group_head(np(_, _, _, w(W, _), _)) :- atom(W), tr_lexeme(foreign, W, L, _), tr_holds(group(L)), !.
%% (the phrase of `of' is definite with what hangs on it too: `sul fondo dei canali, i quali risultano
%% più inquinati' is the bottom of the canals that turn out so)
tr_head_definite(rc(NP, _, _)) :- !, tr_head_definite(NP).
tr_head_definite(nrc(NP, _, _)) :- !, tr_head_definite(NP).
tr_head_definite(with(NP, _)) :- !, tr_head_definite(NP).
tr_head_definite(NP) :- tr_definite_np(NP).
en_relational_noun(relationship).
en_relational_noun(relation).

tr_role_range([pp(w(Q, _), np(none, none, [], N, singular))|_]) :-
    atom(Q), tr_means_to(Q), N = w(_, _), tr_person_word(N), !.
tr_role_range([pp(_, _)|Cs]) :- tr_role_range(Cs).
%% (a phrase of `to' or `until' comes next: `dal 24 luglio al 25 agosto', and after `e' too: `già
%% dal 14 aprile e fino al 30 settembre' is from April 14 to September 30, where it was `since')
tr_date_range([pp(w(Q, _), _)|_]) :-
    atom(Q), ( tr_means_to(Q) ; tr_lexeme(foreign, Q, L, _), tr_solve(mean(L, until)) ), !.
tr_date_range([cnj(_)|Cs]) :- tr_date_range(Cs).
tr_mid_items([mid(X)|Cs], [X|Xs]) :- !, tr_mid_items(Cs, Xs).
tr_mid_items(_, []).
tr_fr_items([fr(X)|Cs], [X|Xs]) :- !, tr_fr_items(Cs, Xs).
tr_fr_items(_, []).

tr_partitive_off(infx(L, A, Cls0), infx(L, A, Cls)) :- select(P, Cls0, Cls), atom(P), tr_solve(partitive(P)), !.
tr_partitive_off(purp(X0), purp(X)) :- tr_partitive_off(X0, X).

tr_quantity_comp(asmuch(_)) :- !.
tr_quantity_comp(obj(np(none, none, [], w(X, _), _))) :- atom(X), tr_quantity_word(X), !.
%% (the words of quantity that stand before `de lo que' as a partitive, `nada de lo que', beside the lesson's numbers and quantities)
tr_quantity_word(Q) :- memberchk(Q, [nada, algo, poco, mucho, bastante, demasiado, parte, resto, 'mayoría', mitad, todo]).
tr_quantity_word(X) :- tr_is(foreign, w(X, lower), number), !.
tr_quantity_word(X) :- tr_lexeme(foreign, X, L, _), tr_solve(mean(L, E)), en_quantity(E), !.
en_quantity(some).     en_quantity(many).     en_quantity(few).      en_quantity(several).
en_quantity('so many'). en_quantity('so much'). en_quantity(nobody).
en_quantity(much).     en_quantity(one).      en_quantity(another).  en_quantity(none).

tr_cross_comp(fr(C0), fr(C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(gapc(NP0, Ps0), gapc(NP, Ps)) :- !, tr_cross_np(NP0, NP), tr_cross_comps(Ps0, Ps).
%% THE WORD THAT BEGINS THE CAUSE, AN ADJECTIVE AND A CLAUSE OF `CHE' ARE A CONCESSION: `Per strano che
%% possa apparire, l'accumulo di veleni deriverebbe ...' is however strange it may appear, and read as the
%% preposition and a relative clause on the adjective it was `For strange that can appear'. The clause's
%% gap is the thing the adjective is said of; it travels as conc(Word, Adjective, Clause), which English
%% writes `however' and the adjective and the clause with `it' for its subject, and the lesson's language
%% as it stood, the clause in the subjunctive (`Por extraño que pueda aparecer')
tr_cross_comp(pp(w(P, C), rc(np(none, none, [w(A, AC)], elided(_), _), subject, S0)), conc(w(P, C), w(AT, AC), S)) :-
    tr_side_here(foreign), atom(P), tr_cause_word(P), S0 = s(_, gap(_, _), _, _),
    tr_word_across(w(A, lower), english, adjective, AT), !,
    tr_cross(foreign, S0, S).
tr_cross_comp(fpart(L0, G, N, Cs0), fpart(L, G, N, Cs)) :- !, tr_lexeme_across(L0, english, L), tr_cross_comps(Cs0, Cs).
tr_cross_comp(frc(C0), frc(C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(mid(C0), mid(C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(frn(C0), frn(C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(sep, sep) :- !.
tr_cross_comp(vq, vq) :- !.
tr_cross_comp(vqc, vqc) :- !.
tr_cross_comp(vqp, vqp) :- !.
tr_cross_comp(qs, qs) :- !.
tr_cross_comp(qrel, qrel) :- !.
tr_cross_comp(sub(C0, S0), sub(C, S)) :- !, tr_side_here(Side), tr_cross_connector(Side, C0, C), tr_cross(Side, S0, S).
tr_cross_comp(qe, qe) :- !.
tr_cross_comp(nonly, nonly) :- !.
tr_cross_comp(paren(K), paren(Inner)) :- !, tr_aside_inner(K, Inner).
tr_cross_comp(comment(K), comment(clause(S))) :- !, nb_getval(K, Ws), tr_side_here(Side), tr_aside_clause(Side, Ws, S).
tr_cross_comp(per(K), per(comma, CC, S)) :- !, nb_getval(K, [w(_, CC)|Ws]), tr_per_read(Ws, S0), tr_cross(foreign, S0, S).
tr_cross_comp(perh(K), per(none, CC, S)) :- !, nb_getval(K, [w(_, CC)|Ws]), tr_per_read(Ws, S0), tr_cross(foreign, S0, S).
tr_cross_comp(perd(K), per(dash, CC, S)) :- !, nb_getval(K, [w(_, CC)|Ws]), tr_per_read(Ws, S0), tr_cross(foreign, S0, S).
tr_cross_comp(abs(L0, NP0), abs(L, NP)) :- !, tr_lexeme_across(L0, english, L), tr_cross_np(NP0, NP).
tr_cross_comp(subj_here, subj_here) :- !.
tr_cross_comp(voc(NP0), voc(NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(dsh(K), dsh(Inner)) :- !, tr_aside_inner(K, Inner).
tr_cross_comp(scomma, scomma) :- !.
tr_cross_comp(agr(G), agr(G)) :- !.
%% the gender a genderless subject takes from its participle or adjective,
%% and the degree adverb before a participle (tr_clause_post/4), which
%% crosses by its degree meaning as an intensifier does
tr_cross_comp(sagr(G), sagr(G)) :- !.
tr_cross_comp(phagr, phagr) :- !.
tr_cross_comp(suagr, suagr) :- !.
tr_cross_comp(whinf(Cs0), whinf(Cs)) :- !, tr_cross_comps(Cs0, Cs).
tr_cross_comp(pp2(w(P1, C1), Co0, w(P2, C2), NP0), pp2(w(T1, C1), Co, w(T2, C2), NP)) :- !,
    tr_prep_across(P1, T1), tr_cross_coord(foreign, Co0, Co), tr_prep_across(P2, T2), tr_cross_np(NP0, NP).
tr_cross_comp(iadv(w(A, C), w(B, BC)), iadv(w(AT, C), w(BT, BC))) :- !,
    ( tr_intensifier_meaning(A, AT0) -> true ; tr_word_across(w(A, lower), english, adverb, AT0) ),
    tr_word_across(w(B, lower), english, adverb, BT),
    tr_much_before(AT0, BT, AT).
tr_cross_comp(gadv(w(A, C)), gadv(w(AT, C))) :- !,
    (   tr_intensifier_meaning(A, AT) -> true
    ;   tr_adjectival_meaning(A, AT) -> true
    ;   tr_word_across(w(A, lower), english, adverb, AT)
    ).
tr_cross_comp(agrn(N), agrn(N)) :- !.
tr_cross_comp(aside(C), aside(C)) :- !.
tr_cross_comp(pdeg(D), pdeg(D)) :- !.
tr_cross_comp(padv(w(A, C)), padv(w(AT, C))) :- !, tr_word_across(w(A, lower), english, adverb, AT).
tr_cross_comp(pcase(C), pcase(C)) :- !.
tr_cross_comp(appos(NP0), appos(NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(topic(NP0), topic(NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(obj(NP0), obj(NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(qnp(A0, NP0), qnp(A, NP)) :- !, tr_cross_asked(A0, A), ( NP0 == none -> NP = none ; tr_cross_np(NP0, NP) ).
tr_cross_comp(adj(Ws0), adj(Ws)) :- !, tr_cross_adjectives(Ws0, Ws).
tr_cross_comp(oadj(Ws0, G, N), oadj(Ws, G, N)) :- !, tr_cross_adjectives(Ws0, Ws).
tr_cross_comp(oc(NP0, Ws0), oc(NP, Ws)) :- !, tr_cross_np(NP0, NP), tr_cross_adjectives(Ws0, Ws).
tr_cross_comp(that(S0), that(S)) :- !, tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(that_open, that_open) :- !.
tr_cross_comp(thatg(S0), thatg(S)) :- !, tr_side_here(Side), tr_cross(Side, S0, S).
%% `which' with its phrase crosses like a question's (tr_cross_asked/2), the
%% pronoun and every other question word stand as they were read
tr_cross_comp(wh(Q0, S0), wh(Q, S)) :- ( Q0 = which(_, _) ; Q0 = pp(_, which(_, _)) ), !,
    tr_side_here(Side),
    ( Q0 = which(_, _) -> tr_cross_q(which, Q0, Q) ; tr_cross_asked(Q0, Q) ),
    tr_cross(Side, S0, S).
tr_cross_comp(wh(pp(w(P, C), Q), S0), wh(pp(w(PT, C), Q), S)) :- atom(Q), !,
    tr_prep_across(P, PT), tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(wh(Q, S0), wh(Q, S)) :- !, tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(rwh(Q, S0), rwh(Q, S)) :- !, tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(cmtc(S0), cmtc(S)) :- !, tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(asrwh(Q, S0), asrwh(Q, S)) :- !, tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(rcl(Role0, S0), rcl(Role, S)) :- !,
    tr_cross_np(rc(np(none, none, [], elided(masculine), singular), Role0, S0), rc(_, Role, S)).
tr_cross_comp(role(NP0), pp(w(as, lower), NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(crel(Role0, S0), crel(Role, S)) :- !,
    tr_cross_np(rc(np(none, none, [], elided(masculine), singular), Role0, S0), rc(_, Role, S)).
%% A BARE NOUN FOR A PERSON AFTER A PREPOSITION THE LESSON GIVES `AS A' IS A ROLE:
%% `pubblicavo da studente' is as a student, and crossed by its first meaning
%% that is not `by' the preposition was `from' and the role the place it came
%% from, `desde estudiante'. The lesson says `The preposition "da" means "as
%% a".', after the meanings it has always had -- NOT `as', which makes the
%% word one of comparison for every reader that asks (tr_means_as/2): `da
%% quando' was `as when', `dipende da come' was refused
tr_cross_comp(pp(w(P, C), NP0), pp(w(as, C), NP)) :-
    tr_side_here(foreign), NP0 = np(none, none, [], N, singular), N = w(_, _), tr_person_word(N),
    tr_lexeme(foreign, P, L, _), tr_meanings_of(L, english, preposition, Ms), memberchk('as a', Ms), !,
    tr_cross_np(NP0, NP).
%% A COUNT OF TIME AFTER A PREPOSITION THE LESSON GIVES `FOR THE PAST' IS HOW
%% LONG IT HAS GONE ON: `Mario lavora da 15 anni', `che da anni coinvolge' --
%% crossed by the first meaning, `from', Spanish said `desde 15 años', a date;
%% it is `desde hace'. A noun the lesson calls a time, in the plural or with
%% a count; `dal 1990' and `da lunedì' stay since (the lesson's second word)
tr_cross_comp(pp(w(P, C), NP0), pp(w('for the past', C), NP)) :-
    tr_side_here(foreign), tr_duration_phrase(NP0),
    tr_lexeme(foreign, P, L, _), tr_meanings_of(L, english, preposition, Ms), memberchk('for the past', Ms), !,
    tr_cross_np(NP0, NP).
%% ... AND A DATE AFTER ONE THE LESSON GIVES `SINCE' IS SINCE THEN: `no gana el scudetto desde
%% 1989', `dal 1989', `desde el lunes', `desde enero' -- crossed by the first meaning, `from', it
%% was `does not win the title from 1989'. A year, a month, a day of the week or a time that says
%% which (`desde la semana pasada'); a place after the word stays from
%% ... AND THE ADVERB OF A DAY BEFORE THIS ONE AFTER IT: `da ieri abbiamo cominciato' is since yesterday,
%% and it was `from yesterday'
tr_cross_comp(pp(w(P, C), adv(w(AW, AC))), pp(w(since, C), adv(w(E, AC)))) :-
    tr_side_here(foreign), atom(AW), tr_word_across(w(AW, lower), english, adverb, E),
    memberchk(E, [yesterday, 'last night', 'the day before yesterday']),
    tr_lexeme(foreign, P, L, _), tr_meanings_of(L, english, preposition, Ms), memberchk(since, Ms), !.
tr_cross_comp(pp(w(P, C), NP0), pp(w(since, C), NP)) :-
    tr_side_here(foreign), tr_since_phrase(NP0),
    tr_lexeme(foreign, P, L, _), tr_meanings_of(L, english, preposition, Ms), memberchk(since, Ms), !,
    tr_cross_np(NP0, NP).
%% THE ARTICLE AND A DECADE'S NUMBER, THE NOUN LEFT OUT, ARE THE YEARS OF THAT DECADE
%% AFTER A PREPOSITION: `en los 70' is `in the 70s', `negli anni 70' -- the phrase of
%% `los años 70', which every writer has (a label after the years); read as a count
%% with its noun left out it was `in the 70'. Not one of a pair, `tra le 70 e le 90
%% mila lire' (between 70 and 90 thousand), whose phrase of the preposition is the pair
tr_cross_comp(pp(w(P, C), NP0), pp(w(PT, C), NP)) :- tr_cross_decade(NP0, NP), !, tr_prep_across(P, PT).
tr_cross_comp(pp(w(P, C), NP0), pp(w(PT, C), NP)) :- !, tr_prep_across(P, PT), tr_cross_np(NP0, NP).
tr_cross_comp(rpp(w(P, C), NP0), rpp(w(PT, C), NP)) :- !, tr_prep_across(P, PT), tr_cross_np(NP0, NP).
tr_cross_comp(rca(Role0, S0), rca(Role, S)) :- !,
    tr_cross_np(rc(np(none, none, [], elided(masculine), singular), Role0, S0), rc(_, Role, S)).
tr_cross_comp(adv(w(A, C)), adv(w(AT, C))) :- !, tr_word_across(w(A, lower), english, adverb, AT).
tr_cross_comp(ans(w(W, C)), ans(w(T, C))) :- !, tr_side_here(Side), tr_answer_meaning(Side, W, T).
tr_cross_comp(purpose(L), purpose(LT)) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(npurpose(L), npurpose(LT)) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(purp(C0), purp(C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(ger(reflexive(L), Cs0), ger(reflexive(LT), Cs)) :- !, tr_lexeme_across(L, english, LT), tr_cross_comps(Cs0, Cs).
tr_cross_comp(ger(L, Cs0), ger(LT, Cs)) :- !, tr_lexeme_across(L, english, LT), tr_cross_comps(Cs0, Cs).
tr_cross_comp(cleft(G0, S0), cleft(G, S)) :- !, tr_cross_comp(G0, G), tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(upon(cl(L, Cls0), Cs0), upon(cl(LT, Cls), Cs)) :- !,
    tr_lexeme_across(L, english, LT),
    findall(X, ( member(Cl, Cls0), tr_cross_comp(opron(Cl), opron(X)) ), Cls),
    tr_cross_comps(Cs0, Cs).
tr_cross_comp(upon(reflexive(L), Cs0), upon(LT, Cs)) :- !,
    tr_verb_across(reflexive(L), _, _, _, LT0), ( LT0 = reflexive(LT) -> true ; LT = LT0 ),
    tr_global('$tr_gov_sense', GS0), nb_setval('$tr_gov_sense', L-LT),
    ( tr_cross_comps(Cs0, Cs) -> nb_setval('$tr_gov_sense', GS0) ; nb_setval('$tr_gov_sense', GS0), fail ).
tr_cross_comp(upon(L, Cs0), upon(LT, Cs)) :- !, tr_lexeme_across(L, english, LT), tr_cross_comps(Cs0, Cs).
tr_cross_comp(upons(L, NP0, Cs0), upons(LT, NP, Cs)) :- !,
    ( tr_intransitive_meanings(L, [LT|_]) -> true ; tr_lexeme_across(L, english, LT) ),
    tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
tr_cross_comp(uponse(L, NP0, Cs0), uponse(LT, NP, Cs)) :- !,
    tr_lexeme_across(L, english, LT), tr_cross_np(NP0, NP), tr_cross_comps(Cs0, Cs).
%% the infinitive of the copula of a state is that copula's too: `o stare a
%% guardare' is to stand by, and crossed as plain `is' Spanish wrote `ser a
%% mirar', where the lesson's language says the state with its own verb
tr_cross_comp(inf(L), inf(state(LT))) :- tr_state_lexeme(L), !, tr_lexeme_across(L, english, LT).
tr_cross_comp(inf(L), inf(LT)) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(ainf(w(_, C), qinf(QC, L)), ainf(w(to, C), qinf(QC, LT))) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(ainf(w(_, C), L), ainf(w(to, C), LT)) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(neg(C0), neg(C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(nega(sub(NP0)), nega(sub(NP))) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(nega(C0), nega(C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(cmp(K, NP0), cmp(K, NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(cmpc(K, S0), cmpc(K, S)) :- !, tr_side_here(Side), tr_cross(Side, S0, S).
tr_cross_comp(asmuch(NP0), asmuch(NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(cmpp(A0, K, PP0), cmpp(A, K, PP)) :- !,
    ( A0 == none -> A = none ; A0 = w(W, C), tr_word_across(w(W, lower), english, adverb, AT), A = w(AT, C) ),
    tr_cross_comp(PP0, PP).
tr_cross_comp(cmpi(K, Cs0), cmpi(K, Cs)) :- !, tr_cross_comps(Cs0, Cs).
tr_cross_comp(mt(Ws0), mt(Ws)) :- !, tr_cross_adjectives(Ws0, Ws).
tr_cross_comp(nprep(w(P, C)), nprep(w(PT, C))) :- !, tr_prep_across(P, PT).
tr_cross_comp(qm(QC, C0), qm(QC, C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(qm2(QC, C0), qm2(QC, C)) :- !, tr_cross_comp(C0, C).
tr_cross_comp(pinf(W, qinf(QC, L0)), pinf(WT, qinf(QC, L))) :- !, tr_cross_comp(pinf(W, L0), pinf(WT, L)).
tr_cross_comp(pinf(w(P, C), perf(L, Cls0)), pinf(w(PT, C), perf(LT, Cls))) :- !,
    tr_prep_across(P, PT), tr_lexeme_across(L, english, LT), maplist(tr_cross_enclitic, Cls0, Cls).
tr_cross_comp(pinf(w(P, C), cl(L, Cls0)), pinf(w(PT, C), cl(LT, Cls))) :- !,
    tr_prep_across(P, PT), tr_lexeme_across(L, english, LT),
    findall(X, ( member(Cl, Cls0), tr_cross_comp(opron(Cl), opron(X)) ), Cls).
tr_cross_comp(pinf(w(P, C), L), pinf(w(PT, C), LT)) :- !,
    tr_prep_across(P, PT), tr_lexeme_across(L, english, LT).
%% ... AND THE PARTITIVE AFTER A FIRST OR SECOND PERSON PRONOUN IS THE VERB'S
%% OWN: `occuparmene' is `occupare' with `mi' and `ne', the pronominal verb
%% that deals with it -- the pronoun that is partitive (`"ne" is
%% partitive.'), a second one after the first, says `of it' of nothing a
%% language writes, and crossed as `it' it came out `ocuparmelo', I occupy
%% me it
tr_cross_comp(infx(L, A, [R, P]), infx(LT, A, [Cl])) :-
    atom(R), atom(P), tr_solve(partitive(P)), memberchk(R, [mi, ti, ci, vi, si]), !,
    tr_lexeme_across(L, english, LT), tr_cross_enclitic(R, Cl).
%% AN INFINITIVE WITH ITS REFLEXIVE PRONOUN CROSSES BY THE MEANING THE LESSON GIVES IT SO, as the verb of a
%% clause does (tr_verb_across/5): `la libertà delle donne di denudarsi davanti ai telespettatori' is their
%% freedom to STRIP (`The reflexive verb "denuda" means "strips".'), and crossed by the plain `bares' it came out
%% `to bare', which Spanish has no verb for, and the sentence was refused. The pronoun goes with the reading,
%% unless English too says the meaning of oneself (en_true_reflexive/1), and the lesson's writer puts its own
%% back where its verb states the meaning as reflexive (tr_comp_out/7)
tr_cross_comp(infx(L, A, Cls0), infx(LT, A, Cls)) :-
    atom(L), select(R, Cls0, Cls1), atom(R), tr_reflexive_word(R), tr_solve(mean_as(L, LT, reflexive)), !,
    ( en_true_reflexive(LT) -> Cls2 = Cls0 ; Cls2 = Cls1 ),
    maplist(tr_cross_enclitic, Cls2, Cls).
tr_cross_comp(infx(L, A, Cls0), infx(LT, A, Cls)) :- !,
    tr_lexeme_across(L, english, LT), maplist(tr_cross_enclitic, Cls0, Cls).
tr_cross_comp(pred(L), pred(LT)) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(cverb(L), cverb(LT)) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(pagr(G, N), pagr(G, N)) :- !.
tr_cross_comp(predq(L, C), predq(LT, C)) :- !, tr_lexeme_across(L, english, LT).
tr_cross_comp(at_time(NP0), at_time(NP)) :- !, tr_cross_np(NP0, NP).
tr_cross_comp(cnj(w(C, CC)), cnj(w(CT, CC))) :- !, tr_cross_connector(foreign, w(C, CC), w(CT, CC)).
tr_cross_comp(cor(W), cor(W)) :- !.                       % `either', English already
tr_cross_comp(both(A0, B0), both(A, B)) :- !, tr_cross_comps(A0, A), tr_cross_comps(B0, B).
tr_cross_comp(nonlyc(A0, B0, Also), nonlyc(A, B, Also)) :- !, tr_cross_comps(A0, A), tr_cross_comps(B0, B).
%% a second verb joined to the first (tr_relative_clause/4): its
%% coordinator and its lexeme cross, its form stays the first one's
tr_cross_comp(cov(w(C, CC), L0, T, P, N), cov(w(CT, CC), L, T, P, N)) :- !,
    tr_cross_connector(foreign, w(C, CC), w(CT, CC)), tr_lexeme_across(L0, english, L).
tr_cross_comp(by(NP0), by(NP)) :- !, tr_as_doer(tr_cross_np(NP0, NP)).
tr_cross_comp(nor(NP0), nor(NP)) :- !, tr_cross_np(NP0, NP).
%% a second participle joined to a reduced relative's (tr_reduced_agent/3)
tr_cross_comp(cpart(w(C, CC), L0, Cs0), cpart(w(CT, CC), L, Cs)) :- !,
    tr_cross_connector(foreign, w(C, CC), w(CT, CC)), tr_lexeme_across(L0, english, L), tr_cross_comps(Cs0, Cs).
%% A DATIVE PRONOUN STAYS ONE: `gli' is to him, and the IR keeps it apart
%% from `lo', him himself, so a lesson that says which of its pronouns are
%% datives writes one of them (`le', `les') -- English has one word for both
tr_cross_comp(opron(w(W, C)), opron(dat(w(T, C)))) :-
    tr_lexeme(foreign, W, L, _), tr_solve(dative(L)), !, tr_pronoun_across(english, object, w(W, C), _, _, T).
tr_cross_comp(opron(w(W, C)), opron(w(T, C))) :- tr_pronoun_across(english, object, w(W, C), _, _, T).

%% `VERY' BEFORE A COMPARATIVE IS `MUCH': `Molto meglio, pensare con intelligenza al
%% futuro' is much better, and `basta assai meno del 50,1%' much less than it --
%% the lesson's `molto' and `assai' mean `very', which English and Spanish say
%% only of a word that is no comparison (`very better', `muy menos')
tr_much_before(very, B, much) :- en_comparative_adverb(B), !.
tr_much_before(A, _, A).
en_comparative_adverb(B) :- memberchk(B, [better, worse, more, less, 'more than', 'less than']).
%% (the phrase of a count of time after `da': a noun the lesson calls a time, in
%% the plural or with a count)
tr_duration_phrase(np(_, Num, _, w(W, _), Number)) :-
    atom(W), tr_lexeme(foreign, W, L, _), tr_holds(time(L)), ( Number == plural ; Num \== none ), !.

%% (a date that `since' can say: a year, or a time that says which and is PAST -- `desde la
%% semana pasada', `dal lunedì scorso' -- or a month or a day of the week as it stands; never one
%% of the future, `dalla settimana prossima' is from next week, and not one with an adjective of
%% another kind, `desde el primer momento' is from the first moment)
tr_since_phrase(np(_, none, [], w(W, _), _)) :- atom(W), atom_length(W, 4), tr_digits(W), !.
tr_since_phrase(NP) :-
    NP = np(_, _, Adjs, W, _), tr_time_which(NP), tr_noun_of_lesson(W, Noun),
    (   ( tr_holds(month(Noun)) ; tr_solve(mean(Noun, E)), tr_weekday(E) )
    ->  \+ tr_adjective_meant(Adjs, [next, forthcoming, following, coming])
    ;   tr_adjective_meant(Adjs, [past, last, previous])
    ).
tr_adjective_meant(Adjs, Meanings) :-
    member(A, Adjs), ( A = pre(w(AW, _)) ; A = w(AW, _) ), atom(AW),
    tr_lexeme(foreign, AW, L, _), tr_solve(mean(L, E)), memberchk(E, Meanings), !.

%% a pronoun joined to an infinitive: the reflexive is `refl' in the IR, as
%% the reflexive verb carries no pronoun of its own there; any other is the
%% English object pronoun it means
tr_cross_enclitic(Cl, refl) :- tr_reflexive_word(Cl), !.
%% ... and a dative stays one, as a dative before the verb does: `indicargli
%% un'edicola' is to show HIM a newsstand, and crossed as `him' it came out
%% `indicarlo un quiosco', him shown
tr_cross_enclitic(Cl, dat(w(T, lower))) :-
    tr_lexeme(foreign, Cl, L, _), tr_solve(dative(L)), !, tr_pronoun_across(english, object, w(Cl, lower), _, _, T).
tr_cross_enclitic(Cl, w(T, lower)) :- tr_pronoun_across(english, object, w(Cl, lower), _, _, T).

%% ---- reading: a question into the statement's order -------------------------------

%% A READING THAT FAILED FAILS AGAIN, AND IS NOT TRIED AGAIN. A sentence
%% with several commas is divided at each of them in turn, each side read
%% and each side divided again, so the same run of words is asked for over
%% and over: the tail after the second comma is read inside the division at
%% the first and again at the second. What failed is kept, for the piece
%% being read, in one assoc keyed on the words themselves, and asked for
%% before anything is tried; a reading that succeeds is the first and only
%% one (every clause below cuts), so there is nothing to keep for it.
%% (A QUESTION IS NO COMMAND: `Mangiate il pane?' asks, and with no second
%% person plural of the present in the vocabulary it read as the command its
%% form also is, `¿Comed el pan?' -- refused now, where it was wrong)
tr_read(Side, Kind, Words, S) :-
    tr_global('$tr_no_command', NC0),
    %% A QUESTION IS NO COMMAND, and reads with the command standing down: `Sembra poco?', `Mangia il
    %% pane?' have the spelling of an imperative, whose clause took the sentence and, its cut kept every
    %% other reading from it, left the question to be refused below
    ( Kind == question -> NC = yes ; NC = NC0 ),
    Key = k(Side, Kind, Words, NC),
    tr_failed_set(F0),
    (   get_assoc(Key, F0, _) -> fail
    ;   ( NC == NC0 -> true ; nb_setval('$tr_no_command', NC) ),
        tr_read0(Side, Kind, Words, S0), \+ ( Kind == question, S0 = s(_, _, g(_, _, imperative, _), _) ),
        \+ tr_there_is_somebody(S0)
    ->  ( NC == NC0 -> true ; nb_setval('$tr_no_command', NC0) ),
        tr_wh_after_object(S0, S1), tr_clause_post(Side, Words, S1, S)
    ;   ( NC == NC0 -> true ; nb_setval('$tr_no_command', NC0) ),
        tr_failed_set(F1), put_assoc(Key, F1, x, F2), nb_setval('$tr_failed', F2), fail
    ).

%% `THERE IS' HAS NOBODY FOR ITS SUBJECT, NAMED OR NOT: its subject is
%% `there' and what there is its object. `se mai ci sarà una causa e un
%% risarcimento non voglio ...' divided after `ci sarà', read that as a verb
%% of somebody nobody named with nothing after it, and gave the lawsuit and
%% the compensation to `voglio' for a subject
%% ... WHERE NOTHING IS SAID TO BE THERE: `ci sarà' alone, with nothing after
%% it and nothing asked. With what there is after it or asked for, the
%% reading stands as it always did: the first cut refused every one, and
%% `che cosa ci sarebbe di male se durasse indefinitamente?', `Ci sono,
%% invece, ed è un problema grave ..., enormi differenze economiche' had no
%% other reading at all
tr_there_is_somebody(s(Asked, null(_, _), g(L, _, _, _), Cs)) :-
    atom(L), ( L == 'there is' -> true ; tr_solve(mean(L, 'there is')) ),
    \+ memberchk(obj(_), Cs), \+ Asked = object(_), !.

%% A QUESTION WORD AFTER THE VERB'S OWN OBJECT OPENS NO QUESTION. Right after
%% the verb it is the indirect question tr_complements0/4 reads (`sapere
%% come'), and after another complement tr_relative_wh/2 makes it the
%% relative one -- but an object PRONOUN stands before the verb and is no
%% complement there, so `l'abbiamo vinto quando gli altri erano vicini' was
%% the question `cuándo' in Spanish. It is the time the verb's object was
%% won at, rwh/2, as after any other complement. A dative is no object: `gli
%% ho chiesto quando arriva' asks.
tr_wh_after_object(s(A, Su, G, Cs0), s(A, Su, G, Cs)) :-
    memberchk(opron(w(_, _)), Cs0), memberchk(wh(_, _), Cs0), !,
    tr_relative_wh1(Cs0, Cs).
tr_wh_after_object(S, S).

%% what a clause's own words say once it is read, on the lesson's side: the
%% adverb that stood before its participle, and the gender its participle or
%% its adjective gives a subject that gives none
%% A DEMONSTRATIVE AFTER THE VERB AND THE NOUN AFTER IT ARE ONE SUBJECT: `no hubiera muerto aquel anciano' is that
%% old man dying, and `Murió aquel perro' that dog -- read as the pronoun `aquel' for the subject, the noun was
%% left for an object or a predicate, `That died dog', `that would not have died elderly'. A bare noun of the
%% lesson in the demonstrative's number
tr_demonstrative_subject(pronoun(third, N, D), [subj_here, X|Cs], np(det(Kind, DL, D), none, Adjs, NW, N), [subj_here|Cs]) :-
    D = w(DW, _), atom(DW), tr_determiner(foreign, D, DL, Kind), Kind == demonstrative,
    (   X = obj(np(none, none, Adjs, NW, N)), NW = w(_, _)
    ;   X = adj([NW]), Adjs = [], NW = w(AW, _), atom(AW), tr_is(foreign, w(AW, lower), noun),
        tr_lexeme(foreign, AW, _, N)
    ), !.
tr_demonstrative_subject(Su, Cs, Su, Cs).
%% THE VERB OF RESULTING, A PARTICIPLE AND A PHRASE AFTER IT: `donde resultó herido el artificiero' is where the bomb
%% disposal expert was injured -- read as an absolute clause after a verb with nobody named, the expert was what the
%% injury left, `It resulted, the expert injured'. The phrase in the verb's number is its subject, kept where it
%% stood (subj_here), and the participle its predicate, as `el artificiero resultó herido' has it
tr_results_subject(null(third, N), g(L, _, simple, _), [abs(P, NP0)|Cs0], NP, [pred(P), subj_here|Cs]) :-
    atom(L), tr_solve(mean(L, results)),
    ( NP0 = np(_, _, _, _, N) -> true ; NP0 = name(_), N == singular ),
    %% (with the phrases of `of' after it: `resultó herido el artificiero de la Guardia Civil', where the guard's phrase
    %% stood after the verb, `the expert was injured of the Civil Guard')
    tr_fo_of_run(Cs0, Ofs, Cs), !,
    ( Ofs == [] -> NP = NP0 ; NP = with(NP0, Ofs) ).
tr_results_subject(Su, _, Cs, Su, Cs).
%% A WORD THAT IS A PERSON'S NOUN AND AN ADJECTIVE, AFTER THE COMMA THAT CLOSES A SUBJECT SET AFTER THE VERB, IS WHAT
%% THE SUBJECT IS: `sostiene Rebeca López, vecina de Cala Crancs' is a resident of it -- read as the adjective it was
%% `Rebeca López maintains, neighbouring of Cala Crancs'. With its phrases it is the subject's apposition, appos/1, as a
%% reporting clause's is (tr_report_appos/2)
tr_person_appos(Cs0, Cs) :-
    append(Front, [sep, adj([w(W, C)])|Tail], Cs0), Tail = [pp(_, _)|_], forall(member(T, Tail), T = pp(_, _)),
    atom(W), tr_lexeme(foreign, W, L, N), tr_class_of(L, noun), tr_holds(person(L)), !,
    append(Front, [sep, appos(np(none, none, [], w(W, C), N))|Tail], Cs).
tr_subject_appos(Cs0, Cs) :-
    append(Pre, [subj_here|Post0], Cs0), tr_person_appos(Post0, Post), !, append(Pre, [subj_here|Post], Cs).
tr_subject_appos(Cs, Cs).
%% ... AND A NAME WITH WHAT IT IS SET BETWEEN COMMAS, AFTER A VERB OF SAYING WITH NOBODY NAMED, IS THE SPEAKER: `sostiene
%% Rebeca López, vecina de Cala Crancs, el lugar donde ...' -- the commas made the name and its noun an aside, and the
%% verb's object, `maintains Rebeca López', with nobody to maintain it. The name is the subject, kept where it stood,
%% and the noun with its phrases its apposition (a phrase with no `a' before it: Spanish marks a person it governs)
tr_aside_speaker(s(A, null(third, singular), g(L, T, Asp, Neg), [obj(app(name(N), aside, K))|Rest]),
                 s(A, name(N), g(L, T, Asp, Neg), [subj_here, sep, appos(NP)|Cs])) :-
    atom(L), tr_saying_verb(L), atom(K), catch(nb_getval(K, Ws), _, fail),
    tr_complements(foreign, Ws, Cs1),
    (   Cs1 = [obj(NP)|T1], NP = np(none, none, _, w(_, _), _), tr_of_class(NP, person) -> true
    ;   tr_person_appos([sep|Cs1], [sep, appos(NP)|T1])
    ), !,
    append(T1, Rest, Cs).
tr_aside_speaker(S, S).
%% `MORE' AND A PLURAL NOUN AFTER A VERB THAT TAKES AN OBJECT ARE THE OBJECT: `Pondrán más explosivos' -- they will put
%% more explosives, and read as the comparative of the adjective `explosivo' it was `They will put more explosive'.
%% The word for `more' is the determiner the lesson states (`The determiner "más" means "more".'), the noun one the
%% lesson has in the plural, and the verb no copula, no verb of seeming or becoming and none it calls intransitive
tr_more_noun(Words, L, Cs0, Cs) :-
    atom(L), \+ memberchk(obj(_), Cs0),
    append(Pre, [adj([deg(comparative, w(W, C))])|Post], Cs0), atom(W),
    \+ ( tr_solve(mean(L, M)), memberchk(M, [is, becomes, seems, remains, results]) ), \+ tr_solve(intransitive(L)),
    tr_is(foreign, w(W, lower), noun), tr_lexeme(foreign, W, NL, plural), tr_class_of(NL, noun),
    once(( member(w(DW, _), Words), atom(DW), tr_determiner(foreign, w(DW, lower), DL, determiner), tr_solve(mean(DL, more)) )), !,
    append(Pre, [obj(np(det(determiner, DL, w(DW, lower)), none, [], w(W, C), plural))|Post], Cs).
%% (and the word read as the adverb before a bare noun: `Pedro come más panes', where English wrote `eats breads more'
%% -- the adverb anywhere among the complements, where the reader moved it last, and the noun right after it in the
%% words: `reclaman más ayudas para asegurar su futuro' and `darle más libertad a tu hijo' were `demand helps to
%% ensure their future more' and `give freedom to your son more', found by the controls)
tr_more_noun(Words, L, Cs0, Cs) :-
    atom(L), select(adv(w(DW, DC)), Cs0, Cs1), atom(DW),
    append(Pre, [obj(np(none, none, Adjs, w(W, C), Nb))|Post], Cs1), atom(W),
    \+ memberchk(obj(_), Pre), append(_, [w(DW, _), w(W, _)|_], Words),
    \+ ( tr_solve(mean(L, M)), memberchk(M, [is, becomes, seems, remains, results]) ),
    tr_determiner(foreign, w(DW, lower), DL, determiner), tr_solve(mean(DL, more)), !,
    append(Pre, [obj(np(det(determiner, DL, w(DW, DC)), none, Adjs, w(W, C), Nb))|Post], Cs).
tr_more_noun(_, _, Cs, Cs).
tr_clause_post(foreign, Words, s(A, SuIn0, G, CsIn0), S) :- !,
    G = g(L, _, Asp, _),
    tr_gerund_subject(SuIn0, G, CsIn0, SuIn, CsIn),
    tr_demonstrative_subject(SuIn, CsIn, SuR, CsR),
    tr_results_subject(SuR, G, CsR, Su0, Cs0r),
    tr_subject_appos(Cs0r, Cs0s),
    tr_more_noun(Words, L, Cs0s, Cs0w),
    tr_warned_infinitive(Cs0w, Cs0p),
    tr_pronoun_adj(Cs0p, Cs0q),
    tr_pronoun_as_adjective(Cs0q, Cs0r2),
    tr_weekday_date(L, Cs0r2, Cs0r3),
    tr_of_participle_head(Cs0r3, Cs0r4),
    tr_lasting_participle(Cs0r4, Cs0r5),
    tr_joined_participle(Cs0r5, Cs0n),
    tr_subject_name_after(L, Su0, Cs0n, Su0n, Cs0),
    tr_subject_adverb_out(Su0n, Cs0, Su0a, Cs0a),
    tr_dislocated_subject(Su0a, Cs0a, Su, Cs00),
    tr_group_adverb(Words, L, Asp, Cs00, Cs01),
    tr_di_comparison(Cs01, Cs01a),
    tr_form_of_phrase(Cs01a, Cs01e),
    tr_like_participle(Cs01e, Cs01c),
    tr_of_participle(Cs01c, Cs01d),
    tr_of_passive(L, Asp, Cs01d, Cs01b),
    tr_of_pred(Cs01b, Cs02),
    tr_ago_order(Cs02, Cs02b0),
    tr_ago_in_comparison(Cs02b0, Cs02b1),
    tr_comparative_adverb(L, Cs02b1, Cs02b),
    tr_ago_phrase(Cs02b, Cs02c),
    tr_there_clitic(L, Cs02c, Cs03),
    tr_object_appos(Cs03, Cs04),
    tr_second_agent(Cs04, Cs04b),
    tr_participle_predicate(L, Cs04b, Cs1),
    tr_subject_agreement(Su, Words, L, Asp, Cs1, Cs1a),
    tr_pred_after_phrase(Su, Words, Cs1a, Cs1b),
    tr_adj_subject_comma(Su, Cs1b, Cs),
    tr_aside_speaker(s(A, Su, G, Cs), Sa),
    tr_see_passive(Sa, S0),
    tr_accident(S0, S1),
    tr_se_passive(S1, S2),
    tr_si_partitive(S2, S3),
    tr_gapping(S3, S4),
    tr_gap_time(S4, S5),
    tr_vos_subject(S5, S).
tr_clause_post(_, _, S, S).
%% A CLAUSE WITH NOBODY NAMED AND TWO OBJECTS, A THING AND THEN A DOER, HAS THE DOER FOR
%% ITS SUBJECT: `Los ánimos se calmaron cuando cruzó la puerta de embarque número 24
%% una patrulla' -- a patrol crossed the gate, the lesson's languages putting the one
%% that does it last, and read as two objects English refused the clause. The first
%% phrase's noun is none the lesson calls a person, animate or a group, the second's is
%% one, in the verb's number, after a verb that takes an object
tr_vos_subject(s(A, null(third, Nb), G, [obj(Su), obj(NP2)|Post]), s(A, NP2, G, [obj(Su), subj_here|Post])) :-
    G = g(L, _, Asp, _), atom(L), Asp \== passive, \+ tr_copula_lexeme(L), \+ tr_solve(intransitive(L)),
    tr_thing_head(Su, N1), \+ tr_doer_noun(N1),
    tr_doer_head(NP2, Nb), !.
tr_vos_subject(S, S).
tr_doer_head(with(NP, _), Nb) :- !, tr_doer_head(NP, Nb).
tr_doer_head(rc(NP, _, _), Nb) :- !, tr_doer_head(NP, Nb).
tr_doer_head(nrc(NP, _, _), Nb) :- !, tr_doer_head(NP, Nb).
tr_doer_head(np(det(_, _, _), _, _, N, Nb), Nb) :- tr_doer_noun(N).
%% the noun of a phrase with its phrases, its number or its clause (`la puerta de
%% embarque número 24')
tr_thing_head(with(NP, _), N) :- !, tr_thing_head(NP, N).
tr_thing_head(app(NP, _, _), N) :- !, tr_thing_head(NP, N).
tr_thing_head(rc(NP, _, _), N) :- !, tr_thing_head(NP, N).
tr_thing_head(nrc(NP, _, _), N) :- !, tr_thing_head(NP, N).
tr_thing_head(np(det(_, _, _), _, _, N, _), N).
%% THE COPULA'S GERUND, A PHRASE AND A PHRASE AFTER IT ARE A SUBJECT AND ITS PREDICATE: `È una giornata decisiva, ...,
%% essendo la spartizione dei finanziamenti un momento cruciale nella vita dell'ente' -- the sharing out of the funds
%% being a crucial moment; read with nobody named, the sharing was the copula's object and the moment a time, and
%% English wrote `is the partition of the fundings a crucial moment'. The first phrase and its phrases of `of' are the
%% subject (with/2), the next phrase the predicate, as the source orders them -- the subject kept where it stood
%% (subj_here), after the gerund, which the lesson's language writes so: `siendo la partición ... un momento crucial'
tr_gerund_subject(none, g(L, present, gerund, _), Cs0, Su, Cs) :-
    atom(L), tr_copula_lexeme(L),
    append(Fr, [obj(NP1)|Rest0], Cs0), forall(member(F, Fr), F = fr(_)),
    NP1 = np(_, _, _, w(_, _), _),
    tr_fo_of_run(Rest0, Ofs, [X|Rest]), ( X = obj(NP2) ; X = at_time(NP2) ), NP2 = np(_, _, _, w(_, _), _), !,
    ( Ofs == [] -> Su = NP1 ; Su = with(NP1, Ofs) ),
    append(Fr, [subj_here, obj(NP2)|Rest], Cs).
tr_gerund_subject(Su, _, Cs, Su, Cs).
%% A NAME RIGHT AFTER A SUBJECT SET AFTER ITS VERB, A PERSON'S NOUN, IS THE PERSON'S: `entra il presidente Luigi Rossi
%% Bernardi e saluta ...' -- the president, Luigi Rossi Bernardi, enters, and read as the object the president entered
%% him, `the president enters Luigi Rossi Bernardi'. Before the verb the reader takes the name among the noun's words
%% (`Il presidente Luigi Rossi dorme'), and the name goes there
%% (with the clause's fronts before the verb the reader keeps no subj_here, and an intransitive verb's object is the
%% name: `Alle 9 di mattina, ..., entra il presidente Luigi Rossi Bernardi e saluta ...')
tr_subject_name_after(_, Su0, Cs0, Su, Cs) :-
    Su0 = np(D, Q, Adjs0, w(N, NC), singular), atom(N),
    append(Pre, [subj_here, obj(name(Name))|Post], Cs0), atom(Name),
    tr_of_class(Su0, person), !,
    append(Adjs0, [w(Name, upper)], Adjs), Su = np(D, Q, Adjs, w(N, NC), singular),
    append(Pre, [subj_here|Post], Cs).
tr_subject_name_after(L, Su0, Cs0, Su, Cs) :-
    Su0 = np(D, Q, Adjs0, w(N, NC), singular), atom(N), atom(L), tr_solve(intransitive(L)),
    append(Fr, [obj(name(Name))|Post], Cs0), atom(Name), Fr = [_|_], forall(member(F, Fr), F = fr(_)),
    tr_of_class(Su0, person), !,
    append(Adjs0, [w(Name, upper)], Adjs), Su = np(D, Q, Adjs, w(N, NC), singular),
    append(Fr, Post, Cs).
tr_subject_name_after(_, Su, Cs, Su, Cs).
%% ... AND THE ADJECTIVE THE READER TOOK FOR A PHRASE OF `OF', after a pronoun that takes the word before an adjective
%% (`"qualcosa" takes "di" before the adjective.'): `C'è qualcosa di nuovo' is something new, padj/2, where it was
%% `something of new' (tr_unjoin_pronoun_adj/3 takes `di nuovo' apart first)
tr_pronoun_adj(Cs0, Cs) :-
    append(Pre, [O, pp(w(P, _), np(none, none, [A], elided(_), singular))|Post], Cs0),
    ( O = obj(pronoun(w(W, C))) ; O = opron(w(W, C)) ), atom(W), atom(P),
    tr_solve(take_before(W, P, adjective)), !,
    append(Pre, [obj(padj(pronoun(w(W, C)), A))|Post], Cs).
tr_pronoun_adj(Cs, Cs).
%% A WORD THAT IS A PRONOUN AND AN ADJECTIVE, RIGHT AFTER A PHRASE, IS THE PHRASE'S ADJECTIVE: `non è una giornata
%% qualunque' is not an ordinary day -- `qualunque' is the lesson's `anybody' too, a pronoun that does not precede the
%% verb, and read as one after the object it was `It is not a day anybody'
tr_pronoun_as_adjective(Cs0, Cs) :-
    append(Pre, [obj(np(D, Q, Adjs0, w(N, NC), Nb)), opron(w(W, C))|Post], Cs0), atom(W), atom(N),
    tr_is(foreign, w(W, lower), adjective), !,
    append(Adjs0, [w(W, C)], Adjs), append(Pre, [obj(np(D, Q, Adjs, w(N, NC), Nb))|Post], Cs).
tr_pronoun_as_adjective(Cs, Cs).
%% A DAY OF THE WEEK AND THE DATE RIGHT AFTER IT ARE ONE TIME: `È giovedì 6 giugno' is Thursday, June 6, and read as
%% two the copula had a time and an object, `It is on Thursday June 6', and a verb two times, `sleeps on Thursday on
%% June 6'. It travels as app(Day, wdate, Date): the copula's object, any other verb's time
tr_weekday_date(L, Cs0, Cs) :-
    append(Pre, [at_time(Wk), C2|Post], Cs0), Wk = np(none, none, [], w(D, _), singular), atom(D),
    ( C2 = at_time(Date) ; C2 = obj(Date) ),
    Date = np(none, w(N, _), [], w(M, MC), singular), atom(N), tr_digits(N), tr_month(foreign, w(M, MC)),
    tr_lexeme(foreign, D, DL, _), tr_solve(mean(DL, E)), tr_weekday(E), !,
    App = app(Wk, wdate, Date),
    ( atom(L), tr_solve(mean(L, is)) -> R = obj(App) ; R = at_time(App) ),
    append(Pre, [R|Post], Cs).
tr_weekday_date(_, Cs, Cs).
%% A PARTICIPLE AFTER A PHRASE OF `OF' THAT AGREES WITH THE PHRASE BEFORE IT AND NOT WITH THE PHRASE OF `OF' IS THAT
%% PHRASE'S: `ai circa 300 organi del Cnr sparsi per la penisola' are the bodies scattered across it -- `sparsi' is
%% plural, the Cnr one, and hung on the nearest noun the participle agreed with the Cnr, `del Cnr esparcido'. The
%% reader carries the participle's own number (agrn/1, tr_rel_number/5); with the phrase before in that number the
%% participle goes on the two, rel(with(Phrase, [pp(Of, Noun)]), Lexeme, Complements), as a participle and its agent do
%% after a phrase and its own phrase (tr_np/3)
%% (and the phrase the participle's verb governs, right after it, goes with it: `sparsi per la penisola' are scattered
%% ACROSS it, `"sparge" takes "per" before the phrase.', where it was the clause's, `for the peninsula')
tr_of_participle_head(Cs0, Cs) :-
    append(Pre, [X1, pp(Of, rel(NP2, L, RCs0))|Post0], Cs0), Of = w(_, _), tr_means_of(foreign, Of),
    select(agrn(PN), RCs0, RCs1),
    ( X1 = pp(P1, NP1), X = pp(P1, R) ; X1 = obj(NP1), X = obj(R) ),
    NP1 = np(_, _, _, w(_, _), PN), ( NP2 = np(_, _, _, _, N2) -> true ; NP2 = name(_), N2 = singular ), N2 \== PN, !,
    (   RCs1 == [], Post0 = [pp(w(PW, PC), NP3)|Post], atom(L), atom(PW), tr_solve(take_before(L, PW, phrase))
    ->  RCs = [pp(w(PW, PC), gov(L, NP3))]
    ;   RCs = RCs1, Post = Post0
    ),
    R = rel(with(NP1, [pp(Of, NP2)]), L, RCs),
    append(Pre, [X|Post], Cs).
tr_of_participle_head(Cs, Cs).
%% THE PARTICIPLE OF A VERB THAT TAKES NO OBJECT, AND A TIME RIGHT AFTER IT, IS A CLAUSE IN THE PAST: `dopo uno
%% "scrutinio" durato mesi' is after an assessment that lasted months -- the time was the clause's and the participle
%% stood alone, `after a lasted assessment months' and `tras una valoración durada meses'. It is the phrase's relative
%% clause, its subject the phrase, as every language says it (`que duró meses')
tr_lasting_participle(Cs0, Cs) :-
    append(Pre, [X0, at_time(T)|Post], Cs0),
    ( X0 = pp(P, rel(NP, L, [])), X = pp(P, R) ; X0 = obj(rel(NP, L, [])), X = obj(R) ),
    atom(L), tr_solve(intransitive(L)), NP = np(_, _, _, w(_, _), N), T = np(_, _, _, w(_, _), _), !,
    R = rc(NP, subject, s(none, gap(third, N), g(L, past, simple, no), [at_time(T)])),
    append(Pre, [X|Post], Cs).
%% (and among the complements of a participle the clause has: `una sorta di maxipagella ... elaborata dalla
%% segreteria personale del presidente, dopo uno "scrutinio" durato mesi' -- the phrase of `after' is the
%% elaborating's)
tr_lasting_participle(Cs0, Cs) :-
    append(Pre, [X0|Post], Cs0),
    ( X0 = pp(P, rel(NP, L, RCs0)), X = pp(P, rel(NP, L, RCs)) ; X0 = obj(rel(NP, L, RCs0)), X = obj(rel(NP, L, RCs)) ),
    RCs0 = [_, _|_], tr_lasting_participle(RCs0, RCs), RCs \== RCs0, !,
    append(Pre, [X|Post], Cs).
tr_lasting_participle(Cs, Cs).

%% A SECOND PARTICIPLE JOINED TO A REDUCED RELATIVE'S, WITH NO AGENT: `secondo i "voti" assegnati e scritti su quei
%% fogli' are the votes assigned and written on those sheets -- the coordinator divided the phrase, and the second
%% participle, a noun too, was a second phrase, `according to the assigned votes and writings'. It is cpart/3, as
%% after an agent (tr_reduced_agent/3), agreeing with the same noun
tr_joined_participle(Cs0, Cs) :-
    append(Pre, [X0|Post], Cs0),
    ( X0 = pp(P, co(C, rel(NP, L1, Cs1), N2)), X = pp(P, rel(NP, L1, Cs2)) ; X0 = obj(co(C, rel(NP, L1, Cs1), N2)), X = obj(rel(NP, L1, Cs2)) ),
    N2 = np(none, none, [], w(W, _), Nb), atom(W), NP = np(_, _, _, _, Nb),
    tr_participle_here(foreign, W, L2), tr_participle_number(W, Nb), !,
    append(Cs1, [cpart(C, L2, [])], Cs2),
    append(Pre, [X|Post], Cs).
tr_joined_participle(Cs, Cs).

%% AN ADVERB THAT ENDS THE SUBJECT'S WORDS, RIGHT BEFORE THE VERB, IS THE CLAUSE'S: `la
%% campaña militar en Chechenia también prosigue' -- the subject's phrase took `también'
%% among its phrases (with/2), and Italian wrote it there, before the verb, `in Cecenia
%% anche continua', where it goes after it
tr_subject_adverb_out(with(NP, Items0), Cs, Su, [adv(W)|Cs]) :-
    append(Items, [adv(W)], Items0),
    %% (an adverb of one word, or one English writes with the verb, `ya no' -- no longer: one of several
    %% words is the phrase's own, `Las previsiones de evolución de este mercado a corto-medio plazo no son
    %% optimistas', the forecasts in the short to medium term, which Italian wrote between the copula and
    %% its adjective, `non sono a breve-medio termine ottimiste')
    W = w(AW, _), atom(AW),
    ( atomic_list_concat([_], ' ', AW) -> true ; tr_word_across(w(AW, lower), english, adverb, AT), en_mid_adverb(AT) ),
    %% (and never the word that denies, which a phrase may end on where the reading went astray: `Un dato
    %% confortante del quale non ci si può rallegrare' -- set after the verb it was `se nos puede no alegrar')
    \+ tr_solve(mean(AW, not)), !,
    ( Items == [] -> Su = NP ; Su = with(NP, Items) ).
tr_subject_adverb_out(Su, Cs, Su, Cs).

%% A VERB LEFT OUT AFTER ITS COORDINATOR, WITH A TIME FOR WHAT IS SAID: `la primera vuelta
%% ... tendrá lugar el 4 de junio y la segunda vuelta, tres semanas más tarde' -- the second
%% round takes place three weeks later. Read as one clause, the date and the round were one
%% object (`will take place June 4 and the second round') and the time after the comma the
%% verb's. After a time, the coordinator and a phrase, the comma and the times that end the
%% clause are the phrase's: cnj/1 and gapc/2, a clause of the same verb (tr_gapping/2), and
%% the first time is when
tr_gap_time(s(A, Su, G, Cs0), s(A, Su, G, Cs)) :-
    append(Pre, [obj(co(K, T1, NP)), sep|Rest], Cs0), Rest = [_|_],
    ( tr_time_phrase(T1) ; tr_date_phrase(T1) ),
    ( NP = np(_, _, _, _, _) ; NP = with(_, _) ; NP = name(_) ),
    forall(member(X, Rest), tr_time_comp(X)), !,
    append(Pre, [at_time(T1), cnj(K), gapc(NP, [sep|Rest])], Cs).
tr_gap_time(s(A, Su, G, Cs0), s(A, Su, G, Cs)) :-
    append(Pre, [at_time(T1), cnj(K), obj(NP), sep|Rest], Cs0), Rest = [_|_],
    ( NP = np(_, _, _, _, _) ; NP = with(_, _) ; NP = name(_) ),
    forall(member(X, Rest), tr_time_comp(X)), !,
    append(Pre, [at_time(T1), cnj(K), gapc(NP, [sep|Rest])], Cs).
tr_gap_time(S, S).
tr_time_comp(at_time(_)).
tr_time_comp(adv(_)).

%% THE COPULA LEFT OUT AFTER A COMMA: `i motori sono più efficienti, le benzine senza piombo, gli
%% antivegetativi meno dannosi, i detersivi quasi tutti biodegradabili' -- the petrol IS without lead and
%% the paints ARE less harmful, the clause's verb said once. Read as phrases among the copula's
%% complements, English wrote them as objects and turned the adjectives round: `the least harmful
%% antifouling paints', `the detergents everyone biodegradable almost'. After a copula and its
%% predicate, each phrase a comma opens with what follows it up to the next comma -- a phrase of a
%% preposition, an adjective, an adverb -- is gapc(Phrase, Predicate), a clause of the same verb; a phrase
%% with nothing after it has its last adjective for the predicate (`il gatto piccolo', the cat small),
%% and a superlative there is the comparative it says (`meno dannosi', less harmful)
tr_gapping(s(A, Su, G, [P1|Cs0]), s(A, Su, G, [P1|Cs])) :-
    G = g(L, _, _, _), atom(L), tr_copula_lexeme(L), ( P1 = adj(_) ; P1 = pred(_) ),
    Cs0 = [sep, obj(_)|_], tr_gap_segments(Cs0, Cs), Cs \== Cs0, !.
tr_gapping(S, S).
tr_gap_segments([], []) :- !.
tr_gap_segments([sep, obj(NP0)|Cs0], [sep, gapc(NP, Ps)|Cs]) :-
    tr_gap_preds(Cs0, Ps0, Rest), tr_gap_np(NP0, Ps0, NP, Ps), !,
    tr_gap_segments(Rest, Cs).
tr_gap_segments([C|Cs0], [C|Cs]) :- tr_gap_segments(Cs0, Cs).
tr_gap_preds([C|Cs], [C|Ps], Rest) :-
    C \== sep, functor(C, F, _), memberchk(F, [pp, adj, adv, opron, pred]), !, tr_gap_preds(Cs, Ps, Rest).
tr_gap_preds(Cs, [], Cs) :- ( Cs == [] ; Cs = [sep|_] ), !.
tr_gap_np(NP, Ps, NP, Ps) :- Ps = [_|_], NP = np(_, _, _, w(_, _), _), !.
tr_gap_np(np(D, Num, Adjs0, N, Nb), [], np(D, Num, Pre, N, Nb), [adj([J])]) :-
    N = w(_, _), append(Pre, [J0], Adjs0),
    (   J0 = deg(less(superlative), W) -> J = deg(less(comparative), W)
    ;   J0 = deg(superlative, W) -> J = deg(comparative, W)
    ;   J0 = w(_, _) -> J = J0
    ), !.

%% ... AND THE PARTITIVE AFTER THE IMPERSONAL `SI' IS WHAT IS DONE: `in molte zone della città si
%% stanno installando delle fosse settiche' are septic tanks being installed, and read as a phrase of
%% `of' it was `are installing of the septic tanks'. The reflexive verb in the plural with nobody named,
%% the contraction of `di' and the article first among its complements, a plural noun after it, in a
%% language whose indefinite article has such a plural (tr_partitive/3's); a verb that takes `di' has
%% the phrase it governs (gov/2), which this is not (`si lamentano dei veleni')
tr_si_partitive(s(A, null(third, plural), g(reflexive(L), T, Asp, Neg), [pp(w(PW, _), NP0)|Cs]),
                s(A, null(third, plural), g(reflexive(L), T, Asp, Neg), [obj(NP)|Cs])) :-
    NP0 = np(det(article, DL, _), Num, Adjs, w(NW, lower), plural), atom(PW), atom(DL), atom(NW), atom(L),
    tr_means_of(PW), tr_solve(mean(DL, the)),
    tr_partitive_language, !,
    NP = np(none, Num, Adjs, w(NW, lower), plural).
tr_si_partitive(S, S).

%% A THING'S REFLEXIVE IS A PASSIVE WHERE THE LESSON SAYS THE VERB TAKES ONE:
%% `El concurso se celebró anoche' was held last night, and written as read English
%% said the contest celebrated, and `la casa que se vende' the house that sells.
%% `"celebra" takes the passive.' names the verb, and the subject is a phrase
%% with a noun that is no person (`El comité se reunió' meets, and a lesson says
%% nothing of `reúne'). It is the reflexive's passive, g(reflexive(L), T, passive,
%% Neg), which English writes as one and the lesson's language as its reflexive
tr_se_passive(s(A, Su, g(reflexive(L), T, simple, Neg), Cs), s(A, Su, g(reflexive(L), T, passive, Neg), Cs)) :-
    atom(L), tr_thing_phrase(Su), tr_solve(take(L, passive)), !.
%% ... AND THE IMPERSONAL `se' WITH A THING AFTER ITS VERB: `En Internet se publica una revista para sus adeptos' --
%% a magazine is published, and written as read English had somebody nobody named publish it, `One publishes a
%% magazine'. The thing is the subject, kept where it stood (subj_here), as a plural verb's reflexive passive already
%% reads one (`se publican revistas')
tr_se_passive(s(A, impersonal, g(L, T, simple, Neg), Cs0), s(A, NP, g(reflexive(L), T, passive, Neg), Cs)) :-
    atom(L), tr_solve(take(L, passive)),
    append(Pre, [obj(NP)|Post], Cs0), \+ ( member(X, Pre), tr_object_comp(X) ), tr_thing_phrase(NP), !,
    append(Pre, [subj_here|Post], Cs).
%% (in the perfect too: `hasta que no se haya resuelto el caso' is until the case has been solved, where English
%% wrote `until one has resolved the case')
tr_se_passive(s(A, impersonal, g(L, T, perfect, Neg), Cs0), s(A, NP, g(reflexive(L), T, passive_perfect, Neg), Cs)) :-
    atom(L), tr_solve(take(L, passive)),
    append(Pre, [obj(NP)|Post], Cs0), \+ ( member(X, Pre), tr_object_comp(X) ), tr_thing_phrase(NP), !,
    append(Pre, [subj_here|Post], Cs).
tr_se_passive(S, S).
%% (a phrase with a noun that is no person, or a name: `Miss Mundo que anoche se
%% celebró' is the contest the name stands for, and a verb the lesson names
%% takes the passive of nobody)
tr_thing_phrase(NP) :- NP = np(_, _, _, w(_, _), _), \+ tr_of_class(NP, person).
tr_thing_phrase(name(_)).
%% (and one with its phrases of `of': `que las explosiones de Salou no se vincularan con una actuación terrorista' --
%% the explosions were not linked, and asked of the phrase whole English wrote `did not link')
tr_thing_phrase(with(NP, _)) :- tr_thing_phrase(NP).
%% ... in a relative clause whose gap is the subject, the phrase it sits on the thing
%% (and in the perfect, the passive's perfect: `tonnellate di piombo ... che si sono depositati nel
%% corso degli anni' have been deposited, and `have deposited' said they had put something down)
tr_se_passive_rc(NP, subject, s(A, gap(P, N), g(reflexive(L), T, perfect, Neg), Cs), s(A, gap(P, N), g(reflexive(L), T, passive_perfect, Neg), Cs)) :-
    atom(L), tr_thing_phrase(NP), tr_solve(take(L, passive)), !.
tr_se_passive_rc(NP, subject, s(A, gap(P, N), g(reflexive(L), T, simple, Neg), Cs), s(A, gap(P, N), g(reflexive(L), T, passive, Neg), Cs)) :-
    atom(L), tr_thing_phrase(NP), tr_solve(take(L, passive)), !.
tr_se_passive_rc(_, _, S, S).

%% A PHRASE AFTER AN OBJECT AND ITS COMMA IS THE OBJECT'S APPOSITION, no second
%% object: `Amava teneramente Marisa Rivolta, la sua compagna d'autunno' -- read
%% as two objects the second took the marker of a person before it, `a su
%% compañero'. It is appos/1, as a reporting clause's is (tr_report_appos/2),
%% and the writers put no marker before it. A name or a phrase with its
%% determiner, after the clause's first object and with nothing but phrases of
%% a preposition after it
tr_object_appos(Cs0, Cs) :-
    append(Front, [obj(NP1), sep, obj(NP2)|Tail], Cs0), \+ memberchk(obj(_), Front),
    tr_appos_head(NP1), tr_appos_phrase(NP2),
    forall(member(T, Tail), T = pp(_, _)), !,
    append(Front, [obj(NP1), sep, appos(NP2)|Tail], Cs).
tr_object_appos(Cs, Cs).
%% A PHRASE THAT IS NOT `OF' AFTER THE PARTICIPLE OF A PREDICATE OR OF AN APPOSITION IS THE PARTICIPLE'S, as
%% a subject's is (tr_participle_adjunct/4): `Ventola es un delantero forjado en la cantera del Inter'
%% is a forward forged in the youth academy, and taken for the clause's phrase the participle stood in front
%% of its noun, `a forged forward in the youth academy'. Only after the copula or an apposition: after any
%% other verb the phrase may be the verb's (`compró un coche usado en Madrid')
tr_participle_predicate(L, Cs0, Cs) :-
    (   atom(L), tr_copula_lexeme(L), Wrap = obj
    ;   Wrap = appos
    ),
    Term0 =.. [Wrap, rel(N, Part, [])], Term =.. [Wrap, rel(N, Part, [pp(P, X)])],
    append(Front, [Term0, pp(P, X)|Tail], Cs0),
    P = w(PW, _), atom(PW), \+ tr_means_of(foreign, P), !,
    append(Front, [Term|Tail], Cs1), tr_participle_predicate(L, Cs1, Cs).
%% ... AND SO IS ONE AFTER A PARTICIPLE IN THE PREDICATE'S PHRASE OF `of': `Xavier Oliveras es el autor de la placa
%% original dedicada al Salvador Seguí' is the author of the plaque dedicated to him, and with the phrase of `to'
%% the clause's English wrote `the author of the devoted plaque to Salvador Seguí'
tr_participle_predicate(L, Cs0, Cs) :-
    atom(L), tr_copula_lexeme(L),
    append(Front, [obj(O), pp(Q, rel(N, Part, [])), pp(P, X)|Tail], Cs0),
    tr_means_of(foreign, Q), P = w(PW, _), atom(PW), \+ tr_means_of(foreign, P), !,
    append(Front, [obj(O), pp(Q, rel(N, Part, [pp(P, X)]))|Tail], Cs1), tr_participle_predicate(L, Cs1, Cs).
%% ... AND AFTER ANY VERB, WHERE THE PARTICIPLE'S MEANING TAKES THE PHRASE'S PREPOSITION IN ENGLISH: `Il programma
%% propone un ciclo di film dedicati alle grandi battaglie' is a cycle of films DEDICATED TO the great battles, and
%% with the phrase of `to' the clause's English wrote `a cycle of dedicated film to the big battles'. A phrase of
%% another verb may be the verb's (`compró un coche usado en Madrid'), so only where English says the participle
%% with that preposition (en_ptc_takes/2); the participle's own agreement marks may be there already
tr_participle_predicate(L, Cs0, Cs) :-
    append(Front, [obj(O), pp(Q, rel(N, Part, Ms)), pp(P, X)|Tail], Cs0),
    tr_means_of(foreign, Q), forall(member(M, Ms), ( M = agr(_) ; M = agrn(_) )),
    P = w(PW, _), atom(PW), \+ tr_means_of(foreign, P), atom(Part),
    tr_lexeme_across(Part, english, PE), tr_prep_across(PW, PT), en_ptc_takes(PE, PT), !,
    append(Ms, [pp(P, X)], Ms1),
    append(Front, [obj(O), pp(Q, rel(N, Part, Ms1))|Tail], Cs1), tr_participle_predicate(L, Cs1, Cs).
tr_participle_predicate(_, Cs, Cs).
%% A SECOND AGENT AFTER THE COMMA, WITH ITS OWN TIME: `in una intervista trasmessa giovedì sera dalla tv danese, e
%% ieri da quella svedese' -- broadcast by the Danish television, and yesterday by the Swedish one, the participle left
%% out. Read as the clause's, `da quella svedese' was a phrase of `from' and English wrote `from the Swedish one'. A
%% reduced relative whose agent ends its complements, and after the comma a coordinator, adverbs or a time, and the
%% word for `by' and its phrase, then a comma: the second agent is the participle's, and the comma closes it
tr_second_agent(Cs0, Cs) :-
    append(Pre, [pp(Q, rel(N, L, RCs0)), sep, cnj(Co)|Rest0], Cs0), last(RCs0, by(_)),
    append(Mid, [pp(w(B, BC), NP2), sep|Rest], Rest0), Mid \== [],
    forall(member(X, Mid), ( X = adv(_) ; X = at_time(_) )),
    atom(B), tr_means_by(foreign, w(B, BC)), !,
    append(RCs0, [sep, cnj(Co)|Mid], RCs1), append(RCs1, [by(NP2)], RCs),
    append(Pre, [pp(Q, rel(N, L, RCs)), sep|Rest], Cs).
tr_second_agent(Cs, Cs).
%% the participles English says with a preposition after them
en_ptc_takes(dedicates, to).    en_ptc_takes(devotes, to).    en_ptc_takes(addresses, to).
en_ptc_takes(links, to).        en_ptc_takes(destines, to).   en_ptc_takes(assigns, to).
tr_appos_head(name(_)).
tr_appos_head(np(_, _, _, _, _)).
tr_appos_phrase(name(_)).
tr_appos_phrase(np(det(_, _, _), _, _, _, _)).
%% ... and the one that stands for a noun left out: `il primo soccorso, quello del
%% bagnino' -- the first rescue, the lifeguard's -- is the rescue again, no
%% person, and with the marker of a person it came out `al del socorrista'
tr_appos_phrase(ell(det(_, _, _), _, _, _)).

%% ITALIAN'S `DI' AFTER A COMPARATIVE IS `THAN'. `Il soccorso immediato è più
%% importante dell'ambulanza' is more important THAN the ambulance, `Corre più
%% veloce di Luca' runs faster than Luca -- and read as the phrase of `of'
%% every writer said `de la ambulancia', `of the ambulance'. The lesson's
%% word for `of' stands for both, and only the degree tells them apart: the
%% superlative's `il più grande del mondo' is of the world and has the
%% superlative's degree, never the comparative's. So the phrase of `di' right
%% after a predicate adjective that ends on the comparative's degree -- the
%% commas between them kept -- is the term of the comparison, cmp(more,
%% Phrase) as `che' makes it, and each writer says its own word for `than'.
%% An adjective inside a noun phrase keeps its `di' (`un numero più alto di
%% casi' is a higher number OF cases): only the clause's own complements are
%% read here, and only the adjective that is one of them -- and the reader
%% sets an adjective after a phrase among them too (`per un numero sempre
%% maggiore di famiglie': a number, ever greater, OF families), which is the
%% phrase's own and keeps its `di'
tr_di_comparison(Cs0, Cs) :-
    append(Pre, [adj(As)|Post], Cs0), last(As, deg(comparative, _)),
    \+ tr_phrase_before(Pre),
    tr_comparison_seps(Post, Seps, [pp(P, NP)|Rest]), tr_means_of(foreign, P), !,
    append(Pre, [adj(As)|Seps], Front), append(Front, [cmp(more, NP)|Rest], Cs).
tr_di_comparison(Cs, Cs).
%% (a phrase stands before the adjective, adverbs apart: `un numero SEMPRE
%% maggiore')
tr_phrase_before(Pre) :-
    append(Pre1, Advs, Pre), forall(member(A, Advs), A = adv(_)), !,
    last(Pre1, Prev), ( Prev = pp(_, _) ; Prev = obj(_) ).
%% A PHRASE OF `of' RIGHT AFTER A PARTICIPLE THAT ENGLISH WRITES WITH ONE IS THE
%% PARTICIPLE'S: `è un tesoro tossico fatto di piombo' is a toxic treasure MADE
%% OF lead, `altre città europee dotate di canali' other European cities
%% endowed with canals -- taken for the clause's, the participle had no
%% complement and English wrote it before the noun, `a made toxic treasure of
%% lead'. The participle is a reduced relative with nothing of its own, an
%% object's or a phrase's, and its English verb one of en_of_participle/1; the
%% phrase is the one it governs, gov/2, so each writer says the preposition its
%% own verb takes (en_governs/2: endowed WITH canals)
tr_of_participle([C0, pp(P, X)|Cs0], [C|Cs]) :-
    tr_rel_slot(C0, rel(N, L, []), C, rel(N, L, [pp(P, gov(L, X))])),
    tr_means_of(foreign, P), atom(L), tr_lexeme_across(L, english, E), en_of_participle(E), !,
    tr_of_participle(Cs0, Cs).
tr_of_participle([C|Cs0], [C|Cs]) :- !, tr_of_participle(Cs0, Cs).
tr_of_participle([], []).
tr_rel_slot(obj(R0), R0, obj(R), R).
tr_rel_slot(pp(Q, R0), R0, pp(Q, R), R).
%% ... AND A PHRASE OF `of' AFTER A PASSIVE OR A PREDICATE WHOSE VERB ENGLISH WRITES WITH ONE IS THE VERB'S: `la
%% plaza estaba cubierta de botellas rotas' was covered WITH broken bottles, and English wrote `covered of', as it did
%% after the participle a comma sets off, `la plaza, cubierta de botellas rotas' -- the rule above takes a reduced
%% relative only. The phrase right after the passive, or right after the predicate, is the one the verb governs
tr_of_passive(L, passive, [pp(P, X)|Cs], [pp(P, gov(L, X))|Cs]) :-
    X \= gov(_, _), tr_means_of(foreign, P), atom(L), tr_lexeme_across(L, english, E), en_of_participle(E), !.
tr_of_passive(_, _, Cs, Cs).
tr_of_pred([pred(L), pp(P, X)|Cs0], [pred(L), pp(P, gov(L, X))|Cs]) :-
    X \= gov(_, _), tr_means_of(foreign, P), atom(L), tr_lexeme_across(L, english, E), en_of_participle(E), !,
    tr_of_pred(Cs0, Cs).
tr_of_pred([C|Cs0], [C|Cs]) :- !, tr_of_pred(Cs0, Cs).
tr_of_pred([], []).
%% `DE FORMA' AND AN ADJECTIVE AFTER A PHRASE ARE THE PHRASE'S, never how: `Navarro, en un momento de forma excepcional,
%% se encargó' is in a moment of exceptional form, and as the manner (tr_comp_out/7) it was `in a moment in an
%% exceptional manner'. Right after the verb, its adverbs or its object it says how (`transcurrió de forma intensa',
%% `come el pan de forma alegre'); after a phrase of a preposition it is that phrase's, and travels as nform/1, which
%% writes as a phrase
tr_form_of_phrase([X, pp(P, NP)|Cs0], [X, pp(P, nform(NP))|Cs]) :-
    X = pp(_, _), NP = np(none, none, [_|_], w(N, _), singular), atom(N),
    tr_lexeme(foreign, N, L, _), tr_solve(mean(L, form)), !,
    tr_form_of_phrase(Cs0, Cs).
%% (and inside an insertion, whose phrases come apart: `Navarro, en un momento de forma excepcional, se encargó')
tr_form_of_phrase([mid(X), mid(pp(P, NP))|Cs0], [mid(X), mid(pp(P, nform(NP)))|Cs]) :-
    X = pp(_, _), NP = np(none, none, [_|_], w(N, _), singular), atom(N),
    tr_lexeme(foreign, N, L, _), tr_solve(mean(L, form)), !,
    tr_form_of_phrase(Cs0, Cs).
tr_form_of_phrase([C|Cs0], [C|Cs]) :- !, tr_form_of_phrase(Cs0, Cs).
tr_form_of_phrase([], []).
%% ... AND A PHRASE OF `like' WITH NO DETERMINER RIGHT AFTER A PARTICIPLE IS THE PARTICIPLE'S: `cubierta de botellas
%% utilizadas como arma' is covered with bottles used as a weapon, and taken for the clause's the phrase stood after
%% the participle's noun, `covered of used bottles like weapon'. The participle is a reduced relative with nothing of
%% its own, an object's or a phrase's
tr_like_participle([C0, pp(P, X)|Cs0], [C|Cs]) :-
    X = np(none, none, _, w(_, _), _), tr_like_word(P),
    tr_rel_slot(C0, rel(N, L, []), C, rel(N, L, [pp(P, X)])), !,
    tr_like_participle(Cs0, Cs).
tr_like_participle([C|Cs0], [C|Cs]) :- !, tr_like_participle(Cs0, Cs).
tr_like_participle([], []).
en_of_participle(makes).     en_of_participle(composes).  en_of_participle(endows).
en_of_participle(equips).    en_of_participle(covers).    en_of_participle(fills).
en_of_participle(loads).     en_of_participle(plants).    % (`estaba todo sembrado de desperdicios', planted with)
tr_comparison_seps([sep|Cs0], [sep|Seps], Rest) :- !, tr_comparison_seps(Cs0, Seps, Rest).
%% ... and an adverb: `i canali risultano più inquinati persino di quelli della
%% zona industriale' are more polluted EVEN THAN those of the industrial zone, and
%% it was `more polluted of those ... even' (each writer puts the adverb before
%% its word for `than')
tr_comparison_seps([adv(W)|Cs0], [adv(W)|Seps], Rest) :- !, tr_comparison_seps(Cs0, Seps, Rest).
tr_comparison_seps(Rest, [], Rest).

%% THE TIME COMES BEFORE `AGO' IN THE IR, as it does in English: `due anni fa'
%% reads that way, and `hace dos años' put the adverb first -- so the Italian
%% writer wrote `fa due anni' from the Spanish and the Spanish `dos años hace'
%% from the Italian. The lesson says which words begin their time (`The word
%% "hace" begins the time.'), and the writer puts the adverb first for them
%% (tr_ago_first/0); the reader here sets what stood the other way round
tr_ago_order([], []).
tr_ago_order([adv(w(A, C)), at_time(NP)|Cs0], [at_time(NP), adv(w(A, C))|Cs]) :-
    atom(A), tr_solve(mean(A, ago)), !, tr_ago_order(Cs0, Cs).
tr_ago_order([fr(adv(w(A, C))), fr(at_time(NP))|Cs0], [fr(at_time(NP)), fr(adv(w(A, C)))|Cs]) :-
    atom(A), tr_solve(mean(A, ago)), !, tr_ago_order(Cs0, Cs).
tr_ago_order([C|Cs0], [C|Cs]) :- tr_ago_order(Cs0, Cs).
%% `VI' BEFORE A VERB WITH AN OBJECT OF ITS OWN IS `THERE': `hanno scavato 295mila metri cubi di
%% sedimenti, ... e vi hanno trovato la presenza di ben 11 veleni' found the poisons THERE, and read as
%% the plural of `ti' it was `have found you the presence'. The clause names its object and its verb is
%% no verb of giving or telling, which would make `vi' the person given to (a subject in the second
%% person plural has its `vi' read as its reflexive before this: `voi vi lavate le mani'). The adverb is
%% the lesson's first for `there'
tr_there_clitic(L, Cs0, Cs) :-
    select(opron(w(vi, C)), Cs0, adv(w(LA, C)), Cs), memberchk(obj(_), Cs0),
    atom(L), \+ ( tr_lexeme_across(L, english, E), en_dative_verb(E) ),
    once(( tr_solve(mean(LA, there)), tr_class_of(LA, adverb) )), !.
tr_there_clitic(_, Cs, Cs).
en_dative_verb(E) :- atom(E), memberchk(E, [gives, tells, says, shows, sends, brings, offers, asks, writes, explains,
    promises, sells, lends, teaches, pays, leaves, hands, presents, reads, sings, owes, returns, grants, demands,
    requests, suggests, recommends, describes, reports, communicates, announces, forbids, allows, permits, takes]).
%% ... AND A COUNT OF TIME AFTER A PREPOSITION TAKES ITS `ago' WITH IT: `come quarant'anni fa' is
%% like forty years ago and `inferiore a quello di trenta anni fa' lower than that of thirty years
%% ago -- the adverb stood apart from the phrase, so English wrote it after the comma that follows,
%% `like forty years, ago when there was', and Spanish, whose `hace' begins the time
%% (tr_ago_first/0), `como cuarenta años hace' and `al de treinta años hace'. The phrase is
%% ago(NP, Word), the time and its adverb, in a phrase of a preposition and in the phrase of `of'
%% of a phrase whose noun is left out
tr_ago_phrase([pp(P, NP0), adv(w(A, C))|Cs0], [pp(P, NP)|Cs]) :-
    atom(A), tr_solve(mean(A, ago)), tr_ago_inside(NP0, w(A, C), NP), !, tr_ago_phrase(Cs0, Cs).
%% ... AND A TIME BEFORE ITS `ago', A WHEN OF THE CLAUSE: `echó en cara hace una semana a Esteve Ferran ... que no se
%% hubiese alertado del peligro' reproached him a week ago -- with the adverb apart English wrote it after the
%% phrase that follows, `reproached a week to Esteve Ferran, mayor of Salou, ago'
%% ... AND ITS `before', a count of time before a past one: `La vicenda era nata sei mesi prima, esattamente il 31
%% ottobre 1984' was born six months before -- apart from the time, English wrote it after the date that follows,
%% `six months, exactly October 31, 1984 before'
tr_ago_phrase([at_time(NP0), adv(w(A, C))|Cs0], [at_time(ago(NP0, w(A, C)))|Cs]) :-
    atom(A), ( tr_solve(mean(A, ago)) ; tr_solve(mean(A, before)) ), tr_one_time(NP0), !, tr_ago_phrase(Cs0, Cs).
%% (and a count the word for `as many as' stresses, read as an object: `Proposto dai fisici ... ben otto anni fa' is
%% proposed a good eight years ago -- the stress goes, and the count of time is the when of the clause)
tr_ago_phrase([obj(advp(_, NP0)), adv(w(A, C))|Cs0], [at_time(ago(NP0, w(A, C)))|Cs]) :-
    atom(A), tr_solve(mean(A, ago)), tr_time_count(NP0), !, tr_ago_phrase(Cs0, Cs).
tr_ago_phrase([C|Cs0], [C|Cs]) :- !, tr_ago_phrase(Cs0, Cs).
tr_ago_phrase([], []).
%% ... AND THE TERM OF A COMPARISON THAT HOLDS THE COUNT OF TIME TAKES IT, in a language whose word for `ago' begins
%% the time: `la situación es notablemente mejor que la de hace un año' is better than that of a year ago -- `hace'
%% stood apart from the term, and English wrote the adverb before it, `that of a year notably ago', and Italian, in
%% the quotation, after the copula, `è fa migliore'
tr_ago_in_comparison(Cs0, Cs) :-
    memberchk(cmp(_, _), Cs0),
    select(adv(w(A, C)), Cs0, Cs1), atom(A), tr_solve(mean(A, ago)), tr_solve(begin(A, time)),
    append(Pre, [cmp(K, NP0)|Post], Cs1),
    (   tr_ago_inside(NP0, w(A, C), NP) -> true
    ;   NP0 = ell(D, G, Nb, pp(Q, T0)), tr_one_time(T0), NP = ell(D, G, Nb, pp(Q, ago(T0, w(A, C))))
    ), !,
    append(Pre, [cmp(K, NP)|Post], Cs).
%% (and inside a clause of `that', which this step does not pass: `Destacó de entrada que "la situación es notablemente
%% mejor que la de hace un año"')
tr_ago_in_comparison(Cs0, Cs) :-
    append(Pre, [that(s(A, Su, G, ICs0))|Post], Cs0), memberchk(cmp(_, _), ICs0),
    tr_ago_in_comparison(ICs0, ICs), ICs \== ICs0, !,
    append(Pre, [that(s(A, Su, G, ICs))|Post], Cs).
tr_ago_in_comparison(Cs, Cs).
%% A COMPARATIVE AFTER A VERB THAT IS NO COPULA IS THE ADVERB: `el debate va mejor en privado' goes better, and with the
%% degree of `bueno' (tr_degrees/4) Italian wrote the adjective, `va migliore'. The word the lesson says is the
%% comparative, where it is an adverb too, stands as the adverb; after the copula and a verb of seeming, becoming or
%% remaining it stays the adjective (`es mejor', `parece mejor')
tr_comparative_adverb(L, Cs0, Cs) :-
    append(Pre, [adj([deg(comparative, w(B, C))])|Post], Cs0), atom(B), atom(L), \+ tr_copula_lexeme(L),
    \+ ( tr_solve(mean(L, M)), memberchk(M, [is, becomes, seems, remains, results, appears, looks, sounds, feels]) ),
    tr_solve(comparative_of(W, B)), tr_class_of(W, adverb), !,
    append(Pre, [adv(w(W, C))|Post], Cs).
tr_comparative_adverb(_, Cs, Cs).
tr_one_time(NP) :- tr_time_count(NP), !.
tr_one_time(np(det(article, _, D), none, [], w(N, _), singular)) :-
    tr_indefinite(foreign, D), atom(N), tr_lexeme(foreign, N, L, _), tr_holds(time(L)), !.
tr_ago_inside(NP0, W, ago(NP0, W)) :- tr_time_count(NP0), !.
tr_ago_inside(ell(D, G, Nb, pp(Q, NP0)), W, ell(D, G, Nb, pp(Q, ago(NP0, W)))) :- tr_time_count(NP0), !.
tr_time_count(np(none, Num, [], w(N, _), _)) :- Num \== none, atom(N), tr_lexeme(foreign, N, L, _), tr_holds(time(L)), !.

%% WHAT HAPPENED TO SOMEBODY BY ACCIDENT IS WHAT THEY DID. `Es un efecto
%% especial que se les olvidó' is a special effect THEY forgot: Spanish says
%% it with the reflexive and the one it happened to as a dative -- the effect
%% forgot itself to them -- and read as written Italian wrote `che si gli
%% dimenticò' and English `that forgot itself them'. A lesson says which
%% verbs do it, `"olvida" takes the accident.', in the shape `"colpisce"
%% takes the experiencer.' has, and the IR says what happened: the dative is
%% the subject, in its person and number and named by nobody, what the verb
%% was said of is its object, and the verb is plain. Only with the reflexive
%% and a dative both: `Se olvidó el libro' is somebody forgetting it, and
%% `El libro me olvidó' a book that forgot me.
tr_accident(s(A, Su, g(reflexive(L), T, Asp, Neg), Cs0), s(A, Su2, g(L, T, Asp, Neg), Cs)) :-
    atom(L), Su \= gap(_, _), tr_accident_dative(L, Cs0, Cs1, Su2), !,
    (   append(Pre, [subj_here|Post], Cs1) -> append(Pre, [obj(Su)|Post], Cs)
    ;   Su = null(_, _) -> Cs = Cs1
    ;   Cs = [obj(Su)|Cs1]
    ).
%% ... and read with `se' for the impersonal subject, what the verb was said
%% of is the object already: `que se les olvidó' as that one forgot them
tr_accident(s(A, impersonal, g(L, T, Asp, Neg), Cs0), s(A, Su2, g(L, T, Asp, Neg), Cs)) :-
    atom(L), tr_accident_dative(L, Cs0, Cs, Su2), !.
tr_accident(S, S).
%% ... and in a relative clause whose gap is the subject, the gap is the
%% object: `que se les olvidó' is that they forgot
tr_accident_rc(subject, s(A, gap(_, _), g(reflexive(L), T, Asp, Neg), Cs0), object, s(A, Su2, g(L, T, Asp, Neg), Cs)) :-
    atom(L), tr_accident_dative(L, Cs0, Cs, Su2), !.
tr_accident_rc(Role, S, Role, S).
tr_accident_dative(L, Cs0, Cs, null(P, N)) :-
    tr_solve(take(L, accident)),
    select(opron(D0), Cs0, Cs), ( D0 = dat(w(D, _)) ; D0 = w(D, _) ), atom(D), \+ tr_reflexive_word(D),
    tr_object_pronoun(foreign, D, E), en_object_of(Sub, E), en_subject(Sub, P, N), !.

%% A NAME AFTER THE LAST COMMA OF A CLAUSE WHOSE SUBJECT NOBODY NAMED IS THAT
%% SUBJECT, SET AT THE END: `non lancia accuse, non chiede processi, Carolyn'
%% is Carolyn not asking, and `Vorrei che fossero sepolte assieme, Sofia e
%% Margherita' is the two of them buried together. Read as an object the
%% name took the word the lesson puts before a person, `no pide procesos, a
%% Carolyn'. A third person, in the verb's number, and its place is kept
%% (subj_here): every writer of the lesson's languages puts it back last
%% ... AND `loro' LAST AFTER THE VERB IS THEY: `che se ne sono accorti loro'
%% is that they noticed it themselves, and read as the dative `loro' puts
%% after a verb it was `que se les han dado cuenta', to them
tr_dislocated_subject(null(third, N), Cs0, Name, Cs) :-
    append(Pre, [sep, obj(Name)], Cs0), tr_name_list(Name, N), !,
    append(Pre, [sep, subj_here], Cs).
tr_dislocated_subject(null(third, plural), Cs0, pronoun(third, plural, w(W, C)), Cs) :-
    append(Pre, [opron(w(W, C))], Cs0), atom(W),
    tr_subject_pronoun(foreign, W, third, plural), !,
    append(Pre, [subj_here], Cs).
tr_dislocated_subject(Su, Cs, Su, Cs).
tr_name_list(name(_), singular).
tr_name_list(co(_, A, B), plural) :- tr_name_list(A, _), tr_name_list(B, _).

%% A DEGREE ADVERB BETWEEN THE AUXILIARY AND THE PARTICIPLE IS THE
%% PARTICIPLE'S: `è stata molto amata', `non è molto conosciuto' -- very
%% loved, very well known. Lifted as the clause's adverb (tr_adverbs_off/4),
%% every writer put it after the participle, `ha sido amado muy'. It travels
%% as gadv/1 and goes back before the participle. Only a word whose meaning
%% says a degree (tr_intensifier_meaning/2), which `anche' and `ancora' do
%% not: `si sono anche appellati' is still `se han llamado también'
tr_group_adverb(Words, L0, Asp, Cs0, Cs) :-
    memberchk(Asp, [passive, passive_perfect, perfect]),
    ( L0 = reflexive(L) -> true ; L = L0 ),
    select(adv(w(D, DC)), Cs0, Cs1), atom(D), tr_participle_degree(D),
    append(_, [w(D, _), w(P, _)|_], Words), atom(P), tr_participle_here(foreign, P, L), !,
    Cs = [gadv(w(D, DC))|Cs1].
tr_group_adverb(_, _, _, Cs, Cs).
%% ... and the word for `more' or `less' before it is its degree too: `sono
%% più occupati a controllare i biglietti' is they are more occupied, and
%% written last it was `son ocupados ... más'
tr_participle_degree(D) :- tr_degree_adverb(D), !.
tr_participle_degree(D) :-
    tr_lexeme(foreign, D, L, _), tr_solve(adverb(L)), once(tr_solve(mean(L, E))), memberchk(E, [more, less]), !.
%% ... and so is the word for `already': `Berlusconi era già convinto che
%% l'apertura ... fosse solo un modo' written last stood right before the
%% clause of `that', `era convencido ya que la apertura', which says since
tr_participle_degree(D) :-
    tr_lexeme(foreign, D, L, _), tr_solve(adverb(L)), once(tr_solve(mean(L, already))), !.
%% ... and so is an adverb the lesson gives a meaning of its own before a
%% participle (`The adjectival adverb "justamente" means "justly".'): `son
%% justamente retribuidos'
tr_participle_degree(D) :- tr_adjectival_meaning(D, _), !.
tr_degree_adverb(D) :-
    tr_lexeme(foreign, D, L, _), tr_solve(adverb(L)), tr_solve(mean(L, E)), en_degree_adverb(E), !.

%% A SUBJECT THAT SAYS NO GENDER LETS ITS PARTICIPLE OR ITS ADJECTIVE SAY
%% IT: `È stata molto amata', `io sono sicura', `mi sentivo tranquilla',
%% `Sofia è stata battezzata' -- the daughter, the mother, a girl. Nobody
%% named, a first person and a name give the writer no gender, and the
%% participle and the adjective came out `amado', `seguro', `callado',
%% `bautizado'. Where the form the source gave is feminine it travels as
%% sagr/1, and a writer takes it where the subject gives none
%% (tr_clause_gender/4)
tr_subject_agreement(Su, Words, L0, Asp, Cs, [sagr(feminine)|Cs]) :-
    tr_genderless_subject(Su),
    (   memberchk(Asp, [passive, passive_perfect]),
        ( L0 = reflexive(L) -> true ; L = L0 ),
        member(w(P, _), Words), atom(P), tr_participle_here(foreign, P, L)
    ;   member(adj(As), Cs), member(X, As), ( X = w(P, _) -> true ; X = int(_, w(P, _)) ), atom(P)
    ;   member(pred(L2), Cs), member(w(P, _), Words), atom(P), tr_participle_here(foreign, P, L2)
    ),
    tr_holds(feminine(P)), !.
tr_subject_agreement(_, _, _, _, Cs, Cs).
%% A PARTICIPLE AFTER A COMMA THAT AGREES WITH THE PHRASE OF A PREPOSITION BEFORE THE COMMA, AND NOT WITH THE SUBJECT,
%% IS SAID OF THAT PHRASE: `Los robos retrasaron la limpieza de la plaza, cubierta de botellas rotas' -- the square is
%% covered, and agreeing with the subject, the thefts, Italian wrote `coperti'. The form the source gave says which
%% (`cubierta' is the feminine singular); where it agrees with the subject too, the participle stays the subject's, as
%% `in piena libertà, regolamentate' is. It travels as phagr/0, which the writers' agreement reads
%% (tr_adj_after_comma/2)
tr_pred_after_phrase(Su, Words, Cs0, Cs) :-
    append(Pre, [pp(_, NP), sep, pred(L)|_], Cs0), \+ last(Pre, sep),
    NP = np(_, _, _, w(NW, _), NNb), atom(NW),
    once(( member(w(P, _), Words), atom(P), tr_participle_here(foreign, P, L) )),
    ( tr_holds(feminine(P)) -> PG = feminine ; PG = masculine ), tr_participle_number(P, PN),
    tr_noun_lexeme(foreign, NW, NNb, _, FN), tr_noun_gender(FN, NG), NG == PG, NNb == PN,
    \+ ( Su = np(_, _, _, w(SW, _), SNb), atom(SW), SNb == PN,
          tr_noun_lexeme(foreign, SW, SNb, _, SF), tr_noun_gender(SF, SG), SG == PG ), !,
    append(Cs0, [phagr], Cs).                          % (last, where no writer's pattern meets it)
tr_pred_after_phrase(_, _, Cs, Cs).
%% ... AND AN ADJECTIVE AFTER A COMMA THAT AGREES WITH THE SUBJECT, AND NOT WITH THE PHRASE BEFORE THE COMMA, IS THE
%% SUBJECT'S: `Otros 20 operarios debían llegar entre las 4.30 y las cinco de la mañana, provistos de dos camiones' --
%% the workers are equipped, and agreeing with the morning Italian wrote `attrezzata'. The source's form says so, and
%% the writers' agreement with the phrase stands down (suagr/0, tr_adj_after_comma/2)
tr_adj_subject_comma(Su, Cs0, Cs) :-
    Su = np(_, _, _, w(SW, _), SNb), atom(SW),
    append(_, [C1, sep, adj(As)|_], Cs0), ( C1 = obj(NP) ; C1 = pp(_, NP) ),
    NP = np(_, _, _, w(NW, _), NNb), atom(NW),
    last(As, w(AW, _)), atom(AW),
    ( tr_holds(feminine(AW)) -> AG = feminine ; AG = masculine ),
    ( tr_solve(plural_of(AW, _)) -> AN = plural ; AN = singular ),
    tr_noun_lexeme(foreign, SW, SNb, _, SF), tr_noun_gender(SF, SG), SG == AG, SNb == AN,
    \+ ( NNb == AN, tr_noun_lexeme(foreign, NW, NNb, _, NF), tr_noun_gender(NF, NG), NG == AG ), !,
    append(Cs0, [suagr], Cs).                          % (last, where no writer's pattern meets it)
tr_adj_subject_comma(_, Cs, Cs).
%% THE REFLEXIVE OF THE VERB OF SEEING AND A PARTICIPLE IS A PASSIVE: `la recogida también se vio afectada por el
%% accidente' -- the collection was affected by the accident, which Spanish says as it saw itself affected (`verse
%% obligado', Italian's `vedersi costretto'). Read as it stands, English wrote `saw itself affected', or a thing's
%% reflexive with nobody to be it. The participle right after the verb, and the verb the lesson's word for `sees'
%% (the phrase of `by' after it is its agent, as after a passive: `por el accidente', by/1)
%% (and adverbs before the participle stay the clause's: `también se vio afectada')
tr_see_passive(s(A, Su, g(reflexive(V), T, simple, Neg), Cs00), s(A, Su, g(L, T, passive, Neg), Cs)) :-
    atom(V), tr_solve(mean(V, sees)),
    append(Advs, [pred(L)|Cs0], Cs00), forall(member(X, Advs), X = adv(_)), atom(L), !,
    ( Cs0 = [pp(P, NP)|Cs1], tr_means_by(foreign, P) -> Cs2 = [by(NP)|Cs1] ; Cs2 = Cs0 ),
    append(Advs, Cs2, Cs).
tr_see_passive(S, S).
tr_genderless_subject(null(_, _)).
tr_genderless_subject(pronoun(P, _, _)) :- P \== third.
tr_genderless_subject(name(_)).
tr_genderless_subject(co(_, A, B)) :- tr_genderless_subject(A), tr_genderless_subject(B).

tr_failed_set(F) :- ( catch(nb_getval('$tr_failed', F0), _, fail) -> F = F0 ; empty_assoc(F) ).

%% a word that answers: English's `no' and `yes', and a word the lesson says
%% means one of them (`The adverb "no" means "no".')
%% ... AND AN INTERJECTION, which stands where an answer does: `"ah, lei dice
%% Catania e io penso a Maiorana' -- ah, you say Catania. A word the lesson
%% calls one (`The interjection "ah" means "ah".'), at the head and before a
%% comma, and English's own few; it crosses by the meaning the lesson gives
%% it as one
tr_answer_word(english, w(W, _)) :- !, memberchk(W, [no, yes, ah, oh]).
tr_answer_word(foreign, w(W, _)) :-
    tr_lexeme(foreign, W, L, _), ( tr_solve(mean(L, no)) ; tr_solve(mean(L, yes)) ; tr_solve(interjection(L)) ), !.
tr_answer_meaning(english, W, W) :- !.
tr_answer_meaning(foreign, W, T) :- tr_lexeme(foreign, W, L, _), member(T, [no, yes]), tr_solve(mean(L, T)), !.
tr_answer_meaning(foreign, W, T) :- tr_lexeme(foreign, W, L, _), tr_solve(interjection(L)), tr_solve(mean(L, T)), !.

%% A SENTENCE MAY HOLD SEVERAL CLAUSES, and where they divide is a comma or
%% a connecting word -- `Il blitz e riuscito, l'operazione e considerata
%% conclusa', `La sinistra l'ha attaccata perche Pivetti non si e adeguata'.
%% Half the newspaper sample needs it and none of it could be reached before,
%% because the comma was dropped in tr_words/2 and tr_split/2 divides on `.',
%% `!' and `?' alone.
%%
%% THE WHOLE PIECE IS TRIED AS ONE STATEMENT FIRST, which is what makes this
%% a strict addition: every sentence that read before reads the same way and
%% by the same clauses. Only when that fails is a division looked for, and a
%% division is taken only when BOTH sides read as clauses of their own --
%% which is what keeps `la sua identita e la sua nazionalita' one subject
%% rather than two sentences, with no rule about phrases needed.
%% A NOUN'S OWN CLAUSE AFTER AN INSERTION BETWEEN COMMAS: `En cuanto al anuncio por parte del
%% ayuntamiento, tras el publicitado robo, de que habían empezado ... los trámites para restaurarla,
%% Oliveras dice:' is the announcement THAT they had begun them. The clause opens after the comma that
%% closes the insertion, and read there it was a relative clause on the theft, `of which they had
%% begun' (tr_phrase_nrc/3), the noun's clause being read only where it follows its noun (tr_np/3's
%% ncl/2). The insertion -- a phrase of a preposition -- goes after the clause, which runs to its next
%% comma, and the words are read so: the noun, its clause, the insertion, the rest
tr_read0(foreign, Kind, Words0, S) :-
    tr_that_set(Ts), once(( member(w(T0, _), Words0), memberchk(T0, Ts) )),
    append(A, [comma|B], Words0), A = [_|_],
    append(Ins, [comma, P, W|C0], B), Ins = [I1|_], \+ memberchk(comma, Ins),
    W = w(WT, _), memberchk(WT, Ts), tr_clause_opener(foreign, [P, W]),
    tr_is(foreign, I1, preposition), last(A, H), tr_is(foreign, H, noun),
    ( append(C, [comma|Rest], C0), \+ memberchk(comma, C) -> RestPart = [comma|Rest] ; C = C0, RestPart = [] ),
    C = [_|_],
    append(A, [P, W|C], AC), append([comma|Ins], RestPart, InsRest), append(AC, InsRest, Words),
    tr_read(foreign, Kind, Words, S), !.
%% AN ADVERB AT THE HEAD, ITS COMMA, A COORDINATOR AND THE REST: `En todo caso, y aunque no soy
%% restaurador, me pongo a su disposición' is in any case, and although I am no restorer, I put
%% myself at their disposal. The front reads as the clause's own only where the clause comes after
%% its comma, and a coordinator there opens a second clause with nothing before it, so the
%% sentence had no reading. The adverb is a fragment of its own, and the rest is the coordinator's
tr_read0(foreign, statement, [A, comma, C|Rest], join(comma, gap([], [adv(A)]), S)) :-
    A = w(AW, _), atom(AW), \+ tr_connector(foreign, AW), tr_is(foreign, A, adverb),
    Rest = [_|_], tr_coord(foreign, C),
    tr_read(foreign, statement, [C|Rest], S), !.
%% A HEADING IN CAPITALS IS READ WITH NO VERB FIRST (tr_caps_piece/2):
%% the whole piece, as the verbless reading reads a heading, and only when
%% that fails is it read as any other sentence
%% A PREPOSITION AND A FREE RELATIVE IN FRONT OF THE CLAUSE: `E per chi viola
%% il divieto ci saranno multe' is fines for whoever breaks the ban. The front
%% holds a verb of its own, which the readers above took for the clause's, and
%% the sentence was refused. The word the lesson says begins the relative
%% (`The word "chi" begins the relative.') right after a preposition at the
%% head of the piece; the shortest run after it that reads as the relative's
%% phrase, with what follows it (a comma between them or none) read as the
%% sentence. The phrase goes in front of the clause (fr/1), where the source
%% had it.
tr_read0(foreign, statement, [P, w(R, RC)|Ws], S) :-
    tr_global('$tr_free_rel', yes), tr_global('$tr_piece', P0), P0 == [P, w(R, RC)|Ws],
    atom(R), tr_lexeme(foreign, R, RL, _), tr_solve(begin(RL, relative)),
    P = w(_, _), tr_is(foreign, P, preposition),
    once(( tr_solve(relative(RR)), tr_solve(mean(RR, that)) )),
    once(( tr_solve(mean(A, the)), tr_solve(article(A)), \+ tr_holds(feminine(A)), \+ tr_solve(plural_of(A, _)) )),
    append(RW, Main0, Ws), RW = [_|_], \+ memberchk(comma, RW),
    ( Main0 = [comma|Main] -> true ; Main = Main0 ), Main = [_, _|_],
    tr_gap_verb_next(foreign, RW),
    tr_relative_clause(foreign, [w(RR, lower)|RW], subject, S1),
    NP = ell(det(article, A, w(A, lower)), masculine, singular, rel(subject, S1)),
    nb_setval('$tr_piece', Main),
    (   tr_read(foreign, statement, Main, S0), S0 = s(Q, Su, G, Cs) -> nb_setval('$tr_piece', P0)
    ;   nb_setval('$tr_piece', P0), fail
    ), !,
    S = s(Q, Su, G, [fr(pp(P, NP))|Cs]).
tr_read0(foreign, statement, Words0, S) :- tr_heading_for_whom(Words0, S), !.
%% A PARTICIPLE AT THE HEAD, ITS PHRASES AND A COMMA, THEN A CLAUSE THAT NAMES ITS
%% SUBJECT: the clause's front, absolute clauses one or two (`Dimenticate le polemiche
%% e messe da parte le idee di ferree ordinanze come quella ... che intendeva proibire
%% ai cani di passeggiare o sostare in piazzetta, il sindaco si è dato ...': the
%% controversies forgotten and the ideas put aside, the mayor took up the services).
%% Read later, `dimenticate' was the command, forget!, and with the commas taken out
%% the relative clause took the mayor for the object of its verb -- so it is read here,
%% before anything takes the commas out
tr_read0(foreign, statement, [w(P, PC)|Ws], S) :-
    atom(P), tr_participle_here(foreign, P, _),
    append(FrontW, [comma|Tail], [w(P, PC)|Ws]), \+ memberchk(comma, Tail), Tail = [_, _|_],
    %% (the front one phrase with no mark in it, and the clause opening on its subject: asked of
    %% every piece that opens on a participle, `Penalizzati anche i nuclei dove è minore l'istruzione:
    %% ..., quelli senza alcun titolo ...' read all of it before its last comma as the front, 2.2
    %% million inferences for nothing)
    \+ ( member(X, FrontW), atom(X) ), tr_opens_on_subject(foreign, Tail),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, FrontW, Front), Front = [abs(_, _)|_], \+ memberchk(obj(_), Front),
    tr_read_statement(foreign, Tail, none, s(A, Su, G, Cs)), Su \= null(_, _), Su \== none, Su \== impersonal, !,
    findall(fr(X), member(X, Front), Fr), append(Fr, Cs, Comps),
    S = s(A, Su, G, Comps).
%% `a' AND AN INFINITIVE AT THE HEAD, BEFORE A COMMA, SAY ON WHAT CONDITION THE CLAUSE HOLDS: `a scavare bene nella
%% compatta testuggine della fisica italiana, qualche incrinatura si riesce a trovarla' is digging well into it, one
%% manages to find some crack -- with nothing to hang on the infinitive had no reading, and after an adverb English
%% wrote `to dig ... well', a purpose. It is the clause's front, a gerund (ger/2), which each writer writes as its
%% gerund, `digging', `cavando' (an adverb and its comma before them are a front of the clause too: `Insomma, ...')
tr_read0(foreign, statement, Words0, S) :-
    ( Words0 = [w(A0, AC), comma|Words], tr_plain_adverb(foreign, w(A0, AC)) -> Fr0 = [fr(adv(w(A0, AC)))] ; Words = Words0, Fr0 = [] ),
    Words = [w(P, _), w(V, VC)|Ws],
    atom(P), atom(V), tr_lexeme(foreign, P, PL, _), tr_class_of(PL, preposition), tr_solve(mean(PL, to)),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    append([w(V, VC)|FrontW], [comma|Tail], [w(V, VC)|Ws]), \+ memberchk(comma, Tail), Tail = [_, _|_],
    \+ ( member(X, FrontW), atom(X) ), tr_opens_on_subject(foreign, Tail),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    ( FrontW == [] -> ICs = [] ; tr_complements(foreign, FrontW, ICs) ),
    tr_read_statement(foreign, Tail, none, s(A, Su, G, Cs)), !,
    append(Fr0, [fr(ger(F, ICs))|Cs], Comps),
    S = s(A, Su, G, Comps).
%% AN ADVERB, ITS COMMA AND A GERUND CLAUSE ARE ONE GERUND CLAUSE WITH ITS FRONT: `"..., y, además, teniendo en
%% cuenta que es parte fundamental en este conflicto"' is besides, taking into account that it is a fundamental
%% part -- with the comma the gerund was read as a front with its clause of `that' left open, and the words after
%% `es' as a clause of their own, `parte' the verb that departs (`tenendo conto che, è grande')
tr_read0(foreign, statement, [w(A0, AC), comma, w(G, GC)|Ws], S) :-
    \+ memberchk(comma, Ws), tr_plain_adverb(foreign, w(A0, AC)),
    atom(G), tr_gerund_here(foreign, G, _),
    tr_read_statement(foreign, [w(G, GC)|Ws], none, s(none, none, g(L, present, gerund, Neg), Cs)), !,
    S = s(none, none, g(L, present, gerund, Neg), [fr(adv(w(A0, AC)))|Cs]).
tr_read0(Side, statement, Words0, S) :-
    tr_global('$tr_caps', yes), tr_global('$tr_piece', Piece), Piece == Words0,
    tr_as_heading(Words0, tr_verbless(Side, Words0, S)), !.
%% NOT ONLY ONE CLAUSE BUT ANOTHER: `"No sólo nos insultan, sino que mienten y
%% lo saben' -- the denial and the word for `only' open the first clause, and
%% after a comma the partner the lesson names for that word (or its `but')
%% opens the second, with the word for `that' where the lesson's language puts
%% one (`sino que') and `also' or `even' after it. Read clause by clause the
%% denial went to the first verb and the word for `only' was an adverb of it,
%% `Non ci abusano soltanto, ma che mentono e lo sanno', and `sino' a `but'
%% that joined nothing. It travels as join(nonlyj(Also, Case), S1, S2), each
%% clause read as it stands, the case the quotation mark that opened on the
%% denial; every writer says it in the words nonly/3 has (tr_nonly_words/6),
%% and a lesson says the partner takes the word for `that' before a clause
%% (`"sino" takes the clause.')
tr_read0(foreign, statement, [N, O|Ws], join(nonlyj(Also, NC), S1, S2)) :-
    tr_nonly_start([N, O|Ws]), N = w(_, NC), O = w(OW, _),
    append(AW, [comma, w(M, _)|BW0], Ws), AW \== [], atom(M),
    ( tr_solve(partner_of(M, OW)) -> true ; tr_solve(mean(M, but)) ),
    ( BW0 = [T1|BW1], tr_that_here(foreign, T1) -> true ; BW1 = BW0 ),
    BW1 \== [],
    tr_nonly_also(BW1, BW, Also),
    tr_read(foreign, statement, AW, S1),
    tr_read(foreign, statement, BW, S2), !.
%% ... AND NOT ONLY, A COMMA AND A CLAUSE, with no partner said: `non solo, mentre
%% le altre squadre si sono accaparrate Stoichkov, la Lazio si è limitata a
%% macerarsi' -- the first half of a not-only-but-also whose second half the
%% sentence leaves to the next. The two words are an adverb of the clause after
%% the comma, which they part with it (nonly/0, written in every language by
%% the words of nonly/3); read as the denial and the word for `only', the
%% clause was `Sólo la Lazio no duerme'
tr_read0(foreign, statement, [N, O, comma|Ws], join(comma, gap([], [nonly]), S2)) :-
    Ws = [_|_], tr_nonly_start([N, O]),
    tr_read(foreign, statement, Ws, S2), !.
%% A HEADLINE THAT OPENS ON A NOUN SPELLED LIKE A VERB IS THE NOUN FIRST:
%% `"tasse più care per studiare meglio"', `Tasse più alte per i più ricchi:
%% avete pensato ...' -- dearer fees to study better. `tasse' is the plural
%% of the noun `tassa', and read through that noun's plural it is the verb's
%% too, so the piece was THEY tax, dearer, with nobody named and an
%% adjective for what they tax. A bare plural noun at the head with its
%% adjective after it is the headline's phrase before it is a verb with no
%% subject: the verbless reading goes first, and only there
%% (never before a PARTICIPLE, which is the headline participle's of 1.8.4:
%% `Auto proibite nelle isole del sole.' is cars forbidden, and read here
%% `proibite' was the adjective `forbidden', which Spanish has no word for,
%% and the islands report's headline was refused)
tr_read0(Side, statement, [W0, W1|Ws], S) :-
    Side == foreign, W0 = w(N0, _), atom(N0),
    (   tr_global('$tr_piece', Piece), Piece == [W0, W1|Ws] -> true
    ;   tr_global('$tr_heading', H), H == [W0, W1|Ws]
    ),
    \+ tr_determiner(Side, W0, _, _), tr_is(Side, W0, noun), tr_lexeme(Side, N0, _, plural),
    ( tr_is(Side, W1, adjective) -> true ; W1 = w(D1, _), atom(D1), tr_degree_word(D1) ),
    \+ ( W1 = w(P1, _), atom(P1), tr_participle_here(Side, P1, _) ),
    tr_verbless(Side, [W0, W1|Ws], S), !.
%% ... AND ONE THAT OPENS ON A PREPOSITION AND A NAME, THEN A BARE NOUN
%% SPELLED LIKE A COMMAND: `Con Vittori laurea in astronautica.' -- with
%% Vittori, a degree in astronautics. `laurea' is the noun and what
%% `laureare' says to one person, and read as that command it was `Gradúa
%% en astronáutica con Vittori'. A command after a front with no comma is
%% the unlikely reading, and a bare noun with only prepositional phrases
%% after it is a headline's: the two parts are read apart and joined with no
%% verb. Only a form the lesson calls an imperative: `Con Maria parte per
%% Roma' is somebody leaving for Rome, `parte' being no command, and it
%% reads as it always did
tr_read0(Side, statement, [P, Nm, N|Post], S) :-
    Side == foreign, tr_global('$tr_piece', Piece), Piece == [P, Nm, N|Post],
    P = w(PW, _), atom(PW), tr_is(Side, P, preposition), Nm = w(_, upper), tr_name_word(Side, Nm),
    N = w(NW, lower), atom(NW), tr_is(Side, N, noun), tr_lexeme(Side, NW, _, singular),
    \+ tr_determiner(Side, N, _, _), tr_solve(imperative_of(NW, _)),
    Post = [P2|_], P2 = w(P2W, _), atom(P2W), tr_is(Side, P2, preposition),
    \+ memberchk(comma, Post),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, [P, Nm], C1), C1 = [pp(_, _)],
    tr_complements(Side, [N|Post], C2), C2 = [obj(np(none, none, [], _, singular))|PPs], PPs \== [],
    forall(member(X, PPs), X = pp(_, _)), !,
    append(C1, C2, Cs), S = gap([], Cs).
%% AN ADJECTIVE WITH ITS INTENSIFIER IN FRONT OF A SENTENCE, BEFORE ITS
%% COMMA: `Giovanissima, s'innamora di un matematico' -- very young, she falls
%% in love. The superlative is the lesson's word for `very' and the plain
%% form (tr_expand/3), and read with the commas out `molto giovane' was a
%% phrase, many a junior, the subject of the verb after the comma, so the
%% front reader below never ran. A piece that opens on an intensifier and
%% its adjectives and then a comma is read as that front first, agreeing in
%% number with the subject after it, as `Egoista e vigliacca, continuerà'
%% does (tr_front_adj_agrees/3)
tr_read0(foreign, statement, [A, J|Ws0], S) :-
    tr_intensifier(foreign, A, J),
    append(AdjW, [comma|Rest], Ws0), \+ memberchk(comma, AdjW), Rest = [R0|_], R0 \== comma,
    tr_complements(foreign, [A, J|AdjW], [adj(FA)]),
    tr_read(foreign, statement, Rest, S0),
    tr_front_on_first(S0, fr(adj(FA)), S, Su),
    tr_front_adj_agrees(foreign, FA, Su), !.
%% PHRASES AFTER A SEMICOLON CARRY ON A LIST: `Entre la audiencia se podía
%% ver a políticos como Enrique Lacalle; el conseller de Presidència de la
%% Generalitat, Xavier Trias; el ministro Josep Piqué y la delegada del
%% Gobierno, Julia García-Valdecasas.' The items have commas of their own, so
%% semicolons set them off, and a part with no verb in it read as no clause
%% at all -- a part of a sentence is verbless only in the gapped form, a
%% comma where the verb was. Each part is phrases and nothing else, the
%% clause before it with its verb left out (gap([], Complements)), and every
%% writer puts the semicolons back. Read with them taken out, the people after
%% the first became objects of their own, `Si potè vedere a Enrique Lacalle il
%% ministro Josep Piqué'.
%% ... AND A SENTENCE MAY BE THE LIST ALONE, going on from the one before:
%% `También actuales cargos de RTVE como ...; colegas de la competencia como
%% ...; así como el analista político Fernando Jáuregui, ...' -- the people
%% one could see, the verb in the sentence before. The first part is an item
%% too when no verb is in it. It is tried BEFORE the division below, which
%% reads a part with a comma as the gapped form: `también actuales cargos de
%% RTVE ..., además de la antecesora de éste' was a verb left out at that
%% comma, with nothing before the comma to do the seeing.
tr_read0(Side, Kind, Words0, S) :-
    memberchk(semicolon, Words0),
    append(Left0, [semicolon|Right0], Words0),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_semi_items(Side, Right, S2),
    (   Kind == statement, tr_semi_item(Side, Left, S1) -> true
    ;   tr_read(Side, Kind, Left, S1)
    ), !,
    S = join(semicolon, S1, S2).

%% A SEMICOLON DIVIDES FIRST. Every other reading below is tried on the
%% whole piece before a division is looked for, which is right for a comma
%% -- a comma is often inside a clause -- and wasted on a semicolon, which
%% never is: measured, one 40-word sentence with a `;' in it spent 185 s
%% refusing itself in whole-sentence readings before the split was tried.
tr_read0(Side, Kind, Words0, S) :-
    memberchk(semicolon, Words0),
    append(Left0, [semicolon|Right0], Words0),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_read(Side, Kind, Left, S1), tr_read(Side, statement, Right, S2), !,
    S = join(semicolon, S1, S2).
%% AN ANSWER BEFORE A COMMA IS NO DENIAL: `No, sería mucho pedir.' answers
%% the question before it -- no, that would be too much to ask. Read whole
%% with its commas taken out, the `no' denied the verb, `Non sarebbe molto
%% chiedere', which says the opposite. A word the lesson says means `no' or
%% `yes', at the head and before a comma, is the answer: a verbless left
%% side, gap/2 with ans/1, and the rest a sentence of its own. The answer
%% crosses by the meaning that makes it one, and never by the word's first:
%% `The word "no" means "not".' comes first in the lesson, and by it the
%% answer was `Non,' in Italian and `Not,' in English.
tr_read0(Side, Kind, [A|Ws0], S) :-
    A = w(_, _), tr_head_words(Ws0, Dsh, Right0), Right0 \== [],
    tr_answer_word(Side, A),
    tr_clause_words(Right0, Right), tr_read(Side, Kind, Right, S2), !,
    tr_head_join(Kind, gap([], [ans(A)|Dsh]), S2, S).
%% A PERSON AT THE HEAD, BEFORE A COMMA, IS WHO IS SPOKEN TO: `"professore
%% - gli ho chiesto - per lei questo dev essere un periodo molto
%% stressante?' -- professor, must this be a very stressful time for you. A
%% bare noun the lesson calls a person, or a name no lesson knows, at the
%% head of its sentence and with a sentence of its own after it: read with
%% the rest, the professor was the subject of a clause he is only spoken to
%% in. It is the vocative, a verbless left side, gap/2 with voc/1, written
%% back in front with its comma as an answer is.
tr_read0(Side, Kind, [N|Ws0], S) :-
    N = w(NW, _), atom(NW), tr_head_words(Ws0, Dsh, Right0), Right0 \== [], tr_at_piece_head([N]),
    %% (a NOUN first, which is cheap: `Niente, se la maggiore preoccupazione
    %% ...' read `niente' as a phrase to ask whether it is a person)
    (   tr_is(Side, N, noun), tr_np(Side, [N], NP0), NP0 = np(none, none, [], w(_, _), singular), tr_of_class(NP0, person) -> NP = NP0
    %% (a NAME only in a question: `Abachidze, en cambio, prefiere poner el
    %% acento ...' is Abachidze preferring, and read as who is spoken to,
    %% `prefiere' was a command -- `Abachidze, invece, preferisci'. A bare
    %% noun cannot be a subject in the lesson's languages, and a name can)
    ;   Kind == question, N = w(_, upper), tr_np(Side, [N], NP), NP = name(_)
    ),
    tr_clause_words(Right0, Right), tr_read(Side, Kind, Right, S2), !,
    tr_head_join(Kind, gap([], [voc(NP)|Dsh]), S2, S).
%% ... AND A TITLE WITH ITS NAME: `Ministro Salvini, non crede che comunque
%% anche un milione e duecentomila lire siano un bel po' di quattrini?' --
%% minister Salvini, do you not believe. A bare noun the lesson calls a
%% person and a name after it no lesson knows, with a comma after them:
%% read with the rest, the minister was the subject with a comma between
%% him and his verb, `Does Minister Salvini, not believe'. A title and a
%% name with no article before them are no subject in the lesson's
%% languages, as a bare noun is none.
tr_read0(Side, Kind, [N, M, comma|Ws0], S) :-
    N = w(NW, _), atom(NW), M = w(_, upper), tr_name_word(Side, M),
    tr_is(Side, N, noun), tr_at_piece_head([N, M]),
    tr_np(Side, [N, M], NP), NP = np(none, none, [_], w(_, _), singular), tr_of_class(NP, person),
    Ws0 \== [], tr_clause_words(Ws0, Right), tr_read(Side, Kind, Right, S2), !,
    tr_head_join(Kind, gap([], [voc(NP)]), S2, S).
%% THE COPULA AFTER A COMMA DIVIDES FIRST TOO, WHERE IT IS ALSO A NOUN: `el
%% telefonino ... estaba vacío, era de pega' -- it WAS a fake. `era' is an
%% era as well, and every reading of the whole piece took it for one: after
%% the comma, a fake era the telephone was empty with, and with the commas
%% taken out a phrase, `vacío era de pega'. After a comma, with no article
%% before it, a form of the copula that opens a clause with nobody named for
%% its subject opens that clause.
tr_read0(Side, Kind, Words0, S) :-
    Side == foreign, memberchk(comma, Words0),
    append(Left0, [comma, W|More], Words0), Left0 \== [], \+ memberchk(comma, More),
    W = w(V, lower), tr_is(Side, W, noun),
    tr_form(V, L, _, _, _), atom(L), tr_copula_lexeme(L),
    %% (never after a subject and an insertion that opens on a preposition: `Abbatino, prima di essere arrestato e
    %% di decidere di collaborare con l'autorità giudiziaria, era uno dei più noti malviventi' is the man who was one,
    %% and divided there he was a heading and the copula had nobody named, `it was one of')
    \+ ( append(SubjW, [comma, P|_], Left0), SubjW \== [], \+ memberchk(comma, SubjW),
         P = w(_, _), tr_is(Side, P, preposition), tr_subject(Side, none, SubjW, third, _, _) ),
    tr_read(Side, statement, [W|More], S2), S2 = s(_, null(_, _), _, _),
    tr_clause_words(Left0, Left), tr_read(Side, Kind, Left, S1), !,
    S = join(comma, S1, S2).
%% A QUOTATION AND THE CLAUSE THAT REPORTS IT: `... incastrati in un dirupo”
%% ha raccontato a Sky Tg24 Tornaboni.' The closing mark is where the
%% quotation's own clause ends (tr_speech_pieces/2 made it `endquote'), and
%% what follows is a REPORTING clause, whose subject stands after its verb
%% in the lesson's languages -- read by tr_read_reporting/3, and failing that
%% as a statement like any other.
%% A comma after the closing mark -- `son únicos ", dijo Claude Lebet' --
%% is the source's, and it is written back after the mark.
tr_read0(Side, Kind, Words0, S) :-
    member(E, [endquote, endquote_plain]), memberchk(E, Words0),
    append(Left0, [E|Right0], Words0), \+ memberchk(E, Left0),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_read(Side, Kind, Left, S1),
    ( tr_read_reporting(Side, Right, S2) -> true ; tr_read(Side, statement, Right, S2) ), !,
    ( Right0 = [comma|_] -> atom_concat(E, '_comma', C) ; C = E ),
    S = join(C, S1, S2).
%% ... and the reporting clause BETWEEN TWO DASHES, with a clause on each side:
%% `sono l'unico ad aver consigliato l'Egibren - conferma Casotto - Rosi
%% sapeva del farmaco' -- what a man said, who says so, and what he said
%% next, one quotation. The division below takes one dash and a closing one at
%% the end, and the two sides of this had a dash in them: the sentence was
%% refused. The first clause and who said so are read as the clause before a
%% closing dash is (dashes), and the clause after it follows with nothing
%% written between, as a quotation that goes on is (aside)
tr_read0(foreign, Kind, Words0, join(aside, join(dashes, S1, S2), S3)) :-
    %% (the two dashes, or the words between them set aside as one: tr_asides/3
    %% took `dice Casotto' for a phrase between two dashes, w(Key, dashed))
    (   memberchk(dash, Words0),
        append(Left0, [dash|R1], Words0), \+ memberchk(dash, Left0),
        append(Mid0, [dash|Right0], R1), \+ memberchk(dash, Mid0), Mid0 \== [], Right0 \== [], \+ memberchk(dash, Right0)
    ;   append(Left0, [w(K, dashed)|Right0], Words0), Left0 \== [], Right0 \== [],
        atom(K), nb_getval(K, Mid0), Mid0 = [_|_]
    ),
    tr_clause_words(Mid0, Mid), tr_read_reporting(foreign, Mid, S2),
    %% (the clause after the second dash begins on its subject or its verb, never on
    %% a preposition: `vedremo - aggiunge Riviezzo - su quali aspetti ...' goes on
    %% with the quotation, and reading it as a clause costs millions)
    \+ ( Right0 = [RW1|_], tr_is(foreign, RW1, preposition) ),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_read(foreign, Kind, Left, S1),
    tr_read(foreign, statement, Right, S3), !.
%% TWO HEADINGS PARTED BY A DASH: `"cinici e diseducativi" i film - Wargames di rai 1' -- what the films are, and whose
%% series it is. Each half reads alone as the heading it is, and the readers of a heading ask for the whole piece,
%% which neither half was, so the headline was refused. Each half is read as a piece of its own; the halves are
%% short, neither has a comma, and the second has no verb
tr_read0(foreign, statement, Words0, join(dash, S1, S2)) :-
    memberchk(dash, Words0), tr_global('$tr_piece', P0), P0 == Words0,
    append(Left, [dash|Right], Words0), Left = [_, _|_], Right = [_, _|_],
    \+ memberchk(dash, Right), \+ memberchk(comma, Left), \+ memberchk(comma, Right),
    length(Left, NL), NL =< 8, length(Right, NR), NR =< 8,
    \+ ( member(w(V, _), Right), atom(V), tr_verb_form_any(V) ),
    tr_as_piece(Left, tr_read(foreign, statement, Left, S1)),
    tr_as_piece(Right, tr_as_heading(Right, tr_verbless(foreign, Right, S2))), !.
%% ... and the reporting clause set off with dashes, a closing dash or none:
%% `bisognerebbe sapere come sono finiti lì – ha spiegato un soccorritore -.'
%% -- and never ONE capitalised word before the dash that a phrase reads:
%% that is the dateline below, and `Calcio - nell'ambito della
%% presentazione ...' read here as a clause `calcio', I kick
tr_read0(Side, Kind, Words0, S) :-
    memberchk(dash, Words0),
    append(Left0, [dash|Right0], Words0), \+ memberchk(dash, Left0),
    \+ ( Left0 = [W1], tr_dateline_word(Side, W1, _) ),
    ( append(Right1, [dash], Right0) -> Conn = dashes ; Right1 = Right0, Conn = dash ),
    \+ memberchk(dash, Right1),
    tr_clause_words(Left0, Left), tr_clause_words(Right1, Right),
    tr_read(Side, Kind, Left, S1),
    ( tr_read_reporting(Side, Right, S2) -> true ; tr_read(Side, statement, Right, S2) ), !,
    S = join(Conn, S1, S2).
%% A HEADLINE AFTER A SECTION'S NAME AND A DASH THAT OPENS ON A PLURAL NOUN AND
%% ITS ADJECTIVE: `Calcio - dichiarazioni varie del giocatore e del Ct della
%% Lazio in merito al mancato rinnovamento' -- statements various of the player
%% and the coach about the failed renewal. `varie' is what `variare' says as
%% well, and read with a verb the statements ranged: after the dash the
%% headline is read with no verb first, as it is alone (tr_read0/4's noun
%% spelled like a verb)
tr_read0(foreign, _, [W, dash, W0, W1|Ws], S) :-
    W0 = w(N0, _), atom(N0), \+ memberchk(dash, Ws),
    \+ tr_determiner(foreign, W0, _, _), tr_is(foreign, W0, noun), tr_lexeme(foreign, N0, _, plural),
    tr_is(foreign, W1, adjective), \+ ( W1 = w(P1, _), atom(P1), tr_participle_here(foreign, P1, _) ),
    tr_dateline_word(foreign, W, NP),
    tr_clause_words([W0, W1|Ws], Right),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_as_heading(Right, tr_verbless(foreign, Right, S2)), !,
    S = join(dash, gap([], [obj(NP)]), S2).
%% A DATELINE: `Roma - lo stato ha il diritto dovere di favorire ...'. A
%% news item opens with the place it was filed from and a dash, and the
%% sentence is what follows the dash -- which read as the clause above has
%% a lone name for a clause of its own, and was refused. The place is ONE
%% word the phrase reader takes for a name, at the head of the piece, and
%% it is written back where it stood, with its dash: `Roma – el estado
%% tiene ...'. A place of several words is not read, because a bare run of
%% capitalised words says nowhere where one name ends (tr_np/3).
%% ... AND A SECTION'S NAME IS ONE TOO, a noun the lesson knows: `Calcio -
%% nell'ambito della presentazione ..., il presidente del Napoli ricorda 25
%% anni del club' is filed under football, `Fútbol – ...'
tr_read0(Side, Kind, [W, dash|Right0], S) :-
    Right0 \== [], \+ memberchk(dash, Right0),
    tr_dateline_word(Side, W, NP),
    tr_clause_words(Right0, Right),
    tr_read(Side, Kind, Right, S2), !,
    S = join(dash, gap([], [obj(NP)]), S2).
%% ... AND A BYLINE BEFORE IT: `Di Elvira Naselli Roma - anche quest'anno il
%% governo ha reiterato il decreto ...' is by Elvira Naselli, filed from
%% Rome. The preposition of `of' and a name, then the place's one word and
%% the dash -- which is what says where the name ends, since a run of
%% capitals does not say it by itself. Written back as it stood.
tr_read0(Side, Kind, [w(P, PC)|Ws], S) :-
    Side == foreign, append(NameWs, [W, dash|Right0], Ws), NameWs = [_|_],
    Right0 \== [], \+ memberchk(dash, Right0),
    tr_is(Side, w(P, lower), preposition), tr_means_of(Side, w(P, lower)),
    forall(member(X, NameWs), X = w(_, upper)), tr_byline_name(Side, NameWs, N),
    tr_dateline_word(Side, W, NP),
    tr_clause_words(Right0, Right),
    tr_read(Side, Kind, Right, S2), !,
    S = join(dash, gap([], [pp(w(P, PC), name(N)), obj(NP)]), S2).
%% A LETTER'S SIGNATURE AND THE NEXT LETTER'S TITLE: `Monica Ferretti
%% Genova - Sestri P pacifismo "mascalzone".' closes one letter with the
%% writer's name and town and opens the next with its title -- names, a dash,
%% names, and a noun with the word it puts in quotation marks. Nothing in it
%% is a clause and nothing is said of anything, so it was refused; the marks
%% are what make the phrase a title, and a bare noun with plain adjectives
%% stays refused (`Big house.'). Every writer puts it back as it stood.
tr_read0(Side, statement, Words0, join(dash, gap([], [obj(name(NL))]), gap([], [obj(name(NR)), obj(NP)]))) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    append(LW, [dash|Rest], Words0), LW = [_, _|_], \+ memberchk(dash, Rest),
    forall(member(X, LW), X = w(_, upper)), tr_np(Side, LW, name(NL)),
    append(RW, TW, Rest), RW = [_|_], TW = [T1|_], T1 = w(_, lower),
    forall(member(X, RW), X = w(_, upper)), tr_np(Side, RW, name(NR)),
    tr_np(Side, TW, NP), NP = np(none, none, As, w(_, _), _),
    once(( member(w(_, Q), As), memberchk(Q, [qboth, qopen, qclose]) )), !.
%% ... AND ONE WHOSE TOWN ENDS ON ITS PROVINCE IN BRACKETS: `Clara Finetto
%% Giovanni Lupatoto (Vr) Bastiglia e termidoro.' is the writer, her town and
%% `(Vr)' for Verona, then the next letter's title, the Bastille and
%% Thermidor. The bracket is where the signature ends, and the title is bare
%% nouns joined, which nothing else here reads -- `Pane e vino.' standing
%% alone stays refused. Nothing is said of anything, and every writer puts it
%% back as it stood, join(aside, ...), the connector that writes nothing.
tr_read0(Side, statement, Words0, join(aside, gap([], [obj(name(NL)), paren(K)]), gap([], [obj(T)]))) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    append(LW, [w(K, paren)|TW], Words0), LW = [_, _|_], TW = [_|_],
    forall(member(X, LW), X = w(_, upper)), tr_np(Side, LW, name(NL)),
    tr_bare_title(Side, TW, T), !.
%% ... AND ONE WHOSE TITLE IS A PHRASE: `Pasquale Iacopino Roma il parco del
%% Giglio.' is the writer and his town, then the next letter's title, the
%% park of Giglio. The capitals end where the article begins, and the title
%% is a phrase a heading may be -- an article, its noun and what the noun
%% carries -- where the two above had bare nouns and a word in quotation
%% marks. Nothing is said of anything, join(aside, ...), as above.
tr_read0(Side, statement, Words0, join(aside, gap([], [obj(name(NL))]), gap([], Back))) :-
    tr_global('$tr_piece', P0), P0 == Words0, \+ memberchk(comma, Words0),
    append(LW, TW, Words0), LW = [_, _|_], TW = [w(A, lower)|_],
    forall(member(X, LW), X = w(_, upper)), tr_np(Side, LW, name(NL)),
    tr_is(Side, w(A, lower), article),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, TW, Back), Back = [obj(np(det(article, _, _), none, _, w(_, _), _))|PPs],
    forall(member(X, PPs), ( X = pp(P, _), tr_means_of(Side, P) )), !.
%% ... AND ONE WHOSE TITLE IS BARE PHRASES WITH WHAT THEY CARRY, AND COMMAS
%% BETWEEN THEM: `Giuseppe Iaconis Bovalino (r c) commento critico sulla
%% guerra tra serbi e bosniaci, decisione di genocidio, pulizia etnica e
%% nazismo da parte dei serbi aggressori.' -- the writer, his town and its
%% province by its initials, then the next letter's title. A title opens on
%% the noun it names, and it is read as a heading is (tr_verbless/3):
%% `commento' is also I comment, and read as a clause the title had a verb
%% and a first person nobody named. Every writer puts it back as it stood.
tr_read0(Side, statement, Words0, join(aside, gap([], [obj(name(NL)), paren(K)]), T)) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    append(LW, [w(K, paren)|TW0], Words0), LW = [_, _|_], TW0 = [w(N1, lower)|_],
    forall(member(X, LW), X = w(_, upper)), tr_np(Side, LW, name(NL)),
    tr_is(Side, w(N1, lower), noun),
    tr_list_commas(Side, TW0, TW),
    tr_as_heading(TW, tr_verbless(Side, TW, T)),
    ( T = gap([obj(np(none, none, _, w(_, _), _))|_], _) ; T = gap([], [obj(np(none, none, _, w(_, _), _))|_]) ), !.
%% A PARENTHESIS AT THE HEAD SAYS WHERE WHAT FOLLOWS CAME FROM: `(dal
%% "Washington Post", 13 luglio 1995) estratto brano dell'articolo ...'.
%% After a phrase a parenthesis is the phrase's (paren/1 among the
%% complements); at the head there is nothing for it to belong to, and the
%% sentence is what follows it, read as the whole piece. It is the
%% dateline's shape with nothing between the two, join(aside, ...), and
%% it goes back where it stood.
%% WHAT FOLLOWS IS READ AS A HEADING, because a line that opens with its
%% source is a caption: `estratto brano dell'articolo pubblicato dal
%% giornale ...' names what it is with no article, which a sentence standing
%% alone may not (`Voto del perro.' stays refused).
tr_read0(Side, Kind, [w(K, paren)|Right], S) :-
    Right \== [],
    tr_global('$tr_piece', P0), P0 == [w(K, paren)|Right],
    nb_setval('$tr_piece', Right),
    (   tr_as_heading(Right, tr_read(Side, Kind, Right, S2)) -> nb_setval('$tr_piece', P0) ; nb_setval('$tr_piece', P0), fail ), !,
    S = join(aside, gap([], [paren(K)]), S2).
%% ... and one set INSIDE the sentence between two dashes: `Sarò per
%% sempre grato – aggiunge Marchionne – al team di leadership'. The
%% sentence reads with the insertion taken out, and the insertion is the
%% reporting clause, written after the sentence between its dashes -- which
%% is where Spanish and English put one as readily as in the middle.
tr_read0(Side, Kind, Words0, S) :-
    memberchk(dash, Words0),
    append(Left0, [dash|Right0], Words0), \+ memberchk(dash, Left0), Left0 \== [],
    append(Mid0, [dash|After0], Right0), \+ memberchk(dash, Mid0), After0 \== [], \+ memberchk(dash, After0),
    tr_clause_words(Mid0, Mid), tr_read_reporting(Side, Mid, S2),
    %% (a word alone before it keeps a comma after it, which the reporting
    %% clause stood in: `"professore - gli ho chiesto - per lei ...' is the
    %% vocative, and `"no - mi ha risposto -, a me piace ...' the answer --
    %% ONLY A WORD A READING AT THE HEAD CAN TAKE: `Gallo - continua - mi ha
    %% lasciato ...' is Gallo leaving, and with a comma after the name every
    %% reading of the rest was tried under it, 1.3 million inferences for
    %% Ferlaino's twenty-first sentence and the same text)
    (   Left0 = [W1], After0 \= [comma|_], tr_head_word(Side, Kind, W1) -> append(Left0, [comma|After0], Main0)
    ;   append(Left0, After0, Main0)
    ),
    tr_clause_words(Main0, Main),
    %% ... OR BETWEEN TWO CLAUSES, EACH OF ITS OWN: `... a Colonia, "che però
    %% non è fornito di laboratori - sottolinea Filippo Graziani, preside
    %% della scuola ... - gli astronauti devono poi concludere la preparazione
    %% a Houston o Mosca' -- the centre has no laboratories, the dean
    %% stresses, and the astronauts must finish elsewhere. The sentence read
    %% with the insertion taken out had two clauses and nothing between them,
    %% so the astronauts were an OBJECT of `fornito', and the sentence took
    %% eleven minutes to come out that way. Each side is read as a clause of
    %% its own, and the reporting clause stays between its dashes, dmid/1,
    %% where the source put it -- first, and only where the side after the
    %% dashes names its own subject: `Gallo - continua - mi ha lasciato ...'
    %% and `Ma i primi dati di quest'anno - precisano al Ministero ... -
    %% suggerirebbero una tendenza al ribasso' go on the clause before them
    (   Left0 = [_, _|_], After0 = [A1|_], A1 \== comma,
        tr_clause_words(After0, Right), tr_opens_on_subject(Side, Right),
        tr_read(Side, Kind, Right, SR), tr_names_subject(SR),
        tr_clause_words(Left0, Left), tr_read(Side, statement, Left, SL), tr_last_statement(SL, s(_, _, _, _))
    ->  S = join(dmid(S2), SL, SR)
    %% ... AND A SIDE THAT OPENS ON THE VERB OF THE FIRST OR THE SECOND
    %% PERSON IS A CLAUSE OF ITS OWN, whose subject is nobody named: `"Non so
    %% com'è andata a Fregene - premette - posso solo parlare in astratto.'
    %% -- I do not know how it went, he prefaces, I can only speak in the
    %% abstract. No subject comes first there, and `posso' has none to take
    %% from the clause before it, as a third person's verb would
    ;   foreign == Side, Left0 = [_, _|_], After0 = [A2|_], A2 \== comma,
        tr_clause_words(After0, Right2), tr_opens_on_person(Right2),
        tr_read(Side, Kind, Right2, SR2),
        tr_clause_words(Left0, Left2), tr_read(Side, statement, Left2, SL2), tr_last_statement(SL2, s(_, _, _, _))
    ->  S = join(dmid(S2), SL2, SR2)
    ;   tr_read(Side, Kind, Main, S1)
    ->  S = join(dashes, S1, S2)
    ), !.
%% A NAME BETWEEN TWO CLAUSES, SET OFF BY COMMAS, IS THE SUBJECT OF BOTH:
%% `Fruga in una scatola piena di fotografie, Carolyn, sfoglia a occhi
%% asciutti le foto della figlioletta morta' -- Carolyn rummages and leafs
%% through. Each clause opens on its verb with nobody named, and the name is
%% the first one's subject after it, its place kept (subj_here): the
%% lesson's writer puts it back where it stood and English's puts it first,
%% and the second clause shares it. Read as three pieces, the name alone was
%% no clause, and the sentence was refused.
%% (both read with no command: `fruga' and `sfoglia' are commands as well)
%% (the commas and the name come joined when the first clause ends on a
%% noun, w(Name, appos), as an apposition does -- tr_list_commas/3)
tr_read0(foreign, statement, Words0, join(comma, s(A1, name(N), G1, Cs), S2)) :-
    (   append(Left0, [w(N, appos)|Right0], Words0) -> true
    ;   append(Left0, [comma|Rest0], Words0),
        append(NameWs, [comma|Right0], Rest0), NameWs = [_|_], \+ memberchk(comma, NameWs),
        forall(member(X, NameWs), X = w(_, upper)),
        ( tr_np(foreign, NameWs, name(N)) -> true ; tr_byline_name(foreign, NameWs, N) )
    ),
    Left0 = [w(V1, _)|_], atom(V1), tr_verb_form_word(V1),
    Right0 = [w(V2, _)|_], atom(V2), tr_verb_form_word(V2),
    tr_global('$tr_no_command', F0), nb_setval('$tr_no_command', yes),
    (   tr_clause_words(Left0, Left), tr_read(foreign, statement, Left, s(A1, null(third, singular), G1, Cs1)),
        tr_clause_words(Right0, Right), tr_read(foreign, statement, Right, S2), S2 = s(_, null(third, singular), _, _)
    ->  nb_setval('$tr_no_command', F0)
    ;   nb_setval('$tr_no_command', F0), fail
    ), !,
    append(Cs1, [sep, subj_here], Cs).
%% ... AND ONE AT THE END OF A QUOTATION THAT CLOSES AT ITS COMMA, WITH NO
%% SPEAKER NAMED: `"Il cane dorme, vista la casa", ha detto.' -- the last
%% word before the comma carries the closing mark, so what is before it was
%% said and the clause after it is the reporting one, the verb alone. With no
%% reading for it the sentence divided at both commas and made a clause of
%% `vista la casa', a headline passive, and the reporting clause was written
%% in the middle of what was said: `"El perro duerme, ha dicho, ..."'.
%% (tr_read_reporting/3 takes the verb alone or with its speaker, as a
%% quotation's own mark says it may)
tr_read0(Side, statement, Words0, S) :-
    Side == foreign, memberchk(comma, Words0),
    append(Left0, [comma|Right], Words0), Left0 \== [], Right = [w(_, _)|_],
    \+ memberchk(comma, Right),
    last(Left0, w(_, LC)), memberchk(LC, [qclose, qboth]),
    %% (only where the quotation has a comma of its own: with the closing
    %% comma alone the division below has always read it, marks and all --
    %% `"Nella casa il gatto dorme", dice il cane', where this wrote the
    %% closing mark after the verb and the adjunct after it)
    memberchk(comma, Left0),
    tr_read_reporting(Side, Right, S2),
    tr_clause_words(Left0, Left), tr_read(Side, statement, Left, S1), !,
    S = join(comma, S1, S2).
%% ... AND ONE BETWEEN TWO QUOTATIONS: `"gli italiani possono ricoprire un
%% importantissimo ruolo ... adattabilità", spiega Vittori, "nel corso
%% cercherò di illustrare una missione spaziale ...' -- the first quotation
%% closes before the reporting clause and the second opens after it. Read
%% as one sentence, the reporting clause was written after both, and there
%% it stood INSIDE the second quotation, which closes only in the next
%% sentence. Each quotation is a clause of its own, and the reporting
%% clause stays between them with its commas, cmid/1.
%% (the marks on a word with its capital too: `"Ignoro de qué está hablando el COI", dijo Mayer, "pero ...' closes on
%% `COI"', and with the small word's marks alone the reporting clause was read into the sentence and written after
%% the second quotation)
tr_read0(Side, statement, Words0, S) :-
    memberchk(comma, Words0),
    append(Left0, [comma|Right0], Words0), Left0 \== [], last(Left0, LW), tr_closes_quote(LW),
    append(Mid0, [comma|After0], Right0), Mid0 = [w(_, _)|_], \+ memberchk(comma, Mid0),
    After0 = [w(_, AC)|_], tr_opens_quote(AC),
    tr_clause_words(Mid0, Mid), tr_read_reporting(Side, Mid, S2), tr_saying_clause(S2),
    tr_clause_words(Left0, Left), tr_read(Side, statement, Left, S1),
    tr_clause_words(After0, Right), tr_read(Side, statement, Right, S3), !,
    S = join(cmid(S2), S1, S3).
%% ... and one set between two COMMAS: `Alla luce della struttura di
%% finanziamento dell'operazione Veba, sottolinea il Lingotto in una nota,
%% non è previsto un aumento di capitale'. Read as three clauses joined, the
%% first had no verb and took `struttura' for the imperative it is spelled
%% like; it is a phrase fronted to the third, and the second reports the
%% whole. The sentence reads with the insertion taken out and its comma
%% kept -- so the front is written back in front -- and the reporting
%% clause is written after it, after a comma.
tr_read0(Side, statement, Words0, S) :-
    memberchk(comma, Words0),
    append(Left0, [comma|Right0], Words0), Left0 \== [],
    append(Mid0, [comma|After0], Right0), Mid0 = [w(_, _)|_], After0 \== [],
    %% (never a stretch that ends the quotation: `"Il cane dorme, vista la
    %% casa", ha detto' -- the second comma is the mark's, and `vista la
    %% casa' is no reporting clause set in the sentence but the last of what
    %% was said, which read as one wrote `ha dicho' in the middle of it)
    \+ ( last(Mid0, w(_, MC0)), memberchk(MC0, [qclose, qboth]), \+ memberchk(w(_, qopen), Mid0) ),
    %% (nor one after a quotation that closed before it, with nothing opened
    %% after it: `"Claro que nos ha complicado el futuro ...", añadió el
    %% técnico, que se mostró "tremendamente desolado"' is the technician who
    %% showed himself so, and `"Estamos muy contentos ...", añadió Metsu, sin
    %% comprender aún la dimensión de esa victoria' Metsu adding it without
    %% understanding. What follows is the reporting clause's own; read as a
    %% clause set in the sentence, it was written INSIDE the quotation)
    \+ ( last(Left0, LW), tr_closes_quote(LW), \+ ( After0 = [w(_, AC)|_], tr_opens_quote(AC) ) ),
    tr_clause_words(Mid0, Mid), tr_read_reporting(Side, Mid, S2), tr_saying_clause(S2),
    append(Left0, [comma|After0], Main), tr_read(Side, statement, Main, S10),
    %% ... and what it reports has a verb of its own: `En esta versión,
    %% además, cuenta con una June Anderson ... de la locura, la más esperada
    %% por los aficionados' had `cuenta' telling, and the fronts and the last
    %% phrase were left to be a sentence with no verb at all
    S10 \= gap(_, _), !,
    %% (the comma kept is the one that opened the reporting clause, and after
    %% a SUBJECT it is no comma of the subject's: `Inoltre la legge approvata,
    %% ha rilevato ancora il presidente della repubblica, crea ...' came out
    %% `la ley aprobada, crea ...', the comma between the law and what it
    %% does, as the subject's closing comma (scomma) -- the reporting clause
    %% goes after the sentence with its own)
    %% (and where the rest divides into clauses, the subject is the first
    %% clause's: `... crea "delle asimmetrie ..." e le posizioni delle parti
    %% ... assumono ...' is two clauses joined, and the comma stayed)
    ( \+ memberchk(comma, Left0), tr_drop_first_scomma(S10, S1) -> true ; S1 = S10 ),
    S = join(comma, S1, S2).
%% ... AND A COMMENT BETWEEN TWO COMMAS: `el técnico optará, como parece
%% probable, por mantener a Reina' -- `como' and a clause of its own, which
%% says how likely the rest is and belongs to no part of it. The sentence
%% reads with the comment and both its commas taken out, and the comment is
%% written after it, after a comma, as the reporting clause above is:
%% `... opterà per mantenere Reina, come sembra probabile.'
tr_read0(Side, statement, Words0, S) :-
    Side == foreign, memberchk(comma, Words0),
    append(Left0, [comma, w(C, CC)|Right0], Words0), Left0 \== [],
    tr_solve(mean(C, as)),
    append(Mid0, [comma|After0], Right0), Mid0 = [w(_, _)|_], After0 \== [],
    \+ memberchk(comma, Mid0),
    %% -- and it is its own clause's: with a colon after it, the colon divides
    %% first (below) and the comment stays before it. `... perché, come si
    %% dice a Napoli, l'abbiamo vinto a schiatto: cioè quando ...' wrote the
    %% saying after the clause that explains the spite
    \+ memberchk(colon, After0),
    %% -- and never before a connector, which ends the clause the comment is
    %% in: `Il cane dorme, come accadde in passato, ma il gatto mangia' wrote
    %% the saying after the cat's clause (the clause below reads it)
    \+ ( After0 = [w(K, _)|_], tr_connector(Side, K) ),
    %% -- nor before the word the lesson names its partner, which answers it
    %% in the clause that follows: `come la chiesa si era sbagliata ..., così
    %% si stava sbagliando sull'evoluzionismo' is as the church was wrong, so
    %% it was being wrong (tr_read0/4's correlative, below)
    \+ ( After0 = [w(K, _)|_], atom(K), tr_solve(partner_of(K, C)) ),
    tr_read_nested(Side, Mid0, none, S2),
    append(Left0, After0, Main), tr_read(Side, statement, Main, S1), !,
    S = join(comma, S1, join(cmt(w(C, CC)), none, S2)).
%% AS ONE THING, SO ANOTHER: `che, come la chiesa si era sbagliata non solo
%% sul geocentrismo ma anche sulla sfericità, così si stava sbagliando
%% sull'evoluzionismo' -- as the church had been wrong about geocentrism and
%% sphericity, so it was being wrong about evolutionism. The word meaning
%% `as' opens the piece and the lesson names the word that answers it after
%% the comma (`"così" is the partner of "come".'); read as a comment between
%% commas the first clause went after the sentence and `così' with the
%% second, `se estaba equivocando en el evolucionismo así, como la iglesia
%% ...'. The first clause is the second's front, fr(sub(cmt(As), Clause)),
%% written before it with its comma as a condition in front of a relative
%% clause is, and the partner stays the second clause's own adverb in front
tr_read0(Side, statement, Words0, S) :-
    Side == foreign, Words0 = [w(C, CC)|Ws], atom(C), memberchk(comma, Ws),
    tr_solve(mean(C, as)),
    append(W1, [comma, w(P, PC)|W2], Ws), W1 \== [], W2 \== [], atom(P),
    tr_solve(partner_of(P, C)), \+ memberchk(comma, W1),
    tr_read_nested(Side, W1, none, S1),
    tr_read(Side, statement, [w(P, PC)|W2], s(A, Su, G, Comps)), !,
    S = s(A, Su, G, [fr(sub(cmt(w(C, CC)), S1))|Comps]).
%% ... AND ONE AT THE END OF ITS CLAUSE: `perché codesti presìdi non
%% debordino dalle loro funzioni, come, peraltro, accadde in passato' -- as,
%% besides, happened in the past. Read with the plain readings `come' was
%% `how', a question the clause asked, and Spanish wrote `cómo pasó'. The
%% comment runs to the end of the piece -- a connector after a comma ends
%% it first, and the division reads that -- and a comma straight after its
%% word opens an insertion, which is kept, wc/1.
%% (its clause's subject is the gap, so its verb comes first, after an
%% insertion if one stands there: `come il loro predecessore, non importa
%% loro ...' is an insertion before a subject, and read as a comment at the
%% end of its clause every reading of what followed was tried and refused --
%% 15.9 million inferences in the Bosnian letter's ninth sentence)
tr_read0(Side, statement, Words0, S) :-
    Side == foreign, memberchk(comma, Words0),
    append(Left0, [comma, w(C, CC)|Right0], Words0), Left0 \== [],
    tr_solve(mean(C, as)),
    (   Right0 = [comma|R1] -> append(Ins, [comma|R2], R1), Ins \== [], \+ memberchk(comma, Ins)
    ;   R2 = Right0
    ),
    tr_gap_verb_next(Side, R2),
    \+ ( append(_, [comma, w(K, _)|_], Right0), tr_connector(Side, K) ),
    \+ memberchk(colon, Right0),
    (   Right0 = [comma|Mid0] -> Conn = wc(cmt(w(C, CC))) ; Mid0 = Right0, Conn = cmt(w(C, CC)) ),
    Mid0 = [w(_, _)|_],
    tr_read(Side, statement, Mid0, S2a), tr_cmt_subject_fix(S2a, S2),
    tr_clause_words(Left0, Left), tr_read(Side, statement, Left, S1), !,
    S = join(comma, S1, join(Conn, none, S2)).
%% ... AND ONE AT THE END THAT SAYS WHO SAID SO: `El comité examinó la
%% posibilidad ..., según añadieron las mismas fuentes' -- as the same
%% sources added. `según' is the preposition `according to', and before a
%% clause it opens the comment above with a REPORTING clause in it, its
%% speaker after its verb and no object of its own; read as a clause of its
%% own, the sources were the object of somebody adding them. It is written
%% as the comment is, after a comma, with the lesson's word for `as':
%% `..., come aggiunsero le stesse fonti'
tr_read0(Side, statement, Words0, S) :-
    Side == foreign, memberchk(comma, Words0),
    append(Left0, [comma, w(C, CC)|Right], Words0), Left0 \== [], Right = [w(_, _)|_],
    \+ memberchk(comma, Right),
    once(( tr_solve(mean(C, as)) ; tr_solve(mean(C, 'according to')) )),
    tr_read_reporting(Side, Right, S2), S2 = s(_, Sub, _, _), Sub \= null(_, _),
    tr_clause_words(Left0, Left), tr_read(Side, statement, Left, S1), !,
    S = join(comma, S1, join(cmt(w(C, CC)), none, S2)).
%% ... AND ONE AT THE END AFTER A PLAIN COMMA: `El Gobierno español ...
%% mantendrá como candidato español a Carlos Westendorp, ..., explicó ayer el
%% ministro de Asuntos Exteriores, Abel Matutes.' No quotation mark says that
%% what went before was said, so the last clause is the reporting one only
%% when its subject after the verb is a PERSON -- a name, or a phrase whose
%% noun the lesson calls one. Read as a clause of its own, the minister was
%% the object of somebody explaining him; and `abrió la puerta' after a
%% comma is still somebody opening the door.
tr_read0(Side, statement, Words0, S) :-
    Side == foreign, memberchk(comma, Words0),
    append(Left0, [comma|Right], Words0), Left0 \== [], Right = [w(_, _)|_],
    tr_speaker_tail(Left0, Right),
    %% (and the person is the clause's subject and nothing else's: `si disse
    %% subito dopo Hiroshima' is IT WAS SAID right after Hiroshima -- `si'
    %% names nobody, and the name is the object of `dopo', which is an adverb
    %% too. Read as the speaker, Spanish wrote `se dijo inmediatamente después
    %% Hiroshima'. tr_reporting/3 asks both as it reads, with `person')
    tr_reporting(person, Right, S2), S2 = s(_, _, _, Cs2),
    \+ memberchk(opron(_), Cs2),
    tr_clause_words(Left0, Left), tr_read(Side, statement, Left, S1), !,
    S = join(comma, S1, S2).
%% A QUOTATION THAT CLOSES INSIDE ITS PIECE, AND THE CLAUSE THAT REPORTS IT:
%% `L'acquisto da parte di Fiat del 100% di Chrysler “ci permetterà di
%% realizzare ... unico al mondo” aggiunge l'ad Sergio Marchionne.' The pair
%% of marks is the tokeniser's (the last quoted word carries qclose), so no
%% `endquote' divides the piece -- and the reporting clause ran on as the
%% quotation's own words. The piece divides after the quoted run when what
%% follows reads as a reporting clause; the marks travel on the words, so
%% the connector writes nothing.
tr_read0(Side, Kind, Words0, S) :-
    append(Left0, [w(Q, qclose)|Right0], Words0), Right0 = [w(_, _)|_],
    append(Left0, [w(Q, qclose)], LeftQ),
    tr_clause_words(Right0, Right), tr_read_reporting(Side, Right, S2),
    tr_clause_words(LeftQ, Left), tr_read(Side, Kind, Left, S1), !,
    S = join(reported, S1, S2).
%% A NAME ALONE BEFORE A COLON IS WHO SPEAKS: `Pecorella: "appare
%% inspiegabile quali possano essere le ragioni di incostituzionalità".' The
%% colon before an opening quotation mark ends the piece (tr_upto/4), and the
%% piece is one word -- which a name alone is not, since a lone capitalised
%% word is a verb with its pronouns joined on as often as a name
%% (`¡Lárgate!'); before a colon it is the speaker. `Mario Rossi:' read, two
%% words being a name where one is not, and `Pecorella:', `Roma:' and
%% `Maria:' were refused. The piece is the word and its colon, and it goes
%% back as it stood: `Pecorella: "..."'.
tr_read0(Side, _, [W, colon], join(colon, gap([], [obj(NP)]), none)) :-
    tr_global('$tr_piece', Piece), Piece == [W, colon],
    tr_dateline_word(Side, W, NP), !.
%% A COLON AT THE END ANNOUNCES WHAT THE NEXT SENTENCE SAYS: `Dello stesso
%% tenore il commento del sindaco di Torino Piero Fassino:', `Soddisfazione
%% dalla Fim Cisl:'. There is nothing after it to be a clause, so the
%% sentence is read without it and the colon is written back after it --
%% and such a sentence is a HEADING, which may have no verb at all (the
%% verbless reading below asks for this piece by name).
tr_read0(Side, Kind, Words0, S) :-
    append(Left0, [colon], Words0), \+ memberchk(colon, Left0), Left0 \== [],
    tr_clause_words(Left0, Left),
    %% (the sentence before the colon is the piece, as the readers that ask
    %% for the whole piece see it: `E per quella data, Funari spera ...:' has a
    %% connector at its head, which is read before any division, and with the
    %% colon in the piece it was divided at its first comma, `data' a command)
    tr_global('$tr_heading', H0), tr_global('$tr_piece', P0),
    nb_setval('$tr_heading', Left), nb_setval('$tr_piece', Left),
    (   tr_colon_left(Side, Kind, Left, S1) -> nb_setval('$tr_heading', H0), nb_setval('$tr_piece', P0)
    ;   nb_setval('$tr_heading', H0), nb_setval('$tr_piece', P0), fail
    ), !,
    S = join(colon, S1, none).
%% A HEADLINE WITH A COLON: `Il comitato di bioetica: no all'eutanasia.'
%% -- who speaks, and what they say, and neither side has a verb. Each side
%% is read as a heading is (tr_as_heading/2), so either may be verbless and
%% a side with a verb reads as it always did, the verbless reading being
%% the last one tried. It goes BEFORE the clause below because a failure
%% is kept per word list and not per heading: read there first, a verbless
%% side would be remembered as unreadable, and a failure with the heading
%% set is one without it too.
%% ... AND A QUESTION IS THE SIDE AFTER THE COLON: `Tasse più alte per i
%% più ricchi: avete pensato all'evasione fiscale?' is a heading and then
%% what is asked about it, and read the other way round the heading was the
%% question -- `¿Gravan más altos ...: habéis pensado ...?'
tr_read0(Side, Kind, Words0, S) :-
    append(Left0, [colon|Right0], Words0), \+ memberchk(colon, Left0), Left0 \== [], Right0 \== [],
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_heading_left(Side, Left, S1),
    tr_as_heading(Right, tr_read_after_colon(Side, Kind, S1, Right, S2)), !,
    ( Kind == question -> S = join(colon, S1, q(S2)) ; S = join(colon, S1, S2) ).
%% ... AND A QUESTION AFTER THE COLON IS THE SECOND CLAUSE'S: `E ora mi
%% domando: in che razza di mondo nasceranno i miei figli?' -- I wonder, and
%% then what I wonder. The mark ends the sentence and belongs to what the
%% colon announces; read as a question, the first clause asked nothing
tr_read0(Side, question, Words0, S) :-
    append(Left0, [colon|Right0], Words0), \+ memberchk(colon, Left0), Left0 \== [], Right0 \== [],
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_read(Side, statement, Left, S1), tr_read(Side, question, Right, S2), !,
    S = join(colon, S1, q(S2)).
%% ... AND TWO QUESTIONS WITH A COMMA BETWEEN THEM, each with its question word:
%% `e perché mai, e chi lo dice?' is why on earth, and who says so -- one mark
%% for the two. Each half reads as the question it is (the first often a
%% question word and nothing else, which no clause says), and the join writes
%% the comma between them
tr_read0(foreign, question, Words0, join(comma, S1, S2)) :-
    append(Left, [comma|Right], Words0), Left \== [], Right \== [], \+ memberchk(comma, Left),
    tr_opens_question(Left), tr_opens_question(Right),
    tr_question_half(Left, S1), tr_read(foreign, question, Right, S2), !.
%% ... AND SO IS A QUESTION AFTER AN ASIDE BETWEEN DASHES: `quanto si spende per
%% la sicurezza sociale - dove si concentrano le famiglie povere - su cento
%% italiani residenti quanti sono i poveri?' is a heading's three questions,
%% the middle one between its dashes (tr_asides/3 makes it one word, and the
%% first clause ends on it). The first is written as the statement it is, the
%% last as the question the mark says, and nothing is written between them
%% but the dashes the aside keeps: join(aside, ...), as a quotation's is.
tr_read0(foreign, question, Words0, join(aside, S1, q(S2))) :-
    append(Left0, [w(K, dashed)|Right0], Words0), Left0 \== [], Right0 \== [],
    \+ memberchk(comma, Right0),
    append(Left0, [w(K, dashed)], Left),
    tr_read(foreign, statement, Left, S1),
    tr_read(foreign, question, Right0, S2), S2 = s(Asked, _, _, _), Asked \== none, !.
%% A COLON DIVIDES AS A SEMICOLON DOES: `Le condizioni generali sono
%% ottime: ridono, scherzano, raccontano.' Two clauses, the second saying
%% what the first announced.
tr_read0(Side, Kind, Words0, S) :-
    memberchk(colon, Words0),
    append(Left0, [colon|Right0], Words0),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_read(Side, Kind, Left, S1), tr_read_after_colon(Side, statement, S1, Right, S2), !,
    S = join(colon, S1, S2).
%% A PURPOSE STANDING ALONE: `Para recordar.' -- a review's verdict, one to
%% remember. The first word is the one the lesson says begins the purpose
%% and the second an infinitive, and read as the verb the first is spelled
%% like -- `parar', to stop -- with a bare infinitive after it, it came out
%% `Detiene ricordare'. A whole piece that is the purpose, an infinitive and
%% its complements has no verb, and it is written as it stood: `Per
%% ricordare.', `To remember.'
tr_read0(foreign, statement, Words0, gap([], Comps)) :-
    Words0 = [w(P, _), w(V, _)|_], tr_purpose_word(P), tr_solve(infinitive_of(V, _)),
    tr_global('$tr_piece', Piece), Piece == Words0, \+ memberchk(comma, Words0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Words0, Comps), Comps = [purpose(_)|_], !.
%% ... AND SO IS `WITHOUT' AND AN INFINITIVE: `Senza contare che il rischio di
%% cadere nel baratro della povertà si agita come uno spettro per un numero
%% sempre maggiore di famiglie.' -- not to mention that the risk ... A whole
%% piece that is the infinitive's complements and the clause of `that' after
%% them has no verb of its own, and is written as it stood: `Sin contar que
%% el riesgo ...', `Without counting that the risk ...'
tr_read0(foreign, statement, Words0, gap([], Comps)) :-
    Words0 = [w(P, _), w(V, _)|_], tr_solve(mean(P, without)), tr_solve(infinitive_of(V, _)),
    tr_global('$tr_piece', Piece), Piece == Words0, \+ memberchk(comma, Words0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Words0, Comps), Comps = [pinf(_, _)|_], !.
%% A PHRASE AND THEN WHAT IT DOES: `la insistencia de los republicanos en
%% buscar otros cargos para fortalecer el proceso contra Lewinsky lo que
%% hace es "desacreditar" la investigación' -- the insistence, what it does
%% is discredit the inquiry. The phrase stands in front with NO comma, and
%% the clause after it has for its subject a word that replaces a noun and a
%% relative clause (`lo que hace', tr_np/3). Read as one clause, `para' was
%% the verb `stops' and `lo' was him -- a WRONG reading, which is why this
%% comes before the plain ones below. The phrase travels in front, frn/1,
%% and every writer puts it back where it stood, its complements after it.
%% It is asked of a clause after `que' too (tr_read_nested/4), where the
%% sentence's own one stood.
tr_read0(foreign, statement, Words0, S) :- tr_topic_cleft(Words0, S), !.
%% A QUESTION WITH NO QUESTION WORD IS A STATEMENT WITH ITS MARK: `-
%% egoista e vigliacca, continuerà a cercare mediazioni impossibili ...?'
%% asks whether it will, in the statement's own order -- so it is read as the
%% statement it is, its commas and its front with it, and only the mark says
%% that it asks. Read with every comma taken out, the adjectives in front had
%% no reading at all and the comma before `senza' was lost.
tr_read0(foreign, question, Words0, S) :-
    memberchk(comma, Words0), Words0 = [W0|_], W0 \== comma,
    tr_uncomma(Words0, Plain), fo_question_word(Plain, _, none),
    tr_read0(foreign, statement, Words0, S), !.
%% A SUBORDINATING WORD AFTER A COMMA DIVIDES THE PIECE BEFORE THE WHOLE IS
%% TRIED AS ONE STATEMENT. `"una buona notizia, visto che erano evidenti i
%% profili ..., che se fosse stata promulgata, avrebbe ulteriormente
%% dissestato l'amministrazione, reso più lunghi ... e acuito ..."' is two
%% clauses, and no statement holds a clause of `since' or `while' among its
%% complements -- so the reading of the whole, with its commas and again
%% without them, could only fail, and did: put back alone, it costs Ciampi's
%% twenty-first sentence 81.4 million inferences more and its ninth 65.2, the
%% texts the same. The last such word divides first, as tr_clause_split/5
%% has it, and both sides must read as clauses: where they do not, the
%% reading goes on as it always did.
%% ... AND SO DOES A COORDINATOR BETWEEN TWO COMMAS, whose comma opens the
%% next clause's insertion (tr_clause_mids/4): `En declaraciones a Europa
%% Press, Millàs consideró que ..., pero, aun así, dijo haber propuesto ...'
%% was read as a front at every length, each rest as one statement, before
%% a division read it: 78.0 million inferences, and 3.1 with this -- the
%% text the same. A coordinator with no comma after it joins phrases as
%% often as clauses, and stays where the readings below find it.
tr_read0(foreign, statement, Words0, S) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    memberchk(comma, Words0),
    findall(L1-X-R0, ( append(L1, [X|R0], Words0), X = w(_, _) ), Splits0), reverse(Splits0, Splits),
    member(Left1-w(C, CC)-Right0, Splits),
    (   append(Left0, [comma], Left1), Left0 \== []
    ->  tr_connector(foreign, C), ( \+ tr_coord(foreign, w(C, CC)) -> true ; Right0 = [comma|_] ),
        Conn = both(comma, w(C, CC))
    %% ... AND A SUBORDINATING WORD AFTER A COMMA AND A COORDINATOR: `...,
    %% che forse la terra era davvero sferica, ma siccome non è conoscendo
    %% ... che ci si salva l'anima, la questione gli appariva ...' -- Eco's
    %% Agostino -- was the whole tried as one statement first, 58.4 million
    %% inferences for the sentence
    ;   append(Left0, [comma, K], Left1), Left0 \== [], K = w(_, _), tr_coord(foreign, K),
        tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
        Conn = both(ck(K), w(C, CC))
    ),
    \+ ( append(_, [w(_, QC), comma|_], Right0), memberchk(QC, [qclose, qcloseu]) ),
    %% (never where the words before the comma have no verb and a verb group
    %% follows the clause's closing comma: `Gli autori, siccome il gatto
    %% dorme, mangiano il pane' is the authors eating, the clause set off
    %% between them and their verb (tr_insertion_off/4); divided here, the
    %% authors were a verbless piece and the verb had nobody named)
    \+ ( append(Cl, [comma|After2], Right0), \+ memberchk(comma, Cl), tr_group_at(foreign, After2, _, _),
         \+ ( member(X, Left0), X = w(XW, _), atom(XW), tr_verb_form_word(XW) ) ),
    tr_clause_words(Left0, _), tr_clause_words(Right0, Right),
    tr_division(foreign, statement, Words0, Left0, Conn, Right, S), !.
%% ... AND A PIECE THAT OPENS ON ONE DIVIDES FIRST AT A COMMA, its head
%% clause running to it: `Siccome molta gente pensa ancora che Colombo
%% sostenesse che la terra è tonda mentre tutti i sapienti del tempo la
%% ritenevano ancora piatta, giustamente Angela ... ha spiegato che ...' is
%% since [people think it round while the wise thought it flat], Angela
%% explained. The whole read as one statement could only fail, and every set
%% of its adverbs lifted out of it failed again -- past its budget of 300
%% million inferences. And divided at the last subordinating word first
%% (tr_clause_split/5), `mentre' took the main clause for its own second
%% half: `Siccome il cane dorme mentre il gatto mangia, Angela ha spiegato
%% che ...' was since the dog sleeps, while [the cat eats, Angela explained]
%% -- the same words in every language, and the wrong IR. The first comma
%% whose two sides both read; never a head clause with a quotation mark in it
tr_read0(foreign, statement, Words0, S) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    Words0 = [w(C, CC)|Rest0], atom(C), memberchk(CC, [lower, upper]), Rest0 = [R0|_], R0 \== comma,
    memberchk(comma, Rest0),
    tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
    append(Sub, [comma|Right0], Rest0), Sub \== [], Right0 = [R1|_], R1 \== comma,
    \+ ( member(w(_, QC), Sub), \+ memberchk(QC, [lower, upper]) ),
    \+ tr_insertion_closer(foreign, Words0, Right0),
    tr_read_under(C, Sub, S1),
    %% (never a phrase and a gerund for the whole clause of the word: `Se la
    %% persona, andando giù, non ha bevuto, ...' is the person, going down, with
    %% her verb after the second comma, and the phrase and its gerund were read
    %% for a clause of `if' of their own)
    \+ S1 = gap([obj(_)|_], [ger(_, _)|_]),
    tr_clause_words(Right0, Right),
    tr_read_joined(foreign, comma, join(w(C, CC), none, S1), Right, S2), !,
    S = join(comma, join(w(C, CC), none, S1), S2).
%% A PLURAL NOUN AND THE PHRASE OF `OF' AFTER IT, AT THE HEAD OF A PIECE THAT
%% HAS NO OTHER VERB, ARE A HEADING: `Sviluppi delle trattative in atto tra
%% polo di destra e coalizione di Centro Sinistra' -- `sviluppi' is what
%% `sviluppare' says to one person, and read as that command, or as a verb
%% with nobody for a subject (`Gli sviluppi delle trattative' as `Le
%% desarrolla de las negociaciones'), it came out `Desarrollas de las
%% negociaciones'. The verbless reading is asked first for such a piece (it
%% asks for the whole piece itself, and for no verb in it).
tr_read0(foreign, statement, Words0, S) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    tr_noun_heading_start(Words0),
    tr_verbless(foreign, Words0, S), !.
%% ... AND A NUMBER, A NAME AND A NOUN ARE THE EDITION OF WHAT THE NAME AND THE NOUN SAY: `38 Spoleto festival.' heads
%% the report on the festival's 38th edition (`la 38-ma edizione del festival', the line after it). The paper writes the
%% name before the noun in English's way, and a count stands right before its noun, never before a name that stands
%% before it: the number is the ordinal, its sign the noun's gender (`38º', `38ª', as `38-mo' and `38-ma' read), and
%% the name is the noun's phrase of `of'. Each writer says it as its own: `38º festival de Spoleto', `38th festival of
%% Spoleto'. Read as a count of festivals the heading had no reading
tr_read0(foreign, statement, [w(D, _), w(N, upper), w(F, FC)], gap([], [obj(NP), pp(w(Of, lower), name(N))])) :-
    FC \== upper, atom(D), atom(N), atom(F),
    atom_codes(D, Ds), Ds = [_|_], forall(member(C, Ds), rt_digit(C)),
    ( tr_name_word(foreign, w(N, upper)) -> true ; tr_solve(city(N)) ),
    tr_is(foreign, w(F, lower), noun), tr_lexeme(foreign, F, L, singular),
    ( tr_gender(L, feminine) -> Sign = 'ª' ; Sign = 'º' ), atom_concat(D, Sign, Ord),
    tr_np(foreign, [w(Ord, lower), w(F, lower)], NP), NP = np(none, w(Ord, _), [], w(_, _), singular),
    once(( tr_solve(mean(Of, of)), tr_is(foreign, w(Of, lower), preposition) )), !.
%% ... AND THE AGENT BEFORE ITS PARTICIPLE, WITH NO PHRASE BEFORE THEM: `C'era la ragazza. da me vista troppo tardi'
%% -- seen by me too late, the girl of the line before. Read as a statement, `vista' was what `vistare' says, approves,
%% and `da me' a place it came from, `Aprueba demasiado tarde desde mí'. The verbless reading is asked first for such
%% a piece (tr_verbless0/3's agent first)
tr_read0(foreign, statement, Words0, S) :-
    Words0 = [B, A1, w(P, _)|_], nb_getval('$tr_agent_first', yes),
    B = w(_, _), tr_means_by(foreign, B), tr_is(foreign, B, preposition), tr_lone_agent(A1, _),
    atom(P), tr_participle_here(foreign, P, _),
    tr_global('$tr_piece', P0), P0 == Words0,
    tr_verbless(foreign, Words0, S), !.
%% A QUOTATION THAT CLOSES AT THE FIRST COMMA AND ONLY A REPORTING CLAUSE
%% AFTER IT divides before the statement is read with its commas: `"credo che
%% sia vero", aveva detto.' read whole, `credo' was the creed that is true
%% (a noun with a relative clause), the subject of `aveva detto', and
%% Spanish wrote `"Credo que es cierto", había dicho' -- the quotation
%% standing for a subject, and its first word kept. The quotation reads as
%% the statement it is (a verb of its own: `"il dialogo può continuare"' had
%% no noun phrase to be read as and always divided) and the clause after the
%% comma reports it.
tr_read0(foreign, statement, Words0, S) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    append(Left0, [comma|Right0], Words0), Left0 = [_|_], \+ memberchk(comma, Left0),
    last(Left0, w(_, qclose)), Right0 = [w(_, _)|_], \+ memberchk(comma, Right0),
    tr_saying_first(Right0),
    tr_clause_words(Right0, Right),
    tr_division(foreign, statement, Words0, Left0, comma, Right, S),
    S = join(_, s(_, _, _, _), S2), S2 = s(_, _, _, _), tr_saying_clause(S2), !.
%% A STATEMENT IS READ FIRST WITH ITS COMMAS, and a comma after the verb
%% group is a complement of its own, sep, which every writer puts back:
%% `Il generale definisce la casa, escludendo che il paese domina' keeps
%% the comma before its gerund. The subject side is read with the commas
%% taken out, as before; and when this reading fails the one below, with
%% every comma taken out, is the one the reader always had.
%% ... AND A PIECE THAT OPENS ON AN ADVERB AND A COMMA IS A PUNCTUATED
%% FRONT, never a verb of the whole: `así, trabajo hecho' is thus, job done,
%% and `así' is also what `asir' says of the first person in the past -- read
%% as that verb, with the comma kept or taken out, Italian wrote `Presi,
%% lavoro fatto', I took. The front reader below reads it (tr_adverb_head/2).
tr_read0(Side, statement, Words0, S) :-
    memberchk(comma, Words0), Words0 = [W0|_], W0 \== comma,
    \+ tr_adverb_head(Side, Words0),
    tr_read_statement(Side, Words0, none, S), !.
tr_read0(Side, Kind, Words0, S) :-
    \+ tr_names_parted(Side, Words0),                       % two names a comma parts stay two
    \+ tr_name_opens_clause(Side, Words0),                  % and a comma before a name and its verb stays
    \+ tr_comma_and_parted(Side, Words0),                   % and a phrase a comma parts from the `y' phrase after it
    \+ ( Kind == statement, tr_adverb_head(Side, Words0) ),
    tr_uncomma(Words0, Plain),
    tr_normalise(Side, Kind, Plain, Words, Asked),
    tr_read_statement(Side, Words, Asked, S), !.
%% AN ADVERB STANDS WHEREVER ITS LANGUAGE LIKES, AND A STATEMENT READER
%% READS ONE ONLY AFTER THE VERB GROUP. `si sono anche appellati', `non
%% sono state ancora accertate', `e considerata gia conclusa' all put one
%% INSIDE the group, between the auxiliary and the participle, where
%% nothing was looking for it; `Velocemente il generale domina' and `Gia si
%% parla' put one at the head, before the subject. So a piece that did not
%% read as a statement is tried again with the adverb words LIFTED OUT of
%% it, and they come back as the adv/1 complements they would have been
%% after the verb.
%%
%% IT IS TRIED ONLY AFTER THE PLAIN READING FAILED, which is what makes it
%% a strict addition -- every sentence that read before reads by the same
%% clauses -- and fewest first, because tr_adverbs_off/4 keeps each word
%% before it lifts it: an adverb the complement reader can already take
%% stays where it is.
%%
%% AND THE POSITION IS NOT WRITTEN BACK. A lifted adverb becomes an
%% ordinary complement and every writer puts it after the verb, so `Gia si
%% parla' comes back as `Si parla gia' -- the same claim in the statement's
%% own order, which is what 1.6.8 already does with a fronted adjunct.
%%
%% THE COST IS A WORD THAT IS AN ADVERB AND SOMETHING ELSE BESIDES. Nothing
%% here can rescue a WRONG reading: `ancora' is an adverb, a noun (anchor)
%% and a verb in the vocabulary, so `mangia ancora il pane' reads as an
%% object and never reaches this clause. A refusal is what this repairs.
%% ... AND NOT OVER A PIECE A COMMA AND A CONNECTOR DIVIDE: `Io la risposta
%% non ce l'ho, ma quei morti ... e, soprattutto, sono un problema anche mio'
%% is two clauses, and every set of its adverbs lifted out of the whole was a
%% reading of the whole that failed -- 42 million of its 59. The division
%% further down reads each half, and each half lifts its own.
tr_read0(Side, Kind, Words0, S) :-
    \+ tr_names_parted(Side, Words0),
    \+ tr_name_opens_clause(Side, Words0),
    \+ ( Kind == statement, Words0 = [_, comma|_] ),       % `Cucharada a cucharada, el chaval ...' is a punctuated front
    \+ ( append(_, [comma, w(CW, _)|_], Words0), tr_connector(Side, CW) ),
    \+ ( append(_, [w(CW, CC), comma|_], Words0), tr_coord(Side, w(CW, CC)) ),   % `... e, soprattutto, sono'
    (   %% ... WITH THE COMMA BEFORE A RELATIVE WORD KEPT, which says the clause
        %% is the phrase's aside: `También se incrementaron las ventas de
        %% minidisc, que superaron ...' read with every comma out made the
        %% clause restrictive, and the comma was lost
        Kind == statement, tr_comma_relative(Side, Words0),
        tr_adverbs_off(Side, Words0, Rest, Advs0), Advs0 \== [], Rest = [R0|_], R0 \== comma,
        tr_read_statement(Side, Rest, none, S0), S0 = s(A, Su, G, Comps0)
    ->  Words = Words0
    ;   %% ... AND AN ADVERB AT THE HEAD LEAVES THE REST ITS COMMAS, which set
        %% off an insertion between the subject and its verb: `Giustamente
        %% Angela, nel dialogo con un consulente scientifico, ha spiegato che
        %% ...' -- read with every comma out, the dialogue was the subject's
        %% own phrase (with/2) and both commas were lost
        %% (never before a preposition, where no subject can follow the
        %% adverb: the opera review's `Sólo en la descripción visual de lord
        %% Arturo Bucklaw, interpretado por ...' was read this way and failed
        %% late, 160 000 inferences of its 1.7 million)
        Kind == statement, Words0 = [W1|Rest], W1 = w(N1, _), atom(N1), Rest = [R1|_], R1 \== comma,
        memberchk(comma, Rest), \+ tr_is(Side, R1, preposition), tr_plain_adverb(Side, W1), \+ tr_negation_word(N1),
        %% (and a verb group at the head of the rest or after one of its
        %% commas -- `Ora è indispensabile ..., come annunciato, ...', or
        %% Angela's, where the insertion ends: Ferlaino's `via lo 0/2, via il
        %% designatore (Gussoni, ndr) che era ...' has neither, and was read
        %% this way and failed late, 2.9 million inferences of the sentence's
        %% 14) -- and no connector before the rest's first comma, whose commas
        %% are then the clause's the connector opens, which the division at
        %% it reads: Livata's `Di certo si sa solo che la famiglia era ... e
        %% mentre il compagno della donna, Emanuele Tornaboni, era in pista
        %% ...' was read this way and failed after 3.8 million inferences
        ( Side == foreign -> once(( ( AfterC = Rest ; append(_, [comma|AfterC], Rest) ), tr_group_past_clitics(AfterC) )) ; true ),
        \+ ( append(BeforeC, [comma|_], Rest), \+ memberchk(comma, BeforeC),
             member(w(CW, _), BeforeC), atom(CW), tr_connector(Side, CW) ),
        \+ tr_governs_adverb(Side, W1, Rest), Advs0 = [adv(W1)],
        tr_read_after_head_adverb(Side, Words0, Advs0, Rest, none, S0), S0 = s(A, Su, G, Comps0)
    ->  Words = Words0
    ;   tr_uncomma(Words0, Plain),
        tr_normalise(Side, Kind, Plain, Words, Asked),
        tr_adverbs_off(Side, Words, Rest, Advs0), Advs0 \== [],
        %% (never the word that opens the piece and subordinates: `Mentre le
        %% squadre hanno comprato Stoichkov, Baggio e Zola' is while the
        %% teams bought them, not `the teams bought them while' -- `mentre'
        %% is an adverb too, and lifted it was written last)
        \+ tr_head_connector_lifted(Side, Words, Advs0),
        %% (nor the preposition that opens a phrase and its comma, which the commas
        %% taken out hid: `Secondo la corte, è necessario ...', tr_governs_adverb/3)
        \+ ( Words0 = [HW|HR], Advs0 = [adv(HW0)|_], HW0 = w(HN, _), HW = w(HN, _), tr_governs_adverb(Side, HW, HR) ),
        tr_read_after_head_adverb(Side, Words, Advs0, Rest, Asked, S0), S0 = s(A, Su, G, Comps0),
        \+ ( Side == foreign, tr_ago_time_subject(Su, Advs0) )
    ), !,
    tr_denials_in_front(Side, Words, Advs0, Advs1),
    tr_connective_in_front(Side, Words, Advs1, Advs),
    tr_advs_join(Side, Words, Comps0, Advs, Comps),
    %% ... AND A QUOTATION THAT OPENED ON AN ADVERB THE LIFT TOOK OUT IS THE
    %% CLAUSE'S, as one that opens on an adjunct the writer moves is
    %% (tr_clause_marks/3): `ma "già ora si può dire che le preoccupazioni ...
    %% erano fondate"' has its mark on `già', and the adverbs are written
    %% after the verb, so `pero se puede decir "ya ahora que ...' opened the
    %% quotation on them and left `se puede decir' outside it
    S1 = s(A, Su, G, Comps),
    (   Side == foreign, tr_clause_marks(Words, S1, S2) -> S = S2
    %% ... AND ONE THAT CLOSES ON THE CLAUSE'S LAST WORD, where the lift left
    %% an adverb behind it: `"En el PNV tenemos derecho a pensar de él lo que
    %% nos parece si realmente es un nostálgico del franquismo", dijo
    %% Arzalluz' closes on `franquismo', and the adverb the lift took out is
    %% written at the end of the clause -- `... del franchismo" realmente'
    %% closed the quotation before it. The clause carries qe, which every
    %% writer puts on the last word it writes (tr_lifted_close/3)
    ;   Side == foreign, tr_lifted_close(Words, Advs, S1, S2) -> S = S2
    ;   S = S1 ).
%% A FRONTED ADJUNCT BEFORE THE SUBJECT. `Negli ambienti giudiziari si
%% tende ad accreditare la tesi' opens with a prepositional phrase that is
%% neither the subject nor part of one -- and the subject reader took `in
%% gli ambienti giudiziari si' for a phrase, failed inside it, and refused
%% the sentence. The inversion clause of 1.6.8 reads the same fronting with
%% the subject AFTER the verb, which an intransitive verb licenses; this
%% one reads it with the subject where it always was, and needs no property
%% of the verb because nothing is being moved.
%%
%% Only material that reads as ADJUNCTS may be taken -- an adverb or a
%% prepositional phrase, never an object -- which is what stops the front
%% swallowing the subject, and the LONGEST front is tried first, which is
%% what stops it stopping short: `Negli ambienti si tende' cut at two words
%% read `gli' as an object pronoun standing alone (nothing followed it to
%% say it was the article it is) and came out `Environments tend in hims'.
%% It is tried only after the plain reading failed, which is what makes it
%% a strict addition.
%%
%% THE FRONTING IS NOT WRITTEN BACK, exactly as 1.6.8 says of the other:
%% the adjuncts become ordinary complements and every writer puts them
%% after the verb.
%%
%% A STATEMENT'S FRONT IS READ WITH ITS COMMAS, and a phrase ends at one:
%% `en los de clase media, chicos difíciles y en las partes altas ...' read
%% with the commas taken out made `clase media chicos difíciles' one phrase.
%% And A FRONT THE SOURCE SET OFF WITH A COMMA IS WRITTEN BACK IN FRONT:
%% `Después, en los barrios marginales se les llamará ...' is a choice the
%% writer made, and each complement of it travels as fr(C) so every writer
%% puts it before the clause and the comma after it. A front with no comma
%% is written after the verb, as 1.6.8 does.
tr_read0(Side, statement, Words0, S) :-
    Words0 = [W0|_], W0 \== comma,
    %% a CONNECTOR at the head is the sentence's, never a front's first
    %% adjunct: `E a Cortina una frana ostruisce ...' took `E' for cnj(and)
    %% and wrote it after the verb, `... de Alemagna y a Cortina'
    \+ ( W0 = w(C0, _), tr_connector(Side, C0) ),
    %% ... and a front that opens on a determiner and a common noun is a
    %% time's (`el martes, ...') and nothing else: `Esta propuesta, que
    %% debería ser refrendada ..., se produce después de que ...' was asked
    %% as a front at every length, each prefix read as complements with its
    %% relative clause, and the sentence ran past its budget before the
    %% division at `después de que' was tried
    \+ ( W0 = w(_, _), tr_determiner(Side, W0, _, _), Words0 = [_, N1|_], N1 = w(N1W, lower), atom(N1W),
         tr_is(Side, N1, noun), \+ tr_is(Side, N1, adjective),
         \+ ( tr_lexeme(Side, N1W, N1L, _), tr_time_lexeme(Side, N1L) ) ),
    length(Words0, Len), Max is Len - 1, Max >= 1,
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    %% A FRONT ENDING AT A COMMA WITH A PHRASE AFTER IT IS TRIED FIRST, for a
    %% subject named after the comma: `En un segundo encuentro ... que tuvo
    %% lugar ayer, el secretario de Estado de Seguridad, Pedro Morenés, y
    %% algunos responsables del PSOE trataron cuestiones'. Longest first, the
    %% relative clause ran over its comma and took the secretary and the
    %% managers for what took place, and the verb was left with nobody for
    %% its subject. Only a rest that names its subject takes this front.
    (   tr_front_comma_ends(Side, Words0, K), Pref = yes
    ;   between(1, Max, Back), K is Max + 1 - Back, Pref = no
    ),
    length(Front0, K), append(Front0, Rest0, Words0),
    \+ last(Front0, comma), Rest0 \== [], Rest0 \= [comma],
    %% a front that opens on `al' and an infinitive ends at a comma: the
    %% clause takes the words to its first comma (tr_upon_rest/5), and asked
    %% at every length of front the rest of the sentence was read as its
    %% complements once a length -- 32 million inferences for `Al abrir la
    %% segunda audiencia ..., su presidente, Henry Hyde, sostuvo que ...'
    \+ ( Rest0 \= [comma|_], tr_upon_head(Side, Front0) ),
    %% the word for `not' is the verb's, never the end of a front: longest
    %% first, `Alla luce della struttura ..., non è previsto' took `non' as
    %% the front's last adverb and the verb lost its denial
    \+ ( last(Front0, w(NW, _)), tr_solve(mean(NW, not)) ),
    %% ... and a front never ends on the auxiliary's infinitive: the
    %% participle after it is the perfect infinitive's, `Cioè dopo aver
    %% mandato in onda il programma' took `dopo aver' for the front and
    %% `mandato in onda il programma' for a headline's passive
    \+ tr_ends_on_auxiliary(Side, Front0),
    %% ... and so is a denying adverb: `..., ni siquiera ha comunicado'
    \+ ( last(Front0, LW), LW = w(_, _), tr_denying_adverb(Side, LW) ),
    %% ... and an adverb before a count is the count's: `Al cierre de los
    %% colegios, MÁS DE un 60% de los electores habían votado' -- longest
    %% first, the front took `más de' and wrote `..., oltre, un 60%'
    \+ ( last(Front0, LW2), LW2 = w(_, _), tr_is(Side, LW2, adverb), tr_count_follows(Side, Rest0) ),
    %% ... and an article with its adjective is followed by its noun: `En la
    %% siguiente toma, cuando ...' is in the next shot, and the front `en la
    %% siguiente', the following one, left `toma' to be the command take
    \+ ( append(_, [D4, A4], Front0), D4 = w(DW4, _), A4 = w(_, _), atom(DW4),
         tr_determiner(Side, D4, _, article), tr_is(Side, A4, adjective),
         Rest0 = [N4|_], N4 = w(NW4, _), atom(NW4), tr_is(Side, N4, noun),
         tr_lexeme(Side, DW4, _, Num4), tr_lexeme(Side, NW4, _, Num4) ),
    %% ... and an adverb after the front's comma and before a determiner is
    %% the rest's, standing before its subject: `che, ieri, proprio la sua
    %% assenza' took `ieri, proprio' for one front, and the writer's comma
    %% after a front came out `que, ayer, precisamente, su ausencia'
    %% -- and before the denial or the verb: `"En primer lugar, todavía no sé
    %% si ...' took `En primer lugar, todavía' for the front, and the comma a
    %% writer puts after a front came out `In primo luogo, ancora, non so'
    \+ ( append(_, [comma, LW3], Front0), LW3 = w(_, _), tr_plain_adverb(Side, LW3),
         Rest0 = [D3|_], D3 = w(D3W, _),
         (   tr_determiner(Side, D3, _, _) -> true
         ;   atom(D3W), tr_solve(mean(D3W, not)) -> true
         ;   atom(D3W), tr_verb_form_word(D3W)
         ) ),
    tr_complements(Side, Front0, Front), Front \== [],
    (   tr_adjuncts(Front) -> Front1 = Front
    %% ... AND A TIME WITH ITS ARTICLE, which the complements take for an
    %% object: `se il prossimo febbraio il senato accademico darà parere
    %% positivo' is next February, and the sentence was refused whole
    %% -- wherever it stands in the front: `A questo scopo il prossimo 24
    %% gennaio nel tempio di Adriano, a Roma, si terrà un'iniziativa' has the
    %% date after a phrase of its own, and with the time first only, the
    %% front ended at `il', and the date was the subject of `si terrà'
    ;   select(obj(TNP), Front, at_time(TNP), Front2), tr_time_or_month(TNP), tr_adjuncts(Front2) -> Front1 = Front2
    ;   Rest0 = [comma|_], Front = [obj(NP)], tr_topic(NP), tr_at_piece_head(Words0), Front1 = [topic(NP)]
    %% ... AND A BARE PHRASE THAT SAYS WHAT THE SUBJECT IS: `Retrato preciso
    %% de la aniquilación psicológica, Anderson ofreció una de sus mejores
    %% noches' -- a portrait, and Anderson is it. It has no determiner and no
    %% verb, and divided at its comma it was read as `retrato', I portray. It
    %% stands at the head of its sentence with its `of' phrases, and only
    %% before a subject that is named (Named below)
    ;   Rest0 = [comma|_], Front = [obj(NP)|PPs], NP = np(none, none, _, w(_, _), singular),
        forall(member(X, PPs), X = pp(_, _)), tr_at_piece_head(Words0),
        Front1 = [topic(NP)|PPs], Named = yes
    %% ... AND ADJECTIVES THAT SAY WHAT THE SUBJECT IS: `Egoista e vigliacca,
    %% continuerà a cercare mediazioni impossibili' -- selfish and cowardly,
    %% it will go on looking. At the head of the sentence and before its
    %% comma, in the number of the subject after it (Agree below), and each
    %% writer puts them back in front agreeing with that subject.
    ;   Rest0 = [comma|_], Front = [adj(FA)], tr_at_piece_head(Words0),
        Front1 = Front, Agree = FA
    %% ... WITH ITS ADJUNCTS: `Stanco del caldo, Paolo parla' -- tired of the
    %% heat, Paolo speaks
    ;   Rest0 = [comma|_], Front = [adj(FA)|ACs], ACs \== [], forall(member(X, ACs), tr_adjunct(X)),
        tr_at_piece_head(Words0),
        Front1 = Front, Agree = FA
    %% ... AND A PURPOSE: `Para demostrarlo, esgrimió una papeleta' -- to show
    %% it, he brandished a ballot. At the head of the sentence and before its
    %% comma, the word the lesson says begins the purpose and an infinitive
    %% with what it takes; divided at the comma, the front was read as a clause
    %% of `parar', to stop, and Italian wrote `Cessa mostrarlo'. It is written
    %% back in front with its comma, as every punctuated front is.
    ;   Rest0 = [comma|_], Front = [P1|PCs], ( P1 = purpose(_) ; P1 = purp(_) ),
        (   forall(member(X, PCs), ( X = obj(_) ; tr_adjunct(X) )) -> true
        %% ... AND ITS OBJECT WITH A PARTICIPLE BETWEEN COMMAS: `Per difendere il fratello, Said, accusato di aver
        %% investito e ucciso Sara Folino a Torvajanica, riesce a contraddire sé stesso' -- to defend his brother,
        %% accused of having run her over, he manages. The participle's own complements travel beside it; refused
        %% here, the shortest front was taken, `Per difendere' alone, and the brother was the one who manages
        ;   PCs = [obj(O)|Aside], ( O = rel(_, PL, _), atom(PL) -> true ; Aside = [sep, pred(_)|_] ),
            tr_front_aside_comps(Aside)
        ),
        tr_at_piece_head(Words0), Front1 = Front
    %% ... AND ONE WITH NO COMMA: `Per farlo bisogna agire', `ma per farlo
    %% bisogna prima conoscerlo' -- a purpose and nothing else, at the head of
    %% a clause and straight before it, which it goes after as any front with
    %% no comma does. It is asked here and not as an adjunct (tr_adjunct/1):
    %% as one, every place that reads "adjuncts only" read a purpose too, and
    %% `veniva in Italia per fare un pò di soldi e mandarli alla sua famiglia'
    %% paid 19 % more
    %% (and adverbs in front of it: `quando invece per contestare arrivano in
    %% tanti' -- when, instead, they come in numbers to protest)
    ;   Rest0 \= [comma|_], tr_front_skip_adverbs(Front, [P2|Objs]), ( P2 = purpose(_) ; P2 = purp(_) ),
        %% ... WITH WHAT IT TAKES, where the rest names its subject or is the
        %% impersonal: `Para celebrar este 50 aniversario no se ha escatimado
        %% en gastos' and `Para celebrar el aniversario el club organizó una
        %% fiesta'. The anniversary was the subject of the rest, `The
        %% anniversary did not skimp in costs to celebrate', and the club's
        %% sentence was refused. The rest with nobody named stays as it was
        %% (`Para sobrevivir el perro come': the dog eats, to survive)
        forall(member(X, Objs), X = obj(_)),
        %% (a front whose last word is an apposition was set off by the comma that closed it: `Per difendere il
        %% fratello, Said, accusato ..., riesce a contraddire sé stesso' -- to defend his brother Said, he manages;
        %% the commas went into the apposition before the reading (w(N, appos)), and with nobody named after it
        %% the shortest front was taken, `Per difendere' alone, and the brother was the one who manages)
        ( Objs == [] -> true ; last(Front0, w(_, appos)) -> true ; Objd = yes ),
        Front1 = Front
    %% ... AND A PARTICIPLE WITH ITS AGENT, SAID OF THE SUBJECT: `En un
    %% santiamén, liderados por un joven cuyo nombre se hará familiar muy
    %% pronto (El-Hadji Diouf), ridiculizaron al campeón' -- led by a young
    %% man, they ridiculed the champion. After the front's adjuncts, if it has
    %% any, the participle and its phrase of `por', which is its agent;
    %% divided at the commas, the participle was a clause of its own with
    %% nobody named, and the sentence was refused. It travels as fpart/4 with
    %% the gender and the number of the source's form, agrees in number with
    %% the subject after the comma (PartN below), and every writer puts it
    %% back in front
    ;   Rest0 = [comma|_], Side == foreign, append(FA, [pred(PL)|PCs], Front),
        forall(member(X, FA), ( X == sep ; tr_adjunct(X) )),
        PCs = [pp(PB, ANP)|PMore], tr_means_by(Side, PB), forall(member(X, PMore), tr_adjunct(X)),
        tr_at_piece_head(Words0),
        once(( member(w(PW, _), Front0), atom(PW), tr_participle_here(Side, PW, PL) )),
        ( tr_holds(feminine(PW)) -> PG = feminine ; PG = masculine ), tr_participle_number(PW, PartN),
        append(FA, [fpart(PL, PG, PartN, [by(ANP)|PMore])], Front1)
    %% ... AND A PARTICIPLE WITH ADJUNCTS ONLY, SAID OF THE SUBJECT: `Sottratto
    %% per qualche momento al mare e al sole della Sardegna, Cecchi Paone
    %% conferma ...' -- taken from the sea and the sun for a moment, he
    %% confirms. The agent's shape above without the agent: the adjuncts
    %% after the participle go with it, and it is written back in front
    ;   Rest0 = [comma|_], Side == foreign, append(FA, [pred(PL)|PCs], Front),
        forall(member(X, FA), ( X == sep ; tr_adjunct(X) )),
        PCs \== [], forall(member(X, PCs), tr_adjunct(X)),
        tr_at_piece_head(Words0),
        once(( member(w(PW, _), Front0), atom(PW), tr_participle_here(Side, PW, PL) )),
        ( tr_holds(feminine(PW)) -> PG = feminine ; PG = masculine ), tr_participle_number(PW, PartN),
        append(FA, [fpart(PL, PG, PartN, PCs)], Front1)
    ),
    %% THE REST IS READ WITH ITS COMMAS FIRST, as a statement is: `... la
    %% tesi di una leggerezza, escludendo che ...' read without them made the
    %% gerund a complement of the clause and the comma was lost
    %% -- after the front's own comma too: `En cambio, las ventas de casetes
    %% mantienen una evolución a la baja, concentrando ..., frente al ...'
    %% lost both commas after it, because the rest began with the front's
    tr_global('$tr_no_command', NC0), tr_time_front(Front1, NC0, NC1), nb_setval('$tr_no_command', NC1),
    (   ( Rest0 = [comma|RestC] -> true ; RestC = Rest0 ), RestC = [RC0|_], RC0 \== comma,
        memberchk(comma, RestC), tr_read_statement(Side, RestC, none, S0)
    ->  true
    %% (never with a comma out between two names, or before a name and its
    %% verb: `En la descripción de lord, Arturo Bucklaw, Vick se permite'
    %% made one person of the character and the director)
    %% ... nor a phrase a comma parts from the phrase after its coordinator:
    %% `Due anni al pugile positivo, ma il giudice ammette' read `positivo, ma il
    %% giudice' as one subject (tr_comma_and_parted/2)
    ;   \+ tr_names_parted(Side, Rest0), \+ tr_name_opens_clause(Side, Rest0), \+ tr_comma_and_parted(Side, Rest0),
        tr_uncomma(Rest0, Rest), Rest \== [],
        tr_read_statement(Side, Rest, none, S0)
    ->  true
    %% ... and with its adverbs lifted, as a whole piece's are (tr_adverbs_off/4):
    %% `En su afán por esconder sus planes, ni siquiera ha comunicado ...'
    ;   \+ tr_names_parted(Side, Rest0), \+ tr_name_opens_clause(Side, Rest0),
        tr_uncomma(Rest0, Rest), Rest \== [],
        tr_adverbs_off(Side, Rest, Rest1, Advs0), Advs0 \== [],
        tr_read_statement(Side, Rest1, none, S1), S1 = s(A1, Su1, G1, C1),
        \+ ( Side == foreign, tr_ago_time_subject(Su1, Advs0) ),
        tr_denials_in_front(Side, Rest, Advs0, Advs10), tr_head_adverb_in_front(Side, Rest, Advs10, Advs1),
        tr_advs_join(Side, Rest, C1, Advs1, C2),
        S0 = s(A1, Su1, G1, C2)
    ->  nb_setval('$tr_no_command', NC0)
    ;   nb_setval('$tr_no_command', NC0), fail
    ),
    S0 = s(A, Su, G, Comps0),
    ( ( Named == yes ; Pref == yes ) -> Su \= null(_, _), Su \== none, Su \== impersonal ; true ),
    ( Objd == yes -> Su \= null(_, _), Su \== none ; true ),
    %% ... and a topic is no front of a first person nobody names whose verb is a noun too: `Processo Grazioli, sconto
    %% al pentito Abbatino' is the Grazioli trial and a discount for the informer, two headings, and read as
    %% `sconto', I discount, English wrote `Trial Grazioli, I discount to the informer'
    \+ ( Front1 = [topic(_)], Su = null(first, singular),
         ( Rest0 = [comma, w(VW, _)|_] -> true ; Rest0 = [w(VW, _)|_] ), atom(VW), tr_is(Side, w(VW, lower), noun) ),
    %% ... and a front with a relative word in it is no command's: `a Ponza
    %% dove la proibizione ... resta valida dal primo luglio' is the place where
    %% the ban stays valid, and longest first the front took `resta' into the
    %% relative clause and left `valida', the adjective, for the command
    %% `validate!' (`s(none, none, g(validates, ..., imperative, ...)'
    %% (a command whose word is an adjective too, the word the relative clause left: with every such
    %% command refused, `in casi come questi conta soprattutto il primo soccorso' -- `come' for `like' --
    %% had no reading, and the Venice report's eighth sentence was read again 40 million inferences
    %% later, `to facilitate him, I accumulate of the sediments')
    \+ ( G = g(_, _, imperative, _), append(_, [w(FX0, _)|_], Front0), atom(FX0),
         ( tr_relative_word(Side, FX0) ; tr_indirect_word(Side, FX0, _) ),
         ( Rest0 = [comma, CW0|_] -> true ; Rest0 = [CW0|_] ), CW0 = w(CW, _), atom(CW), tr_is(Side, w(CW, lower), adjective) ),
    %% ... and a front's relative clause never takes a phrase after its comma, where no verb follows: `senza la ricerca
    %% di punta che si fa nei nostri laboratori, tutto il resto crolla' is everything else collapsing, and longest first
    %% the relative clause took `tutto il resto' for an apposition after the comma and left `crolla' for the command,
    %% `collapse!', or took `tutto' and left `il resto crolla'. Only where the words after the comma open on a subject,
    %% the verb's: an aside with a verb in it is the clause's (`la casa che, dice lui, è grande'), and so is an
    %% insertion (`dal fatto che la struttura urbana della città tende, anche con l'aiuto dell'acqua salmastra, a
    %% facilitare ...', the Venice report's eighth sentence, which refused here ran to the limit); and never where the
    %% rest opens on a subject of its own, so that the phrase is an apposition (`los pulsos tácticos entre Aíto y
    %% Majkovic, dos personajes antagónicos, el partido tuvo pasión' -- refused, the front was read again with `entre'
    %% for the verb, `Aíto enters')
    \+ ( append(_, [w(FX1, _)|FAfter], Front0), atom(FX1), tr_relative_word(Side, FX1),
         append(_, [comma|FTail], FAfter), FTail = [_|_],
         \+ ( member(w(TW, _), FTail), atom(TW), tr_verb_form_word(TW) ),
         (   FTail = [FT1|_], tr_is(Side, FT1, pronoun) -> true
         ;   append(FTail, Rest0, After2), tr_subject_first(After2),
             ( Rest0 = [comma|RestS] -> true ; RestS = Rest0 ), \+ tr_subject_first(RestS)
         ) ),
    %% ... and a front that ends on an absolute clause with no comma after it
    %% leaves the rest its subject: `Dopo una rivoluzione mancata la Lazio si è
    %% ritrovata uguale a sé stessa' is the Lazio's, and longest first the
    %% front took `mancata la Lazio' for a clause of its own and left a verb
    %% with nobody named (tr_absolute_start/2)
    ( Rest0 \= [comma|_], memberchk(abs(_, _), Front1) -> Su \= null(_, _), Su \== none, Su \== impersonal ; true ),
    %% ... and a front that ends on a name leaves the rest its subject: `nel
    %% vii secolo Isidoro di Siviglia ... aveva calcolato' is Isidore's
    %% reckoning, and longest first the name was apposed to the century
    %% (tr_np/3) and the verb had nobody named
    %% (a bracket after the name is the name's: `Isidoro (autorità indiscutibile)')
    %% (only a name APPOSED to a noun: after the front's own preposition or
    %% article the name is what the front is about, and the rest may name
    %% nobody -- `Si en Florencia, en su estreno, la producción recibió
    %% silbidos, en Barcelona pasó sin problemas' is the production passing
    %% in Barcelona, and refused here the sentence had no reading)
    %% ... and so does a front before a verb with its own pronoun, which read with nobody named was the impersonal one:
    %% `alla fine degli anni cinquanta Eco si è trovato nella posizione migliore' is Eco finding himself there, and it
    %% was `One has found in the best position at the end of the fifty years Eco' -- a name the lesson states, as
    %% the impersonal word may follow a place's own name (`nel teatro Morlacchi si canta' is one singing there)
    \+ ( Su = null(_, _), tr_front_name_apposed(Side, Front0) ),
    \+ ( Su == impersonal, last(Front0, w(FN, upper)), atom(FN), tr_solve(name(FN)), tr_front_name_apposed(Side, Front0) ),
    ( nonvar(Agree) -> tr_front_adj_agrees(Side, Agree, Su) ; true ),
    ( nonvar(PartN), tr_front_number(Su, SN) -> SN == PartN ; true ), !,
    %% ... and a front that asks WHERE or relates is written in front as well:
    %% `e da dove abbiamo poi ritrovato la mamma' went after its clause and
    %% came out `hemos recuperado la mamá desde donde'
    (   ( memberchk(comma, Front0) ; Rest0 = [comma|_] )
    ->  findall(fr(X), member(X, Front1), Fr), append(Fr, Comps0, Comps)
    ;   member(w(FX, _), Front0), ( tr_indirect_word(Side, FX, _) ; tr_relative_word(Side, FX) )
    ->  findall(frn(X), member(X, Front1), Fr), append(Fr, Comps0, Comps)
    %% (a connecting adverb at its head stays in front, tr_connective_in_front/4)
    ;   tr_connective_in_front(Side, Front0, Front1, Front2),
        findall(X, ( member(X, Front2), X = frn(_) ), FrC), subtract(Front2, FrC, Front3),
        tr_front_place(main, Comps0, Front3, Comps1), append(FrC, Comps1, Comps)
    ),
    SF = s(A, Su, G, Comps),
    %% ... AND A QUOTATION THAT OPENS ON A FRONT THE WRITER MOVES IS THE
    %% CLAUSE'S (tr_clause_marks/3): `"nel corso cercherò di illustrare una
    %% missione spaziale ...' opens on `nel corso', written after the clause,
    %% and the mark went with it into the middle, `en el transbordador "en el
    %% curso'
    %% (SF, SF2 and CF, because this clause has ONE scope and its adverb
    %% branch above binds S1 and C1: named so, the new goals unified with
    %% the statement read before its adverbs were joined, failed, and `Il
    %% cane dice che, ieri, proprio il gatto dorme' lost its front -- `el gato
    %% duerme ayer precisamente')
    %% (only where the quotation runs on past the front: `Il blitz è riuscito,
    %% "dal punto di vista tattico" l'operazione è considerata già conclusa'
    %% -- the twelve's eleventh -- quotes the front alone, which carries both
    %% its marks where the writer moves it, and read as the clause's the
    %% whole clause came out quoted, `"la operación es considerada ya
    %% concluida desde el punto de vista táctico"')
    (   Side == foreign, \+ ( member(CF, Comps), ( CF = fr(_) ; CF = frn(_) ) ),
        tr_quote_runs_on(Words0), tr_clause_marks(Words0, SF, SF2)
    ->  S = SF2
    ;   S = SF
    ).
tr_read0(Side, question, Words0, S) :-
    tr_uncomma(Words0, Plain),
    tr_normalise(Side, question, Plain, Words, Asked),
    length(Words, Len), Max is Len - 1, Max >= 1,
    %% the complement reader asks two globals the group sets, and no group
    %% has been read yet: left over from the sentence before, `dal punto di
    %% vista tattico' was taken for a PASSIVE'S AGENT and the front refused
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    between(1, Max, Back), K is Max + 1 - Back, length(Front0, K), append(Front0, Rest, Words),
    tr_complements(Side, Front0, Front), Front \== [],
    forall(member(X, Front), tr_adjunct(X)),
    %% (and what follows a fronted TIME is no command: `Così un bel giorno
    %% butta in aria una moneta' is one fine day HE throws a coin, and read as
    %% the imperative `butta' also is it came out `Dump in air a money' --
    %% tr_time_front/2)
    tr_global('$tr_no_command', F0), tr_time_front(Front, F0, F1), nb_setval('$tr_no_command', F1),
    (   tr_read_statement(Side, Rest, Asked, S0) -> nb_setval('$tr_no_command', F0)
    ;   nb_setval('$tr_no_command', F0), fail
    ),
    S0 = s(A, Su, G, Comps0), !,
    append(Comps0, Front, Comps),
    S = s(A, Su, G, Comps).
%% A FRONT BEFORE THE QUESTION WORD: `Su cento italiani residenti quanti sono
%% i poveri?' is out of a hundred resident Italians, how many are poor. The
%% question word was looked for at the head of the words, and with a phrase
%% before it the piece read as a statement with a mark. The front is the
%% adjuncts the words before the first question word read as, written after
%% the clause as every front is.
tr_read0(foreign, question, Words0, S) :-
    append(Front0, [w(Q, QC)|Rest], Words0), Front0 = [_|_], Rest = [_|_],
    atom(Q), tr_asking_word(foreign, w(Q, QC)),
    \+ memberchk(comma, Front0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Front0, Front), Front \== [],
    forall(member(X, Front), tr_adjunct(X)),
    tr_read(foreign, question, [w(Q, QC)|Rest], s(A, Su, G, Comps0)), A \== none, !,
    append(Comps0, Front, Comps),
    S = s(A, Su, G, Comps).
%% A CONNECTING WORD THE LESSON ALSO GIVES AS AN ADVERB THAT STAYS IN FRONT,
%% WITH A COMMA STRAIGHT AFTER IT AT THE HEAD, IS THE ADVERB: `Mientras, la
%% campaña militar en Chechenia también prosigue' is Meanwhile, and read as
%% the connector it was `While the military campaign continues', its comma
%% lost -- and with the comma after `prosigue' the clause was an insertion
%% (below). A connector opens its clause, never a comma; the adverb travels in
%% front, fr/1, and every writer puts its comma back
tr_read0(foreign, Kind, [w(C, CC), comma|Words], S) :-
    tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
    tr_word_across(w(C, lower), english, adverb, T), en_conjunctive(T),
    Words = [_|_], tr_read(foreign, Kind, Words, S0), tr_front_adverb_in(S0, adv(w(C, CC)), S), !.
%% A SUBORDINATE CLAUSE AT THE HEAD, WITH AN INSERTION AFTER ITS WORD: `Al
%% margen de que, como todos, han disfrutado de unos días de descanso,
%% curiosamente Rivaldo y Overmars tampoco estuvieron en Gandía'. A comma
%% straight after the connecting word opens an insertion, and it belongs to
%% the clause the word introduces -- divided at the comma after it, `como
%% todos' read as a clause of its own, `I eat everyone'. The clause runs
%% from the insertion to the next comma that leaves a clause after it, and
%% the IR is the one a comma division of `Si llueve, no salgo' gives, with
%% the connector's own comma kept: join(comma, join(wc(Conn), none, S1),
%% S2). With no clause after it, the sentence is the subordinate clause.
tr_read0(Side, Kind, [w(C, CC), comma|Words0], S) :-
    tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)),
    append(Ins, [comma|R1], Words0), Ins \== [], \+ memberchk(comma, Ins), !,
    (   append(SubRest, [comma|Main0], R1), SubRest \== [], Main0 \== [],
        append(Ins, [comma|SubRest], Sub),
        tr_read(Side, statement, Sub, S1),
        tr_clause_words(Main0, Main), tr_read(Side, Kind, Main, S2)
    ->  S = join(comma, join(wc(w(C, CC)), none, S1), S2)
    ;   append(Ins, [comma|R1], Sub), tr_read(Side, Kind, Sub, S1),
        S = join(wc(w(C, CC)), none, S1)
    ).
%% A CONNECTOR AT THE HEAD IS READ BEFORE ANY DIVISION, AND WITH THE COMMAS
%% AFTER IT: `E il Giglio ... ritorna alla dimensione dell'oasi così come le
%% Eolie, interdette al traffico, e l'isola di Ustica'. The division below
%% came first, found the last `e' and read `l'isola di Ustica' as a clause of
%% its own -- `lo aísla de Ustica', somebody isolating somebody -- because
%% the one reading of the whole after the connector (further down) had lost
%% its commas and failed. What follows the connector is the sentence, so it
%% is read as one, as the whole piece.
%% ... A COORDINATING ONE: `Si bien X, Y' opens a clause that ends at the
%% comma, which the division reads right, and read as one piece the rest cost
%% Spanish's record report 14.4 million inferences a sentence against 5.7
tr_read0(Side, Kind, [w(C, CC)|Rest], S) :-
    Rest = [R1|_], R1 \== comma, tr_connector(Side, C), tr_coord(Side, w(C, CC)),
    tr_global('$tr_piece', P0), tr_piece_starts(P0, [w(C, CC)|Rest]),
    nb_setval('$tr_piece', Rest),
    (   tr_read_after_coord(Side, Kind, w(C, CC), Rest, S1) -> nb_setval('$tr_piece', P0) ; nb_setval('$tr_piece', P0), fail ), !,
    S = join(w(C, CC), none, S1).
%% A QUOTATION THAT OPENS INSIDE THE SENTENCE AND DOES NOT CLOSE IN IT:
%% `Poi l'incontro con Cesare "lui non è un artista molto noto come avete
%% scritto.' -- what went before, and then what Cesare said. Nothing marks
%% the division but the mark, and read as one clause the piece had two
%% verbs. It divides before the word the mark opens on, each side read as a
%% statement, and nothing is written between them, join(aside, ...): the
%% mark goes back on its word, as the source has it
tr_read0(foreign, statement, Words0, S) :-
    append(Left, [Q|Right], Words0), Left \== [], Right \== [],
    Q = w(_, QC), memberchk(QC, [qopen, qopenu]),
    \+ ( member(w(_, C2), Right), memberchk(C2, [qclose, qcloseu, qboth, qbothu]) ),
    tr_read(foreign, statement, Left, S10),
    tr_read(foreign, statement, [Q|Right], S2), !,
    %% (a comma that ends the first side is the source's, and stays before
    %% the mark that opens the second: `"non andrei mai al Tg 4" dice lui,
    %% "né vorrei pestare i piedi a nessuno"' -- the clause of the report
    %% gets its sep/0, as one before a quotation of its own does)
    ( last(Left, comma) -> tr_sep_last(S10, S1) ; S1 = S10 ),
    S = join(aside, S1, S2).
%% A QUESTION THAT OPENS IN THE SECOND CLAUSE: `Sì, può essere che
%% Margherita abbia avuto un malore ma perché nessuno le ha viste?' -- it may
%% be that she was taken ill, but why did nobody see them? The mark ends the
%% sentence and belongs to the clause a question word opens after a
%% coordinator; read as one question, `perché' was the connector `because'
%% and the sentence asked whether it could be. The first clause is the
%% statement it is and the second the question, join/3 with q/1, as after a
%% colon: the lesson's opening mark goes before the second
tr_read0(Side, question, Words0, join(C, S1, q(S2))) :-
    append(Left0, [C|Right0], Words0), C = w(CW, _), atom(CW),
    tr_connector(Side, CW), tr_coord(Side, C),
    Right0 = [w(QW, _)|_], atom(QW), tr_indirect_word(Side, QW, _),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_read(Side, statement, Left, S1),
    tr_read(Side, question, Right, S2), S2 = s(Asked, _, _, _), Asked \== none, !.
tr_read0(Side, Kind, Words0, S) :-
    tr_clause_split(Side, Words0, Left0, Conn0, Right),
    tr_division(Side, Kind, Words0, Left0, Conn0, Right, S), !.

%% A CONNECTOR AT THE HEAD JOINS THIS SENTENCE TO THE ONE BEFORE IT.
%% `Ma gia si parla di epurazioni' -- newspaper prose opens a sentence with
%% `Ma', `E', `Perche', and tr_clause_split/5 finds no left clause for it
%% because there is none IN THE SENTENCE. It is the same join with nothing
%% on its left, so the IR is join(Conn, none, S) and every writer puts the
%% connector first. What is lost is nothing: the connector is written back
%% where it stood.
%% -- THE CLAUSE WITH ITS COMMAS FIRST: `Pese a que empezó frío, poco
%% expresivo, Bros fue entonándose' has two things said of how he began,
%% and read with the comma between them taken out they were one phrase,
%% `frío poco expresivo', a little expressive thing he began cold
tr_read0(Side, Kind, Words0, S) :-
    Words0 = [w(C, CC)|Rest0], Rest0 = [R0|_], R0 \== comma, memberchk(comma, Rest0),
    tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)),
    tr_read(Side, Kind, Rest0, S1), !,
    S = join(w(C, CC), none, S1).
%% A RELATIVE CLAUSE STANDING ALONE AFTER A COORDINATOR: `l'irrequietezza di
%% Bossi, il quale non è un uomo di stato: ma che ha dimostrato di essere un
%% ottimo cane da tartufi' -- who is no statesman, but who has shown himself a
%% fine truffle dog. After the colon there is no phrase for the clause to sit
%% on; it is said of the one the clause before it named, as a time clause
%% standing alone is (rwh/2), and rcl(Role, S) carries it. Every writer puts
%% the relative word before the clause.
tr_read0(Side, statement, [w(C, CC), w(R, RC)|Ws], join(w(C, CC), none, gap([], [rcl(Role, S)]))) :-
    Ws \== [], tr_connector(Side, C), tr_coord(Side, w(C, CC)),
    tr_relative_word(Side, R),
    tr_relative_clause(Side, [w(R, RC)|Ws], Role, S), !.
tr_read0(Side, Kind, Words0, S) :-
    tr_uncomma(Words0, [w(C, CC)|Rest]), Rest \== [],
    tr_connector(Side, C),
    tr_read_after_coord(Side, Kind, w(C, CC), Rest, S1), !,
    S = join(w(C, CC), none, S1).
%% A CLAUSE OF `CHE' IN FRONT OF THE SENTENCE IT IS ABOUT: `Che si tratti di
%% un progetto bocciato sul nascere sono molti i fatti che lo dimostrano' --
%% that it is a project rejected at birth, many facts show it. The clause
%% after `che' runs to the main clause's verb, the nearest place a verb group
%% starts where the rest reads as a statement; it goes in front, frn/1, and
%% is written back there with its word. The `lo' of the main clause stands
%% for it, as it does in every language here.
%% (the main verb's clitics are the main clause's: `Che il cane dorma lo
%% dimostrano i fatti' -- read as the clause's own, the dog slept HIM and
%% somebody demonstrated the facts. `lo' takes the clause up again, so the
%% phrase after the verb that agrees with it is the verb's subject, as the
%% facts are the ones that demonstrate it.)
%% (the MAIN clause may hold a comma, the clause in front none: `Che la
%% terra fosse sferica lo sapevano non solo Tolomeo ed Eratostene, ma
%% persino Pitagora' -- no comma anywhere was asked, and the sentence had
%% no reading)
tr_read0(foreign, statement, [W|Ws], S) :-
    tr_that_here(foreign, W), Ws = [_|_],
    append(Left, Right, Ws), Left \== [], \+ memberchk(comma, Left),
    Right = [w(_, _)|_], tr_group_after_clitics(Right),
    \+ ( last(Left, w(LC, _)), atom(LC), tr_clitic(none, LC) ),
    tr_that_clause(foreign, Left, S1),
    tr_read(foreign, statement, Right, S0), S0 = s(_, _, _, _), !,
    tr_resumed_subject(S0, s(A, Su, G, Cs)),
    S = s(A, Su, G, [frn(that(S1))|Cs]).
%% ... AND ONE A COMMA SETS OFF: `Che poi queste cose le sapessero i dotti e
%% i semplici no, guardate che ancora oggi c'è gente ...' -- that the learned
%% knew these things and the simple did not: look, even today there are
%% people ... The clause in front runs to the comma and the main clause after
%% it opens on its verb, here a command. Read as a clause with no verb, the
%% command was the participle `guardate', looked, said of nobody; it goes in
%% front with its comma, fr/1, as a front the source set off does
tr_read0(foreign, statement, [W|Ws], S) :-
    tr_that_here(foreign, W), Ws = [_|_],
    append(Left, [comma|Right], Ws), Left \== [], \+ memberchk(comma, Left),
    Right = [w(_, _)|_], ( tr_group_after_clitics(Right) ; tr_main_start(foreign, Right) ),
    %% (the cut is after the clause of `that' reads: an exclamation's `che' is
    %% `what' before a noun, `Che ambiguità, una squalifica di due anni!', and
    %% with the cut before it the sentence had no other reading to go on to)
    tr_that_clause(foreign, Left, S10), !,
    tr_read(foreign, statement, Right, S0), S0 = s(A, Su, G, Cs), !,
    %% (and a connecting adverb at its head stays there, `Che poi ...', as
    %% it does at the head of a nested clause: tr_nested_connective/4)
    tr_nested_connective(foreign, Left, S10, S1),
    S = s(A, Su, G, [fr(that(S1))|Cs]).
%% ... AND ONE WHOSE MAIN CLAUSE FOLLOWS WITH NO COMMA: `Se sbaglio
%% correggetemi' is if I am wrong, correct me. It is the time clause's shape
%% (below) for any word that subordinates, tried only where the rest read as
%% no one clause: it divides before a word that starts a verb group, the
%% nearest first, where the subordinate clause reads before it and the main
%% clause after it. The subordinate clause is no command, as after the word
%% anywhere (tr_read_joined/5); the main clause may be one. Nothing is
%% written between the two, join(aside, ...), as the source put nothing.
%% ... AND BEFORE THE MAIN CLAUSE'S SUBJECT: `Se avessimo più soldi le
%% università non sarebbero così scalcinate' is if we had more money, the
%% universities would not be so shabby -- the main clause opens on its
%% subject's article, not on its verb, and the piece was refused
%% ... AND A CONNECTING ADVERB BEFORE THE SUBORDINATE CLAUSE: `Comunque se
%% mai ci sarà una causa e un risarcimento non voglio una lira per me' is
%% anyway, if there is ever a lawsuit, I do not want a lira. The adverb
%% says how the sentence follows from the one before, which is the main
%% clause's to say, and it goes in front of that clause (frn/1); the
%% division below wants the connector first, and read as one clause the
%% piece had two verbs and no reading
tr_read0(foreign, statement, [w(A, AC), w(C, CC)|Ws], join(aside, J1, S2)) :-
    atom(A), tr_lexeme(foreign, A, L, _), once(tr_solve(mean(L, E))), en_conjunctive(E),
    atom(C), tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
    tr_read0(foreign, statement, [w(C, CC)|Ws], join(aside, J1, S20)),
    S20 = s(As, Su, G, Cs), !,
    S2 = s(As, Su, G, [frn(adv(w(A, AC)))|Cs]).
%% ... AND ASIDES IN THE SUBORDINATE CLAUSE: `Si la FIFA, convaleciente de
%% una cruenta batalla interna, salpicada por la plaga de la corrupción,
%% hubiera buscado un escenario mejor no lo habría encontrado' -- what FIFA
%% is stands between commas after it, and a comma anywhere in the piece shut
%% the division out. The main clause holds none, and the subordinate clause
%% does not end on one, which is the division at a comma's to read
tr_read0(Side, statement, [w(C, CC)|Ws], join(aside, join(w(C, CC), none, S1), S2)) :-
    Ws = [_|_],
    tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)),
    append(Left, Right, Ws), Left \== [], \+ memberchk(comma, Right),
    \+ last(Left, comma), \+ ( last(Left, w(N, _)), atom(N), tr_negation_word(N) ),
    tr_main_start(Side, Right),
    tr_global('$tr_no_command', F0), nb_setval('$tr_no_command', yes),
    (   tr_read_nested(Side, Left, none, S1) -> nb_setval('$tr_no_command', F0)
    ;   nb_setval('$tr_no_command', F0), fail
    ),
    tr_read(Side, statement, Right, S2),
    \+ tr_main_object_in_front(Side, Right, S2), !.
%% A CLAUSE WITH NO VERB AT ALL IS ITS COMPLEMENTS, and two kinds of it are
%% ordinary prose: an exclamation, `¡Atención al veneno mental de la hora de
%% la sopa!', and a clause that leaves out the verb of the one before it,
%% `se les llamará muchachos conflictivos; en los de clase media, chicos
%% difíciles' -- the same calling, of other boys. Both are what is left
%% when the verb is taken out, so they read the same way: the words split
%% at their comma, if they have one, into what stood before the missing verb
%% and what stood after it, each read as complements. gap(Front, Back) is
%% the term, and every writer puts back the complements and the comma --
%% and never a verb, which is how all three languages write both kinds.
%%
%% IT IS TRIED LAST, AND ONLY WHERE NO WORD COULD START A VERB GROUP, so a
%% sentence with a verb in it is never read as one that lacks it. And a PART
%% of a sentence -- one side of a comma or a connector -- is verbless only in
%% the gapped form, a comma where the verb was: without that, any tail after
%% `o' read as a clause of its own, and `anárquica o xenófoba' lost its
%% last adjective to one.
%% A SENTENCE THAT IS ONE PHRASE WITH ITS RELATIVE CLAUSE: `Una scelta
%% strategica da cui ci attendiamo positive conseguenze', `Una buona notizia
%% che consolida definitivamente l'integrazione'. The verb is the relative
%% clause's, so the verbless reading below -- which wants no word that could
%% start a group -- stands down, and the phrase had no verb of its own to be
%% a statement. The whole piece is read as one phrase, and only a phrase
%% that carries a clause: a piece with no verb anywhere is the reading
%% below.
%% (a comma that closes an aside is the aside's, which after a name keeps
%% it: `un'idea che Vittori, disposto a dedicarsi alla docenza ..., non esita
%% a definire coraggiosa' is an idea, which Vittori calls brave)
tr_read0(Side, statement, Words0, gap([], [obj(NP)])) :-
    tr_global('$tr_piece', Piece), Piece == Words0,
    \+ ( append(PreC, [comma|_], Words0), \+ last(PreC, w(_, aside)) ),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_phrase_np(Side, Words0, NP), ( NP = rc(_, _, _) ; NP = rel(_, _, _) ), !.
%% ... AND A PHRASE WITH A CLAUSE OPENED BY A QUESTION WORD: `Amene località
%% dove le auto, le moto e i ciclomotori di gitanti e turisti sono banditi'
%% -- pleasant places where cars are banned. The complement reader reads it
%% as the phrase and a relative `where' (rwh/2), and the clause's verb had
%% shut out the verbless reading.
tr_read0(Side, statement, Words0, gap([], [obj(NP), rwh(Q, S)])) :-
    tr_global('$tr_piece', Piece), Piece == Words0,
    \+ memberchk(comma, Words0),
    %% -- and never a phrase whose head is a conjunction: `cioè quando gli
    %% altri erano vicini' is `that is' and a clause, and read here `that is'
    %% was the NOUN of a phrase the clause was said of
    Words0 = [W0|_], \+ tr_is(Side, W0, preposition), \+ tr_is(Side, W0, conjunction),
    once(( member(w(QW, _), Words0), tr_indirect_word(Side, QW, _) )),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, Words0, [obj(NP), rwh(Q, S)]), !.
%% (and a phrase with a participle after its noun is the same kind of
%% sentence, the headline's: `Auto proibite nelle isole del sole.' -- tried
%% BEFORE the verbless reading below, which took `proibite' for an adjective
%% no lesson of the other language has a word for)
%% ... AND A HEADLINE'S PARTICIPLE WITH ITS PHRASES AFTER IT: `Auto
%% proibite nelle isole del sole' is cars banned in the islands of the sun.
%% A reduced relative takes an agent after its participle and nothing else,
%% which is right inside a clause, where a phrase after the participle may
%% be the verb's; a whole piece with no verb has no verb to give it to. The
%% phrase is in the participle's number: `auto' is both.
tr_read0(Side, statement, Words0, gap([], [obj(rel(NP, L, Comps))])) :-
    tr_global('$tr_piece', Piece), Piece == Words0,
    tr_participle_headline(Side, Words0, NP, L, Comps), !.

%% A CLAUSE OPENED BY `when' OR `where' MAY STAND ALONE, said of what came
%% before it: `l'abbiamo vinto a schiatto: cioè quando gli altri erano
%% vicini al traguardo' is the colon, `that is', and a time clause with no
%% clause of its own to hang on. It is the relative word's clause, rwh/2,
%% which a writer spells with the lesson's conjunction -- `cuando', where
%% the question is `cuándo'. Only these two: a `how' or a `why' standing
%% alone asks something.
tr_read0(Side, statement, [w(QW, _)|Ws], gap([], [rwh(Q, S)])) :-
    Ws \== [], tr_indirect_word(Side, QW, Q), memberchk(Q, [when, where]),
    tr_read_nested(Side, Ws, none, S), !.
%% ... AND ONE WHOSE MAIN CLAUSE FOLLOWS WITH NO COMMA: `Cuando pudieron
%% rescatar al accidentado descubrieron con cierta sorpresa que ...' -- when
%% they could rescue him, they found. Nothing marks where the time clause
%% ends but the main clause's verb, and read as one clause the piece had two
%% verbs and no reading. It divides before a word that starts a verb group,
%% the nearest first, where the time clause reads before it and a statement
%% after it -- never across a comma, which the division at a comma reads.
%% Nothing is written between the two, join(aside, ...), as the source put
%% nothing there.
%% ... AND THE MAIN CLAUSE MAY OPEN ON ITS PRONOUNS OR ITS DENIAL: `Cuando Sam
%% y Frodo están en el campo con el espantapájaros se ve al fondo pasar un
%% coche' -- one sees a car. The division was asked only where a verb group
%% starts, which put `se' in the time clause, and nothing read.
tr_read0(Side, statement, [w(QW, _)|Ws], join(aside, gap([], [rwh(when, S1)]), S2)) :-
    Ws \== [], tr_indirect_word(Side, QW, when),
    append(Left, Right, Ws), Left \== [], \+ memberchk(comma, Left),
    Right = [w(_, _)|_], tr_gap_verb_next(Side, Right),
    tr_read_nested(Side, Left, none, S1),
    tr_read(Side, statement, Right, S2), !.
%% A BARE NOUN BEFORE A CLAUSE OF ANOTHER PERSON IS WHAT THE CLAUSE HANGS ON:
%% `testa andiamo a vivere in Brasile, croce in Usa' -- heads, we go to live in
%% Brazil; tails, in the US. A singular noun can be no subject of `andiamo',
%% and read as a verb (`testa', he tests) the clause had two. It stays in
%% front, as the phrase `lo que hace' is said of does (frn/1)
%% (the clause's verb in the first or second person comes first, at its
%% head: asked after the noun, every piece that opens on a bare noun read its
%% whole rest as a statement to find out -- 4.3 million inferences over three
%% sentences of the controls, for no text)
tr_read0(foreign, statement, [N|Rest], S) :-
    N = w(NW, lower), atom(NW), Rest = [R1|_], R1 \== comma,
    \+ \+ ( tr_group_at(foreign, Rest, g(_, _, _, P0, _), _), P0 \== third ),
    tr_is(foreign, N, noun), tr_lexeme(foreign, NW, _, singular), \+ tr_determiner(foreign, N, _, _),
    tr_np(foreign, [N], NP), NP = np(none, none, [], _, singular),
    tr_read_statement(foreign, Rest, none, S0), S0 = s(A, Su, G, Cs),
    Su = null(P, _), P \== third, !,
    S = s(A, Su, G, [frn(topic(NP))|Cs]).
%% AN ADJECTIVE ALONE AT THE HEAD IS THE PROPERTY IT NAMES, AND THE SUBJECT:
%% `Ma immobile non voleva dire piatta' -- but motionless did not mean flat.
%% A word the lesson knows only as an adjective, with no article and no
%% comma after it, before a verb that is no copula (`bello è il cane' has
%% its subject after the copula, and is read so); read as the clause's own,
%% the verb had nobody named and the adjective was no phrase at all, and the
%% sentence was refused. It travels as adjs/1 in the subject's place, and
%% every writer gives the adjective as the lesson does
%% (never the head of the sentence set in small letters by tr_head_lower/3,
%% which a surname is as often: `Redondo declaró a Europa Press que ...'
%% is the man, and read as the property the name was translated, `Rotondo
%% dichiarò' -- tr_read_ir/5 names that word, and the name reading goes on
%% as it was)
%% (and the verb, after its denial, comes next: every sentence that opens
%% on an adjective read its whole rest this way, and the islands report's
%% `Amene località dove ...' and Ciampi's `Lapidario ma significativo il
%% commento ...' paid 0.37 and 0.16 million inferences for nothing -- asked
%% AFTER the class tests, which the sentence keeps: asked before them, the
%% search for a verb group was paid by every statement read, whatever its
%% first word, 51 000 inferences of Tatoeba's 400)
tr_read0(foreign, statement, [A|Rest], S) :-
    A = w(AW, _), atom(AW), Rest = [R1|_], R1 \== comma, \+ tr_global('$tr_head_adjective', AW),
    tr_is(foreign, A, adjective), \+ tr_is(foreign, A, noun), \+ tr_determiner(foreign, A, _, _),
    ( Rest = [w(N1, _)|RestV], atom(N1), tr_negation_word(N1) -> true ; RestV = Rest ),
    tr_group_past_clitics(RestV),
    tr_read_statement(foreign, Rest, none, S0), S0 = s(As, null(third, singular), G, Cs),
    G = g(L, _, _, _), atom(L), \+ tr_solve(mean(L, is)), !,
    S = s(As, adjs([A]), G, Cs).
%% A PREDICATE ADJECTIVE IN FRONT OF ITS SUBJECT, THE COPULA LEFT OUT:
%% `Incerto il futuro di Funari.' says what the future of Funari is. The
%% verbless reader finds the adjective the complement of the phrase after it
%% (tr_complements0/4), as `definire illegale la decisione' has it, and the
%% sentence is the clause `the future of Funari is uncertain': every writer
%% says it with its own copula, and the adjective agrees with its noun
%% ... THE PHRASES OF `of' AFTER THE NOUN ARE THE SUBJECT'S AND THE OTHERS THE
%% CLAUSE'S: `Disastrosa la situazione nel Mezzogiorno' is the situation
%% that is disastrous IN the south, and with every phrase given to the
%% subject, which allows `of' phrases only, only `di Funari' read
tr_read0(foreign, statement, Words0, S) :-
    tr_verbless(foreign, Words0, gap([], [oc(NP, As)|PPs])), tr_copula_lexeme(CL), !,
    tr_subject_pps(PPs, Of, Rest),
    ( Of == [] -> Subject = NP ; Subject = with(NP, Of) ),
    S = s(none, Subject, g(CL, present, simple, no), [adj(As)|Rest]).
%% ... AND TWO ADJECTIVES JOINED: `"cinici e diseducativi" i film' heads the films that are cynical and miseducative.
%% The coordination is read before the clause above can be, and cut, so the piece was refused: the first adjective
%% and its coordinator are taken off, the rest read as the clause above reads it, and they are put back before the
%% adjective it found
tr_read0(foreign, statement, Words0, S) :-
    Words0 = [A1, Co, A2, D|_], Co = w(CW, _), atom(CW), tr_coord(foreign, Co),
    \+ memberchk(comma, Words0), length(Words0, NW0), NW0 =< 10,      % (a heading: short, and no comma in it)
    A2 = w(_, _), tr_determiner(foreign, D, _, _), tr_all_adjectives(foreign, [A1]),
    tr_global('$tr_piece', P0), P0 == Words0, Words1 = [A2, D|_], append([A1, Co], Words1, Words0),
    nb_setval('$tr_piece', Words1),
    (   tr_verbless(foreign, Words1, gap([], [oc(NP, As2)|PPs])) -> nb_setval('$tr_piece', P0)
    ;   nb_setval('$tr_piece', P0), fail
    ),
    tr_copula_lexeme(CL),
    tr_subject_pps(PPs, Of, Rest), !,
    ( Of == [] -> Subject = NP ; Subject = with(NP, Of) ),
    S = s(none, Subject, g(CL, present, simple, no), [adj([A1, Co|As2])|Rest]).
%% A QUESTION WORD AND A PHRASE, NO VERB: `Quanto tempo?' -- how much time,
%% the question of an interview that asks how long. The question word asks
%% (quantity/1) and the phrase after it is what it asks of; qnp/2 holds both,
%% as the clause's Asked and subject would, and every writer puts the
%% question word first. Read with the verbless reader's own phrase, `quanto'
%% was the adverb `as much' -- `¿Cuanto tiempo?' -- and the piece was refused
tr_read0(foreign, question, Words0, gap([], [qnp(Asked, NP)])) :-
    tr_global('$tr_piece', Piece), Piece == Words0,
    fo_question_word(Words0, Rest, Asked), Asked \== none, Asked \= subject(_), Asked \= pp(_, _),
    (   Rest == [] -> NP = none
    ;   Asked = quantity(_), tr_np(foreign, Rest, NP), NP \= name(_)
    ), !.
%% A HEADING OF BARE NOUNS IN A LIST: `Forzatura, distinguo e bacchettata.' --
%% the three things the report goes on to name, one noun each. A list has
%% commas, and it is the commas that make it a heading: `Pane e vino.' stands
%% alone and stays refused, two nouns joined by `e' being a pair and not a
%% list (a section's name is one noun, and a bare title follows a signature).
%% It travels as the object of a clause with no verb, co(C, A, B) among the
%% nouns as in a signature's title (tr_bare_title/3), and every writer puts
%% the commas back
tr_read0(Side, statement, Words0, gap([], [obj(T)])) :-
    tr_global('$tr_piece', P0), P0 == Words0,
    memberchk(w(',', lcomma), Words0),
    tr_bare_title(Side, Words0, T), T = co(_, _, _), !.
%% A QUOTATION RIGHT AFTER A VERB OF SAYING, WITH NO MARK BETWEEN THEM, IS
%% WHAT THE VERB SAYS: `il Polo ha risposto "vedo"' is `ha risposto: "vedo"',
%% the poker player's call. The quoted word is a verb's form, where an
%% object is a noun, and read as an object (an adverb, `ha risposto "sì"')
%% it left the clause no reading. Tried when every other reading has failed,
%% so that `ha detto "sì"' reads as it did; the colon is read in, and every
%% writer puts one back
tr_read0(foreign, Kind, Words0, S) :-
    append(Left, [Q|Right], Words0), Left = [_|_],
    Q = w(_, QC), tr_opens_quote(QC), \+ memberchk(colon, Words0),
    last(Left, w(V, lower)), atom(V),
    (   tr_form(V, L, _, _, _) ; tr_participle_here(foreign, V, L) ), tr_saying_verb(L), !,
    append(Left, [colon, Q|Right], Words1),
    tr_read(foreign, Kind, Words1, S).
tr_read0(Side, _, Words0, S) :- tr_verbless(Side, Words0, S), !.
%% TWO CLAUSES AT A COORDINATOR BETWEEN TWO PHRASES OF ONE PREPOSITION, WHERE
%% NOTHING ELSE READ: `il numero aumenterebbe notevolmente al Nord e al Centro
%% addirittura raddoppierebbe' -- the second clause has its subject left out and
%% its place in front. The division is shut out at such a coordinator
%% (tr_joins_phrases/3: `il responsabile dell'ambiente e dei lavori pubblici' is
%% one manager), and joined into one phrase of `al' the second verb had no
%% subject and the sentence was refused. Asked last, with a verb on each side,
%% so that no sentence that read before can read otherwise.
tr_read0(foreign, Kind, Words0, S) :-
    append(Left1, [w(C, CC)|Right0], Words0),
    tr_connector(foreign, C), tr_coord(foreign, w(C, CC)),
    tr_joins_phrases(foreign, Left1, Right0),
    tr_has_verb_group(foreign, Left1), tr_has_verb_group(foreign, Right0),
    \+ tr_bare_start(foreign, Right0), \+ tr_inside_insertion(foreign, Left1, Right0),
    (   append(Left0, [comma], Left1), Left0 \== [] -> Conn = both(comma, w(C, CC)) ; Left0 = Left1, Conn = w(C, CC) ),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right),
    tr_division(foreign, Kind, Words0, Left, Conn, Right, S), !.
%% A FRONT AND A CLAUSE THAT OPENS ON A CONNECTOR, where nothing else read:
%% `Per questo, ogni volta che andavamo a mangiare insieme - ... - gli
%% ricordavo ...' -- for this reason, and then a clause of whenever with its
%% main clause. A front is read inside the clause it stands before (fr/1), and
%% the clause after it was a connector's, join(Connector, none, S), which has
%% no main clause to hold one, so the sentence was refused with every word
%% known. The front is a verbless part of its own, as an answer is
%% (tr_head_join/4): gap([], Adjuncts), and every writer puts back its comma.
%% Asked last, with adjuncts only before the first comma and a connector right
%% after it, so that no sentence that read before can read otherwise.
tr_read0(foreign, Kind, Words0, S) :-
    Words0 = [W1|_], W1 = w(_, _),
    append(Front, [comma, C|Rest], Words0), Front \== [], \+ memberchk(comma, Front),
    C = w(CW, _), atom(CW), Rest \== [], tr_connector(foreign, CW), \+ tr_coord(foreign, C),
    length(Front, N), N =< 6,
    tr_front_adjuncts(Front, Cs),
    tr_read(foreign, Kind, [C|Rest], S2), !,
    tr_head_join(Kind, gap([], Cs), S2, S).
%% ... AND AN ADVERB RIGHT BEFORE THE WORD FOR `when' OR FOR `or', with no comma: `E così
%% quando martedì le due delegazioni torneranno ad incontrarsi, non ci sarà
%% più spazio per i bluff' -- so, when they meet again, there will be no room.
%% The adverb leads the sentence in, and the rest is a time clause and its
%% main clause, which the piece opening on `quando' reads (the first clause
%% above divides at the comma); the lead-in goes in front as any front does,
%% and the writer's comma after it
tr_read0(foreign, Kind, [W1, W2|Ws], S) :-
    W1 = w(A, _), atom(A), tr_is(foreign, W1, adverb), \+ tr_is(foreign, W1, noun),
    W2 = w(QW, _), atom(QW),
    (   tr_indirect_word(foreign, QW, when)
    %% ... or the word for `or', which opens the first half of an either-or:
    %% `Adesso o quelli del centro-sinistra diventano tutti presidenzialisti,
    %% oppure si perdono un alleato' -- now it is either they do or they lose
    ;   tr_lexeme(foreign, QW, QL, _), tr_solve(mean(QL, or))
    %% ... or the word for `if', which opens a condition and its main clause: `Poi se c'è bisogno della baby sitter,
    %% il conto sale di circa 130 euro al mese' -- then, if there is need of one, the bill rises; the condition's
    %% reader wants its word first, and with the adverb before it the sentence was refused
    ;   tr_lexeme(foreign, QW, QL, _), once(tr_solve(mean(QL, if)))
    ),
    tr_front_adjuncts([W1], Cs),
    tr_read(foreign, Kind, [W2|Ws], S2), !,
    tr_head_join(Kind, gap([], Cs), S2, S).
%% ... AND A QUESTION THE TEXT GAVE NO MARK, A COMMA, AND WHAT FOLLOWS: `"cosa le
%% posso dire, sarà stato un equivoco' -- what can I tell you, it must have
%% been a misunderstanding. The mark the text lacks is not written either: the
%% first half reads as the question it is and the second as a statement, and
%% the join writes the comma between them. Asked last, with a question word
%% at the head, so that no sentence that read before can read otherwise
tr_read0(foreign, statement, [W|Ws], join(comma, qh(S1), S2)) :-
    tr_question_word(W, _),
    append(Left0, [comma|Right], Ws), \+ memberchk(comma, Left0), Right \== [],
    tr_read(foreign, question, [W|Left0], S1), S1 = s(Asked, _, _, _), Asked \== none,
    tr_read(foreign, statement, Right, S2), !.
%% A HEADING AND THE ONE IT IS FOR: `Cattive notizie, infine, per chi ha scelto
%% Cortina per questo fine settimana: ...' is bad news for whoever chose Cortina
%% -- a phrase with no verb, adverbs between commas or none, then a preposition
%% and the word that begins the relative (`The word "chi" begins the
%% relative.'), its clause to the end of the piece. Read as a clause of its own
%% after the comma, the relative's verb was the sentence's (`Cortina has been
%% chosen for this weekend for the one that has'). The phrase is the heading's
%% object, the adverbs and the free relative its complements, the commas where
%% they stood. A sentence that asks (`Per chi lavori?') is no heading. Read
%% before the comma divides the piece, which took the clause after it first.
tr_heading_for_whom(Words0, gap([], [obj(NP)|Back])) :-
    tr_global('$tr_free_rel', yes), tr_global('$tr_kind', statement),
    %% (a whole piece, or the side of a colon read as a heading, tr_as_heading/2)
    ( tr_global('$tr_piece', Piece), Piece == Words0 -> true ; tr_global('$tr_heading', H), H == Words0 ),
    append(PW, [P, w(R, _)|RW], Words0), PW = [_|_], RW = [_|_], \+ memberchk(comma, RW),
    P = w(_, _), atom(R), tr_lexeme(foreign, R, RL, _), tr_solve(begin(RL, relative)), tr_is(foreign, P, preposition),
    (   append(NW, [comma|AW0], PW), \+ memberchk(comma, NW), append(AW, [comma], AW0), AW = [_|_]
    ->  forall(member(X, AW), tr_plain_adverb(foreign, X)), findall(adv(X), member(X, AW), As), append([[sep], As, [sep]], Mid)
    ;   NW = PW, \+ memberchk(comma, NW), Mid = []
    ),
    tr_np(foreign, NW, NP), NP = np(_, _, _, _, _),
    tr_gap_verb_next(foreign, RW),
    once(( tr_solve(relative(RR)), tr_solve(mean(RR, that)) )),
    once(( tr_solve(mean(A, the)), tr_solve(article(A)), \+ tr_holds(feminine(A)), \+ tr_solve(plural_of(A, _)) )),
    nb_setval('$tr_read_group', none),
    tr_relative_clause(foreign, [w(RR, lower)|RW], subject, S1), !,
    append(Mid, [pp(P, ell(det(article, A, w(A, lower)), masculine, singular, rel(subject, S1)))], Back).

%% the front goes on the first clause a division read
tr_front_on_first(s(Q, Su, G, Cs), F, s(Q, Su, G, [F|Cs]), Su) :- !.
tr_front_on_first(join(C, S1, S2), F, join(C, S1b, S2), Su) :- tr_front_on_first(S1, F, S1b, Su).

tr_semi_items(Side, Words, S) :-
    (   append(P, [semicolon|R0], Words)
    ->  tr_clause_words(R0, R), tr_semi_item(Side, P, S1), tr_semi_items(Side, R, S2),
        S = join(semicolon, S1, S2)
    ;   tr_semi_item(Side, Words, S)
    ).
%% no verb in it, and what is read is adverbs or a connector, then a phrase
%% or a preposition's phrase, and adjuncts after it
tr_semi_item(Side, Ws, gap([], Cs)) :-
    Ws = [W1|_], W1 = w(_, _), \+ tr_semi_verb(Side, Ws),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, Ws, Cs), tr_semi_complements(Cs), !.
%% a word that could start a verb group and is nothing else it could be
%% here: not a noun or an adjective too (`ministro' is also what
%% `ministrar' says of me), not capitalised inside the part, which is a
%% name's (`Piqué' is also what `picar' says of me in the past), not a
%% preposition (`como' is also I eat), not a determiner before its noun,
%% and not after a relative word, whose clause it is -- the same words the
%% verbless reading lets by (tr_verbless0/3)
tr_semi_verb(Side, Ws) :-
    append(Pre, [V|R], Ws), V = w(_, VC), VC \== upper,
    tr_group_at(Side, [V|R], _, _),
    \+ tr_also_nominal(Side, V), \+ tr_is(Side, V, preposition), \+ tr_heads_phrase(Side, [V|R]),
    \+ ( member(w(RW, _), Pre), atom(RW), tr_relative_word(Side, RW) ), !.
tr_semi_complements([C|Cs]) :- ( C = adv(_) ; C = cnj(_) ), !, tr_semi_complements(Cs).
tr_semi_complements([C|Cs]) :- ( C = obj(_) ; C = pp(_, _) ), tr_adjuncts(Cs).

%% what stands after the word at the head before the rest: its comma, or a
%% clause between dashes (tr_asides/3 made it one word) and perhaps a comma --
%% `"no - mi ha risposto -, a me piace ...', the answer and who gave it,
%% which stays where it stood (dsh/1)
tr_head_words([comma|Right], [], Right) :- !.
tr_head_words([w(K, dashed)|R1], [dsh(K)], Right) :- ( R1 = [comma|Right] -> true ; Right = R1 ).
%% ... and a question is the clause after the word at the head, which has
%% no verb to ask with: English fronts its own verb there, `Professor, does
%% the dog sleep?', and the lesson's opening mark goes where the question
%% begins, `Profesor, ¿el perro duerme?' (tr_write/4's q/1)
%% (a question already in its second clause carries its own mark there)
tr_head_join(question, Head, S2, join(comma, Head, S2)) :- S2 = join(_, _, q(_)), !.
tr_head_join(question, Head, S2, join(comma, Head, q(S2))) :- !.
tr_head_join(_, Head, S2, join(comma, Head, S2)).
%% a word a reading at the head can take: an answer, a noun the lesson calls
%% a person, or a name in a question (the clauses above)
tr_head_word(Side, _, A) :- A = w(_, _), tr_answer_word(Side, A), !.
tr_head_word(_, Kind, w(_, upper)) :- Kind == question, !.
tr_head_word(Side, _, N) :-
    N = w(NW, _), atom(NW), tr_is(Side, N, noun),
    tr_np(Side, [N], NP0), NP0 = np(none, none, [], w(_, _), singular), tr_of_class(NP0, person), !.
%% the name of a byline: one the phrase reader takes for a name, or a run of
%% two capitalised words or more -- `di Massimo Lugli Roma - parla
%% piangendo', where `massimo' is the greatest and `lugli' the plural of July
%% to the vocabulary, so no word of it was a name to the phrase reader. What
%% says it is one is where it stands: every word between the head's `of' and
%% the place is capitalised, and the place and its dash close it.
tr_byline_name(Side, NameWs, N) :- tr_np(Side, NameWs, name(N)), !.
tr_byline_name(_, NameWs, N) :-
    NameWs = [_, _|_], \+ ( member(X, NameWs), tr_digit_word(X) ),
    findall(C, ( member(w(Y, _), NameWs), tr_cap(Y, C) ), Cs), atomic_list_concat(Cs, ' ', N).
%% bare nouns joined, each keeping the capital the title gave it -- the
%% capitalised word is a noun of the lesson's, never a name
tr_bare_title(Side, Ws, co(C, T1, T2)) :-
    tr_conjunction_split(Side, Ws, W1, C, W2), !,
    tr_bare_title(Side, W1, T1), tr_bare_title(Side, W2, T2).
tr_bare_title(Side, [w(W, WC)], np(none, none, [], w(W, WC), N)) :-
    tr_is(Side, w(W, lower), noun), ( tr_lexeme(Side, W, _, N) -> true ; N = singular ), !.
%% the one word of a dateline: a capitalised name no lesson knows, or a noun
%% the lesson knows (the head of a piece is lowered when it is known)
tr_dateline_word(Side, W, NP) :-
    W = w(WW, C),
    (   C == upper, tr_np(Side, [W], NP), NP = name(_) -> true
    ;   tr_is(Side, w(WW, lower), noun), tr_np(Side, [w(WW, lower)], NP), NP = np(none, none, [], _, _)
    ), !.
%% a clause that opens on a verb of the first or the second person, after a
%% denial if it has one
tr_opens_on_person([w(N, _)|Ws]) :- atom(N), tr_negation_word(N), !, tr_opens_on_person(Ws).
tr_opens_on_person([w(V, _)|_]) :- atom(V), tr_form(V, _, _, _, P), memberchk(P, [first, second]), !.
%% a clause that names its subject, or one a coordinator opens that does
tr_names_subject(s(_, Su, _, _)) :- Su \= null(_, _), Su \== none, Su \== impersonal, !.
tr_names_subject(join(C, none, S)) :- C = w(_, _), tr_names_subject(S).
%% ... and names it FIRST, after a coordinator if one opens it: `Sarò per
%% sempre grato - aggiunge Marchionne - al team di leadership ... che oggi
%% assume la sua forma definitiva' -- Fiat's fourteenth -- has the rest of
%% one clause after the dashes, `grato al team', and read as a clause of
%% its own it had `forma' for its verb and `la sua' for its subject, `que hoy
%% asume la suya forma definitiva'. A side that opens on a preposition is
%% the clause before's, and the reporting clause goes after the sentence as
%% it always did
%% (a preposition that is an adverb too is the preposition there: `"abbiamo
%% vinto due scudetti - ha detto l'ingegnere - contro la logica dei numeri'
%% -- Ferlaino's tenth -- read `contro' as the adverb before a subject and
%% the side after the dashes was read whole for nothing)
tr_opens_on_subject(foreign, [C|Ws]) :- C = w(_, _), tr_coord(foreign, C), !, tr_opens_on_subject(foreign, Ws).
tr_opens_on_subject(foreign, Ws) :- Ws = [W1|_], \+ tr_is(foreign, W1, preposition), tr_subject_first(Ws).

%% the subject's closing comma of a statement, or of the first clause of
%% clauses joined, taken out
tr_drop_first_scomma(s(A, Su, G, Cs0), s(A, Su, G, Cs)) :- selectchk(scomma, Cs0, Cs), !.
tr_drop_first_scomma(join(C, L0, R), join(C, L, R)) :- tr_drop_first_scomma(L0, L).
%% ... THE REPORTING CLAUSE HAS NO COMMA IN IT, or one more after a quotation,
%% which sets off the speaker's own relative clause: `"Escucho", dijo el
%% presidente de la Generalitat, que inauguró el congreso' -- the president,
%% who inaugurated it. With that comma the clause was read as a statement of
%% its own, saying the president, and English wrote `they said the chairman'.
%% tr_reporting/3 reads the speaker and its relative clause whole
tr_speaker_tail(_, Right) :- \+ memberchk(comma, Right), !.
tr_speaker_tail(Left0, Right) :-
    last(Left0, w(_, QC)), memberchk(QC, [qclose, qboth]),
    append(Mid, [comma|R1], Right), \+ memberchk(comma, Mid), \+ memberchk(comma, R1),
    tr_nrc_start(foreign, R1).
%% ... A VERB OF SAYING AND ITS SPEAKER BEFORE THAT COLON ARE THE REPORTING
%% CLAUSE: `Spiega il popolare Sanza:' is the man explaining, and read as a
%% clause like any other it was the command its words are spelled like,
%% `Explain the popular Sanza' (`Spiega il gatto' is one, and stays one: a
%% speaker is named only by a verb of saying, tr_saying_clause/1). The speaker
%% is named: the verb alone is read as any clause is
tr_colon_left(Side, statement, Left, S1) :-
    tr_saying_first(Left),
    tr_read_reporting(Side, Left, S1), S1 = s(_, Sub, _, _), Sub \= null(_, _), tr_saying_clause(S1), !.
tr_colon_left(Side, Kind, Left, S1) :- tr_read(Side, Kind, Left, S1).
%% (the piece opens on a form of a verb of saying, or on the word before one: the cheap
%% test that keeps the reporting reader off every other heading with a colon)
tr_saying_first([W1|Ws]) :- ( tr_saying_word(W1) ; Ws = [W2|_], tr_saying_word(W2) ), !.
tr_saying_word(w(V, C)) :-
    memberchk(C, [lower, upper]), atom(V),
    (   tr_form(V, L, _, _, _) ; tr_participle_here(foreign, V, L) ), tr_saying_verb(L), !.
%% (a name alone is the side before the colon too, whose words they are:
%% `Tatarella: i trucchi sono vietati')
tr_heading_left(Side, Left, S1) :- tr_as_heading(Left, tr_read(Side, statement, Left, S1)), !.
tr_heading_left(Side, Left, gap([], [obj(NP)])) :- Left = [w(_, upper)|_], tr_np(Side, Left, NP), NP = name(_).
%% (a half that is a question word and nothing else, after a connector perhaps, is the fragment
%% the whole piece would be -- tr_read0/4 reads that for a piece alone, and this is no piece)
tr_question_half(Ws, S) :- tr_read(foreign, question, Ws, S), !.
tr_question_half([w(C, CC)|Ws], join(w(C, CC), none, S)) :- Ws = [_|_], atom(C), tr_connector(foreign, C), !, tr_question_half(Ws, S).
tr_question_half(Ws, gap([], [qnp(Asked, none)])) :-
    fo_question_word(Ws, [], Asked), Asked \== none, Asked \= subject(_), Asked \= pp(_, _).
tr_opens_question([W|Ws]) :-
    (   tr_question_word(W, _) -> true
    ;   W = w(C, _), atom(C), tr_connector(foreign, C), Ws = [W2|_], tr_question_word(W2, _)
    ), !.
%% ... AND THE SIDE AFTER THE COLON GOES ON SAYING WHAT THE SUBJECT BEFORE IT DOES: `Yeltsin
%% mantiene un régimen calificado de "semilaboral" por sus allegados: recibe correo y estudia
%% documentos' is what Yeltsin does, and read as commands they were `receive post and study
%% documents'. After a clause whose subject is a third person the source named, a verb spelled
%% as that person's present is the person's, the command standing down as after a coordinator
%% ('$tr_no_command' third)
tr_read_after_colon(Side, Kind, S1, Right, S2) :-
    Side == foreign, S1 = s(_, Su, _, _), tr_named_third_singular(Su), !,
    tr_global('$tr_no_command', NC0), nb_setval('$tr_no_command', third),
    (   tr_read(Side, Kind, Right, S2) -> nb_setval('$tr_no_command', NC0)
    ;   nb_setval('$tr_no_command', NC0), fail
    ).
%% ... AND THE SIDE AFTER THE COLON MAY BE A CLAUSE OF `THAT' ALONE, A COMMA, A COORDINATOR AND A
%% CLAUSE: `Pensé: que se vayan al carajo, y me volví con los plafones' is what I thought -- that they
%% could go to hell -- and then what I did. The first half is the fragment a clause of `that' is alone
%% (tr_that_fragment/4), which no clause reads, so the side had no reading and the sentence was refused
tr_read_after_colon(foreign, Kind, _, Right, join(comma, F, S3)) :-
    Right = [W|_], tr_that_here(foreign, W),
    append(Left2, [comma, C|Right2], Right), \+ memberchk(comma, Left2), Right2 \== [],
    tr_coord(foreign, C),
    tr_that_fragment(foreign, statement, Left2, F),
    tr_read(foreign, Kind, [C|Right2], S3), !.
tr_read_after_colon(Side, Kind, _, Right, S2) :- tr_read(Side, Kind, Right, S2).
tr_named_third_singular(name(_)).
tr_named_third_singular(np(_, _, _, _, singular)).
tr_named_third_singular(with(NP, _)) :- tr_named_third_singular(NP).
%% a goal run with these words read as a heading, which may have no verb
%% (a goal with the words the piece being read, as tr_as_heading/2 makes them the heading)
tr_as_piece(Words, Goal) :-
    tr_global('$tr_piece', P0), nb_setval('$tr_piece', Words),
    (   call(Goal) -> nb_setval('$tr_piece', P0)
    ;   nb_setval('$tr_piece', P0), fail
    ).
tr_as_heading(Words, Goal) :-
    tr_global('$tr_heading', H0), nb_setval('$tr_heading', Words),
    (   call(Goal) -> nb_setval('$tr_heading', H0)
    ;   nb_setval('$tr_heading', H0), fail
    ).
tr_topic_cleft(Words0, S) :-
    once(( member(w(RW, _), Words0), tr_relative_word(foreign, RW) )),   % no split is worth trying without one
    append(Front0, [Q, w(R, RC)|Rest], Words0), Front0 = [_, _|_], Rest \== [],
    \+ memberchk(comma, Front0),
    tr_relative_word(foreign, R), tr_noun_replacer(foreign, Q),
    tr_subject(foreign, none, Front0, third, _, NP0),
    tr_read(foreign, statement, [Q, w(R, RC)|Rest], S0),
    S0 = s(A, Su, G, Comps0), Su = ell(_, _, _, rel(_, _)), !,
    ( NP0 = with(NP, PPs) -> true ; NP = NP0, PPs = [] ),
    findall(frn(X), member(X, [topic(NP)|PPs]), Fr), append(Fr, Comps0, Comps),
    S = s(A, Su, G, Comps).
%% (after an article any preposition does, `Le condizioni per il prosieguo
%% della legislatura' -- `condizioni' is what `condizionare' says to one
%% person, and `le' the pronoun; with no article only `of', which a command
%% is never followed by: `Mandate per posta' is send it by mail)
tr_noun_heading_start([D, N, P|_]) :-
    D = w(_, _), tr_determiner(foreign, D, _, article),
    N = w(V, VC), VC \== upper, atom(V), tr_plural_noun_word(N),
    P = w(PW, _), atom(PW), tr_is(foreign, P, preposition), !.
tr_noun_heading_start([N, P|_]) :-
    N = w(V, VC), VC \== upper, atom(V), tr_plural_noun_word(N),
    P = w(PW, _), atom(PW), tr_means_of(foreign, P), !.
%% ... AND A SINGULAR NOUN THAT IS A COMMAND TOO, BEFORE A PHRASE OF `to' OR `of': `Intervista alle televisioni danese e
%% svedese' heads the interview WITH them, and read as the command `intervista!' English wrote `Interview to the Danish
%% and Swedish televisions' (the verbless reading asks for no other verb in the piece)
tr_noun_heading_start([N, P|_]) :-
    P = w(PW, _), atom(PW), ( tr_means_of(foreign, P) ; tr_means_to(foreign, PW) ),
    N = w(V, VC), VC \== upper, atom(V), tr_is(foreign, N, noun), tr_lexeme(foreign, V, L, singular), tr_class(foreign, L, noun),
    tr_verb_form_any(V), !.

tr_head_connector_lifted(Side, [W|_], [adv(W)|_]) :-
    W = w(C, _), atom(C), tr_connector(Side, C), \+ tr_coord(Side, W).
%% the clause a connecting word opens, read as a clause of `that' is where the
%% lesson says the word takes the subjunctive (tr_read_joined/5)
tr_read_under(C, Words, S) :-
    tr_global('$tr_in_that', T0),
    ( atom(C), tr_solve(take(C, subjunctive)) -> nb_setval('$tr_in_that', yes) ; true ),
    (   tr_read(foreign, statement, Words, S) -> nb_setval('$tr_in_that', T0)
    ;   nb_setval('$tr_in_that', T0), fail
    ).

%% a comma before a relative word, or before a preposition and one (with its
%% article, `a los que') when it is the only comma of the piece: `Pujol
%% también reivindicó un trato para los abogados, a quienes se les retiene el
%% 20%' lifts `también' and keeps the comma, as `..., que superaron' does --
%% with every comma out the relative clause was restrictive. Only where it is
%% the only one: with others the reading with the commas kept is asked of the
%% whole sentence and fails after reading it once more, and the sentence is
%% read with the commas out, as it was (the Basque report's ninth sentence
%% 3.4 million inferences more of its 19, the festival report's last 0.4
%% million of its 3.5; the same comma kept alone among others, tried again for
%% `Pujol también reivindicó, ayer, un trato mejor para los abogados, a
%% quienes se les retiene el 20%', cost the Valencia report's second 1.7
%% million of its 9 and the festival report's last 0.4 of its 3.5 -- the
%% sentence reads with that comma lost)
tr_comma_relative(Side, Words) :-
    append(_, [comma, w(RW, _)|_], Words), tr_relative_word(Side, RW), !.
tr_comma_relative(Side, Words) :-
    append(Before, [comma, w(PW, _)|More], Words), \+ memberchk(comma, Before), \+ memberchk(comma, More),
    atom(PW), tr_is(Side, w(PW, lower), preposition), tr_relative_next(Side, More), !.
tr_relative_next(Side, [w(RW, _)|_]) :- tr_relative_word(Side, RW), !.
tr_relative_next(Side, [w(AW, _), w(RW, _)|_]) :-
    atom(AW), tr_article_word(Side, AW), tr_relative_word(Side, RW), !.

tr_lifted_close(Words, Advs, s(A, Su, G, Cs0), s(A, Su1, G, [qe|Cs])) :-
    last(Words, w(_, QE)), memberchk(QE, [qclose, qboth]),
    \+ memberchk(qe, Cs0), \+ memberchk(qs, Cs0),
    tr_lifted_inside(Words, Advs),
    tr_strip_close([Su|Cs0], [Su1|Cs]).

%% ... BUT ONLY WHERE AN ADVERB THE LIFT TOOK OUT STOOD INSIDE THE QUOTATION,
%% and one that stood before the mark that opens it is written outside it:
%% `Ieri è stato inoltre approvato il documento su "la fine della vita
%% umana"' lifts `ieri' and `inoltre' from before the mark, and a closing
%% mark moved to the last word written went after `ayer', or was lost where
%% the writer has no place for it (`E infine vi è rischio che la legge possa
%% recare "un vulnus ... della giustizia"' was refused). An adverb is inside
%% when a word with an opening mark stands before it, or when no word of the
%% piece opens one: the quotation opened in a piece before this one
tr_lifted_inside(Words, Advs) :-
    member(adv(W), Advs), W = w(_, _),
    append(Before, [W0|_], Words), W0 == W, !,
    (   ( member(w(_, C), Before), memberchk(C, [qopen, qboth]) ) -> true
    ;   \+ ( member(w(_, C2), Words), memberchk(C2, [qopen, qboth]) )
    ).

%% ... AND AN ADVERB LIFTED FROM THE HEAD LEAVES NO COMMAND WHERE THE VERB
%% AFTER IT IS A PERSON'S FORM TOO, outside an exclamation: `(sólo posee
%% 5.000 licencias)' is what the football of Senegal has, and `posee' is also
%% the command `possess!', which the imperative reader, tried before a third
%% person nobody named, took once the lift had taken `sólo' off the head --
%% `possiedi 5.000 licenze soltanto'. A form that is a command and nothing
%% else stays one, and so does one with its pronoun joined, which no person's
%% form takes: `Solo levántate.' is just stand up (tr_third_person_command/3)
tr_read_after_head_adverb(Side, [W1|_], Advs, Rest, none, S) :-
    Side == foreign, memberchk(adv(W1), Advs), \+ tr_global('$tr_exclaim', yes), !,
    tr_read_no_third_command(Side, statement0, Rest, S).
tr_read_after_head_adverb(Side, _, _, Rest, Asked, S) :- tr_read_statement(Side, Rest, Asked, S).

%% A TIME IN FRONT MAKES WHAT FOLLOWS NO COMMAND, outside an exclamation:
%% `un bel giorno butta in aria una moneta' tells what he did one day, and
%% `butta' is also the command `throw!', which the imperative reader, tried
%% before a third person nobody named, took
tr_time_front(Front, _, yes) :- memberchk(at_time(_), Front), \+ tr_global('$tr_exclaim', yes), !.
tr_time_front(_, F, F).

%% ... AND AN ADVERB AT THE HEAD THAT JOINS ITS SENTENCE TO THE ONE BEFORE
%% STAYS THERE: `Così un bel giorno butta in aria una moneta' is thus, one
%% fine day -- how this follows from what went before -- and put after the
%% verb it came out `lanza al aire una moneda así', the way he throws it.
%% Only an adverb whose FIRST meaning joins clauses (en_conjunctive/1); an
%% adverb at the head keeps 1.6.8's rule otherwise (`Siempre el perro come el
%% pan' is `The dog eats the bread always')
tr_connective_in_front(foreign, [W|_], Advs0, Advs) :-
    W = w(A, _), atom(A), select(adv(W), Advs0, Rest),
    tr_lexeme(foreign, A, L, _), once(tr_solve(mean(L, E))), ( en_conjunctive(E) -> true ; en_head_maybe(E) ), !,
    Advs = [frn(adv(W))|Rest].
tr_connective_in_front(_, _, Advs, Advs).
%% (and one that says how likely the sentence is: `Forse non le era piaciuto' is maybe she had not liked it, and put
%% after the verb it came out `She had not liked it maybe')
en_head_maybe(maybe). en_head_maybe(perhaps).
%% ... and one that says how plain it is: `Naturalmente il conto sale con l'aumentare del reddito' is naturally the
%% bill rises, and put after the verb it came out `The account rises with increasing of the income naturally'
en_head_maybe(naturally). en_head_maybe(obviously).

%% THE LIFTED ADVERBS GO WHERE THEY WOULD HAVE STOOD AFTER THE VERB, which is
%% before a clause the verb takes: `poi disse che sarebbe passato per casa' is
%% THEN he said, and put after the `that' clause the adverb was the clause's,
%% `dijo que habría pasado para casa a tomar una maleta entonces'. ONLY ONE
%% THAT STOOD BEFORE THE WORD OPENING THE CLAUSE: the lift takes its words
%% from anywhere in the piece, and `No podemos pensar que antes de jugar esto
%% ya está ganado' lifted `ya' out of the `que' clause -- put before it, the
%% clause's `already' came out the thinking's, `pensare già che'
%% ... AND THE WORD FOR `ALSO', `EVEN' OR `ONLY' THAT STOOD BEFORE THE VERB IS
%% WRITTEN RIGHT AFTER IT, before what it is said of: `Pujol también
%% reivindicó un trato para los abogados, a quienes se les retiene el 20%'
%% put it last, `rivendicò un trattamento per gli avvocati, a cui si trattiene
%% il 20% anche', where it says something of the clause at the end -- `rivendicò
%% anche un trattamento'. English writes its adverbs last, whatever the order
%% here. One at the head of the piece stays as it was (`También Pujol ...' is
%% also of the subject)
tr_advs_join(Side, Words, Comps0, Advs0, Comps) :-
    Side == foreign, Advs0 = [_|_],
    partition(tr_focus_lifted(Words), Advs0, Focus, Advs), Focus \== [], !,
    tr_advs_join0(Side, Words, Comps0, Advs, Comps1),
    append(Focus, Comps1, Comps).
tr_advs_join(Side, Words, Comps0, Advs, Comps) :- tr_advs_join0(Side, Words, Comps0, Advs, Comps).
tr_advs_join0(Side, Words, Comps0, Advs, Comps) :-
    Advs \== [], append(Pre, [C0|Post], Comps0), tr_clause_comp(C0), !,
    partition(tr_adv_before_clause(Side, Words), Advs, Before, After0),
    tr_advs_into_clause(Side, Words, C0, After0, C, After),
    append([Pre, Before, [C|Post], After], Comps).
tr_advs_join0(_, _, Comps0, Advs, Comps) :- append(Comps0, Advs, Comps).
%% THE ADVERBS AFTER THE WORD FOR `that' ARE THE CLAUSE'S OWN: `Es cierto que las
%% candidatas sólo han tenido 10 minutos' has its `sólo' between the clause's
%% subject and its verb, and lifted with the sentence's own it was written
%% after the clause, `It is certain that the candidates have had 10 minutes
%% only' -- or before it, with a focus adverb, `It is certain only that'. They
%% go among the clause's complements, where the reader that lifted them found
%% them in the clause itself -- those that stand after something of the clause's
%% own, its subject: `Lo que sí reconoció es que ...' has its `sí' after the
%% relative `que' (a noun replacer's, none of a clause of `that') and before the
%% verb, and that one is the sentence's
tr_advs_into_clause(Side, Words, that(s(A, Su, G, Cs)), Advs0, that(s(A, Su, G, Cs1)), After) :-
    partition(tr_adv_in_clause(Side, Words), Advs0, Own, After), Own = [_|_], !,
    append(Own, Cs, Cs1).
%% ... OF THE FIRST OF THE TWO CLAUSES A `that' JOINS, when the adverb stands before the connector: `que esa
%% unidad sólo será posible si los nacionalistas aceptan ...' has its `sólo' in the first, and put with the
%% sentence's own it was written at the end of the second, `... that never have had the Basques only'
tr_advs_into_clause(Side, Words, that(join(w(CW, CC), s(A, Su, G, Cs), S2)), Advs0,
                    that(join(w(CW, CC), s(A, Su, G, Cs1), S2)), After) :-
    atom(CW),
    partition(tr_adv_in_first(Side, Words, CW), Advs0, Own, After), Own = [_|_], !,
    append(Own, Cs, Cs1).
tr_advs_into_clause(_, _, C, Advs, C, Advs).
%% an adverb with words between it and the last word that opens a clause
tr_adv_in_clause(Side, Words, adv(W)) :-
    append(B, [W|_], Words), append(_, [X|Between], B), tr_clause_opener(Side, X),
    Between = [_|_], \+ ( member(Y, Between), tr_clause_opener(Side, Y) ), !.
%% an adverb of the first clause a connector joins: the connector comes after it
tr_adv_in_first(Side, Words, CW, adv(W)) :-
    tr_adv_in_clause(Side, Words, adv(W)),
    once(append(_, [W|Rest], Words)), memberchk(w(CW, _), Rest).
tr_focus_lifted(Words, adv(W)) :-
    W = w(A, _), atom(A), tr_focus_adverb(A),
    Words = [W0|_], W0 \== W,
    %% (never one after the word for `that': it is the clause's own, tr_advs_into_clause/6)
    tr_adv_before_clause(foreign, Words, adv(W)).

tr_adv_before_clause(Side, Words, A) :-
    ( A = adv(W) ; A = frn(adv(W)) ), !,
    append(B, [W|_], Words), \+ ( member(X, B), tr_clause_opener(Side, X) ), !.

%% a word that opens a clause a verb takes: `that', or a question word
tr_clause_opener(Side, X) :- tr_that_here(Side, X), !.
tr_clause_opener(Side, w(Q, _)) :- tr_indirect_word(Side, Q, _), !.

%% A NOUN'S OWN CLAUSE OPENS WITH THE WORD THE LESSON SAYS BEGINS IT and the
%% word for `that': Spanish's `prueba de que ...' (`The word "de" begins the
%% clause.'). Read as a relative after a preposition it was `proof of
%% which', and the clause took the phrase after the comma for its object.
tr_clause_opener(foreign, [w(P, _), W|_]) :-
    tr_lexeme(foreign, P, PL, _), tr_solve(begin(PL, clause)), tr_that_here(foreign, W), !.

tr_clause_comp(that(_)).
tr_clause_comp(wh(_, _)).
tr_clause_comp(rwh(_, _)).
tr_clause_comp(cmtc(_)).
tr_clause_comp(rcl(_, _)).

%% A DENYING ADVERB BEFORE ITS VERB STAYS THERE. `Ni siquiera ha comunicado
%% la decisión' and `Rivaldo y Overmars tampoco estuvieron' deny the verb
%% from in front of it, and the lesson's languages deny a verb with nothing
%% else when the word stands there -- `Neanche ha comunicato la decisione'.
%% Put after the verb it came out `Ha comunicato la decisione ai giocatori
%% neanche', which says nothing. One that stood before a verb travels as
%% frn/1, the front every writer puts first.
tr_denials_in_front(Side, Words, Advs0, Advs) :-
    findall(X, ( member(adv(W), Advs0),
                 (   tr_denying_adverb(Side, W), append(_, [W|After], Words),
                     member(w(V, _), After), tr_verb_form_word(V)
                 ->  X = frn(adv(W))
                 ;   X = adv(W)
                 ) ), Advs).
%% ... AND AN ADVERB AFTER A FRONT'S COMMA, BEFORE THE SUBJECT'S DETERMINER,
%% STAYS THERE TOO: `che, ieri, PROPRIO la sua assenza avrebbe potuto avere un
%% significato' is precisely his absence, and put after the verb it came out
%% `que, ayer, su ausencia habría podido tener un significado precisamente',
%% which says something else. Only there: an adverb at the head of a whole
%% piece keeps 1.6.8's rule and goes after the verb (`Siempre el perro come el
%% pan' is `The dog eats the bread always'), where the four pins of it stand.
tr_head_adverb_in_front(Side, Words, Advs0, Advs) :-
    findall(X, ( member(A, Advs0),
                 (   A = adv(W), Words = [W, D|_], D = w(_, _), tr_determiner(Side, D, _, _)
                 ->  X = frn(adv(W))
                 ;   X = A
                 ) ), Advs).
tr_denying_adverb(Side, w(W, _)) :-
    tr_lexeme(Side, W, L, _), tr_solve(mean(L, E)), memberchk(E, [neither, never, 'not even', 'not either', nowhere]), !.

%% a quotation that opens on the first word and does not close before the
%% last
tr_quote_runs_on([w(_, qopen)|Ws]) :-
    \+ ( append(_, [w(_, QC)|R], Ws), memberchk(QC, [qclose, qboth]), R \== [] ).

%% the length of a front that ends at a comma with a determiner or a name
%% after it, the earliest comma first
%% ... OR AN INFINITIVE, the subject an infinitive names: `con determinazione,
%% impegno e la possibilità offerta dall'università, che spero si
%% concretizzi, diventare astronauta è un obiettivo' -- becoming an astronaut
%% is the aim. Longest first, the relative clause ran over its comma, took
%% `diventare astronauta' for its own, and the verb had nobody for its
%% subject: `que espero se materializa, acaecer astronauta, es un objetivo'
tr_front_comma_ends(Side, Words, K) :-
    append(Front, [comma, N|After], Words), Front \== [], \+ last(Front, comma),
    (   tr_determiner(Side, N, _, _) -> true
    ;   tr_name_word(Side, N) -> true
    ;   After \== [], tr_starts_infinitive(Side, [N])
    ),
    length(Front, K).

%% A SUBJECT WITH ITS `di' PHRASES HAS A WORD MEANING `of' AFTER A PHRASE,
%% which is asked before the subject is looked for: the looking reads every
%% prefix of the words as a subject, and `Contra los tópicos nacionales sólo
%% cabe la paciencia, y el ridículo de los que los utilizan ...' -- the
%% England column's ninth, whose `de' has two phrases joined before it --
%% paid three million inferences to find none
tr_of_after_phrase(Ws) :-
    append(Pre, [P|_], Ws), P = w(_, _), tr_means_of(foreign, P), Pre \== [],
    tr_np(foreign, Pre, _), !.

%% a front that ends on a name APPOSED to a noun: the run of capitalised
%% words at its end, a small word between two of them and a bracket after
%% them its own (`nel vii secolo Isidoro di Siviglia (autorità ...)'), after
%% a word that is neither a preposition nor a determiner -- `secolo', where
%% `en Barcelona' and `en la Tate Gallery' have the front's own words
tr_front_name_apposed(Side, Front0) :-
    reverse(Front0, RF0), findall(X, ( member(X, RF0), X \= w(_, paren) ), RF),
    RF = [LN|_], LN = w(_, upper), tr_name_word(Side, LN),
    tr_name_run_back(RF, Before),
    Before = [B|_], \+ tr_is(Side, B, preposition), \+ tr_determiner(Side, B, _, _),
    %% (nor a participle or an infinitive, whose object the name is: `Per difendere il fratello, accusato di aver
    %% ucciso Sara, riesce a dormire' -- Sara is whom he killed, and the rest names nobody: the one who defends)
    %% (an adjective too: `dei cristiano democratici Casini, Mastella, D'Onofrio e del popolare Sanza' -- `popolare'
    %% is also the infinitive of `popola', and with Sanza apposed `del popolare' was left to read as `del poblar')
    \+ ( B = w(BW, _), atom(BW), ( tr_participle_here(Side, BW, _) ; tr_solve(infinitive_of(BW, _)) ) ), !.

%% the words before the capitalised run that ends a front, read backwards:
%% a small word stays in the run where a capital stands before it
tr_name_run_back([w(_, upper)|Ws], Before) :- !, tr_name_run_back(Ws, Before).
tr_name_run_back([w(_, lower), U|Ws], Before) :- U = w(_, upper), !, tr_name_run_back([U|Ws], Before).
tr_name_run_back(Before, Before).

%% the adjectives in front agree in number with the subject after them,
%% where the subject says one
tr_front_adj_agrees(Side, As, Su) :-
    ( tr_front_number(Su, N) -> true ; N = any ),
    forall(( member(A, As), A = w(W, _), \+ tr_coord(Side, A) ),
           ( N == any ; tr_lexeme(Side, W, L, N), tr_class(Side, L, adjective) )).

tr_front_number(null(_, N), N) :- !.
tr_front_number(Su, N) :- tr_subject_number(Su, N).

%% a count: a number, or a determiner and a number (`un 60%')
tr_count_follows(Side, [W|_]) :- tr_count_word(Side, W), !.
tr_count_follows(Side, [D, W|_]) :- tr_determiner(Side, D, _, _), tr_count_word(Side, W), !.
tr_count_word(Side, W) :- tr_is(Side, W, number), !.
tr_count_word(_, w(W, _)) :- atom(W), sub_atom(W, 0, 1, _, F), char_type(F, digit(_)), !.

%% A PLACE A HEADLINE PUTS IN FRONT: `Monte Livata, ritrovati vivi donna e
%% bimbi scomparsi.' It is no adjunct -- it has no preposition -- and no
%% subject either, and only a comma after it and a NAME in it let it stand
%% there: a name, or a phrase with a name apposed to its noun. It is written
%% back in front, with its comma, as every punctuated front is.
%% ... AND IT TRAVELS AS topic(NP), NOT AS AN OBJECT: read as obj/1 it was
%% the verb's object to every rule that asks, and a name there took the word
%% the lesson puts before a person -- `Monreale, i pm vogliono Cassisa alla
%% sbarra.' came out `A Monreale, los fiscales quieren ...'
%% ... and only at the HEAD of its sentence, where a headline puts one: a
%% clause the sentence was divided into does not open on a topic, and
%% `Salvo la concesión de Rivaldo y Overmars, Serra Ferrer no quiere ...'
%% divided at its first `y' read `Overmars' as one before `Serra Ferrer'
tr_at_piece_head(Words) :- tr_global('$tr_piece', P), is_list(P), append(Words, _, P), !.
tr_topic(name(_)) :- !.
tr_topic(np(_, _, Adjs, _, _)) :- member(w(_, upper), Adjs), !.
tr_topic(np(_, _, _, named(_, _), _)).
%% ... AND TWO OF THEM JOINED: `Usa o Italia, "hip hop" è la lingua del
%% ghetto.' puts two places in front, and the pair was no name to the clause
%% above, so the sentence was refused whole
tr_topic(co(_, A, B)) :- tr_topic(A), tr_topic(B).

%% a front with no comma goes after the clause's own complements -- and
%% before the first comma among them, which is where the clause ended
%% ... but never a list's comma, between two phrases of one preposition:
%% `nel corso cercherò di illustrare una missione ... sullo shuttle, sulla
%% navicella Soyuz e la Iss' went into the list, `en el transbordador en el
%% curso, en la cápsula Soyuz'
tr_front_after(Comps0, Front, Comps) :- tr_front_place(plain, Comps0, Front, Comps).

tr_front_place(_, Comps0, Front, Comps) :-
    append(A, [sep|B], Comps0), \+ tr_list_sep(A, B), !, append(A, Front, AF), append(AF, [sep|B], Comps).
%% ... and before a phrase that carries a relative clause after a comma,
%% which runs to the end of its piece: `Por él suspiró Yehudi Menuhin, que
%% elogió su sonoridad' put `da lui' after the clause, where it read as the
%% clause's own, `che lodò la sua sonorità da lui'
tr_front_place(_, Comps0, Front, Comps) :-
    append(A, [C|B], Comps0), tr_carries_nrc(C), !, append(A, Front, AF), append(AF, [C|B], Comps).
%% ... and, for the clause's own front (`main'), before a clause of `that' the
%% verb takes, which the front is no part of: `Tres veces negó el líder
%% peneuvista que su partido se vaya a "tirar al monte"' is denied three
%% times, and written after the clause `tre volte' read as the clause's own,
%% the way a lifted adverb never is (1.8.6). Not for a front read inside a
%% clause of `that' or a relative clause (`plain'): there the front is the
%% quoted clause's adjunct and stays at its end, as `"anche si dice che il
%% gatto dorme"' has it since 1.8.27
tr_front_place(main, Comps0, Front, Comps) :-
    append(A, [that(S)], Comps0), \+ tr_that_is_relative(A, S), !,
    append(A, Front, AF), append(AF, [that(S)], Comps).
tr_front_place(_, Comps0, Front, Comps) :- append(Comps0, Front, Comps).

%% ... but not before a clause with no subject of its own that follows a
%% predicate adjective: `en las partes altas de las ciudades serán neonazis
%% que destrozan la cabeza a un inmigrante' has a relative clause on the
%% predicate, read as a clause of `that', and the front put between the two
%% hung on the cities, `neonazisti nelle parti alte delle città che spaccano
%% la testa'. It stays where 1.6.8 puts it, after the clause
tr_that_is_relative(A, s(_, null(_, _), _, _)) :- last(A, adj(_)).

tr_list_sep(A, [pp(w(P, _), _)|_]) :- last(A, pp(w(P, _), _)).
%% ... nor the commas of a list a preposition of `between' or `among' opens:
%% `El pasado jueves se firmó un preacuerdo entre los actuales dueños, el
%% grupo japonés Sogo, y el Deutsche Bank' put the time after the first of
%% the three, `tra gli attuali proprietari giovedì passato, il gruppo
%% giapponese Sogo, e il Deutsche Bank'. The phrases after the first stand
%% as objects (the reader does not know they are the preposition's), and the
%% comma before the coordinator is the list's too
tr_list_sep(A, [obj(_)|_]) :- last(A, pp(w(P, _), _)), tr_between_list(P).
tr_list_sep(A, [cnj(_)|_]) :-
    append(_, [pp(w(P, _), _), sep|T], A), tr_between_list(P), forall(member(X, T), ( X = obj(_) ; X = sep )).
%% ... nor a comma between two phrases of the subject or the object, a list's:
%% `Dagli stessi paesi provengono studiosi, operatori, autori di diverse
%% espressioni' put `desde los mismos países' after `estudiosos', where the
%% list's first comma was taken for the end of the clause -- and when the
%% first of them is a word that is an adjective as well (`studiosi'), read as
%% one: `provengono studiosi, operatori, autori'. A list of kinds, with no
%% determiner: `se il prossimo febbraio il senato accademico darà parere
%% positivo, la prima facoltà europea ...' has a phrase with one after its
%% comma, and the comma ends the clause of `se' -- the front went after the
%% whole sentence, `... a preparare degli astronauti el próximo febrero'
tr_list_sep(A, [obj(np(none, none, _, _, _))|_]) :- last(A, X), ( X = obj(_) ; X = adj(_) ), !.
tr_between_list(P) :-
    atom(P), tr_lexeme(foreign, P, L, _), tr_solve(mean(L, E)), memberchk(E, [between, among]), !.

tr_carries_nrc(obj(nrc(_, _, _))).
tr_carries_nrc(pp(_, nrc(_, _, _))).
tr_carries_nrc(by(nrc(_, _, _))).
tr_front_adverb_in(s(A, Su, G, Cs), Adv, s(A, Su, G, [fr(Adv)|Cs])).
tr_front_adverb_in(join(K, S1, S2), Adv, join(K, S, S2)) :- S1 = s(_, _, _, _), tr_front_adverb_in(S1, Adv, S).
%% the words are the piece, or its first part before a semicolon: `Ma so che
%% amava Marisa Rivolta, la sua compagna d'autunno; e aveva pianto' -- the
%% first part is read after the semicolon's division and was no piece, so
%% the reading further down had it, with its commas lost
tr_piece_starts(P, Ws) :- P == Ws, !.
tr_piece_starts(P, Ws) :- append(Ws, [semicolon|_], P).
%% ... AND WHAT FOLLOWS A COORDINATOR AT THE HEAD IS NO COMMAND SPELLED AS A
%% THIRD PERSON, outside an exclamation: `Y sabe lo que quiere: jugar de
%% forma sencilla' is and HE knows what he wants -- the sentence goes on from
%% the one before it, which is about somebody -- and `sabe' is also the
%% command `know!', which the imperative reader, tried before a third person
%% nobody named, took: `E conosci quello che vuole'. Only that command stands
%% down (tr_third_person_command/3): a denied one, one with its pronoun
%% joined and one no person's form spells stay commands, `Y no comas el pan'
tr_read_after_coord(Side, Kind, C, Words, S) :-
    tr_coord(Side, C), \+ tr_global('$tr_exclaim', yes), !,
    tr_read_no_third_command(Side, Kind, Words, S).
tr_read_after_coord(Side, Kind, _, Words, S) :- tr_read(Side, Kind, Words, S).
%% (a reading that has already refused every command keeps that)
tr_read_no_third_command(Side, Kind, Words, S) :-
    tr_global('$tr_no_command', F0),
    ( F0 == yes -> F1 = yes ; F1 = third ), nb_setval('$tr_no_command', F1),
    (   ( Kind == statement0 -> tr_read_statement(Side, Words, none, S) ; tr_read(Side, Kind, Words, S) )
    ->  nb_setval('$tr_no_command', F0)
    ;   nb_setval('$tr_no_command', F0), fail
    ).
tr_sep_last(s(A, Su, G, Cs), s(A, Su, G, Cs1)) :- !, ( last(Cs, sep) -> Cs1 = Cs ; append(Cs, [sep], Cs1) ).
tr_sep_last(join(C, S1, S2), join(C, S1, S3)) :- tr_sep_last(S2, S3).
%% the two sides of a division read, and what joins them
tr_division(Side, Kind, Words0, Left0, Conn0, Right, S) :-
    tr_quote_closed(Left0, Conn0, Left, Conn),
    tr_join_left(Side, Kind, Left, Conn, S1),
    tr_read_joined(Side, Conn, S1, Right, S2),
    (   Conn = both(ck(K), C2)
    ->  tr_comma_after(Words0, C2, Right, C2c), S = join(comma, S1, join(K, none, join(C2c, none, S2)))
    ;   Conn = both(C1, C2) -> tr_comma_after(Words0, C2, Right, C2c), S = join(C1, S1, join(C2c, none, S2))
    ;   tr_mood_connector(Side, Conn, Right, ConnM0), tr_comma_after(Words0, ConnM0, Right, ConnM), S = join(ConnM, S1, S2)
    ).
%% ... AND A COMMA AFTER A COORDINATOR IS THE SOURCE'S TOO: `anda por una
%% montaña nevada pero, sorprendentemente, no se ven ...' -- the insertion
%% after `pero' travels as the second clause's front, fr/1, and the comma
%% before it was the division's and was lost, `ma sorprendentemente,'. The
%% connector keeps it, wc/1, as the one at the head of a sentence does.
tr_comma_after(Words, w(C, CC), Right, wc(w(C, CC))) :-
    append(_, [w(C, CC), comma|R1], Words), tr_clause_words(R1, Right), !.
tr_comma_after(_, Conn, _, Conn).
%% A CONNECTOR BEFORE A SUBJUNCTIVE MAY MEAN SOMETHING ELSE. `vigilare perché
%% codesti presìdi non debordino dalle loro funzioni' is watching SO THAT
%% they do not overstep, and `perché' before an indicative is because: the
%% lesson gives it both (`The conjunction "perché" means "so that".' after
%% its `because'), and the mood of the clause after it says which. The IR
%% reads a subjunctive as the tense it stands for, so the mood is asked here,
%% of the clause's first verb form, and the connector travels as subj/1 until
%% it crosses as `so that'.
tr_mood_connector(foreign, w(C, CC), Right, subj(w(C, CC))) :-
    tr_lexeme(foreign, C, L, _), tr_solve(mean(L, 'so that')),
    \+ tr_meanings_of(L, english, conjunction, ['so that'|_]),
    once(( append(_, T, Right), T = [w(V, _)|_], atom(V), tr_verb_form_word(V) )),
    tr_subjunctive_next(T), !.
tr_mood_connector(_, Conn, _, Conn).
%% the left side of a division: a clause -- or AN ANSWER WITH ITS CONDITION.
%% `Niente, se la maggiore preoccupazione è la stabilità.' answers the
%% question before it, nothing if that is the concern, and its left side is
%% one pronoun with no verb, which no clause reads. One pronoun the lesson
%% says stands alone (`The pronoun "niente" does not precede the verb.'),
%% before a connector that is no coordinator, is read as the verbless
%% phrase it is.
tr_join_left(Side, Kind, Left, _, S1) :- tr_read(Side, Kind, Left, S1), !.
tr_join_left(Side, _, [W], Conn, gap([], [obj(pronoun(W))])) :-
    ( Conn = both(comma, K) -> true ; K = Conn ), K = w(_, _), \+ tr_coord(Side, K),
    W = w(X, _), tr_is(Side, W, pronoun),
    tr_lexeme(Side, X, L, _), tr_solve(neg(precede(L, verb))), !.
%% ... AND A HEADING'S PHRASE BEFORE THE CLAUSE THAT SAYS WHY: `una buona
%% notizia, visto che erano evidenti i profili di incostituzionalità ...'
%% -- a leader's comment, a phrase that names what he calls the decision and
%% then the reason for it, and nothing of it has a verb. Read as a heading
%% is (tr_verbless/3), an article and its noun with what they carry, before
%% a subordinating word: `Niente, se ...' above is the same shape with a
%% pronoun. A coordinator does not make it, `Il pane y el vino.'
tr_join_left(foreign, _, Left, Conn, S1) :-
    Left = [_, _|_],
    ( Conn = both(comma, K) -> true ; K = Conn ), K = w(_, _), \+ tr_coord(foreign, K),
    tr_as_heading(Left, tr_verbless(foreign, Left, S1)),
    S1 = gap([], [obj(NP)|PPs]),
    %% (or a bare noun with an adjective and its intensifier, `Mediazione
    %% particolarmente faticosa se persino Gianni Letta ha riferito ...'; or
    %% the phrase with its relative clause, `Un dato confortante del quale non
    %% ci si può rallegrare perché l'intensità della povertà sta crescendo')
    ( tr_heading_np(NP) ; NP = np(none, none, [int(_, _)|_], w(_, _), _)
    ; NP = rc(H, _, _), tr_heading_np(H) ),
    forall(member(X, PPs), ( X = pp(P, _), tr_means_of(foreign, P) )), !.
%% ... AND A HEADLINE'S PHRASE WITH ITS PARTICIPLE: `Un esodo annunciato con
%% dovizia di cifre, tanto che l'osservatorio prevede un aumento ...' -- the
%% exodus announced with a wealth of figures, so much so that the observatory
%% forecasts more traffic. The participle and its phrases are read as the
%% headline's are, a heading's side (the reader above takes a phrase and its
%% `of' phrases alone), and read as the clause's own `annunciato' had nobody
%% to be said of and the sentence was refused
tr_join_left(foreign, _, Left, Conn, gap([], [obj(rel(NP, L, Comps))])) :-
    Left = [_, _|_],
    ( Conn = both(comma, K) -> true ; K = Conn ), K = w(_, _), \+ tr_coord(foreign, K),
    %% (at the head of the piece, and the participle among its first four words, as a headline's phrase
    %% is short: asked of every side before a connector, `El de Guernica aprueba por unanimidad retirar
    %% la medalla ... así como todos los honores concedidos al anterior jefe del Estado que, aunque
    %% moleste a muchos, ...' tried each of its words, 0.8 million inferences)
    tr_global('$tr_piece', Piece), append(Left, _, Piece),
    once(( between(0, 3, K0), length(Pre, K0), append(Pre, [w(PW, _)|_], Left),
           atom(PW), tr_participle_here(foreign, PW, _) )),
    tr_participle_headline(foreign, Left, NP, L, Comps), tr_heading_np(NP), !.
%% ... AND BEFORE A COMMA AND A COORDINATOR: `Un bloque de una tremenda
%% consistencia, y los azulgranas ... se vieron obligados a un tremendo
%% derroche' -- the team the sentence before built, said again in a phrase,
%% and then the clause that goes on. The comma parts them (tr_comma_and_parted/2
%% stops the two being one plural subject), and the phrase is read as a
%% heading is, an article and its noun with the `of' phrases they carry
%% (Not the right side of a coordination that follows a statement:
%% `... no es un punto de llegada, sino el inicio de una nueva etapa, y
%% concluyó' is one statement and a clause, the second half's `sino el inicio
%% de una nueva etapa' is no fragment of its own.)
tr_join_left(foreign, _, Left, both(comma, K), S1) :-
    Left = [_, _|_], K = w(_, _), tr_coord(foreign, K),
    \+ tr_global('$tr_no_command', yes),
    tr_as_heading(Left, tr_verbless(foreign, Left, S1)),
    S1 = gap([], [obj(NP)|PPs]), tr_heading_np(NP),
    forall(member(X, PPs), ( X = pp(P, _), tr_means_of(foreign, P) )), !.
%% ... AND A COUNT OF TIME AND WHAT IT IS FOR, before the comma and the
%% coordinator: `Due anni al pugile positivo per amfetamine, ma il giudice
%% ammette: non fu doping volontario' -- two years for the boxer, a heading
%% as a whole piece reads (tr_predicated/2: a count of time and a phrase of
%% its own), then the clause that goes on. The clause above takes an article
%% and its noun with `of' phrases; a count of time has none, and read as a
%% division the fragment was a clause with nobody for its subject
tr_join_left(foreign, _, Left, both(comma, K), S1) :-
    Left = [_, _|_], K = w(_, _), tr_coord(foreign, K),
    \+ tr_global('$tr_no_command', yes),
    tr_as_heading(Left, tr_verbless(foreign, Left, S1)),
    S1 = gap([], Back), Back = [at_time(_)|_], tr_predicated(foreign, Back), !.
%% ... AND NOTHING TO OBJECT, BEFORE WHAT IT IS SAID OF: `nulla da
%% eccepire sulla necessità di vigilare perché codesti presìdi non debordino
%% ...' -- such a pronoun and the infinitive it is for, with no verb, read as
%% the whole sentence reads one (tr_verbless0/3)
tr_join_left(Side, _, [W|Ws], Conn, gap([], Cs)) :-
    ( Conn = both(comma, K) -> true ; K = Conn ), K = w(_, _), \+ tr_coord(Side, K),
    Ws \== [], W = w(X, _), tr_is(Side, W, pronoun),
    tr_lexeme(Side, X, L, _), tr_solve(neg(precede(L, verb))),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    (   tr_uncomma([W|Ws], Plain), tr_complements(Side, Plain, Cs0)
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ),
    tr_standing_pronoun(Side, Cs0, Cs), Cs = [obj(pronoun(_)), purpose(_)|_], !.

%% A CLAUSE A COORDINATOR JOINS TO A STATEMENT IS NO COMMAND. `el
%% resultado es una versión estilizada ... y permite a los cantantes
%% concentrarse' goes on saying what the result does, and `permite' is the
%% imperative of `permitir' as well as its third person -- the imperative is
%% the reading a bare verb at the head takes (1.6.10), and it came out `e
%% permetti ai cantanti', you allow. After `y' and a statement the verb
%% shares the statement's subject, so the imperative stands down while the
%% right side is read ('$tr_no_command', which the failures kept per word
%% list are keyed on too); after a command, `Come el pan y bebe el vino',
%% it may be one again.
%% ... AND THE STATEMENT IS THE LAST CLAUSE OF WHAT THE COORDINATOR FOLLOWS,
%% however that was joined: `Al inicio, cuando Gandalf lleva a Frodo en el
%% carro, la pipa del mago aparece y desaparece' -- the pipe appears and
%% disappears. The left side was a clause after a front and a time clause,
%% join/3 and no s/4 of its own, so the right side was read as a command,
%% `e scompari', you disappear
tr_read_joined(Side, Conn, S1, Right, S2) :-
    %% ... AND AFTER A PLAIN COMMA, WHEN THE CLAUSE BEFORE NAMED ITS SUBJECT: `Il
    %% cane dorme, mangia il pane, beve l'acqua' is a series of what the dog
    %% does, and `mangia' read as the command it is also spelled (`eat!')
    %% refused the sentence in English. As after a coordinator, the clause is no
    %% command (a clause before it that was one stays one: `Dormi, mangia')
    (   ( Conn = w(_, _) ; Conn = both(comma, K), K = w(_, _) ; Conn == comma ),
        ( Conn = w(_, _) -> tr_coord(Side, Conn) ; Conn == comma -> true ; tr_coord(Side, K) ),
        tr_last_statement(S1, S1L), S1L = s(_, Su1L, g(_, _, A1, _), _), A1 \== imperative,
        ( Conn == comma -> Su1L \= null(_, _), Su1L \== none, Su1L \== impersonal ; true )
    ->  tr_global('$tr_no_command', F0), nb_setval('$tr_no_command', yes),
        (   tr_read(Side, statement, Right, S20) -> nb_setval('$tr_no_command', F0)
        ;   nb_setval('$tr_no_command', F0), tr_gapped_too(Side, Right, S20)
        ),
        tr_shared_subject(Side, S1L, Right, S20, S2)
    %% ... AND A MAIN CLAUSE AFTER A CLAUSE OF `when' IS ITS SUBJECT'S: `cuando
    %% Frodo se está recuperando en Rivendell, se apoya en una barandilla' --
    %% Frodo leans -- and read with nobody named the `se' was the impersonal
    %% one, `one leans'. Only the `se' of a clause with no object of its own,
    %% after a time clause whose subject is a third person singular: the same
    %% words in Italian either way, and in English the reading
    ;   Conn == comma, S1 = gap(_, Cs1), member(WC1, Cs1), ( WC1 = rwh(when, SW) ; WC1 = wh(when, SW) ),
        SW = s(_, SuW, _, _), tr_shared_person(SuW, third, singular)
    ->  tr_read(Side, statement, Right, S20),
        (   S20 = s(_, impersonal, _, _) -> tr_shared_subject(Side, SW, Right, S20, S2) ; S2 = S20 )
    %% ... AND A CLAUSE AFTER A SUBORDINATING WORD IS NONE EITHER: `apoyará
    %% a Javier Solana si logra el consenso' -- if HE achieves it, and
    %% `logra' is the imperative of `lograr' as well, which came out `se
    %% riesci', if you achieve
    %% (and a word the lesson says takes the subjunctive reads its clause as a
    %% clause of `that' is read, a second person no subjunctive's third:
    %% `Mangio prima che arrivi' is before HE arrives, `antes de que llegue')
    ;   ( Conn = w(_, _) -> K1 = Conn ; Conn = both(comma, K1), K1 = w(_, _) ),
        \+ tr_coord(Side, K1)
    ->  tr_global('$tr_no_command', F0), nb_setval('$tr_no_command', yes),
        tr_global('$tr_in_that', T0),
        ( K1 = w(C1, _), atom(C1), tr_solve(take(C1, subjunctive)) -> nb_setval('$tr_in_that', yes) ; true ),
        (   tr_read(Side, statement, Right, S2) -> nb_setval('$tr_no_command', F0), nb_setval('$tr_in_that', T0)
        ;   nb_setval('$tr_no_command', F0), nb_setval('$tr_in_that', T0), fail
        )
    %% ... AND AFTER A QUOTATION THAT CLOSES ON ITS LAST WORD, A REPORTING
    %% CLAUSE FIRST, as after one whose mark stands alone (the reader of
    %% `endquote' above): `"Paral.lel continuará", se limitó a contestar
    %% Puigbó' is who answered, and read as a statement like any other its `se'
    %% was the impersonal word and Puigbó what one answered
    ;   ( Conn == endquote_plain_comma ; Conn == endquote_name_comma ), tr_read_reporting(Side, Right, S20)
    ->  S2 = S20
    ;   tr_read(Side, statement, Right, S2)
    ).

%% A CLAUSE WITH ITS VERB LEFT OUT, AND ITS PHRASE `ALSO': `La ley da para
%% mucho y la voluntad del pueblo también' -- the will of the people too.
%% The coordinator joins the clause before it to a phrase and the word for
%% `also' or `too' after it, which is the gapped form a semicolon's parts
%% read (tr_semi_item/3) and no clause reads. The word goes in front in
%% every language, where each of them puts it: `y también la voluntad del
%% pueblo', `and also the will of the people'. Only a word the lesson gives
%% the meaning `also' or `too', after phrases and nothing else.
tr_gapped_too(foreign, Right, gap([], [adv(A)|Cs])) :-
    append(Ws, [A], Right), Ws = [W1|_], W1 = w(_, _), A = w(AW, _), atom(AW),
    tr_lexeme(foreign, AW, AL, _), once(( tr_solve(mean(AL, also)) ; tr_solve(mean(AL, too)) )),
    tr_semi_item(foreign, Right, gap([], Cs0)),
    append(Cs, [adv(A)], Cs0), Cs = [obj(_)|_].

%% A CLAUSE JOINED BY A COORDINATOR WITH NOBODY NAMED SHARES THE SUBJECT
%% BEFORE IT where its verb could say either: `quei morti ... mi fanno male
%% al cuore e, soprattutto, sono un problema anche mio' -- the deaths and the
%% camps ARE a problem of mine too, and `sono' is also `I am', which the
%% copula's singular predicate chose. When a word of the second clause is its
%% verb in both readings, the one the first clause's subject gives is taken.
tr_shared_subject(foreign, s(_, Su1, _, _), Right, s(A, null(P2, N2), g(L, T, Asp, Neg), Cs), S2) :-
    tr_shared_person(Su1, third, N1), (P2 \== third ; N2 \== N1),
    atom(L), member(w(W, _), Right), atom(W),
    tr_form(W, L, N2, T, P2), tr_form(W, L, N1, T, third), !,
    S2 = s(A, null(third, N1), g(L, T, Asp, Neg), Cs).
%% ... AND A `se' THERE IS THE SHARED SUBJECT'S OWN: `El encuentro estuvo
%% rodeado de gran discreción y se desarrolló entre las tres y las cinco de
%% la tarde' -- the meeting took place -- and read with nobody named the `se'
%% was the impersonal one, `and one developed'. Only a clause with no object
%% of its own, after a subject of the third person singular, which is the
%% person an impersonal verb is in.
%% (a phrase after a comma, `sep', is an apposition and no object: `e si riferisce al progetto finalizzato per l'elettronica
%% dello stato solido, un tema che riveste un'enorme importanza' -- the example refers to it, and with the topic for its
%% object the `si' stayed the impersonal one, `and one refers')
tr_shared_subject(foreign, s(_, Su1, _, _), _, s(A, impersonal, g(L, T, simple, Neg), Cs), S2) :-
    atom(L), tr_shared_person(Su1, third, singular),
    \+ ( append(Pre, [C|_], Cs), functor(C, F, _), memberchk(F, [obj, that, inf, infx, wh, opron]),
         \+ ( C = obj(_), last(Pre, sep) ) ), !,
    S2 = s(A, null(third, singular), g(reflexive(L), T, simple, Neg), Cs).
tr_shared_subject(_, _, _, S2, S2).

%% the first clause of a statement joined to others, through a join that has
%% nothing before its connector (a coordinator and its clause) as through one
%% that has a clause there
tr_first_statement(S, S) :- S = s(_, _, _, _), !.
tr_first_statement(join(_, none, S2), S) :- !, tr_first_statement(S2, S).
tr_first_statement(join(_, S1, _), S) :- tr_first_statement(S1, S).

%% the last clause of a statement joined to others -- what a coordinator
%% after it follows
tr_last_statement(S, S) :- S = s(_, _, _, _), !.
tr_last_statement(join(_, _, R), S) :- tr_last_statement(R, S).

tr_shared_person(co(_, _, _), third, plural) :- !.
tr_shared_person(null(P, N), P, N) :- !.
tr_shared_person(pronoun(P, N, _), P, N) :- !.
tr_shared_person(Su, third, N) :- tr_phrase_subject(Su), tr_subject_number(Su, N).

%% A QUOTATION THAT CLOSES AT A COMMA LEAVES ITS MARK THERE. `... un mes de
%% Febrero muy apretado", explicó.': the closing mark was on `apretado', a
%% participle the IR carries as a predicate with no case, and it was lost.
%% It goes on the join instead, which writes a mark and a comma.
%% ... AND ON A NAME, WHICH CARRIES ITS MARK: `Ha sido un gran Senegal",
%% dijo ayer ...' -- a word no lesson knows is a name spelled with its mark,
%% so the mark is written with it and the join writes the comma alone. What
%% follows is read as a reporting clause first, as after any closing mark
tr_quote_closed(Left0, comma, Left0, endquote_name_comma) :-
    last(Left0, w(W, upper)), atom(W), sub_atom(W, _, 1, 0, '"'), !.
tr_quote_closed(Left0, comma, Left, endquote_plain_comma) :-
    append(F, [w(W, qclose)], Left0), !, append(F, [w(W, lower)], Left).
tr_quote_closed(Left, Conn, Left, Conn).
%% a word that closes a quotation: its case says so, or a name carries the
%% mark; and a case that opens one
tr_closes_quote(w(_, C)) :- memberchk(C, [qclose, qboth, qcloseu, qbothu]), !.
tr_closes_quote(w(W, upper)) :- atom(W), sub_atom(W, _, 1, 0, '"'), !.
tr_opens_quote(C) :- memberchk(C, [qopen, qboth, qopenu, qbothu]), !.
%% the closing mark of a word's case taken off it and put on the preposition English writes after it (the question of
%% `what' and a preposition, tr_comp_out/7)
tr_what_mark_off(qclose, lower, lower, qclose).
tr_what_mark_off(qcloseu, upper, lower, qclose).
tr_what_mark_off(qboth, qopen, lower, qclose).
tr_what_mark_off(qbothu, qopenu, lower, qclose).
tr_group_after_clitics(Ws) :- tr_group_at(foreign, Ws, _, _), !.
tr_group_after_clitics([w(C, _)|Ws]) :- Ws \== [], atom(C), tr_clitic(none, C), tr_group_after_clitics(Ws).
tr_resumed_subject(s(A, null(third, N), G, Cs0), s(A, NP, G, Cs)) :-
    memberchk(opron(_), Cs0),
    append(Pre, [obj(NP)|Post], Cs0), fo_np_number(NP, N), !,
    append(Pre, [subj_here|Post], Cs).
tr_resumed_subject(S, S).
%% (a main clause that opens on an article opens on its SUBJECT, never on an
%% object set in front and taken up by a pronoun: `e se devono rappresentare
%% l'Europa lo fanno su un foglio' divided before the article, the
%% subordinate clause lost its object, and the atlases did Europe, `si deben
%% representar hacen el Europa'. A clause that opens on a pronoun before its
%% verb -- `lo' is an article too -- is read as it was)
tr_main_object_in_front(foreign, [w(V, _)|R], s(_, null(_, _), _, _)) :-
    atom(V), tr_determiner(foreign, w(V, lower), _, article),
    \+ ( tr_clitic(none, V), tr_group_after_clitics(R) ), !.

%% where a main clause may start after a subordinate clause with no comma
%% between them: at a verb group, a command, its subject's article -- never
%% a contraction, which opens a phrase of a preposition's: `mentre la
%% Francia destina il 2 per cento DEL pil per la ricerca noi siamo ...' put
%% the gross product and the research in the main clause, where `del' is
%% also the partitive article -- or a subject pronoun before a verb group:
%% `... noi siamo solo all'1,4' is we are only at 1.4
%% ... and never at a word that is a preposition too: `a meno che non si
%% liberi entro un anno' is within a year, and `entro', I enter, made `entro
%% un anno' the main clause after the clause of `unless' -- `y a menos que se
%% deja marchar entro un año'
tr_main_start(Side, [w(RW, _)|_]) :- atom(RW), tr_is(Side, w(RW, lower), preposition), !, fail.
tr_main_start(Side, Right) :- tr_group_at(Side, Right, _, _), !.
%% ... and its denial before any of those: `se mai ci sarà una causa NON
%% voglio una lira' is if there is a lawsuit, I do not want a lira. The main
%% clause opens on its denial, and with no start there the division took
%% `non' into the subordinate clause, which then said there would be none
tr_main_start(Side, [w(N, _)|R]) :- atom(N), tr_negation_word(N), R = [_|_], tr_main_start(Side, R), !.
tr_main_start(Side, [w(V, _)|_]) :-
    atom(V), tr_solve(imperative_of(V, _)), \+ tr_is(Side, w(V, lower), preposition), !.   % `di' is say! and of
tr_main_start(Side, [w(V, _)|_]) :-
    atom(V), tr_determiner(Side, w(V, lower), _, article), \+ tr_solve(contraction_of(V, _)), !.
tr_main_start(foreign, [w(P, _)|R]) :-
    atom(P), tr_subject_pronoun(foreign, P, _, _), \+ tr_clitic(none, P),
    tr_group_at(foreign, R, _, _), !.
%% ... or the verb's own pronouns before its group: `se i cellulari non smettono di trillare neppure in
%% spiaggia si sono placati almeno i clacson dei turisti' -- the horns have calmed down, and with no
%% start at `si' the piece had no division and was refused
tr_main_start(foreign, [w(C, _)|R]) :-
    atom(C), tr_clitic(none, C), R = [_|_], tr_group_after_clitics(R), !.
%% (also the side of a division before its connector, read by tr_join_left/5
%% and never through tr_read/4, whose failures are kept per word list: `Un
%% esodo annunciato con dovizia di cifre, tanto che l'osservatorio prevede
%% ...' is the headline and then what follows from it)
tr_participle_headline(Side, Words0, NP, L, Comps) :-
    \+ memberchk(comma, Words0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    append(Core, [w(P, PC)|Rest], Words0), Core \== [], Rest \== [],
    tr_participle_here(Side, P, L), tr_participle_number(P, PN),
    tr_object_phrase(Side, Core, NP0), NP0 \= rel(_, _, _), tr_np_in_number(Side, NP0, PN, NP),
    tr_complements(Side, Rest, Comps0), Comps0 \== [], tr_adjuncts(Comps0),
    tr_rel_agreement(Side, P, NP, Comps0, Comps1), tr_rel_case(PC, Comps1, Comps), !.

%% a phrase in a number its noun can be read in: `auto' is `car' and `cars'
tr_np_in_number(Side, np(D, M, As, w(NW, NC), N0), N, np(D, M, As, w(NW, NC), N)) :- !,
    ( N0 == N -> true ; tr_lexeme(Side, NW, _, N) ).
tr_np_in_number(_, NP, N, NP) :- fo_np_number(NP, N).
tr_subject_pps([pp(P, NP)|Ps], [pp(P, NP)|Of], Rest) :- tr_means_of(foreign, P), !, tr_subject_pps(Ps, Of, Rest).
tr_subject_pps(Ps, [], Ps).
%% (THE COMMENT AT THE END OF ITS CLAUSE, tr_read0/4's: a phrase after its verb, with nobody named, is its subject,
%% the gap its object: `..., como indicaban
%% los anónimos recibidos por los patronatos de turismo' is as the anonymous letters indicated -- what they
%% indicated is the clause before the comma -- and read with nobody named they were what somebody indicated, `as
%% they indicated the anonymous letters'. A phrase in the verb's number)
tr_cmt_subject_fix(s(A, null(third, N), G, [obj(X)|Cs]), s(A, X, G, [subj_here|Cs])) :-
    ( X = rel(H, _, _) -> tr_subject_number(H, N) ; tr_subject_number(X, N) ), !.
tr_cmt_subject_fix(S, S).
tr_front_skip_adverbs([adv(_)|Cs], Rest) :- !, tr_front_skip_adverbs(Cs, Rest).
tr_front_skip_adverbs(Cs, Cs).
%% what a participle between commas takes, in a front: its infinitive, a second participle and their objects
tr_front_aside_comps([]).
tr_front_aside_comps([X|Xs]) :-
    ( X = obj(_) ; X = infx(_, _, _) ; X = inf(_) ; X = nprep(_) ; X = cnj(_) ; X = pred(_) ; X == sep ; tr_adjunct(X) ), !,
    tr_front_aside_comps(Xs).
tr_front_adjuncts(Front, Cs) :-
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    (   tr_complements(foreign, Front, Cs), Cs \== [], forall(member(X, Cs), tr_adjunct(X))
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).
%% A NAME ALONE: `The Washington Post.' heads an extract with the paper it
%% came from, and no word of it is the lesson's, which the reading below
%% asks for. Two capitalised words at least, none the lesson knows: one such
%% word alone is a verb with its pronouns joined on as often as it is a
%% name (`¡Lárgate!'). It goes out as the source spelled it.
tr_verbless(Side, Words0, gap([], [obj(name(N))])) :-
    tr_global('$tr_piece', Piece), Piece == Words0,
    (   Words0 = [_, _|_], forall(member(W, Words0), tr_name_word(Side, W))
    %% ... OR A NAME OF SEVERAL WORDS THE LESSON STATES, which tr_stated_names/3 has joined into one: `Bianca nera.' is
    %% the paper's column of crime news (`"Bianca nera" is a name.'), and as one word the heading had no reading --
    %% read as the words it is made of, it is a bare noun and an adjective, `Big house.', which stays refused. Only a
    %% name the lesson states: `Cuida de Tom.' joins as a name of two capitals and a particle, and is a command
    ;   Words0 = [w(J, upper)], atom(J), sub_atom(J, _, 1, _, ' '), tr_downcase_units(J, K), tr_solve(name(K))
    ),
    tr_np(Side, Words0, name(N)), !.
%% A PARTICIPLE STANDING ALONE IN A CLAUSE WITH NO VERB AGREES WITH THE FORM
%% THE SOURCE GAVE IT: `purché praticata con rigorosi controlli' is the
%% therapy, provided it is practised, and with no subject in the clause the
%% writer's gender was whatever the clause before it left -- `siempre que
%% practicado'. The form's own gender and number travel as agr/1 and agrn/1
%% beside it, the reduced relative's own two (1.6.21), and only when they
%% are not the default.
tr_verbless(Side, Words0, gap(Front, Back)) :-
    tr_verbless0(Side, Words0, gap(Front0, Back0)),
    tr_gap_agreement(Side, Words0, Front0, Front),
    tr_gap_agreement(Side, Words0, Back0, Back1),
    tr_pred_governed(Side, Back1, Back).
%% ... AND THE PHRASE A PARTICIPLE STANDING ALONE GOVERNS IS MARKED, as a clause's verb's is (tr_governed/3): `Cifre
%% impressionanti, nate da un'indagine lunga' are born of one, Spanish's `nacidas de' (`"nasce" takes "da" before the
%% phrase.'), where the lesson's `from' wrote `desde'
tr_pred_governed(foreign, [pred(L), pp(w(PW, PC), NP)|Cs], [pred(L), pp(w(PW, PC), gov(L, NP))|Cs]) :-
    atom(L), atom(PW), NP \= adv(_), NP \= gov(_, _), tr_solve(take_before(L, PW, phrase)), !.
tr_pred_governed(_, Cs, Cs).
tr_gap_agreement(foreign, Words, Cs0, Cs) :-
    memberchk(pred(L), Cs0), member(w(P, _), Words), atom(P), tr_participle_here(foreign, P, L), !,
    ( tr_holds(feminine(P)) -> A1 = [agr(feminine)] ; A1 = [] ),
    ( tr_participle_number(P, plural) -> A2 = [agrn(plural)] ; A2 = [] ),
    append([Cs0, A1, A2], Cs).
%% ... and an adjective the same: `Così bella.' is a girl, `tan bella'
tr_gap_agreement(foreign, _, Cs0, Cs) :-
    member(adj(As), Cs0), member(X, As), ( X = w(P, _) -> true ; X = int(_, w(P, _)) ), atom(P), !,
    ( tr_holds(feminine(P)) -> A1 = [agr(feminine)] ; A1 = [] ),
    ( tr_lexeme(foreign, P, _, plural) -> A2 = [agrn(plural)] ; A2 = [] ),
    append([Cs0, A1, A2], Cs).
tr_gap_agreement(_, _, Cs, Cs).
%% a degree adverb before a participle said of nobody is the participle's,
%% written before it (gadv/1): `Così amata.', so loved
tr_degree_pred(foreign, [adv(w(D, DC)), pred(L)], [gadv(w(D, DC)), pred(L)]) :- atom(D), tr_degree_adverb(D), !.
tr_degree_pred(_, Cs, Cs).
%% THE AGENT BEFORE ITS PARTICIPLE, WITH NO PHRASE: `da me vista troppo tardi' is seen by me too late. The
%% participle and what follows it are the fragment a headline is (tr_participle_gap/2), and the agent is its by/1,
%% which every writer puts after it as a reduced relative's (tr_read0/4 asks this first for such a piece)
%% (the participle by its form, which may be a noun too: `vista' is also the view)
tr_verbless0(foreign, [B, A1, w(P, _)|Rest], gap([], [pred(L), by(Agent)|Cs])) :-
    B = w(_, _), tr_means_by(foreign, B), tr_is(foreign, B, preposition),
    tr_lone_agent(A1, Agent), atom(P), tr_participle_here(foreign, P, L),
    ( Rest == [] -> Cs = [] ; tr_complements(foreign, Rest, Cs) ), !.
%% A PHRASE WITH A SERIES OF RELATIVE CLAUSES, a comma between them: `la gente che
%% mi stringe la mano ogni giorno, che mi fa coraggio, che mi dimostra il suo
%% affetto' -- the people who do the three. Divided at its first comma, the
%% phrase was the front and the rest a clause of `that' with nobody named, which
%% English refused, and the third relative clause hung on the courage. The
%% phrase reads whole (tr_np/3's series, nrc/3 on nrc/3), as the heading it is
tr_verbless0(foreign, Words0, gap([], [obj(NP)])) :-
    Words0 = [_, _|_],
    append(F, [comma, w(R, _)|_], Words0), F = [_|_], atom(R), tr_relative_word(foreign, R),
    member(w(R0, _), F), atom(R0), tr_relative_word(foreign, R0),
    (   tr_global('$tr_piece', Piece), Piece == Words0
    ;   tr_global('$tr_heading', H), H == Words0
    ),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Words0, [obj(NP)]), NP = nrc(nrc(_, _, _), _, _), !.
%% ... AND A PHRASE WITH ONE RELATIVE CLAUSE AFTER ITS COMMA: `il crescente conformismo sociale, che obbliga i figli e i
%% genitori a comprare ...' -- the conformism, which obliges them, the second thing a colon's heading names. Divided
%% at the comma, the clause was one of `that' with nobody named, which English refused. Only where nothing before the
%% comma is a relative word: the series above has one there. A phrase before the comma, which opens on a determiner
%% and holds no other comma, and a verb in the clause (asked of every piece with a comma and a relative word after
%% it, the reading cost `Ma come è accaduto, si dirà, che tutte le rappresentazioni ...' 0.6 million inferences, and
%% `Mio dio, che tristezza!' twice what it costs)
tr_verbless0(foreign, Words0, gap([], [obj(NP)])) :-
    %% (or on a name, or on a noun of several words: `Todo lo contrario de Rebeca, que augura:' is quite the opposite of
    %% Rebeca, who predicts it, and `Rebeca, que augura:' her alone)
    Words0 = [D0, _|_],
    %% (or on a count: `Otto anni e sei mesi per il pentito Maurizio Abbatino, che con le sue confessioni ha
    %% consentito di stabilire ...' -- eight years for the informer, who allowed it; the clause was one of `that')
    (   tr_determiner(foreign, D0, _, _) -> true ; tr_name_word(foreign, D0) -> true ; tr_count_word(foreign, D0) -> true
    ;   D0 = w(J0, _), atom(J0), sub_atom(J0, _, 1, _, ' '), tr_is(foreign, D0, noun)
    ),
    append(F, [comma, w(R, _)|RC], Words0), F = [_|_], atom(R), tr_relative_word(foreign, R),
    \+ memberchk(comma, F),
    \+ ( member(w(R0, _), F), atom(R0), tr_relative_word(foreign, R0) ),
    once(( member(w(V0, _), RC), atom(V0), tr_verb_form_any(V0) )),
    (   tr_global('$tr_piece', Piece), Piece == Words0
    ;   tr_global('$tr_heading', H), H == Words0
    ),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Words0, Cs0),
    (   Cs0 = [obj(NP)], NP = nrc(_, _, _) -> true
    ;   ( Cs0 = [obj(NP0)|PPs] -> true ; Cs0 = [at_time(NP0)|PPs] ),     % (a count of time is read as one: `Otto anni per ...')
        PPs = [_|_], forall(member(X, PPs), X = pp(_, _)), last(PPs, pp(_, nrc(_, _, _))),
        NP = with(NP0, PPs)
    ), !.
%% ... AND A HEADING WITH ITS PURPOSE, THE CLAUSE ON ITS LAST PHRASE: `Una interrogazione parlamentare per denunciare
%% il cinismo della trasmissione "generale per una sera", che esalta la cultura della guerra' -- the programme, which
%% exalts it. Divided at the comma, the clause was one of `that' with nobody named, which English refused. The same
%% shape as above, the phrase's complements a purpose and its object
tr_verbless0(foreign, Words0, gap([], Cs0)) :-
    Words0 = [D0, _|_], tr_determiner(foreign, D0, _, _),
    append(F, [comma, w(R, _)|RC], Words0), F = [_|_], atom(R), tr_relative_word(foreign, R),
    \+ memberchk(comma, F),
    once(( member(w(PW, _), F), atom(PW), tr_purpose_word(PW) )),
    \+ ( member(w(R0, _), F), atom(R0), tr_relative_word(foreign, R0) ),
    once(( member(w(V0, _), RC), atom(V0), tr_verb_form_any(V0) )),
    (   tr_global('$tr_piece', Piece), Piece == Words0
    ;   tr_global('$tr_heading', H), H == Words0
    ),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Words0, Cs0),
    Cs0 = [obj(_)|_], memberchk(purpose(_), Cs0), last(Cs0, pp(_, nrc(_, _, _))), !.
tr_verbless0(Side, Words0, gap(Front, Back)) :-
    Words0 \== [],
    %% and one word of it at least is the lesson's: `¡Lárgate!' is a verb
    %% with its pronoun joined on, which no lesson here can say, and read as
    %% no verb at all it passed through untranslated as a name
    once(( member(w(KW, _), Words0), tr_known_word(Side, KW) )),
    %% ... where a word that could start one is a noun, an adjective or a
    %% number as well: `a meno 5 gradi' -- `gradi' is also what `gradire'
    %% says to one person, and that one word shut the reading out
    tr_uncomma(Words0, Plain),
    %% -- a verb after a relative word is its clause's: `dare all'Italia un
    %% governo ..., ma anche molto attento verso i soggetti CHE VIVONO una
    %% vita disagiata' says what a project is, and the relative clause's verb
    %% shut the reading out
    %% -- and so is one after `where' or `when', the relative clause a
    %% question word opens: `quello della statale di Milano DOVE iscriversi
    %% COSTAVA per i più ricchi oltre due milioni'
    \+ ( append(Pre, [W1|R1], Plain),
         \+ ( member(w(RW, _), Pre), atom(RW),
              ( tr_relative_word(Side, RW) -> true ; tr_indirect_word(Side, RW, Q), memberchk(Q, [where, when]) ) ),
         tr_group_at(Side, [W1|R1], _, _), \+ tr_also_nominal(Side, W1),
         %% -- nor a capital inside the piece, which is a name's (the head was
         %% lowered where the lesson knows it): `croce in Usa' -- `usa' is
         %% what `usare' says of one person, and it shut the reading out
         W1 \= w(_, upper),
         %% -- nor one that is a determiner before its noun: `Toda una
         %% proeza' -- `una' is also what `unir' says in the subjunctive
         \+ tr_heads_phrase(Side, [W1|R1]),
         %% -- nor a preposition: `tanto por ese medio siglo como por la
         %% sensibilidad para con su entorno social' -- `como' is also I eat
         %% and `para' it stops, and each shut the reading out
         \+ tr_is(Side, W1, preposition) ),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    %% -- the commas AFTER the first kept, where they part a list of what the
    %% sentence names: `Un Segunda B, un campo en mal estado, la presión de
    %% jugárselo todo a partido único y la motivación de unos y otros'
    %% (a comma that closes an aside is not one: `un'idea che Vittori,
    %% disposto a ..., non esita a definire coraggiosa: "...' was divided
    %% there, and its relative clause read without its verb)
    (   append(F0, [comma|B0], Words0), \+ last(F0, w(_, aside)),
        \+ ( append(F00, [comma|_], F0), \+ last(F00, w(_, aside)) ), F0 \== [], B0 \== []
    ->  tr_uncomma(F0, F),
        tr_complements(Side, F, Front),
        ( tr_complements(Side, B0, Back) -> true ; tr_uncomma(B0, B), tr_complements(Side, B, Back) )
    %% ... and a WHOLE sentence with no verb in it: an exclamation, or a
    %% news item's line that says something of what it names -- a phrase and
    %% an adjunct that is no `di' phrase of it, `Centotrentamila in partenza
    %% da Milano.' A phrase alone is still refused, `El pan del perro.':
    %% nothing is said of it --
    %% EXCEPT A HEADING, AN ARTICLE AND ITS NOUN: `Il futuro.' ends one part
    %% of an interview and opens the next, and a paper's heading says nothing
    %% of what it names by being one. `The house.' reads with it, which the
    %% refusals had pinned.
    %% ... WITH ITS ADJECTIVES AND ITS `DE' PHRASES: `El voto de los
    %% descontentos.' heads the second half of a report on an election, and
    %% it is `El pan del perro.' in shape, which the refusals had pinned too.
    %% A heading is a phrase that names, and nothing tells it from any other
    %% phrase standing alone -- so what stays refused is a phrase with no
    %% article, `Pan del perro.', which names nothing in particular.
    ;   (   tr_global('$tr_piece', Piece), Piece == Words0
        ;   tr_global('$tr_heading', H), H == Words0
        ),
        Front = [], tr_uncomma(Words0, W), tr_complements(Side, W, Back00),
        tr_standing_pronoun(Side, Back00, Back0), tr_degree_pred(Side, Back0, Back),
        (   tr_global('$tr_exclaim', yes) -> true
        ;   tr_global('$tr_heading', H2), H2 == Words0 -> true
        ;   tr_predicated(Side, Back) -> true
        %% ... AND NOTHING TO OBJECT: `Nulla da eccepire.' -- a pronoun that
        %% stands alone and the infinitive it is for, which says what there
        %% is none of (Spanish's own `que objetar' is no form a lesson states,
        %% and the purpose word writes `para objetar')
        ;   Back = [obj(pronoun(_)), purpose(_)|_]
        ;   Back = [obj(NP0)|PPs], tr_heading_np(NP0),
            forall(member(X, PPs), ( X = pp(P, _), tr_means_of(Side, P) ))
        %% ... AND A NAME WITH ITS PHRASE OF `of': `Wargames di rai 1', the second half of a headline, names the series
        %% and whose it is (a name alone stays refused, as a bare phrase does)
        ;   Back = [obj(name(_)), pp(P1, _)|PPs1], tr_means_of(Side, P1),
            forall(member(X, PPs1), ( X = pp(P, _), tr_means_of(Side, P) ))
        %% ... AND WHO A THING IS FOR, AND THE THING: `A voi il calcolo del
        %% numero di cene al ristorante ...' -- over to you the reckoning, a
        %% line that hands the reader something to do. A phrase of a
        %% preposition first, its object a person or a pronoun, then a phrase
        %% with its article; `Al cane il pane.' names no one and stays refused
        ;   Back = [pp(_, PX), obj(NP0)|_],
            ( PX = pronoun(_) ; PX = name(_) ; PX = np(_, _, _, PW, _), tr_person_word(PW) ),
            ( NP0 = with(NP1, _) -> true ; NP1 = NP0 ), tr_heading_np(NP1)
        %% ... AND A SECTION'S NAME, ONE NOUN ALONE: `Lettere.' heads a
        %% paper's letters page, and a bare noun of one word names the section
        %% it opens. Two words with no article stay refused, `Big house.'
        ;   Words0 = [_], Back = [obj(np(none, none, [], w(_, _), _))]
        %% ... AND A BARE NOUN OF SOMEBODY NAMED: `Prudencia de Matutes.'
        %% heads the half of a report that is the minister's, and what it is
        %% of is someone named -- which is what `Pan del perro.' lacks, and
        %% that one stays refused
        ;   Back = [obj(np(none, none, _, w(_, _), _)), pp(P, name(_))], tr_means_of(Side, P)
        %% ... AND A PHRASE AND THE ONE THAT SAYS WHICH: `Il caso più
        %% eclatante quello della statale di Milano dove iscriversi costava
        %% per i più ricchi oltre due milioni' is the most striking case,
        %% that of Milan's state university, where enrolling cost the richest
        %% more than two million -- the copula left out between the two, as a
        %% headline leaves it out, and each writer puts them back side by side
        ;   Back = [obj(np(det(_, _, _), _, _, _, _)), obj(ell(_, _, _, _))|_]
        %% ... AND A LINE OF ADJUNCTS ALONE: `in alcuni casi addirittura
        %% dentro il tetto' goes on from the sentence before it -- in some
        %% cases even within the ceiling -- and says where with no verb of
        %% its own. Two adjuncts at least, a preposition's phrase first, so a
        %% phrase alone and a word alone stay refused
        ;   Back = [pp(_, _), _|_], forall(member(X, Back), tr_adjunct(X))
        %% ... AND AN ADVERB BEFORE IT, OR BEFORE A PHRASE THAT SAYS SOMETHING: `In particolare al Nord.' -- in
        %% particular in the North, after the sentence that said what; `in media 230 mila euro per mantenerlo fino a 24
        %% anni' -- on average that much to keep him, the headline of a report on what a child costs. The adverb leads a
        %% phrase of a preposition, or a phrase with what says something of it (tr_predicated/2); an adverb and a phrase
        %% alone stay refused
        ;   Back = [adv(_)|Back1], Back1 = [pp(_, _)|Adj], forall(member(X, Adj), tr_adjunct(X))
        ;   Back = [adv(_)|Back1], Back1 = [obj(_)|_], tr_predicated(Side, Back1)
        %% ... AND A PERFECT INFINITIVE AFTER A PREPOSITION: `Cioè dopo aver
        %% mandato in onda l'ultimo "punto di svolta".' -- after having
        %% broadcast it, what the sentence before it said would be
        ;   ( Back = [pinf(_, PL), PC|_] ; Back = [cnj(_), pinf(_, PL), PC|_] ),
            atom(PL), tr_solve(auxiliary(PL)), ( PC = abs(_, _) ; PC = pred(_) )
        %% ... AND AN ADJECTIVE OR A PARTICIPLE WITH ITS INTENSIFIER: `"così
        %% bella. Così vivace. Così amata.' -- so beautiful, so lively, so
        %% loved, a mother's lines about her daughter, each with its copula and
        %% its subject left out. The intensifier is what says something of
        %% somebody; a bare adjective alone stays refused
        ;   Back = [adj([int(_, _)])]
        ;   Back = [gadv(_), pred(_)]
        %% ... AND A NAME WITH ITS ADJECTIVE: `"povera Margherita.' names
        %% somebody in particular, as a heading's article does
        ;   Back = [obj(np(none, none, [_|_], named(_, _), _))]
        %% ... AND A BARE NOUN WITH AN ADJECTIVE AND ITS INTENSIFIER: `Mediazione
        %% particolarmente faticosa' says something of the mediation, as `Così
        %% bella' does of the girl. `Big house.' has none and stays refused
        ;   Back = [obj(np(none, none, [int(_, _)|_], w(_, _), _))]
        %% ... AND A BARE NOUN WITH A NAME AFTER IT: `Colloquio Berlusconi -
        %% D'Alema.' heads a report on two men's talk, `Presidente Ciampi.' --
        %% whose it is is said, as an article would say which
        ;   Back = [obj(np(none, none, As, w(_, _), singular))], member(w(_, upper), As)
        %% ... AND AN ADJECTIVE IN FRONT OF A PHRASE THAT HAS ITS ARTICLE:
        %% `Incerto il futuro di Funari.' -- uncertain the future of
        %% Funari, the copula left out (tr_read0/4 says it)
        %% (and the adjuncts after the `of' phrases, which are the clause's:
        %% `Disastrosa la situazione nel Mezzogiorno', tr_subject_pps/3)
        ;   Words0 = [w(AW, _)|_], Back = [oc(np(det(_, _, _), _, _, _, _), [w(AW, _)])|OPPs],
            forall(member(X, OPPs), ( X = pp(P, _), tr_means_of(Side, P) ; tr_adjunct(X) ; X = rwh(_, _) ))
        %% ... AND AN ADJECTIVE WITH ADJUNCTS AFTER IT: `Migliore al Nord dove
        %% resta nell'indigenza un nucleo ogni venti' -- better in the north,
        %% where one household in twenty remains in destitution, the copula
        %% and its subject left out. The first adjunct a preposition's phrase,
        %% so an adjective with a bare adverb stays refused
        ;   Back = [adj(_), pp(_, _)|Adj], forall(member(X, Adj), ( tr_adjunct(X) ; X = rwh(_, _) ))
        %% ... AND AN ADJECTIVE WITH A PERFECT INFINITIVE AFTER IT: `Colpevole di
        %% esser risultato positivo al controllo antidoping ...' -- guilty of
        %% having tested positive, the headline of a report on a verdict, the
        %% copula and its subject left out as above. The infinitive is the
        %% preposition's (tr_complements0/4), and what follows it is its own
        ;   Back = [adj(_), pinf(_, perf(_, _))|Adj], tr_perf_tail(Adj)
        %% ... AND A DAY AND A PHRASE THAT NAMES, THE VERB LEFT OUT: `Martedì
        %% tutti attorno al tavolo.', `Martedì il vertice.' -- a headline says when
        %% and what, as `Incerto il futuro' says how and what. The day is an
        %% adjunct and the rest is a heading's phrase (an article and its noun) or
        %% all of them with where
        ;   Back = [T|Rest], Rest \== [], T = at_time(_),
            (   Rest = [obj(NP0)|PPs], tr_heading_np(NP0),
                forall(member(X, PPs), ( X = pp(P, _), tr_means_of(Side, P) ; tr_adjunct(X) ))
            ;   Rest = [opron(w(Pn, _))|Adj], Adj = [_|_], atom(Pn), tr_all_word(Side, Pn),
                forall(member(X, Adj), tr_adjunct(X))
            )
        %% ... AND AN EXCLAMATION'S `what' WITH NO `!': `Menudo inicio.', what
        %% a start -- the word the lesson calls exclamative is what says
        %% something of it (tr_complements0/4)
        ;   Back = [obj(what_np(_))]
        %% ... AND ONE ADVERB ALONE: `Seguro.' answers the sentence before it,
        %% sure -- `seguro' is also the noun insurance, which the lesson does
        %% not give it here. One word: two adverbs with nothing else stay
        %% refused
        ;   Words0 = [_], Back = [adv(_)]
        %% ... AND A COORDINATOR AND AN ADVERB, a lead-in: `O quasi: perché il
        %% timore ... ce l'ha' -- or almost, before the colon that says why;
        %% `E infatti:', `Ma anche:'. Before a colon only: `Ma non le pare
        %% che ...?' is a clause whose first two words are no lead-in
        ;   Words0 = [_, _], Back = [cnj(_), adv(_)], tr_global('$tr_heading', H3), H3 == Words0
        )
    ), Back \== [], !.
%% A NAME, THE NOUN IT IS AND WHAT IS ADDED, WITH NO COMMA BETWEEN THEM: `Rosi
%% vittima quindi' -- Rosi, a victim therefore, a headline's line that says
%% what the man is and leaves the copula out. With the comma it is read above, a
%% heading and what is said of it; without one the name and the bare noun
%% were a phrase nobody could say, and the sentence was refused. The noun has
%% no article (`Il pugile vittima' is a phrase already), and something stands
%% after it, an adverb or a phrase of its own that is no `of' phrase
tr_verbless0(foreign, Words0, gap([obj(name(N))], Back)) :-
    Words0 = [w(N, upper), w(V, lower), _|_], atom(V), \+ memberchk(comma, Words0),
    tr_name_word(foreign, w(N, upper)), tr_is(foreign, w(V, lower), noun),
    Words0 = [_|Rest],
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Rest, Back),
    Back = [obj(np(none, none, [], w(_, _), _)), M|More], tr_adjunct(M), \+ M = pp(_, _),
    forall(member(X, More), tr_adjunct(X)), !.
%% A NAME AND AN ADJECTIVE, THE COPULA LEFT OUT: `Signori ottimista, Zeman
%% velenoso' -- Signori optimistic, Zeman poisonous, a headline's line that
%% says how a man is. One capitalised word the lesson does not know, or says
%% is a name, and an adjective after it, with no comma (the name and a comma
%% are the heading `Zeman: ...'): the name and its adjective, which every
%% writer puts down in the order the source gave
tr_verbless0(foreign, Words0, gap([], [obj(name(N)), adj([w(A, lower)])])) :-
    Words0 = [w(N, upper), w(A, lower)], atom(A),
    tr_name_word(foreign, w(N, upper)), tr_is(foreign, w(A, lower), adjective),
    \+ tr_determiner(foreign, w(A, lower), _, _), !.
%% ... and the phrase is one the lesson knows: a capitalised word at the head
%% that no lesson knows is not taken for a name here, because a verb with
%% its pronouns joined on looks the same -- `Quédate ahí.', `Besa a Tomás.'
%% came out `Quédate here.' and `Besa to Tomás.'
%% ... or its purpose: `tasse più care per studiare meglio', dearer fees to
%% study better
tr_predicated(Side, [obj(NP)|Cs]) :-
    NP \= name(_), member(C, Cs), ( C = adv(_) ; C = pp(P, _), \+ tr_means_of(Side, P) ; C = purpose(_) ; C = npurpose(_) ), !.
%% ... AND A COUNT OF TIME IS THE PHRASE THAT NAMES, with its purpose: `"quattro
%% minuti per non morire".' -- four minutes not to die, the headline of an
%% interview. The time reading comes first for a number and a time noun
%% (tr_complements0/4); nothing is said of it by a verb, so it names
tr_predicated(Side, [at_time(NP)|Cs]) :-
    tr_counted(NP), member(C, Cs), ( C = pp(P, _), \+ tr_means_of(Side, P) ; C = purpose(_) ; C = npurpose(_) ), !.
%% a pronoun that stands alone at the head of a clause with no verb is what
%% the clause names, not a clitic of a verb it does not have (tr_join_left/5
%% reads `Niente, se ...' the same way)
tr_standing_pronoun(Side, [opron(w(X, C))|Cs], [obj(pronoun(w(X, C)))|Cs]) :-
    tr_is(Side, w(X, C), pronoun), tr_lexeme(Side, X, L, _), tr_solve(neg(precede(L, verb))), !.
tr_standing_pronoun(_, Cs, Cs).
tr_also_nominal(Side, W) :- ( tr_is(Side, W, noun) ; tr_is(Side, W, adjective) ; tr_is(Side, W, number) ), !.
%% what a heading names: an article and its noun, or all of one (all/2):
%% `Toda una proeza.' -- quite a feat
tr_heading_np(np(det(article, _, _), none, _, w(_, _), _)).
%% ... or a plural with none: it names a kind, which `Pan del perro.' does not
%% (`Nuovi linguaggi del disagio giovanile ...' heads a report on a youth festival)
tr_heading_np(np(none, none, _, w(_, _), plural)).
tr_heading_np(all(_, NP)) :- tr_heading_np(NP).
tr_heads_phrase(Side, [D, W|_]) :-
    D = w(_, _), W = w(_, _), tr_determiner(Side, D, _, _), ( tr_is(Side, W, noun) ; tr_is(Side, W, adjective) ), !.

%% every selection of the adverb words, KEEPING each one before lifting it
%% -- so the first solution lifts nothing (which the caller rejects) and
%% the ones after it lift as few as the reading needs.
tr_adverbs_off(_, [], [], []).
tr_adverbs_off(Side, [W|Ws], [W|Rest], Advs) :- tr_adverbs_off(Side, Ws, Rest, Advs).
%% (never a denial: `credo si cominci a vedere qualche risultato ma non
%% posso garantirlo' -- lifted, `non' came back as the first verb's own
%% adverb, `Creo no que ...', and the verb it denies was left affirmed)
tr_adverbs_off(Side, [W|Ws], Rest, [adv(W)|Advs]) :-
    tr_plain_adverb(Side, W), \+ ( W = w(N, _), atom(N), tr_negation_word(N) ),
    \+ tr_governs_adverb(Side, W, Ws),
    tr_adverbs_off(Side, Ws, Rest, Advs).
%% A WORD THAT IS A PREPOSITION TOO IS THE PREPOSITION BEFORE AN ADVERB:
%% `pero hasta entonces mantendrá' is until then and `¿Hasta dónde
%% llegaste?' how far. `hasta' is the adverb `even' as well, for `y hasta
%% anuncios' (tr_complements0/4), and lifted as one before `entonces' it
%% came out `persino allora', where 1.8.20 wrote `fino a allora'; a
%% preposition whose object is an adverb is 1.6.14's `per sempre'
%% (never a word that says `also' or `even' of the preposition's phrase that
%% stands after it: `se la porta dietro anche nel caso' is behind, and `anche'
%% no object of it -- where `di soltanto il 1,4%' is of only 1.4 %)
tr_governs_adverb(Side, W, [N|Ns]) :-
    N = w(NW, _), tr_is(Side, W, preposition), tr_plain_adverb(Side, N),
    \+ ( atom(NW), tr_focus_adverb(NW), Ns = [N2|_], tr_is(Side, N2, preposition) ), !.
%% ... AND BEFORE AN INFINITIVE: `Dopo aver mangiato il pane, tace' is after
%% having eaten the bread, and `dopo' lifted as the adverb left `aver
%% mangiato il pane' to be the subject of `tace'
tr_governs_adverb(foreign, W, [w(R, _)|_]) :-
    atom(R), tr_is(foreign, W, preposition), tr_solve(infinitive_of(R, _)), !.
%% ... AND BEFORE AN ARTICLE AND ITS PHRASE TO A COMMA: `Secondo la corte, è
%% necessario un vero pluralismo' is according to the court, `Dopo la sentenza
%% della corte, però, c'è stato il referendum' after it -- lifted as the adverb
%% (`secondo' is also `second'), the preposition left the court for the subject
%% and the copula's own subject after it an object, `The court, is necessary a
%% true pluralism second'. A phrase with no verb in it, and the comma after it
tr_governs_adverb(foreign, W, [D|Ns]) :-
    tr_determiner(foreign, D, _, article), tr_is(foreign, W, preposition),
    append(NP, [comma|_], Ns), NP = [_|_], \+ memberchk(comma, NP),
    \+ ( member(w(X, _), NP), atom(X), tr_verb_form_word(X) ), !.
%% ... AND BEFORE A NAME AND ITS COMMA: `Secondo Enrico Finzi, sociologo e presidente della società Astra, è così' is
%% according to him -- lifted as the adverb `second', the preposition left the name for the copula's subject, `Enrico
%% Finzi ... is thus Second'. Capitalised words to the comma, and an aside after them
tr_governs_adverb(foreign, W, [D|Ns]) :-
    D = w(_, upper), tr_is(foreign, W, preposition), tr_name_word(foreign, D),
    append(NP, [comma|_], [D|Ns]), \+ memberchk(comma, NP),
    forall(member(X, NP), ( X = w(_, upper) ; X = w(_, aside) )), !.

%% the first division whose two sides both read: a connecting word the
%% lesson gives (`e', `ma', `perche'), or a bare comma. The connector
%% travels as the word it was written with and crosses through mean/2 like
%% every other word; a comma has no word and travels as the atom.
%% A SEMICOLON IS TRIED FIRST: it divides more strongly than a comma or a
%% connecting word, and a sentence that has one divides there before it
%% divides anywhere inside either half
tr_clause_split(_, Words, Left, semicolon, Right) :-
    append(Left0, [semicolon|Right0], Words),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right).
%% A SUBORDINATING WORD DIVIDES BEFORE A COORDINATING ONE, and the last of
%% them first: `raggiunti dagli uomini del soccorso alpino e speleologico che
%% li hanno trovati vigili e in buone condizioni NONOSTANTE le temperature
%% ... abbiano raggiunto i -10 gradi' is a finding and then the cold it was
%% found in, and divided at its first `e' both sides happened to read and
%% neither was a clause of the sentence -- the rescue came out `alpine' and
%% the rest `speleological that found them'. The `e's inside a phrase or a
%% clause are then read where they stand, inside the side that holds them.
%% (never inside a quotation that closes before a comma: `"En primer lugar,
%% todavía no sé si Paral.lel continuará en la parrilla", se limitó a
%% contestar Puigbó ...' is a quotation and who gave it, and divided at `si'
%% first, the quotation's end and its reporting clause were read as the
%% condition's second clause, `if Paral.lel will continue')
tr_clause_split(Side, Words, Left, Conn, Right) :-
    findall(L0-X-R0, append(L0, [X|R0], Words), Splits0), reverse(Splits0, Splits),
    member(Left1-w(C, CC)-Right0, Splits),
    tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)),
    \+ ( append(_, [w(_, QC), comma|_], Right0), memberchk(QC, [qclose, qcloseu]) ),
    %% `... in vacanza E MENTRE il compagno ...': a coordinator straight
    %% before the subordinating word joins the whole of what follows, and
    %% left on the first side it was read as the last word of a phrase
    %% (-- and a comma before THAT is the source's too: `che forse la terra
    %% era davvero sferica, ma siccome non è conoscendo ...' lost it, `quizás
    %% pero ya que', which 1.8.30 wrote as well; ck/1 carries it to the join)
    (   append(Left0, [K], Left1), K = w(_, _), tr_coord(Side, K), Left0 \== []
    ->  ( append(LA, [comma], Left0), LA \== [] -> Conn = both(ck(K), w(C, CC)) ; Conn = both(K, w(C, CC)) )
    %% ... and a COMMA before it is the source's and is written back: `...
    %% la terapia del dolore, in modo che il malato possa ...' lost it
    ;   append(Left0, [comma], Left1), Left0 \== []
    ->  Conn = both(comma, w(C, CC))
    ;   Left0 = Left1, Conn = w(C, CC)
    ),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right).
%% ... AND NEVER BEFORE A BARE NOUN IN THE SINGULAR, which begins no clause
%% here: `Si bien la demanda de las familias en productos de ocio Y
%% entretenimiento mantuvo ...' divided at the `y', the first half read as
%% `although she sues her ...' and the second as `entertainment kept ...',
%% and the division at the comma after them, which is the sentence's, was
%% never tried (tr_bare_start/2).
%% -- and a COMMA before it is the source's, and is written back: `... no
%% son optimistas, y se prevé un mantenimiento' lost it
%% ... A COORDINATOR BEFORE AN OBJECT PRONOUN AND A VERB DIVIDES BEFORE ANY
%% OTHER: `saranno intestati non più al genitore ma direttamente ai figli E NE
%% potranno beneficiare anche i lavoratori autonomi' is two clauses at the
%% `e', the second with its subject after it; divided at the first
%% coordinator, `ma', its second side read as a clause of its own with `e ne'
%% in its front, and the sentence came out garbled where it should have been
%% refused or read right
tr_clause_split(foreign, Words, Left, Conn, Right) :-
    append(Left1, [w(C, CC)|Right0], Words),
    tr_coord(foreign, w(C, CC)),
    tr_clitic_verb_start(Right0),
    \+ tr_joins_phrases(foreign, Left1, Right0),
    \+ tr_inside_insertion(foreign, Left1, Right0),
    (   append(Left0, [comma], Left1), Left0 \== [] -> Conn = both(comma, w(C, CC)) ; Left0 = Left1, Conn = w(C, CC) ),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right).
tr_clause_split(Side, Words, Left, Conn, Right) :-
    append(Left1, [w(C, CC)|Right0], Words),
    tr_connector(Side, C), tr_coord(Side, w(C, CC)),
    \+ ( Side == foreign, tr_clitic_verb_start(Right0) ),
    \+ tr_bare_start(Side, Right0),
    \+ tr_joins_phrases(Side, Left1, Right0),
    \+ tr_inside_insertion(Side, Left1, Right0),
    (   append(Left0, [comma], Left1), Left0 \== [] -> Conn = both(comma, w(C, CC)) ; Left0 = Left1, Conn = w(C, CC) ),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right).
tr_clause_split(Side, Words, Left, comma, Right) :-
    append(Left0, [comma|Right0], Words),
    \+ tr_insertion_closer(Side, Left0, Right0),
    tr_clause_words(Left0, Left), tr_clause_words(Right0, Right).
tr_clitic_verb_start([w(Cl, _), w(V, _)|Ws]) :-
    atom(Cl), tr_clitic(unsaid(none), Cl), atom(V), tr_group_at(foreign, [w(V, lower)|Ws], _, _), !.
%% ... NOR BETWEEN TWO PHRASES OF ONE PREPOSITION: `il responsabile
%% dell'ambiente E dei lavori pubblici' is one manager, of the environment and
%% of public works, and divided at that `e' the rest read with the second
%% phrase fronted and the sentence came out in pieces. The preposition after
%% the coordinator is the one the left side's last phrase opened on.
tr_joins_phrases(Side, Left, [P|_]) :-
    P = w(PW, _), tr_is(Side, P, preposition),
    append(_, [w(PW, _)|After], Left),
    \+ ( member(X, After), ( X == comma ; X = w(_, _), ( tr_is(Side, X, preposition) ; tr_coord(Side, X) ) ) ), !.
tr_has_verb_group(Side, Words) :- append(_, T, Words), T = [w(V, _)|_], atom(V), tr_group_at(Side, T, _, _), !.
%% ... NOR INSIDE AN INSERTION BETWEEN A SUBJECT AND ITS VERB: `Il pane che
%% ho fatto, non solo io ma il gatto, è buono, il cane lo mangia' divided at
%% `ma', both sides read -- a verbless piece, and `il gatto, è buono' -- and
%% English said `I not only but the cat'. The insertion is the one
%% tr_insertion_closer/3 names, its words between two commas opening on a
%% preposition, an adverb or a denial, and a verb group after the second.
%% The Fregene report's own `non solo io ma tanti altri nel nostro campo, va
%% sempre sotto silenzio' read right only because the second side read as no
%% clause, and `ma anche' only because `anche' is also the plural of `anca',
%% a bare noun no clause begins on (tr_bare_start/2)
tr_inside_insertion(Side, Left1, Right0) :-
    append(Pre, [comma|InsL], Left1), Pre \== [], InsL = [P|_], \+ memberchk(comma, InsL),
    ( tr_is(Side, P, preposition) ; tr_plain_adverb(Side, P) ; P = w(PN, _), atom(PN), tr_negation_word(PN) ),
    append(InsR, [comma|After], Right0), InsR \== [], \+ memberchk(comma, InsR),
    tr_group_at(Side, After, _, _), !.
%% ... BUT NOT AT THE COMMA THAT CLOSES AN INSERTION BETWEEN A SUBJECT AND ITS
%% VERB: `E tutto il Lavoro che ho fatto, non solo io ma tanti altri nel
%% nostro campo, va sempre sotto silenzio, non si trova nemmeno un trafiletto'
%% is the work going unnoticed. The whole piece has two clauses, so it is
%% divided -- and divided after the insertion, the subject and the insertion
%% were a clause with its verb left out and `silenzio' the subject of `va'.
%% An insertion is what tr_insertion_off/4 sets aside: words between two
%% commas that open on a preposition, an adverb or a denial, with a verb
%% group right after the second
tr_insertion_closer(Side, Left0, Right0) :-
    Right0 = [_|_], append(Pre, [comma|InsW], Left0), Pre \== [], InsW = [P|_], \+ memberchk(comma, InsW),
    ( tr_is(Side, P, preposition) ; tr_plain_adverb(Side, P) ; P = w(PN, _), atom(PN), tr_negation_word(PN) ),
    tr_group_at(Side, Right0, _, _), !.

%% THE REPORTING CLAUSE: its verb first and its SUBJECT AFTER IT, among its
%% complements -- `ha raccontato a Sky Tg24 Tornaboni', `ha spiegato un
%% soccorritore', `fa sapere, in una nota, la Regione Lazio spiegando che
%% ...' -- which is where both lesson languages put the speaker. The
%% quotation is what was said, so the clause has NO OBJECT of its own, and
%% that is what chooses among the places the subject could stand: read with
%% `Tg24' for the speaker, `Tornaboni' was left over as an object. A name
%% after the clause's last comma is its apposition (`il capitano ...,
%% Alessio Falzone'). The subject's place travels as subj_here among the
%% complements, so the lesson's writer puts it back where it stood, and
%% English's writes it first.
tr_read_reporting(foreign, Words0, S) :- tr_reporting(any, Words0, S), !.
%% ... AND ONE WITH NO SPEAKER AT ALL, the verb alone: `Gallo - continua -
%% mi ha lasciato una società disastrata' is the man quoted going on, and
%% the one who speaks is the one the sentences before named. Read as a
%% clause of its own it had nobody for a subject, and the dashes kept it
%% from the sentence around it; it is the reporting clause, in the third
%% person singular, and nothing is said of it but the verb.
%% (the SINGULAR, which is what makes it the one quoted: widened to either
%% number, `Le condizioni generali sono ottime: ridono, scherzano,
%% raccontano.' took `, scherzano,' for a reporting clause set in the
%% sentence and wrote it last, `ríen, cuentan, bromean')
tr_read_reporting(foreign, Words, s(none, null(third, singular), g(L, T, A, no), [])) :-
    Words = [w(_, _)|_],
    tr_group_from(foreign, Words, [], g(L, T, A, third, singular), []), atom(L), !.
%% ... AND THE VERB WITH A GERUND THAT SAYS HOW: `"la proposta dell'anno
%% passato suscitò un vespaio, ... - commenta ridendo -.' -- he comments,
%% laughing. With the gerund after it the verb alone above had no reading,
%% and the side of the dashes was read as a command, `comment laughing'.
%% (a verb of saying, whose English meaning is one: tr_saying_verb/1)
tr_read_reporting(foreign, Words, s(none, null(third, singular), g(L, T, A, no), Cs)) :-
    Words = [w(_, _), w(_, _)|_],
    tr_group_from(foreign, Words, [], g(L, T, A, third, singular), After), atom(L), tr_saying_verb(L),
    After = [w(G, _)|_], atom(G), tr_solve(gerund_of(G, _)),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', A),
    (   tr_complements(foreign, After, Cs), Cs = [ger(_, _)]
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ), !.
%% ... AND ONE WHOSE SPEAKERS ARE WHERE IT SAYS: `Ma i primi dati di
%% quest'anno - precisano al Ministero dell'Università - ... suggerirebbero
%% una tendenza al ribasso' -- they specify at the Ministry. The verb in the
%% third person, either number, nobody named, and after it only the place
%% it was said at: read as the year's aside, `precisano' was an adjective.
%% (a verb the lesson says takes the clause, which is a verb that can
%% report one: `sono troppi, sono d'accordo, ma ...' is no reporting clause,
%% and taken for one `sono d'accordo' was written after the sentence)
tr_read_reporting(foreign, Words, s(none, null(third, N), g(L, T, A, no), Cs)) :-
    Words = [w(_, _)|_],
    tr_group_from(foreign, Words, [], g(L, T, A, third, N), After), atom(L), tr_solve(take(L, clause)),
    After = [w(P, _)|_], ( tr_is(foreign, w(P, lower), preposition) -> true ; tr_solve(contraction_of(P, _)) ),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', A),
    (   tr_complements(foreign, After, Cs), Cs \== [], forall(member(C, Cs), tr_adjunct(C))
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ), !.

%% the first clause of it, with the speaker it must have: `any' where a
%% quotation mark already says that something was said, and `person' where
%% only the speaker can say so (the reporting clause at the end of a
%% sentence, tr_read0/4) -- asked AS SOON AS the subject is read, and with no
%% pronoun before the verb, because the complements after it are the costly
%% part: read for every phrase the clause could have for its subject,
%% `avrebbe intascato tangenti ... e truffato la comunità ... (per la
%% valutazione ... di un terreno)' cost a million inferences to find that
%% none of them is a person
tr_reporting(Who, Words0, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    Words = [W0|_], W0 \== comma,
    ( Who == person -> Before = [] ; true ),
    tr_group_from(foreign, Words, Before, g(L, T, A, FP, FN), After),
    %% (a copula reports nothing: `La casa, que compró Pedro, es la mejor' has
    %% no comment at its end, and `la mejor', a phrase with its noun left out,
    %% is as much a person as any, so the clause of who said so was `is the
    %% best one' and the house a heading with a verb that marries)
    ( Who == person -> \+ tr_copula_lexeme(L) ; true ),
    %% (and only a verb that can report does: `La banda, dopo il rapimento,
    %% uccise il nobile romano' is the gang killing him, and the Roman after
    %% the verb, a person, was taken for the speaker of a clause that reports,
    %% `The gang, after the abduction, the noble Roman one killed')
    ( Who == person -> ( tr_saying_verb(L) -> true ; tr_solve(take(L, clause)) ) ; true ),
    tr_uncomma(Before, BeforeU),
    %% (an adverb before the verb stays before it: `come INVECE hanno scritto
    %% gli inviati de "La Repubblica", negli articoli ...' -- as the envoys
    %% wrote instead, in the articles. With only pronouns allowed there it
    %% was no comment, and the phrase after it went into the clause before.
    %% Only in the clause of who said so (tr_said_to/1): allowed in every
    %% reporting clause, every piece between two commas that opens on an
    %% adverb -- `Abachidze, en cambio, prefiere ...', `En esta versión,
    %% además, cuenta con ...' -- was read on as one and failed later, 0.8
    %% million inferences more for Georgia's fifth sentence)
    (   tr_global('$tr_said_to', yes) -> tr_front_adverbs(BeforeU, Advs, Clitics)
    ;   Advs = [], Clitics = BeforeU
    ),
    forall(member(w(C, _), Clitics), tr_clitic(normal, C)),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', A),
    append(Pre, SubjPost, After),
    %% (a speaker the clause must have stands after no preposition, which
    %% would govern it: `si disse subito dopo Hiroshima' is IT WAS SAID right
    %% after Hiroshima, and in `... del duomo arabo normanno di Monreale' the
    %% town is the cathedral's)
    \+ ( Who == person, last(Pre, P), P = w(_, _), tr_is(foreign, P, preposition) ),
    %% (... and none begins right after a determiner or a count, inside the phrase it opens: `polemizzavano con le
    %% teorie pagane sulla rotondità della terra' had `teorie pagane ...' read as a bare plural speaker, 1.2 million
    %% inferences of the Middle Ages' thirteenth, and `vivono 6 milioni e 458 mila poveri' 0.4 of the poor's fifth)
    \+ ( SubjPost = [w(SW1, lower)|_], \+ tr_determiner(foreign, w(SW1, lower), _, _),
         last(Pre, P1), P1 = w(_, _), ( tr_determiner(foreign, P1, _, _) ; tr_count_word(foreign, P1) ) ),
    %% a name after a determiner is ONE name, and the speaker does not begin
    %% inside it: `cuenta con una June Anderson en plena forma' has June
    %% Anderson for a singer to count on, and cut after `June' it had
    %% `Anderson' telling the rest
    \+ ( SubjPost = [w(_, upper)|_], append(_, [D|Ns], Pre), Ns \== [], tr_determiner(foreign, D, _, _),
         forall(member(N, Ns), N = w(_, upper)) ),
    tr_report_subject(SubjPost, FP, FN, SW0, Post00),
    %% (a name apposed to the speaker's name between commas is the speaker's:
    %% `Commenta Carlo Rognoni, Pds, vicepresidente del senato' is the man and
    %% his party, and left after the name the party's word was no complement)
    ( Post00 = [w(AP, appos)|Post0] -> append(SW0, [w(AP, appos)], SW) ; SW = SW0, Post0 = Post00 ),
    %% (where a quotation mark is all that says something was said, what
    %% stands between the verb and the speaker is read BEFORE the speaker: it
    %% has no object, and most of the places a speaker could stand leave one
    %% there -- read after the speaker and its phrases of `of', each place was
    %% read whole for nothing, 0.26 million inferences of Georgia's fifth)
    ( Who == person -> true ; tr_complements(foreign, Pre, C1), \+ memberchk(obj(_), C1) ),
    tr_subject(foreign, none, SW, FP, FN, Subject0),
    ( Who == person -> tr_of_class(Subject0, person) ; true ),
    %% ... AND THE SPEAKER'S OWN RELATIVE CLAUSE AFTER A COMMA: `añadió el
    %% técnico, que se mostró "tremendamente desolado"' -- the technician,
    %% who showed himself so. Read as the clause's own complements it was a
    %% clause of `that' the verb took, `added the technician that ...'. It is
    %% the phrase's, nrc/3, as after any phrase
    %% ... AND A SPEAKER WITH PHRASES OF `OF' TAKES IT WHOLE: `dijo el presidente
    %% de la Generalitat, que inauguró el congreso' -- the president, who
    %% inaugurated it; the clause stayed a `that' of the verb, and English
    %% refused it for a verb with nobody named
    (   Post0 = [comma|R1], tr_nrc_start(foreign, R1),
        ( Subject0 = np(_, _, _, _, _) ; Subject0 = name(_) ; Subject0 = with(_, _) ),
        tr_relative_clause(foreign, R1, Role, RS)
    ->  Subject = nrc(Subject0, Role, RS), Post = []
    ;   Subject = Subject0, Post = Post0
    ),
    tr_complements(foreign, Pre, C1), tr_complements(foreign, Post, C20),
    tr_report_appos(C20, C2),
    %% (an object after an infinitive is the infinitive's, as in any clause
    %% (tr_verbal_comp/1): `añadió Metsu, sin comprender aún la dimensión de
    %% esa victoria' -- understanding, not adding, takes the dimension)
    \+ memberchk(obj(_), C1),
    \+ ( append(C2a, [obj(_)|_], C2), \+ ( member(V2, C2a), tr_verbal_comp(V2) ) ), !,
    findall(frn(adv(W)), member(W, Advs), As),
    %% (a reflexive pronoun before the verb is the verb's own, as in a
    %% statement: `se limitó a contestar Puigbó' is Puigbó limiting himself,
    %% and as an object pronoun English wrote `limited itself')
    (   select(w(RW, _), Clitics, Clitics1), atom(RW), tr_reflexive_word(RW), atom(L)
    ->  LV = reflexive(L)
    ;   Clitics1 = Clitics, LV = L
    ),
    findall(opron(W), member(W, Clitics1), Cs),
    append([As, Cs, C1], C1a), append(C1a, [subj_here|C2], Comps),
    S = s(none, Subject, g(LV, T, A, Neg), Comps).

%% the speaker: a run of capitalised words no lesson knows, which is one
%% name -- never one opening on a word with a digit in it, `Tg24' being a
%% channel's -- or a phrase agreeing with the verb
%% THE PERSON AFTER `a' IN THE CLAUSE OF WHO SAID SO IS THE ONE IT WAS SAID
%% TO (tr_takes_before_person/1), for as long as that clause is read and no
%% longer -- set again whenever it is backtracked into, and put back after
%% each answer and on the way out. Only there: a first cut set it for every
%% reporting clause the reader tries, and Clinton's ninth, `El portavoz
%% demócrata, John Conyers, por su parte, criticó a los republicanos por
%% hablar ...', went from 3.6 million inferences to 21.1, the republicans
%% the ones a criticism was said to.
tr_said_to(Goal) :-
    tr_global('$tr_said_to', ST0),
    (   nb_setval('$tr_said_to', yes)
    ;   nb_setval('$tr_said_to', ST0), fail
    ),
    call(Goal),
    (   nb_setval('$tr_said_to', ST0)
    ;   nb_setval('$tr_said_to', yes), fail
    ).

tr_report_subject([W1|Ws], P, N, SW, Rest) :-
    tr_name_word(foreign, W1), \+ tr_digit_word(W1), !,
    tr_name_run([W1|Ws], SW, Rest), P == third, N == singular.
%% ... AND A NAME WHOSE FIRST WORD THE LESSON KNOWS: `según manifestó
%% Redondo Terreros a Europa Press' -- `redondo' is round to the vocabulary.
%% A run of two capitalised words or more with one no lesson knows in it is
%% one name, as it is after a bare preposition (tr_particle_names/4).
tr_report_subject([W1|Ws], P, N, [w(Name, upper)], Rest) :-
    W1 = w(_, upper), \+ tr_digit_word(W1),
    tr_cap_run([W1|Ws], Run, Rest), Run = [_, _|_],
    once(( member(X, Run), tr_name_word(foreign, X) )), !,
    findall(C, ( member(w(Y, _), Run), tr_cap(Y, C) ), Cs), atomic_list_concat(Cs, ' ', Name),
    P == third, N == singular.
%% ... AND ONE WITH ITS OWN RELATIVE CLAUSE AFTER A COMMA: `añadió el
%% técnico, que se mostró "tremendamente desolado"'. The phrase ends at the
%% comma, and tr_reporting/3 takes the clause onto it (nrc/3); read to the
%% end, the phrase took the comma and the clause in and agreed with nothing
tr_report_subject(Words, P, N, SW, [comma|R1]) :-
    append(SW, [comma|R1], Words), SW = [D|_], \+ memberchk(comma, SW),
    tr_determiner(foreign, D, _, _), tr_nrc_start(foreign, R1),
    %% (a speaker is a phrase and its phrases of `of', as the clause below
    %% reads one, and holds no verb: asked before the phrase is read, which
    %% cost Livata's twenty-sixth 0.2 million inferences for `la Regione
    %% Lazio spiegando che "si sono adoperate ...' and Georgia's fifth 0.13
    %% million for `el voto de los descontentos con las reformas')
    \+ ( member(w(VW, _), SW), atom(VW), tr_verb_form_word(VW) ),
    \+ ( member(X, SW), X = w(_, _), tr_is(foreign, X, preposition), \+ tr_means_of(foreign, X) ),
    %% ... a phrase with phrases of `of' after it agrees by its head: `dijo el
    %% presidente de la Generalitat, que inauguró el congreso' took the clause
    %% for a complement of the verb, with the speaker's `de' phrase before it
    (   fo_agreeing(SW, P, N) -> true
    ;   fo_np_words_after(SW, SW0, Rest0), SW0 = [_|_], tr_report_ofs(Rest0, [_|_], []), fo_agreeing(SW0, P, N)
    ), !.
%% -- and the phrase OPENS ON A DETERMINER. A bare noun after the verb is its
%% object in both lesson languages, never its subject: `Lei voleva fare una
%% passeggiata, ha sbagliato strada, ...' read `ha sbagliato strada' as a
%% clause REPORTING the rest, spoken by a road, and wrote it after the
%% sentence. `sottolinea il Lingotto', `ha spiegato un soccorritore' and
%% `aggiunge l'ad Sergio Marchionne' all open on one.
tr_report_subject(Words, P, N, SW, Rest) :-
    Words \= [comma|_],
    fo_np_words_after(Words, SW0, Rest0),
    %% (or a bare plural, persons of no particular kind: `según explicaron fuentes de los turoperadores de la zona'
    %% is as sources of the tour operators explained, and with a determiner asked for the clause was refused)
    SW0 = [D|_],
    (   tr_determiner(foreign, D, _, _) -> fo_agreeing(SW0, P, N)
    ;   N == plural, P == third, D = w(DX, lower), atom(DX),
        %% (the cheap tests first: such a speaker holds no comma, no bracket or aside and no relative clause, and no
        %% name right after its noun -- asked of `los argentinos Guglielminpietro (Milan) y Vivas (Arsenal), los
        %% turcos ...' and `jugadores que asumieron la responsabilidad ...', the phrase read for nothing cost
        %% Kallon's sentence 1.0 million inferences and Rimac's 0.5 -- and no verb, as a speaker with a determiner
        %% holds none: `teorie pagane sulla rotondità della terra e la rappresentavano ...' cost the Middle Ages'
        %% thirteenth 1.6 million)
        \+ SW0 = [_, w(_, upper)|_],
        \+ ( member(X, SW0), ( X == comma ; X = w(XW, XK), ( memberchk(XK, [paren, aside, dashed]) ; atom(XW), tr_relative_word(foreign, XW) ) ) ),
        \+ ( member(w(VW, _), SW0), atom(VW), tr_verb_form_word(VW) ),
        %% (and its noun is no adjective, which after a noun is the noun's: `le teorie pagane')
        tr_is(foreign, D, noun), \+ tr_is(foreign, D, adjective), tr_lexeme(foreign, DX, _, plural),
        tr_subject(foreign, none, SW0, third, plural, _)
    ),
    tr_report_ofs(Rest0, Ofs, Rest1), append(SW0, Ofs, SW1),
    tr_report_name_after(SW1, Rest1, SW, Rest).

%% ... AND THE PHRASES OF `of' AFTER IT ARE THE SPEAKER'S TOO: `come invece
%% hanno scritto gli inviati de "La Repubblica"' -- the paper's envoys. Left
%% to the clause, English said the envoys wrote OF the paper
%% -- WITH THE NAME APPOSED AFTER THE LAST ONE: `ha spiegato il capitano dei
%% carabinieri della Compagnia di Subiaco, Alessio Falzone'. A name after a
%% comma at the end of a piece comes joined, w(Name, appos), and after a
%% phrase that is a name alone the phrase ended before it: the apposition
%% was left with nothing to read it, the speaker's reading failed, and the
%% captain was the OBJECT of a verb nobody named, `ha explicado al capitán'
tr_report_ofs([P|Ws], Ofs, Rest) :-
    P = w(_, _), tr_means_of(foreign, P),
    fo_np_words_after(Ws, NW0, R00), NW0 \== [],
    ( R00 = [w(A, appos)|R0] -> append(NW0, [w(A, appos)], NW) ; NW = NW0, R0 = R00 ), !,
    tr_report_ofs(R0, Ofs1, Rest), append([P|NW], Ofs1, Ofs).
tr_report_ofs(Ws, [], Ws).

%% A NAME AFTER THE SPEAKER'S PHRASE IS THE SPEAKER'S: `spiega il segretario
%% nazionale Ferdinando Uliano', `aggiunge l'ad Sergio Marchionne'. The phrase
%% ends where the name begins, and the name after it was read as an object of
%% the verb -- which a reporting clause has none of, so the clause was
%% refused. The name's words join as ONE word, apposed to the phrase's noun
%% as `il presidente Scalfaro' is.
tr_report_name_after(SW0, Rest0, SW, Rest) :-
    tr_name_run(Rest0, [N1|Ns], Rest), \+ tr_digit_word(N1), !,
    findall(C, ( member(w(X, _), [N1|Ns]), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', A),
    append(SW0, [w(A, upper)], SW).
tr_report_name_after(SW, Rest, SW, Rest).

tr_digit_word(w(W, _)) :- atom_codes(W, Cs), member(C, Cs), rt_digit(C), !.

%% a name after the clause's last comma is the apposition of the phrase
%% before it, and no object
tr_report_appos(Cs0, Cs) :-
    append(Front, [sep, obj(NP)], Cs0), NP = name(_), !, append(Front, [sep, appos(NP)], Cs).
%% ... and so is a PHRASE after it, with the phrases of `of' that complete
%% it: `commenta John Elkann, presidente di Fiat' -- read as the verb's
%% object the clause had one, was read as a statement instead, and the
%% speaker came out with the person marker in front, `comenta a John Elkann'
tr_report_appos(Cs0, Cs) :-
    append(Front, [sep, obj(NP)|Tail], Cs0), NP = np(_, _, _, _, _),
    forall(member(T, Tail), T = pp(_, _)), !,
    append(Front, [sep, appos(NP)|Tail], Cs).
tr_report_appos(Cs0, Cs) :- tr_person_appos(Cs0, Cs), !.
%% ... and TWO phrases joined: `dice Carolyn Christov Bakargev, giornalista
%% e critica' -- a journalist and a critic, one person's two trades. Read as
%% the verb's object the clause had one, and the sentence was refused
tr_report_appos(Cs0, Cs) :-
    append(Front, [sep, obj(NP)], Cs0), NP = co(_, NP1, NP2),
    NP1 = np(_, _, _, _, _), NP2 = np(_, _, _, _, _), !,
    append(Front, [sep, appos(NP)], Cs).
tr_report_appos(Cs, Cs).

%% a side of a division: at least one word, and a comma of its own at the
%% edge is punctuation rather than another clause (`, perche ...')
tr_clause_words(Ws0, Ws) :-
    ( append([comma], W1, Ws0) -> true ; W1 = Ws0 ),
    ( append(Ws, [comma], W1) -> true ; Ws = W1 ),
    Ws \== [], \+ memberchk(Ws, [[comma]]),
    \+ ( Ws = [M], atom(M) ).

%% a word that joins two clauses: one the lesson calls a conjunction whose
%% meaning is one of English's connectors, or one of English's own
tr_connector(english, W) :- !, en_connector(W).
tr_connector(foreign, W) :-
    tr_lexeme(foreign, W, L, _), tr_class_of(L, conjunction),
    tr_solve(mean(L, E)), en_connector(E), !.

%% A COMMENT SET BETWEEN TWO COMMAS REPORTS, AND ONLY A VERB OF SAYING OR A
%% PERSON REPORTS. `..., ha rilevato ancora il presidente della repubblica,
%% crea ...' and `..., sottolinea il Lingotto in una nota, non è previsto ...'
%% are somebody saying it; `che se fosse stata promulgata, avrebbe
%% dissestato l'amministrazione, reso più lunghi i tempi' is not, and read
%% as one -- a verb, its subject after it and no object, which is all a
%% reporting clause is -- the rest of the sentence was read without it and
%% failed: put back with every other rule here in, it costs Ciampi's
%% twenty-first sentence 222.6 million inferences more, where the sentence
%% reads in 10.8 million. The subject is a person the lesson calls one, or
%% the verb means one of English's verbs of saying.
tr_saying_clause(s(_, Subj, g(L0, _, _, _), _)) :-
    (   tr_of_class(Subj, person) -> true
    ;   ( L0 = reflexive(L) -> true ; L = L0 ), atom(L),
        tr_solve(mean(L, E)), en_saying(E)
    ), !.

en_saying(says).       en_saying(tells).      en_saying(states).    en_saying(declares).   en_saying(explains).
en_saying(adds).       en_saying(stresses).   en_saying(underlines). en_saying(emphasises). en_saying(emphasizes).
en_saying(highlights). en_saying('points out'). en_saying(notes).   en_saying(observes).   en_saying(remarks).
en_saying(comments).   en_saying(announces).  en_saying(claims).    en_saying(asserts).    en_saying(affirms).
en_saying(maintains).  en_saying(answers).    en_saying(replies).   en_saying(responds).   en_saying(reveals).
en_saying(specifies).  en_saying(reiterates). en_saying(warns).     en_saying(recalls).    en_saying(reports).
en_saying(writes).     en_saying(admits).     en_saying(confirms).  en_saying(denies).     en_saying(argues).
en_saying(insists).    en_saying(suggests).   en_saying(mentions).  en_saying(repeats).    en_saying(concludes).
en_saying(clarifies).  en_saying('lets know'). en_saying(reminds).  en_saying(sustains).   en_saying(assures).   % `Assicura il sindaco ... che ...'
en_saying(proclaims).  en_saying(whispers).   en_saying(shouts).    en_saying(cries).      en_saying(wonders).
en_saying(roars).      en_saying(retorts).    en_saying(demands).    en_saying(asks).      en_saying(requests).   en_saying(urges).   % `replicó a Ibarretxe que ...', `pidió al ministro que ...'

en_connector(and).  en_connector(but).  en_connector(or).
en_connector(because).  en_connector(so).  en_connector(while).
en_connector(although). en_connector('ever since').      % `sin da quando nel 2009 siamo stati scelti'
en_connector(without).                                   % `sin que un experto lo note'
en_connector('in case').                                 % `los ofrece al comando por si desea reponerlos'
en_connector(if).                                        % `neanche se vi sia l'assenso del paziente'
en_connector('so that').                                 % `in modo che il malato possa accostarsi'
en_connector('provided that').                           % `purché praticata con rigorosi controlli'
en_connector(since).                                     % `ya que nos espera un mes de febrero'
en_connector('not that').                                % `Non che la tranquillità ... sia garantita per tutti'
en_connector('apart from the fact that').               % `al margen de que, como todos, han disfrutado'
en_connector('that is').                                 % `l'abbiamo vinto a schiatto: cioè quando gli altri ...'
en_connector(as).                                        % `A medida que los precios ... se han abaratado, la extensión ...'
en_connector('even before').                             % `a dare forfait prima ancora che ciò potesse accadere'
en_connector('as if').                                   % `voglio procedere come se i mascalzoni fossero pochi'
en_connector('of course').                               % `"certo che ha capito cos'è successo.'
en_connector(after).                                     % `se produce después de que la lista de Porta acusara a Millàs'
en_connector(before).                                    % `passano quattro minuti prima che si producano danni'
en_connector('just as').                                 % `Así como suena.'
en_connector('except that').                             % `Salvo che subito dopo i due dialoganti hanno osservato ...'
en_connector('only that').                               % `Solo che il cerino si fa ogni giorno più corto'
en_connector('so much that').                            % `..., tanto che le mappe dell'epoca rappresentavano la terra come un disco'
en_connector(nor).                                       % `non mangia né dorme', `no come ni duerme'
en_connector(whenever).                                  % `ogni volta che andavamo a mangiare insieme, gli ricordavo'
en_connector('by the time').                             % `Para cuando lean estas líneas, el mundo ya tendrá una nueva miss'
en_connector('given that').                              % `Premesso che ogni federazione ha i suoi regolamenti, non sono d'accordo'
en_connector('so much so that').                         % `..., tanto è vero che siamo arrivati secondi'
en_connector('insofar as').                              % `non risolve il problema, nella misura in cui Berlusconi resta azionista'
en_connector(unless).                                    % `non possa essere membro del governo a meno che non si liberi entro un anno'
en_connector(until).                                     % `es una locura bajar a la playa hasta que no se haya resuelto el caso'

tr_normalise(_, statement, Words, Words, none) :- !.
tr_normalise(english, question, Words0, Words, Asked) :-
    en_question_word(Words0, Words1, Asked),
    en_unfront(Asked, Words1, Words).
tr_normalise(foreign, question, Words0, Words, Asked) :-
    fo_question_word(Words0, Words1, Asked),
    fo_unfront(Asked, Words1, Words).

%% English's question word, and what it asks for: `which' takes the noun
%% phrase after it, which is the object when `does', `will', `has' or the
%% copula follows with a subject and its verb after them (`Which book does
%% Maria read?', `Which book has Maria read?'), and the subject otherwise
%% (`Which dog will eat the bread?', `Which house is big?')
%% (`which' standing alone before its verb: `Which is the house?', `Which
%% do you want?' -- whichp/2, the number the copula gives it or singular)
en_question_word([w(which, C), w(A, AC)|Ws], [w(A, AC)|Ws], Asked) :-
    ( en_fronts(A) ; en_verb_form(A, _, _) ), \+ en_phrase_follows([w(A, AC)|Ws]), !,
    ( en_copula(A, _, N0, _) -> N = N0 ; N = singular ),
    (   en_fronts(A), en_np_words(Ws, S, R2), S \== [], R2 = [w(V, _)|_], ( en_verb_form(V, _, _) ; en_participle(V, _) )
    ->  Asked = object(whichp(N, C))
    ;   Asked = subject(whichp(N, C))
    ).
en_question_word([w(which, C)|Ws], Words, Asked) :- !,
    en_np_words(Ws, NP, Rest),
    (   Rest = [w(A, _)|R1], en_fronts(A), en_np_words(R1, S, R2), S \== [], R2 = [w(V, _)|_], ( en_verb_form(V, _, _) ; en_participle(V, _) )
    ->  Asked = object(which(NP, C)), Words = Rest
    ;   Asked = subject(which(NP, C)), Words = Rest
    ).
en_question_word([w(P, PC), w(which, C)|Ws], Words, pp(w(P, PC), which(NP, C))) :-
    en_preposition(P), !, en_np_words(Ws, NP, Words).
en_question_word([w(Q, C)|Ws], Ws, Asked) :- en_question(Q, Kind), !, Asked =.. [Kind, w(Q, C)].
en_question_word(Ws, Ws, none).

en_question(what, object).   en_question(whom, object).   en_question(who, subject).
en_question(where, place).   en_question(when, time).     en_question(which, which).
en_question(how, manner).
%% ... AND HOW MUCH AND HOW MANY, which ask a quantity: `Quanti sono i poveri?'
%% -- the lesson says which words ask it (`The word "quanti" means "how
%% many".'), as it says which ask where and how
en_question('how much', quantity).
en_question('how many', quantity).
%% ... AND `why': `"ma perché nessuno le ha viste?' asks why nobody saw them,
%% and with no question word for it `perché' was the connector `because', a
%% question that answered itself. The lesson says which word asks it (`The
%% word "perché" means "why".'), as it says which asks where
en_question(why, reason).

%% a fronted `does', `do', `did', `will', `has', `have', `had' or copula goes
%% back behind the subject phrase; not when the subject is what is asked
en_unfront(subject(_), Ws, Ws) :- !.
en_unfront(_, [w(A, AC), w(there, TC)|Ws], [w(there, TC), w(A, AC)|Ws]) :- en_fronts(A), !.      % `Is there a dog?'
en_unfront(_, [w(A, C)|Ws], Words) :-
    en_fronts(A), !,
    en_np_words(Ws, NP, Rest),
    append(NP, [w(A, C)|Rest], Words).
en_unfront(_, Ws, Ws).

en_fronts(A) :- memberchk(A, [does, do, did, will, would, has, have, had, am, is, are, was, were, can, could, may, might, must, should]).

%% the subject phrase at the head of the words: a pronoun, a name, or up to
%% and including the first word the lesson calls a noun -- failing that up
%% to the first verbal word
en_np_words([w(P, C)|Rest], [w(P, C)], Rest) :- en_subject(P, _, _), !.
en_np_words([w(P, C)|Rest], [w(P, C)], Rest) :- en_tonic(P, _), \+ en_phrase_follows(Rest), !.   % `Is this big?', not `Is this dog big?'
en_np_words([w(W, upper)|Rest], [w(W, upper)], Rest) :- \+ tr_known_word(english, W), !.
en_np_words(Words, NP, Rest) :-
    append(NP0, Rest0, Words), NP0 \== [], last(NP0, N), tr_is(english, N, noun), !,
    en_np_more(Rest0, More, Rest1), append(NP0, More, NP1),
    en_np_pps(Rest1, PPs, Rest), append(NP1, PPs, NP).
en_np_words(Words, NP, Rest) :- append(NP, Rest, Words), NP \== [], Rest = [w(V, _)|_], ( en_fronts(V) ; en_verb_form(V, _, _) ), !.
en_np_words(Words, Words, []).

%% a noun, a number, or adjectives and then one: what makes `this' a
%% determiner rather than the pronoun standing alone
en_phrase_follows([W|_]) :- ( tr_is(english, W, noun) ; tr_is(english, W, number) ), !.
en_phrase_follows([W|Ws]) :- tr_is(english, W, adjective), en_phrase_follows(Ws).

%% ... and on over the NOUNS after that noun that are no verb's form, while
%% a verb still follows: `the black cat sleeps', where `black' is a noun
%% too by its translation and `cat' would have been left to the verb; not
%% `the cat black' of a fronted `Is the cat black?', which has no verb
%% left after it
en_np_more([W|Ws], [W|More], Rest) :-
    tr_is(english, W, noun), W = w(V, _), \+ en_verb_form(V, _, _), \+ en_fronts(V),
    member(w(V2, _), Ws), ( en_fronts(V2) ; en_verb_form(V2, _, _) ), !,
    en_np_more(Ws, More, Rest).
en_np_more(Ws, [], Ws).

%% a phrase after a preposition after the noun belongs to it: `the dogs of Maria'
en_np_pps([w(P, C)|Ws], [w(P, C)|NP], Rest) :-
    en_preposition(P), en_np_words(Ws, NP, Rest), NP \== [], \+ ( NP = [w(V, _)|_], en_verb_form(V, _, _) ), !.
en_np_pps(Ws, [], Ws).

%% the lesson's question word, by its meaning; `which' takes the noun phrase
%% after it, and asks for the object when a name or a pronoun stands alone
%% after the verb (`¿Qué libro lee Maria?'), for the subject otherwise
%% the word the lesson puts before a person, then the question word: a
%% person asked for as the OBJECT -- `¿A quién ve Maria?' is whom, `¿A qué
%% amigo ve Maria?' which friend
fo_question_word([w(P, _), w(Q, C)|Ws], Words, Asked) :-
    tr_marker_word(P),
    tr_solve(mean(Q, E0)), en_question(E0, _), !,
    (   tr_solve(mean(Q, which)), Ws = [W1|_], fo_phrase_word(W1)
    ->  fo_np_words(Ws, NP, Words), Asked = object(which(NP, C))
    ;   Asked = object(w(Q, C)), Words = Ws
    ).
%% A PREPOSITION BEFORE THE QUESTION WORD ASKS FOR AN ADJUNCT: `in che
%% razza di mondo sarei nata?' is in what kind of world I would have been
%% born, and nothing is missing from the clause after it. The preposition
%% and the phrase travel as pp(Preposition, which(Phrase, Case)), whatever
%% word asked -- `che' means `what' in the lesson, and with a phrase after it
%% it is the determiner English writes `which'
%% -- the phrase the words that the lesson reads as one, up to a verb group:
%% the shortest cut took `in che razza di' and the verb `mondo', what
%% `mondare' says of oneself, and never tried the world
fo_question_word([w(P, PC), w(Q, C)|Ws], Words, pp(w(P, PC), which(NP, C))) :-
    tr_is(foreign, w(P, lower), preposition), \+ tr_marker_word(P),
    ( tr_solve(mean(Q, which)) ; tr_solve(mean(Q, what)) ), Ws = [W1|_], fo_phrase_word(W1), !,
    append(NP, Words, Ws), NP \== [], Words \== [],
    tr_group(foreign, Words, [], _, _, _), tr_which_phrase(foreign, NP, _).
fo_question_word([w(Q, C)|Ws], Words, Asked) :-
    %% (the plural of `which' asks too: `Quali sono i cani?' -- `quali' is
    %% no lexeme the lesson gives a meaning, `quale' is)
    ( tr_solve(mean(Q, E0)), en_question(E0, _) -> true ; tr_which_form(Q, _) ), !,
    (   tr_which_asks(Q, Ws),
        fo_np_words(Ws, NP, Rest),
        tr_group(foreign, Rest, [], g(_, _, _, WP, WN), _, After)
    %% (a verb of the first or the second person has no which-phrase for its subject: `Quale libro leggi?'
    %% asks for the book, and as the subject it was `which book reads')
    ->  (   ( fo_lone_subject(After) ; WP \== third ; fo_which_object(NP, WN, After) ) -> Asked = object(which(NP, C)) ; Asked = subject(which(NP, C)) ),
        Words = Rest
    %% ... AND `which' STANDING ALONE: `Quale era allora la materia del
    %% contendere ai tempi di Colombo?' is which was the matter, and with no
    %% phrase after the word -- `era' is an era too, which sent it to the
    %% phrase above, and a word that asks only `which' had no reading of its
    %% own. It travels as whichp(Number, Case), the subject where the verb
    %% after it is a third person in its number and the object otherwise;
    %% each writer gives its own word, a pronoun first (`cuál', `cuáles')
    ;   tr_which_form(Q, N), \+ ( tr_solve(mean(Q, E1)), en_question(E1, K1), K1 \== which )
    ->  (   tr_group(foreign, Ws, [], g(_, _, _, third, N), _, _) -> Asked = subject(whichp(N, C))
        ;   Asked = object(whichp(N, C))
        ),
        Words = Ws
    ;   tr_solve(mean(Q, E)), en_question(E, Kind0), Kind0 \== which, !,
        ( Kind0 == object, fo_asks_subject(Ws) -> Kind = subject ; Kind = Kind0 ),
        Asked =.. [Kind, w(Q, C)], Words = Ws
    ).
%% AN ADVERB THAT JOINS ITS SENTENCE TO THE ONE BEFORE MAY STAND BEFORE THE
%% QUESTION WORD: `Ma allora chi aveva detto sia a Colombo che ai suoi
%% avversari che la terra era sferica?' -- then who had said it. The adverb
%% stays at the head of what is read, where a connecting adverb stays in a
%% statement (frn/1), and the word after it asks as it would at the head;
%% read with the adverb first, no question word stood there and the sentence
%% was refused. (The rest is unfronted here, behind the adverb: `Allora che
%% cosa ha detto il cane?' has its subject after the verb, and with the
%% adverb in front fo_unfront/3 found no clitics before the group to move
%% and the dog was the object of a verb nobody named)
fo_question_word([A|Ws0], [A|Words], Asked) :-
    A = w(AW, _), atom(AW), Ws0 = [w(Q, _)|_], atom(Q),
    tr_solve(mean(Q, E)), en_question(E, _), tr_connective_adverb(foreign, AW),
    fo_question_word(Ws0, W1, Asked), Asked \== none, !,
    fo_unfront(Asked, W1, Words).

%% A SUBJECT, OR A PHRASE SET IN FRONT AND ITS SUBJECT, BEFORE THE QUESTION WORD: `Il cane dove dorme?' is where does
%% the dog sleep, and `Ma la musica italiana Caetano come l'ha scoperta?' how Caetano discovered Italian music -- the
%% lesson's languages may name first what the question is about, and with no question word at the head nothing read.
%% A word that asks for an adjunct (how, where, when, why), after words that read as a subject, or as a phrase and
%% the name or pronoun of its subject, is read as if it stood first, as `Dove il cane dorme?' reads
fo_question_word(Ws0, Words, Asked) :-
    Ws0 = [W1|_], W1 = w(X1, _), atom(X1),
    \+ ( tr_solve(mean(X1, E1)), en_question(E1, _) ), \+ tr_is(foreign, W1, preposition),
    append(Pre, [w(Q, C)|Post], Ws0), Pre = [_|_], Post = [_|_], atom(Q),
    tr_solve(mean(Q, E)), en_question(E, K), memberchk(K, [manner, place, time, reason]),
    length(Pre, LP), LP =< 6, forall(member(X, Pre), X = w(_, _)),
    (   tr_subject(foreign, none, Pre, _, _, _) -> true
    ;   append(NPW, [SW], Pre), NPW = [D|_], tr_determiner(foreign, D, _, _), tr_np(foreign, NPW, _),
        ( tr_name_word(foreign, SW) -> true ; SW = w(SWW, _), atom(SWW), tr_subject_pronoun(foreign, SWW, _, _) )
    ), !,
    append(Pre, Post, Rest), fo_question_word([w(Q, C)|Rest], Words, Asked).
fo_question_word(Ws, Ws, none).
%% WHAT A VERB THAT TAKES NO OBJECT ASKS IS ITS SUBJECT: `Che cosa sarebbe
%% accaduto?' is what would have happened, and a verb whose perfect takes the
%% copula (tr_unaccusative/1) has no object for `what' to be -- asked as the
%% object, the subject was nobody named, and English refused it
fo_asks_subject(Ws) :-
    tr_group(foreign, Ws, [], G, _, _), arg(1, G, L), atom(L), tr_unaccusative(L), !.

fo_phrase_word(W) :- ( tr_is(foreign, W, noun) ; tr_is(foreign, W, adjective) ; tr_determiner(foreign, W, _, _) ), !.

fo_lone_subject([w(W, upper)]) :- \+ tr_known_word(foreign, W), !.
fo_lone_subject([w(W, _)]) :- tr_subject_pronoun(foreign, W, _, _).

%% A PHRASE THE VERB CANNOT AGREE WITH IS NO SUBJECT, AND A DOER IS: `¿Qué libros
%% lee el gato?' asks for the books and the cat reads -- `lee' is a singular and
%% `libros' is not -- where read with the books for its subject it was `which
%% books read the cat'. Where the number decides nothing, the phrase after the
%% verb is the doer when it is animate and the one asked for is not: a name, a
%% pronoun, a noun the lesson calls a person (`"amigo" is a person.') or animate
%% (`"gato" is animate.'), so `¿Qué libro lee el médico?' asks for the book and
%% `¿Qué gato lee el libro?' for the cat. Two animate phrases, or none, are read
%% as they were, the one asked for the subject (`¿Qué perro come el pan?'). The
%% phrase after the verb must be one the verb agrees with, and no name that
%% goes on (`Maria Lopez', `Maria y Pedro': the phrase reader ends a bare name at
%% its first word, and the rest would be an object)
fo_which_object(NP, WN, After) :-
    After = [_|_],
    fo_np_words_after(After, Subject, Rest), Subject \== [],
    \+ fo_name_goes_on(Subject, Rest),
    fo_agreeing(Subject, third, WN),
    (   fo_which_clash(NP, WN)
    ;   \+ fo_animate_phrase(NP), fo_animate_phrase(Subject)
    ), !.

fo_name_goes_on([w(_, upper)], [w(X, upper)|_]) :- \+ tr_known_word(foreign, X), !.
fo_name_goes_on([w(_, upper)], [Co|_]) :- Co = w(_, _), tr_coord(foreign, Co).

%% the phrase asked for has a reading, and none in the verb's number
fo_which_clash(NP, WN) :-
    findall(N, ( tr_np(foreign, NP, X), ( fo_np_number(X, N0) -> N = N0 ; N = unknown ) ), Ns),
    Ns = [_|_],
    \+ ( member(N, Ns), ( N == WN ; N == unknown ) ).

%% a phrase is animate when it is a name or a pronoun, or by its first noun
fo_animate_phrase([w(W, upper)|_]) :- \+ tr_known_word(foreign, W), !.
fo_animate_phrase([w(P, _)|_]) :- tr_subject_pronoun(foreign, P, _, _), !.
fo_animate_phrase(Ws) :-
    member(W, Ws), W = w(X, _), atom(X), tr_is(foreign, W, noun), !,
    tr_lexeme(foreign, X, L, _), ( tr_holds(person(L)) ; tr_holds(animate(L)) ; tr_holds(group(L)) ), !.

%% the noun phrase at the head: a name, a pronoun, or a determiner and its
%% content up to the verb group. THE SHAPE IS TRIED BEFORE THE CUT: a
%% determiner, adjectives, a noun and adjectives with the verb group right
%% after, and only then the shortest head the verb group follows -- because
%% with a vocabulary of thousands of verbs a noun is often a verb's form too
%% (`hermano' is the first person of `hermana', to twin), and the shortest
%% cut put the verb at `hermano' and left `Mi' as the subject.
fo_np_words([w(W, upper)|Rest], [w(W, upper)], Rest) :- \+ tr_known_word(foreign, W), !.
fo_np_words([w(P, C)|Rest], [w(P, C)], Rest) :- tr_subject_pronoun(foreign, P, _, _), !.
fo_np_words(Words, NP, Rest) :-
    Words = [w(D, _)|_], tr_determiner(foreign, w(D, lower), _, _),
    append(NP, Rest, Words), NP = [_|Content], Content \== [],
    tr_np_shape(foreign, Content), tr_group(foreign, Rest, [], _, _, _), !.
fo_np_words(Words, NP, Rest) :- append(NP, Rest, Words), NP \== [], tr_group(foreign, Rest, [], _, _, _), !.
fo_np_words(Words, Words, []).

%% adjectives, one noun, adjectives: the content of a phrase
tr_np_shape(Side, Content) :-
    append(Before, [N|After], Content), tr_is(Side, N, noun),
    forall(member(A, Before), tr_is(Side, A, adjective)),
    forall(member(A, After), tr_is(Side, A, adjective)), !.

%% a verb that came first takes its subject from after it: a bare adjective
%% right after the verb is the complement and the subject follows it
%% (`¿Es grande la casa?'); otherwise the first phrase, a name or a pronoun
fo_unfront(subject(_), Ws, Ws) :- !.
fo_unfront(_, Words, Words1) :-
    tr_negation(foreign, Words, W1, Neg),
    tr_group(foreign, W1, Before, g(GL, _, _, P, N), Group, After),
    tr_split_clitics(foreign, Before, fronted, _, _, [], Clitics), !,
    (   fo_inf_subject_verb(GL), After = [w(V, _)|_], atom(V), tr_solve(infinitive_of(V, F)), tr_known(foreign, F)
    ->  Subject0 = [], Rest0 = After
    ;   fo_subject_after(After, P, N, Subject0, Rest0)
    ),
    ( Subject0 == [], fo_adverb_subject(After, P, N, Subject, Rest) -> true ; Subject = Subject0, Rest = Rest0 ),
    append(Subject, Clitics, S1), append(S1, Group, S2), append(S2, Rest, W2),
    ( Neg == yes -> tr_negation_word(No), Words1 = [w(No, lower)|W2] ; Words1 = W2 ).
fo_unfront(_, Ws, Ws).

%% A QUESTION'S ADVERB BETWEEN THE VERB AND ITS SUBJECT STAYS WHERE IT IS:
%% `Che dovrebbe fare, allora, Berlusconi?' is what should Berlusconi do, then
%% -- with the adverb in the way nothing agreed after the verb, and Berlusconi
%% was the object, `¿Qué debería hacer entonces a Berlusconi?', a third person
%% nobody named that English refused. Only where a subject that agrees follows
%% it, and only in a question (fo_unfront/3): a statement's inverted subject
%% after an adverb is read by its own readers, `Fue entonces el momento de
%% homenajear ...', and with this rule there `the moment went moment of honouring'
fo_adverb_subject([w(V, C)|After], P, N, Subject, [w(V, C)|Rest]) :-
    atom(V), tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !, fo_adverb_subject(After, P, N, Subject, Rest).
fo_adverb_subject([A|After], P, N, Subject, [A|Rest]) :-
    fo_adverb_word(A), After = [_|_], fo_subject_after(After, P, N, Subject, Rest), Subject \== [], !.

%% A VERB WHOSE SUBJECT IS AN INFINITIVE HAS NONE AFTER IT: `Quanto costa mantenere un figlio?' is how much it costs to
%% keep a son, and the phrase after the infinitive was taken for the verb's subject, as it is after a modal (`¿Quiere
%% comer Maria?') -- `How much does a son cost to keep?'. The verb of costing
fo_inf_subject_verb(L) :- atom(L), once(tr_solve(mean(L, costs))), !.
%% what follows the verb is its subject only when it agrees with it: after
%% `¿Comes ...?' nothing does, and the verb says who
fo_subject_after([A|After], P, N, Subject, [A]) :-
    tr_is(foreign, A, adjective), After \== [], fo_agreeing(After, P, N), !, Subject = After.
%% an infinitive between the verb and its subject stays where it is
%% (`¿Quiere comer Maria?'): it is no subject
fo_subject_after([w(V, C)|After], P, N, Subject, [w(V, C)|Rest]) :-
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !, fo_subject_after(After, P, N, Subject, Rest).
fo_subject_after(After, P, N, Subject, Rest) :-
    fo_np_words_after(After, Subject0, Rest0), Subject0 \== [], fo_agreeing(Subject0, P, N), !,
    Subject = Subject0, Rest = Rest0.
fo_subject_after(After, _, _, [], After).

%% (an adverb the lesson knows as nothing else)
fo_adverb_word(w(X, _)) :- atom(X), tr_is(foreign, w(X, lower), adverb), \+ tr_is(foreign, w(X, lower), noun),
    \+ tr_is(foreign, w(X, lower), adjective), \+ tr_verb_form_word(X), !.
fo_agreeing([w(W, _)], P, N) :- tr_subject_pronoun(foreign, W, P1, N1), !, P1 == P, N1 == N.
fo_agreeing([w(W, upper)], P, N) :- \+ tr_known_word(foreign, W), !, P == third, N == singular.
fo_agreeing(Words, third, N) :- tr_np(foreign, Words, NP), !, fo_np_number(NP, N1), N1 == N.
%% ... and a list that begins with its own connector is the list after it
fo_agreeing([w(C, _)|Words], third, plural) :- tr_neither_word(C), fo_agreeing(Words, third, plural), !.
%% two phrases joined are plural: `ritrovati vivi donna e bimbi scomparsi'
%% -- and three, the second half a list itself: `ni Rivaldo ni Overmars ni
%% De la Peña'
fo_agreeing(Words, third, plural) :-
    tr_conjunction_split(foreign, Words, W1, W2), tr_np(foreign, W1, _),
    ( tr_np(foreign, W2, _) -> true ; fo_agreeing(W2, third, plural) ), !.

%% a phrase's number, through a reduced relative to the phrase it sits on --
%% `il coprifuoco imposto dai soldati' is singular, and without this clause
%% a rel/3 matched no np/5 and an inverted subject with a participle after
%% it was refused
fo_np_number(rel(NP, _, _), N) :- !, fo_np_number(NP, N).
fo_np_number(all(_, NP), N) :- !, fo_np_number(NP, N).
fo_np_number(app(NP, _, _), N) :- !, fo_np_number(NP, N).
%% ... and through the phrases that say which, to the noun they are said of (`páginas en castellano abiertas por
%% miembros', a participle on a noun and its phrase)
fo_np_number(with(NP, _), N) :- !, fo_np_number(NP, N).
fo_np_number(np(_, _, _, _, N), N).
%% ... and a phrase whose noun was left out is in the number it states (a
%% ratio, `un nucleo ogni venti', tr_np/3)
fo_np_number(ell(_, _, N, _), N).
%% ... and a name is one, a capitalised word the lesson knows included
%% (tr_np/3 reads `va via Pellegrini' so): the plural of `pellegrino' it
%% also is said nothing of the man
fo_np_number(name(_), singular).

%% the subject after the verb: a name, a pronoun, or a phrase up to the next
%% determiner, name, pronoun or preposition
%% A REDUCED RELATIVE AND ITS AGENT STAY INSIDE THE SUBJECT, as they do in
%% tr_phrase_words/4 for a phrase before the verb: `Qui dominava il
%% coprifuoco imposto dai soldati' is the curfew-that-was-imposed
%% dominating, and the agent belongs to the participle rather than to the
%% sentence's verb.
%% A RATIO IS ONE PHRASE, whole: `Resta nell'indigenza un nucleo ogni venti'
%% -- the subject ended at `un nucleo' and `ogni venti' were read as a
%% phrase of their own, each winds (tr_np/3 has the ratio).
fo_np_words_after([D, N, R, M|Rest], [D, N, R, M], Rest) :-
    tr_ratio_count(M), D = w(_, _), tr_indefinite(foreign, D), tr_np(foreign, [D, N, R, M], ell(_, _, _, pp(_, _))), !.
fo_np_words_after(Words, Content, Rest) :-
    append(PW0, Rest0, Words), PW0 \== [],
    last(PW0, w(P, _)), tr_participle_here(foreign, P, _),
    Rest0 = [B|_], tr_is(foreign, B, preposition), tr_means_by(foreign, B),
    tr_reduced_agent(foreign, Rest0, _), !,
    append(PW0, Rest0, Content), Rest = [].
%% ... and a participle with a NAME after it, the whole name: `destaca un
%% violín llamado Ex Von Szerdahely VieuxTemps' ended the subject at the
%% first capitalised word the lesson does not know, which is `Von'
fo_np_words_after(Words, Content, Rest) :-
    append(PW0, Rest0, Words), PW0 = [_, _|_],
    last(PW0, w(P, _)), tr_participle_here(foreign, P, _),
    tr_cap_run(Rest0, NameWs, Rest1), NameWs \== [],
    tr_reduced_agent(foreign, NameWs, [obj(name(_))]), !,
    %% ... and what stands aside after the name is the phrase's too
    ( Rest1 = [w(K, aside)|Rest] -> append(NameWs, [w(K, aside)], NameWs1) ; NameWs1 = NameWs, Rest = Rest1 ),
    append(PW0, NameWs1, Content).
fo_np_words_after([w(W, upper)|Rest], [w(W, upper)], Rest) :- \+ tr_known_word(foreign, W), !.
fo_np_words_after([w(P, C)|Rest], [w(P, C)], Rest) :- tr_subject_pronoun(foreign, P, _, _), !.
%% A DETERMINER AND A RUN OF NAME WORDS IS ONE PHRASE, whole. The clause
%% below ends a phrase at the next capitalised unknown word, which is right
%% for `Maria' and wrong inside `la Tate Gallery' -- measured, the subject
%% came back `la Tate' with `Gallery' left over as the object.
fo_np_words_after([D|After], [D|Content], Rest) :-
    tr_determiner(foreign, D, _, _), After = [W|_], tr_name_word(foreign, W), !,
    tr_name_run(After, Content, Rest).
%% ... AND A RUN OF CAPITALISED WORDS THE PHRASE READER TAKES FOR A NAME,
%% though the lesson knows its first word: `Evacuata la Tate Gallery.' ended
%% its subject at `Tate' -- the plural of `tata' since the babysitter came
%% into the lesson -- and `la Tate' alone has no reading, so the headline was
%% refused on the full store where `La Tate Gallery è stata evacuata.' read
fo_np_words_after([D|After], [D|Run], Rest) :-
    tr_determiner(foreign, D, _, _), After = [w(_, upper), w(_, upper)|_],
    tr_cap_run(After, Run, Rest),
    tr_np(foreign, [D|Run], np(_, _, _, named(_, _), _)), !.
%% ... AND A TITLE AND THE NAME AFTER IT: `Ne fa testo il dott Di Pietro' is
%% the doctor named, and the phrase ended at `dott' and left the name to the
%% verb, an object of a verb that takes none (`"dott" is a title.')
fo_np_words_after([D, T|After], [D, T|Name], Rest) :-
    tr_determiner(foreign, D, _, _), T = w(TW, _), tr_lexeme(foreign, TW, TL, _), tr_holds(title(TL)),
    After = [W|_], tr_name_word(foreign, W), !,
    tr_name_run(After, Name, Rest).
fo_np_words_after([D|After], [D|Content], Rest) :-
    tr_determiner(foreign, D, _, _), !,
    append(Content, Rest, After), Content \== [],
    %% (a phrase does not end on its coordinator: `il nuovo e diverso
    %% approccio' ended at `e', because `diverso' is the determiner `several'
    %% too and seemed to start a phrase, and the subject was refused)
    \+ ( last(Content, Co), Co = w(_, _), tr_coord(foreign, Co) ),
    ( Rest == [] -> true ; Rest = [R|Next], ( fo_phrase_starts(R) ; fo_adverb_ends(R, Next) ) ), !.
%% ... AND A BARE NOUN BEFORE A PHRASE OF A PREPOSITION (NOT `OF') IS THE SUBJECT
%% ALONE: `no existía consenso entre los profesionales' -- the consensus did not
%% exist, among the professionals; the catch-all below took the whole run for
%% the subject, which agrees with nothing, and the verb was read as a command
fo_np_words_after([W, P|After], [W], [P|After]) :-
    W = w(_, _), P = w(_, _), tr_is(foreign, P, preposition), \+ tr_means_of(foreign, P),
    \+ tr_determiner(foreign, W, _, _), tr_is(foreign, W, noun), !.
fo_np_words_after(Words, Words, []).

%% A WORD THAT IS A PREPOSITION OR AN ADVERB AND AN ADJECTIVE, AFTER A NOUN
%% AND WITH NOTHING AFTER IT BUT A COMMA OR THE END, IS THE PHRASE'S
%% ADJECTIVE: `in un paese vicino' is a town nearby, and ended at `vicino' --
%% `near' to the vocabulary before it is `close' -- the phrase left the word
%% to stand alone as an adverb, and Spanish wrote `en un país cerca'
%% -- and one that AGREES with the noun: `il giorno prima' is the day
%% before, and `prima' the feminine of `first' (1.8.6's rule, the adverb)
tr_final_adjective(Side, PW, [R|After]) :-
    PW \== [], ( After == [] ; After = [comma|_] ),
    tr_is(Side, R, adjective), once(( member(X, PW), tr_is(Side, X, noun) )),
    last(PW, N), N = w(_, _), tr_is(Side, N, noun), tr_aside_agrees(N, R).

%% AN ADJECTIVE THAT IS AN ADVERB TOO, RIGHT AFTER THE NOUN IT AGREES WITH AND
%% BEFORE AN `of' PHRASE, IS THE NOUN'S: `con allungamento certo dei tempi del
%% processo' is a certain lengthening of the times, and `certo' is the adverb
%% `certainly' as well. The phrase ended at `allungamento' and the adverb
%% went to the clause -- `alargamiento ciertamente de los tiempos' -- where an
%% adjective `grande' or `importante' stayed with its noun. Nothing else
%% follows an adverb there: an adverb before an `of' phrase is rare, and the
%% adjective is what agrees
tr_adjective_before_of(Side, PW, [R, P|_]) :-
    R = w(_, _), P = w(_, _), PW \== [],
    tr_means_of(Side, P), tr_is(Side, R, adjective),
    last(PW, N), N = w(_, _), tr_is(Side, N, noun), tr_aside_agrees(N, R).

fo_phrase_starts(w(W, upper)) :- \+ tr_known_word(foreign, W), !.
fo_phrase_starts(R) :- ( tr_determiner(foreign, R, _, _) ; tr_is(foreign, R, preposition) ; tr_subject_pronoun(foreign, R, _, _) ), !.
%% ... and a GERUND ends the phrase before it: `Mi si è stretto il cuore
%% leggendo nella cronaca ...' is the heart, and what it did while reading.
%% Taken into the phrase, `il cuore leggendo' was no phrase at all, no
%% subject was found after the verb, and the heart read as its object
fo_phrase_starts(w(G, _)) :- tr_gerund_here(foreign, G, _), !.
%% ... and the word of a clause that says where or when: `Penalizzati anche i
%% nuclei dove è minore l'istruzione' is the households, and where the schooling
%% is less -- the clause is the sentence's, as it is after `Sono penalizzati i
%% nuclei dove ...', and taken into the phrase the headline was refused
fo_phrase_starts(w(W, _)) :- atom(W), tr_indirect_word(foreign, W, Q), memberchk(Q, [where, when]), !.
%% ... and an adverb that is nothing else: `Come nasce una sentenza così?' is
%% how a sentence is born, thus, and `Nasce una sentenza oggi' says when. The
%% phrase ran on over the adverb, `una sentenza così' was no phrase, no
%% subject was found after the verb, and English refused the sentence (the
%% object of a verb that takes none). A word that is a noun, an adjective
%% or a preposition too may belong to the phrase (`il giorno prima')
fo_adverb_ends(R, Next) :-
    R = w(W, _), atom(W), tr_is(foreign, R, adverb),
    \+ tr_is(foreign, R, noun), \+ tr_is(foreign, R, adjective), \+ tr_is(foreign, R, preposition),
    %% (and not before an adjective or a participle, which it grades: `la stampa
    %% piuttosto tiepida' is one phrase)
    \+ ( Next = [w(NW, _)|_], atom(NW), ( tr_is(foreign, w(NW, lower), adjective) ; tr_participle_here(foreign, NW, _) ) ), !.

%% ---- reading: the statement -------------------------------------------------------

%% s(Asked, Subject, Group, Complements): the denial off, the verb group
%% found, the subject before it (with the object pronouns that stand
%% before the verb taken out), the complements after it
%% A STATEMENT THAT FAILED TO READ FAILS AGAIN, as a piece does (tr_read/4):
%% the fronted reading tries every front and the division every comma, and
%% each of them asks for the same run of words as a statement over and over.
%% Measured on `Di certo si sa solo che la famiglia era ... e mentre il
%% compagno della donna, Emanuele Tornaboni, era in pista a sciare, la madre
%% si è allontanata con i bambini': 171 statement readings, 35 of them
%% distinct, 35 s. Every clause below cuts, so a statement has one reading
%% and there is nothing to keep but the failures.
tr_read_statement(Side, Words, Asked, S) :-
    (   ground(Words-Asked)
    ->  Key = rs(Side, Words, Asked), tr_failed_set(F0),
        (   get_assoc(Key, F0, _) -> fail
        ;   tr_read_statement0(Side, Words, Asked, S0), \+ tr_there_is_somebody(S0), \+ tr_adjective_not_verb(Side, Words, S0) -> tr_duty_fix(S0, S01), tr_cleft_fix(Side, S01, S02), tr_infs_fix(Side, S02, S02a), tr_all_copula_fix(Side, S02a, S03), tr_modal_se_fix(Side, S03, S03a), tr_dative_double_fix(Side, S03a, S03b), tr_ident_fix(Side, S03b, S03c), tr_nounobj_fix(Side, S03c, S04), tr_dislocation_fix(Side, S04, S04a), tr_passive_subject_fix(Side, S04a, S04b), tr_aside_head_fix(Side, S04b, S04c), tr_saying_that_fix(Side, S04c, S1), tr_vq_add(Side, Words, S1, S)
        ;   tr_failed_set(F1), put_assoc(Key, F1, x, F2), nb_setval('$tr_failed', F2), fail
        )
    ;   tr_read_statement0(Side, Words, Asked, S0), \+ tr_there_is_somebody(S0), \+ tr_adjective_not_verb(Side, Words, S0), tr_duty_fix(S0, S01), tr_cleft_fix(Side, S01, S02), tr_infs_fix(Side, S02, S02a), tr_all_copula_fix(Side, S02a, S03), tr_modal_se_fix(Side, S03, S03a), tr_dative_double_fix(Side, S03a, S03b), tr_ident_fix(Side, S03b, S03c), tr_nounobj_fix(Side, S03c, S04), tr_dislocation_fix(Side, S04, S04a), tr_passive_subject_fix(Side, S04a, S04b), tr_aside_head_fix(Side, S04b, S04c), tr_saying_that_fix(Side, S04c, S1), tr_vq_add(Side, Words, S1, S)
    ).

%% THE INFINITIVE OF A VERB THAT TAKES NO OBJECT, WITH ITS PHRASE OF `OF', IS A CLAUSE OF `AS': `E al crescere del
%% reddito il conto sale' -- the bill rises as the income grows, and `con l'aumentare del reddito familiare cresce la
%% spesa' as the family income increases. Read as a phrase, the infinitive was a noun and the phrase of `of' the
%% clause's own: `the account rises to the growing of the income', Spanish `con aumentar del ingreso'. After the word
%% for `to' or for `with', a verb the lesson calls intransitive or one whose auxiliary is the copula, and the phrase of
%% `of' right after it, which is its subject; the clause takes the main clause's tense, and every writer puts it after
%% the main clause with its word for `as' (`man mano che', `a medida que')
%% A WORD AFTER A NOUN THAT IS ITS ADJECTIVE AS WELL AS A VERB, WITH NOTHING AFTER IT BUT A COMMA, IS THE ADJECTIVE: `Una
%% spesa media, per una famiglia dell'Italia centrale ...' is an average expense, and read as the verb `media'
%% (mediates) the expense mediated, for a family. A determiner, the noun, the word in its gender and number, and the comma,
%% at the head of the piece, with the comma the first thing after the verb
%% (the piece is asked, which keeps its commas: the reading that took the comma out read the same words)
%% -- AND ONLY WHERE THE WORD IS THE VERB THE READING TOOK: `Ningún deportista español, ni ninguna federación, envía
%% muestras' opens on a determiner, a noun and its adjective before a comma too, and its verb is `envía'; refused for
%% the shape alone, the sentence had no reading
tr_adjective_not_verb(foreign, [D, N, w(V, VC)|_], s(_, _, g(L, _, simple, no), _)) :-
    atom(L), atom(V), tr_form(V, L, _, _, _),
    tr_global('$tr_piece', [D0, N0, w(V, _), comma|_]), D0 == D, N0 == N,
    tr_determiner(foreign, D, _, _), tr_is(foreign, N, noun), atom(V), tr_is(foreign, w(V, lower), adjective),
    tr_aside_agrees(N, w(V, VC)), !.
%% ... AND A LAST WORD THAT IS A NOUN AS WELL AS A VERB, AFTER AN ADJECTIVE IT AGREES WITH, IS THE NOUN: `E per almeno
%% cinque buone ragioni:' is for five good reasons, and read as `ragioni' (you reason) with nobody named, the five were
%% goods. The word ends the piece, and the adjective stands before it there (the front the reader set apart is no
%% part of the words a statement is read from)
tr_adjective_not_verb(foreign, Words, s(_, null(_, _), g(L, _, _, _), _)) :-
    last(Words, w(V, VC)), atom(V), atom(L), tr_form(V, L, _, _, _),
    tr_global('$tr_piece', Piece), append(_, [A, w(V, _)|After], Piece), ( After == [] -> true ; After = [M|_], atom(M) ),
    A = w(AW, _), atom(AW), tr_is(foreign, A, adjective),
    tr_is(foreign, w(V, lower), noun), tr_aside_agrees(w(V, VC), A), !.
%% (the sentence's own clauses, the halves of a join, as the polite wish's: tr_into_ir/4)
tr_as_inf_pass(foreign, join(C, S1, S2), join(C, T1, T2)) :- !, tr_as_inf_pass(foreign, S1, T1), tr_as_inf_pass(foreign, S2, T2).
tr_as_inf_pass(foreign, S0, S) :- !, tr_as_inf_fix(foreign, S0, S).
tr_as_inf_pass(_, S, S).
tr_as_inf_fix(foreign, s(A, Su, G, Cs0), join(asinf(lower), s(A, Su, G, Cs), s(none, NP, g(L, T, simple, no), []))) :-
    G = g(_, T, _, _), atom(T),
    append(Pre, [I, pp(P2, NP)|Post], Cs0), tr_as_infinitive(I, L),
    NP = np(_, _, _, _, _), tr_means_of(foreign, P2),
    ( tr_intransitive_meanings(L, _) -> true ; tr_unaccusative(L) ), !,
    append(Pre, Post, Cs).
tr_as_inf_fix(_, S, S).
tr_as_infinitive(pp(w(P, _), ninf(L)), L) :- atom(P), atom(L), tr_lexeme(foreign, P, PL, _), once(tr_solve(mean(PL, to))), !.
tr_as_infinitive(pinf(w(P, _), L), L) :- atom(P), atom(L), tr_lexeme(foreign, P, PL, _), once(tr_solve(mean(PL, with))), !.

%% A PASSIVE WITH NOBODY NAMED HAS ITS SUBJECT AFTER IT, where a phrase that agrees with it stands
%% where an object would: `vengono vietati ai turisti i mezzi a motore' -- the motor vehicles are
%% forbidden to the tourists, and read as an object English wrote `they are forbidden to the tourists
%% the motor vehicles'. The subject keeps its place, subj_here, for a writer that keeps the order.
%% The phrases of `of' right after the phrase go with it: `siano esclusi ... anche i veicoli (uno
%% per nucleo familiare) di persone che ...' -- the vehicles OF PEOPLE who pay the tax, and left among
%% the complements English wrote them after the ban
tr_passive_subject_fix(foreign, s(A, null(third, N), g(L, T, Asp, Neg), Cs0), s(A, Su, g(L, T, Asp, Neg), Cs)) :-
    memberchk(Asp, [passive, passive_perfect]), \+ memberchk(subj_here, Cs0),
    append(Pre, [obj(NP)|Post0], Cs0), \+ memberchk(obj(_), Pre), fo_np_number(NP, N), !,
    tr_fo_of_run(Post0, Ofs, Post), ( Ofs == [] -> Su = NP ; Su = with(NP, Ofs) ),
    append(Pre, [subj_here|Post], Cs).
%% ... AND A PHRASE AFTER THE COMMA THAT CLOSES THE SUBJECT SET AFTER A PASSIVE VERB IS THE SUBJECT'S APPOSITION: `Sarà
%% ascoltato il dottor Lombardi, il primo medico ad intervenire dopo la tragedia' -- the doctor, the first to arrive. A
%% passive takes no object, and read as one the apposition came out `al primer médico' and `to the first doctor'. It is
%% appos/1, as a reporting clause's is (tr_report_appos/2), which every writer sets after the subject
tr_passive_subject_fix(foreign, s(A, Su, g(L, T, Asp, Neg), Cs0), s(A, Su, g(L, T, Asp, Neg), Cs)) :-
    memberchk(Asp, [passive, passive_perfect]), Su \= null(_, _),
    append(Pre, [subj_here, sep, obj(NP)|Tail], Cs0), ( NP = name(_) ; NP = np(_, _, _, _, _) ), !,
    append(Pre, [subj_here, sep, appos(NP)|Tail], Cs).
tr_passive_subject_fix(_, S, S).
%% (the phrases of the word for `of' at the head of a list of the source's complements, and the rest)
tr_fo_of_run([PP|Cs0], [PP|Ofs], Cs) :- PP = pp(P, _), tr_means_of(foreign, P), !, tr_fo_of_run(Cs0, Ofs, Cs).
tr_fo_of_run(Cs, [], Cs).

%% A QUOTATION THAT OPENS ON THE VERB: `proclamar que su partido "había
%% obtenido sus objetivos electorales"' quotes from the auxiliary on, and the
%% mark travelled on a word the verb group took, which keeps no case -- so
%% the Italian closed a quotation it never opened. When the opening mark
%% stood on a verb's form, a denial or a clitic -- the reflexive among them:
%% `reconoció que las dos partes "se encuentran en sus respectivas
%% posiciones"' -- and nothing in the reading
%% kept it, the clause carries vq, which every writer puts back on the first
%% word of its verb group.
tr_vq_add(Side, Words, S0, S) :- tr_vq_open(Side, Words, S0, S1), tr_vq_close(Side, Words, S1, S).
%% A QUOTATION THAT OPENS ON AN ADJUNCT THE WRITER MOVES: `L'auspicio è che
%% "almeno per una volta il governo sia capace di ascoltare il presidente"'
%% -- the clause begins with its adjuncts, which are written after it, and
%% the mark went with them: `... al presidente" "al menos para una vez'. When
%% the opening mark stood on the clause's first word and nothing in the
%% subject holds it, it is the CLAUSE'S: the word gives it up, and the
%% clause carries qs, which every writer puts back on the first word it
%% writes.
tr_vq_open(foreign, Words, S0, S) :- tr_clause_marks(Words, S0, S), !.
%% A VERB ALONE BETWEEN MARKS keeps both: `"Escucho", dijo el presidente' --
%% the quotation is the whole clause, which every writer marks on the first
%% word it writes and the last (qs and qe): English's `I' is the clause's
%% first word, and the mark on the verb alone was `I "listen"'
tr_vq_open(foreign, [w(QW, qboth)], S0, S) :-
    S0 = s(A, Su, G, Cs), atom(QW), tr_verb_form_word(QW), \+ tr_has_mark(S0), \+ tr_has_close_mark(S0), !,
    S = s(A, Su, G, [qs, qe|Cs]).
tr_vq_open(foreign, Words, S0, S) :-
    memberchk(w(_, qopen), Words), S0 = s(A, Su, G, Cs),
    append(_, [w(QW, qopen)|_], Words),
    ( tr_verb_form_word(QW) ; tr_negation_word(QW) ; tr_object_pronoun(foreign, QW, _) ; tr_reflexive_word(QW) ),
    \+ tr_has_mark(S0), !,
    S = s(A, Su, G, [vq|Cs]).
%% ... AND ONE THAT OPENS ON A PASSIVE'S PARTICIPLE: `aseguró que sus emisoras
%% y los profesionales están "preparados para la radio del 2000"' quotes from
%% the participle on, the second word of the verb group, and the mark was
%% lost with the group's case. The clause carries vqp, which every writer
%% puts back on the LAST word of its verb group, the participle.
tr_vq_open(foreign, Words, S0, S) :-
    S0 = s(A, Su, G, Cs),
    G = g(_, _, Asp, _), memberchk(Asp, [passive, passive_perfect]),
    append(_, [w(QW, QC)|_], Words), memberchk(QC, [qopen, qboth]), tr_participle_here(foreign, QW, _),
    tr_open_marks_missing(Words, S0), !,
    S = s(A, Su, G, [vqp|Cs]).
%% ... and on a progressive's gerund, the last word of its group too: `están
%% "sufriendo"' came out `stanno soffrendo', the marks lost
tr_vq_open(foreign, Words, S0, S) :-
    S0 = s(A, Su, G, Cs), G = g(_, _, progressive, _),
    append(_, [w(QW, QC)|_], Words), memberchk(QC, [qopen, qboth]), atom(QW), tr_solve(gerund_of(QW, _)),
    tr_open_marks_missing(Words, S0), !,
    S = s(A, Su, G, [vqp|Cs]).
tr_vq_open(_, _, S, S).
%% (the closing mark is the clause's too when it stood on the clause's last
%% word: the adjuncts written after the clause come before it, `... al
%% presidente al menos para una vez"', where they had been left outside)
tr_clause_marks(Words, s(A, Su, G, Cs0), s(A, Su1, G, Cs)) :-
    Words = [w(_, QC), _|_], memberchk(QC, [qopen, qboth]),
    \+ tr_has_mark(Su), \+ memberchk(vq, Cs0), \+ memberchk(vqp, Cs0),
    tr_has_mark(Cs0), tr_strip_open(Cs0, Cs1),
    (   last(Words, w(_, QE)), memberchk(QE, [qclose, qboth])
    ->  (   tr_strip_close([Su|Cs1], [Su1|Cs2]) -> Cs = [qs, qe|Cs2]
        %% (or on the verb group's own last word, `"nella casa il gatto
        %% dorme"': nothing in the terms holds it, and the adjunct is
        %% written after the verb, so the mark is the clause's too)
        ;   Su1 = Su, ( selectchk(vqc, Cs1, Cs2) -> true ; Cs2 = Cs1 ), Cs = [qs, qe|Cs2]
        )
    ;   Su1 = Su, Cs = [qs|Cs1]
    ).
%% ... AND ONE THAT CLOSES ON IT: `que "el presidente del Gobierno se
%% alegra" de que haya progresado' quotes to the verb, and the clause after
%% the mark is the verb's own. The mark travelled on the verb's form, which
%% keeps no case, so the quotation opened and never closed. The clause
%% carries vqc, which every writer puts back on the LAST word of its verb
%% group.
%% ... BUT A MARK THAT CLOSES ON AN INFINITIVE THE CLAUSE ENDS ON CLOSES WHERE THE CLAUSE ENDS: `"No he vuelto a la
%% playa, y por ahora no pienso hacerlo", sostiene Rebeca López' -- put on the verb group, the mark came out after the
%% verb, `"I do not think" to make him'. The clause carries qe, which the writers put on the last word it writes
tr_vq_close(foreign, Words, s(A, Su, G, Cs), s(A, Su, G, [qe|Cs])) :-
    append(_, [w(QW, qclose)|Tail], Words), forall(member(T, Tail), T = w(_, enclitic)), atom(QW), tr_solve(infinitive_of(QW, _)),
    last(Cs, Last), ( Last = inf(_) ; Last = infx(_, _, _) ), \+ memberchk(qe, Cs), !.
tr_vq_close(foreign, Words, S0, S) :-
    S0 = s(A, Su, G, Cs),
    append(_, [w(QW, QC)|_], Words),
    ( QC == qclose ; QC == qboth, atom(QW), ( tr_solve(gerund_of(QW, _)) ; tr_participle_here(foreign, QW, _) ) ),
    %% (or a gerund, the last word of a progressive: `"la movida que está
    %% montando" el sector renovador' closed on it and lost the mark)
    ( tr_verb_form_word(QW) ; tr_participle_here(foreign, QW, _) ; tr_solve(infinitive_of(QW, _)) ; tr_solve(gerund_of(QW, _)) ),
    \+ tr_has_close_mark(S0), !,
    S = s(A, Su, G, [vqc|Cs]).
tr_vq_close(_, _, S, S).
tr_has_close_mark(vqc) :- !.
tr_has_close_mark(qe) :- !.
tr_has_close_mark(w(_, C)) :- atom(C), memberchk(C, [qclose, qboth]), !.
%% (a participle's own mark too: `i magistrati di "mani pulite"' closes on the
%% participle of a phrase, and a second mark went on the clause's verb)
tr_has_close_mark(pcase(C)) :- atom(C), memberchk(C, [qclose, qboth]), !.
%% (and a purpose's own, qm2/2 on its infinitive)
tr_has_close_mark(qm2(C, _)) :- atom(C), memberchk(C, [qclose, qboth]), !.
%% (and a participle's said of the subject, predq/2: `sottolineo "osato"',
%% the writer's comment, closes on its participle, and a second mark went on
%% the comment's verb, `subrayo" "osado"')
tr_has_close_mark(predq(_, C)) :- atom(C), memberchk(C, [qclose, qboth]), !.
tr_has_close_mark(T) :- compound(T), T =.. [_|As], member(A, As), tr_has_close_mark(A), !.
%% the mark that opens a quotation, put on the first word of a term when it is a
%% plain one (the term's words stand in the order they are written)
tr_open_first(T0, T) :- tr_first_word(T0, w(_, lower)), tr_strip_mark(open_first, T0, T).
tr_first_word(w(W, C), w(W, C)) :- !.
tr_first_word(T, X) :- compound(T), T =.. [_|As], member(A, As), tr_first_word(A, X), !.

%% the first opening or closing mark in a term, given up by its word
tr_strip_open(T0, T) :- tr_strip_mark(open, T0, T).
tr_strip_close(T0, T) :- tr_strip_mark(close, T0, T).
tr_strip_mark(K, T0, T) :- tr_strip0(K, T0, T, done), !.
tr_strip0(open, w(W, qopen), w(W, lower), done) :- !.
tr_strip0(open_first, w(W, lower), w(W, qopen), done) :- !.
tr_strip0(open, w(W, qboth), w(W, qclose), done) :- !.
tr_strip0(close, w(W, qclose), w(W, lower), done) :- !.
tr_strip0(close, w(W, qboth), w(W, qopen), done) :- !.
%% (a closing mark a nested clause carries on its verb group, vqc, is given up
%% too: the clause's own closing mark is written on the last word of ALL it
%% writes, and with both the quotation closed twice)
tr_strip0(close, [vqc|Xs], Xs, done) :- !.
tr_strip0(K, [X|Xs], [Y|Ys], done) :- !,
    (   tr_strip0(K, X, Y, done) -> Ys = Xs
    ;   Y = X, tr_strip0(K, Xs, Ys, done)
    ).
tr_strip0(K, T0, T, done) :- compound(T0), T0 =.. [F|As0], As0 \== [], !,
    tr_strip_args(K, As0, As), T =.. [F|As].
tr_strip_args(K, [A0|As0], [A|As]) :-
    (   tr_strip0(K, A0, A, done) -> As = As0
    ;   A = A0, tr_strip_args(K, As0, As)
    ).
%% an opening mark in the words that no term of the reading carries: a
%% clause may quote twice, `está "abierto a cualquier negociación" con la
%% oposición con el fin de "encontrar una solución ..."', and with the second
%% carried by the purpose the first was taken as carried too and lost
tr_open_marks_missing(Words, S0) :-
    aggregate_all(count, ( member(w(_, C), Words), memberchk(C, [qopen, qboth, qopenu, qbothu]) ), NW),
    tr_open_marks(S0, NS), NS < NW.
tr_open_marks(T, N) :- tr_open_marks(T, 0, N).
tr_open_marks(T, N0, N) :- var(T), !, N = N0.
tr_open_marks(w(_, C), N0, N) :- !, ( atom(C), memberchk(C, [qopen, qboth, qopenu, qbothu]) -> N is N0 + 1 ; N = N0 ).
%% (a case the reading kept as an atom is a mark carried too: which_np/2's
%% second argument, qm/2's first)
tr_open_marks(T, N0, N) :- atom(T), !,
    ( memberchk(T, [vq, vqp, qs, qopen, qboth, qopenu, qbothu]) -> N is N0 + 1 ; N = N0 ).
tr_open_marks(T, N0, N) :- compound(T), !,
    T =.. [_|As], foldl(tr_open_marks_fold, As, N0, N).
tr_open_marks(_, N, N).
tr_open_marks_fold(A, N0, N) :- tr_open_marks(A, N0, N).
tr_has_mark(vq) :- !.
tr_has_mark(qm(_, _)) :- !.
tr_has_mark(qm2(_, _)) :- !.
tr_has_mark(qinf(_, _)) :- !.
tr_has_mark(vqp) :- !.
tr_has_mark(w(_, C)) :- atom(C), memberchk(C, [qopen, qboth]), !.
tr_has_mark(T) :- compound(T), T =.. [_|As], member(A, As), tr_has_mark(A), !.

%% what must be done, as English reads `must be activated': the modal the
%% lesson gives for `must', the copula's infinitive and the participle
tr_duty_fix(s(A, Su, g(L, T, duty, Neg), Cs), s(A, Su, g(M, T, simple, Neg), [inf(C), pred(L)|Cs])) :- !,
    once(( tr_solve(mean(M, must)), tr_class_of(M, modal) )), tr_copula_lexeme(C).
tr_duty_fix(S, S).

%% WHAT A COPULA WITH NOBODY BEFORE IT HAS LAST IS ITS SUBJECT: `Es la
%% posibilidad de aumentar la libertad ... lo que los hace tan deseados' --
%% it is the possibility that makes them so desired, the thing that makes
%% them desired being what the sentence is about. Read left to right it was
%% a copula with nobody named and two objects, which Italian wrote back in
%% the order it stood and English, having nobody to put first, refused. A
%% phrase whose noun a relative clause stands for, last after something the
%% copula says, is the subject after its verb, and its place travels as
%% subj_here: the lesson's language keeps the order, `È la possibilità ...
%% quello che li fa così desiderati', and English puts the subject first.
%% `Es verdad lo que dices' is the same shape.
tr_cleft_fix(foreign, s(A, null(third, singular), g(L, T, simple, Neg), Cs0), s(A, E, g(L, T, simple, Neg), Cs)) :-
    tr_copula_lexeme(L), append(Pre, [obj(E)], Cs0), Pre \== [],
    E = ell(_, _, singular, rel(_, _)),
    \+ memberchk(subj_here, Pre), !,
    append(Pre, [subj_here], Cs).
%% A COPULA WITH NOBODY NAMED, A PHRASE OF A PREPOSITION AND A CLAUSE OF `che' WHOSE SUBJECT STANDS AFTER ITS VERB
%% IS A CLEFT: `È proprio su quel carrello che si concentra l'interesse dei presenti' -- it is on that trolley that
%% the interest is concentrated; read as a relative clause on the trolley, its doer after the verb took the trolley
%% for its object (`È su quel carrello che dorme il cane', tr_rel_doer/2), or its reflexive the trolley for its
%% subject, and English refused both. The phrase and the clause are what `È su quel carrello che il cane dorme'
%% reads: pp/2 and that/1, a thing's reflexive the passive where the lesson says the verb takes one
tr_cleft_fix(foreign, s(A, null(third, singular), g(L, T, simple, Neg), Cs0), s(A, null(third, singular), g(L, T, simple, Neg), Cs)) :-
    tr_copula_lexeme(L), append(Pre, [pp(P, rc(NP, Role, s(none, Su, G, RCs0)))], Cs0),
    forall(member(X, Pre), X = adv(_)),
    tr_cleft_clause(Role, Su, G, RCs0, S2), !,
    append(Pre, [pp(P, NP), that(S2)], Cs).
%% ... AND AN ADVERB AND A CLAUSE OF `che' WITH NOBODY NAMED, A PHRASE RIGHT AFTER ITS VERB THAT AGREES WITH IT: `È lì
%% che vivevano certi oggetti' is it is there that certain objects lived -- read with nobody named the objects were
%% what somebody lived, and English wrote `It is there that they lived some objects'. The phrase is the clause's
%% subject, its place kept (subj_here)
tr_cleft_fix(foreign, s(A, null(third, singular), g(L, T, simple, Neg), Cs0), s(A, null(third, singular), g(L, T, simple, Neg), Cs)) :-
    tr_copula_lexeme(L), append(Pre, [that(s(none, null(third, N), G, [obj(NP)|RCs]))], Cs0),
    Pre = [_|_], forall(member(X, Pre), X = adv(_)),
    ( NP = rc(H, _, _) -> true ; H = NP ), tr_head_number(foreign, H, N), \+ tr_time_phrase(NP), !,
    append(Pre, [that(s(none, NP, G, [subj_here|RCs]))], Cs).
tr_cleft_fix(Side, S0, S) :- tr_report_inv_fix(Side, S0, S).
%% (the doer after its verb, and a thing after the verb of a reflexive that takes the passive)
tr_cleft_clause(object, Su, G, RCs0, s(none, Su, G, RCs)) :-
    ( Su = np(_, _, _, _, _) ; Su = name(_) ; Su = with(_, _) ), select(subj_here, RCs0, RCs), !.
%% (the passive the relative clause already read, or its reflexive where the lesson says the verb takes the passive,
%% tr_se_passive/2; its phrases of `of' with it: `the interest of those present is concentrated')
tr_cleft_clause(subject, gap(_, _), g(reflexive(V), T, A, Neg), [obj(NP)|RCs0], s(none, Su, g(reflexive(V), T, passive, Neg), [subj_here|RCs])) :-
    atom(V), tr_thing_phrase(NP), ( A == passive -> true ; A == simple, tr_solve(take(V, passive)) ), !,
    tr_fo_of_run(RCs0, Ofs, RCs), ( Ofs == [] -> Su = NP ; Su = with(NP, Ofs) ).

%% THE SUBJECT OF A VERB OF SAYING STANDS AFTER IT: `Tres veces negó el líder
%% peneuvista que su partido se vaya a "tirar al monte" en septiembre' -- the
%% leader denied it three times. Read left to right the phrase after the
%% verb took the clause for a relative clause on it, the leader whom his
%% party goes, and the verb had nobody for its subject: `Negò il dirigente
%% che la sua partita si va'. A verb that means one of English's verbs of
%% saying (en_saying/1) takes no person for an object, so a person phrase
%% straight after it, which agrees with it and has a clause of `that' after
%% it, is the one who says it -- the subject after its verb, its place kept
%% as subj_here, and the clause the verb's own. A clause with its gap in the
%% subject (`Dijo el líder que vendrá') is the verb's clause with nobody
%% named for ITS subject.
tr_report_inv_fix(foreign, s(A, null(third, N), g(L, T, Asp, Neg), Cs0), s(A, NP, g(L, T, Asp, Neg), Cs)) :-
    atom(L), tr_saying_verb(L),
    append(Pre, [obj(rc(NP, Role, S1))], Cs0),
    \+ memberchk(obj(_), Pre), \+ memberchk(subj_here, Pre),
    tr_subject_number(NP, N), tr_of_class(NP, person),
    tr_report_clause(Role, S1, S2), !,
    append(Pre, [subj_here, that(S2)], Cs).
%% ... AND A SUBJECT PRONOUN THAT NEVER STANDS BEFORE A VERB, RIGHT AFTER A
%% VERB OF SAYING, IS ITS SUBJECT: `puntualizza lui', `ha detto lei' -- `lui'
%% stands after a verb or after a preposition (`"lui" does not precede the
%% verb.'), so it is no clitic of this verb, and
%% what a report has after its verb is who says it. It travels as the
%% pronoun, its place kept as subj_here
tr_report_inv_fix(foreign, s(A, null(third, N), g(L, T, Asp, Neg), [opron(w(X, C))|Cs0]),
                  s(A, pronoun(third, N, w(X, C)), g(L, T, Asp, Neg), [subj_here|Cs0])) :-
    atom(L), tr_saying_verb(L), atom(X), tr_subject_pronoun(foreign, X, third, N), tr_solve(neg(precede(X, verb))), !.
%% ... AND THE SAME FOR THE COMMAND IT CAN BE READ AS: `"In ogni caso",
%% puntualizza lui, "comincerò ..."' -- `puntualizza' is the command and the
%% third person alike, and a command has no `lui' to be said of
tr_report_inv_fix(foreign, s(A, none, g(L, T, imperative, Neg), Cs0), s(A, pronoun(third, N, w(X, C)), g(L, T, simple, Neg), Cs)) :-
    atom(L), tr_saying_verb(L), select(opron(w(X, C)), Cs0, Cs1), atom(X),
    tr_subject_pronoun(foreign, X, third, N), tr_solve(neg(precede(X, verb))),
    \+ memberchk(opron(_), Cs1), \+ memberchk(obj(_), Cs1),
    Cs0 = [_|_], once(( append(Pre, [opron(w(X, C))|Post], Cs0), Cs = [subj_here|Rest], append(Pre, Post, Rest) )), !.
%% ... AND THE COMMAND IT CAN BE READ AS, WITH THE ONE WHO SAYS IT AND A
%% CLAUSE OF `that' AFTER IT: `Assicura il sindaco Costantino Federico (e c'è
%% da credergli) che in piazzetta si vede sempre un bel pò di gente' --
%% `assicura' is the command and the third person alike, and read as the
%% command the mayor was told to assure (`Asegura al alcalde ...'). A command
%% has no person for its subject; as above, a person phrase that agrees with
%% the third person singular is the one who says it
tr_report_inv_fix(foreign, s(A, none, g(L, T, imperative, Neg), Cs0), s(A, NP, g(L, T, simple, Neg), Cs)) :-
    atom(L), tr_saying_verb(L),
    append(Pre, [obj(rc(NP, Role, S1))], Cs0),
    \+ memberchk(obj(_), Pre), \+ memberchk(subj_here, Pre), \+ memberchk(opron(_), Pre),
    tr_subject_number(NP, singular), tr_of_class(NP, person),
    tr_report_clause(Role, S1, S2a), tr_report_impersonal(S2a, S2), !,
    append(Pre, [subj_here, that(S2)], Cs).
%% ... AND THE ONE WHO SAYS IT LAST, AFTER WHAT IS SAID AND A COMMA: `Conferma
%% il popolare ritornello "tutti al mare, tutti al mare", l'analisi svolta
%% dall'osservatorio di Milano' -- the analysis confirms the refrain. Read as
%% the command `conferma' also is, the analysis was a second thing to confirm
%% (`Confirm the popular refrain ..., the analysis carried out ...'). A verb
%% of saying with its object first, and a definite phrase after the last
%% comma, which agrees with it and ends the clause: that phrase is the
%% subject, its place kept as subj_here where it stood, so the lesson's
%% language keeps the order and English puts the subject first
tr_report_inv_fix(foreign, s(A, Su0, g(L, T, Asp0, Neg), Cs0), s(A, NP, g(L, T, Asp, Neg), Cs)) :-
    atom(L), tr_saying_verb(L),
    (   Su0 == none, Asp0 == imperative -> Asp = simple, N = singular
    ;   Su0 = null(third, N), Asp = Asp0
    ),
    Cs0 = [obj(_)|_], append(Pre, [sep, obj(NP)], Cs0),
    \+ memberchk(subj_here, Pre),
    ( NP = rel(Head, _, _) -> true ; Head = NP ),
    Head = np(det(article, _, D), _, _, _, N), \+ tr_indefinite(foreign, D), !,
    append(Pre, [sep, subj_here], Cs).
tr_report_inv_fix(_, S, S).
%% (the clause read as the phrase's relative clause had its reflexive for the
%% phrase's own; told as a clause of `that' with an object of its own, the
%% `si' is the impersonal's -- `che in piazzetta si vede sempre un bel pò di
%% gente' is one seeing people, as the same clause read after `dice che' is)
tr_report_impersonal(s(A, null(third, singular), g(reflexive(L), T, simple, Neg), Cs), s(A, impersonal, g(L, T, simple, Neg), Cs)) :-
    atom(L), memberchk(obj(_), Cs), !.
tr_report_impersonal(S, S).
tr_report_clause(object, S, S).
tr_report_clause(subject, s(A, gap(P, N), G, Cs), s(A, null(P, N), G, Cs)).
%% a verb whose lexeme means one of English's verbs of saying
tr_saying_verb(L) :- tr_solve(mean(L, E)), en_saying(E), !.

%% AN INFINITIVE AFTER A VERB THAT PLEASES IS WHAT PLEASES: `mi piace stare in
%% mezzo alla gente' -- being among people pleases me. Read left to right it
%% was a verb with nobody named and an infinitive for a complement, which the
%% lesson's languages write back as they stood and English, having nobody to
%% put first, refused. A verb the lesson calls intransitive, a clitic before
%% it and an infinitive right after: the infinitive with what follows it is
%% the subject (infs/2), its place kept as subj_here, and the clitic the
%% dative that place makes it (tr_dative_here/3).
tr_infs_fix(foreign, s(A, null(third, singular), g(L, T, simple, Neg), [opron(D), inf(F)|ICs]),
            s(A, infs(F, ICs), g(L, T, simple, Neg), [opron(D), subj_here])) :-
    atom(L), tr_solve(intransitive(L)), !.
tr_infs_fix(_, S, S).

%% THE WORD FOR `EVERYTHING' RIGHT AFTER THE COPULA, BEFORE A PARTICIPLE OR AN ADJECTIVE, IS ITS SUBJECT: `porque estaba
%% todo sembrado de desperdicios rotos' -- because everything was strewn with them. Spanish and Italian put it there
%% (`estaba todo listo', `era tutto pronto'), and read as a pronoun of the verb with nobody named English refused the
%% clause. Only with nobody named before the copula: `Pedro estaba todo mojado' is all wet
%% (it travels as every/1, which crosses as `everything' whatever the word's first meaning, `all')
tr_all_copula_fix(foreign, s(A, null(third, singular), g(L, T, Asp, Neg), [opron(w(W, C)), Q|Cs]),
                  s(A, every(w(W, C)), g(L, T, Asp, Neg), [Q|Cs])) :-
    ( Q = pred(_) ; Q = adj(_) ),
    ( L = state(L0) -> true ; L0 = L ), atom(L0), tr_solve(mean(L0, is)),     % (`está' too, the progressive's auxiliary)
    atom(W), tr_lexeme(foreign, W, WL, _), tr_solve(mean(WL, everything)), !.
tr_all_copula_fix(_, S, S).

%% A MODAL AND AN INFINITIVE WITH THE REFLEXIVE JOINED, NOBODY NAMED, IS THE
%% IMPERSONAL `se': `como podía esperarse de los dos equipos' is as one could
%% expect it of them, `puede decirse que ...' one can say that. Read as it
%% stands it was a third person nobody names -- which English refuses, and
%% Italian wrote as a second person, `Puoi dirsi che' -- with an infinitive
%% that is its own reflexive. With the pronoun BEFORE the modal the lesson
%% already reads `se podía esperar' so (the impersonal subject and the plain
%% infinitive); this is the same sentence with the pronoun on the other side.
%% Only a modal, and only the reflexive word the lesson calls impersonal
tr_modal_se_fix(foreign, s(A, null(third, singular), g(L, T, Asp, Neg), [infx(F, simple, [Cl])|Cs]),
                s(A, impersonal, g(L, T, Asp, Neg), [inf(F)|Cs])) :-
    atom(L), atom(Cl), tr_class_of(L, modal), tr_reflexive_word(Cl), tr_solve(impersonal(Cl)), !.
%% ... AND IN THE PLURAL, WITH A BARE PHRASE AFTER IT IN THE VERB'S NUMBER, THE REFLEXIVE'S PASSIVE: `En algunas de
%% ellas pueden encontrarse chats' -- chats can be found there -- was `they' who could find chats. The phrase is the
%% subject, kept where it stood (subj_here), and the group the modal's passive with its infinitive after it, which is
%% how `Se pueden encontrar chats' reads. Only a phrase with no determiner or a count: `pueden lavarse las manos' is
%% their own hands, which they can wash
%% -- and its clause of `where' and a second phrase joined to it are the subject's too: `chats (páginas de
%% conversación) donde los adeptos se comunican y un tablón donde dejar anuncios diversos' can be found, the two
%% phrases each with its clause (rc(Phrase, where, Clause))
tr_modal_se_fix(foreign, s(A, null(third, plural), g(L, T, simple, Neg), Cs0), s(A, Su, g(reflexive(L), T, passive, Neg), Cs)) :-
    atom(L), tr_class_of(L, modal),
    append(Pre, [infx(F, simple, [Cl]), obj(NP)|Post0], Cs0), atom(Cl), tr_reflexive_word(Cl),
    tr_bare_head(NP, plural),
    forall(member(X, Pre), X = adv(_)), !,
    tr_where_rc(NP, Post0, NP1, Post1),
    (   Post1 = [cnj(Co), obj(NP2)|Post2], tr_bare_head(NP2, _)
    ->  tr_where_rc(NP2, Post2, NP3, Post), Su = co(Co, NP1, NP3)
    ;   Su = NP1, Post = Post1
    ),
    append(Pre, [inf(F), subj_here|Post], Cs).
%% ... AND WITH THE REFLEXIVE BEFORE THE MODAL AND A THING FOR ITS SUBJECT, THE MODAL'S PASSIVE: `el tráfico no se
%% pudo normalizar en la zona' -- the traffic could not BE normalised, and English, which has no reflexive for a modal,
%% wrote `could not normalise'. A phrase that names no doer (tr_doer_np/1), and the plain infinitive right after the
%% modal; `Pedro no se pudo levantar' stays his own getting up
tr_modal_se_fix(foreign, s(A, Su, g(reflexive(L), T, simple, Neg), [inf(F)|Cs]), s(A, Su, g(reflexive(L), T, passive, Neg), [inf(F)|Cs])) :-
    atom(L), tr_class_of(L, modal), Su = np(_, _, _, w(_, _), _), \+ tr_doer_np(Su), !.
tr_modal_se_fix(_, S, S).
%% a phrase with no determiner or a count, through its bracket; or one with an indefinite article
tr_bare_head(np(Det, Num, _, w(_, _), N), N) :- !, ( Det == none -> true ; Num \== none -> true ; Det = det(article, _, D), tr_indefinite(foreign, D) ).
tr_bare_head(app(NP, _, _), N) :- tr_bare_head(NP, N).
tr_bare_head(co(_, NP, _), plural) :- tr_bare_head(NP, _).          % `chats y un tablón donde dejar anuncios'
%% (the clause of `where' after a phrase is the phrase's)
tr_where_rc(NP, [rwh(where, S)|Post], rc(NP, where, S), Post) :- !.
tr_where_rc(NP, Post, NP, Post).

%% A DATIVE PRONOUN THAT THE PHRASE OF `a' AFTER THE VERB SAYS AGAIN IS SAID
%% ONCE: `Pedro le dio un libro a María' gave María a book, and `la operación
%% le ha costado al club 75 millones' cost the club it. Spanish says the one
%% who gets it twice, with the clitic before the verb and the phrase after
%% it; read as it stands the pronoun was a second receiver, `gave him a book to
%% María' and `has cost him to the club'. The pronoun goes and the phrase
%% stays, so the claim is the sentence's. A third person dative the lesson
%% states, no reflexive, in the phrase's number, and a phrase of the word
%% that means `to' (a name, a noun's phrase or a pronoun) in the verb's
%% complements, before any infinitive (`el abandono le permitiría dedicarse a
%% Ona Catalana': the `a' is the infinitive's, and `le' is who is allowed) --
%% and the only pronoun before the verb: `Pedro se lo dio a María' has a
%% second, and without the dative `lo' was read as a person
tr_dative_double_fix(foreign, s(A, Su, G, Cs0), s(A, Su, G, Cs)) :-
    (   select(opron(w(R, _)), Cs0, Cs1), \+ memberchk(opron(_), Cs1), tr_doubled_dative(R, Cs1) -> Cs = Cs1
    %% ... or the pronoun joined to an infinitive, `estuvo a punto de complicarle la vida al Joventut'
    ;   append(Pre, [X|Post], Cs0),
        (   X = infx(F, Asp, Cls0), select(R, Cls0, Cls), tr_doubled_dative(R, Post)
        ->  ( Cls == [] -> Y = inf(F) ; Y = infx(F, Asp, Cls) )
        ;   X = pinf(P, cl(F, Cls0)), select(w(R, _), Cls0, Cls), tr_doubled_dative(R, Post)
        ->  ( Cls == [] -> Y = pinf(P, F) ; Y = pinf(P, cl(F, Cls)) )
        ),
        append(Pre, [Y|Post], Cs)
    ), !.
tr_dative_double_fix(_, S, S).

%% TWO PHRASES AFTER A COPULA WITH NOBODY NAMED ARE WHAT IS AND WHAT IT IS:
%% `Fueron César Sanmartín y Jofresa los jugadores que asumieron la
%% responsabilidad' -- César and Jofresa were the players who took it on. A
%% single name after the copula is the subject already (tr_name_subject/10);
%% a pair of names, or a phrase with its article, was an object, and English,
%% which must name its subject, wrote `They were César Sanmartín and Jofresa
%% the players that ...' from a verb nobody named. The first phrase is the
%% subject, in the verb's number, its place kept (subj_here) as the single
%% name's is: the lesson's language keeps the order and English puts it first.
%% Not an indefinite phrase first, which says what the second is (`Es una
%% pena la situación'): the second is the subject of that one
tr_ident_fix(foreign, s(A, null(third, N), g(L, T, Asp, Neg), Cs0), s(A, E1, g(L, T, Asp, Neg), Cs)) :-
    atom(L), tr_copula_lexeme(L),
    append(Pre, [obj(E1), obj(E2)|Post], Cs0), \+ memberchk(obj(_), Pre), \+ memberchk(subj_here, Pre),
    (   E1 = co(_, _, _), N == plural
    ;   E1 = np(det(article, _, DW), _, _, _, _), \+ tr_indefinite(foreign, DW), tr_subject_number(E1, N)
    ),
    ( E2 = rc(_, _, _) ; E2 = np(det(article, _, _), _, _, _, _) ), !,
    append(Pre, [subj_here, obj(E2)|Post], Cs).
%% ... AND A THIRD PERSON'S PRONOUN AFTER THE COPULA, BEFORE A PHRASE WITH ITS ARTICLE, IS THE SUBJECT: `ed è lui,
%% senza dubbio, il trionfatore incontrastato del festival' says who the victor is, and read as an object pronoun
%% with nobody named but the verb's ending English refused it and Spanish wrote `Y lo es, sin duda, el triunfador'.
%% The pronoun first among the complements, of the copula's number, and the phrase after it (a comma's aside between)
tr_ident_fix(foreign, s(A, null(third, N), g(L, T, Asp, Neg), [opron(w(R, RC))|Cs0]), s(A, pronoun(third, N, w(R, RC)), g(L, T, Asp, Neg), [subj_here|Cs0])) :-
    atom(L), tr_copula_lexeme(L), atom(R), tr_subject_pronoun(foreign, R, third, N),
    \+ memberchk(subj_here, Cs0),
    once(( member(obj(E2), Cs0), E2 = np(det(article, _, DW), _, _, _, _), \+ tr_indefinite(foreign, DW) )), !.
tr_ident_fix(_, S, S).
%% a third person dative the lesson states, no reflexive, and in the complements a
%% phrase of the word for `to' in its number
tr_doubled_dative(R, Cs) :-
    atom(R), \+ tr_reflexive_word(R),
    tr_lexeme(foreign, R, RL, _), tr_solve(dative(RL)),
    tr_object_pronoun(foreign, R, E), memberchk(E-N, [him-singular, her-singular, it-singular, them-plural]),
    append(Before, [pp(w(P, _), NP)|_], Cs), atom(P), tr_means_to(P),
    \+ ( member(X, Before), tr_infinitive_comp_any(X) ),
    tr_subject_number(NP, N), !.
tr_infinitive_comp_any(infx(_, _, _)).
tr_infinitive_comp_any(pinf(_, _)).
tr_infinitive_comp_any(X) :- tr_infinitive_comp(X).

%% BARE PLURALS AFTER A VERB THAT TAKES AN OBJECT ARE ITS OBJECT, WHERE EACH
%% IS A NOUN AS WELL AS AN ADJECTIVE: `nel suo governo inserirà tecnici o
%% politici' puts technicians or politicians in it. The complement reader
%% takes bare adjectives for a predicate, which is what they are after the
%% copula, and Spanish wrote `insertará técnico o político' -- a predicate
%% agreeing with nobody. A verb with a clitic before it (`li hanno trovati
%% vigili' found them VIGILANT), an object already, the copula, the
%% state's, a passive and a verb the lesson calls intransitive keep the
%% predicate.
tr_nounobj_fix(foreign, s(A, Su, g(L, T, Asp, Neg), Cs0), s(A, Su, g(L, T, Asp, Neg), Cs)) :-
    atom(L), memberchk(Asp, [simple, perfect]),
    select(adj(Ws), Cs0, obj(NP), Cs),
    \+ memberchk(obj(_), Cs0), \+ memberchk(opron(_), Cs0),
    \+ tr_copula_lexeme(L), \+ tr_state_lexeme(L), \+ tr_solve(intransitive(L)),
    %% (a plural the lesson states, which is cheap, before the phrase is read)
    last(Ws, w(LW, _)), atom(LW), tr_solve(plural_of(LW, _)),
    forall(( member(W, Ws), \+ tr_coord(foreign, W) ), tr_is(foreign, W, noun)),
    tr_phrase_np(foreign, Ws, NP), tr_plural_phrase(NP), !.
%% ... AND A BARE NOUN THAT TAKES `a' AND AN INFINITIVE AFTER `has': `tenemos
%% derecho a pensar de él lo que nos parece' is having a right, and `derecho'
%% is an adjective too -- straight, right -- which the complement reader
%% takes for a predicate, agreeing with the subject: `Abbiamo diritti a
%% pensare'. After the verb that means `has', a noun the lesson knows with
%% `to' and an infinitive after it is its object, `abbiamo diritto a
%% pensare', and English's `has right to think'.
tr_nounobj_fix(foreign, s(A, Su, g(L, T, Asp, Neg), Cs0), s(A, Su, g(L, T, Asp, Neg), Cs)) :-
    atom(L), memberchk(Asp, [simple, perfect]),
    append(Pre, [adj([W]), ainf(P, I)|Post], Cs0),
    \+ memberchk(obj(_), Pre), \+ memberchk(opron(_), Cs0),
    W = w(WA, _), atom(WA), tr_solve(mean(L, has)), tr_is(foreign, W, noun),
    tr_phrase_np(foreign, [W], NP), tr_singular_np(NP), !,
    append(Pre, [obj(NP), ainf(P, I)|Post], Cs).
tr_nounobj_fix(_, S, S).
tr_singular_np(np(_, _, _, _, singular)).
%% A PHRASE IN FRONT THAT A PRONOUN TAKES UP, AND A PERSON AFTER THE VERB:
%% `Che poi queste cose le sapessero i dotti' is that the learned knew these
%% things -- the things said first and `le' saying them again, the learned
%% after the verb its subject. Read left to right the things were the
%% subject, `le' was `to her' and the learned what the things knew, and every
%% word of it was grammar: what tells the two apart is that a thing does not
%% know and a person does. So where the phrase before the verb is no person,
%% a pronoun before the verb can take it up (a third person object in its
%% number) and the first phrase after the verb is a person that agrees with
%% the verb, the phrase before is the object, set in front, and the person
%% the subject after its verb -- the shape of the dislocation reader below,
%% which is tried only where nothing else read. A second half of the subject
%% after a coordinator with its `no' (nega/1) is the subject's too, and is
%% written as one: `y los simples no', never `y a los simples no'
%% ... AND THE SUBJECT WITH COMPLEMENTS OF ITS OWN THAT THE PRONOUN BEFORE
%% THE VERB TAKES UP IS THE VERB'S OBJECT TOO: `Il timore di infastidire
%% Funari ce l'ha' -- he has the fear of bothering him. Read left to right
%% the fear and what it was of were the subject, with the pronoun for the
%% object, and no writer says that. The pronoun only doubles the phrase and
%% goes, as it does where the phrase reads alone (c. tr_front_phrase/3). A
%% subject that stands AFTER its verb is no phrase set in front: `Lo rende noto
%% un comunicato del Quirinale' announces it, and `lo' is its object.
tr_dislocation_fix(foreign, s(A, with(NP, More), G, Cs0), s(A, null(third, N), G, Cs)) :-
    \+ memberchk(subj_here, Cs0),
    NP = np(det(_, _, _), _, _, _, N), atom(N),
    More = [pinf(_, _)|_], forall(member(X, More), ( X = pinf(_, _) ; X = obj(_) ; tr_adjunct(X) )),
    select(opron(w(R, _)), Cs0, Cs1), atom(R), tr_resumptive(R, N),
    \+ memberchk(obj(_), Cs1), !,
    append([obj(NP)|More], Cs1, Cs).
tr_dislocation_fix(foreign, s(A, Su, G, Cs0), s(A, NP2, G, Cs)) :-
    Su = np(det(_, _, _), _, _, _, N), atom(N),
    select(opron(w(R, _)), Cs0, Cs1), atom(R), tr_resumptive(R, N),
    append(Pre, [obj(NP2)|Post0], Cs1), \+ memberchk(obj(_), Pre),
    tr_subject_number(NP2, N), tr_of_class(NP2, person), \+ tr_of_class(Su, person), !,
    ( Post0 = [cnj(C), nega(obj(NP3))|Post] -> Post1 = [cnj(C), nega(sub(NP3))|Post] ; Post1 = Post0 ),
    append(Pre, [obj(Su), subj_here|Post1], Cs).
%% ... AND THE PRONOUN OF THE VERB'S OWN PERSON AFTER IT IS THE SUBJECT, SAID AGAIN:
%% `sono arrivato io alla conclusione' is I came to the conclusion, the verb's ending
%% saying who and the pronoun only stressing it. Read with nobody named but the
%% ending, the pronoun was a noun (`io' is the ego as well), the verb's object, and
%% English wrote it a second time, `I have arrived I'. First and second persons
%% only: `lui' and `loro' are object pronouns as often. Its place is kept
%% (subj_here) and no other object may stand in the clause
tr_dislocation_fix(foreign, s(A, null(P, N), G, [obj(np(none, none, [], w(X, C), _))|Cs]), s(A, pronoun(P, N, w(X, C)), G, [subj_here|Cs])) :-
    memberchk(P, [first, second]), atom(X), \+ memberchk(obj(_), Cs),
    tr_subject_pronoun(foreign, X, P, N), !.
%% ... AND A NAME THAT ENDS THE PHRASE BEFORE A PRONOUN THAT TAKES THE PHRASE UP AGAIN IS THE SUBJECT: `Ma la musica
%% italiana Caetano come l'ha scoperta?' -- Italian music, how did Caetano discover it. Read as one phrase, the name
%% apposed to the music, the music had discovered him. A phrase with its determiner whose last word is a capitalised
%% name, and the pronoun first among the complements in the phrase's number
tr_dislocation_fix(foreign, s(A, np(Det, Num, Adjs0, N, Nb), G, [opron(w(R, _))|Cs]), s(A, name(Name), G, [obj(np(Det, Num, Adjs, N, Nb))|Cs])) :-
    Det = det(_, _, _), append(Adjs, [w(Name, upper)], Adjs0), atom(Name), tr_name_word(foreign, w(Name, upper)),
    atom(R), tr_resumptive(R, Nb), !.
%% ... AND A THING BEFORE AN IMPERSONAL `si' THAT A PRONOUN JOINED TO THE INFINITIVE TAKES UP AGAIN IS THE
%% INFINITIVE'S OBJECT: `qualche incrinatura si riesce a trovarla' is one manages to find some crack -- read left to
%% right the crack was the subject of the reflexive, and English wrote `some crack attains to find her'. The verb has no
%% reflexive meaning of its own, the pronoun agrees with the phrase, and the clause is the impersonal one
tr_dislocation_fix(foreign, s(A, NP, g(reflexive(L), T, simple, Neg), Cs0), s(A, impersonal, g(L, T, simple, Neg), Cs)) :-
    NP = np(det(_, _, _), _, _, _, N), atom(N), atom(L), \+ tr_solve(mean_as(L, _, reflexive)), tr_thing_phrase(NP),
    append(Pre, [infx(F, IA, [R])|Post], Cs0), atom(R), tr_resumptive(R, N), tr_resumptive_agrees(R, NP), !,
    append(Pre, [infx(F, IA, []), obj(NP)|Post], Cs).
tr_dislocation_fix(_, S, S).
tr_plural_phrase(np(_, _, _, _, plural)).
tr_plural_phrase(co(_, A, B)) :- tr_plural_phrase(A), tr_plural_phrase(B).

%% A SUBJECT THAT IS THERE IS READ BEFORE ONE THAT IS NOT. `Los informes son
%% muy buenos' is the reports being good -- and read left to right the first
%% verb it met was `informes', the second person of `informar', with `los'
%% the pronoun before it: `(tú) los informes', and `son muy buenos' an object
%% whose noun was `son', a sound. Every place a verb could start is tried
%% with a subject before it first, and only then with none, which is where
%% the lesson's languages leave it out. English names its subject always.
%% ONLY WHERE THE CLAUSE OPENS ON AN ARTICLE THAT IS AN OBJECT PRONOUN TOO,
%% BEFORE A WORD THAT IS A NOUN AND A VERB'S FORM, which is the shape that
%% misread. Tried on every statement, the pass with a subject walked every
%% later verb of a long sentence first -- Livata's `Di certo si sa solo che
%% la famiglia era ...' cost 7.2 million inferences more for the same
%% reading -- and asked of any article before such a word it still ran on
%% most Italian sentences, `l'acquisto', `la parte', `l'accordo': Fiat's
%% `Siamo particolarmente soddisfatti ...' cost 9.1 million where 1.7.2's
%% cost 4.6.
tr_subject_phase(foreign, none, Words, Phase) :- tr_article_verb_noun(Words), !, member(Phase, [said, unsaid]).
tr_subject_phase(_, _, _, any).

tr_article_verb_noun([D, w(V, _)|_]) :-
    D = w(DW, _), tr_determiner(foreign, D, _, _), tr_object_pronoun(foreign, DW, _),
    tr_is(foreign, w(V, lower), noun),
    tr_form(V, L, _, _, _), atom(L), ( tr_class_of(L, verb) ; tr_class_of(L, modal) ; tr_class_of(L, auxiliary) ), !.
tr_phase_subject(said, Ws) :- Ws \== [].
tr_phase_subject(unsaid, []).
tr_phase_subject(any, _).

%% THE POLITE COMMAND IS A PRESENT SUBJUNCTIVE STANDING ALONE: `"guardi, io
%% voglio fare un governo ...' -- look, I want. Italian commands the person
%% it calls `lei' and Spanish the one it calls `usted' with the subjunctive
%% of the third person, `guardi', `mire', and read as the indicative the
%% lesson also spells `guardi' as it was a statement, `(tú) miras'. A verb
%% alone in its clause, at the head of its sentence and before its comma,
%% that the lesson calls a present subjunctive: the subject is
%% addressee(polite), and each writer writes its own polite command -- the
%% subjunctive its lesson states, and English its base form.
tr_read_statement0(foreign, [w(V, _)], none, S) :-
    atom(V), tr_global('$tr_piece', P), is_list(P), P = [w(V, _), comma|_],
    tr_solve(subjunctive_of(V, L)), \+ tr_holds(past(V)), tr_known(foreign, L), !,
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', imperative),
    S = s(none, addressee(polite), g(L, present, imperative, no), []).
%% `there is': no subject of its own, and what there is as its first object
%% -- English's `there' and the copula, or `there will be'; the lesson's
%% verb that means `there is' (`hay'), which the question form may have
%% put after its phrase (`¿Hay un perro?' reads as `un perro hay')
tr_read_statement0(Side, Words0, none, S) :-
    tr_negation(Side, Words0, Words, Neg0),
    tr_existential(Side, Words, L, T, After, Neg0, Neg),
    nb_setval('$tr_read_group', L),
    %% what there is is a PHRASE, read as one first: `Hay otros servidos con
    %% caldos' is others-that-were-served, and the complement reader took
    %% `otros' for an object pronoun and left the participle stranded
    (   tr_phrase_words(Side, After, PW, Rest), PW \== [], tr_phrase_np(Side, PW, NP),
        tr_complements(Side, Rest, More)
    ->  Comps = [obj(NP)|More]
    ;   tr_complements(Side, After, Comps), tr_existential_first(Comps)
    ), !,
    S = s(none, there, g(L, T, simple, Neg), Comps).
%% A PASSIVE PUTS ITS SUBJECT AFTER ITSELF: `Viene esclusa ogni forma di
%% eutanasia diretta o di "eutanasia genetica"', `Vanno invece attivate la
%% terapia palliativa e la terapia del dolore'. A passive has no object --
%% what would have been its object is its subject -- so the phrase after it
%% that agrees with it in number is that subject, with every phrase that
%% says which one, up to the clause's first comma. Read by the pro-drop
%% readings it was the object of a verb that has none, the subject was
%% `they' or nobody, and the participle agreed with nothing. Only with
%% nothing before the group, which is where a subject would otherwise
%% stand; and the subject's place travels as subj_here, so the lesson's
%% writer keeps the source's order and English's writes the subject first.
%% -- and after a relative word that a preposition governs, whose clause is
%% a whole statement: `nel quale sono previste ulteriori contribuzioni da
%% parte di Chrysler Group al Veba' has the contributions foreseen, and the
%% passive reader stood down for the `rel' such a clause is read with -- so
%% they were an object, nobody was the subject, and Spanish wrote `son
%% previstos adicionales contribuciones', the participle agreeing with nothing
%% ... AND FIRST WHERE THE PREDICATE IS A PARTICIPLE THAT IS AN ADJECTIVE TOO: `Sarebbe più corretto dire che in
%% realtà si spende poco per gli altri' is it would be more correct to say that in reality one spends little on the
%% others -- read as the passive, `would be more corrected', the infinitive was its subject or its complement, and the
%% clause for the copula, its adjective and the infinitive (tr_copula_adj_inf/3) came after the passive's
tr_read_statement0(foreign, Words0, none, S) :- tr_copula_adj_inf(Words0, participle, S), !.
tr_read_statement0(foreign, Words0, Asked, S) :-
    ( Asked == none ; Asked == rel ),
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, [], g(L, T, A, third, N), After0),
    memberchk(A, [passive, passive_perfect, duty]),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', A),
    tr_adverb_prefix(After0, Advs, After),                  % `Vanno INVECE attivate' put its adverb here
    (   append(SubjW, [comma|Rest0], After) -> Rest = [comma|Rest0] ; SubjW = After, Rest = [] ),
    SubjW \== [], \+ memberchk(comma, SubjW),
    tr_subject(foreign, none, SubjW, third, N, Subject), Subject \= null(_, _),
    tr_number_agrees(foreign, Subject, N),
    tr_complements(foreign, Rest, Comps0), !,
    findall(adv(X), member(X, Advs), AC), append(AC, [subj_here|Comps0], Comps),
    S = s(none, Subject, g(L, T, A, Neg), Comps).
%% A PASSIVE MADE WITH THE REFLEXIVE, AND A PLURAL VERB: `También se
%% incrementaron las ventas de minidisc, que superaron ...' -- the sales went
%% up, and the verb agrees with them. With a singular verb the word is the
%% impersonal one, `se prevé un mantenimiento', which every writer here
%% writes; with a plural one it cannot be, and the pro-drop readings made
%% `they' increase the sales. The phrase after the verb that agrees with it
%% is its subject, as a passive's is (above), and the group is the
%% reflexive's passive, g(reflexive(L), T, passive, Neg): English writes its
%% passive, the lesson's language its reflexive and the verb (fo_group/8),
%% in the source's order.
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    %% the group the words make, and only then asked whether it is a simple
    %% one: asked for a simple group, `si sono adoperate 37 associazioni'
    %% offered the copula alone, and a subject was looked for in every
    %% reading of `adoperate 37 associazioni ...' -- 5.5 million inferences
    %% of Livata's longest sentence, before the perfect read it
    tr_group_from(foreign, Words, [w(R, _)], G, After), G = g(L, T, simple, third, plural),
    tr_reflexive_word(R), atom(L),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', simple),
    tr_after_nrc(After, AfterU, Wrap),
    tr_subject_after(AfterU, third, plural, Rest, Subject0), Subject0 \= null(_, _),
    \+ tr_predicate_after_reflexive(L, Subject0),
    tr_number_agrees(foreign, Subject0, plural),
    tr_wrap_nrc(Wrap, Subject0, Rest, Subject),
    tr_complements(foreign, Rest, Comps0), !,
    tr_subject_place(AfterU, Comps0, Comps),
    S = s(none, Subject, g(reflexive(L), T, passive, Neg), Comps).
%% ... AND WITH ADJUNCTS BEFORE ITS SUBJECT: `no se ven en la nieve las
%% huellas de los pasos' -- the footprints are not seen in the snow. The
%% subject was looked for right after the verb, found a preposition, and
%% the pro-drop reading made `they' not see the footprints; the same words
%% in Italian, and in English somebody who did not look. The adjuncts open
%% on a preposition and the subject on a determiner, and they stay where the
%% source had them, the subject's place kept as subj_here.
%% (The reflexive word is asked for first, at the head or after the denial:
%% asked after the group, every statement read paid for a denial and a group
%% it had no reflexive for -- 1.4 million inferences over a few long
%% sentences and Tatoeba's 400.)
tr_read_statement0(foreign, Words0, none, S) :-
    Words0 = [w(R0, _)|Ws0], atom(R0),
    (   tr_negation_word(R0) -> Ws0 = [w(R1, _)|_], atom(R1), tr_reflexive_word(R1)
    ;   tr_reflexive_word(R0)
    ),
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, [w(R, _)], G, After), G = g(L, T, simple, third, plural),
    tr_reflexive_word(R), atom(L),
    After = [P|_], P = w(_, _), tr_is(foreign, P, preposition),
    tr_uncomma(After, AfterU),
    append(Mid, SubjStart, AfterU), Mid \== [], SubjStart = [D|_], D = w(_, _), tr_determiner(foreign, D, _, _),
    \+ ( last(Mid, LM), LM = w(_, _), tr_determiner(foreign, LM, _, _) ),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', simple),
    tr_complements(foreign, Mid, MidComps), forall(member(X, MidComps), tr_adjunct(X)),
    tr_subject_after(SubjStart, third, plural, Rest, Subject), Subject \= null(_, _),
    tr_number_agrees(foreign, Subject, plural),
    tr_complements(foreign, Rest, Comps0), !,
    append(MidComps, [subj_here|Comps0], Comps),
    S = s(none, Subject, g(reflexive(L), T, passive, Neg), Comps).
%% A COPULA, WHAT IT SAYS, AND THEN WHAT IT SAYS IT OF: `sono molti i fatti
%% che lo dimostrano' -- the facts that show it are many. The copula agrees
%% with the phrase with its article after the predicate, and that phrase is
%% the subject; read left to right `sono' was `I am' and `molti' an object of
%% it. The subject's place travels as subj_here, so the lesson's language
%% keeps the order and English puts the subject first.
%% (the predicate is adjectives or a pronoun, so no word in it opens a
%% clause or a phrase: `Es posible que sea la posibilidad de ...' offered a
%% predicate before every article of the sentence, and each was read as
%% complements and refused -- 2.9 million inferences in the mobile column's
%% tenth sentence. An ARTICLE opens a phrase, and a determiner may be the
%% pronoun it also is: `molti' is `molto''s plural as well)
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, [w(C, _)|Rest], Neg),
    tr_form(C, CL, N, T, third), tr_copula_lexeme(CL),
    append(PredW, SubjW, Rest), PredW = [_|_], SubjW = [D, _|_], \+ memberchk(comma, PredW),
    %% (an article, a demonstrative or a possessive: `¿no eran inglesas
    %% estas hordas ...?' is these hordes not being English)
    tr_determiner(foreign, D, _, DK), memberchk(DK, [article, demonstrative, possessive]),
    \+ ( member(X, PredW), X = w(_, _),
         ( tr_opens_clause(X) ; tr_is(foreign, X, preposition) ; tr_determiner(foreign, X, _, article) ) ),
    nb_setval('$tr_read_group', CL), nb_setval('$tr_read_aspect', simple),
    %% (a pronoun that stands alone is what the copula says, never an object
    %% before a verb: `molti')
    tr_complements(foreign, PredW, [P0]),
    ( P0 = adj(_) -> P1 = P0 ; P0 = obj(pronoun(_)) -> P1 = P0 ; P0 = opron(W0), P1 = obj(pronoun(W0)) ),
    (   tr_np(foreign, SubjW, Subject0),
        ( Subject0 = rc(H, _, _) -> fo_np_number(H, N1) ; fo_np_number(Subject0, N1) ), N1 == N
    ->  Subject = Subject0, Comps = [P1, subj_here]
    %% ... WITH ITS OWN `OF' PHRASES: `è sufficiente la mera assunzione della
    %% sostanza proibita' -- the mere intake of the forbidden substance is
    %% enough. The phrase had to reach the end of the words, the `di' phrase
    %% stood among the complements and English wrote `it is sufficient the
    %% mere acceptance of ...'; they are the subject's (tr_subject_ofs/3), as
    %% after the modal below
    ;   P1 = adj(_), tr_phrase_rest(foreign, SubjW, NP, Rest2), Rest2 = [_|_],
        ( NP = rc(H2, _, _) -> fo_np_number(H2, N2) ; fo_np_number(NP, N2) ), N2 == N,
        tr_complements(foreign, Rest2, More0), tr_subject_ofs(More0, PPs, More), PPs = [_|_],
        Subject = with(NP, PPs), Comps = [P1, subj_here|More]
    ), !,
    S = s(none, Subject, g(CL, T, simple, Neg), Comps).
%% ... AND SO DOES A VERB OF SEEMING, with an adverb between commas after its predicate: `Sembra
%% ancora lontano, comunque, il giorno in cui si potrà tornare a fare il bagno nei canali' -- the day
%% when one can swim in them again still seems far, however. Read left to right `sembra' was the
%% command, seem, and the day its object
tr_read_statement0(foreign, Words0, none, S) :-
    nb_getval('$tr_seem_lexemes', SLs), SLs \== [],
    once(( ( Words0 = [w(C0, _)|_] ; Words0 = [_, w(C0, _)|_] ), atom(C0), tr_lexeme(foreign, C0, L0, _), memberchk(L0, SLs) )),
    tr_negation(foreign, Words0, [w(C, _)|Rest], Neg),
    atom(C), tr_form(C, CL, N, T, third), atom(CL), tr_lexeme_across(CL, english, E), memberchk(E, [seems, appears]),
    append(PredW0, SubjW, Rest), PredW0 = [_|_], SubjW = [D, _|_],
    tr_determiner(foreign, D, _, DK), memberchk(DK, [article, demonstrative, possessive]),
    (   append(PredW, [comma|Ins], PredW0), append(InsW, [comma], Ins), InsW = [_|_],
        \+ memberchk(comma, PredW), \+ memberchk(comma, InsW),
        forall(member(X, InsW), tr_is(foreign, X, adverb))
    ->  tr_complements(foreign, InsW, InsCs), findall(sep, true, [Sep]), append([[Sep], InsCs, [sep]], Mid)
    ;   PredW = PredW0, \+ memberchk(comma, PredW), Mid = []
    ),
    PredW = [_|_],
    \+ ( member(X, PredW), X = w(_, _),
         ( tr_opens_clause(X) ; tr_is(foreign, X, preposition) ; tr_determiner(foreign, X, _, article) ) ),
    nb_setval('$tr_read_group', CL), nb_setval('$tr_read_aspect', simple),
    tr_complements(foreign, PredW, Ps), Ps = [_|_], forall(member(P, Ps), ( P = adj(_) ; P = adv(_) )),
    tr_np(foreign, SubjW, Subject),
    ( Subject = rc(H, _, _) -> fo_np_number(H, N1) ; fo_np_number(Subject, N1) ), N1 == N, !,
    append([Ps, Mid, [subj_here]], Comps),
    S = s(none, Subject, g(CL, T, simple, Neg), Comps).
%% A COPULA WITH NOBODY BEFORE IT AND A CLAUSE OF `CHE' AFTER IT: `Era che i
%% suoi avversari avevano fatto calcoli più precisi dei suoi' -- it was that
%% his opponents had made more precise calculations. Read left to right `era'
%% was an era, the subject with a relative clause on it, and `calcoli' the
%% verb, you calculate. The copula in the third person singular, a word for
%% `that' and the clause after it are s(none, null(third, singular), ...,
%% [that(Clause)]), which English, where nobody is named, refuses.
%% (both readings ask first that the piece open on such a copula, a denial
%% before it allowed: tr_negation/4 asks the lesson after every word of the
%% piece, and the two asked it of every statement read, 0.18 million
%% inferences of Tatoeba's 400 and 0.18 of Valencia's eleventh sentence)
tr_read_statement0(foreign, Words0, none, S) :-
    tr_copula_head(Words0),
    tr_negation(foreign, Words0, [w(C, _), T0|Rest], Neg), Rest \== [],
    atom(C), tr_form(C, CL, singular, T, third), tr_copula_lexeme(CL), tr_that_here(foreign, T0),
    tr_that_clause(foreign, Rest, S1), !,
    S = s(none, null(third, singular), g(CL, T, simple, Neg), [that(S1)]).
%% ... AND AN INFINITIVE AFTER THE PREDICATE IS WHAT IT IS SAID OF: `e quindi
%% fosse pazzesco tentare di raggiungere il levante per la via del ponente'
%% -- trying to reach the East by way of the West was mad. The copula is in
%% the third person singular, the predicate adjectives, and the infinitive
%% with all that follows it the subject (infs/2), its place kept (subj_here):
%% the lesson's language keeps the order and English puts the subject first.
%% Read left to right the infinitive had nothing to be and the piece was
%% refused.
tr_read_statement0(foreign, Words0, none, S) :- tr_copula_adj_inf(Words0, any, S), !.
%% ... AND A MODAL BEFORE THE COPULA'S INFINITIVE: `può essere peggiore la
%% qualità dei servizi' -- the quality of the services can be worse. Read
%% with nobody named, the quality was an object complement of `be', which
%% the lesson's language writes in the same place and English refused with
%% nobody to say it of. The modal agrees with the phrase after the
%% predicate, and that phrase is the subject, its place kept (subj_here).
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, [w(M, _), w(E, _)|Rest], Neg),
    atom(M), tr_form(M, ML, N, T, third), atom(ML), tr_class_of(ML, modal),
    atom(E), tr_solve(infinitive_of(E, F)), tr_lexeme(foreign, F, CL, _), tr_copula_lexeme(CL),
    append(PredW, SubjW, Rest), PredW = [_|_], SubjW = [D, _|_], \+ memberchk(comma, PredW),
    tr_determiner(foreign, D, _, DK), memberchk(DK, [article, demonstrative, possessive]),
    \+ ( member(X, PredW), X = w(_, _),
         ( tr_opens_clause(X) ; tr_is(foreign, X, preposition) ; tr_determiner(foreign, X, _, article) ) ),
    nb_setval('$tr_read_group', CL), nb_setval('$tr_read_aspect', simple),
    tr_complements(foreign, PredW, [P0]), P0 = adj(_),
    %% (the phrase and what the sentence says after it: `... ma non quella
    %% degli insegnanti', but not that of the teachers)
    %% -- and the phrase's own `di' phrases are the subject's (tr_subject_ofs/3)
    tr_phrase_rest(foreign, SubjW, NP, Rest2),
    ( NP = rc(H, _, _) -> fo_np_number(H, N1) ; fo_np_number(NP, N1) ), N1 == N,
    ( Rest2 == [] -> More0 = [] ; tr_complements(foreign, Rest2, More0) ),
    tr_subject_ofs(More0, PPs, More), ( PPs == [] -> Subject = NP ; Subject = with(NP, PPs) ), !,
    S = s(none, Subject, g(ML, T, simple, Neg), [inf(CL), P0, subj_here|More]).
tr_read_statement0(Side, Words0, Asked, S) :- tr_read_generic(Side, Words0, Asked, S), !.
%% A QUESTION WITH AN INFINITIVE: `Come affrontare il problema?' -- how to
%% tackle the problem. The question word, an infinitive and what it takes, with
%% no subject and no tense: the verb in the aspect `infinitive', which every
%% writer spells (`to tackle', `afrontar'). Tried after the plain reading has
%% failed, as every question that has a verb of its own is read first.
tr_read_statement0(foreign, Words0, Asked, S) :-
    Asked \== none, Asked \= subject(_), Asked \= pp(_, _),
    tr_negation(foreign, Words0, [w(V, _)|Rest], Neg),
    atom(V), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    nb_setval('$tr_read_group', F), nb_setval('$tr_read_aspect', simple),
    tr_complements(foreign, Rest, Comps), !,
    S = s(Asked, none, g(F, present, infinitive, Neg), Comps).
%% ... WITH ITS REFLEXIVE JOINED: `nuovi linguaggi in cui immergersi' -- new
%% languages to immerse oneself in. The `si' cut off the infinitive
%% (tr_enclitics/3) was left over, no complement reads a pronoun alone, and
%% the relative clause was refused; the reflexive is the verb's, as it is in
%% infs(reflexive(Lexeme), Complements)
tr_read_statement0(foreign, Words0, Asked, S) :-
    Asked \== none, Asked \= subject(_), Asked \= pp(_, _),
    tr_negation(foreign, Words0, [w(V, _), w(Cl, enclitic)|Rest], Neg),
    tr_reflexive_word(Cl), atom(V), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    nb_setval('$tr_read_group', F), nb_setval('$tr_read_aspect', simple),
    tr_complements(foreign, Rest, Comps), !,
    S = s(Asked, none, g(reflexive(F), present, infinitive, Neg), Comps).

%% A PHRASE BEFORE THE VERB THAT A PRONOUN BEFORE THE VERB TAKES UP AGAIN IS
%% THE VERB'S OBJECT, SET IN FRONT: `Io la risposta non ce l'ho' is I do not
%% have the answer -- the answer said first, and `l'' saying it again. Read
%% as the sentence's subject, `io la risposta' was nothing at all. The phrase
%% opens on a determiner, and the pronoun is a third person in the phrase's
%% number; it only doubles the phrase, as `lo' doubles `todo', and goes. Every
%% writer puts the object after its verb: what is lost is the emphasis, not
%% the claim, as a fronting's is. Tried when nothing else read.
%% -- THE PRONOUN IS LOOKED FOR BEFORE THE PHRASE. Every statement that did not
%% read reaches this clause, and with the phrases parsed first every clitic
%% run before every verb -- `si disse', `si tende', `si trasformano' -- paid
%% for a phrase at every determiner before it: 53 million inferences over six
%% sentences of the controls that have no dislocation at all.
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    tr_dislocation_hint(Words),
    %% (the first front the pronoun finds, and no other -- ONCE: the cut after
    %% it said as much, and with its choices kept for the goals below, a front
    %% whose words before the phrase read as no subject paid for every other
    %% split of a long one: 2.8 million inferences on one sentence of the
    %% controls)
    once(( tr_group_from(foreign, Words, Before, g(L, T, A, FP, FN), After),
           \+ memberchk(comma, Before),
           append(Front, Clitics0, Before), Clitics0 = [_|_],
           forall(member(w(C, _), Clitics0), tr_clitic(none, C)),
           select(w(R, _), Clitics0, Clitics1), findall(N0, tr_resumptive(R, N0), Ns), Ns = [_|_],
           %% (a pronoun of two numbers -- `le', `gli' -- reads every front ONCE, and
           %% takes the first in its numbers' order: asked number by number, every
           %% phrase before it was parsed twice, 15 and 16 million inferences on two
           %% sentences of the controls that have no dislocation. A pronoun of one
           %% number stops at the first front in it, as it always did)
           (   Ns = [NN]
           ->  append(SubjW, NPW, Front), NPW = [D|_], tr_determiner(foreign, D, _, _),
               tr_front_phrase(NPW, NP, FRest), tr_fronted_np_number(NP, NN)
           ;   findall(SubjW0-NP0-N0-FR0, ( append(SubjW0, NPW, Front), NPW = [D|_], tr_determiner(foreign, D, _, _),
                                            tr_front_phrase(NPW, NP0, FR0), tr_fronted_np_number(NP0, N0), memberchk(N0, Ns) ), Sols),
               member(NN, Ns), memberchk(SubjW-NP-NN-FRest, Sols)
           ) )),
    %% (the clause is settled on -- the cut -- unless a VERB stands among the
    %% words before the phrase. Those are a clause of their own, and the phrase
    %% is set in front inside the clause that one holds: `Dijo que el perro lo
    %% come' has `el perro' in front of `lo' by this reading and `dijo que'
    %% before it, `avisó a Ibarretxe de que a su Gobierno el tiempo se le
    %% acaba' has `a su Gobierno' and the words up to its `a'. The cut took
    %% every clause after this one with it, the null-subject reading among
    %% them, and the sentence was refused, where `Dijo que Pedro lo come'
    %% read. With no verb the words are a subject or nothing, and no clause
    %% after this one reads them either: `Che poi queste cose le sapessero i
    %% dotti' has `che poi', and asking the clauses below cost 2.5 million
    %% inferences on one sentence of the controls)
    ( member(w(V, _), SubjW), atom(V), tr_verb_form_word(V) -> true ; ! ),
    %% (the pronoun agrees with the phrase taken -- asked once, for the phrase
    %% the clause settled on, and not at every place a determiner stands: that
    %% added 450 000 inferences to a sentence of the controls that has none)
    tr_resumptive_agrees(R, NP),
    %% (and nobody before the phrase set in front is a third person nobody
    %% named, which the phrase and its pronoun make a clause of: `Il timore di
    %% infastidire Funari ce l'ha' -- he has the fear of bothering him)
    %% (... AND WITH NOTHING BEFORE THE PHRASE, THE WORDS AFTER THE VERB MAY BE ITS SUBJECT: `l'italiano me l'hanno
    %% insegnato Pinelli, Flaiano, Zavattini e tutti gli sceneggiatori' -- they taught me Italian, the verb in their
    %% number and not the phrase's, and with nobody before the phrase but a third person singular the clause had
    %% no reading)
    %% (only words a subject can open on: a name, a determiner, a pronoun -- the whole rest parsed as a subject
    %% at every dislocation was most of what the clause cost the controls -- and sixteen words at most: `Che poi
    %% queste cose le sapessero i dotti e i semplici no, guardate che ...' spent 3.1 million inferences more
    %% parsing its 28 for a subject, the article's list after `insegnato' being 14)
    (   SubjW == [], FP == third, After = [A1|_], tr_subject_opener(A1), length(After, NA), NA =< 16,
        tr_subject(foreign, none, After, FP, FN, Inv),
        ( Inv = co(_, _, _) -> FN == plural ; tr_subject_number(Inv, FN) )
    ->  Subject = Inv, Inverted = yes
    ;   SubjW == [], FP == third, FN == singular -> Subject = null(third, singular), Inverted = no
    ;   tr_subject(foreign, none, SubjW, FP, FN, Subject), Inverted = no
    ), !,
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', A),
    tr_reflexive_off(foreign, Clitics1, Clitics, L, LV),
    ( Inverted == yes -> Comps0 = [subj_here] ; tr_complements(foreign, After, Comps0) ), \+ memberchk(obj(_), Comps0),
    findall(opron(W), member(W, Clitics), Cs),
    append(FRest, Comps0, After1),
    append(Cs, [obj(NP)|After1], Comps),
    S = s(none, Subject, g(LV, T, A, Neg), Comps).

%% INVERSION: A FRONTED ADJUNCT PUTS THE SUBJECT AFTER THE VERB.
%% `Qui solo due anni fa dominava il coprifuoco' is the curfew dominating
%% and not somebody dominating the curfew -- and what says so is the
%% material BEFORE the verb: an adverb or a prepositional phrase, never a
%% subject. That is the condition the languages themselves use, and it is
%% why `Mangia il pane' STAYS REFUSED: nothing is fronted there, so nothing
%% says the phrase after the verb is anything but the object, and a third
%% person with no subject could be anybody.
%%
%% AND THE FRONTING IS NOT ENOUGH, which one probe settled: `Ieri mangiava
%% il pane' came out `The bread ate yesterday', because a fronted adjunct
%% makes inversion POSSIBLE and never certain -- Italian reads that one as
%% pro-drop with an object, and what tells the two apart is whether the
%% verb takes an object at all. Nothing in a lesson said so, so the lesson
%% says it now: `"domina" is intransitive.', the bare-property shape
%% `"leche" is feminine.' already has, and reason.pl did not move. A verb
%% no lesson calls intransitive keeps its refusal, which is the honest
%% half of the trade: a wrong reading is worse than none.
%%
%% The agreement is checked, because fo_subject_after/5 is the question
%% form's own finder: the verb and the phrase must agree in person and
%% number before the phrase is taken for the subject.
%%
%% THE FRONTING IS READ AND NOT WRITTEN BACK. The adjuncts become ordinary
%% complements, in their own order, and every writer puts them after the
%% verb -- so `Qui dominava il generale' comes back as `Il generale dominava
%% qui', which is the same sentence in the statement's own order. What is
%% lost is an emphasis, not a claim.
tr_read_statement0(foreign, Words0, Asked, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, Before, g(L, T, A, FP, FN), After),
    Before \== [],
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', A),
    tr_solve(intransitive(L)),
    \+ tr_ser_not_ir(L, Words, Before, After),              % `Ayer fue una equivocación' is no going
    %% (only adverbs and pronouns before the verb are the reader below's,
    %% which finds the subject with its commas and a noun's own infinitive:
    %% `Forse è venuto il momento ... di porsi la stessa domanda ..., e
    %% decidere se ...'. Read here, `il momento' was the subject and `di
    %% porsi' the verb's, so the moment came to ask)
    \+ tr_adverbs_and_clitics(Before),
    %% a front the source set off with a comma is written back in front, as
    %% a statement's is: `De la amplia gama de instrumentos ..., destaca un
    %% violín'
    (   append(Before1, [comma], Before)
    ->  tr_complements(foreign, Before1, Front0), Front0 \== [],
        forall(member(X, Front0), tr_adjunct(X)), findall(fr(X), member(X, Front0), Front)
    ;   tr_complements(foreign, Before, Front),
        Front \== [], forall(member(X, Front), tr_adjunct(X))
    ),
    tr_uncomma(After, AfterU),
    (   %% ... AND ITS `di' PHRASES, which say which: `Fino ad oggi in Europa
        %% esiste un solo centro di addestramento Esa (...), a Colonia' is one
        %% training centre existing. The shortest phrase that agrees was the
        %% subject, the rest the verb's, and put first in the statement's
        %% order the subject lost them: `Un solo centro existe hasta hoy en
        %% Europa de entrenamiento Esa'. The subject after an intransitive
        %% verb is found as the reader below finds it, its `di' phrases with
        %% it (tr_subject_after/5), and what follows keeps its commas
        Asked == none, tr_of_after_phrase(AfterU),
        tr_subject_after(AfterU, FP, FN, Rest0, Subject0), Subject0 = with(_, _)
    ->  Subject = Subject0,
        ( Rest0 \== [], tr_rest_commas(After, AfterU, Rest0, RestC) -> Rest = RestC ; Rest = Rest0 )
    ;   fo_subject_after(AfterU, FP, FN, SubjWords, Rest), SubjWords \== [],
        tr_subject(foreign, Asked, SubjWords, FP, FN, Subject)
    ),
    tr_complements(foreign, Rest, Back), !,
    append(Front, Back, Comps),
    S = s(Asked, Subject, g(L, T, A, Neg), Comps).

%% AN INTRANSITIVE VERB WITH ONLY ITS PRONOUNS BEFORE IT HAS ITS SUBJECT
%% AFTER IT. `le gusta el buen fútbol' is the good football pleasing him, and
%% `Dominava il generale' the general dominating: a verb the lesson calls
%% intransitive takes no object, so the phrase after it that agrees with it
%% can only be what it says something of. Nothing in front is needed for
%% that, where the inversion above needs a front to make a verb the lesson
%% says NOTHING about read that way. The subject's place travels as
%% subj_here, so the lesson's writer keeps `gli piace il buon calcio' and
%% English's writes `The good football pleases him'.
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, Before, g(L, T, A0, FP, FN), After0),
    (   tr_takes_subject_after(L, none, Before), \+ tr_ser_not_ir(L, Words, Before, After0) -> After = After0, Inf = []
    ;   tr_accusative_last(Before, After0) -> After = After0, Inf = []
    ;   tr_intransitive_ainf(L, After0, Inf, After)
    ),
    tr_uncomma(Before, BeforeT), tr_tonic_dative(foreign, BeforeT, BeforeU0),   % `A mí me gusta el pan'
    %% ... and adverbs before them, which are the clause's: `Forse è venuto
    %% il momento di porsi la stessa domanda' is the moment to ask it having
    %% come, perhaps
    tr_front_adverbs(BeforeU0, Advs, BeforeU),
    tr_split_clitics(foreign, BeforeU, unsaid(none), FP, FN, [], Clitics0),
    tr_reflexive_off(foreign, Clitics0, Clitics, L, LV),
    %% (the reflexive's perfect is made with the copula: `si è stretto' is no
    %% passive, as tr_read_generic/4 already says)
    tr_si_perfect(LV, none, A0, A),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', A),
    tr_after_nrc(After, AfterU, Wrap),
    %% A RELATIVE CLAUSE IN THE SUBJECT KEEPS ITS COMMAS: `Ne fa testo il dott
    %% Di Pietro il quale, anziché ..., si difende dai lanciatori di fango,
    %% scappando' -- read with them out, the insertion after `il quale' was
    %% written after the verb and the gerund lost its comma
    %% NOT ONLY ... BUT, WITH THE COMMA BEFORE `but' KEPT: read with the
    %% commas out, the comma the source set before `ma' was lost
    (   Wrap == none, tr_nonly_start(After), memberchk(comma, After),
        tr_subject_after(After, FP, FN, Rest0, Subject), Subject = nonly(_, _, _),
        tr_complements(foreign, Rest0, Back)
    ->  true
    ;   Wrap == none, append(_, [w(RW, _), comma|_], After), tr_relative_word(foreign, RW),
        tr_subject_after(After, FP, FN, [], Subject), Subject = rc(_, _, _)
    ->  Back = []
    %% A COMMA AND A COORDINATOR END AN INVERTED SUBJECT, and what follows
    %% them is the clause's: `È venuto il momento di porsi la stessa domanda
    %% che gli stati si posero ..., e decidere se ...'. Read with the commas
    %% out first, every length of subject read the relative clause again
    %% with the rest of the sentence in it -- 123 million inferences for
    %% that one, where the subject up to the comma is found at once
    %% -- but never before a PHRASE, which joins the subject: `sólo cabe la
    %% paciencia, y el ridículo de los que los utilizan ...' is patience and
    %% ridicule remaining, and ended at the comma the ridicule was an object
    %% of a verb that takes none. The first phrase agrees with the verb, as a
    %% subject after its verb does in the lesson's languages, and the second
    %% takes the phrases that say which (co/3)
    %% (with the comma or without it, and only where the verb says ONE: two
    %% phrases after a plural verb are what fo_agreeing/3 already reads)
    ;   Wrap == none, FN == singular,
        append(Zone0, [Co|Tail0], After), Co = w(CW, CC), tr_coord(foreign, Co),
        ( append(Zone, [comma], Zone0) -> true ; Zone = Zone0 ), Zone \== [], \+ memberchk(comma, Zone),
        tr_uncomma(Tail0, Tail), Tail = [D|_], D = w(_, _), tr_determiner(foreign, D, _, _),
        %% (never between two adjectives of one noun: `mi ha colpito il nuovo
        %% e diverso approccio' is one approach, new and different -- and
        %% `diverso' is also the determiner `several', so the approach was
        %% two subjects, the new one and several approach, and the verb went
        %% plural)
        \+ ( last(Zone, ZW), ZW = w(_, _), tr_is(foreign, ZW, adjective), tr_is(foreign, D, adjective) ),
        tr_subject_after(Zone, FP, FN, [], Subject1), Subject1 \= null(_, _),
        member(N2, [singular, plural]), tr_subject_after(Tail, third, N2, Rest2, Subject2), Subject2 \= null(_, _),
        Subject = co(w(CW, CC), Subject1, Subject2), tr_complements(foreign, Rest2, Back)
    ->  true
    ;   Wrap == none, append(Zone, [comma, Co|Tail], After), Co = w(_, _), tr_coord(foreign, Co), Zone \== [],
        \+ ( Tail = [D|_], D = w(_, _), tr_determiner(foreign, D, _, _) ),
        tr_uncomma(Zone, ZoneU),
        tr_subject_after(ZoneU, FP, FN, Rest1, Subject), Subject \= null(_, _),
        append(Rest1, [comma, Co|Tail], RestC1), tr_complements(foreign, RestC1, Back)
    ->  true
    ;   tr_subject_after(AfterU, FP, FN, Rest, Subject0), Subject0 \= null(_, _),
        %% A TIME THAT SAYS WHICH ONE AFTER AN INTRANSITIVE VERB IS WHEN, never who:
        %% `Murió la semana pasada' died last week, and the week was the one who
        %% died (`The past week died'), as `Llegó el lunes' was Monday arriving
        \+ tr_time_which(Subject0),
        (   tr_wrap_nrc(Wrap, Subject0, Rest, Subject)
        ->  %% what follows the subject is read with the commas the source set
            (   Wrap == none, Rest \== [], tr_rest_commas(After, AfterU, Rest, RestC),
                tr_complements(foreign, RestC, Back0)
            ->  Back = Back0
            ;   tr_complements(foreign, Rest, Back)
            )
        %% ... AND A RELATIVE CLAUSE AFTER A COMMA, WHERE PHRASES OF THE
        %% VERB'S FOLLOW THE SUBJECT: `mi ha colpito il nuovo approccio alla
        %% vita pubblica, che poggia sulle piccole cose' -- the clause hangs
        %% on the last phrase before its comma, as 1.7.2 hangs one, and
        %% read as the subject's alone the subject had to end at the comma
        ;   Wrap = nrc(Role, RS), Rest \== [], Subject = Subject0,
            tr_complements(foreign, Rest, Back0), append(PreB, [LastB], Back0),
            tr_nrc_on(LastB, Role, RS, LastB1), append(PreB, [LastB1], Back)
        )
    ->  true
    %% ... and a subject that ends at a comma is looked for before it:
    %% `Regolamenta il ministro, ma senza penalizzare il vivere civile' read
    %% with its commas out ran `il ministro ma' on as one phrase, no subject
    %% read, and the imperative took the sentence -- regulate the minister
    ;   Wrap == none, append(Zone, [comma|Tail], After), Zone \== [], \+ memberchk(comma, Zone),
        tr_subject_after(Zone, FP, FN, Rest1, Subject), Subject \= null(_, _),
        append(Rest1, [comma|Tail], RestC), tr_complements(foreign, RestC, Back)
    ), !,
    findall(opron(W), member(W, Clitics), Cs),
    %% the adverbs stood in front and are written back there, where both
    %% languages and English put them: `Quizás ha venido el momento',
    %% `Perhaps the moment has come' -- written after the verb, it was `Ha
    %% venido quizás el momento', and `Qui dominava il generale' `Dominava
    %% qui il generale', which is neither the source's order nor a statement's
    findall(frn(adv(X)), member(X, Advs), AC),
    append([AC, Cs, Inf, [subj_here|Back]], Comps),
    S = s(none, Subject, g(LV, T, A, Neg), Comps).

%% ... AND WITH ITS ADJUNCTS BEFORE THE SUBJECT, OR A MODAL BEFORE IT.
%% `Palermo - deve finire in tribunale l'arcivescovo di Monreale' is the
%% archbishop who must end up in court: the phrase after the verb's
%% adjuncts that agrees with it is the subject, read as an object it said
%% that somebody nobody named must finish him. A modal says nothing of an
%% object itself -- the infinitive after it does, and one the lesson calls
%% intransitive takes none, so the phrase is the modal's subject too. The
%% adjuncts stay where the source had them and the subject's place travels
%% as subj_here, so the lesson's writer keeps the order and English's puts
%% the subject first. Tried after the clause above, so a subject right
%% after its verb reads as it did.
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, Before, g(L, T, A, FP, FN), After),
    tr_uncomma(Before, BeforeU),
    tr_split_clitics(foreign, BeforeU, unsaid(none), FP, FN, [], Clitics0),
    (   tr_solve(intransitive(L))
    ->  After1 = After, Inf = []
    ;   atom(L), ( tr_class_of(L, modal) ; tr_about_to(L) ), After = [w(IW, _)|After1],
        tr_solve(infinitive_of(IW, IL)), tr_solve(intransitive(IL))
    ->  Inf = [inf(IL)]
    ),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', A),
    tr_reflexive_off(foreign, Clitics0, Clitics, L, LV),
    tr_uncomma(After1, AfterU),
    %% the words with the source's commas first, when the phrases before the
    %% subject have none: `... soltanto quelli che ... si chiamano Giglio,
    %% Eolie, Ustica, ...' read without them ran the names together
    (   memberchk(comma, After1), AfterW = After1 ; AfterW = AfterU ),
    append(Mid, SubjStart, AfterW), SubjStart \== [], \+ memberchk(comma, Mid),
    ( Inf == [] -> Mid \== [] ; true ),
    %% (never on an article, which is the next phrase's: `È andata dalla casa'
    %% went from the house, and with `andare' intransitive, `da la' was a
    %% phrase of `from' with the pronoun her and `casa' the subject -- `Ha ido
    %% desde ella casa'; `dall'altra' the same, `desde él otros')
    \+ ( last(Mid, LM), LM = w(_, _), tr_determiner(foreign, LM, _, _) ),
    %% (nor between an article with its adjective and the noun they go with:
    %% `Va sottobraccio alla bella moglie Paola' goes arm in arm with his
    %% beautiful wife, and read from `moglie' the wife was the one who went,
    %% arm in arm with the beautiful one)
    \+ ( append(_, [D, J], Mid), D = w(_, _), tr_determiner(foreign, D, _, _), J = w(_, _), tr_is(foreign, J, adjective),
         SubjStart = [N1|_], N1 = w(_, lower), tr_is(foreign, N1, noun) ),
    %% (nor at a name apposed to a person's noun: `la bella moglie Paola' is
    %% one person, and read from `Paola' she went arm in arm with the wife)
    \+ ( last(Mid, LM), LM = w(_, lower), SubjStart = [w(_, upper)|_], fo_animate_phrase([LM]),
         append(_, [D2|Tail2], Mid), D2 = w(_, _), tr_determiner(foreign, D2, _, _), last(Tail2, LM) ),
    %% (nor at an article right after a name, whose apposition it opens: `con
    %% Gilda l'ex compagna di Vinicius De Moraes al fianco' is Gilda, his ex
    %% partner, and read from `l'ex' the partner was the one who went -- a
    %% phrase for a person, as an apposition to a name is: `circolava in
    %% Brasile la versione di una cantante' is the version that went round)
    \+ ( last(Mid, LN), LN = w(_, upper), tr_name_word(foreign, LN), SubjStart = [D3|SR], D3 = w(_, _),
         tr_determiner(foreign, D3, _, article), tr_head_person(SR) ),
    tr_complements(foreign, Mid, MidComps), forall(member(X, MidComps), tr_adjunct(X)),
    (   tr_subject_after(SubjStart, FP, FN, Rest, Subject), Subject \= null(_, _),
        tr_complements(foreign, Rest, Back)
    ;   %% ... and a subject that ends at a comma, found before it, what
        %% follows read with the comma: `Dovrebbero transitare più o meno 290
        %% mila vetture, tra cui 40 mila di stranieri' -- the cars and, after
        %% the comma, the foreigners' among them. With the comma in, no
        %% subject was found, and with every comma out `among them' was the
        %% verb's (`The cars should transit among them the cars'), as the
        %% reader of an intransitive verb's subject has it
        append(Zone, [comma|Tail], SubjStart), Zone \== [], \+ memberchk(comma, Zone),
        tr_subject_after(Zone, FP, FN, Rest1, Subject), Subject \= null(_, _),
        append(Rest1, [comma|Tail], RestC), tr_complements(foreign, RestC, Back)
    ), !,
    findall(opron(W), member(W, Clitics), Cs),
    append([Cs, Inf, MidComps, [subj_here|Back]], Comps),
    S = s(none, Subject, g(LV, T, A, Neg), Comps).

%% AN IMPERSONAL MODAL NAMES ITS SUBJECT BY WHAT IT IS. `Hay que tomar
%% precauciones' is one must take precautions: `hay que' has no subject and
%% could have none, and read as a verb nobody named it said `he must'. The
%% lesson says what it is -- `The impersonal modal "hay que" means "must".'
%% -- and the IR carries the impersonal subject a `se debe' or a `si deve'
%% carries, so every writer has one: `Bisogna prendere precauzioni', `One
%% must take precautions'.
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, Before, g(L, T, A, third, singular), After),
    atom(L), tr_solve(impersonal(L)), tr_class_of(L, modal),
    tr_uncomma(Before, BeforeU),
    tr_split_clitics(foreign, BeforeU, unsaid(none), third, singular, [], Clitics),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', A),
    tr_complements(foreign, After, Comps0), !,
    findall(opron(W), member(W, Clitics), Cs),
    append(Cs, Comps0, Comps),
    S = s(none, impersonal, g(L, T, A, Neg), Comps).

%% A COPULA THAT AGREES WITH THE PHRASE AFTER IT: `L'altro anello debole della
%% catena sono gli anziani' -- the elderly are the other weak link of the
%% chain. Italian and Spanish say what it is first and give the verb the
%% number of who it is said of; with the phrase before the verb for the
%% subject the verb's plural disagreed with it, and the sentence was refused.
%% It reads as the ordinary statement, the phrase after the verb its subject
%% and the one before it what it is, so every writer puts the subject first:
%% `Los ancianos son el otro eslabón débil de la cadena'. Tried only after
%% the plain reading has failed, which is what the disagreement does.
tr_read_statement0(foreign, Words0, none, S) :-
    Words0 = [D0|_], tr_phrase_opener(D0),
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, Before, g(CL, T, simple, third, plural), After), tr_copula_lexeme(CL),
    After = [W2|_], tr_plural_start(W2),
    Before = [D|_], tr_determiner(foreign, D, _, DK), memberchk(DK, [article, demonstrative, possessive]),
    nb_setval('$tr_read_group', CL), nb_setval('$tr_read_aspect', simple),
    tr_complements(foreign, Before, [obj(NP1)|PPs]), fo_np_number(NP1, singular), tr_subject_comps(PPs),
    tr_phrase_rest(foreign, After, NP2, Rest), fo_np_number(NP2, plural),
    ( Rest == [] -> More = [] ; tr_complements(foreign, Rest, More) ), !,
    append([obj(NP1)|PPs], More, Comps),
    S = s(none, NP2, g(CL, T, simple, Neg), Comps).
%% A CLEFT: `A chiederlo è la procura di Palermo' is the prosecution asking
%% for it. Italian puts what is done first -- the word the lesson says
%% begins the cleft (`The word "a" begins the cleft.'), the infinitive and
%% the pronouns joined to it -- then the copula, and who does it last. It
%% reads as the statement it makes, in the copula's tense, with the
%% subject's place kept after the verb as subj_here: Spanish writes `Lo pide
%% la fiscalía de Palermo', and English's writer puts the subject first.
%% The words after the copula are read WITH their commas, as complements
%% are, and the subject is built from them: read as a subject side they
%% lost the commas of the list inside the relative clause (`accuse di
%% concussione, corruzione, falso ideologico e truffa').
tr_read_statement0(foreign, Words0, none, S) :-
    Words0 = [w(CW, _), w(IW, _)|Ws1], tr_solve(begin(CW, cleft)),
    tr_solve(infinitive_of(IW, L)), tr_known(foreign, L),
    append(Cls0, [w(Cop, CC)|SubjWords], Ws1), SubjWords \== [],
    forall(member(X, Cls0), X = w(_, enclitic)),
    tr_group_from(foreign, [w(Cop, CC)], [], g(CL, T, simple, third, N), []), tr_copula_lexeme(CL),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', simple),
    tr_complements(foreign, SubjWords, [obj(NP)|More]),
    ( More == [] -> Subject = NP ; tr_subject_comps(More), Subject = with(NP, More) ),
    tr_number_agrees(foreign, Subject, N), !,
    findall(opron(w(C, lower)), member(w(C, _), Cls0), Cs),
    append(Cs, [subj_here], Comps),
    S = s(none, Subject, g(L, T, simple, no), Comps).

%% ... AND ITS INFINITIVE IN THE PERFECT: `mentre è il solo Segni ad aver
%% sposato questa opzione' is only Segni who has embraced it -- the cleft
%% with `aver' and a participle for its infinitive (tr_infinitive_group/5),
%% in the copula's tense, the perfect its aspect. The infinitive was the
%% auxiliary's alone, `have', and the participle left over read nothing.
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, [], g(CL, T, simple, P, N), After), tr_copula_lexeme(CL),
    append(SubjWords, [w(CW, _)|Rest0], After), SubjWords \== [],
    tr_solve(begin(CW, cleft)),
    tr_infinitive_group(Rest0, L, perfect, Cls0, Rest1),
    tr_cleft_who(SubjWords, P, N, Subject),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', perfect),
    tr_complements(foreign, Rest1, Comps0), !,
    findall(opron(w(C, lower)), member(w(C, _), Cls0), Cs),
    append([subj_here|Cs], Comps0, Comps),
    S = s(none, Subject, g(L, T, perfect, Neg), Comps).
%% ... AND THE CLEFT WITH ITS COPULA FIRST: `In sua assenza non sarà lui a
%% dialogare con Paolo Brosio' is HE who will not converse with him, `è
%% Paolo a parlare' Paolo who speaks. The copula, who it is, the word the
%% lesson says begins the cleft and the infinitive: it reads as the statement
%% it makes, in the copula's tense and with its denial, the subject kept
%% where the source had it, after the verb (subj_here) -- `no dialogará él
%% con Paolo Brosio'. Only a pronoun or a name is who it is: `è il primo a
%% parlare' is the first one to speak, and no cleft
%% ... the copula in the perfect too, and an adverb between commas after who it is: `È stato lui, infatti, a rivelare
%% tutti i retroscena della vicenda' -- it was he, in fact, who revealed them, the perfect's statement (`ha rivelato
%% lui'); with the simple tenses alone it was a copula with nobody named, `It has been him, to reveal'
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    tr_group_from(foreign, Words, [], g(CL, T, A, P, N), After), tr_copula_lexeme(CL), memberchk(A, [simple, perfect]),
    append(SubjWords0, [w(CW, _), w(IW, _)|Rest], After), SubjWords0 \== [],
    tr_solve(begin(CW, cleft)), tr_solve(infinitive_of(IW, L)), tr_known(foreign, L),
    ( append(SubjWords, [comma, AW, comma], SubjWords0), SubjWords \== [], AW = w(_, _), tr_plain_adverb(foreign, AW)
    ->  Mids = [mid(adv(AW))]
    ;   SubjWords = SubjWords0, Mids = []
    ),
    tr_cleft_who(SubjWords, P, N, Subject),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', A),
    tr_complements(foreign, Rest, Comps0), !,
    append([subj_here|Mids], Comps0, Comps),
    S = s(none, Subject, g(L, T, A, Neg), Comps).

%% A HEADLINE LEAVES THE COPULA OUT, AND IT IS NOT A FRAGMENT.
%% `Evacuata la Tate Gallery.' is `La Tate Gallery e stata evacuata' with
%% the copula dropped, which is what a headline does -- so it reads as the
%% PASSIVE it is, a participle at the head with the subject after it, and
%% the IR carries an ordinary statement. There is no fragment in the
%% grammar and this shape needed none.
%%
%% The participle agrees with the subject, and only its NUMBER is asked
%% for here: the gender says the same thing the subject's noun already
%% says, and fo_subject_after/5 checks the number as it checks a
%% question's.
%% ... THE PARTICIPLE'S OWN NUMBER, which the lesson states (`"processate"
%% is the plural of "processata".'): the number was taken from the phrase
%% alone, so `"processate il vescovo"' -- a plural feminine participle
%% before a masculine singular -- read as `the bishop has been processed'.
%%
%% THE COPULA IS WRITTEN BACK. A headline read this way comes out as the
%% full sentence in every language -- `La casa e stata evacuata', `The
%% house has been evacuated' -- because the IR carries the claim and not
%% the typography. What is lost is a headline's shape, not its meaning.
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    Words = [w(P, _)|After], After \== [],
    tr_participle_here(foreign, P, L),
    tr_participle_number(P, N),
    tr_uncomma(After, AfterU),
    fo_subject_after(AfterU, third, N, SubjWords, Rest), SubjWords \== [],
    tr_subject(foreign, none, SubjWords, third, N, Subject),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', passive_perfect),
    tr_complements(foreign, Rest, Comps0),
    %% (a word that says where or when right after the subject is the
    %% clause's relative one, not an indirect question: `i nuclei DOVE è
    %% minore l'istruzione', Spanish's `donde' and not `dónde')
    (   Comps0 = [wh(Q, S0)|Cs0], memberchk(Q, [where, when]) -> Comps = [rwh(Q, S0)|Cs0] ; Comps = Comps0 ), !,
    S = s(none, Subject, g(L, present, passive_perfect, Neg), Comps).

%% A GERUND HEADS A CLAUSE OF ITS OWN, AND ITS SUBJECT IS THE ONE BEFORE
%% IT. `..., escludendo che il militare voleva ...' is `..., excluding that
%% the soldier wanted ...': a clause with a verb, no subject and no
%% auxiliary, which the join of 1.6.1 already knows how to hang off the
%% clause before it. The aspect carries it -- g(L, present, gerund, Neg) --
%% and the subject is `none', the one subject term the writers had no
%% clause for until now.
tr_read_statement0(Side, Words0, none, S) :-
    tr_negation(Side, Words0, Words, Neg),
    Words = [w(G, _)|Rest], Rest \== [],
    tr_gerund_here(Side, G, L),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', gerund),
    tr_complements(Side, Rest, Comps), !,
    S = s(none, none, g(L, present, gerund, Neg), Comps).

%% THE FORM OF A COMMAND IS A STATEMENT WHERE THE SENTENCE SAYS IT IS ONE. Italian's present
%% indicative of the second person plural is its imperative (`aprite', `rispondete'), and the
%% vocabulary states it the imperative and nothing else: stated a person too (corpus/build.pl), it was
%% the statement before the command in every sentence of the controls that had one, and the
%% participle's feminine plural (`proibite') a verb, which made a headline a clause. A PLURAL
%% `YOU' NAMED AT THE HEAD IS WHAT SAYS IT: `... e voi rispondete col presidenzialismo' -- the
%% group is the plural form's (`rispondono'), with the second person the pronoun gives it
tr_read_statement0(foreign, Words0, none, S) :-
    tr_negation(foreign, Words0, Words, Neg),
    Words = [w(PW, PC), w(V, VC)|Rest0], atom(PW), atom(V),
    (   VC \== upper, tr_command_plural_of(V, Pl), tr_plural_you(PW)
    ->  tr_group_at(foreign, [w(Pl, VC)|Rest0], g(L, T, A, third, plural), After),
        nb_setval('$tr_read_group', L),
        nb_setval('$tr_read_aspect', A),
        tr_complements(foreign, After, Comps), !,
        S = s(none, pronoun(second, plural, w(PW, PC)), g(L, T, A, Neg), Comps)
%% ... AND SO IS A FORM OF `stare' WITH A GERUND AFTER IT, where nobody is named: `state proseguendo
%% nel cosiddetto gioco del cerino' is you are continuing. A command of that verb takes an
%% adjective or a place (`state attenti'); the gerund makes the progressive. (One clause for the
%% two, with the form of the command asked first: a denial read twice and a pronoun's lexeme looked
%% for in every statement was 0.4 % of the heaviest sentences)
    ;   PC \== upper, tr_command_plural_of(PW, Pl), tr_gerund_here(foreign, V, _)
    ->  tr_group_at(foreign, [w(Pl, PC), w(V, VC)|Rest0], g(L, T, progressive, third, plural), After),
        nb_setval('$tr_read_group', L),
        nb_setval('$tr_read_aspect', progressive),
        tr_complements(foreign, After, Comps), !,
        S = s(none, null(second, plural), g(L, T, progressive, Neg), Comps)
    ).

%% AN IMPERATIVE HAS NO SUBJECT AND NAMES ONE ANYWAY -- the person spoken
%% to -- so the aspect carries it and the subject is `none', beside the
%% gerund above. `Come el pan.', `No comas el pan.', `Mangia il pane.',
%% `Eat the bread.', `Do not eat the bread.'
%%
%% IT IS TRIED LAST, WHICH IS WHAT MAKES IT A STRICT ADDITION. A bare
%% third person with nothing in front of it was REFUSED -- 1.6.0's rule,
%% `Estaba cansado' could be anybody -- so every sentence that read before
%% reads by the same clauses, and what changes is only what used to refuse.
%%
%% AND ONLY A FORM THE LESSON CALLS AN IMPERATIVE READS AS ONE, which is
%% what keeps the two refusals apart. `come' is the imperative of `come'
%% and the third person of it besides, so `Come el pan.' is read; `comia'
%% is neither, so `Comia el pan.' keeps its refusal exactly as before. The
%% cost is the other half of that: where the two forms are spelled the
%% same the sentence is genuinely ambiguous and the imperative is the
%% reading taken, because it is the one that names its subject.
%%
%% A PRONOUN BEFORE IT MEANS IT WAS DENIED. Both languages join the pronouns
%% to an AFFIRMATIVE imperative -- `dame', `cómelo', `mangialo' -- and put
%% them before only a denied one, `no lo comas', `non lo mangiare'. So `Le
%% gusta el pan' and `Nos espera un mes' are statements about somebody
%% nobody named, where they had read as commands.
%% ... AND AFTER AN AFFIRMATIVE ONE THE PRONOUNS JOINED TO IT (tr_enclitics/3):
%% `correggetemi' is correct me, the pronoun the verb's as a clitic before it
%% would have been
%% ... AND AFTER A COORDINATOR A DENIED ONE THAT NO STATEMENT COULD SHARE:
%% `sono d'accordo, ma non pensate che l'università si basi su questi soldi'
%% is I agree, but do not think -- `pensate' is the form of no person the
%% lesson states, so nothing could share the subject before it, and with
%% the command standing down (tr_read_joined/5) the sentence was refused
tr_read_statement0(foreign, Words0, none, S) :-
    ( tr_global('$tr_no_command', NC) -> true ; NC = no ),
    ( memberchk(NC, [yes, third]) -> NoCommand = NC ; NoCommand = no ),
    tr_negation(foreign, Words0, Words, Neg),
    append(Clitics0, [w(V, VC)|Rest1], Words), \+ memberchk(comma, Clitics0), VC \== upper,
    ( Neg == no -> Clitics0 == [] ; true ),
    (   NoCommand == yes -> Neg == yes, \+ tr_verb_form_word(V)
    ;   NoCommand == third -> \+ tr_third_person_command(Neg, V, Rest1)
    ;   tr_that_follows(Rest1) -> \+ tr_third_person_command(Neg, V, Rest1)
    ;   true
    ),
    tr_imperative_here(foreign, Neg, V, F),
    %% (never a verb of seeming, whose command nobody gives: `Sembra di sentire un'eco dell'apologo' is it seems to
    %% hear an echo of the fable, and read as the command English wrote `Seem to feel an echo')
    \+ ( atom(F), nb_getval('$tr_seem_lexemes', SLs), memberchk(F, SLs) ),
    tr_imperative_number(F, L, Subject),
    forall(member(w(C, _), Clitics0), tr_clitic(none, C)),
    tr_joined_clitics(Neg, Rest1, Joined, Rest),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', imperative),
    append(Clitics0, Joined, Clitics1),
    tr_reflexive_off(foreign, Clitics1, Clitics, L, LV),
    tr_complements(foreign, Rest, Comps0), !,
    findall(opron(W), member(W, Clitics), Cs),
    append(Cs, Comps0, Comps),
    S = s(none, Subject, g(LV, present, imperative, Neg), Comps).
%% THE COMMAND OF THE FIRST PERSON PLURAL: `Finiamola di considerare i parchi
%% un freno allo sviluppo' -- let us stop considering them one. Italian's is
%% spelled as its indicative is and Spanish's as its subjunctive, and each
%% lesson states which (`"finiamo" is the hortative of "finisce".', `"dejemos"
%% is the hortative of "deja".'). A pronoun joined to it is what makes it a
%% command, because no indicative takes one: `Finiamo il pane' stays what we
%% do. The aspect carries it, g(L, present, hortative, Neg), and the subject
%% is `none', as an imperative's is; English writes `let us'.
tr_read_statement0(foreign, Words0, none, S) :-
    \+ tr_global('$tr_no_command', yes),
    Words0 = [w(V, VC)|Rest1], VC \== upper,
    tr_solve(hortative_of(V, L)), tr_known(foreign, L),
    tr_joined_clitics(no, Rest1, Joined, Rest), Joined = [_|_],
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', hortative),
    tr_reflexive_off(foreign, Joined, Clitics, L, LV),
    tr_complements(foreign, Rest, Comps0), !,
    findall(opron(W), member(W, Clitics), Cs),
    append(Cs, Comps0, Comps),
    S = s(none, none, g(LV, present, hortative, no), Comps).
%% A THIRD PERSON SINGULAR WITH NOTHING BEFORE IT BUT CLITICS, READ LAST.
%% `Es la hora del caldo', `Se ha equivocado', `¿Cómo ha podido salir así?':
%% the lesson's languages leave out a subject the verb and the page before
%% it already say, and 1.6.0 refused every such sentence because nothing in
%% it says WHO -- `Estaba cansado' could be anybody. That is true and it is
%% a fact about ENGLISH, which must name a subject. Spanish and Italian need
%% not, so the reading is taken and the IR carries null(third, singular):
%% the lesson's writer leaves the subject out exactly as the source did, and
%% English's writer REFUSES it rather than guess he, she or it.
%%
%% IT IS TRIED AFTER THE IMPERATIVE, which is what keeps `Come el pan.' the
%% command it was; and after every other statement shape above, so a
%% sentence that read before reads by the same clause. What it changes is
%% only what used to refuse -- including a verb before its subject that no
%% lesson calls intransitive (`Dominava il generale.'), which now reads as a
%% null subject with an OBJECT, the plain Romance reading of those words.
tr_read_statement0(foreign, Words0, Asked, S) :-
    Asked \= subject(_),
    tr_negation(foreign, Words0, Words, Neg),
    %% ... AND THE PLURAL'S TOO IN A RELATIVE CLAUSE, where the subject after the
    %% verb is found from this reading (tr_rel_subject_after/3): `la casa en
    %% la que duermen los perros' had the one reading for `duerme el perro'
    %% and none for `duermen los perros'
    ( Asked == rel -> true ; N = singular ),
    tr_group_from(foreign, Words, Before, g(L, T, A, third, N), After),
    tr_denial_before(foreign, Neg, Words0, Before),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', A),
    tr_uncomma(Before, BeforeU0), tr_tonic_dative(foreign, BeforeU0, BeforeU),
    tr_split_clitics(foreign, BeforeU, unsaid(Asked), third, N, [], Clitics0),
    tr_reflexive_off(foreign, Clitics0, Clitics, L, LV),
    tr_si_perfect(LV, null(third, N), A, A1),
    tr_complements(foreign, After, Comps00), !,
    %% (and a bare name after the verb is its subject, as tr_read_generic/4 says)
    tr_name_subject(foreign, null(third, N), third, N, L, LV, Comps00, Subject, LV1, Comps0),
    findall(opron(W), member(W, Clitics), Cs),
    append(Cs, Comps0, Comps),
    S = s(Asked, Subject, g(LV1, T, A1, Neg), Comps).
%% THE PRONOUN OF THE VERB'S OWN PERSON RIGHT AFTER THE COPULA, BEFORE THE PHRASE IT IS, IS THE SUBJECT: `Ero io il re'
%% is I was the king, and `decise che dovevo assolutamente essere io il San Francesco del film di Zeffirelli' I had to
%% be Saint Francis -- the pronoun stressing who. Read with it after the copula there were two phrases for one
%% predicate, and nothing read. The words are read again with the pronoun first, as `Io ero il re' reads; tried when
%% nothing else read (the third person's is tr_ident_fix/3's, `è lui il trionfatore')
tr_read_statement0(foreign, Words, Asked, S) :-
    Asked == none, nb_getval('$tr_pron_copula', yes),
    append(Pre, [w(P, PC)|Post], Words), Pre = [_|_], Post = [D|_], D = w(_, _), tr_determiner(foreign, D, _, _),
    atom(P), tr_subject_pronoun(foreign, P, Per, Num), memberchk(Per, [first, second]),
    last(Pre, w(V, _)), atom(V), once(( ( tr_form(V, L, _, _, _) ; tr_solve(infinitive_of(V, L)) ), atom(L), tr_copula_lexeme(L) )),
    tr_group(foreign, Pre, [], g(_, _, _, Per, Num), _, _), !,
    append(Pre, Post, Rest),
    tr_read_statement0(foreign, [w(P, PC)|Rest], Asked, S).
%% English's is the BASE FORM, and its denial keeps the `do' the negation
%% took the `not' out of: `Do not eat the bread.'
%% ... and `let us' and the base form is the command of the first person
%% plural, `Let us stop considering the parks a brake'
tr_read_statement0(english, Words0, none, S) :-
    tr_negation(english, Words0, W1, Neg),
    W1 = [w(let, _), w(us, _), w(V, _)|Rest],
    tr_imperative_here(english, Neg, V, L),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', hortative),
    tr_complements(english, Rest, Comps), !,
    S = s(none, none, g(L, present, hortative, Neg), Comps).
tr_read_statement0(english, Words0, none, S) :-
    tr_negation(english, Words0, W1, Neg),
    ( Neg == yes, W1 = [w(do, _)|W2] -> true ; W2 = W1 ),
    W2 = [w(V, _)|Rest],
    tr_imperative_here(english, Neg, V, L),
    nb_setval('$tr_read_group', L),
    nb_setval('$tr_read_aspect', imperative),
    tr_complements(english, Rest, Comps), !,
    S = s(none, none, g(L, present, imperative, Neg), Comps).
%% the copula, its predicate and the infinitive that is its subject (above); with PART `participle', only where the
%% predicate's last word is a participle the lesson calls an adjective too
tr_copula_adj_inf(Words0, Part, S) :-
    tr_copula_head(Words0),
    tr_negation(foreign, Words0, [w(C, _)|Rest], Neg),
    atom(C), tr_form(C, CL, singular, T, third), tr_copula_lexeme(CL),
    append(PredW, [w(V, VC)|SubjW], Rest), PredW = [_|_], \+ memberchk(comma, PredW),
    (   Part == participle
    ->  last(PredW, w(P, _)), atom(P), tr_solve(participle_of(P, _)), tr_is(foreign, w(P, lower), adjective)
    ;   true
    ),
    atom(V), tr_solve(infinitive_of(V, F)), tr_known(foreign, F), \+ tr_is(foreign, w(V, lower), noun),
    forall(member(X, PredW), ( X = w(_, _), \+ tr_opens_clause(X), \+ tr_is(foreign, X, preposition) )),
    nb_setval('$tr_read_group', CL), nb_setval('$tr_read_aspect', simple),
    %% (the participle alone is read as the participle it is too, and taken as the adjective here)
    (   tr_complements(foreign, PredW, [P0]), P0 = adj(_) -> true
    ;   Part == participle, PredW = [W1], P0 = adj([W1])
    ),
    tr_subject(foreign, none, [w(V, VC)|SubjW], third, singular, Subject), Subject = infs(_, _), !,
    S = s(none, Subject, g(CL, T, simple, Neg), [P0, subj_here]).

%% what there is comes first -- after the adverbs the verb has, if any: `non
%% vi saranno QUINDI altri vincoli' is there will then be no other
%% restrictions, and with the adverb first the reader found no `there is'
%% and the sentence read as THEY will not be, which English wrote `they will
%% not there is'. The writer puts the adverbs right after the verb.
tr_existential_first([obj(_)|_]) :- !.
tr_existential_first([adv(_)|Cs]) :- tr_existential_first(Cs).
%% ... and after an insertion between two commas: `Hubo, sin embargo, un
%% desliz protocolario' -- there was, however, a slip. With the comma first
%% the reader found no `there is', and the verb was read with nobody named
%% for its subject, in the plural `hay' is also stated as: `C'erano', and
%% English's `They thered is'.
tr_existential_first([sep|Cs]) :- tr_existential_first(Cs).
%% (a verb that shows or declares what one is, with a bare word that is an adjective too after it:
%% `i Tecnici ... assolvono le industrie e si mostrano ottimisti' show themselves optimistic, and read as
%% the passive's subject `optimists are displayed')
tr_predicate_after_reflexive(L, np(none, none, [], w(NW, _), plural)) :-
    atom(L), atom(NW), tr_is(foreign, w(NW, lower), adjective),
    tr_lexeme_across(L, english, E), memberchk(E, [displays, shows, demonstrates, reveals, feels, declares, considers,
                                                    deems, believes, proves, judges, presents, maintains, keeps]), !.

%% THE SUBJECT'S PLACE IS AFTER THE INFINITIVE THE FINDER STEPPED OVER: `si
%% possono capire i loro problemi' -- their problems can be understood, and
%% with the place kept straight after the modal Spanish wrote `se pueden sus
%% problemas entender'
tr_subject_place([w(V, _)|_], [C|Cs], [C, subj_here|Cs]) :-
    ( C = inf(_) ; C = infx(_, _, _) ), atom(V), tr_solve(infinitive_of(V, _)), !.
tr_subject_place(_, Cs, [subj_here|Cs]).
%% A SUBJECT NEVER ENDS ON A COORDINATOR AND ADJUNCTS: `perché celebrare un
%% processo che avrebbe accolto la linea difensiva e nonostante ciò avrebbe
%% condannato l'imputato' -- the verb after `nonostante ciò' is the relative
%% clause's second verb (tr_relative_clause/4's join), and taken for the
%% sentence's own, the subject was the infinitive and its clause up to the
%% coordinator and the trial the one who would have condemned the defendant.
%% A few words at most after the coordinator, none a comma's, all adjuncts
tr_dangling_coordinator(foreign, Before) :-
    Before = [_, _, _|_],
    reverse(Before, Rev),
    between(1, 4, N), length(RFront, N), append(RFront, [Co|Pre], Rev), Pre = [_|_],
    Co = w(CW, _), atom(CW), tr_coord(foreign, Co),
    reverse(RFront, Front), Front = [F1|_], F1 = w(FW, _), \+ memberchk(comma, Front),
    %% (a relative word before it: `L'azione combinata del sole e di una bibita
    %% ghiacciata causa' has two phrases of `di' and no relative clause to extend;
    %% and not a word the clause has met already, which makes the coordinator
    %% join two phrases: `contro le armi e contro il nucleare ha osato')
    \+ memberchk(w(FW, _), Pre),
    ( member(w(RW, _), Pre), atom(RW), tr_relative_word(foreign, RW) -> true ),
    tr_front_adjuncts(Front, _), !.
tr_read_generic(Side, Words0, Asked, S) :-
    tr_negation(Side, Words0, Words, Neg),
    tr_subject_phase(Side, Asked, Words, Phase),
    tr_group_from(Side, Words, Before0, g(L, T, A, FP, FN), After),
    tr_denial_before(Side, Neg, Words0, Before0),             % `... ma non posso' denies `posso'
    \+ tr_dangling_coordinator(Side, Before0),                % `... che ha accolto la linea e nonostante ciò' ha condannato
    \+ tr_article_noun_of(Side, Words, Before0, After),       % `le accuse della madre' is no verb
    \+ tr_ends_on_auxiliary(Side, Before0),                   % `dopo aver mandato' is the perfect infinitive
    \+ tr_noun_after_adjective(Side, Words, Before0),         % `i rispettivi programmi' is no clause
    \+ tr_purpose_as_verb(Side, Words, Before0),              % `un solar apto para levantar' is no clause
    nb_setval('$tr_read_group', L),                           % for the complements: a bare base after a modal
    nb_setval('$tr_read_aspect', A),                          % and: a `by' phrase after a passive is its agent
    tr_insertion_off(Side, Before0, Before, Mids),            % `Cassisa, secondo l'accusa, avrebbe'
    tr_uncomma(Before, BeforeU0),                             % the subject side is read without its commas
    tr_tonic_dative(Side, BeforeU0, BeforeU),                 % `a me piace' is `mi piace'
    \+ tr_names_parted(Side, Before),                         % ... but never two names a comma parts
    \+ tr_comma_and_parted(Side, Before),                     % ... nor a phrase a comma parts from the `y' phrase after it
    \+ tr_name_after_comma(Side, Before),                     % ... nor a word and the name after its comma
    (   Side == foreign, Asked == none, FP == third, tr_si_after_object(BeforeU, SubjectWords, Clitics0)
    ->  true
    ;   Side == foreign, Asked == none, FP == third, FN == singular, tr_ci_si(BeforeU, SubjectWords, Clitics0)
    ->  true
    ;   tr_split_clitics(Side, BeforeU, Asked, FP, FN, SubjectWords, Clitics0)
    ),
    tr_phase_subject(Phase, SubjectWords),
    tr_reflexive_off(Side, Clitics0, Clitics1, L, LV00),
    %% THE REFLEXIVE THE LESSON NAMES IS A THIRD PERSON: `si' and `se' mean
    %% itself, and the first and second persons have pronouns of their own.
    %% `Che si tratti di un progetto' took `tratti' for YOU treat, the
    %% indicative's second person, with `si' its reflexive; the subjunctive's
    %% third person is what the sentence says, it is a matter of
    %% ... EXCEPT WHERE THE SOURCE SLIPPED: `como si se le hubiéramos echado'
    %% (the treebank's own text) has a `se' the verb cannot take beside the
    %% dative `le', a blend of `como si le hubiéramos echado' and `como si
    %% se le hubiese echado'. A reflexive before a dative pronoun and a first
    %% or second person's verb is read as nothing, where the sentence would
    %% be refused: `se lo dije' keeps its refusal, `se' there is the dative
    %% before an accusative, and no reading of it is dropped
    (   LV00 = reflexive(_), nonvar(FP), FP \== third
    ->  tr_slip_reflexive(Clitics1), LV0 = L
    ;   LV0 = LV00
    ),
    tr_personal_reflexive(Side, FP, FN, Clitics1, Clitics, L, LV0, LV),
    tr_subject(Side, Asked, SubjectWords, FP, FN, Subject00),
    tr_set_off_subject(Side, Before0, SubjectWords, Subject00, Subject0a),
    tr_coord_rc_fix(Side, Before0, Subject0a, Subject0),
    tr_person_agrees(Side, Subject0, FP), tr_number_agrees(Side, Subject0, FN), tr_impersonal_agrees(Subject0, FP, FN),
    %% A SECOND PERSON NOBODY NAMED IS NO SUBJUNCTIVE'S THIRD, IN A CLAUSE OF
    %% `THAT': `Lui spera che passi al Biscione' hopes that HE moves, and `passi'
    %% (stated the second person of `passa' and its subjunctive) read as YOU
    %% move -- `Espera que pasas'. The third person is the reading after it
    \+ ( Side == foreign, FP == second, FN == singular, Subject0 = null(second, singular),
         tr_global('$tr_in_that', yes), tr_second_is_subjunctive(Words, Before0) ),
    %% AN IMPERSONAL MODAL HAS NO SUBJECT BEFORE IT, and could have none:
    %% `Anche secondo l'associazione nazionale magistrati, "bisogna leggere le
    %% motivazioni"' is the association's saying so, and read with the
    %% association for the subject of `bisogna' -- the verb `needs' as well as
    %% the modal, and `secondo' the adverb `second' -- it was the association
    %% that needed to read them. The fronted phrase reads it
    \+ ( Side == foreign, atom(L), FP == third, FN == singular, Subject0 \= null(_, _), Subject0 \== impersonal,
         tr_solve(impersonal(L)), tr_class_of(L, modal) ),
    %% A BARE NOUN IN THE SINGULAR IS NO SUBJECT WHERE IT IS A VERB'S FORM TOO.
    %% The lesson's languages put a determiner before a singular subject, and
    %% `En esta versión, además, cuenta con una June Anderson en plena forma'
    %% read `cuenta con ... en plena' as the subject, an account, and `forma'
    %% as its verb, it forms -- where `cuenta' is the verb, it counts on her
    %% (EXCEPT A SHARE OF A PLURAL: `Parte de los explosivos fueron colocados' --
    %% `parte' is the verb's third person too, and a share word before `de' and
    %% a plural is the noun, with the plural's verb after it; AND A ONE OF A
    %% PLURAL: `Uno de los hombres duerme' -- `uno' is the first person of
    %% `unir' too, and a pronoun that means a part of a whole before `de' and a
    %% plural is the subject, with the singular verb after it; AND A PART OF A
    %% GROUP: `Parte del pasaje volaba por placer' is a share of the passengers,
    %% and with the singular after `de' the share's noun was read as the verb
    %% `parte', departs, and the sentence was refused -- tr_part_of_group/1)
    \+ ( Side == foreign, tr_bare_singular(Subject0), \+ tr_share_subject(Subject0),
         \+ tr_part_of_subject(Subject0), \+ tr_part_of_group(Subject0),
         SubjectWords = [w(F1, _)|_],
         tr_form(F1, L1, _, _, _), atom(L1), tr_class_of(L1, verb) ),
    %% A VERB THE LESSON CALLS REFLEXIVE TAKES `se' AS ITS OWN PRONOUN, never
    %% as the impersonal subject: `Se ha equivocado' is somebody erring, and
    %% `"equivoca" is reflexive.' says so; the subject is the one nobody named
    (   Subject0 == impersonal, LV == L, tr_solve(reflexive(L)), tr_reflexive_out(_)
    ->  Subject = null(FP, FN), LV1 = reflexive(L)
    ;   Subject = Subject0, LV1 = LV
    ),
    tr_si_perfect(LV1, Subject, A, A1),
    %% (and the complements are read in that aspect: `E si era tratto il
    %% massimo profitto da due autori cristiani' drew profit FROM them, and
    %% read under the passive the copula first said, `da' was their agent --
    %% `se había extraído ... por dos autores', the authors extracting it)
    ( A1 \== A -> nb_setval('$tr_read_aspect', A1) ; true ),
    tr_complements(Side, After, Comps00),
    %% A VERB THAT IS A PREPOSITION TOO HAS NO PERSON FOR ITS OBJECT with nothing before him, as the verb's object
    %% has: `Hace dos años que el Inter no ocupaba el primer puesto, un largo periodo PARA su propietario' is a
    %% long period for its owner, and `para' the verb (it stops) made of the period a clause that stopped him
    \+ ( Side == foreign, append(Before0, [w(VA, _)|_], Words), atom(VA), tr_is(foreign, w(VA, lower), preposition),
         Comps00 = [obj(PNP)|_], tr_of_class(PNP, person) ),
    %% A BARE NAME STRAIGHT AFTER THE VERB IS ITS SUBJECT where the lesson
    %% puts a word before a person who is the object (`The word "a" precedes
    %% the person.'): `se permite Vick alguna pequeña ironía' is Vick allowing
    %% himself some irony, and read with `se' for the impersonal subject the
    %% director was an object, `si permette Vick'. Without the word before
    %% him he cannot be one; `se' is then his reflexive.
    tr_name_subject(Side, Subject, FP, FN, L, LV1, Comps00, Subject2, LV2, Comps0),
    %% a verb the lesson calls intransitive, with nobody named before it, has
    %% its subject after it and no object: `Godranno di qualche boccata ...
    %% soltanto quelli che ...' read here as THEY enjoying those who chose,
    %% and the readers below that find the subject after the verb never ran.
    %% The reading gives up at once, or it went on to every later word that
    %% could be a verb -- 7.7 million inferences against 0.3 for that one
    %% -- and so has a verb the lesson calls reflexive, with its reflexive
    %% pronoun before it (tr_takes_subject_after/3)
    %% (a THIRD person nobody named: a phrase after the verb is a third
    %% person, so it can be the subject of no other, and `Finiamo il pane' is
    %% we finish the bread -- given up at once, it was refused)
    %% -- and so has a verb before `a' and an infinitive the lesson calls
    %% intransitive, with a phrase after them: `Cominciano ad arrivare i
    %% mugugni' is the complaints beginning to arrive (tr_intransitive_ainf/4)
    %% (an object after an infinitive is the infinitive's: `Van a restaurar la parte de arriba' is them going to restore
    %% it, and with the part counted the verb of going, which takes no object, had a subject to find after it and none)
    (   Side == foreign, Subject2 = null(third, _), tr_takes_subject_after(L, LV2, Before),
        append(CPre, [obj(_)|_], Comps0), \+ ( member(I, CPre), ( I = ainf(_, _) ; I = inf(_) ; I = infx(_, _, _) ) )
    ->  !, fail
    ;   Side == foreign, Subject2 = null(third, SN), tr_accusative_first(Before, After, SN, Comps0)
    ->  !, fail
    ;   Side == foreign, Subject2 = null(third, _), Comps0 = [ainf(_, IL)|CR], atom(IL), tr_solve(intransitive(IL)),
        CR = [obj(_)|_]
    ->  !, fail
    %% -- and so has a MODAL before an infinitive the lesson calls
    %% intransitive, with a phrase after it (its adverbs first): `Dovrebbero
    %% transitare più o meno 290 mila vetture' is the cars that should pass,
    %% and read here they were what somebody should transit -- `They should
    %% transit 290 thousand cars'. The reader of a modal's subject after its
    %% infinitive has it (`deve finire in tribunale l'arcivescovo')
    ;   Side == foreign, Subject2 = null(third, _), Comps0 = [inf(IL)|CR], atom(IL), atom(L), tr_class_of(L, modal),
        tr_solve(intransitive(IL)), append(CA, [obj(_)|_], CR), forall(member(X, CA), X = adv(_))
    ->  !, fail
    ;   true
    ),
    %% A TIME IS NO SUBJECT OF A VERB WITH AN OBJECT. `L'anno era lungo' is
    %% about the year, and a determiner is what makes a time phrase one
    %% (tr_subject_shape/4) -- but `Il giorno prima caricò i compagni' is the
    %% day before, when HE loaded the team-mates, and read with the day for
    %% the subject, the day loaded them. The fronted adjunct reads it.
    \+ ( Side == foreign, tr_time_phrase(Subject2), memberchk(obj(_), Comps0) ),
    %% ... NOR A DATE OF A VERB THAT IS NO COPULA: `Il 3 giugno, due anni fa, ha
    %% nuotato' is the day and the time before it, and read with the commas
    %% taken out the date was the swimmer -- `El 3 de junio dos año ha nadado
    %% hace'. A date is a day's number and a month; `il 3 giugno è domenica'
    %% says what it is
    \+ ( Side == foreign, tr_date_phrase(Subject2), \+ tr_copula_lexeme(L) ),
    tr_null_copula_agrees(Subject2, L, A1, Comps0), tr_null_adjective_agrees(Side, Subject2, L, A1, Comps0), !,
                                                              % the cut once the WHOLE statement read: `house'
                                                              % is a verb's form, and `The house is big' must
                                                              % go on to the group at `is' when `is big' is no complement
    findall(opron(W), member(W, Clitics), Cs),
    %% A COMMA BETWEEN THE SUBJECT AND ITS VERB IS THE SOURCE'S, and the one
    %% that closes an apposition: `Inglaterra, el país que ha producido la
    %% minifalda, ..., seguirá describiéndose' is England, the country ...,
    %% and the subject side is read without its commas, so the second was
    %% lost -- `Juan, il fratello di María dorme'. It travels as scomma, and
    %% only where it is the subject side's one comma: `Los niños, que estaban
    %% cansados, durmieron' has lost the comma that opens its clause, and
    %% the one that closes it alone would be half a pair
    ( Mids == [], append(SubW, [comma], Before), SubW \== [], \+ memberchk(comma, SubW) -> SC = [scomma] ; SC = [] ),
    append([Mids, SC, Cs, Comps0], Comps),
    %% ... AND NO PHRASE BEFORE `THERE IS' IS WHAT THERE IS WHERE THE WORDS AFTER
    %% IT HAVE AN OBJECT OF THEIR OWN: `Dietro le voci ci sono molti ragazzi' is
    %% behind the voices there are many boys, and with `le voci' for what there
    %% is, the boys were a second thing there was -- `Hay las voces a muchos
    %% niños atrás'. The front phrase reads
    %% (a phrase with its phrases of `of' too: `Dopo la sentenza della corte, però, c'è
    %% stato il referendum' is after the judgment there was the referendum, and with
    %% the judgment of the court for what there was, `dopo' was left an adverb, `the
    %% judgment of the court thered is the referendum after')
    \+ ( Side == foreign, ( Subject2 = np(_, _, _, _, _) ; Subject2 = with(_, _) ), atom(LV2), tr_solve(mean(LV2, 'there is')),
         memberchk(obj(_), Comps0) ),
    tr_existential_fix(Side, s(Asked, Subject2, g(LV2, T, A1, Neg), Comps), S).
%% A WORD THAT BEGINS THE PURPOSE, RIGHT BEFORE AN INFINITIVE AND AFTER A NOUN
%% OR AN ADJECTIVE, IS NO VERB. `Un edificio anexo y un solar apto para levantar
%% otro hotel' has no verb at all, a list of two things, and `para' is also
%% what `parar' says of one person: the clause with `para' for its verb and
%% the plot for its subject came out `un terreno idoneo arresta alzare altro
%% albergo'. The lesson says which words begin a purpose (`The word "para"
%% begins the purpose.'); where one stands so, the group is not a clause's
%% ... nor after an infinitive: `quisiera saber qué hacer para iniciarme en el satanismo' is what to do in order to
%% begin, and with `hacer' the subject and `para' the verb of `parar' it was `what to do stops beginning'
tr_purpose_as_verb(foreign, Words, Before0) :-
    last(Before0, B), B = w(BW, _), ( tr_is(foreign, B, adjective) ; tr_is(foreign, B, noun) ; atom(BW), tr_solve(infinitive_of(BW, _)) ),
    append(Before0, [w(V, _), I|_], Words), atom(V), tr_starts_infinitive(foreign, [I]), tr_purpose_word(V), !.

%% a phrase that is an English pronoun no object is spelled like, with
%% `same' or nothing: `I', `he', `she', `we', `they' (tr_subject_out/6)
tr_pronoun_np(english, np(none, none, As, w(E, _), _), P, N) :-
    atom(E), en_subject_only(E), en_subject(E, P, N),
    forall(member(A, As), A = w(same, _)).
en_subject_only(E) :- en_subject(E, _, _), \+ en_object_of(_, E).

%% A PRONOUN THAT STANDS ALONE, AFTER THE WORD FOR `to' AND STRAIGHT BEFORE
%% THE VERB, IS ITS DATIVE: `a me piace stare in mezzo alla gente' is `mi
%% piace', I like being among people -- the pronoun said with the word for
%% `to' to stress it. Read as a phrase of `to' it went after everything,
%% `gusta estar ... a mí', where Spanish says `a mí me gusta', with the
%% clitic besides. It is the clitic its English meaning has, which every
%% writer spells, and the stress is what is lost.
tr_tonic_dative(foreign, Before0, Before) :-
    append(Pre, [w(P, _), w(T, TC)], Before0), atom(P), atom(T), tr_means_to(P),
    tr_lexeme(foreign, T, TL, _), tr_class_of(TL, pronoun), tr_solve(neg(precede(TL, verb))),
    tr_pronoun_across(english, object, w(T, TC), _, _, E),
    once(( tr_solve(mean(Cl, E)), tr_holds(precede(Cl, verb)), tr_object_pronoun(foreign, Cl, _) )), !,
    append(Pre, [w(Cl, TC)], Before).
%% ... AND ONE THE CLITIC AFTER IT DOUBLES IS SAID ONCE: `A mí me gustaba eso'
%% -- `me' says it already, and read as a phrase of `to' it came out `That
%% pleased me to me'
tr_tonic_dative(foreign, Before0, Before) :-
    append(Pre, [w(P, _), w(T, TC), w(Cl, ClC)], Before0), atom(P), atom(T), atom(Cl), tr_means_to(P),
    tr_lexeme(foreign, T, TL, _), tr_class_of(TL, pronoun), tr_solve(neg(precede(TL, verb))),
    tr_object_pronoun(foreign, Cl, _), tr_holds(precede(Cl, verb)),
    tr_pronoun_across(english, object, w(T, TC), _, _, E),
    tr_pronoun_across(english, object, w(Cl, ClC), _, _, E), !,
    append(Pre, [w(Cl, ClC)], Before).
tr_tonic_dative(_, B, B).
tr_bare_singular(np(none, none, _, w(_, _), singular)).
tr_bare_singular(with(NP, _)) :- tr_bare_singular(NP).
%% the subject that is ONE of a plural, or any part of a whole a pronoun names
%% (tr_partitive_head/1): the head, `de' and the plural
tr_part_of_subject(with(NP, [pp(P, NP2)|_])) :-
    tr_partitive_head(NP), tr_means_of(foreign, P), tr_subject_number(NP2, plural).
%% ... and a part of a phrase the lesson calls a group (`"pasaje" is a group.')
tr_part_of_group(with(NP, [pp(P, NP2)|_])) :-
    tr_partitive_head(NP), tr_means_of(foreign, P), NP2 = np(det(_, _, _), _, _, _, singular), tr_group_head(NP2).

%% AN OBJECT PRONOUN BEFORE `si' MAKES IT THE IMPERSONAL ONE: `li si voglia
%% murare' is one wanting to wall them in. A reflexive `si' with an object
%% pronoun is spelled `se' and stands BEFORE it (`se li vuole'), so `si'
%% after one is the subject nobody named; read with nobody before the verb,
%% it was the reflexive of `wants', and English refused a verb whose subject
%% nobody named. Only after a third person that is no dative: `mi si è
%% stretto il cuore' is the heart tightening, `mi' who it happens to, and
%% `gli si è rotta la gamba' his leg breaking.
%% (and never after a SUBJECT pronoun, which a pronoun that stands alone is
%% too: `Él se divirtió con ella' is he enjoyed himself, and `él' means
%% `him' after a preposition, so read as the object before an impersonal
%% `se' it came out `One amused him with her')
tr_si_after_object(Before, [S], Clitics) :-
    append(Clitics, [S], Before), Clitics = [_|_], S = w(SW, _), tr_impersonal(foreign, SW),
    forall(member(w(C, _), Clitics), tr_clitic(fronted, C)),
    last(Clitics, w(O, _)), tr_object_pronoun(foreign, O, E), memberchk(E, [him, her, it, them]),
    \+ ( tr_lexeme(foreign, O, OL, _), tr_solve(dative(OL)) ),
    \+ tr_reflexive_word(O), !.

%% `CI SI' IS THE IMPERSONAL `si' WITH A REFLEXIVE VERB, the impersonal
%% spelled `ci' before the verb's own `si' -- the lesson's `"ci" is the
%% impersonal of "si".': `non è conoscendo la forma della terra che ci si
%% salva l'anima' is how one saves one's soul. Read as it stands, `ci' was
%% `us' and the verb had nobody named -- `se nos ahorra la alma'. The one
%% `si' left is both: the subject nobody names, and the verb's reflexive.
tr_ci_si([w(Ci, _), S], [S], [S]) :-
    atom(Ci), S = w(SW, _), atom(SW), tr_solve(impersonal_of(Ci, SW)),
    tr_impersonal(foreign, SW), tr_reflexive_word(SW), !.
%% the number of a phrase set in front: a phrase with its relative clause has
%% the phrase's, `il pane che ho, l'ho mangiato'. Asked here alone: a phrase's
%% number through its clause everywhere (fo_np_number/2) let wrong readings
%% agree -- `es el mensaje que ha repetido con insistencia' had the message for
%% the subject of `es', `the message that they have repeated is with insistence'
tr_fronted_np_number(rc(NP, _, _), N) :- !, fo_np_number(NP, N).
tr_fronted_np_number(NP, N) :- fo_np_number(NP, N).
%% a word a subject after the verb can open on (tr_read_statement0/4's phrase set in front)
tr_subject_opener(w(_, upper)) :- !.
tr_subject_opener(W) :- W = w(X, _), atom(X), ( tr_determiner(foreign, W, _, _) -> true ; tr_is(foreign, W, pronoun) ), !.
%% ... and a count: `La placa la forman cuatro plafones' -- four panels make up the plaque, the verb in their number,
%% and with no word a subject could open on after the verb the clause had no reading
tr_subject_opener(W) :- W = w(X, _), atom(X), ( tr_digits(X) -> true ; tr_is(foreign, W, number) ), !.
%% the phrase set in front, and what goes with it: a phrase, or -- where the
%% phrase reader takes none -- a phrase and complements of its own, `il
%% timore di infastidire Gianfranco Funari un pò' (a fear, to bother him, a
%% little), which stay after it
tr_front_phrase(NPW, NP, []) :- tr_np(foreign, NPW, NP), !.
%% ... AND A PHRASE WITH PHRASES OF `OF' AFTER IT, which the subject reader
%% keeps with it (with/2): `Stefano Makula, 40 anni, romano, l'acqua delle
%% piscine la conosce bene' -- the water of the pools, and he knows it well.
%% Read alone, `l'acqua delle piscine la conosce' is the subject's own
%% dislocation (tr_dislocation_fix/3); after a subject the phrase and its `of'
%% phrases are the object's, which the pronoun takes up. A phrase of `of' is
%% a plain noun phrase: one with a relative clause in it has a verb in it,
%% and `la forma della terra che ci si salva l'anima' made `salva' the end of
%% the phrase and `l'' the pronoun of the verb `anima' (`uno se salva lo
%% anima')
tr_front_phrase(NPW, NP, Rest) :-
    NPW = [D, N, w(P, PC)|After], atom(P), tr_means_of(foreign, w(P, PC)),
    %% (a short phrase with no comma in it: the reader asks this at every
    %% determiner of a long front, and a front of 20 words cost one sentence of
    %% the controls a quarter of its inferences)
    length(NPW, Len), Len =< 9, \+ memberchk(comma, NPW),
    tr_np(foreign, [D, N], NP), NP = np(_, _, _, _, _),
    tr_of_phrases([w(P, PC)|After], Rest), !.
%% ... AND A PHRASE, ITS PHRASE OF `OF' AND A RELATIVE CLAUSE SAID OF THE WHOLE: `quel po' d'italiano che so, l'ho
%% imparato al cinema' is the bit of Italian I know, which I learnt at the cinema -- with the clause in the phrase of
%% `of' (which the clause above keeps plain) nothing read
tr_front_phrase(NPW, rc(with(NP, PPs), Role, S), []) :-
    NPW = [D, N, w(P, PC)|After], atom(P), tr_means_of(foreign, w(P, PC)),
    length(NPW, Len), Len =< 12, \+ memberchk(comma, NPW),
    append(OfW, [w(R, RC)|RelW], After), OfW = [_|_], RelW = [_|_], atom(R), tr_relative_word(foreign, R),
    tr_np(foreign, [D, N], NP), NP = np(_, _, _, _, _),
    tr_of_phrases([w(P, PC)|OfW], PPs),
    tr_relative_clause(foreign, [w(R, RC)|RelW], Role, S), !.
tr_front_phrase(NPW, NP, Rest) :-
    tr_preposition_infinitive(NPW),
    tr_complements(foreign, NPW, [obj(NP)|Rest]), Rest \== [],
    forall(member(X, Rest), ( X = pinf(_, _) ; X = obj(_) ; tr_adjunct(X) )).
%% (the phrases of `of': each a plain phrase up to the next, the commas of a
%% list not being among them; asked of the words after a short phrase, never of
%% the whole front, which the subject reader's own search made dear)
tr_of_phrases([], []).
tr_of_phrases([w(P, PC)|Ws], [pp(w(P, PC), N2)|Rest]) :-
    tr_means_of(foreign, w(P, PC)),
    %% (a bare noun of one word too: `quel po' d'italiano che so, l'ho imparato al cinema' -- that bit of Italian)
    append(Ph, Next, Ws), ( Ph = [_, _|_] -> true ; Ph = [B], tr_is(foreign, B, noun) ),
    (   Next == [] -> true ; Next = [w(P2, PC2)|_], tr_means_of(foreign, w(P2, PC2)) ),
    tr_np(foreign, Ph, N2), N2 = np(_, _, _, _, _), !,
    tr_of_phrases(Next, Rest).
%% (a preposition and an infinitive stand in the words, or the complements are
%% not read: the reader asks this at every place a determiner stands before
%% the pronoun, and a front that is no phrase read all its words for it)
tr_preposition_infinitive([P, I|Ws]) :-
    (   P = w(_, _), I = w(IW, _), atom(IW), tr_is(foreign, P, preposition), tr_solve(infinitive_of(IW, _)) -> true
    ;   tr_preposition_infinitive([I|Ws])
    ).

%% -- AND A VERB GROUP IS ASKED FOR ONLY WHERE ONE COULD CARRY THE PRONOUN.
%% What the clause needs is a pronoun with a determiner and no comma before
%% it and a group after it, perhaps past more clitics; that is one
%% tr_group_at/4 at each such place, where tr_group_from/5 asks at every
%% word. And the phrase ends where the clitics begin, so the word before
%% them must be one a phrase can end on: `... e l'isola di Ustica' has
%% `isola', he isolates, after `l'', and `una valigia e lo vide' a group
%% after `lo', and a phrase ending on `e' was parsed at every determiner
%% before it -- ten, thirteen and four million inferences on three
%% sentences of the controls that have no dislocation. Nor may the words
%% open on a preposition: what stands before the phrase is its subject or
%% nothing, and `Negli ambienti giudiziari si tende ad accreditare la tesi'
%% is neither, whatever `tesi' is.
tr_dislocation_hint(Words) :-
    Words = [W1|_], \+ tr_preposition_only(W1),
    append(Pre, [w(R, _)|Post], Words), tr_resumptive(R, _),
    \+ memberchk(comma, Pre),
    tr_clitics_back(Pre, Front), last(Front, Last), \+ tr_no_phrase_end(Last),
    member(D, Front), tr_determiner(foreign, D, _, _),
    tr_group_past_clitics(Post), !.
tr_group_past_clitics(Ws) :- tr_group_at(foreign, Ws, _, _), !.
tr_group_past_clitics([w(C, _)|Ws]) :- tr_clitic(none, C), tr_group_past_clitics(Ws).
tr_clitics_back(Ws, Front) :-
    append(Front0, [w(C, _)], Ws), tr_clitic(none, C), !, tr_clitics_back(Front0, Front).
tr_clitics_back(Ws, Ws).
%% a word no phrase ends on: a coordinator, or a conjunction or a
%% preposition the lesson calls nothing a phrase can end with
tr_no_phrase_end(W) :- W = w(_, _), tr_coord(foreign, W), !.
tr_no_phrase_end(W) :- W = w(_, _),
    ( tr_is(foreign, W, conjunction) ; tr_is(foreign, W, preposition) ),
    tr_nothing_else(W), !.
tr_preposition_only(W) :- W = w(_, _), tr_is(foreign, W, preposition), tr_nothing_else(W),
    \+ tr_determiner(foreign, W, _, _), !.
tr_nothing_else(W) :-
    \+ tr_is(foreign, W, noun), \+ tr_is(foreign, W, pronoun),
    \+ tr_is(foreign, W, adjective), \+ tr_is(foreign, W, number).

%% the pronoun that takes the phrase up again: a third person object, in the
%% phrase's number -- an elided one is `lo' and `la' alike
%% (in every number it can be: `le' is `to her' and, as `la''s plural,
%% `them' -- `queste cose le sapessero i dotti', tr_dislocation_fix/3)
tr_resumptive(R, N) :-
    ( tr_solve(elision_of(R, F)) -> true ; F = R ),
    findall(N0, ( tr_object_pronoun(foreign, F, E), memberchk(E-N0, [it-singular, him-singular, her-singular, them-plural]) ), Ns0),
    sort(Ns0, Ns), member(N, Ns).
%% ... AND IT AGREES WITH THE PHRASE IN GENDER where the lesson gives both one:
%% `Un convegno, proiezioni, la mostra dei Murales' set `un convegno proiezioni'
%% in front for `la', which is feminine, and made `mostra' -- the exhibition --
%% a verb. An elided pronoun (`l'') has no gender to ask, nor a phrase whose
%% head the lesson gives none
tr_resumptive_agrees(R, NP) :-
    (   tr_solve(elision_of(R, _)) -> true
    ;   tr_holds(feminine(R)), tr_np_head_gender(NP, G) -> G == feminine
    ;   tr_holds(masculine(R)), tr_np_head_gender(NP, G) -> G == masculine
    ;   true
    ).
tr_np_head_gender(np(_, _, _, w(W, _), _), G) :-
    atom(W), ( tr_holds(feminine(W)) -> G = feminine ; tr_holds(masculine(W)) -> G = masculine ).
tr_np_head_gender(np(_, _, _, named(G, _), _), G).

%% ... and the name stays where it stood, subj_here among the complements:
%% `son únicos", dijo Claude Lebet, uno de los luthiers' is a speaker after
%% his verb, and moved in front it came out `Claude Lebet disse'
tr_name_subject(Side, Subject, FP, FN, L, LV, [obj(name(N))|Comps], name(N), LV1, [subj_here|Comps]) :-
    Side == foreign, ( Subject == impersonal ; Subject = null(third, singular) ),
    FP == third, FN == singular, tr_solve(precede(_, person)), !,
    ( Subject == impersonal, LV == L -> LV1 = reflexive(L) ; LV1 = LV ).
tr_name_subject(_, Subject, _, _, _, LV, Comps, Subject, LV, Comps).

%% AN ASIDE BETWEEN THE SUBJECT AND ITS VERB: `Monsignor Cassisa, secondo
%% l'accusa, avrebbe intascato tangenti' -- adjuncts between two commas, the
%% second right before the verb group. Read with the commas taken out they
%% were a phrase of the subject's (`Monseñor Cassisa según la acusación
%% habría embolsado'); each travels as mid(C), and every writer puts it
%% back after the subject with its commas. Tried first and given up when
%% the rest will not read with it, so a subject that is a list with commas
%% reads as it did.
tr_insertion_off(Side, Before0, Before, Mids) :-
    append(Before, [comma|InsW], Before0), Before \== [], \+ last(Before, comma),
    append(InsW0, [comma], InsW), InsW0 \== [], \+ memberchk(comma, InsW0),
    %% ... opening on a preposition or on an adverb: `la Pace, ALMENO nelle
    %% piccole isole del Belpaese, arriva per decreto' lost its commas, the
    %% islands became the peace's and `almeno' went to the end
    %% ... or on a gerund: `Se la persona, andando giù, non ha bevuto' -- the
    %% person, going down, has not drunk; read as two pieces at the commas the
    %% second had nobody named and English refused it
    InsW0 = [P|_], ( tr_is(Side, P, preposition) ; tr_plain_adverb(Side, P) ; P = w(PN, _), atom(PN), tr_negation_word(PN)
                   ; P = w(GW, _), atom(GW), tr_gerund_here(Side, GW, _) ),
    tr_complements(Side, InsW0, Cs1), tr_ungoverned(Cs1, Cs), Cs \== [],
    %% ... or not only somebody but somebody else (nonly/3): `Tutto il
    %% lavoro che ho fatto, non solo io ma tanti altri nel nostro campo, va
    %% sempre sotto silenzio' -- the work I did, and many others with me
    tr_insertion_comps(Cs),
    findall(mid(X), member(X, Cs), Mids).
%% ... AND THE WORD FOR `NOR' AND A PHRASE, SET OFF AFTER THE SUBJECT: `Ningún deportista español, ni ninguna
%% federación, envía muestras a su laboratorio' -- no sportsman, nor any federation, sends them; the verb is the
%% subject's, singular, and the phrase between the commas is said beside it. Read as a coordinated subject the halves
%% did not read with their commas, and the sentence was refused. It travels as mid(nor(Phrase)), written after the
%% subject between its commas, with the lesson's word for `nor' (`ni', `né') and English's `nor'
tr_insertion_off(foreign, Before0, Before, [mid(nor(NP))]) :-
    append(Before, [comma, w(N, _)|InsW], Before0), Before \== [], \+ last(Before, comma),
    atom(N), tr_neither_word(N),
    append(InsW0, [comma], InsW), InsW0 = [_|_], \+ memberchk(comma, InsW0),
    tr_np(foreign, InsW0, NP), !.
%% ... AND ADJUNCTS AFTER THE COMMA THAT CLOSES THE SUBJECT'S RELATIVE CLAUSE, RIGHT BEFORE THE VERB: `Abbatino, che ha
%% dato tutta una serie di indicazioni sulla base delle quali è stata sostenuta l'accusa, per il pm è "pienamente
%% affidabile"' -- for the prosecutor he is fully reliable. With no comma before the verb the phrase was read into the
%% subject, and the long sentence was refused
tr_insertion_off(foreign, Before0, Before, Mids) :-
    append(Before, [comma|AdjW], Before0), AdjW = [P, _|_], P = w(_, _), tr_is(foreign, P, preposition),
    \+ memberchk(comma, AdjW),
    append(_, [comma, w(R, _)|_], Before), atom(R), tr_relative_word(foreign, R),
    tr_complements(foreign, AdjW, Cs), Cs \== [], tr_adjuncts(Cs), \+ memberchk(sep, Cs), !,
    findall(mid(X), member(X, Cs), Mids).
%% ... AND A CLAUSE WITH ITS SUBORDINATING WORD: `I due autori, siccome un
%% passo della bibbia descriveva la terra in forma di tabernacolo,
%% polemizzavano ...' -- the authors, since a passage described it so,
%% polemicized. Divided at its commas, the authors were a verbless piece of
%% their own and the verb had nobody named -- `Gli autori, siccome il gatto
%% dorme, mangiano il pane' read so, the same words either way -- and with
%% a count in the subject the sentence was refused
tr_insertion_off(foreign, Before0, Before, [mid(sub(w(C, CC), S))|Advs]) :-
    append(Subj, [comma, w(C, CC)|InsW], Before0), Subj \== [], \+ last(Subj, comma), atom(C),
    tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
    append(InsW0, [comma|Tail], InsW), InsW0 \== [], \+ memberchk(comma, InsW0),
    tr_insertion_tail(Tail, Advs, Cls), append(Subj, Cls, Before),
    tr_read_nested(foreign, InsW0, none, S), !.
%% ... OR THE WORD AND AN ADJECTIVE PHRASE WITH NO VERB: `Zapatero, aunque fiel a
%% su consigna de no arremeter contra el PP, sí se permitió hacer una crítica'
%% -- although faithful to it. The phrase is the fragment a headline is,
%% gap([], [obj(Phrase)]), which every writer puts after the word
tr_insertion_off(foreign, Before0, Before, [mid(sub(w(C, CC), gap([], [obj(NP)])))|Advs]) :-
    append(Subj, [comma, w(C, CC), A|InsW], Before0), Subj \== [], \+ last(Subj, comma), atom(C),
    tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
    A = w(AW, _), atom(AW), tr_is(foreign, A, adjective), \+ tr_is(foreign, A, noun),
    append(InsW0, [comma|Tail], [A|InsW]), \+ memberchk(comma, InsW0),
    tr_insertion_tail(Tail, Advs, Cls), append(Subj, Cls, Before),
    tr_subject(foreign, none, InsW0, third, _, NP), !.
%% ... OR THE WORD AND A PARTICIPLE WITH NO AUXILIARY: `una teoria che, se
%% accettata, potrebbe modificare l'antidoping' -- a theory that, if accepted,
%% could change it. The participle is the fragment a headline is, as an
%% adjective phrase is above, gap([], [pred(...)]) with the form's gender and
%% number, and every writer puts it after the word
tr_insertion_off(foreign, Before0, Before, [mid(sub(w(C, CC), S))|Advs]) :-
    append(Subj, [comma, w(C, CC), A|InsW], Before0), Subj \== [], \+ last(Subj, comma), atom(C),
    tr_connector(foreign, C), \+ tr_coord(foreign, w(C, CC)),
    A = w(AW, _), atom(AW), tr_participle_here(foreign, AW, _),
    append(InsW0, [comma|Tail], [A|InsW]), \+ memberchk(comma, InsW0),
    tr_insertion_tail(Tail, Advs, Cls), append(Subj, Cls, Before),
    tr_participle_gap(InsW0, S), !.
%% ... OR THE WORD FOR `THUS' AND A CLAUSE WITH ITS VERB FIRST: `L'utilità
%% dell'Egibren, così si chiama il farmaco prescritto da Casotto e assunto da
%% Rosi, è stata una delle colonne' -- so the drug is called, the name saying
%% what Egibren is. Divided at its commas, the clause was a piece of its own
%% with nobody to say it of, and the sentence was refused. The clause is read
%% with its subject after the verb (tr_rel_subject_fix/2), and it travels as a
%% subordinate clause whose word is the adverb, so(Word), which every writer
%% puts back as it put the connectors: `así se llama la medicina', `thus the
%% medicine is called'
tr_insertion_off(foreign, Before0, Before, [mid(sub(so(w(C, CC)), S))|Advs]) :-
    append(Subj, [comma, w(C, CC)|InsW], Before0), Subj \== [], \+ last(Subj, comma), atom(C),
    tr_thus_word(C),
    append(InsW0, [comma|Tail], InsW), InsW0 = [_|_], \+ memberchk(comma, InsW0),
    tr_insertion_tail(Tail, Advs, Cls), append(Subj, Cls, Before),
    tr_read_nested(foreign, InsW0, none, S0), tr_rel_subject_fix(S0, S), !.
%% ... AND ONE THE APPOSITION BEFORE IT OPENS: `su constructor, Joseph
%% Guarnerius del Gesù, de Cremona (Italia), está considerado' -- the comma
%% after the name closes the name and opens the place, and the apposition
%% took it (tr_list_commas/3). Read as the subject's `of' phrase, the place's
%% own closing comma was lost: `di Cremona (Italia) è considerato'.
%% ... AND AN ADVERB OF ITS OWN: `El portavoz demócrata, John Conyers, por su
%% parte, criticó a los republicanos' -- `por su parte' is one adverb, for its
%% part, and with its opening comma in the apposition it went to the end of the
%% clause, `criticised the republicans ... for its part'
tr_insertion_off(Side, Before0, Before, Mids) :-
    append(Before, InsW, Before0), Before = [_|_], last(Before, w(_, appos)),
    append(InsW0, [comma], InsW), InsW0 = [P|_], \+ memberchk(comma, InsW0),
    ( tr_is(Side, P, preposition) -> true ; InsW0 = [_], tr_is(Side, P, adverb) ),
    tr_complements(Side, InsW0, Cs), Cs \== [], forall(member(X, Cs), tr_adjunct(X)),
    findall(mid(X), member(X, Cs), Mids).
%% ... AND ONE INSIDE A CLAUSE, which tr_clause_mids/4 set aside with its
%% commas: `che la "Bastiglia", qui da noi, non mi risulta'
tr_insertion_off(Side, Before0, Before, Mids) :-
    append(B1, [w(K, mid)|B2], Before0), B1 = [_|_], !,
    nb_getval(K, InsW), tr_complements(Side, InsW, Cs), Cs \== [],
    findall(mid(X), member(X, Cs), Mids), append(B1, B2, Before).
%% ... AND AN ADJECTIVE SAID OF A PRONOUN OR A NAME, set off by commas that
%% tr_list_commas/5 took with it: `che egli, latitante, si permette' -- he, a
%% fugitive -- travels as mid(adj(...))
%% (the clitics after it are the verb's: `egli, latitante, SI permette' --
%% and a relative clause before it keeps its own: `i magistrati che egli,
%% latitante, si permette ... dormono' is the clause's aside, not the verb
%% `dormono''s)
tr_insertion_off(Side, Before0, Before, [mid(adj([w(A, lower)]))]) :-
    append(B1, [w(A, pappos)|B2], Before0), B1 = [_|_],
    \+ ( member(w(R, _), B1), tr_relative_word(Side, R) ), !, append(B1, B2, Before).
%% ... AND WHO SAID SO, RIGHT BEFORE THE VERB: `Il cane - come ha detto il
%% gatto - mangia il pane', `Il cane, come ha detto il gatto, mangia il
%% pane'. Set aside as w(Key, perd) or w(Key, per) (tr_asides/3), it was a
%% word of the subject's that no phrase takes, and the sentence was refused
%% -- where 1.8.30 had read the dashes as the dog's own clause of `how',
%% `El perro – cómo ha dicho el gato – come el pan'. It travels as mid/1 and
%% goes back where it stood, between its dashes or its commas (tr_write/4).
tr_insertion_off(foreign, Before0, Before, [mid(perd(K))]) :-
    append(Before, [w(K, perd)], Before0), Before = [_|_], !.
tr_insertion_off(foreign, Before0, Before, [mid(perh(K))]) :-
    append(Before, [w(K, per), comma], Before0), Before = [_|_], !.
tr_insertion_off(_, Before, Before, []).
%% ... AND A TIME BETWEEN THE SUBJECT AND ITS VERB WITH NO COMMA AROUND IT:
%% `Anche lui un giorno rischiò di morire', `Maria una volta ha visto il cane'
%% -- he too, one day, risked dying. A determiner and a noun the lesson calls
%% a time stand after the subject, and the subject read with them in it was
%% refused (`lui un giorno' is no phrase). The time travels as mid/1, as the
%% one between commas does, and every writer puts it back after the subject.
%% It is asked AFTER the plain reading and the others above, so a sentence
%% that read before reads by the same clause.
tr_insertion_off(foreign, Before0, Before, [mid(at_time(NP))]) :-
    %% (the last two words by the list builtins, not by append/3 from the front:
    %% this clause is asked at every backtrack into the predicate, and a walk
    %% of the subject's words each time cost the controls 1.5 %)
    last(Before0, N), N = w(NW, _), atom(NW),
    length(Before0, L), L >= 3, I is L - 1, nth1(I, Before0, D),
    D = w(DW, _), atom(DW), tr_determiner(foreign, D, _, _),
    tr_complements(foreign, [D, N], [at_time(NP)]),
    J is L - 2, length(Before, J), append(Before, [D, N], Before0).
%% (no phrase of an insertion is one the clause's verb governs: `Navarro, en un momento de forma
%% excepcional, se encargó de llevar el peso' is in a moment OF exceptional form, and read with the
%% verb's `de' it was the phrase `takes charge of' takes, which English writes bare -- `in a moment
%% exceptional form')
tr_ungoverned([], []).
tr_ungoverned([pp(W, gov(_, NP))|Cs0], [pp(W, NP)|Cs]) :- !, tr_ungoverned(Cs0, Cs).
tr_ungoverned([C|Cs0], [C|Cs]) :- tr_ungoverned(Cs0, Cs).
%% what an insertion between commas may hold: adjuncts, a `not only ... but' pair, and an
%% adjective after a name that `with' governs (`los azulgranas, con Rentzias convaleciente, se vieron')
tr_insertion_comps([]).
tr_insertion_comps([pp(P, name(_)), adj(_)|Xs]) :- tr_means_with(P), !, tr_insertion_comps(Xs).
%% (and a preposition with its infinitive, which takes the rest: `Abbatino, prima di essere arrestato e di decidere di
%% collaborare con l'autorità giudiziaria, era uno dei più noti malviventi' -- before he was arrested he was one, and
%% divided at the commas the man was a heading and the copula had nobody named, `it was one of')
tr_insertion_comps([pinf(_, _)|_]) :- !.
tr_insertion_comps([X|Xs]) :- ( tr_adjunct(X) -> true ; X = obj(nonly(_, _, _)) ), tr_insertion_comps(Xs).
%% (what stands between the insertion's closing comma and the verb group: the
%% clause's adverbs, which become its complements as a lifted adverb does, and
%% its pronouns, which stay with the subject's side for tr_split_clitics/7:
%% `Zapatero, aunque fiel a su consigna, SÍ SE permitió ...')
tr_insertion_tail([], [], []).
tr_insertion_tail([W|Ws], [adv(W)|Advs], Cls) :-
    W = w(A, _), atom(A), tr_plain_adverb(foreign, W), !, tr_insertion_tail(Ws, Advs, Cls).
tr_insertion_tail([W|Ws], Advs, [W|Cls]) :-
    W = w(Cl, _), atom(Cl), tr_clitic(unsaid(none), Cl), tr_insertion_tail(Ws, Advs, Cls).
tr_thus_word(C) :- tr_solve(mean(C, thus)), !.
%% the participle and what it takes, read as the fragment of a line with no verb
tr_participle_gap(Ws, gap([], Cs)) :-
    tr_complements(foreign, Ws, Cs0), Cs0 = [pred(_)|_],
    tr_gap_agreement(foreign, Ws, Cs0, Cs).

%% ... OR A VERB BEFORE `a' AND AN INFINITIVE THE LESSON CALLS INTRANSITIVE:
%% `Da più parti cominciano ad arrivare i mugugni degli studenti' is the
%% complaints beginning to arrive -- the infinitive takes no object, so the
%% phrase after it is the subject of both, and read with nobody named the
%% complaints were what they began to make arrive. The infinitive stays
%% where it stood, before the subject's place (ainf/2).
tr_intransitive_ainf(L, [w(P, PC), w(IW, _)|After], [ainf(w(P, PC), IL)], After) :-
    atom(L), After \== [], atom(IW), tr_means_to(P),
    tr_solve(infinitive_of(IW, IL)), tr_solve(intransitive(IL)), !.

%% A VERB THAT TAKES NO OBJECT: one the lesson calls intransitive, or one it
%% calls REFLEXIVE with its reflexive pronoun before it -- `Mi si è stretto il
%% cuore leggendo ...' is my heart tightening, `stringersi' being `stringere'
%% with nothing to tighten but itself, and `mi' who it happens to. Read with
%% nobody named for the subject, the heart was the verb's object: somebody
%% tightening it (`"stringe" is reflexive.', the shape `"equivoca" is
%% reflexive.' has)
%% (LV is the lexeme the reader already took the pronoun off, or `none' where
%% it has not yet: given unbound, `LV = reflexive(_)' held for every verb the
%% lesson calls reflexive, `si' or not, and `ha sbagliato strada' went through
%% the reader below on Livata's fifteenth sentence -- 3.8 million inferences
%% of 14.9)
tr_takes_subject_after(L, _, _) :- tr_solve(intransitive(L)), !.
%% ... AND ONE WHOSE OBJECT IS WHO FEELS IT, with that object before it as a
%% pronoun: `Di quell'uomo mi ha colpito il nuovo e diverso approccio alla
%% vita pubblica' -- the approach struck me. The verb takes an object, so the
%% lesson cannot call it intransitive; read with nobody named for its
%% subject, the approach was what somebody struck, and English refused the
%% sentence. A lesson says it of the verb, `"colpisce" takes the
%% experiencer.', in the shape `"risulta" takes the clause.' has -- because
%% `mi ha dato un libro' has a pronoun before its verb and a phrase after it
%% too, and there the phrase is the object
tr_takes_subject_after(L, _, Before) :-
    atom(L), tr_solve(take(L, experiencer)),
    member(w(C, _), Before), tr_clitic(normal, C), \+ tr_reflexive_word(C), !.
tr_takes_subject_after(L, LV, Before) :-
    atom(L), tr_solve(reflexive(L)),
    ( LV = reflexive(_) -> true ; member(w(R, _), Before), tr_reflexive_word(R) ), !.

%% ... AND THE OTHER WAY: A COPULA WITH NOTHING BUT A PHRASE OF `TO' AFTER IT IS THE GOING. `El ceramista se fue a la
%% plaza de Sant Jaume' went to the square, and `fue' read as the copula it is too came out `was to the square' (and
%% `fu alla piazza'). A sentence whose word is the past of the copula and of the verb of going both, with no predicate,
%% no object and a phrase of `to' first among its complements, has the going (Italian's `fu' is the copula's alone)
tr_copula_goes(foreign, Words, s(A, Su, g(L0, T, Asp, Neg), Cs), s(A, Su, g(L, T, Asp, Neg), Cs)) :-
    Asp == simple, ( L0 = reflexive(CL) -> true ; CL = L0 ), atom(CL), tr_copula_lexeme(CL),
    Cs = [pp(w(P, _), _)|_], atom(P), tr_means_to(foreign, P),
    \+ ( member(C, Cs), ( C = obj(_) ; C = adj(_) ; C = pred(_) ) ),
    member(w(V, _), Words), atom(V), tr_form(V, CL, _, _, _), tr_form(V, GL, _, _, _), GL \== CL,
    atom(GL), tr_solve(mean(GL, goes)), !,
    L = GL.                       % (its own pronoun dropped: `si andò' is no Italian, and English goes either way)
%% (and in each clause a coordinator joins: `envolvió los plafones y se fue a la plaza de Sant Jaume')
tr_copula_goes(foreign, Words, join(C, S10, S20), join(C, S1, S2)) :- !,
    tr_copula_goes(foreign, Words, S10, S1), tr_copula_goes(foreign, Words, S20, S2).
tr_copula_goes(_, _, S, S).

%% THE VERB OF GOING IN THE PRESENT BEFORE `a' AND AN INFINITIVE IS THE NEAR FUTURE: `Creo que van a restaurar la parte de
%% arriba' is they will restore it, and read as the going English wrote `they go to restore' and Italian `vadano a
%% restaurare'. The lesson says which verb makes it (`"va" takes the future.': Italian's `andare a' is a going), and the
%% clause is the infinitive's verb in the future; in a clause of `that' too
tr_near_future(foreign, join(C, S10, S20), join(C, S1, S2)) :- !,
    tr_near_future(foreign, S10, S1), tr_near_future(foreign, S20, S2).
%% ... AND ITS PAST, THE CONDITIONAL: `Reiteró que se iban a endurecer las medidas' -- that they would be tightened,
%% the future as it was seen then; read word by word it was `si andavano a indurire', went to tighten. And the verb's
%% reflexive pronoun is the infinitive's, as the source's `se' before `iban' is `endurecerse''s, and a thing's
%% reflexive is the passive there as it is anywhere (tr_se_passive/2: the measures would be tightened)
tr_near_future(foreign, s(A, Su, g(L0, T0, simple, Neg), [ainf(_, IL)|Cs0]), S) :-
    tr_near_future_tense(T0, T), tr_near_future_verb(L0, L, IL, IL1),
    atom(L), atom(IL), tr_solve(take(L, future)), !,
    tr_near_future_comps(Cs0, Cs), S1 = s(A, Su, g(IL1, T, simple, Neg), Cs),
    ( IL1 = reflexive(_) -> tr_near_future_passive(S1, S) ; S = S1 ).
tr_near_future(foreign, s(A, Su, G, Cs0), s(A, Su, G, Cs)) :- !, tr_near_future_comps(Cs0, Cs).
tr_near_future(_, S, S).
tr_near_future_comps([], []).
tr_near_future_comps([that(S0)|Cs0], [that(S)|Cs]) :- !, tr_near_future(foreign, S0, S), tr_near_future_comps(Cs0, Cs).
tr_near_future_comps([C|Cs0], [C|Cs]) :- tr_near_future_comps(Cs0, Cs).
tr_near_future_tense(present, future).
tr_near_future_tense(imperfect, conditional).
tr_near_future_verb(reflexive(L), L, IL, reflexive(IL)) :- !.
tr_near_future_verb(L, L, IL, IL).
%% (the thing after the verb, in the verb's number, is the subject of the passive, as the reader takes it where the
%% reflexive stands on the verb itself: `se endurecerían las medidas')
tr_near_future_passive(s(A, null(third, N), g(L, T, simple, Neg), Cs0), s(A, NP, g(L, T, passive, Neg), Cs)) :-
    append(Pre, [obj(NP)|Post], Cs0), \+ ( member(X, Pre), tr_object_comp(X) ),
    tr_thing_phrase(NP), tr_subject_number(NP, N), !,
    append(Pre, [subj_here|Post], Cs).
tr_near_future_passive(S0, S) :- tr_se_passive(S0, S).

%% A PERSON MARKED AFTER AN ACCUSATIVE PRONOUN IS THE ONE IT GOES TO: `Ahora los ofrece desinteresadamente al comando'
%% offers them TO the commando -- the pronoun is the verb's object, and Spanish marks no second one with `a'; read as the
%% person object, the group (`"comando" is a group.') was what was offered, `Li offre il commando'. A third person's
%% pronoun that is no dative (`lo', `la', `los', `las'), then an object that is a person or a group, with adverbs
%% between them or none, and the marker of a person among the source's words (`Se les llamará chicos' is what they will
%% be called, the boys no person marked: a lesson that does not say `les' is a dative reads it as no dative)
tr_accusative_dative(foreign, Words, join(C, S10, S20), join(C, S1, S2)) :- !,
    tr_accusative_dative(foreign, Words, S10, S1), tr_accusative_dative(foreign, Words, S20, S2).
tr_accusative_dative(foreign, Words, s(A, Su, G, Cs0), s(A, Su, G, Cs)) :-
    append(Pre, [opron(w(R, RC))|Mid0], Cs0), atom(R), \+ tr_solve(dative(R)), \+ tr_reflexive_word(R),
    append(Advs, [obj(NP)|Post], Mid0), \+ ( member(X, Advs), X \= adv(_) ),
    tr_lexeme(foreign, R, RL, _), tr_class_of(RL, pronoun), tr_solve(mean(RL, E)), memberchk(E, [him, her, it, them]),
    ( tr_of_class(NP, person) ; tr_of_class(NP, group) ),
    once(( tr_solve(mean(To, to)), tr_class_of(To, preposition), tr_solve(precede(To, person)) )),
    once(( member(w(TW, _), Words), atom(TW),
           ( TW == To ; tr_solve(contraction_of(TW, J)), atomic_list_concat([To|_], ' ', J) ) )), !,
    append(Advs, [pp(w(To, lower), NP)|Post], Mid),
    append(Pre, [opron(w(R, RC))|Mid], Cs).
tr_accusative_dative(_, _, S, S).

%% THE PRETERITE OF `ir' IS THE PRETERITE OF `ser': `Fue una equivocación' is
%% it was a mistake, and read as the verb of going, which the lesson calls
%% intransitive, a mistake went and its subject is after it (`Ayer fue una
%% equivocación', `Entonces fue un error' too). A form that is the copula's
%% as well keeps the copula, which the readers below have for a statement
%% with nobody named, unless the going has somewhere to go: a phrase of `a'
%% after it (`Fue un niño a Madrid'). The plural was never read so, its
%% nobody being named by the generic reader that comes first.
tr_ser_not_ir(L, Words, Before, After) :-
    append(Before, [w(V, _)|_], Words), atom(V),
    tr_form(V, L, _, _, _), tr_form(V, CL, _, _, _), CL \== L, tr_copula_lexeme(CL),
    \+ ( member(w(P, _), After), atom(P), tr_means_to(foreign, P) ), !.

%% AN OBJECT PRONOUN THAT IS NO DATIVE IS THE VERB'S ONE DIRECT OBJECT, so a
%% phrase after the verb that agrees with it can only be its subject: `Lo
%% rende noto un comunicato del Quirinale' is the communique announcing it,
%% and `Lo mangia il cane' the dog eating it. Read with nobody named for the
%% subject, the phrase was a second object -- `lo anuncia un comunicado', the
%% same words in Spanish, and English refused it. Only the third person's
%% pronoun, `lo', `la', `li': `mi', `ti' and `ci' are datives as often, `mi ha
%% dato un libro' has one before its verb and a phrase after it, and there
%% the phrase is the object. And never a phrase the word before a person
%% opens: Spanish's `Lo ve a Maria' doubles its pronoun with the person the
%% word marks. The phrase agrees with the verb in number, or `Lo chiamano
%% Mario' -- they call him Mario -- has no subject after it at all
%% ... and the phrase opens on a determiner or is a name, which is what
%% a subject after its verb does: asked of every group with a clitic before
%% it, `Inoltre la legge approvata crea ...' offered `legge' (she reads) with
%% `la' before it and read the rest of a forty-five word sentence for its
%% subject, four times over -- 56 million inferences that the phrase's first
%% word, `approvata', refuses at once
tr_accusative_last(Before, After) :-
    After = [First|_], First = w(_, FC),
    ( FC == upper -> true ; tr_determiner(foreign, First, _, _) -> true ; tr_nonly_start(After) -> true ; tr_focus_start(After) ),
    tr_uncomma(Before, BU), append(_, [w(C, _)], BU), tr_accusative_clitic(C),
    \+ tr_marked_start(After).
tr_accusative_first(Before, After, N, [obj(O)|_]) :- tr_accusative_number(O, N), tr_accusative_last(Before, After).
%% ... and one with the word for `even', `also' or `only' before it: `Lo
%% sanno persino Luisa, Anna, Rosa' is EVEN they knowing it, and read with
%% nobody named the names were the object, `Lo saben incluso a Luisa, Anna,
%% Rosa' -- where 1.8.30, whose reader had no such list, refused it
tr_accusative_first(Before, After, N, [adv(w(A, _)), obj(O)|_]) :-
    atom(A), tr_focus_adverb(A), tr_accusative_number(O, N), tr_accusative_last(Before, After).
tr_accusative_first(Before, After, N, [obj(advp(w(A, _), O))|_]) :-
    atom(A), tr_focus_adverb(A), tr_accusative_number(O, N), tr_accusative_last(Before, After).
%% the word for `even', `also' or `only' before a phrase that opens on a
%% capital or a determiner (tr_accusative_last/2)
tr_focus_start([w(A, _), N|_]) :-
    atom(A), tr_focus_adverb(A), N = w(_, NC), ( NC == upper -> true ; tr_determiner(foreign, N, _, _) ), !.
tr_focus_adverb(A) :- atom(A), tr_language(G), tr_memo(focusw(G, A), x, tr_focus_adverb0(A), [_|_]), !.
tr_focus_adverb0(A) :-
    tr_is(foreign, w(A, lower), adverb), tr_lexeme(foreign, A, L, _),
    once(( tr_solve(mean(L, E)), memberchk(E, [even, also, only]) )).
%% ... one that is no preposition too, for the front of a subject: `hasta' is
%% `until' before it is `even', and `Hasta entonces el perro duerme' is until
%% then -- the adverb `entonces' lifted out of the words left `hasta el
%% perro', which read as `even the dog' (tr_governs_adverb/3 keeps the two
%% together only while both stand in the words)
tr_focus_front(W) :-
    W = w(AW, WC), memberchk(WC, [lower, upper]), atom(AW), tr_focus_adverb(AW),
    \+ tr_is(foreign, W, preposition).
%% (the denial and the word for `only' that open not only ... but)
tr_nonly_start([w(N, _), w(O, _)|_]) :-
    atom(N), tr_negation_word(N), atom(O), tr_lexeme(foreign, O, OL, _), tr_solve(mean(OL, only)), !.
%% (the phrase's number: a phrase's own, a name one, two joined and not only
%% one but another the plural a verb takes for them -- `Lo sapevano Tolomeo
%% ed Eratostene' is the two knowing it, and read with nobody named they
%% were a second object, `lo conocieron a Tolomeo y Eratostene')
tr_accusative_number(np(_, _, _, _, N), N).
tr_accusative_number(name(_), singular).
tr_accusative_number(co(C, _, _), plural) :- C = w(CW, _), atom(CW), \+ tr_solve(mean(CW, or)).
tr_accusative_number(nonly(_, _, _), plural).
tr_accusative_number(advp(_, S), N) :- tr_accusative_number(S, N).
tr_marked_start([w(P, _)|_]) :- atom(P), tr_marker_word(P, person), !.
tr_accusative_clitic(C) :-
    atom(C), tr_clitic(normal, C), \+ tr_reflexive_word(C),
    ( tr_solve(elision_of(C, F)) -> true ; F = C ),
    \+ tr_solve(dative(F)),
    tr_object_pronoun(foreign, F, E), memberchk(E, [it, him, her, them]), !.

%% the plain adverbs at the head of the words before a verb, and the rest
tr_front_adverbs([W|Ws], [W|As], Rest) :- W = w(_, _), tr_plain_adverb(foreign, W), \+ tr_clitic(none, W),
    \+ tr_governs_adverb(foreign, W, Ws), !,
    tr_front_adverbs(Ws, As, Rest).
tr_front_adverbs(Ws, [], Ws).

tr_adverbs_and_clitics(Before) :-
    tr_uncomma(Before, BU), tr_front_adverbs(BU, [_|_], Rest),
    forall(member(X, Rest), ( X = w(C, _), tr_clitic(none, C) )), !.

%% the words of After past the ones a reading of AfterU -- After with its
%% commas out -- took before Rest, with their commas kept
tr_rest_commas(After, AfterU, Rest, RestC) :-
    length(AfterU, NA), length(Rest, NR), K is NA - NR,
    tr_skip_words(After, K, RestC), RestC \== Rest.
tr_skip_words(Ws, 0, Ws) :- !.
tr_skip_words([comma|Ws], K, R) :- !, tr_skip_words(Ws, K, R).
tr_skip_words([_|Ws], K, R) :- K1 is K - 1, tr_skip_words(Ws, K1, R).

%% A RELATIVE CLAUSE AFTER A COMMA AT THE END OF AN INVERTED SUBJECT IS THE
%% SUBJECT'S: `si bien destaca el fuerte aumento experimentado por las ventas
%% de sencillos, que en 1999 absorbieron casi el 4% del mercado total'. The
%% words after the verb lost their commas before the subject was looked for,
%% so the clause ran on into the subject and no subject read; the verb was
%% then read with an object -- `evidenzia il forte aumento', highlights it --
%% where the lesson says it is the increase that stands out. The clause is
%% read on its own and hangs on the subject as it hangs on any phrase before
%% a comma (tr_phrase_nrc/3), and nothing may follow the subject but it.
tr_after_nrc(After, AfterU, nrc(Role, RS)) :-
    append(SW, [comma, w(RW, RC)|R1], After), \+ memberchk(comma, SW), SW \== [],
    tr_relative_word(foreign, RW),
    tr_relative_clause(foreign, [w(RW, RC)|R1], Role, RS), !,
    tr_uncomma(SW, AfterU).
tr_after_nrc(After, AfterU, none) :- tr_uncomma(After, AfterU).

tr_wrap_nrc(none, S, _, S) :- !.
%% ... on the last phrase of a subject that carries phrases (`las ventas DE
%% MINIDISC, que ...'), which is what with/2 is and no phrase is
tr_wrap_nrc(nrc(Role, RS), with(NP, PPs0), [], with(NP, PPs)) :-
    append(Pre, [pp(P, NP2)], PPs0), !, append(Pre, [pp(P, nrc(NP2, Role, RS))], PPs).
tr_wrap_nrc(nrc(Role, RS), S0, [], nrc(S0, Role, RS)) :- S0 \= with(_, _).
%% the last complement's phrase with the clause on it
tr_nrc_on(pp(P, NP), Role, RS, pp(P, nrc(NP, Role, RS))) :- NP \= nrc(_, _, _), !.
tr_nrc_on(obj(NP), Role, RS, obj(nrc(NP, Role, RS))) :- NP \= nrc(_, _, _), !.

%% (the first noun of a phrase's words, before any preposition, is a person)
tr_head_person([W|Ws]) :-
    W = w(X, _), atom(X),
    (   tr_is(foreign, W, preposition) -> fail
    ;   tr_is(foreign, W, noun) -> fo_animate_phrase([W])
    ;   tr_head_person(Ws)
    ).

%% ... AND THE VERB OF BEING ABOUT TO, WHICH TAKES ITS INFINITIVE AS A MODAL
%% DOES: `stava per uscire Transa' is the record that was about to come out,
%% and read as the infinitive's object it was somebody nobody named who was
%% about to go out -- `estaba a punto de salir a Transa'. A verb that makes
%% somebody do something (`fece uscire il disco') takes its infinitive bare
%% too, and its phrase is the one made to, so the verb is asked by what it
%% means.
tr_about_to(L) :- tr_solve(mean(L, 'is about')), !.

%% THE SUBJECT AFTER AN INTRANSITIVE VERB TAKES THE PHRASES THAT SAY WHICH
%% ONE: `l'arcivescovo di Monreale monsignor Salvatore Cassisa' is one
%% subject, and the finder of a question's subject ended it at `di' -- the
%% place and the person were then the verb's, an object among them. Only a
%% `di' phrase and a title with its name go with it, the longest run that
%% reads; anything else after the subject stays the verb's, as it was.
%% A SUBJECT WITH ITS RELATIVE CLAUSE TAKES THE REST OF THE WORDS: `Godranno
%% ... soltanto quelli che hanno scelto di trascorrere le proprie ferie ...'
%% is those who chose, and the finder ended the subject at `quelli' and read
%% `che hanno scelto' as a `that' clause of the verb's
tr_subject_after(Words, third, FN, [], Subject) :-
    once(( member(w(RW, _), Words), tr_relative_word(foreign, RW) )),
    %% (a phrase, so never a preposition or an adverb first: the reader
    %% above offers every place the subject could start, and each read the
    %% relative clause again before the head failed)
    Words = [W1|_], W1 = w(_, _), \+ tr_is(foreign, W1, preposition), \+ tr_plain_adverb(foreign, W1),
    %% (the clause may end in a bracket, which the phrase takes as its last
    %% thing: `... di irretire i presìdi (leggi procure)', app/3)
    (   tr_np(foreign, Words, Subject), ( Subject = rc(Head, _, _) ; Subject = app(rc(Head, _, _), _, _) )
    ->  tr_rc_head_number(Head, FN)
    %% ... AND TWO PHRASES JOINED, THE CLAUSE ON THE LAST: `Ne fanno testo i
    %% lacci e lacciuoli in cui si è cercato ...' is the snares in which one
    %% tried, and a coordination is plural whatever its phrases are. The
    %% phrase reader joins no phrases; the subject reader does
    ;   FN == plural, tr_conjunction_split(foreign, Words, _, _, _),
        tr_subject(foreign, none, Words, third, plural, Subject),
        Subject = co(_, _, Last), tr_co_last_rc(Last)
    ), !.
tr_subject_after(Words, FP, FN, Rest, Subject) :-
    FP == third, length(Words, Len), Len >= 3,
    Words = [W1|_], W1 = w(_, _), \+ tr_is(foreign, W1, preposition), \+ tr_plain_adverb(foreign, W1),
    between(3, Len, K0), K is Len + 3 - K0,
    length(SW, K), append(SW, Rest, Words),
    tr_subject(foreign, none, SW, FP, FN, Subject), Subject = with(_, PPs),
    %% ... and two `di' phrases joined: `Firma il responsabile dell'ambiente E
    %% DEI LAVORI PUBBLICI, Paolo Baratta' is the minister of both, and the
    %% subject ended at the first, the second and the name left to the verb
    %% ... and an infinitive the noun's `di' governs, with its object: `è
    %% venuto il momento DI PORSI LA STESSA DOMANDA'
    tr_subject_after_pps(PPs),
    \+ last(PPs, cnj(_)),
    %% (a share of a plural agrees in the plural, as before the verb: `que "se imponen" una serie de reformas'
    %% is a series of them, and with the plural verb the subject after it had no reading -- English said
    %% `they prevail a series of reforms')
    ( tr_subject_number(Subject, N), N == FN -> true ; FN == plural, tr_share_subject(Subject) ), !.
%% ... AND NOT ONLY ONE BUT ANOTHER (nonly/3): `Che la terra fosse sferica
%% lo sapevano non solo il geocentrico Tolomeo ... ed Eratostene, ma persino
%% Pitagora, ...' is they knowing it, and read with nobody named the denial
%% went to the verb and the halves were its objects
tr_subject_after([w(N, _), O|Ws], third, FN, Rest, nonly(A, B, Also)) :-
    atom(N), tr_negation_word(N), tr_nonly_parts(O, Ws, A, B, Also0, Rest),
    tr_nonly_number(A, B, Also0, FN, Also), !.
%% ... AND ONE WITH THE WORD FOR `even', `also' OR `only' BEFORE IT, which
%% is said of the subject: `Lo sanno persino Luisa, Anna, Rosa' -- even they
%% know it. It travels as advp(Adverb, Subject), which every writer puts in
%% front of the subject, where the subject stands (tr_subject_out/6)
tr_subject_after([A|Words], third, FN, Rest, advp(A, Subject)) :-
    A = w(AW, _), atom(AW), tr_focus_adverb(AW), Words = [_|_],
    tr_subject_after(Words, third, FN, Rest, Subject), Subject \= advp(_, _), !.
%% ... AND TWO JOINED AFTER A PLURAL VERB: `Lo sapevano Tolomeo ed
%% Eratostene' is the two knowing it -- the finder below ends a subject at
%% a name, and two phrases joined were no subject there
%% (`and' only: `Lo sanno non solo Maria ma anche Carla' took `ma' for
%% it, the denial went to the verb and Maria but Carla knew it, `No lo
%% saben Maria pero Carla sólo también')
tr_subject_after(Words, third, plural, Rest, Subject) :-
    append(W1, [Co|W2R], Words), Co = w(CW, _), tr_coord(foreign, Co), W1 \== [], tr_and_word(foreign, CW),
    \+ memberchk(comma, W1),
    %% (or names with list commas between them: `Lo sanno Luisa, Anna e Rosa'
    %% is the three knowing it, and refused here they were read as the object)
    ( tr_np(foreign, W1, _) -> true ; tr_lcomma_names(W1) ),
    fo_np_words_after(W2R, W2, Rest), W2 \== [],
    append(W1, [Co|W2], SW),
    tr_subject(foreign, none, SW, third, plural, Subject), Subject = co(_, _, _), !.
%% ... AND NAMES WITH LIST COMMAS BETWEEN THEM AND NO `and' AT ALL, to the end
%% of the words: `Lo sanno persino Maria, Carla, Luisa' (tr_list_commas/5
%% marks such a run) -- the finder below ends a subject at a name
tr_subject_after(Words, third, plural, [], Subject) :-
    memberchk(w(',', lcomma), Words), tr_lcomma_names(Words),
    tr_subject(foreign, none, Words, third, plural, Subject), Subject = co(_, _, _), !.
tr_subject_after(Words, FP, FN, Rest, Subject) :-
    fo_subject_after(Words, FP, FN, SubjWords, Rest), SubjWords \== [],
    tr_subject(foreign, none, SubjWords, FP, FN, Subject),
    \+ tr_lone_adjective(SubjWords, Subject).

%% ... AND NEVER A LONE WORD THE LESSON KNOWS AS AN ADJECTIVE AND NO NOUN:
%% `aunque haya pasado casi inadvertido' is it went almost unnoticed, and
%% read as the subject after the intransitive verb it was `careless' that
%% happened -- where the same words with a subject before them were already
%% read as what they are, `El efecto ha pasado casi inadvertido'
tr_lone_adjective([W], np(none, none, [], _, _)) :- tr_is(foreign, W, adjective), \+ tr_is(foreign, W, noun).
%% ... and the same word read with its noun left out (tr_np/3's adjective alone)
tr_lone_adjective([W], np(none, none, [W], elided(_), _)) :- tr_is(foreign, W, adjective), \+ tr_is(foreign, W, noun).
%% one-word names with list commas between them: `Luisa, Anna'
tr_lcomma_names([N]) :- !, tr_name_word(foreign, N).
tr_lcomma_names([N, w(',', lcomma)|Ns]) :- tr_name_word(foreign, N), tr_lcomma_names(Ns).

tr_subject_after_pps([]).
tr_subject_after_pps([X|Xs]) :-
    (   X = pp(P, _), tr_means_of(foreign, P) -> Ys = Xs
    ;   X = pinf(P, _), tr_means_of(foreign, P) -> ( Xs = [obj(_)|Ys] -> true ; Ys = Xs )
    ;   X = nprep(P), tr_means_of(foreign, P), Xs = [infx(_, _, _)|Xs1] -> ( Xs1 = [obj(_)|Ys] -> true ; Ys = Xs1 )
    ;   ( X = appos(_) ; X = cnj(_) ) -> Ys = Xs
    ),
    tr_subject_after_pps(Ys).

tr_rc_head_number(pronoun(w(W, _)), N) :- !, tr_lexeme(foreign, W, _, N).
tr_rc_head_number(NP, N) :- fo_np_number(NP, N).
%% the last phrase of a coordination carries a relative clause
tr_co_last_rc(rc(_, _, _)).
tr_co_last_rc(app(rc(_, _, _), _, _)).
tr_co_last_rc(co(_, _, L)) :- tr_co_last_rc(L).

%% (the piece opens on an article, a demonstrative or a possessive in the
%% singular -- asked first, for a plural one is the plural verb's own subject
%% and the plain reading has it: the phrases of every piece that read no
%% other way were read before a verb of it was found to be the wrong one)
tr_phrase_opener(D) :-
    D = w(W, _), atom(W), tr_determiner(foreign, D, DL, DK), memberchk(DK, [article, demonstrative, possessive]),
    tr_det_gender(foreign, D, DL, _, singular), !.
%% (and the word after the verb is a plural noun, the plural of a word that
%% opens a phrase, or a count -- the two phrases were read, the dearest part,
%% only to find an adjective or a participle after the verb)
tr_plural_start(w(W, _)) :-
    atom(W), tr_lexeme(foreign, W, L, plural),
    ( tr_class_of(L, noun) ; tr_class_of(L, article) ; tr_class_of(L, determiner) ; tr_class_of(L, demonstrative) ; tr_class_of(L, possessive) ), !.
tr_plural_start(w(W, C)) :- atom(W), ( tr_digits(W) ; tr_is(foreign, w(W, C), number) ), !.
tr_cleft_who([w(X, C)], P, N, pronoun(P, N, w(X, C))) :- atom(X), tr_subject_pronoun(foreign, X, P, N), !.
tr_cleft_who(Ws, third, singular, name(Name)) :- tr_complements(foreign, Ws, [obj(name(Name))]).
%% ... AND `ONLY' BEFORE THE NAME, with the article or without: `è il solo
%% Segni a ...', `è solo Mario a ...' -- only he (advp/2, as a subject's
%% word for `only' is read)
tr_cleft_who([D, W|Ws], third, singular, advp(W, name(Name))) :-
    D = w(_, _), tr_determiner(foreign, D, _, article), W = w(AW, _), atom(AW), tr_focus_adverb(AW),
    Ws = [_|_], tr_complements(foreign, Ws, [obj(name(Name))]).
tr_cleft_who([W|Ws], third, singular, advp(W, name(Name))) :-
    W = w(AW, _), atom(AW), tr_focus_adverb(AW),
    Ws = [_|_], tr_complements(foreign, Ws, [obj(name(Name))]).
%% the plural form a plural imperative is stated of (`"aprite" is the imperative of "aprono"'), not a denial
tr_command_plural_of(V, Pl) :-
    tr_solve(imperative_of(V, Pl)), \+ tr_holds(negative(V)), tr_solve(plural_of(Pl, _)), !.
%% ... AND SO DOES ONE BEFORE A `that' CLAUSE: `Añade que el Gobierno se
%% comprometió' and `Quiere que se cumpla la ley' are a person nobody named
%% adding and wanting -- the way a newspaper reports -- and read as commands
%% they were `Aggiungi che' and `Vuoi che', to somebody. A command is the
%% reading only where the verb has a form of its own (`di que sí').
tr_that_follows([w(Q, _)|_]) :- atom(Q), tr_solve(mean(Q, that)), tr_solve(conjunction(Q)), !.
%% an affirmative command spelled as a verb's third person singular, with no
%% pronoun joined to it: the reading a coordinator or an adverb at the head
%% stands down (tr_read_after_coord/5)
tr_third_person_command(no, V, Rest1) :-
    \+ Rest1 = [w(_, enclitic)|_], tr_verb_form_any(V), tr_form(V, _, singular, present, third), !.

%% the pronouns an affirmative command carries joined to it, as the words a
%% clitic before the verb would have been
%% ... AND THE SAME PRONOUN WRITTEN AGAIN AFTER IT IS THAT PRONOUN ONCE: the
%% letter signs off `Se sbaglio correggetemi mi.', the treebank's text with
%% the clitic twice. Read as two it could only be written `corregidmeme', a
%% word no speaker writes, so the second is taken for the slip it is.
tr_joined_clitics(no, Ws0, Cls, Ws) :- !, tr_enclitic_run(Ws0, Cls, Ws1), tr_repeated_clitic(Cls, Ws1, Ws).
tr_joined_clitics(_, Ws, [], Ws).

tr_enclitic_run([w(Cl, enclitic)|Ws0], [w(Cl, lower)|Cls], Ws) :- !, tr_enclitic_run(Ws0, Cls, Ws).
tr_enclitic_run(Ws, [], Ws).

tr_repeated_clitic(Cls, [w(X, lower)|Ws], Ws) :- memberchk(w(X, lower), Cls), !.
tr_repeated_clitic(_, Ws, Ws).

%% the imperative of a verb the lesson gives: the form it states, and a
%% DENIED sentence wants the form it states for one -- Spanish's negative
%% imperative is not its affirmative (`come' against `no comas') and
%% Italian's is the infinitive (`non mangiare'), neither of which this
%% knows or needs to: the lesson says which form is which.
%% ... and never a word the lesson calls a preposition: `di' is what `dire'
%% says to one person and the `of' of every other sentence, and `Grazie
%% all'Arma dei carabinieri' came out `Say to the carabineers'
tr_imperative_here(foreign, _, V, _) :- tr_is(foreign, w(V, lower), preposition), !, fail.
tr_imperative_here(foreign, no, V, L) :-
    tr_solve(imperative_of(V, L)), \+ tr_holds(negative(V)), tr_imperative_known(L), !.
tr_imperative_here(foreign, yes, V, L) :-
    tr_solve(imperative_of(V, L)), tr_holds(negative(V)), tr_imperative_known(L), !.
%% ... and a PLURAL whose language states no denial of its own is denied
%% with itself: Italian's `non processate' (tr_imperative_plural_denied/2)
tr_imperative_here(foreign, yes, V, L) :-
    tr_solve(imperative_of(V, L)), tr_imperative_plural_denied(V, L), tr_imperative_known(L), !.
tr_imperative_here(english, _, V, L) :- en_verb_form(V, L, present), !.

%% THE PLURAL IMPERATIVE IS STATED OF THE PLURAL FORM -- `"processate" is
%% the imperative of "processano".', as the past of a plural is -- so the
%% form it is stated of says the number, and the plural's subject is the
%% people spoken to, addressee(plural). The singular keeps `none', the
%% subject it has had since 1.6.10. `"processate il vescovo".' is a
%% headline's command, `"procesad al obispo".', and with no plural stated
%% it read as a passive whose participle agreed with nothing.
tr_imperative_number(F, L, addressee(plural)) :- tr_solve(plural_of(F, L)), !.
tr_imperative_number(L, L, none).

%% the form an imperative is stated of is the lesson's verb: the lexeme,
%% or the plural of one (a plural form has no meaning of its own)
tr_imperative_known(F) :- tr_known(foreign, F), !.
tr_imperative_known(F) :- tr_solve(plural_of(F, L)), tr_known(foreign, L), !.

%% a plural imperative is its own denial where the lesson states none for
%% its form: Spanish says `no comáis', Italian `non processate'. Only the
%% PLURAL: a singular with no denial stated is the third person it is
%% spelled like, `Non mangia il pane', he does not eat the bread.
tr_imperative_plural_denied(V, F) :-
    \+ tr_holds(negative(V)), tr_solve(plural_of(F, _)),
    \+ ( tr_solve(imperative_of(V2, F)), tr_holds(negative(V2)) ).

%% and the form out, for either
tr_imperative_form(L, no, F) :-
    once(( tr_solve(imperative_of(F0, L)), \+ tr_holds(negative(F0)) )), F = F0.
tr_imperative_form(L, yes, F) :-
    once(( tr_solve(imperative_of(F0, L)), tr_holds(negative(F0)) )), F = F0.
%% ... in the number the subject says: the plural's is stated of the plural
%% form, and its denial is the affirmative where the lesson states none
tr_imperative_form(L, singular, Neg, F) :- !, tr_imperative_form(L, Neg, F).
%% (each plural the lesson states of the word, the verb's among the noun's:
%% `cuenta' is a bill as well as counts, and with the bill's `cuentas' taken
%% first `Non contate sulla probabilità' had no Spanish command, `no contéis')
tr_imperative_form(L, plural, Neg, F) :-
    tr_solve(plural_of(Pl, L)),
    (   tr_imperative_form(Pl, Neg, F) -> true
    ;   Neg == yes, tr_imperative_form(Pl, no, F), tr_imperative_plural_denied(F, Pl)
    ), !.

%% a gerund of a verb the lesson gives, on either side
tr_gerund_here(foreign, G, L) :- tr_solve(gerund_of(G, L)), tr_known(foreign, L), !.
tr_gerund_here(english, G, L) :- en_gerund(G, L), !.

%% the word a lesson gives for `that' before a clause: English's own, and
%% a conjunction of the lesson's that means it
tr_that_here(english, w(that, _)) :- !.
tr_that_here(foreign, w(W, _)) :-
    tr_lexeme(foreign, W, L, _), tr_class_of(L, conjunction), tr_solve(mean(L, that)), !.

%% how, where, when and why: the words that open an indirect question
tr_indirect_word(english, W, W) :- memberchk(W, [how, where, when, why, 'whether and how']), !.
tr_indirect_word(foreign, W, Q) :-
    tr_lexeme(foreign, W, L, _), tr_solve(mean(L, Q)), memberchk(Q, [how, where, when, why, 'whether and how']), !.

tr_if_word(W) :- tr_lexeme(foreign, W, L, _), tr_solve(mean(L, if)), tr_class_of(L, conjunction), !.
%% a word that asks, and the English question word it means: `quién' who
tr_question_word(w(Q, _), E) :-
    atom(Q), tr_asking_word(foreign, w(Q, lower)),
    tr_lexeme(foreign, Q, L, _), tr_solve(mean(L, E)), en_question(E, _), !.

%% the verb being read is one the lesson says takes the question
%% (`"capisce" takes the question.')
tr_takes_question_here :- tr_global('$tr_read_group', G), atom(G), tr_solve(take(G, question)), !.

tr_that_word(english, that) :- !.
tr_that_word(foreign, W) :- once(( tr_solve(mean(L, that)), tr_class_of(L, conjunction), W = L )).
%% ... and all of them, kept once a sentence: tr_np/3 asks for one in every
%% word list a phrase might be, and tr_that_here/2 asked of each word in
%% turn cost the controls 0.67 million inferences in five sentences.
%% (WALKED FROM THE CONJUNCTIONS: `mean(L, that)' with L unbound walks every
%% meaning the lesson states, 3.7 ms a sentence against 0.87 -- and 932
%% inferences against 1 384, so the count said the opposite of the clock.
%% Tatoeba's 400 short sentences ran 4 % slower that way with 0.8 % fewer
%% inferences and the same texts.)
tr_that_set(Ts) :- tr_memo(that_set('$tr_that'), L, ( tr_solve(conjunction(L)), tr_solve(mean(L, that)) ), Ts).

%% the complements of a front are adjuncts -- and an infinitive's own
%% object after it: `En su afán por esconder sus planes, ...' hides the
%% plans, and the front was refused for an object in it
tr_ends_on_auxiliary(foreign, Words) :-
    last(Words, w(R, _)), atom(R), tr_solve(infinitive_of(R, L)), tr_solve(auxiliary(L)), !.
%% a perfect infinitive after a preposition, the participle's phrase after it
tr_perfect_before(pinf(_, has), [N|_]) :- ( N = abs(_, _) ; N = pred(_) ), !.

tr_adjuncts([]).
tr_adjuncts([X|Xs]) :- tr_adjunct(X), tr_adjuncts_after(X, Xs).
tr_adjuncts_after(pinf(_, _), [obj(_)|Xs]) :- !, tr_adjuncts(Xs).
%% ... and an adjective straight after a name that `with' governs: `Con Rimac apagado, ...'
%% is an absolute phrase, Rimac being subdued, and the adjective after a name belongs to no
%% phrase (tr_phrase_words/4) -- it stood among the complements, and no adjunct is one
tr_adjuncts_after(pp(P, name(_)), [adj(_)|Xs]) :- tr_means_with(P), !, tr_adjuncts(Xs).
%% ... and a perfect infinitive's participle: `Dopo aver mangiato, tace'
tr_adjuncts_after(pinf(_, L), [pred(_)|Xs]) :- atom(L), tr_solve(auxiliary(L)), !, tr_adjuncts(Xs).
%% ... and a passive one's, the copula's: `per Abbatino, che prima di essere arrestato e di decidere di collaborare con
%% l'autorità giudiziaria era uno dei più noti malviventi della capitale, il pm ha chiesto' -- before he was arrested,
%% a front of the relative clause, and with the participle and the second infinitive no adjuncts it was no front and
%% the sentence was refused. The infinitives joined to it are its own
tr_adjuncts_after(pinf(_, L), [pred(_)|Xs]) :- atom(L), tr_copula_lexeme(L), !, tr_pinf_more(Xs).
tr_adjuncts_after(_, Xs) :- tr_adjuncts(Xs).
tr_pinf_more([cnj(_), X|Xs]) :- ( X = inf(_) ; X = pinf(_, _) ), !, tr_inf_run(Xs).
tr_pinf_more(Xs) :- tr_adjuncts(Xs).
tr_inf_run([inf(_)|Xs]) :- !, tr_inf_run(Xs).
tr_inf_run(Xs) :- tr_adjuncts(Xs).
%% what follows a perfect infinitive after an adjective, in a line with no verb: its predicate
%% (`di esser risultato positivo'), then adjuncts and the date it was on
tr_perf_tail([]).
tr_perf_tail([X|Xs]) :- ( tr_adjunct(X) ; X = adj(_) ; X = obj(NP), tr_date_phrase(NP) ), !, tr_perf_tail(Xs).

%% what may stand before an inverted verb: an adjunct, never an object
tr_adjunct(sep).
tr_adjunct(adv(_)).
tr_adjunct(pp(_, _)).
tr_adjunct(pp2(_, _, _, _)).
tr_adjunct(at_time(_)).
tr_adjunct(pinf(_, _)).                               % `invece di andare da una parte, ...'
tr_adjunct(cnj(_)).                                   % `nella vita di ogni grande organizzazione E delle sue persone'
tr_adjunct(upon(_, _)).                               % `Al abrir la segunda audiencia pública ..., su presidente sostuvo'
tr_adjunct(uponse(_, _, _)).                          % `al generarse un círculo vicioso'
tr_adjunct(upons(_, _, _)).                           % `al estallarle una bomba colocada en la arena'
tr_adjunct(per(_)).                                   % `En él, según manifestó Redondo Terreros a Europa Press, no se abordó'
tr_adjunct(perh(_)).
tr_adjunct(abs(_, _)).                                % `dada la situación de minoría de su Ejecutivo
tr_adjunct(paren(_)).                                 % `chi in Italia (evidentemente a lui obbligato) non lo imita'
tr_adjunct(rwh(where, _)).                             % `alla riunione dove ha combattuto Parisi, Rosi ha smentito': a place's clause stands in front
tr_adjunct(ger(_, Cs)) :-                             % `soltanto parlando con le persone comuni si possono capire'
    \+ ( select(obj(_), Cs, Cs1), memberchk(obj(_), Cs1) ).  % -- one object: a second is the subject after it

tr_existential(english, [w(there, _), w(C, _)|After0], 'there is', T, After, Neg0, Neg) :-
    en_copula(C, third, _, T), tr_existential_no(After0, After, Neg0, Neg).
tr_existential(english, [w(there, _), w(will, _), w(be, _)|After0], 'there is', future, After, Neg0, Neg) :-
    tr_existential_no(After0, After, Neg0, Neg).
tr_existential(foreign, [w(V, _)|After], L, T, After, Neg, Neg) :-
    tr_form(V, L, _, T, third), tr_solve(mean(L, 'there is')),
    \+ tr_auxiliary_before_participle(V, L, After).
%% (never where the word is the auxiliary's too and a participle follows it:
%% `aunque haya pasado casi inadvertido' is the perfect, and `haya' is also
%% what `hay' says in the subjunctive -- read as `there is' the past was a
%% thing there was, `c'è passato quasi inosservato')
tr_auxiliary_before_participle(V, L, [w(P, _)|_]) :-
    atom(P), tr_participle_here(foreign, P, _),
    tr_form(V, AL, _, _, _), AL \== L, tr_solve(auxiliary(AL)), !.

%% `there is no dog': the denial as a determiner
tr_existential_no([w(no, _)|After], After, _, yes) :- !.
tr_existential_no(After, After, Neg, Neg).

%% the phrase a fronted `hay' took for its subject is what there is
tr_existential_fix(foreign, s(Asked, Subject, g(L, T, simple, Neg), Comps), s(Asked, there, g(L, T, simple, Neg), [obj(Subject)|Comps])) :-
    Subject = np(_, _, _, _, _), tr_solve(mean(L, 'there is')), !.
tr_existential_fix(_, S, S).

%% English's `not' wherever it stands, and `cannot' as `can' denied; the
%% lesson's word for `not' wherever it stands
tr_negation(english, Words, Rest, yes) :- append(A, [w(cannot, C)|B], Words), !, append(A, [w(can, C)|B], Rest).
tr_negation(english, Words, Rest, yes) :- append(A, [w(not, _)|B], Words), !, append(A, B, Rest).
%% ... and not a denial that stands before an INFINITIVE after the head of
%% the sentence: `è facile NON ritrovarsi più' denies the getting lost, and
%% taken as the sentence's it said `it is not easy' -- the opposite claim.
%% The complement reader reads it where it stands (neg/1). At the head it is
%% still the sentence's: `Non mangiare il pane' is the negative imperative.
%% NOR A DENIAL INSIDE A CLAUSE THAT STARTED BEFORE IT: `stanno valutando le
%% loro condizioni, che NON destano preoccupazione' denies the concern, and
%% taken as the sentence's it said the doctors were not assessing. A relative
%% word, a `che', a question word or a connecting word before the denial
%% opens a clause of its own, which reads its own denial when its turn comes.
%% -- UNLESS THAT CLAUSE HAS HAD ITS VERB: `el grupo de jugadores que
%% deberán resolver este ingrato compromiso NO figuran ...' is finished at
%% `compromiso', and the denial is the verb's after it; given to the
%% relative clause it said the players must not solve it. A verb form the
%% lesson calls no noun, between the clause's first word and the denial, is
%% that verb.
tr_negation(foreign, Words, Rest, yes) :-
    append(A, [w(N, _)|B], Words), tr_solve(mean(N, not)),
    \+ ( A \== [], tr_starts_infinitive(foreign, B) ),
    %% NOR A DENIAL AFTER A COORDINATOR WITH NO VERB AFTER IT: `un governo che
    %% duri 5 anni e non due mesi' is five years and not two months, and
    %% taken as the sentence's it said `no quiero hacer un gobierno', the
    %% claim turned round. It is the phrase's, which the complement reader
    %% reads where it stands (neg/1).
    \+ ( last(A, w(Co, CoC)), tr_coord(foreign, w(Co, CoC)), \+ ( member(w(V, _), B), atom(V), tr_verb_form_word(V) ) ),
    %% NOR A DENIAL BETWEEN A NOUN AND ITS ADJECTIVE: `un peso non
    %% indifferente' is a weight that is not negligible, and taken as the
    %% sentence's it said that the detail could NOT carry weight. The phrase
    %% reads it where it stands: `non' is an adverb to the lesson, and before
    %% an adjective an adverb is its intensifier (tr_intensify/3).
    \+ ( last(A, P0), P0 = w(_, _), ( tr_is(foreign, P0, noun) ; tr_is(foreign, P0, adjective) ),
         B = [J0|_], J0 = w(JW0, _), atom(JW0), tr_is(foreign, J0, adjective), \+ tr_verb_form_word(JW0) ),
    %% (a verb form that is a PREPOSITION too is no verb here: `manifestó que
    %% la fusión entre Carrefour y Promodès no es buena' -- `entre' is also
    %% the subjunctive of `entrar', and counted as the clause's verb it
    %% gave the denial to `manifestó' and left the clause without it)
    %% (nor the verb of a relative clause there, which is the subject's: `prevede che
    %% chi ha partecipazioni ... non possa essere membro' -- whoever has them may not
    %% be, and with `ha' counted the denial went to `prevede')
    \+ ( append(_, [w(X, XC)|Between], A), tr_opens_clause(w(X, XC)),
         \+ ( append(B1, [w(V, VC)|_], Between), tr_verb_form_word(V), \+ tr_is(foreign, w(V, VC), preposition),
              \+ ( member(w(RW, _), B1), atom(RW), tr_relative_opener(RW) ) ) ),
    %% NOR A DENIAL BEFORE `only' AND A `but' AFTER IT: `vede non solo il
    %% gatto ma anche la casa' sees not only the cat but the house too, and
    %% taken as the sentence's it said he did not see them (nonly/3)
    \+ ( B = [w(OW, _)|B1], atom(OW), tr_lexeme(foreign, OW, OL, _), tr_solve(mean(OL, only)),
         member(w(M, _), B1), atom(M), ( tr_solve(partner_of(M, OW)) ; tr_solve(mean(M, but)) ) ), !,
    append(A, B, Rest).
tr_negation(_, Words, Words, no).

tr_negation_word(N) :- once(tr_solve(mean(N, not))).
%% a word that begins a relative clause, `che' or `chi'
tr_relative_opener(W) :- tr_relative_word(foreign, W), !.
tr_relative_opener(W) :- tr_lexeme(foreign, W, L, _), tr_solve(begin(L, relative)), !.

%% A DENIAL STANDS BEFORE THE VERB IT DENIES: `credo si cominci a vedere
%% qualche risultato ma non posso garantirlo' is I believe one begins to see
%% some result, but I cannot guarantee it. tr_negation/4 takes a word meaning
%% `not' out wherever it stands, and read as one clause the `non' of the
%% second verb denied the first -- `No creo que se comienza a ver algún
%% resultado pero puedo garantizarlo', the claim turned round. In the
%% lesson's languages the denial comes before its verb and its pronouns,
%% never after the verb it denies; English's comes after its auxiliary, so
%% the rule is the lesson's side's. (And the ORDER is the lesson's: where it
%% says its denial follows the verb, `follow(N, verb)', the writer puts it
%% there, and asked here too the check refused `El perro come no el pan',
%% which the `rules' section of the case reads.)
tr_denial_before(foreign, yes, Words0, Before) :- !,
    once(( nth0(I, Words0, w(N, _)), atom(N), tr_negation_word(N) )),
    (   tr_holds(follow(N, verb)) -> true
    ;   length(Before, LB), I =< LB
    ).
tr_denial_before(_, _, _, _).

tr_opens_clause(w(X, _)) :- tr_relative_word(foreign, X), !.
tr_opens_clause(W) :- tr_that_here(foreign, W), !.
tr_opens_clause(w(X, _)) :- tr_indirect_word(foreign, X, _), !.
%% ... and a word that stands for a phrase and its relative both: `redarguire
%% chi non lo imita' denies the imitating, and taken as the sentence's it
%% said Craxi did not rebuke anybody
tr_opens_clause(w(X, _)) :- tr_lexeme(foreign, X, L, _), tr_solve(begin(L, relative)), !.
%% ... but not a COORDINATOR, which joins two phrases of one subject as
%% often as two clauses: `La sua identità E la sua nazionalità non sono
%% state accertate' denies the one verb there is, and with `e' taken for a
%% clause's start the denial was left over and read as an adverb -- `han
%% sido verificados todavía no', the claim turned round. A second clause
%% after a coordinator is the division's to read (tr_read/4), where each
%% half reads its own denial; what the whole-statement reading can take
%% after one is only what tr_after_coord/2 admits -- an infinitive, a
%% preposition, a participle standing alone -- and the rule above keeps a
%% denial before an infinitive where it stands.
tr_opens_clause(w(X, C)) :- tr_connector(foreign, X), \+ tr_coord(foreign, w(X, C)), !.

%% object pronouns at the end of what stands before the verb (`Maria lo
%% ve'): the longest subject that has a subject's shape, the rest object
%% pronouns -- `Ellos la ven' is they and her, never nobody and them
tr_split_clitics(english, Before, _, _, _, Before, []) :- !.
%% (never a pronoun JOINED to the word before it, which is that word's:
%% `gli unici a non credervi erano stati' -- the `vi' is the infinitive's,
%% and taken for a clitic of `erano stati' it left the subject)
tr_split_clitics(foreign, Before, Asked, P, N, Subject, Clitics) :-
    length(Before, Len), between(0, Len, K), length(Clitics, K),
    append(Subject, Clitics, Before),
    forall(member(w(C, CC), Clitics), ( CC \== enclitic, tr_clitic(Asked, C) )),
    tr_subject_shape(Asked, Subject, P, N), !.

%% A REFLEXIVE PRONOUN BELONGS TO THE VERB, NOT TO THE SENTENCE. `si e
%% adeguata', `si sono appellati': the `si' is part of what the verb means,
%% not a thing the subject did it to -- so it comes OFF the clitics and the
%% lexeme is wrapped, `g(reflexive(L), T, A, Neg)'. It travels that way
%% because the reflexive is the VERB's property: a language with a reflexive
%% pronoun writes it back, and English, which has none there, drops it.
%%
%% THE COST IS A TRUE REFLEXIVE, AND IT IS STATED. `si lava' is `washes
%% himself' and comes out `washes'. Italian spells a lexical reflexive and a
%% true one the same way and nothing in a lesson tells them apart; the
%% lexical one is what newspaper prose is made of (`appellarsi', `adeguarsi',
%% `riferirsi'), so that is the reading taken, and the other is wrong.
%%
%% AND `si' IS THE IMPERSONAL WORD TOO, which needs no rule to separate: the
%% impersonal has NOTHING before the verb but itself and is read as the
%% subject, the reflexive has a subject of its own and is read here.
tr_reflexive_off(foreign, Cs0, Cs, L, reflexive(L)) :-
    select(w(R, _), Cs0, Cs), tr_reflexive_word(R), !.
tr_reflexive_off(_, Cs, Cs, L, L).

%% ... AND A PRONOUN OF THE SUBJECT'S OWN PERSON IS ITS REFLEXIVE. `mi sono
%% avvicinato' is I approached, `ci siamo lavati' we washed: the lesson names
%% one reflexive pronoun, the third person's, and the first and second
%% persons use their object pronouns -- so a clitic that means the subject's
%% own object pronoun (`me' for I, `us' for we, `you' for you) comes off the
%% clitics and wraps the lexeme, as `si' does. Read as an object, `mi sono
%% avvicinato' was a passive with a pronoun for its object and came out `Me
%% soy acercado'; and the other way `Me he lavado' came out `Mi ho
%% strofinato', where Italian builds a reflexive's perfect with the copula
tr_personal_reflexive(foreign, FP, FN, Cs0, Cs, L, L, reflexive(L)) :-
    atom(L), nonvar(FP), memberchk(FP, [first, second]), tr_personal_object(FP, FN, E),
    select(w(C, Case), Cs0, Cs), tr_pronoun_across(english, object, w(C, Case), _, _, E), !.
tr_personal_reflexive(_, _, _, Cs, Cs, _, LV, LV).
tr_slip_reflexive(Cs) :- member(w(C, _), Cs), atom(C), tr_solve(dative(C)), !.
tr_personal_object(first, singular, me).
tr_personal_object(first, plural, us).
tr_personal_object(second, singular, you).
tr_personal_object(second, plural, 'you all').

%% A SUBJECT NOBODY NAMED TAKES THE NUMBER OF WHAT THE COPULA SAYS IT IS:
%% `sono due eroi' is they -- `sono' is also I, and read first it came out
%% `Soy dos héroes'. The phrase after the copula agrees with the subject, so
%% its number decides between the verb's two readings.
%% ... EXCEPT A PLURAL OF THE FIRST OR THE SECOND PERSON, which names a team in the
%% singular: `Siamo una squadra' is we are a team, and `siamo' is no one else's
%% (it is `sono' that is I and they alike)
tr_null_copula_agrees(null(P, N), L, A, Comps) :-
    memberchk(A, [simple, perfect]), atom(L), tr_copula_lexeme(L),
    (   Comps = [obj(NP)|_] -> fo_np_number(NP, NN)
    ;   tr_past_adverbs(Comps, [obj(NP)|_]), fo_np_number(NP, NN), NN == plural
    ), !,
    ( NN == N -> true ; N == plural, P \== third ).
tr_null_copula_agrees(_, _, _, _).
%% (... past an adverb before the phrase, where the phrase is plural: `Per il momento
%% sono solo stime' is THEY are only estimates, and with `solo' first it came out `Soy
%% sólo estimaciones' -- a singular one there says nothing of the subject, `erano solo
%% un centinaio i tifosi' is the supporters, and taken for a denial of `they' the
%% sentence was refused)
tr_past_adverbs([adv(_)|Cs], Rest) :- !, tr_past_adverbs(Cs, Rest).
tr_past_adverbs(Cs, Cs).

%% ... AND THE ADJECTIVE SAYS IT TOO: `in un certo senso sono troppi' is
%% THEY are too many, and `sono' is I am as well -- read with the first
%% reading the group finder gave, it came out `Soy demasiado'. A predicate
%% adjective the lesson knows only in the other number is no predicate of
%% that subject; an adjective the lesson gives both numbers says nothing.
tr_null_adjective_agrees(foreign, null(_, N), L, A, [adj([J|_])|_]) :-
    memberchk(A, [simple, perfect]), atom(L), tr_copula_lexeme(L),
    ( J = w(W, _) -> true ; J = int(_, w(W, _)) ), atom(W),
    tr_lexeme(foreign, W, _, _), \+ tr_lexeme(foreign, W, _, N), !, fail.
%% ... AND SO DOES A PRONOUN THE LESSON STATES AS A PLURAL: `Non sono pochi'
%% is THEY are not few -- `pochi' is a pronoun of its own (`The pronoun
%% "pochi" means "few".') and the plural of `poco' -- and read with `sono' as
%% the first person it came out `No soy pocos'
tr_null_adjective_agrees(foreign, null(_, N), L, A, [opron(w(W, _))|_]) :-
    memberchk(A, [simple, perfect]), atom(L), tr_copula_lexeme(L),
    atom(W), tr_solve(plural_of(W, _)), N == singular, !, fail.
tr_null_adjective_agrees(_, _, _, _, _).

%% A PHRASE IS A THIRD PERSON. The subject reader took the verb's person on
%% trust, so `Monte Livata, ritrovati vivi donna' read `vivi' -- you live --
%% as the verb of `Monte Livata retrieved', and the headline came out as a
%% mountain living. A name, a phrase and everything built on one takes a
%% verb in the third person; a pronoun, two joined and nobody say their own.
%% The LESSON's side only: English's `are' is you, we and they alike, and
%% its reader gives the one reading `second' -- `The houses are big' would
%% be refused.
tr_person_agrees(foreign, S, P) :- tr_phrase_subject(S), !, P == third.
tr_person_agrees(_, _, _).

%% A COMMA BETWEEN TWO NAMES PARTS THEM. The subject side is read without
%% its commas, and a run of capitalised words is one name -- so `Salvo la
%% concesión de Rivaldo y Overmars, Serra Ferrer no quiere correr riesgos'
%% gave the coach's name the player's in front of it, `Overmars Serra
%% Ferrer', and `Salvo' was a verb, I save. A list's commas and an
%% apposition's are words of their own by now (tr_list_commas/3), so a
%% bare comma between two names is where a front ends.
%% ... and a capitalised NOUN after the comma is a name there too, since a
%% name goes on through one (tr_np/3, `Javier Solana'): read with its commas
%% out, `Juan, Pedro, Casa, María y Ana duermen' had `Pedro Casa María' for
%% one name
tr_names_parted(Side, Words) :-
    append(_, [W1, comma, W2|_], Words), W1 = w(_, upper), W2 = w(_, upper),
    tr_name_word(Side, W1), ( tr_name_word(Side, W2) ; tr_is(Side, W2, noun) ), !.
%% ... AND A SUBJECT DOES NOT RUN ACROSS A COMMA INTO THE NAME THAT ENDS IT:
%% `Pese a que empezó frío, poco expresivo, Bros fue entonándose' divided at
%% its first comma read `poco expresivo Bros' as one subject, a little
%% expressive thing called Bros. What stands before the comma is the clause
%% before's, and the name is the subject on its own.
%% ... which is what a comma before a name and a verb says of the whole
%% piece: read with its commas taken out, the word before the comma ran
%% into the name
tr_name_opens_clause(Side, Words) :-
    append(_, [W1, comma, W2, w(V, _)|_], Words), W1 = w(_, _), \+ tr_name_word(Side, W1),
    W2 = w(_, upper), tr_name_word(Side, W2), tr_verb_form_word(V), !.
tr_name_after_comma(Side, Words) :-
    append(_, [W1, comma, W2], Words), W1 = w(_, _), \+ tr_name_word(Side, W1),
    W2 = w(_, upper), tr_name_word(Side, W2), !.

%% ... AND A COMMA BEFORE THE `y' THAT JOINS A PHRASE TO THE ONE AFTER IT
%% PARTS THEM: `Un bloque de una tremenda consistencia, y los azulgranas ...
%% se vieron obligados a un tremendo derroche' is a phrase with no verb --
%% the team Maljkovic built, said again -- and then a clause. The lesson's
%% languages write no comma before the coordinator of a pair, and read with
%% the commas taken out the block and the players were one plural subject,
%% the block forced to a splurge. The first phrase has no comma of its own (a
%% list's last comma is `A, B, y C'), the coordinator opens a phrase with a
%% determiner, and the commas after it come in pairs, an aside's: one
%% comma after it closes the pair that began before the `y' (`El presidente,
%% y los ministros, firmaron'), and stays a subject of two
tr_comma_and_parted(foreign, Words) :-
    append(Pre, [comma, C, D|Post], Words), Pre = [_|_], \+ memberchk(comma, Pre),
    C = w(_, _), tr_coord(foreign, C), D = w(_, _), tr_determiner(foreign, D, _, _),
    aggregate_all(count, member(comma, Post), N), 0 is N mod 2, !.

%% ... AND IN ITS OWN NUMBER: `e il bambino su una roccia, poi si sono fatti
%% forza' read the boy on a rock as the subject of `si sono fatti' and wrote
%% `se ha hecho fuerza', one boy for the two children the plural said. A
%% phrase whose number is its noun's must agree with the verb that has it.
%% ... EXCEPT A SHARE OF A PLURAL: `más de un 60% de los electores habían
%% votado' agrees with the voters, as `la mayoría de los electores votaron'
%% does, and both languages allow it. The head is a percentage, or a noun
%% the lesson says means majority or minority, and a `de' phrase in the
%% plural follows it.
tr_number_agrees(foreign, S, plural) :- tr_share_subject(S), !.
tr_number_agrees(foreign, S, N) :- tr_subject_number(S, SN), !, SN == N.
tr_number_agrees(_, _, _).

%% the subject that is a share of a plural: the head a share word, `de' and the plural
tr_share_subject(with(NP0, [pp(P, NP2)|_])) :-
    ( NP0 = all(_, NP) -> true ; NP = NP0 ),                % `tutta una serie di problemi'
    NP = np(_, _, _, w(W, _), singular), tr_share_word(W),
    tr_means_of(foreign, P), tr_subject_number(NP2, plural).

tr_share_word(W) :- atom(W), sub_atom(W, _, 1, 0, '%'), !.
%% ... and a SERIES of them: `una serie di problemi (...) vengono trascurati'
%% ... and a PART of them: `parte de los explosivos fueron colocados cerca de
%% un vehículo' -- the verb is the explosives', as the majority's is the voters'
tr_share_word(W) :- tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)), memberchk(E, [majority, minority, series, part]), !.

tr_subject_number(np(_, _, _, W, N), N) :- W \= elided(_), W \= named(_, _).
%% (and a name the lesson states with no determiner is in the number it
%% states: `llegaron les lions de Bruno Metsu', tr_np/3)
tr_subject_number(np(none, _, _, named(_, _), N), N).
%% ... and a name after its article is in the article's number: `e se
%% devono rappresentare l'Europa lo fanno su un foglio' -- the atlases do it,
%% and with `l'Europa' in no number the division before the article read
%% Europe as the subject of `lo fanno', `el Europa lo hace', one for the plural
tr_subject_number(np(det(_, _, _), _, _, named(_, _), N), N) :- atom(N).
%% ... and a bare name is ONE: `curiosamente Rivaldo y Overmars tampoco
%% estuvieron' divided at its `y', and `Overmars tampoco estuvieron' read as
%% a clause of its own with one man for the plural's subject
tr_subject_number(name(_), singular).
tr_subject_number(advp(_, S), N) :- tr_subject_number(S, N).
tr_subject_number(ninf(_), singular).
tr_subject_number(nq(_, _), singular).
tr_subject_number(with(NP, _), N) :- tr_subject_number(NP, N).
tr_subject_number(all(_, NP), N) :- tr_subject_number(NP, N).
tr_subject_number(app(NP, _, _), N) :- tr_subject_number(NP, N).
%% ... and a phrase with its relative clause is the phrase's number: `Carlos
%% Herrera, que se expresó en catalán, y Margarida Lluch presentaron el acto'
%% -- read with its commas out the clause ran on over `y Margarida Lluch',
%% one man for the plural's subject, and Italian wrote `presentò'
tr_subject_number(rc(NP, _, _), N) :- tr_subject_number(NP, N).

%% ... and the impersonal `si' takes the third person SINGULAR: `si sono
%% fatti forza', `si sono mossi' are they, and the reflexive -- read as the
%% impersonal the plural came out `se ha hecho', one person where there were
%% two. With a plural verb the `si' is the verb's own, and the subject the
%% one nobody named.
tr_impersonal_agrees(impersonal, P, N) :- !, P == third, N == singular.
tr_impersonal_agrees(_, _, _).

tr_phrase_subject(np(_, _, _, _, _)).
tr_phrase_subject(name(_)).
tr_phrase_subject(rel(_, _, _)).
tr_phrase_subject(rc(_, _, _)).
tr_phrase_subject(ncl(_, _)).
tr_phrase_subject(app(_, _, _)).
tr_phrase_subject(all(_, _)).
tr_phrase_subject(with(_, _)).

%% THE COPULA IS THE PERFECT'S AUXILIARY AFTER `si', AND THE LESSON SAYS SO:
%% `"è" is the auxiliary of the reflexive.' With no `si' before it, the
%% copula and a participle are a passive -- and so `si è adeguata' was read
%% as `is adapted', which is how `no se es adaptado' came out of the
%% newspaper sample. After the reflexive or the impersonal `si' they are the
%% perfect: `si è adeguata' has adapted, `si era temuto il peggio' one had
%% feared the worst. A lesson that names no such auxiliary keeps its passive.
tr_si_perfect(LV, Subject, passive, perfect) :-
    ( LV = reflexive(_) ; Subject == impersonal ), tr_solve(auxiliary_of(_, reflexive)), !.
tr_si_perfect(_, _, A, A).

%% a pronoun the lesson calls reflexive
tr_reflexive_word(R) :- tr_lexeme(foreign, R, RL, _), tr_class_of(RL, pronoun), tr_solve(reflexive(RL)), !.

%% an object pronoun that is no tonic one (`esto', `estas' stand after the
%% verb, never before it); before a fronted verb, one that could not be
%% the subject standing in its place (`¿Ella come el pan?' is she, in order)
tr_clitic(fronted, C) :- !, tr_object_pronoun(foreign, C, _), \+ tr_tonic_word(C), \+ tr_subject_pronoun(foreign, C, _, _).
tr_clitic(_, C) :- tr_reflexive_word(C), !.
%% (never a subject pronoun the lesson says does not precede the verb: `noi
%% siamo solo all'1,4' is we are, and read as the object pronoun `us' before
%% a first person verb it was that person's reflexive, `se son' -- nor the
%% reflexive pronoun that stands after a preposition and never before the
%% verb, Spanish's `sí' and Italian's `sé': `Pedro sí se permitió hacer una
%% crítica' is yes, he allowed himself, and `sí' the pronoun was `Pedro itself
%% allowed itself', `si si permise')
tr_clitic(_, C) :-
    tr_object_pronoun(foreign, C, _), \+ tr_tonic_word(C),
    \+ ( tr_lexeme(foreign, C, L, _), tr_solve(neg(precede(L, verb))),   % the denial first: few pronouns
         ( tr_subject_pronoun(foreign, C, _, _) ; tr_solve(mean(L, itself)) ) ).   % have one, and this is the dear question

%% a word of the lesson's that means one of English's pronouns standing alone
tr_tonic_word(C) :- tr_lexeme(foreign, C, L, _), tr_solve(mean(L, E)), en_tonic(E, _), !.

%% what may stand as the subject: nothing when the subject is asked for or
%% comes after a fronted verb, or when the verb says who (I, you, we,
%% they: never a third person singular, who could be anybody); one
%% pronoun agreeing with the verb; one name; two subjects joined; a phrase
%% with a noun the lesson knows, or headed by a determiner or a number,
%% no object pronoun in it that is not an article too, and none at its end
%% (`Sus perros la ven': the dogs, and her)
%% a relative word as the subject stands for the phrase before it, which is
%% a third person: `lo que quiero' is what I love, and read with `que' for
%% the subject it came out `that loves'
tr_subject_shape(subject(rel), Words, P, _) :- !, Words == [], P == third.
tr_subject_shape(subject(_), Words, _, _) :- !, Words == [].
tr_subject_shape(fronted, Words, _, _) :- !, Words == [].
tr_subject_shape(unsaid(_), Words, _, _) :- !, Words == [].
tr_subject_shape(_, [], P, N) :- !, ( P \== third ; N == plural ).
%% WHAT STANDS ASIDE AFTER A SUBJECT IS NO WORD OF ITS SHAPE: `Carlos
%% Westendorp, Alto Representante Civil en Bosnia, ...' is a name and what
%% it is, and the name's shape is the name's alone -- with the aside's key
%% counted as a word the phrase had no noun and the sentence was refused
%% -- and a name apposed to a name between commas (tr_list_commas/3): `Carlo
%% Rognoni, Pds, parla dell'intreccio ...' is a man and his party, and with the
%% party's word counted the two names had no shape
tr_subject_shape(A, Words, P, N) :-
    append(Core, [w(_, Kind)], Words), memberchk(Kind, [aside, paren, dashed, appos]), Core = [_|_], !,
    tr_subject_shape(A, Core, P, N).
%% ... AND THE WORD FOR `all' BEFORE THE SHAPE OF A PHRASE HAS ITS SHAPE:
%% `Tutti gli altri hanno perplessità' -- `gli altri' is a determiner and a
%% pronoun, the shape above, and with `tutti' before it the words had none
tr_subject_shape(A, [w(T, _), D|Ws], P, N) :-
    atom(T), tr_all_word(foreign, T), D = w(_, _), tr_determiner(foreign, D, _, _),
    tr_subject_shape(A, [D|Ws], P, N), !.
%% ... AND BEFORE A WORD THAT REPLACES A NOUN AND ITS RELATIVE CLAUSE: `Todo lo que dice Pedro es
%% verdad' (tr_np/3's all/2), and with a pronoun that says how much and its `of': `Nada de lo que
%% hoy es el equipo' -- each has the shape of the phrase after it
tr_subject_shape(A, [w(T, _), Q, w(R, RC)|Ws], P, N) :-
    nb_getval('$tr_replacer', yes),
    atom(T), tr_all_word(foreign, T), tr_noun_replacer(foreign, Q), tr_relative_word(foreign, R),
    tr_subject_shape(A, [Q, w(R, RC)|Ws], P, N), !.
tr_subject_shape(A, [w(T, _), Pr, Q, w(R, RC)|Ws], P, N) :-
    nb_getval('$tr_replacer', yes),
    atom(T), tr_none_word(T), tr_means_of(foreign, Pr), tr_noun_replacer(foreign, Q), tr_relative_word(foreign, R),
    tr_subject_shape(A, [Q, w(R, RC)|Ws], P, N), !.
%% ... AND THE WORD FOR `even', `also' OR `only' BEFORE A SUBJECT HAS THE
%% SUBJECT'S SHAPE (tr_subject/6's advp/2): `Persino Maria ha parlato'
tr_subject_shape(A, [W|Ws], P, N) :-
    Ws = [_|_], tr_focus_front(W), tr_subject_shape(A, Ws, P, N), !.
tr_subject_shape(_, [w(W, _)], P, N) :- tr_subject_pronoun(foreign, W, P1, N1), !, P1 == P, N1 == N.
tr_subject_shape(_, [w(W, _)], P, N) :- tr_impersonal(foreign, W), !, P == third, N == singular.
tr_subject_shape(_, [w(W, upper)], _, _) :- \+ tr_known_word(foreign, W), !.
tr_subject_shape(_, [W1, W2|Ws], P, N) :-
    forall(member(W, [W1, W2|Ws]), tr_name_word(foreign, W)), !, P == third, N == singular.
%% AN INFINITIVE AND WHAT IT TAKES (tr_subject/6's infs/2), in the third
%% person singular: `parlare con Diego era ...' has no noun in it, and the
%% shape below wants one
tr_subject_shape(_, [w(V, _)|_], P, N) :-
    P == third, N == singular, tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !.
%% A DETERMINER AND A PRONOUN IS A PHRASE WHOSE HEAD IS THE PRONOUN.
%% `Il tutto avviene' is `The whole happens' -- and the guard below refuses
%% any object pronoun in a subject phrase, which is right for `Sus perros la
%% ven' (the dogs, and her) and wrong here, where the pronoun is the only
%% content word the phrase has. A word that is a determiner too is no head,
%% which is the `uno' rule of 1.6.7 said from this side.
tr_subject_shape(_, [D, w(X, _)], _, _) :-
    tr_determiner(foreign, D, _, _),
    tr_is(foreign, w(X, lower), pronoun),
    \+ tr_determiner(foreign, w(X, lower), _, _), !.
%% ... AND A PRONOUN OF SOMEBODY OR NOBODY AND A PREPOSITION AFTER IT (tr_subject/6's with/2): `Por fin alguien con
%% sensibilidad se ha preocupado' -- the guard below refuses a pronoun in a subject phrase
tr_subject_shape(A, [w(X, _), Pr|Ws], P, N) :-
    P == third, N == singular, atom(X), tr_is(foreign, Pr, preposition), \+ tr_means_of(foreign, Pr),
    %% (never before a phrase of `of', which says how many of them: `se nessuno di voi ci ha mai creduto' is none of you,
    %% `ninguno de vosotros', and read as the pronoun with its phrase it was `nadie de vosotros')
    %% (and no object pronoun at its end, which is the verb's: tr_split_clitics/7 asks the longest words first, and
    %% `alguien con sensibilidad se' kept the reflexive in the subject)
    \+ ( last(Ws, w(LW, _)), atom(LW), tr_clitic(A, LW) ),
    tr_lexeme(foreign, X, L, _), tr_class_of(L, pronoun),
    once(( tr_solve(mean(L, E)), memberchk(E, [somebody, someone, nobody, anybody, anyone, everybody, everyone]) )), !.
%% A WORD THAT REPLACES A NOUN AND A RELATIVE CLAUSE is a phrase whose noun
%% was left out: `lo que hace es "desacreditar" la investigación', what it
%% does. `lo' is an object pronoun too, which the guard below refuses in a
%% subject, and it is no determiner either
%% ... WITHOUT AN OBJECT PRONOUN AT ITS END, which is the verb's after it, as
%% it is after any phrase (`Sus perros la ven'): `Quello che è accaduto mi
%% sorprende' is what happened surprises me, and the clitic taken for the
%% relative clause's own, `eso que me ha pasado sorprende', the main verb had
%% nobody to be said of
tr_subject_shape(_, [Q, w(R, _)|Ws], P, N) :-
    P == third, N == singular, tr_noun_replacer(foreign, Q), tr_relative_word(foreign, R),
    \+ ( last(Ws, w(X, XC)), XC \== enclitic, atom(X), tr_clitic(none, X) ), !.
%% ... AND THE SAME WORD AND AN ADJECTIVE THAT JUDGES: `lo cierto es que' (tr_np/3)
tr_subject_shape(_, [Q, A], P, N) :-
    P == third, N == singular, tr_noun_replacer(foreign, Q), tr_judging_adjective(A), !.
%% ... AND THE WORD FOR `more' AND AN ADJECTIVE: `lo más formidable' (tr_np/3's most formidable thing)
tr_subject_shape(_, [Q, w(M, _), A|_], P, N) :-
    nb_getval('$tr_replacer', yes),
    P == third, N == singular, tr_noun_replacer(foreign, Q), atom(M), tr_degree_word(M), tr_is(foreign, A, adjective), !.
tr_subject_shape(_, Words, _, _) :-
    tr_conjunction_split(foreign, Words, W1, W2), !,
    tr_subject_shape(none, W1, third, singular), tr_subject_shape(none, W2, third, singular).
%% ... and both ... and (tr_subject/6's co(both, ...)), each half its own
%% shape -- a pronoun alone among them: `tanto él como los actuales
%% miembros', where `él' is `him' too and the guard below refused it
tr_subject_shape(_, [w(B, _)|Ws], _, _) :-
    atom(B), tr_both_word(foreign, B, Pa), append(W1, [w(Pa, _)|W2], Ws), W1 \== [], W2 \== [], !,
    forall(member(H, [W1, W2]),
           ( H = [w(X, _)], atom(X), tr_subject_pronoun(foreign, X, _, _) -> true ; tr_subject_shape(none, H, third, singular) )).
tr_subject_shape(_, Words, _, _) :-
    %% A BARE TIME PHRASE IS NOT A SUBJECT. `Qui solo due anni fa dominava
    %% il coprifuoco' is the curfew dominating and `solo due anni' is when;
    %% the plain reading took it for the subject, which is a WRONG reading
    %% rather than a refusal and the worse of the two. A DETERMINER makes it
    %% one again -- `L'anno era lungo' is about the year -- so the rule is
    %% as narrow as the shape that needs it.
    \+ ( Words = [W0|_], \+ tr_determiner(foreign, W0, _, _),
         tr_np(foreign, Words, NP0), tr_time_phrase(NP0) ),
    %% -- in the phrase's OWN words, which end at a relative word: `Los
    %% violines que se exponen han mejorado' has its reflexive inside the
    %% relative clause, where it is the clause's and no adjective of the
    %% phrase, and refused there the sentence read with no verb at all.
    %% ONLY A RELATIVE CLAUSE THAT OPENS NO FURTHER CLAUSE: Livata's `... che
    %% li hanno trovati vigili e in buone condizioni nonostante le
    %% temperature ... abbiano raggiunto' offered twenty-seven words before
    %% `abbiano' as a subject, their `li' after `che', and the one-statement
    %% reading parsed all of them before the division at `nonostante' read
    %% the sentence: 8.3 million inferences became 13.6. A subject's relative
    %% clause runs to the subject's verb; one that opens another clause on
    %% the way is two clauses, and the pronoun in it is the old refusal.
    (   append(Own, [w(RW, _)|RelWs], Words), tr_relative_word(foreign, RW),
        \+ ( member(X, RelWs), tr_opens_clause(X) )
    ->  true
    ;   Own = Words
    ),
    %% (a pronoun JOINED to the infinitive before it is that infinitive's:
    %% `gli unici a non credervi' -- and only an infinitive's: a gerund's,
    %% Clinton's `pidiéndole que designara ...', counted as no clitic too, and
    %% the subject reading ran on through the whole clause before it failed,
    %% 4.4 million inferences of that sentence's 11.8)
    \+ ( append(OwnBefore, [w(X, XC)|_], Own), \+ tr_infinitive_pronoun(OwnBefore, XC), tr_object_pronoun(foreign, X, _), \+ tr_determiner(foreign, w(X, lower), _, _),
         %% ... but a pronoun right after a preposition is that preposition's
         %% object and no clitic, which stands before a verb: `Le preoccupazioni manifestate da noi erano
         %% fondate' -- `noi' and `lui' are object pronouns as well as subject
         %% ones, and every subject with `da noi' in it was refused
         \+ ( OwnBefore = [_|_], last(OwnBefore, PrevW), tr_is(foreign, PrevW, preposition) ),
         %% ... but `all' before a determiner is the phrase's own, all/2:
         %% `Tutta una serie di problemi (...) vengono trascurati', and
         %% `tutta' is the pronoun `everything' as well
         \+ ( Own = [w(X, _), D1|_], tr_all_word(foreign, X), tr_determiner(foreign, D1, _, _) ),
         %% ... or a pronoun that opens the subject and has a phrase of `of'
         %% after it, which a clitic never has: `Qualcuno dei suoi ragazzi
         %% affogasse' is someone of his boys, and `qualcuno' is an object
         %% pronoun as well as a subject one
         \+ ( OwnBefore == [], Own = [_, P|_], P = w(_, _), tr_is(foreign, P, preposition), tr_means_of(foreign, P) ) ),
    %% -- and at its end a CLITIC, never a pronoun that stands alone after its
    %% determiner: `Gli altri erano vicini' is the others, and `altri' means
    %% `others', which an object may be as well as a subject. ONLY AFTER A
    %% DETERMINER, where the pronoun heads the phrase: after a preposition it
    %% ends the phrase's `in' phrase, and `Due bambini ..., in quelle
    %% condizioni, a meno 5 gradi' read `quelle' there, and `condizioni' as
    %% its verb
    %% (or right after a preposition, where a pronoun is that preposition's
    %% object and never a clitic: `manifestate da noi')
    \+ ( last(Words, w(X, XC)), \+ ( XC == enclitic, append(Before, [_], Words), tr_infinitive_pronoun(Before, XC) ), tr_object_pronoun(foreign, X, _),
         \+ ( tr_tonic_word(X), append(_, [D, w(X, _)], Words), tr_determiner(foreign, D, _, _) ),
         %% (a pronoun no determiner is: `i profili di incostituzionalità di
         %% questa legge' has `questa' after its preposition and `legge'
         %% after it, and with `questa' the subject's last word `legge' was
         %% the verb, `esto lee'). A POSSESSIVE IS NO DETERMINER OF THE NEXT
         %% WORD HERE: `loro' is `them' as well as `their', and `alcuni di
         %% loro vivono' is some of them -- taken for a clitic the subject was
         %% refused and the sentence with it
         %% ... AND AFTER THE WORD FOR `like' A DEMONSTRATIVE IS THE PRONOUN, whatever
         %% word comes next: `verdetti alla casereccia come questo mi fan venire
         %% voglia' -- like this one -- where `un cane come questo dorme' had
         %% `questo' taken for a clitic (it is a determiner as well) and the
         %% subject refused
         \+ ( append(_, [PW0, w(X, _)], Words), tr_is(foreign, PW0, preposition),
              \+ ( tr_determiner(foreign, w(X, lower), _, DK), DK \== possessive, \+ tr_like_word(PW0) ) ) ),
    %% nor a REFLEXIVE pronoun anywhere in it: `la casa si' is the phrase and
    %% the clitic, never a phrase with `si' for an adjective
    \+ ( member(w(X, _), Own), tr_reflexive_word(X) ),
    %% -- nor at its end past a relative clause: `El hombre que duerme se
    %% reunió' is the man gathering, and with the subject's words taken to
    %% the verb the clause ran on to `se' -- the impersonal `one', its
    %% object: `L'uomo che dorme uno adunò'
    \+ ( last(Words, w(X, _)), atom(X), tr_reflexive_word(X) ),
    (   member(W, Words), tr_is(foreign, W, noun) -> true
    %% ... or a NAME with its relative clause: `E Pannella che si unisce a
    %% Ferrara ... non ha pensato', `Maria che dorme mangia'. A name is no
    %% noun to the lesson, so a clause with no noun in it refused the
    %% subject, and one with a noun (`Maria che mangia il pane') passed by
    %% the clause's noun
    ;   Own \== Words, Own = [_|_], forall(member(N0, Own), tr_name_word(foreign, N0)) -> true
    %% ... or a NAME AND THE PHRASES AFTER IT that say which: `Jeffrey
    %% Burton Russell nel suo Inventing The Flat Earth (New York, 1991) ha
    %% mostrato ...' -- the man in his book, and with a name for the book the
    %% subject had no noun at all
    ;   append(NWs, [P1|_], Words), NWs \== [], tr_is(foreign, P1, preposition),
        forall(member(N1, NWs), tr_name_word(foreign, N1)) -> true
    ;   Words = [D, _|_], ( tr_determiner(foreign, D, _, _) ; tr_is(foreign, D, number) )
    %% ... or a WORD THAT BEGINS THE RELATIVE and its clause (tr_subject/6): `Chi
    %% dorme mangia', `che chi ha partecipazioni di rilievo non possa essere
    %% membro del governo' -- whoever sleeps; with no noun in its clause the
    %% subject had no shape, and `Chi dorme bene' read only because `bene' is a noun
    ;   Words = [w(RW, _), _|_], atom(RW), tr_lexeme(foreign, RW, RL, _), tr_solve(begin(RL, relative))
    %% ... or a PRONOUN AND A PHRASE OF `of' AFTER IT, which has no noun of its
    %% own but its object's: `Qualcuno di voi sta giocando' is somebody of you,
    %% as `Nessuno di voi' and `Uno di loro' are, whose heads are determiners
    %% the line above lets through -- `qualcuno' is only a pronoun, and the
    %% subject was refused
    ;   Words = [Q, P|_], Q = w(_, _), P = w(_, _), tr_is(foreign, Q, pronoun),
        tr_is(foreign, P, preposition), tr_means_of(foreign, P)
    ).

%% the verb group at the first place one starts WHOSE SUBJECT READS, for a
%% statement: with a vocabulary of thousands of verbs a noun is often a
%% verb's form too -- `hermano' is the first person of `hermana', to twin
%% -- and the first place a group starts in `Mi hermano tiene un coche' is
%% `hermano', which leaves `Mi' as the subject. The place is tried in
%% order and the reader goes on to the next when nothing before it is a
%% subject
%% A SECOND PERSON AT THE HEAD, SPELLED LIKE A NOUN'S PLURAL, IS TRIED LAST.
%% `Diferencias en las proporciones de los personajes ... son algunos de los
%% errores' is differences being some of the errors, and `diferencias' is
%% also what `diferenciar' says to one person: read at the first place a
%% group starts, YOU differentiated, and `son' after `en el plano' was the
%% noun `sound'. Spanish and Italian spell a second person like a noun's
%% plural (`compras', `parti'), and a statement opens on its subject far
%% oftener than on a verb spoken to somebody, so the places after the head
%% are tried first; where none of them reads, the head is the verb as before
%% (`Compras pan', you buy bread).
%% ... BUT A BARE NOUN ALONE IS NO SUBJECT BEFORE ITS VERB, in either language:
%% `Diferencias en las proporciones ... son' has its phrase after it. `i
%% presìdi (leggi procure)' is `(read: prosecutors' offices)', the command
%% the reader takes for `you read' (1.8.14's cost); with the place right
%% after the head tried first, the head was the laws and `procure' -- the
%% offices' plural, and the verb `procura''s as well -- what they did,
%% `(actos procuran)'. So that place comes after the head itself, where it
%% came before it until this rule, and no reading is lost.
%% (A person the lesson states is asked for first, which few words are: asked
%% after the noun and the group, every group found paid for them.)
tr_group_from(Side, Words, Before, Group, After) :-
    Side == foreign, Words = [W1|_], W1 = w(A1, _), atom(A1), tr_solve(person_of(A1, _)), tr_is(foreign, W1, noun),
    once(tr_group_at(foreign, Words, g(_, _, _, P0, _), _)), P0 == second, !,
    (   tr_group_from0(Side, Words, Before, Group, After), Before = [_, _|_]
    ;   Before = [], tr_group_from0(Side, Words, [], Group, After)
    ;   Before = [_], tr_group_from0(Side, Words, Before, Group, After)
    ).
tr_group_from(Side, Words, Before, Group, After) :- tr_group_from0(Side, Words, Before, Group, After).
tr_group_from0(Side, Words, Before, Group, After) :-
    tr_split_prev(Words, none, Before, Rest, Prev),
    \+ tr_named_there(Side, Before, Rest),
    \+ tr_article_before(Side, Before),
    tr_group_at(Side, Rest, Group, After),
    %% (asked where a group DOES start, which few places are: asked of every
    %% place it cost the Solana report's tenth sentence 58 000 inferences)
    \+ tr_all_before(Side, Prev, Rest).

%% the places, in the order append/3 gives them, each with the word before it
%% (or none): the rule below asks for that word at every place, and last/2
%% walked the words before it to find it -- a walk as long as the words at
%% each of them
tr_split_prev(Ws, Prev, [], Ws, Prev).
tr_split_prev([W|Ws], _, [W|B], R, P) :- tr_split_prev(Ws, W, B, R, P).

%% ... AND A WORD THAT MEANS `all' IS FOLLOWED BY THE PHRASE IT BELONGS TO:
%% `Toda una proeza' -- quite a feat -- read `toda' as the pronoun
%% `everything' and `una' as what `unir' says in the subjunctive, and the
%% heading was a clause, `everything joins exploit'. A word the lesson calls
%% a determiner, right after one that means `all', begins no verb group
%% (all/2, 1.8.8).
tr_all_before(Side, w(T, _), [D|_]) :-
    atom(T), tr_all_word(Side, T), tr_determiner(Side, D, _, _), !.

%% A PREPOSITION AND ITS ARTICLE ARE FOLLOWED BY THE ARTICLE'S NOUN, NEVER BY
%% A VERB: `Auto proibite nelle isole del sole' read `isole' as what
%% `isolare' says to one person, after `in le', and the headline came out as
%% a clause about isolating. An article with no preposition before it may
%% still be a pronoun before its verb (`la mangia').
tr_article_before(Side, Before) :-
    append(_, [P, D], Before), P = w(_, _), D = w(_, _),
    tr_is(Side, P, preposition), tr_determiner(Side, D, _, article), !.

%% A WORD WITH ITS CAPITAL INSIDE A SENTENCE IS A NAME, NOT A VERB: `Grazie
%% all'Arma dei carabinieri' -- `arma' is also `he arms', and a verb
%% there shut out the one reading the sentence has, which has none. The
%% head of a sentence was lowered when the lesson knows it (tr_head_lower/3),
%% so what still has its capital past the head was written with one --
%% and that is true of the head of any PART of a sentence too: the fronted
%% reading reads `Arma dei carabinieri' as a statement of its own, where
%% the capital is the only sign left.
tr_named_there(foreign, _, [w(_, upper)|_]) :- !.

%% the verb group: at the first place one starts, the words before it and after it
tr_group(Side, Words, Before, Group, GroupWords, After) :-
    append(Before, Rest, Words),
    tr_group_at(Side, Rest, Group, After), !,
    append(GroupWords, After, Rest).

%% English: `will' and a base form, or `be' and a gerund; `would' and a
%% base form; `has', `have' or `had' and a participle; `does', `do' or
%% `did' and a base form; a modal the lesson gives a word for, in its
%% tense; a copula and a gerund; a copula; a verb form
tr_group_at(english, [w(will, _), w(be, _), w(G, _)|R], g(L, future, progressive, third, singular), R) :- en_gerund(G, L), !.
tr_group_at(english, [w(will, _), w(B, _)|R], g(L, future, simple, third, singular), R) :- en_verb_form(B, L, present), !.
tr_group_at(english, [w(would, _), w(B, _)|R], g(L, conditional, simple, third, singular), R) :- en_verb_form(B, L, present), !.
%% ENGLISH'S PASSIVE PERFECT GOES ABOVE ITS PERFECT, for the reason the
%% lesson's own does: `been' is the participle of `is', so `has been
%% evacuated' read as a perfect is `has been' with `evacuated' left over and
%% the sentence refused. Measured before this clause moved -- `The house has
%% been evacuated.' and `The house had been evacuated.' were both refused on
%% the English side while the WRITER produced exactly those words, so a
%% passive perfect could not round-trip through English at all.
%%
%% It is safe by what it requires: the middle word must be `been', so `has
%% eaten the bread' matches nothing here and falls through as before.
tr_group_at(english, [w(H, _), w(been, _), w(P, _)|R], g(L, T, passive_perfect, third, singular), R) :-
    memberchk(H, [has, have, had]), en_passive_participle(P, L), !, ( H == had -> T = past ; T = present ).
tr_group_at(english, [w(H, _), w(P, _)|R], g(L, T, perfect, third, singular), R) :-
    memberchk(H, [has, have, had]), en_participle(P, L), !, ( H == had -> T = past ; T = present ).
tr_group_at(english, [w(D, _), w(B, _)|R], g(L, T, simple, third, singular), R) :-
    memberchk(D, [does, do, did]), en_verb_form(B, L, present), !, ( D == did -> T = past ; T = present ).
tr_group_at(english, [w(M, _)|R], g(L, T, simple, third, singular), R) :-
    en_modal_form(M, L, T), tr_known(english, L), tr_class(english, L, modal), !.
tr_group_at(english, [w(C, _), w(G, _)|R], g(L, T, progressive, P, N), R) :- en_copula(C, P, N, T), en_gerund(G, L), !.
%% English's passive: `is considered', `was thrown'. It
%% is tried BEFORE the plain copula, or `is considered' would read as the
%% copula with an adjective after it -- and it is refused for a word the
%% lesson also calls an ADJECTIVE, which is what keeps `She is licensed' the
%% adjective sentence it was. The PERFECT passive, `has been thrown', is
%% above with the perfect it has to beat.
tr_group_at(english, [w(C, _), w(P, _)|R], g(L, T, passive, Per, N), R) :-
    en_copula(C, Per, N, T), en_passive_participle(P, L), !.
tr_group_at(english, [w(C, _)|R], g(is, T, simple, P, N), R) :- en_copula(C, P, N, T), !.
tr_group_at(english, [w(V, _)|R], g(L, T, simple, third, singular), R) :- en_verb_form(V, L, T), !.
%% the lesson's language: the auxiliary that means `is' and a gerund, the
%% progressive; an auxiliary's form and a participle, the perfect; a
%% verb's or a modal's form
tr_group_at(foreign, [w(A, _), w(G, _)|R], g(L, T, progressive, Person, N), R) :-
    tr_form(A, AL, N, T, Person), tr_solve(auxiliary(AL)), tr_solve(mean(AL, is)), tr_solve(gerund_of(G, L)), tr_known(foreign, L), !.
%% THE PASSIVE: the copula and a participle (`e considerata'), and the
%% PERFECT passive with the copula's own participle between them (`e stato
%% gettato', `ha sido evacuada'). The three-word reading is tried FIRST --
%% before the perfect just below and before the two-word passive -- or its
%% middle word would be taken for the verb: `ha sido evacuada' read as a
%% perfect is `has been' with `evacuada' left over, which is how Spanish's
%% own passive perfect was refused outright until 1.6.8.
%%
%% AND WHICH WORD CARRIES THE TENSE IS THE LESSON'S, NOT THIS CODE'S.
%% Italian builds the copula's perfect with the copula (`e stata evacuata')
%% and Spanish with the auxiliary (`ha sido evacuada'), and nothing else in
%% a lesson tells them apart -- so the lesson says it, in the shape
%% `"los" is the plural of "el"' already has: `"ha" is the auxiliary of
%% "es".' The copula itself is the default, so a lesson that says nothing
%% writes what it wrote before.
tr_group_at(foreign, [w(C, _), w(B, _), w(P, _)|R], g(L, T, passive_perfect, Person, N), R) :-
    tr_form(C, CL, N, T, Person),
    tr_solve(participle_of(B, BL)), tr_copula_lexeme(BL), tr_perfect_auxiliary(BL, CL),
    tr_solve(participle_of(P, L)), tr_known(foreign, L), tr_participle_agrees(P, N), !.
%% ... AND AN ADVERB MAY STAND INSIDE IT, before the verb's participle: `non
%% sono state ANCORA accertate'. The two-word passive below then took `sono
%% state' for the passive of `stare' -- `stata' is the participle of `stare'
%% as well as of the copula, and the store answers `stare' first -- and read
%% `accertate' as a participle predicated of the subject, which is `are not
%% stood, even verified'. The adverbs go back at the head of what follows,
%% where the complement reader reads any adverb after the verb.
%% The participle's number chooses among the copula's readings, as it does
%% in the clause above: `sono' is I am before it is they are, and cut on
%% the first `I generali non sono stati ancora accertati' had a first
%% person no phrase agrees with, and read only once the adverb was lifted.
tr_group_at(foreign, [w(C, _), w(B, _)|R0], g(L, T, passive_perfect, Person, N), R) :-
    tr_adverb_prefix(R0, Advs, [w(P, _)|R1]), Advs \== [],
    tr_form(C, CL, N, T, Person),
    tr_solve(participle_of(B, BL)), tr_copula_lexeme(BL), tr_perfect_auxiliary(BL, CL),
    tr_solve(participle_of(P, L)), tr_known(foreign, L), tr_participle_agrees(P, N), !,
    append(Advs, R1, R).
%% -- an auxiliary that means HAS: the one that means `is' is the
%% progressive's and the state's (`está comiendo', `está considerado'), and
%% `Su constructor está considerado como el Van Gogh' came out `has
%% considered'
tr_group_at(foreign, [w(A, _), w(P, _)|R], g(L, T, perfect, Person, N), R) :-
    tr_form(A, AL, N, T, Person0), tr_solve(auxiliary(AL)), \+ tr_solve(mean(AL, is)),
    tr_solve(participle_of(P, L)), tr_known(foreign, L), !,
    tr_group_person(A, N, T, Person0, Person).
%% ... AND AN ADVERB MAY STAND BETWEEN THE AUXILIARY AND THE PARTICIPLE OF
%% ANY OF THEM: `è SEMPRE risultato spento', `si era QUINDI temuto il
%% peggio', `abbiamo POI ritrovato la mamma'. Without this the copula alone
%% was the group and the participle a bare predicate after it, which is how
%% `Se era entonces temido lo peor' came out. The group is read with the
%% adverbs taken out and they go back at the head of what follows, as the
%% passive perfect's do above.
tr_group_at(foreign, [w(C, CC)|R0], G, R) :-
    tr_adverb_prefix(R0, Advs, [w(P, PC)|R1]), Advs \== [],
    tr_solve(participle_of(P, _)),
    tr_group_at(foreign, [w(C, CC), w(P, PC)|R1], G, R2),
    G = g(_, _, A, _, _), memberchk(A, [perfect, passive, duty]), !,
    append(Advs, R2, R).
%% A VERB THE LESSON SAYS BUILDS ITS PERFECT WITH THE COPULA IS READ AS THAT
%% PERFECT: `"è" is the auxiliary of "risulta".' makes `è risultato spento'
%% has turned out off, and `sono caduti', `sono proseguite' has fallen, has
%% gone on -- where the passive just below read the same two words as `is
%% resulted', and the Spanish came out `es resultado'. The writer has used
%% the same line since 1.6.15 to write `è riuscito'; this is its reading. It
%% goes before the passive because it is the narrower of the two: only a
%% verb the lesson names.
%% The copula's OWN perfect is the same shape: `sono stati eroici' has been,
%% where the lesson names no other word for it (tr_perfect_auxiliary/2).
tr_group_at(foreign, [w(C, _), w(P, _)|R], g(L, T, perfect, Person, N), R) :-
    tr_form(C, CL, N, T, Person0), tr_copula_lexeme(CL),
    tr_solve(participle_of(P, L)),
    ( tr_solve(auxiliary_of(CL, L)) -> true ; tr_copula_lexeme(L), tr_perfect_auxiliary(L, CL) ),
    tr_known(foreign, L), tr_participle_agrees(P, N), !,
    tr_group_person(C, N, T, Person0, Person).
%% WHAT TELLS A PASSIVE FROM A PERFECT IS THE LESSON, not this code. Italian
%% builds the perfect of some verbs with `essere' too -- `e riuscito' is `has
%% succeeded', not `is succeeded' -- and nothing in a lesson says which verbs
%% those are. The rule above fires only for a word the lesson calls an
%% auxiliary, so `ha' takes the perfect and `e' falls through to here; a
%% lesson that called its copula an auxiliary would get the other reading.
%% The cost is stated rather than hidden: an intransitive perfect built with
%% the copula reads as a passive.
%% A VERB THE LESSON SAYS MARKS THE PASSIVE BUILDS ONE WITH A PARTICIPLE:
%% `Viene esclusa ogni forma di eutanasia diretta' is `is excluded', and
%% Italian says it with `venire' as readily as with the copula. Read as the
%% verb it also is, it came out `comes excluded'. `The verb "viene" marks
%% the passive.' is the line, the shape `The auxiliary "está" marks the
%% state.' already has, so reason.pl did not move; a language that says
%% nothing keeps its copula's passive alone.
%% ... AND ONE THAT MARKS THE DUTY SAYS WHAT MUST BE DONE: `Vanno invece
%% attivate la terapia palliativa e la terapia del dolore' is `must be
%% activated', `andare' and a participle. The group is duty(L); the
%% statement reader writes it out as the modal, the copula's infinitive and
%% the participle (tr_duty_fix/2), which is what English's `must be
%% activated' reads as, so every writer already has it.
tr_group_at(foreign, [w(V, _), w(P, _)|R], g(L, T, A, Person, N), R) :-
    tr_form(V, VL, N, T, Person), tr_solve(mark(VL, M)), memberchk(M-A, [passive-passive, duty-duty]),
    tr_solve(participle_of(P, L)), tr_known(foreign, L), tr_participle_agrees(P, N), !.
%% ... and the copula of a STATE with a participle is a passive too: Spanish
%% says what a thing is held to be with `estar', `está considerado como el
%% Van Gogh de la luthiere', and Italian and English with the copula
tr_group_at(foreign, [w(C, _), w(P, _)|R], g(L, T, passive, Person, N), R) :-
    tr_form(C, CL, N, T, Person), ( tr_copula_lexeme(CL) -> true ; tr_state_lexeme(CL) ),
    tr_solve(participle_of(P, L)), tr_known(foreign, L), tr_participle_agrees(P, N), !.
%% -- and NOT cut on the first reading: `sono' is the first person of `è'
%% and the plural of it, and which one it is in `Le case sono grandi' the
%% subject decides, so the statement reader backtracks into the next
tr_group_at(foreign, [w(V, _)|R], g(L, T, simple, Person, N), R) :-
    tr_form(V, L, N, T, Person), tr_verb_lexeme(L).
%% ... AND A PRESENT SUBJUNCTIVE'S FIRST PERSON IS SPELLED AS ITS THIRD in the
%% perfect too (tr_form0/5): `Il capo che io abbia visto', `credo che io sia
%% stato felice' -- the group read for the third, the cut taken, and the
%% subject `io' had no group to agree with, so the sentence was refused with
%% every word known. The first person is the second reading of the group,
%% after the third and only where the sentence names the first person
tr_group_person(A, N, T, Person0, Person) :-
    (   Person = Person0
    ;   Person0 == third, N == singular, T == present, tr_global('$tr_first', yes),
        tr_solve(subjunctive_of(A, _)), \+ tr_holds(past(A)), Person = first
    ).

%% a verb of the lesson's, or a modal
tr_verb_lexeme(L) :- ( tr_class_of(L, verb) -> true ; tr_class_of(L, modal) ).

%% A PARTICIPLE AFTER THE COPULA AGREES WITH THE SUBJECT, SO IT SAYS THE
%% NUMBER the copula's form may not: `sono' is the first person singular and
%% the third plural, and `si sono mossi', `sono caduti', `sono stati eroici'
%% came out `me he movido', `he caído', `soy sido' until the plural
%% participle was allowed to decide. A participle the lesson states as the
%% plural of another is plural; any other is singular. A language whose
%% participle does not agree -- Spanish's `sido' is one form -- states no
%% plural for it, and every number passes.
tr_participle_agrees(P, N) :-
    (   tr_solve(plural_of(P, S)), tr_solve(participle_of(S, _)) -> N == plural
    ;   tr_solve(plural_of(_, P)) -> N == singular
    ;   true
    ), !.

%% the copula's lexeme: the verb the lesson gives for `is', never an
%% auxiliary it named for the perfect or the progressive
tr_copula_lexeme(L) :- tr_solve(mean(L, is)), tr_class_of(L, verb), \+ tr_solve(auxiliary(L)), !.

%% a piece that opens on the copula in the third person singular, a denial
%% before it allowed
tr_copula_head(Ws0) :-
    ( Ws0 = [w(N, _)|Ws], atom(N), tr_negation_word(N) -> true ; Ws = Ws0 ),
    Ws = [w(C, _)|_], atom(C), tr_form(C, CL, singular, _, third), tr_copula_lexeme(CL), !.

%% the adverbs at the head of a run of words, the longest run first
tr_adverb_prefix([A|Ws], [A|As], Rest) :- tr_is(foreign, A, adverb), tr_adverb_prefix(Ws, As, Rest).
tr_adverb_prefix(Ws, [], Ws).

%% the word that builds the COPULA's own perfect: the one a lesson names
%% (`"ha" is the auxiliary of "es"'), and the copula itself where no lesson
%% says otherwise, which is Italian's `e stata'. The participle after it
%% agrees with whatever forms the lesson gives it to agree with -- four in
%% Italian, and in Spanish the one invariable `sido', which is the language
%% saying the same thing through its data.
tr_perfect_auxiliary(CL, Aux) :- tr_solve(auxiliary_of(A, CL)), !, Aux = A.
tr_perfect_auxiliary(CL, CL).

%% a participle that may head a passive: one of a verb the lesson gives, and
%% NOT a word it also calls an adjective
en_passive_participle(P, L) :- en_participle(P, L), \+ tr_class(english, P, adjective).

%% the subject: what was asked, a pronoun, a name, two joined, a phrase --
%% or, in the lesson's language, nobody, and then the pronoun the verb's
%% person and number say
%% (a relative word asked for as the subject keeps the verb's number:
%% tr_relative_clause/4 hands it to the gap)
tr_subject(_, subject(Q), [], P, N, asked(Q1)) :- !, ( Q == rel -> Q1 = rel(P, N) ; Q1 = Q ).
tr_subject(foreign, _, [], P, N, null(P, N)) :- !, ( P \== third ; N == plural ).
tr_subject(Side, _, [w(P, C)], _, _, pronoun(Person, Number, w(P, C))) :- tr_subject_pronoun(Side, P, Person, Number), !.
%% BEFORE the phrase below, on both sides: English's `one' is a number word
%% as well, and the lesson's word is a pronoun the phrase reader would take
%% for one
tr_subject(Side, _, [w(W, _)], _, _, impersonal) :- tr_impersonal(Side, W), !.
%% ... and not only one thing but another (nonly/3): `Non solo il cane ma
%% anche il gatto dorme' -- the verb agrees with the second half, the nearer
tr_subject(foreign, _, [w(N, _), O|Ws], third, Num, nonly(A, B, Also)) :-
    atom(N), tr_negation_word(N), tr_nonly_parts(O, Ws, A, B, Also0, []),
    tr_nonly_number(A, B, Also0, Num, Also), !.
%% (the cut after BOTH halves read: `la storia della scomparsa E del
%% ritrovamento' splits, the second half is no subject, and a cut at the
%% split shut out the one subject the sentence has)
%% -- and never a bare noun after a first half with a preposition in it:
%% `la demanda de las familias en productos de ocio y entretenimiento' is
%% one demand, for leisure and entertainment, and split there the subject
%% was two things against a verb that says one, the cut shut out the
%% reading below, and the sentence was divided at the `y' instead
%% ... AND TWO NOUNS UNDER ONE ARTICLE WITH A SINGULAR VERB ARE ONE PERSON:
%% `el actual presidente y ex ministro ... Eduard Shevardnadze' is one man,
%% and read as two the verb that says one came out plural in Italian,
%% `votarono'. The second noun has no determiner of its own; the term is
%% one/1, which every writer takes for the singular the source said.
%% ... AND `and' AFTER A PREPOSITION WITH A SINGULAR VERB JOINS INSIDE THE
%% PREPOSITION'S PHRASE: `La final de copa entre Inglaterra y Alemania ha
%% tenido' is one final, between the two, and split at the `y' it was the
%% final AND Germany against a verb that says one -- Italian wrote `hanno
%% avuto'. The halves of a split are read with `singular' as a marker and
%% not as a verb's number, so they carry `half' and the guard leaves them.
%% BOTH ... AND AS A SUBJECT: `tanto él como los actuales miembros de la
%% junta directiva ... están "sufriendo"' -- both he and the members. The
%% pair the complements read (both/2) opens the subject too, and its halves
%% are read as a coordinated subject's are; it travels as co(both, S1, S2)
%% and every writer gives its own pair round them, `tanto lui quanto gli
%% attuali membri', `both he and the current members'
tr_subject(Side, _, [w(B, _)|Ws], _, N, co(both, S1, S2)) :-
    atom(B), N \== singular, tr_both_word(Side, B, P),
    append(W1, [w(P, _)|W2], Ws), W1 \== [], W2 \== [],
    tr_subject(Side, half, W1, third, singular, S1), tr_subject(Side, half, W2, third, singular, S2), !.
tr_subject(Side, A, Words, _, N, Subject) :-
    tr_conjunction_split(Side, Words, W1, C, W2),
    \+ ( member(P1, W1), tr_is(Side, P1, preposition), \+ tr_phrase_marked(Side, W2),
         \+ ( tr_bare_plural_start(Side, W1), tr_bare_plural_start(Side, W2) ) ),
    \+ ( A \== half, N == singular, C = w(CW, _), tr_and_word(Side, CW), member(P2, W1), tr_is(Side, P2, preposition) ),
    %% -- NOR BETWEEN TWO WORDS SAID OF ONE NOUN: `la hermosa y joven Senegal
    %% le concedió' is one country, beautiful and young, and divided the
    %% first half was the article with its noun left out, `the beautiful
    %% one', and the verb had two subjects. Refused where the whole reads as
    %% one phrase with the coordinator among its adjectives -- asked after
    %% both halves read, where the division would be taken: before them it
    %% read the whole as a phrase at every `y' of every subject the reader
    %% tried, `Matutes evitó dar un respaldo claro y anticipado a Solana y
    %% sólo señaló ...' among them, 0.14 million inferences over seven
    %% Spanish sentences for halves that never read
    tr_subject(Side, half, W1, third, singular, S10), tr_subject(Side, half, W2, third, singular, S2),
    \+ ( last(W1, L1), W2 = [F2|_], tr_said_of_noun(Side, L1), tr_said_of_noun(Side, F2),
         tr_np(Side, Words, np(_, _, Adjs, Noun, _)), Noun \= elided(_), memberchk(C, Adjs) ), !,
    tr_set_off_rc(Side, W1, C, S10, S1),
    (   N == singular, tr_determined(S1), tr_undetermined(S2)
    ->  Subject = one(co(C, S1, S2))
    ;   Subject = co(C, S1, S2)
    ).
%% A LIST THAT BEGINS WITH ITS OWN CONNECTOR: `no figuran ni Rivaldo ni
%% Overmars ni De la Peña'. The first `ni' joins nothing -- it says the
%% list is a denial from its first word -- so the list is read without it
%% and the IR keeps it as nei/1, which every writer gives its first word
%% back: `né Rivaldo né Overmars né De la Peña', `neither ... nor ...'.
tr_subject(foreign, _, [w(C, _)|Words], _, _, nei(co(W, S1, S2))) :-
    tr_neither_word(C),
    tr_conjunction_split(foreign, Words, W1, W, W2), W = w(C2, _), C2 == C,
    tr_subject(foreign, half, W1, third, singular, S1), tr_subject(foreign, half, W2, third, singular, S2), !.
%% A WORD THAT BEGINS THE RELATIVE IS A SUBJECT WITH ITS CLAUSE: `Chi ruba miliardi
%% si vede concedere la libertà provvisoria' -- whoever steals billions is
%% granted release. As an object, or after a preposition, it is the phrase a
%% noun replacer opens (tr_complements0/4, ell/4: `the one that'); as a subject
%% it stood before a verb with no clause of its own, and the piece was refused.
%% The clause follows at once with its verb, the gap its subject. Third person
%% singular, as the verb of the sentence will be.
tr_subject(foreign, _, [w(W, _)|Ws], third, singular, ell(det(article, A, w(A, lower)), masculine, singular, rel(subject, S))) :-
    Ws = [_|_], atom(W), tr_lexeme(foreign, W, L, _), tr_solve(begin(L, relative)),
    tr_gap_verb_next(foreign, Ws),
    once(( tr_solve(relative(R)), tr_solve(mean(R, that)) )),
    once(( tr_solve(mean(A, the)), tr_solve(article(A)), \+ tr_holds(feminine(A)), \+ tr_solve(plural_of(A, _)) )),
    tr_relative_clause(foreign, [w(R, lower)|Ws], subject, S), !.
%% AN INFINITIVE AND WHAT IT TAKES ARE A SUBJECT: `essere presidente di
%% questa società è la cosa più difficile del mondo', `parlare con Diego era
%% come parlare con due persone diverse'. What is done is the subject, and
%% the verb after it is in the third person singular. infs(Lexeme,
%% Complements) is the term: English writes `to' and the base form, the
%% lesson's language its infinitive, each with the complements after it.
%% -- AND A QUOTATION THAT OPENS ON THE INFINITIVE KEEPS ITS MARK: `sostuvo
%% que "cometer perjurio no es aceptable"' lost the opening one, because
%% infs/2 carries a lexeme and no case; infs/3 carries the mark as well
tr_subject(foreign, _, [w(V, VC)|Ws], third, singular, Subj) :-
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    tr_complements(foreign, Ws, no, Cs), !,
    ( memberchk(VC, [qopen, qboth]) -> Subj = infs(F, Cs, VC) ; Subj = infs(F, Cs) ).
%% ... AND WITH ITS REFLEXIVE JOINED: `dove iscriversi costava per i più
%% ricchi oltre due milioni' is where enrolling cost the richest more than
%% two million. The `si' cut off the infinitive (tr_enclitics/3) was left
%% over, and no complement reads a pronoun alone: the reflexive is the
%% verb's, infs(reflexive(Lexeme), Complements), as it is in pinf/2
tr_subject(foreign, _, [w(V, _), w(Cl, enclitic)|Ws], third, singular, infs(reflexive(F), Cs)) :-
    tr_reflexive_word(Cl), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    tr_complements(foreign, Ws, no, Cs), !.
%% ... AND WITH ANOTHER PRONOUN JOINED: `discuterne ... è bene' is
%% discussing them is good -- the pronoun is the infinitive's, as it is in
%% pinf/2, infs(cl(Lexeme, Pronouns), Complements); read with nothing to
%% take it, the sentence was refused
%% (and the same pronoun said again after it is that pronoun once:
%% `discuterne ne è bene', the treebank's own text, as `correggetemi mi' is
%% -- tr_repeated_clitic/3)
tr_subject(foreign, _, [w(V, _), w(Cl, enclitic)|Ws0], third, singular, infs(cl(F, Cls), Cs)) :-
    \+ tr_reflexive_word(Cl), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    ( Ws0 = [w(Cl2, enclitic)|Ws1] -> Cls = [w(Cl, lower), w(Cl2, lower)] ; Cls = [w(Cl, lower)], Ws1 = Ws0 ),
    tr_repeated_clitic(Cls, Ws1, Ws),
    tr_complements(foreign, Ws, no, Cs), !.
%% THE WORD FOR `even', `also' OR `only' BEFORE THE SUBJECT IS SAID OF IT:
%% `Anche Gianni Letta ha parlato', `Persino Gianni Letta' -- as it is after
%% the verb (tr_subject_after/5). Read as the clause's adverb it was written
%% last, `Gianni Letta ha hablado también', and `se persino Gianni Letta, ...,
%% ha riferito di una discussione' put `incluso' after the discussion. It
%% travels as advp(Adverb, Subject), which every writer puts in front of it
%% (tr_focus_front/1: never a word that is a preposition too)
tr_subject(foreign, A, [W|Words], P, N, advp(W, Subject)) :-
    Words = [_|_], tr_focus_front(W),
    tr_subject(foreign, A, Words, P, N, Subject), Subject \= advp(_, _), !.
%% A GERUND AFTER A SUBJECT'S PHRASE SAYS WHAT ITS PEOPLE DO: `100 jóvenes de 18
%% a 25 años rivalizando hasta el último minuto por un título merecen una
%% audiencia digna de una Copa del Mundo' -- 100 young people who compete until
%% the last minute for a title. No reading had a phrase with a gerund after it,
%% and the sentence was refused. The gerund and what it takes are a relative
%% clause on the phrase (rc/3), present, which both languages write with a verb
%% of its own (`che rivaleggiano', `that compete'); the verb that follows is
%% the sentence's, so a subject is the only place the gerund is taken for the
%% phrase's (an object's, `ver a los niños jugando', is the verb's complement). The
%% sentence's gerunds are noted when it is read ($tr_ger), and the phrase before one is
%% twelve words at most and what the gerund takes ten: asked of every phrase the search tried,
%% the first cut cost the long sentences 5 % (a refusal of 476 million inferences rose 25 million)
tr_subject(foreign, A, Words, _, _, rc(Subj0, subject, s(none, gap(third, N), g(L, present, simple, no), Cs))) :-
    nb_getval('$tr_ger', Gs), Gs = [_|_],
    member(G, Gs), memberchk(w(G, _), Words),
    append(Core, [w(G, GC)|Rest], Words), Core = [_|_], length(Core, K), K =< 12, length(Rest, KR), KR =< 10,
    GC \== enclitic, \+ last(Core, comma),
    %% (a phrase has no verb of its own: `la intensidad de la pobreza está creciendo' is the progressive
    %% and `Mi si è stretto il cuore leggendo ...' a clause, the gerund no clause on a phrase)
    \+ ( member(w(V, _), Core), atom(V), tr_verb_form_word(V), \+ tr_participle_here(foreign, V, _) ),
    %% (and a noun, an adjective, a number or a name last: the phrase read for each place a gerund
    %% could follow was most of the cost)
    last(Core, LW), ( tr_is(foreign, LW, noun) ; tr_is(foreign, LW, adjective) ; tr_is(foreign, LW, number) ; LW = w(LWA, _), tr_name_word(foreign, w(LWA, upper)) ), !,
    tr_gerund_here(foreign, G, L), \+ tr_is(foreign, w(G, lower), noun),
    tr_subject(foreign, A, Core, third, _, Subj0), tr_phrase_subject(Subj0), tr_subject_number(Subj0, N),
    ( Rest == [] -> Cs = [] ; tr_complements(foreign, Rest, Cs) ), !.
tr_subject(Side, _, Words, _, _, Subject) :- tr_np(Side, Words, Subject), !.
%% a phrase and the prepositional phrases after it: `the dogs of Maria'
%% ... and whatever else a phrase carries that is no object and no clause:
%% `la storia a lieto fine DELLA scomparsa E DEL ritrovamento di una donna,
%% 36 anni, e due bambini (...), SPARITI IERI sul Monte Livata vicino
%% Subiaco (Roma) deve essere ancora completamente chiarita' -- the story,
%% with everything that says which story, is what must be cleared up
%% -- and the word the lesson puts before a person is a preposition there,
%% never the mark of an object: `La visita a Ceuta presenta ...' is the
%% visit to Ceuta, and read as `visits Ceuta' the subject was refused
%% -- AND NEVER AN ARTICLE ALONE BEFORE IT: `Los más destacados luthiers del
%% mundo' divided at `más', which is the preposition `plus' as well as the
%% comparative, and took `los' for the phrase -- the pronoun it also is --
%% so the subject was one thing against a plural verb and the cut after it
%% shut out the superlative the sentence is
%% A PRONOUN OF SOMEBODY OR NOBODY WITH ITS PHRASES IS A SUBJECT: `Por fin alguien con sensibilidad se ha preocupado de
%% que ...' is finally somebody with sensitivity, and the phrase reader reads no pronoun, so the subject was none. The
%% pronoun as an object is (`ve a alguien con sensibilidad'), with/2 and the phrases after it
tr_subject(foreign, _, [w(P, PC), Pr|Ws], third, singular, with(pronoun(w(P, PC)), PPs)) :-
    atom(P), tr_is(foreign, Pr, preposition), \+ tr_means_of(foreign, Pr),
    tr_lexeme(foreign, P, L, _), tr_class_of(L, pronoun),
    once(( tr_solve(mean(L, E)), memberchk(E, [somebody, someone, nobody, anybody, anyone, everybody, everyone]) )),
    tr_complements(foreign, [Pr|Ws], yes, PPs), PPs = [_|_], forall(member(X, PPs), X = pp(_, _)), !.
tr_subject(Side, _, Words, _, _, with(NP, PPs)) :-
    append(NPWords, [P|PPWords], Words), tr_is(Side, P, preposition), NPWords \== [],
    \+ ( NPWords = [D1], tr_determiner(Side, D1, _, _), \+ tr_standalone_det(Side, D1) ),   % `uno dei Paesi' does
    %% (nor a word that replaces the noun: `quelli senza alcun titolo di studio'
    %% is the phrase of tr_np/3's ell/4 and `di studio' the one after it, and
    %% with the head alone, `that' in the plural, no writer had a word)
    \+ ( NPWords = [Q1], tr_noun_replacer(Side, Q1) ),
    tr_np(Side, NPWords, NP0), tr_complements(Side, [P|PPWords], yes, PPs0),
    tr_noun_infinitive(Side, P, PPs0, PPs1),
    tr_title_appos(PPs1, PPs2),
    tr_subject_comps(PPs2),
    tr_participle_adjunct(NP0, PPs2, NP, PPs3),
    tr_inner_participle_adjunct(PPs3, PPs), !.

%% an adjective, or a participle that stands where one does
tr_said_of_noun(Side, W) :- W = w(X, _), atom(X),
    ( tr_is(Side, W, adjective) -> true ; Side == foreign, tr_pre_participles([W], _, []) ), !.

%% ... and a relative clause the source set off between two commas is the
%% first phrase's aside (nrc/3), which every writer closes with its comma:
%% `Carlos Herrera, que se expresó en catalán, y Margarida Lluch' -- read
%% with the subject's commas out, both were lost
tr_set_off_rc(Side, W1, C, rc(NP, Role, S), nrc(NP, Role, S)) :-
    append(Pre, [w(RW, RC)|_], W1), Pre \== [], atom(RW), tr_relative_word(Side, RW),
    tr_comma_before(Pre, w(RW, RC)), tr_comma_before(W1, C), !.
tr_set_off_rc(_, _, _, S, S).

%% ... AND ONE SET OFF AFTER A SUBJECT ALONE, the closing comma straight
%% before the verb: `Esta propuesta, que debería ser refrendada por los
%% miembros ..., se produce' -- read with the subject's commas out, both
%% were lost, `Questa proposta che dovrebbe esser confermata ... si produce'
tr_set_off_subject(Side, Before, SubjectWords, rc(NP, Role, S), nrc(NP, Role, S)) :-
    append(Pre, [comma|After], Before), Pre \== [], \+ memberchk(comma, Pre),
    tr_relative_start(Side, After),                      % `, que', `, a quien'
    last(SubjectWords, LW), append(_, [LW, comma|Tail], Before), \+ memberchk(comma, Tail), !.
%% ... AND ONE ON THE SUBJECT'S LAST PHRASE OF `of': `La oficina del sheriff, que declinó hacer comentarios ...,
%% reconoció' keeps its commas, which the relative clause on the sheriff lost (`the office of the sheriff that
%% declined', the sheriff's restriction)
tr_set_off_subject(Side, Before, SubjectWords, with(H, PPs0), with(H, PPs)) :-
    append(PPs1, [pp(P, rc(NP, Role, S))], PPs0),
    append(Pre, [comma|After], Before), Pre \== [], \+ memberchk(comma, Pre),
    tr_relative_start(Side, After),
    last(SubjectWords, LW), append(_, [LW, comma|Tail], Before), \+ memberchk(comma, Tail), !,
    append(PPs1, [pp(P, nrc(NP, Role, S))], PPs).
tr_set_off_subject(_, _, _, S, S).
%% ... AND ONE SET OFF AFTER TWO PHRASES JOINED HANGS ON BOTH, its relative word the subject: `el
%% Ayuntamiento de Salou y la policía, que conocían las amenazas, debían haber avisado a la población' is the
%% council and the police, who knew of the threats -- the plural clause disagrees with `la policía', and read
%% as the police's object relative (tr_rc_role/7's last reading) the threats knew the police. Only where the
%% phrase after the verb names no doer, which would be the subject (`el perro y la casa, que compraron los
%% niños,'), and where its number is the plural one the last phrase lacks
tr_coord_rc_fix(foreign, Before, co(J, A, rc(B, object, s(T, Su, G, Cs0))),
                nrc(co(J, A, B), subject, s(T, gap(third, plural), G, [obj(Su)|Cs]))) :-
    append(_, [comma|After], Before), tr_relative_start(foreign, After),
    select(subj_here, Cs0, Cs), \+ tr_doer_np(Su),
    tr_head_number(foreign, B, singular), tr_head_number(foreign, Su, plural), !.
%% ... AND ONE AFTER THE PHRASES OF `of' OF A PLURAL HEAD, ITS VERB IN THE PLURAL, HANGS ON THE HEAD: `Los artificieros
%% de la Guardia Civil y del Ejército que han peinado las playas' are the experts who combed them -- hung on the
%% Army, a singular, the clause took the beaches for its subject, `the Army that the beaches have combed'
tr_coord_rc_fix(foreign, _, with(H, PPs0), rc(with(H, PPs), subject, s(T, gap(third, plural), G, [obj(Su)|Cs]))) :-
    append(PPs1, [pp(P, rc(B, object, s(T, Su, G, Cs0)))], PPs0),
    select(subj_here, Cs0, Cs), \+ tr_doer_np(Su),
    tr_head_number(foreign, H, plural), tr_head_number(foreign, B, singular), tr_with_number(Su, plural), !,
    append(PPs1, [pp(P, B)], PPs).
tr_coord_rc_fix(_, _, S, S).
%% (a phrase's number, its phrases of `of' aside: `las playas de Tarragona')
tr_with_number(with(NP, _), N) :- !, tr_head_number(foreign, NP, N).
tr_with_number(NP, N) :- tr_head_number(foreign, NP, N).

tr_determined(np(det(_, _, _), _, _, _, _)) :- !.
tr_determined(with(NP, _)) :- tr_determined(NP).
tr_undetermined(np(none, none, _, w(_, _), singular)) :- !.
tr_undetermined(with(NP, _)) :- tr_undetermined(NP).

%% ... UNLESS BOTH HALVES OPEN ON A BARE PLURAL NOUN: `Voces de un ayer que
%% marcó época y estrellas de las ondas de hoy ... se reunieron' is voices
%% and stars side by side, and the parallel is what says so. Refused, the
%% stars were read inside the `de' phrase, and nothing read the sentence.
tr_bare_plural_start(Side, [W|_]) :-
    W = w(X, _), atom(X), \+ tr_phrase_marked(Side, [W]),
    tr_is(Side, W, noun), tr_lexeme(Side, X, _, plural), !.

%% a phrase that says it begins: a determiner, a number, a name or a pronoun
tr_phrase_marked(Side, [W|_]) :-
    (   tr_determiner(Side, W, _, _) ; tr_is(Side, W, number) ; W = w(_, upper)
    ;   W = w(X, _), ( tr_subject_pronoun(Side, X, _, _) ; tr_object_pronoun(Side, X, _) )
    ), !.

%% A PHRASE THAT IS NOT `OF' AFTER A PARTICIPLE WITH NO ADJUNCT OF ITS OWN IS
%% THE PARTICIPLE'S: `Il comunicato diramato dopo quasi tre ore di discussione
%% ... contiene' is the statement issued after almost three hours. Taken for
%% the noun's, English wrote the participle in front of it, `The issued
%% communique after almost three hours', which says the hours came after the
%% statement was issued only by a reader's good will.
tr_participle_adjunct(rel(N, L, []), [pp(P, X)|More], rel(N, L, [pp(P, X)]), More) :-
    P = w(PW, _), atom(PW), \+ tr_means_of(foreign, P), !.
%% (and one of `of' after a participle English writes with it, tr_of_participle/2:
%% `un tesoro fatto di piombo')
tr_participle_adjunct(rel(N, L, []), [pp(P, X)|More], rel(N, L, [pp(P, gov(L, X))]), More) :-
    tr_means_of(foreign, P), atom(L), tr_lexeme_across(L, english, E), en_of_participle(E), !.
tr_participle_adjunct(NP, PPs, NP, PPs).
%% ... AND SO IS ONE AFTER A PARTICIPLE IN THE SUBJECT'S PHRASE OF `of', with the phrases of `of' after it:
%% `Algunos habitantes de las localidades incluidas en la campaña de amenazas' are inhabitants of the localities
%% included in the campaign of threats, and with the campaign the inhabitants' English wrote `the included
%% localities in the campaign of threats'
tr_inner_participle_adjunct([pp(Q, rel(N, L, [])), pp(P, X)|More0], [pp(Q, rel(N, L, [pp(P, X)|Ofs]))|More]) :-
    tr_means_of(foreign, Q), P = w(PW, _), atom(PW), \+ tr_means_of(foreign, P), !,
    tr_of_run_split(More0, Ofs, More).
tr_inner_participle_adjunct(PPs, PPs).
tr_of_run_split([pp(P, X)|Cs0], [pp(P, X)|Ofs], Cs) :- tr_means_of(foreign, P), !, tr_of_run_split(Cs0, Ofs, Cs).
tr_of_run_split(Cs, [], Cs).

%% A `di' AND AN INFINITIVE WITH ITS PRONOUNS AFTER A SUBJECT'S NOUN ARE THE
%% NOUN'S: `è venuto il momento di porsi la stessa domanda' is the time to
%% ask oneself the question. The lesson says `di' begins the infinitive,
%% which makes it the verb's after a verb (infx/3 alone), and a subject has
%% no verb to give it to -- read that way the subject was refused and the
%% moment became the time the verb happened at. The preposition travels as
%% nprep/1, which the lesson's writer spells (`el momento de plantearse').
tr_noun_infinitive(foreign, P, [infx(F, A, Cls)|Cs], [nprep(P), infx(F, A, Cls)|Cs]) :-
    P = w(PW, _), tr_means_of(PW), !.
tr_noun_infinitive(_, _, Cs, Cs).

%% A TITLE AND ITS NAME AFTER THE PHRASE ARE ITS APPOSITION: `l'arcivescovo
%% di Monreale monsignor Salvatore Cassisa' is one person, and the phrase
%% after the `di' phrase is no object -- a subject has none
tr_title_appos([], []).
tr_title_appos([obj(NP)|Xs], [appos(NP)|Ys]) :- tr_title_np(NP), !, tr_title_appos(Xs, Ys).
tr_title_appos([X|Xs], [X|Ys]) :- tr_title_appos(Xs, Ys).

tr_title_np(np(none, none, [w(_, upper)], w(TW, _), singular)) :- tr_title_word(foreign, TW), !.
tr_title_np(np(none, none, [w(_, upper)], w(TW, _), singular)) :- tr_title_word(english, TW).

tr_title_word(foreign, W) :- tr_lexeme(foreign, W, L, _), tr_solve(title(L)), !.
tr_title_word(english, W) :- tr_solve(mean(F, W)), tr_solve(title(F)), !.

%% ... an infinitive among them with its own object: `Esta obsesión por
%% eliminar cualquier signo de relajación le ha llevado ...' is an obsession
%% with getting rid of every sign of it
%% -- and a PURPOSE with its object: `la insistencia de los republicanos en
%% buscar otros cargos PARA FORTALECER EL PROCESO contra Lewinsky' is one
%% phrase, the insistence, and with the purpose refused there it had none
tr_subject_comps([]).
tr_subject_comps([pinf(_, _), obj(_)|Xs]) :- !, tr_subject_comps(Xs).
tr_subject_comps([nprep(_), infx(_, _, _), obj(_)|Xs]) :- !, tr_subject_comps(Xs).
tr_subject_comps([nprep(_), infx(_, _, _)|Xs]) :- !, tr_subject_comps(Xs).
tr_subject_comps([purpose(_), obj(_)|Xs]) :- !, tr_subject_comps(Xs).
%% ... and the `to' and a DENIED infinitive of the phrase: `gli unici a non
%% credervi erano stati solo Leucippo e Democrito' is the only ones not to
%% believe it, and with the infinitive refused there the subject was refused
%% with it. A denied one is the preposition and the denied infinitive,
%% nprep/1 and neg/1 (tr_complements0/4). Not denied, `a' and an infinitive
%% (ainf/2) is left as it was: allowed in every subject, it made Livata's
%% `era in pista a sciare' a subject the reader went on with, 10.6 million
%% inferences of a sentence that cost 11 without it, and no sentence of the
%% article has it
tr_subject_comps([nprep(_), neg(I)|Xs]) :- ( I = inf(_) ; I = infx(_, _, _) ), !, tr_subject_comps(Xs).
tr_subject_comps([X|Xs]) :- tr_subject_comp(X), tr_subject_comps(Xs).

tr_subject_comp(pp(_, _)).
tr_subject_comp(appos(_)).
tr_subject_comp(pinf(_, _)).
tr_subject_comp(purpose(_)).
tr_subject_comp(npurpose(_)).
tr_subject_comp(purp(_)).
tr_subject_comp(cnj(_)).
tr_subject_comp(pred(_)).
tr_subject_comp(predq(_, _)).
tr_subject_comp(adv(_)).
tr_subject_comp(sep).
tr_subject_comp(paren(_)).
tr_subject_comp(at_time(_)).

%% `Maria and Omar', `the bread and the egg': two phrases, each with a
%% noun, a name or a pronoun of its own
%% THE CONJUNCTION IS KEPT, which it was not: every phrase joined by one
%% travelled as and/2, so `el caldo o la sopa' came out `il brodo e la
%% minestra' -- a different claim. co(Conjunction, A, B) carries the word
%% the text joined them with, it crosses by its meaning like a connector
%% between clauses, and each writer puts the target's word for it back.
tr_conjunction_split(Side, Words, W1, W2) :- tr_conjunction_split(Side, Words, W1, _, W2).
tr_conjunction_split(Side, Words, W1, w(C, CC), W2) :-
    append(W1, [w(C, CC)|W2], Words), CC \== acomma, tr_coord(Side, w(C, lower)), W1 \== [], W2 \== [],
    \+ ( W2 = [P0|_], tr_is(Side, P0, preposition) ),         % `e DEL ritrovamento' joins two phrases' prepositions
    %% nor between the two numbers of a count whose adverb stands before the
    %% first: `unos 5.000 o 6.000 millones' is about five or six thousand
    %% million, one phrase (tr_np/3's adv_num/2 over nums/3) -- split at the
    %% `o' the first half was `unos 5.000' and `unos' its article, `dei 5.000
    %% o 6.000 milioni'
    \+ tr_count_pair(Side, W1, W2),
    %% never inside a relative clause -- unless a comma closed the clause
    %% before the coordinator: `Carlos Herrera, que se expresó en catalán, y
    %% Margarida Lluch presentaron el acto' is two people, and read with the
    %% clause running on it said Herrera spoke in Catalan and Margarida Lluch
    %% -- AND A LIST'S OWN COMMA CLOSES IT AS WELL, between two items that open
    %% on a bare plural noun: `políticos de ese centro que se disputan desde
    %% todas direcciones, deportistas y artistas se reunieron' -- the clause
    %% ends at the comma, and running on it made the sportsmen and the
    %% artists part of the directions. Only there: `la procura che vuole il
    %% pane, il gatto e il cane' is what the office wants, and closed at the
    %% comma the cleft around it was refused
    \+ ( member(w(R, _), W1), tr_relative_word(Side, R), \+ tr_comma_before(W1, w(C, CC)),
         \+ ( CC == lcomma, tr_bare_plural_start(Side, W1), tr_bare_plural_start(Side, W2) ),
         \+ tr_closed_relative(Side, W1) ),
    %% nor before a run of ADJECTIVES with nothing to head them: `la violencia
    %% gratuita juvenil, anárquica o xenófoba' is one violence, and split
    %% there `xenófoba' was a xenophobe and came out masculine
    %% -- a bracket after them says something of the whole phrase and heads
    %% nothing: `funzioni geografiche bensì simboliche (con Gerusalemme al
    %% centro)' split at `bensì', and the symbolic ones came out masculine
    %% -- a run goes on from an ADJECTIVE: `los comerciantes y vecinos' is two
    %% nouns, `vecinos' being an adjective too, and after a noun the guard
    %% left the whole phrase unread
    %% -- and a RELATIVE CLAUSE after them is the whole phrase's: `un tema delicato ma importantissimo sul quale aveva
    %% assunto una posizione' is a delicate but most important topic on which he had taken one, and split at `ma'
    %% the clause hung on `importante', a person, `pero a importante en el que'
    \+ ( W1 = [_, _|_], last(W1, L0), tr_is(Side, L0, adjective),
         ( append(W2a, [R4|W2r], W2), W2a \== [], tr_relative_after(Side, [R4|W2r]) -> true ; W2a = W2 ),
         member(Y, W2a), tr_is(Side, Y, adjective),
         %% (an adverb among them too, which the tokeniser makes of a superlative: `molto importante')
         forall(member(X, W2a), ( tr_coord(Side, X) ; tr_is(Side, X, adjective) ; X = w(_, paren) ;
                                  W2a = [_, _|_], X = w(_, _), tr_is(Side, X, adverb) )) ),
    %% nor between two ADJECTIVES before one noun: `i loro assurdi e folli
    %% scopi' is their absurd and mad aims -- `assurdi' is also the noun
    %% `absurdities', and split there the aims were a second thing
    %% -- the noun last, or straight after the adjective with a relative clause
    %% after it: `le piccole e grandi manovre che preludono ...' split there
    %% was the small ones, and big manoeuvres that foreshadow
    %% -- and a determiner that is an adjective too, in the article's number:
    %% `il nuovo e diverso approccio' is the new and different approach, and
    %% split at `e' it was the new one and `several approach', whose verb
    %% then took the plural of two things
    %% -- and a NAME as the one they are said of: `la hermosa, joven y
    %% cautivadora Senegal' is one country, and split at `y' it was the
    %% beautiful one and a captivating Senegal, whose verb then took the plural
    \+ ( W1 = [D1|_], tr_determiner(Side, D1, _, _), last(W1, L1), tr_is(Side, L1, adjective),
         W2 = [A2|_], tr_is(Side, A2, adjective), ( \+ tr_determiner(Side, A2, _, _) ; tr_same_number(Side, D1, A2) ),
         ( last(W2, N2) ; W2 = [_, N2, w(R2, _)|_], tr_relative_word(Side, R2) ),
         ( tr_is(Side, N2, noun) ; N2 = w(_, upper), tr_name_word(Side, N2) ) ),
    %% nor before a PARTICIPLE with its agent, which joins the participle before
    %% it and divides no phrases: `il farmaco prescritto da Casotto e assunto da
    %% Rosi' is one drug, and split at `e' its second half had no noun for a
    %% name's agent (tr_reduced_agent/3's cpart/3)
    \+ ( Side == foreign, W2 = [w(P2, _), P3|_], atom(P2), tr_participle_here(foreign, P2, _),
         \+ tr_is(foreign, w(P2, lower), noun), tr_means_by(foreign, P3) ),
    %% nor at the first coordinator after the word for `among', which joins the two it takes: `Le differenze tra Nord e
    %% Sud sono limitate' are the differences between the North and the South, and split at `e' the South was a second
    %% subject beside the differences, whose participle took the masculine of the two (`limitados'). After a word of
    %% the phrase's own: words that open on the preposition are no phrase to split, and blocked there the split went on
    %% to the next coordinator, `Entre la Meridiana y la calle del Coronel Sanfeliu habrá dos carriles ... y la carga',
    %% whose left words held the verb (2.6 million inferences more to the same refusal); and only in a sentence with
    %% such a word ('$tr_among', tr_among_note/1: asked at every split, the walk cost long sentences 0.1 to 0.2 million)
    \+ ( nb_getval('$tr_among', yes),
         append(Pre, [P|After], W1), Pre \== [], P = w(PW, _), atom(PW), tr_is(Side, P, preposition),
         tr_lexeme(Side, PW, PL, _), once(tr_solve(mean(PL, among))), After = [_|_],
         \+ ( member(Q, After), Q = w(_, _), ( tr_is(Side, Q, preposition) ; tr_coord(Side, Q) ) ) ),
    tr_headed(Side, W1), tr_headed(Side, W2), !.
%% (a relative word, or a preposition and one: `che', `sul quale')
tr_relative_after(Side, [w(R, _)|_]) :- atom(R), tr_relative_word(Side, R), !.
tr_relative_after(Side, [P, w(R, _)|_]) :- P = w(_, _), tr_is(Side, P, preposition), atom(R), tr_relative_word(Side, R), !.
tr_count_pair(Side, W1, [M2|_]) :-
    tr_is(Side, M2, number),
    append(Advs, [M1], W1), Advs = [_|_],
    forall(member(X, Advs), ( X = w(_, _), tr_is(Side, X, adverb) )),
    tr_is(Side, M1, number), !.
%% ... AND A NUMBER, A COORDINATOR AND A NUMBER WITH A NOUN AFTER IT, in
%% digits: `entre 5.000 y 6.000 millones de pesetas' is one count, as `entre
%% cinco y seis millones' is, and divided at the `y' it was two phrases, the
%% second `6.000 millones', and the person before it was the object
tr_count_pair(Side, [M1], [M2, N|_]) :-
    M1 = w(D1, _), atom(D1), tr_digits(D1), M2 = w(D2, _), atom(D2), tr_digits(D2),
    tr_is(Side, M1, number), tr_is(Side, M2, number), N = w(_, _), tr_is(Side, N, noun), !.
tr_same_number(Side, w(X, _), w(Y, _)) :- atom(X), atom(Y), tr_lexeme(Side, X, _, N), tr_lexeme(Side, Y, _, N), !.
%% ... or where the clause is its relative word and one verb the lesson calls
%% intransitive, which takes nothing after it: `Voces de un ayer que marcó
%% época y estrellas de las ondas de hoy se reunieron' -- the voices of a
%% yesterday that made history, and the stars; with the clause running on,
%% the stars were a second thing it made
tr_closed_relative(foreign, W1) :-
    append(_, [w(R, _), w(V, _)], W1), atom(R), tr_relative_word(foreign, R),
    atom(V), tr_form_nt(V, L, _, _), tr_solve(intransitive(L)), !.
tr_headed(Side, Ws) :- member(w(W, _), Ws), ( tr_is(Side, w(W, lower), noun) ; tr_is_name(Side, W) ; tr_subject_pronoun(Side, W, _, _) ; tr_object_pronoun(Side, W, _) ), !.
%% ... or an emphatic reflexive pronoun: `contraddire sé stesso e le parole dell'imputato' is to contradict himself and
%% the defendant's words, one object of two -- `sé stesso' is a pronoun of no role, and with nothing to head the words
%% before the coordinator the split was refused and the sentence with it
tr_headed(Side, [w(W, _)]) :- tr_emphatic_pronoun(Side, W), !.
%% ... or a phrase whose noun was left out: `un grupo y el más débil'
%% (a count before it as well as an article: `(21 nuevas y 12 renovaciones)'
%% is twenty-one new ones and twelve renewals)
tr_headed(Side, Ws) :-
    Ws = [D, _|_], ( tr_determiner(Side, D, _, article) ; tr_is(Side, D, number) ),
    tr_np(Side, Ws, NP), ( NP = np(_, _, _, elided(_), _) ; NP = ell(_, _, _, _) ), !.
%% ... or a pronoun that stands alone: `un elicottero della forestale e UNO
%% della Guardia di finanza' is one more helicopter, the noun said once
tr_headed(foreign, [w(W, _)|_]) :- tr_lexeme(foreign, W, L, _), tr_class_of(L, pronoun), tr_solve(neg(precede(L, verb))), !.
%% ... or a count with its noun left out: `oltre 50 mezzi e 130 circa' is
%% vehicles and a hundred and thirty people, the number standing for them
tr_headed(_, Ws) :- last(Ws, w(W, _)), tr_digits(W), !.
%% ... or a count and an adjective that stands for the thing counted: `vivono
%% 6 milioni e 458 mila poveri' -- `poveri' is an adjective of the lesson
%% only, and `458 mila poveri' a noun phrase all the same (tr_np/3)
tr_headed(Side, Ws) :-
    Ws = [C0, _|_], tr_count_word(Side, C0), tr_np(Side, Ws, np(_, _, _, _, _)), !.
tr_is_name(Side, W) :- \+ tr_known_word(Side, W), \+ en_function(W), \+ en_subject(W, _, _).

%% A PERSON'S NAME AFTER A PHRASE THAT ENDS ON CAPITALISED WORDS THE LESSON KNOWS, WITH NO COMMA, IS APPOSED AS
%% IT IS AFTER ONE: `el artificiero de la Guardia Civil Luis Marfil' is the Civil Guard's bomb disposal expert, Luis
%% Marfil -- with the capitals run together the name was read inside the institution's, and the phrase had no reading.
%% The name's words join as one, w(Name, appos), the word a comma before the name makes (tr_list_commas/3)
tr_np(foreign, Words, NP) :-
    %% (the name begins at its first word no lesson knows, and runs in capitals to the end: `marfil' is ivory too; and
    %% it is the phrase of `of''s own, `la Guardia Civil Luis Marfil', after a determiner and capitals the lesson knows)
    Words = [_, _, _, _|_], last(Words, w(_, upper)),
    append(Pre, NameWs, Words), NameWs = [N1, _|_], tr_name_word(foreign, N1), forall(member(X, NameWs), X = w(_, upper)),
    last(Pre, PL), PL = w(PW, upper), atom(PW), tr_known_word(foreign, PW),
    Pre = [D, _|_], tr_determiner(foreign, D, _, _),
    %% (... and the capitals before the name come right after a determiner, as an institution's do: `un violín
    %% llamado Ex Von Szerdahely VieuxTemps' has `ex' after a participle, and the phrase read for nothing cost its
    %% sentence 0.39 million inferences of 1.37)
    once(( append(PreA, CapRun, Pre), CapRun = [_|_], forall(member(X2, CapRun), X2 = w(_, upper)),
           last(PreA, DA), tr_determiner(foreign, DA, _, _) )),
    findall(C, ( member(w(Y, _), NameWs), tr_cap(Y, C) ), Cs), atomic_list_concat(Cs, ' ', Name),
    append(Pre, [w(Name, appos)], W2), tr_np(foreign, W2, NP), !.
%% A CAPITAL NAME THE LESSON STATES AFTER AN ARTICLE THAT IS NOT ITS NOUN'S GENDER IS THE NAME:
%% `triunfó en el Mallorca y en el Valencia' is the club, and `valencia' is a FEMININE noun (the
%% valency) that a masculine `el' cannot be the article of -- it was `in the Valency'. The lesson
%% says it is a name (`"valencia" is a name.'), the article is another gender than every noun
%% reading the word has, and nothing but the word follows: the name with its article, as a name no
%% lesson knows is (named/2). `la Valencia' keeps the noun, and so does a name not stated
tr_np(foreign, [D, w(W, upper)], np(det(DK, DL, D), none, [], named(G, [w(W, upper)]), Number)) :-
    atom(W), tr_solve(name(W)), tr_determiner(foreign, D, DL, DK), DK == article,
    tr_det_gender(foreign, D, DL, G, Number), atom(G), G \== none,
    findall(NG, ( tr_lexeme(foreign, W, L, _), tr_gender(L, NG), NG \== none ), NGs), NGs = [_|_],
    \+ memberchk(G, NGs), !.
%% A NAME OF SEVERAL WORDS IN SMALL LETTERS, WHERE THE LESSON SAYS IT IS ONE:
%% `llegaron les lions de Bruno Metsu' -- the team by its French name, which
%% the paper keeps as it keeps `grandeur' (`"les lions" is a name.'). It is
%% a name in the number the lesson states of it, and it crosses as itself:
%% read as the noun it also is, `les lions' was a lion, singular, and no
%% plural verb agreed with it
tr_np(foreign, [w(W, lower)], np(none, none, [], named(G, [w(W, lower)]), N)) :-
    atom(W), tr_solve(name(W)), sub_atom(W, _, _, _, ' '), !,
    ( tr_solve(plural_of(W, _)) -> N = plural ; N = singular ),
    ( tr_holds(feminine(W)) -> G = feminine ; G = masculine ).
%% ADJECTIVES BEFORE A NAME WITH NO DETERMINER: `"povera Margherita.'
%% -- poor Margherita, a mother's whole line about the girl. One capitalised
%% word, a name or a noun the lesson knows written as one (`margherita' is a
%% daisy), with adjectives in small letters before it; each adjective stays
%% before the name (pre/1), and its own form says the gender the name carries.
%% It is read before every other phrase clause: the phrase of an adjective
%% and a capitalised noun took the daisy and crossed it by its meaning
%% ... A NOUN THE LESSON KNOWS ONLY WHERE THE LESSON SAYS IT IS A NAME TOO
%% (`"margherita" is a name.'): the first cut took any, and `¡Feliz
%% Navidad!', an old control's `Happy Christmas!', came out `Happy
%% Navidad!', the feast passed through as a name
tr_np(foreign, [A|Ws0], np(none, none, AdjsM, named(G, [w(N, upper)]), singular)) :-
    A = w(AW, lower), atom(AW), Ws0 \== [], tr_is(foreign, A, adjective),    % before the list is walked
    tr_adjectives_then_name(Ws0, Pre0, N), atom(N),                         % and it stops at a word that is none
    ( tr_name_word(foreign, w(N, upper)) -> true
    ; tr_solve(name(N)), tr_is(foreign, w(N, lower), noun), \+ tr_is(foreign, w(N, lower), pronoun) ),
    Pre = [A|Pre0],
    forall(member(P, Pre), ( P = w(_, lower), \+ tr_coord(foreign, P), tr_adj_word(foreign, P), tr_is(foreign, P, adjective) )),
    findall(pre(P), member(P, Pre), AdjsM),
    ( tr_holds(feminine(AW)) -> G = feminine ; G = masculine ), !.

%% a phrase: a name; or a determiner or none, a number or none, then the
%% content -- one noun (the word the lesson calls one, failing that the last
%% word in English and, where adjectives follow the noun, the first) and
%% the rest adjectives, an `and' among them kept
%% A PARTICIPLE AFTER THE NOUN IS A REDUCED RELATIVE: `il coprifuoco imposto
%% dai soldati' is the curfew THAT WAS imposed by the soldiers, and `le
%% autorita costituite' the authorities that were constituted. It is a
%% passive relative clause with the copula and the pronoun left out, and both
%% languages and English put it in the same place -- after the noun -- which
%% is why one shape writes into all three.
%%
%% `rel(NP, Lexeme, Comps)' is the term: the phrase, the verb's lexeme
%% (English in the IR like every other), and what belongs to the participle,
%% which is the agent when there is one. The lexeme rather than the FORM,
%% because the form must agree with the noun on the way out and the writer
%% picks it exactly as a passive does.
%% A RELATIVE CLAUSE WITH ITS OWN PRONOUN: `esos, que son culpables', `el
%% caldo que el pequeño aprende', `el grupo social al que pertenece'.
%% rc(Phrase, Role, Clause) is the term: the phrase it sits on, what the
%% relative word stands for in the clause -- subject, object, or the object
%% of a preposition, pp(P) -- and the clause as a sentence of the IR with
%% that one thing left out. A subject left out is `gap', and the writer
%% gives it the PHRASE's person and number, which is what the verb agreed
%% with; an object or a preposition's object is simply not there.
%%
%% THE SUBJECT READING IS TRIED FIRST: `que come el pan' is the phrase
%% eating, and only when nothing may stand before the verb does it fail and
%% the object reading take the whole clause as a statement of its own.
tr_np(Side, Words, app(NP, Kind, K)) :-
    append(Core, [w(K, Kind)], Words), memberchk(Kind, [paren, aside, dashed, dash1]), Core \== [],
    %% (but a bracket right after a name that ends a relative clause is the name's: `los artificieros que han peinado
    %% las playas de Tarragona, Salou (Tarragonès) y Cambrils (Baix Camp)' -- Cambrils's district, and hung on the
    %% phrase with its clause it was written after the clause's verb)
    \+ ( Kind == paren, last(Core, w(_, upper)), member(w(X, _), Core), atom(X), tr_relative_word(Side, X) ), !,
    tr_np(Side, Core, NP).
%% ... AND A BRACKET BETWEEN A NOUN AND ITS ADJECTIVE glosses the phrase:
%% `i presìdi (leggi procure) addetti alla pulizia ambientale' -- the
%% garrisons, read: the prosecutors, assigned to the cleaning. The phrase
%% reads without it and the bracket is the phrase's, app/3, which every
%% writer puts after the phrase: the gloss moves past the adjective.
%% (a PLAIN phrase before it: after a relative clause's object the bracket
%% is that object's, `i lacci in cui si cerca di irretire i presìdi (leggi
%% procure) addetti ...', and hung on the whole it moved to its end)
%% (and never before a PARTICIPLE WITH ITS AGENT, which is a reduced
%% relative on the phrase the bracket closes: `per omicidio colposo (contro
%% ignoti) aperta dal pm Delia Cardia' -- and hung on the whole, the bracket
%% went after the prosecutor's name)
tr_np(Side, Words, app(NP, paren, K)) :-
    append(Pre, [w(K, paren)|Post], Words), Pre = [_, _|_], Post = [A|_],
    A = w(AW, _), tr_is(Side, A, adjective), tr_headed(Side, Pre),
    \+ ( atom(AW), tr_participle_here(Side, AW, _), Post = [_, B|_], B = w(_, _), tr_means_by(Side, B) ),
    \+ ( member(w(X, _), Pre), atom(X), tr_relative_word(Side, X) ),
    tr_np(Side, Pre, np(_, _, _, w(_, _), _)),
    append(Pre, Post, Core), tr_np(Side, Core, NP), NP \= app(_, _, _), !.
%% A TITLE AND THE NAME IT GOES WITH: `la descripción visual de lord Arturo
%% Bucklaw' -- a noun of the lesson's in small letters, and a name of two
%% words or more after it, which is one person with his title. A name
%% apposed to a noun stands only after a determiner (`il presidente
%% Scalfaro'), so with none the name was a sentence's subject of its own,
%% `Arturo Bucklaw Vick'. The name's words join as one, apposed to the
%% noun, and cross as themselves: `lord Arturo Bucklaw'.
tr_np(foreign, [w(NW, lower), W1, W2|Ws], np(none, none, [w(Name, upper)], w(NW, lower), Number)) :-
    tr_is(foreign, w(NW, lower), noun),
    forall(member(X, [W1, W2|Ws]), tr_name_word(foreign, X)), !,
    ( tr_lexeme(foreign, NW, _, Number) -> true ; Number = singular ),
    findall(C, ( member(w(X1, _), [W1, W2|Ws]), tr_cap(X1, C) ), Cs), atomic_list_concat(Cs, ' ', Name).
%% ... and a NAME with a name apposed to it between commas (tr_list_commas/3):
%% `en Josep Bros, Edgardo,' is the singer and the role he sang
tr_np(Side, Words, app(NP, apposed, w(W, appos))) :-
    append(Core, [w(W, appos)], Words), Core = [_|_], forall(member(X, Core), tr_name_word(Side, X)), !,
    tr_np(Side, Core, NP).
%% ... and a capitalised word the lesson knows, read as the name it stands
%% for there: `la ministra de Justicia, Janet Reno,' -- after `de' the word
%% is a name (tr_np/3), and the apposition after it refused the phrase
%% -- or several: `El presidente de Òmnium Cultural, Josep Millàs,' is the
%% association's name, and `cultural' is a word the lesson knows
tr_np(Side, Words, app(NP, apposed, w(W, appos))) :-
    append(Core, [w(W, appos)], Words), Core = [w(_, upper)|_], forall(member(X, Core), X = w(_, upper)),
    tr_np(Side, Core, NP), NP = name(_), !.
%% ... and a name with a DETERMINER before it: `del actual presidente y ex
%% ministro ... de la antigua URSS, Eduard Shevardnadze,' -- the phrase is
%% an article and a name (named/2), which takes no adjective after it, so
%% the name apposed to it refused the whole sentence
tr_np(Side, Words, app(NP, apposed, w(W, appos))) :-
    append(Core, [w(W, appos)], Words), Core = [D, _|_], tr_determiner(Side, D, _, _),
    last(Core, L), tr_name_word(Side, L),
    tr_np(Side, Core, NP), NP = np(_, _, _, named(_, _), _), !.
%% A NAME OR A PERSON HAS NO CLAUSE OF ITS OWN, in any of the three readers
%% below: `chi aveva detto a Colombo che la terra era sferica?' said to
%% Columbus THAT it was round -- `colombo' is a pigeon too, so the word
%% before `che' passed as a noun, and the clause was the name's, which
%% Spanish wrote `a Colombo de que'; and `ai suoi avversari che la terra era
%% sferica' is the same with a noun the lesson calls a person
%% A NOUN AND THE CLAUSE THAT SAYS WHAT IT IS: `Como prueba de que los
%% violines ... han mejorado con el tiempo, los solistas ...' is proof THAT
%% the violins have improved. The clause runs to the end of the phrase's
%% words, as a `che' clause runs to the end of its piece, and each writer
%% puts its own words before it: Spanish its `de que', Italian `che',
%% English `that'.
%% -- and after its last comma it has adjuncts only: `... han mejorado con
%% el tiempo, los solistas de la Orquesta de Valencia ofrecerán un
%% concierto' offered the soloists as what the violins had improved, and
%% then `los' alone as their object pronoun, and either way the main clause
%% was left with nobody to offer the concert. A phrase after the comma
%% begins the next clause, so the front ends before it.
tr_np(foreign, Words, ncl(NP, S)) :-
    append(Core, [P, W|Rest], Words), Core \== [], Rest \== [],
    tr_clause_opener(foreign, [P, W]), !,
    tr_object_phrase(foreign, Core, NP), \+ tr_of_class(NP, person),
    tr_read_nested(foreign, Rest, none, S),
    \+ ( S = s(_, _, _, Cs), append(_, [sep|After], Cs), \+ memberchk(sep, After),
         member(C, After), \+ tr_adjunct(C) ).
%% A NOUN THE LESSON SAYS TAKES THE CLAUSE HAS ITS OWN AFTER `che': `il
%% rischio che una laurea in fisica a Catania valga meno che quella al
%% politecnico di Milano' is the risk THAT a degree is worth less -- and the
%% clause has no object, so the relative reading below took `che' for what
%% the degree is worth. `"rischio" takes the clause.' says so, in the shape
%% `"risulta" takes the clause.' has for a verb; only where the clause's
%% subject stands first, so `il rischio che corriamo' stays the risk we run.
tr_np(foreign, Words, ncl(NP, S)) :-
    tr_that_set(Ts), once(( member(w(T0, _), Words), memberchk(T0, Ts) )),   % the rare word first,
    append(Core, [W|Rest], Words), Core \== [], Rest \== [],                     % and at every place
    W = w(WT, _), memberchk(WT, Ts), tr_that_here(foreign, W), last(Core, H), H = w(HW, _), atom(HW),
    tr_lexeme(foreign, HW, HL, _), tr_solve(take(HL, clause)),
    \+ ( member(w(R0, _), Core), tr_relative_word(foreign, R0) ),
    %% ... OR THE CLAUSE IS AN EXISTENTIAL, which has no subject before its
    %% verb: `la conclusione che non ci fu dolo' is the conclusion that there
    %% was no malice. Read as a relative clause it had the conclusion for its
    %% gap, and English wrote `that did not there is criminal intent'
    (   tr_subject_first(Rest) -> Existential = no ; Existential = yes ),
    tr_object_phrase(foreign, Core, NP), \+ tr_of_class(NP, person),
    tr_read_nested(foreign, Rest, none, S),
    S = s(_, Su, _, _), Su \= null(_, _), Su \== none,
    ( Existential == yes -> Su == there ; true ), !.
%% A SECOND RELATIVE CLAUSE AFTER A COMMA IS THE SAME NOUN'S: `la gente che mi
%% stringe la mano ogni giorno, che mi fa coraggio, che mi dimostra il suo
%% affetto' -- the people who shake my hand, who encourage me, who show me
%% their affection. A relative clause runs to the end of the phrase's words, so
%% the second `che' was the first clause's own, a clause of `that' with
%% nobody named for its subject, and English refused it. The last comma and
%% relative word divide: what is before them is a phrase with its relative
%% clause (itself divided the same way), and what is after them a relative
%% clause hung on it, nrc/3 as after any phrase
tr_np(foreign, Words, nrc(NP1, Role2, S2)) :-
    nb_getval('$tr_comma_rel', yes), memberchk(comma, Words),
    append(First, [comma, w(R2, RC2)|Rel2], Words), First \== [], Rel2 \== [],
    tr_relative_word(foreign, R2),
    \+ ( append(_, [comma, w(R3, _)|_], Rel2), tr_relative_word(foreign, R3) ),
    ( member(w(R0, _), First), atom(R0), tr_relative_word(foreign, R0) -> true ),     % (a relative clause before it to hang this one on)
    %% (and every comma before it parts relative clauses: an apposition, `che ..., Jorge Arandes y
    %% Joan Viñas, che ...', is no series, and its phrase was read whole to say so)
    \+ ( append(_, [comma, N1|_], First), \+ ( N1 = w(NW1, _), atom(NW1), tr_relative_word(foreign, NW1) ) ),
    tr_np(foreign, First, NP1), ( NP1 = rc(_, _, _) ; NP1 = nrc(_, _, _) ),
    tr_relative_clause(foreign, [w(R2, RC2)|Rel2], Role2, S2), !.
%% ... AND JOINED TO IT BY A COORDINATOR, no comma: `un ataque con el que sueñan los interistas Y QUE han
%% truncado las constantes lesiones' is an attack the fans dream of and the injuries have truncated. The
%% second `que' is a relative word on the same phrase, and read after the first clause it was a clause of
%% `that' that the verb took (`is that ... and that they have truncated the constant injuries', with a
%% subject nobody named). The role carries the coordinator, ro(Coordinator, Role)
tr_np(foreign, Words, nrc(NP1, ro(Co, Role2), S2)) :-
    nb_getval('$tr_second_rel', yes),
    append(First, [Co, w(R2, RC2)|Rel2], Words), Co = w(CW, _), atom(CW), tr_coord(foreign, Co),
    First \== [], Rel2 \== [], tr_relative_word(foreign, R2), tr_doer_after_verb(Rel2),
    \+ ( append(_, [Co3, w(R3, _)|_], Rel2), Co3 = w(CW3, _), atom(CW3), tr_coord(foreign, Co3), tr_relative_word(foreign, R3) ),
    ( member(w(R0, _), First), atom(R0), tr_relative_word(foreign, R0) -> true ),
    tr_np(foreign, First, NP1), ( NP1 = rc(_, _, _) ; NP1 = nrc(_, _, _) ),
    tr_relative_clause(foreign, [w(R2, RC2)|Rel2], Role0, S0),
    tr_nrc_head(NP1, Head), tr_rc_role(foreign, [w(R2, RC2)|Rel2], Head, Role0, S0, Role2, S2), !.
%% `AL QUE' AFTER AN ADJECTIVE THAT TAKES THE WORD FOR `TO' IS THE ADJECTIVE'S
%% PHRASE: `un horario similar al que desarrollan las cajas de ahorros' is a
%% schedule similar TO THE ONE the savings banks keep -- `al' is `a el', and read
%% as the preposition and its article before the relative word it was `similar
%% to which they develop'. The adjective's English takes `to' (en_adj_takes/2), so the
%% contraction's article and the clause are the phrase whose noun the clause
%% stands for (ell/4), and the adjective's phrase travels after its phrase
%% (with/2), as English and the lesson's writer each place it
tr_np(foreign, Words, with(NP, [pp(w(A, PC), ell(det(article, ArtL, D), G, Number, rel(Role, S)))])) :-
    nb_getval('$tr_adj_rel', yes),
    append(Core, [w(A, PC), D, w(R, RC)|Ws], Words), Core \== [], Ws \== [],
    atom(A), atom(R), tr_relative_word(foreign, R), tr_is(foreign, w(A, lower), preposition),
    tr_determiner(foreign, D, ArtL, article),
    last(Core, w(AdW, _)), atom(AdW),
    tr_lexeme(foreign, AdW, AdL, _), tr_solve(mean(AdL, E)), tr_prep_across(A, T), en_adj_takes(E, T),
    tr_object_phrase(foreign, Core, NP), NP = np(_, _, Adjs, _, _), last(Adjs, w(AdW, _)),
    tr_det_gender(foreign, D, ArtL, G, Number),
    tr_relative_clause(foreign, [w(R, RC)|Ws], Role0, S0), Role0 \= pp(_), !,
    tr_rc_role(foreign, [w(R, RC)|Ws], ell(none, G, Number, none), Role0, S0, Role, S).
tr_np(Side, Words, rc(NP, Role, S)) :-
    (   nb_getval('$tr_joined', yes)                                   % no split is worth trying without one
    ->  once(( member(W0, Words), W0 = w(RW, _),
               ( tr_relative_word(Side, RW) -> true ; tr_joined_relative(Side, W0, _, _) ) ))
    ;   once(( member(w(RW, _), Words), tr_relative_word(Side, RW) ))
    ),
    append(Core, Rest, Words), Core \== [],
    tr_relative_start(Side, Rest),
    \+ ( member(w(R0, _), Core), tr_relative_word(Side, R0) ),
    %% a clitic that replaces a noun is that noun's place, never a pronoun
    %% the clause is about: `lo que hace' is what it does (the phrase a
    %% noun replacer opens, below), and read as `him that' it came out `Him
    %% that is to discredit the research ago'
    %% -- nor an article that is a clitic too: `después de la que celebraron
    %% el Lunes ... delegaciones' is after the one they held, and read as
    %% `her that' Italian wrote `dopo lei che'. An article before a relative
    %% word is a phrase whose noun a relative clause stands for (ell/4)
    \+ ( Side == foreign, Core = [Q1], Q1 = w(C1, _), tr_clitic(normal, C1),
         ( tr_noun_replacer(foreign, Q1) ; tr_determiner(foreign, Q1, _, article) ) ),
    tr_relative_clause(Side, Rest, Role0, S0),
    tr_object_phrase(Side, Core, NP),
    %% ... AND THE ARTICLE BETWEEN A PREPOSITION AND THE RELATIVE WORD AGREES
    %% WITH THE PHRASE IT STANDS FOR: `el ridículo de los que los utilizan' is
    %% the ridicule of THOSE who use them -- `los' cannot stand for the
    %% singular `ridículo', and read as `of which' it came out `il ridicolo di
    %% cui li usano'. What is left is the phrase and a `de' phrase whose noun
    %% the relative clause stands for (ell/4)
    %% (the number of THE ARTICLE: `los' is also the pronoun `them', whose
    %% lexeme is singular, and `los gatos en los que duermen los perros' was
    %% blocked as a plural article for a singular phrase)
    \+ ( Role0 = pp(_), Rest = [_, D, _|_], D = w(DW, _), tr_determiner(Side, D, DL, article),
         tr_head_number(Side, NP, N), tr_lexeme(Side, DW, DL, DN), DN \== N ),
    %% ... AND A PREPOSITION'S RELATIVE THAT IS A PERSON'S WORD HANGS ON A PERSON: `para entregarlos ... a quien
    %% correspondiera' hands them to whoever it concerned, and `quien' (which the lesson says begins the relative)
    %% hung on `el ayuntamiento' before it was `the town council to which corresponded', which no writer wrote: the
    %% sentence was refused. After a phrase that is no person, the preposition and the word are the free relative
    %% (tr_complements0/4)
    \+ ( Side == foreign, Role0 = pp(_), Rest = [_, w(QR, _)|_], atom(QR), tr_solve(begin(QR, relative)),
         NP \= name(_), \+ tr_of_class(NP, person) ), !,
    tr_rc_role(Side, Rest, NP, Role0, S0, Role1, S1),
    ( Side == foreign -> tr_accident_rc(Role1, S1, Role, S2a), tr_se_passive_rc(NP, Role, S2a, S2) ; Role = Role1, S2 = S1 ),
    tr_rel_mark(Rest, S2, S).
%% ... AND `CHE' STRAIGHT AFTER THE NOUN, WITH A CLAUSE THAT HAS ITS OWN
%% SUBJECT AND ITS OWN OBJECT: `della notizia che finalmente il fondo Veba e
%% Fiat hanno raggiunto l'accordo' is the news THAT they reached it. Such a
%% clause leaves no gap for a relative to fill, so it is no relative clause
%% (tr_relative_clause/4 says so of the object) -- it is the noun's own, and
%% Spanish writes it `la noticia de que'.
%% -- AND TWO CHEAP TESTS COME BEFORE THE READ, because the read is the rest
%% of the sentence and this is asked of every phrase with a `che' in it: the
%% phrase before it ends in a noun, and the clause's subject stands first,
%% after its adverbs. Without them `los violonchelos que se exponen ...' read
%% every word after `que' to the end of Valencia's last sentence, 28 s to 44.
tr_np(foreign, Words, ncl(NP, S)) :-
    append(Core, [W|Rest], Words), Core \== [], Rest \== [],
    tr_that_here(foreign, W), W = w(T, _), tr_relative_word(foreign, T),
    \+ ( member(w(R0, _), Core), tr_relative_word(foreign, R0) ),
    last(Core, H), tr_is(foreign, H, noun),
    tr_subject_first(Rest),
    tr_object_phrase(foreign, Core, NP), \+ tr_of_class(NP, person),
    %% (read as a verb's clause of `che' is, whose comma straight after the
    %% word opens an insertion in front of it: `dal fatto che, almeno sino a
    %% Copernico, il mondo greco aveva ritenuto ...', where the nested reader
    %% had nothing for the comma and the clause went to the verb, `nace
    %% desde el hecho que')
    tr_that_clause(foreign, Rest, S),
    S = s(_, Su, G, Cs), Su \= null(_, _), Su \== none,
    %% ... OR ITS OWN COPULA AND WHAT IT SAYS: `all'affermazione che la
    %% "Bastiglia" è inviolabile' is the assertion THAT it is, and a copula
    %% takes no object for a relative to be
    %% ... OR A CLAUSE OF ITS OWN: `per il semplice motivo che la "Bastiglia"
    %% ... non mi risulta sia stata mai occupata'
    (   memberchk(obj(_), Cs) -> true
    ;   G = g(CL, _, _, _), tr_copula_lexeme(CL), memberchk(adj(_), Cs) -> true
    ;   memberchk(that(_), Cs)
    ), !.
%% THE MOST AWAITED BY THE FANS: `una ejemplar escena de la locura, la más
%% esperada por los aficionados' -- an article, the word for `more' and a
%% participle with its agent, the scene's noun said once. The article made
%% no phrase with `más' after it, so `la' was read as the pronoun `her' and
%% put before the verb of the clause. The phrase is the article's with its
%% noun left out, and the participle carries the degree the article makes
%% of it, pdeg(Degree) among its complements: `la più attesa dagli
%% appassionati', `the one most awaited by the fans'.
tr_np(foreign, [D, w(M, _), w(P, PC)|Rest], rel(np(det(DK, DL, D), none, [], elided(G), Number), L, Comps)) :-
    tr_degree_word(M),                                 % the rare word first: this is asked of every phrase
    tr_determiner(foreign, D, DL, DK), DK == article, \+ tr_standalone_det(foreign, D),
    tr_participle_here(foreign, P, L), \+ tr_is(foreign, w(P, lower), adjective),
    tr_det_gender(foreign, D, DL, G, Number), tr_participle_agrees(P, Number),
    ( Rest == [] -> Comps0 = [] ; tr_reduced_agent(foreign, Rest, Comps0) ),
    tr_degree_of(foreign, det(DK, DL, D), Degree),
    tr_rel_case(PC, [pdeg(Degree)|Comps0], Comps), !.
%% AN ADVERB BETWEEN A NOUN AND ITS PARTICIPLE IS THE PARTICIPLE'S: `en
%% sesiones a puerta cerrada centradas en las consecuencias' are sessions held
%% behind closed doors and centred on the consequences. The phrase ended at
%% the adverb, and the participle after it was said of the sentence's subject
%% and agreed with it, `centrati'. The adverb travels as padv/1, and every
%% writer puts it BEFORE the participle, where the source had it: written
%% after it as an ordinary complement, `un mes de Febrero muy apretado' came
%% out `stretto molto', where 1.8.8 had read the intensifier and written
%% `molto stretto'.
tr_np(foreign, Words, rel(NP, L, [padv(A)|Comps])) :-
    append(Core, [A, w(P, PC)|Rest], Words), Core = [_|_],
    A = w(_, _), tr_plain_adverb(foreign, A), \+ tr_is(foreign, A, preposition),
    tr_participle_here(foreign, P, L), \+ tr_is(foreign, w(P, lower), noun),
    tr_headed(foreign, Core),
    tr_object_phrase(foreign, Core, NP), NP \= rel(_, _, _), \+ tr_clause_phrase(NP),
    ( Rest == [] -> Comps0 = [] ; tr_ptc_complements(foreign, L, Rest, Comps0) ),
    tr_rel_agreement(foreign, P, NP, Comps0, Comps1), tr_rel_case(PC, Comps1, Comps), !.
%% (the lesson's word for `more' is looked for first: tr_np/3 is asked of
%% every word list a phrase might be, and walking each one for a degree
%% word cost the controls 1.2 million inferences in one sentence)
tr_np(foreign, Words, rel(NP, L, Comps)) :-
    once(( tr_solve(begin(DW, comparative)), memberchk(w(DW, _), Words) )),
    append(Core, [w(M, _), w(P, PC)|Rest], Words), Core = [_|_],
    tr_degree_word(M),
    tr_participle_here(foreign, P, L), \+ tr_is(foreign, w(P, lower), noun),
    \+ tr_is(foreign, w(P, lower), adjective),         % an adjective is tr_degrees/4's to fold
    tr_headed(foreign, Core),
    tr_object_phrase(foreign, Core, NP), NP = np(Det, _, _, _, _),
    ( Rest == [] -> Comps0 = [] ; tr_ptc_complements(foreign, L, Rest, Comps0) ),
    tr_degree_of(foreign, Det, Degree),
    tr_rel_agreement(foreign, P, NP, [pdeg(Degree)|Comps0], Comps1), tr_rel_case(PC, Comps1, Comps), !.
%% A QUOTED TITLE AFTER A PHRASE IS THE PHRASE'S: `sul tema "spazio al tuo
%% futuro"' is the theme called that, and `al corso trimestrale "missioni
%% umane nello spazio" per il quale ...' the course. Read as words, the title's
%% first noun was an adjective of `tema', written before it in Spanish -- `el
%% "espacio tema a tu futuro"' -- and the course's title was an object of the
%% verb with the relative clause on its last word. The title is read as the
%% complements it is, app(Phrase, title, Complements), its marks on its
%% words, and every writer puts it after the phrase. Two words at least and
%% no comma: one word in quotation marks after a noun says what kind (a
%% compound, nmod/1), and a run with a comma is a quotation of its own.
tr_np(foreign, Words, app(NP, title, Cs)) :- tr_quoted_title(Words, NP, Cs), !.
%% THE AGENT BEFORE ITS PARTICIPLE: `la tuta da lui usata nelle missioni
%% spaziali' is the suit HE used -- Italian may put a short agent first, and
%% the phrase ended at `da', so `lui' was a place and the participle said of
%% nothing: `el traje desde él utilizado'. The participle agrees with the
%% phrase, the agent is its by/1, and every writer puts it after the
%% participle, where a reduced relative's agent goes: `el traje usado por
%% él'. One word for the agent, a pronoun or a name (tr_phrase_words0/4)
tr_np(foreign, Words, rel(NP, L, Comps)) :-
    nb_getval('$tr_agent_first', yes),                                          % the sentence has one
    once(( member(B0, Words), B0 = w(_, _), tr_means_by(foreign, B0) )),        % the rare word first
    append(Core, [B, A1, w(P, PC)], Words), Core \== [],
    B = w(_, _), tr_means_by(foreign, B), tr_is(foreign, B, preposition),
    tr_lone_agent(A1, Agent),
    tr_participle_here(foreign, P, L), \+ tr_is(foreign, w(P, lower), noun),
    tr_headed(foreign, Core),
    tr_object_phrase(foreign, Core, NP), NP = np(_, _, _, _, N),
    tr_participle_agrees(P, N), tr_rel_agreement(foreign, P, NP, [], []),
    tr_rel_case(PC, [by(Agent)], Comps), !.
%% A PARTICIPLE AND ITS AGENT AFTER A NOUN AND A PHRASE OF THE NOUN'S OWN, AGREEING WITH THE NOUN AND NOT WITH
%% THE PHRASE: `En la Red existen páginas en castellano abiertas por miembros de estas sectas' are pages in Spanish
%% opened by members -- `abiertas' is feminine and plural, `castellano' masculine and singular -- and with the
%% participle hung on the nearest noun, the only place the phrase reader had, the language was what the members
%% opened, the subject after `existen' had no reading, and the sentence was refused. The noun and its phrase travel as
%% with/2, the participle's head, which every writer writes and then the participle agreeing with its noun. Only with
%% the agent right after the participle and a word before it that it does not agree with (`$tr_ptc_agent', noted
%% once a sentence), and never a phrase of `of', whose noun the participle hangs on with the agreement it carries
%% (agr/1, tr_rel_agreement/5)
tr_np(foreign, Words, rel(with(NP, [pp(Prep, PNP)]), L, Comps)) :-
    nb_getval('$tr_ptc_agent', yes),
    append(Core, [w(P, PC), B|Rest], Words), B = w(_, _), tr_means_by(foreign, B), atom(P),
    tr_participle_here(foreign, P, L), \+ tr_is(foreign, w(P, lower), noun),
    \+ memberchk(comma, Core),
    append(HeadW, [Prep|PPW], Core), HeadW = [_|_], PPW = [_|_],
    Prep = w(_, _), tr_is(foreign, Prep, preposition), \+ tr_means_of(foreign, Prep), \+ tr_means_by(foreign, Prep),
    tr_headed(foreign, HeadW), tr_object_phrase(foreign, HeadW, NP), NP = np(_, _, _, w(_, _), N),
    tr_participle_agrees(P, N), tr_rel_agreement(foreign, P, NP, [], []),
    tr_phrase_np(foreign, PPW, PNP), PNP \= rc(_, _, _),
    tr_ptc_complements(foreign, L, [B|Rest], Comps0),
    tr_rel_case(PC, Comps0, Comps), !.
tr_np(Side, Words, rel(NP, L, Comps)) :-
    append(Core, [w(P, PC)|Rest], Words), Core \== [],
    %% a clitic heads nothing: `la tesi' is the thesis, never `her, tended'
    \+ ( Side == foreign, Core = [w(C1, _)], tr_clitic(normal, C1) ),
    %% ... and a word that replaces the noun is no phrase of its own before a
    %% participle: `quello guidato dal magnate' is the one the tycoon led,
    %% the ellipsis read further down, and taken here it was the pronoun
    %% `that', led
    \+ ( Side == foreign, Core = [Q1], tr_noun_replacer(foreign, Q1) ),
    %% ... nor does an article alone before a word that is a NOUN as well as
    %% a participle: `delle coperte' is blankets, not `the covered ones'
    \+ ( Core = [D1], tr_determiner(Side, D1, _, _), tr_is(Side, w(P, lower), noun) ),
    %% ... nor anything with no noun of its own before one: `a doble partido'
    %% is a two-legged match, `partido' the noun, and read as `double, split'
    %% the adjective was a noun by its place and the match a participle
    \+ ( tr_is(Side, w(P, lower), noun), \+ tr_headed(Side, Core) ),
    %% ... nor a bare count before a word that is a noun too: `una media de 22
    %% empleados por empresa' is twenty-two employees, and read as the number
    %% and the participle of `emplear' it came out `22 impiegato' (a
    %% percentage is no count: `del 41,5% detenuta dal fondo' stays)
    \+ ( Core = [w(Nm, _)], tr_digits(Nm), \+ tr_percent(Nm), tr_is(Side, w(P, lower), noun) ),
    %% ... nor a word shortened to stand before a noun: `en mal estado' is in
    %% bad shape, and `mal' is `malo' there and nothing else
    \+ ( Side == foreign, Core = [w(A1, _)], tr_solve(apocope_of(A1, _)) ),
    tr_participle_here(Side, P, L),
    %% ... nor an article and a possessive: `la loro proposta' is their proposal,
    %% the possessive's phrase, and not `the theirs, proposed' (asked of a participle
    %% only: asked of every pair of words before one, it cost the heaviest
    %% sentences of the controls 0.8 %)
    \+ ( Core = [D2, Q2], tr_is(Side, w(P, lower), noun), tr_determiner(Side, Q2, _, possessive), tr_determiner(Side, D2, _, article) ),
    %% a participle the lesson calls an ADJECTIVE too, with no agent after
    %% it, is the adjective: `la donna dispersa' is missing, and read as the
    %% participle of `disperdere' she had been dispersed
    \+ ( Rest == [], tr_is(Side, w(P, lower), adjective) ),
    %% ... nor a determiner and its adjectives, with no agent after: `el
    %% mejor sentido del término' is the best sense, and read as the best
    %% one, felt, it came out `il migliore sentito' (asked of a participle
    %% only: asked of every last word, it cost Livata's sentences 3 %)
    \+ ( Rest == [], Core = [D2, _|_], tr_determiner(Side, D2, _, _), tr_is(Side, w(P, lower), noun),
         Core = [_|As2], forall(member(A2, As2), ( A2 = deg(_, _) ; A2 = w(M2, _), ( tr_is(Side, A2, adjective) ; Side == foreign, tr_degree_word(M2) ) )) ),
    tr_object_phrase(Side, Core, NP), NP \= rel(_, _, _), \+ tr_clause_phrase(NP),
    (   Rest == []
    ->  Comps0 = []
    ;   tr_ptc_complements(Side, L, Rest, Comps0)
    ),
    tr_rel_agreement(Side, P, NP, Comps0, Comps1), tr_rel_case(PC, Comps1, Comps), !.

%% ALL THAT A CLAUSE SAYS: `todo lo que dice Pedro' is all that Pedro says, `tutto quello che
%% dice' -- the phrase a noun replacer opens (its relative clause stands for the noun, below)
%% with `all' before it; read as the pronoun `everything' and a second phrase it was
%% `eats everything what there is', and as a subject it was refused
tr_np(foreign, [w(T, TC), Q, w(R, RC)|Ws], all(w(T, TC), NP)) :-
    nb_getval('$tr_replacer', yes),
    Ws \== [], tr_all_word(foreign, T), tr_noun_replacer(foreign, Q), tr_relative_word(foreign, R),
    tr_np(foreign, [Q, w(R, RC)|Ws], NP), NP = ell(_, _, _, rel(_, _)), !.
%% ... AND NOTHING OF IT: `nada de lo que hoy es el equipo' is nothing of what the team is today
%% (`algo de lo que', `nulla di quello che'), the pronoun and its phrase of `of' -- the
%% pronoun alone is read as a subject, and a phrase of `of' after it was no part of it
tr_np(foreign, [w(T, TC), P, Q, w(R, RC)|Ws], with(pronoun(w(T, TC)), [pp(P, NP)])) :-
    nb_getval('$tr_replacer', yes),
    Ws \== [], tr_none_word(T), tr_means_of(foreign, P), tr_noun_replacer(foreign, Q), tr_relative_word(foreign, R),
    tr_np(foreign, [Q, w(R, RC)|Ws], NP), NP = ell(_, _, _, rel(_, _)), !.
%% ALL THE NIGHT: `le ricerche sono proseguite tutta la notte', `toda la
%% noche'. A word the lesson says means `all', before a determiner, is no
%% pronoun standing alone but the phrase's own, and it agrees with the
%% phrase's noun -- read as the pronoun it also is, it was `everything' and
%% came out `todo la noche'.
%% (in the number of the word for `all': `Mangiammo tutti il pane' is we all
%% ate the bread, and read as all the bread the plural `tutti' was the
%% singular bread's)
tr_np(Side, [w(T, TC), D|Ws], all(w(T, TC), NP)) :-
    tr_all_word(Side, T), tr_determiner(Side, D, _, _),
    tr_np(Side, [D|Ws], NP), NP = np(_, _, _, _, NN),
    \+ ( Side == foreign, tr_lexeme(foreign, T, L, TN), tr_solve(mean(L, all)), memberchk(TN, [singular, plural]),
         \+ ( tr_lexeme(foreign, T, L2, NN), tr_solve(mean(L2, all)) ) ), !.
%% ... AND BEFORE A BARE PLURAL NOUN: `desde todas direcciones' is from all
%% directions. Read as the pronoun `todas' standing alone, it was from
%% everything, with the directions a second object: `da tutto direzioni'.
tr_np(Side, [w(T, TC), N|Ws], all(w(T, TC), NP)) :-
    tr_all_word(Side, T), N = w(NW, _), atom(NW), \+ tr_determiner(Side, N, _, _),
    tr_is(Side, N, noun), tr_lexeme(Side, NW, _, plural),
    tr_np(Side, [N|Ws], NP), NP = np(none, none, _, _, plural), !.
%% ... AND BEFORE A BARE SINGULAR NOUN: `con tutta evidenza' is with all
%% evidence, `con toda evidencia'; `con tutta calma', `a tutta velocità'.
%% Read as the pronoun alone, `tutta' was everything and the noun a second
%% object, and the writer made it `con todo evidencia'
tr_np(Side, [w(T, TC), N|Ws], all(w(T, TC), NP)) :-
    tr_all_word(Side, T), N = w(NW, _), atom(NW), \+ tr_determiner(Side, N, _, _),
    tr_is(Side, N, noun), tr_lexeme(Side, NW, _, singular),
    tr_np(Side, [N|Ws], NP), NP = np(none, none, _, _, singular), !.
%% ... AND BEFORE A PLURAL PERSONAL PRONOUN: `per tutti noi' is for all of us,
%% `todos nosotros'. `tutti' is the pronoun for everyone, and `noi' was left
%% with no phrase to stand in: the sentence was refused with every word known
tr_np(foreign, [w(T, TC), w(P, PC)], all(w(T, TC), pronoun(w(P, PC)))) :-
    tr_all_word(foreign, T), tr_all_person(P), !.
tr_np(Side, [w(W, upper)], name(W)) :- \+ tr_known_word(Side, W), !.
%% A DEFINITE ARTICLE BEFORE A PERSON'S FIRST NAME AND SURNAME IS NO PHRASE'S: `la placa original dedicada al
%% Salvador Seguí' is dedicated to him -- Catalan's article before a name, which a Barcelona paper writes in Spanish
%% too -- and read as the noun `salvador', a rescuer, with a surname apposed it came out `to the Rescuer Seguí', or
%% with a run of capitals `the Juan Pérez'. The run is the name the last clause of the bare names reads, a first name
%% the lesson says is a name (and no city: `la Spoleto Festival Orchestra') and capitals after it, and the article is
%% dropped; a word no lesson knows is no first name of this (`la Tate Gallery' keeps its article)
tr_np(foreign, [D, w(W1, upper), W2|Ws], NP) :-
    nonvar(W2), W2 = w(_, upper), atom(W1), tr_solve(name(W1)), \+ tr_city_name(W1),
    tr_determiner(foreign, D, DL, article), tr_lexeme_across(DL, english, the),
    tr_det_gender(foreign, D, DL, _, singular),
    tr_np(foreign, [w(W1, upper), W2|Ws], NP), NP = name(_), !.
%% A CAPITALISED NOUN STANDING ALONE AS A PHRASE INSIDE A SENTENCE IS A NAME,
%% even one the lesson knows: `en Valencia' is the city, where the
%% vocabulary's `valencia' is the chemist's valency and came out `Valenzia',
%% and `di Pale' is the town the dictionary made `Retablos'. The head of a
%% sentence is lowered before this when the lesson knows the word, so what
%% arrives capitalised is inside the sentence; a common noun there has its
%% article (`dei Paesi', `all'Arma'), which this one-word phrase has not.
%% Only on the lesson's side -- English capitalises its days and months --
%% and never a pronoun.
%% ... but never a word of several words the lesson states as one: `de
%% Asuntos Exteriores' is the ministry, and a town is not named with a
%% phrase the lesson knows (tr_multi/3 joined it)
%% ... AND ONE THE LESSON KNOWS AS AN ADJECTIVE: `Alto Representante Civil
%% en Bosnia' -- `bosnia' is the feminine of Bosnian to the vocabulary, and
%% read as an adjective with its noun left out it came out `in Bosniaco'
%% ... UNLESS THE LESSON SAYS IT IS AN INSTITUTION, which a newspaper
%% capitalises with no article after its preposition: `un pacto de Estado
%% sobre Justicia' is a pact of State on Justice, and kept a name it came
%% out `un patto d'Estado su Justicia' (`"estado" is an institution.')
tr_np(foreign, [w(W, upper)], name(W)) :-
    \+ sub_atom(W, _, _, _, ' '),
    ( tr_is(foreign, w(W, lower), noun) ; tr_is(foreign, w(W, lower), adjective) ),
    \+ tr_is(foreign, w(W, lower), pronoun), \+ tr_solve(institution(W)), !.
%% ... AND ONE THE LESSON KNOWS ONLY AS A VERB'S FORM: `croce in Usa' is the
%% United States, and `usa' is what `usare' says of one person, so the
%% one-word phrase after the preposition had no reading at all. A verb is
%% never a phrase, so a capital here is a name's
tr_np(foreign, [w(W, upper)], name(W)) :-
    \+ sub_atom(W, _, _, _, ' '), tr_verb_form_word(W),
    \+ tr_is(foreign, w(W, lower), adjective), \+ tr_is(foreign, w(W, lower), pronoun), !.
%% SEVERAL CAPITALISED WORDS NO LESSON KNOWS ARE ONE NAME, bare as well as
%% after a determiner: `Alexia Canestrari ha raccontato', `a Sky Tg24'.
%% What kept a bare run apart was `Sabato Mladic' -- a day and a surname --
%% and `sabato' is a word the lesson KNOWS, so a run of words it knows none
%% of cannot be that. The name is written as the source spelled its words.
%% A DATE IS A PHRASE: the day is its count and the month its noun, which
%% is how `il 20 gennaio' already read -- and the YEAR after the month is
%% the phrase's own, app(Phrase, year, Year), where it was an adjective in
%% digits and refused the phrase. Which nouns are months is the lesson's
%% (`"gennaio" is a month.'), and so is the word a language joins a date's
%% parts with (`The word "de" joins the date.': `el 20 de enero de 2014'),
%% which comes off before the phrase is read.
%% ... AND A YEAR SAID IN WORDS: `domenica mattina (9 luglio novantacinque)'
%% -- a number word after a month is the year, app(Phrase, yearw, Word), and
%% it crosses by its meaning where a year in digits is its digits. Read as
%% an adjective of the month it came out `(ninety-five July 9)'. ONE CLAUSE
%% FOR BOTH: two asked the last word of every phrase twice, about half a
%% per cent of every control.
tr_np(Side, Words, app(NP, K, w(Y, lower))) :-
    append(Core0, [w(Y, _)], Words), atom(Y),
    ( tr_digits(Y) -> \+ tr_percent(Y), K = year ; tr_is(Side, w(Y, lower), number), K = yearw ),
    ( append(Core, [J], Core0), tr_date_join(Side, J) -> true ; Core = Core0 ),
    last(Core, M), tr_month(Side, M),
    tr_np(Side, Core, NP), !.
%% A NOUN, THE WORD FOR `number' AND DIGITS ARE THE NOUN AND ITS NUMBER: `cruzó la
%% puerta de embarque número 24 una patrulla' is the boarding gate number 24, and
%% read as a label after a noun of two words, `the number boarding gate', the
%% digits were left a phrase of their own and the sentence was refused
%% (app(Phrase, numbered, Digits), each writer writing its word for number
%% between them)
tr_np(Side, Words, app(NP, numbered, w(N, NC))) :-
    nb_getval('$tr_numbered', yes),
    last(Words, w(N, NC)), atom(N), tr_digits(N), \+ tr_percent(N),
    append(Core, [w(NW, _), w(N, NC)], Words), Core = [_, _|_],
    atom(NW), tr_lexeme(Side, NW, NL, singular), atom(NL), tr_solve(mean(NL, number)), tr_class_of(NL, noun),
    last(Core, LW), tr_is(Side, LW, noun),
    tr_np(Side, Core, NP), NP = np(_, _, _, _, _), !.
%% A NUMBER AFTER A NOUN IS ITS LABEL: `el próximo día 14' is the day
%% numbered fourteen -- a date with its month left out, which a newspaper
%% writes when the month is this one. It travels as app(Phrase, label,
%% Number) and every writer puts the number back after the noun. Only after
%% a noun the lesson knows, so `el 20' and a count before its noun read as
%% they did.
tr_np(Side, Words, app(NP, label, w(N, NC))) :-
    append(Core, [w(N, NC)], Words), Core = [_, _|_], tr_digits(N), \+ tr_percent(N),
    last(Core, LW), tr_is(Side, LW, noun),
    tr_np(Side, Core, NP), NP = np(_, _, _, _, _), !.
%% ... AND A DAY WITH NO ARTICLE: `giovedì 20' in a newspaper's brackets --
%% a bare noun the lesson calls a time and the number that labels it
tr_np(Side, [w(D, DC), w(N, NC)], app(NP, label, w(N, NC))) :-
    atom(D), tr_digits(N), \+ tr_percent(N),
    tr_lexeme(Side, D, L, singular), tr_time_lexeme(Side, L), \+ tr_month(Side, w(D, DC)),
    tr_np(Side, [w(D, DC)], NP), NP = np(_, _, _, _, _), !.
%% A TITLE BEFORE A NAME IS A PHRASE: `monsignor Salvatore Cassisa',
%% `Monsignor Cassisa'. The lesson says which nouns are titles -- `"monsignore"
%% is a title.' -- because a title takes no article before a name in either
%% of the lesson's languages, and nothing else in the phrase says where it
%% begins. The name's words join as one, apposed to the title as `il
%% presidente Scalfaro' has its name, and each writer puts the title first.
tr_np(Side, [w(TW, _)|Ns], np(none, none, [w(A, upper)], w(TW, lower), singular)) :-
    Ns \== [], tr_title_word(Side, TW),
    %% every capitalised word after the title is the name's, one the lesson
    %% knows included: `Salvatore' is a rescuer in the vocabulary
    forall(member(N, Ns), N = w(_, upper)), !,
    findall(C, ( member(w(X, _), Ns), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', A).
%% (a word the lesson knows only as a VERB's form is a name's too, in a run
%% with a name in it: `interpretado por Carlos Cosías' -- `cosías' is what
%% `coser' says to one person, and the singer was no name at all)
tr_np(Side, [W1, W2|Ws], name(N)) :-
    forall(member(W, [W1, W2|Ws]), tr_name_part(Side, W)),
    once(( member(W0, [W1, W2|Ws]), tr_name_word(Side, W0) )), !,
    findall(C, ( member(w(X, _), [W1, W2|Ws]), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', N).
%% ... AND A NAME'S LATER WORDS MAY BE WORDS THE LESSON KNOWS, after a first
%% word no lesson does: `apoyará a Javier Solana' -- `solana' is a sunny
%% slope to the vocabulary, and the object was refused as a name and a
%% noun. A known FIRST word is what keeps `Sabato Mladic' a day and a
%% surname, and it still does.
%% ... OR ADJECTIVES: `de Òmnium Cultural, Josep Millàs,' -- `cultural' is
%% an adjective to the lesson, and the association's name was no name
tr_np(foreign, [W1, W2|Ws], name(N)) :-
    tr_name_word(foreign, W1),
    forall(member(W, [W2|Ws]), ( W = w(_, upper), ( tr_name_part(foreign, W) ; tr_is(foreign, W, noun) ; tr_is(foreign, W, adjective) ) )), !,
    findall(C, ( member(w(X, _), [W1, W2|Ws]), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', N).
%% ... AND A FIRST NAME THE LESSON KNOWS AS A NOUN AND SAYS IS A NAME TOO:
%% `Salvador Bellido' -- `salvador' is a saviour in the vocabulary
%% (`"salvador" is a name.'), and read as the noun with a surname apposed to
%% it the man crossed as `Soccorritore Bellido'. Every word after it is a
%% capital, as in the run above.
tr_np(foreign, [w(W1, upper), W2|Ws], name(N)) :-
    atom(W1), tr_solve(name(W1)),
    forall(member(W, [W2|Ws]), ( W = w(_, upper), ( tr_name_part(foreign, W) ; tr_is(foreign, W, noun) ; tr_is(foreign, W, adjective) ) )), !,
    findall(C, ( member(w(X, _), [w(W1, upper), W2|Ws]), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', N).
%% ENGLISH PUTS A BARE PARTICIPLE BEFORE ITS NOUN, and it is read there as
%% the reduced relative the writer made of it (tr_np_out/5): `the imposed
%% house' is `la casa imposta'. Only right before the noun, and never a word
%% a lesson gives as an adjective, which `tired' is.
tr_np(english, Words, rel(NP, L, [])) :-
    append(Pre, [w(P, PC), N], Words), Pre \== [],
    en_participle(P, L), \+ tr_is(english, w(P, PC), adjective), \+ en_own(P),
    append(Pre, [N], Words1), tr_np(english, Words1, NP), NP = np(_, _, _, w(_, _), _), !.
%% `LA UNA' IS ONE O'CLOCK: `entre la una y la 1.30 de la madrugada' is between one and 1.30 in the morning. The
%% hours are counts after the article (below), and the first of them is said with the word the lesson gives as the
%% article `a' and as nothing else, which the count does not take, so the pair had no first half and the sentence
%% was refused. The definite article and the indefinite one after it, both in the feminine singular, alone in the
%% phrase; it crosses as the count one (one/1, tr_cross_num/2)
tr_np(Side, [D, A], np(det(article, DL, D), one(A), [], elided(feminine), singular)) :-
    Side == foreign, A = w(AW, _), atom(AW), nb_getval('$tr_a_lexemes', ALs), memberchk(AW, ALs),
    tr_determiner(Side, A, AL, article), tr_solve(mean(AL, a)),
    tr_determiner(Side, D, DL, article), tr_solve(mean(DL, the)), \+ tr_standalone_det(Side, D),
    tr_det_gender(Side, D, DL, feminine, singular), tr_det_gender(Side, A, AL, feminine, singular), !.
%% A COUNT ALONE AFTER AN ARTICLE IS A PHRASE WHOSE NOUN WAS LEFT OUT, never
%% a noun by position: `se desarrolló entre las tres y las cinco de la
%% tarde' is between three and five, the hours left out, and read as the
%% noun `tres' the phrase was singular, `al tre'. The article says the gender
%% and the number, and every writer puts the count where the noun would have
%% been: `tra le tre e le cinque del pomeriggio'.
tr_np(Side, [D, M], np(det(DK, DL, D), M, [], elided(G), Number)) :-
    Side == foreign, tr_is(Side, M, number),          % the rare test first: it is asked of every two words
    tr_determiner(Side, D, DL, DK), DK == article, \+ tr_standalone_det(Side, D),
    tr_det_gender(Side, D, DL, G, Number), Number == plural, !.
%% ... AND ONE AFTER AN ADJECTIVE OF ORDER: `(gli ultimi tre, esponenti della banda di Montespaccato)' are the last
%% three of the names before the bracket -- with the adjective between the article and the count the phrase had no
%% reading, and the sentence of the eleven names was refused
tr_np(Side, [D, A, M], np(det(DK, DL, D), M, [A], elided(G), plural)) :-
    Side == foreign, tr_is(Side, M, number), A = w(AW, lower), atom(AW),
    tr_lexeme(Side, AW, AL, plural), tr_solve(mean(AL, E)), en_order_adjective(E),
    tr_determiner(Side, D, DL, DK), DK == article, tr_det_gender(Side, D, DL, G, plural), !.
%% ... AND DIGITS AND A NUMBER WORD, WITH NOTHING AFTER THEM: `mentre altri
%% 70 mila lasceranno la città' is another seventy thousand, the people left
%% out -- the number word read as the phrase's noun was a thousand, singular,
%% and the plural verb had no subject that agreed. It is a count in the
%% plural with its noun left out, as one after an article is above
%% (and with a determiner before them, `altri 70 mila', in its own words; never a number
%% word that is a noun too, a magnitude: `230 millones de pesetas' is 230 million pesetas,
%% and read as a count with its noun left out it was `230 million of pesetas', `230 milione')
tr_np(Side, [M1, M2], np(none, numw(M1, M2), [], elided(masculine), plural)) :-
    Side == foreign, M1 = w(D1, _), atom(D1), tr_digits(D1), M2 = w(D2, _), atom(D2), \+ tr_digits(D2),
    tr_is(Side, M2, number), \+ tr_is(Side, M2, noun), !.
tr_np(Side, [D, M1, M2], np(det(DK, DL, D), numw(M1, M2), [], elided(masculine), plural)) :-
    Side == foreign, M1 = w(D1, _), atom(D1), tr_digits(D1), M2 = w(D2, _), atom(D2), \+ tr_digits(D2),
    tr_is(Side, M2, number), \+ tr_is(Side, M2, noun), tr_determiner(Side, D, DL, DK), !.
%% ... AND ONE WITH AN ADJECTIVE THAT JUDGES AFTER IT, WHAT IS SO: `Pero lo
%% cierto es que las candidatas sólo han tenido 10 minutos' -- what is certain is
%% that. The word the lesson says replaces a noun and no relative word had a
%% clause to end the phrase: `lo' was the pronoun him and `cierto' a word with
%% nothing to be said of, and the sentence was refused. It travels as the phrase
%% of `lo que es cierto' (tr_np/3 below, the clause with the copula and the
%% adjective) in the present, which is the tense of nearly every such phrase;
%% only an adjective that judges (en_judging/1: `lo mismo' is the same thing,
%% `lo primero' the first, and neither is what is the same)
tr_np(foreign, [Q, A], ell(det(article, what, Q), masculine, singular,
                           rel(subject, s(none, gap(third, singular), g(CL, present, simple, no), [adj([A])])))) :-
    A = w(AW, AC), memberchk(AC, [lower, qboth]), atom(AW),
    tr_noun_replacer(foreign, Q), Q = w(QW, _), tr_lexeme(foreign, QW, QL, singular), tr_gender(QL, none),
    tr_judging_adjective(A), tr_copula_lexeme(CL), !.
%% ... AND THE WORD FOR `more' AND AN ADJECTIVE BETWEEN THEM: `Lo más formidable de esta rápida
%% transformación es que ...' is the most formidable THING about it. The word that replaces a noun and a
%% superlative are the phrase of the lesson's noun for `thing' (`la cosa más formidable'), so that English
%% writes `the most formidable thing' and the lesson's languages `la cosa più formidabile'; read as
%% `what is more formidable' it was `what is important is more that ...' (the adverb after the clause)
tr_np(foreign, [Q, w(M, MC), A], np(Det, none, [deg(superlative, A)], w(N, lower), singular)) :-
    nb_getval('$tr_replacer', yes),
    A = w(AW, AC), memberchk(AC, [lower, qboth]), atom(AW), atom(M), memberchk(MC, [lower, qopen]),
    tr_noun_replacer(foreign, Q), Q = w(QW, _), tr_lexeme(foreign, QW, QL, singular), tr_gender(QL, none),
    tr_degree_word(M), tr_is(foreign, A, adjective),
    tr_thing_phrase(Det, N), !.
%% ... AND AFTER THE COMPLEMENTS HAVE FOLDED ITS DEGREE (tr_degrees/4: `más alto' is the adjective with its degree, the
%% article after it deciding the superlative): `colocar al club en lo más alto' puts the club at the top, `habla de lo
%% mejor' of the best -- read with `lo' for the pronoun and the adjective for a comparative of the verb, `eats him higher'
tr_np(foreign, [Q, deg(D, A)], np(Det, none, [deg(Sup, A)], w(N, lower), singular)) :-
    A = w(AW, AC), memberchk(AC, [lower, qboth]), atom(AW),
    ( ( D == comparative ; D == superlative ) -> Sup = superlative ; D = less(_), Sup = less(superlative) ),
    tr_noun_replacer(foreign, Q), Q = w(QW, _), tr_lexeme(foreign, QW, QL, singular), tr_gender(QL, none),
    tr_is(foreign, A, adjective),
    tr_thing_phrase(Det, N), !.

%% A WORD THAT REPLACES THE NOUN, WITH ADJECTIVES AFTER IT: `rispetto a
%% quelli esistenti' is compared with the existing ones. `esistente' is an
%% adjective and nothing else, and read as the phrase's noun by position
%% after the demonstrative it came out `esos existentes', those existents;
%% it is the article's phrase with its noun left out, as `el más débil' is
%% (tr_np/3 below), and it comes before the reader that takes a noun by
%% position.
%% -- and one adjective alone after it, though the lesson calls it a noun
%% too: `sia il mondo greco che quello cristiano' is the Christian one, and
%% read as the demonstrative before the noun `cristiano' it was `ese
%% cristiano', that Christian (Italian's determiner there is `quel')
%% (so never the form that stands only before a noun, the lesson's apocope
%% and its plural: `ma quei morti per le strade' is those dead, and read as
%% the ones left out and an adjective it lost its demonstrative, `los
%% muertos')
tr_np(foreign, [Q|Ws], np(det(article, AL, Q), none, Ws, elided(G), Number)) :-
    Ws \== [], tr_noun_replacer(foreign, Q), Q = w(QW, _),
    \+ tr_solve(apocope_of(QW, _)), \+ ( tr_solve(plural_of(QW, QS)), tr_solve(apocope_of(QS, _)) ),
    (   Ws = [A1], A1 = w(_, _) -> tr_is(foreign, A1, adjective)
    ;   forall(member(A, Ws), ( A = w(_, _), tr_is(foreign, A, adjective), \+ tr_is(foreign, A, noun) ))
    ),
    tr_lexeme(foreign, QW, L, Number), tr_gender(L, G0), ( G0 == none -> G = masculine ; G = G0 ),
    once(( tr_solve(mean(AL, the)), tr_class_of(AL, article) )), !.
%% A COUNT AND ADJECTIVES WITH NO NOUN: `el reparto de las 33 licencias (21
%% nuevas y 12 renovaciones)' is twenty-one new ones, the licences left out.
%% Taken by its place, `nuevas' was the noun, and English wrote `21 news'.
%% With no article, the adjectives say the gender, their own, and the count
%% and the adjectives say the number.
tr_np(foreign, [M|Ws], np(none, M, Ws, elided(G), plural)) :-
    Ws = [w(AW, _)|_], tr_is(foreign, M, number),
    forall(member(A, Ws), ( A = w(_, _), tr_is(foreign, A, adjective), \+ tr_is(foreign, A, noun) )),
    tr_lexeme(foreign, AW, AL, plural), ( tr_gender(AL, G0), G0 \== none -> G = G0 ; G = masculine ), !.
%% A DAY AND ITS PART ARE ONE TIME: `domenica mattina' is Sunday morning --
%% two nouns the lesson calls times (`"mattina" is a time.'), with no
%% article and no preposition between them. Read as one phrase, `mattina'
%% was an adjective of the day, and Spanish wrote `mañana domingo', which
%% says TOMORROW Sunday. It travels as app(Day, part, Part), and the word a
%% language joins the two with is the lesson's, in the shape the date's has
%% (`The word "por" joins the time.'): a language that joins them writes
%% each with its article, `el domingo por la mañana', and one that does not
%% writes them bare, `domenica mattina', `sunday morning'. Read back, the
%% join and the two articles come off again (tr_time_part_after/5).
tr_np(Side, [D, P], app(np(none, none, [], D, singular), part, np(none, none, [], P, singular))) :-
    D = w(DW, _), P = w(PW, _), tr_time_word(Side, PW), tr_time_word(Side, DW), !.
%% A NOUN AFTER A NOUN, IN ITS NUMBER, SAYS WHAT KIND IT IS: `los
%% muchachotes hinchas del equipo inglés' are big lads who are fans. The
%% reader below takes adjectives after the noun and no second noun, so the
%% phrase was no phrase and the sentence was refused with every word known.
%% The second noun travels among the adjectives as nmod(Word); the lesson's
%% writer puts it after the noun in the phrase's number, English's before
%% it in the singular, as English's own compounds have it -- `the fan lads'.
%% Only a determiner, the noun and a second noun that is no adjective; a
%% verb's form the lesson calls a noun too is left to the statement reader,
%% which tries the verb first: `La madre ama a su hijo' is the mother loving.
%% ... AND A FIRST NOUN THAT IS NO ADJECTIVE EITHER: an adjective before its
%% noun is the commoner shape, and read as a noun it was the head -- `un
%% esnob bate' came out `uno snob mazza', `una ejemplar escena' `una copia
%% scena', `otro brillante jalón' `altro brillante pietra miliare', `un
%% segundo encuentro' `un secondo riunione'
%% (the second noun asked first, and the determiner last: the clause is
%% tried on every three words a phrase could be, and asked the other way
%% round it cost a sentence of the twelve 99 000 inferences, 2.5 %)
%% ... AND ONE THAT IS NO NUMBER: `tra i dieci e i venti milioni' is
%% between ten and twenty million, and `venti' is the plural of `vento' too
%% -- read as a noun, it came out `los vientos millones', the winds
%% ... AND A SECOND NOUN THAT IS NO THIRD PERSON OF A VERB IN THE PHRASE'S
%% NUMBER: `Al sud l'università costa meno e non credo possa costare di più'
%% is the university costing less, and where the verb read first failed on
%% the rest of the piece the reader went on to `possa', with `l'università
%% costa' a coast university for its subject. A noun and then the verb that
%% agrees with it is a subject and its verb. Only in the singular: a plural
%% noun is a verb's plural only through the noun's own plural -- `hinchas'
%% is the fans, and the verb's is `hinchan' -- and asked of the plural too,
%% the guard shut out `los muchachotes hinchas', which the England column
%% reads (and tr_form/5 answers any known word as its own third singular,
%% so it is asked of the word the lesson calls a verb).
%% ... AND A SECOND NOUN IN QUOTATION MARKS: `lo stabilimento "miraggio"' is
%% the bathing establishment called Mirage, and the marks, which travel in
%% the word's case, let the adjectives take it -- written before its noun,
%% `el "espejismo" establecimiento'
%% AN ARTICLE BEFORE AN INFINITIVE MAKES A NOUN OF IT: `Quale era allora la
%% materia del contendere ai tempi di Colombo?' is the matter of the
%% contending, and `contendere' is no noun the lesson gives, so the phrase
%% had no reading and the question was refused. The definite article and a
%% verb's infinitive, the verb no noun, travel as ninf(Lexeme): the lesson's
%% language writes the masculine singular article and the infinitive (`el
%% contender', which the contraction makes `del contender'), English `the'
%% and the gerund
%% (the infinitive asked first: every two words the phrase reader is given
%% reach this clause, and few second words are an infinitive)
%% ... AND A QUOTED WORD AFTER AN ARTICLE IS THE WORD SAID: `Il "qui" di cui
%% parla, al telefono, Alessandro Cecchi Paone, è un albergo discreto' -- the
%% "here" he speaks of. The lesson knows `qui' as an adverb, which no phrase
%% takes for its noun, and the article with the word in its marks travels as
%% nq/2: crossed and written as the adverb it is, in the same marks
tr_np(foreign, [D, w(W, qboth)], nq(det(DK, DL, D), w(W, qboth))) :-
    atom(W), D = w(DW, _), atom(DW), tr_determiner(foreign, D, DL, DK), DK == article,
    tr_is(foreign, w(W, lower), adverb), \+ tr_is(foreign, w(W, lower), noun), !.
tr_np(foreign, [D, w(V, _)], ninf(F)) :-
    atom(V), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    D = w(DW, _), atom(DW), tr_determiner(foreign, D, DL, article), tr_solve(mean(DL, the)),
    \+ tr_is(foreign, w(V, lower), noun),
    tr_det_gender(foreign, D, DL, G, singular), G \== feminine, !.
tr_np(foreign, [D, N, M], np(det(DK, DL, D), none, [nmod(M)], N, Number)) :-
    M = w(MW, MC), memberchk(MC, [lower, qboth]), tr_is(foreign, w(MW, lower), noun), \+ tr_is(foreign, w(MW, lower), adjective),
    N = w(NW, _), tr_is(foreign, N, noun), \+ tr_is(foreign, N, adjective), \+ tr_is(foreign, N, number),
    D = w(_, _), tr_determiner(foreign, D, DL, DK),
    tr_lexeme(foreign, NW, NL, Number), tr_class(foreign, NL, noun),
    tr_lexeme(foreign, MW, ML, Number), tr_class(foreign, ML, noun),
    \+ ( Number == singular, tr_verb_lexeme(MW) ),
    %% (... AND A SECOND NOUN THAT IS NO PREPOSITION: `al ministro delle poste contro "generale per una sera"' is
    %% the question against the programme, and `contro' is a noun too, the con of pros and cons -- read as the
    %% kind of mail, English wrote `the con mails')
    \+ tr_is(foreign, w(MW, lower), preposition), !.
%% ... AND TWO BARE NOUNS, a headline's: `Ciampi boccia legge inappellabilità' is
%% Ciampi rejecting the law on unappealability, and read with the second as an
%% adjective of the first -- the reading the general clause below gives any
%% word that is no preposition, pronoun or verb -- the lesson's writer, which
%% puts a word before its noun where no rule says an adjective follows it,
%% wrote `inapelabilidad ley'. It is the same compound with no determiner and
%% in the singular, and it is written as the other is, after the noun. A
%% determiner is no first noun: `este hombre' is this man and `este' is east
%% too, and the compound took the east for the noun (`Man east is died', where
%% Tatoeba's `Este hombre está muerto.' had read `This man is died.')
tr_np(foreign, [N, M], np(none, none, [nmod(M)], N, singular)) :-
    M = w(MW, lower), tr_is(foreign, M, noun), \+ tr_is(foreign, M, adjective),
    N = w(NW, lower), tr_is(foreign, N, noun), \+ tr_is(foreign, N, adjective), \+ tr_is(foreign, N, number),
    \+ tr_determiner(foreign, N, _, _),
    tr_lexeme(foreign, NW, NL, singular), tr_class(foreign, NL, noun),
    tr_lexeme(foreign, MW, ML, singular), tr_class(foreign, ML, noun),
    \+ tr_verb_lexeme(MW), !.
%% A PLURAL NOUN AFTER A NOUN AND ITS ADJECTIVE IS THE NAME'S TAIL, ITS `of'
%% LEFT OUT: `l'associazione nazionale magistrati' is the National
%% Association OF Magistrates, an institution's name that Italian writes with
%% no `di'. Read as adjectives it was `la magistrada asociación nacional', and
%% after `secondo' at the head of a sentence, before a comma, nothing read it
%% at all, so the sentence was taken for the association's own -- it was the
%% association that needed to read. It travels among the adjectives as
%% nmodp(Word), the noun's plural kept: `the national magistrate association',
%% `la asociación nacional magistrados'. Only a determiner, a noun, an
%% adjective that follows it and a plural noun that is no verb's form and
%% that the lesson calls a person: an institution's members (`magistrati',
%% `giornalisti', `consumatori'), where `comitato etico tempi e modi' is
%% no name's tail
tr_np(foreign, [D, N, A, M], np(det(DK, DL, D), none, [A, nmodp(M)], N, singular)) :-
    D = w(_, _), N = w(NW, _), A = w(AW, AC), M = w(MW, lower),
    memberchk(AC, [lower, qboth]),
    tr_determiner(foreign, D, DL, DK),
    tr_lexeme(foreign, NW, NL, singular), tr_class(foreign, NL, noun), \+ tr_is(foreign, N, adjective),
    tr_lexeme(foreign, MW, ML, plural), tr_class(foreign, ML, noun), \+ tr_verb_lexeme(MW), tr_holds(person(ML)),
    tr_lexeme(foreign, AW, AL, singular), tr_class(foreign, AL, adjective), \+ tr_is(foreign, A, noun),
    tr_adj_word(foreign, A), !.
%% A RATIO: `una famiglia su cinque' is one family in five and `un nucleo
%% ogni venti' one household in every twenty -- what Spanish says `una de
%% cada cinco familias', which tr_np/3 below reads as one of each five
%% families (the indefinite article and a `de' phrase), so it is read as
%% that: the indefinite article, the noun it takes, a word that means `on'
%% or `each' and then a count, and nothing else. The noun is the phrase's
%% plural, the `of' and the `each' the lesson's own words for them. Read as
%% a family and a phrase of `on' it was `una familia en cinco', and
%% `ogni' and `venti' among the adjectives of `un nucleo'.
tr_np(foreign, [D, N0, R, M], ell(det(DK, DL, D), G, singular,
                                  pp(w(PW, lower), np(det(determiner, EL, w(EW, lower)), M, [], w(NPl, lower), plural)))) :-
    tr_ratio_count(M),
    R = w(RW, _), atom(RW), tr_lexeme(foreign, RW, RL, _),
    (   tr_class_of(RL, preposition), tr_solve(mean(RL, on))
    ->  once(( tr_solve(mean(EL, each)), tr_class_of(EL, determiner) )), EW = EL
    ;   tr_class_of(RL, determiner), tr_solve(mean(RL, each)), EL = RL, EW = RW
    ),
    D = w(_, _), tr_determiner(foreign, D, DL, DK), DK == article, tr_indefinite(foreign, D),
    N0 = w(NW, lower), atom(NW), tr_lexeme(foreign, NW, NL, singular), tr_class_of(NL, noun),
    tr_det_gender(foreign, D, DL, G, singular), tr_gender(NL, NG), ( G == none ; NG == none ; NG == G ),
    once(( tr_solve(mean(PW, of)), tr_class_of(PW, preposition) )),
    tr_number_form(NL, plural, NPl), !.
%% A PARTICIPLE BEFORE ITS NOUN IS SAID OF IT AS AN ADJECTIVE BEFORE ITS
%% NOUN IS: `el esperado regreso' is the awaited return, and `proclamó un
%% emocionado Bruno Metsu' a thrilled Bruno Metsu. After its noun a
%% participle is a reduced relative (rel/3), which English writes before the
%% noun when it is bare; before the noun the phrase had no reading at all,
%% because the lesson gives the word no adjective. It travels among the
%% phrase's adjectives as pptc(Lexeme), and each writer puts its own
%% participle there, agreeing with the noun: `un emozionato Bruno Metsu'.
%% Two joined by a coordinator are two, `un rendido y entregado Roger
%% Lemerre', and an adjective after the coordinator is the phrase's own.
%% Never a word the lesson gives as an adjective or a noun, which the
%% phrase's own clauses read (`el dicho comité', `el herido').
%% (ONLY IN A SENTENCE THAT HAS ONE AFTER A DETERMINER, which a note says,
%% made once in tr_into_ir/4: asked of every phrase that opens on a
%% determiner, the clause cost the controls 5.4 million inferences over
%% seven Italian sentences -- Salvini's twenty-fifth 3.1 million of them --
%% and a participle anywhere was no note at all: nearly every sentence has
%% a perfect's, `ha dejado', `hemos puesto')
tr_np(foreign, [D, W|Ws], np(Det, Num, Adjs, Noun, Number)) :-
    nb_getval('$tr_pptc', yes),
    Ws = [_|_], W = w(P, lower), atom(P), tr_determiner(foreign, D, _, _),
    tr_pre_participles([W|Ws], Pre, Rest), Rest = [_|_],
    tr_np(foreign, [D|Rest], np(Det, Num, Adjs0, Noun, Number)), Noun \= elided(_),
    forall(member(_-N, Pre), ( N == none ; N == Number )),
    findall(X, member(X-_, Pre), Pre1), append(Pre1, Adjs0, Adjs), !.
%% AN ADJECTIVE ALONE IS A PHRASE WHOSE NOUN WAS LEFT OUT, with no article to
%% say so where the lesson knows the word as no noun: `la transformación en
%% peatonal del tramo' is into pedestrian -- a street left out -- and read as
%% a noun it crossed by the noun's meaning, `in pedone', a person who walks
tr_np(foreign, [A], np(none, none, [A], elided(G), Number)) :-
    A = w(W, lower), atom(W), tr_is(foreign, A, adjective),
    \+ tr_is(foreign, A, noun), \+ tr_is(foreign, A, pronoun), \+ tr_is(foreign, A, adverb),
    \+ tr_determiner(foreign, A, _, _), \+ tr_participle_here(foreign, W, _),
    tr_adjective_agreement(A, G, Number0), ( Number0 == plural -> Number = plural ; Number = singular ), !.
tr_np(Side, Words00, np(Det, Num, AdjsM, Noun, Number)) :-
    tr_tail_name(Side, Words00, Words0),
    %% A POSSESSIVE AFTER AN ARTICLE IS THE PHRASE'S DETERMINER: `la sua
    %% casa' is his house, which Spanish writes `su casa' and Italian, whose
    %% lesson says `The article "il" takes the possessive', with the article
    %% back in front. Read as an adjective it was `la su identidad', and it
    %% crossed by the adjective's meaning -- `sua' is `hers' as one
    (   Side == foreign, Words0 = [A0, P0|Ws1], Ws1 \== [],
        tr_determiner(Side, A0, _, article), tr_determiner(Side, P0, PL, possessive)
    ->  Det = det(possessive, PL, P0), Words1 = Ws1
    %% A DETERMINER THE LESSON CALLS AN ADVERB TOO, BEFORE A NUMBER, IS THE
    %% COUNT'S ADVERB: `unos 980 trabajadores' is about 980 of them (`The
    %% adverb "unos" means "about".'), and read as the article it came out
    %% `dei 980 lavoratori', which no Italian writes
    ;   Words0 = [D, M|Ws1], Ws1 \== [], D = w(_, _), tr_is(Side, D, adverb), tr_is(Side, M, number),
        tr_determiner(Side, D, _, _)
    ->  Det = none, Words1 = Words0
    %% ... AND BEFORE AN ADJECTIVE IT DOES NOT AGREE WITH, IT IS THE
    %% ADJECTIVE'S: `in serissime storie della scienza' is in very serious
    %% histories -- the tokeniser unfolds the superlative to `molto serie',
    %% and `molto', the masculine singular determiner `much', cannot stand
    %% before the feminine plural `serie'. Read as the determiner it came out
    %% `muchas serias historias'. A human writes the same: `molto belle cose'
    %% is very beautiful things, the determiner being `molte'
    ;   Side == foreign, Words0 = [D, J|Ws1], Ws1 \== [], D = w(DW, _), atom(DW),
        J = w(JW, _), atom(JW), tr_adverb_word(Side, D),
        tr_determiner(Side, D, DL, _), tr_det_gender(Side, D, DL, DG, DN),
        tr_lexeme(Side, JW, JL, JN), tr_class_of(JL, adjective),
        (   JN \== DN -> true
        ;   DG \== none, ( tr_holds(feminine(JW)) -> JG = feminine ; tr_holds(masculine(JW)) -> JG = masculine ), JG \== DG
        )
    ->  Det = none, Words1 = Words0
    ;   Words0 = [D|Ws1], tr_determiner(Side, D, DL, DK), Ws1 \== []
    ->  Det = det(DK, DL, D), Words1 = Ws1
    ;   Det = none, Words1 = Words0
    ),
    %% the count is the number before the noun -- at the head of what is left
    %% after the determiner, or, since 1.6.14, ANYWHERE among the adjectives
    %% before it: `solo due anni' is `only two years', and with the number
    %% left among them the writer asked the lesson for an ADJECTIVE meaning
    %% `two' and the phrase could not be written at all
    %% ... and a count may carry an adverb before it or be two numbers
    %% joined: `a meno 5 gradi' (at minus five degrees), `con oltre 50 mezzi',
    %% `bambini di 4 e 5 anni'
    %% (the count's adverb is NA and not A: the forall below names its own
    %% A, and with the adverb bound to it `member(A, Adjs)' matched nothing,
    %% so every adjective after such a count passed unchecked)
    %% ... and the adverb stands before a PAIR of them: `unos 5.000 o 6.000
    %% millones' is about five or six thousand million -- the phrase gave up
    %% at the `o' left after the first, and `unos' was the article, `dei 5.000
    %% o 6.000 milioni'
    (   Words1 = [NA|Rest1], NA = w(_, _), tr_is(Side, NA, adverb), \+ tr_is(Side, NA, adjective),
        (   Rest1 = [M1, NC, M2|Ws2], tr_is(Side, M1, number), tr_coord(Side, NC), tr_is(Side, M2, number), Ws2 \== []
        ->  Num = adv_num(NA, nums(M1, NC, M2)), Words2 = Ws2
        %% (and digits with their number word, one count after the adverb as
        %% without it: `più o meno 290 mila vetture', where `mila' read as an
        %% adjective of the noun came out `290 miles coches')
        ;   Rest1 = [M1, M2|Ws2], M1 = w(D1, _), atom(D1), tr_digits(D1), M2 = w(D2, _), atom(D2), \+ tr_digits(D2),
            tr_is(Side, M2, number), \+ tr_is(Side, M2, noun), Ws2 \== []
        ->  Num = adv_num(NA, numw(M1, M2)), Words2 = Ws2
        ;   Rest1 = [M|Ws2], tr_is(Side, M, number), Ws2 \== []
        ->  Num = adv_num(NA, M), Words2 = Ws2
        )
    ->  true
    ;   Words1 = [M1, NC, M2|Ws2], tr_is(Side, M1, number), tr_coord(Side, NC), tr_is(Side, M2, number), Ws2 \== []
    ->  Num = nums(M1, NC, M2), Words2 = Ws2
    %% ... or digits and a number word, ONE count: `il milione e 200 mila
    %% lire' is two hundred thousand of them, and `mila' read as an adjective
    %% of the noun came out `200 miles liras', a plural of thousands
    ;   Words1 = [M1, M2|Ws2], M1 = w(D1, _), atom(D1), tr_digits(D1), M2 = w(D2, _), atom(D2), \+ tr_digits(D2),
        tr_is(Side, M2, number), Ws2 \== []
    ->  Num = numw(M1, M2), Words2 = Ws2
    ;   Words1 = [M|Ws2], tr_is(Side, M, number), Ws2 \== []
    ->  Num = M, Words2 = Ws2
    ;   append(Pre1, [M|Post1], Words1), tr_is(Side, M, number), Post1 \== [],
        forall(member(X1, Pre1), tr_adj_word(Side, X1))
    ->  Num = M, append(Pre1, Post1, Words2)
    ;   Num = none, Words2 = Words1
    ),
    Words2 \== [],
    %% (and no phrase opens on a coordinator, which joins two things and
    %% begins neither: `y no son reales' above)
    \+ ( Words2 = [C2w|_], C2w = w(_, _), tr_coord(Side, C2w) ),
    tr_date_day(Side, Num, Words2, Words2d0),
    tr_noun_adverb(Side, Det, Words2d0, Words2d),
    tr_intensify(Side, Words2d, Words3a), tr_focus_ints(Side, Words3a, Words3),
    tr_plural_hint(Side, Det, Num, PluralHint),
    tr_noun(Words3, Side, PluralHint, Noun0, Adjs0),
    %% A COORDINATOR AMONG THE ADJECTIVES JOINS TWO OF THEM, never one to a
    %% noun: `donna e bimbi scomparsi' is two phrases, and read as one whose
    %% adjectives were `and' and `children' it was a singular subject, which
    %% the plural headline participle before it (`ritrovati') refused
    \+ ( append(_, [Co, X|_], Adjs0), tr_coord(Side, Co), X = w(_, _),
         tr_is(Side, X, noun), \+ tr_is(Side, X, adjective) ),
    %% ... nor one standing NEXT TO the noun, which joins an adjective to the
    %% noun itself: `Egoista e vigliacca, continuerà ...' is selfish and
    %% cowardly, a front that says what the subject is (tr_read0/4), and read
    %% as the noun `egoist' with `and' and `cowardly' for adjectives it was the
    %% subject of `continuerà' -- the clause's own subject, which nobody named
    \+ ( ( append(_, [Noun0, Co2|_], Words3) ; append(_, [Co2, Noun0|_], Words3) ), Co2 = w(_, _), tr_coord(Side, Co2) ),
    %% A NAME RIGHT AFTER THE DETERMINER, BEFORE A WORD THAT IS AN ADJECTIVE
    %% TOO, IS THE PHRASE'S HEAD where the language sets its adjectives after
    %% the noun: `potrebbe diventare la Houston italiana' is the Italian
    %% Houston, and read with `italiana' -- an Italian woman -- for the noun
    %% and the city set before it, it came out `al italiano Houston', a
    %% person with the word before a person in front. The clause for
    %% adjectives after a name reads it
    \+ ( Side == foreign, Words3 = [NW1, Noun0|_], NW1 = w(_, upper), tr_name_word(Side, NW1),
         tr_is(Side, Noun0, adjective), tr_holds(follow(_, noun)) ),
    tr_degree_of(Side, Det, Degree), tr_degrees(Side, Degree, [Noun0|Adjs0], [Noun|Adjs]),
    %% `The' alone is no phrase, whatever `el' means -- UNLESS the lesson
    %% also calls the word a noun or a pronoun, which is what `uno' is in
    %% `uno dei paesi': the masculine article and the word for `one'
    \+ ( tr_determiner(Side, Noun, _, _), \+ tr_is(Side, Noun, noun), \+ tr_is(Side, Noun, pronoun) ),
    \+ ( \+ tr_is(Side, Noun, noun), tr_is(Side, Noun, verb) ),   % nor is a verb's form the lesson calls no noun (`son grandes')
    %% nor a word the word for `very' stands before, which is an adjective:
    %% `el altísimo Gandalf' is the very tall Gandalf -- the tokeniser unfolds
    %% the superlative to `muy alto', and `alto' is a noun too, the height, to
    %% which the name was apposed and which nothing could write
    \+ ( Side == foreign, append(_, [I1, Noun|_], Words2d0), I1 = w(_, _), tr_intensifier(Side, I1, Noun) ),
    \+ ( \+ tr_is(Side, Noun, noun), tr_is(Side, Noun, adverb) ), % nor a word known only as an adverb (`Después, en ...')
    %% nor a pronoun that stands before a verb and is no noun: `un ayer que
    %% marcó época y estrellas de las ondas de hoy se reunieron' -- read as a
    %% phrase, `se' was `one', the relative clause's second object, and the
    %% clause ran on over the rest of the subject
    %% (a clitic is a pronoun to the lesson, and that is kept for the
    %% sentence: asked first, it spares the clitic's own lookups for every
    %% word that is no pronoun)
    \+ ( Side == foreign, \+ tr_is(Side, Noun, noun), tr_is(Side, Noun, pronoun), Noun = w(NW0, _), atom(NW0), tr_clitic(none, NW0) ),
    %% nor an AUXILIARY or a modal the lesson calls no noun: `han mejorado'
    %% after a relative clause read as a phrase `han' with the participle
    %% on it, `the has improved', and the clause ran on past its own verb
    \+ ( \+ tr_is(Side, Noun, noun), ( tr_is(Side, Noun, auxiliary) ; tr_is(Side, Noun, modal) ) ),
    %% nor a CONJUNCTION the lesson calls nothing a phrase can be: `senza
    %% rendersi conto che, come il loro predecessore, non importa ...' read
    %% `che' as a phrase, `what', and the rest as a clause about how
    \+ ( Side == foreign, tr_is(Side, Noun, conjunction),
         \+ tr_is(Side, Noun, noun), \+ tr_is(Side, Noun, pronoun), \+ tr_is(Side, Noun, adjective) ),
    %% nor an ADJECTIVE that is no noun after an article: `l'altra' is the
    %% other one, a noun left out, which the clause further down reads and
    %% writes agreeing -- taken for the noun here it came out `el otro'
    \+ ( Det = det(article, _, _), \+ tr_is(Side, Noun, noun), tr_is(Side, Noun, adjective) ),
    forall(member(A, Adjs), ( tr_adj_word(Side, A) ; tr_apposed_name(Side, Det, Words0, A) )),
    \+ ( last(Adjs, LA), LA = w(_, _), tr_coord(Side, LA) ),       % a conjunction joins two adjectives, never ends them
    %% AN ADVERB THAT IS AN ADJECTIVE'S FORM TOO, AFTER THE NOUN AND IN THE
    %% OTHER GENDER, IS THE ADVERB: `il giorno prima caricò i compagni' is the
    %% day before, and read with `prima' -- first, feminine -- for an
    %% adjective of the masculine `giorno' it was the first day, which loaded
    %% the team-mates
    \+ ( Side == foreign, append(_, [Noun|After], Words3), member(A, After), A = w(_, _),
         tr_is(Side, A, adverb), tr_is(Side, A, adjective), tr_genders_differ(Noun, A) ),
    Noun = w(NW, _),
    %% A CAPITALISED NOUN NO READING OF ITS DETERMINER CAN TAKE IS NO NOUN OF
    %% IT: `Evacuata la Tate Gallery.' was refused once `"tate" is the plural
    %% of "tata".' came into the lesson -- `la Tate' read as the article and
    %% the babysitters, with `Gallery' apposed to them, and nothing could
    %% write it. `la' is singular, so the run is the name the clause below
    %% reads (a noun in small letters keeps the reading it had)
    %% (on the lesson's side: English's `the' says no number)
    \+ ( Side == foreign, Noun = w(_, upper), Det = det(_, DL0, D0),
         \+ ( tr_det_gender(Side, D0, DL0, _, DN), ( var(DN) -> true ; tr_noun_in_number(Side, NW, DN) ) ) ),
    %% the noun's number by the reading of it that IS a noun: `houses' is a
    %% verb's form too (to house), and known so before it is a plural
    ( tr_lexeme(Side, NW, NL, Number0), tr_class(Side, NL, noun) -> true ; tr_lexeme(Side, NW, _, Number0) ),
    tr_invariable_number(Side, NW, Det, Adjs, Number0, Number1),
    %% (and so does a count above one: `Tre recital di straordinaria malia'
    %% are three recitals, and the singular it read first came out `Three
    %% recital')
    %% (never the unit of a percentage, which every language here writes the same in both numbers: `l'87 per cento')
    (   Number1 == singular, Num \== none, tr_plural_count(Side, Num), tr_lexeme(Side, NW, _, plural),
        \+ ( tr_lexeme(Side, NW, NL1, _), tr_solve(mean(NL1, PCM)), memberchk(PCM, ['per cent', percent]) )
    ->  Number = plural
    ;   Number = Number1
    ),
    %% A PHRASE WITH NO DETERMINER AGREES WITH THE ADJECTIVE AFTER ITS NOUN:
    %% `e quindi fosse pazzesco tentare di ...' -- `fosse' is the plural of
    %% `fossa' and the subjunctive of the copula, and read as a bare phrase the
    %% pits were `pazzesco', a singular whose plural the lesson states
    %% (`pazzeschi'). Only with no determiner, which would say the number
    %% -- and only a noun that is a verb's form too, which is what the other
    %% reading is: `con un bagaglio di esperienze, punti di vista e competenze
    %% unico al mondo' has the adjective agree with the baggage, before the
    %% list, and refused here the phrase had no reading and Fiat's sentence
    %% with it
    \+ ( Side == foreign, Det == none, Number == plural, tr_is(Side, Noun, verb),
         append(_, [Noun|After2], Words3), member(A2, After2), A2 = w(AW2, _), atom(AW2),
         tr_singular_adjective(AW2) ),
    %% AN ADJECTIVE THE SOURCE SET BEFORE ITS NOUN STAYS BEFORE IT, where the
    %% language puts adjectives after the noun and so a word before one was a
    %% choice: `una paradójica educación familiar', `la sacrosanta
    %% institución'. It travels as pre(Adjective) and the lesson's writer
    %% puts it before the noun whatever its rule says; English puts every
    %% adjective there anyway.
    (   Side == foreign, tr_holds(follow(_, noun)), append(PreWs, [Noun|_], Words3), PreWs \== []
    ->  tr_mark_pre(Side, Adjs, PreWs, AdjsM)
    ;   AdjsM = Adjs
    ), !.
%% AN ARTICLE BEFORE A NAME IS A PHRASE WHOSE NOUN IS THE NAME, and Italian
%% puts one there far more often than English does -- `la Tate Gallery', `la
%% Sidoti'. The clause above looks for a noun the lesson knows and a name is
%% the one word no lesson can know, so before this the whole phrase was
%% refused: `Evacuata la Gallery.' came back `unknown: []', a SHAPE refusal
%% with no shape missing.
%%
%% It is the ordinary phrase with `named(Gender, Words)' where the noun goes,
%% so the number, the determiner and every writer that takes a phrase apart
%% by np/5 are untouched -- and the NAME IS NOT CROSSED, which is the whole
%% point of it being a name.
%%
%% THE GENDER IS THE SOURCE ARTICLE'S, because a name has none of its own.
%% `la Tate Gallery' is feminine because the lesson calls `la' feminine, and
%% that gender travels in the IR so Spanish writes `la' and the participle of
%% a passive agrees (`La Tate Gallery e stata evacuata'). Read on the ENGLISH
%% side there is no gender to read, so the IR carries `none' and the lesson's
%% writer falls back to the masculine: `The Tate Gallery' into Italian is `Il
%% Tate Gallery', which is the cost and is stated rather than guessed at.
%%
%% Several capitalised words after the determiner are ONE name. Bare, they are
%% one only when the lesson knows none of them (tr_np/3 above), because
%% after a determiner the phrase's start is not in doubt and bare it is:
%% `Sabato Mladic' is a day and a surname.
%% ... AND A RUN WHOSE LAST WORD NO LESSON KNOWS is one too, when no word of
%% it is a noun the lesson knows: `el Van Gogh de la luthiere', where `van'
%% is the plural of a verb's form. A known noun keeps the ordinary reading,
%% so `la Casa Bianca' is still the white house.
%% ... AND A NOUN THE LESSON KNOWS IN THE OTHER NUMBER ONLY is no noun of this
%% determiner: `la Tate Gallery' is refused since `"tate" is the plural of
%% "tata".', a babysitter, came into the lesson -- and `la' is singular, so
%% `tate' cannot be its noun, and the run is the name it was
tr_np(Side, [D|Ws], np(det(DK, DL, D), none, [], named(G, Ws), Number)) :-
    Ws \== [], tr_determiner(Side, D, DL, DK),
    (   forall(member(W, Ws), tr_name_word(Side, W)) -> tr_det_gender(Side, D, DL, G0, Number)
    ;   Ws = [_, _|_], forall(member(W, Ws), W = w(_, upper)),
        last(Ws, WL), tr_name_word(Side, WL),
        tr_det_gender(Side, D, DL, G0, Number),
        \+ ( member(w(X, _), Ws), tr_is(Side, w(X, lower), noun), tr_noun_in_number(Side, X, Number) )
    %% ... AND A RUN WHOSE FIRST WORD IS A NAME, whatever the words after it are: `La Spoleto Festival
    %% Orchestra sarà diretta da ...' is the orchestra called that, and with `orchestra' a noun of this
    %% determiner the run was no name and the sentence was refused
    %% (the second word's capital asked first, then the name's lookup, then every capital: asked of every phrase that
    %% opens on a name word, the lookup first cost `L'Italia ha avuto quattro governi ...' 9 % more, and the
    %% capitals first, a run whose first word is a name and whose second is in small letters, cost three files of the
    %% controls 0.1 % more; the name first is a guard of cost, the same texts as any run of capitals for 0.35 % fewer
    %% inferences over the controls)
    ;   Ws = [W1, W2|_], nonvar(W2), W2 = w(_, upper), tr_name_word(Side, W1), forall(member(W, Ws), W = w(_, upper)),
        tr_det_gender(Side, D, DL, G0, Number)
    ),
    tr_name_gender(Side, D, Ws, G0, G), !.
%% ... AND A QUOTED RUN WITH A WORD NO LESSON KNOWS: `el "ja sóc aquí" de
%% Tarradellas' -- his words on his return, in Catalan, which is no
%% lesson's. The run stands where the noun goes, as a name does, and is
%% written back word for word in its marks; the unknown words had refused
%% the sentence.
tr_np(foreign, [D, w(W1, qopen)|Ws0], np(det(DK, DL, D), none, [], named(G, [w(W1, qopen)|Ws0]), Number)) :-
    tr_determiner(foreign, D, DL, DK),
    last(Ws0, w(_, qclose)), \+ ( member(X, Ws0), \+ X = w(_, _) ),
    \+ ( append(_, [w(_, QC)|_], Ws0), memberchk(QC, [qopen, qboth]) ),
    once(( member(w(U, _), [w(W1, qopen)|Ws0]), \+ tr_known_word(foreign, U) )),
    tr_det_gender(foreign, D, DL, G, Number), !.
%% ... AND ADJECTIVES AFTER THE NAME: `L'Italia attuale ha le forme della
%% democrazia' was refused whole, the name taking no word after it. The
%% name's words and then adjectives the lesson knows, placed by each writer
%% where its language puts an adjective (`la Italia actual').
tr_np(foreign, [D|Ws0], np(det(DK, DL, D), none, Adjs, named(G, Ws), Number)) :-
    Ws0 = [W1, _|_], tr_name_word(foreign, W1),
    append(Ws, Adjs, Ws0), Ws \== [], Adjs \== [],
    forall(member(W, Ws), tr_name_word(foreign, W)),
    forall(member(A, Adjs), ( A = w(_, lower), tr_adj_word(foreign, A), tr_is(foreign, A, adjective) )),
    tr_determiner(foreign, D, DL, DK),
    tr_det_gender(foreign, D, DL, G0, Number), tr_name_gender(foreign, D, Ws, G0, G), !.
%% ... AND AFTER A NAME THAT HAS NO DETERMINER: `la commissione sulla povertà
%% presieduta da Pierre Carniti grafico' ends on a name and the word that
%% labels what follows it, an adjective, and the phrase of a name and an
%% adjective had no reading. The gender is the adjective's where it says one.
%% (asked of every phrase that opens on a capital word, a sentence's first
%% included: the phrase must end in small letters, the name words are the
%% longest run -- tr_name_run/3, each word asked once -- and the rest are all
%% adjectives, where splitting the phrase at every word asked them again)
tr_np(foreign, Ws0, np(none, none, Adjs, named(G, Ws), singular)) :-
    Ws0 = [W1, _, _|_], W1 = w(_, upper), last(Ws0, w(_, lower)), tr_name_word(foreign, W1),
    tr_name_run(Ws0, Ws, Adjs), Ws \== [], Adjs \== [],
    forall(member(A, Adjs), ( A = w(_, lower), tr_is(foreign, A, adjective), tr_adj_word(foreign, A) )),
    Adjs = [w(AW, _)|_], atom(AW),
    ( tr_holds(feminine(AW)) -> G = feminine ; G = masculine ), !.
%% ... AND A POSSESSIVE AFTER THE ARTICLE IS THE DETERMINER, as it is before a
%% noun: `Il nostro "Robespierre"' is our Robespierre, `Nuestro
%% "Robespierre"' -- read as an adjective before the name it came out `El
%% nuestro', the article kept and the possessive crossed as `ours'
tr_np(foreign, [A0, P0|Ws], np(det(possessive, PL, P0), none, [], named(G, Ws), Number)) :-
    Ws \== [], tr_determiner(foreign, A0, AL, article), tr_determiner(foreign, P0, PL, possessive),
    forall(member(W, Ws), tr_name_word(foreign, W)),
    tr_det_gender(foreign, A0, AL, G0, Number), tr_name_gender(foreign, A0, Ws, G0, G), !.
%% ... AND ADJECTIVES MAY STAND BETWEEN THE DETERMINER AND THE NAME: `le più
%% canicolari Eolie', the most sweltering of the islands, had no reading at
%% all. Each stays before the name as the source set it (pre/1), a degree
%% word makes it a superlative as the article says, and every writer agrees
%% it with the gender the name carries.
%% (the run of name words at the END is the name, found once: tried at every
%% split of every phrase with a determiner, the reading cost Valencia's
%% sentence of names a quarter again)
tr_np(Side, [D|Ws0], np(det(DK, DL, D), none, AdjsM, named(G, Ws), Number)) :-
    Ws0 = [_, _|_], last(Ws0, WL), tr_name_word(Side, WL),
    reverse(Ws0, Rev), tr_name_run_rev(Side, Rev, RevNames, RevPre),
    %% (the adjectives' comma may stand before the name: `i nuovi, piccoli,
    %% meschini, Hitler', tr_adj_lists/3)
    ( RevPre = [w(',', acomma), LastPre|_] -> true ; RevPre = [LastPre|_] ),
    ( LastPre = deg(_, LA) -> true ; LA = LastPre ),
    %% (or a determiner of quantity after the article: `alla caccia di uno dei pochissimi Athanasius Kircher' is
    %% one of the very few Athanasius Kirchers, the books, and the phrase had no reading)
    ( tr_is(Side, LA, adjective) ; tr_name_pre_det(Side, LA) ),         % the word before the name
    tr_determiner(Side, D, DL, DK),
    reverse(RevNames, Ws), reverse(RevPre, Pre0),
    tr_degree_of(Side, det(DK, DL, D), Degree), tr_degrees(Side, Degree, Pre0, Pre00),
    %% (and the word for `very' before one of them is its, advn/1 before it as
    %% before a noun: `el altísimo Gandalf', the superlative unfolded)
    tr_name_pre_int(Side, Pre00, Pre),
    Pre = [P1|_], \+ ( P1 = w(_, _), tr_coord(Side, P1) ),
    %% (a coordinator between two of them is the phrase's, kept among its
    %% adjectives as a noun's are: `la hermosa, joven y cautivadora Senegal')
    forall(member(A, Pre), ( A \= w(_, _) -> tr_adj_word(Side, A)
                           ; A = w(',', acomma) -> true
                           ; tr_coord(Side, A) -> true
                           ; tr_name_pre_det(Side, A) -> true
                           ; tr_adj_word(Side, A), tr_is(Side, A, adjective) )),
    findall(B, ( member(A, Pre), ( Side == foreign, A = w(_, _), \+ tr_coord(Side, A) -> B = pre(A) ; B = A ) ), AdjsM),
    tr_det_gender(Side, D, DL, G0, Number), tr_name_gender(Side, D, Ws, G0, G), !.

%% A PHRASE WHOSE NOUN THE SENTENCE LEFT OUT. `el más débil' is the weakest
%% one and `los de clase media' those of the middle class: an article and
%% then adjectives, or an article and a `de' phrase, with no noun. The noun
%% slot holds elided(Gender), the gender the article lends it -- the one
%% thing the missing noun would have said -- so every word written after it
%% agrees; and a `de' phrase travels as ell(Det, Gender, Number, PP).
%% ... AND A COUNT BEFORE THE ADJECTIVES: `Los dos primeros se han quedado
%% en casa' is the first two, the players left out, and with the number
%% where the adjectives were looked for the phrase was refused
tr_np(Side, [D, M|Ws], np(det(DK, DL, D), M, Adjs, elided(G), Number)) :-
    Ws \== [], tr_determiner(Side, D, DL, DK), DK == article, \+ tr_standalone_det(Side, D),
    tr_is(Side, M, number),
    tr_np(Side, [D|Ws], np(_, none, Adjs, elided(G), Number)), !.
%% (`uno stoico' is a stoic: `uno' is the pronoun for one too, and read as one
%% it left no noun to elide -- but the lesson's article is the word before
%% `st', `z', `gn' ..., and a pronoun is the word before nothing in particular,
%% so an adjective that begins one of them has the article before it. Only
%% where the article IS a pronoun: written as `; tr_article_by_letters' beside
%% `\+ tr_standalone_det', the letters were tried again for every article that
%% passed, when the rest of the clause failed -- `gli errori' read the whole
%% phrase for adjectives 21 000 times in one sentence, +45 %)
tr_np(Side, [D|Ws], np(det(DK, DL, D), none, Adjs, elided(G), Number)) :-
    Ws \== [], tr_determiner(Side, D, DL, DK), DK == article,
    ( \+ tr_standalone_det(Side, D) -> true ; tr_article_by_letters(Side, D, Ws) ),
    tr_degree_of(Side, det(DK, DL, D), Degree), tr_degrees(Side, Degree, Ws, Adjs),
    Adjs \== [], forall(member(A, Adjs), ( A = deg(_, _) ; tr_is(Side, A, adjective) )),
    ( member(deg(_, _), Adjs) -> true ; \+ ( member(A, Ws), tr_is(Side, A, noun) ) ),
    tr_det_gender(Side, D, DL, G0, Number),
    %% an ELIDED article says no gender -- `l'' is `lo' and `la' alike -- and
    %% the adjective after it does: `dall'altra' is the other one, feminine
    (   D = w(DW, _), tr_solve(elision_of(DW, _)),
        member(w(AW, _), Adjs), tr_lexeme(Side, AW, AL, _), tr_gender(AL, AG), AG \== none
    ->  G = AG
    ;   G = G0
    ), !.
%% ... AND ONE WHOSE NOUN A RELATIVE CLAUSE STANDS FOR: `un descalabro como
%% el que sufrió el Madrid en Toledo' is like the one Madrid suffered. The
%% article and the clause are the whole phrase, rel(Role, Clause) where a
%% `de' phrase would be, and each writer says `quello che', `el que', `the
%% one that'.
tr_np(Side, [D, w(R, RC)|Ws], ell(det(DK, DL, D), G, Number, rel(Role, S))) :-
    Side == foreign, Ws \== [],
    tr_determiner(Side, D, DL, DK), DK == article, \+ tr_standalone_det(Side, D),
    tr_relative_word(Side, R),
    tr_det_gender(Side, D, DL, G, Number),
    tr_relative_clause(Side, [w(R, RC)|Ws], Role0, S0), Role0 \= pp(_), !,
    tr_rc_role(Side, [w(R, RC)|Ws], ell(none, G, Number, none), Role0, S0, Role, S).
%% ... AND THE INDEFINITE ARTICLE BEFORE ANY PREPOSITION: `dos papeletas,
%% una para cada candidatura' is one for each, the ballot left out, and read
%% as the subjunctive of `unir' it was a clause of its own, `unisco per ogni
%% candidatura' (tr_indefinite/2; the definite article before a preposition
%% that is no `de' is the pronoun and its phrase, `la para' being nothing)
tr_np(Side, [D, P|Ws], ell(det(DK, DL, D), G, Number, pp(P, NP))) :-
    tr_determiner(Side, D, DL, DK), DK == article, \+ tr_standalone_det(Side, D),
    tr_is(Side, P, preposition), ( tr_means_of(Side, P) -> true ; tr_indefinite(Side, D) ), Ws \== [],
    tr_object_phrase(Side, Ws, NP),
    tr_det_gender(Side, D, DL, G, Number), !.
%% ... AND ONE OPENED BY A WORD THAT REPLACES THE NOUN (tr_noun_replacer/2):
%% `ha superato in durata quello di Berlusconi' is Berlusconi's government,
%% and read as the pronoun `that' it came out `eso de Berlusconi'. It
%% travels as the phrase an article would open -- the lesson's article for
%% `the', in the word's own gender and number -- so Spanish writes `el de'
%% and English `the one of'.
%% ... WITH ANY PREPOSITION, not only `di': `quelli senza alcun titolo di
%% studio sono il 27 per cento' is those without any qualification, `los sin
%% título', and read as the pronoun with a phrase after it (with/2) its head
%% was `that' in the plural, which no writer has a word for
tr_np(foreign, [Q, P|Ws], ell(det(article, AL, Q), G, Number, pp(P, NP))) :-
    Ws \== [], tr_noun_replacer(foreign, Q), Q = w(QW, _),
    tr_is(foreign, P, preposition),
    tr_object_phrase(foreign, Ws, NP),
    tr_lexeme(foreign, QW, L, Number), tr_gender(L, G),
    once(( tr_solve(mean(AL, the)), tr_class_of(AL, article) )), !.

%% ... AND ONE WITH A RELATIVE CLAUSE AFTER IT, WHAT SOMETHING DOES: `lo
%% que hace es "desacreditar" la investigación' -- the word the lesson says
%% replaces a noun (`The word "lo" replaces the noun.'), with the clause
%% where the `de' phrase is above, as `el que sufrió el Madrid' has it.
%% Read as the pronoun `lo', it came out `him that is ... ago'
%% ... AND THE WORD OF NO GENDER IS "WHAT", NOT "THE ONE": `lo que interesa hoy
%% es la belleza del espíritu' is what interests today, and it was written
%% `the one that interests' (and `Eso es lo que no entiendo' `That is the one
%% that I do not understand'). The article of the phrase is `what', which no
%% lesson has as an article, so Italian's writer finds its pronoun for `that'
%% (`quello che') as before and English's puts `what' for the word and the
%% relative word together (tr_np_out/5)
tr_np(foreign, [Q, w(R, RC)|Ws], ell(det(article, AL, Q), G, Number, rel(Role, S))) :-
    Ws \== [], tr_noun_replacer(foreign, Q), Q = w(QW, _),
    tr_relative_word(foreign, R),
    tr_relative_clause(foreign, [w(R, RC)|Ws], Role0, S0), Role0 \= pp(_),
    tr_lexeme(foreign, QW, L, Number), tr_gender(L, G0),
    (   G0 == none -> G = masculine, AL = what
    ;   G = G0, once(( tr_solve(mean(AL, the)), tr_class_of(AL, article) ))
    ),
    tr_rc_role(foreign, [w(R, RC)|Ws], ell(what, G, Number, none), Role0, S0, Role, S), !.
%% ... AND ONE WITH A PARTICIPLE AFTER IT: `quello guidato dal magnate
%% televisivo Silvio Berlusconi' is the one the tycoon led. It is the
%% reduced relative (rel/3) of a phrase whose noun was left out with nothing
%% after its head, ell(Det, G, N, none), so Spanish writes `el conducido
%% por', Italian `quello guidato da' and English `the one led by'.
tr_np(foreign, [Q, w(P, PC)|Rest], rel(ell(det(article, AL, Q), G, Number, none), L, Comps)) :-
    tr_noun_replacer(foreign, Q), Q = w(QW, _),
    tr_participle_here(foreign, P, L), \+ tr_is(foreign, w(P, lower), noun),
    \+ ( Rest == [], tr_is(foreign, w(P, lower), adjective) ),
    tr_lexeme(foreign, QW, QL, Number), tr_gender(QL, G), tr_participle_agrees(P, Number),
    ( Rest == [] -> Comps0 = [] ; tr_ptc_complements(foreign, L, Rest, Comps0) ),
    tr_rel_case(PC, Comps0, Comps),
    once(( tr_solve(mean(AL, the)), tr_class_of(AL, article) )), !.
%% (a determiner of quantity, in small letters, between an article and a name: `uno dei pochissimi Athanasius Kircher')
tr_name_pre_det(Side, A) :- A = w(_, lower), tr_determiner(Side, A, _, determiner), !.
%% THE GAP OF A SUBJECT'S RELATIVE CLAUSE AGREES WITH ITS PHRASE: `después
%% de la que celebraron el Lunes por la noche delegaciones del Gobierno' is
%% the one the delegations held, and read with `la' for the subject, a
%% singular that celebrated in the plural, the delegations were its object.
%% A phrase whose number nothing says is not asked.
tr_gap_agrees(Side, subject, s(_, gap(_, GN), _, _), NP) :- tr_head_number(Side, NP, N), !, GN == N.
tr_gap_agrees(_, _, _, _).
%% the phrase a series of relative clauses hangs on
tr_nrc_head(rc(Head, _, _), Head).
tr_nrc_head(nrc(NP, _, _), Head) :- tr_nrc_head(NP, Head).
%% the clause and what its relative word stands for: the clause's first
%% reading, where its gap agrees -- and the object's otherwise, which the
%% subject's cut would have kept from being asked. The clause is read first
%% and the phrase after it, as before, and asked again only when it
%% disagrees: a first cut read the phrase first and the clause up to three
%% times, and the Washington Post's third, `quattro governi di cui solo uno,
%% quello guidato dal magnate televisivo ...', went from 8.3 million
%% inferences to 13.4
%% THE DOER AFTER A RELATIVE CLAUSE'S VERB IS ITS SUBJECT, THE RELATIVE WORD ITS
%% OBJECT: `el pan que come el perro' is the bread the dog eats, and `lo que
%% dice el técnico' what the coach says -- read with the relative word for the
%% subject, as the clause's first reading is, they were `the bread that eats the
%% dog' and `what says the coach'. Spanish marks an animate object with `a' (`el
%% hombre que ve al perro'), so a definite phrase right after the verb that
%% names a doer -- a name, a team's name, a noun the lesson calls a person,
%% animate or a group -- and no `a' in the clause is the subject. Not for an
%% indefinite phrase (`un jugador que busca un entrenador' looks for one), not
%% for a name where the phrase it hangs on is a doer itself (`el técnico que
%% dirige el Inter': a team is the object of the man who leads it), and only
%% RIGHT after the verb: not after an infinitive, whose object it is (`Craxi che
%% minaccia di regolare i conti', and `conti' are also counts, persons), nor
%% after the phrase of a pronoun (`de toda Catalunya'). A lesson with no word
%% before a person, Italian's, has the rule where the phrase it hangs on is no
%% doer: `il pane che mangia il cane' is the bread the dog eats, and `una madre
%% che ha perso la figlia' keeps its object
%% A VERB OF SAYING WITH NOTHING AFTER IT HAS ITS OBJECT IN THE RELATIVE WORD:
%% `con lo que dice' is with what he says -- read with the relative word for the subject, as
%% the clause's first reading is, it was `with what says', a verb with nobody to do it. The
%% subject is nobody named (English writes the singular `they' for a verb of saying,
%% tr_null_subject/5). NOT `hace': `lo que hace es "desacreditar"' is what the insistence
%% does, the clause's subject the phrase it hangs on, and with nobody named English refused it
tr_rc_role(Side, Rest, _, subject, s(_, gap(third, _), g(L, _, _, _), []), object, S) :-
    Side == foreign, atom(L), tr_object_verb(L),
    tr_relative_clause(Side, Rest, object, S), !.
%% ... AND AFTER A COPULA, `lo que hoy es el equipo' is what the team is today: the
%% phrase after `lo que es' is what is spoken of, and the relative word what it
%% is (a definite phrase only, and only for `lo que': `la ciudad que es la
%% capital' is the city that IS the capital)
tr_rc_role(Side, Rest, NP, subject, S0, object, S) :-
    Side == foreign, tr_rel_doer(NP, S0),
    (   tr_marker_word(M, person) -> \+ memberchk(w(M, _), Rest) ; \+ tr_head_animate(NP) ),
    tr_relative_clause(Side, Rest, object, S), S = s(_, Su, _, _), \+ tr_time_phrase(Su), !.
tr_rc_role(Side, _, NP, Role0, S0, Role0, S0) :- tr_gap_agrees(Side, Role0, S0, NP), !.
%% (never with a DAY for the subject: `un niño de 10 años que el domingo había
%% resultado herido' hangs on the years, which the singular gap does not
%% agree with, and read for an object `el domingo' was the subject, the day
%% that was hurt, `che domenica era risultata ferita')
tr_rc_role(Side, Rest, _, _, _, object, S) :-
    tr_relative_clause(Side, Rest, object, S), S = s(_, Su, _, _), \+ tr_time_phrase(Su), !.
%% ... and where neither reads, the first reading as it stood: a relative
%% clause after two phrases joined agrees with both and hangs on the last,
%% `un elicottero della forestale e uno della Guardia di finanza che hanno
%% pattugliato la zona', `lembi di terra che si chiamano Giglio, ...' --
%% asked to agree with its own phrase it refused Livata's last sentence and
%% the islands report's ninth
tr_rc_role(_, _, _, Role0, S0, Role0, S0).
%% a phrase that does what a verb says: a name, a team's name with its article, or a
%% definite phrase whose noun the lesson calls a person or animate
tr_rel_doer(NP, s(_, gap(third, _), g(L, _, _, _), Cs)) :-
    append(Pre, [obj(X)|_], Cs), \+ ( member(Y, Pre), ( tr_object_comp(Y) ; tr_infinitive_comp_any(Y) ; Y = pp(_, pronoun(_)) ) ),
    (   atom(L), tr_copula_lexeme(L) -> NP = ell(what, _, _, _), tr_definite_np(X)
    %% ... and a verb the lesson calls intransitive has no object to be: `la hora
    %% y media que duró el encuentro' is the hour and a half the MEETING lasted,
    %% and read with the relative word for the subject it was `that lasted the
    %% meeting' (`"dura" is intransitive.') -- never after `lo que', the subject
    %% itself: `lo que ocurrirá esa fecha' is what will occur on that date, and
    %% read for the doer it was `what that date will occur'
    ;   atom(L), tr_solve(intransitive(L)) -> NP \= ell(what, _, _, _), tr_definite_np(X)
    ;   tr_doer_np(X), ( tr_head_animate(NP) -> \+ tr_named_doer(X) ; true ),
        %% ... and never a person after a verb the lesson gives a meaning for a person object (`The personal verb
        %% "turba" means "troubles".'): `i complessi di colpa che avevano profondamente turbato i loro maestri' are
        %% the complexes that had deeply troubled their teachers, and read with the teachers for the doer English
        %% wrote `that their teachers had troubled'
        \+ ( atom(L), nb_getval('$tr_personal', PLs), memberchk(L, PLs), tr_person_object(X) )
    ).
tr_definite_np(name(_)).
tr_definite_np(np(det(_, _, D), _, _, _, _)) :- \+ tr_indefinite(foreign, D).
tr_doer_np(name(_)).
tr_doer_np(np(det(_, _, D), _, _, N, _)) :- \+ tr_indefinite(foreign, D), tr_doer_noun(N).
%% ... and `the others', the noun left out: `comprare "quello che hanno anche gli altri"' is to buy what the others
%% have too, and read with the relative word for the subject it was `what also have the other ones'
tr_doer_np(np(det(_, _, D), _, Adjs, elided(_), _)) :-
    \+ tr_indefinite(foreign, D), member(w(A, _), Adjs), atom(A), tr_lexeme(foreign, A, AL, _), once(tr_solve(mean(AL, other))), !.
tr_object_verb(L) :- tr_saying_verb(L), !.
tr_doer_noun(named(_, _)).
tr_doer_noun(w(W, _)) :- atom(W), tr_lexeme(foreign, W, L, _), ( tr_holds(person(L)) ; tr_holds(animate(L)) ; tr_holds(group(L)) ), !.
tr_head_animate(name(_)).
tr_head_animate(np(_, _, _, N, _)) :- N = w(_, _), tr_doer_noun(N).
tr_named_doer(name(_)).
tr_named_doer(np(_, _, _, named(_, _), _)).
tr_head_number(_, np(_, _, _, _, N), N) :- atom(N).
tr_head_number(_, name(_), singular).
tr_head_number(Side, pronoun(w(W, _)), N) :- tr_object_pronoun(Side, W, E), tr_object_agreement(E, _, N).
tr_head_number(_, ell(_, _, N, _), N) :- atom(N).

%% a clause whose subject stands first: after its adverbs, a determiner, a
%% name or a count
tr_subject_first([W|Ws]) :- tr_plain_adverb(foreign, W), !, tr_subject_first(Ws).
%% (and after an insertion between two commas, and the word that says both
%% ... and: `dal fatto che, almeno sino a Copernico, sia il mondo greco che
%% quello cristiano avevano ritenuto ...' is the fact THAT both had believed)
tr_subject_first([comma|Ws]) :- !, append(Ins, [comma|R], Ws), Ins \== [], \+ memberchk(comma, Ins), !, tr_subject_first(R).
tr_subject_first([w(B, _)|Ws]) :- atom(B), tr_both_word(foreign, B, _), !, tr_subject_first(Ws).
tr_subject_first([W|_]) :- tr_determiner(foreign, W, _, _), !.
tr_subject_first([W|_]) :- tr_name_word(foreign, W), !.
tr_subject_first([W|_]) :- tr_count_word(foreign, W).
%% A PARTICIPLE AFTER A RELATIVE CLAUSE IS THE CLAUSE'S: `lo que los hace tan
%% deseados' makes them so desired, and read as the phrase's reduced relative
%% it was `the one that makes them, so desired'. A phrase that ends in a
%% clause takes no participle after it; the clause reads it.
tr_clause_phrase(rc(_, _, _)) :- !.
tr_clause_phrase(nrc(_, _, _)) :- !.
tr_clause_phrase(ell(_, _, _, rel(_, _))) :- !.
%% ... AND A NAME'S: `Con Rimac excesivamente apagado en tareas ofensivas,
%% fueron César Sanmartín y Jofresa los jugadores' -- with Rimac excessively
%% subdued. The phrase ended at the name, the adverb and the participle were
%% the sentence's own, said of its subject and agreeing with it in number,
%% and a plural subject (`fueron ...') left the front with no reading
tr_adverb_before_participle(foreign, PW, [A, w(P, _)|_]) :-
    A = w(_, _), \+ tr_is(foreign, A, preposition),
    member(X, PW), ( tr_is(foreign, X, noun) ; tr_name_word(foreign, X) ),
    tr_participle_here(foreign, P, _), \+ tr_is(foreign, w(P, lower), noun), !.
%% THE WORD FOR `more' BETWEEN A NOUN AND ITS PARTICIPLE IS THE PARTICIPLE'S
%% DEGREE: `con una adhesión más limitada, más contenida' is a more limited
%% adherence. `más' is also the preposition `plus', so the phrase ended at
%% it, and the participle after it was said of the sentence's subject and
%% agreed with it, `più limitati'. The phrase runs on over the pair, and
%% tr_np/3 reads it as the reduced relative with pdeg/1 that `la más
%% esperada' already is -- a comparative after an indefinite article, a
%% superlative after a definite one, which is what the article says of an
%% adjective too.
tr_degree_before_participle(foreign, PW, [w(M, _), w(P, _)|_]) :-
    tr_degree_word(M),                                 % the rare word first: asked at every boundary
    member(X, PW), tr_is(foreign, X, noun),
    tr_participle_here(foreign, P, _), \+ tr_is(foreign, w(P, lower), noun), !.
%% (THE TITLE IS ASKED BEFORE THE PHRASE IS READ, and the title reader of the
%% phrase readers asks it here and not through tr_np/3: the Òmnium report's
%% second sentence offered `una candidatura única "siempre y cuando haya
%% voluntad"' nine times, and read the three words as a phrase every time --
%% a third of a million inferences -- before it found no title in them.
%% The cut above is tr_np/3's: the one at the end of the helper cuts the
%% helper alone, and without it every other clause of tr_np/3 was tried
%% again after a title had read -- astro's first sentence, 39 000 more)
tr_quoted_title(Words, NP, Cs) :-
    memberchk(w(_, qopen), Words),                                          % the rare word first
    append(Core, [w(Q1, qopen)|Run], Words), Core = [_|_], Run = [_|_],
    tr_title_first(Q1),
    last(Run, w(_, qclose)), \+ memberchk(comma, Run),
    tr_title_core(Core),
    tr_title_comps([w(Q1, qopen)|Run], Cs),
    tr_object_phrase(foreign, Core, NP), NP = np(_, _, _, _, _), !.
%% A TITLE OPENS ON NO DETERMINER: a quoted run that opens on its own
%% article is a phrase of its own. `desconocen "qué consecuencias" reportará
%% para la imagen de la entidad "la movida que está montando" el sector
%% renovador' -- the Òmnium report's ninth -- is the stir the sector is
%% mounting, which is what will bring the consequences, and read as the
%% entity's title it left the sector for the subject of `reportará', the
%% sentence was divided at the first closing mark, and `qué' was written as
%% the adjective `what': `ignorano "cose conseguenze"'
tr_title_first(Q1) :- \+ tr_determiner(foreign, w(Q1, lower), _, _).
%% the phrase before a title: a determiner, a noun, no preposition, and it
%% ends on its noun or an adjective. (THE END IS WHAT THE TWO TITLE CLAUSES
%% COST: the Òmnium report's ninth offered `la junta directiva - - ... - -
%% están "sufriendo" porque desconocen' before `"qué consecuencias"' forty
%% times, and reading that as a phrase to be refused was 1.1 million
%% inferences of its 7.6; and its thirteenth has `con la oposición con el fin
%% de "encontrar una solución que favorezca al país"', where `con el fin de',
%% one word of several that begins a purpose, is no preposition to the walk
%% below -- 114 638 inferences, to be refused. A verb anywhere in the phrase
%% was refused first, for the ninth; once the last word was asked it refused
%% nothing the last word had not, over every control, and cost 6 000
%% inferences, so it is out)
tr_title_core(Core) :-
    Core = [D|_], tr_determiner(foreign, D, _, _),
    last(Core, L), ( tr_is(foreign, L, noun) -> true ; tr_is(foreign, L, adjective) ),
    \+ ( member(X, Core), X = w(_, _), tr_is(foreign, X, preposition),
         \+ tr_is(foreign, X, noun), \+ tr_is(foreign, X, adjective) ),
    once(( member(N, Core), N = w(_, _), tr_is(foreign, N, noun) )), !.
%% the title's words as complements, read with no verb group around them
tr_title_comps(Ws, Cs) :-
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_group', none), nb_setval('$tr_read_aspect', simple),
    (   tr_complements(foreign, Ws, Cs0), Cs0 = [obj(_)|_], \+ memberchk(sep, Cs0)
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), Cs = Cs0
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).
%% the words of a phrase and its title, to the title's closing mark, and an
%% aside set off after it (tr_phrase_words0/4)
tr_title_words(Words, PW, Rest) :-
    memberchk(w(_, qopen), Words),
    once(append(Core, [w(Q1, qopen)|Ws], Words)), Core = [_|_], \+ memberchk(comma, Core),
    tr_title_first(Q1),
    once(( append(Run, Rest0, Ws), Run = [_|_], last(Run, w(_, qclose)) )),
    \+ memberchk(comma, Run),
    tr_title_core(Core),
    append(Core, [w(Q1, qopen)|Run], PW0),
    tr_quoted_title(PW0, _, _), !,
    (   Rest0 = [w(K, Kind)|Rest], memberchk(Kind, [paren, aside, dashed])
    ->  append(PW0, [w(K, Kind)], PW)
    ;   PW = PW0, Rest = Rest0
    ).
%% the agent of one word: a pronoun that stands after a preposition, as the
%% preposition's reader takes one (tr_complements0/4), or a name
tr_lone_agent(w(W, C), pronoun(w(W, C))) :-
    atom(W), tr_object_pronoun(foreign, W, _), tr_oblique_pronoun(foreign, W), !.
tr_lone_agent(w(W, C), A) :- tr_name_word(foreign, w(W, C)), tr_np(foreign, [w(W, C)], A), !.
%% A PARTICIPLE THAT DOES NOT AGREE WITH THE NOUN BEFORE IT AGREES WITH A
%% NOUN FURTHER BACK: `la partecipazione del 41,5% detenuta dal fondo' -- the
%% share is held, and the percentage between them is masculine. The IR has
%% no phrase of `di' inside a phrase, so the relative hangs on the nearest
%% noun; the gender the source gave the participle travels with it,
%% agr(Gender) among its complements, and the writer agrees with that.
%% -- BOTH, WHERE BOTH DIFFER: `le attività del tempo libero legate al
%% turismo' are the activities, tied to tourism, and `legate' is feminine
%% AND plural beside a masculine singular `tempo'. The gender alone went, and
%% Spanish wrote `legada', singular.
tr_rel_agreement(Side, P, NP, Cs0, Cs) :-
    tr_rel_number(Side, P, NP, Cs0, Cs1), tr_rel_gender(Side, P, NP, Cs1, Cs).
tr_rel_gender(foreign, P, np(_, _, _, w(NW, _), _), Cs, [agr(PG)|Cs]) :-
    ( tr_solve(feminine(P)) -> PG = feminine ; PG = masculine ),
    tr_lexeme(foreign, NW, L, _), tr_gender(L, NG),
    ( NG == none -> PG == feminine ; NG \== PG ), !.            % a percentage has no gender to agree with
%% ... and a NAME has no gender to agree with, so the participle's own goes:
%% `l'isola di Ustica "proibita"' -- the island is banned, and the noun
%% nearest the participle is the name
tr_rel_gender(foreign, P, name(_), Cs, [agr(feminine)|Cs]) :- tr_solve(feminine(P)), !.
%% ... and a phrase with a bracket after it agrees as the phrase: `las 33
%% licencias (21 nuevas y 12 renovaciones) efectuado a principios ...' is
%% the distribution done, masculine and singular, and past the bracket the
%% participle agreed with the licences, `effettuate'
tr_rel_gender(Side, P, app(NP, _, _), Cs0, Cs) :- !, tr_rel_gender(Side, P, NP, Cs0, Cs).
tr_rel_gender(_, _, _, Cs, Cs).
%% ... AND IN NUMBER: `la lista delle priorità fissata dal governo' -- the
%% list is set, singular, and `priorità' is plural by its article, so
%% `fijadas' agreed with the priorities. The participle's own number
%% travels as agrn(Number) when it is not the phrase's.
tr_rel_number(foreign, P, np(_, _, _, H, N), Cs, [agrn(PN)|Cs]) :-
    ( H = w(_, _) ; H = named(_, _) ), tr_participle_number(P, PN), PN \== N, !.
tr_rel_number(foreign, P, name(_), Cs, [agrn(plural)|Cs]) :- tr_participle_number(P, plural), !.
tr_rel_number(Side, P, app(NP, _, _), Cs0, Cs) :- !, tr_rel_number(Side, P, NP, Cs0, Cs).
tr_rel_number(_, _, _, Cs, Cs).

%% the participle's own case, where it is not plain: the quotation marks of
%% `l'isola di Ustica "proibita"' travel with it and go back round it
tr_rel_case(lower, Cs, Cs) :- !.
tr_rel_case(upper, Cs, Cs) :- !.
tr_rel_case(C, Cs, [pcase(C)|Cs]).
tr_name_part(Side, W) :- tr_name_word(Side, W), !.
tr_name_part(foreign, W) :-
    W = w(X, upper), \+ tr_is(foreign, W, noun), \+ tr_is(foreign, W, adjective),
    \+ tr_is(foreign, W, preposition), \+ tr_determiner(foreign, W, _, _), tr_verb_form_word(X), !.
tr_thing_phrase(det(article, AL, w(AL, lower)), N) :-
    tr_solve(mean(N, thing)), atom(N), tr_class_of(N, noun), tr_gender(N, G), G \== none,
    tr_solve(mean(AL, the)), atom(AL), tr_class_of(AL, article), tr_gender(AL, G), !.
tr_judging_adjective(w(AW, _)) :-
    atom(AW), tr_is(foreign, w(AW, lower), adjective), tr_lexeme(foreign, AW, AL, _),
    tr_solve(mean(AL, E)), en_judging(E), !.
en_judging(E) :- memberchk(E, [certain, true, sure, important, good, bad, best, worst, better, worse, interesting, strange,
                               curious, sad, funny, positive, negative, essential, fundamental, difficult, easy, possible,
                               necessary, obvious, evident, normal, logical, natural, serious, remarkable, surprising, clear]).
%% the count of a ratio, a number in digits or one the lesson names -- asked
%% first, being the test that nearly every phrase of four words fails (the
%% clause was one of the dearer of the reader's, asked of them all)
tr_ratio_count(M) :- M = w(MW, _), tr_digits(MW), !.
tr_ratio_count(M) :- tr_is(foreign, M, number), !.
%% the participles at the head of a phrase, each with its number, and a
%% coordinator between two of them (none: no number to agree)
tr_pre_participles([w(P, _)|Ws], [pptc(L)-N|Xs], Rest) :-
    atom(P), \+ tr_is(foreign, w(P, lower), adjective), \+ tr_is(foreign, w(P, lower), noun),
    tr_participle_number(P, N),
    ( N == plural -> once(tr_solve(plural_of(P, S))) ; S = P ), tr_participle_here(foreign, S, L),
    (   Ws = [C, W2|Ws2], C = w(_, _), tr_coord(foreign, C), W2 = w(P2, _), atom(P2)
    ->  (   tr_pre_participles([W2|Ws2], Xs0, Rest0) -> Xs = [C-none|Xs0], Rest = Rest0
        ;   tr_is(foreign, W2, adjective) -> Xs = [C-none], Rest = [W2|Ws2]
        ;   Xs = [], Rest = Ws
        )
    ;   Xs = [], Rest = Ws
    ).

%% two words each in a gender the lesson states, and not in one: `giorno'
%% and `prima' -- never a word with no gender of its own, and never the
%% degree word, which has neither a gender nor a number (`i paesi più
%% ricchi')
tr_genders_differ(N, A) :-
    N = w(NW, _), A = w(AW, _),
    tr_lexeme(foreign, NW, NL, _), tr_gender(NL, GN), GN \== none,
    tr_lexeme(foreign, AW, AL, _), tr_gender(AL, GA), GA \== none, GN \== GA,
    \+ tr_aside_agrees(N, A), !.

%% A NOUN THAT IS ITS OWN PLURAL TAKES ITS NUMBER FROM WHAT AGREES WITH IT:
%% `unità cinofile' is canine UNITS, and `unità' read first as the singular
%% it also is came out `unidad canina'. A determiner or an adjective the
%% lesson knows only in the plural says which.
%% (the determiner's number is the one its DETERMINER reading has: `le
%% università costano' -- `le' is the dative `her' too, a singular, and read
%% as plural-only no more, the universities were one and the verb refused)
tr_invariable_number(Side, NW, Det, Adjs, singular, plural) :-
    tr_lexeme(Side, NW, _, plural),
    (   Det = det(_, DL, DW), DW = w(DWW, _), atom(DL),
        tr_lexeme(Side, DWW, DL, plural), \+ tr_lexeme(Side, DWW, DL, singular) -> true
    ;   member(A, Adjs), A = w(_, _), tr_plural_only(Side, A)
    ), !.
tr_invariable_number(_, _, _, _, N, N).

tr_plural_only(Side, w(W, _)) :- tr_lexeme(Side, W, _, plural), \+ tr_lexeme(Side, W, _, singular), !.
tr_plural_count(Side, w(M, _)) :-
    atom(M), ( atom_number(M, V) -> V > 1 ; tr_lexeme(Side, M, L, _), tr_solve(mean(L, E)), E \== one ), !.
tr_plural_count(Side, adv_num(_, N)) :- !, tr_plural_count(Side, N).
tr_plural_count(_, nums(_, _, _)) :- !.
tr_plural_count(_, numw(_, _)).
%% an adjective the lesson knows only in the singular, and whose plural it
%% states: `pazzesco', beside `pazzeschi'
tr_singular_adjective(W) :-
    tr_lexeme(foreign, W, L, singular), tr_class_of(L, adjective), \+ tr_lexeme(foreign, W, _, plural),
    tr_solve(plural_of(P, W)), P \== W, !.

%% the day's join word comes off between the count and the month: `el 20
%% DE enero'
tr_date_day(Side, Num, [J, M], [M]) :- Num \== none, tr_date_join(Side, J), tr_month(Side, M), !.
%% ... and with the adjectives that stood before the count still in front of
%% them: `el pasado 11 DE septiembre' -- the last 11th of September
tr_date_day(Side, Num, Ws, Out) :-
    Num \== none, append(Pre, [J, M], Ws), Pre = [_|_], tr_date_join(Side, J), tr_month(Side, M), !,
    append(Pre, [M], Out).
tr_date_day(_, _, Ws, Ws).

%% the join word INSIDE a date ends no phrase: a day before it and a month
%% after it, or a month before it and a year after it
tr_date_inside(Side, PW, [J, N|_]) :-
    tr_date_join(Side, J), last(PW, P),
    (   P = w(D, _), tr_digits(D), tr_month(Side, N)
    ;   tr_month(Side, P), N = w(Y, _), tr_digits(Y)
    ), !.

%% a month: English's own twelve, or a word the lesson says is one
tr_month(english, w(W, _)) :- !, en_month(W).
tr_month(foreign, w(W, _)) :- tr_lexeme(foreign, W, L, _), tr_solve(month(L)), !.
%% ... AND A DATE'S MONTH IS WRITTEN BY THE WORD THE LESSON CALLS A MONTH:
%% `el 7 de marzo' is March, and English's `march' is a walk too, so the
%% lesson's first word for it is `marcia' and the date came out `il 7
%% marcia'. The twelve months are asked first and their meanings after, so
%% the lookup is keyed on the word.
tr_month_word(E, W) :- tr_solve(month(W)), tr_solve(mean(W, E)), !.

%% the word the lesson joins a date's parts with; English has none
tr_date_join(foreign, w(J, _)) :- tr_solve(join(J, date)), !.

tr_mark_pre(_, [], _, []).
tr_mark_pre(Side, [A|As], Pre, [B|Bs]) :-
    ( A = w(_, _), memberchk(A, Pre), \+ tr_coord(Side, A) -> B = pre(A) ; B = A ),
    tr_mark_pre(Side, As, Pre, Bs).
%% a noun of the lesson's in this number
%% (English's `the' says no number, so any of its nouns may be the noun)
tr_noun_in_number(_, _, Number) :- var(Number), !.
tr_noun_in_number(english, _, _) :- !.
tr_noun_in_number(Side, X, Number) :- tr_lexeme(Side, X, L, Number), tr_class_of(L, noun), !.

%% AN ELIDED ARTICLE SAYS NO GENDER -- `l'' is `lo' and `la' alike -- so a
%% name after one takes the gender the lesson states of it: `l'Italia',
%% `"italia" is feminine.' Without one it is the article's first reading.
tr_name_gender(foreign, w(DW, _), [w(N0, _)|_], _, G) :-
    tr_solve(elision_of(DW, _)),
    %% (the name in small letters, as the lesson states it: a name the lesson knows travels with its capital,
    %% `Italia', and asked so it had no gender and took the masculine of `lo', `El Italia que padece')
    atom(N0), downcase_atom(N0, N),
    ( tr_holds(feminine(N)) -> G = feminine ; tr_holds(masculine(N)) -> G = masculine ), !.
tr_name_gender(_, _, _, G, G).

tr_name_run_rev(Side, [W|Ws], [W|Ns], Rest) :- tr_name_word(Side, W), !, tr_name_run_rev(Side, Ws, Ns, Rest).
tr_name_run_rev(_, Ws, [], Ws).

tr_name_pre_int(Side, [A, J|Ws], [advn(A), J|Os]) :-
    A = w(_, _), J = w(_, _), tr_intensifier(Side, A, J), !, tr_name_pre_int(Side, Ws, Os).
tr_name_pre_int(Side, [W|Ws], [W|Os]) :- !, tr_name_pre_int(Side, Ws, Os).
tr_name_pre_int(_, [], []).

%% A NAME'S FIRST WORDS MAY BE WORDS THE LESSON KNOWS: `dal giornalista rai
%% Salvatore Biazzo' is one man, and `Salvatore' is a saviour in the
%% vocabulary -- read as an adjective of the noun it crossed as `Salvador',
%% and `un libro Home Video' had two words where the apposed name takes one.
%% A run of capitalised words at the end of a phrase, after a word without a
%% capital, one of which no lesson knows, is one name, spelled as the source
%% spelled it, apposed to the noun as `il presidente Scalfaro' is (`video'
%% is a word of the lesson's; `la Casa Bianca', every word known, is still
%% the white house). APPOSED TO A NOUN, which the words before it must have:
%% after an article alone the run is the phrase's head, and `sul Monte
%% Livata' made one name of it, left the phrase no noun, and refused Livata's
%% second sentence -- 99.5 million inferences where 1.8.5 read it in 32
%% (and before an apposition that ends the phrase: `de la entidad
%% catalanista Òmnium Cultural, Josep Millàs,' -- the association's name,
%% then its president's; held to the phrase's end the run was two words, and
%% the name before the apposition is one, tr_apposed_name/4)
tr_tail_name(foreign, Words0, Words) :-
    (   append(Words1, [AP], Words0), AP = w(_, appos) -> Tail = [AP] ; Words1 = Words0, Tail = [] ),
    append(Front, Run, Words1), Front = [_|_], Run = [_, _|_],
    last(Front, F), F = w(_, FC), FC \== upper,
    forall(member(X, Run), X = w(_, upper)),
    once(( member(L, Run), tr_name_word(foreign, L) )),
    once(( member(w(NW, _), Front), tr_is(foreign, w(NW, lower), noun) )), !,
    findall(C, ( member(w(X, _), Run), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', N),
    append(Front, [w(N, upper)|Tail], Words).
tr_tail_name(_, Words, Words).

%% a word of a name: capitalised, and no lesson knows it
tr_name_word(Side, w(W, upper)) :- \+ tr_known_word(Side, W).
%% (and one the lesson says is a name, with its capital inside a sentence,
%% whatever else it knows the word as: `"metrópolis" is a name.' -- `el
%% consorcio integrado por el grupo Metrópolis' is a group called that, and
%% read with `metrópolis' for a common noun the sentence was refused)
tr_name_word(foreign, w(W, upper)) :- atom(W), tr_solve(name(W)).
%% (and one in small letters that the lesson says is a name and knows as
%% nothing else: `lo speciale superquark di Piero Angela' is the programme
%% by its name, which the paper writes small -- `"superquark" is a name.',
%% as `"les lions" is a name.' says it of two words)
tr_name_word(foreign, w(W, lower)) :- nb_getval('$tr_small_name', yes), atom(W), tr_solve(name(W)), \+ tr_known_word(foreign, W).
%% ... or one the lesson knows only as a verb's form, which is a name inside
%% a sentence as it is alone after a preposition (tr_np/3's `croce in Usa'):
%% `dijo haber propuesto a Porta la confección' -- `porta' is what `portar'
%% says of one person, and with no name word in it the phrase ran on through
%% the article after it. (The head's capital is lowered before this where
%% the lesson knows the word.)
tr_name_like(Side, W) :- tr_name_word(Side, W), !.
tr_name_like(foreign, w(W, upper)) :-
    atom(W), \+ sub_atom(W, _, _, _, ' '), tr_verb_form_word(W),
    \+ tr_is(foreign, w(W, lower), noun), \+ tr_is(foreign, w(W, lower), adjective),
    \+ tr_is(foreign, w(W, lower), pronoun), !.

%% A NAME APPOSED TO A NOUN: `il presidente Scalfaro', `la Tate Gallery' the
%% other way round. It stands where an adjective stands and crosses as
%% ITSELF, which is what being a name means -- and only at the END of a
%% phrase that has a DETERMINER, because bare `Sabato Mladic' is a day and a
%% surname and nothing says where one ends.
%% ... after a determiner, or after a noun written with its capital: `Monte
%% Livata', `Regione Lazio' are one place each, with no article in front
%% ... AND AFTER A NOUN IN SMALL LETTERS, A NAME OF SEVERAL WORDS: `la
%% cadena de radio Ona Catalana' -- the radio network, named. The noun has
%% no capital, so where the name begins is not in doubt, and tr_tail_name/3
%% has joined its words; with no determiner before `radio' the phrase had
%% no reading and the sentence was refused. The noun is no adverb: `E anche
%% "La Repubblica" ci sembrava ...' has `anche', also, which is the plural
%% of `anca', a hip, as well, and read as the noun of a phrase with the
%% paper's name after it, it cost the sentence 105 000 inferences for no
%% reading
%% ... AND OF ONE WORD NO LESSON KNOWS, after a NOUN in small letters: `un
%% solo centro di addestramento Esa' is the ESA's training centre -- where
%% the name begins is not in doubt for the same reason, and with no
%% determiner before `addestramento' the phrase had no reading
tr_apposed_name(Side, Det, Words, w(W, upper)) :-
    (   Det \== none -> true
    ;   Words = [w(_, upper), _|_] -> true
    ;   Words = [X, w(N, upper)], X = w(_, lower), \+ tr_is(Side, X, adverb),
        (   sub_atom(N, _, _, _, ' ') -> true
        ;   tr_name_word(Side, w(N, upper)), tr_is(Side, X, noun),
            %% (never after a time: `Sabato Mladic aveva spedito un fax' is a
            %% day and the man who sent it -- the head's capital comes off a
            %% time, and read as a noun with a name after it `sabato Maria'
            %% was a Saturday called Maria, with nobody for the verb)
            \+ ( tr_noun_of_lesson(X, TN), tr_holds(time(TN)) )
        )
    ),
    last(Words, w(W, upper)).
tr_apposed_name(_, _, Words, w(W, appos)) :- last(Words, w(W, appos)).
%% ... AND A NAME BEFORE AN APPOSITION, after a determiner: `Il segretario
%% Ds, Piero Fassino, è capace' -- `Ds' is the party's name, apposed to the
%% noun, and the name set off after it is the person's. The apposition is the
%% last word, so the first clause above held the party's name to the phrase's
%% end and the phrase had no reading.
tr_apposed_name(_, Det, Words, w(W, upper)) :-
    Det \== none, append(_, [w(W, upper), w(_, appos)], Words), !.
%% ... AND ADJECTIVES MAY FOLLOW IT, on the lesson's side and after a
%% determiner: `il governo Dini successivo' is the Dini government that came
%% after. With the name held to the phrase's end the adjective was left
%% over as a complement of its own, and the reduced relative that ended on
%% that phrase lost its agent: `pubblicato dal giornale' came out `emitido
%% desde el diario', published FROM it.
tr_apposed_name(_, Det, Words, w(W, upper)) :-
    Det \== none,
    append(_, [w(W, upper)|After], Words), After = [_|_],
    forall(member(A, After), ( A = w(_, lower), tr_is(foreign, A, adjective) )), !.

%% the gender of the determiner a writer chose, where the phrase carried none
tr_written_gender(foreign, [o(DW, _)|_], G) :- tr_lexeme(foreign, DW, DL, _), tr_gender(DL, G), G \== none, !.
tr_written_gender(_, _, none).

%% the run of them at the head of a list, and what is left after it
tr_name_run([W|Ws], [W|Cs], Rest) :- tr_name_word(foreign, W), !, tr_name_run(Ws, Cs, Rest).
tr_name_run(Ws, [], Ws).

%% what a determiner says about a phrase whose noun cannot say it itself
tr_det_gender(english, _, _, none, singular) :- !.
tr_det_gender(foreign, w(DW, _), DL, G, Number) :-
    ( tr_lexeme(foreign, DW, DL, N0) -> Number = N0 ; Number = singular ),
    tr_gender(DL, G).

%% a participle of a verb the lesson gives, on either side
tr_participle_here(foreign, P, L) :- tr_solve(participle_of(P, L)), tr_known(foreign, L), !.
tr_participle_here(english, P, L) :- en_passive_participle(P, L), !.

%% a participle's number: plural when the lesson states it as the plural of
%% its singular, as the builder does for every participle that inflects
%% (steadfast: asked with the number given, the default clause answered
%% `singular' of EVERY participle -- `negli articoli apparsi il 12 luglio'
%% read `apparsi il 12 luglio' as an absolute clause whose participle agreed
%% with the date, where it is the articles', which appeared on it)
tr_participle_number(P, N) :- ( tr_solve(plural_of(P, _)) -> N = plural ; N = singular ).

%% A PARTICIPLE BEFORE A PHRASE IT AGREES WITH IS AN ABSOLUTE CLAUSE: `que el
%% lehendakari adelante las elecciones en Euskadi dada la situación de
%% minoría de su Ejecutivo' -- given the situation. Read into the phrase
%% before it, it was a reduced relative, `Euskadi given', and the situation
%% the verb's second object. It travels as abs(Lexeme, Phrase), and every
%% writer puts the participle before the phrase, agreeing with it: `data la
%% situazione', `given the situation'. Only a participle no lesson calls a
%% noun, before a determiner of its own gender and number: `la ley aprobada
%% la semana pasada' agrees too and reads so, which every writer puts back in
%% the same words.
tr_absolute_start(foreign, [w(P, _), D, _|_]) :- tr_absolute_start0(no, P, D).
%% ... AND ONE AFTER A COMMA MAY BE A NOUN TOO: `visto il parere assai
%% critico' -- given the opinion, `visto' being the visa as well. After a
%% comma nothing before it can be the noun's determiner, so the word is the
%% participle and the phrase after it its own; read as the predicate of the
%% clause before it, the participle stayed masculine, `visto la opinión', where
%% Spanish agrees, `vista la opinión'
tr_absolute_start(foreign, sep, [w(P, _), D, _|_]) :- tr_absolute_start0(yes, P, D).
tr_absolute_start0(Sep, P, D) :-
    tr_participle_here(foreign, P, _), ( Sep == yes -> true ; \+ tr_is(foreign, w(P, lower), noun) ),
    tr_determiner(foreign, D, DL, DK), DK \== possessive,
    %% (an ARTICLE after a noun that is a participle too: `visto che erano
    %% evidenti ...' is `seen that', and `che' is a determiner, `what')
    ( Sep == yes -> DK == article ; true ),
    tr_det_gender(foreign, D, DL, G, N),
    ( tr_holds(feminine(P)) -> G == feminine ; G == masculine ),
    tr_participle_number(P, N), !.

%% what may follow a reduced relative and belong to it: its agent, and
%% nothing else -- a phrase after it is the sentence's, not the participle's
%% ... or an adverb of its own: `la primera medida votada ayer en el congreso'
%% was voted yesterday, and with `ayer' the sentence's it was lifted out of
%% the phrase and written at the end, where it said when the measure PERMITTED
tr_reduced_agent(foreign, [A], [adv(A)]) :-
    A = w(AW, _), atom(AW), tr_plain_adverb(foreign, A), \+ tr_is(foreign, A, preposition), !.
%% ... and what follows the agent is the participle's too, when it is only
%% adjuncts: `i risultati raggiunti da Chrysler negli ultimi quattro anni e
%% mezzo' were reached by Chrysler IN those years, and with the agent held to
%% the end of the phrase `da Chrysler' was read as where they came from
%% ... or a NAME, which is what the participle says of its noun: `un violín
%% llamado Ex Von Szerdahely VieuxTemps' is the violin CALLED that. It
%% travels as the participle's object and is written back as itself.
%% After such a participle EVERY capitalised word is the name's, one the
%% lesson knows among them: `Ex' is the adjective `former' to the lesson,
%% and the violin is the `Ex Von Szerdahely VieuxTemps'.
tr_reduced_agent(Side, Ws, [obj(name(N))]) :-
    Ws = [w(_, upper)|_], tr_np(Side, Ws, name(N)), !.
tr_reduced_agent(Side, Ws, [obj(name(N))]) :-
    Ws = [w(_, upper), _|_], forall(member(W, Ws), W = w(_, upper)),
    member(W1, Ws), tr_name_word(Side, W1), !,
    findall(C, ( member(w(X, _), Ws), tr_cap(X, C) ), Cs), atomic_list_concat(Cs, ' ', N).
%% ... and a RANGE OF DAYS, which is when the participle holds: `l'isola di
%% Ustica "proibita" dal primo al 31 agosto'
tr_reduced_agent(Side, Ws, Cs) :-
    Ws = [P|Rest], tr_is(Side, P, preposition), tr_date_range(Side, Rest),
    tr_complements(Side, Ws, Cs), Cs \== [], tr_adjuncts(Cs), \+ memberchk(sep, Cs), !.
%% ... AND ADJUNCTS BEFORE THE AGENT: `el polémico reparto de las 33
%% licencias ... efectuado a principios del pasado mes de mayo por el Consell
%% Executiu de la Generalitat' -- done early in May, by the council. The
%% agent was read only first, so the phrases before it were the reading's
%% end and `por' a preposition of `for', `effettuata ... per il Consell'.
tr_reduced_agent(Side, Ws, Cs) :-
    Ws = [P0|_], tr_is(Side, P0, preposition), \+ tr_means_by(Side, P0),
    append(Pre, [P|Rest], Ws), Pre \== [], Rest \== [],
    P = w(_, _), tr_is(Side, P, preposition), tr_means_by(Side, P),
    %% (three tests before the adjuncts are read, each cheap: adjuncts never
    %% end on a coordinator, and after the word for `by' the agent's clause
    %% below wants no bare noun and no range of days. Read first, the words
    %% in front cost the islands report's `le più canicolari Eolie, interdette
    %% al traffico dal 4 al 24 agosto, ...' 231 000 inferences, `al traffico'
    %% read for a range of days, and Livata's `la passeggiata nei boschi e da
    %% dove abbiamo ...' 218 000, `in i boschi e' read before `da dove')
    \+ ( last(Pre, LP), LP = w(_, _), tr_coord(Side, LP) ),
    \+ tr_bare_start(Side, Rest), \+ tr_date_range(Side, Rest),
    tr_complements(Side, Pre, Cs1), Cs1 \== [], forall(member(C, Cs1), tr_adjunct(C)), \+ memberchk(sep, Cs1),
    tr_reduced_agent(Side, [P|Rest], Cs2), Cs2 = [by(_)|_], !,
    append(Cs1, Cs2, Cs).
%% ... AND AN INSERTION BETWEEN COMMAS AFTER THEM: `le richieste fatte ieri, a conclusione della requisitoria, dal pm
%% Andrea De Gasperis' were made yesterday, at the end of the closing speech, by the prosecutor. With no comma before
%% the agent the participle took `ieri' alone, and `dal pm' was a phrase of `from' the copula took, `del fiscal'
tr_reduced_agent(foreign, Ws, Cs) :-
    append(Pre, [comma|Rest0], Ws), Pre \== [], \+ memberchk(comma, Pre),
    append(Mid, [comma, P|Rest], Rest0), Mid \== [], \+ memberchk(comma, Mid), Rest \== [],
    P = w(_, _), tr_is(foreign, P, preposition), tr_means_by(foreign, P),
    tr_complements(foreign, Pre, Cs1), Cs1 \== [], tr_adjuncts(Cs1),
    tr_complements(foreign, Mid, Cs2), Cs2 \== [], tr_adjuncts(Cs2),
    tr_reduced_agent(foreign, [P|Rest], Cs3), Cs3 = [by(_)|_], !,
    append([Cs1, [sep|Cs2], [sep|Cs3]], Cs).
%% ... AND A DAY OR AN ADVERB ALONE BEFORE THE AGENT: `il disegno sul conflitto
%% d'interessi varato giovedì dal senato' was passed on Thursday by the senate
%% -- with a word between the participle and the word for `by' the agent was not
%% read, and `dal senato' was a phrase of `from', `desde el senado'
tr_reduced_agent(foreign, [T, P|Rest], Cs) :-
    T = w(_, _), P = w(_, _), Rest = [_|_], tr_is(foreign, P, preposition), tr_means_by(foreign, P),
    \+ tr_is(foreign, T, preposition),
    tr_complements(foreign, [T], Cs1), Cs1 = [C1], ( C1 = at_time(_) ; C1 = adv(_) ),
    tr_reduced_agent(foreign, [P|Rest], Cs2), Cs2 = [by(_)|_], !,
    append(Cs1, Cs2, Cs).
%% ... and a day and its part: `un'intervista trasmessa giovedì sera dalla tv danese' was broadcast on Thursday
%% evening BY Danish television, and it was `from the Danish television'
tr_reduced_agent(foreign, [T1, T2, P|Rest], Cs) :-
    T1 = w(_, _), T2 = w(_, _), P = w(_, _), Rest = [_|_], tr_is(foreign, P, preposition), tr_means_by(foreign, P),
    \+ tr_is(foreign, T1, preposition),
    tr_complements(foreign, [T1, T2], Cs1), Cs1 = [at_time(_)],
    tr_reduced_agent(foreign, [P|Rest], Cs2), Cs2 = [by(_)|_], !,
    append(Cs1, Cs2, Cs).
%% ... AND A TIME: `los hechos ocurridos el pasado domingo arrastran la
%% situación' -- the day they happened. A phrase that names a day or a month is
%% nobody's agent and no object of the verb after it, so it is the participle's
%% own: with nothing but an agent allowed here the phrase was left to a verb
%% that is not its, and the sentence was refused (`ocurridos ayer' read, an
%% adverb the clause took)
tr_reduced_agent(foreign, Ws, Cs) :-
    Ws = [w(_, _)|_], tr_time_noun_then(4, Ws, After), tr_time_tail(After), tr_time_after(foreign, Ws),
    tr_complements(foreign, Ws, Cs), Cs = [at_time(_)|_], tr_adjuncts(Cs), \+ memberchk(sep, Cs), !.
%% ... AND A SECOND AGENT JOINED TO THE FIRST: `páginas abiertas por miembros de estas sectas o por las mismas
%% hermandades' were opened by members or by the fraternities themselves -- read on as the first agent's adjuncts,
%% the second was a phrase of `for', `or for the same fraternities'. Each agent is by/1 and the coordinator between
%% them cnj/1, as the complements reader keeps one
tr_reduced_agent(foreign, Ws, Cs) :-
    Ws = [P|Rest], tr_is(foreign, P, preposition), tr_means_by(foreign, P),
    append(Mid, [Co, P2|Rest2], Rest), Mid = [_|_], Rest2 = [_|_],
    Co = w(CW, _), atom(CW), tr_coord(foreign, Co),
    P2 = w(_, _), tr_means_by(foreign, P2), tr_is(foreign, P2, preposition),
    \+ memberchk(comma, Mid),
    tr_reduced_agent(foreign, [P|Mid], Cs1), Cs1 = [by(_)|_],
    tr_reduced_agent(foreign, [P2|Rest2], Cs2), Cs2 = [by(_)|_], !,
    append(Cs1, [cnj(Co)|Cs2], Cs).
%% ... AND A SECOND PARTICIPLE JOINED TO IT, with its own agent: `il farmaco
%% prescritto da Casotto e assunto da Rosi' -- prescribed by Casotto and taken
%% by Rosi, both said of the drug. The phrase of the first agent was read on
%% through the coordinator (`Casotto e assunto da Rosi'), no phrase at all, and
%% the reduced relative was refused: it ends at the coordinator that a
%% participle follows, and the second participle is cpart/3, written after
%% the first agent and agreeing with the same noun
%% ... with the first agent's own phrases between it and the coordinator: `El plan ..., propuesto por el
%% Gobierno de Jospin y aprobado por la Asamblea corsa el pasado viernes, prevé ...' -- read as one phrase
%% the agent and its `of' were no object phrase, and the sentence was refused
tr_reduced_agent(foreign, Ws, Cs) :-
    Ws = [P|Rest], tr_is(foreign, P, preposition), tr_means_by(foreign, P), Rest = [_, _, _|_],
    append(PW0, [C2, w(P2, _)|Rest3], Rest), PW0 = [_|_], C2 = w(CW, _), atom(CW), atom(P2),
    tr_coord(foreign, C2), tr_participle_here(foreign, P2, L2), \+ tr_is(foreign, w(P2, lower), noun),
    (   tr_phrase_np(foreign, PW0, NP) -> Adj = []
    ;   tr_phrase_words(foreign, PW0, PW, AW), PW \== [], AW \== [], tr_phrase_np(foreign, PW, NP),
        tr_complements(foreign, AW, Adj), Adj \== [], forall(member(C, Adj), tr_adjunct(C)), \+ memberchk(sep, Adj)
    ),
    ( Rest3 == [] -> Cs2 = [] ; tr_reduced_agent(foreign, Rest3, Cs2) ), !,
    append([by(NP)|Adj], [cpart(C2, L2, Cs2)], Cs).
tr_reduced_agent(Side, Ws, [by(NP)|Cs]) :-
    Ws = [P|Rest], tr_is(Side, P, preposition), tr_means_by(Side, P), \+ tr_bare_start(Side, Rest),
    \+ tr_date_range(Side, Rest), \+ tr_time_after(Side, Rest),
    (   %% ... AND THE AGENT'S OWN RELATIVE CLAUSE AFTER A COMMA: `la
        %% possibilità offerta dall'università, che spero si concretizzi' is
        %% the possibility the university offers, and one I hope comes true.
        %% Read to the comma, the agent had the clause after it and failed, so
        %% the phrase ended at `da', and `dall'università, che ...' was a
        %% phrase of `from': `ofrecida desde la universidad'. The clause hangs
        %% on the agent's phrase, the last before the comma (tr_phrase_nrc/3),
        %% and runs to the end of the words as that clause does
        Side == foreign, memberchk(comma, Rest), tr_phrase_nrc(Side, Rest, NP)
    ->  Cs = []
    ;   tr_phrase_words(Side, Rest, PW, Rest2), PW \== [], tr_phrase_np(Side, PW, NP),
        (   Rest2 == [] -> Cs = []
        ;   tr_complements(Side, Rest2, Cs), Cs \== [], forall(member(C, Cs), tr_adjunct(C)),
            %% (never a comma last: a phrase that ends on one is the phrase a
            %% relative clause after it hangs on, and with the comma read as
            %% the participle's own complement `la casa costruita dal padre,
            %% che era ricco' hung the clause on the house, `que era rica')
            \+ last(Cs, sep)
        )
    ).

%% WHAT FOLLOWS A PARTICIPLE STANDING AFTER ITS NOUN: the agent and its
%% adjuncts (tr_reduced_agent/3) -- BUT A VERB WHOSE PERFECT TAKES THE COPULA
%% HAS NO PASSIVE, SO NO AGENT: `uno uscito da elezioni generali' came FROM
%% the elections, and read as the agent it was `salido por elecciones', gone
%% out by them. The lesson says which verbs those are -- `"è" is the
%% auxiliary of "esce".', a line since 1.6.17 -- and the phrase after the
%% preposition is an ordinary one, pp/2.
%% NOT `intransitive', which the first cut asked: that says a verb MAY take
%% no object (1.6.8's inversion), and `"domina" is intransitive.' made the
%% opera review's `la función dominada por la excepcional Anderson' come out
%% `dominata per', the agent lost. `dominare' takes `avere'.
tr_ptc_complements(Side, L, [P|R2], Comps) :-
    Side == foreign, tr_unaccusative(L), tr_is(Side, P, preposition), !,
    tr_phrase_rest(Side, R2, NP, R3),
    (   R3 == [] -> Cs = []
    ;   tr_complements(Side, R3, Cs), Cs \== [], forall(member(C, Cs), tr_adjunct(C))
    ),
    %% (and the phrase its verb governs is marked, as below: `Cifre nate da un'indagine' are born of one, `nacidas
    %% de', where the lesson's `from' wrote `desde')
    tr_ptc_governed(Side, L, [pp(P, NP)|Cs], Comps).
tr_ptc_complements(Side, L, Rest, Comps) :- tr_reduced_agent(Side, Rest, Comps0), tr_ptc_governed(Side, L, Comps0, Comps).
%% ... AND THE PHRASE THE PARTICIPLE'S VERB GOVERNS IS MARKED, as a clause's is (tr_governed/3):
%% `un régimen calificado de "semilaboral" por sus allegados' is described AS one (`"califica"
%% takes "de" before the phrase.'), and with the clause's verb asked, `mantiene', it was `described
%% of "semi-working"' -- the first phrase of a preposition, as the clause's
tr_ptc_governed(foreign, L, Cs0, Cs) :-
    atom(L), append(Pre, [pp(w(PW, PC), NP)|Post], Cs0), atom(PW), NP \= adv(_), NP \= gov(_, _),
    \+ memberchk(pp(_, _), Pre),
    tr_solve(take_before(L, PW, phrase)), !,
    append(Pre, [pp(w(PW, PC), gov(L, NP))|Post], Cs).
%% (and the phrase of `of' of a participle English writes with one, its first phrase: `de la plaza, cubierta de
%% botellas' is the square, covered WITH bottles, read as a reduced relative between commas -- tr_of_participle/2)
tr_ptc_governed(foreign, L, Cs0, Cs) :-
    atom(L), append(Pre, [pp(P, NP)|Post], Cs0), NP \= adv(_), NP \= gov(_, _), \+ memberchk(pp(_, _), Pre),
    tr_means_of(foreign, P), tr_lexeme_across(L, english, E), en_of_participle(E), !,
    append(Pre, [pp(P, gov(L, NP))|Post], Cs).
tr_ptc_governed(_, _, Cs, Cs).
tr_unaccusative(L) :- tr_solve(auxiliary_of(A, L)), tr_copula_lexeme(A), !.

%% A BARE NOUN IN THE SINGULAR IS NOBODY WHO DID ANYTHING: `una media de 22
%% empleados por empresa' is twenty-two to a company, and `por' is `by' as
%% well, so `empleados' was taken for the participle and the company for
%% who employed them -- `22 impiegato da impresa'. An agent has a
%% determiner, a number or a name (`por la consultora', `dai soldati', `da
%% Chrysler'); a noun alone after the word, lower case and singular, says
%% how many or how -- `por empresa', `por unanimidad' -- and reads as the
%% phrase of any other preposition.
%% -- and a noun that is a verb's form as well may begin a clause: `juegan
%% muy ordenados y SON muy competitivos' is two clauses, and `son' is a
%% sound too, so read as one the second verb came out `suono'
%% -- and one that closes a quotation is as bare as any: `crea "delle
%% asimmetrie tra accusa e difesa" e le posizioni delle parti ... assumono'
%% divided at the first `e', and `difesa"' -- the word that closes the
%% quotation -- began the second clause, its subject `defence and the
%% positions'. The same words in every language, and an IR with the defence
%% doing what the positions do
%% -- and so is a noun that is the first person of a verb, before the word for
%% `that': `Il cane dorme e credo che il gatto dorma' -- `credo' is a creed to
%% the lesson, and a bare noun there joined nothing: the sentence was refused
tr_bare_start(Side, [W|Rest]) :-
    W = w(X, C), memberchk(C, [lower, qclose]), \+ tr_determiner(Side, W, _, _), \+ tr_is(Side, W, number), \+ tr_is(Side, W, pronoun),
    tr_is(Side, W, noun), \+ tr_is(Side, W, adjective), \+ tr_is(Side, W, verb),
    tr_lexeme(Side, X, _, singular),
    \+ tr_first_person_that(Side, [W|Rest]), !.
%% a first person of a verb and the word for `that' after it -- or the end of
%% the phrase read so far, when the piece goes on with it
tr_first_person_that(Side, [w(X, _)|Rest]) :-
    atom(X), tr_form(X, FL, _, _, first), atom(FL), tr_class_of(FL, verb),
    (   Rest = [T|_] -> tr_that_here(Side, T)
    ;   tr_global('$tr_piece', Piece), append(_, [w(X, _), T|_], Piece), tr_that_here(Side, T)
    ), !.

%% A DEGREE IS A DEGREE OF AN ADJECTIVE, and the two sides mark it in
%% different places. The lesson's language puts a WORD in front -- `piu
%% ricco', `mas rico' -- which the lesson names (`The word "piu" begins the
%% comparative.', the shape `The word "per" begins the purpose' already
%% has), and that one word spells the comparative and the superlative
%% alike: what tells them apart is the ARTICLE, `il paese piu ricco' being
%% the richest country and `un paese piu ricco' a richer one. English marks
%% it on the adjective itself, richer and richest, with `more' and `most'
%% for the words its endings will not take.
%%
%% So it travels as deg(Degree, w(Word, Case)) among the adjectives, and
%% the DEGREE is what English needs: the foreign writer spells both the
%% same and lets its own article say which.
tr_degrees(_, _, [], []).
%% ... AND ITS TERM OF COMPARISON, WHEN THAT IS ADJECTIVES TOO: `estas hordas
%% más vikingas que británicas' are these hordes, more Viking than British.
%% Read as a phrase with the degree and nothing after it, `que británicas'
%% was a comparison with a phrase whose noun was `British', and the subject
%% of the copula before it was refused. degt(Degree, Adjective, Adjectives)
%% is the term, and it ends the phrase's adjectives: each writer puts its
%% degree, its word for `than' and the adjectives after the noun, where
%% English puts an adjective with a complement of its own
%% (always the comparative: a term of comparison says so whatever the
%% article, which makes a superlative of a bare degree -- `los perros más
%% negros que blancos' came out `The dogs blackest than white')
%% The lesson's side is read by the clause below that reads the degree, so
%% that the degree word is asked once a position: tr_complements/3 walks
%% every word list it reads, and a second ask cost a sentence of Ferlaino's
%% 1.3 million inferences, 12 %
tr_degrees(english, _, [w(more, _), w(W, C), w(than, _)|Ws], [degt(comparative, w(W, C), Ws)]) :-
    tr_is(english, w(W, C), adjective), tr_all_adjectives(english, Ws), !.
tr_degrees(english, D, [w(M, _), w(W, C)|Ws], [deg(D1, w(W, C))|Os]) :-
    en_degree_marker(M, D1), tr_is(english, w(W, C), adjective), !,
    tr_degrees(english, D, Ws, Os).
%% ... and `more'/`most' alone is NOT one, or `more bread' would read as
%% the comparative of `much' and cross as a word. The pair above is the
%% only reading they have here.
tr_degrees(english, D, [w(W, C)|Ws], [deg(D1, w(L, C))|Os]) :-
    \+ en_degree_marker(W, _), en_degree_word(W, D1, L), !,
    tr_degrees(english, D, Ws, Os).
%% ... AND A WORD THAT IS A COMPARATIVE BY ITSELF: `el mejor de los
%% intérpretes' is the best of them, and the dictionary gives `mejor' only
%% as `good', so it came out `il buono degli interpreti'. The lesson says
%% which words these are -- `"mejor" is the comparative of "bueno".' -- and
%% the degree travels on the plain adjective, as the one `más' marks does.
tr_degrees(foreign, D, [w(W, C)|Ws], [deg(D, w(B, C))|Os]) :-
    tr_lexeme(foreign, W, L, _), tr_solve(comparative_of(L, B)), !,
    tr_degrees(foreign, D, Ws, Os).
%% ... AND THE DEGREE BELOW: `i meno abbienti' are the least wealthy, and
%% the lesson's word for `less' before an adjective marks it as its word for
%% `more' does -- read apart, `meno' was an adverb of the verb and the
%% wealthy slept less. It travels as deg(less(Degree), Word), and English
%% writes `less' and `least', the lesson its own adverb.
%% (THE ADJECTIVE IS ASKED FIRST. This clause is tried at every word of every
%% list the complement reader is given, and the degree word and the word for
%% `less' each cost a lexeme and a question of the lesson, where the class
%% is kept once a sentence: asked first, the two cost the controls 5.6
%% million inferences in five sentences.)
tr_degrees(foreign, D, [w(M, _), w(W, C)|Ws0], Out) :-
    tr_is(foreign, w(W, C), adjective),
    ( tr_degree_word(M) -> Less = no ; tr_less_word(M) -> Less = yes ), !,
    (   Less == no, Ws0 = [w(Q, _)|Ws], Ws \== [], tr_solve(mean(Q, than)), tr_all_adjectives(foreign, Ws)
    ->  Out = [degt(comparative, w(W, C), Ws)]
    ;   ( Less == yes -> D1 = less(D) ; D1 = D ),
        Out = [deg(D1, w(W, C))|Os], tr_degrees(foreign, D, Ws0, Os)
    ).
%% AND THE PHRASE DECIDES LAST, which is why this clause exists: the
%% complements are folded before the phrase inside them is, at the
%% comparative, because a bare predicate has no article to read -- so an
%% object's own article must be allowed to make it a superlative after all.
%% Only on the lesson's side: English took the degree off the WORD.
tr_degrees(foreign, D, [deg(D0, A)|Ws], [deg(D1, A)|Os]) :- !,
    ( D0 = less(_) -> D1 = less(D) ; D1 = D ),
    tr_degrees(foreign, D, Ws, Os).
tr_degrees(Side, D, [W|Ws], [W|Os]) :- tr_degrees(Side, D, Ws, Os).

%% the word this lesson puts in front of a comparative
tr_degree_word(M) :- tr_lexeme(foreign, M, L, _), tr_solve(begin(L, comparative)), !.
%% ... and the adverb it means `less' by
tr_less_word(M) :- atom(M), tr_lexeme(foreign, M, L, _), tr_solve(mean(L, less)), tr_class_of(L, adverb), !.
tr_less_out(M) :- tr_meanings_of(less, foreign, adverb, [M|_]), !.
tr_degree_out(W) :- once(( tr_solve(begin(W0, comparative)), W = W0 )).

%% a phrase whose determiner is the definite article makes a superlative of
%% the degree inside it, and every other determiner a comparative
tr_degree_of(english, _, comparative).
tr_degree_of(foreign, det(article, DL, _), superlative) :- tr_solve(mean(DL, the)), !.
%% ... and so does a possessive: `sus mejores noches' is her BEST nights,
%% `le sue migliori serate', where it came out `her better nights'
tr_degree_of(foreign, det(possessive, _, _), superlative) :- !.
tr_degree_of(foreign, _, comparative).

%% a word that may be an adjective in a phrase: known, and no preposition,
%% pronoun or verb -- or the `and' between two
tr_adj_word(_, deg(_, _)) :- !.
tr_adj_word(_, degt(_, _, _)) :- !.
tr_adj_word(_, int(_, _)) :- !.
tr_adj_word(_, mti(_)) :- !.
tr_adj_word(_, advn(_)) :- !.
tr_adj_word(Side, A) :- tr_coord(Side, A), !.
tr_adj_word(Side, w(W, C)) :-
    tr_lexeme(Side, W, _, _),
    %% no preposition -- unless the lesson calls it an adjective too, which
    %% only a phrase's last word can be (tr_final_adjective/3): `in un paese
    %% vicino' is a town nearby
    \+ ( tr_is(Side, w(W, C), preposition), \+ tr_is(Side, w(W, C), adjective) ),
    %% no pronoun -- unless the lesson calls it an adjective too: `un altro
    %% provvedimento', `nessun altro provvedimento' is another measure, and
    %% `altro' is the pronoun `others' as well, so the phrase was refused
    \+ ( ( tr_object_pronoun(Side, W, _) ; tr_subject_pronoun(Side, W, _, _) ), \+ tr_is(Side, w(W, C), adjective) ),
    %% no verb's form -- unless the lesson calls it an adjective too: `clase
    %% media' is the middle class, and `media' is also what `mediar' says
    \+ ( tr_is(Side, w(W, C), verb), \+ tr_is(Side, w(W, C), adjective) ),
    %% ... NOR A WORD THE LESSON KNOWS ONLY AS AN ADVERB. `Qui solo due
    %% anni fa dominava il coprifuoco' read `qui solo due anni' as ONE
    %% phrase with `here' for an adjective of `years', so the plain reading
    %% won and the fronted clause never saw it. A word that is an adjective
    %% too (`solo', `molto') is still one, which is the judge's own rule in
    %% library(reasoning/tagger) said from this side.
    \+ ( tr_is(Side, w(W, C), adverb), \+ tr_is(Side, w(W, C), adjective) ),
    %% ... NOR THE WORD FOR `not', which denies a verb and describes no noun:
    %% `Las piedras pesan muy poco y no son reales' read `y no son reales' as
    %% one phrase, `son' the noun sound and `no' and `reales' its adjectives
    \+ ( atom(W), tr_negation_word(W) ),
    %% ... NOR A CONJUNCTION, A MODAL OR AN AUXILIARY. `descanso porque hay
    %% que dosificar' read as ONE phrase whose noun was `descanso' and whose
    %% adjectives were `because' and `must', and `riesgos y ha reclamado' as
    %% risks described by `has'; each of the three begins or carries a
    %% clause and describes no noun. A coordinator between two adjectives is
    %% read above, before this clause.
    \+ ( ( tr_is(Side, w(W, C), conjunction) ; tr_is(Side, w(W, C), modal) ; tr_is(Side, w(W, C), auxiliary) ),
         \+ tr_is(Side, w(W, C), adjective) ),
    %% ... NOR AN ARTICLE, which a phrase has at most one of and at its
    %% head. `Sabado el perro come el pan' read `Sabado el perro' as one
    %% phrase with `saturday' and `the' for adjectives of `dog', so the
    %% fronted clause never saw it. A POSSESSIVE is still an adjective
    %% here, because `il suo quartier generale' is one phrase.
    \+ tr_determiner(Side, w(W, C), _, article),
    \+ ( Side == foreign, tr_reflexive_word(W) ),
    %% ... NOR A RELATIVE WORD, which begins a clause and never describes a
    %% noun: `uno della Guardia di finanza CHE hanno pattugliato' read `che'
    %% as `what' and made it a finance's adjective
    \+ ( Side == foreign, tr_relative_word(foreign, W) ),
    %% ... NOR A NUMBER IN DIGITS, which counts a phrase and never describes
    %% one: `oltre 50 mezzi e 130 circa' took `e 130' for adjectives of
    %% `mezzi', and no language had an adjective to write for them
    \+ tr_digits(W),
    %% ... NOR A WORD THAT ASKS HOW MANY OR HOW MUCH, which opens the
    %% question the phrase stands before: `Su cento famiglie quanti sono i
    %% poveri?' took `quanti' for an adjective of the families, and no
    %% language had one to write
    %% ... NOR THE WORD FOR `when', `where', `how' OR `why', which opens a
    %% clause: `E così quando martedì le due delegazioni torneranno ad
    %% incontrarsi' took `quando' for an adjective of `martedì' -- a Tuesday
    %% called when -- and the time came out `el cuando martes'
    \+ ( Side == foreign, atom(W), \+ tr_is(Side, w(W, C), adjective),
         ( tr_how_many_word(W) ; tr_indirect_word(foreign, W, _) ) ).
tr_how_many_word(W) :-
    tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)), memberchk(E, ['how many', 'how much']), !.

%% a determiner: English's articles, possessives, demonstratives and the
%% determiners a lesson may give a word for (`each', `another', `many');
%% the lesson's, in either number -- det(Kind, Lexeme, Word)
tr_determiner(english, w(the, _), the, article).
tr_determiner(english, w(a, _), a, article).
tr_determiner(english, w(an, _), a, article).
tr_determiner(english, w(P, _), P, possessive) :- en_possessive(P).
tr_determiner(english, w(W, _), L, demonstrative) :- en_det(W, L, _), en_demonstrative(L).
tr_determiner(english, w(W, _), L, determiner) :- en_det(W, L, _), \+ en_demonstrative(L).
tr_determiner(foreign, w(W, _), L, article) :- tr_lexeme(foreign, W, L, _), tr_class_of(L, article).
tr_determiner(foreign, w(W, _), L, possessive) :- tr_lexeme(foreign, W, L, _), tr_class_of(L, possessive).
tr_determiner(foreign, w(W, _), L, demonstrative) :- tr_lexeme(foreign, W, L, _), tr_class_of(L, demonstrative).
tr_determiner(foreign, w(W, _), L, determiner) :- tr_lexeme(foreign, W, L, _), tr_class_of(L, determiner).

%% the noun of a phrase's content: the one word the lesson calls a noun;
%% none, or SEVERAL -- `el gato negro', where a vocabulary of any size calls
%% `negro' a noun as well as an adjective -- by position among them, the
%% first where adjectives follow the noun and the last otherwise
tr_noun(Words, Side, Noun, Adjs) :- tr_noun(Words, Side, no, Noun, Adjs).
tr_noun(Words, Side, Plural, Noun, Adjs) :-
    findall(W, ( member(W, Words), tr_is(Side, W, noun) ), Nouns),
    (   Nouns = [Noun] -> true
    %% ... and a PREPOSITION is no noun by its place: `quello di Berlusconi'
    %% took `di' for the noun of `quello' with the name apposed to it, and
    %% wrote `ese de Berlusconi' from an IR that said `that of'
    %% ... nor a QUESTION WORD that relates nothing, among other words:
    %% `¿Qué tal un poco de leche?' took `qué' for the noun of `tal', such
    %% what, once the lesson could read `un poco' -- it was refused, and came
    %% out `Such what of milk a bit?' (ALONE it is still one, `da dove' being
    %% from where -- the case found the guard asked of a one-word phrase)
    ;   Nouns == [] -> tr_noun_by_position(Words, Side, Noun), \+ tr_is(Side, Noun, preposition),
        ( Words = [_] -> true ; \+ tr_asking_word(Side, Noun) ),
        %% ... nor a RELATIVE WITH ITS ARTICLE, one word to the lesson: `La nota sulla quale aveva insistito era
        %% stata quella della valutazione' has `la quale' open the relative clause, and read as the noun `who'
        %% after `su' it was the note on who, `era' an era the insisting took for its object
        \+ ( Side == foreign, Noun = w(NW, _), tr_relative_word(foreign, NW), atomic_list_concat([_, _|_], ' ', NW) )
    %% ... and among several, the ONE that cannot be an adjective: `un esnob
    %% bate de béisbol' has `esnob' (a snob, and snobbish) before its noun,
    %% and position alone made the snob the head
    ;   findall(W, ( member(W, Nouns), \+ tr_is(Side, W, adjective) ), [Noun]) -> true
    %% ... and an ORDINAL before a noun is its adjective, though it is a noun too:
    %% `el segundo cuarto' is the second quarter, and `segundo' -- a second of
    %% time, and an ordinal -- was the head by position, `the fourth second'
    ;   Side == foreign, \+ ( member(W0, Nouns), \+ tr_is(Side, W0, adjective) ),
        append(_, [W1, W2|_], Words), W1 = w(OW, _), atom(OW), memberchk(W1, Nouns), memberchk(W2, Nouns),
        tr_ordinal_word(Side, OW) -> Noun = W2
    %% ... and among nouns that are all adjectives too, the ONE the lesson
    %% calls a person: `altos ejecutivos de medios de comunicación' are senior
    %% executives -- `alto' is a height and the alto voice to the lesson, and
    %% by position it was the head with `executive' for its adjective, which no
    %% writer could write
    %% (ALL of them adjectives too, as it says: with two nouns that are no
    %% adjectives beside them -- `per finanziare il miglioramento didattico
    %% universitario giurisprudenza medicina', a document's keywords -- the
    %% one person among the rest was made the head, and Spanish marked it as
    %% a person object, `financiar al perfeccionamiento ... médico')
    ;   Side == foreign, \+ ( member(W0, Nouns), \+ tr_is(Side, W0, adjective) ),
        findall(W, ( member(W, Nouns), tr_person_word(W),
                     %% (one the others agree with: `l'aeronautica militare' is the
                     %% air force, and `militare' -- a soldier -- is masculine,
                     %% which the feminine `aeronautica' could say nothing of; it
                     %% came out `el aeronáutico soldado')
                     \+ ( member(A, Nouns), A \== W, tr_genders_clash(W, A) ),
                     %% (and never one the lesson states in both genders, whose gender
                     %% says nothing of the others: `"militare" is feminine.', for the
                     %% adjective of `la campagna militare', made the air force the
                     %% aeronautical soldier again)
                     \+ ( W = w(WA, _), atom(WA), tr_stated_both(WA) ),
                     %% (and never a nationality after another noun: `la fisica italiana' is Italian physics, and
                     %% `italiana' -- an Italian woman, and Italian -- was the head as the one person, `the
                     %% physical Italian')
                     \+ ( Nouns = [N1|_], N1 \== W, tr_nationality_word(W) ) ), [Noun]) -> true
    %% ... and among nouns that are all adjectives too, the ONE that has a
    %% plural to be: `due sole alternative' is only two alternatives, and `sole'
    %% -- the sun, singular, as a noun; the feminine plural of `solo' as an
    %% adjective -- was the head by position, `dos solos alternativos'. A plural
    %% numeral or article says the head is a plural noun
    ;   Side == foreign, Plural == yes, \+ ( member(W0, Nouns), \+ tr_is(Side, W0, adjective) ),
        findall(W, ( member(W, Nouns), tr_plural_noun_word(W) ), [Noun]) -> true
    ;   tr_noun_by_position(Nouns, Side, Noun)
    ),
    select(Noun, Words, Adjs).
%% ... and a word the lesson says is NOT feminine beside a feminine one clashes
%% as well (`tr_genders_differ/2' wants both genders stated): `la directiva
%% azulgrana' is the Barça board, and `azulgrana' -- a Barça player, masculine
%% though it ends in `a', which the grammar would make feminine -- was the head
%% as the one person, `the managerial Barça player'
tr_genders_clash(W, A) :- tr_genders_differ(W, A), !.
tr_genders_clash(W, A) :- ( tr_not_feminine_beside(W, A) ; tr_not_feminine_beside(A, W) ), !.
tr_not_feminine_beside(w(NF, _), w(F, _)) :-
    tr_lexeme(foreign, NF, NL, N), tr_gender(NL, none), tr_solve(neg(feminine(NL))),
    tr_lexeme(foreign, F, FL, N), tr_gender(FL, feminine).
%% a word with a plural lexeme the lesson calls a noun
tr_plural_noun_word(w(W, _)) :- atom(W), tr_lexeme(foreign, W, L, plural), tr_class_of(L, noun), !.
%% a plural numeral or determiner before the content (`due', `le', `i'): the
%% numeral that is not one, or a determiner whose own lexeme is plural in that word
tr_plural_hint(Side, Det, Num, yes) :-
    (   Num = w(NW, _), atom(NW), tr_is(Side, Num, number), \+ memberchk(NW, [uno, un, una, 'un''', one, '1'])
    ;   Num == none, Det = det(_, DL, w(DW, _)), atom(DW), atom(DL), tr_lexeme(Side, DW, DL, plural)
    ), !.
tr_plural_hint(_, _, _, no).
tr_adjectives_then_name([w(N, upper)], [], N) :- !.
tr_adjectives_then_name([P|Ws], [P|Pre], N) :- P = w(_, lower), tr_is(foreign, P, adjective), tr_adjectives_then_name(Ws, Pre, N).
tr_person_word(w(W, _)) :- atom(W), tr_lexeme(foreign, W, L, _), tr_holds(person(L)), !.
%% a word whose English meaning is a nationality (`italiana': Italian)
tr_nationality_word(w(W, _)) :-
    atom(W), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)), atom(E), downcase_atom(E, D), en_nationality(D), !.
%% a word that asks and does not relate: English's question words, and a
%% lesson's word that means one and is no relative word (`qué', not `que')
tr_asking_word(english, w(W, _)) :- !, atom(W), en_question(W, _).
tr_asking_word(foreign, w(W, _)) :-
    atom(W), \+ tr_relative_word(foreign, W),
    tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)), en_question(E, _), !.

tr_noun_by_position(Words, english, Noun) :- last(Words, Noun).
tr_noun_by_position(Words, foreign, Noun) :- ( tr_holds(follow(_, noun)) -> Words = [Noun|_] ; last(Words, Noun) ).

%% the complements after the verb: a preposition and its phrase, an object
%% pronoun, an adverb, and otherwise a phrase (or two joined, or bare
%% adjectives) up to the next of those
tr_complements(Side, Words0, Comps) :-
    tr_degrees(Side, comparative, Words0, Words),      % `e piu ricco' is richer: no article, no superlative
    tr_complements(Side, Words, no, Comps0),
    tr_relative_wh(Side, Comps0, Comps1a),
    tr_wh_subjects(Side, Comps1a, Comps1),
    tr_joined_infinitives(Side, Comps1, Comps2),
    tr_partitive(Side, Comps2, Comps2p),
    tr_rc_of_head(Side, Comps2p, Comps2r),
    tr_governed(Side, Comps2r, Comps).
%% A RELATIVE CLAUSE AFTER A PHRASE OF `OF' WHOSE VERB AGREES WITH THE PHRASE BEFORE IT AND NOT WITH THE PHRASE OF `OF'
%% IS THE FIRST PHRASE'S, ITS SUBJECT: `Un gigantesco carrello carico di documenti che è stato collocato ... alla
%% sinistra del presidente' -- the trolley has been placed, singular, and hung on the documents, plural, the clause had
%% them for its object and nobody for its subject, which English refused. The clause goes on the two
%% (rc(with(Phrase, [pp(Of, Noun)]), subject, Clause)), as a participle does (tr_of_participle_head/2)
tr_rc_of_head(foreign, Cs0, Cs) :-
    append(Pre, [X1, pp(Of, rc(NP2, object, s(none, null(third, N), G, RCs)))|Post], Cs0),
    Of = w(_, _), tr_means_of(foreign, Of),
    ( X1 = obj(NP1), X = obj(R) ; X1 = pp(P1, NP1), X = pp(P1, R) ),
    NP1 = np(_, _, _, w(_, _), N), NP2 = np(_, _, _, _, N2), N2 \== N, !,
    R = rc(with(NP1, [pp(Of, NP2)]), subject, s(none, gap(third, N), G, RCs)),
    append(Pre, [X|Post], Cs).
tr_rc_of_head(_, Cs, Cs).

%% THE PARTITIVE AFTER A VERB OF HAVING, BUYING, EATING AND THE LIKE: `il torneo ha
%% delle novità' has novelties and `compro dei libri' is I buy books -- the contraction
%% of `di' and the article before a noun, FIRST among the complements, is no phrase of
%% `of' but what the verb has: the noun alone, which English and Spanish say with no
%% word for `some'. Only in a language whose indefinite article has a partitive plural
%% (Italian's `dei' is `di i'; Spanish's `unos' is the article, and `del' there is only
%% of the), after the verbs that take a direct object so (tr_partitive_verb/1) and not
%% one the lesson says takes `di' (`parla dei libri' is of the books), before a definite
%% article and a common noun: `della piccola Sofia' and `di una domenica' are phrases
%% of `of'
tr_partitive(foreign, [pp(w(PW, _), NP0)|Cs], [obj(NP)|Cs]) :-
    atom(PW), tr_means_of(PW), tr_partitive_np(NP0, NP),
    tr_global('$tr_read_group', G), atom(G), tr_partitive_verb(G), \+ tr_solve(take_before(G, PW, phrase)),
    tr_partitive_language, !.
%% ... and after an infinitive of such a verb: `abbiamo cominciato a installare delle macchinette che
%% distribuiscono sacchetti' began to install machines that hand out bags, and read as a phrase of `of'
%% it was `to install of the machines'
tr_partitive(foreign, [I, pp(w(PW, _), NP0)|Cs], [I, obj(NP)|Cs]) :-
    ( I = inf(G) ; I = ainf(_, G) ), atom(G), atom(PW), tr_means_of(PW), tr_partitive_np(NP0, NP),
    tr_partitive_verb(G), \+ tr_solve(take_before(G, PW, phrase)), tr_partitive_language, !.
tr_partitive(_, Cs, Cs).
%% (the article and a common noun, with its relative clause too)
tr_partitive_np(np(det(article, DL, _), Num, Adjs, w(NW, lower), Number), np(none, Num, Adjs, w(NW, lower), Number)) :-
    atom(NW), atom(DL), tr_solve(mean(DL, the)), !.
tr_partitive_np(rc(NP0, R, S), rc(NP, R, S)) :- tr_partitive_np(NP0, NP).
tr_partitive_verb(G) :-
    tr_solve(mean(G, E)),
    memberchk(E, [has, buys, sells, eats, drinks, brings, takes, makes, finds, sees, receives, offers, produces,
                  installs, distributes]), !.         % (`abbiamo cominciato a installare delle macchinette', some machines)
%% the lesson's indefinite article has a plural that is the contraction of `of' and an article --
%% Italian's `dei' is `di i' -- where Spanish's `unos' is none
tr_partitive_language :-
    tr_solve(mean(A, a)), tr_class_of(A, article), tr_solve(plural_of(P, A)),
    tr_solve(contraction_of(P, J)), atomic_list_concat([Of|_], ' ', J), tr_means_of(Of), !.

%% THE ACTOR AFTER THE VERB OF AN INDIRECT QUESTION IS ITS SUBJECT: `sa cosa
%% mangia il gatto', `sa come lavora il gatto' -- what the cat eats, how the cat
%% works. The question word stands for the object or the manner, so the phrase
%% after the verb can only be who acts; read with nobody named it was an object
%% of a verb with no subject, which English refused (`sa dove dorme il gatto'
%% read, a verb with no object having the place for its subject already). Not
%% after `who' or `which', whose word may be the subject itself
tr_wh_subjects(foreign, Cs0, Cs) :- !, tr_wh_subjects_(Cs0, Cs).
tr_wh_subjects(_, Cs, Cs).
tr_wh_subjects_([], []).
tr_wh_subjects_([wh(Q, S0)|Cs0], [wh(Q, S)|Cs]) :-
    ( memberchk(Q, [what, how, where, when, why]) ; Q = pp(_, how) ), !,
    tr_rel_subject_fix(S0, S), tr_wh_subjects_(Cs0, Cs).
tr_wh_subjects_([rwh(Q, S0)|Cs0], [rwh(Q, S)|Cs]) :-
    memberchk(Q, [what, how, where, when, why]), !,
    tr_rel_subject_fix(S0, S), tr_wh_subjects_(Cs0, Cs).
tr_wh_subjects_([C|Cs0], [C|Cs]) :- tr_wh_subjects_(Cs0, Cs).

%% AN INFINITIVE AFTER `e di' IS THE VERB'S OWN WHERE ONE OF THE SAME CLAUSE
%% STANDS BEFORE IT: `spera di aver discusso i suoi destini con i vertici, e di
%% poter dire la sua' hopes to have discussed ... and to be able to say. After
%% an object the word `di' before an infinitive belongs to the noun (`la
%% visione di creare'), and the second infinitive, read so, kept its
%% preposition: `y de poder decir la suya'. After an infinitive of the clause
%% and a coordinator it is the first one's partner, and the lesson's word
%% that begins an infinitive (`The word "di" begins the infinitive.') is no
%% word to write
tr_joined_infinitives(foreign, Cs0, Cs) :- tr_joined_inf(Cs0, no, Cs), !.
tr_joined_infinitives(_, Cs, Cs).
tr_joined_inf([], _, []).
tr_joined_inf([C|Cs0], _, [C|Cs]) :- ( C = inf(_) ; C = infx(_, _, _) ), !, tr_joined_inf(Cs0, yes, Cs).
tr_joined_inf([cnj(K), pinf(w(P, _), F)|Cs0], yes, [cnj(K), inf(F)|Cs]) :-
    atom(P), atom(F), tr_infinitive_mark(P), !, tr_joined_inf(Cs0, yes, Cs).
tr_joined_inf([C|Cs0], Inf, [C|Cs]) :- tr_joined_inf(Cs0, Inf, Cs).

%% A QUESTION WORD AFTER A PHRASE IS A RELATIVE ONE: `all'ospedale di
%% Subiaco DOVE i medici ...' is the hospital where, and Spanish spells that
%% `donde' where its question is `dónde'. Right after the verb it is the
%% indirect question it was (`sapere come'); after another complement it
%% travels as rwh/2, which a writer spells with its relative word for it.
tr_relative_wh(_, [], []).
%% ... EXCEPT `how' WITH A VERB OF SAYING AND ITS SPEAKER AFTER IT: `se "cambiare
%% è migliorare" come dicono i giocatori all'unisono' -- as the players say in
%% unison. Right after a verb that asks nothing the word is the `as' of a
%% comment (cmtc/1), as after a phrase below; a verb that takes the question
%% keeps it (`non so come dicono i giocatori')
tr_relative_wh(foreign, [wh(how, S0)|Cs0], [cmtc(S)|Cs]) :-
    tr_how_as_saying(S0, S), !,
    tr_relative_wh_after(cmtc(S), Cs0, Cs).
%% ... AND `when' AND `where' RIGHT AFTER A VERB THAT ASKS NOTHING ARE THE
%% RELATIVE WORDS: `il cane dorme quando il gatto mangia' -- Spanish spells
%% that `cuando', where its question is `cuándo' (rwh/2, as after a phrase)
tr_relative_wh(foreign, [wh(Q, S)|Cs0], [rwh(Q, S)|Cs]) :-
    memberchk(Q, [when, where]), \+ tr_asks_question_here, !,
    tr_relative_wh_after(rwh(Q, S), Cs0, Cs).
tr_relative_wh(_, [C|Cs0], [C|Cs]) :- tr_relative_wh_after(C, Cs0, Cs).
%% A VERB THAT TAKES THE QUESTION whether or not the lesson says so (`"sa" takes the
%% question.'): the ones of asking, seeing and finding out, and of saying --
%% `Il cane chiede quando arriva il gatto', `Vedremo quando arriva il treno' and
%% `annuncia quando arrivano' ask, where `dorme quando il gatto mangia' does not
tr_asks_question_here :- tr_takes_question_here, !.
tr_asks_question_here :-
    tr_global('$tr_read_group', G), atom(G),
    (   tr_saying_verb(G) -> true ; tr_solve(mean(G, E)), en_asks(E) ), !.
en_asks(asks).       en_asks(wonders).    en_asks(sees).       en_asks(discovers).  en_asks(learns).
en_asks(checks).     en_asks(verifies).   en_asks(examines).   en_asks(investigates).  en_asks(reveals).
en_asks(shows).      en_asks(clarifies).  en_asks(specifies).  en_asks(determines).    en_asks(evaluates).
en_asks(predicts).   en_asks(foresees).   en_asks(notices).    en_asks(realises).      en_asks(realizes).
tr_how_as_saying(S0, S) :-
    S0 = s(_, null(third, _), g(L, _, _, _), [obj(_)|_]), atom(L), tr_saying_verb(L),
    \+ tr_asks_question_here,
    tr_rel_subject_fix(S0, S), S \== S0.
%% (from the first complement on, as after an object pronoun or in a bracket)
tr_relative_wh1(Cs0, Cs) :- tr_relative_wh_after(none, Cs0, Cs).
tr_relative_wh_after(_, [], []).
%% ... AND `how' AFTER A PHRASE IS `as': `lui non è un artista molto noto come
%% avete scritto' -- as you wrote. Read as the relative `how' it came out
%% `cómo habéis escrito', a question; it is the comment the word opens after
%% a comma (tr_read0/4), cmtc/1, with the lesson's word for `as'
%% (after a PHRASE: `bisognerebbe sapere come sono finiti lì' asks how, and
%% after the infinitive it came out `habría que conocer como han acabado')
tr_relative_wh_after(Prev, [wh(how, S0)|Cs0], [cmtc(S)|Cs]) :-
    ( Prev = obj(_) ; Prev = adj(_) ; Prev = pp(_, _) ), !,
    %% (the word that acts stands after its verb in the comment, `come prescrive il
    %% regolamento' -- as the regulation prescribes -- and read with nobody
    %% named the regulation was the object of a verb with no subject, which
    %% English refused)
    tr_rel_subject_fix(S0, S),
    tr_relative_wh_after(cmtc(S), Cs0, Cs).
%% ... and so it is after the comma that parts it from a phrase in a bracket:
%% `(e non dopo le controanalisi, come prescrive il regolamento)' -- as the
%% regulation prescribes. Only a clause whose subject stands after its verb
%% (tr_rel_subject_fix/2 gave it one) is the comment; `(ma, come stai?)' asks
tr_relative_wh_after(sep, [wh(how, S0)|Cs0], [cmtc(S)|Cs]) :-
    S0 = s(_, null(third, _), _, [obj(_)|_]), tr_rel_subject_fix(S0, S), S \== S0, !,
    tr_relative_wh_after(cmtc(S), Cs0, Cs).
%% ... and after any complement when the comment is a verb of saying and its
%% speaker, tr_relative_wh/2's: `ha vinto il pallone d'oro, come dicono tutti'
tr_relative_wh_after(_, [wh(how, S0)|Cs0], [cmtc(S)|Cs]) :-
    tr_how_as_saying(S0, S), !,
    tr_relative_wh_after(cmtc(S), Cs0, Cs).
%% (and `which' asks after a phrase or an adjective as it asks after a verb,
%% `appare inspiegabile quali possano essere le ragioni': the lesson's
%% relative `quale' opens no clause with no article before it, so it is no
%% relative `where' or `when' either)
tr_relative_wh_after(_, [wh(Q, S)|Cs0], [wh(Q, S)|Cs]) :- tr_which_wh(Q), !, tr_relative_wh_after(wh(Q, S), Cs0, Cs).
%% (and so does any question word after an infinitive that takes the question,
%% as it asks after a verb: `si è limitata a macerarsi su chi dovesse vendere',
%% tr_question_after_inf/4)
tr_relative_wh_after(Prev, [wh(Q, S)|Cs0], [wh(Q, S)|Cs]) :-
    ( Prev = ainf(_, F) ; Prev = inf(F) ), atom(F),
    ( tr_solve(take(F, question)) ; tr_solve(take_before(F, _, question)) ), !,
    tr_relative_wh_after(wh(Q, S), Cs0, Cs).
tr_relative_wh_after(_, [wh(Q, S)|Cs0], [rwh(Q, S)|Cs]) :- Q \== whether, Q \== 'how much', !, tr_relative_wh_after(rwh(Q, S), Cs0, Cs).    % whether and how much ask, never relate
tr_relative_wh_after(_, [C|Cs0], [C|Cs]) :- tr_relative_wh_after(C, Cs0, Cs).
tr_which_wh(which(_)).
tr_which_wh(which(_, _)).
tr_which_wh(which_np(_, _)).
tr_which_wh(pp(_, which(_, _))).
tr_which_wh(pp(_, which_np(_, _))).
tr_which_wh(pp(_, how)).                              % `a seconda di come ...' stays a question after an object

%% THE COMPLEMENTS OF A WORD LIST ARE READ ONCE A SENTENCE, UNDER WHAT THE
%% READING DEPENDS ON. Every reading of a statement reads the complements of
%% what follows its verb, and the same rest of a sentence comes back under
%% the next reading: over the three longest sentences of Monte Livata, 583
%% readings of 409 distinct ones. The reader asks four things besides the
%% words and whether an object was read -- the group and the aspect being
%% read (a modal, the copula, a passive, no verb at all), the side, and
%% whether a reporting clause is being read (tr_said_to/1) -- so the key
%% carries all six; and a clause read inside it puts the group and
%% the aspect back (tr_read_nested/4), so nothing leaks in or out. The reader
%% is all but deterministic -- those 409 readings gave 96 solutions between
%% them and none gave more than one -- so every solution is kept, as a
%% word's lexemes are (tr_memo/4), and a caller that cuts sees the same
%% first one. Only a ground word list is kept: a key with a variable in it
%% is not one a later call could find.
tr_complements(Side, Ws, Seen, Cs) :-
    Ws = [T|_], ground(Ws-Seen), tr_token_atom(T, W0), !,
    tr_global('$tr_read_group', G), tr_global('$tr_read_aspect', A), tr_side_here(F),
    tr_global('$tr_said_to', ST),
    atom_concat('c|', W0, W),
    tr_memo(cm(Side, Seen, G, A, F, ST, Ws, W), Cs0, tr_complements0(Side, Ws, Seen, Cs0), Sols),
    member(Cs, Sols).
tr_complements(Side, Ws, Seen, Cs) :- tr_complements0(Side, Ws, Seen, Cs).

%% the atom a token's table is named after
tr_token_atom(w(W, _), W) :- atomic(W), !.
tr_token_atom(T, T) :- atom(T).

%% ... with whether an object has been read: the word the lesson puts
%% before a person, with no object yet and a person after it, is the
%% OBJECT's (`Maria ve a Omar' is Omar); after an object it is the
%% preposition it is (`Maria da el libro a Omar' is to Omar)
tr_complements0(_, [], _, []) :- !.
%% A NAME AFTER THE WORD FOR `WITH', AND A BARE NOUN FOR A PERSON RIGHT AFTER IT, SAY WHAT THE ONES NAMED ARE: `con
%% Lucio Dalla, Fiorella Mannoia, Renzo Arbore e lo stilista Romeo Gigli promotori di un immaginario fanclub' is with
%% them as the promoters of an imaginary fan club. Read as the clause's object the noun had no verb to take it, and
%% the sentence was refused. The phrase ends on a capitalised name, and the noun after it has no determiner; it is
%% the role of the ones named (role/1), which crosses as the IR's `as' (pp(as, Noun), written with each language's
%% word for it, `como promotores')
tr_complements0(foreign, [P|Ws0], Seen, [pp(P, NP), role(R)|Cs]) :-
    P = w(PW, _), atom(PW), tr_means_with(P),
    append(NPW, [N|Rest], Ws0), NPW = [_|_], N = w(NW, lower), atom(NW),
    last(NPW, w(_, upper)), \+ tr_determiner(foreign, N, _, _), tr_person_word(N),
    ( tr_np(foreign, NPW, NP) -> true ; tr_subject(foreign, none, NPW, third, plural, NP), NP = co(_, _, _) ),
    tr_lexeme(foreign, NW, _, Nb), atom(Nb), !,
    %% (with its phrases of `of', up to the next comma: `promotori di un immaginario fanclub')
    R0 = np(none, none, [], N, Nb),
    (   Rest = [D|_], D = w(_, _), tr_means_of(foreign, D),
        ( append(OfW, [comma|R2], Rest) -> Rest2 = [comma|R2] ; OfW = Rest, Rest2 = [] ),
        tr_of_phrases(OfW, PPs), PPs \== []
    ->  R = with(R0, PPs)
    ;   R = R0, Rest2 = Rest
    ),
    tr_complements(foreign, Rest2, Seen, Cs).
%% TWO PREPOSITIONS JOINED BEFORE ONE PHRASE: `leggere tutto pro o contro
%% Berlusconi' is in favour of or against him, `dorme con o senza il gatto' with
%% or without it -- the first preposition had no phrase of its own, and the
%% sentence was refused. The second is read with its phrase, and the pair travels
%% as pp2(First, Coordinator, Second, Phrase)
%% (each a word the lesson gives an English preposition for: `colocados cerca o dentro
%% de un vehículo' has `cerca', near as an adverb and a wall as a noun, whose
%% preposition is `cerca de', and taken for one it was `placed wall or within')
tr_complements0(foreign, [P1, Co, P2|Ws], Seen, [pp2(P1, Co, P, NP)|Cs]) :-
    P1 = w(P1W, _), Co = w(CW, _), atom(CW), tr_coord(foreign, Co), P2 = w(_, _), atom(P1W),
    tr_is(foreign, P1, preposition), tr_is(foreign, P2, preposition),
    tr_prep_across(P1W, T1), atom(T1), ( en_preposition(T1) -> true ; sub_atom(T1, _, 1, _, ' ') ),   % (`in favour of')
    tr_complements(foreign, [P2|Ws], Seen, [pp(P, NP)|Cs]), !.
%% A CLAUSE BETWEEN DASHES AFTER A COMPLEMENT THAT IS NO PHRASE stays where it
%% stood, as it does at the head of a sentence (dsh/1): `ogni volta che
%% andavamo a mangiare insieme - o meglio: io mangiavo, lui testava piccoli
%% campioni alimentari - gli ricordavo' -- after an adverb there is no phrase
%% for it to hang on (app/3), and the sentence was refused with every word known
tr_complements0(foreign, [w(K, dashed)|Ws], Seen, [dsh(K)|Cs]) :-
    tr_complements(foreign, Ws, Seen, Cs).
%% NOT ONLY ... BUT: `non solo io ma tanti altri nel nostro campo' -- not
%% only I but many others in our field. The denial and the word for `only'
%% before a phrase, and the word for `but' before a second: read word by
%% word the denial went to the verb and `ma' joined the two phrases as one
%% subject, `El perro pero el gato no duermen sólo también'. It travels as
%% nonly(First, Second, Also), each half as a subject is (a pronoun stays
%% the pronoun it is), Also `yes' where the word for `also' follows `but';
%% each writer says it in its own words: English's `not only ... but
%% (also)', a lesson its words for `not' and `only' and the partner it
%% names for the second (`"sino" is the partner of "sólo".') or its `but'
tr_complements0(foreign, [w(N, _), O|Ws], Seen, [obj(nonly(A, B, Also))|Cs]) :-
    atom(N), tr_negation_word(N), tr_nonly_parts(O, Ws, A, B, Also, Rest), !,
    tr_complements(foreign, Rest, Seen, Cs).
%% ... AND NOT ONLY IN ONE PLACE BUT IN ANOTHER: `la chiesa si era sbagliata
%% non solo sul geocentrismo ma anche sulla sfericità' was wrong not only
%% about geocentrism but also about sphericity. Each half opens on a
%% preposition, as both/2's do, and read as phrases `solo' was the adjective
%% `alone', agreeing with the church, and `ma' the `but' that joins two
%% clauses: `no sola en el geocentrismo pero también en la esfericidad'. It
%% travels as nonlyc(First, Second, Also), the complements of each half, and
%% each writer says it in the words nonly/3 has; the second half is its
%% first complement, and what follows it the clause's
tr_complements0(foreign, [w(N, _), O|Ws], Seen, [nonlyc(Cs1, [C2], Also)|Cs]) :-
    atom(N), tr_negation_word(N),
    O = w(OW, _), atom(OW), Ws = [P1|_], P1 = w(_, _), tr_is(foreign, P1, preposition),
    tr_lexeme(foreign, OW, OL, _), tr_solve(mean(OL, only)),
    append(AW, [w(M, _)|BW0], Ws), AW \== [], atom(M), \+ memberchk(comma, AW),
    ( tr_solve(partner_of(M, OW)) -> true ; tr_solve(mean(M, but)) ),
    tr_nonly_also(BW0, BW, Also),
    BW = [P2|_], P2 = w(_, _), tr_is(foreign, P2, preposition),
    tr_complements(foreign, AW, Seen, Cs1),
    tr_complements(foreign, BW, Seen, [C2|Cs]), !.
%% EITHER ... OR: `consiguió entonces, bien directamente o bien a través de
%% empresas participadas, siete nuevas explotaciones' -- either directly or
%% through companies. The first word says that a choice follows (`The word
%% "bien" begins the choice.'), and read as the adverb `well' it came out
%% `bene direttamente o bene tramite'. It travels as cor/1 before the first
%% choice, and every writer gives its own word for `either': `o direttamente
%% o tramite ...', `either directly or through ...'. Only with a choice
%% before the coordinator that means `or'. (A mark and not a meaning: said
%% as `The conjunction "bien" means "either".', `either' was a meaning of
%% `bien' in an adverb's place too, and `Él me conoce bien.' came out `He
%% knows me either.')
%% BOTH ... AND: `Toda una proeza, tanto por ese medio siglo como por la
%% sensibilidad para con su entorno social' -- both for the half century and
%% for the sensitivity. The first word is the conjunction the lesson says
%% means `both' (the dictionary's `tanto'), and the lesson says which word
%% is its partner (`"como" is the partner of "tanto".'); read word by word,
%% `tanto' was the determiner `so much' and `como' the preposition `like'.
%% It travels as both/2, the complements of each half, and every writer
%% gives its own pair: `tanto ... quanto', `both ... and'. The second half
%% is its first complement, and what follows it the clause's. Only where
%% both halves open on a preposition: `tanto pan como queso' is also as
%% much bread as cheese, and nothing here says which.
tr_complements0(Side, [w(B, _)|Ws], Seen, [both(Cs1, [C2])|Cs]) :-
    atom(B), tr_both_word(Side, B, P),
    Ws = [F1|_], F1 = w(_, _), tr_is(Side, F1, preposition),
    append(A, [w(P, _)|Rest], Ws), A \== [],
    Rest = [F2|_], F2 = w(_, _), tr_is(Side, F2, preposition),
    tr_complements(Side, A, Seen, Cs1),
    tr_complements(Side, Rest, Seen, [C2|Cs]), !.
%% AS MUCH AS: `i buoni medievali ne sapevano tanto quanto Colombo' knew as
%% much as Columbus. The pair that says both ... and with nothing between
%% its two words is the quantity and its comparison, the lesson's own pair
%% (`"quanto" is the partner of "tanto".', `"como" is the partner of
%% "tanto".'); read word by word, `tanto' was the adverb `as' and `quanto'
%% the adverb `as much', and Columbus the object, `lo conocieron tan cuanto
%% a Colombo'. It travels as asmuch(Phrase), and every writer gives its own
%% pair: `tanto como Colón', `as much as Columbus'
tr_complements0(foreign, [w(B, _), w(P, _)|Ws], Seen, [asmuch(NP)|Cs]) :-
    atom(B), atom(P), Ws = [F|_], F = w(_, _), \+ tr_is(foreign, F, preposition),
    tr_both_word(foreign, B, P),
    tr_phrase_rest(foreign, Ws, NP, Rest), !,
    tr_complements(foreign, Rest, Seen, Cs).
tr_complements0(english, [w(as, _), w(much, _), w(as, _)|Ws], Seen, [asmuch(NP)|Cs]) :-
    tr_phrase_rest(english, Ws, NP, Rest), !,
    tr_complements(english, Rest, Seen, Cs).
tr_complements0(foreign, [w(B, BC)|Ws], Seen, [cor(w(either, BC))|Cs]) :-
    atom(B), tr_solve(begin(B, choice)),
    Ws = [F|_], F = w(_, _), \+ tr_coord(foreign, F),
    once(( member(K, Ws), K = w(KW, _), atom(KW), tr_coord(foreign, K), tr_solve(mean(KW, or)) )), !,
    tr_complements(foreign, Ws, Seen, Cs).
%% A COMMA, A COORDINATOR AND A PHRASE: `situaban como favoritos a la Unión
%% de Ciudadanos de Georgia, el partido de Shevardnadze, Y EL BLOQUE
%% Renovación'. Neither language puts a comma before the coordinator of a
%% list, so that comma closes the phrase set off before it, and the phrase
%% after the coordinator joins the objects before it. Read with every comma
%% out, the phrases on either side became one, `de Shevardnadze y el
%% bloque', and both commas were lost. It travels as sep and cnj/1, which
%% every writer puts back where they stood.
tr_complements0(foreign, [comma, C|Ws], Seen, [sep, cnj(C)|Cs]) :-
    C = w(_, _), tr_coord(foreign, C), Ws = [D|_], tr_determiner(foreign, D, _, _), !,
    tr_complements(foreign, Ws, Seen, Cs).
%% ... AND AFTER A BARE COORDINATOR, A WORD THAT IS AN ADVERB AS WELL AS A
%% PREPOSITION IS THE PHRASE'S ADVERB WHERE NO DETERMINER FOLLOWS IT:
%% `sintonías (...) y hasta anuncios (...)' -- and even adverts. Read as the
%% preposition it came out `and until ads'; `hasta el final' has its
%% article, and `hasta mañana' is a time
tr_complements0(foreign, [C, A|Ws], _, [cnj(C), obj(advp(A, NP))|Cs]) :-
    C = w(_, _), tr_coord(foreign, C), A = w(AW, _), atom(AW),
    Ws = [N|_], N = w(NW, _), atom(NW), \+ tr_determiner(foreign, N, _, _), tr_is(foreign, N, noun),
    tr_is(foreign, A, preposition), tr_is(foreign, A, adverb),
    \+ ( tr_lexeme(foreign, NW, NL, _), tr_solve(time(NL)) ),
    tr_phrase_words(foreign, Ws, PW, Rest), PW \== [], tr_phrase_np(foreign, PW, NP),
    tr_bare_head(NP), !,
    tr_complements(foreign, Rest, yes, Cs).
%% ... AND ADVERBS BEFORE THAT PHRASE ARE THE PHRASE'S: `non vi saranno
%% altri vincoli ..., ma SOLO PIÙ turismo e ricchezza' -- but only more
%% tourism and wealth. Read as the clause's, `ma solo' was two adjectives,
%% `but' and `alone', and Spanish wrote `pero solos'; the coordinator joins
%% the phrase after it to the objects before, and what stands between them
%% is the phrase's, advp/2, as it is after `di cui' (rpp/2)
tr_complements0(foreign, [comma, C|Ws0], _, [sep, cnj(C), obj(NP)|Cs]) :-
    C = w(_, _), tr_coord(foreign, C), Ws0 = [A|_], tr_plain_adverb(foreign, A),
    tr_lead_adverbs(foreign, Ws0, As, Ws), As \== [],
    tr_phrase_words(foreign, Ws, PW, Rest), PW \== [], tr_phrase_np(foreign, PW, NP0),
    %% (never a lone word the lesson knows only as an adjective, which is no
    %% phrase: `, ma anche molto attento' says more of the noun before it,
    %% and read as a phrase with the adjective for its noun it agreed with
    %% nothing, `pero también muy cansado' of a house)
    \+ tr_lone_adjective(PW, NP0), !,
    tr_advp(As, NP0, NP),
    tr_complements(foreign, Rest, yes, Cs).
%% A RELATIVE THAT COMMENTS ON THE CLAUSE BEFORE IT: `el Gobierno se comprometió
%% a rebajar la retención al 18%, LO QUE, en su opinión, no basta' -- which, in
%% his opinion, is not enough. Read as the phrase it looks like, `the one that',
%% Italian wrote `quello che' (it says `il che'). The lesson says which two
%% words are one (`"lo que" is a remark.'), and only after a comma
tr_complements0(foreign, [comma, w(A, _), w(B, _)|Ws], _, [sep, crel(Role, S)]) :-
    atom(A), atom(B), Ws \== [], atomic_list_concat([A, B], ' ', J), tr_solve(remark(J)),
    member(Role, [subject, object]),
    tr_relative_clause(foreign, [w(B, lower)|Ws], Role, S), !.
tr_complements0(foreign, [comma, w(P, PC)|Ws], Seen, [sep, abs(L, NP)|Cs]) :-
    tr_absolute_start(foreign, sep, [w(P, PC)|Ws]), tr_participle_here(foreign, P, L),
    tr_phrase_words(foreign, Ws, PW, Rest), PW \== [], tr_phrase_np(foreign, PW, NP),
    %% (a time with an adjective is when the participle happened, not a phrase of
    %% its own: `Eric Morley, fallecido el pasado noviembre' died last
    %% November, and read as the absolute clause `died the past november'
    %% -- and so is a day of the month: `el jubilado fallecido el día 13' died on the 13th)
    \+ tr_time_deictic(NP), \+ tr_day_label(NP), !,
    tr_complements(foreign, Rest, Seen, Cs).
tr_complements0(Side, [comma|Ws], Seen, [sep|Cs]) :- !, tr_complements(Side, Ws, Seen, Cs).
tr_complements0(Side, [w(K, paren)|Ws], Seen, [paren(K)|Cs]) :- !, tr_complements(Side, Ws, Seen, Cs).
tr_complements0(Side, [w(K, comment)|Ws], Seen, [comment(K)|Cs]) :- !, tr_complements(Side, Ws, Seen, Cs).
tr_complements0(foreign, [w(P, PC)|Ws], Seen, [abs(L, NP)|Cs]) :-
    tr_absolute_start(foreign, [w(P, PC)|Ws]), tr_participle_here(foreign, P, L),
    tr_phrase_words(foreign, Ws, PW, Rest), PW \== [], tr_phrase_np(foreign, PW, NP),
    \+ tr_time_deictic(NP), \+ tr_day_label(NP), !,
    tr_complements(foreign, Rest, Seen, Cs).
tr_complements0(Side, [w(K, per)|Ws], Seen, [per(K)|Cs]) :- !, tr_complements(Side, Ws, Seen, Cs).
tr_complements0(Side, [w(K, perh)|Ws], Seen, [perh(K)|Cs]) :- !, tr_complements(Side, Ws, Seen, Cs).
tr_complements0(Side, [w(K, perd)|Ws], Seen, [perd(K)|Cs]) :- !, tr_complements(Side, Ws, Seen, Cs).
%% AN EXCLAMATION'S `what' AND ITS PHRASE: `Mio dio, che tristezza!' -- what
%% sadness. The word the lesson gives for `what' asks nothing there, and
%% before a noun with no article it is the exclamation's; read as anything
%% else the sentence had no reading. Only in a sentence that ends in `!':
%% elsewhere `che libro' is a question's, which book. what_np/1 is the term,
%% and each writer puts its own word for `what' before the phrase
%% ... AND A WORD THE LESSON CALLS EXCLAMATIVE, AT THE HEAD OF ITS PIECE,
%% WITH NO `!' AFTER IT: `Menudo inicio.' -- what a start. `menudo' is also
%% the adjective small, and read as one before a noun with no article the
%% sentence was a phrase with nothing said of it, which stays refused
tr_complements0(Side, [w(Q, QC)|Ws], Seen, [obj(what_np(NP))|Cs]) :-
    Ws = [_|_],
    (   tr_global('$tr_exclaim', yes), tr_what_word(Side, Q) -> true
    ;   Side == foreign, nb_getval('$tr_exclamative', yes), atom(Q), tr_solve(exclamative(Q)),
        tr_global('$tr_piece', Piece), Piece == [w(Q, QC)|Ws]
    ),
    tr_phrase_words(Side, Ws, PW, Rest), PW \== [], tr_phrase_np(Side, PW, NP), NP = np(none, _, _, _, _), !,
    %% (the phrase is an object, and what follows it is read as after one: the
    %% `di' of `che strano modo di salutare Rosi' is the phrase's, as after
    %% `è un modo di salutare', and with none seen it was left out, `¡Qué
    %% extraña manera saludar a Gianfranco Rosi')
    ( Seen == no -> Seen1 = yes ; Seen1 = Seen ),
    tr_complements(Side, Rest, Seen1, Cs).
%% A COMPARISON: `más grande que el perro', `idénticos condicionantes que la
%% ronda anterior'. The lesson's word for `than' before a phrase and no verb
%% is neither a relative word nor the start of a clause; it travels as
%% cmp(Kind, Phrase) -- `equal' where the sentence has a word meaning `same'
%% or `identical' before it, `more' otherwise -- and English writes `as' or
%% `than', and each lesson its own word for `than' (`del turno precedente').
%% ... AND THE ONE AT, THE ONE IN: `una laurea in fisica a Catania valga meno
%% che quella al politecnico di Milano' is worth less than the one at the
%% polytechnic. A comparison sets like beside like, so after the word for
%% `than' a word that replaces the noun takes any preposition as its own --
%% read as the pronoun `that', the polytechnic was where the first degree is
%% worth less, `que eso al politécnico'. Only there: `ho dato quello a Maria'
%% gives that TO her.
tr_complements0(foreign, [w(Q, _), R, P|Ws], Seen, [cmp(Kind, ell(det(article, AL, R), G, Number, pp(P, NP)))|Cs]) :-
    Ws \== [], tr_noun_replacer(foreign, R), R = w(RW, _),
    P = w(_, _), tr_is(foreign, P, preposition), \+ tr_means_of(foreign, P),
    tr_comparison_start(foreign, [w(Q, lower), R, P|Ws]),
    tr_phrase_rest(foreign, Ws, NP, Rest),
    tr_lexeme(foreign, RW, L, Number), tr_gender(L, G),
    once(( tr_solve(mean(AL, the)), tr_class_of(AL, article) )), !,
    ( tr_equative_piece(Q) -> Kind = equal ; Kind = more ),
    tr_complements(foreign, Rest, Seen, Cs).
tr_complements0(foreign, [w(Q, _)|Ws], Seen, [cmp(Kind, NP)|Cs]) :-
    tr_comparison_start(foreign, [w(Q, lower)|Ws]),
    tr_phrase_rest(foreign, Ws, NP, Rest), !,
    ( tr_equative_piece(Q) -> Kind = equal ; Kind = more ),
    tr_complements(foreign, Rest, Seen, Cs).
%% ... AND A COMPARISON WHOSE SECOND TERM HAS A PREPOSITION: `un 2,4% menos
%% que en el ejercicio precedente' is two point four per cent less than in
%% the year before. The phrase after the preposition is no noun's -- `que' was
%% read as the noun of a phrase, `than', which wrote the right words by
%% accident until a conjunction stopped being a noun -- and it travels as
%% cmpp(Adverb, Kind, pp(P, NP)): English's `less than in', a lesson's
%% adverb and its conjunction for `than' before the preposition, `meno che
%% nell'esercizio'. The adverb before `than' travels inside it, because
%% English writes a lone adverb after every complement, `than in the house
%% less'.
tr_complements0(foreign, [A, w(Q, _), P|Ws], Seen, [cmpp(A, more, PP)|Cs]) :-
    A = w(_, _), tr_plain_adverb(foreign, A),
    P = w(_, _), tr_is(foreign, P, preposition),
    tr_solve(mean(Q, than)), \+ tr_class_of(Q, preposition),
    tr_complements(foreign, [P|Ws], Seen, [PP|Cs]), PP = pp(_, _), !.
tr_complements0(foreign, [w(Q, _), P|Ws], Seen, [cmpp(none, Kind, PP)|Cs]) :-
    P = w(_, _), tr_is(foreign, P, preposition),
    tr_solve(mean(Q, than)), \+ tr_class_of(Q, preposition), tr_compared_before(Q, [P|Ws]),
    tr_complements(foreign, [P|Ws], Seen, [PP|Cs]), PP = pp(_, _), !,
    ( tr_equative_piece(Q) -> Kind = equal ; Kind = more ).
%% ... AND ONE WHOSE SECOND TERM IS AN ADVERB: `aboga por la situación en las
%% mismas condiciones que en la actualidad' is in the same conditions AS AT
%% PRESENT, and `en la actualidad' is one word, an adverb the lesson states
%% whole -- with no preposition after `que' the comparison had no reading, and
%% the division before a main clause took `condiciones que ...' for a verb of
%% the second person, `you condition that currently'. The adverb travels as
%% the term's phrase, cmpp(none, Kind, adv(A)) -- and never one a verb follows
%% in the piece, which opens a relative clause: `el instrumento más amplio de
%% convivencia que jamás han tenido los vascos' is the widest instrument the
%% Basques have ever had, and the term read in a piece cut after `jamás' cost
%% the sentence 0.87 million inferences of 85, the text the same
tr_complements0(foreign, [w(Q, _), A|Ws], Seen, [cmpp(none, Kind, adv(A))|Cs]) :-
    A = w(AW, _), atom(AW), tr_is(foreign, A, adverb), \+ tr_is(foreign, A, preposition),
    tr_solve(mean(Q, than)), \+ tr_class_of(Q, preposition), tr_compared_before(Q, [A|Ws]),
    \+ ( tr_global('$tr_piece', P), is_list(P), append(_, [w(Q, _), A, w(V, _)|_], P), atom(V), tr_verb_form_word(V) ),
    tr_complements(foreign, Ws, Seen, Cs), !,
    ( tr_equative_piece(Q) -> Kind = equal ; Kind = more ).
%% ... AND ONE WHOSE SECOND TERM IS AN INFINITIVE WITH ITS PREPOSITION:
%% `sono più occupati a controllare i biglietti e gli abbonamenti che a
%% vigilare sulla sicurezza di chi nuota' is busier checking tickets than
%% watching over the safety of those who swim. The term is the infinitive
%% and all that follows it, which is the infinitive's own, and cmpp/3 wants
%% one preposition's phrase, so the piece was refused. cmpi(Kind, Comps) is
%% the term: English's `than' and its `to', a lesson's conjunction for
%% `than' and its preposition and infinitive
tr_complements0(foreign, [w(Q, _), P|Ws], Seen, [cmpi(Kind, IC)]) :-
    P = w(_, _), tr_is(foreign, P, preposition),
    tr_solve(mean(Q, than)), \+ tr_class_of(Q, preposition), tr_compared_before(Q, [P|Ws]),
    tr_complements(foreign, [P|Ws], Seen, IC), IC = [ainf(_, _)|_], !,
    ( tr_equative_piece(Q) -> Kind = equal ; Kind = more ).
tr_complements0(english, [A, w(than, _), P|Ws], Seen, [cmpp(A, more, PP)|Cs]) :-
    A = w(_, _), tr_is(english, A, adverb),
    P = w(_, _), tr_is(english, P, preposition),
    tr_complements(english, [P|Ws], Seen, [PP|Cs]), PP = pp(_, _), !.
%% ... AND ONE WHOSE SECOND TERM IS A CLAUSE: `ritenevano che la sfera
%% terrestre fosse più ampia di quanto il genovese sosteneva' is wider than
%% the Genoese maintained. The lesson names the word that opens such a term
%% (`The conjunction "di quanto" means "than what".', Spanish's `de lo
%% que'), and the clause after it is read as a relative clause is, its
%% object the thing compared and left out. cmpc(Kind, Clause) is the term:
%% English writes `than' and the clause, a lesson its word for `than what'.
%% With no term for a clause the comparison had no reading, and the one the
%% sentence found instead took `fosse' for the plural of `fossa', a pit, and
%% `sosteneva' for its verb.
tr_complements0(foreign, [w(Q, _)|Ws], _, [cmpc(Kind, S)]) :-
    Ws \== [], atom(Q), tr_solve(mean(Q, 'than what')), tr_compared_before(Q, Ws),
    tr_read_nested(foreign, Ws, rel, S0),
    ( tr_rel_subject_after(foreign, S0, S1) -> tr_unrel(S1, S) ; tr_unrel(S0, S) ), !,
    ( tr_equative_piece(Q) -> Kind = equal ; Kind = more ).
%% MORE THAN AN ADJECTIVE: `esa elección resulta más que cuestionable'. The
%% word that begins the comparative, the lesson's word for `than' and
%% adjectives with no phrase after them -- read as a comparison it made
%% `que cuestionable' a phrase whose noun was `que', and `más' a preposition.
%% mt(Adjectives) is the term, and each writer says it in its own words:
%% English `more than', and a lesson its comparative word and the word it
%% calls a CONJUNCTION meaning `than' (tr_than_word/2), `più che'.
tr_complements0(foreign, [w(M, _), w(Q, _)|Ws], Seen, [mt(As)|Cs]) :-
    tr_degree_word(M), tr_solve(mean(Q, than)),
    tr_phrase_words(foreign, Ws, As, Rest), As \== [], tr_all_adjectives(foreign, As), !,
    tr_complements(foreign, Rest, Seen, Cs).
tr_complements0(english, [w(more, _), w(than, _)|Ws], Seen, [mt(As)|Cs]) :-
    tr_phrase_words(english, Ws, As, Rest), As \== [], tr_all_adjectives(english, As), !,
    tr_complements(english, Rest, Seen, Cs).
%% A `che' CLAUSE IS A COMPLEMENT, AND IT RUNS TO THE END OF ITS PIECE.
%% `escludendo che il militare voleva ...' -- the word the lesson gives for
%% `that' before a clause, and everything after it read as a statement of
%% its own. Taking the WHOLE rest rather than the shortest readable piece
%% is deliberate: a shortest-first append would stop at the first clause
%% that happens to read, which is never what `that' introduces.
%% ... AFTER THE WORD THE VERB TAKES BEFORE A CLAUSE: `se da cuenta DE QUE
%% ...' is realizing that, and the lesson says so (`"da cuenta" takes "de"
%% before the clause.'); the word is the verb's, and each writer puts back
%% what its own verb takes
tr_complements0(foreign, [w(P, _), W|Ws], Seen, Cs) :-
    tr_global('$tr_read_group', G), atom(G), tr_solve(take_before(G, P, clause)),
    tr_that_here(foreign, W), Ws \== [],
    tr_complements0(foreign, [W|Ws], Seen, Cs), Cs = [that(_)|_], !.
%% AN INDIRECT QUESTION AFTER A VERB THAT TAKES ONE: `decidere se ci
%% costerebbe più caro intervenire' is to decide WHETHER it would cost more,
%% and the word for `if' there opens no condition. The lesson says which
%% verbs take a question -- `"decide" takes the question.', the shape
%% `"continúa" takes the gerund.' has -- and without one `se' stays the
%% connector it is (`Il cane dorme se piove'). Read as a condition, `e
%% decidere' was a clause of its own and the sentence cost 67 million
%% inferences finding that out. It travels as wh(whether, Clause), after
%% the verb or after the infinitive the verb is.
%% (and after a verb that puts a word before its question, `pregunta por
%% quién come', as after its infinitive: tr_complements_after_inf/5)
tr_complements0(foreign, [w(P, _), W|Ws], _, [wh(E, S)]) :-
    tr_global('$tr_read_group', G), atom(G), tr_solve(take_before(G, P, question)), Ws \== [],
    tr_question_word(W, E),
    tr_read_nested(foreign, Ws, none, S0), ( E == who -> tr_who_gap(S0, S) ; S = S0 ), !.
%% ... AND AN INFINITIVE AFTER THE WORD FOR `if': `dovrà scegliere se fare l'uomo
%% di governo o mantenere il controllo delle sue tv' is choose WHETHER TO be the
%% man of government or to keep the control -- no clause, so the question was no
%% question, and the sentence was refused. It travels as whinf(Complements), the
%% infinitive first among them, after the verb or after the infinitive the verb is
%% (the clause after this one's)
tr_complements0(foreign, [w(W, _), w(V, VC)|Ws], _, [whinf(Cs)]) :-
    tr_if_word(W),
    tr_global('$tr_read_group', G), atom(G), tr_solve(take(G, question)),
    tr_whether_infinitive([w(V, VC)|Ws], Cs), !.
tr_complements0(foreign, [w(W, _)|Ws], _, [wh(whether, S)]) :-
    Ws \== [], tr_if_word(W),
    tr_global('$tr_read_group', G), atom(G), tr_solve(take(G, question)),
    tr_read_nested(foreign, Ws, none, S), !.
tr_complements0(foreign, [w(V, _), w(W, _)|Ws], _, [inf(F), whinf(Cs)]) :-
    tr_if_word(W), tr_solve(infinitive_of(V, F)), tr_solve(take(F, question)),
    tr_whether_infinitive(Ws, Cs), !.
tr_complements0(foreign, [w(V, _), w(W, _)|Ws], _, [inf(F), wh(whether, S)]) :-
    Ws \== [], tr_if_word(W),
    tr_solve(infinitive_of(V, F)), tr_solve(take(F, question)),
    tr_read_nested(foreign, Ws, none, S), !.
%% ... AND WHAT: `certo che ha capito cos'è successo' -- she understood WHAT
%% happened. The question word stands for the clause's subject or its
%% object, which the clause read as a statement leaves out, and it travels
%% as wh(what, Clause), as `come' travels as wh(how, Clause). After a verb
%% that takes the question only, and never the word for `that': `cosa' is a
%% thing after any other verb, and read as one the clause after it was a
%% sentence of its own, `ha entendido cosa ha pasado'.
tr_complements0(foreign, [w(W, _)|Ws], _, [wh(what, S)]) :-
    Ws \== [], atom(W),
    tr_global('$tr_read_group', G), atom(G), tr_solve(take(G, question)),
    \+ tr_that_here(foreign, w(W, lower)),
    tr_lexeme(foreign, W, L, _), tr_solve(mean(L, what)),
    tr_read_nested(foreign, Ws, none, S), !.
%% ... AND WHO: `non so chi vende' is I do not know WHO sells, and not the one who
%% does. `chi' is the free relative everywhere else (`The word "chi" begins the
%% relative.'); it asks after a verb that takes the question, as `cosa' does.
%% The clause after it has no subject of its own unless it names one, and
%% then the question word is it: wh(who, Clause), the subject a gap, which
%% every writer leaves out (`quién vende', `who sells')
tr_complements0(foreign, [w(W, _)|Ws], _, [wh(who, S)]) :-
    Ws \== [], atom(W),
    tr_global('$tr_read_group', G), atom(G), tr_solve(take(G, question)),
    \+ tr_that_here(foreign, w(W, lower)),
    tr_lexeme(foreign, W, L, _), tr_solve(mean(L, who)),
    tr_read_nested(foreign, Ws, none, S0), tr_who_gap(S0, S), !.
%% THE WORD FOR `LIKE' THAT NEVER ASKS, BEFORE A CLAUSE WITH ITS OWN SUBJECT OR ITS VERB FIRST, IS THE `AS' OF A COMMENT:
%% `que el monumento a Seguí quede como él se merece' is as he deserves -- Spanish's `como' with no accent asks nothing
%% (`cómo' does), and read as nothing the clause was refused. It travels as the comment `come avete scritto' is, cmtc/1,
%% and every writer says its own word for `as'. A word that also means `how' (Italian's `come') is left to the readers
%% of a question, and a clause that names nobody is no comment (`como presidente' has no verb at all)
%% ... the rest read once, and only where a verb that is no infinitive or participle stands among its first four words
%% before a comma, with only pronouns, clitics or a name before it (`como él se merece'): read after every such word, `como alternativa a cerrar los sábados, la instauración de ...' was the
%% whole piece read again for nothing, 1.4 million inferences more in that sentence. A clause whose subject the reader
%% left after its verb, with nobody named and that phrase for an object, has it for its subject (`como dice el
%% ceramista', tr_rel_subject_fix/2)
tr_complements0(foreign, [w(W, WC)|Ws], _, [cmtc(S)]) :-
    Ws = [_|_], atom(W), tr_like_word(w(W, WC)), \+ tr_indirect_word(foreign, W, how),
    \+ tr_global('$tr_read_group', none),
    tr_like_head(Ws, 4, Head),
    once(( append(Pre, [w(V, _)|_], Head), atom(V), forall(member(P, Pre), tr_like_pre(P)),
           \+ tr_solve(infinitive_of(V, _)), \+ tr_solve(participle_of(V, _)), tr_verb_form_any(V) )),
    tr_read_nested(foreign, Ws, none, S0),
    (   S0 = s(_, Su0, _, _), Su0 \= null(_, _), Su0 \= gap(_, _) -> S = S0
    ;   S0 = s(_, null(third, _), _, [obj(_)|_]), tr_rel_subject_fix(S0, S), S \== S0
    ), !.
%% ... AND WHO AFTER A PREPOSITION: `No conseguí averiguar con quién tenía que hablar' is I could not find out WITH WHOM I
%% had to speak, and read as a phrase of `with' and a noun (`hablar' is a speech too) it had no reading. It travels as
%% wh(pp(Preposition, who), Clause), as a preposition before `how' does, after a verb that takes the question or the
%% infinitive of one; the clause names its own subject or none
tr_complements0(foreign, [w(P, PC), w(W, _)|Ws], _, [wh(pp(w(P, PC), who), S)]) :-
    Ws \== [], atom(P), atom(W), tr_global('$tr_who_word', yes),
    tr_global('$tr_read_group', G), atom(G), tr_solve(take(G, question)), tr_is(foreign, w(P, lower), preposition),
    tr_lexeme(foreign, W, L, _), tr_solve(mean(L, who)),
    tr_read_nested(foreign, Ws, none, S), !.
tr_complements0(foreign, [w(V, _), w(P, PC), w(W, _)|Ws], _, [inf(F), wh(pp(w(P, PC), who), S)]) :-
    Ws \== [], atom(V), atom(P), atom(W), tr_global('$tr_who_word', yes), tr_solve(infinitive_of(V, F)), tr_solve(take(F, question)),
    tr_is(foreign, w(P, lower), preposition),
    tr_lexeme(foreign, W, L, _), tr_solve(mean(L, who)),
    tr_read_nested(foreign, Ws, none, S), !.
%% ... AND `WHAT': `Ignoro de qué está hablando el COI' -- what the IOC is talking about. Read with `qué' for the
%% determiner of the word after it (`habla' is speech too), it was `of what speech'. It travels as wh(pp(Preposition,
%% what), Clause), and English puts the preposition after the clause (`what the IOC is speaking of'), the lesson's
%% language before the word that asks (`de qué', `di cosa'). The word that asks only (`qué', with its accent), in a
%% sentence that has one ('$tr_what_word'), after a verb that takes the question -- and the doer after its verb is its
%% subject, the question being the preposition's (`de qué habla el gato' is what the cat talks about, and read with
%% nobody named it was `speaks the cat', tr_rel_subject_fix/2)
tr_complements0(foreign, [w(P, PC), w(W, WC)|Ws], _, [wh(pp(w(P, PC), what), S)]) :-
    Ws \== [], atom(P), atom(W), tr_global('$tr_what_word', yes),
    tr_question_word(w(W, WC), what), tr_takes_question_here, tr_is(foreign, w(P, lower), preposition),
    tr_read_nested(foreign, Ws, none, S0), !, tr_rel_subject_fix(S0, S).
%% ... AND HOW MUCH: `che ci vogliono dire quanto Roma disti da Gerusalemme' is
%% they want to tell us HOW FAR Rome is from Jerusalem. The lesson's `quanto'
%% is `as much' first, and so it stays everywhere else -- `per quanto mi
%% riguarda', `con quanto stabilito' -- so it asks only after a verb, or the
%% infinitive of one, that takes the question: `"dice" takes the question.'
%% It travels as wh('how much', Clause), and every writer puts its own word
%% for it in front (`cuánto dista Roma'). Read as `as much' the clause had
%% nothing to be, and `Roma' was a person marked as the object, `cuanto a Roma'
%% (the verb asked first, as for `what' above: every complement list reaches
%% this clause, and the word's meaning was looked up for each of them)
tr_complements0(foreign, [w(W, _)|Ws], _, [wh('how much', S)]) :-
    Ws \== [], tr_takes_question_here, tr_how_much_word(W),
    tr_read_nested(foreign, Ws, none, S), !.
%% ... AND TWO OF THEM JOINED ARE TWO: `senza rendersi conto che non importa
%% loro null'altro che perseguire i loro scopi E CHE l'unico linguaggio che
%% parlano è quello della violenza' -- that nothing else matters to them, and
%% that the only language they speak is violence. Read as one clause the
%% second `che' had nothing to be, and the sentence was refused. Each is read
%% on its own and the coordinator stands between them, cnj/1.
%% A WORD THAT BEGINS THE RELATIVE STANDS FOR A PHRASE AND ITS RELATIVE WORD
%% BOTH: `non senza redarguire chi in Italia ... non lo imita' is whoever does
%% not imitate him, and `chi' is `colui che', the one who. The lesson says so
%% -- `The word "chi" begins the relative.', in the shape `The word "per"
%% begins the purpose.' has -- and it is the phrase a noun replacer opens with
%% its clause (`el que', 1.8.0), ell/4, which every writer already has: `al
%% que no lo imita', `the one that does not imitate him'. The clause is read
%% as the lesson's own relative's would be, with its subject the gap.
%% (the phrase's article is the lesson's own masculine `the', as the words
%% `quello che' would have given it)
%% (only where a verb was read, whose object the phrase is: with none, `chi'
%% asks. `(ma chi avrebbe potuto pensare di "mediare" con Hitler)' is who
%% could have thought it, and read as the one who, a phrase in a bracket with
%% nothing said of it, it came out `el que habría podido pensar')
tr_complements0(foreign, [w(W, _)|Ws], _, [obj(ell(det(article, A, w(A, lower)), masculine, singular, rel(subject, S)))]) :-
    Ws \== [], \+ tr_global('$tr_read_group', none),
    tr_lexeme(foreign, W, L, _), tr_solve(begin(L, relative)),
    once(( tr_solve(relative(R)), tr_solve(mean(R, that)) )),
    once(( tr_solve(mean(A, the)), tr_solve(article(A)), \+ tr_holds(feminine(A)), \+ tr_solve(plural_of(A, _)) )),
    tr_relative_clause(foreign, [w(R, lower)|Ws], subject, S), !.
%% ... AND AFTER A PREPOSITION: `ha l'aria di chi deve spiegare per la
%% centesima volta una cosa ...' is the air of one who must explain -- the
%% same phrase, the preposition's, and refused with no reading for `chi'
%% (the word itself, or its lexeme: Spanish's `quien' is a relative of no class, `a quien correspondiera')
tr_complements0(foreign, [P, w(W, _)|Ws], _, [pp(P, ell(det(article, A, w(A, lower)), masculine, singular, rel(subject, S)))]) :-
    Ws \== [], atom(W),
    ( tr_global('$tr_free_rel', yes), tr_solve(begin(W, relative)) -> true ; tr_lexeme(foreign, W, L, _), tr_solve(begin(L, relative)) ),
    P = w(_, _), tr_is(foreign, P, preposition), \+ tr_global('$tr_read_group', none),
    once(( tr_solve(relative(R)), tr_solve(mean(R, that)) )),
    once(( tr_solve(mean(A, the)), tr_solve(article(A)), \+ tr_holds(feminine(A)), \+ tr_solve(plural_of(A, _)) )),
    tr_relative_clause(foreign, [w(R, lower)|Ws], subject, S), !.
%% A RELATIVE CLAUSE JOINED TO WHAT WAS SAID OF AN OBJECT: `è un problema
%% grave e che mi tormenta' -- a serious problem, and one that torments me.
%% The coordinator joins the clause to the adjective before it, both said of
%% the problem; with no reading for a relative word after a coordinator the
%% clause had none. It is the relative clause standing alone that rcl/2
%% already carries after a colon, with the coordinator before it, and only
%% after an object, which is what it is said of.
tr_complements0(foreign, [C, w(R, RC)|Ws], Seen, [cnj(C), rcl(Role, S)]) :-
    Seen == yes, Ws \== [], C = w(_, _), tr_coord(foreign, C),
    tr_relative_word(foreign, R),
    tr_relative_clause(foreign, [w(R, RC)|Ws], Role, S), Role \= pp(_), !.
%% (with the comma before the coordinator kept: `que "se imponen" una serie de reformas, pero que, en todo caso, ...'
%% was `reforms prevails but that', the comma lost with the first clause's words)
tr_complements0(Side, [W|Ws], _, Cs) :-
    tr_that_here(Side, W), W = w(T, _),
    append(W1, [C, w(T2, _)|Ws2], Ws), T2 == T, W1 \== [], Ws2 \== [],
    C = w(_, _), tr_coord(Side, C),
    ( append(W1a, [comma], W1) -> Sep = [sep] ; W1a = W1, Sep = [] ), W1a \== [],
    tr_that_clause(Side, W1a, S1), tr_that_clause(Side, Ws2, S2),
    \+ tr_second_relative(Side, S1, S2, Ws), !,
    append([[that(S1)], Sep, [cnj(C), that(S2)]], Cs).
tr_complements0(Side, [W|Ws], _, [that(S)]) :-
    tr_that_here(Side, W), Ws \== [],
    tr_that_clause(Side, Ws, S), !.
%% ... AND A CLAUSE OF `THAT' LEFT OPEN AT THE END, which a trail of points
%% stands for: `diciamo che ...' says that, and the clause is not there. The
%% word is written as it stood, that_open/0
tr_complements0(Side, [W], _, [that_open]) :-
    tr_that_here(Side, W), !.
%% WHICH AS AN INDIRECT QUESTION: `appare inspiegabile quali possano essere le
%% ragioni di incostituzionalità' is it seems inexplicable WHICH the reasons
%% may be, and `vedremo su quali aspetti della riforma il capo dello stato ha
%% puntato la sua attenzione' is we shall see ON WHICH aspects the head of
%% state has focused his attention. The lesson's `quale' means `which', and
%% `quali' is its plural; the question word stands for the clause's subject,
%% its object or an adjunct, which the clause read as a statement leaves out,
%% and it travels as wh(Asked, Clause) -- `which' with the number the source
%% gave it, or `which' with its noun phrase (the reader's words, crossed
%% like a question's) -- with the preposition in front when there is one.
%% It came out before as a RELATIVE clause on the adjective, `inexplicable
%% which they may be the reasons', and Spanish wrote `que pueden ser'.
tr_complements0(foreign, [w(W, C)|Ws], _, [wh(Q, S)]) :-
    Ws \== [], tr_which_form(W, N),
    tr_which_clause(Ws, N, C, Q0, S), !,
    tr_what_to(W, Q0, S, Q).
tr_complements0(foreign, [w(P, PC), w(W, C)|Ws], _, [wh(pp(w(P, PC), Q), S)]) :-
    Ws \== [], atom(P), tr_is(foreign, w(P, lower), preposition), tr_which_form(W, N),
    tr_which_clause(Ws, N, C, Q, S), Q = which(_, _), !.
%% A PREPOSITION BEFORE THE QUESTION `HOW': `dipende da come vanno le trattative'
%% depends on how the negotiations go, `a seconda di come saranno andate le
%% proprie trattative' according to how they will have gone. Only how, whose
%% word is no preposition's object anywhere else (`da quando' is since, `da
%% dove' from where), and never the word for `as' before it. It travels as
%% wh(pp(Preposition, how), Clause) as a preposition before `which' does, and
%% each writer says its own word for the preposition and for `how'
tr_complements0(foreign, [w(P, PC), w(W, _)|Ws], _, [wh(pp(w(P, PC), how), S)]) :-
    Ws \== [], atom(P), atom(W), tr_is(foreign, w(P, lower), preposition),
    \+ tr_means_as(foreign, w(P, PC)),
    tr_indirect_word(foreign, W, how),
    tr_read_nested(foreign, Ws, none, S), !.
%% A QUESTION WORD AFTER THE VERB OPENS AN INDIRECT QUESTION, and it runs to
%% the end of its piece as a `che' clause does: `bisognerebbe sapere COME
%% sono finiti lì', `Non si sa come possa essere successo', `all'ospedale
%% DOVE i medici stanno valutando'. wh(Word, Clause) is the term, the English
%% question word and the clause read as a statement; each writer puts the
%% target's word for it in front, as a question's is.
%% ... BUT NOT A WORD THAT IS A PREPOSITION TOO WHEN A PHRASE IS ALL THAT
%% FOLLOWS IT: `come dividendo straordinario' is AS an extraordinary
%% dividend, and read as `how' the phrase had to be a clause, so the noun
%% was taken for the gerund it is spelled like and came out `cómo
%% dividiendo extraordinario'.
%% ... NOR WHEN THE PHRASE HAS ONLY ADJUNCTS AFTER IT: `previsto dalla legge
%% come importo massimo per le tasse universitarie' is set by law AS the
%% maximum amount for the fees, and read as `how' the noun was `I matter'
%% AS WHEN: `è come quando fai una mostra' is it is as when you put on an
%% exhibition -- the word for `as' before a clause of `when' or `where',
%% which no reader took: as the question word `come' asked how of a clause
%% that opened on another question word, and as the preposition it wanted a
%% phrase. It is the clause rwh/2 carries with the word for `as' before it,
%% asrwh/2, and it runs to the end of the words, as a clause of `that' does
tr_complements0(Side, [C, w(QW, _)|Ws], _, [asrwh(Q, S)]) :-
    Ws \== [], C = w(CW, _), atom(CW), atom(QW), tr_means_as(Side, C),
    tr_indirect_word(Side, QW, Q), memberchk(Q, [when, where]),
    tr_read_nested(Side, Ws, none, S), !.
%% ... AND A CLAUSE OF `where' ENDS AT A COORDINATOR AND A PHRASE AFTER IT: `pueden encontrarse chats donde los adeptos
%% se comunican y un tablón donde dejar anuncios diversos' are chats and a board, each with its clause -- read to the
%% end of the words, the clause had `y un tablón' in it, and nothing read. The phrase opens on a determiner, and what
%% follows the coordinator is read as the complements it is (cnj/1, the phrase, its own clause)
tr_complements0(foreign, [w(W, WC)|Ws], _, [wh(where, S)|Cs]) :-
    nb_getval('$tr_where_co', yes),
    Ws = [_|_], \+ memberchk(comma, Ws), atom(W), tr_indirect_word(foreign, W, where),
    append(CW, [Co, D|Rest], Ws), CW = [_|_], Rest = [_|_], Co = w(CoW, _), atom(CoW), tr_coord(foreign, Co),
    D = w(_, _), tr_determiner(foreign, D, _, _),
    %% (the phrase alone to the end, or with a clause of `where' of its own -- asked before the clause before it is
    %% read again, which a sentence with a coordinator after every `dove' paid at each: it_9472_9484's tenth, 1.2
    %% million inferences more)
    tr_where_tail(Rest),
    tr_phrase_rest(foreign, [D|Rest], NP2, Rest2), NP2 \= rc(_, _, _),
    ( Rest2 == [] -> true ; Rest2 = [w(W2, _)|_], atom(W2), tr_indirect_word(foreign, W2, where) ),
    tr_complements0(foreign, [w(W, WC)|CW], _, [wh(where, S)]),
    ( Rest2 == [] -> Cs2 = [] ; tr_complements(foreign, Rest2, Cs2) ), !,
    Cs = [cnj(Co), obj(NP2)|Cs2].
%% ... AND ONE BEFORE AN INFINITIVE ASKS WITH IT: `No sé dónde dormir' is where to sleep, and `un tablón donde
%% dejar anuncios diversos' a board on which to leave ads -- with the infinitive read as a statement nothing read,
%% and the word was the adverb `where' beside an infinitive, `I do not know to sleep where'. The clause is the
%% infinitive's, as a question with an infinitive is (s(_, none, g(F, present, infinitive, Neg), _)); after a phrase
%% it is the relative rwh/2, as a clause of `where' with a verb of its own is (tr_relative_wh/3)
%% (`how' only after a verb that takes the question: `era come parlare con due persone diverse' was LIKE speaking
%% with two people, and `è come cavalcare una tigre' like riding a tiger -- the word for `how' is the word for
%% `like' too, and read as the question it was `how to speak', `cómo cabalgar')
tr_complements0(foreign, [w(W, _), w(V, VC)|Ws], _, [wh(Q, S)]) :-
    atom(W), atom(V), tr_indirect_word(foreign, W, Q), memberchk(Q, [where, how, when]),
    ( Q == how -> tr_asks_question_here ; true ),
    tr_solve(infinitive_of(V, _)), \+ tr_is(foreign, w(V, lower), noun),
    tr_read_nested(foreign, [w(V, VC)|Ws], rel, S0), S0 = s(_, none, g(_, _, infinitive, _), _), !,
    tr_unrel(S0, S).
%% ... AND A QUESTION WORD THAT IS A CONNECTOR TOO ASKS ONLY AFTER A VERB THAT
%% TAKES THE QUESTION: `perché' is why and because, and the line that lets
%% it ask (`The word "perché" means "why".') made `La sinistra l'ha
%% attaccata perché Pivetti non si è adeguata' an attack WHY she had not
%% adapted -- `por qué' in four old controls, found by the controls and not
%% by the case. After any other verb it is the connector it was
tr_complements0(Side, [w(W, _)|Ws], _, [wh(Q, S)]) :-
    Ws \== [], tr_indirect_word(Side, W, Q),
    \+ ( tr_connector(Side, W), \+ tr_takes_question_here ),
    \+ ( tr_is(Side, w(W, lower), preposition), tr_phrase_words(Side, Ws, PW, Rest), PW \== [], tr_phrase_np(Side, PW, _),
         ( Rest == [] -> true ; Rest = [w(RP, _)|_], tr_is(Side, w(RP, lower), preposition), tr_complements(Side, Rest, RCs), tr_adjuncts(RCs) ) ),
    tr_read_nested(Side, Ws, none, S), !.
%% A GERUND AFTER A CLAUSE'S COMPLEMENTS IS HOW THE CLAUSE WAS DONE:
%% `destrozan la cabeza a un inmigrante utilizando un bate de béisbol'. It
%% takes the rest of the words as its own complements, the way a `che'
%% clause does, and travels as ger(Lexeme, Complements); every language
%% here writes it as its own gerund in the same place.
%% ... WITH ITS REFLEXIVE, the verb's as in a group: `Bros fue entonándose
%% hasta conseguir triunfar' is getting into his voice, ger(reflexive(L),
%% Complements) -- and NEVER AFTER THE COPULA, which takes no gerund in the
%% lesson's languages: `fue' is the past of `ser' and of `ir', and a gerund
%% after it says it is `ir', going on doing a thing, `andò intonandosi'
%% A GERUND AFTER THE COPULA WITH `che' AND A CLAUSE AFTER IT IS A CLEFT --
%% the manner put in front and stressed: `non è conoscendo la forma della
%% terra che ci si salva l'anima' is that one does not save one's soul BY
%% knowing the earth's shape. The copula takes no gerund (below), so it had
%% no reading. It travels as cleft(Gerund, Clause), the gerund read under
%% its own group, and every writer puts it back as it stood: the copula,
%% the gerund, its word for `that' and the clause, `No es conociendo la
%% forma de la tierra que uno se salva el alma'
%% (the gerund is asked first, which few words are: the copula's lexeme is
%% three lookups, and asked first they were paid by every complement read
%% after a copula, 15 000 inferences of Tatoeba's 400)
tr_complements0(foreign, [w(G, GC)|Ws], _, [cleft(ger(L, GCs), S)]) :-
    tr_gerund_here(foreign, G, L), tr_copula_group, \+ tr_is(foreign, w(G, lower), noun),
    append(GWs, [W|Rest], Ws), Rest \== [], tr_that_here(foreign, W),
    \+ memberchk(comma, GWs),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_group', L), nb_setval('$tr_read_aspect', simple),
    (   ( GWs == [] -> GCs = [] ; tr_complements(foreign, GWs, GCs) )
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ),
    GC \== enclitic, tr_that_clause(foreign, Rest, S), !.
tr_complements0(foreign, [w(G, _), w(Cl, enclitic)|Ws], _, [ger(reflexive(L), Cs)]) :-
    \+ tr_copula_group, tr_reflexive_word(Cl),
    tr_gerund_here(foreign, G, L), tr_complements(foreign, Ws, Cs), !.
%% ... AND WITH A PRONOUN OF ITS OWN JOINED TO IT: `pidiéndole que designara
%% a un fiscal' asks her to appoint one. The pronoun is the gerund's object,
%% and read as a phrase of its own it headed a relative clause, `le que
%% designara', him who appointed; it travels as opron/1 first among the
%% gerund's complements, and the lesson's writer joins it back on
tr_complements0(foreign, [w(G, _), w(Cl, enclitic)|Ws], _, [ger(L, [opron(w(Cl, lower))|Cs])]) :-
    \+ tr_copula_group, \+ tr_reflexive_word(Cl),
    tr_gerund_here(foreign, G, L), tr_complements(foreign, Ws, Cs), !.
%% ... AND ALONE, the last word of the clause: `si difende dai lanciatori di
%% fango, scappando' defends himself by running away
tr_complements0(Side, [w(G, _)|Ws], _, [ger(L, Cs)]) :-
    \+ ( Side == foreign, tr_copula_group ),
    tr_gerund_here(Side, G, L), \+ tr_is(Side, w(G, lower), noun),
    ( Ws == [] -> Cs = [] ; tr_complements(Side, Ws, Cs) ), !.
%% `AL' AND AN INFINITIVE IS THE MOMENT SOMETHING WAS DONE: `ha provocado el
%% escándalo al acusar a la institución' -- on accusing it. The lesson names
%% the word, `The word "al" begins the moment.', in the shape `The word
%% "per" begins the purpose.' already has; it is read as the words the
%% contraction stands for (`a el') with the infinitive after them, and the
%% rest of the words are the infinitive's complements. upon(Lexeme,
%% Complements) is the term; English writes `on' and the -ing form, and a
%% lesson that names no such word writes its gerund.
%% -- AND IT ENDS AT ITS FIRST COMMA: `Al abrir la audiencia, Hyde sostuvo
%% que ...' took the comma and `Hyde' for the infinitive's, so the front
%% swallowed the subject and the clause after it had nobody to say it
%% -- AND WITH THE INFINITIVE'S OWN PRONOUNS JOINED TO IT: `al reclamarle que
%% mantenga ...' is on demanding of him that he keep ... -- the `le' cut off
%% the infinitive stood in front of the rest as a word of the clause, which
%% no reading took (a preposition's infinitive carries them in pinf's cl/2,
%% and so does this one: upon(cl(Lexeme, Pronouns), Complements))
%% ... AND WITH ITS REFLEXIVE PRONOUN JOINED TO IT AND A PHRASE AFTER IT, the reflexive's passive and what it is done
%% to: `La situación se complicó al generarse un círculo vicioso' -- on a vicious circle being generated. The clause
%% below refuses a reflexive pronoun, which is no object's, and with it the words had no reading. uponse(Lexeme,
%% Phrase, Complements): English writes `on', the phrase, `being' and the participle; a lesson its own word and the
%% infinitive with the pronoun joined (`al generarse'), or its gerund with it (`generandosi un circolo vizioso')
tr_complements0(foreign, Ws0, Seen, [uponse(F, NP, Cs)|More]) :-
    Ws0 = [w(P, _), w(D, _), w(V, _), w(Cl, enclitic)|Ws1],
    tr_reflexive_word(Cl),
    tr_solve(begin(M, moment)), tr_solve(contraction_of(M, J)), atomic_list_concat([P, D], ' ', J),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    tr_upon_rest(foreign, Ws1, Seen, [obj(NP)|Cs], More), !.
%% ... AND OF A VERB WHOSE MEANING THE LESSON STATES WITH ITS PRONOUN, the reflexive verb's: `Al enterarse de la acción
%% del Comando ..., Oliveras recordó la peripecia' -- on finding out about it. With no phrase for the passive's subject
%% the clause above had nothing, and the one below refuses a reflexive pronoun: the front had no reading.
%% upon(reflexive(Lexeme), Complements), which crosses by the reflexive's meaning (tr_verb_across/5)
%% (and the phrase its verb governs is marked, as a participle's is: `enterarse de' finds out about it, never `of')
tr_complements0(foreign, Ws0, Seen, [upon(reflexive(F), Cs)|More]) :-
    Ws0 = [w(P, _), w(D, _), w(V, _), w(Cl, enclitic)|Ws1],
    tr_reflexive_word(Cl),
    tr_solve(begin(M, moment)), tr_solve(contraction_of(M, J)), atomic_list_concat([P, D], ' ', J),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), once(tr_solve(mean_as(F, _, reflexive))),
    tr_upon_rest(foreign, Ws1, Seen, Cs0, More), \+ memberchk(obj(_), Cs0), !,
    tr_ptc_governed(foreign, F, Cs0, Cs).
tr_complements0(foreign, Ws0, Seen, [Upon|More]) :-
    Ws0 = [w(P, _), w(D, _), w(V, _), w(Cl, enclitic)|Ws1],
    tr_solve(begin(M, moment)), tr_solve(contraction_of(M, J)), atomic_list_concat([P, D], ' ', J),
    \+ tr_reflexive_word(Cl),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    ( Ws1 = [w(Cl2, enclitic)|Ws] -> Cls = [w(Cl, lower), w(Cl2, lower)] ; Cls = [w(Cl, lower)], Ws = Ws1 ),
    tr_upon_rest(foreign, Ws, Seen, Cs, More), !,
    ( tr_upon_subject(F, Cs, NP, Rest) -> Upon = upons(F, NP, Rest) ; Upon = upon(cl(F, Cls), Cs) ).
tr_complements0(foreign, Ws0, Seen, [Upon|More]) :-
    Ws0 = [w(P, _), w(D, _), w(V, _)|Ws],
    tr_solve(begin(M, moment)), tr_solve(contraction_of(M, J)), atomic_list_concat([P, D], ' ', J),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    tr_upon_rest(foreign, Ws, Seen, Cs, More), !,
    ( tr_upon_subject(F, Cs, NP, Rest) -> Upon = upons(F, NP, Rest) ; Upon = upon(F, Cs) ).
tr_complements0(english, [w(on, _), w(G, _)|Ws], Seen, [upon(L, Cs)|More]) :-
    en_gerund(G, L), tr_upon_rest(english, Ws, Seen, Cs, More), !.
tr_complements0(foreign, [w(P, PC)|Ws], no, Out) :-
    tr_global('$tr_read_group', G0),
    tr_marker_word(P, Class),
    tr_person_words(Ws, PW, Rest),
    tr_phrase_np(foreign, PW, NP),
    ( tr_marked_class(NP, Class) ; tr_named_object(NP, Class, G0, P, PW) ; tr_warned_group(Class, NP, G0) ), !,
    tr_complements(foreign, Rest, yes, Cs),
    %% ... AND AN OBJECT AFTER IT MAKES IT THE INDIRECT ONE: `ha reclamado a
    %% los jugadores la máxima concentración' asked the players for it, and
    %% read as the object they came out `ha reclamato i giocatori la massima
    %% concentrazione', two objects and no `to'
    %% -- BUT ONLY AN OBJECT OF THE VERB ITSELF: the complements are one
    %% flat list, and an object after an infinitive is the infinitive's.
    %% `acusó a la mayoría de buscar el pan' accuses the majority of
    %% seeking the bread, and with the bread counted it came out `accusò
    %% alla maggioranza'
    %% -- AND A VERB THE LESSON SAYS TAKES THE WORD BEFORE A PERSON IS
    %% WRITTEN TO THEM, never done to them: `escribieron a la ministra' came
    %% out `scrissero la ministra'. `"escribe" takes "a" before the person.'
    %% is the shape `"confida" takes "di" before the infinitive.' already has
    %% -- AND SO DOES A CLAUSE OF THE VERB'S: `Redondo declaró a Europa Press
    %% que ...' said it TO the agency, and read as the object it came out
    %% `dichiarò Europa Press che ...'. What was declared is the clause.
    %% -- AND WITH NO VERB READ, IT IS THE PREPOSITION IT IS: `En
    %% declaraciones a Europa Press, Millàs consideró ...' -- statements to
    %% the agency, in front of the clause, and read as the person object a
    %% front takes no object, and the sentence was refused. The group is the
    %% one read when the words came here: the phrase's own relative clause
    %% reads clauses of its own, and after `al ministro que, en 1974, como
    %% señal de amistad, comió el pan' it was none, and the minister was a
    %% phrase of `to', `vide al ministro'
    %% -- AND AFTER A VERB THE LESSON CALLS INTRANSITIVE: `el fútbol también
    %% ha llegado a África' arrived in Africa, and read as a person marked as
    %% the object, Africa was what football arrived: `è arrivato África'
    %% -- AND A VERB OF SAYING TAKES THE PERSON TOLD AND THE CLAUSE TOLD, never
    %% the person as the one who says it: `dijo al técnico que el gato duerme'
    %% is told the coach that, and the person's relative clause was the
    %% clause -- the phrase `el técnico que el gato duerme' an object, which
    %% the subject after a verb of saying (tr_report_inv_fix/3) then took for
    %% the one who says
    %% -- AND AFTER A PASSIVE, whose subject is what was done to: `el proyecto
    %% fue presentado a los comerciantes' was shown TO the traders, and read as
    %% the object they came out `era presentato i commercianti'
    (   atom(G0), tr_saying_verb(G0), NP = rc(NP0, Role0, S1), tr_report_clause(Role0, S1, S2)
    ->  Out = [pp(w(P, PC), NP0), that(S2)|Cs]
    ;   ( tr_verb_object(Cs) ; tr_verb_clause(Cs) ; tr_takes_before_person(P) ; G0 == none
        ; atom(G0), tr_solve(intransitive(G0)) ; tr_read_passive )
    ->  Out = [pp(w(P, PC), NP)|Cs]
    ;   Out = [obj(NP)|Cs]
    ).
%% AN ARTICLE BEFORE A PERFECT INFINITIVE MAKES A NOUN OF IT, as before any
%% infinitive (ninf/1, tr_np/3): `L'errore è stato l'aver ceduto' and `La
%% forzatura è l'aver fatto passare l'intera coalizione per presidenzialista'
%% are the error being having yielded. `l'' read as the pronoun `lo', the
%% object of the copula, and Spanish wrote `El error lo ha sido haber
%% cedido'. The infinitive is the complement and the article is not written
%% back: every writer has the perfect infinitive without it.
tr_complements0(foreign, [D|Ws1], Seen, [infx(F, perfect, Cls)|Cs]) :-
    Ws1 = [w(AW, _)|_], atom(AW), tr_solve(infinitive_of(AW, _)),
    D = w(DW, _), atom(DW), tr_determiner(foreign, D, DL, article), tr_solve(mean(DL, the)),
    tr_det_gender(foreign, D, DL, G, singular), G \== feminine,
    tr_infinitive_group(Ws1, F, perfect, Cls0, Ws), !,
    tr_complements(foreign, Ws, Seen, Cs),
    tr_undouble(Cls0, Cs, Cls).
%% AN INFINITIVE WITH ITS OWN PRONOUNS, OR IN THE PERFECT: `riprenderli'
%% (to recover them), `ritrovarsi' (to find oneself), `di aver lasciato i
%% piccoli' (to have left the little ones), `di essersi persa' (to have got
%% lost), `possa essere successo' (may have happened). The perfect's
%% auxiliary is an infinitive the lesson gives -- of its auxiliary, or of
%% the copula where the lesson says the verb or the reflexive builds its
%% perfect with it -- and the pronouns are the ones tr_enclitics/3 cut off.
%% It travels as infx(Lexeme, simple|perfect, Pronouns); an infinitive with
%% neither is still inf/1, so nothing that read before reads differently.
%%
%% A PREPOSITION MEANING `of' OR `to' IN FRONT OF ONE IS ITS OWN: `ha
%% raccontato DI aver avuto un problema' -- the complementiser Italian puts
%% before an infinitive after a verb of saying -- and the IR carries the
%% infinitive alone, the stated cost of tr_means_to/1 below.
%% -- AND AFTER AN OBJECT A `de' IS THE NOUN'S, AS IT IS BEFORE A PLAIN
%% INFINITIVE (pinf/2): `la presión de jugárselo todo' is the pressure of
%% risking it all, and the preposition travels as nprep/1 before the
%% infinitive, which the lesson's writer spells and English's leaves out
%% (`the pressure to risk everything')
%% -- unless the lesson says the word BEGINS THE INFINITIVE, which is the
%% verb's: `di aver avuto un problema e di aver lasciato i bimbi' has an
%% object before its second `di', and read as the problem's it came out `y
%% de haber dejado'
tr_complements0(foreign, Ws0, Seen, Out) :-
    ( Ws0 = [w(P, PC)|Ws1], ( tr_means_to(P) ; tr_means_of(P) ) -> Pre = w(P, PC) ; Ws1 = Ws0, Pre = none ),
    tr_infinitive_group(Ws1, F, Asp, Cls0, Ws), !,
    tr_complements(foreign, Ws, Seen, Cs),
    tr_undouble(Cls0, Cs, Cls),
    (   Pre = w(PW, _), tr_means_of(PW), Seen == yes, \+ tr_solve(begin(PW, infinitive))
    ->  Out = [nprep(Pre), infx(F, Asp, Cls)|Cs]
    %% -- AND A `to' IS KEPT, which the lesson's writer spells as it spells
    %% the one before a plain infinitive (ainf/2) and English writes as its
    %% own: `Il cane comincia a lavarsi' came out `El perro comienza
    %% lavarse', and `Vittori, disposto a dedicarsi alla docenza' lost its
    %% `a' the same way
    %% (never where the verb before it takes that word before its
    %% infinitive, which makes the word the verb's, as it is before a plain
    %% infinitive (take_before/3, below): `è riuscito a dirmi', `"riesce"
    %% takes "a" before the infinitive.', is `ha logrado decirme', and with
    %% the `a' kept it was `ha logrado a decirme' -- the Fregene report's
    %% seventy-second, which read right before this version)
    ;   Pre = w(PW, _), tr_means_to(PW),
        \+ ( tr_global('$tr_read_group', G), atom(G), tr_solve(take_before(G, PW, infinitive)) )
    ->  Out = [nprep(Pre), infx(F, Asp, Cls)|Cs]
    ;   Out = [infx(F, Asp, Cls)|Cs]
    ).
%% ... AND DENIED, the denial between the preposition and the infinitive:
%% `gli unici a non credervi erano stati solo Leucippo e Democrito' -- the
%% only ones NOT TO believe it. Read as a preposition whose object is the
%% adverb `non' (`per sempre') and an infinitive after it, it held only where
%% the vocabulary calls `non' an adverb meaning `non', the pronoun joined to
%% the infinitive was the adverb `there', and English wrote `the only ones to
%% not to sleep'. The infinitive is the denied one tr_complements0/4 reads
%% after its denial (neg/1), and the preposition is kept or left as above:
%% English writes `not to believe', a lesson `a no creer'
%% (the denial asked first: every complement list of two words or more
%% reaches this clause, and the two lookups of the preposition were paid by
%% each of them)
tr_complements0(foreign, [w(P, PC), w(N, _)|Ws1], Seen, Out) :-
    atom(N), tr_negation_word(N), atom(P), ( tr_means_to(P) ; tr_means_of(P) ),
    tr_starts_infinitive(foreign, Ws1),
    tr_complements(foreign, Ws1, Seen, [C|Cs]), ( C = inf(_) ; C = infx(_, _, _) ), !,
    (   tr_means_of(P), Seen == yes, \+ tr_solve(begin(P, infinitive))
    ->  Out = [nprep(w(P, PC)), neg(C)|Cs]
    ;   tr_means_to(P),
        \+ ( tr_global('$tr_read_group', G), atom(G), tr_solve(take_before(G, P, infinitive)) )
    ->  Out = [nprep(w(P, PC)), neg(C)|Cs]
    ;   Out = [neg(C)|Cs]
    ).
%% A DENIED INFINITIVE, the denial its own (tr_negation/4 leaves it where
%% it stands): `è facile non ritrovarsi più' -- not to find oneself.
%% (and a quotation that opens on the denial opens there, qm/2: `recomendó "no cerrar puertas"' -- the mark on the
%% denial was taken for the verb group's, `"raccomandò non chiudere porte"')
tr_complements0(foreign, [w(N, NC)|Ws0], Seen, [NegC|Cs]) :-
    tr_solve(mean(N, not)), tr_starts_infinitive(foreign, Ws0),
    tr_complements(foreign, Ws0, Seen, [C|Cs]), ( C = inf(_) ; C = infx(_, _, _) ), !,
    ( tr_open_mark(NC) -> NegC = qm(NC, neg(C)) ; NegC = neg(C) ).

%% A PREPOSITION THE VERB TAKES BEFORE AN INFINITIVE IS THE VERB'S, NOT THE
%% SENTENCE'S. `confía EN repetir el guión' is trusting to repeat it, and
%% Italian's verb takes another word there: `confida DI ripetere'. Carried
%% as a phrase, the preposition crossed as `in' and came out `affida in
%% ripetere'. The lesson says which word a verb takes -- `"confía" takes
%% "en" before the infinitive.' -- the IR carries the infinitive alone, and
%% each writer puts back what ITS verb takes (tr_verb_takes/1).
%% (a quotation that opens on the infinitive opens there, qm/2 written on the infinitive itself: `acusara a Millàs de
%% "hacer trampa"' came out `di fare trappola"' once the lesson said `"acusa" takes "de" before the infinitive.')
tr_complements0(foreign, [w(P, _), w(V, VC)|Ws], Seen, [Inf|Cs]) :-
    tr_global('$tr_read_group', G), atom(G), tr_solve(take_before(G, P, infinitive)),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    ( tr_open_mark(VC) -> Inf = qm(VC, inf(F)) ; Inf = inf(F) ),
    tr_question_after_inf(F, Ws, Seen, Cs).
%% A PREPOSITION BEFORE AN INFINITIVE: `invece di andare da una parte' --
%% instead of going, en vez de ir. The lesson's languages put the infinitive
%% after a preposition where English puts the -ing form; pinf(Preposition,
%% Lexeme) is the term, and the infinitive's own complements follow it.
%% ... AND WITH THE REFLEXIVE JOINED TO IT: `hasta situarse en 61,9
%% millones de unidades' is until it stood at 61.9 million, and the `se' cut
%% off the infinitive (tr_enclitics/3) was read as a pronoun of its own, the
%% impersonal one -- `fino situare uno in'. The reflexive is the verb's, as
%% it is in a group: pinf(Preposition, reflexive(Lexeme)).
tr_complements0(foreign, [w(P, C), w(V, _), w(Cl, enclitic)|Ws], Seen, [pinf(w(P, C), reflexive(F))|Cs]) :-
    tr_is(foreign, w(P, C), preposition), \+ tr_means_to(P), \+ tr_means_of(P), \+ tr_purpose_word(P),
    tr_reflexive_word(Cl),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    tr_complements_after_inf(w(P, C), F, Ws, Seen, Cs).
%% ... AND WITH ANOTHER PRONOUN JOINED TO IT: `sin pedirles grandes
%% exigencias' is without asking THEM, and the `les' cut off the infinitive
%% was read as a pronoun of the clause, which the lesson's writer puts before
%% the clause's verb -- `e gli permette ... senza chiedere'. The pronouns are
%% the infinitive's, one or two: pinf(Preposition, cl(Lexeme, Pronouns)).
tr_complements0(foreign, [w(P, C), w(V, _), w(Cl, enclitic)|Ws0], Seen, [pinf(w(P, C), cl(F, Cls))|Cs]) :-
    tr_is(foreign, w(P, C), preposition), \+ tr_means_to(P), \+ tr_means_of(P), \+ tr_purpose_word(P),
    \+ tr_reflexive_word(Cl),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    ( Ws0 = [w(Cl2, enclitic)|Ws] -> Cls = [w(Cl, lower), w(Cl2, lower)] ; Cls = [w(Cl, lower)], Ws = Ws0 ), !,
    tr_complements_after_inf(w(P, C), F, Ws, Seen, Cs).
%% (a quotation that opens on the infinitive opens there, qinf/2: `está en "reconocer como válidos ..."' lost its
%% opening mark, the infinitive keeping no case, `è in riconoscere come vigente ..."')
tr_complements0(foreign, [w(P, C), w(V, VC)|Ws], Seen, [pinf(w(P, C), FQ)|Cs]) :-
    tr_is(foreign, w(P, C), preposition), \+ tr_means_to(P), \+ tr_means_of(P), \+ tr_purpose_word(P),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    ( tr_open_mark(VC) -> FQ = qinf(VC, F) ; FQ = F ),
    tr_complements_after_inf(w(P, C), F, Ws, Seen, Cs).
%% ... and with an ARTICLE between them, the infinitive used as a noun:
%% `il loro incessante impegno NEL realizzare il progetto' is in carrying it
%% out, and `nel' is `in' and `il'. The article says nothing a writer needs
%% -- Spanish writes `en realizar' and English `in carrying out' -- so it
%% goes, and the preposition and the infinitive are what they were above.
tr_complements0(foreign, [w(P, C), D, w(V, _)|Ws], Seen, [pinf(w(P, C), F)|Cs]) :-
    tr_is(foreign, w(P, C), preposition), \+ tr_means_to(P), \+ tr_means_of(P), \+ tr_purpose_word(P),
    tr_determiner(foreign, D, _, article),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    tr_complements_after_inf(w(P, C), F, Ws, Seen, Cs).
%% A PREPOSITION MEANING `of' BEFORE A PLAIN INFINITIVE: `ci permetterà DI
%% realizzare la nostra visione', `la nostra visione DI creare un
%% costruttore'. Only a perfect infinitive or one with a pronoun joined to it
%% had a reading after `di', so both refused. Straight after the verb the
%% word is the verb's and every language here has its own way with it --
%% Spanish writes `nos permitirá realizar', bare, and English `to realize'
%% -- so it is the plain infinitive; after an OBJECT it belongs to the noun
%% before it, `la visión DE crear', and it keeps its preposition as pinf/2.
%% STRAIGHT AFTER THE VERB ONLY WHERE THE LESSON SAYS THE WORD BEGINS AN
%% INFINITIVE -- `The word "di" begins the infinitive.', the purpose word's
%% shape -- because Italian's `di' is what English's `to' is and Spanish's
%% `de' is not: `Él me acaba de enviar un mensaje' read as `He finishes me
%% to send a message', where `acabar de' is `has just', and it had been
%% refused. Nothing in a lesson says which verbs take which word, so a
%% language whose lesson says nothing keeps the refusal.
%% (a quotation that opens on the infinitive after `de' opens there, qinf/2:
%% `acusara a Millàs de "hacer trampa"' came out `di fare trappola"', the
%% closing mark with no opening one)
tr_complements0(foreign, [w(P, C), w(V, VC)|Ws], Seen, [Inf|Cs]) :-
    tr_means_of(P), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    ( tr_open_mark(VC) -> FQ = qinf(VC, F) ; FQ = F ),
    ( Seen == yes -> Inf = pinf(w(P, C), FQ), Prep = w(P, C) ; tr_infinitive_mark(P), Inf = inf(F), Prep = none ), !,
    ( tr_copula_group -> Seen1 = no ; Seen1 = Seen ),
    tr_complements_after_inf(Prep, F, Ws, Seen1, Cs).
%% an infinitive: the lesson's (`"comer" is the infinitive of "come"'), or
%% English's `to' and a base form, and a bare base form after a modal
%% A WORD THAT BEGINS THE CAUSE, BEFORE A PERFECT INFINITIVE, SAYS WHY: `punito
%% per aver riconquistato il titolo' is punished FOR HAVING regained it, and
%% `Innocente, per aver assunto la sostanza' innocent for having taken it. The
%% word is the purpose word too (`per', as `per mangiare' is to eat), and read
%% so the group came out `to have regained', `para tener recuperado'; nobody
%% acts in order to have done something, so before a perfect infinitive the
%% word is the cause's, which the lesson states (`The word "per" begins the
%% cause.'). The group travels whole, pinf(Word, perf(Lexeme, Pronouns)),
%% as the perfect infinitive does after the preposition of an adjective below
tr_complements0(foreign, [w(P, PC), w(V, VC)|Ws1], Seen, [pinf(w(P, PC), perf(F, Cls))|Cs]) :-
    atom(V), tr_solve(infinitive_of(V, _)),
    tr_infinitive_group([w(V, VC)|Ws1], F, perfect, Cls0, Ws),
    tr_cause_word(P), !,
    tr_perf_rest(F, Ws, Seen, Cs),
    tr_undouble(Cls0, Cs, Cls).
%% A PURPOSE IS AN INFINITIVE WITH A WORD IN FRONT OF IT: `per definire' is
%% `to define', `para definir'. The lesson names the word -- `The word "per"
%% begins the purpose.' -- which is the shape `The mark "¿" begins the
%% question' already uses, so no grammar moved for it.
%%
%% ENGLISH LOSES THE DISTINCTION AND THAT IS ENGLISH'S DOING, not a gap here.
%% `wants to eat' and `came to eat' are the same three words, so English
%% writes a purpose exactly as it writes a plain infinitive, and an English
%% source is read as the plain one. Italian into Spanish keeps the mark
%% because both languages make it; Italian into English and back loses it.
%% (a quotation that opens on the purpose word opens on the purpose, qm/2:
%% `"para evitar una alteración ..."' -- the word is a verb's form too, and
%% the mark was taken for one that opened on the verb and written at the
%% head of the sentence)
%% ... DENIED: `quattro minuti per non morire' -- four minutes not to die, the
%% headline of an interview. The word that denies stands between the purpose
%% word and the infinitive, and read as the phrase of `per' that it is
%% otherwise (`per non morire' was pp(per, adv(non)) and inf/1) English wrote
%% `for not to die'. It travels as npurpose/1, written with the lesson's own
%% word for `not' and English's `not to'
tr_complements0(foreign, [w(P, _), w(N, _), w(V, _)|Ws], _, [npurpose(F)|Cs]) :-
    tr_purpose_word(P), atom(N), tr_negation_word(N), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    \+ Ws = [w(_, enclitic)|_], !,
    tr_complements(foreign, Ws, _, Cs).
tr_complements0(foreign, [w(P, PC), w(V, VC)|Ws], _, [Purpose|Cs]) :-
    tr_purpose_word(P), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    \+ Ws = [w(_, enclitic)|_], !,                     % (the pronoun joined to it is the clause below)
    %% (and one that opens on the infinitive after it opens there, qm2/2:
    %% `con el fin de "encontrar una solución ..."')
    %% (and a quotation of the purpose alone closes on its infinitive, both
    %% marks kept: `"para dormir".' came out `mangia" il pane "per
    %% dormire', the closing mark taken for one on the clause's verb)
    (   tr_open_mark(PC), VC == qclose -> Purpose = qm(PC, qm2(VC, purpose(F)))
    ;   tr_open_mark(PC) -> Purpose = qm(PC, purpose(F))
    ;   tr_open_mark(VC) -> Purpose = qm2(VC, purpose(F))
    ;   Purpose = purpose(F)
    ),
    %% (what follows the infinitive is ITS complements, read afresh: `recuperó
    %% la hemeroteca para "retratar" a Aznar' portrays Aznar, and with the
    %% main clause's object counted as seen the person after `a' was `to
    %% Aznar', `per ritrarre a Aznar')
    tr_complements(foreign, Ws, _, Cs).
%% ... AND AN INFINITIVE WITH ITS OWN PRONOUNS AFTER THE WORD: `per
%% stringergli la mano' -- to shake his hand. The pronoun joined to the
%% infinitive kept it from being one the lesson gives, and the sentence was
%% refused with every word known. It travels as purp(infx(...)), the
%% infinitive group tr_infinitive_group/5 reads, and each writer puts its
%% purpose word before what it writes for the group.
tr_complements0(foreign, [w(P, _)|Ws1], Seen, [purp(infx(F, Asp, Cls))|Cs]) :-
    tr_purpose_word(P), tr_infinitive_group(Ws1, F, Asp, Cls0, Ws), Cls0 \== [], !,
    tr_complements(foreign, Ws, Seen, Cs),
    tr_undouble(Cls0, Cs, Cls).
%% A PREPOSITION MEANING `to' BEFORE AN INFINITIVE IS THE INFINITIVE.
%% `si tende AD accreditare la tesi', `comienza A comer' -- the word belongs
%% to the verb and not to a phrase, and without this clause the pp/2 clause
%% below took it, cut, and refused the sentence for want of a phrase after
%% it. The purpose clause above is the same shape with the word the lesson
%% calls the purpose's.
%%
%% WHICH PREPOSITION A VERB WANTS IS NOT IN THE IR, and that is the cost.
%% English writes its own `to' and the lesson's language writes the bare
%% infinitive, so `si tende ad accreditare' comes back `se tiende
%% acreditar': the word is lost, because nothing a lesson says pairs a verb
%% with the preposition its infinitive takes.
%% THE `to' BEFORE AN INFINITIVE IS KEPT: `andare a chiedere aiuto' is `ir a
%% pedir ayuda', and dropped it came out `ir pedir'. It travels as ainf/2 and
%% English writes its own `to' either way; the lesson's writer puts its word
%% for `to' back, which is right after the verbs of going and beginning that
%% take one, and wrong after the few that take none (`riuscire a', `lograr')
%% (a quotation that opens on the infinitive opens there, qinf/2, as after a
%% preposition: `que su partido se vaya a "tirar al monte"' came out `si va a
%% gettare al monte"', the closing mark with no opening one)
tr_complements0(foreign, [w(P, PC), w(V, VC)|Ws], Seen, [ainf(w(P, PC), FQ)|Cs]) :-
    tr_means_to(P), tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    ( tr_open_mark(VC) -> FQ = qinf(VC, F) ; FQ = F ),
    tr_question_after_inf(F, Ws, Seen, Cs).
%% (the copula's infinitive and a participle after it are a passive, and a
%% `by' phrase after them its agent: `debería ser refrendada por los
%% miembros' is confirmed BY the members, and read as an adjunct it came out
%% `confermata per i membri', for them)
%% (and after the infinitive of a verb that takes the question, as after the
%% verb: `vogliono dire quanto Roma disti', how much, above)
tr_complements0(foreign, [w(V, _), w(Q, _)|Ws], _, [inf(F), wh('how much', S)]) :-
    Ws \== [], atom(V),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), tr_solve(take(F, question)), tr_how_much_word(Q),
    tr_read_nested(foreign, Ws, none, S), !.
%% (a quotation that opens on it opens there, qm/2: `recomendó "cerrar puertas"' lost its opening mark -- bare/1 on the
%% mark, as no word of the source stood before it: English's `"to close doors"')
tr_complements0(foreign, [w(V, VC)|Ws], Seen, [Inf|Cs]) :-
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    ( tr_open_mark(VC) -> Inf = qm(bare(VC), inf(F)) ; Inf = inf(F) ),
    (   Ws = [w(P1, _)|_], atom(P1), tr_copula_lexeme(F), tr_participle_here(foreign, P1, _)
    ->  tr_global('$tr_read_aspect', A0), nb_setval('$tr_read_aspect', passive),
        (   tr_complements(foreign, Ws, Seen, Cs) -> nb_setval('$tr_read_aspect', A0)
        ;   nb_setval('$tr_read_aspect', A0), fail
        )
    ;   tr_complements(foreign, Ws, Seen, Cs)
    ).
tr_complements0(english, [w(to, _), w(B, _)|Ws], Seen, [inf(L)|Cs]) :-
    en_infinitive(B, L), !,
    tr_complements(english, Ws, Seen, Cs).
tr_complements0(english, [w(B, _)|Ws], Seen, [inf(L)|Cs]) :-
    tr_read_modal, en_infinitive(B, L), !,
    tr_complements(english, Ws, Seen, Cs).
%% TWO VERBS IN THE SIMPLE PAST JOINED BY A COORDINATOR SHARE THE SUBJECT AND
%% THE OBJECT: `la banda che rapì e uccise nel 1977 il duca' kidnapped and
%% killed him. `uccise' is the feminine plural participle too, and read as one
%% it was said of the gang, `secuestró y matada'; a relative clause is not
%% divided at its coordinator as a sentence is (`mangiò e bevve il latte').
%% After a verb that is no copula, in a simple tense, a word that is a verb's
%% past in the third person as well travels as cverb/1 where an object
%% follows, and each writer writes it in the clause's tense and person
%% (tr_cverbs/6)
tr_complements0(foreign, [C, w(P, _)|Ws], Seen, [cnj(C), cverb(L2)|Cs]) :-
    tr_coord(foreign, C), atom(P), tr_global('$tr_read_aspect', simple),
    tr_global('$tr_read_group', L), atom(L), \+ tr_copula_lexeme(L),
    tr_participle_here(foreign, P, _),
    tr_group_from(foreign, [w(P, lower)], [], g(L2, past, simple, third, singular), []), atom(L2),
    \+ tr_copula_lexeme(L2),
    tr_complements(foreign, Ws, Seen, Cs), memberchk(obj(_), Cs), !.
%% TWO INFINITIVES UNDER ONE PURPOSE: `per definire "illegale" la decisione
%% E invocare il sostegno dei suoi soldati'. The conjunction is not inside a
%% phrase -- which is the splitter's `A e B' -- and it is not between two
%% clauses either, because the second half has no subject and no finite
%% verb. It is between two COMPLEMENTS, so it travels as one and writes
%% with the target's word for it.
tr_complements0(Side, [C|Ws], Seen, [cnj(C)|Cs]) :-
    tr_coord(Side, C), tr_after_coord(Side, Ws), !,
    tr_complements(Side, Ws, Seen, Cs).
%% ... AND AN ADJECTIVE AFTER A COORDINATOR IS SAID OF A NOUN THE PHRASE BEFORE
%% IT DOES NOT AGREE WITH: `una calle con tramos de acera de distintas
%% anchuras e incómodos para el tránsito' -- the stretches are uncomfortable,
%% and the adjective stands after the whole chain of `de' phrases, which
%% tr_phrase_words0/4 ends before the coordinator (tr_postposed_adjective/2).
%% It travels as oadj/3 with its OWN gender and number: left to the clause's
%% subject (`la peatonalización', feminine singular) it was `scomoda'.
tr_complements0(foreign, [C, A|Ws], _, [cnj(C), oadj(PW, G, N)|Cs]) :-
    C = w(_, _), tr_coord(foreign, C), tr_postposed_adjectives([A|Ws], PW, Rest),
    tr_adjective_agreement(A, G, N), !,
    tr_complements(foreign, Rest, yes, Cs).
%% ... AND A WORD FOR `THAT IS' BEFORE WHAT IT SAYS AGAIN: `smentisce quanto
%% pubblicato e cioè di aver firmato il passaggio' -- what was published,
%% that is, signing the move; `..., vale a dire che il suo diretto superiore
%% non sarà Emilio Fede' -- that is, that his boss will not be. The word is
%% a connector of two clauses where a verb follows it, and between two
%% COMPLEMENTS where an infinitive or a clause of `that' does: it travels as
%% one, and writes with the target's word for it
tr_complements0(foreign, [C|Ws], Seen, [cnj(C)|Cs]) :-
    C = w(CW, _), atom(CW), tr_solve(conjunction(CW)), tr_solve(mean(CW, 'that is')),
    Ws = [W1|_], ( tr_after_coord(foreign, Ws) ; tr_that_here(foreign, W1) ), !,
    tr_complements(foreign, Ws, Seen, Cs).
%% ... AND AN ABSOLUTE PHRASE: `Paolo Brosio in diretta e il tribunale di
%% Milano come sfondo' is live AND WITH the court of Milan as background. A
%% phrase that opens on its article after a coordinator, and what it is
%% (`come' and a phrase) after it, is the preposition's phrase it is
%% understood to be: the lesson's word for `with' is put before it
tr_complements0(foreign, [C, D|Ws], Seen, [cnj(C), pp(w(With, lower), NP)|Cs]) :-
    tr_coord(foreign, C), D = w(_, _), tr_determiner(foreign, D, _, article),
    tr_like_within(Ws, 12),
    tr_phrase_words(foreign, [D|Ws], PW, Rest), PW \== [],
    tr_phrase_np(foreign, PW, NP),
    once(( tr_solve(mean(With, with)), tr_class_of(With, preposition) )),
    tr_complements(foreign, Rest, Seen, Cs),
    append(Of, [pp(w(Like, _), _)|_], Cs), forall(member(X, Of), ( X = pp(P, _), tr_means_of(foreign, P) )),
    atom(Like), tr_lexeme(foreign, Like, LL, _), tr_solve(mean(LL, like)), !.
%% ... AND A SUBORDINATING WORD BEFORE A DENIED ADJUNCT: `sono banditi SE NON
%% per sempre quantomeno per qualche giorno' -- if not for ever, at least for
%% some days. No verb follows it, so no clause does; read as a phrase, `se'
%% was the noun of one, because a word no lesson calls a noun is a phrase's
%% noun by position, and the IR said the cars were banned an `if'.
%% The denial and the adjunct after it are one complement, neg/1.
%% ... OR A PHRASE: `una curiosità maliziosa, se non una vera e propria
%% pressione' -- if not a genuine pressure. The word for `if' and a denial
%% before a phrase travel as they do before an adjunct, the phrase after the
%% denial as the object it is
tr_complements0(Side, [C|Ws], Seen, [cnj(C), neg(C1)|Cs]) :-
    C = w(CW, _), tr_connector(Side, CW), \+ tr_coord(Side, C),
    Ws = [w(N, _)|Ws1], ( Side == english -> N == not ; tr_negation_word(N) ),
    (   tr_after_coord(Side, Ws1), !,
        tr_complements(Side, Ws1, Seen, [C1|Cs]), tr_adjunct(C1)
    ;   Side == foreign, tr_if_word(CW),
        tr_complements(foreign, Ws1, Seen, [C1|Cs]), C1 = obj(_), !
    ).
%% ... AND A COORDINATOR BEFORE A DENIED PHRASE: `un governo che duri 5 anni
%% e non due mesi' -- five years and not two months. tr_negation/4 leaves a
%% denial after a coordinator with no verb after it where it stands, and the
%% denial and the phrase are one complement, neg/1, after the coordinator.
tr_complements0(foreign, [C, w(N, _)|Ws1], Seen, [cnj(C), neg(obj(NP))|Cs]) :-
    C = w(_, _), tr_coord(foreign, C), atom(N), tr_negation_word(N),
    %% (and a phrase after the denial, which a verb's form does not begin:
    %% `Pero ¿no eran inglesas estas hordas ...?' read `eran inglesas ...'
    %% as a phrase to find that it was not one)
    %% -- nor a verb's form that is a noun too: `que pesan muy poco y no son,
    %% en consecuencia, reales' is and are not real, and `son' read as the
    %% noun `sound' made them weigh little and no sound
    Ws1 = [w(V1, _)|_], \+ ( atom(V1), tr_denied_verb_form(V1) ),
    tr_phrase_words(foreign, Ws1, PW, Rest), PW \== [], tr_phrase_np(foreign, PW, NP), !,
    tr_complements(foreign, Rest, Seen, Cs).
%% ... AND A PHRASE AFTER A COORDINATOR WITH THE WORD FOR `no' AFTER IT, the
%% last of the words: `Che poi queste cose le sapessero i dotti e i semplici
%% no' -- the learned knew them and the simple did NOT. The phrase and its
%% `no' are one complement, nega/1, after the coordinator; every lesson's
%% writer puts its word for `no' after the phrase, as the source did, and
%% English its `not' before it. Read as the clause's adverb, the `no' said
%% nothing of the second half, and English wrote `the learned and the simple
%% ones no'
tr_complements0(foreign, [C|Ws1], _, [cnj(C), nega(obj(NP))]) :-
    C = w(_, _), tr_coord(foreign, C), Ws1 = [_, _|_],
    last(Ws1, w(N, _)), atom(N), tr_no_word(N),
    append(PW, [_], Ws1), tr_phrase_np(foreign, PW, NP), !.
%% OF WHICH, WITH NO VERB: `si sono adoperate 37 associazioni di protezione
%% civile, di cui tre di unità cinofile' -- three of them, of canine units.
%% A preposition and the relative the lesson says follows one (`"cui"
%% follows the preposition'), then a phrase and nothing that is a verb. It
%% travels as rpp/2, and each writer puts its own relative after the
%% preposition: English's `of which', Spanish's `de las que' with the
%% article agreeing with the OBJECT before it, which is what the which is.
%% -- and ADVERBS BEFORE ITS PHRASE are the phrase's: `di cui SOLO uno' is
%% only one of them, advp(Adverb, Phrase), which every writer puts in front
%% A RELATIVE CLAUSE WHOSE ARTICLE IS NOT THE PHRASE'S BEFORE IT: `envió una
%% carta a los 16.000 socios EN LA QUE se les insta ...' is the letter in
%% which, and `la' cannot stand for the plural `socios' -- tr_np/3 refused
%% the clause there, and the sentence had no reading. It is the relative
%% clause of the object before, rca(Role, Clause), written after what stands
%% between, its article agreeing with that object as `of which' does (rpp/2).
%% It commits to nothing: `El perro de los que comen pan duerme' is the dog
%% of those who eat bread, a `de' phrase whose noun the clause stands for
%% (ell/4, below), and with a cut here that reading was never asked and the
%% sentence was refused
tr_complements0(foreign, [P, D, w(R, RC)|Ws], Seen, [rca(pp(P), S)]) :-
    Seen == yes, Ws \== [], tr_is(foreign, P, preposition), tr_determiner(foreign, D, _, article),
    tr_relative_word(foreign, R),
    once(tr_relative_clause(foreign, [P, D, w(R, RC)|Ws], pp(P), S)).
tr_complements0(Side, [P, w(R, _)|Ws0], Seen, [rpp(P, NP)|Cs]) :-
    tr_rel_after_prep(Side, R), tr_is(Side, P, preposition),
    tr_lead_adverbs(Side, Ws0, As, Ws),
    tr_phrase_words(Side, Ws, PW, Rest), PW \== [], tr_phrase_np(Side, PW, NP0), !,
    tr_advp(As, NP0, NP),
    tr_complements(Side, Rest, Seen, Cs).
%% THE AGENT OF A PASSIVE IS NOT AN ADJUNCT: `dai soldati' is who did it,
%% and it travels as by/1 so that it writes with the TARGET's word for `by'.
%% Read as an ordinary pp/2 it would cross by the first meaning of `da',
%% which the lesson gives as `from' -- and `imposed from the soldiers' is
%% not what the sentence says.
tr_complements0(Side, [P|Ws], Seen, [by(NP)|Cs]) :-
    tr_read_passive, tr_is(Side, P, preposition), tr_means_by(Side, P), \+ tr_bare_start(Side, Ws),
    \+ tr_date_range(Side, Ws), \+ tr_time_after(Side, Ws), !,
    tr_phrase_rest(Side, Ws, NP, Rest),
    tr_complements(Side, Rest, Seen, Cs).
%% AND A PREPOSITION'S OBJECT MAY BE AN ADVERB: `per sempre' is `for
%% ever', `para siempre', and every language writes it as the two words it
%% is. It rides pp/2 with adv/1 where the phrase goes, so the crossing and
%% both writers take it apart by the clauses they already had.
%% A WORD THAT IS A PREPOSITION AND AN ADVERB IS THE ADVERB WHEN NO PHRASE
%% FOLLOWS IT: `130 circa tra uomini e donne' -- about a hundred and thirty,
%% and `circa' is `concerning' too. The preposition is committed to only
%% once its phrase has read.
%% ... AND ONE MEANING `as' OR `like' MAY TAKE A PHRASE WITH A PREPOSITION OF
%% ITS OWN: `regolamentate con giudizio e con equilibrio come in tutti i
%% parchi naturali' -- as in all the natural parks. With no noun phrase after
%% `come' the sentence was refused; the inner pp/2 rides where the phrase
%% goes, as the adverb of `per sempre' does.
tr_complements0(Side, [P, P2|Ws], Seen, [pp(P, PP)|Cs]) :-
    P2 = w(_, _), tr_is(Side, P, preposition), tr_is(Side, P2, preposition), tr_means_as(Side, P),
    tr_complements(Side, [P2|Ws], Seen, [PP|Cs]), PP = pp(_, _), !.
%% A PREPOSITION THAT TAKES `di' BEFORE A PRONOUN has it as its own (`"senza" takes
%% "di" before the pronoun.'): `senza di lui' is without him, `contro di noi'
%% against us -- the pronoun is the preposition's object, as it is with no `di'
tr_complements0(foreign, [P, w(DI, _), w(O, OC)|Ws], Seen, [pp(P, pronoun(w(O, OC)))|Cs]) :-
    P = w(PW, _), atom(PW), atom(DI),
    tr_is(foreign, P, preposition), tr_solve(take_before(PW, DI, pronoun)),
    tr_object_pronoun_here(foreign, [w(O, OC)|Ws]), \+ tr_relative_start(foreign, Ws), tr_oblique_pronoun(foreign, O), !,
    tr_after_phrase(no, foreign, Ws, Seen, Cs).
%% A CLITIC IS NEVER A PREPOSITION'S OBJECT. `En la siguiente toma, cuando
%% ...' is in the next shot, and cut after `la' it was `in her' and `toma'
%% the command take: `Prendi nella seguente'. A pronoun after a preposition
%% is one that may be a subject or that the lesson says does not precede
%% the verb (`con él', `a lui', `per me') -- the writer's own choice for an
%% oblique pronoun (tr_pronoun_across/6), read.
%% `BEN' BEFORE A COUNT SAYS HOW MANY: `la presenza di ben 11 veleni diversi' is the presence of as many
%% as 11 different poisons -- `ben' is the apocope of `bene', and read as its noun the presence was of a
%% good and the eleven poisons a second object. The adverb whose meaning is `well', right before a count,
%% is the phrase's (advp/2), and it crosses as `as many as' (tr_cross_np/2); so is one the lesson says
%% means `as many as' (Spanish's `nada menos que 11 venenos', which was `finds 11 poisons as many as')
tr_complements0(foreign, [P, w(B, BC), N|Ws], Seen, [pp(P, advp(w(B, BC), NP))|Cs]) :-
    atom(B), tr_count_lexeme(B), tr_count_word(foreign, N), tr_count_adverb(B), tr_is(foreign, P, preposition),
    tr_phrase_rest(foreign, [N|Ws], NP, Rest), NP = np(_, Num, _, _, _), Num \== none, !,
    tr_after_phrase(yes, foreign, Rest, Seen, Cs).
tr_complements0(foreign, [w(B, BC), N|Ws], Seen, [obj(advp(w(B, BC), NP))|Cs]) :-
    atom(B), tr_count_lexeme(B), tr_count_word(foreign, N), tr_count_adverb(B),
    tr_phrase_rest(foreign, [N|Ws], NP, Rest), NP = np(_, Num, _, _, _), Num \== none, !,
    tr_after_phrase(yes, foreign, Rest, Seen, Cs).
tr_complements0(Side, [P|Ws], Seen, [pp(P, NP)|Cs]) :-
    tr_is(Side, P, preposition), \+ tr_determiner_before_noun(Side, P, Ws),
    (   Ws = [w(O, OC)|Rest], tr_object_pronoun_here(Side, Ws), \+ tr_relative_start(Side, Rest), \+ tr_ellipsis_start(Side, Ws),
        tr_oblique_pronoun(Side, O)
    ->  NP = pronoun(w(O, OC)), Phrase = no
    ;   tr_phrase_rest(Side, Ws, NP, Rest), \+ ( NP = pronoun(w(O2, _)), \+ tr_oblique_pronoun(Side, O2) )
    ->  Phrase = yes
    ;   Ws = [A|Rest], tr_is(Side, A, adverb),
        \+ ( A = w(AW, _), atom(AW), tr_focus_adverb(AW), Rest = [N2|_], tr_is(Side, N2, preposition) ), NP = adv(A)
    ->  Phrase = no
    ;   \+ tr_is(Side, P, adverb)
    ->  fail
    ), !,
    ( Phrase == yes, Rest = [w(_, _), w(_, _)|_], tr_noun_takes_inf(Side, P, NP), tr_governed_here(P) -> Ph = noun ; Ph = Phrase ),
    tr_after_phrase(Ph, Side, Rest, Seen, Cs).
%% (never a pronoun cut off the word before it, which is that word's: after
%% a finite verb `Correggimi' read as you correct me, the pronoun a free
%% object, where the joined pronoun is what says the verb is a command)
%% (nor one before a subjunctive, which is the clause's with its `che' left
%% out: `qui mi pare li si voglia murare' is one wanting to wall THEM in,
%% and read as the object of `pare' the pronoun left the clause it is in)
tr_complements0(Side, [w(W, C)|Ws], Seen, [opron(w(W, C))|Cs]) :-
    C \== enclitic,
    tr_object_pronoun_here(Side, [w(W, C)|Ws]), \+ tr_relative_start(Side, Ws), \+ tr_ellipsis_start(Side, [w(W, C)|Ws]),
    \+ ( Side == foreign, tr_cheless_here([w(W, C)|Ws]) ),
    \+ tr_pronoun_joined(Side, Ws), !,
    tr_complements(Side, Ws, Seen, Cs).
%% AN ADVERB THAT IS AN ADJECTIVE TOO, LAST IN THE CLAUSE AFTER ITS PREDICATE
%% ADJECTIVE, IS THE CLAUSE'S: `un joven cuyo nombre se hará familiar muy
%% pronto' is familiar very soon -- `pronto' is `prompt' as well, and read as
%% the noun `familiar', a relative, with `muy pronto' its adjective, it came
%% out `si farà familiare molto immediato'; with no `muy' the two were one
%% list, `familiare immediato'. Two predicate adjectives take a coordinator
%% or a comma between them, so the second word is the adverb it also is:
%% iadv/2 with its degree word, as `così poco' is, or adv/1
tr_complements0(foreign, [J|Ws], _, [adj([J]), Adv]) :-
    ( Ws = [_] ; Ws = [_, _] ), J = w(JW, _), atom(JW), tr_is(foreign, J, adjective), \+ tr_participle_here(foreign, JW, _),
    (   Ws = [A, B], A = w(AW, _), atom(AW), tr_degree_adverb(AW) -> Adv = iadv(A, B)
    ;   Ws = [B], Adv = adv(B)
    ),
    B = w(BW, _), atom(BW), \+ tr_degree_adverb(BW),
    tr_is(foreign, B, adjective), tr_plain_adverb(foreign, B), !.
%% AN ADVERB BEFORE A PREDICATE ADJECTIVE IS THE ADJECTIVE'S: `Esto es muy
%% gracioso' is very funny, and read as the clause's adverb it came out `This
%% is funny very' -- the intensifier a phrase carries (tr_intensify/3), which
%% `graciosísimo' is too once the lesson states it a superlative
%% -- but never a participle, which stands after its verb predicated of the
%% subject (the clause below): `juegan muy ordenados' is `giocano molto
%% ordinati', and taken as the adjective `orderly' Italian had no word for it
tr_complements0(Side, [A, J|Ws], _, [adj([int(A, J)|Js])|Cs]) :-
    tr_intensifier(Side, A, J), \+ ( J = w(JW, _), tr_participle_here(Side, JW, _) ),
    tr_phrase_words(Side, [J|Ws], [J|Js], Rest), tr_all_adjectives(Side, [J|Js]), !,
    tr_complements(Side, Rest, yes, Cs).
%% (an ARTICLE the lesson calls an adverb is no adverb here: `emplean unos
%% 980 trabajadores' is about 980 of them, tr_np/3's count, and read here it
%% was `employ 980 workers about' -- and `emplean unos trabajadores' came out
%% `employ about industrious')
%% A DENIAL BEFORE A VERB'S OWN FORM DENIES THAT VERB'S CLAUSE: `sono
%% d'accordo, ma non pensate che l'università si basi su questi soldi' is I
%% agree, but do not think -- read as one clause, `non' was an adverb of it
%% and `pensate' a participle said of its subject, `soy de acuerdo, pero no
%% pensado'. A word meaning `not' is no complement where a form of a verb
%% with a person follows it, or a command, and no adjective; the division
%% reads the clause it opens.
tr_complements0(foreign, [w(N, _), w(V, _)|_], _, _) :-
    atom(N), atom(V), tr_negation_word(N),
    ( tr_verb_form_word(V) -> true ; tr_solve(imperative_of(V, _)) ),
    \+ tr_is(foreign, w(V, lower), adjective), !, fail.
%% A DEGREE ADVERB BEFORE ANOTHER ADVERB IS THAT ADVERB'S: `è durata così
%% poco' is so little, and read as two adverbs of the clause `così' crossed as
%% `thus', `ha durado así poco'. It travels as iadv/2 and every writer puts the
%% two side by side, the first by its degree meaning (tr_intensifier_meaning/2)
tr_complements0(foreign, [A, B|Ws], Seen, [iadv(A, B)|Cs]) :-
    A = w(AW, _), atom(AW), B = w(BW, _), atom(BW), tr_degree_adverb(AW),
    tr_plain_adverb(foreign, B), \+ tr_degree_adverb(BW), !,
    tr_complements(foreign, Ws, Seen, Cs).
tr_complements0(Side, [A|Ws], Seen, [adv(A)|Cs]) :-
    tr_plain_adverb(Side, A), \+ tr_determiner_before_noun(Side, [A|Ws]),    % `tanto eroismo'
    \+ tr_ordinal_before_noun(Side, [A|Ws]), !,
    tr_complements(Side, Ws, Seen, Cs).
%% A PARTICIPLE STANDING ALONE AFTER THE VERB IS PREDICATED OF THE SUBJECT.
%% `l'operazione e considerata gia CONCLUSA' -- the passive says what was
%% done to it and the participle says what it now is, which is the copula's
%% own complement with the copula already spent on the passive. A bare
%% adjective was read as adj/1 by the last clause below and a participle is
%% no adjective of any lesson, so the sentence was refused.
%%
%% IT CARRIES THE LEXEME AND NOT THE FORM, exactly as 1.6.4's reduced
%% relative does, because the form has to agree on the way out -- with the
%% SUBJECT here, which is the gender the writer already holds, so
%% tr_participle_agreeing/3 needs nothing wrapped round it.
%% ... AND ONE IN QUOTATION MARKS KEEPS THEM: `sottolineo "osato"' stresses
%% the word, and pred/1 carries a lexeme and no case, so the marks were lost,
%% `subrayo osado'. predq(Lexeme, Case) is the same complement with the case
%% the source gave it.
tr_complements0(Side, [w(P, PC)|Ws], Seen, [Pred|Cs1]) :-
    \+ tr_ptc_noun_here(Side, P),
    tr_participle_here(Side, P, L), !,
    ( memberchk(PC, [qboth, qopen, qclose]) -> Pred = predq(L, PC) ; Pred = pred(L) ),
    tr_complements(Side, Ws, Seen, Cs),
    tr_participle_agr(Side, P, Ms),
    append(Ms, Cs, Cs1).
%% AN OBJECT COMPLEMENT IS WHAT THE VERB PREDICATES OF ITS OBJECT --
%% `definire illegale la decisione', `declarar ilegal la decision', `define
%% the decision illegal'. The two sides put it in OPPOSITE places, the
%% lesson's language before the object and English after it, so it travels
%% as oc(Object, Adjectives) and each writer puts it where its own language
%% wants it. The adjectives agree with the OBJECT and not with the subject.
%%
%% WHAT TELLS IT FROM AN ORDINARY OBJECT IS NOT THE SAME THING IN THE TWO
%% LANGUAGES, which is why there are two clauses rather than one. In English
%% it is the POSITION: an attributive adjective goes before its noun, so a
%% phrase-final one can only be predicative. In the lesson's language an
%% adjective before its noun is ordinary (`buono pane'), and what marks the
%% complement is the DETERMINER after the adjectives -- `illegale la
%% decisione' has one and `buono pane' has none. Both are read before the
%% ordinary phrase, because the ordinary reading takes either shape
%% otherwise: `the decision illegal' as `the illegal decision', and
%% `illegale la decisione' as one phrase with the article among its
%% adjectives.
%%
%% AND THE OBJECT MUST BE AN OBJECT, which is what `\+ tr_all_adjectives'
%% says: a bare adjective reads as a phrase of its own, so `is big and red'
%% offered `big' as the object and `and red' as the complement of it, and
%% the copula's own predicate came out as one.
%%
%% AND NEITHER IS GUARDED BY WHETHER AN OBJECT HAS BEEN READ, because the
%% sample's own sentence has one already: `manda un fax per definire
%% illegale la decisione' gives the main verb its object and the purpose
%% infinitive a complement of its own. The shape is the guard, and the
%% `Seen' flag belongs to the word the lesson puts before a person.
tr_complements0(english, Ws, _, [oc(NP, As)|Cs]) :-
    tr_phrase_words(english, Ws, PW, Rest), PW \== [],
    append(PW0, As, PW), PW0 \== [], As \== [],
    tr_all_adjectives(english, As), \+ tr_all_adjectives(english, PW0),
    tr_phrase_np(english, PW0, NP), !,
    tr_complements(english, Rest, yes, Cs).
%% ... AND A DATE AFTER THE ADJECTIVE IS WHEN, never what it is said of:
%% `esser risultato positivo il 17 maggio' is positive on the 17th of May, and
%% the day was the thing called positive (oc/2), so the sentence was refused
tr_complements0(foreign, Ws, _, [oc(NP, As)|Cs]) :-
    \+ tr_read_copula,                                  % the copula's adjective is its own predicate
    append(As, Rest0, Ws), As \== [], tr_all_adjectives(foreign, As),
    Rest0 = [D|_], tr_determiner(foreign, D, _, _),
    tr_phrase_words(foreign, Rest0, PW, Rest), PW \== [],
    tr_phrase_np(foreign, PW, NP), \+ tr_time_phrase(NP), \+ tr_date_phrase(NP), !,
    tr_complements(foreign, Rest, yes, Cs).
%% A BARE TIME PHRASE IS AN ADJUNCT AND NOT AN OBJECT. `Sabato Mladic
%% aveva spedito un fax' is `On Saturday Mladic had sent a fax' -- and none
%% of the three languages puts a preposition there, so the subject reader
%% took `Sabato Mladic' for one phrase, found `Mladic' was no adjective of
%% its noun, and refused the sentence. WHICH NOUNS ARE TIMES IS THE
%% LESSON'S, in the bare-class shape `"amigo" is a person.' already has, so
%% reason.pl did not move -- and being an adjunct is what lets the fronted
%% clause above take it.
%% A LONE WORD THAT IS AN ADVERB TOO IS THE ADVERB: `Ora è indispensabile
%% procedere' is now, and `ora' is also the hour the lesson calls a time --
%% read as a bare time phrase it came out `proceder a invertir hora'. A bare
%% singular time noun is an adjunct only where it names a day (`Sabato
%% Mladic'), which is no adverb.
%% ... NOR A TIME WITH ITS OWN INFINITIVE AFTER IT, which is a thing named:
%% `Fue entonces el momento de homenajear a dos "personajes singulares"' is
%% the moment to pay homage, and read as an adjunct the moment left `de
%% homenajear' nobody's to be, and the sentence was refused
tr_complements0(Side, Ws, Seen, [at_time(NP)|Cs]) :-
    tr_phrase_words(Side, Ws, PW, Rest0), PW \== [],
    \+ ( PW = [W1], tr_is(Side, W1, adverb) ),
    tr_phrase_np(Side, PW, NP0),
    (   tr_time_phrase(NP0) ; Side == foreign, tr_month_which(NP0)
    %% (... AND A DATE IS WHEN after a verb that takes no object, or after another complement: `la
    %% primera vuelta tendrá lugar el 4 de junio' takes place ON June 4, and read as the verb's
    %% object it was `will take place June 4'; `la Duma fijó el 4 de junio' sets the date itself)
    ;   Side == foreign, tr_date_phrase(NP0), tr_date_adjunct_here(Seen)
    ),
    \+ ( Side == foreign, Rest0 = [w(P, _)|R0], atom(P), tr_means_of(P), tr_starts_infinitive(foreign, R0) ),
    %% (... nor a time with a relative clause after its preposition, which the phrase's readers below
    %% take: `Ricordo il giorno in cui il cane dormiva' remembers the day, and `cui' was left unread)
    \+ ( Rest0 = [P2, w(R2, _)|_], tr_is(Side, P2, preposition), atom(R2), tr_relative_word(Side, R2) ), !,
    ( tr_time_part_after(Side, NP0, Rest0, NP1, Rest) -> NP = NP1 ; NP = NP0, Rest = Rest0 ),
    tr_complements(Side, Rest, Seen, Cs).
tr_complements0(Side, Ws, _, [obj(NP)]) :-
    tr_phrase_nrc(Side, Ws, NP), !.
%% (and an object with a participle after its comma, tr_phrase_aside/4)
tr_complements0(Side, Ws, _, [obj(NP)|Cs]) :-
    tr_phrase_aside(Side, Ws, NP, Rest), !,
    tr_complements(Side, Rest, yes, Cs).
%% ... and the phrase of an article, the word for `more' and a participle
%% with its agent (tr_np/3's rel/3 with pdeg/1): `..., la más esperada por
%% los aficionados' -- the phrase words end at `la', which the pronoun
%% reading then took. The longest agent first.
tr_complements0(foreign, [D, w(M, MC), w(P, PC)|Ws], Seen, [obj(NP)|Cs]) :-
    tr_determiner(foreign, D, _, article), tr_degree_word(M), tr_participle_here(foreign, P, _),
    length(Ws, N), between(0, N, I), K is N - I, length(AW, K), append(AW, Rest, Ws),
    tr_np(foreign, [D, w(M, MC), w(P, PC)|AW], NP), NP = rel(_, _, _), !,
    tr_complements(foreign, Rest, Seen, Cs).
%% AN ADJECTIVE LIST DOES NOT END ON ITS COORDINATOR: `el éxito, discreto
%% pero al fin y al cabo éxito, de esta Lucia' -- the phrase's words ran on
%% to `pero', and `but' came out as one of the adjectives. What follows the
%% coordinator is no adjective, so the coordinator joins the adjectives to
%% it, as cnj/1 joins two complements.
%% (the list's first word must be one, which is cheap to ask and is asked
%% first: asked of every word list, the phrase words cost Livata's sentences
%% 5 to 13 % more to read -- and the list is three words at least, an
%% adjective, the coordinator and what it joins them to, which is free to
%% ask and saves Tatoeba's 400 sentences 55 000 inferences)
tr_complements0(Side, Ws, _, [adj(As), cnj(K)|Cs]) :-
    Ws = [A1, _, _|_], tr_predicate_word(Side, A1),
    tr_phrase_words(Side, Ws, PW, Rest), Rest \== [],
    append(As, [K], PW), As \== [], K = w(_, _), tr_coord(Side, K),
    tr_all_adjectives(Side, As), \+ tr_verbless_thing(Side, As), !,
    tr_complements(Side, Rest, yes, Cs).
%% AN ADJECTIVE AND THE PREPOSITION IT TAKES BEFORE A PERFECT INFINITIVE:
%% `Colpevole di esser risultato positivo al controllo' is guilty OF HAVING
%% TESTED positive, `è sicuro di aver mangiato' sure of having eaten. The
%% perfect infinitive after a word that means `of' kept no preposition
%% (`di' begins an infinitive in Italian, so it is the verb's, as after
%% `ha detto di aver mangiato'), and `colpevole' is no verb: the adjective's
%% own `di' went, and English wrote `guilty to have tested', Spanish
%% `culpable haber dado'. With the adjectives before it, the group is the
%% preposition's, pinf(Word, perf(Lexeme, Pronouns)) as after a cause word
%% above. Asked as the clauses beside it are, by the first word being one
tr_complements0(foreign, Ws, Seen, [adj(As), pinf(w(P, PC), perf(F, Cls))|Cs]) :-
    Ws = [A1, _, _, _|_], tr_predicate_word(foreign, A1),
    append(As, [w(P, PC), w(V, VC)|More], Ws), As \== [], atom(P), atom(V), tr_solve(infinitive_of(V, _)),
    tr_means_of(P),
    tr_infinitive_group([w(V, VC)|More], F, perfect, Cls0, Rest),
    tr_all_adjectives(foreign, As), \+ tr_verbless_thing(foreign, As), !,
    tr_perf_rest(F, Rest, Seen, Cs),
    tr_undouble(Cls0, Cs, Cls).
%% AN ADJECTIVE AND THE CLAUSE SAID OF IT: `Es difícil que el perro coma',
%% `Hoy es más difícil que pase algo así' -- difficult THAT it happens. The
%% phrase's words ran on through `que' as a relative clause on `difícil',
%% and Italian wrote the same words from that reading; the adjectives are
%% the predicate, and the clause after them the `that' clause it is. It is
%% tried before the phrase reader below, which is what keeps the relative
%% reading from being the one taken -- a guard in tr_np/3 refusing a
%% relative clause on bare adjectives bought nothing beside it, measured,
%% and cost 0.7 million inferences in one sentence of the controls.
%% (and nothing is committed to until the clause reads: `más grande que el
%% perro' is the comparison the reader below finds)
tr_complements0(foreign, Ws, Seen, [adj(As)|Cs]) :-
    Ws = [A1, _, _|_], tr_predicate_word(foreign, A1),
    append(As, [W|More], Ws), As \== [], tr_that_here(foreign, W), More \== [],
    tr_all_adjectives(foreign, As), \+ tr_verbless_thing(foreign, As),
    tr_complements0(foreign, [W|More], Seen, Cs), Cs = [that(_)|_], !.
%% ... AND THE QUESTION SAID OF IT: `appare inspiegabile quali possano essere le
%% ragioni di incostituzionalità' -- inexplicable WHICH the reasons may be.
%% The phrase's words ran on through `quali' as a relative clause on
%% `inspiegabile', and Spanish wrote `que pueden ser', the relative word
tr_complements0(foreign, Ws, Seen, [adj(As)|Cs]) :-
    Ws = [A1, _, _|_], tr_predicate_word(foreign, A1),
    append(As, [w(W, WC)|More], Ws), As \== [], atom(W), tr_which_form(W, _), More \== [],
    tr_all_adjectives(foreign, As), \+ tr_verbless_thing(foreign, As),
    tr_complements0(foreign, [w(W, WC)|More], Seen, Cs), Cs = [wh(_, _)|_], !.
%% ... AND THE CLAUSE IT IS COMPARED WITH: `fosse più ampia di quanto il
%% genovese sosteneva' -- the phrase's words ran on through the word for
%% `than what', which is no preposition to end them, and nothing read
%% (cmpc/2)
tr_complements0(foreign, Ws, Seen, [adj(As)|Cs]) :-
    Ws = [A1, _, _|_], tr_predicate_word(foreign, A1),
    append(As, [w(W, WC)|More], Ws), As \== [], atom(W), tr_solve(mean(W, 'than what')), More \== [],
    tr_all_adjectives(foreign, As), \+ tr_verbless_thing(foreign, As),
    tr_complements0(foreign, [w(W, WC)|More], Seen, Cs), Cs = [cmpc(_, _)|_], !.
%% A CLAUSE WITH ITS `CHE' LEFT OUT (the last clause below) COMES BEFORE THE
%% PHRASE WHERE ITS VERB IS NO DETERMINER: `"La Repubblica" ci sembrava fosse
%% su questa posizione' -- it seemed to us it was. Read as a phrase first,
%% `fosse' was the plural of `fossa', pits, a noun with no article; a
%% determiner opens the phrase it opens, and `mi sembra una buona idea' is a
%% good idea, never that it unites one.
tr_complements0(foreign, Ws, _, [that(S)]) :-
    Ws = [w(V, _)|_], \+ tr_determiner(foreign, w(V, lower), _, _),
    tr_cheless_here(Ws),
    tr_that_clause(foreign, Ws, S), !.
tr_complements0(Side, Ws, _, [C|Cs]) :-
    tr_phrase_words(Side, Ws, PW, Rest), PW \== [],
    (   tr_all_adjectives(Side, PW), \+ tr_verbless_thing(Side, PW) -> C = adj(PW)
    ;   tr_phrase_np(Side, PW, NP), C = obj(NP)
    ),
    tr_complements(Side, Rest, yes, Cs).
%% A CLAUSE WITH ITS `CHE' LEFT OUT: `la "Bastiglia" non mi risulta sia stata
%% mai occupata', `qui mi pare li si voglia murare'. Italian leaves the word
%% out before a subjunctive, and the subjunctive is what says a clause begins:
%% the first verb after the denial and the clitics is a form the lesson calls
%% one. It is the verb's `that' clause, that/1, and every writer puts the
%% word back, `no me resulta que ...'. Tried last, when nothing read the
%% words as a phrase.
tr_complements0(foreign, Ws, _, [that(S)]) :-
    tr_cheless_here(Ws),
    tr_that_clause(foreign, Ws, S), !.
%% ... AND AN INDICATIVE ONE WHOSE SUBJECT STANDS FIRST, after a verb that
%% takes the clause and where nothing else read: `y agregó la "única
%% preocupación" del sector renovador es decapitarle' -- the source left the
%% word out, the subject and its verb say a clause begins, and read as the
%% verb's object the preoccupation had a verb after it and nothing read. The
%% word is put back by every writer, `aggiunse che ...'. Only STRAIGHT AFTER
%% the verb: `è sempre risultato spento, quindi l'uomo aveva lanciato
%% l'allarme' is two clauses joined by `quindi', and read as the clause of
%% `risulta' after an adjective and an adverb it came out `entonces que el
%% hombre había lanzado'.
tr_complements0(foreign, Ws, _, [that(S)]) :-
    tr_global('$tr_read_group', G), atom(G), G \== none, tr_solve(take(G, clause)),
    tr_subject_first(Ws), \+ tr_subjunctive_next(Ws),
    tr_global('$tr_piece', P), append(_, [w(V, _)|Ws], P), once(tr_form(V, G, _, _, _)),
    tr_that_clause(foreign, Ws, S), S = s(_, Su, _, _), Su \= null(_, _), !.
%% (the phrase with no determiner, a bracket after it included: `hasta
%% anuncios (Telefunken, La Lechera)')
tr_bare_head(np(none, _, _, _, _)).
tr_bare_head(app(NP, _, _)) :- tr_bare_head(NP).
tr_who_gap(s(A, null(third, N), G, Cs), s(A, gap(third, N), G, Cs)) :- !.
tr_who_gap(S, S).
%% (the comment of `as' below: what stands before its verb, and the words before the next comma)
tr_like_pre(w(_, upper)) :- !.
tr_like_pre(w(X, _)) :- atom(X), ( tr_clitic(none, X) -> true ; tr_is(foreign, w(X, lower), pronoun) ), !.
%% A WORD THAT IS A NOUN AS WELL AS A PARTICIPLE IS THE NOUN AFTER A VERB OF SUFFERING, RECEIVING OR CAUSING:
%% `sufrieron heridas al manipular el material' suffered injuries, and read as the participle said of the subject
%% (a participle standing alone after the verb, above) it was `soffrirono feriti' and `suffered injured'. Such a verb
%% takes what it suffers or causes and says nothing of its subject
tr_ptc_noun_here(foreign, P) :-
    atom(P), tr_global('$tr_read_group', G), atom(G), G \== none,
    once(( tr_solve(mean(G, E)), memberchk(E, [suffers, receives, causes, inflicts, sustains, shows, presents, treats, heals, cures]) )),
    tr_is(foreign, w(P, lower), noun), !.
tr_like_head([], _, []) :- !.
tr_like_head([comma|_], _, []) :- !.
tr_like_head(_, 0, []) :- !.
tr_like_head([X|Xs], N, [X|Ys]) :- N1 is N - 1, tr_like_head(Xs, N1, Ys).
tr_how_much_word(W) :- atom(W), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, 'how much')), !.

%% A SECOND `QUE' AFTER A COORDINATOR CAN BE A RELATIVE WORD ON THE PHRASE THAT ENDS THE FIRST CLAUSE: `es que la
%% eficacia ha llegado sin sus estrellas, un ataque con el que sueñan los interistas y que han truncado
%% las constantes lesiones' -- the injuries have truncated the attack, and the second clause, taken for a
%% clause of `that' of its own, had nobody for its subject (`and that they have truncated the constant
%% injuries'). The first clause ends in a phrase with a relative clause and the second has no subject of
%% its own: the whole is read as one clause, whose phrase takes the second relative clause (nrc/3)
tr_second_relative(foreign, s(_, _, _, Cs1), s(_, null(_, _), _, _), Ws) :-
    last(Cs1, Last), tr_ends_in_rc(Last),
    tr_that_clause(foreign, Ws, s(_, _, _, Cs)),
    last(Cs, L2), tr_carries_ro(L2).
tr_ends_in_rc(obj(NP)) :- tr_rc_phrase(NP).
tr_ends_in_rc(pp(_, NP)) :- tr_rc_phrase(NP).
tr_rc_phrase(rc(_, _, _)).
tr_rc_phrase(nrc(_, _, _)).
tr_carries_ro(obj(NP)) :- tr_has_ro(NP).
tr_carries_ro(pp(_, NP)) :- tr_has_ro(NP).
tr_has_ro(nrc(_, ro(_, _), _)).

%% the second person of a clause of `that' that its verb's form says is the subjunctive's third too
tr_second_is_subjunctive(Words, Before) :-
    append(Before, [w(VW, _)|_], Words), atom(VW),
    tr_solve(second(VW)), tr_solve(subjunctive_of(VW, _)), \+ tr_holds(past(VW)), !.

%% the clause after `che', read as a statement -- and a comma STRAIGHT AFTER
%% the word opens an insertion in front of it: `senza rendersi conto che,
%% come il loro predecessore, non importa loro null'altro che ...' is like
%% their predecessor, nothing else matters to them. Read with the commas
%% out, `loro predecessore' was a subject and `come ... loro' an adjunct,
%% `de que predecesor no les importa ... como el ellos'. It is the clause's
%% front, and it travels as frc/1, which every writer puts back with a comma
%% before it as well as after.
%% (read as a whole statement is, whose front may end at a comma -- the
%% nested reader's front has none -- and the reader's globals put back)
tr_that_clause(Side, [comma|Ws], S) :- !,
    Ws = [_|_],
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    (   tr_read(Side, statement, Ws, S0) -> nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ),
    S0 = s(A, Su, G, Cs0), append(Pre, [fr(X)|Post], Cs0), \+ memberchk(fr(_), Pre), !,
    append(Pre, [frc(X)|Post], Cs), S = s(A, Su, G, Cs).
%% ... and who said so between dashes right after the word: `Era che - come
%% ha mostrato bene la trasmissione di Angela - i suoi avversari ...' -- the
%% rest read as a sentence is, its commas kept, and the comment in front of
%% its first clause (frn/1)
tr_that_clause(Side, [w(K, perd)|Ws], S) :- !,
    Ws = [_|_],
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    (   tr_read(Side, statement, Ws, S0) -> nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ),
    tr_prefront(frn(perd(K)), S0, S).
tr_that_clause(Side, Ws, S) :-
    tr_global('$tr_in_that', T0), nb_setval('$tr_in_that', yes),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    (   tr_read_nested(Side, Ws, none, S1) -> nb_setval('$tr_in_that', T0), tr_subjunctive_reading(G0, A0, S1, S)
    ;   nb_setval('$tr_in_that', T0), fail
    ).
%% A CLAUSE OF `THAT' IS READ IN THE SUBJUNCTIVE AFTER A VERB THAT TAKES IT, or
%% after a command: `Quiero que vengas' wants you to come, and `venga' is also
%% the third person of the verb that avenges -- the lesson names a verb by its
%% third person present, so the word is that verb's own lexeme, which the
%% reader takes first (tr_form_nt/5), and it was `quiero que vendiques'. The
%% lesson says which verbs take the subjunctive (`"quiere" takes the
%% subjunctive.'), and the word the lesson states as a verb's subjunctive
%% (`"venga" is the subjunctive of "viene".') is that verb's there
tr_subjunctive_reading(G, A, s(As, Su, g(L, T, Asp, Neg), Cs), s(As, Su, g(L2, T, Asp, Neg), Cs)) :-
    ( A == imperative ; atom(G), tr_solve(take(G, subjunctive)) ),
    atom(L), tr_solve(subjunctive_of(L, L2)), L2 \== L, \+ tr_holds(past(L)), !.
tr_subjunctive_reading(_, _, S, S).
tr_prefront(X, s(A, Su, G, Cs), s(A, Su, G, [X|Cs])) :- !.
tr_prefront(X, join(C, S1, S2), join(C, T1, S2)) :- tr_prefront(X, S1, T1).
%% (THE WORD THAT ASKS WITH NO PHRASE, BEFORE AN INFINITIVE, IS `what': `quisiera saber qué hacer' is what to do --
%% the lesson's `qué' is `which' and `what', and with no phrase after it to choose between them the infinitive's
%% question was `which to make', `quale fare')
tr_what_to(W, which(_), s(_, none, g(_, _, infinitive, _), _), what) :- tr_solve(mean(W, what)), !.
tr_what_to(_, Q, _, Q).
%% the lesson's word for `which', by its lexeme, and the number it is in
tr_which_form(W, N) :- atom(W), tr_lexeme(foreign, W, L, N), tr_solve(mean(L, which)), !.
%% ... and the word that asks with a phrase: that one, with any phrase, or a
%% word the lesson gives `what' with a noun or an adjective at the head of
%% it -- `che colpa ha?' is which fault, as the word before a preposition
%% already was (`in che razza di mondo'); not `cosa le posso dire?', whose
%% `le' is the clause's own. Stating `which' for `che' too gave every `che'
%% of a sentence a second meaning to try, and the controls rose 11 %: 2 to 4
%% times a sentence with two of them
tr_which_asks(Q, [W1|_]) :- tr_which_form(Q, _), fo_phrase_word(W1), !.
tr_which_asks(Q, [W1|_]) :- atom(Q), tr_solve(mean(Q, what)), ( tr_is(foreign, W1, noun) ; tr_is(foreign, W1, adjective) ), !.
%% the phrase it asks with, longest first, and the clause after it; or the
%% pronoun and the clause after it. The clause is read with the question
%% word standing where its subject, object or adjunct would be
tr_which_clause(Ws, N, C, Q, S) :-
    (   tr_which_split(Ws, NPWs, Rest, PN), tr_wh_clause(Rest, PN, S), Q = which(NPWs, C)
    ;   tr_wh_clause(Ws, N, S), Q = which(N)
    ), !.
tr_which_split(Ws, NPWs, Rest, N) :-
    length(Ws, Len), Max is Len - 1, Max >= 1, between(1, Max, I), K is Max - I + 1,
    length(NPWs, K), append(NPWs, Rest, Ws),
    tr_which_phrase(foreign, NPWs, NP), tr_which_phrase_number(NP, N).
tr_which_phrase_number(with(NP, _), N) :- !, tr_which_phrase_number(NP, N).
tr_which_phrase_number(np(_, _, _, _, N), N) :- atom(N), !.
tr_which_phrase_number(_, singular).
%% ... a subject that is the gap when the verb agrees with what is asked for
%% (`quali possano essere le ragioni'), and otherwise the clause read whole,
%% its subject after its verb when it has none before it (`quali aspetti ha
%% scelto il capo')
tr_wh_clause(Ws, N, S) :-
    (   tr_read_nested(foreign, Ws, subject(rel), S1), S1 = s(_, asked(Q0), G, Comps),
        ( Q0 = rel(_, GN) -> GN == N ; true )
    ->  ( Q0 = rel(P0, GN0) -> Gap = gap(P0, GN0) ; Gap = gap ),
        S = s(none, Gap, G, Comps)
    ;   tr_read_nested(foreign, Ws, rel, S0),
        ( tr_rel_subject_after(foreign, S0, S1) -> tr_unrel(S1, S) ; tr_unrel(S0, S) )
    ).
%% (a phrase of four words at most after its determiner, to the end or to its own word for `where')
tr_where_tail(Rest) :- length(Rest, L), L =< 4, !.
tr_where_tail(Rest) :- append(PW, [w(W2, _)|_], Rest), length(PW, L), L =< 4, atom(W2), tr_indirect_word(foreign, W2, where), !.
%% the group being read is the copula's
tr_copula_group :- tr_global('$tr_read_group', GL), atom(GL), GL \== none, tr_copula_lexeme(GL), !.
tr_upon_head(foreign, [w(P, _), w(D, _), w(V, _)|_]) :-
    tr_solve(begin(M, moment)), tr_solve(contraction_of(M, J)), atomic_list_concat([P, D], ' ', J),
    tr_solve(infinitive_of(V, _)), !.
tr_upon_head(english, [w(on, _), w(G, _)|_]) :- en_gerund(G, _), !.
%% ... UNLESS NOTHING READS TO ITS FIRST COMMA, which a clause of `that' with an
%% apposition in it does not: `fue más lejos al precisar que esa actitud, "que
%% no tuvo el PP en su día", es la que les diferencia' -- the first comma is
%% the apposition's, `que esa actitud' no clause, and the words go whole
%% ... AND A RELATIVE CLAUSE BETWEEN ITS COMMAS AFTER THAT IS THE LAST PHRASE'S: `Al enterarse de la acción del Comando
%% Ciudadano Justiciero, que secuestró la placa para restaurarla, Oliveras recordó ...' is the commando that kidnapped it,
%% and with the front ended at the comma the clause was one of `that' standing alone, with nobody named
tr_upon_rest(Side, Ws, Seen, Cs, More) :-
    append(Ws1, [comma, w(R, RC)|Ws3], Ws), \+ memberchk(comma, Ws1), Ws1 \== [], atom(R),
    tr_relative_word(Side, R),
    ( append(RW, [comma|Ws4], Ws3), \+ memberchk(comma, RW) -> true ; RW = Ws3, Ws4 = [] ),
    tr_complements(Side, Ws1, Cs1), append(CPre, [CL], Cs1),
    tr_relative_clause(Side, [w(R, RC)|RW], Role, RS),
    tr_nrc_on(CL, Role, RS, CL1), !,
    append(CPre, [CL1], Cs),
    ( Ws4 == [] -> More = [] ; tr_complements(Side, [comma|Ws4], Seen, More) ).
tr_upon_rest(Side, Ws, Seen, Cs, More) :-
    (   append(Ws1, [comma|Ws2], Ws), \+ memberchk(comma, Ws1), Ws1 \== [],
        tr_complements(Side, Ws1, Cs1), tr_complements(Side, [comma|Ws2], Seen, More1)
    ->  Cs = Cs1, More = More1
    ;   tr_complements(Side, Ws, Cs), More = []
    ).
tr_verb_clause([C|Cs]) :- ( C = that(_) -> true ; \+ tr_verbal_comp(C), C \= obj(_), tr_verb_clause(Cs) ).
%% the class the word before a person marks: the phrase's, or a list's whose
%% first item is of it -- `teniendo por testigos directos a 62.561
%% espectadores y millones y millones de personas' has the spectators and
%% the millions for witnesses, and the word stands before the first. Asked
%% of both items, the millions were no persons, and the list was a phrase of
%% `to': `avendo per testimoni a 62.561 spettatori'
tr_marked_class(NP, Class) :- tr_of_class(NP, Class), !.
tr_marked_class(co(_, A, _), Class) :- tr_marked_class(A, Class).
%% ... and a group of persons after a verb of warning, alerting or informing, which is done to persons: `debían haber
%% avisado a la población' should have warned the population, and read as a phrase of `to' English wrote `warned to the
%% population'
tr_warned_group(person, NP, G0) :-
    atom(G0), tr_of_class(NP, group), tr_solve(mean(G0, E)), en_person_passive(E), !.
%% (and after the infinitive of one: `debían haber avisado a la población', read with the modal's group)
tr_warned_infinitive([I, pp(W, NP)|Cs], [I, obj(NP)|Cs]) :-
    ( I = inf(L) ; I = infx(L, _, []) ), W = w(P, _), tr_marker_word(P, person), tr_warned_group(person, NP, L), !.
tr_warned_infinitive(Cs, Cs).
%% ... AND A NAME AFTER ITS ARTICLE IS A PERSON FOR IT, READ, RIGHT AFTER THE
%% VERB'S OWN WORD: `temas que benefician al Govern' benefit the Govern, and
%% read as a phrase of `to' the word before a person stayed, `avvantaggiano al
%% Govern'. Only read, and only here: a name with its article is as often a
%% paper or a gallery as somebody, and written back it took the person's `a'
%% (`ve a la Tate Gallery'). Asked of every phrase (tr_of_class/2) the reading
%% of `aseguró, advirtiendo que es un rival superior al Gandia' went through
%% this branch for the Gandia as the object of `aseguró', 0.8 million
%% inferences of the football report's twentieth -- so the word before the
%% marker is the group's, found in the piece -- and in any of its forms where
%% the word for `to' and an infinitive follow the name, which is what the name
%% is moved to do (`la coalición radical animó al PNV a que acepte ...'
%% encouraged the PNV, and the past was asked as a lexeme, which a verb's form
%% is not: `encouraged to the PNV'; elsewhere a form keeps its phrase of `to',
%% `las descalificaciones que ETA lanzó al PNV')
tr_named_object(np(_, _, _, named(_, _), _), Class, G, P, PW) :-
    ( Class == name ; Class == person ),
    atom(G), G \== none, \+ tr_saying_verb(G),
    tr_global('$tr_piece', Piece),
    append(_, [w(V, _), w(P, _)|T], Piece), append(PW, After, T),
    (   tr_lexeme(foreign, V, G, _) -> true
    ;   After = [w(A, _), w(I, _)|_], atom(A), atom(I), atom(V), tr_solve(infinitive_of(I, _)), tr_means_to(A),
        tr_form(V, G, _, _, _)
    ), !.

%% the person's words -- AND AFTER A VERB THE LESSON SAYS TAKES THE CLAUSE,
%% THE PERSON ALONE FIRST: `Redondo declaró a Europa Press que la "parálisis"
%% institucional hará ...' said it to the agency, and the phrase reader,
%% which reads a phrase and its relative clause to the end first
%% (tr_phrase_words/4), made the clause the agency's -- the agency that the
%% paralysis will make necessary, `que' the object of `hará' -- and Italian
%% wrote it in the same words, `dichiarò Europa Press che ...'. `"declara"
%% takes the clause.' is the lesson's, in the shape `"risulta" takes the
%% clause.' already has, and a clause whose subject stands first is then the
%% verb's, as a `that' clause's is.
%% ... WITH THE WORD THE VERB PUTS BEFORE ITS CLAUSE AFTER THE PERSON, AND A
%% CLAUSE WHOSE SUBJECT IS LEFT OUT: `El líder del PNV previno a los suyos de
%% que no deben albergar "miedo" alguno' warned his own that they must not --
%% `de que' after the person (`"previene" takes "de" before the clause.'), and
%% a clause that opens on its denial and its verb, the subject being the ones
%% warned. Read on, `a los suyos' was the object and the clause a relative
%% clause on it, the ones who must not, and the sentence was refused
tr_person_words(Ws, PW, Rest) :-
    tr_global('$tr_read_group', G), atom(G), G \== none, ( tr_solve(take(G, clause)) ; tr_saying_verb(G) ),
    tr_phrase_words0(foreign, Ws, PW, Rest), PW \== [],
    (   Rest = [T|After], tr_that_here(foreign, T)
    ;   Rest = [w(P, _), T|After], atom(P), tr_solve(take_before(G, P, clause)), tr_that_here(foreign, T)
    ),
    tr_clause_after_person(After).
tr_person_words(Ws, PW, Rest) :- tr_phrase_words(foreign, Ws, PW, Rest), PW \== [].
tr_clause_after_person(After) :- tr_subject_first(After), !.
tr_clause_after_person([w(N, _), w(V, _)|_]) :- atom(N), tr_negation_word(N), atom(V), tr_verb_form_word(V), !.
%% (... and its denial and then the pronouns of its verb: `han recriminado a las autoridades que no se les hubiera
%% alertado' -- the clause was the authorities' relative clause)
tr_clause_after_person([w(N, _)|Ws]) :-
    atom(N), tr_negation_word(N),
    append(Cls, [w(V, _)|Ws2], Ws), Cls = [_|_], length(Cls, NC), NC =< 2,
    forall(member(C, Cls), ( C = w(CW, _), atom(CW), tr_clitic(unsaid(none), CW) )),
    atom(V), tr_group_at(foreign, [w(V, lower)|Ws2], _, _), !.
tr_clause_after_person([w(V, _)|_]) :- atom(V), tr_verb_form_word(V), \+ tr_is(foreign, w(V, lower), noun).
%% ... AND ONE THAT OPENS ON A PRONOUN OF ITS VERB: `advirtió a sus antiguos
%% socios de que SE convertirán en un "lastre"' -- the clitic and then a verb
tr_clause_after_person(After) :- tr_clitic_verb_start(After), !.
%% ... AND ONE THAT OPENS ON A CONJUNCTION OF ITS OWN: `advirtió a sus socios de
%% que SI siguen por la senda, dejarán de ser un partido' -- a relative clause
%% never begins with `if', `when' or `although'
tr_clause_after_person([w(C, _)|_]) :- atom(C), tr_solve(conjunction(C)), !.
%% ... AND ONE THAT SETS A PHRASE IN FRONT OF ITS SUBJECT: `avisó a Ibarretxe
%% de que a su Gobierno el tiempo se le acaba' -- the phrase of `a', and then
%% the subject
tr_clause_after_person([P|Ws]) :-
    P = w(PW, _), atom(PW), tr_is(foreign, P, preposition),
    tr_phrase_words0(foreign, Ws, PWs, Rest), PWs \== [], Rest = [_|_], tr_subject_first(Rest), !.
tr_takes_before_person(P) :-
    tr_global('$tr_read_group', G), atom(G), G \== none, tr_solve(take_before(G, P, person)), !.
%% ... and in the clause of WHO SAID SO the person is the one it was said
%% to: what was said is the sentence the comment stands in -- `según
%% manifestó Redondo Terreros a Europa Press' (tr_said_to/1)
tr_takes_before_person(_) :- tr_global('$tr_said_to', yes), !.
%% (not an object set off by a comma straight after the person, which is the
%% person again: `homenajear a dos "personajes ...", Jorge Arandes y Joan
%% Viñas, que ...' honours the two, and with the names counted as a second
%% object the two were who it was done to, `onorare a due')
tr_verb_object([sep, obj(_)|Cs]) :- !, tr_verb_object(Cs).
%% ... A RANGE OF A QUANTITY IS AN OBJECT: `reclamó ayer a Jordi Pujol entre
%% 5.000 y 6.000 millones de pesetas' asked Pujol FOR them, and the range, a
%% phrase of `among', left the person the object: `reclamò ieri Pujol tra
%% 5.000 e 6.000 milioni'
tr_verb_object([C|Cs]) :- ( C = obj(_) -> true ; tr_range_pp(C) -> true ; \+ tr_verbal_comp(C), tr_verb_object(Cs) ).
tr_range_pp(pp(_, np(_, nums(_, _, _), _, _, _))).
tr_verbal_comp(inf(_)).
tr_verbal_comp(infx(_, _, _)).
tr_verbal_comp(pinf(_, _)).
tr_verbal_comp(ainf(_, _)).
tr_verbal_comp(purpose(_)).
tr_verbal_comp(npurpose(_)).
tr_verbal_comp(purp(_)).
tr_verbal_comp(qm(_, C)) :- tr_verbal_comp(C).        % (a quoted one: `acusa a María de "hacer trampa"')

%% A PRONOUN THAT ONLY DOUBLES `todo' IS NOT A SECOND OBJECT. Spanish says
%% `jugárselo todo', `se lo comió todo' -- the pronoun and the word for
%% everything are one object said twice -- and Italian says it once,
%% `giocarsi tutto'. Where the complements have the word for everything, a
%% pronoun joined to the infinitive that is no reflexive goes.
tr_undouble(Cls0, Cs, Cls) :-
    member(C, Cs), ( C = opron(w(T, _)) ; C = obj(pronoun(w(T, _))) ),
    tr_lexeme(foreign, T, L, _), tr_solve(mean(L, everything)), !,
    exclude(tr_plain_enclitic, Cls0, Cls).
tr_undouble(Cls, _, Cls).
tr_plain_enclitic(Cl) :- \+ tr_reflexive_word(Cl).
tr_infinitive_mark(P) :- tr_lexeme(foreign, P, L, _), tr_solve(begin(L, infinitive)), !.
tr_open_mark(C) :- ( C == qopen ; C == qboth ), !.

%% WHAT FOLLOWS A PREPOSITION AND ITS INFINITIVE IS THE INFINITIVE'S --
%% and UNDER THE COPULA it is read with no object counted, so a person
%% marked with the word before a person is the infinitive's object:
%% `homenajear a dos personajes' after `Fue entonces el momento de' honours
%% the two, and with the moment counted as an object the word was `to',
%% `onorare a due caratteri'. Only there: the copula takes nobody `to'
%% whom, where a verb can -- `enviar órdenes de comparecer al director' sends
%% them TO the director, and read as the infinitive's object he was who
%% appeared, `ordini di figurare il direttore'. And after the copula that
%% matters: `es partidario de continuar con las
%% reformas y anclar a su país en Occidente SOLICITANDO el ingreso en la
%% OTAN' -- the gerund says how the anchoring is done, and read as the
%% copula's it was refused, because the copula takes no gerund. The rest is
%% read with the infinitive as the group being read.
%% ... AND AN INFINITIVE JOINED TO IT IS UNDER THE SAME PREPOSITION: `es
%% partidario de continuar con las reformas Y ANCLAR a su país' -- the copula
%% takes no bare infinitive, so the second is what `de' governs too, and
%% English wrote `of continuing ... and to anchor'. It travels as pinf/2 with
%% the first one's preposition.
tr_complements_after_inf(Prep, F, Ws, Seen, Cs) :-
    tr_copula_group, atom(F), !,
    tr_global('$tr_read_group', G0), nb_setval('$tr_read_group', F),
    (   tr_complements(foreign, Ws, Seen, Cs0) -> nb_setval('$tr_read_group', G0)
    ;   nb_setval('$tr_read_group', G0), fail
    ),
    tr_share_prep(Prep, Cs0, Cs).
%% (and after an infinitive the word before a clause is the infinitive's:
%% `sin darse cuenta de que ...')
tr_complements_after_inf(_, F, [w(P, _), W|Ws], Seen, Cs) :-
    atom(F), tr_solve(take_before(F, P, clause)), tr_that_here(foreign, W), Ws \== [],
    tr_complements(foreign, [W|Ws], Seen, Cs), Cs = [that(_)|_], !.
%% ... and the word an infinitive puts before its question: `sin preguntar
%% por quién tiene delante' is without asking WHO he has in front of him --
%% `"pregunta" takes "por" before the question.' Read as a phrase of `por',
%% the question word was a person the asking was for and the clause after
%% it had no reading; Italian's `chiedere' takes the question bare, so the
%% preposition is the reader's and no writer puts it back
tr_complements_after_inf(_, F, [w(P, _), W|Ws], _, [wh(E, S)]) :-
    atom(F), tr_solve(take_before(F, P, question)), Ws \== [],
    tr_question_word(W, E),
    tr_read_nested(foreign, Ws, none, S0), ( E == who -> tr_who_gap(S0, S) ; S = S0 ), !.
%% ... and an infinitive that takes a question takes it here: `si tratta di
%% stabilire se ... o se ...' is to establish whether one thing is so or
%% another -- and two such questions joined are two, as two `che' clauses are
tr_complements_after_inf(_, F, [w(W, _)|Ws], _, Cs) :-
    atom(F), tr_if_word(W), tr_solve(take(F, question)), Ws \== [],
    tr_indirect_questions(Ws, Cs), !.
tr_complements_after_inf(_, _, Ws, Seen, Cs) :- tr_complements(foreign, Ws, Seen, Cs).
%% ... and the word an infinitive puts before its question is read after the
%% infinitive of `a' and the bare one too: `si è limitata a macerarsi SU CHI
%% dovesse vendere' (`"si macera" takes "su" before the question.')
tr_question_after_inf(F, [w(P, _), W|Ws], _, [wh(E, S)]) :-
    atom(F), tr_solve(take_before(F, P, question)), Ws \== [],
    tr_question_word(W, E),
    tr_read_nested(foreign, Ws, none, S0), ( E == who -> tr_who_gap(S0, S) ; S = S0 ), !.
tr_question_after_inf(_, Ws, Seen, Cs) :- tr_complements(foreign, Ws, Seen, Cs).

%% (the infinitive and what it takes, read under the infinitive: the first word one, known to
%% the lesson, and the complements beginning with it)
tr_whether_infinitive([w(V, VC)|Ws], Cs) :-
    atom(V), tr_solve(infinitive_of(V, F)), tr_known(foreign, F),
    tr_global('$tr_read_group', G0), tr_global('$tr_read_aspect', A0),
    nb_setval('$tr_read_group', F), nb_setval('$tr_read_aspect', simple),
    (   tr_complements(foreign, [w(V, VC)|Ws], Cs), Cs = [inf(_)|_]
    ->  nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0)
    ;   nb_setval('$tr_read_group', G0), nb_setval('$tr_read_aspect', A0), fail
    ).
tr_indirect_questions(Ws, [wh(whether, S1), cnj(C), wh(whether, S2)]) :-
    append(W1, [C, w(W2, _)|Ws2], Ws), W1 \== [], Ws2 \== [], C = w(_, _), tr_coord(foreign, C), tr_if_word(W2),
    tr_read_nested(foreign, W1, none, S1), tr_read_nested(foreign, Ws2, none, S2), !.
tr_indirect_questions(Ws, [wh(whether, S)]) :- tr_read_nested(foreign, Ws, none, S).

tr_share_prep(Prep, Cs0, Cs) :-
    Prep \== none, append(Pre, [cnj(K), inf(F2)|Post], Cs0),
    \+ memberchk(cnj(_), Pre), \+ memberchk(inf(_), Pre), !,
    append(Pre, [cnj(K), pinf(Prep, F2)|Post], Cs).
tr_share_prep(_, Cs, Cs).
tr_no_word(N) :- tr_lexeme(foreign, N, L, _), tr_solve(mean(L, no)), tr_class_of(L, adverb), !.
tr_lead_adverbs(Side, [A|Ws0], [A|As], Ws) :-
    Ws0 = [_|_], A = w(_, _), tr_plain_adverb(Side, A), \+ tr_is(Side, A, preposition), !,
    tr_lead_adverbs(Side, Ws0, As, Ws).
tr_lead_adverbs(_, Ws, [], Ws).
tr_advp([], NP, NP).
tr_advp([A|As], NP0, advp(A, NP)) :- tr_advp(As, NP0, NP).
%% ... NOR A TIME: `verrà istituzionalizzato con la laurea in astronautica già
%% dal prossimo anno accademico' is from next academic year, and read as the
%% agent the year did it, `ya por el próximo año académico'
tr_time_after(Side, Ws) :-
    ( Side == foreign -> tr_time_near(Ws) ; true ),
    tr_phrase_words(Side, Ws, PW, _), PW \== [], tr_phrase_np(Side, PW, NP), tr_time_or_month(NP), !.
%% (a noun the lesson calls a time or a month before the first preposition
%% or comma is asked first, where the phrase's noun stands, and the phrase is
%% read only then: `dai carabinieri, è stata trasportata ...' read its phrase
%% for nothing, a million inferences in Livata's third sentence)
tr_time_near([W|Ws]) :-
    W = w(X, _), atom(X), \+ tr_is(foreign, W, preposition),
    (   tr_noun_of_lesson(W, N), ( tr_holds(time(N)) ; tr_holds(month(N)) ) -> true
    ;   tr_time_near(Ws)
    ).
%% ... in the first N words only, where a time phrase has its noun (`el
%% pasado domingo': the third); a clause's words run to the end of the sentence
tr_time_in_first(N, Ws) :- tr_time_noun_then(N, Ws, _).
%% ... and the words after that noun
tr_time_noun_then(N, [W|Ws], After) :-
    N > 0, W = w(X, _), atom(X), \+ tr_is(foreign, W, preposition),
    (   tr_noun_of_lesson(W, Noun), ( tr_holds(time(Noun)) ; tr_holds(month(Noun)) ) -> After = Ws
    ;   N1 is N - 1, tr_time_noun_then(N1, Ws, After)
    ).
%% a time phrase starts with an article or a demonstrative (`el domingo',
%% `este lunes'), asked of the word first, which the phrase reader has asked
%% already: the sentence keeps the answer (tr_is/3)
tr_time_starts(Side, W) :-
    W = w(X, _), atom(X), ( tr_is(Side, W, article) ; tr_is(Side, W, demonstrative) ), !.
%% what follows a participle's time and belongs to it: nothing, or an adjunct
%% -- never a comma, which the complements make a separator (and the participle's
%% time has none), nor a phrase of its own, an object: `approvata il 12 gennaio il
%% presidente ...' (the comma of an aside is not among the words) read the phrase
%% and the rest of the sentence for the hundred thousand inferences that failed it
tr_time_tail([]).
tr_time_tail([R|_]) :-
    R \== comma, \+ tr_is(foreign, R, article), \+ tr_is(foreign, R, demonstrative).

%% ... BUT A DAY IS NOBODY'S AGENT: `è vietato DAL 24 luglio al 25 agosto',
%% `"proibita" dal primo al 31 agosto' -- from one day to another, and read
%% as the agent the day had done the banning, `por el 24 de julio'. The
%% phrase is a date, or the start of a range whose end is one.
%% ... and a range ends at `to': `dal gatto nel 2014' is the cat, and a year
tr_means_to(english, to) :- !.
tr_means_to(foreign, W) :- tr_lexeme(foreign, W, L, _), tr_solve(mean(L, to)), !.
%% a preposition of comparison: English's `as' and `like', or a lesson's
%% word meaning one of them (`come', `como')
tr_means_as(english, w(W, _)) :- !, memberchk(W, [as, like]).
tr_means_as(foreign, w(W, _)) :- ( tr_solve(mean(W, as)) ; tr_solve(mean(W, like)) ), !.
%% It is asked of the words and not of their phrases, because it is asked
%% after every participle a preposition follows: read as phrases, the rest of
%% Livata's `soccorsa dai carabinieri, è stata trasportata ...' cost its
%% sentence half as much again.
tr_date_range(Side, Ws0) :-
    ( Ws0 = [D|Ws], tr_determiner(Side, D, _, article) -> true ; Ws = Ws0 ),
    (   Ws = [w(N, _), M|_], tr_digits(N), tr_month(Side, M) -> true                 % `dal 24 luglio'
    ;   append(Pre, [P2|Ws2], Ws), Pre \== [], length(Pre, K), K =< 2,                 % `dal 4 al 24 agosto',
        P2 = w(PW, _), tr_is(Side, P2, preposition), tr_means_to(Side, PW),          % `dal primo al 31 agosto'
        ( Ws2 = [D2, w(N2, _)|_], tr_determiner(Side, D2, _, article) -> true ; Ws2 = [w(N2, _)|_] ),
        tr_digits(N2)
    ), !.
%% (a word one of whose lexemes says how many: the sentence's list, tr_into_ir/4)
tr_count_lexeme(B) :- nb_getval('$tr_count_lexemes', Ls), Ls \== [], tr_lexeme(foreign, B, L, _), memberchk(L, Ls), !.
tr_count_adverb(B) :-
    tr_lexeme(foreign, B, L, _), atom(L), tr_class_of(L, adverb), ( tr_solve(mean(L, well)) ; tr_solve(mean(L, 'as many as')) ), !.
%% (... BUT A WORD THAT IS A DETERMINER TOO BEGINS NO PHRASE OF A PREPOSITION BEFORE A BARE NOUN: `No aparecen
%% más artefactos' are no more devices appearing -- `más' is the preposition `plus' as well, and read so the
%% devices were its phrase and the verb had nobody named, `They do not appear more devices')
tr_determiner_before_noun(foreign, P, [N|_]) :-
    P = w(PW, _), atom(PW), tr_determiner(foreign, P, _, determiner),
    tr_is(foreign, N, noun), \+ tr_determiner(foreign, N, _, _), !.
%% (a common noun in the phrase the verb governs, `"conta" takes "su" before the
%% phrase.': tr_after_phrase/5 gives that noun the infinitive after it -- in any
%% phrase, `consentire a lupi, volpi e topi di fogna di circolare', the wolves
%% allowed to roam, had the sewer's infinitive, `of circulating', and `non mi è mai
%% passato per la testa di preparare' was `for the head of preparing')
tr_noun_takes_inf(foreign, w(PW, _), np(_, _, _, w(_, _), _)) :- atom(PW).
tr_governed_here(w(PW, _)) :- atom(PW), tr_global('$tr_read_group', G), atom(G), tr_solve(take_before(G, PW, phrase)), !.

%% ... AND THE PREPOSITION A VERB GOVERNS IS MARKED, gov(Phrase): `depende DE
%% la calidad' -- Italian's `dipende DA', where the preposition the source
%% used came out `di' by its first meaning. The lesson says which a verb takes
%% before a phrase (`"depende" takes "de" before the phrase.'), and the writer
%% of the verb it is written with says its own (`"dipende" takes "da" before
%% the phrase.'); with none stated either side, the phrase is written as it was
%% -- the FIRST phrase after the verb with the preposition it takes, and no
%% other: `depende de la calidad de las instituciones' governs the first `de'
%% only, the second is the institutions' of the quality
%% -- of the verb the phrase follows: after an infinitive, the infinitive's
%% (`pueden contar con su colaboración' is `contare SU', not the modal's)
tr_governed(Side, Cs0, Cs) :-
    tr_global('$tr_read_group', G), atom(G), G \== none,
    append(Pre, [pp(w(PW, PC), NP)|Post0], Cs0), atom(PW), NP \= adv(_),
    tr_governing_verb(Pre, G, V),
    (   Side == foreign -> tr_solve(take_before(V, PW, phrase)) ; en_governs(V, PW) ), !,
    tr_gov_second(V, PW, Post0, Post),
    append(Pre, [pp(w(PW, PC), gov(V, NP))|Post], Cs).
%% ... and so are the two halves of both ... and when each opens on that preposition: `non deriverebbe
%% tanto dagli scarichi delle industrie quanto da un inquinamento' derives FROM both, `no derivaría
%% tanto de los vertidos como de una contaminación', where Spanish wrote `desde', the first `from'
tr_governed(Side, Cs0, Cs) :-
    tr_global('$tr_read_group', G), atom(G), G \== none,
    append(Pre, [both([pp(w(PW, PC), NP1)|R1], [pp(w(PW2, PC2), NP2)|R2])|Post], Cs0),
    atom(PW), atom(PW2), NP1 \= adv(_), NP2 \= adv(_),
    tr_governing_verb(Pre, G, V),
    (   Side == foreign -> tr_solve(take_before(V, PW, phrase)), tr_solve(take_before(V, PW2, phrase))
    ;   en_governs(V, PW), en_governs(V, PW2)
    ), !,
    append(Pre, [both([pp(w(PW, PC), gov(V, NP1))|R1], [pp(w(PW2, PC2), gov(V, NP2))|R2])|Post], Cs).
tr_governed(_, Cs, Cs).
%% ... and so is a second phrase joined to the first by `or' or `and', on the same preposition, past the first one's
%% own phrases of `of': `Non tengono conto della mancanza cronica di posti ... o della distanza dei nonni' takes into
%% account the lack or the distance, and the second kept its `of', `or of the distance', `o de la distancia'
tr_gov_second(V, PW, Post0, Post) :-
    append(Ofs, [cnj(C), pp(w(PW, PC2), NP2)|Rest], Post0),
    forall(member(X, Ofs), ( X = pp(w(OW, _), _), atom(OW), tr_lexeme(foreign, OW, OL, _), once(tr_solve(mean(OL, of))) )),
    NP2 \= adv(_), NP2 \= gov(_, _), !,
    append(Ofs, [cnj(C), pp(w(PW, PC2), gov(V, NP2))|Rest], Post).
tr_gov_second(_, _, Post, Post).
%% (and an infinitive after its preposition: `responsabilizaba a un sector del PNV de poner trabas a la
%% pacificación' hinders the pacification, and with the sector's phrase of `of' between them the infinitive was
%% read after its `de', pinf/2, whose phrase Italian wrote with its `a', `d'ostacolare alla pacificazione')
tr_governing_verb(Pre, G, V) :-
    (   append(_, [C|Rest], Pre), ( C = inf(IL) ; C = infx(IL, _, _) ; C = purpose(IL) ; C = pinf(_, IL) ), atom(IL),
        \+ ( member(X, Rest), ( X = inf(_) ; X = infx(_, _, _) ; X = purpose(_) ; X = pinf(_, _) ) )
    ->  V = IL
    ;   V = G
    ).

tr_oblique_pronoun(english, _) :- !.
%% (an elided form is the words it elides: `tra l'Europa e l'Asia ci stesse
%% un altro continente' is between Europe and Asia, and `l'' -- which the
%% lesson calls no pronoun, so it said nothing of its place -- was `among
%% him', with Europe and Asia the subject of `there was')
tr_oblique_pronoun(foreign, W) :- tr_solve(elision_of(W, _)), !,
    \+ ( tr_solve(elision_of(W, F)), \+ tr_oblique_pronoun(foreign, F) ).
tr_oblique_pronoun(foreign, W) :- tr_subject_pronoun(foreign, W, _, _), !.
tr_oblique_pronoun(foreign, W) :- \+ tr_holds(precede(W, verb)).

%% A `de' AND AN INFINITIVE AFTER A PREPOSITION'S PHRASE ARE THAT PHRASE'S:
%% `apeló a la necesidad de ser humildes' is the need to be humble, and it
%% keeps its preposition as it does after an object (pinf/2)
%% -- BUT NOT A WORD THE LESSON SAYS BEGINS THE INFINITIVE, which is the
%% verb's: `aveva riferito ai carabinieri di aver lasciato i piccoli' is
%% telling them to have left the children, and read as the carabinieri's
%% `di' it came out `de tener dejado'. Spanish says nothing of `de' there,
%% and `la necesidad de ser humildes' keeps its reading.
tr_after_phrase(Ph, foreign, [w(P, C), w(V, _)|Ws], Seen, [pinf(w(P, C), F)|Cs]) :-
    ( Ph == yes ; Ph == noun ), tr_means_of(P), \+ tr_solve(begin(P, infinitive)),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    tr_complements(foreign, Ws, Seen, Cs).
%% ... BUT WITH NO VERB READ THERE IS NOBODY ELSE'S IT COULD BE: `nulla da
%% eccepire sulla necessità di vigilare' is the need to watch, and read as a
%% verb's the infinitive lost its `de' -- `sobre la necesidad vigilar'.
%% (Where a verb was read, a phrase after `di' is as often a noun's own part
%% as the one the verb asks -- `consentire a lupi ... e topi di fogna di
%% circolare' is the wolves allowed to roam, and the sewer's infinitive was
%% `de circular' -- and nothing a lesson says tells them apart.)
%% ... AND WHERE A VERB WAS READ, THE INFINITIVE AFTER A NOUN IN A PHRASE OF
%% ANY PREPOSITION BUT `to': `E non contate sulla probabilità di farla franca'
%% is the probability of getting away with it, and read as the verb's the
%% infinitive lost its `de' (`no contéis con la probabilidad salirse con la
%% suya'). A phrase of `to' names who a verb lets, asks or forbids, and the
%% infinitive is the verb's: `proibire ai cani di passeggiare', `consentire a
%% lupi ... di circolare'. Nor where the verb takes the word before the phrase
%% or the infinitive itself (`"parla" takes "di" ...'): that is the verb's.
tr_after_phrase(Ph, foreign, [w(P, C), w(V, _)|Ws], Seen, [pinf(w(P, C), F)|Cs]) :-
    ( Ph == yes ; Ph == noun ), tr_means_of(P), tr_solve(begin(P, infinitive)),
    tr_global('$tr_read_group', G),
    (   G == none -> true
    ;   Ph == noun, atom(G), \+ tr_solve(take_before(G, P, phrase)), \+ tr_solve(take_before(G, P, infinitive))
    ),
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !,
    tr_complements(foreign, Ws, Seen, Cs).
tr_after_phrase(_, Side, Ws, Seen, Cs) :- tr_complements(Side, Ws, Seen, Cs).
%% AN ORDINAL BEFORE A NOUN IT AGREES WITH IS THE NOUN'S ADJECTIVE: `a norma
%% dell'articolo 74, primo comma, della costituzione' is the first paragraph,
%% and `primo' is the adverb `first' as well -- read as the clause's adverb it
%% came out `primero coma', the word for the punctuation mark, written after
%% the phrase in English. Only an ordinal: `solo pane' is only bread, and
%% `solo' is an adjective too
tr_ordinal_before_noun(Side, [A, N|_]) :-
    A = w(AW, _), N = w(NW, _), atom(AW), atom(NW),
    tr_is(Side, A, adjective), tr_is(Side, N, noun), \+ tr_is(Side, N, adjective),
    tr_ordinal_word(Side, AW), tr_aside_agrees(N, A), !.
tr_ordinal_word(Side, W) :-
    tr_lexeme(Side, W, L, _), tr_solve(mean(L, E)), en_ordinal(E), !.
en_ordinal(first).  en_ordinal(second). en_ordinal(third).  en_ordinal(fourth). en_ordinal(fifth).
en_ordinal(sixth).  en_ordinal(seventh). en_ordinal(eighth). en_ordinal(ninth). en_ordinal(tenth).
en_ordinal(last).

%% an adverb that is no article: `unos' is `about' before a number (tr_np/3)
%% and an article everywhere else, and as an adverb anywhere a phrase begins
%% it cut `unas ventas' off before its article
tr_plain_adverb(Side, A) :- tr_is(Side, A, adverb), \+ tr_determiner(Side, A, _, article).
%% a piece that opens on one adverb and a comma: `Así, trabajo hecho'
tr_adverb_head(Side, [A, comma|_]) :- A = w(W, _), atom(W), tr_plain_adverb(Side, A), !.
%% the halves of `non solo X ma (anche) Y' after the denial: the word for
%% `only', the first half up to the word for `but' -- or the partner the
%% lesson names for `only' -- the word for `also', and the second half
tr_nonly_parts(O, Ws, A, B, Also, Rest) :-
    O = w(OW, _), atom(OW), tr_lexeme(foreign, OW, OL, _), tr_solve(mean(OL, only)),
    append(AW1, [w(M, _)|BW0], Ws), AW1 \== [], atom(M),
    ( tr_solve(partner_of(M, OW)) -> true ; tr_solve(mean(M, but)) ),
    %% (a comma before `but' is the source's, and travels as c/1 around
    %% Also: `non solo Tolomeo ed Eratostene, ma persino Pitagora')
    ( append(AW, [comma], AW1), AW \== [] -> Comma = yes ; AW = AW1, Comma = no ),
    \+ memberchk(comma, AW),
    tr_subject(foreign, none, AW, _, _, A), A \= null(_, _),
    tr_nonly_also(BW0, BW, Also0), ( Comma == yes -> Also = c(Also0) ; Also = Also0 ),
    %% (the whole second half first, with its own phrases: `tanti altri nel
    %% nostro campo' -- and a phrase's words end before `altri', which is
    %% an object pronoun too)
    (   tr_subject(foreign, none, BW, _, _, B), B \= null(_, _) -> Rest = []
    ;   tr_phrase_words(foreign, BW, PW, Rest), PW \== [],
        tr_subject(foreign, none, PW, _, _, B), B \= null(_, _)
    ), !.
%% the word after `but' that says the second half is more: `also', or
%% `EVEN' -- `non solo Tolomeo ed Eratostene, ma persino Pitagora, ...' is
%% not only they but even Pythagoras; read as `also' was, `persino' was left
%% at the head of the second half, which no subject reads
tr_nonly_also([w(Al, _)|BW], BW, yes) :- atom(Al), tr_solve(mean(Al, also)), !.
tr_nonly_also([w(Al, AC)|BW], BW, even) :- atom(Al), BW \== [], tr_solve(mean(Al, even)), tr_is(foreign, w(Al, AC), adverb), !.
tr_nonly_also(BW, BW, no).
%% the number `not only A but B' takes: plural when EITHER half is, and the
%% second half's otherwise -- `Non solo il cane ma anche il gatto dorme' is
%% singular, `Lo sapevano non solo Tolomeo ed Eratostene, ma persino
%% Pitagora' plural. The writer (tr_np_out/5) says the same, so a verb read
%% in one number is written in it.
tr_nonly_number(A, B, N) :-
    ( ( tr_half_plural(A) ; tr_half_plural(B) ) -> N = plural ; tr_subject_number(B, N) ).
%% ... or, two halves in the singular, the plural a verb says of them both:
%% `Lo sanno non solo Maria, ma anche Carla' is the two knowing it, and read
%% in the second half's number the subject after the verb had no reading --
%% where 1.8.30, with no such subject, had read the two as the objects of
%% a verb nobody named. That plural is kept in the term, pl(Also), so the
%% writer says it again (tr_np_out/5)
tr_nonly_number(A, B, Also, N, Also1) :-
    tr_nonly_number(A, B, N0),
    (   N = N0, Also1 = Also
    ;   N0 == singular, N = plural, Also1 = pl(Also)
    ).
tr_half_plural(X) :- tr_accusative_number(X, plural), !.
tr_half_plural(X) :- tr_subject_number(X, plural), !.
tr_half_plural(pronoun(_, plural, _)).
tr_determiner_before_noun(Side, [D, N|_]) :-
    D = w(DW, _), N = w(NW, _), atom(DW), atom(NW),
    tr_determiner(Side, D, _, DK), DK \== article,
    tr_is(Side, N, noun), \+ tr_is(Side, N, adjective),
    tr_lexeme(Side, DW, _, Num), tr_lexeme(Side, NW, _, Num), !.
%% ... AND, IN A PERFECT CLAUSE, THE FORM IT WAS GIVEN IN WHEN THAT IS NOT THE
%% DEFAULT: a participle after the comma of a perfect clause is the perfect's
%% and never agrees (`avrebbe dissestato l'amministrazione, reso piu lunghi i
%% tempi e acuito la crisi' -- the writer's rule below, tr_perfect_preds/3), but
%% `Una madre che ha perso la figlia di 4 anni, annegata in una piscina' is
%% the DAUGHTER drowned, and `annegata' says so: a feminine or a plural form
%% cannot be the invariable one. It travels as pagr(Gender, Number) beside the
%% participle, only in a perfect clause, where the writer takes it -- and only
%% when it is not the masculine singular, so a clause whose participles are
%% all the default reads as it did. (A form that agrees with a pronoun BEFORE
%% the verb, `li abbiamo fatti bere, riscaldati', is the perfect's too, and
%% the writer knows that from the pronoun.)
tr_participle_agr(foreign, P, [pagr(G, N)]) :-
    tr_global('$tr_read_aspect', perfect),
    %% (never after a verb whose perfect the lesson builds with the copula
    %% when the participle's own verb does too, `sono uscite, arrivate':
    %% there the participle agrees with the subject as part of the perfect,
    %% and the other language's is invariable. A participle of a verb that
    %% takes `avere' is a predicate of the subject and agrees in both:
    %% `sono morte abbracciate' and `è morta felice, stretta alla sua tata'
    %% are `han muerto abrazadas' and `ha muerto feliz, apretada a su
    %% niñera', where every participle after the copula's perfect was
    %% taken for its elided part and came out `abrazado', `apretado')
    tr_global('$tr_read_group', G0), ( G0 = reflexive(G1) -> true ; G1 = G0 ),
    \+ ( atom(G1), tr_unaccusative(G1), tr_participle_unaccusative(P) ),
    ( tr_holds(feminine(P)) -> G = feminine ; G = masculine ),
    ( tr_participle_number(P, plural) -> N = plural ; N = singular ),
    ( G \== masculine ; N \== singular ), !.
tr_participle_agr(_, _, []).
tr_participle_unaccusative(P) :- tr_solve(participle_of(P, L)), tr_unaccusative(L), !.
%% what follows a perfect infinitive after its preposition is the infinitive's,
%% read with its verb as the group (a line with no verb has none, and a lone
%% adjective that is a noun too was the noun: `positivo il 17 maggio')
tr_perf_rest(F, Ws, Seen, Cs) :-
    tr_global('$tr_read_group', G0), nb_setval('$tr_read_group', F),
    (   tr_complements(foreign, Ws, Seen, Cs) -> nb_setval('$tr_read_group', G0)
    ;   nb_setval('$tr_read_group', G0), fail
    ).
%% THE PHRASE AFTER THE INFINITIVE OF `UPON' (tr_complements0/4) THAT THE LESSON CALLS INTRANSITIVE IS ITS SUBJECT: `al estallarle una bomba
%% colocada en la arena' is on a bomb placed in the sand exploding -- read as its object, English wrote `on bursting him
%% a placed bomb on the sand'. upons(Lexeme, Phrase, Complements), the infinitive's pronoun of the person it happens
%% to left out; a participle with no phrase of its own takes the one after it (tr_participle_adjunct/4)
tr_upon_subject(F, [obj(NP0)|Cs0], NP, Cs) :-
    atom(F), tr_solve(intransitive(F)), tr_participle_adjunct(NP0, Cs0, NP, Cs), !.

%% ... AND ONLY AFTER A VERB THE LESSON SAYS TAKES THE CLAUSE: `"risulta"
%% takes the clause.', in the shape `"stabilisce" takes the question.' has.
%% The subjunctive is the clause's only mark, and a word spelled like one is
%% often something else: `li hanno trovati vigili e in buone condizioni' found
%% them VIGILANT, and Spanish's `el resultado es una versión' is a version --
%% `vigili' and `una' are subjunctives too, of `vigilare' and `unir', and read
%% as the clause's verbs they made `que vigilas' and `che unisce'. Which
%% verbs leave the word out is the language's, and a lesson says it verb by
%% verb; one that says it of none, as Spanish's, reads no such clause.
tr_cheless_here(Ws) :-
    tr_global('$tr_read_group', G), atom(G), G \== none, tr_solve(take(G, clause)),
    tr_subjunctive_next(Ws).

tr_subjunctive_next([w(X, _)|Ws]) :- tr_negation_word(X), !, tr_subjunctive_next(Ws).
tr_subjunctive_next([w(C, _)|Ws]) :- Ws \== [], tr_clitic(after, C), !, tr_subjunctive_next(Ws).
%% (the plural of a form the lesson states as a subjunctive is one too -- but not
%% a verb's own word: `vive' is the plural of the adjective `viva', `viva' the
%% subjunctive of `vivere', and `vive' itself the indicative `lives', so
%% `perché ciascuno vive' is because each lives, and read so it was `de modo que')
tr_subjunctive_next([w(V, _)|_]) :-
    (   tr_solve(subjunctive_of(V, _)) -> true
    ;   tr_solve(plural_of(V, V1)), tr_solve(subjunctive_of(V1, _)), \+ tr_class_of(V, verb)
    ), !.

%% A RELATIVE CLAUSE AFTER A COMMA SAYS SOMETHING MORE OF THE PHRASE BEFORE
%% IT: `Un capitolo riassume la sperimentazione sul vaccino contro la
%% pertosse, che ha fatto passare la protezione ... dal 30 al 90%.' The
%% phrase ends at the comma (tr_phrase_words/4), and what followed it was
%% read as a `che' clause of the VERB's -- `summarises ..., that has made'
%% with nobody for its subject -- which no writer could write. It is the
%% phrase's, set off with a comma, and it runs to the end of its piece as a
%% `che' clause does. nrc(Phrase, Role, Clause) is the term, rc/3's shape,
%% and every writer puts the comma back before the relative word. It hangs
%% on the LAST phrase before the comma, which is where every language here
%% writes it, whichever phrase the clause is about.
tr_phrase_nrc(Side, Ws, nrc(NP, Role, S)) :-
    append(_, [comma|After], Ws), tr_nrc_start(Side, After), !,
    tr_phrase_words(Side, Ws, PW, [comma|R1]), PW \== [],
    tr_nrc_start(Side, R1), \+ tr_all_adjectives(Side, PW),
    tr_relative_clause(Side, R1, Role, S0),
    tr_phrase_np(Side, PW, NP), !,
    %% (a thing's reflexive is its passive here too: `di arsenico e di pesticidi, che si sono depositati')
    ( Side == foreign -> tr_se_passive_rc(NP, Role, S0, S1) ; S1 = S0 ),
    tr_rel_mark(R1, S1, S).

%% ... AND A QUOTATION THAT OPENS ON ITS RELATIVE WORD: `a Colonia, "che però
%% non è fornito di laboratori - sottolinea ...' quotes the dean from `che'
%% on. The relative word is the writer's, never a word of the clause, so the
%% mark it carried was lost with it and the quotation closed in the next
%% sentence with nothing that opened it. qrel among the clause's complements
%% says so, and every writer puts the mark on the relative word it writes
%% ... and one that closes on the verb the clause ends on closes where the clause ends: `las críticas, "que en
%% política siempre vienen bien"' -- the words before the verb are written after it, and with the mark on the verb
%% they came out outside the quotation, `"che aiutano" in politica sempre'. qe for vqc: the last word written
tr_rel_mark([w(_, qopen)|Ws], s(A, Su, G, Cs0), s(A, Su, G, [qrel, qe|Cs])) :-
    last(Ws, w(_, qclose)), selectchk(vqc, Cs0, Cs), !.
tr_rel_mark([w(_, qopen)|_], s(A, Su, G, Cs), s(A, Su, G, [qrel|Cs])) :- !.
tr_rel_mark(_, S, S).

%% what opens such a clause: the relative word, or a preposition before it
%% and an article between them -- `joyas de este tipo de instrumentos, POR
%% LAS QUE el mejor de los intérpretes perdería la cabeza', which read as a
%% clause of the verb's came out `per le che'
tr_nrc_start(Side, [w(RW, _)|_]) :- tr_relative_word(Side, RW), !.
tr_nrc_start(Side, [P, w(RW, _)|_]) :- tr_is(Side, P, preposition), tr_relative_word(Side, RW), !.
tr_nrc_start(Side, [P, D, w(RW, _)|_]) :-
    tr_is(Side, P, preposition), tr_determiner(Side, D, _, article), tr_relative_word(Side, RW), !.

%% a phrase's words read as its phrase, and a relative clause after a comma
%% with them: the rest is what follows, and nothing does after such a clause
tr_phrase_rest(Side, Ws, NP, []) :- tr_phrase_nrc(Side, Ws, NP), !.
tr_phrase_rest(Side, Ws, NP, Rest) :- tr_phrase_aside(Side, Ws, NP, Rest), !.
tr_phrase_rest(Side, Ws, NP, Rest) :-
    tr_phrase_words(Side, Ws, PW, Rest), PW \== [], tr_phrase_np(Side, PW, NP).
%% ... AND THE PHRASE BEFORE ITS COORDINATOR, where the two joined are no
%% phrase: `in diretta e il tribunale di Milano come sfondo' is live and
%% something else, and `diretta e il tribunale' reads as nothing -- a bare
%% noun and a phrase with its article. Asked only after the whole read
%% nothing, and the coordinator and what follows it stay in the rest. Only
%% the lesson's own side reads it (the absolute phrase it serves is read
%% there), and only where a coordinator and an article stand a few words ahead
%% and a word that means `like' after them: the phrase reader is asked at
%% every place a phrase can end, and this clause ran its words a second time
%% at each place that read nothing -- 3.3 % of the inferences of three
%% controls, and 0.7 % with these two looks first.
tr_phrase_rest(foreign, Ws, NP, Rest) :-
    tr_coord_article_ahead(foreign, Ws, 8),
    tr_phrase_words(foreign, Ws, PW, Rest0), PW \== [],
    append(PW1, [C|PW2], PW), PW1 \== [], PW2 = [D|_], C = w(_, _), tr_coord(foreign, C),
    D = w(_, _), tr_determiner(foreign, D, _, article),
    append(PW2, Rest0, After), tr_like_within(After, 12),
    tr_phrase_np(foreign, PW1, NP), !,
    append([C|PW2], Rest0, Rest).
tr_coord_article_ahead(Side, [C, D|_], _) :-
    C = w(_, _), D = w(_, _), tr_coord(Side, C), tr_determiner(Side, D, _, article), !.
tr_coord_article_ahead(Side, [_|Ws], N) :- N > 0, N1 is N - 1, tr_coord_article_ahead(Side, Ws, N1).
%% a word that means `like' among the next N words
tr_like_within([X|Ws], N) :-
    (   X = w(W, _), atom(W), tr_lexeme(foreign, W, LL, _), tr_solve(mean(LL, like)) -> true
    ;   N > 0, N1 is N - 1, tr_like_within(Ws, N1)
    ).

%% A PARTICIPLE AFTER A COMMA IS THE PHRASE'S TOO: `le più canicolari Eolie,
%% interdette al traffico dal 4 al 24 agosto, e l'isola di Ustica' -- the
%% islands closed to traffic. Read with the commas taken out, `al traffico e
%% l'isola' was one phrase, the island joined to the traffic. It is a reduced
%% relative with the participle's own adjuncts up to the next comma, and
%% aside(Closed) among them says whether a comma closed it, so every writer
%% puts back the commas the source had; a coordinator after the closing
%% comma joins a second phrase to the first.
%% ... AND A PARTICIPLE WITH ITS DEGREE, AFTER A PHRASE THAT HAS ONE:
%% `una adhesión más limitada, más contenida' is a more limited, more
%% restrained adherence -- the phrase before the comma is itself a reduced
%% relative (tr_np/3), and the participle after it agrees with the same noun,
%% where read with the phrase refused it was said of the sentence's subject
%% and came out `più contenuti'.
tr_phrase_aside(Side, Ws, NP, Rest) :-
    append(PW, [comma|R0], Ws), PW \== [], \+ memberchk(comma, PW),
    (   R0 = [w(M, _), w(P, PC)|R1], Side == foreign, tr_degree_word(M) -> Deg = yes
    ;   R0 = [w(P, PC)|R1], Deg = no
    ),
    tr_participle_here(Side, P, L), \+ tr_is(Side, w(P, lower), noun),
    (   append(CW, [comma|R2], R1), \+ memberchk(comma, CW) -> Closed = yes
    ;   CW = R1, R2 = [], Closed = no
    ),
    (   CW == [] -> Cs0 = []
    %% (and its agent: `Pedro es el autor de la placa, secuestrada por el comando.' -- with no comma to close the
    %% participle the agent was read as a phrase of `for', `kidnapped for the commando')
    ;   Side == foreign, tr_reduced_agent(foreign, CW, CsA), memberchk(by(_), CsA) -> Cs0 = CsA
    ;   tr_complements(Side, CW, Cs0a), tr_adjuncts(Cs0a), \+ memberchk(sep, Cs0a),
        ( Side == foreign -> tr_ptc_governed(Side, L, Cs0a, Cs0) ; Cs0 = Cs0a )   % (`cubierta de botellas', covered WITH them)
    ),
    tr_phrase_np(Side, PW, NP1), ( NP1 = np(_, _, _, _, _) -> true ; NP1 = rel(np(_, _, _, _, _), _, _) ),
    tr_np_head(NP1, H1),
    %% (and it agrees with the phrase in number, or it is the SUBJECT'S:
    %% `le attività ... potranno svolgersi in piena libertà, regolamentate con
    %% giudizio' -- the activities are regulated, and the freedom before the
    %% comma is singular; the participle stood as the freedom's aside)
    \+ ( Side == foreign, H1 = np(_, _, _, _, HN), atom(HN), tr_participle_number(P, PN), PN \== HN ),
    (   Deg == yes -> H1 = np(Det1, _, _, _, _), tr_degree_of(foreign, Det1, Degree), Cs00 = [pdeg(Degree)|Cs0]
    ;   Cs00 = Cs0
    ),
    tr_rel_agreement(Side, P, H1, Cs00, Cs1), tr_rel_case(PC, Cs1, Cs),
    A = rel(NP1, L, [aside(Closed)|Cs]),
    (   Closed == yes, R2 = [C|R3], C = w(_, _), tr_coord(Side, C), R3 \== [],
        tr_phrase_rest(Side, R3, NP2, Rest0)
    ->  NP = co(C, A, NP2), Rest = Rest0
    %% ... and a relative clause after the closing comma is the same phrase's:
    %% `con quella sua voce lieve, sussurrata, che è già musica' is the voice
    %% that is music already, and left among the clause's complements it was
    %% a clause of `that' with nobody named, `that it is already music'
    ;   Closed == yes, tr_nrc_start(Side, R2), tr_relative_clause(Side, R2, Role, S0)
    ->  ( Side == foreign -> tr_se_passive_rc(A, Role, S0, S1) ; S1 = S0 ), tr_rel_mark(R2, S1, S2),
        NP = nrc(A, Role, S2), Rest = []
    ;   NP = A, Rest = R2
    ).

%% A WORD STANDING ALONE IN A CLAUSE WITH NO VERB IS A THING NAMED, NOT ONE
%% PREDICATED, because nothing is there to predicate it of: `Grazie
%% all'Arma ..., a Provincia, Regione Lazio, volontari, ai cani' thanks the
%% volunteers, and `volontari' -- a noun and an adjective -- read first as
%% the adjective came out `voluntario', one thing and voluntary. Only a word
%% the lesson calls a noun too, and only where no verb was read (the gapped
%% clause and a front, tr_read0/4, which set the group to none).
tr_verbless_thing(Side, [W]) :- tr_global('$tr_read_group', none), tr_is(Side, W, noun), !.

%% a phrase whose noun the lesson calls a time
tr_time_phrase(np(_, _, _, W, _)) :- tr_noun_of_lesson(W, Noun), tr_holds(time(Noun)).
tr_time_phrase(app(NP, label, _)) :- tr_time_phrase(NP).
tr_time_phrase(app(NP, part, _)) :- tr_time_phrase(NP).
tr_time_subject(with(NP, _)) :- !, tr_time_phrase(NP).
tr_time_subject(NP) :- tr_time_phrase(NP).
%% ... a time that says which: a month, a day of the week, or any time with an
%% adjective (`la semana pasada', `el pasado noviembre'); `el tiempo' and `la
%% hora' say none, and `pasó el tiempo' is the time passing
%% ... a month with an adjective is a time as well, as a complement: `el pasado
%% noviembre' (the months are no times to the lesson, `Odio noviembre')
tr_month_which(np(_, _, [_|_], W, _)) :- tr_noun_of_lesson(W, Noun), tr_holds(month(Noun)).
%% ... and the time or the month with an adjective alone is the deictic one,
%% `la semana pasada', `el pasado noviembre', never a day's date
tr_day_label(app(np(_, none, [], W, singular), label, w(N, _))) :-
    atom(N), tr_digits(N), tr_noun_of_lesson(W, Noun), tr_holds(time(Noun)), !.
tr_time_deictic(np(_, Num, [_|_], W, _)) :-
    Num == none, tr_noun_of_lesson(W, Noun), ( tr_holds(month(Noun)) ; tr_holds(time(Noun)) ), !.
tr_time_which(with(NP, _)) :- !, tr_time_which(NP).
tr_time_which(app(NP, _, _)) :- !, tr_time_which(NP).
tr_time_which(np(_, _, Adjs, W, _)) :-
    tr_noun_of_lesson(W, Noun),
    (   tr_holds(month(Noun)) -> true
    ;   tr_holds(time(Noun)), ( Adjs \== [] -> true ; tr_solve(mean(Noun, E)), tr_weekday(E) )
    ), !.
%% ... NOR A TIME WHEN `AGO' IS LIFTED OUT AFTER IT: `Un mese e mezzo fa, al Foro
%% Italico ha nuotato' -- the month and a half, and then `fa' -- is the time
%% before the adverb, an adjunct; read as the subject it swam (and a subject
%% named is what makes a front end at the first comma, so `Il 3 giugno, un
%% mese e mezzo fa, ha nuotato' lost its second time to it)
tr_ago_time_subject(Su, Advs) :- tr_time_subject(Su), member(adv(w(A, _)), Advs), atom(A), tr_solve(mean(A, ago)), !.
%% ... and a date: the number of a day and the month
tr_date_phrase(np(_, w(D, _), _, W, _)) :- atom(D), tr_digits(D), tr_noun_of_lesson(W, Noun), tr_holds(month(Noun)).
tr_date_adjunct_here(Seen) :- Seen == yes, !.
tr_date_adjunct_here(_) :- catch(nb_getval('$tr_read_group', L), _, fail), atom(L), tr_solve(intransitive(L)), !.
%% ... or a month, where a time is asked of a phrase that is no complement
%% of the verb's -- a front, or what follows the word for `by' in a passive:
%% `se il prossimo febbraio il senato darà parere positivo'
tr_time_or_month(NP) :- tr_time_phrase(NP), !.
tr_time_or_month(np(_, _, _, W, _)) :- tr_noun_of_lesson(W, Noun), tr_holds(month(Noun)).

%% a singular noun the lesson calls a time, and the word it joins a day and
%% its part with (English has none)
tr_time_word(Side, W) :- atom(W), tr_lexeme(Side, W, L, singular), tr_time_lexeme(Side, L), tr_class(Side, L, noun), !.
tr_time_join(foreign, w(J, _)) :- tr_solve(join(J, time)), !.

%% ... and the part after a day where the lesson joins them: `el domingo
%% por la mañana' -- the phrase words end at the preposition, so the day
%% is read alone and the join, an article and the part are looked for
%% after it
tr_time_part_after(foreign, np(det(article, _, _), none, [], D, singular), [J|R1],
                   app(np(none, none, [], D, singular), part, np(none, none, [], P, singular)), Rest) :-
    tr_time_join(foreign, J), R1 = [A2, P|Rest], tr_determiner(foreign, A2, _, article),
    P = w(PW, _), tr_time_word(foreign, PW), !.

%% what may follow a conjunction between two complements: an infinitive or
%% a preposition, or an adverb and then one of those -- `di aver lasciato i
%% bimbi ... ma POI di essersi persa'
tr_after_coord(Side, [comma|Ws]) :- !,
    append(Ins, [comma|After], Ws), Ins \== [], \+ memberchk(comma, Ins), !,
    tr_after_coord0(Side, After).
tr_after_coord(Side, Ws) :- tr_after_coord0(Side, Ws).
tr_after_coord0(Side, Ws) :- ( tr_starts_infinitive(Side, Ws) ; Ws = [P|_], tr_is(Side, P, preposition) ), !.
%% ... or a participle standing alone, the verb before it understood: `gli
%% abbiamo messo delle coperte E AFFIDATI al 118'
tr_after_coord0(Side, [w(P, C)|_]) :- tr_participle_here(Side, P, _), \+ tr_is(Side, w(P, C), adjective), !.
tr_after_coord0(Side, [A|Ws]) :- tr_is(Side, A, adverb), ( Ws == [] -> tr_lead_in_adverb(A) ; tr_after_coord0(Side, Ws) ).
%% ... or adverbs and an ADJECTIVE, which says more of what the first half
%% named: `un governo stabile, ..., ma anche molto attento verso i soggetti'
%% -- but also very attentive. After an adverb only: an adjective straight
%% after a coordinator is the adjective list's own (adj/1 reads it).
tr_after_coord0(Side, Ws) :- tr_adverbs_adjective(Side, Ws), !.
%% (... and one adverb and nothing else is a lead-in, `O quasi:', where the
%% heading before a colon is just a coordinator and that adverb: `Ma non le
%% pare che ...?' has a coordinator and an adverb in front of its clause)
tr_lead_in_adverb(A) :- tr_global('$tr_heading', [_, A]).
%% ... AND A COMMA RIGHT AFTER THE COORDINATOR OPENS AN INSERTION, and what
%% follows the insertion decides (tr_after_coord/2 above): `sul contatto
%% diretto con la gente e, soprattutto, su un comportamento' -- read with
%% the commas out, the list of what the approach rests on lost all three,
%% and read with them it had no reading at all. Not the insertion's own
%% words: `tutta la notte e, oltre ai cani molecolari, sono stati
%% utilizzati ...' opens a clause of its own, and read as a second half
%% after `oltre' it cost Livata's twenty-ninth sentence more for the same
%% text

%% adverbs, and then an adjective
tr_adverbs_adjective(Side, [A, J|_]) :- tr_is(Side, A, adverb), J = w(_, _), tr_is(Side, J, adjective), !.
tr_adverbs_adjective(Side, [A|Ws]) :- tr_is(Side, A, adverb), tr_adverbs_adjective(Side, Ws).

%% THE ADJECTIVES AFTER A COORDINATOR, STANDING FOR A NOUN FAR BEFORE IT:
%% words that begin with an adjective (no noun, no adverb) and end where
%% their phrase does, all of them adjectives -- `incómodos para el tránsito'
%% is `incómodos' and then a phrase of `para' (tr_complements0/4, oadj/3)
tr_postposed_adjectives([A|Ws], PW, Rest) :-
    A = w(AW, _), atom(AW), tr_is(foreign, A, adjective),
    \+ tr_is(foreign, A, noun), \+ tr_is(foreign, A, adverb),
    tr_phrase_words(foreign, [A|Ws], PW, Rest), PW \== [],
    tr_all_adjectives(foreign, PW), \+ tr_verbless_thing(foreign, PW).
%% ... and one a phrase ENDS BEFORE, where its last word is a noun the
%% adjective does not agree with: `tramos de acera de distintas anchuras e
%% incómodos' read on, `acera e incómodos' was one phrase and no phrase
%% reads a noun and an adjective joined (tr_np/3), so nothing read. An
%% adjective that agrees with the noun stays in the phrase, and so does one
%% with a noun after it: `las casas y estoicos estudiantes' is two phrases
%% joined, and cut before `estoicos' nothing read
tr_postposed_adjective(PW, [A|Ws]) :-
    A = w(AW, _), atom(AW), tr_is(foreign, A, adjective), \+ tr_is(foreign, A, noun),
    last(PW, N), N = w(NW, _), atom(NW), tr_is(foreign, N, noun), \+ tr_is(foreign, N, adjective),
    \+ tr_aside_agrees(N, A),
    tr_postposed_adjectives([A|Ws], _, _).
%% an adjective's own gender and number, as its form says them: its lexeme's
%% gender where the lesson states one, the masculine where it states none
tr_adjective_agreement(w(W, _), G, N) :-
    once(tr_lexeme(foreign, W, L, N)),
    ( tr_stated_gender(L, G0), G0 \== none -> G = G0 ; G = masculine ).

%% what may follow a conjunction standing between two complements
tr_starts_infinitive(foreign, [w(V, _)|_]) :- tr_solve(infinitive_of(V, _)), !.
tr_starts_infinitive(english, [w(to, _), w(_, _)|_]).

%% a phrase, or two joined
%% ... and the second half is a list again, split at its own first
%% coordinator: `compañeros y vecinos, emigrantes y minorías' is four
%% phrases, and read once it was one phrase and a noun with three adjectives
%% ... AND AFTER A NAME AND A COORDINATOR, A RUN OF CAPITALISED WORDS IS A
%% NAME TOO, whatever its words mean: `tan dispares como Josep Cuní y Nieves
%% Herrero' -- `nieves' is snows and `herrero' a smith to the lesson, and read
%% as words the second presenter came out `Nevi Fabbri'. Two words at least,
%% and nothing but capitals.
tr_phrase_np(Side, PW, co(C, N1, name(N))) :-
    append(_, [w(_, upper), w(_, upper)], PW),          % (two capitals end it: asked before the split)
    tr_conjunction_split(Side, PW, W1, C, W2), W2 = [_, _|_],
    forall(member(X, W2), X = w(_, upper)),
    tr_object_phrase(Side, W1, N1), tr_names_only(N1), !,
    findall(Cap, ( member(w(W, _), W2), tr_cap(W, Cap) ), Cs), atomic_list_concat(Cs, ' ', N).
tr_phrase_np(Side, PW, co(C, N1, N2)) :-
    tr_conjunction_split(Side, PW, W1, C, W2), !, tr_object_phrase(Side, W1, N1), tr_phrase_np(Side, W2, N2).
tr_phrase_np(Side, PW, NP) :- tr_object_phrase(Side, PW, NP).

tr_names_only(name(_)).
tr_names_only(co(_, A, B)) :- tr_names_only(A), tr_names_only(B).

%% the word the lesson puts before an object of a class -- `The word "a"
%% precedes the person' -- and whether a phrase is of that class: a name
%% is a person (and a name), a phrase is what the lesson calls its noun,
%% two joined are when both are, and `whom' asks for a person. The rule
%% over pronouns and the verb is not a marker.
tr_marker_word(P) :- tr_marker_word(P, _).
tr_marker_word(P, Class) :- tr_solve(precede(P, Class)), Class \== verb, !.

tr_of_class(person, person) :- !.
tr_of_class(rc(NP, _, _), Class) :- !, tr_of_class(NP, Class).
tr_of_class(nrc(NP, _, _), Class) :- !, tr_of_class(NP, Class).
tr_of_class(ncl(NP, _), Class) :- !, tr_of_class(NP, Class).
tr_of_class(app(NP, _, _), Class) :- !, tr_of_class(NP, Class).
tr_of_class(all(_, NP), Class) :- !, tr_of_class(NP, Class).
%% a phrase with its phrases of `of' is of its head's class: `explicó ayer
%% el ministro de Asuntos Exteriores, Abel Matutes' is the minister telling
%% it -- the speaker's `of' phrases are the speaker's (tr_report_ofs/3), and
%% with no clause here the person the reporting clause at the end must have
%% was nobody, and the minister the object of a verb nobody named
tr_of_class(with(NP, _), Class) :- !, tr_of_class(NP, Class).
%% ... and so is a phrase with its participle after it: `ha investito la ragazza quindicenne molestata poco prima' ran
%% over the girl, and with the participle the phrase was of no class and lost its `a', `ha atropellado la niña' -- but
%% never a word that replaces the noun, which is of any class above: `ve el conducido por el gato' sees the one led,
%% and it came out `al conducido'
tr_of_class(rel(NP, _, _), Class) :- NP \= ell(_, _, _, _), !, tr_of_class(NP, Class).
%% a noun the sentence left out is of the class its sentence needs: `a un
%% grupo y el más débil' is two of the same thing
%% -- but never a count alone, which is as often an hour: `se desarrolló a
%% las tres' happened AT three, and taken for two persons marked as the
%% object it lost its `a', `si sviluppò le tre'
tr_of_class(np(_, w(_, _), [], elided(_), _), _) :- !, fail.
%% ... NOR A POSSESSIVE ALONE IN THE FEMININE SINGULAR, which is a thing the
%% subject owns: `dire la sua' is to say one's own, an opinion, and with the
%% phrase of any class it came out `decir a la suya'
tr_of_class(np(_, none, [w(P, _)], elided(feminine), singular), _) :- en_possessive_pronoun(P), !, fail.
tr_of_class(np(_, _, _, elided(_), _), _) :- !.
%% ... but the one of a phrase is of the class of what the phrase names: `ho visto una delle
%% squadre' is not a person, and took the `a' that goes before one
tr_of_class(ell(_, _, _, pp(w(of, _), NP2)), Class) :-
    tr_np_head(NP2, np(_, _, _, w(NW, _), _)), atom(NW), !, tr_of_class(NP2, Class).
tr_of_class(ell(_, _, _, _), _) :- !.
tr_of_class(name(_), Class) :- !, ( Class == name ; Class == person ), !.
%% ... and a pronoun is of the class the lesson says its word is of:
%% `representan a otros muchos' -- `"otros muchos" is a person.' -- and read
%% as a phrase of `to' the word before a person stayed, `a molti altri'
%% (a personal pronoun that stands as an object of its own is one: `vede lui e il gatto' is `ve a él y al gato')
tr_of_class(pronoun(w(W, _)), person) :- tr_side_here(english), memberchk(W, [him, her, them, me, us, you, 'you all']), !.
tr_of_class(pronoun(W), Class) :- !, tr_pronoun_of_lesson(W, P), G =.. [Class, P], tr_holds(G).
tr_of_class(co(_, A, B), Class) :- !, tr_of_class(A, Class), tr_of_class(B, Class).
%% ... AND A PERSON'S EMPHATIC REFLEXIVE IS ONE: `contraddire sé stesso' is to contradict himself, and Spanish puts
%% its `a' before it, `contradecir a sí mismo' -- with no noun of the lesson, the phrase was of no class
tr_of_class(np(_, _, _, w(W, _), _), person) :- atom(W), tr_side_here(Side), tr_reflexive_person(Side, W), !.
tr_of_class(np(_, _, _, W, _), Class) :- tr_noun_of_lesson(W, Noun), G =.. [Class, Noun], tr_holds(G).
%% ... AND A DEFINITE ANIMAL IS A PERSON FOR THE WORD BEFORE ONE: `Pedro ve al perro' sees the dog, and
%% read as a phrase of `to' it was `sees to the dog' (`"gato" is animate.'); an indefinite one is
%% not -- `preparar un "cocodrilo"' takes no `a' (a crocodile is also an obituary, `coccodrillo')
tr_of_class(np(det(_, _, D), _, _, W, _), person) :- tr_side_here(Side), \+ tr_indefinite(Side, D), tr_noun_of_lesson(W, Noun), tr_holds(animate(Noun)).

en_possessive_pronoun(hers).  en_possessive_pronoun(his).    en_possessive_pronoun(mine).
en_possessive_pronoun(yours). en_possessive_pronoun(ours).   en_possessive_pronoun(theirs).

%% a pronoun as the lesson's word, the same way as a noun (below)
tr_pronoun_of_lesson(w(PW, _), P) :-
    tr_side_here(Side),
    (   Side == foreign -> tr_lexeme(foreign, PW, P, _)
    ;   tr_lexeme(english, PW, L, _), tr_meanings_of(L, foreign, pronoun, [P|_])
    ), !.
%% a phrase's noun as the lesson's word: read on the lesson's side it is
%% the lexeme, read in English it is the lexeme's first meaning
tr_noun_of_lesson(w(NW, _), Noun) :-
    tr_side_here(Side),
    (   Side == foreign -> tr_lexeme(foreign, NW, Noun, _)
    ;   tr_lexeme(english, NW, L, _), tr_meanings_of(L, foreign, noun, [Noun|_])
    ), !.

%% the marker before an object out, in the lesson's language: `a Omar' --
%% never after the copula, whose complement is no object (`son nuestros
%% amigos')
tr_marker(foreign, What, [o(P, lower)]) :-
    \+ ( catch(nb_getval('$tr_verb', V), _, fail), ( memberchk(V, [is, none]) ; V = refl(_) ; en_copular(V) ) ),    % nor where there is no verb at all
    \+ tr_bare_plural(What),
    \+ ( What = np(_, none, [], w(LW, _), singular), en_language(LW), tr_global('$tr_verb', LV), en_language_verb(LV) ),
    tr_marker_word(P, Class), tr_of_class(What, Class), !.
tr_marker(_, _, []).
%% (the languages, and the verbs a language is the object of: `Studio
%% l'italiano' is `Estudio el italiano', where `italiano' is a person too and
%% it came out `Estudio al italiano')
en_language(L) :- memberchk(L, [italian, english, spanish, french, german, portuguese, catalan, neapolitan, latin, greek, russian, basque]).
en_language_verb(V) :- memberchk(V, [teaches, learns, studies, speaks, knows, understands, translates]).
%% ... NOR AFTER A VERB WHOSE COMPLEMENT SAYS WHAT THE SUBJECT IS: `potrebbe
%% diventare la Houston italiana' could become it, and with the city a name
%% and a name a person it came out `llegar a ser a la Houston'; `sembra un
%% bambino' seems one, and came out `parece a un niño'. English's words,
%% because the IR's verb is English's
en_copular(becomes).
en_copular(seems).
en_copular(remains).    % `Il regista favorito resta comunque Federico Fellini', `queda Federico Fellini'
%% ... nor before a bare plural, persons of no particular kind: `inserirà
%% tecnici o politici' is `insertará técnicos o políticos', and a person
%% named or determined keeps the word (`a los jugadores')
tr_bare_plural(np(none, none, _, _, plural)).
tr_bare_plural(co(_, A, B)) :- tr_bare_plural(A), tr_bare_plural(B).

%% the words of one phrase: up to the next preposition, adverb or object pronoun
%% A REDUCED RELATIVE AND ITS AGENT STAY INSIDE THE PHRASE, or the phrase
%% would end at the preposition and the agent would hang on the sentence's
%% verb instead of on the participle it belongs to.
%% A RELATIVE CLAUSE STAYS INSIDE ITS PHRASE AND RUNS TO THE END OF IT:
%% `contra "esos", que son culpables de "todo"', `el caldo que el pequeño
%% aprende en familia', `el grupo social al que pertenece'. The phrase's own
%% words end where a relative word starts (tr_phrase_words0/4 stops there),
%% and everything from that word on is the clause -- which is what the
%% `che'/`that' complement of 1.6.8 already does, for the reason it gives:
%% a shortest-first cut would end the clause at the first place that reads.
%% A RELATIVE CLAUSE ENDS AT THE COMMA OF A CONTRAST THAT HAS NO VERB: `no convence a nadie con
%% lo que dice, pero sí con lo que hace el Inter' -- the second `con' phrase is the sentence's,
%% set against the first, and read to the end of the clause it was the relative clause's
%% (`dice, but itself with what Inter makes'). The words after `, pero' (and `sí') open on a
%% preposition: a clause of its own would open on a verb
tr_contrast_cut(foreign, [w(R, RC)|Ws], [w(R, RC)|Clause], After) :-
    memberchk(comma, Ws), tr_relative_word(foreign, R),
    append(Clause, [comma, w(B, BC)|After0], Ws), Clause = [_|_], \+ memberchk(comma, Clause),
    atom(B), tr_solve(mean(B, but)),
    (   After0 = [w(Y, _), P|_], memberchk(Y, ['sí', 'sì']) -> true ; After0 = [P|_] ),
    tr_is(foreign, P, preposition), !,
    After = [comma, w(B, BC)|After0].
tr_phrase_words(Side, Words, PW, Rest) :-
    tr_phrase_words0(Side, Words, PW0, Rest0),
    (   PW0 \== [], Rest0 \== [], \+ tr_comparison_start(Side, Rest0), \+ tr_cmpc_start(Side, Rest0),
        ( tr_relative_start(Side, Rest0) -> true ; tr_clause_opener(Side, Rest0) )
    ->  (   tr_contrast_cut(Side, Rest0, Clause, After), append(PW0, Clause, PW), Rest = After
        ;   append(PW0, Rest0, PW), Rest = []
        %% ... OR THE PHRASE ALONE, where a preposition and the relative that
        %% follows one open a part with NO VERB: `quattro governi di cui solo
        %% uno ... uscito da elezioni generali' is four governments, of which
        %% only one came from elections -- read as a relative clause it had
        %% no verb and the sentence was refused, where the same words after
        %% a comma read (rpp/2). Asked only when the clause reading failed.
        ;   Rest0 = [P, w(R, _)|_], tr_is(Side, P, preposition), tr_rel_after_prep(Side, R),
            PW = PW0, Rest = Rest0
        %% ... OR THE PHRASE ALONE BEFORE A PREPOSITION AND A WORD THAT BEGINS THE RELATIVE, the free relative
        %% (tr_complements0/4): `para entregarlos en el ayuntamiento a quien correspondiera' -- to whoever it
        %% concerned, and the town council, no person, takes no `quien' (tr_np/3)
        ;   Side == foreign, Rest0 = [P, w(R, _)|_], atom(R), tr_is(Side, P, preposition), tr_solve(begin(R, relative)),
            PW = PW0, Rest = Rest0
        %% ... OR THE PHRASE ALONE BEFORE A PREPOSITION, AN ARTICLE AND THE
        %% RELATIVE WORD WHERE THE ARTICLE IS NOT IN THE PHRASE'S NUMBER: `a los
        %% 16.000 socios en la que se les insta' -- the clause is the letter's
        %% before them (rca/2)
        ;   Side == foreign, Rest0 = [P, D, w(R, _)|_], tr_is(Side, P, preposition),
            tr_determiner(Side, D, AL, article), tr_relative_word(Side, R),
            %% (the article's number is its ARTICLE reading's: `las' is the
            %% pronoun too, and asked any reading's the singular pronoun
            %% disagreed with `instrumentos' in Valencia's `de instrumentos,
            %% por las que el mejor ...', and the phrase alone was read there
            %% for 279 000 inferences more with the same text)
            D = w(DW, _), once(tr_lexeme(Side, DW, AL, DN)), last(PW0, w(HW, _)), atom(HW),
            once(tr_lexeme(Side, HW, _, HN)), HN \== DN,
            PW = PW0, Rest = Rest0
        %% ... OR THE PHRASE AND ITS CLAUSE UP TO A SECOND RELATIVE THAT OPENS
        %% ON AN ARTICLE: `de los ciudadanos que ofrecen estos inventos LO QUE
        %% los hace tan deseados' -- the clause ends where the phrase whose
        %% noun a relative clause stands for begins (tr_relative_clause/4).
        %% Asked only when the reading to the end failed.
        ;   Side == foreign, append(RC, [D, w(Q, QC)|After], Rest0), RC = [_, _|_], After \== [],
            tr_relative_word(Side, Q), ( tr_determiner(Side, D, _, article) -> true ; tr_noun_replacer(Side, D) ),
            append(PW0, RC, PW), Rest = [D, w(Q, QC)|After]
        %% ... OR THE PHRASE ALONE BEFORE A CLAUSE OF THE VERB'S: `descubrieron
        %% con cierta sorpresa QUE el telefonino ... estaba vacío' -- a phrase
        %% between the verb and the `that' clause it takes, where no relative
        %% clause reads (tr_relative_clause/4). Only a clause whose subject
        %% stands first, as a `that' clause's does: `dagli uomini del soccorso
        %% alpino e speleologico CHE LI hanno trovati vigili' is the men's
        %% relative clause with its subject left out, and taken for the verb's
        %% clause it read with the rest of Livata's sixth sentence as one
        %% statement, `despiertos y condiciones ... en bienes', before the
        %% division at `nonostante' was tried -- and only a PHRASE, with a
        %% noun: `si sa solo che la famiglia era ...' offered `solo' alone,
        %% and every reading of the rest was tried under it
        ;   Side == foreign, Rest0 = [T|After], tr_that_here(Side, T), tr_subject_first(After),
            once(( member(X0, PW0), tr_is(Side, X0, noun) )),
            PW = PW0, Rest = Rest0
        %% ... OR THE PHRASE WITHOUT THE COORDINATOR BEFORE THE RELATIVE WORD:
        %% `è un problema grave e che mi tormenta' -- a serious problem, and one
        %% that torments me. The coordinator joins the clause to what was said
        %% of the phrase, and the adjectives had ended on it, so read with the
        %% clause on the phrase the words were no phrase and the clause no
        %% complement (rcl/2 after cnj/1 reads it, tr_complements0/4) -- and
        %% only after an ADJECTIVE, which is what the clause is joined to:
        %% `la candidatura" y que "el presidente del Gobierno se alegra"' is
        %% a noun and a `that' clause, and the reading cost Solana's tenth
        %% sentence 0.65 million inferences to fail
        ;   Side == foreign, append(PW1, [C], PW0), PW1 \== [], C = w(_, _), tr_coord(Side, C),
            last(PW1, A1), tr_is(Side, A1, adjective),
            tr_relative_start(Side, Rest0),
            PW = PW1, Rest = [C|Rest0]
        )
    ;   PW = PW0, Rest = Rest0
    ).

%% a word that is a noun too, after a phrase that is a determiner and no
%% noun yet -- a NAME is a noun: `la inquietud del PNV ante el dictamen' ended
%% at `PNV', and `ante' is an elk too, so it was the phrase's noun and the
%% sentence was refused with every word known
tr_noun_after_det(Side, [D|Mid], R) :-
    tr_determiner(Side, D, _, _), tr_is(Side, R, noun),
    \+ ( member(X, Mid), tr_is(Side, X, noun) ),
    \+ member(w(_, upper), Mid), !.

%% an adverb at the head of a phrase and a number after it is the phrase's
%% own count, whatever else the word is: `con oltre 50 mezzi' is with more
%% than fifty, and `oltre' is a preposition too, which ended the phrase
%% before it began
tr_counting_adverb(Side, [], [A, M|_]) :-
    tr_is(Side, A, adverb), tr_is(Side, M, number),
    \+ tr_determiner(Side, M, _, _), !.          % `en conjunto UNOS 980': the article is no count
%% ... and so after the phrase's article: `ai circa 300 organi del Cnr' are the about 300 bodies, and `circa' is a
%% preposition too, which ended the phrase at its article -- the adverb was lifted out and written last, `to the 300
%% organs ... approximately' (tr_np/3 reads it as adv_num/2)
tr_counting_adverb(Side, [D], [A, M|_]) :-
    tr_determiner(Side, D, _, article), tr_is(Side, A, adverb), tr_is(Side, M, number),
    \+ tr_determiner(Side, M, _, _), !.

%% AN ARTICLE AND A `de' PHRASE WITH NO NOUN BETWEEN THEM ARE ONE PHRASE:
%% `en los de clase media' -- in those of the middle class. The article
%% stands for a noun the sentence already said, and the preposition belongs
%% to it; without this the phrase ended at the preposition and was the
%% article alone, which reads as the object pronoun `los'.
%% a determiner and a QUOTED RUN with a word no lesson knows are one phrase
%% to the run's closing mark (tr_np/3's named run): `el "ja sóc aquí" de
%% Tarradellas' ended at `aquí', an adverb
%% (the checks before the cut: a run of words the lesson knows is an
%% ordinary phrase in marks, `los "personajes singulares"', and cut here it
%% had no reading at all)
%% A RATIO IS ONE PHRASE, whole, where a phrase's words are cut (tr_np/3 has
%% the ratio): `Resta nell'indigenza un nucleo ogni venti' ended the phrase
%% at `un nucleo' and read `ogni venti' as one of its own, each winds.
%% (never with an article for the ratio's word: `una delle quattro squadre' is one of the four
%% teams, `una di le quattro' with its noun after the count, and not one in four)
%% THE WORD FOR `more' AS A DETERMINER, BEFORE A NOUN THAT IS NO ADJECTIVE, ENDS NO PHRASE AS A PREPOSITION: `recomendó
%% al PNV "más deportividad"' recommended more sportsmanship to the PNV -- `más' is the preposition `plus' too, and
%% asked as one it ended the phrase of `to' and began one with no phrase of its own, and the words had no reading
tr_more_determiner(foreign, [R, N1|_]) :-
    R = w(MW, _), atom(MW), tr_gen_words(degree, Ds), memberchk(MW, Ds), tr_determiner(foreign, R, _, _),
    N1 = w(_, _), tr_is(foreign, N1, noun), \+ tr_is(foreign, N1, adjective).
tr_phrase_words0(foreign, [D, N, R, M|Rest], [D, N, R, M], Rest) :-
    tr_ratio_count(M), D = w(_, _), tr_indefinite(foreign, D), \+ tr_determiner(foreign, R, _, article),
    tr_np(foreign, [D, N, R, M], ell(_, _, _, pp(_, _))), !.
tr_phrase_words0(foreign, [D, w(W1, qopen)|Ws], [D, w(W1, qopen)|Run], Rest) :-
    tr_determiner(foreign, D, _, _),
    append(Run, Rest, Ws), Run = [_|_], last(Run, w(_, qclose)),
    once(( member(w(U, _), [w(W1, qopen)|Run]), \+ tr_known_word(foreign, U) )), !.
%% ... and a determiner, `more than' and an adjective are the head of one
%% phrase (tr_intensify/3's mti/1): `en el más que probable caso' ended at
%% `más', a preposition too, and `que' opened a relative clause
tr_phrase_words0(Side, [D, M, Q, J|Ws], [D, M, Q, J|PW2], Rest) :-
    tr_more_than(Side, M, Q, J), tr_determiner(Side, D, _, _),
    tr_phrase_words0(Side, Ws, PW2, Rest), PW2 \== [], !.
tr_phrase_words0(Side, [D, P|Ws], [D, P|PW2], Rest) :-
    ( tr_determiner(Side, D, _, article), \+ tr_standalone_det(Side, D) -> true ; tr_noun_replacer(Side, D) ),
    tr_is(Side, P, preposition), ( tr_means_of(Side, P) -> true ; tr_indefinite(Side, D) ),
    tr_phrase_words0(Side, Ws, PW2, Rest), PW2 \== [], !.
%% ... a phrase and the quoted title after it (tr_np/3's title): `il tema
%% "spazio al tuo futuro"', to the title's closing mark. The first opening
%% mark and the first closing one after it, each found with once/1 and not
%% behind a cut: a cut there committed the whole of tr_phrase_words0/4 to a
%% title before the phrase before it was asked, so `martedì il corso
%% "missioni ..."' -- a time first, then the course -- had no phrase words
%% at all and the sentence was refused. An aside set off after the title is
%% the phrase's too (tr_np/3 takes it off the end): `con il corso "missioni
%% umane nello spazio", il primo del genere in Europa, che sarà tenuto ...'
%% ended at the title, and the key left after it read as nothing
tr_phrase_words0(foreign, Words, PW, Rest) :-
    tr_title_words(Words, PW, Rest), !.
%% ... a phrase, `da', its agent of one word and the participle after it
%% (tr_np/3's agent before its participle): `la tuta da lui usata'
tr_phrase_words0(foreign, Words, PW, Rest) :-
    nb_getval('$tr_agent_first', yes),
    once(( member(B0, Words), B0 = w(_, _), tr_means_by(foreign, B0) )),
    append(Core, [B, A1, w(P, PC)|Rest], Words), Core = [_|_], \+ memberchk(comma, Core),
    B = w(_, _), tr_means_by(foreign, B), tr_is(foreign, B, preposition),
    \+ ( member(Q, Core), ( tr_is(foreign, Q, preposition) ; tr_is(foreign, Q, verb) ),
         \+ tr_is(foreign, Q, noun), \+ tr_is(foreign, Q, adjective) ),
    tr_lone_agent(A1, _), tr_participle_here(foreign, P, _),
    append(Core, [B, A1, w(P, PC)], PW),
    tr_np(foreign, PW, rel(_, _, _)), !.
tr_phrase_words0(Side, Words, PW, Rest) :-
    append(PW0, Rest0, Words), PW0 \== [],
    last(PW0, w(P, _)), tr_participle_here(Side, P, _),
    %% ... a participle closing a phrase with no preposition in it: `la
    %% partecipazione del 41,5% detenuta dal fondo' is the share and then
    %% what holds it, and taken whole it was one phrase with a phrase of `di'
    %% inside, which no phrase reads, so the sentence was refused
    %% -- and no VERB before the participle either: `I piccoli sono stati
    %% raggiunti dagli uomini ...' is a clause, and it was asked as a phrase
    %% once for every place a verb could start after it -- each time reading
    %% the agent and, since the agent may take adjuncts, the rest of that
    %% region as complements: 8.5 million inferences to 16.2 for Livata's
    %% sixth sentence, and 8.0 with this
    append(Front, [_], PW0),
    %% ... and no COMMA, which ends a phrase as it does below: `una escena,
    %% la más esperada por los aficionados' ran on to the participle and
    %% was one phrase with a comma in it, which no phrase reads
    \+ memberchk(comma, Front),
    \+ ( member(Q, Front), ( tr_is(Side, Q, preposition) ; tr_is(Side, Q, verb) ),
         \+ tr_is(Side, Q, noun), \+ tr_is(Side, Q, adjective) ),
    %% -- and a participle the lesson calls a noun too, with no noun before
    %% it, is the phrase's NOUN: `i risultati dell'autopsia che verrà
    %% effettuata dal medico legale' are the results of the autopsy, and
    %% `risultati' is also what `risultare' says of several things, so the
    %% whole of it was one phrase closed by a participle with its agent, the
    %% other readings cut away, and the sentence refused
    \+ ( tr_is(Side, w(P, lower), noun), \+ ( member(Q, Front), tr_is(Side, Q, noun) ) ),
    %% (or a day, a time or an adverb before the agent: `in una intervista trasmessa giovedì sera dalla tv danese' was
    %% broadcast on Thursday evening BY it, and with the phrase ended at the participle the agent was a phrase of
    %% `from' -- the word for `by' within the next two words, as tr_reduced_agent/3 reads them)
    Rest0 = [B|_], ( tr_is(Side, B, preposition) -> true ; tr_time_before_agent(Side, Rest0) ),
    %% (the agent first, or after adjuncts: `efectuado a principios del
    %% pasado mes de mayo por el Consell Executiu' -- tr_reduced_agent/3)
    %% ... AND ENDING AT A COMMA, where what follows it is no part of the agent:
    %% `de esos lagrimones vertidos por la elegida, en este caso la india Yukta
    %% Mookhey' -- read to the end of the words the agent could not be read, the
    %% participle's phrase ended before `por', and the agent was a phrase of
    %% `for', `poured big tears for the chosen one'
    (   RestA = Rest0, Tail = []
    ;   append(RestA, [comma|Tail0], Rest0), RestA = [_|_], \+ memberchk(comma, RestA), Tail = [comma|Tail0]
    ),
    (   tr_means_by(Side, B) -> tr_reduced_agent(Side, RestA, _)
    ;   once(( member(B2, RestA), B2 = w(_, _), tr_means_by(Side, B2) )),
        tr_reduced_agent(Side, RestA, Cs0), memberchk(by(_), Cs0)
    ), !,
    append(PW0, RestA, PW), Rest = Tail.
tr_phrase_words0(Side, Words, PW, Rest) :-
    append(PW, Rest, Words),
    (   Rest == []
    ->  true
    ;   Rest = [R|_],
        (   R == comma
        %% who said so, set aside (w(Key, per)), ends the phrase before it
        ;   R = w(_, RK), ( RK == per ; RK == perh )
        ;   PW \== [], tr_relative_start(Side, Rest)
        %% a gerund ends the phrase before it: `a un inmigrante utilizando un
        %% bate' is the phrase and then how it was done
        ;   PW \== [], R = w(G, _), tr_gerund_here(Side, G, _), \+ tr_is(Side, R, noun)
        %% ... and so does a purpose word before its infinitive, which may be
        %% no preposition: `abierto a cualquier negociación CON EL FIN DE
        %% encontrar una solución' ran the phrase on through the purpose
        ;   PW \== [], Side == foreign, R = w(PR, _), atom(PR), tr_purpose_word(PR),
            Rest = [_, w(V1, _)|_], atom(V1), tr_solve(infinitive_of(V1, _))
        %% ... and so does a participle before a phrase it agrees with (abs/2)
        ;   PW \== [], tr_absolute_start(Side, Rest)
        %% ... and so does an infinitive: `è stato difficile riprenderli' is
        %% an adjective and then what was difficult, never one phrase
        %% (but not right after an article, which makes a noun of it: `la
        %% materia del contendere' -- ninf/1, tr_np/3)
        ;   PW \== [], tr_starts_infinitive(Side, Rest), \+ tr_is(Side, R, noun),
            \+ ( last(PW, LD), LD = w(_, _), tr_determiner(Side, LD, _, article) )
        %% ... and a question word: `all'ospedale di Subiaco DOVE i medici'
        ;   PW \== [], R = w(QW, _), tr_indirect_word(Side, QW, _)
        %% ... and the word of a clause of comparison (tr_cmpc_start/2): `meno
        %% della metà DI QUANTO spende l'italiano'
        ;   PW \== [], Side == foreign, tr_cmpc_start(Side, Rest)
        %% ... and a coordinator before a denial: `che duri 5 anni E NON due
        %% mesi' -- the second half is denied (neg/1), and read on to the
        %% denial the phrase was `5 anni e', which no phrase reads
        ;   PW \== [], Side == foreign, Rest = [_, w(N, _)|_], atom(N), tr_negation_word(N), tr_coord(Side, R)
        %% ... and a coordinator before a phrase with the word for `no' after
        %% it, at the end of the words: `le sapessero i dotti E i semplici no'
        %% -- the simple did not (nega/1), and read on the phrase was the
        %% learned and the simple both, with `no' an adverb of the clause
        ;   PW \== [], Side == foreign, Rest = [_|R1], R1 = [_, _|_], tr_coord(Side, R),
            last(R1, w(NA, _)), atom(NA), tr_no_word(NA)
        %% ... and a coordinator before a comma, which opens an insertion
        %% before the second half: `sul contatto diretto con la gente E,
        %% soprattutto, su un comportamento' -- read on to the comma the
        %% phrase was `la gente e', which no phrase reads
        %% -- where what follows the insertion may follow a coordinator:
        %% `tutta la notte e, oltre ai cani molecolari, sono stati utilizzati
        %% ...' opens a clause of its own, and ended at `e' the phrase cost
        %% Livata's twenty-ninth sentence 2 % more for the same text
        ;   PW \== [], Rest = [_|R1], R1 = [comma|_], R = w(_, _), tr_coord(Side, R), tr_after_coord(Side, R1)
        %% ... except a `de' after a coordinator and an article, which is
        %% the second half's own: `el pan de los gatos y el de los chicos'
        %% ended at the second `de' and left `el' as a phrase of one article
        ;   tr_is(Side, R, preposition), \+ tr_counting_adverb(Side, PW, Rest), \+ tr_date_inside(Side, PW, Rest),
            \+ tr_more_determiner(Side, Rest),
            \+ tr_final_adjective(Side, PW, Rest),
            \+ ( tr_means_of(Side, R), append(_, [Co, LA], PW),
                 tr_coord(Side, Co), tr_determiner(Side, LA, _, article), \+ tr_standalone_det(Side, LA) ),
            %% ... nor a word that is a NOUN too, after a determiner and before
            %% the phrase has a noun: `optó por una vía más instintiva' is a
            %% way, and `vía' is also the preposition `via', which ended the
            %% phrase at `una'
            %% -- but not the word for `to' before an infinitive, which is that
            %% preposition: `sono l'unico ad aver consigliato l'Egibren' is the
            %% only one to have advised it, and `ad' is the chief executive
            %% (the line that writes `AD') too, so the phrase ran on over it
            \+ ( tr_noun_after_det(Side, PW, R), \+ ( Side == foreign, Rest = [w(RW0, _)|After], atom(RW0), tr_means_to(RW0), tr_starts_infinitive(Side, After) ) )
        ;   tr_plain_adverb(Side, R), \+ tr_counting_adverb(Side, PW, Rest),
            \+ tr_final_adjective(Side, PW, Rest),
            %% ... nor an adjective right after the noun it agrees with and
            %% before its `of' phrase (tr_adjective_before_of/3)
            \+ tr_adjective_before_of(Side, PW, Rest),
            %% ... but not a word that is an ADJECTIVE too while the phrase has
            %% no noun yet: `fin dalle prime ore' is the first hours, and
            %% `prime' is also `before' -- the phrase ended at its article
            \+ ( tr_is(Side, R, adjective), \+ ( member(X0, PW), tr_is(Side, X0, noun) ) ),
            %% ... nor an adjective with the adjectives' own comma after it
            %% (tr_adj_lists/3): `un uomo alto, snello, scuro' is tall and the
            %% rest, and ended at `uomo', `alto' was the clause's `high'
            %% -- or with a coordinator and an adjective after it: `un uomo
            %% alto e snello' was a man, high, and slender
            \+ ( Rest = [_, w(',', acomma)|_], tr_is(Side, R, adjective) ),
            \+ ( Rest = [_, Co1, J1|_], Co1 = w(_, _), tr_coord(Side, Co1), J1 = w(_, _),
                 tr_is(Side, J1, adjective), tr_is(Side, R, adjective) ),
            %% ... nor the second of two adjectives before their noun, right after the coordinator
            %% that joins them: `un largo y duro periodo' is a long and hard period, and `duro' is
            %% an adverb too (hard) -- the phrase ended at `y', `un largo' was a long one, and
            %% `duro' the clause's adverb
            \+ ( append(_, [A0, Co0], PW), Co0 = w(_, _), tr_coord(Side, Co0), A0 = w(_, _), tr_is(Side, A0, adjective),
                 tr_is(Side, R, adjective), Rest = [_, N0|_], N0 = w(_, _), tr_is(Side, N0, noun) ),
            %% ... nor a NOUN too, right after a determiner: `solo la via della
            %% mediazione' is the way, and `via' is also `away' -- the
            %% phrase ended at `la', which was then the pronoun `her'
            \+ tr_noun_after_det(Side, PW, R),
            %% ... nor a NOUN too that the phrase reads as its head with the words
            %% before it: `al terzo piano' is on the third floor, and `terzo' is a
            %% noun too (a third), so the phrase had its noun and `piano' -- the
            %% adverb `slowly' -- was the clause's: `vivo al tercio despacio'
            %% -- AFTER AN ORDINAL ONLY: the guard with any word before the noun
            %% took `ancora oggi' for one phrase (`ancla hoy'), `più tardi' for
            %% `more afternoon' and `dietro anche' for `behind hips', every adverb
            %% that is a noun too after a word that leaves it room to be one
            \+ ( tr_is(Side, R, noun), last(PW, w(OW, _)), atom(OW), tr_ordinal_word(Side, OW),
                 append(PW, [R], PWR), tr_np(Side, PWR, np(_, _, _, R1, _)), R1 == R ),
            %% ... nor an adverb with the phrase's PARTICIPLE after it (tr_np/3
            %% reads the pair): `sesiones a puerta cerrada centradas en ...'
            \+ tr_adverb_before_participle(Side, PW, Rest),
            %% ... nor the word for `more' between an article and a participle, the
            %% noun left out (tr_np/3's degree before a participle): `è stata fra le
            %% più eseguite' is among the most performed, and the phrase of `fra'
            %% ended at its article, which read as nothing
            \+ ( Side == foreign, PW = [D1], D1 = w(_, _), tr_determiner(Side, D1, _, article),
                 Rest = [w(M1, _), w(P1, _)|_], tr_degree_word(M1), atom(P1), tr_participle_here(Side, P1, _) ),
            %% ... nor one between a determiner and its noun (tr_noun_adverb/4):
            %% `del todavía editor', `el entonces presidente'
            \+ ( last(PW, LD), LD = w(_, _), tr_determiner(Side, LD, _, _),
                 Rest = [_, N1|_], N1 = w(_, _), tr_is(Side, N1, noun) ),
            %% ... nor a DETERMINER that is an adverb too, before a noun in its
            %% number: `con tanto eroismo' is with so much heroism, and `tanto'
            %% is also `as' -- the phrase ended before it, the preposition took
            %% the adverb for its object and the heroism was a second object
            \+ tr_determiner_before_noun(Side, Rest)
        %% an object pronoun ends a phrase that has begun; at its head it IS
        %% the phrase, which is reached only when the pronoun readings above
        %% stood down for a relative clause after it (`contra esos, que son')
        ;   PW \== [], tr_object_pronoun_here(Side, Rest),
            \+ ( last(PW, LW0), tr_coord(Side, LW0) ),    % `sopas y otros': the pronoun is the second half
            \+ ( last(PW, LD0), tr_determiner(Side, LD0, _, article) ),   % `l'altra': an article is no phrase alone
            %% ... nor a plural personal pronoun after `all': `per tutti noi'
            %% is one phrase, all of us (tr_np/3's all/2 with a pronoun)
            \+ ( last(PW, w(AT0, _)), atom(AT0), tr_all_word(Side, AT0), Side == foreign,
                 Rest = [w(P0, _)|_], tr_all_person(P0) )
        %% ... AND A DETERMINER AFTER A PHRASE THAT ALREADY HAS ITS NOUN
        %% STARTS THE NEXT ONE. `mettere in pericolo LA casa' -- the
        %% infinitive's phrase is `pericolo' and the object is `la casa',
        %% and with no boundary here the three words were one phrase with
        %% an article among its adjectives and the sentence was refused.
        %%
        %% THE NOUN IS WHAT MAKES IT SAFE, and a plain `PW \== []' was not:
        %% `dal suo quartier generale' cut after `il', which is a phrase of
        %% one article, and a sentence that read before stopped reading.
        %% A determiner before this phrase's noun is this phrase's own.
        %%
        %% AND NOT AFTER A CONJUNCTION, which the case caught at once: `el
        %% pan y el huevo' cut before the second `el' and wrote `el y pan
        %% el huevo'. A determiner after `y' opens the second half of a
        %% phrase the splitter is about to take apart, not a new phrase.
        %% -- a NUMBER last in the phrase is a noun for that too: `concentrando en
        %% 1999 el 17,1% del total', `se estima en 45 el número de empresas' --
        %% a year, or a count with its noun left out, and read on through the
        %% article `1999 el 17,1%' was one phrase and the sentence refused
        ;   PW \== [], tr_determiner(Side, R, _, _),
            %% ... but a word that is an ADJECTIVE too starts one only with a
            %% word after it for it to head: `con due persone diverse' is
            %% different people, and `diverse' is `several' as well -- cut
            %% there, it was an adjective of the clause's own and agreed with
            %% the subject, `dos personas diverso'
            \+ ( tr_is(Side, R, adjective), \+ ( Rest = [_, N0|_], N0 = w(_, _), \+ tr_is(Side, N0, preposition) ) ),
            %% ... nor a determiner that is an ADVERB too, with the phrase's
            %% participle after it: `su comportamiento POCO civilizado' is
            %% behaviour little civilised, and `poco' is `few' as well -- cut
            %% there, the participle was said of the sentence's subject and
            %% agreed with it, `poco civilizzati' (tr_np/3 reads the pair, as
            %% it reads `muy civilizado')
            \+ ( tr_is(Side, R, adverb), tr_adverb_before_participle(Side, PW, Rest) ),
            member(X, PW), ( tr_is(Side, X, noun) ; tr_name_like(Side, X) ; last(PW, X), tr_is(Side, X, number) ),
            \+ ( last(PW, LW), tr_coord(Side, LW) ),
            \+ ( last(PW, LP), tr_is(Side, LP, preposition) ),  % `y el de LOS chicos'
            %% ... nor `all' before its determiner, the phrase's own (all/2):
            %% `Giovanni e tutti gli amici' ended at `tutti', the pronoun for
            %% everyone, and `gli amici' was a second object
            \+ ( last(PW, w(AT, _)), atom(AT), tr_all_word(Side, AT) )
        %% ... A NAME IS A PHRASE'S NOUN FOR THAT, and a number after one starts
        %% the next phrase too: `acquisirà da Veba LA partecipazione' and
        %% `verserà a Veba 3,65 miliardi' put a short phrase with its
        %% preposition before the object, and the name no lesson knows was no
        %% noun to end at -- so `Veba la partecipazione' was one phrase with
        %% an article among its adjectives, and the sentence was refused
        ;   PW \== [], last(PW, LN), tr_name_word(Side, LN), tr_is(Side, R, number)
        %% ... AND SO IS A NUMBER WITH A NOUN OF ITS OWN AFTER A NOUN: `ho visto
        %% il cane due anni fa', `il cane tre volte' -- `cane' is an adjective
        %% too (bad), and read on, `due anni' was the dog's: the two dog years.
        %% The number is the next phrase's count. `il capitolo due' has no noun
        %% after the number and stays one phrase
        ;   PW \== [], tr_is(Side, R, number), Rest = [_, N1|_], N1 = w(_, lower), tr_is(Side, N1, noun),
            last(PW, LN1), LN1 = w(_, _), tr_is(Side, LN1, noun), \+ tr_is(Side, LN1, number)
        %% ... and an ADJECTIVE after a name is no part of its phrase: `Capri,
        %% Procida, Ischia, Giglio, Eolie e Ponza off limits per i turisti' is
        %% the islands and then what they are, a clause with its verb left
        %% out, and the name with the adjective after it read as no phrase
        %% (a quoted one too: `un artículo de Aznar "nostálgico del franquismo"'
        %% is an article by Aznar, nostalgic of Francoism in the writer's
        %% marks -- read on, `Aznar "nostálgico"' was a name and a quoted
        %% word, which no phrase reads, and the sentence was refused)
        ;   PW \== [], last(PW, LN2), tr_name_word(Side, LN2), R = w(_, RC2), memberchk(RC2, [lower, qboth, qopen]),
            tr_is(Side, R, adjective), \+ tr_is(Side, R, noun),
            %% ... unless the name is APPOSED to a noun after a determiner:
            %% `il governo Dini successivo' is one phrase, the government that
            %% came after, and tr_apposed_name/3 reads the adjective there
            \+ ( PW = [D5|_], tr_determiner(Side, D5, _, _),
                 member(N5, PW), N5 \== LN2, tr_is(Side, N5, noun) ),
            %% ... or the name stands right after its determiner: `la Barcelona
            %% olímpica' and `l'Italia attuale' are one phrase, the city as it
            %% was (tr_np/3's adjectives after a name), and cut after the name
            %% the adjective was a predicate of the clause, agreeing with its
            %% subject -- `della Barcelona olimpici'
            \+ ( PW = [D6|Names6], Names6 = [_|_], tr_determiner(Side, D6, _, _),
                 forall(member(N6, Names6), tr_name_word(Side, N6)) )
        %% ... AND A TITLE BEFORE A NAME STARTS THE NEXT PHRASE: `di Monreale
        %% monsignor Salvatore Cassisa' is the place and then the person, the
        %% title taking no article to say so (tr_np/3's title clause)
        ;   PW \== [], R = w(TW, _), Rest = [_, w(_, upper)|_], tr_title_word(Side, TW),
            member(X1, PW), ( tr_is(Side, X1, noun) ; X1 = w(_, upper) )
        %% ... AND A NOUN IN THE OTHER NUMBER, AFTER A PHRASE THAT HAS ITS
        %% NOUN, BEGINS THE NEXT PHRASE: `portando a conoscenza di un comitato
        %% etico TEMPI e modi della terapia' is the committee, and then the
        %% times and ways it is told of. With no boundary `tempi' -- a word
        %% the lesson knows only as a noun -- was an adjective of `comitato'
        %% and came out `un templo comité'. An adjective agrees with its noun,
        %% so a word that is no adjective and has no form in the phrase's
        %% number is no part of it. Only on the lesson's side: English puts a
        %% noun of either number before its head (`the university students').
        %% -- and never across a coordinator, which joins two phrases the
        %% splitter takes apart: `pan y huevos' cut before `huevos'
        ;   Side == foreign, PW \== [], R = w(RW, _), tr_is(Side, R, noun), \+ tr_is(Side, R, adjective),
            \+ ( member(CW, PW), tr_coord(Side, CW) ),
            %% (and no name the lesson says is one: `el grupo Metrópolis')
            \+ tr_name_word(Side, R),
            member(w(XW, XC), PW), tr_is(Side, w(XW, XC), noun),
            findall(XN0, tr_lexeme(Side, XW, _, XN0), XNs0), sort(XNs0, [XN]),
            \+ tr_lexeme(Side, RW, _, XN),
            %% ... nor the tail of a NAME with its `of' left out: `l'associazione
            %% nazionale magistrati' is one phrase (tr_np/3's nmodp/1)
            \+ ( PW = [_, _, _], append(PW, [R], NameWords), tr_np(Side, NameWords, np(_, _, [_, nmodp(_)], _, _)) )
        %% ... and after a run of ADJECTIVES with no noun, which is a
        %% predicate: `sono stati eroici UN'intera notte' is heroic, and then
        %% for how long -- read as one phrase it had an article among its
        %% adjectives and no reading at all
        ;   PW \== [], tr_determiner(Side, R, _, article), \+ tr_standalone_det(Side, R),
            tr_all_adjectives(Side, PW), \+ ( last(PW, LW2), tr_coord(Side, LW2) )
        %% ... and a coordinator before a PREPOSITION joins two complements,
        %% not two halves of this phrase: `en los barrios de la ciudad y en
        %% los de clase media' -- read as one phrase, `y' was an adjective of
        %% `ciudad' and came out `of the and city'
        ;   PW \== [], tr_coord(Side, R), Rest = [_, P2|_], tr_is(Side, P2, preposition)
        %% ... and so does one before a participle standing alone: `delle
        %% coperte e affidati al 118' is the blankets, and then entrusted
        ;   PW \== [], tr_coord(Side, R), Rest = [_, w(P4, C4)|_], tr_participle_here(Side, P4, _),
            \+ tr_is(Side, w(P4, C4), adjective), \+ tr_is(Side, w(P4, C4), noun)
        %% ... and so does a conjunction before an INFINITIVE: `un fax e
        %% invocare il sostegno' is the object and a second infinitive
        %% under the same purpose, never one phrase with `e' in it -- which
        %% is what the phrase splitter's `A e B' made of it, and it refused
        %% the sentence because the second half is no phrase.
        ;   Rest = [_|More], tr_coord(Side, R), tr_starts_infinitive(Side, More)
        %% ... and one before an ADVERB that one of those follows: `chiedere
        %% aiuto MA POI di essersi persa' is help, and then the other thing
        %% she said -- read as one phrase, `ma' was an adjective of `aiuto'
        ;   PW \== [], Rest = [_, A3|More3], tr_coord(Side, R), tr_is(Side, A3, adverb), \+ tr_is(Side, A3, adjective),
            tr_after_coord(Side, [A3|More3]),
            %% (but adverbs and an ADJECTIVE after the coordinator are the
            %% phrase's own: `es persona ocupada y a veces maleducada' is a
            %% busy and sometimes rude person, and ended at `y' the adjective
            %% agreed with the subject, `maleducato'. After a comma they say
            %% more of the phrase before it, which the complement reader reads)
            \+ tr_adverbs_adjective(Side, [A3|More3])
        %% ... and one before an ADJECTIVE THE NOUN BEFORE IT DOES NOT AGREE
        %% WITH: `tramos de acera de distintas anchuras e incómodos para el
        %% tránsito' -- the stretches are what is uncomfortable, and
        %% the adjective is no part of `acera' (tr_postposed_adjective/2)
        ;   PW \== [], Side == foreign, tr_coord(Side, R), Rest = [_|More4], tr_postposed_adjective(PW, More4)
        ),
        %% asked only where a boundary was found, and not at every word
        \+ tr_degree_start(Side, Rest),             % `el más débil': `más' is a preposition too
        \+ ( Side == foreign, tr_focus_adj_start(PW, Rest) ),
        \+ tr_degree_before_participle(Side, PW, Rest)   % `una adhesión más limitada'
    ), !.
%% (a day, a time or an adverb, one word or two, and then the word for `by')
tr_time_before_agent(Side, [T|Ws]) :-
    T = w(TW, _), atom(TW), ( tr_time_word(Side, TW) ; tr_plain_adverb(Side, T) ), !,
    ( Ws = [B|_] ; Ws = [_, B|_] ), B = w(_, _), tr_means_by(Side, B), !.

%% an object pronoun standing as one: not an article or a possessive with
%% its noun after it -- `la casa', `los libros', English's `her house'
tr_object_pronoun_here(Side, [w(W, _)|Ws]) :-
    tr_object_pronoun(Side, W, _),
    \+ ( tr_determiner(Side, w(W, lower), _, K), Ws = [N|_], tr_content_word(Side, N),
         %% ... a POSSESSIVE before a pronoun is none: `non importa loro
         %% null'altro' is to them, nothing else -- `nulla' is also the
         %% adjective `invalid', and `loro' was their nothing
         \+ ( K == possessive, tr_is(Side, N, pronoun) ) ),
    \+ ( tr_determiner(Side, w(W, lower), _, article), tr_article_holds(Side, Ws) ),
    \+ ( tr_all_word(Side, W), Ws = [D|_], tr_determiner(Side, D, _, _) ),
    %% (nor before a plural personal pronoun: `per tutti noi', tr_np/3)
    \+ ( Side == foreign, tr_all_word(Side, W), Ws = [w(P, _)|_], tr_all_person(P) ),
    %% (nor before a bare plural noun: `desde todas direcciones', tr_np/3,
    %% nor a bare singular one: `con tutta evidenza')
    \+ ( tr_all_word(Side, W), Ws = [N|_], N = w(NW, _), atom(NW), tr_is(Side, N, noun),
         tr_lexeme(Side, NW, _, _) ).

%% AN ARTICLE BEFORE A POSSESSIVE, OR BEFORE THE WORD FOR `very' AND AN
%% ADJECTIVE, IS THE ARTICLE: `stanno valutando le loro condizioni' is their
%% conditions, `con le pesantissime accuse' the very heavy accusations (the
%% tokeniser unfolds the superlative, tr_expand/3), `dalle loro funzioni'
%% from their functions. Neither word after it is a content word, and with
%% `The dative pronoun "le" means "her".' in the lesson -- for `Ma non le
%% pare che ...?' -- the article was the pronoun: `le están evaluando sus
%% condiciones', `con ella muy pesadas acusaciones'. It was older than that
%% line: `la loro condizione' and `con la pesantissima accusa' read the
%% article `la' as `her' on 1.8.19 too. A clitic stands before its verb,
%% never between a verb and its object, and never after a preposition.
%% (its own name: tr_article_before/2 is taken, by the rule that a
%% preposition and its article are followed by no verb, and two clauses
%% added to it under the same name made `\+ tr_article_before' fail for a
%% possessive -- `My house is big.' was refused, and nothing warned)
tr_article_holds(Side, [N|_]) :- tr_determiner(Side, N, _, possessive), !.
tr_article_holds(Side, [A, J|_]) :- A = w(_, _), tr_is(Side, A, adverb), tr_is(Side, J, adjective), !.
%% ... AND SO IS ONE BEFORE A PARTICIPLE AND A NOUN: `si concentra l'imbarazzato interesse dei presenti' is
%% the embarrassed interest -- the participle is no content word, and read as the pronoun `lo' and a predicate
%% the interest came out a bare object, `concentrates him embarrassed interest'
tr_article_holds(foreign, [P, N|_]) :-
    P = w(PW, _), atom(PW), tr_participle_here(foreign, PW, _), N = w(NW, _), atom(NW), tr_is(foreign, N, noun), !.
%% AN ARTICLE AND A NOUN IN ITS NUMBER WITH A WORD MEANING `of' AFTER IT ARE A
%% PHRASE, NEVER A CLITIC AND A VERB: `il dolore e le accuse della madre' is
%% the mother's accusations -- `accuse' is the plural of `accusa', which the
%% lesson states as a noun and as a verb alike, and read as the verb's plural
%% it was THEY accusing her of the mother. A verb group is refused where it
%% opens on such a noun right after the article
tr_article_noun_of(foreign, Words, Before, After) :-
    last(Before, w(D, _)), atom(D), tr_determiner(foreign, w(D, lower), _, article),
    append(Before, [G|_], Words), G = w(GW, _), atom(GW), tr_is(foreign, G, noun),
    After = [P|_], P = w(_, _), tr_means_of(foreign, P),
    tr_lexeme(foreign, D, _, Num), tr_lexeme(foreign, GW, _, Num), !.
%% ... AND AN ARTICLE AND AN ADJECTIVE BEFORE A WORD THAT IS A NOUN TOO, all
%% of one number, are one phrase: `nonostante la grande diversità fra i due
%% personaggi e i rispettivi programmi' read `programmi' as a verb, `i
%% rispettivi' (the respective ones) its subject's last phrase, and the
%% programmes were written `los respectivos programa'
tr_noun_after_adjective(foreign, Words, Before) :-
    append(_, [D, A], Before), D = w(DW, _), atom(DW), tr_determiner(foreign, D, _, article),
    A = w(AW, _), atom(AW), tr_is(foreign, A, adjective), \+ tr_is(foreign, A, noun),
    append(Before, [G|_], Words), G = w(GW, _), atom(GW), tr_is(foreign, G, noun),
    tr_lexeme(foreign, DW, _, Num), tr_lexeme(foreign, GW, _, Num), !.
tr_content_word(Side, N) :- ( tr_is(Side, N, noun) ; tr_is(Side, N, adjective) ; tr_is(Side, N, number) ), !.
%% ... and so is an adjective the complements were folded to a degree of
%% before this is asked: `Eres la mejor', `Eres la más buena' are the best
%% one, and read as the pronoun `la' they came out `You are her better'
tr_content_word(_, deg(_, _)) :- !.
tr_content_word(_, degt(_, _, _)) :- !.
%% ... and so is the lesson's word for `more' before a participle it has
%% not folded: `la más esperada por los aficionados' is the most awaited one
tr_content_word(foreign, w(M, _)) :- tr_degree_word(M), !.
%% ... and so is a NAME: `dalla Fim Cisl' is `da', the article and the
%% union's name, and read as the pronoun `la' before a stranger it came out
%% `desde ella Fim Cisl'
tr_content_word(Side, N) :- tr_name_word(Side, N), !.

%% a word that means `all': English's own, or one the lesson gives
%% (KEPT FOR THE SENTENCE (tr_memo/4), as a coordinator is: the verb group
%% finder asks it at every place a group can start, and the phrase reader
%% and the object pronoun of every word they meet. Asked of the lesson each
%% time, a lexeme and a meaning a word, it was a fifth of what this version
%% first cost the controls in inferences.)
tr_all_word(english, all) :- !.
tr_all_word(foreign, T) :- atom(T), tr_language(G), tr_memo(allw(G, T), x, tr_all_word0(T), [_|_]), !.
tr_all_word0(T) :- tr_lexeme(foreign, T, L, _), tr_solve(mean(L, all)), !.
%% THE PRONOUN `all' TAKES INTO ONE PHRASE (`tutti noi', `todos nosotros') is a
%% plural PERSONAL one: its English is we, us, they, them or you. A
%% demonstrative is a third person plural to tr_subject_pronoun/4 as well, and
%% `tutti quelli con cui ho lavorato' -- all of those I worked with -- was
%% taken for `all of us': `quelli' left no phrase for its relative clause and
%% the sentence was refused with every word known
tr_all_person(P) :-
    atom(P), tr_subject_pronoun(foreign, P, _, plural),
    tr_solve(mean(P, E)), tr_plural_person(E, _), !.

%% the word that begins BOTH ... AND and its partner: English's own pair; the
%% lesson's word that means `both' and the word it says is its partner
%% (the partner first, the lesson's few of them, and then the meaning)
tr_both_word(english, both, and) :- !.
tr_both_word(foreign, B, P) :- tr_solve(mean(B, both)), tr_solve(partner_of(P, B)), !.
%% (in a denied clause the pair says which of the two it is: `non deriverebbe tanto dagli scarichi ...
%% quanto da un inquinamento di tipo urbano' would derive not so much from the discharges as from an
%% urban pollution, and `would not derive both from ... and from' said that it came from neither)
tr_both_pair(english, 'so much', as) :- tr_global('$tr_denied', yes), !.
tr_both_pair(english, both, and) :- !.
tr_both_pair(foreign, B, P) :- once(( tr_solve(partner_of(P, B)), tr_solve(mean(B, both)) )).

%% (never a phrase that begins with a pronoun cut off the word before it,
%% which is that word's: `Correggimi' read as you correct me, the pronoun a
%% free object -- or, `mi' being a note of the scale too, the note E)
tr_object_phrase(_, [w(_, enclitic)|_], _) :- !, fail.
%% (nor an elided form alone, which is written only against the word after
%% it: `tra l'Europa e l'Asia ci stesse' read the second `l'' as `him', the
%% second of the two things between, and Asia was the subject of `there was')
tr_object_phrase(foreign, [w(W, _)], _) :- atom(W), tr_solve(elision_of(W, _)), !, fail.
tr_object_phrase(Side, [w(W, C)], pronoun(w(W, C))) :- tr_object_pronoun(Side, W, _), !.
tr_object_phrase(Side, Words, NP) :- tr_np(Side, Words, NP).

%% the words that open a phrase whose noun was left out, and a degree word
%% before an adjective, which is no adverb standing alone
tr_ellipsis_start(Side, [D, P|_]) :-
    (   tr_determiner(Side, D, _, article), \+ tr_standalone_det(Side, D)
    ->  tr_is(Side, P, preposition), tr_means_of(Side, P)
    ;   tr_noun_replacer(Side, D), tr_is(Side, P, preposition)
    ), !.
%% ... and a word that replaces the noun before a participle: `vede quello
%% guidato dal gatto' is the one the cat led (tr_np/3's rel/3 on ell/4), and
%% read as the pronoun `that' with a participle after it, `eso conducido'
tr_ellipsis_start(foreign, [Q, w(P, _)|_]) :-
    tr_noun_replacer(foreign, Q), tr_participle_here(foreign, P, _), \+ tr_is(foreign, w(P, lower), noun), !.

%% A WORD THE LESSON SAYS STANDS FOR A NOUN THE SENTENCE LEFT OUT, where its
%% language has no article for it: Italian's `quello di Berlusconi' is
%% Berlusconi's one. `The word "quello" replaces the noun.' is the line
%% Spanish's `el' has had since 1.6.15.
tr_noun_replacer(foreign, w(Q, _)) :-
    atom(Q), \+ tr_determiner(foreign, w(Q, lower), _, article),
    tr_lexeme(foreign, Q, L, _), tr_solve(replace(L, noun)), !.

%% AN ARTICLE THE LESSON ALSO CALLS A PRONOUN STANDING ALONE HEADS ITS OWN
%% PHRASE. `uno' is the masculine article and the pronoun `one', and `The
%% pronoun "uno" does not precede the verb' is what says it stands alone --
%% so `uno dei paesi' is one of the countries, as 1.6.7 read it, and never
%% an article whose noun was left out. A clitic (`la', `los') carries no
%% such denial, and `los de clase media' stays the ellipsis it is.
%% (KEPT FOR THE SENTENCE (tr_memo/4): the phrase reader asks it of the article
%% at every place a phrase can begin, and each time was a lexeme and a query
%% of the lesson)
tr_standalone_det(foreign, w(W, _)) :-
    (   atom(W) -> tr_language(G), tr_memo(sdet(G, W), x, tr_standalone_det0(W), [_|_])
    ;   tr_standalone_det0(W)
    ), !.
tr_standalone_det0(W) :- tr_lexeme(foreign, W, L, _), tr_solve(neg(precede(L, verb))), !.
%% an article the lesson says comes before the letters the next word begins with
%% (KEPT FOR THE SENTENCE (tr_memo/4), by the two words: `uno che stabilisca'
%% asked it 1 900 times of the same pair, a query of the lesson's eighteen
%% beginnings each, and a fifth of Ferlaino's twenty-first sentence was that)
tr_article_by_letters(foreign, w(W, _), [w(N, _)|_]) :-
    atom(N), atom(W), tr_language(G), tr_memo(letters(G, W, N), x, tr_article_by_letters0(W, N), [_|_]), !.
tr_article_by_letters0(W, N) :- tr_lexeme(foreign, W, L, _), tr_solve(come_before(L, P)), begin_with(N, P), !.
tr_degree_start(foreign, [w(M, _), A|_]) :- tr_degree_word(M), tr_is(foreign, A, adjective), !.
tr_degree_start(english, [w(M, _), A|_]) :- en_degree_marker(M, _), tr_is(english, A, adjective), !.
tr_degree_start(Side, [A, J|_]) :- tr_intensifier(Side, A, J), !.
%% the word for `also' or `even' that is a noun too, after a noun and before an adjective, which the phrase keeps
%% (tr_focus_ints/3) -- never after a coordinator, where it is the clause's: `presidente della società di fisica e anche
%% responsabile del progetto' went on over it, and `anche responsabile' was the responsible hips
tr_focus_adj_start(PW, [w(M, lower), J|_]) :-
    atom(M), tr_focusnoun_here(M),
    last(PW, N), N = w(NW, lower), atom(NW), tr_is(foreign, N, noun), \+ tr_participle_here(foreign, NW, _),
    J = w(JW, _), atom(JW), tr_is(foreign, J, adjective), \+ tr_focus_adverb(JW), \+ tr_participle_here(foreign, JW, _), !.

%% an adverb before an adjective inside a phrase is the adjective's: `una
%% familia tan pacífica' is so peaceful a family, and read as an adverb of
%% the sentence it came out after the verb, the adjective left behind
tr_intensifier(Side, A, J) :-
    A = w(M, _), tr_adverb_word(Side, A), \+ tr_is(Side, A, adjective), \+ tr_is(Side, A, noun),
    \+ tr_determiner(Side, A, _, article),
    \+ ( Side == english, en_degree_marker(M, _) ), \+ ( Side == foreign, tr_degree_word(M) ),
    J = w(_, _), tr_is(Side, J, adjective), \+ tr_connective_adverb(Side, M).

%% AN ADVERB THAT JOINS ITS CLAUSE TO THE ONE BEFORE IT SAYS NOTHING OF THE
%% ADJECTIVE AFTER IT. `Siate perciò coerenti' is be consistent, THEREFORE,
%% and read as the adjective's intensifier it was `therefore consistent',
%% one phrase, which Spanish refused; `non vi saranno quindi altri vincoli'
%% is there will THEN be no other restrictions, and `quindi altri' read as
%% one adjective went after its noun, `restricciones entonces otras'. What
%% says so is the English word, a closed class, as `en_connector/1' is: an
%% adverb every meaning of which is one of them -- `così' is `so' as well
%% as `thus', and `così pacifica' stays so peaceful. Asked last, of an
%% adverb before an adjective only.
tr_connective_adverb(english, M) :- !, en_conjunctive(M).
tr_connective_adverb(foreign, M) :-
    tr_solve(mean(M, _)), forall(tr_solve(mean(M, E)), en_conjunctive(E)).

en_conjunctive(therefore).  en_conjunctive(then).     en_conjunctive(thus).
en_conjunctive(hence).      en_conjunctive(however).  en_conjunctive(instead).
en_conjunctive(besides).    en_conjunctive(moreover). en_conjunctive(furthermore).
en_conjunctive(nevertheless). en_conjunctive(nonetheless).
en_conjunctive(consequently). en_conjunctive(accordingly).
en_conjunctive(meanwhile).  en_conjunctive(otherwise). en_conjunctive(indeed).
en_conjunctive(anyway).     en_conjunctive('in fact').
en_conjunctive('or else').     % `Altrimenti mi dedicherò al mondiale Wba' stays in front: `Or else I will dedicate'
en_conjunctive('to begin with').  % `De entrada se llevaron a las candidatas a protagonizar un anuncio'
en_conjunctive('in reality').     % `En realidad lo que quería era simplemente atraer la atención'

%% an adverb does not inflect, so on the lesson's side the word itself is
%% asked: this runs on every word of every phrase the reader tries
tr_adverb_word(foreign, w(M, _)) :- !, tr_solve(adverb(M)).
tr_adverb_word(Side, A) :- tr_is(Side, A, adverb).

%% AN ADVERB BETWEEN THE DETERMINER AND THE NOUN SAYS WHEN THE NOUN HOLDS:
%% `El grupo radiofónico del todavía editor y presentador' is the group of the
%% man who is still its editor, `el entonces presidente' the president then,
%% which English writes `the then president' and Italian `l'allora
%% presidente'. Read as the clause's, the adverb went after the verb, `sleeps
%% still'. It stays in the phrase, advn/1 among the adjectives, before the
%% noun in every language.
tr_noun_adverb(Side, Det, [A, N|Ws], [advn(A), N|Ws]) :-
    Det \== none, A = w(AW, _), atom(AW), \+ tr_degree_word(AW),
    tr_plain_adverb(Side, A), \+ tr_is(Side, A, adjective), \+ tr_is(Side, A, noun),
    N = w(_, _), tr_is(Side, N, noun), !.
tr_noun_adverb(_, _, Ws, Ws).

tr_intensify(_, [], []).
tr_intensify(Side, [A, J|Ws], [int(A, J)|Os]) :- tr_intensifier(Side, A, J), !, tr_intensify(Side, Ws, Os).
%% ... AND `MORE THAN' BEFORE AN ADJECTIVE, INSIDE A PHRASE: `en el más que
%% probable caso' is the more than likely case. mt/1 reads the same words
%% after a copula; inside a phrase they were the degree word, the relative
%% `que' and nothing, and the sentence was refused. mti(Adjective) is the
%% term, and each writer puts its own `more than' before the adjective
tr_intensify(Side, [M, Q, J|Ws], [mti(J)|Os]) :- tr_more_than(Side, M, Q, J), !, tr_intensify(Side, Ws, Os).
tr_intensify(Side, [W|Ws], [W|Os]) :- tr_intensify(Side, Ws, Os).

%% THE WORD FOR `also' OR `even' THAT IS A NOUN TOO, BETWEEN A NOUN AND ITS ADJECTIVE, IS THE ADJECTIVE'S: `per una
%% serie di ragioni anche generazionali' are reasons, generational ones among them, and `sono un problema anche mio' a
%% problem that is mine too -- `anche' is the plural of `anca' as well, and read apart the adjective had no noun and the
%% front no reading. Never before the word for `only': `sono una piccola imprenditrice ..., odio anche solo l'idea della
%% guerra' is I hate even the idea of war, and read as `also alone' the clause lost its commas; nor beside a participle,
%% which the verb has (`Era stato anche proibito alla radio' read so again, the text the same, for a quarter more).
%% Asked of a phrase that holds one of the sentence's such words (`$tr_focusnoun'): as a clause of tr_intensify/3,
%% tried at every word of every phrase, it cost the Venice report's eighth sentence 0.76 million inferences
tr_focus_ints(foreign, Ws0, Ws) :-
    nb_getval('$tr_focusnoun', L), L \== [], ( L == any -> tr_gen_words(focusnoun, Fs) ; Fs = L ),
    member(M, Fs), memberchk(w(M, lower), Ws0),
    append(Pre, [N, w(M, lower), J|Post], Ws0),
    N = w(NW, lower), atom(NW), tr_is(foreign, N, noun), \+ tr_participle_here(foreign, NW, _),
    J = w(JW, _), atom(JW), tr_is(foreign, J, adjective), \+ tr_focus_adverb(JW), \+ tr_participle_here(foreign, JW, _), !,
    append(Pre, [N, int(w(M, lower), J)|Post], Ws).
tr_focus_ints(_, Ws, Ws).

%% the words for `more than' and an adjective after them (the adjective
%% first: this is asked at every word of every phrase)
tr_more_than(Side, M, Q, J) :-
    J = w(_, _), tr_is(Side, J, adjective), M = w(MW, _), Q = w(QW, _), atom(MW), atom(QW),
    (   Side == english -> MW == more, QW == than
    ;   tr_solve(mean(QW, than)), tr_degree_word(MW)
    ), !.

%% the indefinite article, which may stand for a noun left out before any
%% preposition: `una para cada candidatura', one for each
tr_indefinite(english, w(W, _)) :- ( W == a ; W == an ), !.
tr_indefinite(foreign, w(W, _)) :- atom(W), tr_lexeme(foreign, W, L, _), tr_class_of(L, article), tr_solve(mean(L, a)), !.

%% a word that means `of': English's own, or the lesson's
tr_means_of(english, w(of, _)) :- !.
tr_means_of(foreign, w(W, _)) :- tr_lexeme(foreign, W, L, _), tr_solve(mean(L, of)), !.

%% the words that open a relative clause: the relative word itself, a
%% preposition before it (`a cui'), or a preposition and an article before
%% it (`a el que', which is how `al que' reads once the contraction is
%% expanded)
tr_relative_start(Side, [w(R, _)|_]) :- tr_relative_word(Side, R), !.
tr_relative_start(Side, [J|_]) :- nb_getval('$tr_joined', yes), tr_joined_relative(Side, J, _, _), !.
tr_relative_start(Side, [P, w(R, _)|_]) :-
    tr_is(Side, P, preposition), tr_relative_word(Side, R), \+ tr_clause_opener(Side, [P, w(R, lower)]), !.
tr_relative_start(Side, [P, D, w(R, _)|_]) :-
    tr_is(Side, P, preposition), \+ ( P = w(PW, _), tr_solve(mean(PW, like)) ),     % `como el que' compares
    tr_determiner(Side, D, _, article), tr_relative_word(Side, R), !.

%% the lesson's word for `than', and a phrase after it with no verb in it
%% -- and SOMETHING COMPARED BEFORE IT: the word that begins the comparative
%% or a word meaning same, identical or equal (tr_compared_before/2). Italian
%% says `than' with `di' before a phrase (`più grande del cane'), and without
%% this every `di' was one: the controls read `la historia de la
%% desaparición' as the story THAN the disappearance and wrote `que'.
%% -- AND NOT A PREPOSITION: Italian's `di' is `than' after `più' and `of'
%% in the superlative the same words make, `i Paesi più ricchi del mondo',
%% and only the article tells the two apart; read as `than' the twelve's
%% richest countries were refused, and `Dello stesso tenore il commento del
%% sindaco' compared everything after `stesso'. The lesson's word is still
%% the one written for `than' before a phrase (tr_than_word/2), so Spanish's
%% comparisons go into Italian, and an Italian one is read as `of'.
%% -- AND NOT A CLAUSE IN THE SUBJUNCTIVE: `Hoy es más difícil que pase algo
%% así' is harder THAT something like it happens, and `pase' is a pass as well
%% as the subjunctive of `pasar', so the comparison took it for a noun, more
%% difficult than a pass. A word the lesson states as a subjunctive right
%% after the word for `than' opens a clause.
tr_comparison_start(foreign, [w(Q, _)|Ws]) :-
    Ws \== [], tr_solve(mean(Q, than)), \+ tr_class_of(Q, preposition),
    tr_compared_before(Q, Ws),
    \+ ( member(w(V, _), Ws), tr_verb_form_word(V), \+ tr_is(foreign, w(V, lower), adjective) ),
    \+ ( Ws = [w(V1, _)|_], atom(V1), tr_subjunctive_word(V1) ), !.
%% ... and one that opens on a preposition before an infinitive, whatever
%% follows it: `più occupati a controllare i biglietti che a vigilare sulla
%% sicurezza di chi nuota' has a verb in its term, `nuota', which read the
%% words from `che' on as a relative clause of `i biglietti' (cmpi/2)
tr_comparison_start(foreign, [w(Q, _), P, w(I, _)|Rest]) :-
    atom(I), P = w(_, _), tr_is(foreign, P, preposition), tr_solve(infinitive_of(I, _)),
    tr_solve(mean(Q, than)), \+ tr_class_of(Q, preposition), tr_compared_before(Q, [P, w(I, _)|Rest]), !.

%% ... AND THE WORD THAT OPENS A CLAUSE OF COMPARISON, `than what', ends the
%% phrase before it as well: `meno della metà di quanto spende l'italiano
%% medio' is less than half of what he spends, and the phrase `la metà' took
%% `di quanto spende ...' for its relative clause, so the comparison (cmpc/2)
%% never saw its word
tr_cmpc_start(foreign, [w(Q, _)|Ws]) :-
    Ws \== [], atom(Q), tr_language(L), tr_memo(cmpc(L, Q), x, tr_solve(mean(Q, 'than what')), [_|_]),
    tr_compared_before(Q, Ws), !.

%% (`"pasara" is the past subjunctive of "pasa".' is subjunctive_of/2 too, and
%% past/1 beside it)
tr_subjunctive_word(V) :- tr_solve(subjunctive_of(V, _)), !.

%% (in its own part of the piece, after the last comma before it: `avevano
%% fatto calcoli PIÙ precisi dei suoi, ritenevano che la sfera terrestre
%% fosse più ampia' -- the first clause's `più' made the second clause's
%% `che' the word for `than', the sphere the term, and `fosse' the pits)
%% ... AND AFTER THE LAST `que' BEFORE THIS ONE, which asks about its own
%% place in the piece (the words after it, Ws0): `Redondo fue más lejos al
%% decir que esa actitud es la que les diferencia' -- the `más' of the first
%% clause made the `que' of `la que' the word for `than', the relative's
%% pronoun the term and `diferencia' a noun, a difference. Only the `que'
%% the `más' is straight before is the comparison's; a conjunction between
%% them has taken it
tr_compared_before(Q, Ws0) :-
    tr_global('$tr_piece', Ws), is_list(Ws),
    (   append(Before00, [w(Q, _)|Tail], Ws), append(Ws0, _, Tail)
    ->  \+ tr_that_follows_saying(Before00, Ws0)
    ;   append(Before00, [w(Q, _)|_], Ws)
    ),
    ( append(_, [comma|Before0], Before00), \+ memberchk(comma, Before0) -> true ; Before0 = Before00 ),
    ( append(_, [w(Q, _)|Before], Before0), \+ memberchk(w(Q, _), Before) -> true ; Before = Before0 ),
    member(w(W, _), Before),
    (   tr_degree_word(W)
    ;   tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)), memberchk(E, [same, identical, equal, less, better, worse])
    ), !.
%% `que' STRAIGHT AFTER A VERB THAT SAYS SOMETHING, with a clause's subject
%% after it, is the conjunction whatever stands before the verb: `fue más lejos
%% al precisar que esa actitud ...' is no `more far than that attitude'
tr_that_follows_saying(Before, After) :-
    last(Before, w(I, _)), atom(I),
    (   tr_solve(infinitive_of(I, L)) -> true ; tr_form(I, L, _, _, _) ),
    ( tr_solve(take(L, clause)) ; tr_saying_verb(L) ), !,
    tr_subject_first(After).

%% the lesson's word for `than': before an adjective the one it calls a
%% CONJUNCTION (`più che discutibile'), before a phrase one it does not
%% (`più ricco del mondo'), and the first it gives where it has only one
%% kind -- Spanish's `que' serves both
tr_than_word(adjective, W) :- tr_solve(mean(W, than)), tr_class_of(W, conjunction), !.
tr_than_word(phrase, W) :- tr_solve(mean(W, than)), \+ tr_class_of(W, conjunction), !.
tr_than_word(_, W) :- once(tr_solve(mean(W, than))).

%% a form of a verb of the lesson's -- a verb, a modal or an auxiliary --
%% that the lesson calls no noun. tr_form/5 alone answers for any word the
%% lesson knows, `el' among them, as its own third person.
tr_verb_form_word(V) :-
    tr_form(V, L, _, _, _), atom(L),
    ( tr_class_of(L, verb) ; tr_class_of(L, modal) ; tr_class_of(L, auxiliary) ),
    \+ tr_is(foreign, w(V, lower), noun), !.
tr_denied_verb_form(V) :-
    tr_form(V, L, _, _, _), atom(L), L \== V,
    ( tr_class_of(L, verb) ; tr_class_of(L, modal) ; tr_class_of(L, auxiliary) ), !.

%% the sentence says the two things are the same: a word before the
%% comparison meaning `same', `identical' or `equal'
tr_equative_piece(Q) :-
    tr_global('$tr_piece', Ws), is_list(Ws), append(Before, [w(Q, _)|_], Ws),
    member(w(W, _), Before), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)),
    memberchk(E, [same, identical, equal]), !.

%% a relative word: English's own, or one the lesson calls one (`"que" is a
%% relative.')
tr_relative_word(english, W) :- !, memberchk(W, [that, which, who, whom]).
tr_relative_word(foreign, W) :- tr_solve(relative(W)), !.

%% a relative that is a determiner meaning `whose' (`cuyo', `il cui'), in
%% either gender and number
tr_whose_word(R) :-
    atom(R), tr_determiner(foreign, w(R, lower), L, determiner), tr_solve(mean(L, whose)), !.

%% the clause after a relative word, and what the word stands for in it
%% (and never with a second object that a relative clause stands for, after
%% one of its own: `los ciudadanos que ofrecen estos inventos LO QUE los hace
%% tan deseados' -- the clause is the citizens' and the phrase after it the
%% copula's subject, tr_cleft_fix/3; read as the clause's second object no
%% writer could write it, and the sentence was refused)
%% A COMMA STRAIGHT AFTER THE RELATIVE WORD OPENS AN INSERTION IN FRONT OF
%% ITS CLAUSE: `il dott Di Pietro il quale, anziché riprendere il proprio
%% posto in seno ai "presidi", si difende' -- instead of taking his place
%% back, he defends himself. It is the clause's front, set off on both sides,
%% frc/1 as a `che' clause's is (tr_that_clause/3); read with the commas out
%% it went after the verb and lost them.
%% ... AND TWO OR MORE, each set off: `ex ministro de Información y Turismo
%% que, en 1974, como señal de aperturismo, se puso una barretina' -- the
%% first comma after the insertion was taken for the one that closes it, and
%% `como señal' was no verb
%% (and the second one may have come set aside already, w(Key, mid), by
%% tr_clause_mids/4, with the comma that closed the first)
%% A RELATIVE THAT IS THE DETERMINER OF A PHRASE IN ITS OWN CLAUSE: `un joven
%% cuyo nombre se hará familiar muy pronto' -- a young man whose name will
%% soon be familiar. It stands in no gap: the clause reads whole, the word
%% the determiner of its phrase, agreeing with that phrase's noun and not
%% with the one the clause is on (`cuya casa', `il cui nome'). The lesson
%% says it of the word -- `The masculine determiner "cuyo" means "whose".',
%% `"cuyo" is a relative.' -- and the role is whose, so every writer writes
%% no relative word before the clause: its phrase carries its own, `il cui
%% nome', `whose name'.
%% THE CLAUSE OF A RELATIVE THAT STANDS FOR A PLACE OR AFTER A PREPOSITION HAS A
%% SUBJECT OF ITS OWN, though it may stand after the verb: `la casa in cui dorme
%% Maria', `dove ha combattuto Parisi'. Read with nobody named and the name its
%% object it was `en la que duerme a Maria', and English had no one to sleep.
%% The first object, a name or a phrase in the number the third person nobody
%% named has, is the subject, its place kept (subj_here) as a main clause's
%% inverted subject is
tr_rel_subject_fix(s(A, null(third, N), G, [obj(X)|Cs]), s(A, X, G, [subj_here|Cs])) :-
    ( X = name(_) ; X = np(_, _, _, _, _) ), tr_subject_number(X, N),
    %% (never an INDEFINITE phrase after a verb that takes an object: `un tema delicato sul quale aveva assunto
    %% una posizione assai decisa' is a topic on which he had taken a position, and made the subject it came out
    %% `on which a position had taken')
    \+ ( X = np(det(article, DL, _), _, _, _, _), atom(DL), tr_solve(mean(DL, a)),
         G = g(L, _, _, _), atom(L), \+ tr_solve(intransitive(L)) ), !.
tr_rel_subject_fix(S, S).
tr_relative_clause(foreign, [w(R, RC)|Ws], whose, S) :-
    nb_getval('$tr_whose', yes),                              % the sentence has one
    Ws \== [], tr_whose_word(R),
    tr_read_nested(foreign, [w(R, RC)|Ws], none, S), !.
%% ... AND A CLAUSE WITH ITS SUBORDINATING WORD, set off on both sides: `due
%% autori cristiani ... i quali, siccome un passo della bibbia descriveva la
%% terra in forma di tabernacolo, polemizzavano con le teorie pagane' -- who,
%% since a passage of the bible described it so, polemicized; the insertion
%% below takes adjuncts only, and the sentence was refused
tr_relative_clause(Side, [w(R, RC), comma, w(C, CC)|Ws], subject, S) :-
    tr_relative_word(Side, R), atom(C), tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)),
    append(Cond, [comma|Rest], Ws), Cond = [_|_], Rest = [_|_], \+ memberchk(comma, Cond),
    tr_gap_verb_next(Side, Rest),
    %% (or a participle with nothing else, `che, se accettata, potrebbe modificare':
    %% if accepted -- the fragment tr_insertion_off/4 reads after a subject)
    (   tr_read_nested(Side, Cond, none, S1) -> true
    ;   Side == foreign, Cond = [w(CP, _)|_], atom(CP), tr_participle_here(foreign, CP, _), tr_participle_gap(Cond, S1)
    ),
    tr_relative_clause(Side, [w(R, RC)|Rest], subject, s(A, Su, G, Comps0)), !,
    S = s(A, Su, G, [frc(sub(w(C, CC), S1))|Comps0]).
tr_relative_clause(Side, [w(R, RC), comma|Ws], subject, S) :-
    tr_relative_word(Side, R),
    append(Ins, [Sep|Rest], Ws), ( Sep == comma -> true ; Sep = w(_, mid) ), Ins = [_|_], Rest = [_|_],
    tr_gap_verb_next(Side, Rest),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, Ins, Front0), Front0 \== [], tr_adjuncts(Front0),
    (   Sep = w(K, mid) -> nb_getval(K, MW), tr_complements(Side, MW, MCs), tr_adjuncts(MCs),
        append(Front0, [sep|MCs], Front)
    ;   Front = Front0
    ),
    tr_relative_clause(Side, [w(R, RC)|Rest], subject, s(A, Su, G, Comps0)), !,
    findall(frc(X), member(X, Front), Fr), append(Fr, Comps0, Comps),
    S = s(A, Su, G, Comps).
%% A CONDITION BEFORE A RELATIVE CLAUSE'S VERB, a comma after it: `questa
%% legge, che se fosse stata promulgata nel testo attuale, avrebbe
%% ulteriormente dissestato l'amministrazione' -- the law that, had it been
%% promulgated, would have thrown the administration into disorder. The word
%% after the relative word is a subordinating connector, its clause runs to
%% the comma, and the rest is the relative clause with its verb. The
%% condition is the clause's front, fr(sub(Connector, Clause)), written in
%% front of it with the comma after it as an adjunct's is.
tr_relative_clause(Side, [w(R, RC), w(C, CC)|Ws], subject, S) :-
    tr_relative_word(Side, R), tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)),
    append(Cond, [comma|Rest], Ws), Cond = [_|_], Rest = [_|_], \+ memberchk(comma, Cond),
    tr_gap_verb_next(Side, Rest),
    tr_read_nested(Side, Cond, none, S1),
    tr_relative_clause(Side, [w(R, RC)|Rest], subject, s(A, Su, G, Comps0)), !,
    S = s(A, Su, G, [fr(sub(w(C, CC), S1))|Comps0]).
%% A TIME BEFORE A RELATIVE CLAUSE'S VERB IS ITS FRONT, NOT ITS SUBJECT: `un
%% niño que el domingo había resultado gravemente herido' -- the boy was hurt
%% on Sunday. Read with the day before the verb the clause had no gap to
%% leave: the relative word was an object and `el domingo' the subject, `che
%% domenica era risultata ferita', the day hurt (and a sentence whose clause
%% has an object of its own was refused). The phrase for a day or a month
%% first, the clause is read without it, and the time is its front.
%% (Three tests come first, each cheap: the clause's first word an article or
%% a demonstrative, a noun the lesson calls a time in its first three words,
%% and only then the phrases. A clause's words run to the end of the sentence
%% and every reading of it asks this: `que tuvo lugar ayer, el secretario ...'
%% found `ayer' at the end of a scan to the first preposition and read `tuvo
%% lugar' and `tuvo lugar ayer' for phrases, 2.4 million inferences in one
%% sentence of the Basque article, a hundred times over.)
%% ... AND A DATE IN FRONT: `i componenti della banda che il 7 novembre del settantasette, rapì il duca' are of the
%% gang that kidnapped him on November 7, of '77 (the comma is the paper's slip: tr_rel_time_comma/3). The only reading
%% took the date for the clause's subject (`that November 7 ... kidnapped the duke'), and in a heading none had a verb,
%% so the sentence of the ten life sentences was refused. An article, a month among the next words, and the date with
%% its phrase of `of' read as one phrase
tr_relative_clause(foreign, [w(R, RC)|Ws], subject, S) :-
    tr_global('$tr_month', yes),
    Ws = [D1, _|_], D1 = w(_, _), tr_determiner(foreign, D1, _, article), tr_relative_word(foreign, R),
    member(N, [6, 5, 4, 3]), length(PW, N), append(PW, Rest, Ws), \+ memberchk(comma, PW), Rest = [w(_, _)|_],
    once(( member(w(MW, _), PW), atom(MW), tr_lexeme(foreign, MW, ML, _), tr_holds(month(ML)) )),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, PW, Cs0), ( Cs0 = [C0] -> PPs = [] ; Cs0 = [C0, PP], PP = pp(_, _), PPs = [PP] ),
    ( C0 = obj(X1) -> true ; C0 = at_time(X1) ), ( PPs == [] -> X0 = X1 ; X0 = with(X1, PPs) ),
    ( X0 = with(XN, _) -> true ; XN = X0 ), tr_time_or_month(XN), tr_date_year(X0, X),
    tr_relative_clause(foreign, [w(R, RC)|Rest], subject, s(A, Su, G, Comps0)), !,
    S = s(A, Su, G, [frn(at_time(X))|Comps0]).
tr_relative_clause(Side, [w(R, RC)|Ws], subject, S) :-
    Ws = [W1, _|_], tr_time_starts(Side, W1), tr_relative_word(Side, R), tr_time_in_first(3, Ws),
    between(2, 5, N), length(PW, N), append(PW, Rest, Ws), Rest = [w(_, _)|_],
    \+ memberchk(comma, PW),
    tr_phrase_np(Side, PW, NP0), tr_time_phrase(NP0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, PW, [at_time(NP)]),
    tr_relative_clause(Side, [w(R, RC)|Rest], subject, s(A, Su, G, Comps0)), !,
    S = s(A, Su, G, [frn(at_time(NP))|Comps0]).
tr_relative_clause(Side, [w(R, _)|Ws], subject, S) :-
    tr_relative_word(Side, R), Ws \== [],
    tr_read_nested(Side, Ws, subject(rel), S0),
    S0 = s(_, asked(Q), G, Comps),
    \+ append(_, [obj(_), obj(ell(_, _, _, rel(_, _)))], Comps), !,
    %% THE GAP KEEPS THE NUMBER ITS VERB HAD. `gli uomini del soccorso alpino
    %% e speleologico che li hanno trovati' hangs the clause on the nearest
    %% phrase, the rescue, where it belongs to the men -- and written in the
    %% PHRASE's number `hanno' came out `ha'. The source's own agreement is
    %% the one thing here that knows which, so the writer takes it.
    ( Q = rel(P, N) -> Gap = gap(P, N) ; Gap = gap ),
    S = s(none, Gap, G, Comps).
%% ... and the clause of an object or a preposition's object is read with
%% `rel' where a question's asked term goes: every statement shape that
%% insists on `none' -- an imperative, a headline, a gerund clause -- stands
%% down, because none of them can follow a relative word. Measured: `al que
%% pertenece' read `pertenece' as the IMPERATIVE it is spelled like and
%% wrote Italian's second person, `a cui appartieni'.
%% ... and the relative word is the object only where the clause has none of
%% its own: `las reformas, que al igual que en la mayoría de las
%% exrepúblicas soviéticas, no han traído a Georgia la prosperidad' is the
%% reforms bringing no prosperity, and read with `que' for the object the
%% majority became the clause's subject and the prosperity its object too
%% -- nor where a copula already has what it says: `descubrieron con cierta
%% sorpresa que el telefonino ... estaba vacío' found THAT the mobile was
%% empty, and read as the surprise the mobile was empty the `que' clause was
%% the surprise's and no clause of the verb's
%% (an object after an infinitive is the infinitive's, which leaves the verb
%% its gap: `i magistrati che egli si permette di chiamare fuorilegge, non
%% senza redarguire chi ... non lo imita' -- whoever it is is what he rebukes,
%% and the magistrates what he calls outlaws)
%% (nor where the verb takes no object at all, which leaves no gap for one:
%% `per il semplice motivo che la "Bastiglia" ... non mi risulta sia stata
%% mai occupata' is the reason THAT it never was, `"risulta" is
%% intransitive.' -- read as the reason the Bastille does not result to me,
%% the clause was the reason's relative)
%% ... AND THE GAP IS THE SUBJECT OF A CLAUSE THE VERB TAKES: `la
%% possibilità offerta dall'università, che spero si concretizzi,' -- which
%% I hope materialises. Read with the relative word for the object of
%% `spero', the clause of `si concretizzi' was left with nobody for its
%% subject, and the sentence was divided round it: `que espero, se
%% materializa,'. The clause is the verb's, its subject is the gap, and it
%% travels as thatg/1, written with no word for `that' in any language:
%% English cannot say `which I hope that materialises', and the source
%% said none
%% (ONE CLAUSE WITH THE OBJECT'S BELOW, over one reading of the words: the
%% two read the same words the same way, and as two clauses every relative
%% clause whose gap is no clause's subject was read twice -- `la orientación
%% que los publicistas de las marcas que se disputan el mercado español dan
%% a sus campañas' 0.7 million inferences more for the same text)
tr_relative_clause(Side, [w(R, _)|Ws], Role, S) :-
    ( var(Role) -> true ; memberchk(Role, [subject, object]) ),
    tr_relative_word(Side, R), Ws \== [],
    %% (asked for the subject alone, the words are read only for the gap in a
    %% clause the verb takes, whose own subject is a first or second person:
    %% the form of one is asked first, and a word for `that' or a verb the
    %% lesson says takes the clause -- `a chi più guadagna in modo da poter
    %% utilizzare il denaro ... le borse di studio' has neither, `studio' being
    %% a noun and I study, and was read for nothing: 257 000 inferences in the
    %% Salvini interview's twelfth)
    (   Role == subject
    ->  Side == foreign,
        once(( member(w(X, _), Ws), atom(X), tr_form(X, _, _, _, XP), XP \== third )),
        once(( member(w(Y, YC), Ws), atom(Y),
               ( tr_that_here(foreign, w(Y, YC)) ; tr_form(Y, YL, _, _, _), atom(YL), tr_solve(take(YL, clause)) ) ))
    ;   true
    ),
    tr_read_nested(Side, Ws, rel, S0),
    (   Role \== object, tr_rel_gap_clause(Side, S0, S1)
    ->  Role = subject, S = S1
    ;   Role \== subject, tr_rel_object(Side, S0, S1)
    ->  Role = object, S = S1
    ), !.
%% AN ADVERB BEFORE THE VERB OF A RELATIVE CLAUSE WHOSE GAP IS ITS OBJECT: `lo que hoy es
%% el equipo', `lo que ya tiene el Inter' -- the clause is read without it and the
%% adverb is one of its complements, where `lo que es hoy el equipo' has it, so
%% English writes it after the subject (`what the team is today'); the subject's
%% gap is read first, so only a role asked for is read here
tr_relative_clause(foreign, [w(R, RC), A|Ws], Role, s(Q, Su, G, [adv(A)|Cs])) :-
    Role == object, Ws = [_|_],
    tr_relative_word(foreign, R), tr_plain_adverb(foreign, A),
    tr_relative_clause(foreign, [w(R, RC)|Ws], object, s(Q, Su, G, Cs)), !.
%% ... AND TWO VERBS JOINED IN ONE CLAUSE: `Paral.lel, espacio de Canal 33
%% que hasta finales del pasado mes de mayo presentaba y dirigía Jaume
%% Barberà' -- the programme Barberà presented and directed. The clause after
%% the relative word joins two verbs in one tense and one person that share
%% the gap, the subject and what follows; read as one verb, the clause ended
%% at `y', the programme presented, and the sentence was divided there with
%% Barberà directing the rest. The first verb is the clause's group and the
%% second travels as cov(Coordinator, Lexeme, Tense, Person, Number), which
%% every writer puts after it in the same form; a front before the first
%% goes after the verbs, as a relative clause's does (tr_front_after/3).
tr_relative_clause(foreign, [w(R, RC)|Ws], Role, S) :-
    tr_relative_word(foreign, R),
    append(Pre, [w(V1, _), C, w(V2, V2C)|Post], Ws),
    C = w(CW, _), atom(CW), CW \== ',', tr_coord(foreign, C),
    atom(V1), atom(V2), tr_verb_form_word(V1), tr_verb_form_word(V2),
    \+ ( member(w(XW, _), Pre), atom(XW), ( tr_verb_form_word(XW) ; tr_solve(mean(XW, not)) ) ),
    ( Pre == [] -> Front = [] ; tr_complements(foreign, Pre, Front), Front \== [], tr_adjuncts(Front) ),
    member(Role, [subject, object]),
    tr_relative_clause(foreign, [w(R, RC), w(V2, V2C)|Post], Role, S2),
    S2 = s(_, Subj, g(L2, T, simple, no), Cs2), atom(L2),
    tr_form(V2, L2, N, T, P), tr_form(V1, L1, N, T, P), atom(L1), L1 \== L2, !,
    tr_front_after([cov(C, L2, T, P, N)|Cs2], Front, Cs),
    S = s(none, Subj, g(L1, T, simple, no), Cs).
%% (the word the lesson puts before a person, and a relative after it, is
%% the relative OBJECT where the clause has a subject after its verb and no
%% object of its own: `el hombre a quien vio el perro' is the man the dog
%% saw, and read as `to whom' somebody nobody named saw the dog -- `a quien
%% los renovadores atribuyen un comportamiento' keeps its `to whom')
%% ... AND TWO VERBS, EACH WITH WORDS OF ITS OWN: `un processo che avrebbe accolto
%% in pieno la linea difensiva e nonostante ciò avrebbe condannato l'imputato' --
%% a trial that would have accepted the defence in full and would have
%% condemned the defendant all the same. The relative clause was read to its
%% first coordinator and the words after it were another clause, with nobody to
%% say them of (`perché celebrare un processo che ... e avrebbe condannato'
%% asked why the trial would have condemned). Both halves are relative clauses
%% on the one gap, joined as the relative clauses of a preposition's object are
%% (tr_rel_join/3): join(Coordinator, First, Second). The second half opens on
%% its verb, after adjuncts if it has any.
tr_relative_clause(foreign, [w(R, RC)|Ws], subject, join(w(W, WC), S1, S2)) :-
    nb_getval('$tr_front_coord', yes),
    tr_relative_word(foreign, R),
    append(L, [w(W, WC), X|Rest0], Ws), L = [_|_], atom(W), tr_coord(foreign, w(W, WC)),
    X = w(XW, _), atom(XW), ( tr_is(foreign, X, preposition) ; tr_is(foreign, X, adverb) ),
    Rest = [X|Rest0],
    tr_gap_verb_next(foreign, L), tr_front_verb(Rest),
    tr_relative_clause(foreign, [w(R, RC)|L], subject, S1),
    tr_relative_clause(foreign, [w(R, RC)|Rest], subject, S2), !.
%% ... AND THE SECOND HALF OPENING ON ITS VERB: `La oficina del sheriff, que declinó hacer comentarios y dirigió
%% cualquier pregunta al COI, reconoció ...' -- the office that declined to comment and directed every question to the
%% IOC. Read to its coordinator the clause left `y dirigió ...' to the sentence, which was divided there, and English
%% refused the half with nobody named. The verb after the coordinator is in the tense, the person and the number of
%% the clause's first verb, which opens the clause, each a verb's or a modal's form (tr_verb_lexeme/1); the two share
%% the gap. The rule is asked in a sentence that has the pattern only ('$tr_rel_two_verbs', tr_rel_two_verbs_note/1)
tr_relative_clause(foreign, [w(R, RC)|Ws], subject, join(w(W, WC), S1, S2)) :-
    nb_getval('$tr_rel_two_verbs', yes),
    tr_relative_word(foreign, R), Ws = [w(V1, _), _|_], atom(V1),
    append(L, [w(W, WC), w(V2, V2C)|Post], Ws), L = [_, _|_], atom(W), tr_coord(foreign, w(W, WC)), atom(V2),
    tr_form(V1, L1, N, T, P), atom(L1), tr_verb_lexeme(L1), tr_form(V2, L2, N, T, P), atom(L2), tr_verb_lexeme(L2),
    tr_relative_clause(foreign, [w(R, RC)|L], subject, S1),
    tr_relative_clause(foreign, [w(R, RC), w(V2, V2C)|Post], subject, S2), !.
tr_relative_clause(Side, [P, w(R, RC)|Ws], Role, S) :-
    tr_is(Side, P, preposition), tr_relative_word(Side, R), Ws \== [],
    (   Side == foreign, P = w(PW, _), atom(PW), tr_solve(precede(PW, person)),
        tr_relative_clause(Side, [w(R, RC)|Ws], object, S1), S1 = s(_, Su1, _, Cs1),
        Su1 \= null(_, _), Su1 \== impersonal, \+ memberchk(obj(_), Cs1)
    ->  Role = object, S = S1
    ;   Role = pp(P),
        (   tr_read_nested(Side, Ws, rel, S0) -> tr_unrel(S0, S1a), tr_rel_ci_si(Ws, S1a, S1)
        ;   tr_rel_join(Side, Ws, S1)
        ),
        tr_rel_subject_fix(S1, S)
    ), !.
%% ... AND ITS ADJUNCTS BEFORE THE CLAUSE, when the relative word has a
%% preposition: `Iside Frigerio, con cui per decenni ha condotto una battaglia
%% silenziosa' -- for decades, and the clause after it. Only the relative
%% with a subject gap had a front (below); here the words after `cui' were
%% read as a clause and `per decenni' was none, so the sentence was refused,
%% and an adverb alone (`la donna con cui spesso parla') was lifted out of
%% the clause and written after the main clause's verb, `es alta a menudo'.
%% The front goes where the other relatives put it: an adverb alone before
%% the verb, a phrase after it (tr_front_after/3)
tr_relative_clause(Side, [P, w(R, _)|Ws], Role, S) :-
    tr_is(Side, P, preposition), tr_relative_word(Side, R), Ws = [F1, _|_],
    ( tr_is(Side, F1, preposition) ; tr_is(Side, F1, adverb) ),
    tr_front_max(Side, Ws, no, Max),
    append(Front0, _, Max), Front0 \== [], append(Front0, Rest, Ws), Rest \== [],
    tr_complements(Side, Front0, Front), Front \== [], tr_adjuncts(Front),
    tr_read_nested(Side, Rest, rel, S0), !,
    Role = pp(P), S0 = s(_, Su, G, Comps0),
    (   forall(member(X, Front), X = adv(_))
    ->  tr_front_adverbs(Front, Fr), append(Fr, Comps0, Comps)
    ;   tr_front_after(Comps0, Front, Comps)
    ),
    S = s(none, Su, G, Comps).
%% ... AND A PREPOSITION AND THE RELATIVE WORD JOINED AS ONE WORD OF THE
%% LESSON'S: `Il terzo motivo per cui il cronista è qui ... è lo
%% stabilimento' is the reason FOR WHICH the reporter is here, and `per cui'
%% is also a conjunction of two words the lesson gives, `so', joined before
%% the reading -- which left the phrase no relative clause and the subject
%% no reading
tr_relative_clause(Side, [J|Ws], pp(w(P, JC)), S) :-
    J = w(_, JC), tr_joined_relative(Side, J, P, _), Ws \== [],
    (   tr_read_nested(Side, Ws, rel, S0) -> tr_unrel(S0, S)
    ;   tr_rel_join(Side, Ws, S)
    ), !.
%% -- never after `como': `como el que sufrió' is like the one that, and no
%% relative clause has `like' for its preposition
tr_relative_clause(Side, [P, D, w(R, _)|Ws], pp(P), S) :-
    tr_is(Side, P, preposition), \+ ( P = w(PW, _), tr_solve(mean(PW, like)) ),
    tr_determiner(Side, D, _, article), tr_relative_word(Side, R), Ws \== [],
    tr_read_nested(Side, Ws, rel, S0), !, tr_unrel(S0, S1a), tr_rel_ci_si(Ws, S1a, S1), tr_rel_doer_fix(Side, S1, S).
%% ... AND ITS ADJUNCTS BEFORE THE CLAUSE, with an article between the
%% preposition and the relative word: `el Congreso, al que también asistieron,
%% entre otros, la consellera' -- also, and then the clause. The relative with
%% no article had its front (above); this one read `también asistieron ...' as
%% a clause and found none, so `al que' was `a quello che' -- the one that --
%% and the adverb stood in the middle of it. Asked only where the clause above
%% found nothing, so a relative that read keeps its reading.
tr_relative_clause(Side, [P, D, w(R, _)|Ws], pp(P), S) :-
    Ws = [F1, _|_], ( tr_is(Side, F1, preposition) ; tr_is(Side, F1, adverb) ),
    tr_is(Side, P, preposition), \+ ( P = w(PW, _), tr_solve(mean(PW, like)) ),
    tr_determiner(Side, D, _, article), tr_relative_word(Side, R),
    tr_front_max(Side, Ws, no, Max),
    append(Front0, _, Max), Front0 \== [], append(Front0, Rest, Ws), Rest \== [],
    tr_complements(Side, Front0, Front), Front \== [], tr_adjuncts(Front),
    tr_read_nested(Side, Rest, rel, S0), !,
    S0 = s(_, Su, G, Comps0),
    (   forall(member(X, Front), X = adv(_))
    ->  tr_front_adverbs(Front, Fr), append(Fr, Comps0, Comps)
    ;   tr_front_after(Comps0, Front, Comps)
    ),
    S = s(none, Su, G, Comps).

%% ... AND WITH ITS ADJUNCTS BEFORE ITS VERB: `las ventas de sencillos, que
%% en 1999 absorbieron casi el 4% del mercado total' -- the gap and then
%% when. Only a front that opens on a preposition or an adverb is looked
%% for, and it goes after the verb, as a statement's front with no comma
%% does (tr_front_after/3).
%% ... AND A COMMA AFTER THE FRONT SETS IT OFF, as a statement's: `que al
%% igual que en la mayoría de las exrepúblicas soviéticas, no han traído'
%% -- the front stops at the comma, the verb is after it, and the front is
%% written back in front with its comma (fr/1).
tr_relative_clause(Side, [w(R, _)|Ws], subject, S) :-
    tr_relative_word(Side, R), Ws = [F1, _|_],
    ( tr_is(Side, F1, preposition) ; tr_is(Side, F1, adverb) ),
    tr_front_max(Side, Ws, no, Max),
    append(Front0, _, Max), Front0 \== [], append(Front0, Rest0, Ws), Rest0 \== [],
    ( Rest0 = [comma|Rest] -> Set = yes ; Rest = Rest0, Set = no ), Rest \== [],
    tr_gap_verb_next(Side, Rest),
    tr_complements(Side, Front0, Front), Front \== [], tr_adjuncts(Front),
    tr_read_nested(Side, Rest, subject(rel), S0),
    S0 = s(_, asked(Q), G, Comps0), !,
    ( Q = rel(P, N) -> Gap = gap(P, N) ; Gap = gap ),
    (   Set == yes
    ->  findall(fr(X), member(X, Front), Fr), append(Fr, Comps0, Comps)
    %% ... AND AN ADVERB ALONE STAYS BEFORE THE VERB: `a chi più guadagna in
    %% modo da poter utilizzare il denaro ...' is the one who earns MORE, and
    %% put after everything the clause took it came out `a los menos ricos y
    %% los dignos más', the more worthy; `Il gatto che sempre mangia il pane
    %% dorme' came out `The cat that eats the bread always sleeps', which is
    %% the cat's sleeping. A phrase still goes after the verb.
    ;   forall(member(X, Front), X = adv(_))
    ->  findall(frn(X), member(X, Front), Fr), append(Fr, Comps0, Comps)
    ;   tr_front_after(Comps0, Front, Comps)
    ),
    S = s(none, Gap, G, Comps).

%% ... AND TWO OF THEM, EACH SET OFF BY COMMAS: `la gestión de Moratti que ahora, con su noveno proyecto,
%% parece estar al fin en el buen camino' -- the adverb, then the phrase, then the verb. A front stops at
%% its first comma, so the second began a part with no verb and the clause had no reading (a subject read
%% it, with the phrase hung on the verb of the sentence). The first front is read apart and the clause
%% after its comma is the one above, whose front it is: both go in front (fr/1)
tr_relative_clause(Side, [w(R, RC)|Ws], subject, S) :-
    tr_relative_word(Side, R), Ws = [F1, _|_],
    ( tr_is(Side, F1, preposition) ; tr_is(Side, F1, adverb) ),
    append(Front1, [comma|Rest1], Ws), Front1 \== [], \+ memberchk(comma, Front1),
    Rest1 = [F2, _|_], ( tr_is(Side, F2, preposition) ; tr_is(Side, F2, adverb) ),
    tr_complements(Side, Front1, Front), Front \== [], tr_adjuncts(Front),
    tr_relative_clause(Side, [w(R, RC)|Rest1], subject, S1), !,
    S1 = s(Q, Gap, G, Comps1),
    append(Front, [sep], FrontSep),                                  % (its comma goes with it)
    findall(fr(X), member(X, FrontSep), Fr), append(Fr, Comps1, Comps),
    S = s(Q, Gap, G, Comps).
tr_rel_gap_clause(Side, S0, S) :-
    Side == foreign,
    S0 = s(_, Su, G, Cs0), tr_speaker_subject(Su),
    append(Pre, [that(S1)], Cs0), tr_gap_clause(S1, S1g),
    \+ tr_verb_object(Pre), !,
    append(Pre, [thatg(S1g)], Cs),
    S = s(none, Su, G, Cs).
%% (the relative clause's own subject is its first or second person, named
%% by the verb or by a pronoun: a third person may be what the clause of the
%% verb is about, raised to be the verb's subject -- `per il semplice motivo
%% che la "Bastiglia", qui da noi, non mi risulta sia stata mai occupata' is
%% the reason THAT the Bastille was never taken, `la Bastiglia' belonging to
%% `sia stata occupata', and read as a relative clause with its gap there it
%% was the reason the Bastille results to have been taken, `para el motivo
%% que la casa ... no me resulta es grande')
tr_speaker_subject(null(P, _)) :- P \== third.
tr_speaker_subject(pronoun(P, _, _)) :- P \== third.
%% (the clause's subject is nobody named, or the impersonal word that a
%% reflexive with nobody named reads as: `si concretizzi' is it materialising)
tr_gap_clause(s(A, null(third, N), G, Cs), s(A, gap(third, N), G, Cs)).
tr_gap_clause(s(A, impersonal, g(L, T, simple, Neg), Cs), s(A, gap(third, singular), g(reflexive(L), T, simple, Neg), Cs)) :- atom(L).
tr_rel_object(Side, S0, S) :-
    (   \+ ( S0 = s(_, _, _, Cs0), tr_verb_object(Cs0) ),
        %% (a clause of `that' is the verb's object too, and leaves no gap:
        %% `nasce dal fatto che il mondo greco aveva ritenuto che la terra
        %% fosse immobile' is the fact THAT it had believed it, the noun's
        %% own clause -- read as the fact the Greek world believed, Spanish
        %% wrote `el hecho que' where it says `el hecho de que')
        \+ ( S0 = s(_, _, _, Cs2), memberchk(that(_), Cs2) ),
        \+ ( Side == foreign, S0 = s(_, _, g(L0, _, _, _), _), atom(L0), tr_solve(intransitive(L0)) ),
        \+ ( S0 = s(_, _, g(L0, _, simple, _), Cs1), memberchk(adj(_), Cs1), ( tr_copula_lexeme(L0) ; tr_state_lexeme(L0) ) )
    ->  tr_unrel(S0, S)
    ;   Side == foreign, tr_rel_subject_after(Side, S0, S)
    ), !.
%% ... AND WITH ITS SUBJECT AFTER ITS VERB: `después de la que celebraron el
%% Lunes por la noche delegaciones del Gobierno central y del PSOE' -- the
%% one the delegations held. A relative clause puts its subject after its
%% verb as often as before it, and read with nobody named the delegations
%% were the object and the clause had no gap left for the relative word. A
%% phrase after the verb that agrees with it is the subject, and it keeps
%% its place (subj_here), as a reporting clause's speaker does.
%% (asked of the clause the reading above has read, and not read again: a
%% nested clause has one reading, and as a clause of its own this read the
%% words a second time wherever the reading above failed -- the Solana
%% report's ninth sentence 9.6 % more inferences, the mobile column's fifth
%% 12.8 %)
tr_rel_subject_after(Side, S0, S) :-
    S0 = s(_, null(third, N), G, Cs0),
    append(Pre, [obj(NP)|Post], Cs0), \+ ( member(X, Pre), tr_object_comp(X) ),
    NP \= pronoun(_), tr_head_number(Side, NP, N),
    \+ ( member(Y, Post), tr_object_comp(Y) ), !,
    %% (and the phrases of `de' after it are the subject's: `delegaciones del
    %% Gobierno central y del PSOE' -- read as the verb's, English put the
    %% subject first and left `of the central Government' behind the verb)
    tr_subject_ofs(Post, PPs, Post1),
    ( PPs == [] -> Subj = NP ; Subj = with(NP, PPs) ),
    append(Pre, [subj_here|Post1], Cs),
    S = s(none, Subj, G, Cs).

tr_subject_ofs([pp(w(P, PC), X)|R0], [pp(w(P, PC), X)|PPs], Post) :-
    tr_means_of(foreign, w(P, PC)), !,
    (   R0 = [cnj(C), pp(w(P2, PC2), Y)|R1], tr_means_of(foreign, w(P2, PC2))
    ->  PPs = [cnj(C)|PPs1], tr_subject_ofs([pp(w(P2, PC2), Y)|R1], PPs1, Post)
    ;   tr_subject_ofs(R0, PPs, Post)
    ).
tr_subject_ofs(Post, [], Post).
%% (adjuncts, a few words at most, and then a verb: `nonostante ciò avrebbe condannato')
%% the gerunds of verbs the lesson gives in the sentence's words (by their ending first, where the
%% lesson is a lookup): tr_subject/6 asks the phrase for the ones it holds
tr_gerunds_of(Words, Gs) :-
    findall(G, ( member(w(G, _), Words), atom(G), ( atom_concat(_, ando, G) ; atom_concat(_, endo, G) ),
                 tr_gerund_here(foreign, G, _) ), Gs0),
    sort(Gs0, Gs).
%% the sentence has the word for `number' and digits after it (tr_np/3's noun and its number)
%% the sentence's words for `also' or `even' that are nouns too (tr_intensify/3)
tr_focusnoun_note(Words, FNs) :-
    tr_gen_words(focusnoun, Fs),
    (   Fs == [] -> FNs = []
    ;   findall(W, ( member(w(W, _), Words), atom(W), memberchk(W, Fs) ), FNs0), sort(FNs0, FNs)
    ).
%% ... and whether a word is one of them (`any' before the first sentence: every such word of the lessons)
tr_focusnoun_here(M) :-
    nb_getval('$tr_focusnoun', L), L \== [], ( L == any -> tr_gen_words(focusnoun, Fs) ; Fs = L ), memberchk(M, Fs), !.
tr_numbered_note(Words) :-
    append(_, [w(NW, _), w(N, _)|_], Words), atom(N), tr_digits(N), atom(NW),
    tr_lexeme(foreign, NW, NL, singular), atom(NL), tr_solve(mean(NL, number)), !.
%% the sentence has a word that replaces a noun and a relative word or a degree word right after it:
%% `todo lo que dice Pedro', `nada de lo que hoy es el equipo', `lo más formidable' (tr_np/3's all/2, its
%% phrase of `of' and its most ... thing, and tr_subject_shape/4's clause for each)
tr_replacer_note(Words) :-
    append(_, [Q, w(X, _)|_], Words), atom(X),
    ( tr_relative_word(foreign, X) ; tr_degree_word(X) ),
    tr_noun_replacer(foreign, Q), !.
%% the sentence has an adjective, a preposition, an article and a relative word: `un horario similar al que
%% desarrollan las cajas de ahorros' (tr_np/3's adjective whose phrase is the one that)
tr_adj_rel_note(Words) :-
    append(_, [w(J, _), w(A, _), D, w(R, _)|_], Words), atom(R), tr_relative_word(foreign, R),
    atom(A), tr_is(foreign, w(A, lower), preposition), tr_determiner(foreign, D, _, article),
    atom(J), tr_is(foreign, w(J, lower), adjective), !.
%% the sentence has a word the lesson's language says `among' with (`tra', `fra', `entre': a preposition is its own
%% lexeme)
tr_among_note(Words) :-
    findall(L, tr_solve(mean(L, among)), Ls), Ls \== [],
    member(w(W, _), Words), atom(W), memberchk(W, Ls), !.
%% the sentence has a word for `where', and after it a coordinator, a determiner and a phrase of four words at most
%% to the end or to another word for `where'
tr_where_co_note(Words) :-
    append(_, [w(W, _)|After], Words), atom(W), tr_indirect_word(foreign, W, where),
    append(_, [Co, D|Rest], After), Co = w(CoW, _), atom(CoW), tr_coord(foreign, Co),
    D = w(_, _), tr_determiner(foreign, D, _, _), tr_where_tail(Rest), !.
%% the sentence has a participle with the word for `by' right after it, and a word right before it that it does not
%% agree with, in number or in gender: `en castellano abiertas por miembros'. (A participle that agrees with the word
%% before it hangs on that word, as it always did; asked of every participle with an agent, the clause cost the Hotel
%% Arts report's tenth sentence 16 % more, `el fondo participado por Prudential', to its refusal)
tr_ptc_agent_note(Words) :-
    append(_, [w(N, _), w(P, _), B|_], Words), B = w(BW, _), atom(BW), tr_means_by(foreign, B),
    atom(P), atom(N), tr_participle_here(foreign, P, _),
    %% (a noun or an adjective, never an infinitive: `que debería ser refrendada por los miembros' is the
    %% proposal's, and with `ser' for the word before it the note was made for a sentence that has no such phrase)
    ( tr_is(foreign, w(N, lower), noun) ; tr_is(foreign, w(N, lower), adjective) ), \+ tr_solve(infinitive_of(N, _)),
    tr_lexeme(foreign, N, NL, NN),
    tr_participle_number(P, PN), ( tr_solve(feminine(P)) -> PG = feminine ; PG = masculine ),
    (   PN \== NN -> true
    ;   ( tr_gender(NL, G0), G0 \== none -> NG = G0 ; tr_solve(feminine(N)) -> NG = feminine ; NG = masculine ), NG \== PG
    ), !.
%% A PARTICIPLE BETWEEN COMMAS AFTER A PHRASE AND ITS PHRASES OF `of' IS THE HEAD'S, where it agrees with the
%% head and not with the last noun: `El plan de autonomía para Córcega, propuesto por el Gobierno de Jospin y
%% aprobado por la Asamblea corsa el pasado viernes, prevé ...' -- the plan was proposed, and hung on Corsica the
%% Italian participle agreed with it, `la Corsica, proposta dal Governo'. The aside goes on the whole phrase
tr_aside_head_fix(foreign, s(A, Su0, G, Cs), s(A, Su, G, Cs)) :-
    Su0 = with(H, PPs0), append(Front, [pp(P, app(NP2, aside, K))], PPs0),
    atom(K), catch(nb_getval(K, [w(PW, _)|_]), _, fail), atom(PW), tr_participle_here(foreign, PW, _),
    tr_ptc_fits(PW, H), !,
    append(Front, [pp(P, NP2)], PPs), Su = app(with(H, PPs), aside, K).
tr_aside_head_fix(_, S, S).
%% A VERB OF SAYING, ITS COMMA AND ONE PHRASE SET IN, THEN THE CLAUSE OF `que': `al afirmar, durante la reunión del
%% Consejo de Ministros, que no tenía "nada que añadir"' affirmed that he had nothing to add -- read left to right,
%% the clause after the second comma was a relative clause on the council, and English said `which did not have'.
%% The comma right after the verb opens the phrase set in, whose own phrases of `of' run to the clause; the clause
%% is the verb's, with nobody named for its subject, and its comma stays. A clause with a subject of its own was
%% read as an object's relative clause (`afirma, durante la reunión del consejo, que el perro duerme' was `which
%% the dog sleeps'), and is the verb's clause too
tr_saying_that_fix(foreign, s(A, Su, G, Cs0), s(A, Su, G, Cs)) :-
    G = g(L, _, _, _), atom(L), tr_saying_that_comps(L, Cs0, Cs1), !, Cs = Cs1.
tr_saying_that_fix(foreign, s(A, Su, G, Cs0), s(A, Su, G, Cs)) :-
    append(Pre, [upon(L, Us0)|Post], Cs0), atom(L), tr_saying_that_comps(L, Us0, Us), !,
    append(Pre, [upon(L, Us)|Post], Cs).
tr_saying_that_fix(_, S, S).
tr_saying_that_comps(L, [sep, pp(P1, NP1)|PPs0], [sep, pp(P1, NP1)|PPs]) :-
    tr_saying_verb(L), append(Of, [pp(P2, nrc(NP2, Role, S2))], PPs0),
    forall(member(X, Of), ( X = pp(PX, _), tr_means_of(foreign, PX) )), tr_means_of(foreign, P2),
    tr_saying_that_clause(Role, S2, S), !,
    append(Of, [pp(P2, NP2), sep, that(S)], PPs).
tr_saying_that_clause(subject, s(A, gap(Pe, Nu), G, Cs), s(A, null(Pe, Nu), G, Cs)) :- G \= g(_, _, infinitive, _).
tr_saying_that_clause(object, s(A, Su, G, Cs), s(A, Su, G, Cs)) :- Su \= gap(_, _), Su \== none, G \= g(_, _, infinitive, _).
%% the participle agrees with the phrase's noun in number and in gender
tr_ptc_fits(P, np(_, _, _, w(N, _), NN)) :-
    atom(N), tr_participle_number(P, PN), PN == NN,
    ( tr_solve(feminine(P)) -> PG = feminine ; PG = masculine ),
    tr_lexeme(foreign, N, NL, _),
    ( tr_gender(NL, G0), G0 \== none -> NG = G0 ; tr_solve(feminine(N)) -> NG = feminine ; NG = masculine ), NG == PG.
%% the sentence has the copula, a pronoun of the first or the second person and a determiner: `Ero io il re'
tr_pron_copula_note(Words) :-
    append(_, [w(V, _), w(P, _), D|_], Words), atom(P), tr_subject_pronoun(foreign, P, Per, _), memberchk(Per, [first, second]),
    D = w(_, _), tr_determiner(foreign, D, _, _),
    atom(V), once(( ( tr_form(V, L, _, _, _) ; tr_solve(infinitive_of(V, L)) ), atom(L), tr_copula_lexeme(L) )), !.
%% the sentence has a comma and then a relative word
tr_comma_rel_note(Words) :-
    append(_, [comma, w(R, _)|_], Words), atom(R), tr_relative_word(foreign, R), !.
%% the sentence has a coordinator, a relative word, a verb of one word or two and a definite phrase or a
%% name: `un ataque con el que sueñan los interistas Y QUE han truncado las constantes lesiones'
%% (tr_np/3's second relative clause, joined, whose doer follows its verb)
tr_second_rel_note(Words) :-
    append(_, [Co, w(R, _)|Rel], Words), Co = w(CW, _), atom(CW), tr_coord(foreign, Co), atom(R), tr_relative_word(foreign, R),
    tr_doer_after_verb(Rel), !.
%% a verb of one word or two and then a definite phrase or a name: the doer that follows its verb
tr_doer_after_verb([w(V, _)|After]) :-
    atom(V), tr_verb_form_any(V),
    (   After = [D|_], tr_doer_start(D) -> true
    ;   After = [w(V2, _), D2|_], atom(V2), tr_verb_form_any(V2), tr_doer_start(D2)
    ), !.
%% (a form of a verb, a modal or an auxiliary, or its participle, whatever else the word is: a participle
%% is often a noun too)
tr_verb_form_any(V) :-
    ( tr_form(V, L, _, _, _) ; tr_solve(participle_of(V, L)) ), atom(L),
    ( tr_class_of(L, verb) ; tr_class_of(L, modal) ; tr_class_of(L, auxiliary) ), !.
tr_doer_start(w(W, upper)) :- atom(W), !.
tr_doer_start(D) :- D = w(W, _), atom(W), tr_determiner(foreign, D, _, article).
%% the sentence has a coordinator and then a preposition or an adverb
tr_front_coord_note(Words) :-
    append(_, [Co, X|_], Words), Co = w(CW, _), atom(CW), tr_coord(foreign, Co),
    X = w(XW, _), atom(XW), ( tr_is(foreign, X, preposition) ; tr_is(foreign, X, adverb) ), !.
%% the sentence has a relative word and a verb right after it, and after them a coordinator and a verb in the first
%% verb's tense, person and number (tr_relative_clause/4's relative clause with two verbs) -- each a verb's or a
%% modal's form: tr_form/5 gives any word as itself, a present third person singular, and `che si occupa ... e il
%% Ministero' took `il' for the second verb
tr_rel_two_verbs_note(Words) :-
    append(_, [w(R, _), w(V1, _)|Rest], Words), atom(R), atom(V1), tr_relative_word(foreign, R),
    tr_form(V1, L1, N, T, P), atom(L1), tr_verb_lexeme(L1),
    append(_, [Co, w(V2, _)|_], Rest), Co = w(CW, _), atom(CW), atom(V2), tr_coord(foreign, Co),
    tr_form(V2, L2, N, T, P), atom(L2), tr_verb_lexeme(L2), !.
tr_front_verb(Rest) :-
    between(1, 4, N), length(Front, N), append(Front, VRest, Rest), \+ memberchk(comma, Front),
    tr_gap_verb_next(foreign, VRest), tr_front_adjuncts(Front, _), !.
%% (and the relative word is no word for `that': Spanish's `que' is both, so
%% `para que', `de que' and `sin que' -- lesson words, so that, that, without
%% -- were joined relatives too, and every phrase before one was tried as the
%% head of a relative clause that could not read: 1.7 million inferences over
%% four sentences of the controls, for no text)
tr_joined_relative(Side, w(J, _), P, R) :-
    atom(J), atomic_list_concat([P, R], ' ', J),
    tr_is(Side, w(P, lower), preposition), tr_relative_word(Side, R),
    \+ ( tr_that_set(Ts), memberchk(R, Ts) ), !.
%% THE DOER AFTER THE VERB OF A CLAUSE ON A PREPOSITION'S RELATIVE IS ITS SUBJECT: `un ataque con el
%% que sueñan los interistas' is the attack the fans dream of -- the gap is the preposition's, so the
%% phrase after the verb is the object only if nothing else can be the subject, and read with nobody
%% named it was `with which they dream the inter fans'. A phrase that does what the verb says, in
%% the verb's number (the same doers as tr_rc_role/7's, and no `a' before it)
tr_rel_doer_fix(foreign, s(A, null(third, N), G, [obj(X)|Cs]), s(A, X, G, [subj_here|Cs])) :-
    tr_doer_np(X), tr_subject_number(X, N), !.
tr_rel_doer_fix(_, S, S).

%% THE ADVERBS BEFORE THE VERB OF A RELATIVE CLAUSE WITH A PREPOSITION STAY IN
%% FRONT, BUT FOR THE WORD FOR `ALSO', `EVEN' OR `ONLY', which is of the subject
%% after the verb and is written right after it: `al que también asistieron los
%% abogados' is `a cui assistettero anche gli avvocati', and it was `a cui
%% anche assistettero'. (A clause of its own with the subject after the verb
%% keeps its adverb in front, `Solo rimangono il cane e il gatto', and the
%% lesson says so, 43j)
tr_front_adverbs([], []).
tr_front_adverbs([adv(W)|Ws], [F|Fs]) :-
    (   W = w(A, _), atom(A), tr_focus_adverb(A) -> F = adv(W) ; F = frn(adv(W)) ),
    tr_front_adverbs(Ws, Fs).
%% (the year after the date's `of' is the date's own, app(Phrase, year, Year) as a joined year is: `il 7 novembre del
%% settantasette' is November 7, '77, where it came out `of the seventy-seven, on November 7')
tr_date_year(with(NP, [pp(_, np(_, none, [], w(Y, _), singular))]), app(NP, K, w(Y, lower))) :-
    atom(Y), ( tr_digits(Y) -> K = year ; tr_is(foreign, w(Y, lower), number), K = yearw ), !.
tr_date_year(X, X).

%% A VERB THE LESSON CALLS INTRANSITIVE HAS ITS SUBJECT AFTER IT in a relative
%% clause that stands for a preposition's phrase: `la casa en la que duerme el
%% perro' is the dog sleeping, and read as nobody named and an object the
%% clause had no subject English could say (`en la que' leaves none to the
%% gap). Its place travels as subj_here, as a statement's does
tr_unrel(s(_, null(third, N), g(L, T, A, Neg), [obj(NP)|Cs]), s(none, NP, g(L, T, A, Neg), [subj_here|Cs])) :-
    atom(L), NP = np(_, _, _, _, N), tr_solve(intransitive(L)), !.
tr_unrel(s(_, Su, G, Cs), s(none, Su, G, Cs)).
%% `CI SI' AFTER A PREPOSITION'S RELATIVE IS THE IMPERSONAL `si' WITH A
%% REFLEXIVE VERB, as a statement's is (tr_ci_si/3): `Un dato confortante del
%% quale non ci si può rallegrare' is a fact one cannot rejoice at. The clause
%% is read for a gap, where `ci si' may be `us' and the verb's own `si' with the
%% gap for the subject; under a preposition the gap is no subject, and read so
%% the clause had `us' and nobody named, which English refused. The words open
%% on the lesson's impersonal of `si', after a denial at most
tr_rel_ci_si(Ws, s(Q, null(third, singular), g(reflexive(L), T, A, Neg), Cs0), s(Q, impersonal, g(reflexive(L), T, A, Neg), Cs)) :-
    append(Pre, [w(Ci, _), w(Si, _)|_], Ws), atom(Ci), atom(Si),
    forall(member(X, Pre), ( X = w(XW, _), atom(XW), tr_solve(mean(XW, not)) )),
    tr_solve(impersonal_of(Ci, Si)), select(opron(_), Cs0, Cs), !.
tr_rel_ci_si(_, S, S).

%% A CLAUSE AFTER A PREPOSITION AND ITS RELATIVE MAY BE TWO, JOINED: `i lacci
%% e lacciuoli in cui si è cercato e si cerca di irretire i presìdi' is the
%% snares in which one has tried and one tries to ensnare them. Such a clause
%% has no gap -- the preposition's phrase is what it is about -- so each side
%% reads as the whole clause it is, and read as one clause it had two verbs;
%% the sentence was then divided at the second `e', which put the trying
%% outside the snares. Only a coordinator joins them here.
tr_rel_join(Side, Ws, join(w(W, WC), S1, S2)) :-
    append(L, [w(W, WC)|R], Ws), L = [_|_], R = [_|_],
    tr_coord(Side, w(W, WC)),
    tr_read_nested(Side, L, rel, S10), tr_unrel(S10, S1),
    tr_read_nested(Side, R, rel, S20), tr_unrel(S20, S2), !.

%% what follows the front when the relative word is the subject: the verb,
%% with a denial or a clitic before it -- never a subject of its own. `la
%% notizia che finalmente il fondo Veba e Fiat hanno raggiunto l'accordo' is
%% no relative clause at all, and every front of it was read and then every
%% reading of the rest as a clause with its subject gone
tr_gap_verb_next(Side, Rest) :-
    ( Side == english -> tr_negation(english, Rest, Ws, _) ; Ws = Rest ),
    tr_gap_verb_next0(Side, Ws), !.
tr_gap_verb_next0(foreign, [w(X, _)|Ws]) :- tr_negation_word(X), !, tr_gap_verb_next0(foreign, Ws).
tr_gap_verb_next0(foreign, [w(C, _)|Ws]) :- Ws \== [], tr_clitic(after, C), tr_gap_verb_next0(foreign, Ws), !.
tr_gap_verb_next0(Side, Ws) :- tr_group_at(Side, Ws, _, _), !.
%% the longest front of adjuncts the words allow: up to a comma, and up to
%% a determiner no preposition governs -- `che finalmente IL fondo' is a
%% subject, and `fondo' is also what `fondere' says of oneself, so the rest
%% after it looked like a verb and every longer front was read in turn
tr_front_max(_, [], _, []).
tr_front_max(_, [comma|_], _, []) :- !.
tr_front_max(Side, [W|_], no, []) :- tr_determiner(Side, W, _, _), !.
tr_front_max(Side, [W|Ws], P0, [W|Max]) :-
    ( P0 == yes -> P = yes ; tr_is(Side, W, preposition) -> P = yes ; P = no ),
    tr_front_max(Side, Ws, P, Max).

%% a clause read inside another puts back the group the outer one is
%% reading, which its later complements ask about -- the mirror of
%% tr_write_nested/3
%% ... AND A CLAUSE READ INSIDE ANOTHER IS NO COMMAND: `Apuntó que asume las
%% críticas' is that HE takes the criticism, and `asume' is the imperative of
%% `asumir' as well -- read as one, Italian wrote `che assumi le critiche'.
%% A command is a sentence's own, never a clause of `that', of a relative
%% word or of a subordinating one.
tr_read_nested(Side, Ws, Asked, S) :-
    tr_global('$tr_no_command', NC0), nb_setval('$tr_no_command', yes),
    (   tr_read_nested0(Side, Ws, Asked, S0) -> nb_setval('$tr_no_command', NC0), S = S0
    ;   nb_setval('$tr_no_command', NC0), fail
    ).
tr_read_nested0(Side, Ws, Asked, S) :-
    tr_global('$tr_read_group', G), tr_global('$tr_read_aspect', A),
    (   Side == foreign, Asked == none, tr_topic_cleft(Ws, S0)
    ->  nb_setval('$tr_read_group', G), nb_setval('$tr_read_aspect', A), S = S0
    ;   tr_read_statement(Side, Ws, Asked, S0), \+ tr_there_is_somebody(S0)
    ->  nb_setval('$tr_read_group', G), nb_setval('$tr_read_aspect', A), tr_clause_post(Side, Ws, S0, S)
    %% (and what a clause's own words say once it is read, as for the statement
    %% above: `spiega come, nei casi di annegamento, il soccorso immediato sia più
    %% importante dell'ambulanza' read its front and lost the comparison's
    %% `than', `es más importante de la ambulancia')
    ;   Asked == none, tr_nested_front(Side, Ws, S0)
    ->  nb_setval('$tr_read_group', G), nb_setval('$tr_read_aspect', A), tr_clause_post(Side, Ws, S0, S)
    ;   Asked == none, tr_nested_join(Side, Ws, S0)
    ->  nb_setval('$tr_read_group', G), nb_setval('$tr_read_aspect', A), S = S0
    ;   Asked == none, tr_nested_sub_head(Side, Ws, S0)
    ->  nb_setval('$tr_read_group', G), nb_setval('$tr_read_aspect', A), S = S0
    ;   nb_setval('$tr_read_group', G), nb_setval('$tr_read_aspect', A), fail
    ).

%% A SUBORDINATE CLAUSE AT THE HEAD OF A NESTED ONE, ITS MAIN CLAUSE AFTER IT
%% WITH NO COMMA: `il problema è ... che mentre la Francia destina il 2 per
%% cento del pil per la ricerca e la Germania tra il 2,3 e il 2,5 noi siamo
%% solo all'1,4' -- that while France assigns 2 per cent and Germany between
%% 2.3 and 2.5, we are only at 1.4. A whole sentence of that shape divides
%% before its main clause (tr_read0/4); a clause of `che' had no such
%% reading, `mentre' was lifted as the adverb it also is and written last,
%% and `noi' read as the reflexive of `siamo'. The same division, the
%% subordinate clause no command, as after the word anywhere.
%% ... AND WHERE THE SOURCE HAS A COMMA BETWEEN THE TWO, THE COMMA IS KEPT:
%% a nested clause is read with its commas out, so `e mentre il compagno
%% della donna, Emanuele Tornaboni, era in pista a sciare, la madre si è
%% allontanata' divided here lost the comma before `la madre' that 1.8.19
%% wrote -- join(comma, ...) is what a head subordinate clause with its
%% comma is at the top of a sentence (tr_comma_before/2 asks the piece)
tr_nested_sub_head(Side, [w(C, CC)|Ws], S) :-
    Ws = [_|_], \+ memberchk(comma, Ws),
    tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)),
    append(Left, Right, Ws), Left \== [], \+ ( last(Left, w(N, _)), atom(N), tr_negation_word(N) ),
    tr_main_start(Side, Right),
    tr_global('$tr_no_command', F0), nb_setval('$tr_no_command', yes),
    (   tr_read_nested(Side, Left, none, S1) -> nb_setval('$tr_no_command', F0)
    ;   nb_setval('$tr_no_command', F0), fail
    ),
    tr_read_nested(Side, Right, none, S2), !,
    (   Right = [R1|_], tr_comma_before(Left, R1)
    ->  S = join(comma, join(w(C, CC), none, S1), S2)
    ;   S = join(aside, join(w(C, CC), none, S1), S2)
    ).

%% A CLAUSE INSIDE A SENTENCE MAY BE TWO, JOINED BY A CONNECTOR: `decidere se
%% ci costerebbe più caro intervenire o stare a guardare MENTRE si consuma un
%% altro olocausto E l'intero popolo bosniaco viene distrutto' asks whether
%% one thing would cost more than another while two things happen. Only the
%% whole sentence was ever divided at a connector, so the question read as
%% nothing and the sentence went through every other reading first -- 110
%% million inferences to find the division at the top. Each side reads as a
%% clause, the left one whole and the right one perhaps two again, the
%% leftmost division that reads first.
%% (never a coordinator before an infinitive, which joins two infinitives:
%% `intervenire O STARE a guardare' is one choice between two acts)
%% (nor a connector after a COMMA or a CLOSING QUOTATION MARK, which divide
%% the sentence the nested clause stands in: `sostuvo que "cometer perjurio
%% no es aceptable y debe tener consecuencias", por lo que el comité se
%% propone ...' -- divided there inside the `que' clause, the committee's
%% intention was part of what Hyde said)
%% (and after a coordinator the right side shares the left's subject and is
%% no command, as a whole sentence's is (tr_read_joined/5): `debe tener
%% consecuencias' read alone was a command, `devi')
%% (and never after a comma -- but for a coordinator whose clause is in the
%% SUBJUNCTIVE, which is the mood that keeps it under the word that opened
%% the clause: `ritenevano che la sfera terrestre fosse più ampia ..., e
%% quindi fosse pazzesco tentare ...' held both, where `pero su solicitud
%% fue rechazada' after `que designara' is the sentence's own, indicative)
%% (the comma the source put there is written back, join(comma, ...), and a
%% connecting adverb at the head of the second clause stays in front of it,
%% as at the head of a sentence: `e quindi fosse pazzesco ...')
tr_nested_join(Side, Ws, J) :-
    append(L, [w(W, WC)|R], Ws), L = [_|_], R = [_|_],
    \+ last(L, comma), \+ last(L, w(_, qclose)),
    ( \+ tr_comma_before(L, w(W, WC)) -> Comma = no ; tr_coord(Side, w(W, WC)), tr_subjunctive_after(Side, R), Comma = yes ),
    tr_connector(Side, W),
    \+ ( tr_coord(Side, w(W, WC)), R = [w(V, _)|_], tr_solve(infinitive_of(V, _)) ),
    %% (nor between two phrases of ONE preposition, as the whole sentence
    %% is not divided there (tr_joins_phrases/3): `opina que el acuerdo es
    %% una mala noticia para los consumidores y para los pequeños
    %% comerciantes en España, al endurecer ... sin que eso provoque ...'
    %% divided at that `y', and `para' -- also the verb `parar' -- stopped
    %% the traders: `e arresta i piccoli commercianti')
    \+ ( tr_coord(Side, w(W, WC)), tr_joins_phrases(Side, L, R) ),
    tr_read_statement(Side, L, none, S1),
    (   tr_coord(Side, w(W, WC)), S1 = s(_, _, g(_, _, A1, _), _), A1 \== imperative
    ->  tr_global('$tr_no_command', F0), nb_setval('$tr_no_command', yes),
        (   tr_nested_right(Side, R, S20) -> nb_setval('$tr_no_command', F0)
        ;   nb_setval('$tr_no_command', F0), fail
        ),
        tr_shared_subject(Side, S1, R, S20, S21)
    ;   tr_read_nested(Side, R, none, S21)
    ), !,
    tr_nested_connective(Side, R, S21, S2),
    ( Comma == yes -> J = join(comma, S1, join(w(W, WC), none, S2)) ; J = join(w(W, WC), S1, S2) ).
%% ... AND THE RIGHT SIDE OF A COORDINATOR MAY BE A SUBORDINATE CLAUSE ALONE:
%% `prevede che chi ha partecipazioni non possa essere membro del governo e a
%% meno che non si liberi entro un anno' -- and unless he frees himself within
%% a year. With no main clause after it the clause of `unless' had no reading
%% inside the clause of `that' (tr_main_start/2 no longer takes `entro un
%% anno' for one), and the whole sentence was read again from the top
%% (never at a word that asks as well: `può essere che Margherita abbia avuto
%% un malore ma perché nessuno le ha viste?' asks why, and read so `perché'
%% was because, `can it be ... but because nobody has seen her?')
tr_nested_right(Side, R, S) :- tr_read_nested(Side, R, none, S), !.
tr_nested_right(Side, [w(C, CC)|R], join(w(C, CC), none, S)) :-
    R = [_|_], atom(C), tr_connector(Side, C), \+ tr_coord(Side, w(C, CC)), \+ tr_asking_word(Side, w(C, lower)),
    tr_read_nested(Side, R, none, S), !.
tr_nested_connective(foreign, [W|_], s(As, Su, G, Cs0), s(As, Su, G, [frn(adv(W))|Cs])) :-
    W = w(A, _), atom(A), selectchk(adv(W), Cs0, Cs),
    tr_lexeme(foreign, A, L, _), once(tr_solve(mean(L, E))), en_conjunctive(E), !.
tr_nested_connective(_, _, S, S).

%% ... the comma looked for in the piece, because a nested clause is read with
%% its commas out: `pidiéndole que designara un fiscal ... de fondos
%% electorales, pero su petición fue rechazada' divided at `pero' inside the
%% `que' clause, and the comma the sentence divides at was lost
tr_subjunctive_after(Side, R) :-
    append(Adv, [w(V, _)|_], R), forall(member(A, Adv), ( A = w(_, _), tr_plain_adverb(Side, A) )),
    atom(V), tr_subjunctive_word(V), !.
tr_comma_before(L, C) :-
    last(L, X), tr_global('$tr_piece', P), is_list(P), append(_, [X, comma, C|_], P), !.

%% A CLAUSE INSIDE A SENTENCE MAY HAVE A FRONT OF ITS OWN: `que antes de
%% jugar esto ya está ganado' puts `before playing' before its subject. The
%% shortest front of adjuncts that leaves a statement is taken -- a longer
%% one would take `esto' for what is played -- and it goes after the
%% clause's own complements, as a front with no comma does (1.6.8).
%% -- and it begins with a PREPOSITION OR AN ADVERB, which an adjunct does:
%% tried on every clause that failed to read, the walk over every front
%% cost Livata's `... che la famiglia era ...' 7.7 million inferences more
%% and found nothing
%% (or a parenthesis: `se (volendo rimanere nella metafora) la presa della
%% "Bastiglia" sia ancora possibile')
%% ... AND A FRONT SET OFF BY COMMAS: `L'equivoco nasce dal fatto che, almeno
%% sino a Copernico, sia il mondo greco che quello cristiano avevano ritenuto
%% ...' -- the clause of `che' opens on an insertion between two commas and
%% its subject stands after it. Read with the front's comma as the first word
%% of the rest, nothing read the rest, and the relative reading took `che'
%% for a subject and `sia' for its verb, `es el mundo griego'. The front goes
%% in front with both its commas, frc/1, as a relative clause's does
tr_nested_front(Side, [comma|Ws], s(A, Su, G, Comps)) :-
    append(Front0, [comma|Rest], Ws), Front0 = [W1|_], Rest = [_|_], \+ memberchk(comma, Front0),
    W1 = w(_, _), ( tr_is(Side, W1, preposition) ; tr_is(Side, W1, adverb) ),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, Front0, Front), Front \== [], tr_adjuncts(Front),
    tr_read_statement(Side, Rest, none, s(A, Su, G, Comps0)), !,
    findall(frc(X), member(X, Front), Fr), append(Fr, Comps0, Comps).
%% ... AND A TIME NOUN, A DAY: `E così quando martedì le due delegazioni
%% torneranno ad incontrarsi' -- the clause of `quando' opens on Tuesday, and
%% only a preposition, an adverb or a bracket began a front here, so `dice che
%% martedì il cane dorme' was refused where `dice che ieri il cane dorme' read
tr_nested_front(Side, Ws, s(A, Su, G, Comps)) :-
    Ws = [W1|_], W1 = w(_, _),
    (   tr_is(Side, W1, preposition) ; tr_is(Side, W1, adverb) ; W1 = w(_, paren)
    ;   W1 = w(WD, _), atom(WD), tr_time_word(Side, WD)
    ),
    append(Front0, Rest, Ws), Front0 = [_|_], Rest = [_|_], \+ memberchk(comma, Front0),
    \+ tr_ends_on_auxiliary(Side, Front0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(Side, Front0, Front), Front \== [], tr_adjuncts(Front),
    tr_read_statement(Side, Rest, none, s(A, Su0, G, Comps00)), !,
    tr_front_doer_fix(Side, Rest, Su0, Comps00, Su1, Comps0),
    tr_front_after(Comps0, Front, Comps1),
    %% a quotation that opens on the front's first word is the clause's,
    %% whose adjuncts are written after it (tr_vq_open/4)
    ( tr_clause_marks(Ws, s(A, Su1, G, Comps1), s(_, Su, _, Comps)) -> true ; Su = Su1, Comps = Comps1 ).
%% ... AND A PURPOSE, with its adverbs before it and no comma: `quando
%% invece per contestare arrivano in tanti' -- when, instead, they come in
%% numbers to protest. The top of a sentence reads it (tr_read0/4); inside
%% a clause the front was adjuncts only, and a purpose is none. The purpose
%% with what it takes, and a rest that names its subject where it takes
%% something (`Para celebrar el aniversario el club organizó una fiesta')
tr_nested_front(foreign, Ws, s(A, Su, G, Comps)) :-
    Ws = [W1|_], W1 = w(P1, _), atom(P1),
    ( tr_purpose_word(P1) ; tr_is(foreign, W1, adverb) ),
    append(Front0, Rest, Ws), Front0 = [_, _|_], Rest = [_|_], \+ memberchk(comma, Front0),
    nb_setval('$tr_read_aspect', simple), nb_setval('$tr_read_group', none),
    tr_complements(foreign, Front0, Front),
    tr_front_skip_adverbs(Front, [P2|Objs]), ( P2 = purpose(_) ; P2 = purp(_) ),
    forall(member(X, Objs), X = obj(_)),
    tr_read_statement(foreign, Rest, none, s(A, Su1, G, Comps0)),
    ( Objs == [] -> true ; Su1 \= null(_, _), Su1 \== none ), !,
    tr_front_after(Comps0, Front, Comps1),
    ( tr_clause_marks(Ws, s(A, Su1, G, Comps1), s(_, Su, _, Comps)) -> true ; Su = Su1, Comps = Comps1 ).
%% (... AND THE DOER RIGHT AFTER THE VERB OF A CLAUSE WITH A FRONT IS ITS SUBJECT: `La mujer recuerda que en
%% Cala Crancs juegan familias enteras en la arena' is whole families playing on the sand, and read with nobody
%% named, as a clause's first reading is, it was `they play whole families'. A front of place or time before
%% the verb is where the language puts the subject after it, so a phrase of persons, animals or a group there
%% with no `a' before it -- the word a person's object takes, which a bare one can do without (`buscan
%% familias') -- is the doer: a definite one, or a bare plural, in the verb's number)
tr_front_doer_fix(foreign, Rest, null(third, N), [obj(X)|Cs], X, [subj_here|Cs]) :-
    ( tr_doer_np(X) ; X = np(none, _, _, NW, plural), tr_doer_noun(NW) ),
    tr_subject_number(X, N),
    \+ ( tr_marker_word(M, person), memberchk(w(M, _), Rest) ), !.
tr_front_doer_fix(_, _, Su, Cs, Su, Cs).

%% the word this lesson puts before an infinitive of purpose -- or a word of
%% several words the lesson states ONLY as beginning one, which has no
%% meaning of its own to be a lexeme by: `in modo da poter utilizzare'
tr_purpose_word(P) :- tr_lexeme(foreign, P, L, _), tr_solve(begin(L, purpose)), !.
%% (the space by memberchk/2: sub_atom/5 is clauses, and it walked every
%% position of every word asked)
tr_purpose_word(P) :- atom(P), atom_codes(P, Cs), memberchk(0' , Cs), tr_solve(begin(P, purpose)), !.

%% the word this lesson puts before the reason for a thing: `The word "per"
%% begins the cause.'
tr_cause_word(P) :- tr_lexeme(foreign, P, L, _), tr_solve(begin(L, cause)), !.

%% the group being read is a modal, so a bare base form after it is its verb
tr_read_modal :- catch(nb_getval('$tr_read_group', L), _, fail), en_modal_out(L, _, _).

%% the group being read is the copula's: `sono stati eroici un'intera notte'
%% is heroic for a whole night, and the adjective before a determiner is its
%% predicate, never an object complement of a night
tr_read_copula :- catch(nb_getval('$tr_read_group', L), _, fail), atom(L), tr_copula_lexeme(L).

%% the group being read is a passive, so a `by' phrase after it is the agent
tr_read_passive :- catch(nb_getval('$tr_read_aspect', A), _, fail), memberchk(A, [passive, passive_perfect, duty]).

%% a word of the lesson's that means `to' -- what a verb puts before its
%% infinitive (`tende AD accreditare')
tr_means_to(P) :- tr_lexeme(foreign, P, L, _), tr_solve(mean(L, to)), !.
tr_means_of(P) :- tr_lexeme(foreign, P, L, _), tr_solve(mean(L, of)), !.

%% the infinitive group of infx/3: the perfect with a pronoun joined to its
%% auxiliary, the perfect, and the infinitive with a pronoun joined to it
tr_infinitive_group([w(A, _), w(Cl, enclitic), w(P, _)|Ws], F, perfect, [Cl], Ws) :-
    tr_perfect_infinitive(A, P, F, [Cl]), !.
tr_infinitive_group([w(A, _), w(P, _)|Ws], F, perfect, [], Ws) :-
    tr_perfect_infinitive(A, P, F, []), !.
%% ... AND ONE ADVERB BETWEEN THE AUXILIARY AND ITS PARTICIPLE, which goes on
%% after the group: `di non aver affatto abbracciato il presidenzialismo' is
%% `no haber abrazado ... el presidencialismo'. With the adverb there the
%% auxiliary was the verb that means `have' and the participle an adjective,
%% `no tener completamente abrazado'
tr_infinitive_group([w(A, _), X, w(P, _)|Ws], F, perfect, [], [X|Ws]) :-
    X = w(XW, _), atom(XW), tr_plain_adverb(foreign, X),
    tr_perfect_infinitive(A, P, F, []), !.
tr_infinitive_group([w(V, _), w(Cl1, enclitic), w(Cl2, enclitic)|Ws], F, simple, [Cl1, Cl2], Ws) :-
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !.
tr_infinitive_group([w(V, _), w(Cl, enclitic)|Ws], F, simple, [Cl], Ws) :-
    tr_solve(infinitive_of(V, F)), tr_known(foreign, F), !.

%% an auxiliary's infinitive and a participle: the auxiliary's own, or the
%% copula's where the lesson says the verb -- or, with the reflexive joined
%% to it, the reflexive -- builds its perfect with the copula
tr_perfect_infinitive(A, P, F, Cls) :-
    tr_solve(infinitive_of(A, AL)),
    tr_solve(participle_of(P, F)), tr_known(foreign, F),
    (   tr_solve(auxiliary(AL))
    ->  true
    ;   tr_copula_lexeme(AL),
        (   tr_solve(auxiliary_of(AL, F)) -> true
        ;   member(Cl, Cls), tr_reflexive_word(Cl), tr_solve(auxiliary_of(AL, reflexive))
        )
    ), !.

%% a word that means `by': English's own, or one the lesson gives for it
tr_means_by(english, w(by, _)) :- !.
tr_means_by(foreign, w(W, _)) :- tr_lexeme(foreign, W, L, _), tr_solve(mean(L, by)), !.
tr_means_with(w(W, _)) :- atom(W), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, with)), !.
%% the word for `like' (`come'), the comparison a thing is made by
tr_like_word(w(W, _)) :- atom(W), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, like)), !.

%% English's base form of a verb the lesson gives (`sleep' for `sleeps'),
%% never one of English's own words
en_infinitive(be, is) :- !.
en_infinitive(have, has) :- !.
en_infinitive(B, L) :- \+ en_own(B), reason_third(B, L), L \== B, tr_known(english, L), tr_class(english, L, verb).

%% ---- English's degrees --------------------------------------------------------
%% richer and richest, more careful and most careful, and the handful that
%% are neither. BOTH FORMS ARE READ whatever the rule would write, so `more
%% rich' comes back as the comparative and is written `richer' -- a round
%% trip through English normalises the spelling, which is the better
%% English of the two.

en_irregular_degree(good, better, best).
en_irregular_degree(well, better, best).
en_irregular_degree(bad, worse, worst).
en_irregular_degree(far, further, furthest).
en_irregular_degree(little, less, least).
en_irregular_degree(much, more, most).
en_irregular_degree(many, more, most).

en_degree_marker(more, comparative).
en_degree_marker(most, superlative).
en_degree_marker(less, less(comparative)).
en_degree_marker(least, less(superlative)).

en_degree_suffix(comparative, er).
en_degree_suffix(superlative, est).

%% reading a form: an irregular, or an ending taken off a word the lesson
%% knows as an adjective
en_degree_word(F, comparative, L) :- en_irregular_degree(L0, F, _), !, L = L0.
en_degree_word(F, superlative, L) :- en_irregular_degree(L0, _, F), !, L = L0.
en_degree_word(F, D, L) :-
    en_degree_suffix(D, Suf), atom_concat(Stem, Suf, F),
    en_degree_stem(Stem, L), tr_known(english, L), tr_class(english, L, adjective).

%% what an ending may have done to the word: nothing, an `e' dropped
%% (larger), a letter doubled (bigger), a `y' made `i' (happier)
en_degree_stem(Stem, Stem).
en_degree_stem(Stem, L) :- atom_concat(Stem, e, L).
en_degree_stem(Stem, L) :-
    atom_length(Stem, N), N > 2, M is N - 1,
    sub_atom(Stem, M, 1, 0, C), sub_atom(Stem, 0, M, _, L), sub_atom(L, _, 1, 0, C).
en_degree_stem(Stem, L) :- atom_concat(S1, i, Stem), atom_concat(S1, y, L).

%% writing one: the irregular, the ending where English gives one, and
%% `more'/`most' otherwise
en_degree_out(less(D), L, C, [o(M, lower), o(L, C)]) :- !, ( D == superlative -> M = least ; M = less ).
en_degree_out(D, L, C, [o(F, C)]) :-
    en_irregular_degree(L, Cm, Sp), !, ( D == comparative -> F = Cm ; F = Sp ).
en_degree_out(D, L, C, [o(F, C)]) :-
    en_short_adjective(L), !,
    en_degree_suffix(D, Suf), en_degree_base(L, Stem), atom_concat(Stem, Suf, F).
en_degree_out(D, L, C, [o(M, lower), o(L, C)]) :- en_degree_marker(M, D), !.

%% the stem an ending is added to
en_degree_base(L, Stem) :- atom_concat(Stem, e, L), !.
en_degree_base(L, Stem) :- atom_concat(S1, y, L), !, atom_concat(S1, i, Stem).
en_degree_base(L, Stem) :- en_doubles(L), !, sub_atom(L, _, 1, 0, C), atom_concat(L, C, Stem).
en_degree_base(L, L).

%% a word of one syllable ending consonant-vowel-consonant doubles it
en_doubles(L) :-
    atom_length(L, N), N >= 3, en_syllables(L, 1),
    A is N - 3, sub_atom(L, A, 3, 0, Last3), atom_chars(Last3, [C1, V, C2]),
    \+ en_vowel(C1), en_vowel(V), \+ en_vowel(C2), \+ memberchk(C2, [w, x, y]).

en_vowel(V) :- memberchk(V, [a, e, i, o, u, y]).

%% ONE SYLLABLE, OR TWO ENDING IN `y', is what English gives an ending to.
%% The cost is stated: `narrow' and `simple' take `more' here where a
%% grammar allows narrower and simpler, and both are still READ.
en_short_adjective(L) :-
    en_syllables(L, N), ( N =< 1 -> true ; N =:= 2, atom_concat(_, y, L) ).

%% vowel groups, with a silent final `e' not counted
en_syllables(W, N) :-
    atom_chars(W, Cs0),
    ( append(Cs1, [e], Cs0), Cs1 \== [] -> Cs = Cs1 ; Cs = Cs0 ),
    en_groups(Cs, no, 0, N0), ( N0 < 1 -> N = 1 ; N = N0 ).

en_groups([], _, N, N).
en_groups([C|Cs], Prev, N0, N) :-
    (   en_vowel(C) -> ( Prev == yes -> N1 = N0 ; N1 is N0 + 1 ), P = yes
    ;   N1 = N0, P = no
    ),
    en_groups(Cs, P, N1, N).

%% bare adjectives, an `and' among them allowed: the predicate of a copula
tr_all_adjectives(Side, Words) :-
    Words \== [],
    forall(member(W, Words), tr_predicate_word(Side, W)),
    \+ forall(member(W, Words), tr_coord(Side, W)).

tr_predicate_word(_, deg(_, _)) :- !.
tr_predicate_word(_, degt(_, _, _)) :- !.
%% A CAPITALISED WORD INSIDE A SENTENCE IS NO ADJECTIVE on the lesson's side,
%% where the head was lowered when the lesson knows it (tr_head_lower/3):
%% `se a Milano va via Pellegrini' is the man, and `pellegrini' is also the
%% plural of `pellegrino', wandering -- read as what he was, the subject
%% nobody named went away and Pellegrini became `Peregrino'
tr_predicate_word(foreign, w(_, upper)) :- !, fail.
tr_predicate_word(Side, W) :- tr_is(Side, W, adjective), !.
tr_predicate_word(Side, W) :- tr_coord(Side, W).

%% THE SPOLETO FAULTS' HELPERS: a pronoun joined to a phrase (tr_complements0/4), the word before a person in two
%% joined objects (tr_comp_out/7), and the word a verb or a participle takes before the infinitive after it
%% (tr_comp_out/7, tr_comps_out/7, tr_fronts_out/5)
%% (nor a pronoun a coordinator joins to a phrase after it: `vede lui e il gatto' sees him and the cat, one object of
%% two, which the phrase reader below reads -- taken alone, the pronoun left `e il gatto' to read as nothing, and the
%% clause was refused, where `il gatto e lui' read)
tr_pronoun_joined(Side, [K, D|_]) :- K = w(_, _), tr_coord(Side, K), D = w(_, _), tr_determiner(Side, D, _, _), !.
%% (never before a name, which a capitalised word may be read as: `tempi e Modi della terapia' came out `tiempos y a
%% Modi')
tr_joined_marker(name(_), []) :- !.
%% (nor before a phrase whose noun is left out, which is of the class of the other one -- alone it is of any class:
%% `vede due stanche e tre gatti' sees two tired ones and three cats, and it came out `ve a dos cansadas')
tr_joined_marker(np(_, _, _, elided(_), _), []) :- !.
tr_joined_marker(ell(_, _, _, P), []) :- P \= pp(w(of, _), _), !.
tr_joined_marker(NP, M) :- tr_marker(foreign, NP, M).
tr_infx_lead(P) :-
    \+ tr_global('$tr_infx_kept', yes),
    %% (after a participle the infinitive is the participle's: `Per difendere il fratello, accusato di aver ucciso Sara,
    %% riesce a ...' is `acusado DE haber matado', where the clause's verb, `consigue', takes no word)
    (   tr_global('$tr_last_pred', L), L \== none
    ->  atom(L), tr_lexeme_across(L, foreign, VT), atom(VT), tr_solve(take_before(VT, P, infinitive))
    ;   tr_verb_takes(P)
    ), !.
%% the participle a complement list just wrote, for the infinitive after it (tr_infx_lead/1)
tr_note_pred(C) :- tr_verbal_inf(C), nb_setval('$tr_inf_seen', yes), fail.     % (tr_en_prep_gerund/1)
tr_note_pred(pred(L)) :- atom(L), !, nb_setval('$tr_last_pred', L).
tr_note_pred(obj(rel(_, L, _))) :- atom(L), !, nb_setval('$tr_last_pred', L).   % `il fratello, accusato di ...'
tr_note_pred(opred(L, _, _)) :- atom(L), !, nb_setval('$tr_last_pred', L).      % the same, agreeing with the object
tr_note_pred(_) :- nb_setval('$tr_last_pred', none).
%% an infinitive written where its word is written already, or by the clause around it
tr_with_infx_kept(G) :-
    tr_global('$tr_infx_kept', Old), nb_setval('$tr_infx_kept', yes),
    ( call(G) -> nb_setval('$tr_infx_kept', Old) ; nb_setval('$tr_infx_kept', Old), fail ).
%% an infinitive a clause's verb takes, in any of its forms
tr_verbal_inf(inf(_)).
tr_verbal_inf(infx(_, _, _)).
tr_verbal_inf(pinf(_, _)).
tr_verbal_inf(ainf(_, _)).
tr_verbal_inf(neg(C)) :- tr_verbal_inf(C).
tr_verbal_inf(qm(_, C)) :- tr_verbal_inf(C).
%% the word an infinitive's writer put before it (tr_comp_out/7's qm/2): English's `to' or the preposition of its
%% gerund, the lesson's word its verb takes
tr_inf_lead_word(english, W) :- tr_en_prep_gerund(W), !.
tr_inf_lead_word(foreign, W) :- tr_verb_takes(W), !.

%% ---- writing ------------------------------------------------------------------

%% (a clause written starts with no participle noted for the infinitive after it, tr_infx_lead/1)
tr_write(_, _, _, _) :- nb_setval('$tr_last_pred', none), nb_setval('$tr_inf_seen', no), fail.
%% WHAT THE SPEAKER IS, AFTER THE SPEAKER: `Commenta Carlo Rognoni, Pds,
%% vicepresidente del senato e grande esperto di media: ...' (tr_report_appos/2)
%% stands after the name in the lesson's languages, where the verb comes first;
%% English puts the speaker before the verb and his apposition with him,
%% between commas -- written after the verb it was `Carlo Rognoni comments,
%% vice-president of the senate:'
tr_write(english, Kind, s(A, Su, G, Comps0), Outs) :-
    append(Pre, [subj_here, sep, appos(NP)|Tail], Comps0), tr_appos_tail(Tail),
    Su \= null(_, _), Su \== none, !,
    append(Pre, [subj_here], Comps),
    tr_write(english, Kind, s(A, app(Su, aside, comps([obj(NP)|Tail])), G, Comps), Outs).
%% AN INFINITIVE AFTER THE COPULA AND ITS ADJECTIVE IS SAID AFTER THEM, WITH `it'
%% BEFORE: `è necessario evitare che ci siano ... tre reti' is it is necessary to
%% avoid that there are three networks, and `È facile mangiare il pane' it is
%% easy to eat the bread -- the lesson's languages put such a subject after the
%% copula, and English, which writes its subject first, wrote `To avoid that
%% there are three nets is necessary'. Only where the source had it after
%% (subj_here); `Mangiare il pane è facile' keeps its order
tr_write(english, Kind, s(A, infs(L, ICs), g(Is, T, Asp, N), Comps0), Outs) :-
    atom(Is), en_copula_lexeme(Is), memberchk(subj_here, Comps0), append(Pre, [adj(J)|Post0], Comps0), !,
    subtract(Post0, [subj_here], Post), subtract(Pre, [subj_here], Pre1),
    append([Pre1, [adj(J), inf(L)|ICs], Post], Comps),
    tr_write(english, Kind, s(A, null(third, singular), g(Is, T, Asp, N), Comps), Outs).
%% AN ABSTRACT NOUN IN `-ism' IS ENGLISH'S WITH NO ARTICLE, where it names the thing itself: `con links contra el
%% nazismo y el racismo' are links against Nazism and racism, and `el terrorismo' terrorism -- the lesson's
%% languages say it with the article, and English wrote `the nazism and the racism'. A phrase of `of' after it keeps
%% the article (`the optimism of the Russian military'), and so does one with an adjective (`the Catalan nationalism')
tr_write(english, Kind, s(A, Su0, G, Comps0), Outs) :-
    tr_ism_comps(Comps0, Comps), ( en_ism_np(Su0, Su1) -> Su = Su1 ; Su = Su0 ),
    ( Comps \== Comps0 -> true ; Su \== Su0 ), !,
    tr_write(english, Kind, s(A, Su, G, Comps), Outs).
%% `NEITHER' IN A CLAUSE THAT DENIES NOTHING IS THE DENIAL AND `either' LAST: `El perro tampoco duerme' is the dog does
%% not sleep either, and English wrote `Neither the dog sleeps' -- the lesson's languages deny with the adverb alone
%% (`tampoco', `neanche'), where English's `neither' in front wants the verb before its subject
tr_write(english, Kind, s(A, Su, g(L, T, Asp, no), Comps0), Outs) :-
    select(C0, Comps0, Comps1), ( C0 = frn(adv(w(neither, _))) ; C0 = adv(w(neither, _)) ), !,
    append(Comps1, [either], Comps),
    tr_write(english, Kind, s(A, Su, g(L, T, Asp, yes), Comps), Outs).
%% `HAS' AND A COUNT OF YEARS IS AN AGE: `Tengo 14 años' is I am 14 years old -- the lesson's languages say how old
%% one is with the verb of having, and English wrote `I have 14 years'. The count is what the verb took first, read as
%% a time (at_time/1) or an object, and English writes it with the copula and `old' (age/1)
tr_write(english, Kind, s(A, Su, g(has, T, Asp, N), [X|Rest]), Outs) :-
    ( X = at_time(NP) ; X = obj(NP) ), NP = np(none, Num, [], w(U, _), _), Num \== none, memberchk(U, [year, month]), !,
    tr_write(english, Kind, s(A, Su, g(is, T, Asp, N), [age(NP)|Rest]), Outs).
%% `ALL' AFTER THE VERB OF A PLURAL SUBJECT NOBODY NAMES IS THE SUBJECT'S: `Così partimmo tutti' is so we all
%% left, and `se la presero tutti a male' they all took it badly -- the lesson's languages put the pronoun for
%% `all' after the verb, and read as the verb's object English wrote `we departed everyone', `they took it
%% everyone to badly'. English writes it after the subject's pronoun ('$tr_subj_all', tr_subject_out/6); a
%% plural object pronoun keeps it (`li abbiamo visti tutti', we saw them all)
tr_write(english, Kind, s(A, null(P, plural), G, Cs0), Outs) :-
    select(opron(w(everyone, C)), Cs0, Cs),
    \+ ( member(X, Cs), ( X = opron(w(them, _)) ; X = obj(np(_, _, _, _, plural)) ; X = obj(co(_, _, _)) ) ), !,
    nb_setval('$tr_subj_all', C),
    (   tr_write(english, Kind, s(A, null(P, plural), G, Cs), Outs)
    ->  nb_setval('$tr_subj_all', none)
    ;   nb_setval('$tr_subj_all', none), fail
    ).
%% THE ONE WHO LIKES IS ENGLISH'S SUBJECT: `Mi piace il cane' is I like the dog, and `Forse non le era piaciuto' she
%% had not liked it. The lesson's languages make the thing liked the subject and the one who likes it a dative
%% (`piace', `gusta': pleases), and English wrote `The dog pleases me', or refused the clause where nobody is named.
%% A verb of pleasing with a person's pronoun among its complements -- a dative, or any pronoun of `pleases' -- is
%% written with that person for its subject and the subject for its object, `it' or `them' where nobody is named
tr_write(english, Kind, s(A, Su, g(V, T, Asp, N), Cs0), Outs) :-
    memberchk(V, [pleases, likes]), Asp \== passive,
    select(opron(P0), Cs0, Cs1), ( P0 = dat(w(P, _)) -> true ; V == pleases, P0 = w(P, _) ),
    atom(P), en_object_of(SP, P), SP \== it, en_liker_person(SP, Pers, Num),
    %% (the person a phrase of `to' names is the one the pronoun stands for, said again: `A ella le gustan los
    %% helados' is she likes them and `A Tom le gustan las morenas' Tom does, never `He likes them to Tom')
    (   select(pp(w(to, _), Liker), Cs1, Cs1b), tr_liker_phrase(Liker, Subject) -> true
    ;   Cs1b = Cs1, Subject = pronoun(Pers, Num, w(SP, lower))
    ),
    (   Su = null(third, singular), member(IC, Cs1b), tr_english_inf_lexeme(IC, _) -> Os = []     % (`Mi piace dormire': I like to sleep)
    ;   Su = null(third, SN) -> ( SN == plural -> Os = [opron(w(them, lower))] ; Os = [opron(w(it, lower))] )
    ;   Su = pronoun(_, _, w(SW, _)) -> atom(SW), en_object_of(SW, OW), Os = [opron(w(OW, lower))]
    ;   Su = null(_, _) -> fail
    %% (and an infinitive liked is the infinitive after `likes': `a me piace stare in mezzo alla gente' is I
    %% like to be among the people, and as an object it had no writer and the sentence was refused)
    ;   Su = infs(L0, ICs) -> ( L0 = state(L) -> true ; L = L0 ), Os = [inf(L)|ICs]
    ;   Os = [obj(Su)]
    ),
    \+ memberchk(obj(_), Cs1b), !,
    delete(Cs1b, subj_here, Cs2), append(Os, Cs2, Cs3),
    tr_write(english, Kind, s(A, Subject, g(likes, T, Asp, N), Cs3), Outs).
%% WHAT LACKS TO SOMETHING IS MISSING FROM IT: `al dibattito italiano mancavano gli strumenti analitici' -- the
%% analytical tools were missing from the Italian debate, and `che mancano alla sua collezione' the ones that are
%% missing from his collection, where English wrote `lacked to' and `lack to'. The lesson's `manca' lacks, and with no
%% object and a phrase of `to' its subject is what is not there (an object after an infinitive or a purpose is theirs:
%% `mancavano gli strumenti analitici per cogliere gli effetti')
tr_write(english, Kind, s(A, Su, g(lacks, T, Asp, N), Cs0), Outs) :-
    Asp \== passive,
    append(Pre, [pp(w(to, C), Y)|Post], Cs0), \+ memberchk(obj(_), Pre),
    \+ ( append(PostPre, [obj(_)|_], Post), \+ ( member(X, PostPre), tr_infinitive_comp_any(X) ) ), !,
    append(Pre, [pp(w(from, C), Y)|Post], Cs),
    tr_write(english, Kind, s(A, Su, g('is missing', T, Asp, N), Cs), Outs).
%% (and English's wish is `would like' before an infinitive: `quisiera saber' is I would like to know, where `would
%% want to know' was written)
tr_write(english, Kind, s(A, Su, g(wants, conditional, simple, N), [inf(L)|Cs]), Outs) :-
    Su \= null(third, singular), !,
    tr_write(english, Kind, s(A, Su, g(likes, conditional, simple, N), [inf(L)|Cs]), Outs).
%% `RETURNS TO' AND AN INFINITIVE IS THE INFINITIVE'S VERB `AGAIN': `volvió a hacer los plafones dañados' made the
%% damaged panels again, `volveré a llamar' I will call again -- `volver a' is the lesson's `return to', and English
%% wrote `returned to make' (the lesson's languages keep it: `tornò a fare')
tr_write(english, Kind, s(A, Su, g(returns, T, Asp, N), [ainf(w(to, _), L)|Cs]), Outs) :-
    atom(L), !, append(Cs, [adv(w(again, lower))], Cs1),
    tr_write(english, Kind, s(A, Su, g(L, T, Asp, N), Cs1), Outs).
%% `MAKES' WITH NOTHING MADE IS `DOES': `Che dovrebbe fare Berlusconi?' is what
%% should he DO, `chi compra ... lo fa a suo rischio' does it at his own risk
%% and `non fa niente' does nothing -- the lesson's `fa' and `hace' mean
%% `makes', which English says only of something made: an object, an
%% infinitive (`lo fa piangere', makes him cry) or a predicate. The clitic
%% `lo' is `it' then, the thing done, where the lesson's first word for it is
%% `him'
tr_write(english, Kind, s(A, Su, g(makes, T, Asp, N), Comps0), Outs) :-
    tr_makes_does(A, Comps0, Comps), !,
    tr_write(english, Kind, s(A, Su, g(does, T, Asp, N), Comps), Outs).
%% (and its infinitive after a modal: `Che dovrebbe fare Berlusconi?')
tr_write(english, Kind, s(A, Su, G, Comps0), Outs) :-
    append(Pre, [inf(makes)|Post0], Comps0), \+ ( member(C, Pre), tr_makes_made(C) ),
    tr_makes_does(A, Post0, Post), !,
    append(Pre, [inf(does)|Post], Comps),
    tr_write(english, Kind, s(A, Su, G, Comps), Outs).
%% (and with its pronoun joined: `no pienso hacerlo' is I do not intend to DO IT, where it was `to make him')
tr_write(english, Kind, s(A, Su, G, Comps0), Outs) :-
    append(Pre, [infx(makes, IA, [w(P, C)])|Post], Comps0), memberchk(P, [him, it]), \+ ( member(X, Post), tr_makes_made(X) ), !,
    append(Pre, [infx(does, IA, [w(it, C)])|Post], Comps),
    tr_write(english, Kind, s(A, Su, G, Comps), Outs).
%% A VERB OF SAYING WITH A PERSON'S PRONOUN AND WHAT IS SAID, A CLAUSE OF `that' OR AN OBJECT, IS `TELLS':
%% `gli esperti ci dicono che ...' TELL us that, `Te estoy diciendo la verdad' I am telling you the truth,
%% and English wrote `say us that' -- `says' takes a person only after `to'. With neither the pronoun may
%% be what is said, `A dirlo è Giuseppe Signori' (Signori says it), or the person beside it, `te lo digo'
%% (I say it to you)
%% -- or an infinitive right after the pronoun: `il mio fratellino mi disse di stare attento' TOLD me to take care,
%% and English wrote `said me to take care'
tr_write(english, Kind, s(A, Su, g(says, T, Asp, N), Comps), Outs) :-
    (   memberchk(that(_), Comps) -> true
    ;   memberchk(obj(_), Comps) -> true
    ;   Comps = [opron(_), I|_], ( I = inf(_) ; I = infx(_, simple, _) )
    ),
    once(( member(opron(w(P, _)), Comps), memberchk(P, [me, you, him, her, us, them, 'you all']) )), !,
    tr_write(english, Kind, s(A, Su, g(tells, T, Asp, N), Comps), Outs).
%% A VERB OF STOPPING OR KEEPING ON TAKES THE GERUND: `i cellulari non smettono di trillare' do not stop
%% RINGING, and with `to' it was `do not quit to ring' -- the infinitive the verb takes, its first complement
%% after its adverbs, and no other: a purpose's infinitive after `keeps' keeps its `to' (`mantuvieron ...
%% para intentar avanzar' kept a meeting to try to advance, and asked of every infinitive the clause wrote
%% it was `to try advancing'). A reflexive `stops' is a halt, which takes the infinitive of what it is for:
%% `si ferma a mangiare' stops to eat
%% THE IMPERSONAL `se' WITH A PERSON FOR ITS VERB'S OBJECT IS ENGLISH'S PASSIVE, the person its subject: `que no se
%% les hubiera alertado con anterioridad' is that THEY had not been alerted beforehand, and `Si se hubiera advertido
%% a la gente' if the people had been warned -- written with the impersonal subject they were `that one had not
%% alerted them' and `If one had warned to the people'. A verb whose English takes a person for its object (warns,
%% alerts, informs), the person a pronoun of the verb's own or its phrase of `to'
tr_write(english, Kind, s(A, impersonal, g(V, T, Asp, N), Comps0), Outs) :-
    atom(V), en_person_passive(V), memberchk(Asp-PA, [simple-passive, perfect-passive_perfect]),
    (   select(opron(dat(w(P, _))), Comps0, Comps), en_object_subject(P, Su) -> true
    ;   ( select(pp(w(to, _), NP), Comps0, Comps) ; select(obj(NP), Comps0, Comps) ), tr_of_class(NP, person) -> Su = NP
    ), !,
    tr_write(english, Kind, s(A, Su, g(V, T, PA, N), Comps), Outs).
%% A DENIED CLAUSE WHOSE SUBJECT SAYS `more' DENIES IN ITS SUBJECT: `No aparecen más artefactos' is `No more
%% devices appear', and with the denial on the verb it was `More devices do not appear'
tr_write(english, Kind, s(A, np(det(determiner, more, w(_, C)), Num, As, N, Nb), G0, Comps), Outs) :-
    G0 = g(V, T, Asp, yes), Kind == statement, !,
    tr_write(english, Kind, s(A, np(det(determiner, 'no more', w('no more', C)), Num, As, N, Nb), g(V, T, Asp, no), Comps), Outs).
%% THE PAST OF `must' BEFORE A PERFECT INFINITIVE IS `should have': `debían haber avisado a la población' should
%% have warned it, and `had to', the past `must' takes before a plain infinitive, said `had to have warned'
tr_write(english, Kind, s(A, Su, g(must, T, simple, N), Comps), Outs) :-
    memberchk(T, [past, imperfect]), memberchk(infx(_, perfect, _), Comps), !,
    tr_write(english, Kind, s(A, Su, g(must, conditional, simple, N), Comps), Outs).
%% (... and the infinitive with the word its verb takes before it: `muchos de los cuales han renunciado a
%% visitar las playas' have given up VISITING them)
tr_write(english, Kind, s(A, Su, g(V, T, Asp, N), Comps0), Outs) :-
    atom(V), en_gerund_verb(V), append(Pre, [I|Post], Comps0), ( I = inf(L) ; I = ainf(_, L) ), atom(L),
    forall(member(X, Pre), X = adv(_)), !,
    append(Pre, [ger(L, [])|Post], Comps),
    tr_write(english, Kind, s(A, Su, g(V, T, Asp, N), Comps), Outs).
%% A MODAL'S REFLEXIVE PASSIVE IS THE MODAL AND THE PASSIVE INFINITIVE: `Se pueden encontrar chats' -- chats can be
%% found, and written as the passive of the modal itself it was `Chats are caned find'. The infinitive after the
%% modal is what is done, written as the copula's infinitive and its participle, as `pueden ser encontrados' reads
tr_write(english, Kind, s(A, Su, g(reflexive(V), T, passive, N), Comps0), Outs) :-
    atom(V), en_modal_out(V, _, _), append(Pre, [inf(F)|Post], Comps0), !,
    append(Pre, [inf(is), pred(F)|Post], Comps),
    tr_write(english, Kind, s(A, Su, g(V, T, simple, N), Comps), Outs).
%% A VERB THAT SHOWS WHAT ONE IS, WITH ITS OWN PRONOUN AND A PREDICATE, IS `APPEARS': `i Tecnici si
%% mostrano ottimisti per il futuro' appear optimistic, and English wrote `display optimistic'
tr_write(english, Kind, s(A, Su, g(reflexive(V), T, Asp, N), Comps), Outs) :-
    atom(V), memberchk(V, [displays, shows]), once(( member(C, Comps), ( C = adj(_) ; C = pred(_) ) )), !,
    tr_write(english, Kind, s(A, Su, g(appears, T, Asp, N), Comps), Outs).
%% A PERFECT WITH A TIME THAT IS OVER IS ENGLISH'S PAST: `una frana è caduta ieri pomeriggio' FELL yesterday
%% afternoon, where the lesson's languages say what has happened with the perfect and English wrote `has
%% fallen ... yesterday afternoon'. The time is an adverb of a day before this one in the clause itself
tr_write(english, Kind, s(A, Su, g(L, present, perfect, N), Comps), Outs) :-
    once(( member(adv(w(D, _)), Comps), atom(D), en_past_time(D) )), !,
    tr_write(english, Kind, s(A, Su, g(L, past, simple, N), Comps), Outs).
%% THE REFLEXIVE PRONOUN AFTER A PREPOSITION IS THE SUBJECT'S: `estas formaciones entre sí' talk among THEMSELVES,
%% and the IR's word for `sí', `itself', came out whatever the subject was, `among itself'
tr_write(english, Kind, s(A, Su, G, Comps0), Outs) :-
    append(Pre, [pp(P, pronoun(w(itself, C)))|Post], Comps0), en_reflexive_of(Su, R), R \== itself, !,
    append(Pre, [pp(P, pronoun(w(R, C)))|Post], Comps),
    tr_write(english, Kind, s(A, Su, G, Comps), Outs).
%% A VERB ENGLISH TOO SAYS OF ONESELF WRITES ITS REFLEXIVE PRONOUN: `il sindaco si è dato ai servizi di
%% pubblica utilità' has dedicated himself to them, and with the pronoun dropped, as English drops a
%% lexical reflexive (`si appella' appeals), it was `has given to the services'. The pronoun is the
%% subject's: a plural one's `themselves', a person's `himself', or `herself' for a woman the source
%% names in the feminine, a thing's `itself', the speaker's and the hearer's their own -- a name, whose
%% gender the IR does not carry, keeps the verb bare
tr_write(english, Kind, s(A, Su, g(reflexive(V), T, Asp, N), Comps), Outs) :-
    atom(V), en_true_reflexive(V), \+ memberchk(obj(_), Comps), en_reflexive_of(Su, R), !,
    tr_write(english, Kind, s(A, Su, g(V, T, Asp, N), [opron(w(R, lower))|Comps]), Outs).
%% ... AND `puts' WITH ITS OWN PRONOUN AND NOTHING PUT IS PUTTING ONESELF SOMEWHERE: `me pongo a su disposición' is
%% I put MYSELF at his disposal, and with the pronoun dropped it was `I put at his disposal'. Only with a place or a
%% phrase to put it in, and never with what one becomes (`se puso nervioso') or begins to do (`se puso a comer')
tr_write(english, Kind, s(A, Su, g(reflexive(puts), T, Asp, N), Comps), Outs) :-
    \+ memberchk(obj(_), Comps), once(( member(X0, Comps), ( X0 = adv(_) ; X0 = pp(_, _) ) )),
    \+ ( member(X, Comps), ( X = adj(_) ; X = pred(_) ; X = ainf(_, _) ; X = inf(_) ; X = infx(_, _, _) ) ),
    en_reflexive_of(Su, R), !,
    tr_write(english, Kind, s(A, Su, g(puts, T, Asp, N), [opron(w(R, lower))|Comps]), Outs).
%% `RESULTS' BEFORE A PREDICATE IS `TURNS OUT': `i canali, i quali risultano più inquinati' turn out
%% more polluted, and `è risultato positivo al controllo' turned out positive -- the lesson's `risulta'
%% is `results', which English says only of what follows from something (`risulta da')
%% ... BUT A PARTICIPLE OF A VERB AFTER IT IS THE VERB'S PASSIVE: `donde resultó herido el artificiero' is where the
%% expert WAS INJURED, which English never says as `turned out injured' (Spanish's `resultar' with a participle says
%% what happened to the subject, `resultó elegido', `resultaron afectados')
tr_write(english, Kind, s(A, Su, g(R, T, Asp, N), Comps0), Outs) :-
    memberchk(R, [results, 'turns out']), memberchk(Asp-PA, [simple-passive, perfect-passive_perfect]),
    selectchk(pred(P), Comps0, Comps), atom(P), !,
    tr_write(english, Kind, s(A, Su, g(P, T, PA, N), Comps), Outs).
tr_write(english, Kind, s(A, Su, g(results, T, Asp, N), Comps), Outs) :-
    once(( member(C, Comps), ( C = adj(_) ; C = pred(_) ) )), !,
    tr_write(english, Kind, s(A, Su, g('turns out', T, Asp, N), Comps), Outs).
%% `ENDS UP' WITH NOWHERE TO END UP IS `ENDS': `le sorprese non finiscono qui'
%% do not END here. The lesson's intransitive `finisce' is `ends up' (`deve
%% finire in tribunale', the archbishop ending up in court), which English says
%% only of where or how a thing comes to be: a phrase, a predicate, a gerund,
%% or an adverb of place of several words (`in court'). With other adverbs, or
%% none, it is `ends', and so is its infinitive
tr_write(english, Kind, s(A, Su, g('ends up', T, Asp, N), Comps), Outs) :-
    \+ ( member(C, Comps), tr_ends_up_where(C) ), !,
    tr_write(english, Kind, s(A, Su, g(ends, T, Asp, N), Comps), Outs).
tr_write(english, Kind, s(A, Su, G, Comps0), Outs) :-
    append(Pre, [inf('ends up')|Post], Comps0), \+ ( member(C, Post), tr_ends_up_where(C) ), !,
    append(Pre, [inf(ends)|Post], Comps),
    tr_write(english, Kind, s(A, Su, G, Comps), Outs).
%% `there is': English's `there', the copula in the number of what there is
%% (`There are dogs') and `no' for the denial with the article dropped
%% (`There is no dog'); the lesson's verb and the phrase, no subject
%% two clauses joined: the first, the connector, the second. Only the
%% first carries the sentence's KIND -- a question mark belongs to the whole
%% -- and a comma is written with no space before it (tr_join/5).
tr_write(To, _, gap(Front, Back0), Outs) :- !,
    nb_setval('$tr_verb', none),                       % no verb: an object is no verb's, and takes no marker
    %% (the participles and adjectives after the comma agree with the phrase before it, as in a clause: `: un
    %% equipo compacto, organizado tácticamente y unido' is `una squadra compatta, organizzata ... e unita')
    (   To == foreign, Front = [_|_], Back0 = [_|_], append(Front, [sep|Back0], All0), tr_adj_after_comma(All0, All),
        append(Front, [sep|Back1], All)
    ->  Back = Back1
    ;   Back = Back0
    ),
    tr_gap_comps_out(To, Front, FO),
    %% (an adverb at the head of the rest, set off by its comma, stays there in English: `che è stato collocato,
    %% bene in vista, proprio alla sinistra del presidente' has been placed, in full view, precisely to the left of
    %% him -- written last with the clause's adverbs it was `placed, to the left of the president in full view')
    (   To == english, Back = [adv(w(A, AC)), sep|Back2]
    ->  tr_word_across(w(A, lower), english, adverb, AT), tr_gap_comps_out(To, Back2, BO2),
        BO = [o(AT, AC), o(',', comma)|BO2]
    ;   tr_gap_comps_out(To, Back, BO)
    ),
    ( FO == [] -> Outs = BO ; append(FO, [o(',', comma)|BO], Outs) ).
%% NOT ONLY ONE CLAUSE BUT ANOTHER (tr_read0/4): the words of nonly/3 round the
%% two clauses, the quotation mark that opened on the denial on its first
%% word, a comma before the partner, and the word for `that' after it where
%% the lesson says the partner takes one
tr_write(To, _, join(nonlyj(Also, NC), S1, S2), Outs) :- !,
    tr_nonly_words(To, Also, [o(No, _)], OnlyO, ButO, AlsoO),
    tr_write(To, statement, S1, O1), tr_write(To, statement, S2, O2),
    (   To == foreign, last(ButO, o(But, _)), tr_solve(take(But, clause)), tr_that_word(foreign, TW)
    ->  ThO = [o(TW, lower)]
    ;   ThO = []
    ),
    append([[o(No, NC)], OnlyO, O1, [o(',', comma)], ButO, ThO, AlsoO, O2], Outs).
%% (and where the first `ni' stands before the two clauses: `Ni el perro duerme ni el gato come', neither the dog
%% sleeps nor the cat eats)
tr_write(english, Kind, join(w(neither, C), none, join(w(neither, C2), S1, S2)), Outs) :- !,
    tr_write(english, Kind, join(w(neither, C), none, join(w(nor, C2), S1, S2)), Outs).
%% -- and a clause after a SUBORDINATING word is no question of its own,
%% whatever the sentence is: `¿Y si soy pobre?' came out `And if am I poor?'
tr_write(To, Kind, join(C, none, S20), Outs) :- !,
    tr_if_future(C, none, S20, S2),
    tr_connector_out(To, C, CO),
    ( ( C = w(T, _) ; C = wc(w(T, _)) ), atom(T), en_connector(T), \+ tr_coord(english, w(T, lower)) -> K2 = statement ; K2 = Kind ),
    tr_connector_mood(To, CO),
    tr_write(To, K2, S2, O2),
    append(CO, O2, Outs).
%% ... and a question with no mark of its own, a comma and a statement
%% (tr_read0/4): the first clause is written as the question it is, with the
%% question word in front and the verb in its place, and the statement after
%% the comma as it stands -- `Cosa le posso dire, sarà stato un equivoco'
tr_write(To, _, join(C, qh(S1), S2), Outs) :- !,
    tr_write(To, question, S1, O1), tr_connector_out(To, C, CO),
    tr_write(To, statement, S2, O2),
    append([O1, CO, O2], Outs).
%% ... and a question after a colon is the SECOND clause's (tr_read0/4):
%% the first is written as the statement it is
%% -- and the lesson's opening mark opens it there: `...: ¿en qué raza de
%% mundo nacerán mis hijos?'
tr_write(To, _, join(C, S1, q(S2)), Outs) :- !,
    tr_write(To, statement, S1, O1), tr_connector_out(To, C, CO),
    tr_write(To, question, S2, O20),
    %% (a second clause that is a statement and then a question of its own opens
    %% its mark there, not here: join(aside, S, q(Q)) of tr_read0/4)
    (   To == foreign, S2 \= join(aside, _, q(_)), once(tr_solve(begin(M, question))) -> O2 = [o(M, lower)|O20]
    ;   O2 = O20
    ),
    append(O1, CO, Front), append(Front, O2, Outs).
tr_write(To, Kind, join(C, S1, none), Outs) :- !,
    tr_write(To, Kind, S1, O1), tr_connector_out(To, C, CO), append(O1, CO, Outs).
%% THE SECOND `ni' OF TWO CLAUSES IS `nor' IN ENGLISH: `Así que ni se cerró el suculento trato ni la testigo entregó
%% los anillos' -- neither was the deal closed nor the witness handed over the rings, and each `ni' crossing as
%% `neither' English wrote `neither the witness handed'. The first clause opened on its own `neither'
tr_write(english, Kind, join(w(neither, C), S1, S2), Outs) :- tr_opens_neither(S1), !,
    tr_write(english, Kind, join(w(nor, C), S1, S2), Outs).
tr_write(To, Kind, join(C, S1, S20), Outs) :- !,
    tr_if_future(C, S1, S20, S2),
    tr_write(To, Kind, S1, O1),
    tr_connector_out(To, C, CO),
    %% ENGLISH LEAVES OUT A SUBJECT THE CLAUSE BEFORE NAMED: `Abachidze
    %% prefiere poner el acento en la corrupción e intenta aglutinar el
    %% voto' is one man doing both, and the second clause's subject nobody
    %% named refused the sentence -- `... and tries to agglutinate'
    %% (and after a comma where the first clause's subject stood after its
    %% verb between two commas: `Fruga in una scatola ..., Carolyn, sfoglia
    %% ...' is `Carolyn rummages in a box ..., leafs through ...')
    %% (and after a comma and a coordinator, join(C2, none, S): `Aragorn acude
    %% en auxilio de Frodo, que está herido, y aparta unas grandes piedras')
    %% ... AND AFTER A PLAIN COMMA, A SERIES OF PREDICATES: `Rosi ora è furioso,
    %% promette vendetta, vuole riprendersi il titolo' is one man being, promising
    %% and wanting -- the second and third clauses name nobody, and English wrote
    %% `they promise vengeance, they want' (a null subject is `they' to it). The
    %% subject elided in the middle of the series stands for the first one's
    %% ('$tr_chain': the clause before had its own elided)
    (   To == english,
        (   ( C = w(CW, _) ; C = wc(w(CW, _)) ), memberchk(CW, [and, or, but])
        ;   C == comma, S1 = s(_, _, _, Cs1), last(Cs1, subj_here)
        ;   C == comma, S2 = join(w(CW2, _), none, _), memberchk(CW2, [and, or, but])
        %% ... a plain comma only in a SERIES, a third clause after the second that
        %% names nobody either (`Rosi ora è furioso, promette vendetta, vuole
        %% riprendersi il titolo'); two clauses with a comma between them are a
        %% comma splice, which English writes with its pronoun (`The violins cannot
        %% be copied, they are unique'), and the third of a series follows the second
        ;   C == comma, S2 = join(comma, _, S2b), tr_first_statement(S2b, s(_, null(third, _), _, _))
        ;   C == comma, tr_global('$tr_chain', yes)
        ),
        %% (never of a subordinate clause standing alone: `prevede che il cane non
        %% possa dormire e a meno che non mangi entro un anno' is and unless IT eats,
        %% and elided it was `and unless eats')
        \+ ( S2 = join(w(SW, _), none, _), \+ memberchk(SW, [and, or, but]) ),
        %% (the subject the LAST clause before named: `Al inicio, cuando Gandalf
        %% lleva a Frodo en el carro, la pipa del mago aparece y desaparece')
        tr_last_statement(S1, S1L), S1L = s(_, Su1, _, _),
        (   Su1 \= null(_, _), Su1 \== none -> true
        ;   Su1 = null(third, _), tr_global('$tr_chain', yes)
        ),
        tr_first_statement(S2, S2s), S2s = s(_, null(third, N2), _, _),
        %% (and never the impersonal `si' with what it does: `... i detersivi quasi tutti biodegradabili e
        %% in molte zone della città si stanno installando delle fosse settiche' is THEY are installing
        %% them, nobody named, and elided the detergents were installing septic tanks)
        %% (an object after a comma, `sep', is an apposition: `L'esempio è citato e si riferisce al progetto, un tema
        %% grande' is the example referring)
        \+ ( S2s = s(_, _, g(reflexive(_), _, _, _), Cs2), append(Pre2, [obj(_)|_], Cs2), \+ last(Pre2, sep) ),
        %% (only a subject of the same person and number: `Io non parlo per
        %% quel bagnino ma in genere è così' is I and then it, and elided
        %% the second clause came out `I do not speak ... but is thus')
        \+ ( Su1 = pronoun(P1, _, _), P1 \== third ), \+ ( tr_front_number(Su1, N1), N1 \== N2 )
    ->  nb_setval('$tr_elide', yes), nb_setval('$tr_chain', yes)
    ;   nb_setval('$tr_chain', no)
    ),
    tr_connector_mood(To, CO),
    (   tr_write_second(To, S1, S2, O20) -> nb_setval('$tr_elide', no), nb_setval('$tr_chain', no)
    ;   nb_setval('$tr_elide', no), nb_setval('$tr_chain', no), fail     % (the next sentence is not elided by a refusal)
    ),
    ( C == dashes -> append(O20, [o('–', lower)], O2) ; O2 = O20 ),       % and the dash that closes it
    append(O1, CO, Front), append(Front, O2, Outs).
%% (a front with no comma is the clause below's, which writes it and comes
%% back here: `allora c'è spazio per qualche preoccupazione' is then there is
%% room, and with the connecting adverb kept in front this writer found it
%% among the complements and wrote nothing)
%% `NO LONGER' IS THE DENIAL AND `MORE' IN THE LESSON'S LANGUAGES: `El perro ya no
%% come' is `Il cane non mangia più', the denial before the verb and the word for
%% `more' right after it, where it was written `Il cane mangia non più'. English
%% keeps the one adverb, with the verb (en_mid_adverb/1)
tr_write(foreign, Kind, s(Asked, Subject, g(L, T, A, no), Comps0), Outs) :-
    select(adv(w('no longer', C)), Comps0, Comps1), !,
    tr_write(foreign, Kind, s(Asked, Subject, g(L, T, A, yes), [adv(w(more, C))|Comps1]), Outs).
tr_write(To, Kind, s(none, there, g(L, T, simple, Neg), Comps00), Outs) :-
    \+ memberchk(frn(_), Comps00),
    %% (the marks the clause carries, qs and qe: they stood first among the
    %% complements and no split below took them, so a quoted `there is' was
    %% refused)
    ( selectchk(qs, Comps00, Comps01) -> QS = yes ; Comps01 = Comps00, QS = no ),
    ( selectchk(qe, Comps01, Comps0) -> QE = yes ; Comps0 = Comps01, QE = no ),
    tr_existential_split(Comps0, LeadA, [obj(NP0)|MoreA0]), !,
    %% (an adjective with a phrase of its own stands after its noun, as in any clause, tr_comps_out/7: `ci sono i dati
    %% relativi a tutti gli istituti' are the data relative to all the institutes, where it was `the relative data to')
    (   To == english, MoreA0 = [PPa|MoreA1], tr_adj_takes_phrase(NP0, PPa, NPa)
    ->  NP = NPa, MoreA = MoreA1
    ;   NP = NP0, MoreA = MoreA0
    ),
    %% (an adverb of time or focus after the phrase stands with the verb, before it: `También hay escritos de
    %% personas de Barcelona' -- there are also writings, `ci sono anche scritti' -- where `There are writings
    %% ... also' was written, the adverb read at the head of the clause and written last)
    (   append(MPre, [adv(w(MA, MC))|MPost], MoreA), atom(MA), en_mid_adverb(MA)
    ->  append(LeadA, [adv(w(MA, MC))], Lead0), append(MPre, MPost, More0)
    ;   Lead0 = LeadA, More0 = MoreA
    ),
    %% (the word for `more' before the phrase of a denied `there is' is
    %% `anymore', last: `Non c'è più pane' is `There is no bread anymore',
    %% where it came out `There is more no bread')
    (   To == english, Neg == yes, selectchk(adv(w(more, _)), Lead0, Lead)
    ->  AnyMore = yes
    ;   Lead = Lead0, AnyMore = no
    ),
    nb_setval('$tr_verb', L),
    tr_lexeme_across(L, To, LT),
    tr_np_out(To, NP, NPOut0, _, Number),
    %% (and the adjectives after a comma agree with what there is: `ci saranno
    %% multe, addirittura "salate"' -- `incluso "caras"', where they agreed
    %% with nothing, `caros')
    ( To == foreign, tr_adj_after_comma([obj(NP)|More0], [obj(NP)|More1]) -> true ; More1 = More0 ),
    tr_comps_out(To, More1, none, Number, _, RestOuts, Advs), append(RestOuts, Advs, Rest0),
    ( AnyMore == yes -> append(Rest0, [o(anymore, lower)], Rest) ; Rest = Rest0 ),
    tr_lead_out(To, Lead, Number, LeadOuts),
    (   To == english
    ->  (   Neg == yes
        ->  (   NPOut0 = [o(NW, _)|_], memberchk(NW, [nothing, nobody, none]), ( NP = pronoun(_) ; NP = padj(_, _) )
            %% (a pronoun that denies by itself takes no `no': `Non c'è niente di nuovo' is there is nothing
            %% new, where it was `There is no nothing new')
            ->  Tail0 = NPOut0
            ;   ( NP = np(det(article, _, _), _, _, _, _) -> NPOut0 = [_|NPOut] ; NPOut = NPOut0 ), Tail0 = [o(no, lower)|NPOut]
            )
        ;   Tail0 = NPOut0
        ),
        %% (the adverbs after `will' or the copula: `there will then be no
        %% other restrictions', `there are therefore no dogs')
        (   T == future -> Front = o(will, lower), append(LeadOuts, [o(be, lower)|Tail0], Tail)
        ;   en_copula_form(third, Number, T, C), Front = o(C, lower), append(LeadOuts, Tail0, Tail)
        ),
        en_assemble(Kind, none, [], [o(there, lower)], [Front|Tail], Front, Tail, Rest, Outs0)
    %% (a language whose `there is' takes no definite phrase says the thing is there with its state
    %% copula: `non c'è più il carbone' is `ya no está el carbón', and `no hay más el carbón' is no
    %% Spanish -- `"hay" takes the indefinite.'; never in the past, where what there was is an event:
    %% `c'è stato il referendum' is `hubo el referéndum', never `estuvo')
    ;   (   NP = np(det(article, the, _), _, _, _, _), T \== past, atom(LT), tr_solve(take(LT, indefinite)),
            once(( tr_solve(auxiliary(SL)), tr_solve(mean(SL, is)), tr_class_of(SL, verb) ))
        ->  fo_group(SL, third, Number, T, simple, Neg, [], Group)
        ;   fo_group(LT, third, Number, T, simple, Neg, [], Group)    % `ci sono' agrees; `hay' has one form
        ),
        append([LeadOuts, NPOut0, Rest], After),
        fo_assemble(none, [], [], Group, After, Outs0)
    ),
    tr_qs_mark(QS, QE, Outs0, Outs).
%% ... BUT THE COPULA WITH `thus' ALONE IN FRONT AND NOBODY NAMED IS `it is thus' in English, as with the adverb
%% after it: `se così fosse stato, la Bx con l'urto avrebbe subìto una decelerazione' -- if it had been thus, and with
%% the front written apart the clause had nothing to say `it' of, and English refused it
tr_write(english, Kind, s(Asked, null(third, singular), G, [frn(adv(w(thus, C)))]), Outs) :-
    G = g(is, _, _, _), !,
    tr_write(english, Kind, s(Asked, null(third, singular), G, [adv(w(thus, C))]), Outs).
%% ... and a front that asks where or relates, in front with no comma
tr_write(To, Kind, s(Asked, Subject, G, Comps0), Outs) :-
    select(frn(_), Comps0, _), \+ memberchk(fr(_), Comps0), \+ memberchk(frc(_), Comps0), !,  % a punctuated front goes first
    findall(C, member(frn(C), Comps0), Fr), findall(C, ( member(C, Comps0), C \= frn(_) ), Comps),
    tr_fronts_out(To, Fr, FO),
    tr_write(To, Kind, s(Asked, Subject, G, Comps), O2),
    append(FO, O2, Outs).
%% AN ASIDE AFTER THE SUBJECT goes back after it, between its commas: the
%% sentence is written without it and the subject's words, which every
%% writer puts first in a statement, are found at its head
tr_write(To, Kind, s(none, Subject, G, Comps0), Outs) :-
    select(mid(_), Comps0, _), !,
    findall(C, member(mid(C), Comps0), Mid), findall(C, ( member(C, Comps0), C \= mid(_) ), Comps),
    tr_write(To, Kind, s(none, Subject, G, Comps), O2),
    (   tr_subject_out(To, Subject, SO, _, _, _), SO \== [], append(SO, After, O2),
        tr_fronts_out(To, Mid, MO)
    ->  (   Mid = [per(dash, _, _)]                     % who said so between its dashes, which it writes
        ->  append([SO, MO, After], Outs)
        ;   append([SO, [o(',', comma)], MO, [o(',', comma)], After], Outs)
        )
    ;   tr_fronts_out(To, Mid, MO), append(O2, MO, Outs)
    ).
%% the complements the source set off in front are written in front, and the
%% comma after them
tr_write(To, Kind, s(Asked, Subject, G, Comps0), Outs) :-
    ( memberchk(fr(_), Comps0) ; memberchk(frc(_), Comps0) ), !,
    findall(C, ( member(X, Comps0), ( X = fr(C) ; X = frc(C) ) ), Fr),
    findall(C, ( member(C, Comps0), C \= fr(_), C \= frc(_) ), Comps),
    %% (a front the clause's word set off with a comma before it too: `de
    %% que, como su predecesor, no les importa ...', frc/1)
    ( memberchk(frc(_), Comps0) -> Lead = [o(',', comma)] ; Lead = [] ),
    %% each in the order it stood, an adverb among them too -- and every one
    %% of them written, or the sentence is refused: a findall here dropped a
    %% phrase it could not write and wrote the rest
    %% (adjectives in front agree with the subject: `Egoístas y cobardes,
    %% continuarán ...', and in its gender where it names a noun: `Cansada y
    %% roja, la casa duerme', where they were written masculine)
    ( tr_front_number(Subject, FN) -> true ; FN = singular ),
    (   Subject \= null(_, _), tr_subject_out(To, Subject, _, _, _, FNoun) -> true ; FNoun = none ),
    ( To == english -> tr_abs_phrases(Fr, Fr1) ; Fr1 = Fr ),
    tr_fronts_out(To, Fr1, FNoun, FN, FO),
    tr_write(To, Kind, s(Asked, Subject, G, Comps), O2),
    append([Lead, FO, [o(',', comma)|O2]], Outs).
%% `HACE DOS AÑOS QUE NO ...' IS `IT HAS BEEN TWO YEARS SINCE ...': the verb `hace' with a time, a DENIED clause of
%% `that' and nobody named for its subject -- written as read English refused it (a verb with nobody to do it), and
%% `ago two years that the Inter did not occupy' was no sentence. The clause is not denied after `since': the years went by with
%% it undone, and it is the last time it was done that the sentence counts from
tr_write(english, _, s(none, null(third, singular), g(makes, present, simple, no), [at_time(NP), that(S0)]), Outs) :-
    S0 = s(A0, Su, g(L, _, _, yes), Cs),
    tr_with_time_noun(tr_np_out(english, NP, TOut, _, _)),
    tr_write_nested(english, s(A0, Su, g(L, past, simple, no), Cs), SOut), !,
    append([[o(it, lower), o(has, lower), o(been, lower)], TOut, [o(since, lower)], SOut], Outs).
%% `SE TRATA DE' IS `IT IS': `Se trata de la segunda hospitalización del líder del Kremlin' is the second one, and
%% read as the impersonal `one' and the verb's own lexeme it was `One treats of the second hospitalisation' (`se
%% trató de unos 10 kilos' the same, and Italian's `si tratta di'). The phrase of `of' is what the clause is, the
%% copula's object, and `it' its subject
tr_write(english, Kind, s(A, impersonal, g(V, T, simple, Neg), [pp(w(of, _), NP)|Cs]), Outs) :-
    memberchk(V, [treats, deals]),     % (Italian's `si tratta di' crosses by its first meaning, deals)
    tr_write(english, Kind, s(A, pronoun(third, singular, w(it, lower)), g(is, T, simple, Neg), [obj(NP)|Cs]), Outs), !.
%% A REPORTING CLAUSE KEEPS ITS SUBJECT WHERE THE SOURCE HAD IT, after the
%% verb and among the complements -- `ha contado a Sky Tg24 Tornaboni' --
%% which is where the lesson's language puts a speaker too. English writes
%% its subject first, and the place is simply dropped there.
tr_write(english, Kind, s(Asked, Subject0, G, Comps0), Outs) :-
    append(Pre0, [subj_here|Post], Comps0), !,
    %% (an adverb that says how much of the subject, right before it, is
    %% written before it: `Están inscritos unos 1.200 abogados' is `About
    %% 1,200 lawyers are registered', where it came last, `are registered about')
    (   append(Pre, [adv(w(A, C))], Pre0), en_object_adverb(A), Subject0 \= null(_, _)
    ->  Subject = advp(w(A, C), Subject0)
    ;   Pre = Pre0, Subject = Subject0
    ),
    %% (and the comma before a subject set at the end goes with it)
    ( Post == [], append(Pre1, [sep], Pre) -> Comps1 = Pre1 ; append(Pre, Post, Comps1) ),
    %% (a quotation that opened on the verb and closed in the subject, which
    %% English writes before the verb, opens on the subject: `"è sufficiente la
    %% mera assunzione" della sostanza' is `"the mere intake" of the substance
    %% is sufficient', never `the mere intake" "is sufficient')
    (   memberchk(vq, Comps1), tr_has_close_mark(Subject), tr_open_first(Subject, SubjectQ)
    ->  selectchk(vq, Comps1, Comps)
    %% (and one that closed on the noun of a subject set last closes where the clause ends: `"... hasta que no se haya
    %% resuelto el caso", dice Marta' is `until the case has been resolved", Marta says', where the mark stayed on the
    %% case, `until the case" has been resolved'; a mark inside the subject's phrase stays, `"è sufficiente la mera
    %% assunzione" della sostanza')
    ;   Post == [], \+ memberchk(qe, Comps1), Subject = np(_, _, _, w(_, qclose), _), \+ tr_strip_open(Subject, _),
        tr_strip_close(Subject, SubjectC)
    ->  SubjectQ = SubjectC, Comps = [qe|Comps1]
    ;   SubjectQ = Subject, Comps = Comps1
    ),
    tr_write(english, Kind, s(Asked, SubjectQ, G, Comps), Outs).
%% (the verb is chosen by its object as the general clause chooses it,
%% tr_verb_out/4: `¿Pararán por ello los bobalicones comentarios ...?' has
%% the comments for its subject and no object, and by the verb's first
%% meaning it came out `Fermeranno', the verb the lesson calls transitive)
tr_write(foreign, _, s(none, Subject, g(L, T, A, Neg), Comps00), Outs) :-
    append(_, [subj_here|_], Comps00), !,
    %% (the quotation marks the clause carries, put back as the general clause
    %% puts them: `che "dorme il gatto"' lost the mark that opened on the verb,
    %% `que duerme el gato"')
    ( selectchk(vq, Comps00, Comps0q) -> VQ = yes ; Comps0q = Comps00, VQ = no ),
    ( selectchk(vqc, Comps0q, Comps0v) -> VQC = yes ; Comps0v = Comps0q, VQC = no ),
    ( selectchk(vqp, Comps0v, Comps0s0) -> VQP = yes ; Comps0s0 = Comps0v, VQP = no ),
    ( selectchk(qs, Comps0s0, Comps0s1) -> QS = yes ; Comps0s1 = Comps0s0, QS = no ),
    ( selectchk(qe, Comps0s1, Comps0a) -> QE = yes ; Comps0a = Comps0s1, QE = no ),
    %% (the adjectives after a comma are said of the phrase before it with the subject after the verb
    %% as with it before: `Volaron bombas de harina contra un espectáculo, al parecer de muchas,
    %% vulgar y degradante' -- tr_adj_after_comma/2)
    ( tr_adj_after_comma(Comps0a, Comps0) -> true ; Comps0 = Comps0a ),
    append(Pre, [subj_here|Post], Comps0),
    ( L = reflexive(L0) -> true ; L = state(L0) -> true ; L0 = L ), nb_setval('$tr_verb', L0),
    tr_global('$tr_sbj', Sbj0), nb_setval('$tr_sbj', ind), tr_that_mood(Comps0, Neg),
    tr_subject_out(foreign, Subject, SubjectOut, Person, Number, Noun),
    tr_clause_gender(Subject, Noun, Comps0, SG),
    nb_setval('$tr_subject_gender', SG),
    append(Pre, Post, CompsV0), tr_passive_object(A, CompsV0, CompsV), tr_verb_out(foreign, L, CompsV, LT),
    tr_comps_out(foreign, Pre, Noun, Number, Cl1, O1, A1),
    tr_comps_out(foreign, Post, Noun, Number, Cl2, O2, A2),
    append(Cl1, Cl2, Clitics),
    tr_with_mood(Sbj0, fo_group(LT, Person, Number, T, A, Neg, Clitics, Group0)),
    tr_vq_mark(VQ, Group0, Group1), tr_vqc_mark(VQC, Group1, Group2), tr_vqp_mark(VQP, Group2, Group),
    tr_concat([Group, O1, SubjectOut, O2, A1, A2], Outs0),
    tr_qs_mark(QS, QE, Outs0, Outs).

%% THE WORD FOR `ALSO' BEFORE A SUBJECT IS WRITTEN WITH THE VERB IN ENGLISH,
%% where `even' and `only' stay in front: `Anche Maria dorme' is `Maria also
%% sleeps' (en_mid_adverb/1), never `Also Maria sleeps'. It travels in front
%% of the subject for the languages that write it there (tr_subject/6), and
%% goes back among the clause's adverbs for the one that does not
tr_write(english, Kind, s(Asked, Subject, g(L, present, simple, Neg), Comps), Outs) :-
    atom(L), \+ en_modal_out(L, _, _), en_since_comp(Comps),
    tr_write(english, Kind, s(Asked, Subject, g(L, present, perfect, Neg), Comps), Outs), !.
tr_write(english, Kind, s(Asked, Subject0, G, Comps), Outs) :-
    en_subject_adverb(Subject0, A, C0, Subject), en_mid_adverb(A), !,
    %% (the capital the word had at the head of the sentence goes with it:
    %% `Anche Rosi cade' is `Rosi also falls', never `Rosi Also falls')
    ( C0 == upper -> C = lower ; C = C0 ),
    tr_write(english, Kind, s(Asked, Subject, G, [adv(w(A, C))|Comps]), Outs).

tr_write(To, Kind, s(Asked, Subject, g(L, T, A, Neg0), Comps00), Outs) :-
    %% the quotation that opened on the verb, and the one that closed on it
    %% (tr_vq_add/4)
    ( selectchk(vq, Comps00, Comps0q) -> VQ = yes ; Comps0q = Comps00, VQ = no ),
    ( selectchk(vqc, Comps0q, Comps0v) -> VQC = yes ; Comps0v = Comps0q, VQC = no ),
    ( selectchk(vqp, Comps0v, Comps0s0) -> VQP = yes ; Comps0s0 = Comps0v, VQP = no ),
    %% ... and the one that opened on the clause's first word, which the
    %% clause's adjuncts had carried (tr_vq_open/4)
    ( selectchk(qs, Comps0s0, Comps0s1) -> QS = yes ; Comps0s1 = Comps0s0, QS = no ),
    ( selectchk(qe, Comps0s1, Comps0s) -> QE = yes ; Comps0s = Comps0s1, QE = no ),
    %% ... and the comma the source set between the subject and its verb
    %% (tr_read_generic/4)
    ( selectchk(scomma, Comps0s, Comps0g) -> SC = yes ; Comps0g = Comps0s, SC = no ),
    %% ... and the degree adverb that stood before the participle
    %% (tr_group_adverb/5), which goes back before it
    ( selectchk(gadv(GAdv), Comps0g, Comps) -> true ; Comps = Comps0g, GAdv = none ),
    %% a denied list BEFORE its verb is the whole denial: `Né Rivaldo né
    %% Overmars figurano', `Neither Rivaldo nor Overmars appears' -- with the
    %% verb denied as well it said the opposite in both
    %% ... AND A NEGATIVE PRONOUN FOR THE SUBJECT IS THE DENIAL IN ENGLISH, which
    %% has one to a clause: `non conta nulla' is `nothing counts'
    ( Subject = nei(_) -> Neg = no
    ; To == english, Subject = pronoun(_, _, w(NSW, _)), memberchk(NSW, [nothing, nobody]) -> Neg = no
    %% ... AND THE WORD FOR `ever' IN A DENIED CLAUSE IS `never', the denial in
    %% it: `non ha mai convinto' has never convinced, not `has not convinced
    %% ever' (below, where the adverb goes with the verb)
    ; To == english, Neg0 == yes, memberchk(adv(w(ever, _)), Comps) -> Neg = no
    ; Neg = Neg0 ),
    %% a reflexive verb is its own object, so no phrase after it takes the
    %% word the lesson puts before a person: `si è fatta male alla spalla,
    %% il bimbo alla manina' is the boy too, never `al niño'
    ( L = reflexive(L0) -> V = refl(L0) ; L = state(L0) -> V = L0 ; L0 = L, V = L0 ), nb_setval('$tr_verb', V),
    ( To == foreign -> tr_global('$tr_sbj', Sbj0), nb_setval('$tr_sbj', ind), tr_that_mood(Comps, Neg) ; Sbj0 = ind ),
    %% ... and the other way round: an impersonal subject with a modal is
    %% written as the lesson's impersonal modal when it has one, and then
    %% the modal is the whole of the subject: `si deve' is `hay que' -- so
    %% the lesson's impersonal word is not asked for, and a lesson that has
    %% `bisogna' and no impersonal `si' writes `Bisogna mangiare pane'
    (   To == foreign, Subject == impersonal, tr_impersonal_modal(L, IM)
    ->  LT = IM, ImpDrop = yes, SubjectOut = [], Person = third, Number = singular, Noun = none
    ;   tr_null_subject(To, Subject, L, Comps, SubjectW),
        %% (the noun the copula says a demonstrative is, for the demonstrative's gender: tr_subject_out/6)
        (   To == foreign, Subject = pronoun(third, singular, w(DW, _)), memberchk(DW, [this, that]), L == is,
            Comps = [obj(np(_, _, _, w(PN, _), PNb))|_], atom(PN)
        ->  nb_setval('$tr_dem_pred', p(PN, PNb))
        ;   nb_setval('$tr_dem_pred', none)
        ),
        tr_subject_out(To, SubjectW, SubjectOut0, Person, Number0, Noun),
        tr_verb_number(To, Noun, Number0, Number),
        (   SC == yes, SubjectOut0 \== [] -> append(SubjectOut0, [o(',', comma)], SubjectOut)
        %% (a relative clause set off after the subject closes with its comma
        %% before the verb, as English's subject writer closes it:
        %% `Questa proposta, che dovrebbe essere confermata dai membri, si
        %% produce' -- tr_set_off_subject/5)
        %% ... and one on its last phrase of `of' (`L'ufficio dello sceriffo, che declinò ..., riconobbe')
        ;   To == foreign, ( Subject = nrc(_, _, _) ; Subject = with(_, SPPs), last(SPPs, pp(_, nrc(_, _, _))) ),
            \+ last(SubjectOut0, o(',', _))
        ->  append(SubjectOut0, [o(',', comma)], SubjectOut)
        ;   SubjectOut = SubjectOut0
        ),
        tr_passive_object(A, Comps, CompsV), tr_verb_out(To, L, CompsV, LT), ImpDrop = no
    ),
    %% THE IMPERSONAL OF A REFLEXIVE VERB IS NOT THE REFLEXIVE TWICE: `ci si
    %% salva l'anima' is one saving one's soul, and written with the lesson's
    %% impersonal word before the verb's own it came out `Se se ahorra la
    %% alma', `si si salva', which nobody writes. A lesson names the
    %% impersonal's form before its reflexive (`"ci" is the impersonal of
    %% "si".'), and it goes before it; one that names none writes its pronoun
    %% that means `one' and stands alone, Spanish's `uno se salva el alma'
    (   To == foreign, Subject == impersonal, ImpDrop == no, LT = reflexive(LR),
        SubjectOut = [o(ImpW, _)], tr_reflexive_out(ImpW)
    ->  (   tr_solve(impersonal_of(IW, ImpW)) -> ImpRefl = clitics([o(IW, lower), o(ImpW, lower)]), LTR = LR
        ;   tr_one_pronoun(U) -> ImpRefl = subject([o(U, lower)]), LTR = LT
        ;   ImpRefl = no, LTR = LT
        )
    ;   ImpRefl = no, LTR = LT
    ),
    %% the subject's gender, for a passive participle to agree with
    tr_clause_gender(Subject, Noun, Comps, SG),
    nb_setval('$tr_subject_gender', SG),
    tr_asked_out(To, Asked, AskedOut),
    %% A GERUND STRAIGHT AFTER THE VERB IS THE VERB'S OWN, and a language may
    %% say it with an infinitive: `el disco compacto continúa aumentando su
    %% penetración' is `continua a aumentare' in Italian, where the gerund
    %% came out as itself, `continua accrescendo'. The lesson says which word
    %% its verb takes before an infinitive (`"continua" takes "a" before the
    %% infinitive.'), and a gerund that is the clause's only complement is
    %% written that way; one after an object is how the clause was done.
    (   To == foreign, Comps = [ger(GL, GCs)], tr_verb_takes(_)
    ->  Comps1 = [pger(GL, GCs)]
    ;   Comps1 = Comps
    ),
    %% A PARTICIPLE AFTER THE COMMA OF A PERFECT CLAUSE IS THE PERFECT'S, and
    %% never agrees: `avrebbe dissestato l'amministrazione, reso più lunghi i
    %% tempi e acuito la crisi' is would have disorganised, made longer and
    %% sharpened, and the participles were written as predicated of the
    %% subject -- `rendida', `afilada', the law's gender -- where Spanish's
    %% follow the auxiliary, `rendido', `afilado'. A verb whose perfect the
    %% lesson builds with the copula agrees, as the participle after it does
    (   To == foreign, A == perfect, L \= reflexive(_), atom(LT), \+ tr_unaccusative(LT), memberchk(pred(_), Comps1)
    ->  tr_perfect_preds(Comps1, Comps2p)
    ;   Comps2p = Comps1
    ),
    %% ... and a second verb the subject shares is written in the clause's
    %% tense and person: `rapì e uccise il duca' is `secuestró y mató al duque'
    ( memberchk(cverb(_), Comps2p) -> tr_cverbs(To, T, Person, Number, Comps2p, Comps2) ; Comps2 = Comps2p ),
    %% (whether the clause is denied, for a `but' among its complements:
    %% tr_connector_out/3 -- and put back, for the clause this one sits in)
    ( tr_global('$tr_denied', D0) -> true ; D0 = no ), nb_setval('$tr_denied', Neg),
    %% ... and English writes the adverbs of time and focus that stand with its
    %% verb before it (`also', `always', `never'): `Los perros también
    %% duermen' is `The dogs also sleep', where it came last, `sleep also'
    %% ... and the word for `more' in a denied clause is `anymore', last: `Non c'è
    %% più pane' is `There is no bread anymore', where it came out `There is
    %% more no bread' (the adverb stood before the object it was read with)
    %% (a clause whose denial a word of its own says, `nobody', too: `Oggi non ce n'è rimasto più nessuno' is today
    %% nobody is left anymore, and it was `nobody has remained more')
    (   To == english, ( Neg == yes -> true ; Neg0 == yes ), selectchk(adv(w(more, _)), Comps2, Comps2c)
    ->  AnyMore = yes
    ;   Comps2c = Comps2, AnyMore = no
    ),
    (   To == english, Neg0 == yes, Neg == no, selectchk(adv(w(ever, _)), Comps2c, Comps2n)
    ->  Comps2e = [adv(w(never, lower))|Comps2n], nb_setval('$tr_denied', yes)    % (`non ho mai scritto niente' is never anything)
    ;   Comps2e = Comps2c
    ),
    (   To == english, tr_pull_adverb(Comps2e, Comps3, MidAdv) -> true
    %% ... and so do the lesson's languages, for the adverb the lesson says goes with
    %% the verb (`The adverb "ya" precedes the verb.'): `el mundo ya tendrá' is
    %% `il mondo avrà già', where it was written last, `avrà una nuova miss già'
    ;   To == foreign, tr_pull_foreign_adverb(Comps2e, Comps3, MidAdv) -> true
    ;   Comps3 = Comps2e, MidAdv = none
    ),
    %% THE VERB OF KNOWING TAKES `HOW TO' BEFORE THE INFINITIVE THAT STANDS FIRST
    %% AMONG ITS COMPLEMENTS: `el Unicaja supo contrarrestar la apuesta' knew HOW
    %% TO counter it, where `knew to counter' was what the infinitive was (`non
    %% so cosa fare', with the question word before the infinitive, keeps its `to')
    ( To == english, LT == knows, Comps3 = [inf(HL)|Comps3t] -> Comps3h1 = [hinf(HL)|Comps3t] ; Comps3h1 = Comps3 ),
    ( To == foreign, tr_adj_after_comma(Comps3h1, Comps3h2) -> Comps3h0 = Comps3h2 ; Comps3h0 = Comps3h1 ),
    %% ... and the second `né' of a list is `nor' in English, the first `neither'
    ( To == english, memberchk(cnj(w(neither, _)), Comps3h0) -> tr_nor_list(Comps3h0, no, Comps3h) ; Comps3h = Comps3h0 ),
    tr_wh_verb_set(Comps3h),
    (   tr_comps_out(To, Comps3h, Noun, Number, Clitics, CompOuts, Advs) -> nb_setval('$tr_denied', D0)
    ;   nb_setval('$tr_denied', D0), fail
    ),
    (   To == english
    ->  %% `non è né bello né brutto' is one denial in Italian and two in English: the clause that
        %% is denied and opens its list with `neither' says it once, `is neither beautiful nor ugly'
        (   Neg == yes, memberchk(cnj(w(neither, _)), Comps3h) -> NegE = no ; NegE = Neg ),
        en_group(LT, Person, Number, T, A, NegE, Statement0, Front, Tail0),
        %% (a quotation that closes on the verb group of a clause whose complements are
        %% its object pronouns alone closes after them, which English writes after the
        %% verb: `"No es la primera vez que Air Europa me toma el pelo"' is `... fools me"',
        %% where the mark came out `fools" me')
        (   VQC == yes, Comps3h = [_|_], forall(member(X, Comps3h), X = opron(_)) -> VQC1 = no, VQE = yes
        ;   VQC1 = VQC, VQE = no
        ),
        tr_vq_mark(VQ, Statement0, Statement1), tr_vqc_mark(VQC1, Statement1, Statement2),
        tr_vqp_mark(VQP, Statement2, Statement3a), tr_gadv_insert(english, GAdv, Statement3a, Statement3),
        tr_mid_insert(MidAdv, Statement3, Statement4), tr_mid_insert(MidAdv, Tail0, Tail),
        %% ... AND A DAY'S ADVERB THE SOURCE PUT RIGHT AFTER ITS VERB STANDS BEFORE THE VERB
        %% WHERE THE CLAUSE RUNS LONG, as a newspaper writes it: `El jefe guerrillero ...
        %% lanzó ayer un llamamiento ... en una cadena de televisión chechena, según la
        %% cadena ... RTR' YESTERDAY launched an appeal, and written last it came after the
        %% network that told of it. A clause of a few words keeps it last (`ate the bread
        %% yesterday'), and so does a verb group of more than one word
        (   Kind == statement, A == simple, memberchk(T, [past, present]), Comps3h = [adv(w(D, _))|_], en_day_adverb(D),
            selectchk(o(D, DC), Advs, Advs1), en_long_tail(CompOuts)
        ->  %% (after a copula that stands alone: `Kallon de 21 años y Ventola, de 23, son hoy el
            %% exponente' ARE today the exponent, and before it it was `today are')
            ( Statement4 = [o(B, _)], en_aux_alone(B) -> append(Statement4, [o(D, DC)], Statement) ; Statement = [o(D, DC)|Statement4] ),
            AdvsW = Advs1
        ;   Statement = Statement4, AdvsW = Advs
        ),
        %% (an adverb the IR has after the complement that closes the quotation stood outside it:
        %% `mentre oggi l'inquinamento "è inferiore a quello di trenta anni fa"' is `... ago" today')
        ( last(Comps3h, adv(_)) -> append(CompOuts, AdvsW, Rest0) ; tr_close_after_advs(CompOuts, AdvsW, Rest0) ),
        ( AnyMore == yes -> append(Rest0, [o(anymore, lower)], Rest) ; Rest = Rest0 ),
        en_assemble(Kind, Asked, AskedOut, SubjectOut, Statement, Front, Tail, Rest, Outs0a),
        tr_vqc_mark(VQE, Outs0a, Outs0),
        tr_qs_mark(QS, QE, Outs0, Outs)
    ;   %% the impersonal word goes AFTER the object pronouns where the
        %% lesson says it follows them: Italian's `li si chiamerà'
        (   ImpDrop == yes
        ->  Clitics1 = Clitics, SubjectOut1 = []
        ;   ImpRefl = clitics(IC)
        ->  append(Clitics, IC, Clitics1), SubjectOut1 = []
        ;   ImpRefl = subject(US)
        ->  Clitics1 = Clitics, SubjectOut1 = US
        ;   Subject == impersonal, SubjectOut = [o(ImpW, _)], tr_holds(follow(ImpW, pronoun))
        ->  append(Clitics, [o(ImpW, lower)], Clitics1), SubjectOut1 = []
        %% ... and after the denial, as a pronoun before the verb is: `Non si
        %% sa', `No se sabe' -- written as a subject it came out `se no sabe'
        ;   Subject == impersonal, Neg == yes, SubjectOut = [o(ImpW, _)]
        ->  Clitics1 = [o(ImpW, lower)|Clitics], SubjectOut1 = []
        %% ... and after a question word: `Quanto si spende?' is `¿Cuánto se
        %% gasta?', where the word an question puts the subject after the verb
        %% (fo_assemble/6) left it `¿Cuánto gasta se?'
        ;   Subject == impersonal, Asked \== none, SubjectOut = [o(ImpW, _)]
        ->  Clitics1 = [o(ImpW, lower)|Clitics], SubjectOut1 = []
        ;   Clitics1 = Clitics, SubjectOut1 = SubjectOut
        ),
        %% THE PROGRESSIVE OF A PASSIVE IS THE VERB THE LESSON SAYS MARKS THE
        %% PASSIVE, where it names one: `está siendo presionado' is `is being
        %% pressured', and Italian says `viene pressato' -- `sta essendo
        %% pressato' is a progressive Italian does not build. A lesson that
        %% names no such verb writes its copula's progressive, as Spanish does
        (   A == progressive, L == is, Comps = [pred(_)|_], tr_solve(mark(PV, passive))
        ->  LT1 = PV, A1 = simple
        %% A VERB THE LESSON BUILDS WITH THE COPULA BUILDS ITS PERFECT WITH
        %% `HAS' WHERE THE CLAUSE HAS AN OBJECT OF ITS OWN: `"è" is the
        %% auxiliary of "aumenta".' is for `i prezzi sono aumentati', and
        %% `el gobierno ha aumentado el gasto' came out `il governo è
        %% aumentato il costo' -- the same for `finisce', `passa'. The
        %% intransitive perfect takes the lesson's word; a clause with an
        %% object takes the one that means `has', as it did before the line --
        %% never the copula's own, whose predicate is no object: `ha sido un
        %% gran Senegal' is `è stato un gran Senegal'
        ;   A == perfect, atom(LTR), tr_clause_object(Comps), \+ tr_copula_lexeme(LTR), tr_solve(auxiliary_of(_, LTR))
        ->  LT1 = LTR, A1 = perfect_has
        %% ... AND SO DOES A VERB OF BEGINNING WITH AN INFINITIVE AFTER IT: `ha
        %% comenzado a recoger información' is `ha iniziato a raccogliere', never
        %% `è iniziato a raccogliere' -- the copula is for `è iniziato il vertice',
        %% where nothing follows the verb (what the infinitive takes is its own
        %% object, not the clause's)
        ;   A == perfect, atom(LTR), tr_beginning_verb(L), memberchk(ainf(_, _), Comps),
            \+ tr_copula_lexeme(LTR), tr_solve(auxiliary_of(_, LTR))
        ->  LT1 = LTR, A1 = perfect_has
        ;   LT1 = LTR, A1 = A
        ),
        %% ... and the impersonal's own perfect agrees with what was done
        %% (tr_impersonal_gender/3) -- its GROUP, written after the
        %% complements, which keep the subject's gender
        (   A == perfect, tr_impersonal_gender(Subject, Comps, IG) -> nb_setval('$tr_subject_gender', IG) ; true ),
        %% THE IMPERSONAL WORD BUILDS ITS PERFECT AS THE REFLEXIVE DOES: `tal y
        %% como se había anunciado' is `come si era annunciato', and with the
        %% auxiliary that means `has' it came out `si aveva annunciato' -- the
        %% lesson's `"è" is the auxiliary of the reflexive.' says which
        (   Subject == impersonal, ImpDrop == no
        ->  tr_global('$tr_refl', R0), nb_setval('$tr_refl', yes),
            (   tr_with_mood(Sbj0, fo_group(LT1, Person, Number, T, A1, Neg, Clitics1, Group0)) -> nb_setval('$tr_refl', R0)
            ;   nb_setval('$tr_refl', R0), fail
            )
        ;   tr_with_mood(Sbj0, fo_group(LT1, Person, Number, T, A1, Neg, Clitics1, Group0))
        ),
        %% ... AND THE QUOTATION THAT OPENED ON THE VERB OPENS ON THE IMPERSONAL
        %% WORD WRITTEN BEFORE IT: `"bisogna leggere ..."' is `"se necesita
        %% leer ..."', where the mark stood on the verb after the `se'
        (   VQ == yes, Subject == impersonal, ImpDrop == no, SubjectOut1 = [_|_]
        ->  tr_vq_mark(yes, SubjectOut1, SubjectOut2), VQ1 = no
        ;   SubjectOut2 = SubjectOut1, VQ1 = VQ
        ),
        tr_vq_mark(VQ1, Group0, Group1), tr_vqc_mark(VQC, Group1, Group2),
        tr_vqp_mark(VQP, Group2, Group3), tr_gadv_insert(foreign, GAdv, Group3, Group4),
        %% (the word that precedes the verb stands before the impersonal word too: `ya se puede decir')
        (   MidAdv = fadv(MT, before, MC), Subject == impersonal, SubjectOut2 = [_|_]
        ->  SubjectOut3 = [o(MT, MC)|SubjectOut2], Group = Group4
        ;   SubjectOut3 = SubjectOut2, tr_fo_mid_insert(MidAdv, A1, Group4, Group)
        ),
        append(CompOuts, Advs, Rest),
        fo_assemble(Asked, AskedOut, SubjectOut3, Group, Rest, Outs0),
        tr_qs_mark(QS, QE, Outs0, Outs)
    ).
tr_ism_comps([], []).
tr_ism_comps([C0|Cs0], [C|Cs]) :-
    (   \+ ( Cs0 = [pp(w(of, _), _)|_] ),
        (   C0 = obj(NP0), en_ism_np(NP0, NP) -> C = obj(NP)
        ;   C0 = pp(P, NP0), en_ism_np(NP0, NP) -> C = pp(P, NP)
        )
    ->  true
    ;   C = C0
    ),
    tr_ism_comps(Cs0, Cs).
en_ism_np(np(det(article, the, _), none, [], w(N, C), singular), np(none, none, [], w(N, C), singular)) :-
    atom(N), ( atom_concat(_, ism, N) -> true ; en_mass_activity(N) ), !.
en_ism_np(co(K, A0, B0), co(K, A, B)) :-
    ( en_ism_np(A0, A1) -> A = A1 ; A = A0 ), ( en_ism_np(B0, B1) -> B = B1 ; B = B0 ),
    ( A \== A0 -> true ; B \== B0 ), !.
en_liker_person(i, first, singular).    en_liker_person(we, first, plural).
en_liker_person(you, second, singular). en_liker_person(he, third, singular).
en_liker_person(she, third, singular).  en_liker_person(they, third, plural).
tr_liker_phrase(pronoun(w(W, _)), pronoun(Pers, Num, w(SP, lower))) :-
    atom(W), en_object_of(SP, W), SP \== it, en_liker_person(SP, Pers, Num).
tr_liker_phrase(name(Nm), name(Nm)).
tr_liker_phrase(NP, NP) :- NP = np(_, _, _, _, _), tr_of_class(NP, person).
en_gerund_verb(V) :- memberchk(V, [stops, quits, finishes, keeps, avoids, enjoys, risks, misses, 'gives up']).
en_past_time(D) :- memberchk(D, [yesterday, 'last night', 'yesterday afternoon', 'yesterday morning', 'the day before yesterday']).
en_true_reflexive(V) :- memberchk(V, [dedicates, devotes, finds]).
en_reflexive_of(null(P, N), R) :- !, en_own_reflexive(P, N, R).
en_reflexive_of(pronoun(P, N, _), R) :- P \== third, !, en_own_reflexive(P, N, R).
en_reflexive_of(pronoun(third, plural, _), themselves) :- !.
en_reflexive_of(co(_, _, _), themselves) :- !.
en_reflexive_of(NP, R) :-
    NP = np(_, _, _, w(Noun, _), Number), !,
    (   Number == plural -> R = themselves
    ;   tr_of_class(NP, person) -> ( nb_getval('$tr_fem_persons', Fs), memberchk(Noun-singular, Fs) -> R = herself ; R = himself )
    ;   R = itself
    ).
en_own_reflexive(first, singular, myself).    en_own_reflexive(first, plural, ourselves).
en_own_reflexive(second, singular, yourself). en_own_reflexive(second, plural, yourselves).
en_own_reflexive(third, plural, themselves).
%% the complements of a clause with no verb, a participle among them agreeing
%% with the form the source gave it (agr/1, agrn/1) and the gender put back
tr_gap_comps_out(To, Cs0, Out) :-
    ( select(agr(G0), Cs0, Cs1) -> true ; Cs1 = Cs0, G0 = none ),
    ( select(agrn(N), Cs1, Cs) -> true ; Cs = Cs1, N = singular ),
    %% A PARTICIPLE AND AN INFINITIVE WITH NO SUBJECT ARE SAID OF THE
    %% INFINITIVE: `Questo tavolo decide: vietato truccare' is forbidden to rig,
    %% not a forbidden table -- it took the gender of the clause before the
    %% colon, `esta mesa decide: prohibida amañar'. The infinitive is masculine
    (   G0 == none, Cs = [pred(_), I|_], ( I = inf(_) ; I = infx(_, _, _) ) -> G = masculine ; G = G0 ),
    (   G == none
    ->  tr_comps_out(To, Cs, none, N, _, O1, A1)
    ;   ( catch(nb_getval('$tr_subject_gender', Old), _, fail) -> true ; Old = masculine ),
        nb_setval('$tr_subject_gender', G),
        (   tr_comps_out(To, Cs, none, N, _, O1, A1) -> nb_setval('$tr_subject_gender', Old)
        ;   nb_setval('$tr_subject_gender', Old), fail
        )
    ),
    append(O1, A1, Out).
%% THE FUTURE AFTER `IF' IS THE PRESENT in English and in the lesson's languages:
%% Italian's `se riusciremo a giocare' is `if we succeed in playing', `si logramos
%% jugar' -- never `if we will succeed', `si lograremos'. Of a text in a language
%% that writes its condition so (tr_future_protasis_language/1: Spanish's `si
%% vendrá' is a question, whether, and keeps the future), and not of the clause
%% that `if' joins to a clause that asks a question: a copula with nothing after
%% it or a verb of asking, saying and knowing (tr_whether_governor/1: `Il dubbio
%% è se il cane verrà o se il gatto dormirà' is the doubt is if the dog WILL
%% come), nor of the `or' clause after one ('$tr_whether', tr_write_second/4)
tr_if_future(C, S1, S20, S2) :-
    (   tr_global('$tr_future_protasis', yes), \+ tr_global('$tr_whether', yes), \+ tr_whether_governor(S1)
    ->  tr_if_future(C, S20, S2)
    ;   S2 = S20
    ).
tr_if_future(C, S0, S) :-
    ( C = w(if, _) ; C = wc(w(if, _)) ), !, tr_clause_present(S0, S).
tr_if_future(_, S, S).
%% (and both clauses of a condition joined by `and': `se Pedro verrà e porterà il pane')
tr_clause_present(s(A, Su, g(L, future, As, Neg), Cs), s(A, Su, g(L, present, As, Neg), Cs)) :- !.
tr_clause_present(join(K, A0, B0), join(K, A, B)) :-
    K = w(W, _), memberchk(W, [and, or, but]), !, tr_clause_present(A0, A), tr_clause_present(B0, B).
tr_clause_present(S, S).
tr_whether_governor(S1) :-
    S1 \== none, tr_last_statement(S1, s(_, _, g(L, _, _, _), Cs)), atom(L),
    (   L == is, ( Cs == [] ; Cs = [adj([w(A, _)])], memberchk(A, [doubtful, uncertain, unclear, unknown]) )
    ;   en_asks(L)
    ;   en_saying(L)
    ;   memberchk(L, [knows, decides, understands, establishes, doubts])
    ), !.
tr_whether_join(join(C, S1, _)) :- ( C = w(if, _) ; C = wc(w(if, _)) ), tr_whether_governor(S1).
tr_write_second(To, S1, S2, O) :-
    (   tr_whether_join(S1)
    ->  nb_setval('$tr_whether', yes),
        (   tr_write(To, statement, S2, O) -> nb_setval('$tr_whether', no)
        ;   nb_setval('$tr_whether', no), fail
        )
    ;   tr_write(To, statement, S2, O)
    ).
tr_future_protasis_note(Side) :-
    nb_setval('$tr_whether', no),
    (   Side == foreign, tr_language(L), tr_future_protasis_language(L)
    ->  nb_setval('$tr_future_protasis', yes)
    ;   nb_setval('$tr_future_protasis', no)
    ).
tr_future_protasis_language(italian).

tr_existential_split([obj(NP)|More], [], [obj(NP)|More]) :- !.
tr_existential_split([adv(A)|Cs], [adv(A)|Lead], Rest) :- tr_existential_split(Cs, Lead, Rest).
tr_existential_split([sep|Cs], [sep|Lead], Rest) :- tr_existential_split(Cs, Lead, Rest).   % `Hubo, sin embargo, un desliz'
%% ... written in the order it stood: English writes its adverbs after the
%% complements, and `There was, however, a slip' came out with both commas
%% before the adverb, and one of them lost
tr_lead_out(_, [], _, []).
tr_lead_out(To, [C|Cs], Number, Outs) :-
    tr_comp_out(To, C, none, Number, _, O, A), append(O, A, OA),
    tr_lead_out(To, Cs, Number, Os), append(OA, Os, Outs).
%% (AN ABSOLUTE CLAUSE IN FRONT IS ENGLISH'S PHRASE AND THEN ITS PARTICIPLE, as one that says how the verb
%% leaves its phrase is (abso/2): `Dimenticate le polemiche e messe da parte le idee ..., il sindaco ...' is
%% the controversies forgotten and the ideas put aside, and participle first it was `Forgotten the
%% controversies and put aside the ideas' -- but never the participle of a perfect infinitive, `Dopo aver
%% mangiato il pane, ...' is after having eaten the bread. The phrases of `of' and `like' after the phrase go
%% with it, before the participle: `messe da parte le idee di ferree ordinanze come quella dell'estate
%% scorsa' are the ideas of iron ordinances like that of last summer put aside, and the participle stood
%% between the ideas and what they were of, `The ideas put aside of iron ordinances')
tr_abs_phrases([pinf(P, has), X|Fr0], [pinf(P, has), X|Fr]) :- !, tr_abs_phrases(Fr0, Fr).
tr_abs_phrases([abs(L, NP)|Fr0], [abso(L, NP1)|Fr]) :- !,
    ( tr_abs_pps(Fr0, PPs, Fr1), PPs \== [] -> NP1 = with(NP, PPs) ; NP1 = NP, Fr1 = Fr0 ),
    tr_abs_phrases(Fr1, Fr).
tr_abs_phrases([X|Fr0], [X|Fr]) :- !, tr_abs_phrases(Fr0, Fr).
tr_abs_phrases([], []).
tr_abs_pps([pp(w(P, C), X)|Fr0], [pp(w(P, C), X)|PPs], Fr) :- memberchk(P, [of, like]), !, tr_abs_pps(Fr0, PPs, Fr).
tr_abs_pps(Fr, [], Fr).
%% A THIRD PERSON SINGULAR NOBODY NAMED IS WRITTEN IN ENGLISH WHERE THE VERB OR
%% THE PREDICATE SAYS WHAT IT IS: `it' for the copula with an adjective, a
%% clause or an infinitive after it (`Es injusto que ...' is `It is unjust
%% that ...'), and for the verbs of no agent (`suffices', `seems'); the
%% singular `they' for a verb of saying (`Añadió que ...', `They added that
%% ...'), which names neither a man nor a woman, who the source named neither.
%% Any other stays refused, as he, she and it are three claims
tr_null_subject(english, null(third, singular), L, Comps, pronoun(P, N, w(W, lower))) :-
    ( L = reflexive(L1) -> true ; L1 = L ), atom(L1),
    %% (`it' is nobody the clause before named, and stays where a coordination
    %% elides its subject: `Sofia è stata battezzata e mi sembra giusto' is `and
    %% it seems me just')
    (   en_null_it(L1, Comps) -> W = it, P = third, N = singular, ( tr_global('$tr_elide', yes) -> nb_setval('$tr_elide', no) ; true )
    %% (a verb of saying with a person for its object has the speaker after
    %% it, `dice el presidente', and no reading of that is a null subject;
    %% with a thing it is the verb's own, `y apuntó la necesidad de un pacto')
    %% (and not the second clause of a coordination that elides its subject:
    %% `Serra Ferrer no quiere correr riesgos y ha exigido ...' is one man,
    %% `and has demanded', never `and they have demanded' -- tr_write/4 on join/3)
    ;   \+ tr_global('$tr_elide', yes), en_null_they(L1), \+ ( member(obj(NP), Comps), tr_of_class(NP, person) ) -> W = they, P = third, N = plural
    ), !.
tr_null_subject(_, Subject, _, _, Subject).
%% the verbs that take a person and an infinitive in English where Spanish
%% has a clause: wanting for any phrase, asking for a person only
en_raising_verb(V, any) :- memberchk(V, [wants, wishes, prefers, needs]).
en_raising_verb(V, person) :- memberchk(V, [asks, orders, urges, advises, begs]).
%% the raised subject as the object it becomes: a phrase, or a pronoun in the
%% first or second person that the verb's ending named
tr_raised_subject(null(P, N), _, [o(O, lower)]) :- memberchk(P, [first, second]), !,
    en_subject(W, P, N), en_object_form(W, O), !.
tr_raised_subject(pronoun(_, _, w(W, _)), _, [o(O, lower)]) :- !, atom(W), en_object_form(W, O).
tr_raised_subject(Subject, Kind, Outs) :-
    ( Subject = np(_, _, _, _, _) ; Subject = name(_) ),
    ( Kind == person -> tr_of_class(Subject, person) ; true ),
    tr_comp_out(english, obj(Subject), none, singular, [], Outs, []).
en_object_form(i, me).     en_object_form(he, him).   en_object_form(she, her).  en_object_form(it, it).
en_object_form(we, us).    en_object_form(they, them). en_object_form(you, you).
en_null_it(is, Comps) :-
    member(C, Comps), ( C = adj(_) ; C = that(_) ; C = inf(_) ; C = obj(NP), ( \+ tr_of_class(NP, person) ; en_cleft_infinitive(Comps) ) ), !.
%% ... AND `IT IS BETTER', `IT IS WORSE': `È ancora meglio' -- an adverb that grades
%% what is said, with the copula and nobody named
en_null_it(is, Comps) :-
    member(adv(w(A, _)), Comps), memberchk(A, [better, worse]), !.
%% ... AND `IT IS SO': `Secondo Enrico Finzi, ..., è così' -- the adverb that says the thing said holds, and nothing else
en_null_it(is, [adv(w(thus, _))]) :- !.
en_null_it(V, _) :- memberchk(V, [suffices, matters, seems, appears, remains, happens, rains, snows]).
%% ... AND `IT BECOMES' AN ADJECTIVE TO DO SOMETHING: `diventa fondamentale stabilire il costo' -- it becomes essential to
%% establish it, and with nobody named English refused it. The adjective and the infinitive both: `diventa grande' says
%% nothing of what grows, and stays refused
en_null_it(becomes, Comps) :-
    memberchk(adj(_), Comps), ( memberchk(inf(_), Comps) ; memberchk(infx(_, _, _), Comps) ), !.
%% ... AND `IT COSTS' TO DO SOMETHING: `Quanto costa mantenere un figlio?' is how much does it cost to keep a son
en_null_it(costs, Comps) :- ( memberchk(inf(_), Comps) ; memberchk(infx(_, _, _), Comps) ), !.
%% ... AND A MODAL WITH THE COPULA AFTER IT, the same shapes: `Dovrebbe essere la
%% gente a giudicarmi' -- it should be the people to judge me. Read with nobody
%% named the modal was a verb of no agent, and English refused it
en_null_it(M, Comps) :-
    en_modal_out(M, _, _), memberchk(inf(is), Comps),
    member(C, Comps), ( C = adj(_) ; C = that(_) ; C = obj(NP), ( \+ tr_of_class(NP, person) ; en_cleft_infinitive(Comps) ) ), !.
%% ... AND A MODAL WITH A VERB OF NO AGENT AFTER IT: `Oggi può capitare di incontrarlo' -- it can happen to meet him,
%% as `Capita di incontrarlo' is it happens to; read with nobody named, English refused the modal
en_null_it(M, Comps) :-
    en_modal_out(M, _, _), Comps = [inf(V)|_], atom(V), memberchk(V, [suffices, matters, seems, appears, happens]), !.
%% a phrase and the infinitive that says what it does, after the copula, is a
%% cleft (`È il medico a decidere', it is the doctor to decide) and its `it' is
%% nobody's, a person or not
en_cleft_infinitive(Comps) :- memberchk(nprep(_), Comps), ( memberchk(infx(_, _, _), Comps) ; memberchk(inf(_), Comps) ), !.
%% (the verbs of saying, and those the paper says it with that a lesson gives
%% other English words for: `señaló' signals, `reconoció' recognises)
en_null_they(V) :- en_saying(V), !.
en_null_they(V) :- memberchk(V, [signals, indicates, recognises, recognizes, acknowledges, assures, ensures, points,
                                 pledges, promises, deplores, regrets, wishes, hopes, wants, asks, demands, requests,
                                 thinks, believes, considers, fears, knows, understands, doubts, expects, orders,
                                 prefers, proposes, recommends]).
%% A PRESENT THAT HAS GONE ON SINCE THEN IS THE PERFECT IN ENGLISH: `no gana el scudetto desde 1989' is
%% `has not won the title since 1989' and `vive aquí desde hace dos años' `has lived here for the past
%% two years', never `does not win ... since 1989' -- the lesson's languages say it in the present. Only a
%% plain present, and not a modal
%% -- never from a time to come: `fin dalla prossima riunione' is from the next meeting on; nor after a comma, where the
%% phrase is the aside's: `Pratesi, amico da anni della coppia' is a friend for years, and it is not the interview that has paralysed
en_since_comp(Comps) :- append(Before, [pp(w(P, _), NP)|_], Comps), \+ memberchk(sep, Before), memberchk(P, [since, 'for the past']), \+ en_future_np(NP), !.
en_future_np(np(_, _, Adjs, _, _)) :- member(A, Adjs), ( A = pre(w(W, _)) ; A = w(W, _) ), memberchk(W, [next, forthcoming, following, coming]), !.
en_future_np(with(NP, _)) :- en_future_np(NP).
%% (the adverb of a list of subjects stands before the first: `Anche Maria e
%% Paolo dormono', `Maria and Paolo also sleep')
en_subject_adverb(advp(w(A, C), Subject), A, C, Subject) :- Subject \= advp(_, _).
en_subject_adverb(co(Cn, advp(w(A, C), S1), S2), A, C, co(Cn, S1, S2)) :- S1 \= advp(_, _).
%% (WHAT THE SPEAKER IS, tr_write/4's: the apposition's phrases of a preposition, and a phrase apposed to the last of
%% them with its clause of `where':
%% `sostiene Rebeca López, vecina de Cala Crancs, el lugar donde resultó herido el artificiero' -- the place is Cala
%% Crancs, and all of it is what the speaker is)
tr_appos_tail(Tail) :- forall(member(T, Tail), T = pp(_, _)), !.
tr_appos_tail(Tail) :-
    append(PPs, [sep, obj(_)|Rest], Tail), PPs = [_|_], forall(member(T, PPs), T = pp(_, _)),
    forall(member(R, Rest), ( R = rwh(_, _) ; R = sep ; R = upon(_, _) )), !.
en_person_passive(V) :- memberchk(V, [warns, alerts, informs, notifies, advises, reproaches, blames, encourages]).
en_object_subject(them, pronoun(third, plural, w(they, lower))).
en_object_subject(him, pronoun(third, singular, w(he, lower))).
en_object_subject(her, pronoun(third, singular, w(she, lower))).
en_object_subject(us, pronoun(first, plural, w(we, lower))).
en_object_subject(me, pronoun(first, singular, w(i, lower))).

tr_qs_mark(QS, QE, Os0, Os) :- tr_qs_open(QS, Os0, Os1), tr_qs_close(QE, Os1, Os).
tr_qs_open(yes, [o(W, C0)|Os], [o(W, C)|Os]) :- !, ( C0 == qclose -> C = qboth ; C = qopen ).
tr_qs_open(_, Os, Os).
tr_qs_close(yes, Os0, Os) :- append(Front, [o(W, C0)], Os0), !,
    ( C0 == qopen -> C = qboth ; C = qclose ), append(Front, [o(W, C)], Os).
tr_qs_close(_, Os, Os).

tr_vq_mark(yes, [o(W, C0)|Os], [o(W, C)|Os]) :- !, ( C0 == qclose -> C = qboth ; C = qopen ).
tr_vq_mark(_, Os, Os).
tr_vqc_mark(yes, Os0, Os) :- append(Front, [o(W, C0)], Os0), !,
    ( C0 == qopen -> C = qboth ; C = qclose ), append(Front, [o(W, C)], Os).
tr_vqc_mark(_, Os, Os).
tr_vqp_mark(yes, Os0, Os) :- append(Front, [o(W, C0)], Os0), !,
    ( C0 == qclose -> C = qboth ; C = qopen ), append(Front, [o(W, C)], Os).
tr_vqp_mark(_, Os, Os).
%% the degree adverb before the group's last word, its participle
tr_gadv_insert(_, none, G, G) :- !.
tr_gadv_insert(To, w(A, AC), G0, G) :-
    tr_word_across(w(A, lower), To, adverb, T), append(G1, [Last], G0), !, append(G1, [o(T, AC), Last], G).
%% ... and the adverb of time or focus that stands with the verb: before its
%% last word, `has also claimed', `will always sleep', after a copula or a
%% modal that is alone, `is also', `can also eat' -- and in the question's tail
%% too, `Do the cats also eat the bread?'
tr_pull_adverb(Cs0, Cs, Adv) :-
    append(Pre, [adv(w(A, C))|Post], Cs0), atom(A), en_mid_adverb(A),
    %% (never `also' that opens an insertion on a phrase of a preposition, which it is said of: `la
    %% struttura urbana tende, anche con l'aiuto dell'acqua salmastra, a facilitare' tends, also with the
    %% help of the water, and pulled to the verb it was `also tends, with the help')
    \+ ( A == also, last(Pre, sep), Post = [pp(_, _)|_] ),
    %% (nor one right after a denied infinitive, which is the infinitive's: `di non aver ancora sviluppato')
    \+ ( last(Pre, neg(I)), tr_verbal_inf(I) ), !,
    append(Pre, Post, Cs), Adv = w(A, C).
%% ... AND A MANNER ADVERB IN `-ly' THE SOURCE PUT RIGHT AFTER ITS VERB, BEFORE AN
%% OBJECT OR A CLAUSE: `el Kremlin confirmó ayer oficialmente los temores' officially
%% confirmed them and `suspende temporalmente a Yuri Skuratov' temporarily suspends
%% him -- written last, as English writes its adverbs, it came after the object and
%% its phrases (`confirmed the initial fears of the doctors of Boris Yeltsin yesterday
%% officially') and between a name and its apposition (`suspends Yuri Skuratov
%% temporarily, the prosecutor general'). With nothing after it to cross it stays
%% where English puts it: `se recupera satisfactoriamente'
tr_pull_adverb(Cs0, Cs, w(A, C)) :-
    append(Pre, [adv(w(A, C))|Post], Cs0), forall(member(P, Pre), P = adv(_)),
    atom(A), atom_concat(_, ly, A), \+ en_not_manner_ly(A),
    Post = [X|_], ( X = obj(_) ; X = that(_) ; X = inf(_) ), !,
    append(Pre, Post, Cs).
%% the adverb `already' the lesson's language puts with the verb: before the group, where the
%% lesson says the word precedes the verb (Spanish's `ya'), and before the group's last word,
%% the participle, where it follows it (Italian's `già'): `ha già mangiato'
tr_pull_foreign_adverb(Cs0, Cs, fadv(T, Mode, C)) :-
    append(Pre, [adv(w(already, C))|Post], Cs0),
    tr_word_across(w(already, lower), foreign, adverb, T), atom(T),
    ( tr_holds(precede(T, verb)) -> Mode = before ; tr_holds(follow(T, verb)) -> Mode = inside ), !,
    append(Pre, Post, Cs).
tr_fo_mid_insert(none, _, G, G) :- !.
tr_fo_mid_insert(fadv(T, before, C), _, G0, [o(T, C)|G0]) :- !.
%% ... and the word that follows the verb stands after the verb that is finite: before the participle of
%% a verb with its auxiliary (`ha già mangiato'), after a verb of one word (`si disputeranno già')
tr_fo_mid_insert(fadv(T, inside, C), A, G0, G) :-
    (   A == simple -> append(G0, [o(T, C)], G)
    ;   append(G1, [Last], G0) -> append(G1, [o(T, C), Last], G)
    ;   G = [o(T, C)]
    ).
tr_mid_insert(none, G, G) :- !.
tr_mid_insert(w(A, AC), G0, G) :-
    tr_word_across(w(A, lower), english, adverb, T),
    %% (an adverb of how sure, in a denied group with an auxiliary, before the group: `non pensavo certo
    %% di trovare' is I certainly did not think, and before the verb it was `I did not certainly think')
    (   en_sentence_adverb(T), memberchk(o(not, _), G0), \+ ( G0 = [o(B0, _)|_], en_aux_alone(B0) ) -> G = [o(T, AC)|G0]
    %% (... and after the auxiliary that opens one: `non diventeranno certo aree pedonali' will
    %% certainly not become them, and before the verb it was `will not certainly become')
    ;   en_sentence_adverb(T), G0 = [o(B1, BC), o(not, NC)|GR], en_aux_alone(B1) -> G = [o(B1, BC), o(T, AC), o(not, NC)|GR]
    ;   G0 = [o(B, _)], en_aux_alone(B) -> append(G0, [o(T, AC)], G)
    %% (`have to', the modal of must where English has no form of `must', takes the adverb before `have':
    %% `dovrà scegliere davvero' will really have to choose, and before `to' it was `will have really to')
    ;   append(G1, [o(H, HC), o(to, TC)], G0), memberchk(H, [have, has, had]) -> append(G1, [o(T, AC), o(H, HC), o(to, TC)], G)
    %% (a group of three words or more takes it after its first auxiliary: `è stato anche riconosciuto' has also been
    %% acknowledged, and before the verb it was `has been also acknowledged'; a denied group keeps it before its verb,
    %% `does not always eat')
    ;   G0 = [o(B2, B2C), Second|Rest], Rest = [_|_], ( en_aux_alone(B2) ; memberchk(B2, [has, have, had]) ),
        \+ memberchk(o(not, _), G0)
    ->  G = [o(B2, B2C), o(T, AC), Second|Rest]
    ;   append(G1, [Last], G0) -> append(G1, [o(T, AC), Last], G)
    ;   G = [o(T, AC)]
    ).
en_sentence_adverb(T) :- memberchk(T, [certainly, probably, surely, clearly, obviously, evidently, definitely]).
%% (and `really', which a question says of its verb: `Davvero i fondi ottantacinque saranno distribuiti ...?' is will
%% the funds really be distributed, where it was written last, `... on those sheets really?')
en_mid_adverb(A) :-
    memberchk(A, [also, always, never, often, usually, sometimes, already, still, rarely, seldom, frequently, generally,
                  'no longer', simply, 'in reality', therefore, certainly, really]).
%% the adverbs of a day, which a long clause writes before its verb (tr_write/4), and a long tail of complements:
%% one with a comma in it (an apposition, a relative clause, an aside) or of more than eight words
en_day_adverb(D) :- memberchk(D, [yesterday, today, 'last night', 'yesterday afternoon', 'yesterday morning']).
%% (the words in `-ly' that say no manner: a time's, a likelihood, and the focus adverbs, which are
%% said of what follows them -- `ha explicado precisamente que el perro duerme' explained precisely
%% THAT, and pulled to the verb it was `has precisely explained that')
en_not_manner_ly(A) :- memberchk(A, [only, early, daily, weekly, monthly, yearly, likely, precisely, exactly, especially,
                                     particularly, mainly, mostly, merely, solely, simply, specifically, chiefly, largely,
                                     awfully]).    % (`awfully', a degree: `No, sería mucho pedir' was `it would awfully be to ask')
en_long_tail(Outs) :- ( memberchk(o(',', _), Outs) -> true ; length(Outs, N), N > 8 ).
en_aux_alone(B) :- memberchk(B, [am, is, are, was, were, can, could, may, might, must, shall, should, will, would]).

%% the verb's lexeme across: the English third person for the lesson's
%% verb, the lesson's verb for the English one -- `is' is `is' either way
%% as the copula, and the lesson's word for it
%% a reflexive verb is written with its pronoun, so a word of the lesson that
%% already carries one is passed over for it: `realizes' is `se da cuenta' to
%% a lesson that states the idiom whole (`Ci si rende conto che ...', read as
%% one word), and written with the pronoun of `sin darse cuenta' it came out
%% `se se da cuenta'
tr_lexeme_across(reflexive(L0), To, reflexive(LT)) :- !,
    (   To == foreign, tr_meanings_of(L0, foreign, verb, Ms), member(LT, Ms), \+ tr_carries_reflexive(LT) -> true
    ;   tr_lexeme_across(L0, To, LT)
    ).
tr_lexeme_across(state(L0), To, LT) :- !,
    ( To == foreign, tr_state_word(W) -> LT = W ; tr_lexeme_across(L0, To, LT) ).
%% ... AND WHERE A VERB'S TRANSITIVE SENSE IS THE INTRANSITIVE ONE'S ENGLISH,
%% that is what it crosses as when the clause is not the intransitive's:
%% `non ho firmato nessun contratto', `di aver firmato il passaggio' sign, and
%% `firma' is the intransitive `signs' of `Firma il responsabile' -- passed
%% over, as that sense is, the first meaning left was `endorses'. `The
%% transitive verb "firma" means "signs".' says it
tr_lexeme_across(L, To, LT) :-
    To == english, atom(L), tr_intransitive_meanings(L, Is), member(LT, Is), tr_solve(transitive_sense(LT, L)), !.
tr_lexeme_across(L, To, LT) :-
    tr_meanings_of(L, To, verb, Ms),
    (   To == english, atom(L), tr_intransitive_meanings(L, Is), member(LT, Ms), \+ memberchk(LT, Is) -> true
    %% an impersonal modal is written only for the impersonal subject (above)
    ;   To == foreign, member(LT, Ms), \+ tr_solve(impersonal(LT)) -> true
    ;   Ms = [LT|_]
    ).

tr_carries_reflexive(W) :-
    atom(W), atomic_list_concat(Ps, ' ', W), Ps = [_, _|_], member(P, Ps), tr_reflexive_word(P), !.

%% A VERB'S SENSE BY ITS OBJECT, WRITTEN. `Conozco al entrenador' knows a
%% person and `sé que' knows a fact, and Italian says the two with two verbs
%% -- `conosco l'allenatore', `so che' -- where English has one. The lesson
%% says which of its verbs takes a phrase for its object: `The transitive
%% verb "conosce" means "knows".' A clause with such an object takes that
%% verb; any other takes the first verb meaning it that is not it.
tr_verb_out(foreign, L, Comps, LT) :-
    atom(L), tr_solve(transitive_sense(L, W)), !,
    (   tr_own_object(Comps) -> LT = W
    ;   tr_meanings_of(L, foreign, verb, Ms), member(LT, Ms), LT \== W -> true
    ;   LT = W
    ).
%% THE COPULA OF A PLACE IS THE STATE'S, WHERE A LESSON HAS ONE: `Non sono
%% stato a Milano', `Il cane è nella casa' say where somebody is, and Spanish
%% says it with `estar' -- `no he estado en Milano', never `no he sido a'. A
%% lesson names the word of the state (`The auxiliary "está" marks the
%% state.'), and a clause whose phrases are places, adverbs and times, with
%% a place first, takes it for the plain copula. Italian says nothing of the
%% kind and keeps its `essere'.
tr_verb_out(foreign, is, Comps, LT) :-
    tr_state_plain(W), tr_where_clause(Comps), !, LT = W.
%% `SI FA' AND `SE HACE' BEFORE AN ADJECTIVE ARE ENGLISH'S `BECOMES': `Il cerino
%% si fa ogni giorno più corto' is the matchstick getting shorter, and English
%% dropped the reflexive pronoun and wrote `The matchstick makes shorter every
%% day'. A clause of the reflexive `makes' with an adjective among its
%% complements and no object of its own (the other languages keep the verb: it
%% is theirs as well).
tr_verb_out(english, reflexive(makes), Comps, reflexive(becomes)) :-
    memberchk(adj(_), Comps), \+ ( member(C, Comps), tr_object_comp(C) ), !.
%% `ATTAINS' BEFORE AN INFINITIVE IS `MANAGES': `iniciativa que consiguió pactar con
%% la dirección' managed to agree, `riesce a giocare' manages to play -- Italian's
%% `riesce' and Spanish's `logra' and `consigue' cross as attaining, which English
%% says of an aim and never before an infinitive (`achieved to agree', `attain to')
tr_verb_out(english, attains, Comps, manages) :-
    tr_first_comp(Comps, I), ( I = inf(_) ; I = infx(_, _, _) ; I = ainf(_, _) ), !.
%% A VERB WHOSE MEANING THE LESSON STATES AS A REFLEXIVE ONE IS WRITTEN WITH ITS PRONOUN, where
%% the clause gives it no object: `si sono rassegnati a muoversi' is `se han resignado a moverse'
%% (`The reflexive verb "resigna" means "becomes resigned to".'), and written plain it was `han
%% resignado a moverse'
tr_verb_out(foreign, L, Comps, reflexive(LT)) :-
    atom(L), tr_lexeme_across(L, foreign, LT), atom(LT), tr_solve(mean_as(LT, L, reflexive)),
    \+ memberchk(obj(_), Comps), !.
tr_verb_out(To, L, _, LT) :- tr_lexeme_across(L, To, LT).
tr_where_clause(Comps) :-
    member(pp(w(P, _), NP), Comps), memberchk(P, [in, to, at]), ( NP = name(_) ; NP = np(_, _, _, _, _) ),
    \+ tr_pp_of_time(NP), !,
    forall(member(C, Comps), tr_where_comp(C)).
tr_where_comp(pp(_, _)).
tr_where_comp(adv(_)).
tr_where_comp(at_time(_)).
tr_where_comp(sep).                                   % `sono in corso, ma che ...' keeps its comma
tr_pp_of_time(np(_, _, _, w(N, _), _)) :- atom(N), tr_time_lexeme(english, N), !.
tr_pp_of_time(np(_, _, _, w(N, _), _)) :- atom(N), tr_number_noun(N).
tr_number_noun(N) :- ( tr_digits(N) -> true ; en_number(N) ).
%% ... the verb's own object: a phrase after a coordinator is the conjunct of
%% the complement before it (`ritorna alla dimensione dell'oasi così come le
%% Eolie, e l'isola di Ustica' returns to the dimension as the Eolie do and
%% as Ustica does), and no object of the verb -- so `regresa' and not
%% `devuelve' -- and neither is one after an infinitive, which is the
%% infinitive's (`torna ad affilare gli artigli' goes back to sharpen the
%% claws, and the claws are what is sharpened)
tr_own_object(Comps) :- tr_own_object(Comps, other).
tr_own_object([obj(_)|Cs], Prev) :- !, ( Prev == other -> true ; tr_own_object(Cs, other) ).
tr_own_object([sep|Cs], Prev) :- !, tr_own_object(Cs, Prev).
tr_own_object([cnj(_)|Cs], _) :- !, tr_own_object(Cs, cnj).
tr_own_object([C|Cs], _) :- \+ tr_verbal_comp(C), tr_own_object(Cs, other).
%% ... a pronoun that is the object too, `el gobierno lo ha terminado'
tr_clause_object(Comps) :- tr_own_object(Comps), !.
tr_clause_object(Comps) :- member(opron(W), Comps), tr_object_comp(opron(W)), !.
%% (the verbs of beginning, whose perfect takes `has' before an infinitive, tr_write/4)
tr_beginning_verb(begins).   tr_beginning_verb(starts).   tr_beginning_verb(commences).
%% ... and a passive has an object by what it is, as the reader already
%% counts it (tr_verb_across/5): `non è molto conosciuto' is `conocido', and
%% taken as a clause with no object `conoce' gave way to `sabe', `sabido'
%% ... and so has the clause of a relative whose word stands for the object, which is
%% not among its complements (tr_np_out/5): `l'allenatore che ora conosciamo' is
%% `conocemos', the verb that takes a phrase, and not `sabemos'
tr_passive_object(A, Comps, CompsV) :-
    tr_global('$tr_rel_object', Rel), ( Rel == yes -> nb_setval('$tr_rel_object', no) ; true ),
    (   memberchk(A, [passive, passive_perfect]) -> CompsV = [obj(passive)|Comps]
    ;   Rel == yes -> CompsV = [obj(relative)|Comps]
    ;   CompsV = Comps
    ).

%% the lesson's impersonal modal for a modal meaning, if it gives one
tr_impersonal_modal(L, IM) :-
    atom(L), tr_meanings_of(L, foreign, modal, Ms), member(IM, Ms),
    tr_solve(impersonal(IM)), tr_class_of(IM, modal), !.

%% the subject out, with its person and number for the verb and its noun
%% for the agreement of what is said of it
tr_subject_out(To, asked(w(Q, C)), [o(QT, C)], third, singular, none) :- !, tr_question_across(To, subject, Q, QT).
tr_subject_out(To, asked(whichp(N, C)), [o(W, C)], third, N, none) :- !, tr_which_pronoun_number(To, N, W).
tr_subject_out(To, asked(which_np(NP, C)), [o(QT, C)|NPOut], third, Number, Noun) :- !,
    tr_which_word(To, QT), tr_which_np_out(To, NP, NPOut, Noun, Number).
tr_subject_out(_, none, [], third, singular, none) :- !.
%% the people a plural imperative speaks to: no word in any language, and
%% the number for the verb (tr_imperative_number/3)
tr_subject_out(_, addressee(polite), [], polite, singular, none) :- !.
tr_subject_out(_, addressee(N), [], second, N, none) :- !.
tr_subject_out(To, name(W), [o(N, upper)], third, singular, none) :- !,
    ( To == foreign, tr_name_word_out(W, N0) -> N = N0 ; N = W ).    % (a name's meaning: tr_cross_np/2)
%% (English agrees with its own word: `everyone' is singular, whatever the
%% number of the lesson's `tutti')
tr_subject_out(english, pronoun(third, _, w(W, C)), [o(W, C)], third, N, none) :- en_tonic(W, N), !.
%% A DEMONSTRATIVE THE COPULA SAYS IS A NOUN TAKES THE NOUN'S GENDER: `Questa è la casa del cane' is `Esta es la casa',
%% and with the pronoun written as the lesson's own neuter `esto' it came out `Esto es la casa', `esto es el juicio';
%% the lesson's first demonstrative in the noun's gender is the pronoun (`questa', `esta'), never one of no gender
tr_subject_out(foreign, pronoun(third, singular, w(W, C)), [o(T, C)], third, singular, none) :-
    memberchk(W, [this, that]), tr_global('$tr_dem_pred', p(NW, singular)),
    tr_noun_lexeme(foreign, NW, singular, _, Noun), atom(Noun), tr_noun_gender(Noun, G), G \== none,
    tr_det_meanings(demonstrative, W, Ms), member(T, Ms), tr_gender(T, G), !.
tr_subject_out(To, pronoun(P, N, w(W, C)), Outs, P, N, none) :- !,
    (   tr_pronoun_across(To, subject, w(W, C), P, N, T) -> Outs = [o(T, C)]
    ;   To == foreign, W == it -> Outs = []                                % `It rains': the verb says who
    ).
%% ... and a third person singular nobody named is refused in English:
%% he, she and it are three claims and the source made none of them
tr_subject_out(english, null(P, N), [], P, N, none) :- tr_global('$tr_elide', yes), !, nb_setval('$tr_elide', no).
tr_subject_out(english, null(third, singular), _, _, _, _) :- !, fail.
%% (English's `you' is both numbers: `avete pensato all'evasione fiscale?'
%% has you all for its subject, and with `you' in English's table as the
%% singular only, English wrote nothing)
tr_subject_out(english, null(P, plural), [o(T, lower), o(all, C)], P, plural, none) :-
    tr_global('$tr_subj_all', C), C \== none, !, nb_setval('$tr_subj_all', none),
    ( P == second -> T = you ; en_subject(T, P, plural) ), !.
tr_subject_out(english, null(second, plural), [o(you, lower)], second, plural, none) :- !.
tr_subject_out(english, null(P, N), [o(T, lower)], P, N, none) :- !, en_subject(T, P, N), !.
%% a language whose verb says who needs no subject written: what the IR
%% carries is the person and the number, and the verb group takes them
tr_subject_out(foreign, null(P, N), [], P, N, none) :- !.
%% the impersonal subject out: the lesson's own word, which stands before
%% the verb as the pronoun it is; English says `one'. The word is asked for
%% with its first argument unbound, which keys 0 and walks the predicate --
%% impersonal/1 is one row a language, so the walk is one row.
tr_subject_out(english, impersonal, [o(one, lower)], third, singular, none) :- !.
tr_subject_out(foreign, impersonal, [o(W, lower)], third, singular, none) :- !,
    tr_solve(impersonal(W)), tr_class_of(W, pronoun), !.
%% two joined agree as FEMININE when both are, which is the one case where
%% the lessons' languages do not write the masculine: `la terapia palliativa
%% e la terapia del dolore' are `attivate', and written with no noun to
%% agree with they came out `activados'. The first noun stands for both.
%% ... and a list that began with its connector gets it back in front: the
%% lesson's word before the first, and English's `neither ... nor ...'
tr_subject_out(To, nei(Co0), Outs, third, plural, Noun) :- !,
    ( To == english -> tr_nor(Co0, Co) ; Co = Co0 ),
    tr_subject_out(To, Co, O1, _, _, Noun),
    (   To == english -> CO = [o(neither, lower)]
    ;   Co = co(C, _, _), tr_connector_out(To, C, CO)
    ),
    append(CO, O1, Outs).
tr_subject_out(To, one(co(C, S1, S2)), Outs, third, singular, Noun) :- !,
    tr_subject_out(To, S1, O1, _, _, Noun), tr_subject_out(To, S2, O2, _, _, _),
    tr_connector_out(To, C, CO), append(CO, O2, O3), append(O1, O3, Outs).
tr_subject_out(To, nonly(A, B, Also), Outs, third, N, none) :- !, tr_np_out(To, nonly(A, B, Also), Outs, _, N).
%% the word for `even', `also' or `only' before the subject it is said of
tr_subject_out(To, advp(w(A, C), S), [o(AT, C)|Outs], P, N, Noun) :- !,
    tr_word_across(w(A, lower), To, adverb, AT), tr_subject_out(To, S, Outs, P, N, Noun).
%% (an adjective for the property it names: `immobile', `motionless')
tr_subject_out(To, adjs(As), Outs, third, singular, none) :- !,
    tr_adjectives_out(To, As, none, singular, AOs), tr_adj_words(AOs, Outs).
%% (both ... and: each language's pair round the two halves)
tr_subject_out(To, co(both, S1, S2), Outs, third, plural, none) :- !,
    tr_both_pair(To, B, P),
    tr_subject_out(To, S1, O1, _, _, _), tr_subject_out(To, S2, O2, _, _, _),
    append([[o(B, lower)], O1, [o(P, lower)], O2], Outs).
tr_subject_out(To, co(C, S1, S2), Outs, third, plural, Noun) :- !,
    tr_subject_out(To, S1, O10, _, _, N1), tr_subject_out(To, S2, O2, _, _, N2),
    tr_closed_aside(S1, O10, O1),
    (   To == foreign, N1 \== none, N2 \== none, tr_gender(N1, feminine), tr_gender(N2, feminine)
    ->  Noun = N1
    ;   Noun = none
    ),
    tr_connector_out(To, C, CO), append(CO, O2, O3), append(O1, O3, Outs).
%% (a pronoun read as a phrase's noun is in the pronoun's person: `puede
%% ser que me decapite yo mismo' has `yo mismo' after its verb for the
%% subject, and in the third person Italian wrote `si decapita io stesso')
tr_subject_out(To, np(none, none, As, w(E, C), Number), Outs, P, Number, Noun) :-
    tr_pronoun_np(english, np(none, none, As, w(E, C), Number), P, _), P \== third, !,
    tr_np_out(To, np(none, none, As, w(E, C), Number), Outs, Noun, Number).
tr_subject_out(To, np(D, M, As, N, Number), Outs, third, Number, Noun) :- !, tr_np_out(To, np(D, M, As, N, Number), Outs, Noun, Number).
%% a phrase with a reduced relative on it is still a phrase: the person and
%% number are its noun's, and tr_np_out/5 writes the participle and the agent
tr_subject_out(To, rel(NP, L, Cs), Outs, third, Number, Noun) :- !, tr_np_out(To, rel(NP, L, Cs), Outs, Noun, Number).
tr_subject_out(To, rc(NP, R, S), Outs, third, Number, Noun) :- !, tr_np_out(To, rc(NP, R, S), Outs, Noun, Number).
%% ... and in English, where the verb comes after it, the aside closes with
%% its comma: `The dog, who eats the bread, stands out.'
tr_subject_out(english, nrc(NP, R, S), Outs, third, Number, Noun) :- !,
    tr_np_out(english, nrc(NP, R, S), Outs0, Noun, Number), append(Outs0, [o(',', comma)], Outs).
tr_subject_out(To, nrc(NP, R, S), Outs, third, Number, Noun) :- !, tr_np_out(To, nrc(NP, R, S), Outs, Noun, Number).
tr_subject_out(To, ncl(NP, S), Outs, third, Number, Noun) :- !, tr_np_out(To, ncl(NP, S), Outs, Noun, Number).
tr_subject_out(To, all(W, NP), Outs, third, Number, Noun) :- !, tr_np_out(To, all(W, NP), Outs, Noun, Number).
tr_subject_out(To, ninf(L), Outs, third, singular, Noun) :- !, tr_np_out(To, ninf(L), Outs, Noun, singular).
tr_subject_out(To, nq(Det, W), Outs, third, singular, Noun) :- !, tr_np_out(To, nq(Det, W), Outs, Noun, singular).
%% a phrase whose noun was left out, as a subject: `lo que hace es ...' --
%% ell/4 had no clause here, and a subject the writer cannot take apart
%% fails the sentence without a word (the 1.6.4 rule, a third time)
tr_subject_out(To, ell(D, G, N0, T), Outs, third, Number, Noun) :- !, tr_np_out(To, ell(D, G, N0, T), Outs, Noun, Number).
tr_subject_out(To, app(NP, K, I), Outs, third, Number, Noun) :- !, tr_np_out(To, app(NP, K, I), Outs, Noun, Number).
%% the subject a relative word stands for is written as nothing: the verb
%% takes the person and number of the phrase the clause sits on
tr_subject_out(_, gap(P, N), [], P, N, none) :- !.
%% an infinitive and its complements: `to be president of this club',
%% `ser presidente de esta sociedad'
tr_subject_out(To, infs(L, Cs, C), [o(W1, C)|Outs], third, singular, none) :- !,
    tr_subject_out(To, infs(L, Cs), [o(W1, _)|Outs], third, singular, none).
%% ... and with its pronouns: English's `to', the base form and the object
%% pronouns after it, the lesson's infinitive with its own joined to it
tr_subject_out(To, infs(cl(L, Cls), Cs), Outs, third, singular, none) :- !,
    tr_lexeme_across(L, To, LT),
    (   To == english
    ->  en_base(LT, B),
        findall(o(T, lower), ( member(X, Cls), ( X = dat(w(T, _)) -> true ; X = w(T, _) ) ), Objs),
        V = [o(to, lower), o(B, lower)|Objs]
    ;   findall(F, ( member(X, Cls), tr_pinf_clitic_out(X, F) ), Ps),
        once(tr_solve(infinitive_of(Inf0, LT))), tr_joined_infinitive(Inf0, Ps, Inf), V = [o(Inf, lower)]
    ),
    tr_comps_out(To, Cs, none, singular, [], O2, A2), append([V, O2, A2], Outs).
tr_subject_out(To, infs(L, Cs), Outs, third, singular, none) :- !,
    tr_lexeme_across(L, To, LT0),
    %% a reflexive is joined back where the language has one, and English,
    %% which has none there, drops it: `inscribirse', `to enrol'
    ( LT0 = reflexive(LT) -> ( To == foreign -> tr_reflexive_out(R), Ps = [R] ; Ps = [] ) ; LT = LT0, Ps = [] ),
    (   To == english -> en_base(LT, B), V = [o(to, lower), o(B, lower)]
    ;   once(tr_solve(infinitive_of(Inf0, LT))), tr_joined_infinitive(Inf0, Ps, Inf), V = [o(Inf, lower)]
    ),
    tr_comps_out(To, Cs, none, singular, [], O2, A2), append([V, O2, A2], Outs).
tr_subject_out(To, with(NP00, PPs00), Outs, third, Number, Noun) :-
    tr_with_adj(To, NP00, PPs00, NP, PPs0),
    tr_of_dropped(To, NP, PPs0, PPs),
    (   To == foreign, PPs = [PP|_], tr_partitive_gender(NP, PP, G)
    ->  tr_with_partitive(G, tr_np_out(To, NP, O1, Noun, Number))
    ;   tr_np_out(To, NP, O1, Noun, Number)
    ),
    tr_comps_out(To, PPs, Noun, Number, _, O2, A2), append([O1, O2, A2], Outs0),
    %% ... and in English an aside on the last phrase closes with its comma,
    %% as one on the subject itself does: `The sales of minidisc, which
    %% surpassed ..., were increased'
    (   To == english, last(PPs, pp(_, nrc(_, _, _))) -> append(Outs0, [o(',', comma)], Outs) ; Outs = Outs0 ).
%% (a relative clause set off in the first of two subjects closes with its
%% comma in every language: `Carlos Herrera, che si espresse in catalano, e
%% Margarida Lluch' -- English's subject writer has put it there already)
tr_closed_aside(nrc(_, _, _), O0, O) :- \+ last(O0, o(',', _)), !, append(O0, [o(',', comma)], O).
tr_closed_aside(_, O, O).

%% THE SECOND `NEITHER' OF A LIST OF COMPLEMENTS IS `NOR': `non dorme né con il
%% gatto né con il pane' is sleeps neither with the cat nor with the bread
%% (the first stays, every later one is the lesson's word for it, `nor')
tr_nor_list([], _, []).
tr_nor_list([cnj(w(neither, K))|Cs], Seen, [X|Ys]) :- !,
    ( Seen == yes -> X = cnj(w(nor, K)) ; X = cnj(w(neither, K)) ),
    tr_nor_list(Cs, yes, Ys).
tr_nor_list([C|Cs], Seen, [C|Ys]) :- tr_nor_list(Cs, Seen, Ys).
%% (the clauses before the second `ni' open on the first)
tr_opens_neither(join(w(neither, _), none, _)) :- !.
tr_opens_neither(join(_, _, S)) :- tr_opens_neither(S).
%% the connector out: a comma as itself, a word through the lesson
tr_connector_out(_, comma, [o(',', comma)]) :- !.
tr_connector_out(_, w(',', lcomma), [o(',', comma)]) :- !.
tr_connector_out(_, w(',', acomma), [o(',', comma)]) :- !.
tr_connector_out(_, semicolon, [o(';', comma)]) :- !.
tr_connector_out(_, colon, [o(':', comma)]) :- !.
tr_connector_out(_, endquote, [o('”', comma)]) :- !.
tr_connector_out(_, endquote_comma, [o('”', comma), o(',', comma)]) :- !.
tr_connector_out(_, endquote_plain, [o('"', comma)]) :- !.
tr_connector_out(_, endquote_plain_comma, [o('"', comma), o(',', comma)]) :- !.
tr_connector_out(_, endquote_name_comma, [o(',', comma)]) :- !.
tr_connector_out(_, dash, [o('–', lower)]) :- !.
tr_connector_out(_, dashes, [o('–', lower)]) :- !.
tr_connector_out(_, reported, []) :- !.
tr_connector_out(_, aside, []) :- !.
%% `BUT' AFTER A DENIAL IS THE PARTNER THE LESSON NAMES FOR ITS DENIAL WORD,
%% where it names one: `non avevano funzioni geografiche bensì simboliche'
%% is `no tenían funciones geográficas sino simbólicas', and `non
%% rappresentavano la terra ma le terre note' `no representaban la tierra
%% sino las tierras conocidas' -- Spanish's `pero' says `yet', and `"sino" is
%% the partner of "no".' names the word that sets one thing in place of
%% another. Only between two complements of a denied clause (tr_write/4 says
%% which, '$tr_denied'): `no duerme pero come' joins two clauses and stays
tr_connector_out(foreign, w(but, C), [o(T, C)]) :-
    tr_global('$tr_denied', yes), tr_negation_word(No), tr_solve(partner_of(T, No)), !.
tr_connector_out(To, w(W, C), [o(T, C)]) :- tr_word_across(w(W, lower), To, conjunction, T).
%% a connecting word and the comma after it, which opens an insertion
tr_connector_out(To, wc(W), Outs) :- tr_connector_out(To, W, O), append(O, [o(',', comma)], Outs).
%% ... and a reporting clause between two dashes, written where it stood
tr_connector_out(To, dmid(R), Outs) :- !,
    tr_write(To, statement, R, RO), append([[o('–', lower)], RO, [o('–', lower)]], Outs).
%% ... or between two commas
tr_connector_out(To, cmid(R), Outs) :- !,
    tr_write(To, statement, R, RO), append([[o(',', comma)], RO, [o(',', comma)]], Outs).
%% ... and the one a comment opens with, English's `as', by the lesson's
%% preposition for it (`como', `come'): its first word for `as' is `tan'
tr_connector_out(To, cmt(w(W, C)), [o(T, C)]) :-
    ( To == english -> T = W ; tr_word_across(w(W, lower), To, preposition, T) ).
%% ... and the adverb `thus' a clause set off after a subject opens with
tr_connector_out(To, so(w(W, C)), [o(T, C)]) :-
    ( To == english -> T = W ; tr_word_across(w(W, lower), To, adverb, T) ).

%% what a question word asks for, out: the word itself, or `which' with its phrase
tr_asked_out(_, none, []) :- !.
tr_asked_out(_, subject(_), []) :- !.                                    % the subject out already carries it
tr_asked_out(To, object(which_np(NP, C)), Outs) :- !,
    tr_which_word(To, QT), tr_which_np_out(To, NP, NPOut, _, _),
    tr_marker(To, NP, M), append(M, [o(QT, C)|NPOut], Outs).
tr_asked_out(To, pp(w(P, PC), which_np(NP, C)), [o(PT, PC), o(QT, C)|NPOut]) :- !,
    ( To == english -> PT = P ; tr_word_across(w(P, lower), To, preposition, PT) ),
    tr_which_word(To, QT), tr_which_np_out(To, NP, NPOut, _, _).
tr_asked_out(To, object(whichp(N, C)), [o(W, C)]) :- !, tr_which_pronoun_number(To, N, W).
tr_asked_out(To, object(w(Q, C)), Outs) :- tr_asks_person(Q), !,
    tr_question_across(To, object, Q, QT), tr_marker(To, person, M), append(M, [o(QT, C)], Outs).
tr_asked_out(To, Asked, [o(QT, C)]) :- Asked =.. [Kind, w(Q, C)], tr_question_across(To, Kind, Q, QT).

%% `whom', or a word of the lesson's that means `who' or `whom', asks for a person
tr_asks_person(Q) :- ( Q == whom ; tr_solve(mean(Q, whom)) ; tr_solve(mean(Q, who)) ), !.

%% a question word across, by what it asks for: `qué' may mean `what' and
%% `which', and the object asked is `what'
tr_question_across(To, _, Q, Q) :- tr_side_here(From), From == To, !.
tr_question_across(english, Kind, Q, E) :- tr_solve(mean(Q, E)), en_question(E, Kind), !.
tr_question_across(english, object, Q, whom) :- tr_solve(mean(Q, who)), !.       % who, asked for as the object
tr_question_across(english, subject, Q, what) :- tr_solve(mean(Q, what)), !.     % what, asked for as the subject
tr_question_across(foreign, _, E, Q) :- tr_solve(mean(Q, E)), !.
tr_question_across(foreign, object, whom, Q) :- tr_solve(mean(Q, who)), !.       % whom is who as an object

tr_which_word(english, which).
tr_which_word(foreign, W) :- once(tr_solve(mean(W, which))).
%% ... in the number the phrase it asks with has: Italian's `quale' is `quali'
%% before a plural, and a language whose word does not change keeps it
tr_which_word_number(To, Number, W) :-
    tr_which_word(To, W0),
    (   To == foreign, Number == plural, tr_solve(plural_of(P, W0)) -> W = P ; W = W0 ).
%% ... `which' BY ITSELF, with no noun after it, is a pronoun where the lesson
%% has one that means it: `quali possano essere i motivi' is `cuáles pueden
%% ser los motivos', and Spanish's `qué', the lesson's first word for `which',
%% asks what -- `aparece inexplicable qué pueden ser los motivos'. A word that
%% is a pronoun comes first for this and no other: before a noun (which_np)
%% the first word for it stands
tr_which_pronoun_number(To, Number, W) :-
    (   To == foreign, once(( tr_solve(mean(W0, which)), tr_solve(pronoun(W0)) ))
    ->  (   Number == plural, tr_solve(plural_of(P, W0)) -> W = P ; W = W0 )
    ;   tr_which_word_number(To, Number, W)
    ).
%% the word for `what', an exclamation's: English's own, and the lesson's
%% first word of one word that means it -- `che cosa' is Italian's too
tr_what_word(english, what) :- !.
tr_what_word(foreign, W) :- atom(W), !, once(tr_solve(mean(W, what))).
tr_what_word(foreign, W) :- once(( tr_solve(mean(W, what)), atom(W), \+ sub_atom(W, _, _, _, ' ') )).
tr_and_word(english, and).
tr_and_word(foreign, W) :- once(( tr_solve(mean(W, and)) )).

%% a pronoun across: English's by person and number, or by the meaning of
%% the lesson's (`ella' is `she'); the lesson's by the meaning of English's
%% -- as the subject one that may be a subject, as the object one the
%% lesson puts before the verb, after a preposition one it does not, or
%% one that serves as a subject too (`con nosotros', `con él')
tr_pronoun_across(To, _, w(W, _), _, _, T) :- tr_side_here(From), From == To, !,
    ( W == 'you all' -> T = you ; T = W ).
tr_pronoun_across(english, subject, w(W, _), P, N, T) :- tr_solve(mean(W, E)), en_subject(E, P, N), !, T = E.
%% (`uno' standing alone is `one', not the first third person: tr_subject_pronoun/4)
tr_pronoun_across(english, subject, w(W, _), third, singular, one) :- tr_solve(mean(W, one)), !.
tr_pronoun_across(english, _, w(W, _), _, _, T) :- tr_tonic_across(W, T), !.
tr_pronoun_across(english, subject, w(W, _), P, N, T) :- tr_solve(mean(W, _)), en_subject(T, P, N), !.
tr_pronoun_across(english, Role, w(W, _), _, _, T) :-
    tr_solve(mean(W, E)), en_object(E), !,
    %% THE PLURAL OF `you' IS ITS OWN WORD OF THE IR where it is no subject (a
    %% subject carries its number): `voi' and `vi' mean `you', English's word
    %% has no number, and `Qualcuno di voi' came out `Alguien de tú' and `vi
    %% accusa' `te acusa'. English writes it `you', the lesson's language the
    %% plural of the pronoun the role takes (`voi', `vi')
    ( E == you, Role \== subject, tr_plural_you(W) -> T = 'you all' ; T = E ).
tr_pronoun_across(english, _, w(W, _), _, _, T) :- tr_solve(mean(W, E)), en_object_of(E, T), !.
tr_pronoun_across(english, _, w(W, _), _, _, T) :- tr_solve(mean(W, E)), en_reflexive(E), !, T = E.
%% AN ELIDED FORM IS THE WORD IT ELIDES, here as it is in tr_object_pronoun/3:
%% `La sinistra L'ha attaccata' split the clitic off correctly and then had no
%% meaning to cross it by, because an elision has no mean/2 row of its own.
tr_pronoun_across(To, Role, w(W, C), P, N, T) :-
    tr_solve(elision_of(W, F)), F \== W,
    tr_pronoun_across(To, Role, w(F, C), P, N, T), !.
tr_pronoun_across(foreign, Role, w('you all', C), P, _, T) :- !, tr_pronoun_across(foreign, Role, w(you, C), P, plural, T).
tr_pronoun_across(foreign, Role, w(W, _), _, N, T) :-
    findall(T0, ( tr_solve(mean(T0, W)), tr_class_of(T0, pronoun) ), Ts0), Ts0 \== [],
    tr_pronouns_first(W, Ts0, Ts1),
    %% and with nothing to agree with, a feminine one last: `others' is
    %% `altro' and `altra', and the IR carries no gender for a pronoun
    (   en_tonic(W, _)
    ->  findall(X, ( member(X, Ts1), \+ tr_holds(feminine(X)) ), NotF), findall(X, ( member(X, Ts1), tr_holds(feminine(X)) ), Fem),
        append(NotF, Fem, Ts)
    ;   Ts = Ts1                                     % `her' says its gender itself
    ),
    (   Role == subject -> member(T0, Ts), tr_subject_pronoun(foreign, T0, _, _)
    ;   Role == object, member(T0, Ts), tr_holds(precede(T0, verb)) -> true
    ;   Role == oblique, member(T0, Ts), ( tr_subject_pronoun(foreign, T0, _, _) ; \+ tr_holds(precede(T0, verb)) ) -> true
    ;   Ts = [T0|_]
    ), !,
    %% a pronoun English says is plural goes out in its plural where the
    %% lesson states one: `others' is `altro' in the dictionary and `altri'
    %% in the sentence
    %% (and `you' of the plural: `voi' for `tu', `vosotros' for `tú')
    ( ( en_tonic(W, plural) ; W == you, N == plural ), tr_inflect(foreign, pronoun, T0, plural, TP) -> T = TP ; T = T0 ).
%% `these', `those': the first word for the singular that HAS a plural --
%% `esto' stands alone and has none, `este' has `estos'
tr_pronoun_across(foreign, Role, w(W, _), _, _, T) :-
    en_tonic_plural(S, W),
    findall(T0, ( tr_solve(mean(T0, S)), tr_class_of(T0, pronoun) ), Ts0), tr_pronouns_first(S, Ts0, Ts),
    member(T1, Ts), ( Role == subject -> tr_subject_pronoun(foreign, T1, _, _) ; true ),
    tr_inflect(foreign, pronoun, T1, plural, T), !.
tr_pronoun_across(foreign, Role, w(W, _), _, _, T) :- Role \== subject, tr_solve(mean(T, W)), !.

%% the words that are pronouns and nothing else first: `esto' stands alone
%% where `este' is the demonstrative too, and a vocabulary gives the
%% demonstrative's line before the pronoun's
%% -- and a word whose FIRST sentence meaning E was a pronoun's: Italian's
%% `questo' is the demonstrative and the pronoun both, and has no neuter
%% beside it, so the rule above put the dictionary's `codesto' first and
%% `esto ya está ganado' came out `codesto è vinto'; the lesson that says
%% `The pronoun "questo" means "this".' before anything else is choosing it
tr_pronouns_first(E, Ts, Out) :-
    findall(T, ( member(T, Ts),
                 ( \+ tr_class_of(T, demonstrative), \+ tr_class_of(T, determiner)
                 ; once(tr_solve(mean_as(T, E, C))), C == pronoun
                 ) ), Pure),
    findall(T, ( member(T, Ts), \+ memberchk(T, Pure) ), Rest),
    append(Pure, Rest, Out).

%% a pronoun of the lesson's that stands alone (`esto', `nadie'), in
%% English: what it means, and `these' for `this' in the plural
tr_tonic_across(W, T) :-
    tr_lexeme(foreign, W, L, N),
    %% the meaning its PRONOUN sentence gave first: `otro' is the determiner
    %% `another' and the pronoun `others', and a pronoun is the second
    (   tr_solve(mean_as(L, E, pronoun)), en_tonic(E, _) -> true
    ;   tr_solve(mean(L, E)), en_tonic(E, _)
    ), !,
    ( N == plural, en_tonic_plural(E, P) -> T = P ; T = E ).

%% English's object form of a subject pronoun, for a lesson that gave
%% `él' as `he' only
en_object_of(i, me). en_object_of(you, you). en_object_of(he, him). en_object_of(she, her).
en_object_of(it, it). en_object_of(we, us). en_object_of(they, them).
%% English's reflexive pronouns: what `sé' and `sí' mean after a preposition
en_reflexive(itself). en_reflexive(himself). en_reflexive(herself). en_reflexive(oneself).
en_reflexive(themselves). en_reflexive(myself). en_reflexive(yourself). en_reflexive(ourselves).
%% one of English's reflexive pronouns that says a person: not `itself'
tr_reflexive_person(english, W) :- memberchk(W, [himself, herself, themselves, oneself]), !.
tr_reflexive_person(foreign, W) :-
    tr_two_words(W),
    tr_is(foreign, w(W, lower), pronoun), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)),
    memberchk(E, [himself, herself, themselves, oneself]), !.
%% a pronoun that means one of them: `sé stesso', `sí mismo', `himself'
tr_emphatic_pronoun(english, W) :- en_reflexive(W), !.
tr_emphatic_pronoun(foreign, W) :-
    atom(W), tr_two_words(W),
    tr_is(foreign, w(W, lower), pronoun), tr_lexeme(foreign, W, L, _), tr_solve(mean(L, E)), en_reflexive(E), !.
%% an emphatic reflexive is of two words, the pronoun and the word for `same' (`sé stesso', `sí mismo'), and the
%% lesson's word of two is one token: asked first, before the lexicon, which the two rules above asked of every phrase
%% of one word and of every phrase's noun -- 2 500 of the 3 600 inferences the new rules cost 28 sentences of the
%% controls, and the plain `sé' and `sí' (itself, after a preposition) and the clitic `se' are none
tr_two_words(W) :- atomic_list_concat([_, _|_], ' ', W).

%% a phrase out: the determiner and each adjective agreeing with the noun
%% in gender and number, a number word as it is, the adjectives before or
%% after the noun as the rule says; Noun is the target noun's lexeme
%% the phrase, then the participle AGREEING with its noun, then the agent.
%% English agrees with nothing and takes the participle as it is; the
%% lesson's language picks the form the way a passive does, so the gender it
%% reads is the phrase's own and not the sentence's subject.
%% a phrase and its relative clause: the relative word for the role, then
%% the clause with the gap left out and, where the subject is the gap, the
%% verb in the PHRASE's number
%% the noun's own clause out: the phrase, the word the target's lesson
%% says begins such a clause if it names one, its word for `that', the clause
tr_np_out(To, ncl(NP, S), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, NPOut, Noun, Number),
    (   To == foreign, once(tr_solve(begin(B, clause))) -> BOut = [o(B, lower)] ; BOut = [] ),
    tr_that_word(To, TW),
    tr_write_nested(To, S, SOut),
    append([NPOut, BOut, [o(TW, lower)], SOut], Outs).
%% ... AND `THAT WHICH' IS `WHAT' IN ENGLISH: `quello che è accaduto' is what
%% has happened, never `that that has happened' -- the demonstrative pronoun
%% and the relative word are one word there. A clause whose phrase is the
%% subject or the object; one after a preposition keeps both
tr_np_out(english, rc(pronoun(w(that, C)), Role, S0), [o(what, C)|SOut], Noun, Number) :-
    memberchk(Role, [subject, object]), !,
    tr_np_out(english, pronoun(w(that, C)), _, Noun, Number),
    ( S0 = s(A, gap, G, Cs) -> S1 = s(A, gap(third, Number), G, Cs) ; S1 = S0 ),
    tr_gap_write(english, Noun, S1, SOut).
tr_np_out(To, rc(NP, Role0, S0), Outs, Noun, Number) :- !,
    tr_global('$tr_keep_det', K0), nb_setval('$tr_keep_det', yes),
    ( tr_np_out(To, NP, NPOut, Noun, Number) -> nb_setval('$tr_keep_det', K0) ; nb_setval('$tr_keep_det', K0), fail ),
    %% (the preposition before the relative word is the English verb's own where it governs one: `un
    %% ataque con el que sueñan los interistas' is an attack THEY DREAM OF, never `with which')
    (   To == english, Role0 = pp(w(_, RPC)), S0 = s(_, _, g(RV, _, _, _), _), atom(RV), en_governs(RV, RQ)
    ->  Role = pp(w(RQ, RPC))
    ;   Role = Role0
    ),
    (   To == english, Role == where, S0 = s(_, none, g(_, _, infinitive, _), _)
    ->  RelOut0 = [o(in, lower), o(which, lower)]                % `a board in which to leave ads'
    %% ... AND AN OBJECT'S CLAUSE WITH AN INFINITIVE AND NOBODY IN IT IS `TO': `no tenía "nada que añadir"' had
    %% nothing to add, and English wrote `anything that to add'; the lesson's language begins it with the word it
    %% states (`The word "da" begins the gerundive.', Italian's `niente da aggiungere'), or with its relative
    %% word, as Spanish does
    ;   Role == object, S0 = s(_, none, g(_, _, infinitive, _), _)
    ->  (   To == english -> RelOut0 = []
        ;   once(tr_solve(begin(B, gerundive))) -> RelOut0 = [o(B, lower)]
        ;   tr_relative_out(To, Role, Noun, Number, RelOut0)
        )
    ;   tr_relative_out(To, Role, Noun, Number, RelOut0)
    ),
    %% (a quotation that opened on the relative word, tr_rel_mark/3, as a
    %% relative set off with a comma has it: `un monopolio "que quita la
    %% competencia"' lost its opening mark and kept the closing one)
    (   S0 = s(A0, Su0, G0, Cs0), select(qrel, Cs0, Cs1), RelOut0 = [o(RW, _)|RR]
    ->  S = s(A0, Su0, G0, Cs1), RelOut = [o(RW, qopen)|RR]
    ;   S = S0, RelOut = RelOut0
    ),
    (   S = s(A, gap, G, Cs) -> tr_verb_number(To, Noun, Number, GN), S1 = s(A, gap(third, GN), G, Cs) ; S1 = S ),
    (   S1 = s(_, Su1, _, _), Su1 \= gap, Su1 \= gap(_, _), Role \= pp(_), Role \== whose
    ->  nb_setval('$tr_rel_object', yes)
    ;   true
    ),
    (   tr_gap_write(To, Noun, S1, SOut) -> nb_setval('$tr_rel_object', no)
    ;   nb_setval('$tr_rel_object', no), fail
    ),
    append(NPOut, RelOut, O1), append(O1, SOut, Outs).
%% ... and the one the source set off with a comma, which English writes
%% with `which', or `who' for a person, and never with `that'
%% (before a noun the word for `what' is one the lesson calls no noun:
%% Italian's first is `cosa', a thing too, and `Menudo inicio.' came out
%% `Cos'inizio.' where Italian says `Che inizio.')
tr_np_out(To, what_np(NP), [o(QW, lower)|Outs], Noun, Number) :- !,
    (   To == foreign, once(( tr_solve(mean(W, what)), atom(W), \+ sub_atom(W, _, _, _, ' '),
                              \+ tr_is(foreign, w(W, lower), noun) ))
    ->  QW = W
    ;   tr_what_word(To, QW)
    ),
    tr_np_out(To, NP, Outs, Noun, Number).
%% a phrase and its phrases of `of', as the head of a clause after a comma
%% (tr_reporting/3): `el presidente de la Generalitat, que inauguró ...'
tr_np_out(english, rng(NP), Outs, Noun, Number) :- !, tr_np_out(english, NP, Outs, Noun, Number).
tr_np_out(To, with(NP00, PPs00), Outs, Noun, Number) :- !,
    tr_with_adj(To, NP00, PPs00, NP, PPs0),
    tr_of_dropped(To, NP, PPs0, PPs),
    tr_np_out(To, NP, O1, Noun, Number),
    tr_comps_out(To, PPs, Noun, Number, _, O2, A2), append([O1, O2, A2], Outs).
%% ... a second relative clause JOINED to the first, with the coordinator where a comma would be: `an attack of
%% which the fans dream and which the injuries have truncated'
tr_np_out(To, nrc(NP, ro(Co, Role), S0), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, NPOut, Noun, Number),
    tr_connector_out(To, Co, CoOut),
    (   To == english
    ->  ( Role = pp(_) -> tr_relative_out(To, Role, Noun, Number, RelOut) ; RelOut = [o(which, lower)] )
    ;   tr_relative_out(To, Role, Noun, Number, RelOut)
    ),
    (   S0 = s(A, gap, G, Cs) -> S1 = s(A, gap(third, Number), G, Cs) ; S1 = S0 ),
    tr_gap_write(To, Noun, S1, SOut),
    append([NPOut, CoOut, RelOut, SOut], Outs).
tr_np_out(To, nrc(NP, Role, S0), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, NPOut, Noun, Number),
    (   To == english, Role \= pp(_), Role \== whose
    ->  ( tr_of_class(NP, person) -> RelOut0 = [o(who, lower)] ; RelOut0 = [o(which, lower)] )
    ;   tr_relative_out(To, Role, Noun, Number, RelOut0)
    ),
    %% (the quotation that opened on the relative word, tr_rel_mark/3)
    (   S0 = s(A0, Su0, G0, Cs0), select(qrel, Cs0, Cs1), RelOut0 = [o(RW, _)|RR]
    ->  S = s(A0, Su0, G0, Cs1), RelOut = [o(RW, qopen)|RR]
    ;   S = S0, RelOut = RelOut0
    ),
    (   S = s(A, gap, G, Cs) -> S1 = s(A, gap(third, Number), G, Cs) ; S1 = S ),
    tr_gap_write(To, Noun, S1, SOut),
    append([NPOut, [o(',', comma)], RelOut, SOut], Outs).
%% A DATE OUT: the lesson's language puts the day, its join word and the
%% month in the phrase's own order -- `il 20 gennaio', `el 20 de enero' --
%% and English puts the month first with no article, `January 20'. The year
%% follows with the join word again, or in English after a comma when a day
%% was written: `el 20 de enero de 2014', `January 20, 2014'.
tr_np_out(To, app(NP, year, w(Y, C)), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, O1, Noun, Number),
    (   To == english -> ( NP = np(_, w(_, _), _, _, _) -> Sep = [o(',', comma)] ; Sep = [] )
    ;   tr_date_join_out(Sep)
    ),
    append([O1, Sep, [o(Y, C)]], Outs).
%% ... and with an adjective, which English puts before the month and the
%% lesson's languages after it: `il 12 luglio scorso' is `el 12 de julio
%% último', `last July 12' -- written as any phrase, the join word was lost,
%% `el 12 julio último'
tr_np_out(To, np(Det, Num, Adjs, w(NW, NC), Number), Outs, Noun, Number) :-
    Num = w(_, _), tr_month(english, w(NW, NC)), !,
    ( To == foreign, tr_month_word(NW, Noun0) -> Noun = Noun0 ; tr_noun_lexeme(To, NW, Number, _, Noun) ),
    tr_num_out(To, Num, NumOut),
    ( Adjs == [] -> AdjOut = [] ; tr_adjectives_out(To, Adjs, Noun, Number, As), tr_adj_words(As, AdjOut) ),
    (   To == english
    ->  append(AdjOut, [o(Noun, upper)|NumOut], Outs)
    ;   tr_inflect(To, noun, Noun, Number, NounForm),
        %% (the article is the one for the word that follows it, the day's
        %% number: `dell'8 marzo', `dall'11 settembre' -- asked of the month it
        %% was `del 8 marzo' and `dal 11 settembre'. The first of the month is
        %% `primo', a consonant: `il 1 maggio')
        ( NumOut = [o(Day, _)|_], Day \== '1' -> Next = NumOut ; Next = [o(NounForm, NC)] ),
        tr_det_out(To, Det, Noun, Number, Next, DetOut),
        tr_date_join_out(Sep),
        append([DetOut, NumOut, Sep, [o(NounForm, NC)], AdjOut], Outs)
    ).
tr_np_out(To, app(NP, yearw, w(Y, C)), Outs, Noun, Number) :- !,
    tr_word_across(w(Y, lower), To, number, YT0),
    %% (English writes a year of two digits said in words as `'79': `nel settembre del settantanove' is in September
    %% '79, where it was `September seventy-nine')
    ( To == english, en_short_year(YT0, YT1) -> YT = YT1 ; YT = YT0 ),
    tr_np_out(To, app(NP, year, w(YT, C)), Outs, Noun, Number).
%% ... a day and its date (app/3's wdate, tr_weekday_date/2): English's comma between them, `Thursday, June 6'; the
%% lesson's language with none, `el jueves 6 de junio', `giovedì 6 giugno'
tr_np_out(To, app(NP1, wdate, NP2), Outs, Noun, Number) :- !,
    tr_with_time_noun(tr_np_out(To, NP1, O1, Noun, Number)), tr_np_out(To, NP2, O2, _, _),
    ( To == english -> append([O1, [o(',', comma)], O2], Outs) ; append(O1, O2, Outs) ).
tr_np_out(To, app(NP1, part, NP2), Outs, Noun, Number) :- !,
    (   To == foreign, tr_solve(join(J, time))
    ->  tr_with_article(NP1, A1), tr_with_article(NP2, A2),
        tr_np_out(To, A1, O1, Noun, Number), tr_np_out(To, A2, O2, _, _),
        append([O1, [o(J, lower)], O2], Outs)
    ;   tr_np_out(To, NP1, O1, Noun, Number), tr_np_out(To, NP2, O2, _, _), append(O1, O2, Outs)
    ).
%% ... a decade's, `the 70s' in English
tr_np_out(english, app(np(det(article, _, _), none, [], w(year, _), plural), label, w(N, C)), [o(the, lower), o(N70, C)], year, plural) :-
    tr_decade(N), atom_concat(N, s, N70), !.
%% ... a day of the month the source names by `the day' and its number, the ordinal in English: `La bomba del
%% día 21 fue una anécdota' is the bomb of the 21st, and `the day 21' was written
tr_np_out(english, app(NP, label, w(N, C)), [o(the, lower), o(Nth, C)], day, singular) :-
    tr_day_number(app(NP, label, w(N, C)), N), en_ordinal(N, Nth), !.
tr_np_out(To, app(NP, label, w(N, C)), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, O1, Noun, Number), append(O1, [o(N, C)], Outs).
tr_np_out(To, app(NP, apposed, w(N, _)), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, O1, Noun, Number), append(O1, [o(',', comma), o(N, upper), o(',', comma)], Outs).
%% ... a title, after its phrase (tr_np/3's)
%% (a title's words are no verb's complements, and a person in them takes no marker: `il cinismo della
%% trasmissione "generale per una sera"' came out `de la transmisión a "general durante una noche"', the general
%% marked as the clause's object -- tr_marker/3 asks the verb being written, which the title has none of)
tr_np_out(To, app(NP, title, Cs), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, O1, Noun, Number),
    tr_global('$tr_verb', V0), nb_setval('$tr_verb', none),
    (   tr_comps_out(To, Cs, none, singular, _, O2, A2) -> nb_setval('$tr_verb', V0)
    ;   nb_setval('$tr_verb', V0), fail
    ),
    append([O1, O2, A2], Outs).
tr_np_out(To, app(NP, numbered, w(N, C)), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, O1, Noun, Number), tr_word_across(w(number, lower), To, noun, NW), append(O1, [o(NW, lower), o(N, C)], Outs).
tr_np_out(To, app(NP, Kind, Inner), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, O1, Noun, Number), tr_aside_out(To, Kind, Inner, Noun, Number, O2), append(O1, O2, Outs).
%% A YEAR TAKES THE ARTICLE WHERE THE LESSON SAYS SO: `The article "il"
%% takes the year.' Spanish's `un violín de 1736' is Italian's `un violino
%% del 1736', and English's `of 1736'. The IR carries the year bare --
%% the reader takes such an article off again (tr_cross_np/2) -- so the
%% article is the language's, written where its lesson puts it.
%% The article is the one the lesson names, because a year has no gender
%% for an article to agree with.
tr_np_out(foreign, np(none, none, [], w(Y, C), singular), [o(A, lower), o(Y, C)], none, singular) :-
    tr_year(Y), once(tr_solve(take(A, year))), !.
%% ... AND A DAY OF THE WEEK THE SAME, where the lesson says so: `The article
%% "el" takes the day.' Italian's `da martedì scorso fino a lunedì prossimo'
%% is Spanish's `desde el martes pasado hasta el lunes próximo'. The IR
%% carries the day bare, as it does a year, and the reader takes the article
%% off again (tr_cross_np/2); the article is the lesson's definite one, which
%% agrees with the day.
tr_np_out(foreign, np(none, Num, Adjs, w(D, C), singular), Outs, Noun, singular) :-
    tr_weekday(D), once(tr_solve(take(_, day))),
    tr_np_out(foreign, np(det(article, the, w(the, lower)), Num, Adjs, w(D, C), singular), Outs, Noun, singular), !.
%% ... AND ENGLISH PUTS A BARE PARTICIPLE BEFORE ITS NOUN: `la valutazione
%% gonfiata' is the inflated valuation, and after the noun it read `the
%% evaluation inflated of a terrain'. A participle with its agent or an
%% adjunct stays after it, `the curfew imposed by the soldiers'.
%% -- with its degree too: `una adhesión más limitada' is a more limited
%% adherence
%% -- and never one of a verb of several words, which stays after it too:
%% `la ragazza investita a Torvaianica' is the girl run over in it, and
%% before the noun it was `the run over girl'
%% -- nor after a name apposed to its noun, between commas, which the participle follows as the source has it:
%% `il fratello, Said, accusato di aver ucciso Sara' is the brother, Said, accused of having killed her, where it was
%% `the accused brother, Said, of having killed'
tr_np_out(english, rel(np(Det, Num, Adjs, w(NW, NC), Nb), L, Comps0), Outs, Noun, Number) :-
    \+ ( member(C, Comps0), C \= agr(_), C \= agrn(_), C \= pdeg(_), \+ tr_pre_participle_adverb(C, _) ),
    \+ memberchk(w(_, appos), Adjs),
    tr_lexeme_across(L, english, LT), en_reduced_participle(LT, PP), \+ atomic_list_concat([_, _|_], ' ', PP),
    (   memberchk(pdeg(D), Comps0)
    ->  ( D == superlative -> DW = most ; DW = more ), P1 = ptcd(DW, PP)
    %% (and the adverb before it, which says how: `su una superficie sostanzialmente limitata' is on a
    %% substantially limited surface, where it was `a surface substantially limited')
    ;   member(C2, Comps0), tr_pre_participle_adverb(C2, AW)
    ->  P1 = ptcd(AW, PP)
    ;   P1 = ptc(PP)
    ),
    append(Adjs, [P1], Adjs1),
    tr_np_out(english, np(Det, Num, Adjs1, w(NW, NC), Nb), Outs, Noun, Number), !.
tr_np_out(To, rel(NP, L, Comps0), Outs, Noun, Number) :- !,
    tr_np_out(To, NP, NPOut0, Noun, Number),
    ( select(agr(GA), Comps0, Comps01) -> true ; Comps01 = Comps0, GA = none ),
    ( select(agrn(NA), Comps01, Comps1) -> PNumber = NA ; Comps1 = Comps01, PNumber = Number ),
    %% an aside after a comma: the commas the source had, before the
    %% participle and after its adjuncts
    (   select(aside(Cl), Comps1, Comps2)
    ->  append(NPOut0, [o(',', comma)], NPOut), ( Cl == yes -> Close = [o(',', comma)] ; Close = [] )
    ;   Comps2 = Comps1, NPOut = NPOut0, Close = []
    ),
    ( select(pcase(PC), Comps2, Comps3) -> true ; Comps3 = Comps2, PC = lower ),
    %% the degree the participle carries: the lesson's word for `more', or
    %% English's `most' and `more' (the most awaited)
    (   select(pdeg(D), Comps3, Comps4)
    ->  ( To == english -> ( D == superlative -> DW = most ; DW = more ) ; tr_degree_out(DW) ), Deg = [o(DW, lower)]
    ;   Comps4 = Comps3, Deg = []
    ),
    %% ... and the adverb that stood before the participle, before it again
    (   select(padv(w(A, AC)), Comps4, Comps)
    ->  tr_word_across(w(A, lower), To, adverb, AT), Adv = [o(AT, AC)]
    ;   Comps = Comps4, Adv = []
    ),
    (   To == english
    ->  tr_lexeme_across(L, english, LT), en_reduced_participle(LT, PP)
    ;   tr_lexeme_across(L, foreign, LT),
        ( GA \== none -> G = GA ; tr_gender(Noun, G0), G0 \== none -> G = G0 ; G = masculine ),
        tr_with_gender(G, tr_participle_agreeing(LT, PNumber, PP))
    ),
    tr_ptc_day_first(To, Comps, DayOut, CompsD),
    tr_comps_out(To, CompsD, Noun, Number, _, CompOuts0, AdvOuts), append(DayOut, CompOuts0, CompOuts),
    append([NPOut, Adv, Deg, [o(PP, PC)|CompOuts], AdvOuts, Close], Outs).
tr_np_out(To, adv(w(A, C)), [o(AT, C)], none, singular) :- !, tr_word_across(w(A, lower), To, adverb, AT).
tr_np_out(To, pp(w(P, C), NP), [o(PT, C)|Outs], none, singular) :- !,                   % `come in tutti i parchi'
    tr_word_across(w(P, lower), To, preposition, PT), tr_np_out(To, NP, Outs, _, _).
%% an adverb on a phrase goes in front of it in every language: `solo uno',
%% `only one'
%% (`as many as' in a lesson's language is its word for it, or nothing where it states none: the count
%% says it)
tr_np_out(english, advp(w('as many as', C), NP), [o(as, C), o(many, lower), o(as, lower)|Outs], Noun, Number) :- !,
    tr_np_out(english, NP, Outs, Noun, Number).
tr_np_out(foreign, advp(w('as many as', C), NP), Outs, Noun, Number) :- !,
    tr_np_out(foreign, NP, NOut, Noun, Number),
    ( tr_word_across(w('as many as', lower), foreign, adverb, AT) -> Outs = [o(AT, C)|NOut] ; Outs = NOut ).
tr_np_out(To, advp(w(A, C), NP), [o(AT, C)|Outs], Noun, Number) :- !,
    tr_word_across(w(A, lower), To, adverb, AT), tr_np_out(To, NP, Outs, Noun, Number).
%% (and English's `the Internet', which the lesson's languages name with no article: `utilizan cada vez más
%% Internet' use the Internet increasingly)
tr_np_out(english, name(W), [o(the, lower), o('Internet', upper)], none, singular) :- atom(W), downcase_atom(W, internet), !.
tr_np_out(foreign, name(W), [o(N, upper)], none, singular) :- tr_name_word_out(W, N), !.
tr_np_out(_, name(W), [o(W, upper)], none, singular) :- !.
%% `all' before the phrase, agreeing with its noun in the lesson's language
%% -- and before a plural personal pronoun English says `all of us', `all of
%% them', and the lesson's `all' is plural for it, whatever number the IR
%% gave the pronoun's noun: `per tutti noi' wrote `para todo nosotros'
tr_np_out(english, all(w(_, C), NP), [o(all, C), o(of, lower), o(T, lower)], none, plural) :-
    tr_all_of_pronoun(NP, T), !.
tr_np_out(english, all(w(_, C), ell(det(article, what, _), _, Number, rel(_, S0))), [o(all, C), o(that, lower)|SOut], none, Number) :- !,
    ( S0 = s(A, gap, G, Cs) -> S = s(A, gap(third, Number), G, Cs) ; S = S0 ),
    tr_gap_write(english, none, S, SOut).
tr_np_out(english, all(w(_, C), NP), [o(all, C)|O], Noun, Number) :- !, tr_np_out(english, NP, O, Noun, Number).
tr_np_out(foreign, all(w(_, C), NP), [o(AW, C)|O], Noun, Number) :- !,
    tr_np_out(foreign, NP, O, Noun, Number0),
    findall(A, ( tr_solve(mean(A, all)), tr_class_of(A, pronoun) ), As), As \== [],
    ( tr_all_of_pronoun(NP, _) -> Number = plural ; Number = Number0 ),
    tr_agree(foreign, As, Noun, A1), tr_inflect(foreign, pronoun, A1, Number, AW).
%% a phrase whose noun was left out: the article and the adjectives, agreeing
%% with the gender the source's article lent it; English adds `one' unless
%% the adjective is a superlative, which stands alone (`the weakest')
%% -- and its count after the article, as it stood: `los dos primeros'
%% (and one o'clock: the lesson's feminine article for `a', as the source said it -- `a la una', `all'una' -- where
%% Italian has no number word for one and Spanish's is `un', which wrote `la un')
tr_np_out(foreign, np(Det, w(one, C), [], elided(feminine), singular), Outs, elided(feminine), singular) :-
    tr_det_meanings(article, a, Ms), member(A, Ms), atom(A), tr_gender(A, feminine), \+ tr_solve(elision_of(A, _)), !,
    tr_det_out(foreign, Det, elided(feminine), singular, [o(A, C)], DetOut),
    append(DetOut, [o(A, C)], Outs).
tr_np_out(To, nform(NP), Outs, N, Nb) :- !, tr_np_out(To, NP, Outs, N, Nb).        % (tr_form_of_phrase/2)
tr_np_out(To, np(Det, Num, Adjs, elided(G0), Number), Outs, elided(G), Number) :- !,
    ( G0 \== none -> G = G0 ; G = masculine ),
    tr_adjectives_out(To, Adjs, elided(G), Number, AdjOuts), tr_adj_words(AdjOuts, AOs),
    tr_num_out(To, Num, NumOut),
    %% (English puts an adjective of order before the count, and adds no `ones': `gli ultimi tre' are the last three,
    %% where it was `the three last ones')
    (   To == english, NumOut = [_|_], AOs = [o(OA, _)|_], atom(OA), en_order_adjective(OA)
    ->  append(AOs, NumOut, After), Ordered = yes
    %% (and `other' alone in the plural is `others': `si spende poco per gli altri' is one spends little on the others,
    %% where it was `the other ones')
    ;   To == english, Number == plural, NumOut == [], AOs = [o(other, OC)]
    ->  After = [o(others, OC)], Ordered = yes
    ;   append(NumOut, AOs, After), Ordered = no
    ),
    tr_det_out(To, Det, elided(G), Number, After, DetOut),
    %% (a count alone needs no `ones' in English: `entre las tres y las cinco'
    %% is between the three and the five, and it came out `the three ones')
    %% (nor an adjective alone, which says what it is of nothing: `convertir en
    %% peatonal' is turn into pedestrian, never `pedestrian one')
    (   To == english, Ordered == no, \+ memberchk(deg(superlative, _), Adjs), \+ memberchk(deg(less(superlative), _), Adjs),
        \+ ( Adjs == [], Num \== none ), \+ ( Det == none, Num == none ),
        %% (nor `the same': `el mundo ya no es el mismo' is the world is no longer the same)
        \+ ( Adjs = [A1], ( A1 = w(same, _) ; A1 = pre(w(same, _)) ) )
    ->  ( Number == plural -> One = [o(ones, lower)] ; One = [o(one, lower)] )
    ;   One = []
    ),
    append(DetOut, After, O1), append(O1, One, Outs).
%% ... and one with a `de' phrase: English's `those' or `the one'; the
%% lesson's article where it says the article REPLACES the noun (`The word
%% "el" replaces the noun.', Spanish's `los de'), and otherwise its pronoun
%% for `that' in the gender and the number (Italian's `quelli di')
%% -- and after the INDEFINITE article it is `one of': `una de sus mejores
%% noches' is one of her best nights, and it came out `quella delle sue
%% notti', that one; the lesson's pronoun for `one' that stands alone
%% (`uno'), or the article where the gender has no such pronoun (`una')
tr_np_out(english, ell(det(article, a, _), _, Number, PP), Outs, none, Number) :- !,
    tr_ell_tail(english, PP, none, Number, PPOut), append([o(one, lower)], PPOut, Outs).
%% (and the gender of the noun the `of' phrase names, as the other language writes it, when it
%% names one: `una delle squadre' is `uno de los equipos', never `una de los')
tr_np_out(foreign, ell(Det, G0, Number, PP), Outs, elided(G), Number) :-
    Det = det(article, a, _), !,
    ( tr_ell_gender(PP, G1) -> G = G1 ; G0 \== none -> G = G0 ; G = masculine ),
    findall(P, ( tr_solve(mean(P, one)), tr_class_of(P, pronoun), tr_solve(neg(precede(P, verb))) ), Ps),
    (   Ps \== [], tr_agree(foreign, Ps, elided(G), P1), tr_gender(P1, PG), ( PG == G ; PG == none, G == masculine )
    ->  Head = [o(P1, lower)]
    ;   tr_det_out(foreign, Det, elided(G), Number, [], Head)
    ),
    tr_ell_tail(foreign, PP, elided(G), Number, PPOut), append(Head, PPOut, Outs).
%% ... and `what' with its clause, no `that' between them (tr_np/3)
tr_np_out(english, ell(det(article, what, _), _, Number, rel(_, S0)), Outs, none, Number) :- !,
    ( S0 = s(A, gap, G, Cs) -> S = s(A, gap(third, Number), G, Cs) ; S = S0 ),
    tr_gap_write(english, none, S, SOut), append([o(what, lower)], SOut, Outs).
%% (a count of time and its `ago' (tr_ago_phrase/2): the time, then the adverb -- or the
%% adverb first, where the lesson's word for it begins a time, `hace cuarenta años')
tr_np_out(english, ago(NP, w(E, C)), Outs, Noun, Number) :- !,
    tr_np_out(english, NP, NOut, Noun, Number), append(NOut, [o(E, C)], Outs).
tr_np_out(foreign, ago(NP, w(E, C)), Outs, Noun, Number) :- !,
    tr_word_across(w(E, lower), foreign, adverb, AT),
    tr_np_out(foreign, NP, NOut, Noun, Number),
    (   E == ago, tr_ago_first
    ->  %% (the adverb written first, the mark that closes on it goes to the time's last word, and one
        %% that opens on the time to the adverb: `"... a quello di trenta anni fa"' is `"... al de hace
        %% treinta años"', where it was `al de hace" treinta años')
        (   C == qclose, append(NPre, [o(LW, LC)], NOut) -> tr_join_case(LC, qclose, LC1), append(NPre, [o(LW, LC1)], NOut1), AC = lower
        ;   NOut = [o(FW, qopen)|NRest] -> NOut1 = [o(FW, lower)|NRest], AC = qopen
        ;   NOut1 = NOut, AC = C
        ),
        Outs = [o(AT, AC)|NOut1]
    ;   append(NOut, [o(AT, C)], Outs)
    ).
%% (one with a phrase of `of' is `that of', as `those of' is: `l'inquinamento è
%% inferiore a quello di trenta anni fa' is lower than that of thirty years ago,
%% where it was `the one of'; before a clause it stays `the one that')
tr_np_out(english, ell(_, _, Number, PP), Outs, none, Number) :- !,
    (   Number == plural -> Head = [o(those, lower)]
    ;   PP = pp(w(of, _), _) -> Head = [o(that, lower)]
    ;   Head = [o(the, lower), o(one, lower)]
    ),
    tr_ell_tail(english, PP, none, Number, PPOut), append(Head, PPOut, Outs).
tr_np_out(foreign, ell(Det, G0, Number, PP), Outs, elided(G), Number) :- !,
    ( G0 \== none -> G = G0 ; G = masculine ),
    (   Det = det(_, DL, _), tr_meanings_of(DL, foreign, article, Ms), member(A, Ms), tr_solve(replace(A, noun))
    ->  tr_det_out(foreign, Det, elided(G), Number, [], Head)
    ;   findall(P, ( tr_solve(mean(P, that)), tr_class_of(P, pronoun) ), Ps), Ps \== [],
        tr_agree(foreign, Ps, elided(G), P1), tr_inflect(foreign, pronoun, P1, Number, PF), Head = [o(PF, lower)]
    ),
    tr_ell_tail(foreign, PP, elided(G), Number, PPOut), append(Head, PPOut, Outs).
%% a pronoun's number is the one English gives it -- `those' is plural, and a
%% relative clause on it must say `che sono', never `che e'
%% ... AND A NEGATIVE PRONOUN AFTER A DENIED VERB IS THE POSITIVE ONE IN
%% ENGLISH, which has one negation to a clause: `non ho nulla' is `I do not have
%% anything', never `I do not have nothing'; `non ho visto nessuno' `I have not
%% seen anybody' (the clause's denial is the global tr_write/4 sets while it
%% writes the complements)
tr_np_out(To, pronoun(w(W, C)), [o(T, C)], none, N) :- !,
    tr_pronoun_across(To, oblique, w(W, C), _, _, T0),
    ( To == english, tr_global('$tr_denied', yes), en_any_form(T0, T1) -> T = T1 ; T = T0 ),
    ( tr_side_here(english), en_tonic(W, N0) -> N = N0 ; N = singular ).
%% (a pronoun of quantity and its adjective, padj/2: the adjective after the pronoun, `something new', `algo nuevo')
tr_np_out(To, padj(P, A), Outs, none, singular) :- !,
    tr_np_out(To, P, PO, _, _),
    tr_adjective_out(To, A, named(masculine, []), singular, a(_, AO)),
    append(PO, AO, Outs).
tr_np_out(To, ninf(L), Outs, named(masculine, []), singular) :- !,     % `del contendere', `of the contending'
    tr_lexeme_across(L, To, LT),
    (   To == english -> en_gerund_of(LT, G), Outs = [o(the, lower), o(G, lower)]
    ;   once(tr_solve(infinitive_of(Inf, LT))),
        tr_det_out(foreign, det(article, the, w(the, lower)), named(masculine, []), singular, [o(Inf, lower)], DO),
        append(DO, [o(Inf, lower)], Outs)
    ).
%% the article and the word it quotes, the adverb of the language written
%% (nq/2: `il "qui"' is `el "aquí"'); masculine, as the article before an
%% infinitive is
tr_np_out(To, nq(Det, w(T, C)), Outs, named(masculine, []), singular) :- !,
    tr_word_across(w(T, lower), To, adverb, WT),
    tr_det_out(To, Det, named(masculine, []), singular, [o(WT, C)], DO),
    append(DO, [o(WT, C)], Outs).
tr_np_out(To, nonly(A, B, Also), Outs, none, N) :- !,          % `non solo io ma tanti altri'
    tr_subject_out(To, A, AO, _, NA, _), tr_subject_out(To, B, BO, _, NB, _),
    %% (plural when EITHER half is: `lo sapevano non solo Tolomeo ed
    %% Eratostene, ma persino Pitagora' -- the second half's number alone
    %% wrote `Lo supo', one who knew where the source says several)
    ( ( NA == plural ; NB == plural ; Also = pl(_) ) -> N = plural ; N = NB ),
    tr_nonly_words(To, Also, NotO, OnlyO, ButO, AlsoO),
    append([NotO, OnlyO, AO, ButO, AlsoO, BO], Outs).
%% A COUNT WHOSE NOUN THE PHRASE AFTER THE COORDINATOR NAMES takes that noun's gender as the target
%% writes it: `le quattro o cinque squadre' is `los cuatro o cinco equipos', and the article
%% of the first count took the source noun's feminine. A number and nothing else: `21 nuove e 12
%% rinnovi' are twenty-one new ones (licenses) and twelve renewals, the first count's own noun
tr_np_out(foreign, co(C, N1, N2), Outs, none, plural) :-
    tr_elided_count(N1, G0),
    tr_np_head(N2, np(_, _, _, w(NW2, _), N2n)), atom(NW2), \+ atom_number(NW2, _),   % (no time in digits: `la 1.30')
    tr_noun_lexeme(foreign, NW2, N2n, _, Noun2), tr_gender(Noun2, G1), G1 \== none, G1 \== G0, !,
    tr_elided_count_gender(N1, G1, N1g),
    tr_np_out(foreign, co(C, N1g, N2), Outs, none, plural).
tr_np_out(To, co(C, N1, N2), Outs, none, plural) :- !,
    tr_np_out(To, N1, O1, _, _), tr_np_out(To, N2, O2, _, _),
    tr_connector_out(To, C, CO), append(CO, O2, O3), append(O1, O3, Outs).
%% a name goes out as the words it is, with the determiner agreeing against
%% the gender the phrase carries rather than against a noun there is none of
tr_np_out(To, np(Det0, none, [], named(G0, Ws), Number), Outs, named(G, Ws), Number) :- !,
    %% (each word in its own case: a quoted run carries its marks)
    tr_named_words(To, Ws, Content),
    tr_country_det(To, Det0, Ws, Det),
    %% (a name the lesson gives a meaning has the gender the lesson states of it, not the source article's: `en los
    %% Alpes' is `nelle Alpi', and with Spanish's masculine it was `negli Alpi')
    ( To == foreign, tr_crossed_name_gender(Ws, G1) -> true ; G1 = G0 ),
    tr_det_out(To, Det, named(G1, Ws), Number, Content, DetOut),
    %% AND WHERE THE IR CARRIES NO GENDER THE WRITTEN ARTICLE SUPPLIES ONE,
    %% which is the reading rule seen from the other side. An English source
    %% gives `none', the article is then chosen by the lesson's own order,
    %% and everything after it -- a participle agreeing, an adjective --
    %% must agree with the word actually written or the sentence disagrees
    %% with itself: measured, `La Tate Gallery e stato evacuato'.
    ( G0 \== none -> G = G0 ; tr_written_gender(To, DetOut, G) ),
    append(DetOut, Content, Outs).
%% ... and with its adjectives, placed as a noun's are and agreeing with the
%% gender the name carries
%% (each word in its own case too: a name the lesson states in small
%% letters, `lo speciale superquark', was dropped here, `el especial')
tr_np_out(To, np(Det, none, Adjs, named(G0, Ws), Number), Outs, named(G, Ws), Number) :- !,
    tr_named_words(To, Ws, Name),
    tr_adjectives_out(To, Adjs, named(G0, Ws), Number, AdjOuts),
    ( To == english -> en_adj_order(Adjs, AdjOuts, AdjOutsO) ; tr_foreign_adj_order(Adjs, AdjOuts, AdjOutsO) ),
    tr_order(To, '$name', AdjOutsO, Content0),
    append(Before, ['$name'|After], Content0), append([Before, Name, After], Content),
    tr_det_out(To, Det, named(G0, Ws), Number, Content, DetOut),
    ( G0 \== none -> G = G0 ; tr_written_gender(To, DetOut, G) ),
    append(DetOut, Content, Outs).
%% A YEAR TAKES NO ARTICLE IN ENGLISH: `las transferencias de competencias de aquí al 2002', `prevé de
%% cara al 2004' are until 2002 and with a view to 2004 -- Spanish and Italian give a year the article
%% (`al 2002', `nel 2004'), and English wrote `until the 2002'
tr_np_out(english, np(det(article, the, _), none, [], w(Y, C), singular), [o(Y, C)], Y, singular) :-
    tr_year_word(Y), !.
%% English capitalises a title before a name: `Monsignor Salvatore Cassisa'
tr_np_out(english, np(none, none, [w(A, upper)], w(NW, _), singular), [o(Noun, upper), o(A, upper)], Noun, singular) :-
    tr_noun_lexeme(english, NW, singular, _, Noun), tr_title_word(english, Noun), !.
%% ... and the lesson's language writes the title's short form where it
%% states one: `monsignor Salvatore Cassisa', `"monsignor" is the apocope of
%% "monsignore".', as an adjective's is written before its noun
tr_np_out(To, gov(_, NP), Outs, Noun, Number) :- !, tr_np_out(To, NP, Outs, Noun, Number).
tr_np_out(foreign, np(none, none, [w(A, upper)], w(NW, NC), singular), [o(T, NC), o(A, upper)], Noun, singular) :-
    tr_noun_lexeme(foreign, NW, singular, _, Noun), tr_title_word(foreign, Noun), !,
    ( tr_solve(apocope_of(T0, Noun)) -> T = T0 ; T = Noun ).
%% THE DAY, THE MONTH OR THE YEAR THAT WAS OR IS TO COME: `el año pasado' is last
%% year, `el pasado martes' last Tuesday, `el próximo noviembre' next November
%% -- no article, `last' or `next' for the adjective, and the day or the month
%% with its capital (English wrote `the past year', `past tuesday')
%% ... AND HALF A SOMETHING: `medio siglo' is half a century, the article after `half'
tr_np_out(english, np(none, none, [pre(w(half, C))|Adjs], w(NW, NC), singular), [o(half, C)|Outs], Noun, singular) :- !,
    tr_np_out(english, np(det(article, a, w(a, lower)), none, Adjs, w(NW, NC), singular), Outs, Noun, singular).
tr_np_out(english, np(Det, none, [A], w(NW, NC), singular), [o(Which, OC), o(NWOut, CC)], NW, singular) :-
    ( Det == none ; Det = det(article, _, _) ),
    ( A = w(W0, AC) ; A = pre(w(W0, AC)) ), memberchk(W0-Which, [past-last, next-next]),
    atom(NW), en_time_noun(NW),
    ( NC \== upper, en_calendar_word(NW) -> tr_cap(NW, NWOut) ; NWOut = NW ),
    %% (the marks of the words that went stay: the article's opening one, and the closing one of
    %% the adjective, which stood last, or of the noun)
    ( Det = det(_, _, w(_, DC)) -> true ; DC = lower ),
    (   ( tr_opens_quote(DC) ; tr_opens_quote(AC) ) -> OC = qopen ; OC = lower ),
    (   ( memberchk(AC, [qclose, qcloseu, qboth, qbothu]) ; memberchk(NC, [qclose, qcloseu, qboth, qbothu]) ) -> CC = qclose ; CC = NC ), !.
%% A POSSESSIVE AFTER ITS NOUN, OR AFTER ANOTHER DETERMINER, IS THE PHRASE'S OWN: `a casa sua' is to his house,
%% `quella sua voce' that voice of his, `un amico suo' a friend of his. The vocabulary's adjective `sua' is `hers'
%% (the dictionary's possessive pronoun), and English wrote `to hers house' and `that hers voice'. With no determiner
%% or the article it is the determiner, the lesson's first possessive (`his'); after another it is `of' and the
%% pronoun, after the phrase. (The lesson's languages write it after the noun, tr_poss_after/2: `esa voz suya')
tr_np_out(english, np(Det, Num, Adjs0, N, Nb), Outs, Noun, Number) :-
    select(A, Adjs0, Adjs), ( A = w(P, PC) ; A = pre(w(P, PC)) ), atom(P), en_poss_pronoun(P, PD, PO), !,
    (   ( Det == none ; Det = det(article, the, _) )
    ->  tr_np_out(english, np(det(possessive, PD, w(PD, PC)), Num, Adjs, N, Nb), Outs, Noun, Number)
    ;   tr_np_out(english, np(Det, Num, Adjs, N, Nb), Outs0, Noun, Number), append(Outs0, [o(of, lower), o(PO, lower)], Outs)
    ).
tr_np_out(To, np(Det, Num, Adjs00, w(NW, NC), Number), Outs, Noun, Number) :-
    tr_poss_after(To, Adjs00, Adjs),
    tr_noun_lexeme(To, NW, Number, _, Noun),
    tr_inflect(To, noun, Noun, Number, NounForm00),
    tr_counted_form(To, Num, Noun, NounForm00, NounForm01),
    tr_percent_style(To, NounForm01, NounForm0),
    tr_name_apocope(To, Adjs, Number, Noun, NounForm0, NounForm),
    tr_plural_gender(To, Noun, Number, NounForm, GNoun0),
    tr_meaning_gender(To, Noun, NW, GNoun0, GNoun1),
    tr_fem_person_gender(To, NW, Number, Noun, GNoun1, GNoun),
    tr_degree_last(To, Adjs, Adjs1),
    tr_adjectives_out(To, Adjs1, GNoun, Number, AdjOuts),
    %% (an English day, month or nationality with its capital, wherever it stands, in the plural as well: the Catalans)
    %% (and a noun of several words that opens on one: `Italian football' is the lesson's noun for `el calcio')
    (   To == english, NC \== upper,
        (   en_calendar_word(Noun) ; en_nationality(Noun)
        ;   atom(Noun), atomic_list_concat([Opening, _|_], ' ', Noun), en_nationality(Opening)
        )
    ->  tr_cap(NounForm, NounOut)
    ;   NounOut = NounForm
    ),
    ( To == english -> en_adj_order(Adjs1, AdjOuts, AdjOutsO) ; tr_foreign_adj_order(Adjs1, AdjOuts, AdjOutsO) ),
    tr_order(To, o(NounOut, NC), AdjOutsO, Content0),
    %% (a mark that closes on the noun itself stays there: `di inserimento"
    %% francese' quotes the noun, and the adjective after it is outside)
    ( NC == qclose -> Content = Content0 ; tr_edge_marks(Content0, Content) ),
    %% (a number before an anniversary or a birthday counts the years it is the
    %% ... of: `este 50 aniversario' is this 50th anniversary)
    (   To == english, Num = w(N, NCnt), atom(N), tr_digits(N), memberchk(NounForm, [anniversary, birthday]),
        en_ordinal(N, Ord)
    ->  NumOut = [o(Ord, NCnt)]
    ;   tr_num_out(To, Num, NumOut)
    ),
    %% the determiner's form is chosen by the word written after it, which is
    %% the count when there is one: `los dos últimos años' is `i due ultimi
    %% anni', and chosen by the noun it came out `gli due ultimi anni'
    %% (... and English puts an adjective of order before the count: `en las últimas tres semanas' is in the last
    %% three weeks, and `the three last weeks' was written)
    (   To == english, NumOut = [_|_], Content = [o(OA, OC)|ContentR], atom(OA), en_order_adjective(OA)
    ->  append([[o(OA, OC)], NumOut, ContentR], After)
    ;   append(NumOut, Content, After)
    ),
    tr_det_out(To, Det, GNoun, Number, After, DetOut),
    append(DetOut, After, Outs).
%% ENGLISH'S COLLECTIVE PLURALS TAKE THE PLURAL VERB: `la gente dorme' is `the
%% people sleep' and `la polizia' `the police are', the noun singular in the
%% lesson's language and plural to the verb that agrees with it (the clause of
%% a relative on it too: `la gente che dorme', `the people that sleep')
tr_verb_number(english, Noun, singular, plural) :- atom(Noun), en_collective_plural(Noun), !.
tr_verb_number(_, _, Number, Number).
tr_collective_gap(english, Noun, S0, S) :- atom(Noun), en_collective_plural(Noun), !, tr_collective_gap_(S0, S).
tr_collective_gap(_, _, S, S).
tr_collective_gap_(s(A, gap(third, singular), G, Cs), s(A, gap(third, plural), G, Cs)) :- !.
tr_collective_gap_(join(C, S1, S2), join(C, T1, T2)) :- !, tr_collective_gap_(S1, T1), tr_collective_gap_(S2, T2).
tr_collective_gap_(S, S).
%% (an adverb in `-ly', or `already', `newly', `often': never `well', `ever' or `never', which English
%% writes after the noun -- `75 anni ben portati' is 75 years well carried, and `el Mundial más exótico
%% jamás organizado' was `the most exotic never organised World cup')
tr_pre_participle_adverb(padv(w(A, _)), AT) :-
    tr_word_across(w(A, lower), english, adverb, AT), atom(AT), \+ sub_atom(AT, _, _, _, ' '),
    ( sub_atom(AT, _, 2, 0, ly) -> true ; memberchk(AT, [already, newly, often]) ), !.
%% THE PARTICIPLE OF A VERB ENGLISH SAYS WITH `IS' IS ITS SECOND WORD after a noun: `Cifre nate da un'indagine' are
%% figures BORN of a survey, and the perfect's participle of `is born' came out `figures been born from'
en_reduced_participle(LT, PP) :- atom(LT), atom_concat('is ', PP0, LT), !, PP = PP0.
%% (and the state a verb of posture leaves: `i presidenti dei "comitati", seduti nervosamente intorno al grande tavolo'
%% are SEATED around it, and the perfect's participle came out `sat around the table')
en_reduced_participle(sits, seated) :- !.
en_reduced_participle(LT, PP) :- en_participle_of(LT, PP).
%% (a day's adverb the source put first after a participle stays right after it in English: `presentato ieri dal
%% ministro ... e dal direttore generale' is presented YESTERDAY by both, and with the agents joined it was written
%% between them, `by the minister ... yesterday and by the general director')
tr_ptc_day_first(english, [adv(w(D, DC))|Cs], [o(D, DC)], Cs) :- atom(D), en_day_adverb(D), !.
tr_ptc_day_first(_, Cs, [], Cs).
tr_all_of_pronoun(pronoun(w(W, _)), T) :- tr_plural_person(W, T).
tr_all_of_pronoun(np(none, none, [], w(W, _), _), T) :- tr_plural_person(W, T).
%% a pronoun that says how much of something there is: nothing, something, anything
tr_none_word(T) :- atom(T), tr_solve(mean(T, E)), memberchk(E, [nothing, something, anything]), tr_class_of(T, pronoun), !.
%% a plural personal pronoun of English's, in the form that follows `of'
tr_plural_person(we, us).      tr_plural_person(us, us).
tr_plural_person(they, them).  tr_plural_person(them, them).
tr_plural_person(you, you).

%% what follows the head of a phrase whose noun was left out: its `de'
%% phrase, or the relative word and its clause -- or nothing, where a
%% participle after it is the reduced relative's (`quello guidato da')
tr_ell_tail(_, none, _, _, []) :- !.
%% (the gap is the phrase's, in its gender, as a relative clause's on a
%% phrase with a noun is (tr_gap_write/4): written inside another relative
%% clause it took that one's, and `chi in Italia (evidentemente a lui
%% obbligato) non lo imita', inside the clause on `mani pulite', came out
%% `obligada')
tr_ell_tail(To, rel(Role, S0), Noun, Number, Outs) :- !,
    tr_relative_out(To, Role, Noun, Number, RelOut),
    ( S0 = s(A, gap, G, Cs) -> S = s(A, gap(third, Number), G, Cs) ; S = S0 ),
    tr_gap_write(To, Noun, S, SOut), append(RelOut, SOut, Outs).
tr_ell_tail(To, PP, _, Number, Outs) :- tr_comp_out(To, PP, none, Number, _, Outs, _).
tr_elided_count(np(_, Num, [], elided(G), _), G) :- Num \== none, !.
tr_elided_count(ell(_, _, _, pp(w(of, _), NP)), G) :- tr_elided_count(NP, G).
tr_elided_count_gender(np(D, M, A, elided(_), Nb), G, np(D, M, A, elided(G), Nb)) :- !.
tr_elided_count_gender(ell(Det, _, Nb, pp(P, NP0)), G, ell(Det, G, Nb, pp(P, NP))) :- tr_elided_count_gender(NP0, G, NP).
%% A COUNTRY TAKES NO ARTICLE in English, nor in a lesson's language that
%% does not say it does: `l'Italia è un sentimento' is ITALY is a feeling,
%% and `La Italia es una sensación' no Spanish page prints, where Italian's
%% `The article "il" takes the country.' keeps its own. A country is a name
%% the lesson states one (`"italia" is a country.'), and a phrase a relative
%% clause hangs on keeps the article it has (`l'Italia che soffre' is the
%% Italy that suffers, `la Italia que padece': '$tr_keep_det', set by the
%% relative clause's writer)
tr_country_det(To, det(article, the, _), [w(E, _)], none) :-
    tr_global('$tr_keep_det', K), K \== yes,
    tr_country_name(E),
    ( To == english -> true ; \+ tr_solve(take(_, country)) ), !.
tr_country_det(_, Det, _, Det).
tr_crossed_name_gender([w(E, _)], G) :-
    atom(E), tr_name_word_out(E, L0), tr_unmark(L0, _, L1, _), downcase_atom(L1, L), tr_stated_gender(L, G), G \== none, !.
tr_country_name(N) :-
    atom(N), ( tr_name_word_out(N, L0) -> true ; L0 = N ), tr_unmark(L0, _, L1, _), downcase_atom(L1, L),
    ( tr_solve(country(L)) ; tr_solve(region(L)) ; tr_solve(continent(L)) ), !.
%% ... AND IT TAKES ONE IN A LESSON'S LANGUAGE THAT SAYS IT DOES, where the text
%% gave none: `las reformas preconizadas para Córcega' are `le riforme
%% raccomandate per la Corsica', and `Italia es bonita' is `L'Italia è bella' --
%% Spanish and English name a country with no article, and written as the bare
%% name it came in as it was `per Corsica'. Never after `in', which Italian says
%% with none (`in Corsica', `in Francia e Germania'), and only for a name whose
%% gender the lesson states, as it states `"italia" is feminine.' (`Israele'
%% takes none). Asked of a sentence that crossed a name the lesson gives a
%% meaning ('$tr_xnames'); an English text reads `Italy' as a noun, which this
%% leaves. A quotation that opens on the name opens on the article (`che "la
%% Spagna vede con simpatia la candidatura"', where the article stood outside the
%% mark), and three places keep the bare name: after a verb of going, whose `to'
%% is Italian's `in' (`va in Francia', where it was `va alla Francia'), after a
%% phrase whose noun has its capital, a name's own (`Radio Nazionale di Spagna',
%% `l'Assemblea di Corsica'), after a superlative (`l'imprenditore più ricco
%% d'Italia'), and alone in a bracket (`di Cremona (Italia)')
tr_country_articles(S0, S) :-
    nb_getval('$tr_xnames', [_|_]),
    tr_solve(take(_, country)), !,
    tr_country_articles0(S0, S).
tr_country_articles(S, S).
tr_country_articles0(T, T) :- \+ compound(T), !.
tr_country_articles0(pp(w(in, C), X), pp(w(in, C), X)) :- tr_names_only(X), !.
tr_country_articles0(app(A0, paren, X), app(A, paren, X)) :- ( X = np(N) -> tr_names_only(N) ; tr_names_only(X) ), !,
    tr_country_articles0(A0, A).
tr_country_articles0(s(A0, Su0, G, Cs0), s(A, Su, G, Cs)) :-
    G = g(L, _, _, _), atom(L), tr_motion_verb(L), !,
    tr_country_articles0(A0, A), tr_country_articles0(Su0, Su), tr_country_motion(Cs0, Cs1), tr_country_seq(none, Cs1, Cs).
tr_country_articles0(with(NP0, PPs0), with(NP, PPs)) :- !,
    tr_country_articles0(NP0, NP), tr_country_seq(NP0, PPs0, PPs).
tr_country_articles0([X0|Xs0], [X|Xs]) :- !, tr_country_seq(none, [X0|Xs0], [X|Xs]).
tr_country_articles0(name(W), np(det(article, the, w(the, DC)), none, [], named(G, [w(W1, upper)]), singular)) :-
    tr_country_name(W), tr_country_gender(W, G), !,
    ( atom_concat('"', W1, W) -> DC = qopen ; W1 = W, DC = lower ).
tr_country_articles0(T0, T) :-
    T0 =.. [F|As0], tr_country_articles_list(As0, As), T =.. [F|As].
tr_country_articles_list([], []).
tr_country_articles_list([A0|As0], [A|As]) :- tr_country_articles0(A0, A), tr_country_articles_list(As0, As).
%% a list of complements or phrases, each with the one before it: a phrase of `of' after a capitalised noun or a
%% superlative keeps its name
tr_country_seq(_, [], []).
tr_country_seq(Prev, [X0|Xs0], [X|Xs]) :-
    ( X0 = pp(w(of, _), Y), tr_names_only(Y), tr_bare_country_after(Prev) -> X = X0 ; tr_country_articles0(X0, X) ),
    tr_country_seq(X0, Xs0, Xs).
tr_bare_country_after(P) :- tr_capital_head(P), !.
tr_bare_country_after(P) :- tr_superlative_head(P).
tr_superlative_head(pp(_, NP)) :- !, tr_superlative_head(NP).
tr_superlative_head(obj(NP)) :- !, tr_superlative_head(NP).
tr_superlative_head(with(NP, _)) :- !, tr_superlative_head(NP).
tr_superlative_head(np(_, _, Adjs, _, _)) :- memberchk(deg(superlative, _), Adjs).
tr_capital_head(pp(_, NP)) :- !, tr_capital_head(NP).
tr_capital_head(obj(NP)) :- !, tr_capital_head(NP).
tr_capital_head(with(NP, _)) :- !, tr_capital_head(NP).
tr_capital_head(np(_, _, _, w(_, upper), _)).
tr_capital_head(np(_, _, _, named(_, _), _)).
tr_capital_head(name(_)).
%% (a verb of going: its `to' before a country is `in', and the name bare)
tr_country_motion([], []).
tr_country_motion([pp(w(to, C), X)|Cs0], [pp(w(in, C), X)|Cs]) :- tr_countries_only(X), !, tr_country_motion(Cs0, Cs).
tr_country_motion([X|Cs0], [X|Cs]) :- tr_country_motion(Cs0, Cs).
tr_countries_only(name(W)) :- tr_country_name(W).
tr_countries_only(co(_, A, B)) :- tr_countries_only(A), tr_countries_only(B).
tr_country_gender(W, G) :-
    ( tr_name_word_out(W, L0) -> true ; L0 = W ), tr_unmark(L0, _, L1, _), downcase_atom(L1, L),
    ( tr_holds(feminine(L)) -> G = feminine ; tr_holds(masculine(L)) -> G = masculine ).
%% (a named thing of one word in the lesson's own name for it: `il Cremlino', tr_cross_np/2)
tr_named_words(foreign, [w(E, C)], [o(N, C)]) :- tr_name_word_out(E, N), !.
tr_named_words(_, Ws, Content) :- findall(o(W, C), member(w(W, C), Ws), Content).
%% A NOUN WITH A NAME APPOSED TO IT TAKES ITS SHORT FORM where the lesson
%% states one: `al señor Westendorp' is `al signor Westendorp'. `"signor" is
%% the apocope of "signore".' was asked only of a title with no article (below),
%% and a phrase with its article came out `al signore Westendorp'.
tr_name_apocope(foreign, Adjs, singular, Noun, _, A) :-
    member(w(W, upper), Adjs), tr_name_out([o(W, upper)]),
    tr_solve(apocope_of(A, Noun)), !.
tr_name_apocope(_, _, _, _, F, F).
en_poss_pronoun(hers, his, his).     en_poss_pronoun(his, his, his).   en_poss_pronoun(mine, my, mine).
en_poss_pronoun(yours, your, yours). en_poss_pronoun(ours, our, ours). en_poss_pronoun(theirs, their, theirs).
tr_poss_after(foreign, Adjs0, Adjs) :-
    member(pre(w(P, _)), Adjs0), atom(P), en_poss_pronoun(P, _, _), !,
    findall(X, ( member(X0, Adjs0), ( X0 = pre(w(Q, QC)), atom(Q), en_poss_pronoun(Q, _, _) -> X = w(Q, QC) ; X = X0 ) ), Adjs).
tr_poss_after(_, Adjs, Adjs).
tr_day_number(app(np(det(article, the, _), none, [], w(day, _), singular), label, w(N, _)), N) :-
    atom(N), atom_number(N, V), integer(V), V >= 1, V =< 31.

en_order_adjective(A) :- memberchk(A, [last, first, next, past, previous, final]).

%% A DEGREE IS THE LAST OF THE ADJECTIVES IN THE LESSON'S LANGUAGE: `un mejor
%% trato fiscal' is `un trattamento fiscale migliore', and in the source's
%% order it was `un trattamento migliore fiscale', the adjective that says what
%% kind of treatment it is cut off from its noun. English keeps its order,
%% and a list with a coordinator in it keeps the source's: `a better and a
%% fiscal one' is no sentence of this
tr_degree_last(foreign, Adjs0, Adjs) :-
    Adjs0 = [_, _|_], \+ ( member(A, Adjs0), A = w(_, _), tr_side_here(Side), tr_coord(Side, A) ),
    partition(tr_degree_adj, Adjs0, Ds, Others), Ds \== [], Others \== [], !,
    append(Others, Ds, Adjs).
tr_degree_last(_, Adjs, Adjs).
tr_degree_adj(deg(_, _)).

%% A PLURAL MAY HAVE A GENDER OF ITS OWN, and the lesson says so: Italian's
%% `braccio' is masculine and its plural `braccia' feminine (`"braccia" is
%% feminine.'), as `dito', `uovo' and `lenzuolo' are. `sus brazos izquierdos'
%% came out `i suoi braccia sinistri', the determiner and the adjective
%% agreeing with the singular; the phrase's own words take the plural's
%% gender now, `le sue braccia sinistre'. (What the phrase answers its
%% caller is still the noun, which the rest of a sentence asks for more
%% than its gender.)
tr_plural_gender(foreign, Noun, plural, Form, elided(feminine)) :-
    atom(Noun), atom(Form), Form \== Noun, tr_solve(feminine(Form)), \+ tr_holds(feminine(Noun)), !.
tr_plural_gender(_, Noun, _, _, Noun).

%% A NOUN THE LESSON STATES IN BOTH GENDERS TAKES THE GENDER OF THE MEANING
%% WRITTEN: the writer's side of tr_gendered_noun/4. `el capital' is the money
%% and `la capital' the city, the vocabulary says `The masculine noun "capitale"
%% means "capital funds".' and `The feminine noun "capitale" means "capital".',
%% and the lesson keeps which goes with which (mean_gender/3, tr_gender_links/3)
%% -- but tr_gender/2 took the feminine whatever the phrase said, `il 4,03%
%% della capitale dell'istituzione'. The meaning linked to a gender has it, and
%% one linked to none has the other gender; a noun with no link, nearly every
%% noun, is asked nothing more than this one question
tr_meaning_gender(foreign, Noun, NW, _, elided(G)) :-
    atom(Noun), tr_solve(mean_gender(Noun, _, _)),
    (   tr_solve(mean_gender(Noun, NW, G0)) -> G = G0
    ;   tr_solve(mean_gender(Noun, _, G1)), tr_other_gender(G1, G)
    ), !.
tr_meaning_gender(_, _, _, GNoun, GNoun).
%% ... AND A WOMAN NAMED BY A NOUN WITH NO GENDER OF ITS OWN IS FEMININE: the writer's side of the note
%% tr_fem_person_note/4 makes, where the language's word for her has no feminine form to take (`una cantante')
tr_fem_person_gender(foreign, NW, Number, Noun, _, elided(feminine)) :-
    atom(NW), atom(Noun), nb_getval('$tr_fem_persons', Fs), Fs \== [], memberchk(NW-Number, Fs),
    tr_stated_gender(Noun, none), tr_holds(person(Noun)), !.
tr_fem_person_gender(_, _, _, _, G, G).

tr_date_join_out(Sep) :- ( tr_solve(join(J, date)) -> Sep = [o(J, lower)] ; Sep = [] ).
tr_with_article(np(_, Num, As, N, Nb), np(det(article, the, w(the, lower)), Num, As, N, Nb)).

%% A QUOTATION THAT OPENS OR CLOSES ON A PHRASE OPENS OR CLOSES ON ITS EDGE,
%% whatever order the language puts its words in: `sus objetivos
%% electorales"' closed on the adjective, English puts the adjective first,
%% and the mark came out `his electoral" aims'. A mark on one word alone
%% (qboth) stays where it is.
%% ... BUT A QUOTATION WITH BOTH ITS MARKS IN THE PHRASE IS A RUN OF ITS OWN:
%% `il "reddito minimo" francese' quotes the income and not the adjective
%% after the mark, and with the closing mark moved to the edge it came out
%% `"ingreso mínimo francés"'. The marks stay on their words where the written
%% order keeps the open before the close, and change places where it turns
%% them round (`French "minimum income"')
tr_edge_marks(Cs0, Cs) :-
    Cs0 = [_, _|_], \+ memberchk(o(_, qboth), Cs0),
    memberchk(o(_, qopen), Cs0), memberchk(o(_, qclose), Cs0), !,
    (   append(_, [o(_, qopen)|After], Cs0), memberchk(o(_, qclose), After)
    ->  Cs = Cs0
    ;   append(Pre, [o(W2, qclose)|Mid0], Cs0), append(Mid, [o(W3, qopen)|Post], Mid0)
    ->  append([Pre, [o(W2, qopen)|Mid], [o(W3, qclose)|Post]], Cs)
    ;   Cs = Cs0
    ).
tr_edge_marks(Cs0, Cs) :-
    Cs0 = [_, _|_], \+ memberchk(o(_, qboth), Cs0),
    ( memberchk(o(_, qopen), Cs0) -> Open = yes ; Open = no ),
    ( memberchk(o(_, qclose), Cs0) -> Close = yes ; Close = no ),
    ( Open == yes ; Close == yes ), !,
    findall(o(W, C), ( member(o(W, C0), Cs0), ( memberchk(C0, [qopen, qclose]) -> C = lower ; C = C0 ) ), [o(F, FC0)|Rest0]),
    ( Open == yes -> FC = qopen ; FC = FC0 ),
    append(Mid, [o(L, LC0)], Rest0),
    ( Close == yes -> LC = qclose ; LC = LC0 ),
    append([o(F, FC)|Mid], [o(L, LC)], Cs).
tr_edge_marks(Cs, Cs).

%% a phrase's count out: a number, an adverb and a number, two joined
tr_num_out(_, none, []) :- !.
%% an ordinal: English writes its own suffix, `the 50th anniversary', and
%% the lesson's language the sign after the digits, `il 50º anniversario'
tr_num_out(english, w(MW, MC), [o(MT, MC)]) :- tr_ordinal(MW, N), !, en_ordinal(N, MT).
tr_num_out(foreign, w(MW, MC), [o(MT, MC)]) :- tr_ordinal(MW, N), \+ atom_concat(_, 'º', MW), \+ atom_concat(_, 'ª', MW), !,
    atom_concat(N, 'º', MT).
tr_num_out(To, w(MW, MC), [o(MT, MC)]) :- tr_number_style(To, MW, MT), !.
tr_num_out(To, w(MW, MC), [o(MT, MC)]) :- !, tr_word_across(w(MW, MC), To, number, MT).
%% (English says a hundred and a thousand with their article: `unos cien pasajeros' are about a hundred, where
%% `About hundred passengers' was written)
tr_num_out(english, adv_num(w(A, C), w(N, NC)), [o(A, C), o(a, lower), o(N, NC)]) :- memberchk(N, [hundred, thousand, million]), !.
tr_num_out(To, adv_num(w(A, C), M), [o(AT, C)|MO]) :- !, tr_word_across(w(A, lower), To, adverb, AT), tr_num_out(To, M, MO).
tr_num_out(To, nums(M1, C, M2), Outs) :-
    tr_num_out(To, M1, O1), tr_connector_out(To, C, CO), tr_num_out(To, M2, O2), append([O1, CO, O2], Outs).
tr_num_out(To, numw(M1, M2), Outs) :- tr_num_out(To, M1, O1), tr_num_out(To, M2, O2), append(O1, O2, Outs).

%% A NUMBER IS WRITTEN IN THE TARGET'S STYLE WHERE ENGLISH MEETS A LANGUAGE
%% THAT WRITES THE COMMA: Spanish and Italian group the thousands with a point
%% and put the decimals after a comma (`5.000 millones', `3,5 millones'),
%% English does the reverse (`5,000 million', `3.5 million'), and the digits
%% crossed as they stood -- `5.000 and 6.000 millions' in English, `1,200' in
%% Spanish. The reader notes the style of the text it read ($tr_numsrc,
%% tr_number_source/1) and the writer swaps the two marks of a NUMBER and of
%% nothing else: a first group of one to three digits, groups of three after
%% it, one decimal mark, a percent sign perhaps. `10.30', an hour, and `2.5'
%% read as Spanish are no numbers and stay. Between two languages of the one
%% style, and for a language this table does not list, nothing changes.
tr_decimal_comma(L) :-
    memberchk(L, [spanish, italian, french, german, portuguese, catalan, galician, basque, dutch, romanian,
                  danish, swedish, norwegian, finnish, polish, czech, russian, turkish, greek]).
tr_number_source(Side) :-
    (   Side == english -> St = point
    ;   tr_language(L), tr_decimal_comma(L) -> St = comma
    ;   St = none
    ),
    nb_setval('$tr_numsrc', St).
tr_number_style(To, W0, W) :-
    atom(W0), tr_global('$tr_numsrc', Src), Src \== none,
    (   To == english -> Tgt = point
    ;   tr_language(L), tr_decimal_comma(L) -> Tgt = comma
    ;   Tgt = none
    ),
    Tgt \== none, Tgt \== Src,
    atom_codes(W0, Cs0), Cs0 = [D|_], tr_digit_code(D),
    tr_nstyle_marks(Src, G, DM),
    tr_nstyle_digits(Cs0, Ds, R1), Ds \== [],
    (   R1 = [G|_] -> length(Ds, N), N =< 3, tr_nstyle_groups(G, R1, Gs, R2) ; Gs = [], R2 = R1 ),
    (   R2 = [DM|R3], tr_nstyle_digits(R3, Fd, R4), Fd \== [] -> Fs = [DM|Fd] ; Fs = [], R4 = R2 ),
    ( R4 == [] -> Tail = [] ; R4 == [0'%] -> Tail = R4 ),
    Gs-Fs \== []-[],
    tr_nstyle_swap(Gs, Gs1), tr_nstyle_swap(Fs, Fs1),
    append([Ds, Gs1, Fs1, Tail], Cs), atom_codes(W, Cs).
tr_nstyle_marks(comma, 0'., 0',).
tr_nstyle_marks(point, 0',, 0'.).
tr_nstyle_digits([C|Cs], [C|Ds], R) :- tr_digit_code(C), !, tr_nstyle_digits(Cs, Ds, R).
tr_nstyle_digits(R, [], R).
tr_nstyle_groups(G, [G, A, B, C|Cs], [G, A, B, C|Gs], R) :-
    tr_digit_code(A), tr_digit_code(B), tr_digit_code(C), \+ ( Cs = [E|_], tr_digit_code(E) ), !,
    tr_nstyle_groups(G, Cs, Gs, R).
tr_nstyle_groups(G, [G|_], _, _) :- !, fail.
tr_nstyle_groups(_, R, [], R).
tr_nstyle_swap([], []).
tr_nstyle_swap([C|Cs], [S|Ss]) :- ( C =:= 0'. -> S = 0', ; C =:= 0', -> S = 0'. ; S = C ), tr_nstyle_swap(Cs, Ss).
%% a percentage that is the phrase's own noun (`el 3,5%') is a number as well
tr_percent_style(To, F0, F) :- atom(F0), atom_concat(_, '%', F0), tr_number_style(To, F0, F), !.
%% ... and so is a number that is the phrase's head, its noun left out: `8.737 chili
%% di nichel, 7.496 di cromo' is 8,737 kilos of nickel and 7,496 of chromium, where
%% the second stayed `7.496'
tr_percent_style(To, F0, F) :- atom(F0), atom_codes(F0, [D|_]), tr_digit_code(D), tr_number_style(To, F0, F), !.
tr_percent_style(_, F, F).
%% A MAGNITUDE AFTER A COUNT IS SINGULAR IN ENGLISH: `5.000 millones' is `5,000
%% million' and `tres docenas' three dozen, where it is plural alone --
%% `millions sleep' -- and with no count (`miles de personas')
tr_counted_form(english, Num, Noun, _, Noun) :- Num \== none, en_magnitude(Noun), !.
tr_counted_form(_, _, _, F, F).
en_magnitude(M) :- memberchk(M, [million, billion, trillion, thousand, hundred, dozen]).
tr_counted_magnitude(np(_, Num, _, w(M, _), _)) :- Num \== none, en_magnitude(M).
tr_counted_comp(obj(NP)) :- tr_counted_magnitude(NP).
tr_counted_comp(pp(_, NP)) :- tr_counted_magnitude(NP).
%% A COUNTED MAGNITUDE TAKES ITS NOUN WITH NO `of' IN ENGLISH: `tres millones de
%% perros' is three million dogs, the `de' the noun's own in the lesson's
%% language -- and with an article after it `of' stays, `three million of the
%% dogs' (tr_counted_form/5 makes the magnitude singular). The phrase after
%% the `of' is written as it is, bare(NP), after the magnitude's
tr_of_dropped(english, NP, [pp(w(of, _), NP2)|PPs], [bare(NP2)|PPs]) :-
    tr_counted_magnitude(NP), NP2 = np(none, _, _, _, _), !.
tr_of_dropped(_, _, PPs, PPs).
%% the adverbs that say how much of a phrase, written before it
en_object_adverb(A) :-
    memberchk(A, ['more than', 'less than', 'at least', 'at most', about, almost, nearly, approximately, around, roughly, exactly, only, even, just,
                  'not even']).   % `neanche uno strapuntino libero', not even a free folding seat

%% English's ordinal suffix: `st', `nd', `rd' after 1, 2 and 3, and `th'
%% after everything else, 11, 12 and 13 included
en_ordinal(N, W) :-
    atom_number(N, V), T is V mod 100, U is V mod 10,
    (   T >= 11, T =< 13 -> S = th
    ;   U =:= 1 -> S = st ; U =:= 2 -> S = nd ; U =:= 3 -> S = rd ; S = th
    ),
    atom_concat(N, S, W).

tr_lexeme_here(W, L) :- tr_side_here(Side), tr_lexeme(Side, W, L, _), !.

%% the phrase's noun as a lexeme, and its noun on the other side: the
%% reading of the word that is a noun in the phrase's number, with a
%% meaning the lesson calls a noun -- `houses' is a verb's form too (to
%% house, `aloja'), and a word known as one is known as itself first
tr_noun_lexeme(To, NW, Number, L, Noun) :-
    tr_noun_lexeme0(To, NW, Number, L, Noun0),
    tr_time_pick(To, L, Noun0, Noun).
%% a bare time takes the lesson's word for a time where it has one
tr_time_pick(foreign, L, Noun0, Noun) :-
    tr_global('$tr_time_noun', yes), \+ tr_time_lexeme(foreign, Noun0),
    tr_meanings_of(L, foreign, noun, Ms), member(Noun, Ms), tr_time_lexeme(foreign, Noun), tr_class_of(Noun, noun), !.
tr_time_pick(_, _, Noun, Noun).
tr_noun_lexeme0(foreign, NW, Number, L, Noun) :-
    atom(NW), nb_getval('$tr_fem_persons', Fs), Fs \== [], memberchk(NW-Number, Fs),
    tr_lexeme_here(NW, L), tr_meanings_of(L, foreign, noun, Ms),
    member(Noun, Ms), tr_stated_gender(Noun, feminine), tr_holds(person(Noun)), !.
tr_noun_lexeme0(To, NW, Number, L, Noun) :-
    tr_side_here(Side),
    (   tr_lexeme(Side, NW, L0, Number), tr_meanings_of(L0, To, noun, [N0|_]), ( To == foreign -> tr_class_of(N0, noun) ; true )
    ->  L = L0, Noun = N0
    ;   tr_lexeme_here(NW, L), tr_meanings_of(L, To, noun, Ms),
        %% a partitive's head takes the gender tr_with_partitive/2 set
        (   tr_global('$tr_partitive', G), G \== none, member(Noun, Ms), tr_gender(Noun, G) -> true
        ;   Ms = [Noun|_]
        )
    ).

%% A PARTITIVE'S HEAD AGREES WITH THE NOUN OF ITS `of' PHRASE: `algunas de
%% las diferencias' is `alcune delle differenze', where the head has no noun
%% of its own to agree with and the lesson's first word for `some' was the
%% masculine -- `alcuni delle differenze'. The head is a phrase with nothing
%% but its word; the gender is the one the target gives the other noun.
%% -- of a word that says a part or a number of it, never of a noun that has its
%% own gender to choose: `autori di diverse espressioni' are authors, and took
%% the feminine of the expressions, `autoras'
tr_partitive_gender(np(none, none, [], w(W, _), _), pp(w(of, _), NP2), G) :-
    tr_partitive_word(W),
    tr_np_head(NP2, np(_, _, _, w(NW2, _), N2)),
    tr_noun_lexeme(foreign, NW2, N2, _, Noun2), tr_gender(Noun2, G), G \== none, !.
tr_ell_gender(pp(w(of, _), NP2), G) :-
    tr_np_head(NP2, np(_, _, _, w(NW2, _), N2)), atom(NW2),
    tr_noun_lexeme(foreign, NW2, N2, _, Noun2), tr_gender(Noun2, G), G \== none.
tr_partitive_word(W) :-
    memberchk(W, [some, one, someone, somebody, anyone, anybody, everyone, everybody, none, nobody, each, any,
                  many, much, few, several, half, part, majority, minority, rest, most, both, all, others, other, another]).

%% the phrase at the head of what hangs on it: `las diferencias que
%% distinguen ...' is a relative clause on the differences
tr_np_head(np(D, M, A, N, Nb), np(D, M, A, N, Nb)) :- !.
tr_np_head(rc(NP, _, _), H) :- !, tr_np_head(NP, H).
tr_np_head(nrc(NP, _, _), H) :- !, tr_np_head(NP, H).
tr_np_head(what_np(NP), H) :- !, tr_np_head(NP, H).
tr_np_head(rel(NP, _, _), H) :- !, tr_np_head(NP, H).
tr_np_head(app(NP, _, _), H) :- !, tr_np_head(NP, H).
tr_np_head(ncl(NP, _), H) :- tr_np_head(NP, H).

tr_with_time_noun(Goal) :-
    tr_global('$tr_time_noun', T0), nb_setval('$tr_time_noun', yes),
    (   call(Goal) -> nb_setval('$tr_time_noun', T0)
    ;   nb_setval('$tr_time_noun', T0), fail
    ).
tr_with_partitive(G, Goal) :-
    tr_global('$tr_partitive', G0), nb_setval('$tr_partitive', G),
    (   call(Goal) -> nb_setval('$tr_partitive', G0)
    ;   nb_setval('$tr_partitive', G0), fail
    ).
%% AN INFINITIVE WITH ITS OWN OBJECT RIGHT AFTER IT CHOOSES ITS VERB AS A
%% CLAUSE WITH AN OBJECT DOES (tr_verb_out/4): `quiere lograr una tregua' wants
%% to attain a truce, `vuole ottenere una tregua', where `riuscire' is the verb
%% with no object and the infinitive had taken it
tr_infinitive_comp(inf(_)).
tr_infinitive_comp(ainf(_, _)).
tr_infinitive_comp(purpose(_)).
tr_infinitive_comp(npurpose(_)).
tr_infinitive_comp(purp(_)).
tr_with_inf_obj(Goal) :-
    tr_global('$tr_inf_obj', Y0), nb_setval('$tr_inf_obj', yes),
    (   call(Goal) -> nb_setval('$tr_inf_obj', Y0)
    ;   nb_setval('$tr_inf_obj', Y0), fail
    ).
tr_inf_lexeme(L, LT) :-
    (   tr_global('$tr_inf_obj', yes) -> tr_verb_out(foreign, L, [obj(none)], LT)
    %% ... AND ONE WITH NONE TAKES THE VERB OF NO OBJECT, where the lesson gives the meaning a transitive word of its
    %% own: `quisiera saber qué hacer' is `sapere cosa fare', as the clause `sabe qué hace' is `sa cosa fa' --
    %% `conoscere' knows a thing or a person, and the infinitive took it whatever followed
    ;   atom(L), tr_solve(transitive_sense(L, _)) -> tr_verb_out(foreign, L, [], LT)
    ;   tr_lexeme_across(L, foreign, LT)
    ).
tr_side_here(Side) :- ( catch(nb_getval('$tr_from', S0), _, fail) -> Side = S0 ; Side = english ).

%% each adjective as a(Lexeme, Out); an `and' among them as the conjunction
tr_adjectives_out(_, [], _, _, []).
tr_adjectives_out(To, [A|As], Noun, Number, [O|Os]) :-
    (   tr_side_here(Side), tr_coord(Side, A)
    ->  tr_connector_out(To, A, [O0]), O = c(O0)
    ;   tr_adjective_out(To, A, Noun, Number, O)
    ),
    tr_adjectives_out(To, As, Noun, Number, Os).

%% A NAME APPOSED TO A NOUN IS WRITTEN AS ITSELF, in every language, and it
%% agrees with nothing: `il presidente Scalfaro', `el presidente Scalfaro',
%% `the president Scalfaro'. It is the one word no lesson can know.
tr_adjective_out(_, w(W, upper), _, _, a(W, [o(W, upper)])) :-
    tr_side_here(Side), \+ tr_known_word(Side, W), !.
%% (a name the lesson's text kept as itself, tr_kept_name_note/2: after its
%% noun and its adjectives in the lesson's language, `la compañía
%% discográfica Paramount', where English puts it before, `the Paramount
%% company')
tr_adjective_out(foreign, w(W, upper), _, _, a(post, [o(W, upper)])) :-
    nb_getval('$tr_xnames', Xs), memberchk(kept(W), Xs), !.
%% (a NUMBER the source put after its noun as its label, in words: `i fondi ottantacinque' are the funds of '85, the
%% year said short, and the lesson has no adjective for the number, so the sentence was refused -- the lesson's own
%% number word after the noun, as the source has it)
tr_adjective_out(foreign, w(W, C), _, _, a(post, [o(T, C)])) :-
    atom(W), C \== upper, tr_is(english, w(W, lower), number), tr_word_across(w(W, lower), foreign, number, T), !.
tr_adjective_out(To, w(W, appos), _, _, a(W, [o(',', comma), o(N, upper), o(',', comma)])) :- !,
    ( To == foreign, tr_name_word_out(W, N0) -> N = N0 ; N = W ).
tr_adjective_out(english, ptc(PP), _, _, a(PP, [o(PP, lower)])) :- !.     % a bare participle, English's own word
%% a participle the source put before its noun (pptc/1), before it in every
%% language and agreeing with the noun as a reduced relative's does
tr_adjective_out(english, pptc(L), _, _, a(pre, [o(PP, lower)])) :- !,
    tr_lexeme_across(L, english, LT), en_participle_of(LT, PP).
tr_adjective_out(foreign, pptc(L), Noun, Number, a(pre, [o(PP, lower)])) :- !,
    tr_lexeme_across(L, foreign, LT),
    ( tr_gender(Noun, G0), G0 \== none -> G = G0 ; G = masculine ),
    tr_with_gender(G, tr_participle_agreeing(LT, Number, PP)).
tr_adjective_out(english, ptcd(DW, PP), _, _, a(PP, [o(DW, lower), o(PP, lower)])) :- !.   % ... and with its degree
%% an adjective marked to stand before its noun: `pre' is no adjective the
%% lesson has a rule for, so tr_sides/3 puts it before the noun
%% ... UNLESS THE LESSON SAYS IT NEVER STANDS THERE: `il suo diretto
%% superiore' is Spanish's `su jefe directo', where `un buon cane' is `un
%% buen perro' -- the source's adjective before its noun is its own, and a
%% lesson that has the adjective stand after (`The adjective "directo" does
%% not precede the noun.') writes it as it writes any adjective
tr_adjective_out(foreign, pre(w(W, C)), Noun, Number, a(L, [o(T, C)])) :-
    tr_adjective_form(foreign, W, Noun, Number, L, T), tr_solve(neg(precede(L, noun))), !.
%% an adjective that carries its own gender and number (tr_carry_agreement/4):
%% English has none to keep
tr_adjective_out(english, agrd(_, _, A), Noun, Number, R) :- !, tr_adjective_out(english, A, Noun, Number, R).
tr_adjective_out(foreign, agrd(G, N, w(W, C)), Noun, _, a(L, [o(T, C)])) :- !,
    ( G == none -> AgrNoun = Noun ; AgrNoun = elided(G) ),
    tr_adjective_form(foreign, W, AgrNoun, N, L, T).
%% (but one the lesson's language says in several words that open on a preposition stands after its noun:
%% `cinquantaduenne direttore scientifico' is `director científico de cincuenta y dos años', and before it
%% it was `de cincuenta y dos años director científico')
tr_adjective_out(foreign, pre(A), Noun, Number, a(postlast, Os0)) :-
    tr_adjective_out(foreign, A, Noun, Number, a(_, Os0)), Os0 = [o(Wd, _)], atom(Wd),
    atomic_list_concat([P, _|_], ' ', Wd), tr_is(foreign, w(P, lower), preposition), !.
tr_adjective_out(To, pre(A), Noun, Number, a(pre, Os)) :- !,
    tr_adjective_out(To, A, Noun, Number, a(_, Os0)), tr_apocope(To, Number, Os0, Os).
%% ... and a NOUN that says what kind the noun is (nmod/1): after the noun
%% in the phrase's number on the lesson's side, and before it in the
%% singular in English, as English's own compounds have it -- `los
%% muchachotes hinchas' is `i ragazzi appassionati' and `the fan lads'
tr_adjective_out(english, nmod(w(W, C)), _, _, a(pre, [o(W, C)])) :- !.
%% ... and the same in the plural, the name's tail with its `of' left out
%% (nmodp/1): `the national magistrate association', `la asociación nacional
%% magistrados'
tr_adjective_out(english, nmodp(w(W, C)), _, _, a(pre, [o(W, C)])) :- !.
tr_adjective_out(foreign, nmodp(w(W, C)), _, _, a(nmod, [o(T, C)])) :- !,
    tr_word_across(w(W, lower), foreign, noun, T0), tr_inflect(foreign, noun, T0, plural, T).
tr_adjective_out(foreign, nmod(w(W, C)), _, Number, a(nmod, [o(T, C)])) :- !,
    tr_word_across(w(W, lower), foreign, noun, T0), tr_inflect(foreign, noun, T0, Number, T).
%% an adverb that says when the noun holds (tr_noun_adverb/4), before the
%% noun in every language: `l'allora presidente', `the then president'
tr_adjective_out(To, advn(w(W, C)), _, _, a(pre, [o(T, C)])) :- !, tr_word_across(w(W, lower), To, adverb, T).
%% an adjective with its intensifier: the adverb first in every language,
%% the adjective agreeing as it would alone -- `così pacifica', `so peaceful'
%% ... and with `more than' before it (mti/1): `more than likely', `più
%% che probabile' -- the lesson's comparative word and its word for `than'
%% before an adjective
tr_adjective_out(To, mti(J), Noun, Number, a(L, [o(M, lower), o(T, lower)|JO])) :- !,
    ( To == english -> M = more, T = than ; tr_degree_out(M), tr_than_word(adjective, T) ),
    tr_adjective_out(To, J, Noun, Number, a(L, JO)).
tr_adjective_out(To, int(w(A, AC), J), Noun, Number, a(L, [o(AT, AC)|JO])) :- !,
    tr_word_across(w(A, lower), To, adverb, AT), tr_adjective_out(To, J, Noun, Number, a(L, JO)).
tr_adjective_out(To, w(W, C), Noun, Number, a(L, [o(T1, C)])) :-
    tr_adjective_form(To, W, Noun, Number, L, T),
    %% (an English nationality or creed with its capital: `la india Yukta Mookhey' is
    %% the Indian, `los socialistas vascos' the Basque socialists -- spelled with it, so
    %% that a mark which closes on the word stays: `grupos de compra españoles"'). A word that came
    %% with its capital keeps the case and its small letters: the order asks (tr_name_out/1) whether
    %% the lesson knows a capitalised word, and `Olympic' is none (`los Juegos Olímpicos')
    ( To == english, C \== upper, en_nationality(T) -> tr_cap(T, T1)
    %% (and `close', the lesson's `vicino', is `nearby' with no degree: `la vicina zona industriale di
    %% Porto Marghera' is the nearby industrial zone, and `close' before a noun is intimate)
    ; To == english, T == close -> T1 = nearby
    ; T1 = T ).
%% a degree: English's own ending, or the word the lesson puts in front
%% -- and where the lesson has a word that is the comparative by itself,
%% that word: `il migliore degli interpreti', never `il più buono'
%% ... and with its term of comparison, after the noun in every language:
%% `these hordes more Viking than British', `queste orde più vichinghe che
%% britanniche' -- the lesson's word for `than' before an adjective
%% ... AN ADJECTIVE AND THE PHRASE IT TAKES (postadj/2, tr_comps_out/7): after the
%% noun, as one word
tr_adjective_out(english, postadj(A, PP), Noun, Number, a(post, Outs)) :- !,
    tr_adjective_out(english, A, Noun, Number, a(_, AO)),
    tr_comp_out(english, PP, none, Number, _, PO, _), append(AO, PO, Outs).
tr_adjective_out(To, degt(D, A, As), Noun, Number, a(post, Outs)) :- !,
    tr_adjective_out(To, deg(D, A), Noun, Number, a(_, O1)),
    ( To == english -> T = than ; tr_than_word(adjective, T) ),
    tr_adjectives_out(To, As, Noun, Number, AOs), tr_adj_words(AOs, O2),
    append(O1, [o(T, lower)|O2], Outs).
%% ... AND `BIG' AND `SMALL' SAID OF A BROTHER, A SISTER, A SON OR A DAUGHTER
%% ARE ENGLISH'S `OLDER' AND `YOUNGER': `mia sorella più grande' is my older
%% sister and `il fratello più piccolo' the younger brother -- the lesson's
%% languages say who was born first by the word for big, and English wrote
%% `my biggest sister'
tr_adjective_out(english, deg(_, w(W, C)), Noun, _, a(W, Outs)) :-
    memberchk(W, [big, small, little]), atom(Noun), en_kin_noun(Noun), !,
    ( W == big -> B = old ; B = young ),
    en_degree_out(comparative, B, C, Outs).
tr_adjective_out(To, deg(D, w(W, C)), Noun, Number, a(L, Outs)) :-
    tr_adjective_form(To, W, Noun, Number, L, T),
    (   To == english -> en_degree_out(D, T, C, Outs)
    ;   D = less(_) -> tr_less_out(M), Outs = [o(M, lower), o(T, C)]
    ;   tr_synthetic_comparative(W, CW) -> tr_inflect(To, adjective, CW, Number, CT), Outs = [o(CT, C)]
    ;   tr_degree_out(M), Outs = [o(M, lower), o(T, C)]
    ).

%% AN ADJECTIVE BEFORE A SINGULAR NOUN MAY LOSE ITS ENDING: `dal primo
%% momento' is `desde el PRIMER momento' and `ogni grande organizzazione'
%% `cada GRAN organización' -- written `el primero momento', `cada grande
%% organización', which no Spanish page prints. The lesson states the short
%% form (`"primer" is the apocope of "primero".'), and only of the form that
%% loses it: `primera' states none, so a feminine noun keeps the whole word.
tr_apocope(foreign, singular, [o(T, C)], [o(A, C)]) :- tr_solve(apocope_of(A, T)), !.
tr_apocope(_, _, Os, Os).
en_kin_noun(N) :- memberchk(N, [sister, brother, son, daughter, child, sisters, brothers, sons, daughters, children]).

%% the lesson's comparative of an adjective that means W, whichever of its
%% forms the phrase chose: `buona' agrees with `la', and `migliore' is stated
%% of `buono'
tr_synthetic_comparative(W, CW) :- tr_solve(comparative_of(CW, B)), tr_solve(mean(B, W)), !.

tr_adjective_form(To, W, Noun, Number, L, T) :-
    tr_lexeme_here(W, WL),
    tr_meanings_of(WL, To, adjective, Ms),
    tr_agree_adjective(To, Ms, Noun, L),
    tr_adjective_plural(To, L, Noun, Number, T).

%% ONE SINGULAR FOR BOTH GENDERS AND A PLURAL FOR EACH: `ottimista' is
%% `ottimisti' and `ottimiste', and the lesson says which plural is feminine
%% (`"ottimiste" is feminine.'). A feminine noun takes that one and any other
%% the first plural not said to be: `le previsioni ... non sono ottimiste',
%% where the first plural stated came out whatever the noun. Asked only of a
%% word of no gender, because the plurals are found by a walk over them all
%% (1.8 ms on the full store) where the first costs microseconds.
tr_adjective_plural(foreign, L, Noun, plural, T) :-
    tr_gender(L, none),
    findall(P, tr_solve(plural_of(P, L)), Ps0), sort(Ps0, Ps), Ps = [_, _|_],
    (   tr_noun_gender(Noun, G0), G0 \== none -> G = G0
    ;   Noun == none -> tr_subject_gender(G)
    ;   G = masculine
    ),
    (   G == feminine, member(T, Ps0), tr_solve(feminine(T)) -> true
    ;   member(T, Ps0), \+ tr_solve(feminine(T)) -> true
    ), !.
tr_adjective_plural(To, L, _, Number, T) :- tr_inflect(To, adjective, L, Number, T).

%% AN ADJECTIVE THAT AGREES IS TAKEN IN THE LESSON'S ORDER, one of no gender
%% among them -- the rule the determiners follow (tr_det_form/6). A word's
%% gender is what the lesson says of the WORD, whatever its class, and
%% `corrente' is a feminine NOUN: asked for a feminine adjective meaning
%% common first, `la seguridad común' came out `la sicurezza corrente', where
%% the lesson's first word, `comune', has no gender and agrees with anything.
%% -- AND AN ADJECTIVE'S GENDER IS THE ONE THE LESSON STATES OF THE WORD,
%% never one a rule about nouns proves: `The noun "comune" means "town
%% council".', for `un ayuntamiento socio', made `comune' a noun, and
%% `Every noun that does not end in "a" is masculine.' then made the
%% adjective masculine too -- the Solana report's `seguridad común' came out
%% `sicurezza corrente' again. No lesson has a rule about an adjective's
%% gender; its gender is stated or it has none.
tr_agree_adjective(english, [M|_], _, M) :- !.
tr_agree_adjective(foreign, Ms, Noun, T) :-
    tr_noun_gender(Noun, G), G \== none,
    member(T, Ms), tr_stated_gender(T, G1), ( G1 == G ; G1 == none ; tr_stated_both(T) ), !.
%% ... AND ONE SAID OF A SUBJECT WITH NO NOUN AGREES WITH THE SUBJECT'S
%% GENDER, as a participle does (tr_participle_agreeing/3): `Ella es alta',
%% and `el telefonino ... estaba vacío, era de pega', the second clause's
%% subject nobody, where the first meaning the lesson gave was taken and it
%% came out `era finta'
tr_agree_adjective(foreign, Ms, none, T) :-
    tr_subject_gender(G), member(T, Ms), tr_stated_gender(T, G1), ( G1 == G ; G1 == none ), !.
tr_agree_adjective(foreign, Ms, Noun, T) :- tr_agree(foreign, Ms, Noun, T).
%% (a word the lesson states in both genders agrees with either: `militare' is the noun for a
%% soldier, `il militare' and `la militare', and as the adjective it was masculine to the
%% writer, `la campagna bellica' and `la leadership bellica' where it is `militare')
tr_stated_both(T) :- tr_fact(feminine(T)), tr_fact(masculine(T)), !.

%% English puts an adjective before its noun; the lesson's language does what
%% its rule says of each adjective, follow(A, noun), and English's order otherwise
%% (and in the order en_adj_order/3 gave them)
tr_order(english, Noun, Adjs0, Outs) :-
    tr_names_last(Adjs0, Adjs, Names),
    tr_adj_words(Adjs, Os), tr_adj_words(Names, Ns), append(Os, [Noun|Ns], Outs).
tr_order(foreign, Noun, Adjs, Outs) :-
    tr_sides(Adjs, Before, After),
    append(Before, [Noun|After], Outs).

%% THE ADJECTIVES THE SOURCE PUT AFTER ITS NOUN, NEAREST FIRST, ARE NEAREST IT IN
%% ENGLISH TOO, so English writes them the other way round: `la patronal bancaria
%% española' is the Spanish banking employers, and `el acuerdo laboral colectivo' the
%% collective labour agreement -- in the source's order they were `the banking Spanish
%% employers'. Of each adjective of the phrase (Irs) and what it was written as
%% (Adjs0): a degree and one the source put before its noun come first, as they
%% stood (`un mejor trato fiscal' is a better fiscal treatment, `sus mejores noches
%% liceísticas' his best liceistic nights, `un nuevo acuerdo laboral colectivo' a
%% new collective labour agreement -- reversed with the rest, the controls found `a
%% fiscal better treatment'); a list with anything else in it -- a name, a
%% coordinator, a quoted word, a noun that says what kind (`l'associazione nazionale
%% magistrati' is the national magistrate association, and reversed it was `the
%% magistrate national association'), an adjective that keeps a number of its own
%% and says it of another word (agrd/3: `la asociación nacional magistrados') --
%% keeps the source's order
%% (and a name the source apposed to the noun among them stays after them, where English writes it
%% after the noun: `El jefe guerrillero checheno Chamil Basayev' is the Chechen guerrilla chief, and
%% with the name in the list the source's order stood, `the guerrilla Chechen boss Chamil Basayev')
%% (and a superlative joined to an adjective after it is one degree, before the plain adjectives the source put before
%% it: `le situazioni culturali più variegate e vivaci' are the most varied and lively cultural situations, and with a
%% coordinator in the list the source's order stood, `the cultural most varied and lively situations')
en_adj_order(Irs, Adjs0, Adjs) :-
    append(IPre, [deg(superlative, _), w(and, lower), w(J, lower)], Irs), atom(J), IPre = [_|_],
    forall(member(I, IPre), I = w(_, lower)),
    length(IPre, N), length(OPre, N), append(OPre, OTail, Adjs0), forall(member(O, OPre), O = a(_, _)), !,
    reverse(OPre, RPre), append(OTail, RPre, Adjs).
en_adj_order(Irs, Adjs0, Adjs) :-
    en_adj_classes(Irs, Adjs0, Pres, Plains, Names), !,
    reverse(Plains, Rev), append([Pres, Rev, Names], Adjs).
en_adj_order(_, Adjs, Adjs).
en_adj_classes([], [], [], [], []).
en_adj_classes([I|Is], [O|Os], Pres, Plains, Names) :-
    O = a(_, _), ( I = w(W, upper), atom(W), Os == [] -> K = name ; en_adj_class(I, K) ),
    en_adj_classes(Is, Os, Pres0, Plains0, Names0),
    (   K == pre -> Pres = [O|Pres0], Plains = Plains0, Names = Names0
    ;   K == name -> Pres = Pres0, Plains = Plains0, Names = [O|Names0]
    ;   Pres = Pres0, Plains = [O|Plains0], Names = Names0
    ).
en_adj_class(w(W, lower), plain) :- atom(W).
en_adj_class(ptc(_), plain).
en_adj_class(int(_, _), plain).
en_adj_class(mti(_), plain).
en_adj_class(deg(_, _), pre).
en_adj_class(pre(_), pre).
en_adj_class(pptc(_), pre).
en_adj_class(advn(_), pre).
%% ... AND THE LESSON'S LANGUAGE WRITES THE ADJECTIVES ENGLISH PUT BEFORE ITS NOUN
%% THE OTHER WAY ROUND, the one nearest the noun nearest it in both: `the big red
%% house' is `la casa roja grande', where it was `la casa grande roja', which read
%% back into English is `the red big house' (en_adj_order/3). From an English
%% source and a list of plain adjectives only -- the side the text was READ on
%% (`$tr_read_side', set by tr_into_ir/4): every writer runs with `$tr_from' set
%% to english, and asked of it the first cut turned Spanish into Italian too, `la
%% televisione catalana pubblica' -- tr_sides/3 then puts each where the lesson
%% says
tr_foreign_adj_order(Irs, Adjs0, Adjs) :-
    nb_getval('$tr_read_side', english), Irs = [_, _|_], forall(member(I, Irs), en_adj_class(I, plain)),
    forall(member(O, Adjs0), O = a(_, _)), !,
    reverse(Adjs0, Adjs).
tr_foreign_adj_order(_, Adjs, Adjs).
%% A NAME APPOSED TO A NOUN FOLLOWS IT IN EVERY LANGUAGE -- `il presidente
%% Scalfaro', `the president Scalfaro' -- and the adjective rules do not
%% place it: measured, `del Scalfaro presidente' and `Il Chevènement
%% ministro' before this. In English it goes after the noun; in the
%% lesson's language it keeps its place among the adjectives that follow the
%% noun (tr_sides/3), because the source put it there: `il magnate televisivo
%% Silvio Berlusconi' has the adjective first and `il governo Dini
%% successivo' the name, and written with the names last the second came out
%% `el gobierno sucesivo Dini'
tr_names_last([], [], []).
tr_names_last([a(W, Os)|As], Adjs, [a(W, Os)|Ns]) :- tr_name_out(Os), !, tr_names_last(As, Adjs, Ns).
tr_names_last([a(post, Os)|As], Adjs, [a(post, Os)|Ns]) :- !, tr_names_last(As, Adjs, Ns).   % `more Viking than British'
%% ... AND SO IS `AND A HALF': `un minuto e mezzo' is a minute and a half, and
%% before the noun it was `an and a half minute'
tr_names_last([a(W, Os)|As], Adjs, [a(W, Os)|Ns]) :-
    Os = [o(Wd, _)|_], atom(Wd), atom_concat('and ', _, Wd), !, tr_names_last(As, Adjs, Ns).
%% ... AND AN ADJECTIVE OF SEVERAL WORDS THAT OPENS ON A PREPOSITION: `le isole in questione' are the
%% islands in question, and before the noun it was `the in question islands'
tr_names_last([a(W, Os)|As], Adjs, [a(W, Os)|Ns]) :-
    Os = [o(Wd, _)|_], atom(Wd), atomic_list_concat([P, _|_], ' ', Wd), en_preposition(P), !, tr_names_last(As, Adjs, Ns).
%% ... AND AN ADJECTIVE THE WORD FOR `also' OR `even' IS SAID OF: `per una serie di ragioni anche generazionali' is for a
%% series of reasons also generational, and before the noun it was `also generational reasons'
tr_names_last([a(W, Os)|As], Adjs, [a(W, Os)|Ns]) :-
    Os = [o(F, _), _|_], memberchk(F, [also, even]), !, tr_names_last(As, Adjs, Ns).
tr_names_last([A|As], [A|Adjs], Ns) :- tr_names_last(As, Adjs, Ns).
tr_name_out([o(',', comma)|_]) :- !.
tr_name_out([o(W, upper)]) :- tr_side_here(Side), \+ tr_known_word(Side, W).

tr_adj_words([], []).
tr_adj_words([a(_, Os0)|As], Os) :- tr_adj_words(As, Os1), append(Os0, Os1, Os).
tr_adj_words([c(O)|As], [O|Os]) :- tr_adj_words(As, Os).

tr_sides([], [], []).
tr_sides([c(O)|As], Before, After) :- !,
    tr_sides(As, Before1, After1),
    ( After1 == [] -> Before = [O|Before1], After = After1 ; Before = Before1, After = [O|After1] ).
%% (one the lesson says in several words that open on a preposition goes after the other adjectives:
%% `director científico de cincuenta y dos años', tr_adjective_out/5)
tr_sides([a(postlast, Os)|As], Before, After) :- !,
    tr_sides(As, Before, After1), append(After1, Os, After).
tr_sides([a(L, Os)|As], Before, After) :-
    tr_sides(As, Before1, After1),
    (   ( L == nmod ; L == post ; tr_name_out(Os) ; tr_holds(follow(L, noun)) ) -> Before = Before1, append(Os, After1, After)
    ;   append(Os, Before1, Before), After = After1
    ).

%% the determiner out: English's `the' either way, `a' in the singular --
%% `an' before a vowel -- and nothing in the plural, a possessive as it is;
%% the lesson's by the gender and the number of the noun
tr_det_out(_, none, _, _, _, []) :- !.
%% (a denied clause's `more' in its subject: tr_write/4)
tr_det_out(english, det(determiner, 'no more', w(_, C)), _, _, _, [o(no, C), o(more, lower)]) :- !.
tr_det_out(english, det(Kind, DL, w(_, C)), _, Number, Content, Outs) :- !,
    tr_word_across(w(DL, lower), english, Kind, T),
    (   Kind == possessive -> Outs = [o(T, C)]
    %% (`another' before a count stays `another' in the plural: `altri 70 mila' are another 70
    %% thousand, and English wrote `Other 70 thousand' -- and `other' before one is `another' too: `Otros 20
    %% operarios' are another 20 workers)
    ;   memberchk(T, [another, other]), Content = [o(First, _)|_], en_count_first(First) -> Outs = [o(another, C)]
    %% (`some' and `no' in a denied clause are `any': `non subirà alcun calo' will not undergo ANY
    %% decline, `non mangia nessun pane' does not eat any bread -- English has one denial to a clause)
    ;   Kind == determiner, Number == singular, memberchk(T, [some, no]), tr_global('$tr_denied', yes) -> Outs = [o(any, C)]
    ;   memberchk(Kind, [demonstrative, determiner]) -> en_det_number(T, Number, T1), Outs = [o(T1, C)]
    %% (no article before a percentage: `el 80%' is `80%', `the 80%' is no English)
    ;   T == the, Content = [o(First, _)|_], atom(First), atom_concat(_, '%', First) -> Outs = []
    %% (... and before one in words: `pari all''87 per cento del totale'' is equal to 87 per cent of it)
    ;   T == the, Content = [_, o(PC, _)|_], memberchk(PC, ['per cent', percent]) -> Outs = []
    ;   T == the -> Outs = [o(the, C)]
    ;   Number == plural -> Outs = []
    ;   Content = [o(First, _)|_], tr_starts_vowel(english, First) -> Outs = [o(an, C)]
    ;   Outs = [o(a, C)]
    ).
%% `SOME' IN A DENIED CLAUSE IS THE WORD FOR `NO': `non subirà alcun calo' is `no experimentará
%% ningún descenso', and Spanish wrote `algún', which a denial does not take after its verb
tr_det_out(foreign, det(determiner, some, W), Noun, singular, Content, Outs) :-
    tr_global('$tr_denied', yes), !,
    tr_det_out(foreign, det(determiner, no, W), Noun, singular, Content, Outs).
%% A POSSESSIVE TAKES THE ARTICLE IN FRONT OF IT where the lesson says so
%% (`The article "il" takes the possessive.'): Italian's `i suoi figli', and
%% `de sus hijos' is `dei suoi figli' once the contraction is made
tr_det_out(foreign, det(possessive, DL, W), Noun, Number, Content, Outs) :-
    once(( tr_solve(take(A, possessive)), tr_class_of(A, article) )), !,
    tr_det_form(possessive, DL, Noun, Number, Content, PT), W = w(_, C),
    tr_det_out(foreign, det(article, the, w(the, lower)), Noun, Number, [o(PT, C)|Content], AOut),
    append(AOut, [o(PT, lower)], Outs).
%% A DETERMINER THAT TAKES THE ARTICLE AFTER IT, where the lesson says so
%% (`"entrambe" takes the article.'): `por ambas partes' is `per entrambe le
%% parti', where Spanish writes no article after `ambas'
tr_det_out(foreign, det(Kind, DL, w(_, C)), Noun, Number, Content, Outs) :-
    tr_det_form(Kind, DL, Noun, Number, Content, T),
    (   Kind \== article, tr_solve(take(T, article))
    ->  tr_det_out(foreign, det(article, the, w(the, lower)), Noun, Number, Content, AOut),
        Outs = [o(T, C)|AOut]
    %% (... AND ONE THAT TAKES THE INDEFINITE ARTICLE HAS IT BEFORE IT IN THE SINGULAR: `Otra vecina manifiesta' is
    %% `Un'altra vicina', and the Italian writer wrote `Altra vicina', which Spanish says with no article --
    %% `"altra" takes the indefinite.')
    ;   Kind == determiner, Number == singular, tr_solve(take(T, indefinite)),
        tr_det_out(foreign, det(article, a, w(a, lower)), Noun, singular, [o(T, lower)|Content], [o(Art, _)])
    ->  Outs = [o(Art, C), o(T, lower)]
    ;   Outs = [o(T, C)]
    ).
en_count_first(F) :- atom(F), ( atom_number(F, _) -> true
                                ; memberchk(F, [two, three, four, five, six, seven, eight, nine, ten, twenty, hundred, thousand]) ).

%% THE FORM OF A DETERMINER IS CHOSEN BY THE WORD AFTER IT where the lesson
%% says so: `The article "lo" comes before "sc".', `... before a vowel.' --
%% so `lo scandalo', `uno scandalo', and before a vowel `lo', which the
%% elision makes `l'' and the contractions `dell'' and `degli'. Among the
%% determiners of the noun's gender, one whose come_before/2 matches the
%% next word; failing that the first with no such rule, which is the
%% ordinary `il'; failing that the first.
%% THE DETERMINERS THAT AGREE ARE TAKEN IN THE LESSON'S ORDER, one of no
%% gender among them: `cualquier signo' is `qualsiasi segno', and with the
%% noun's gender asked first the dictionary's masculine `molto', an adverb
%% it also lists as a determiner meaning any, came before the lesson's word
%% and wrote `molto segno'.
%% ... AND A FEMININE NOUN WHOSE FIRST VOWEL IS A STRESSED `A' TAKES THE
%% MASCULINE ARTICLE IN THE SINGULAR, where the lesson says it is euphonic
%% (`"agua" is euphonic.'): `el agua', `un águila', never `la agua'. The
%% adjectives still agree with the noun, and the plural is the feminine's
tr_det_form(Kind, DL, Noun, Number, Content, T) :-
    tr_det_meanings(Kind, DL, Ms),
    tr_noun_gender(Noun, G1),
    (   G1 == feminine, Number == singular, atom(Noun), tr_solve(euphonic(Noun)) -> G = masculine ; G = G1 ),
    findall(M, ( member(M, Ms), ( G == none ; tr_gender(M, G) ; tr_gender(M, none) ) ), Cands0),
    ( Cands0 == [] -> Cands = Ms ; Cands = Cands0 ),
    (   Content = [o(Next, _)|_], atom(Next), member(L0, Cands), tr_solve(come_before(L0, P)), tr_begin_with(Next, P) -> L = L0
    ;   member(L0, Cands), \+ tr_solve(come_before(L0, _)) -> L = L0
    ;   Cands = [L|_]
    ), !,
    (   Kind == demonstrative, tr_det_apocope(L, Content, A) -> tr_inflect(foreign, Kind, A, Number, T)
    %% (and a determiner in the singular: `ningún artefacto' is `nessun dispositivo', where it was `nessuno
    %% dispositivo', and `cualquier' is the short form of `cualquiera')
    ;   Kind == determiner, Number == singular, tr_det_apocope(L, Content, A) -> T = A
    ;   tr_inflect(foreign, Kind, L, Number, T)
    ).

%% (`its' takes the words for `his' after its own, where the lesson has none of the noun's gender: the
%% lesson's languages say both with one, and a store taught before `"suo" means "its".' wrote no sentence
%% that had it -- one with the masculine alone wrote `la suo porta')
tr_det_meanings(possessive, its, Ms) :- !,
    ( tr_meanings_of(its, foreign, possessive, Ms1) -> true ; Ms1 = [] ),
    ( tr_meanings_of(his, foreign, possessive, Ms2) -> true ; Ms2 = [] ),
    append(Ms1, Ms2, Ms).
tr_det_meanings(Kind, DL, Ms) :- tr_meanings_of(DL, foreign, Kind, Ms).

%% A DEMONSTRATIVE BEFORE ITS NOUN LOSES ITS ENDING WHERE THE ARTICLE DOES:
%% `ese medio siglo' is `quel mezzo secolo', and written whole it came out
%% `quello secolo', which no Italian page prints. The lesson states the
%% short form (`"quel" is the apocope of "quello".', and `quei' its plural)
%% and says where the article keeps its long form (`The article "lo" comes
%% before "sc".', `... before a vowel.'), and the demonstrative keeps its own
%% there: `quello studente', and before a vowel the elision, `quell'uomo'.
tr_det_apocope(L, [o(Next, _)|_], A) :-
    atom(Next), tr_solve(apocope_of(A, L)),
    \+ ( tr_solve(come_before(Art, P)), tr_class_of(Art, article), tr_begin_with(Next, P) ), !.

%% A NOUN OF BOTH GENDERS TAKES THE MASCULINE WHERE NOTHING SAYS WHICH. The
%% builder states one with no gender and denies it the feminine that the rule
%% for `-a' would give it -- `"solista" is not feminine.' -- and asked for a
%% determiner with no gender at all, the writer took the lesson's first:
%% Italian's is `la', and `los solistas' came out `le solisti', the article
%% feminine and the noun masculine. Spanish's first is `el', which is why
%% the same statement had always written `el socorrista'.
tr_noun_gender(Noun, G) :-
    tr_gender(Noun, G0),
    (   G0 == none, atom(Noun), Noun \== none, tr_solve(neg(feminine(Noun))) -> G = masculine
    ;   G = G0
    ).

tr_adj_complement(obj(NP0), PP, obj(NP)) :- tr_adj_takes_phrase(NP0, PP, NP).
tr_adj_complement(pp(P, NP0), PP, pp(P, NP)) :- tr_adj_takes_phrase(NP0, PP, NP).
tr_adj_takes_phrase(np(Det, Num, Adjs0, N, Nb), pp(w(Q, QC), X), np(Det, Num, Adjs, N, Nb)) :-
    append(Adjs1, [A0], Adjs0), tr_adj_with_intensifier(A0, A), atom(A), en_adj_takes(A, Q),
    ( Q == of, en_with_adjective(A) -> Q1 = with ; Q1 = Q ),
    append(Adjs1, [postadj(A0, pp(w(Q1, QC), X))], Adjs).
%% (an adjective, with the word that says how much before it too: `di tipo "urbano" del tutto simile a
%% quello di altre città europee' is completely similar to that of other European cities)
tr_adj_with_intensifier(w(A, _), A).
tr_adj_with_intensifier(int(_, w(A, _)), A).
%% (and the subject's: a phrase and the phrases after it, with/2)
%% THE MOST FORMIDABLE THING ABOUT IT: the phrase of `of' after a superlative of `thing' (tr_np/3's
%% `lo más formidable de esta transformación') says what the thing is about
tr_with_adj(english, np(D, Q, [deg(superlative, A)], w(thing, TC), singular), [pp(w(of, PC), X)|More],
            np(D, Q, [deg(superlative, A)], w(thing, TC), singular), [pp(w(about, PC), X)|More]) :- !.
tr_with_adj(english, NP0, [PP|More], NP, More) :- tr_adj_takes_phrase(NP0, PP, NP), !.
tr_with_adj(_, NP, PPs, NP, PPs).
%% the verbs whose participle says who did it (`died', `arrived'): no passive to
%% mistake it for
en_active_participle(V) :- memberchk(V, [dies, arrives, disappears, occurs, happens, emigrates, collapses]).
%% the adjectives that take a phrase of their own, and its preposition
en_adj_takes(A, of) :- memberchk(A, [full, worthy, capable, afraid, aware, proud, tired, fond, devoid, ashamed, jealous]).
en_adj_takes(A, to) :- memberchk(A, [close, similar, equal, related, faithful, loyal, hostile, opposed, accustomed,
                                      relative]).
%% ... AND THE ONES ENGLISH SAYS WITH `with', after their noun too: `un gigantesco carrello carico di documenti' is a
%% gigantic trolley loaded WITH documents, and with the noun's adjective before it English wrote `a gigantic loaded
%% trolley of documents' (the phrase of `of' the source gave them is written `with', tr_adj_takes_phrase/3)
en_adj_takes(A, of) :- en_with_adjective(A).

%% ADJECTIVES AFTER A COMMA ARE SAID OF THE PHRASE BEFORE IT: `Volaron bombas de
%% harina contra un espectáculo, al parecer de muchas, vulgar y degradante' --
%% the show was vulgar, and agreeing with the subject (the bombs) Italian wrote
%% `volgari e degradanti'. They agree with the phrase of the complement before
%% the comma (an aside between commas, `al parecer de muchas', allowed between) --
%% asked once, of the clause's complements whole (tr_write/4): asked of each tail the
%% writer takes, the comma before an aside of its own was gone
tr_adj_after_comma(Cs0, Cs) :-
    %% (not where the source adjective says its gender for a subject that gives none, sagr/1, whose phrase
    %% is then the clause's own: `Alle spalle ha una vita movimentata, quasi avventurosa' -- nor a phrase
    %% between commas of its own, `no son, en consecuencia, reales')
    \+ memberchk(sagr(_), Cs0), \+ memberchk(suagr, Cs0),
    append(Pre, [C1, sep|Mid0], Cs0), \+ last(Pre, sep), ( C1 = obj(NP) ; C1 = pp(_, NP) ),
    NP = np(_, _, _, w(NW, _), Number), atom(NW),
    (   Mid0 = [adj(As)|Post], Mid = []
    ;   Mid0 = [A, sep, adj(As)|Post], A = pp(_, _), Mid = [A, sep]
    ), !,
    tr_noun_lexeme(foreign, NW, Number, _, FNoun),
    ( tr_gender(FNoun, G0), G0 \== none -> G = G0 ; G = masculine ),
    append(Pre, [C1, sep], P1), append(P1, Mid, P2), append(P2, [oadj(As, G, Number)|Post], Cs).
%% ... AND A PARTICIPLE OR AN ADJECTIVE JOINED TO IT, with its adverb and its phrase: `un equipo
%% compacto, organizado tácticamente y unido en mentalidad' -- the Spanish noun is masculine
%% and Italian's `squadra' is not, so the participle and the adjective after the comma agree
%% with the noun written, `organizzata' and `unita', as the first adjective (`compatta') does
tr_adj_after_comma(Cs0, Cs) :-
    \+ memberchk(sagr(_), Cs0),
    append(Pre, [C1, sep, Q|Post0], Cs0), \+ last(Pre, sep), ( C1 = obj(NP) ; C1 = pp(_, NP), memberchk(phagr, Cs0) ),
    NP = np(_, _, _, w(NW, _), Number), atom(NW),
    ( Q = pred(_) ; Q = adj(_) ),
    tr_agreeing_run([Q|Post0], Run, Post),
    memberchk(pred(_), Run),
    tr_noun_lexeme(foreign, NW, Number, _, FNoun),
    ( tr_gender(FNoun, G0), G0 \== none -> G = G0 ; G = masculine ),
    tr_run_agree(Run, G, Number, Run1), !,
    append(Pre, [C1, sep|Run1], P1), append(P1, Post, Cs).
tr_agreeing_run([C|Cs0], [C|Cs], Post) :- tr_run_comp(C), !, tr_agreeing_run(Cs0, Cs, Post).
tr_agreeing_run(Post, [], Post).
tr_run_comp(pred(_)).
tr_run_comp(adj(_)).
tr_run_comp(oadj(_, _, _)).
tr_run_comp(adv(_)).
tr_run_comp(cnj(_)).
tr_run_comp(pp(_, _)).
tr_run_agree([], _, _, []).
tr_run_agree([pred(L)|Cs0], G, N, [opred(L, G, N)|Cs]) :- !, tr_run_agree(Cs0, G, N, Cs).
tr_run_agree([adj(As)|Cs0], G, N, [oadj(As, G, N)|Cs]) :- !, tr_run_agree(Cs0, G, N, Cs).
tr_run_agree([oadj(As, _, _)|Cs0], G, N, [oadj(As, G, N)|Cs]) :- !, tr_run_agree(Cs0, G, N, Cs).
tr_run_agree([C|Cs0], G, N, [C|Cs]) :- tr_run_agree(Cs0, G, N, Cs).

%% the complements out: objects and predicates in place, the adverbs last,
%% and an object pronoun the lesson puts before the verb kept aside for it
tr_comps_out(_, [], _, _, [], [], []).
%% (a comparative adverb with its comparison after it stays where it stands: `el debate va mejor en privado de lo que
%% trasciende' goes better in private than what transpires, and written last it came out `goes than what transpires
%% better')
tr_comps_out(english, [adv(w(A, C))|Cs], Noun, Number, Clitics, [o(A, C)|Outs], Advs) :-
    memberchk(A, [better, worse]), ( memberchk(cmpc(_, _), Cs) ; memberchk(cmp(_, _), Cs) ), !,
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% (and an adverb in -ly straight before a comparative is said of it: `la situación es notablemente mejor que la de
%% hace un año' is notably better, and written last it came out `better than that of a year ago notably')
tr_comps_out(english, [adv(w(A, C)), X|Cs], Noun, Number, Clitics, [o(A, C)|Outs], Advs) :-
    X = adj([deg(comparative, _)|_]), atom(A), sub_atom(A, _, 2, 0, ly), !,
    tr_comps_out(english, [X|Cs], Noun, Number, Clitics, Outs, Advs).
%% (`too' before an adjective or an adverb is `too' still, said of it: `Ero troppo giovane' is I was too young, and
%% `too much' -- the adverb among a verb's complements, tr_comp_out/7 -- wrote `too much young')
tr_comps_out(english, [adv(w(too, C)), X|Cs], Noun, Number, Clitics, [o(too, C)|Outs], Advs) :-
    ( X = adj(_) ; X = pred(_) ; X = adv(_) ), !,
    tr_comps_out(english, [X|Cs], Noun, Number, Clitics, Outs, Advs).
%% A COUNT OF YEARS AFTER `TO' IS NO AGE IN A RANGE: `100 jóvenes de 18 a 25 años' are of 18 to 25 years, and with the
%% age (tr_comp_out/7) it was `of 18 at 25'. After a bare number in a phrase of `of' or `from', the phrase of `to' is
%% written as any phrase (rng/1)
tr_comps_out(english, [PP1, pp(W, NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    PP1 = pp(w(P1, _), np(none, none, [], w(N1, _), _)), atom(P1), memberchk(P1, [of, from]), atom(N1), atom_number(N1, _),
    W = w(to, _), NP = np(none, w(_, _), [], w(year, _), plural), !,
    tr_comps_out(english, [PP1, pp(W, rng(NP))|Cs], Noun, Number, Clitics, Outs, Advs).
%% AN ADJECTIVE THAT ENGLISH SAYS WITH `with' TAKES ITS PHRASE OF `of' SO: `llegaron provistos de dos camiones'
%% arrived equipped WITH two trucks, and English wrote `equipped of'
tr_comps_out(english, [adj(As), pp(w(of, C), X)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    last(As, w(A, _)), en_with_adjective(A), !,
    tr_comps_out(english, [adj(As), pp(w(with, C), X)|Cs], Noun, Number, Clitics, Outs, Advs).
%% `ASKS' FOR SOMETHING OF SOMEBODY IS `ASKS SOMEBODY FOR IT': `El Ayuntamiento ha pedido un informe a la
%% concesionaria FCC' has asked the contractor FCC for a report, and English wrote the lesson's order, `has asked for
%% a report to the contractor'
%% A DENIED INFINITIVE'S `still' IS ITS `yet', inside it: `di non aver ancora sviluppato un sentimento comune' is of
%% not having YET developed one -- pulled to the clause's verb, English wrote `has still accused'
tr_comps_out(english, [neg(I), adv(w(still, C))|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_verbal_inf(I), !,
    tr_comp_out(english, neg(I), Noun, Number, _, O0, _), tr_note_pred(neg(I)),
    ( append(O1, [Last], O0) -> append(O1, [o(yet, C), Last], O) ; O = O0 ),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Rest, Advs), append(O, Rest, Outs).
%% ... AND A SERIES OF INFINITIVES AFTER A COMMA ARE ALL THE VERB'S, each with its preposition: `ha accusato le donne
%% di non essersi evolute ..., di non aver sviluppato un sentimento comune' accused them of not having evolved, of not
%% having developed one, and with the verb's preposition for its first infinitive alone (tr_en_prep_gerund/1) the
%% second came out `not to have developed'
tr_comps_out(english, [sep, I|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_verbal_inf(I), tr_global('$tr_inf_seen', yes), tr_global('$tr_last_pred', none),
    tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V), en_prep_gerund(V, _), !,
    nb_setval('$tr_inf_seen', no),
    tr_comps_out(english, [sep, I|Cs], Noun, Number, Clitics, Outs, Advs).
%% A PRONOUN ON A MODAL'S INFINITIVE IS THE OBJECT OF THE INFINITIVE AFTER IT: `vuole poterlo mangiare' wants to be
%% able to eat it -- Italian and Spanish put the pronoun of the second infinitive on the modal before it (`poterlo',
%% `doverlo', `volerlo', `poderlo'), and written where it stood English said `to be able him to eat'; a purpose too
%% (`per poterlo vedere', to be able to see it)
tr_comps_out(english, [K0, inf(IL)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    ( K0 = infx(L, simple, Cls), K = inf(L) ; K0 = purp(infx(L, simple, Cls)), K = purp(inf(L)) ),
    memberchk(L, [can, must, wants]), Cls = [_|_], forall(member(C, Cls), ( C = w(_, _) ; C = dat(w(_, _)) )), !,
    tr_comps_out(english, [K, infx(IL, simple, Cls)|Cs], Noun, Number, Clitics, Outs, Advs).
tr_comps_out(english, [obj(NP), pp(w(to, _), P)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_global('$tr_verb', asks), \+ en_counted(P), !,
    tr_np_out(english, P, PO, _, _), tr_np_out(english, NP, NO, _, _),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Rest, Advs), append([PO, [o(for, lower)], NO, Rest], Outs).
%% AN INFINITIVE JOINED TO A PREPOSITION'S INFINITIVE IS UNDER THE SAME PREPOSITION IN ENGLISH, which writes both as
%% gerunds: `che prima di essere arrestato e di decidere di collaborare era uno dei più noti malviventi' -- before
%% being arrested and deciding to collaborate, where it was `and to decide'. What stands between them is the first
%% infinitive's own
tr_comps_out(english, [pinf(W, L1)|Cs0], Noun, Number, Clitics, Outs, Advs) :-
    W = w(P, _), atom(P), P \== to,
    append(Mid, [cnj(K), inf(F)|Cs1], Cs0),
    forall(member(X, Mid), ( X = pred(_) ; X = obj(_) ; X = pp(_, _) ; X = adv(_) )), !,
    append([[pinf(W, L1)], Mid, [cnj(K), pinf(W, F)], Cs1], Cs),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% A SPAN OF TIME BEFORE THE OBJECT STANDS AFTER IT IN ENGLISH, WITH `for': `esperó siete horas la salida de un avión
%% averiado' waited for the departure of a damaged aeroplane for seven hours, and the lesson's order wrote `expected
%% seven hours the departure' (and after the object's phrases of `of', `waited for the departure of a damaged aeroplane
%% for seven hours', where it was `the departure for seven hours of a damaged aeroplane')
tr_comps_out(english, [at_time(Sp), obj(NP)|Cs0], Noun, Number, Clitics, Outs, Advs) :-
    tr_span_np(Sp), !, tr_en_of_run(Cs0, Ofs, Cs1),
    append([[obj(NP)], Ofs, [pp(w(for, lower), Sp)], Cs1], Cs),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% ... and one the source put after the object takes its `for' there: `Los pasajeros aguantaron con estoicismo su mala
%% suerte un par de horas' held it for a couple of hours, where English wrote `their bad luck a couple of hours'
tr_comps_out(english, [obj(NP)|Cs0], Noun, Number, Clitics, Outs, Advs) :-
    tr_en_of_run(Cs0, Ofs, [at_time(Sp)|Cs1]), tr_span_np(Sp), !,
    append([[obj(NP)], Ofs, [pp(w(for, lower), Sp)], Cs1], Cs),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% (an hour and the part of the day after it, en_day_part/2)
tr_comps_out(english, [PP1, pp(w(of, C), np(det(article, the, _), none, [], w(D, _), singular))|Cs], Noun, Number, Clitics, Outs, Advs) :-
    en_clock_pp(PP1), en_day_part(D, Ws), !,
    tr_comp_out(english, PP1, Noun, Number, _, O1, _), findall(o(X, lower), member(X, Ws), O2), O2 = [o(F, _)|O2r],
    tr_comps_out(english, Cs, Noun, Number, Clitics, Rest, Advs), append([O1, [o(F, C)|O2r], Rest], Outs).
%% `MAKES' OR `LETS' AND AN INFINITIVE BEFORE ITS OBJECT ARE THE OBJECT AND THE BARE INFINITIVE IN ENGLISH: `tutti
%% fattori che fanno impennare la bolletta figlio' make the child bill soar, and English wrote the lesson's order, `make
%% to soar the son bill'
%% -- the phrase being the one that does it: the infinitive's verb takes no object, one with that meaning the lesson
%% calls intransitive or one whose perfect takes the copula (`fanno scattare la positività', `ha fatto passare la
%% protezione'; `Le ho fatto recapitare il disco a casa da un amico' delivered the disc, and English wrote `made her the
%% disc deliver'), and the phrases of `of' right after it go with it (`made the protection of this disease happen',
%% where it was `the protection happen of this disease')
tr_comps_out(english, [inf(L), obj(NP)|Cs0], Noun, Number, Clitics, Outs, Advs) :-
    tr_global('$tr_verb', V), atom(V), memberchk(V, [makes, lets]), en_causee_infinitive(L), !,
    tr_en_of_run(Cs0, Ofs, Cs), ( Ofs == [] -> O = NP ; O = with(NP, Ofs) ),
    tr_comps_out(english, [obj(O), binf(L)|Cs], Noun, Number, Clitics, Outs, Advs).
tr_comps_out(english, [purpose(L), pp(w(to, _), NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    atom(L), en_bare_person_verb(L), !,
    tr_comp_out(english, purpose(L), Noun, Number, _, PO, _), tr_np_out(english, NP, NO, _, _),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Rest, Advs), append([PO, NO, Rest], Outs).
%% AN ADVERB OF MANNER RIGHT AFTER A PARTICIPLE STAYS WITH IT: `un equipo compacto, organizado
%% tácticamente y unido' is organised tactically and united, never `organised and united ...
%% tactically' -- the adverbs go last in English, and this one belongs to the participle
tr_comps_out(english, [pred(L), adv(w(A, C))|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_comp_out(english, adv(w(A, C)), Noun, Number, _, _, [o(AT, AC)]), atom(AT), sub_atom(AT, _, 2, 0, ly), !,
    tr_comp_out(english, pred(L), Noun, Number, _, POut, _),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs1, Advs),
    append([POut, [o(AT, AC)], Outs1], Outs).
%% ... AND AN OBJECT AFTER THE PHRASE OF A PREPOSITION, LAST IN ITS CLAUSE, COMES
%% BEFORE IT: `la UGT, que denunció ante la Audiencia Nacional este acuerdo'
%% denounced THIS AGREEMENT before the court -- Spanish and Italian put a short
%% object after the phrase, and English writes the object next to its verb
%% (`which denounced in front of the Audiencia Nacional this agreement'). The
%% phrase of a preposition before a phrase or a name, never a phrase the verb
%% governs and never `of', which says more of the word before it (`Di Corrado
%% Sannucci Roma' is the byline's reporter and his city, and it was `Roma of
%% Corrado Sannucci'; `tenere d'occhio le piscine' was `hold the pools of eye');
%% the object a phrase with a determiner or a count -- a bare noun or a number is
%% no object of its own (`al Tg 4' is the channel's name, and it was `go 4 to the
%% Tg'; `sin más compañía' was `without more' and `company') -- and never the
%% phrase of `to' of a verb that takes it bare: what something costs somebody
%% is the person and then the price, and the object first it was `costs a book
%% to the dog' (the clause below)
tr_comps_out(english, [PP, obj(NP)], Noun, Number, Clitics, Outs, Advs) :-
    PP = pp(w(P, _), X), atom(P), P \== of,
    ( X = np(_, _, _, _, _) ; X = name(_) ; X = with(_, _) ),
    \+ ( P == to, tr_global('$tr_verb', V), en_bare_dative(V) ),
    NP = np(D, Num, _, w(_, _), _), ( D \== none ; Num \== none ), !,
    tr_comps_out(english, [obj(NP), PP], Noun, Number, Clitics, Outs, Advs).
%% ... AND THE CORNER OF A STREET IS `AT' IT: `la placa se colocó en la esquina de la calle de la Cadena' was placed at
%% the corner of the street, where English wrote `in the corner' (a room's corner stays `in')
tr_comps_out(english, [pp(w(in, C), NP), pp(w(of, C2), X)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_on_head(NP, corner), tr_on_head(X, SN), memberchk(SN, [street, square, avenue, road, boulevard, promenade]), !,
    tr_np_out(english, NP, NPOut, _, _),
    tr_comps_out(english, [pp(w(of, C2), X)|Cs], Noun, Number, Clitics, Rest, Advs),
    append([o(at, C)|NPOut], Rest, Outs).
%% ... AND A UNIT OF TIME AFTER A TIME IS HOW OFTEN: `las cajas de ahorros, que
%% abren una tarde a la semana' open one afternoon A WEEK -- `a la semana' is
%% the lesson's `to the week', and English says `a' and the unit
tr_comps_out(english, [T, pp(w(to, _), np(det(article, the, _), none, [], w(U, UC), singular))|Cs], Noun, Number, Clitics, Outs, Advs) :-
    T = at_time(_), atom(U), memberchk(U, [day, week, month, year, hour]), !,
    tr_comp_out(english, T, Noun, Number, _, TO, _),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Rest, Advs),
    append(TO, [o(a, lower), o(U, UC)|Rest], Outs).
%% ... AND THE PHRASES OF `OF' AFTER AN ABSOLUTE CLAUSE'S PHRASE ARE THAT
%% PHRASE'S: `mantiene bloqueado el convenio colectivo del sector bancario' keeps
%% the collective agreement OF THE BANKING SECTOR blocked -- English writes the
%% participle after its phrase (tr_comp_out/7), and the phrase of `of', read
%% after it, stood after the participle: `keeps the agreement blocked of the sector'
tr_comps_out(english, [abso(L, NP), PP|Cs0], Noun, Number, Clitics, Outs, Advs) :-
    PP = pp(w(of, _), _), tr_of_run([PP|Cs0], Ofs, Cs), !,
    tr_comps_out(english, [abso(L, with(NP, Ofs))|Cs], Noun, Number, Clitics, Outs, Advs).
%% THE WORD FOR `SAME' AFTER A REFLEXIVE PRONOUN IS ITS EMPHASIS, which English
%% has in the pronoun: `uguale a sé stessa', `igual a sí misma' is `equal to
%% itself', never `equal to itself same'
tr_comps_out(english, [pp(P, pronoun(w(R, RC))), adj([w(same, _)])|Cs], Noun, Number, Clitics, Outs, Advs) :-
    atom(R), en_reflexive(R), !,
    tr_comps_out(english, [pp(P, pronoun(w(R, RC)))|Cs], Noun, Number, Clitics, Outs, Advs).
%% PRONOUNS THAT CLIMBED TO A VERB OF THE SAME SUBJECT ARE THE INFINITIVE'S:
%% `No nos pueden acusar de desleales' has `nos' before `pueden', and English
%% says `cannot accuse us' -- never `cannot us accuse', nor, for `Lo quiero
%% comer', `want him to eat', which is another sentence. A modal and the verbs
%% of wanting, trying and beginning take their own subject's infinitive; the
%% verbs that make or let another one do it (`Lo dejo comer') keep the object
%% where it stands.
tr_comps_out(english, [opron(P)|Cs0], Noun, Number, Clitics, Outs, Advs) :-
    tr_same_subject_verb, tr_climbed_pronouns(Cs0, Ps, I, Post), !,
    append([I, opron(P)|Ps], Post, Cs),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% A PRONOUN AFTER AN INFINITIVE IS THE INFINITIVE'S, not what the verb of saying
%% says: `una amichetta le ha detto di essere stata lei ad avvertire il bagnino'
%% is she said to her to have been HER, where the pronoun after `essere' was
%% written `it', the thing said (tr_comp_out/7, the verb of saying's pronoun)
tr_comps_out(english, [I, opron(P)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    ( I = infx(_, _, _) ; I = inf(_) ),
    tr_global('$tr_verb', V), atom(V), en_saying(V),
    tr_comp_out(english, I, Noun, Number, Clitic, Out, Adv),
    nb_setval('$tr_verb', none),
    (   tr_comps_out(english, [opron(P)|Cs], Noun, Number, Clitics1, Outs1, Advs1) -> nb_setval('$tr_verb', V)
    ;   nb_setval('$tr_verb', V), fail
    ), !,
    append(Clitic, Clitics1, Clitics), append(Out, Outs1, Outs), append(Adv, Advs1, Advs).
%% TWO OBJECT PRONOUNS ARE A THING AND A PERSON: `te lo digo' is `I say it to
%% you' and `se lo doy' `I give it to him', where written in their order it was
%% `I say you him', `I give him him'. The second is what is said or given --
%% `it', or `them' -- and the first the one it goes to, `to' for the verbs of
%% giving and saying and `from' for the ones of taking (en_takes_from/1)
tr_comps_out(english, [opron(P1), opron(w(W2, C2))|Cs], Noun, Number, Clitics, Outs, Advs) :-
    memberchk(W2, [him, her, it, them]), !,
    ( W2 == them -> T2 = them ; T2 = it ),
    (   tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V), en_takes_from(V) -> Prep = from ; Prep = to ),
    tr_comp_out(english, opron(P1), Noun, Number, _, O1, _),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs0, Advs),
    append([[o(T2, C2), o(Prep, lower)], O1, Outs0], Outs).
%% THE `of' AFTER A COUNTED MAGNITUDE IS ITS NOUN'S, wherever the magnitude
%% stands (see tr_np_out/5): `piden 5.000 millones de pesetas' is ask for 5,000
%% million pesetas, where the reader gave the verb the phrase and then its `of'
tr_comps_out(english, [C1, pp(w(of, _), NP2)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    NP2 = np(none, _, _, _, _), tr_counted_comp(C1), !,
    tr_comps_out(english, [C1, bare(NP2)|Cs], Noun, Number, Clitics, Outs, Advs).
%% AN ADJECTIVE WITH A PHRASE OF ITS OWN STANDS AFTER ITS NOUN IN ENGLISH: `una
%% audiencia digna de una Copa del Mundo' is an audience worthy of a World Cup,
%% `una casa llena de gatos' a house full of cats -- never `a worthy audience of
%% a Cup' nor `a full house of cats'. The reader leaves the phrase among the
%% complements, after the noun's; the last of the noun's adjectives, if it is
%% one of the few that take such a phrase (en_adj_takes/2), takes it
tr_comps_out(english, [C1, PP|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_adj_complement(C1, PP, C2), !,
    tr_comps_out(english, [C2|Cs], Noun, Number, Clitics, Outs, Advs).
%% A QUESTION OF NO VERB OF ITS OWN BETWEEN COMMAS IS BARE: `..., para qué
%% engañarnos' is `why deceive us' -- the infinitive after `why' takes no `to'
%% (after a verb of knowing it does, `I do not know why to eat', and that is
%% not set off by a comma)
tr_comps_out(english, [sep, obj(NP), infx(L, Asp, Cls)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    NP = np(none, none, [], w(why, _), singular), !,
    tr_comps_out(english, [sep, obj(NP)], Noun, Number, Cl1, O1, A1),
    tr_lexeme_across(L, english, LT),
    (   Asp == perfect -> en_participle_of(LT, PP), V = [o(have, lower), o(PP, lower)]
    ;   en_base(LT, B), V = [o(B, lower)]
    ),
    findall(o(T, lower), ( member(W, Cls), ( W = w(T, _) ; W = dat(w(T, _)) ) ), Objs),
    tr_comps_out(english, Cs, Noun, Number, Cl2, O2, A2),
    append(Cl1, Cl2, Clitics), append(A1, A2, Advs), append([O1, V, Objs, O2], Outs).
%% THE PARTICIPLE OF WHAT HAPPENED TO A PERSON, AFTER HIS COMMA, IS WHO DID IT:
%% `Eric Morley, fallecido el pasado noviembre' is Eric Morley, who died last
%% November -- English has no such participle after a name (`Eric Morley, died
%% last November'), only for a verb that has no passive (en_active_participle/2)
tr_comps_out(english, Cs0, Noun, Number, Clitics, Outs, Advs) :-
    append(Pre, [sep, pred(L)|Post], Cs0), append(Pre1, [obj(X)|Mid], Pre), forall(member(M, Mid), M = pp(_, _)),
    %% (the person is the last object before the comma, phrases of the clause's
    %% between them allowed: `hay que recordar a Eric Morley en el inicio de este
    %% tinglado, fallecido ...')
    ( X = name(_) ; X = np(_, _, _, _, _), tr_of_class(X, person) ),
    tr_lexeme_across(L, english, LT), en_active_participle(LT), !,
    en_past_of(LT, Past),
    %% ... and the phrases between them and the comma come after the clause,
    %% between commas, so that it is Eric Morley's and not the last of them (an
    %% adverb in it is written at the end of the clause and would part it from
    %% the participle: there the phrases stay where they were)
    (   Mid \== [], \+ memberchk(adv(_), Post)
    ->  append(Pre1, [obj(X)], PreP), PostMid = Mid
    ;   PreP = Pre, PostMid = []
    ),
    tr_comps_out(english, PreP, Noun, Number, Cl1, O1, A1),
    tr_comps_out(english, Post, Noun, Number, Cl2, O2, A2),
    (   PostMid == [] -> O3 = [], A3 = [], Cl3 = []
    ;   tr_comps_out(english, PostMid, Noun, Number, Cl3, O3a, A3), O3 = [o(',', comma)|O3a]
    ),
    append([Cl1, Cl2, Cl3], Clitics), append([A1, A2, A3], Advs),
    append([O1, [o(',', comma), o(who, lower), o(Past, lower)], O2, O3], Outs).
%% WHAT SOMETHING COSTS SOMEBODY IS THE PERSON AND THE PRICE, with no `to': `le
%% ha costado al club 75 millones' has cost the club 75 million, where `a' made
%% it `cost to the club'. Only before the price, the object that follows it: a
%% place after the verb is a place (`Al Sud le università costano meno che al
%% Nord' -- the South and the North are not who pays), and `costa molto di più
%% allo stato' has no price after it
tr_comps_out(english, [pp(w(to, _), NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_global('$tr_verb', V), en_bare_dative(V), memberchk(obj(_), Cs), !,
    tr_comps_out(english, [bare(NP)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... and the person a verb of forbidding, allowing or asking says what to do takes no `to' before
%% the infinitive: `intendeva proibire ai cani di passeggiare' intended to forbid the dogs to stroll,
%% where it was `to forbid to the dogs to stroll' -- after the clause's verb and after an infinitive
tr_comps_out(english, [inf(V), pp(w(to, _), NP), inf(L)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    atom(V), en_person_before_inf(V), !,
    tr_comps_out(english, [inf(V), bare(NP), inf(L)|Cs], Noun, Number, Clitics, Outs, Advs).
tr_comps_out(english, [pp(w(to, _), NP), inf(L)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_global('$tr_verb', V), atom(V), en_person_before_inf(V), !,
    tr_comps_out(english, [bare(NP), inf(L)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... and the person a verb of reproaching, warning or telling says a clause of `that' to: `echó en cara hace una
%% semana a Esteve Ferran ... que no se hubiese alertado del peligro' reproached Esteve Ferran, where it was
%% `reproached to Esteve Ferran'
tr_comps_out(english, [pp(w(to, _), NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_global('$tr_verb', V), atom(V), en_person_that(V), memberchk(that(_), Cs), !,
    tr_comps_out(english, [bare(NP)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... and `instead of' before the phrase of a preposition it is said of:
%% `ricorrere al Tar, invece che alla commissione federale' is to appeal to the
%% Tar instead of to the commission, where it was written last, `to the
%% commission instead of'. The negation stands there too, `(e non dopo le
%% controanalisi)' is and not after the counteranalyses, never `after the
%% counteranalyses not'
tr_comps_out(english, [adv(w(A, C)), pp(P, NP)|Cs], Noun, Number, Clitics, [o(AT, C)|Outs], Advs) :-
    ( A == 'instead of' ; A == not ), !,
    tr_word_across(w(A, lower), english, adverb, AT),
    tr_comps_out(english, [pp(P, NP)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... and an adverb that says how much of the object, `more than', `about',
%% `almost', is written before it in English: `reciben más de 5 perros'
%% receive more than 5 dogs, where it came last, `receive 5 dogs more than'
%% (and `more than' or `less than' before `a' is before `one': `más de una
%% casa' is more than one house, never `more than a house')
%% (and with its degree adverb before it: `basta assai meno del 50,1%' is much less than 50.1%)
%% (`neppure' before the phrase of a preposition is said of it, and in a denied clause it is `even':
%% `i cellulari non smettono di trillare neppure in spiaggia' do not stop ringing even on the beach,
%% where it was written last, `in beach not even')
tr_comps_out(english, [adv(w('not even', C)), C1|Cs], Noun, Number, Clitics, [o(AT, C)|Outs], Advs) :-
    C1 = pp(_, _), !,
    ( tr_global('$tr_denied', yes) -> AT = even ; AT = 'not even' ),
    tr_comps_out(english, [C1|Cs], Noun, Number, Clitics, Outs, Advs).
tr_comps_out(english, [iadv(w(I, IC), w(A, C)), C1|Cs], Noun, Number, Clitics, [o(IT, IC), o(AT, C)|Outs], Advs) :-
    en_object_adverb(A), C1 = obj(_), !,
    tr_word_across(w(I, lower), english, adverb, IT), tr_word_across(w(A, lower), english, adverb, AT),
    tr_comps_out(english, [C1|Cs], Noun, Number, Clitics, Outs, Advs).
tr_comps_out(english, [adv(w(A, C)), obj(np(det(article, a, W), none, Adjs, N, singular))|Cs], Noun, Number, Clitics,
             [o(AT, C)|Outs], Advs) :-
    ( A == 'more than' ; A == 'less than' ), !,
    tr_word_across(w(A, lower), english, adverb, AT),
    W = w(_, WC),
    tr_comps_out(english, [obj(np(none, w(one, WC), Adjs, N, singular))|Cs], Noun, Number, Clitics, Outs, Advs).
tr_comps_out(english, [adv(w(A, C)), C1|Cs], Noun, Number, Clitics, [o(AT, C)|Outs], Advs) :-
    en_object_adverb(A), ( C1 = obj(_) ; C1 = at_time(np(_, w(_, _), _, _, _))      % (a count of time: `sólo ... 10 minutos')
                         ; A == even, C1 = pp(_, _)                                  % (`e persino di arsenico', and even of arsenic)
                         ; A == only, C1 = pp(_, _) ), !,                            % (`soltanto nel week end', only at the weekend)
    %% (`not even' before the object of a denied clause is `even': `non si trova nemmeno un
    %% trafiletto' does not find even a snippet, never `does not find not even a snippet')
    ( A == 'not even', tr_global('$tr_denied', yes) -> AT = even ; tr_word_across(w(A, lower), english, adverb, AT) ),
    tr_comps_out(english, [C1|Cs], Noun, Number, Clitics, Outs, Advs).
%% (and `precisely' before the phrase of a preposition it is said of: `proprio alla sinistra del presidente' is
%% precisely to the left of him, where it was written last)
tr_comps_out(english, [adv(w(precisely, C)), C1|Cs], Noun, Number, Clitics, [o(precisely, C)|Outs], Advs) :-
    C1 = pp(_, _), !,
    tr_comps_out(english, [C1|Cs], Noun, Number, Clitics, Outs, Advs).
%% (`also' the mid-adverb puller left where it stood, before a phrase of a preposition after a comma:
%% `tende, anche con l'aiuto dell'acqua salmastra, a facilitare' tends, also with the help of the water)
tr_comps_out(english, [adv(w(also, C)), C1|Cs], Noun, Number, Clitics, [o(also, C)|Outs], Advs) :-
    C1 = pp(_, _), !,
    tr_comps_out(english, [C1|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... and `each' after the object it says how much of: `diez minutos cada una' is
%% ten minutes each, where it was written last, `had ten minutes to convince
%% the jury ... each'
tr_comps_out(english, [C1, adv(w(each, C))|Cs], Noun, Number, Clitics, Outs, Advs) :-
    ( C1 = obj(_) ; C1 = at_time(_) ), !,
    tr_comps_out(english, [C1], Noun, Number, Cl1, O1, A1),
    tr_comps_out(english, Cs, Noun, Number, Cl2, O2, A2),
    append(Cl1, Cl2, Clitics), append(A1, A2, Advs),
    append([O1, [o(each, C)], O2], Outs).
%% ... but in English an adverb before a QUANTITY is the quantity's: `muy
%% pocos elementos' is very few elements, and put last it was `few elements
%% very'
tr_comps_out(english, [adv(w(A, C)), obj(NP)|Cs], Noun, Number, Clitics, [o(AT, C)|Outs], Advs) :-
    NP = np(det(determiner, L, _), _, _, _, _), memberchk(L, [little, much]), !,
    tr_word_across(w(A, lower), english, adverb, AT),
    tr_comps_out(english, [obj(NP)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... and an adverb before a comparison is the comparison's: `han tardado
%% más que nosotros' took more than us, and put last it was `have taken than
%% us ... more'
tr_comps_out(english, [adv(w(A, C)), cmp(K, X)|Cs], Noun, Number, Clitics, [o(AT, C)|Outs], Advs) :- !,
    tr_word_across(w(A, lower), english, adverb, AT),
    tr_comps_out(english, [cmp(K, X)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... and `while' and `not' right before a gerund are the gerund's: `persone che
%% pur non essendo residenti pagano la tassa' pay the tax while not being
%% resident, where the two came last, `being resident while not'
tr_comps_out(english, [adv(w(A, C))|Cs], Noun, Number, Clitics, [o(AT, C)|Outs], Advs) :-
    memberchk(A, [while, not]), ( Cs = [ger(_, _)|_] ; Cs = [adv(w(not, _)), ger(_, _)|_] ), !,
    tr_word_across(w(A, lower), english, adverb, AT),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% ... and an adverb that is the first of a choice (cor/1) stays in it:
%% `either directly or through companies' -- put last it was `either or
%% through participated companies, ... directly'
tr_comps_out(english, [cor(W), adv(w(A, C))|Cs], Noun, Number, Clitics, [O1, o(AT, C)|Outs], Advs) :- !,
    tr_comp_out(english, cor(W), Noun, Number, _, [O1], _),
    tr_word_across(w(A, lower), english, adverb, AT),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% ... and English, which writes its adverbs after the complements, writes
%% them before a clause the verb takes, where the reader put them
%% (tr_advs_join/3): `he said then that ...', never `that ... then' -- and
%% before a clause between dashes, which stays where it stood (dsh/1):
%% `we went to eat together - or rather: I ate - ...'
tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs) :-
    append(Pre, [C|Post], Cs), Pre \== [], ( tr_clause_comp(C) ; C = dsh(_) ), memberchk(adv(_), Pre), !,
    tr_comps_out(english, Pre, Noun, Number, Cl1, O1, A1),
    tr_comps_out(english, [C|Post], Noun, Number, Cl2, O2, Advs),
    append(Cl1, Cl2, Clitics), append([O1, A1, O2], Outs).
%% A PARTICIPLE AFTER AN OBJECT PRONOUN IS SAID OF THE OBJECT: `lo que los
%% hace tan deseados' makes THEM so desired, and agreeing with the subject it
%% came out `li fa così desiderato'. The pronoun says the number and, where
%% it has one, the gender: English's `them' is plural and `her' feminine.
tr_comps_out(foreign, Cs0, Noun, Number, Clitics, Outs, Advs) :-
    Cs0 = [opron(w(P, _))|_], tr_object_agreement(P, G, N),
    append(Pre, [pred(L)|Post], Cs0), !,
    append(Pre, [opred(L, G, N)|Post], Cs),
    tr_comps_out(foreign, Cs, Noun, Number, Clitics, Outs, Advs).
%% ... AND SO IS AN ADJECTIVE: `tutti i sapienti del tempo la ritenevano
%% ancora piatta' believed IT still flat, the earth, and agreeing with the
%% subject it came out `la creyeron todavía planos'
tr_comps_out(foreign, Cs0, Noun, Number, Clitics, Outs, Advs) :-
    Cs0 = [opron(w(P, _))|_], tr_object_agreement(P, G, N),
    append(Pre, [adj(As)|Post], Cs0), !,
    append(Pre, [oadj(As, G, N)|Post], Cs),
    tr_comps_out(foreign, Cs, Noun, Number, Clitics, Outs, Advs).
%% AN INFINITIVE JOINED TO ANOTHER IS THE SAME VERB'S: `quiere continuar con
%% las reformas y anclar a su país' -- both are what he wants, and with the
%% first infinitive the verb being written, the second took the word
%% `continuare' takes, `e a ancorare'
%% ... AND SO IS ONE AFTER A COMMA: `ha accusato le donne di dormire, di mangiare il pane' is `de dormir, de comer el
%% pan', and with the first infinitive's verb the one being written the second took no word
tr_comps_out(foreign, [K|Cs], Noun, Number, Clitics, Outs, Advs) :-
    ( K = cnj(_) ; K == sep ), Cs = [I|_], ( I = inf(_) ; I = neg(inf(_)) ),
    tr_global('$tr_inf_governor', gov(V, V0)), tr_global('$tr_verb', V1), V1 == V, !,
    nb_setval('$tr_verb', V0),
    tr_comp_out(foreign, K, Noun, Number, Clitic, Out, Adv),
    tr_comps_out(foreign, Cs, Noun, Number, Clitics1, Outs1, Advs1),
    append(Clitic, Clitics1, Clitics), append(Out, Outs1, Outs), append(Adv, Advs1, Advs).
%% ... AND `AGO' IS WRITTEN BEFORE THE TIME WHERE THE LESSON'S WORD BEGINS IT
%% (tr_ago_first/0): `due anni fa' is `hace dos años'
tr_comps_out(foreign, [at_time(NP), adv(w(ago, C))|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_ago_first, !,
    tr_comps_out(foreign, [adv(w(ago, C)), at_time(NP)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... AND A RANGE TAKES THE WORD THE LESSON BEGINS IT WITH, where it says one (`The word "de" begins
%% the range.'): `dal 10 marzo al 31 ottobre' is `del 10 de marzo al 31 de octubre', and `da un
%% minimo di 540 mila lire ai due milioni' `de un mínimo de 540 mil liras a los dos millones', where
%% the lesson's word for `from' wrote `desde ... a'. A phrase of `of' that says what the first end
%% is of may stand between the two; a lesson with no such word (Italian's `da') writes `from' as it did
tr_comps_out(foreign, [pp(w(from, C), NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_range_rest(Cs), once(tr_solve(begin(PT, range))), atom(PT), !,
    tr_np_out(foreign, NP, NPOut, _, _),
    tr_comps_out(foreign, Cs, Noun, Number, Clitics, Outs1, Advs),
    append([o(PT, C)|NPOut], Outs1, Outs).
%% ... AND `UNTIL' AFTER `FROM' IS `TO': `dal lido fino a San Marco' is from the Lido to San Marco,
%% and `fino a' is the lesson's `until' -- `from the shore until San Marco'. Spanish keeps its
%% `desde ... hasta', which is why the IR keeps `until'
tr_comps_out(english, [pp(w(from, C1), NP1), pp(w(until, C2), NP2)|Cs], Noun, Number, Clitics, Outs, Advs) :- !,
    tr_comps_out(english, [pp(w(from, C1), NP1), pp(w(to, C2), NP2)|Cs], Noun, Number, Clitics, Outs, Advs).
%% (and with `e' between them: `già dal 14 aprile e fino al 30 settembre' is from April 14 to September 30)
tr_comps_out(english, [pp(w(from, C1), NP1), cnj(w(and, _)), pp(w(until, C2), NP2)|Cs], Noun, Number, Clitics, Outs, Advs) :- !,
    tr_comps_out(english, [pp(w(from, C1), NP1), pp(w(to, C2), NP2)|Cs], Noun, Number, Clitics, Outs, Advs).
%% ... AND AN ADVERB BETWEEN COMMAS AT THE END OF A CLAUSE IS WRITTEN AFTER THE OTHER ADVERBS, ITS
%% COMMA BEFORE IT: `Il cane sembra lontano, comunque' seems far, anyway -- English writes its adverbs
%% after the other complements and the commas where they stood, so it was `seems, far anyway'
tr_comps_out(english, [sep, adv(w(A, C))|Cs0], Noun, Number, Clitics, Outs, [o(',', comma), o(AT, C)|Advs]) :-
    forall(member(X, Cs0), memberchk(X, [sep, subj_here])), !,
    tr_word_across(w(A, lower), english, adverb, AT),
    exclude(==(sep), Cs0, Cs),
    tr_comps_out(english, Cs, Noun, Number, Clitics, Outs, Advs).
%% ... AND A DURATION WITH AN ADVERB BEFORE IT: `per circa un minuto' reads the
%% adverb as the phrase of `for' and the minute as a time of its own, so the
%% word for a duration (tr_span_word/2) stands before both
tr_comps_out(foreign, [pp(w(for, C), adv(w(A, AC))), at_time(NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_span_word(NP, PT), !,
    tr_word_across(w(A, lower), foreign, adverb, AT),
    tr_np_out(foreign, NP, NOut, _, _),
    tr_comps_out(foreign, Cs, Noun, Number, Clitics, Outs1, Advs),
    append([[o(PT, C), o(AT, AC)], NOut, Outs1], Outs).
%% THE OBJECT AFTER AN INFINITIVE IS THE INFINITIVE'S, and what English puts
%% before it is that verb's: `mi ha chiesto di indicargli un'edicola' asked me
%% to indicate a kiosk to him, and with the verb of asking still the one
%% written it came out `to indicate him for a kiosk' (en_object_with/2)
%% ... and the phrase of `to' after the adjective of `remains' is the
%% adjective's: `rimase fedele al partito' remained faithful TO the party,
%% never `at' it (en_place_np/2 is the verb's)
tr_comps_out(english, [adj(Ws), pp(w(to, C), NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_global('$tr_verb', V), atom(V), memberchk(V, [arrives, remains, stays]), !,
    tr_comp_out(english, adj(Ws), Noun, Number, Cl1, O1, A1),
    tr_np_out(english, NP, NPOut, _, _),
    tr_comps_out(english, Cs, Noun, Number, Cl3, O3, A3),
    append(Cl1, Cl3, Clitics), append([O1, [o(to, C)|NPOut], O3], Outs), append(A1, A3, Advs).
%% ... AND THE PERSON AFTER THE INFINITIVE OF A VERB OF TAKING IS A PHRASE OF `FROM', and the pronoun joined to it the
%% thing taken: `recibió una llamada ... para saber el coste de la placa y reclamarlo a la aseguradora del camión' is to
%% claim it FROM the insurer, where with the verb of receiving still the one written English wrote `to demand him to
%% the insurer' (a finite verb of taking had it already, en_takes_from/1)
%% (... and the pronoun joined to the infinitive of a verb of giving, before a phrase of `to', is the thing given:
%% `quiere darlo a Juan' is to give IT to Juan, and it came out `to give him Juan')
tr_comps_out(english, [C0, pp(w(to, PC), NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    C0 = infx(L, A, [w(P, PCase)]), memberchk(P, [him, her, it]),
    tr_lexeme_across(L, english, LT), atom(LT), ( en_takes_from(LT) -> Prep = from ; en_dative_verb(LT), Prep = to ), !,
    tr_comp_out(english, infx(L, A, [w(it, PCase)]), Noun, Number, Cl1, O1, A1),
    tr_np_out(english, NP, NPOut, _, _),
    tr_comps_out(english, Cs, Noun, Number, Cl3, O3, A3),
    append(Cl1, Cl3, Clitics), append([O1, [o(Prep, PC)|NPOut], O3], Outs), append(A1, A3, Advs).
%% (... and the person after the infinitive's object: `reclamar el coste a la aseguradora' is to claim the cost FROM it)
tr_comps_out(english, [C, obj(O), pp(w(to, PC), NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_english_inf_lexeme(C, L), tr_lexeme_across(L, english, LT), atom(LT), en_takes_from(LT), tr_global('$tr_verb', V0), !,
    tr_comp_out(english, C, Noun, Number, Cl1, O1, A1),
    nb_setval('$tr_verb', LT),
    (   tr_comp_out(english, obj(O), Noun, Number, Cl2, O2, A2) -> nb_setval('$tr_verb', V0)
    ;   nb_setval('$tr_verb', V0), fail
    ),
    tr_np_out(english, NP, NPOut, _, _),
    tr_comps_out(english, Cs, Noun, Number, Cl3, O3, A3),
    append([Cl1, Cl2, Cl3], Clitics), append([O1, O2, [o(from, PC)|NPOut], O3], Outs), append([A1, A2, A3], Advs).
tr_comps_out(english, [C, obj(NP)|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_english_inf_lexeme(C, L), tr_lexeme_across(L, english, LT), atom(LT), tr_global('$tr_verb', V0), !,
    tr_comp_out(english, C, Noun, Number, Cl1, O1, A1),
    nb_setval('$tr_verb', LT),
    (   tr_comp_out(english, obj(NP), Noun, Number, Cl2, O2, A2) -> nb_setval('$tr_verb', V0)
    ;   nb_setval('$tr_verb', V0), fail
    ),
    tr_comps_out(english, Cs, Noun, Number, Cl3, O3, A3),
    append([Cl1, Cl2, Cl3], Clitics), append([O1, O2, O3], Outs), append([A1, A2, A3], Advs).
%% a word the source kept before its infinitive (nprep/1) is written, and the infinitive after it takes no other
tr_comps_out(foreign, [nprep(P), I|Cs], Noun, Number, Clitics, Outs, Advs) :-
    ( I = infx(_, _, _) ; I = neg(infx(_, _, _)) ; I = inf(_) ; I = neg(inf(_)) ), !,
    tr_comp_out(foreign, nprep(P), Noun, Number, _, O1, _),
    tr_with_infx_kept(tr_comp_out(foreign, I, Noun, Number, _, O2, _)),
    tr_comps_out(foreign, Cs, Noun, Number, Clitics, O3, Advs), append([O1, O2, O3], Outs).
%% UNDER A MODAL ONLY THE FIRST INFINITIVE IS BARE: `Oggi può capitare di incontrarlo' is it can happen to meet him,
%% and `deve smettere di mangiarlo' must stop to eat it -- the infinitive after the first is the first one's, and with
%% the modal still the verb being written it came out bare, `can happen meet him', `must stop eat him' -- never after a
%% verb that makes, lets or perceives, whose infinitive is bare too (`Nadie puede oírte gritar' is nobody can hear you
%% shout, and `deve avergli fatto cambiare idea' must have made him change his mind)
tr_comps_out(english, [C, D|Cs], Noun, Number, Clitics, Outs, Advs) :-
    tr_en_inf_comp(C, L), tr_en_inf_comp(D, _), tr_modal_verb,
    tr_lexeme_across(L, english, LT), \+ memberchk(LT, [makes, lets, hears, sees, watches, feels, helps]), !,
    tr_comp_out(english, C, Noun, Number, Clitic, Out, Adv),
    nb_getval('$tr_verb', V0), nb_setval('$tr_verb', LT),
    (   tr_comps_out(english, [D|Cs], Noun, Number, Clitics1, Outs1, Advs1) -> nb_setval('$tr_verb', V0)
    ;   nb_setval('$tr_verb', V0), fail
    ),
    append(Clitic, Clitics1, Clitics), append(Out, Outs1, Outs), append(Adv, Advs1, Advs).
tr_comps_out(To, [C|Cs], Noun, Number, Clitics, Outs, Advs) :-
    (   To == foreign, C = obj(NP), Cs = [PP|_], tr_partitive_gender(NP, PP, G)
    ->  tr_with_partitive(G, tr_comp_out(To, C, Noun, Number, Clitic, Out, Adv))
    %% AN ADJECTIVE BEFORE A CLAUSE OF THE VERB'S IS SAID OF THE CLAUSE: `la
    %% "parálisis" institucional hará "necesario" que los vascos acudan' makes
    %% it necessary THAT they go, and agreeing with the subject it came out
    %% `farà "necessaria"'. A clause has no gender, so the masculine singular
    %% -- but never after the copula, whose adjective is the subject's:
    %% `serán neonazis que destrozan la cabeza ...' are neo-Nazis who do, and
    %% taken for the clause's it came out `saranno neonazista'
    ;   To == foreign, C = adj(_), Cs = [that(_)|_], \+ tr_global('$tr_verb', is)
    ->  tr_with_gender(masculine, tr_comp_out(To, C, none, singular, Clitic, Out, Adv))
    ;   To == foreign, Cs = [obj(_)|_], tr_infinitive_comp(C)
    ->  tr_with_inf_obj(tr_comp_out(To, C, Noun, Number, Clitic, Out, Adv))
    %% A PERFECT INFINITIVE AFTER A PREPOSITION IS THE AUXILIARY'S: `dopo aver
    %% mangiato' is `tras haber comido', and `has' written as the verb that
    %% means `has' came out `tras tener comido'
    ;   To == foreign, tr_perfect_before(C, Cs)
    ->  C = pinf(PP, _), tr_comp_out(To, pinf(PP, has_aux), Noun, Number, Clitic, Out, Adv)
    ;   tr_comp_out(To, C, Noun, Number, Clitic, Out, Adv)
    ),
    tr_note_pred(C),
    tr_comps_out(To, Cs, Noun, Number, Clitics1, Outs1, Advs1),
    append(Clitic, Clitics1, Clitics), append(Out, Outs1, Outs), append(Adv, Advs1, Advs).
tr_en_inf_comp(inf(L), L).
tr_en_inf_comp(infx(L, _, _), L).
tr_en_inf_comp(ainf(_, L), L).

en_person_before_inf(V) :-
    memberchk(V, [forbids, prohibits, allows, permits, asks, orders, tells, requests, advises, urges, invites,
                  encourages, forces, obliges, begs]).
en_person_that(V) :- memberchk(V, [reproaches, warns, alerts, tells, informs, assures, reminds, convinces, persuades, notifies]).
tr_range_rest([pp(w(to, _), _)|_]) :- !.
tr_range_rest([pp(w(of, _), _)|Cs]) :- tr_range_rest(Cs).
%% a count after `asks' is how much is asked, and takes no `for' (tr_comps_out/7): `il pm ha chiesto la condanna a otto
%% anni e sei mesi di reclusione' asked for the sentence of eight years, and it came out `has asked eight years and six
%% months for the conviction'
en_counted(np(_, w(_, _), _, _, _)) :- !.
en_counted(co(_, A, _)) :- en_counted(A).
%% the infinitives whose verb English writes before their object (tr_comps_out/7)
tr_english_inf_lexeme(inf(L), L).
tr_english_inf_lexeme(infx(L, _, _), L).
tr_english_inf_lexeme(ainf(_, L), L).
%% (the lesson says the word for `ago' begins a time: its clauses above and
%% tr_fronts_out/5's put the adverb first)
tr_ago_first :- tr_word_across(w(ago, lower), foreign, adverb, AT), tr_solve(begin(AT, time)), !.

%% the gender and the number an object pronoun gives a participle said of it
tr_object_agreement(them, masculine, plural).
tr_object_agreement(her, feminine, singular).
tr_object_agreement(him, masculine, singular).
tr_object_agreement(it, masculine, singular).

tr_comp_out(_, sep, _, _, [], [o(',', comma)], []) :- !.
%% (the phrase set off after the subject with the word for `nor', tr_insertion_off/4: English says `any' where the
%% source denied the phrase again, `nor any federation')
tr_comp_out(To, nor(NP0), _, _, [], Outs, []) :- !,
    (   To == english, NP0 = np(det(determiner, no, w(no, DC)), A, B, Nn, Nb)
    ->  NP = np(det(determiner, any, w(any, DC)), A, B, Nn, Nb)
    ;   NP = NP0
    ),
    tr_connector_out(To, w(nor, lower), CO), tr_np_out(To, NP, NO, _, _), append(CO, NO, Outs).
%% `not only' standing alone before a comma (tr_read0/4): the denial and the word for `only'
tr_comp_out(To, nonly, _, _, [], Outs, []) :- !,
    tr_nonly_words(To, no, NotO, OnlyO, _, _), append(NotO, OnlyO, Outs).
tr_comp_out(_, vq, _, _, [], [], []) :- !.
tr_comp_out(_, vqc, _, _, [], [], []) :- !.
tr_comp_out(_, vqp, _, _, [], [], []) :- !.
tr_comp_out(_, qs, _, _, [], [], []) :- !.
%% a subordinate clause with its connector, a relative clause's front
tr_comp_out(To, sub(C, S), _, _, [], Outs, []) :- !,
    tr_connector_out(To, C, CO), tr_connector_mood(To, CO), tr_write(To, statement, S, SO), append(CO, SO, Outs).
tr_comp_out(_, qe, _, _, [], [], []) :- !.
tr_comp_out(_, suagr, _, _, [], [], []) :- !.               % the adjective is the subject's (tr_adj_subject_comma/3)
tr_comp_out(english, either, _, _, [], [], [o(either, lower)]) :- !.     % `does not sleep either' (tr_write/4)
tr_comp_out(_, phagr, _, _, [], [], []) :- !.               % the participle is the phrase's (tr_pred_after_phrase/4)
tr_comp_out(_, sagr(_), _, _, [], [], []) :- !.            % the subject's gender (tr_clause_gender/4)
%% an adverb with its degree adverb: where the clause's adverbs go, the two
%% side by side -- `tan poco', `so little'
tr_comp_out(To, iadv(w(A, C), w(B, BC)), _, _, [], Outs, Advs) :- !,
    tr_word_across(w(A, lower), To, adverb, AT), tr_word_across(w(B, lower), To, adverb, BT),
    ( To == english -> Outs = [], Advs = [o(AT, C), o(BT, BC)] ; Outs = [o(AT, C), o(BT, BC)], Advs = [] ).
%% a degree adverb before a participle, where no group took it: written where
%% it stands, before the participle of a clause with no verb (`Così amata.')
tr_comp_out(To, gadv(w(A, C)), _, _, [], [o(T, C)], []) :- !, tr_word_across(w(A, lower), To, adverb, T).
tr_comp_out(To, appos(NP), _, _, [], Outs, []) :- !, tr_np_out(To, NP, Outs, _, _).
tr_comp_out(To, qnp(Asked, NP), _, _, [], Outs, []) :- !,
    tr_asked_out(To, Asked, QOut),
    ( NP == none -> NOut = [] ; tr_np_out(To, NP, NOut, _, _) ),
    append(QOut, NOut, Outs).
tr_comp_out(To, topic(NP), _, _, [], Outs, []) :- !, tr_np_out(To, NP, Outs, _, _).
tr_comp_out(_, scomma, _, _, [], [], []) :- !.            % written after the subject (tr_write/4)
%% ENGLISH TAKES A PREPOSITION WHERE SPANISH AND ITALIAN TAKE A PHRASE: `escucho
%% las reivindicaciones' is `I listen to the claims' (en_object_with/2)
tr_comp_out(english, obj(NP), _, _, [], [o(P, lower)|Outs], []) :-
    tr_global('$tr_verb', V), en_object_with(V, P),
    %% (the one asked is no thing asked for: `il gatto chiede a Pedro di dormire' asks Pedro to sleep)
    \+ ( V == asks, ( NP = name(_) ; NP = pronoun(_) ; tr_of_class(NP, person) ) ), !,
    tr_np_out(english, NP, O1, AN, ANb), nb_setval('$tr_ant', a(AN, ANb)),
    tr_marker(english, NP, M), append(M, O1, Outs).
%% A LANGUAGE AFTER A VERB OF LEARNING, TEACHING OR SPEAKING TAKES NO ARTICLE
%% IN ENGLISH: `l'italiano me l'hanno insegnato' taught me Italian, and `the
%% Italian' was the man (tr_marker/3 keeps Spanish's `a' off it the same way)
tr_comp_out(english, obj(np(det(article, the, _), none, [], w(L, C), singular)), _, _, [], Outs, []) :-
    en_language(L), tr_global('$tr_verb', V), en_language_verb(V), !,
    tr_np_out(english, np(none, none, [], w(L, C), singular), Outs, AN, ANb), nb_setval('$tr_ant', a(AN, ANb)).
%% TWO OBJECTS JOINED, ONE OF THEM A PERSON: the word the lesson puts before a person goes before that one alone --
%% `contraddire sé stesso e le parole dell'imputato' is `contradecir a sí mismo y las palabras del imputado'. Asked of
%% the two together, the pair was no person and neither took it
tr_comp_out(foreign, obj(co(K, A, B)), _, _, [], Outs, []) :-
    \+ tr_of_class(co(K, A, B), person),
    tr_joined_marker(A, MA), tr_joined_marker(B, MB), ( MA \== [] ; MB \== [] ), !,
    tr_np_out(foreign, A, OA, _, _), tr_np_out(foreign, B, OB, _, _), nb_setval('$tr_ant', a(none, plural)),
    tr_connector_out(foreign, K, KO), append([MA, OA, KO, MB, OB], Outs).
tr_comp_out(To, obj(NP), _, _, [], Outs, []) :-
    tr_np_out(To, NP, O1, AN, ANb), nb_setval('$tr_ant', a(AN, ANb)),      % what an `of which' after it agrees with
    tr_marker(To, NP, M), append(M, O1, Outs).
tr_comp_out(To, adj(Ws), Noun, Number, [], Outs, []) :- tr_adjectives_out(To, Ws, Noun, Number, As), tr_adj_words(As, Outs).
%% an object complement: the adjectives agree with the OBJECT, whose noun
%% and number tr_np_out/5 answers, and they go before the object in the
%% lesson's language and after it in English
tr_comp_out(To, oc(NP, Ws), _, _, [], Outs, []) :-
    tr_np_out(To, NP, O1, Noun, Number), tr_marker(To, NP, M), append(M, O1, Obj),
    tr_adjectives_out(To, Ws, Noun, Number, As), tr_adj_words(As, AOut),
    ( To == english -> append(Obj, AOut, Outs) ; append(AOut, Obj, Outs) ).
%% a `that' clause: the word, and the clause written as a statement
tr_comp_out(To, paren(Inner), _, _, [], Outs, []) :- !, tr_aside_out(To, paren, Inner, Outs).
tr_comp_out(To, comment(Inner), _, _, [], Outs, []) :- !, tr_aside_out(To, comment, Inner, Outs).
%% an absolute clause: the participle, agreeing with its phrase, and the phrase
%% (English's preposition where it has one for the participle: `a los representantes corsos, incluidos los
%% nacionalistas' is including the nationalists, and it was `included the nationalists')
tr_comp_out(To, abs(L, NP), _, _, [], [o(PP, lower)|NO], []) :- !,
    tr_np_out(To, NP, NO, Noun, Number),
    (   To == english -> en_participle_of(L, PP0), ( en_participle_preposition(PP0, PP) -> true ; PP = PP0 )
    ;   tr_lexeme_across(L, foreign, LT), tr_gender(Noun, G0),
        ( G0 == none -> G = masculine ; G = G0 ),
        tr_with_gender(G, tr_participle_agreeing(LT, Number, PP))
    ).
%% ... and the one that says how the verb leaves its phrase (abso/2, tr_abs_first/2):
%% English writes the phrase and then the participle -- `mantiene bloqueado el
%% convenio' keeps the agreement blocked, `tiene levantado el brazo' has the arm
%% raised, never `keeps blocked the agreement' -- unless the participle is one
%% English puts before a phrase as a preposition (`given', `seen')
tr_comp_out(english, abso(L, NP), _, _, [], Outs, []) :-
    en_participle_of(L, PP), \+ en_prepositional_participle(PP), !,
    tr_np_out(english, NP, NO, _, _), append(NO, [o(PP, lower)], Outs).
tr_comp_out(To, abso(L, NP), N, Nb, Cl, Outs, As) :- !, tr_comp_out(To, abs(L, NP), N, Nb, Cl, Outs, As).
%% who said so, with the word for `as' and the comma before it where it had one
tr_comp_out(To, per(Lead, CC, S), _, _, [], Outs, []) :- !,
    tr_connector_out(To, cmt(w(as, CC)), CO), tr_write(To, statement, S, SO),
    (   Lead == comma -> append([[o(',', comma)], CO, SO], Outs)
    ;   Lead == dash -> append([[o('–', lower)], CO, SO, [o('–', lower)]], Outs)
    ;   append(CO, SO, Outs)
    ).
%% (and of a plain infinitive the same: `ha accusato le donne di non dormire' is `de no dormir', and with the denial
%% written first and the word by the infinitive's writer it came out `no de dormir')
tr_comp_out(foreign, neg(C), Noun, Number, [], Outs, []) :- ( C = infx(_, _, _) ; C = inf(_) ), tr_infx_lead(P), !,  % `de no haber ...'
    tr_negation_word(No), tr_with_infx_kept(tr_comp_out(foreign, C, Noun, Number, [], Outs0, [])),
    Outs = [o(P, lower), o(No, lower)|Outs0].
%% ... and English's `not' after the preposition a gerund takes: `ha accusato le donne di non essersi evolute' accused
%% them OF NOT having evolved, where it was `not of having evolved'
tr_comp_out(english, neg(C), Noun, Number, [], Outs, []) :- tr_verbal_inf(C), tr_en_prep_gerund(Pr), !,
    tr_comp_out(english, C, Noun, Number, [], Outs0, []),
    ( Outs0 = [o(Pr, PC)|R] -> Outs = [o(Pr, PC), o(not, lower)|R] ; Outs = [o(not, lower)|Outs0] ).
tr_comp_out(To, neg(C), Noun, Number, [], [o(No, lower)|Outs], []) :- !,
    ( To == english -> No = not ; tr_negation_word(No) ),
    tr_comp_out(To, C, Noun, Number, [], Outs, []).
%% ... and after its phrase, the lesson's word for `no' (nega/1): `e i
%% semplici no', `y los simples no' -- and English's `not' before it
tr_comp_out(english, nega(sub(NP)), _, _, [], [o(not, lower)|Outs], []) :- !,
    tr_np_out(english, NP, Outs, _, _).
tr_comp_out(foreign, nega(sub(NP)), _, _, [], Outs, []) :- !,
    tr_word_across(w(no, lower), foreign, adverb, No),
    tr_np_out(foreign, NP, Outs0, _, _), append(Outs0, [o(No, lower)], Outs).
tr_comp_out(english, nega(C), Noun, Number, [], [o(not, lower)|Outs], []) :- !,
    tr_comp_out(english, C, Noun, Number, [], Outs, []).
tr_comp_out(foreign, nega(C), Noun, Number, [], Outs, []) :- !,
    tr_word_across(w(no, lower), foreign, adverb, No),
    tr_comp_out(foreign, C, Noun, Number, [], Outs0, []), append(Outs0, [o(No, lower)], Outs).
%% a noun's preposition before its infinitive: the lesson's word, and none
%% in English, whose infinitive has its own `to' -- except after a modal, whose
%% bare infinitive leaves the noun's none: `dovrebbe essere la gente a giudicarmi'
%% is `it should be the people TO judge me'
tr_comp_out(english, nprep(_), _, _, [], Outs, []) :- !, ( tr_modal_verb -> Outs = [o(to, lower)] ; Outs = [] ).
tr_comp_out(foreign, nprep(w(P, C)), _, _, [], [o(PT, C)], []) :- !, tr_word_across(w(P, lower), foreign, preposition, PT).
%% as much as: English's own words, and the lesson's pair for both ... and
tr_comp_out(english, asmuch(NP), _, _, [], [o(as, lower), o(much, lower), o(as, lower)|NPOut], []) :- !,
    tr_np_out(english, NP, NPOut, _, _).
tr_comp_out(foreign, asmuch(NP), _, _, [], [o(B, lower), o(P, lower)|NPOut], []) :- !,
    tr_both_pair(foreign, B, P), tr_np_out(foreign, NP, NPOut, _, _).
%% a comparison: English's `than' or `as', and the lesson's word for `than'
tr_comp_out(english, cmp(K, NP), _, _, [], [o(W, lower)|NPOut], []) :- !,
    ( K == equal -> W = as ; W = than ), tr_np_out(english, NP, NPOut, _, _).
tr_comp_out(foreign, cmp(_, NP), _, _, [], [o(W, lower)|NPOut], []) :- !,
    tr_than_word(phrase, W), tr_np_out(foreign, NP, NPOut, _, _).
%% ... and before a clause, English's `than' and the lesson's word for `than
%% what' (`di quanto', `de lo que')
%% ... AND A CLAUSE THAT NAMES NOBODY AND HAS NO OBJECT IS SAID OF WHAT IS COMPARED: `el debate va mejor en privado de
%% lo que trasciende' is better than what transpires -- the clause's subject is the thing compared, and with nobody
%% named English refused the sentence; a verb English says with `it' keeps it (`than it seems')
tr_comp_out(english, cmpc(K, s(A, null(third, N), G, Cs)), _, _, [], [o(W, lower)|SOut], []) :-
    G = g(L, _, _, _), atom(L), \+ memberchk(obj(_), Cs), \+ en_null_it(L, Cs), !,
    ( K == equal -> W = as ; W = than ),
    tr_write_nested(english, s(A, np(none, none, [], w(what, lower), N), G, Cs), SOut).
tr_comp_out(english, cmpc(K, S), _, _, [], [o(W, lower)|SOut], []) :- !,
    ( K == equal -> W = as ; W = than ), tr_write_nested(english, S, SOut).
tr_comp_out(foreign, cmpc(_, S), _, _, [], [o(W, lower)|SOut], []) :- !,
    once(tr_solve(mean(W, 'than what'))), tr_write_nested(foreign, S, SOut).
%% ... and before a preposition, the lesson's conjunction for `than'
%% (an adverb term is written where it stands, after `as' or `than': `in the
%% same conditions as currently' -- English's adverbs otherwise go last)
tr_comp_out(english, cmpp(A, K, adv(w(AW2, AC2))), _, _, [], Outs, []) :- !,
    ( A = w(AW, AC) -> AO = [o(AW, AC)] ; AO = [] ),
    ( K == equal -> W = as ; W = than ),
    append(AO, [o(W, lower), o(AW2, AC2)], Outs).
tr_comp_out(english, cmpp(A, K, PP), N, Nb, [], Outs, []) :- !,
    ( A = w(AW, AC) -> AO = [o(AW, AC)] ; AO = [] ),
    ( K == equal -> W = as ; W = than ), tr_comp_out(english, PP, N, Nb, [], PPO, []),
    append(AO, [o(W, lower)|PPO], Outs).
tr_comp_out(foreign, cmpp(A, _, PP), N, Nb, [], Outs, []) :- !,
    ( A = w(AW, AC) -> tr_word_across(w(AW, lower), foreign, adverb, AT), AO = [o(AT, AC)] ; AO = [] ),
    tr_than_word(adjective, W), tr_comp_out(foreign, PP, N, Nb, [], PPO, []),
    append(AO, [o(W, lower)|PPO], Outs).
%% ... and before an infinitive and its complements, the same words
tr_comp_out(english, cmpi(K, Cs), Noun, Number, [], [o(W, lower)|COut], []) :- !,
    ( K == equal -> W = as ; W = than ),
    tr_comps_out(english, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut).
tr_comp_out(foreign, cmpi(_, Cs), Noun, Number, [], [o(W, lower)|COut], []) :- !,
    tr_than_word(adjective, W),
    tr_comps_out(foreign, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut).
%% more than an adjective: `more than questionable', `più che discutibile'
tr_comp_out(english, mt(Ws), Noun, Number, [], [o(more, lower), o(than, lower)|Outs], []) :- !,
    tr_adjectives_out(english, Ws, Noun, Number, As), tr_adj_words(As, Outs).
tr_comp_out(foreign, mt(Ws), Noun, Number, [], [o(M, lower), o(T, lower)|Outs], []) :- !,
    tr_degree_out(M), tr_than_word(adjective, T),
    tr_adjectives_out(foreign, Ws, Noun, Number, As), tr_adj_words(As, Outs).
%% ... an infinitive with its pronouns: English's -ing form and the object
%% pronouns after it, the lesson's infinitive with its own joined to it --
%% a dative as the lesson's dative (`chiedergli')
%% ... with the quotation mark that opened on it (qm/2 on a complement's
%% first word, qinf/2 on a preposition's infinitive)
%% (on an infinitive the mark goes on the infinitive, after the word its verb takes: `di "fare trappola"', `of
%% "making trap"')
tr_comp_out(To, qm(QC0, inf(L)), N, Nb, Cl, Outs, A) :- !,
    ( QC0 = bare(QC) -> Bare = yes ; QC = QC0, Bare = no ),
    ( Bare == no, tr_inf_lead_word(To, Lead0) -> Lead = Lead0 ; Lead = none ),      % (asked first: the writer sets its own verb)
    tr_comp_out(To, inf(L), N, Nb, Cl, Outs0, A),
    (   Bare == no, Outs0 = [O1, o(W2, _)|R], O1 = o(W1, _), ( W1 == Lead ; To == english, W1 == to ) -> Outs = [O1, o(W2, QC)|R]
    %% (a mark that opens and closes on the infinitive alone, `lo que hace es "desacreditar" la investigación', is
    %% around all the words written for it: `"to discredit"', where it came out `"to" discredit')
    ;   Bare == yes, QC == qboth, Outs0 = [o(W1, _)|R0], append(Mid, [o(Wn, _)], R0) -> append([o(W1, qopen)|Mid], [o(Wn, qclose)], Outs)
    ;   Outs0 = [o(W, _)|R] -> Outs = [o(W, QC)|R]
    ;   Outs = Outs0
    ).
tr_comp_out(To, qm(QC, C), N, Nb, Cl, Outs, A) :- !,
    tr_comp_out(To, C, N, Nb, Cl, Outs0, A),
    ( Outs0 = [o(W, _)|R] -> Outs = [o(W, QC)|R] ; Outs = Outs0 ).
tr_comp_out(To, qm2(QC, C), N, Nb, Cl, Outs, A) :- !,
    tr_comp_out(To, C, N, Nb, Cl, Outs0, A),
    ( Outs0 = [O1, o(W, _)|R] -> Outs = [O1, o(W, QC)|R] ; Outs = Outs0 ).
tr_comp_out(To, pinf(P, qinf(QC, L)), N, Nb, Cl, Outs, A) :- !,
    tr_comp_out(To, pinf(P, L), N, Nb, Cl, Outs0, A),
    ( Outs0 = [O1, o(W, _)|R] -> Outs = [O1, o(W, QC)|R] ; Outs = Outs0 ).
tr_comp_out(To, ainf(P, qinf(QC, L)), N, Nb, Cl, Outs, A) :- !,
    tr_comp_out(To, ainf(P, L), N, Nb, Cl, Outs0, A),
    ( Outs0 = [O1, o(W, _)|R] -> Outs = [O1, o(W, QC)|R] ; Outs = Outs0 ).
tr_comp_out(foreign, pinf(w(P, C), has_aux), _, _, [], [o(PT, C), o(Inf, lower)], []) :- !,
    tr_word_across(w(P, lower), foreign, preposition, PT), tr_lexeme_across(has, foreign, LT0),
    ( tr_auxiliary(has, Aux), Aux \== LT0 -> LT = Aux ; LT = LT0 ),
    once(tr_solve(infinitive_of(Inf0, LT))), tr_joined_infinitive(Inf0, [], Inf),
    tr_infinitive_verb(has).
%% A PREPOSITION AND A PERFECT INFINITIVE: `of having tested positive', `por
%% haber dado positivo'. English writes the gerund of `have' and the
%% participle; the lesson's language writes its preposition -- a cause's word
%% for English's `for' (`per', `por', not the purpose's `para') -- and the
%% perfect infinitive the way infx/3 does
tr_comp_out(english, pinf(w(P, C), perf(L, Cls)), _, _, [], [o(PT, C), o(having, lower), o(PP, lower)|Objs], []) :- !,
    tr_word_across(w(P, lower), english, preposition, PT), tr_lexeme_across(L, english, LT), en_participle_of(LT, PP),
    findall(o(T, lower), ( member(W, Cls), ( W = w(T, _) ; W = dat(w(T, _)) ) ), Objs).
tr_comp_out(foreign, pinf(w(P, C), perf(L, Cls)), N, Nb, Cl, [o(PT, C)|Outs], A) :- !,
    (   P == for, once(tr_solve(begin(PT0, cause))) -> PT = PT0
    ;   tr_word_across(w(P, lower), foreign, preposition, PT)
    ),
    tr_comp_out(foreign, infx(L, perfect, Cls), N, Nb, Cl, Outs, A).
tr_comp_out(english, pinf(w(P, C), cl(L, Cls)), _, _, [], [o(PT, C), o(G, lower)|Objs], []) :- !,
    tr_word_across(w(P, lower), english, preposition, PT), tr_lexeme_across(L, english, LT),
    en_gerund_of(LT, G),
    findall(o(T, lower), ( member(X, Cls), ( X = dat(w(T, _)) -> true ; X = w(T, _) ) ), Objs).
tr_comp_out(foreign, pinf(w(P, C), cl(L, Cls)), _, _, [], [o(PT, C), o(Inf, lower)], []) :- !,
    tr_word_across(w(P, lower), foreign, preposition, PT), tr_lexeme_across(L, foreign, LT),
    findall(F, ( member(X, Cls), tr_pinf_clitic_out(X, F) ), Ps),
    once(tr_solve(infinitive_of(Inf0, LT))), tr_joined_infinitive(Inf0, Ps, Inf),
    tr_infinitive_verb(L).
%% (after a noun English says with `to', `of' and the -ing form are `to' and the infinitive: `Il tentativo di trovare le
%% forze primordiali' is the attempt to find them, and it was `the attempt of finding')
tr_comp_out(english, pinf(w(of, C), L), Noun, _, [], [o(to, C), o(B, lower)], []) :-
    atom(Noun), en_noun_to_inf(Noun), atom(L), tr_lexeme_across(L, english, LT), atom(LT), en_base(LT, B), !.
%% (... and after a verb English says with its own preposition and the gerund, that preposition: `responsabilizaba
%% a un sector del PNV de poner trabas' blames it FOR hindering, where the source's `de' came out `of hindering')
tr_comp_out(english, pinf(w(of, C), L), _, _, [], [o(Pr, C), o(G, lower)], []) :-
    atom(L), tr_en_prep_gerund(Pr), Pr \== of, tr_lexeme_across(L, english, LT), atom(LT), en_gerund_of(LT, G), !.
tr_comp_out(english, pinf(w(P, C), L), _, _, [], [o(PT, C), o(G, lower)], []) :- !,
    tr_word_across(w(P, lower), english, preposition, PT), tr_lexeme_across(L, english, LT0),
    ( LT0 = reflexive(LT) -> true ; LT = LT0 ),                  % English has no reflexive there
    en_gerund_of(LT, G).
tr_comp_out(foreign, pinf(w(P, C), L), _, _, [], [o(PT, C), o(Inf, lower)], []) :- !,
    tr_word_across(w(P, lower), foreign, preposition, PT), tr_lexeme_across(L, foreign, LT0),
    ( LT0 = reflexive(LT) -> tr_reflexive_out(R), Ps = [R] ; LT = LT0, Ps = [] ),
    once(tr_solve(infinitive_of(Inf0, LT))), tr_joined_infinitive(Inf0, Ps, Inf),
    tr_infinitive_verb(L).
%% ... after the word the verb takes before a clause, where the lesson
%% states one: `sin darse cuenta DE que ...', `"da cuenta" takes "de" before
%% the clause.'
%% ENGLISH SAYS WHAT IS WANTED OF SOMEBODY WITH THE PERSON AND AN INFINITIVE,
%% never with a clause of `that': `quieren que los abogados sean retribuidos'
%% is `they want the lawyers to be rewarded', and it came out `they want
%% that the lawyers are rewarded'. After a verb of wanting, and after a verb of
%% asking when the one asked is a person (en_raising_verb/2); a clause with
%% an aspect, a tense of its own or a subject nobody named in the third person
%% stays a clause
tr_comp_out(english, that(s(none, Subject, g(L, T, A, Neg), Cs)), _, _, [], Outs, []) :-
    atom(L), memberchk(A, [simple, passive]), memberchk(T, [present, past, imperfect]),
    tr_global('$tr_verb', V), atom(V), en_raising_verb(V, Kind),
    tr_raised_subject(Subject, Kind, SOut),
    tr_lexeme_across(L, english, LT), atom(LT),
    (   A == passive -> en_participle_of(LT, PP), Vb = [o(be, lower), o(PP, lower)]
    ;   en_base(LT, B), Vb = [o(B, lower)]
    ),
    ( Neg == no -> To = [o(to, lower)] ; To = [o(not, lower), o(to, lower)] ),
    ( tr_global('$tr_denied', D0) -> true ; D0 = no ), nb_setval('$tr_denied', Neg), nb_setval('$tr_verb', L),
    (   tr_comps_out(english, Cs, none, singular, [], COuts, Advs)
    ->  nb_setval('$tr_denied', D0), nb_setval('$tr_verb', V)
    ;   nb_setval('$tr_denied', D0), nb_setval('$tr_verb', V), fail
    ),
    append([SOut, To, Vb, COuts, Advs], Outs), !.
tr_comp_out(To, that_open, _, _, [], [o(W, lower)], []) :- !, tr_that_word(To, W).
%% a result clause (tr_result_clause/3): the word for `that' and the clause, whose subject is the
%% main clause's -- English names it, `they' for a plural and `it' for a thing, where the lesson's
%% languages leave it out with the verb agreeing
tr_comp_out(To, res(S0, P), _, _, [], Outs, []) :- !,
    (   To == english, S0 = s(A, null(third, singular), G, Cs) -> S = s(A, pronoun(third, singular, w(P, lower)), G, Cs)
    ;   S = S0
    ),
    tr_that_word(To, W), tr_write_nested(To, S, SOut), Outs = [o(W, lower)|SOut].
tr_comp_out(To, that(S), _, _, [], Outs, []) :- !,
    ( To == foreign, tr_verb_takes(P, clause) -> Pre = [o(P, lower)] ; Pre = [] ),
    ( To == foreign, tr_global('$tr_that_mood', sbj) -> nb_setval('$tr_sbj', sbj) ; nb_setval('$tr_sbj', ind) ),
    tr_that_word(To, W), tr_write_nested(To, S, SOut),
    nb_setval('$tr_sbj', ind),
    append(Pre, [o(W, lower)|SOut], Outs).
%% a cleft whose focus is a gerund (tr_complements0/4): the gerund, the word
%% for `that' and the clause, as they stood
tr_comp_out(To, cleft(Ger, S), Noun, Number, [], Outs, []) :- !,
    tr_comp_out(To, Ger, Noun, Number, [], GOut, []),
    tr_that_word(To, W), tr_write_nested(To, S, SOut),
    append(GOut, [o(W, lower)|SOut], Outs).
%% a participle in front with its agent (tr_read0/4, fpart/4): written as a
%% participle aside is, without the aside's commas -- a front's comma comes
%% after it
tr_comp_out(To, fpart(L, G, N, Cs), _, _, [], Outs, []) :- !,
    tr_aside_out(To, front, part(L, [agr(G), agrn(N)|Cs]), none, N, Outs0),
    append([o(',', comma)|Outs], [o(',', comma)], Outs0).
%% ... and one whose subject is a relative clause's gap, with no word for
%% `that' (tr_relative_clause/4): `che spero si concretizzi'
tr_comp_out(To, thatg(S), _, _, [], SOut, []) :- !, tr_write_nested(To, S, SOut).
%% (two prepositions joined before one phrase, tr_complements0/4's pp2/4)
tr_comp_out(To, pp2(w(P1, C1), w(K, KC), w(P2, C2), NP), _, _, [], [o(T1, C1), o(KT, KC), o(T2, C2)|NPOut], []) :- !,
    ( To == english -> T1 = P1, T2 = P2, KT = K
    ; tr_word_across(w(P1, lower), To, preposition, T1), tr_word_across(w(P2, lower), To, preposition, T2),
      tr_word_across(w(K, lower), To, conjunction, KT)
    ),
    tr_np_out(To, NP, NPOut, _, _).
%% (`whether' and an infinitive: `scegliere se fare ... o mantenere ...', whether
%% to be ... or to keep, and the lesson's `se' before its infinitive)
tr_comp_out(To, whinf(Cs), Noun, Number, [], [o(W, lower)|COut], []) :- !,
    ( To == english -> W = whether ; once(( tr_solve(mean(W, if)), tr_class_of(W, conjunction) )) ),
    %% (under no verb of the clause's: after a modal English's infinitive is bare, and
    %% `whether' takes `to', `must choose whether to sleep')
    tr_global('$tr_verb', V0), nb_setval('$tr_verb', none),
    (   tr_comps_out(To, Cs, Noun, Number, _, CO, CA) -> nb_setval('$tr_verb', V0)
    ;   nb_setval('$tr_verb', V0), fail
    ),
    append(CO, CA, COut).
%% (`whether' is English's own, and the lesson's word for `if' says it)
tr_comp_out(To, wh(whether, S), _, _, [], [o(W, lower)|SOut], []) :- !,
    ( To == english -> W = whether ; once(( tr_solve(mean(W, if)), tr_class_of(W, conjunction) )) ),
    tr_write_nested(To, S, SOut).
%% `which', by itself or with its phrase and the preposition before it, in the
%% number the phrase has: `quali' and `qué', but English's `which' for both
%% (`what' and the infinitive of `makes' with nothing made after it is what to DO: `quisiera saber qué hacer para
%% iniciarme en el satanismo', where English wrote `what to make to begin')
tr_comp_out(english, wh(what, s(A, none, g(makes, T, infinitive, N), Cs)), Noun, Number, Cl, Outs, Advs) :-
    \+ ( member(C, Cs), C \= purpose(_), tr_makes_made(C) ), !,
    tr_comp_out(english, wh(what, s(A, none, g(does, T, infinitive, N), Cs)), Noun, Number, Cl, Outs, Advs).
tr_comp_out(To, wh(which(N), S), _, _, [], [o(W, lower)|SOut], []) :- !,
    tr_which_pronoun_number(To, N, W), tr_write_nested(To, S, SOut).
tr_comp_out(To, wh(which_np(NP, C), S), _, _, [], Outs, []) :- !,
    tr_which_np_out(To, NP, NPOut, _, Number), tr_which_word_number(To, Number, QT),
    tr_write_nested(To, S, SOut), append([o(QT, C)|NPOut], SOut, Outs).
tr_comp_out(To, wh(pp(w(P, PC), which_np(NP, C)), S), _, _, [], Outs, []) :- !,
    ( To == english -> PT = P ; tr_word_across(w(P, lower), To, preposition, PT) ),
    tr_which_np_out(To, NP, NPOut, _, Number), tr_which_word_number(To, Number, QT),
    tr_write_nested(To, S, SOut), append([o(PT, PC), o(QT, C)|NPOut], SOut, Outs).
%% (English's `who' after a preposition is `whom': `with whom I had to speak')
tr_comp_out(english, wh(pp(w(P, PC), who), S), _, _, [], [o(P, PC), o(whom, lower)|SOut], []) :- !,
    tr_write_nested(english, S, SOut).
%% (and `what' after a preposition leaves the preposition after its clause: `what the IOC is speaking of' -- with the
%% quotation's closing mark the source's last word carried, which English writes before the verb, on the word or as its
%% case: `"I ignore what the IOC is speaking of",', and `"Ignoro de qué habla el perro", dijo Pedro' was `"I ignore what
%% the dog speaks" of')
tr_comp_out(english, wh(pp(w(P, PC), what), S), _, _, [], [o(what, lower)|Outs], []) :- !,
    tr_write_nested(english, S, SOut),
    (   append(Front, [o(L, LC)|Back], SOut), atom(L), atom_concat(L0, '"', L)
    ->  atom_concat(P, '"', PQ), append([Front, [o(L0, LC)|Back], [o(PQ, PC)]], Outs)
    ;   append(Front, [o(L, LC)|Back], SOut), tr_what_mark_off(LC, LC1, PC, PC1)
    ->  append([Front, [o(L, LC1)|Back], [o(P, PC1)]], Outs)
    ;   append(SOut, [o(P, PC)], Outs)
    ).
tr_comp_out(To, wh(pp(w(P, PC), Q), S), _, _, [], [o(PT, PC), o(W, lower)|SOut], []) :- atom(Q), !,
    ( To == english -> PT = P ; tr_word_across(w(P, lower), To, preposition, PT) ),
    tr_question_across(To, _, Q, W), tr_write_nested(To, S, SOut).
tr_comp_out(To, wh(Q, S), _, _, [], Outs, []) :- !,
    ( tr_wh_preposition(To, P) -> Pre = [o(P, lower)] ; Pre = [] ),
    tr_question_across(To, _, Q, W), tr_write_nested(To, S, SOut),
    append(Pre, [o(W, lower)|SOut], Outs).
%% a relative clause standing alone, said of what the clause before it named
%% (tr_read0/4): the relative word and the clause, `pero que ha demostrado'
tr_comp_out(To, rcl(Role, S), _, _, [], Outs, []) :- !,
    tr_relative_out(To, Role, none, singular, RO), tr_write_nested(To, S, SOut), append(RO, SOut, Outs).
%% ... and one that comments on the clause before it (crel/2): English's
%% `which', and the lesson's words for it, `il che'
tr_comp_out(english, crel(_, S), _, _, [], [o(which, lower)|SOut], []) :- !, tr_write_nested(english, S, SOut).
tr_comp_out(foreign, crel(_, S), _, _, [], Outs, []) :- !,
    (   tr_solve(remark(J)), atomic_list_concat(Ws, ' ', J), Ws = [_, _|_]
    ->  findall(o(W, lower), member(W, Ws), RO)
    ;   tr_relative_that(R), RO = [o(R, lower)]
    ),
    tr_write_nested(foreign, S, SOut), append(RO, SOut, Outs).
%% ... and one said of the object before what stands between (rca/2): the
%% relative word agreeing with that object, as `of which' does
tr_comp_out(To, rca(Role, S), _, _, [], Outs, []) :- !,
    tr_global('$tr_ant', A), ( A = a(AN, ANb) -> true ; AN = none, ANb = singular ),
    tr_relative_out(To, Role, AN, ANb, RO), tr_write_nested(To, S, SOut), append(RO, SOut, Outs).
%% the comment of `as' after a phrase (tr_relative_wh_after/3): the word a comment
%% opens with, and its clause
tr_comp_out(To, cmtc(S), _, _, [], Outs, []) :- !,
    tr_connector_out(To, cmt(w(as, lower)), CO), tr_write_nested(To, S, SOut), append(CO, SOut, Outs).
%% the relative one: a conjunction the lesson gives the meaning, before the
%% question word -- `donde' before `dónde'
tr_comp_out(To, asrwh(Q, S), N, Nb, [], Outs, []) :- !,          % `come quando', `as when'
    tr_connector_out(To, cmt(w(as, lower)), CO),
    tr_comp_out(To, rwh(Q, S), N, Nb, [], ROut, []), append(CO, ROut, Outs).
%% (English says where to do a thing after a phrase with `in which': `un tablón donde dejar anuncios' is a board in
%% which to leave ads, where `a board where to leave ads' was written; after a verb it asks, `where to sleep')
tr_comp_out(english, rwh(where, S), _, _, [], [o(in, lower), o(which, lower)|SOut], []) :-
    S = s(_, none, g(_, _, infinitive, _), _), !, tr_write_nested(english, S, SOut).
tr_comp_out(To, rwh(Q, S), _, _, [], [o(W, lower)|SOut], []) :- !,
    (   To == foreign, tr_solve(mean(W0, Q)), tr_class_of(W0, conjunction) -> W = W0
    ;   tr_question_across(To, _, Q, W)
    ), !, tr_write_nested(To, S, SOut).

%% ... written after its preposition, agreeing with the object before it
tr_comp_out(To, rpp(w(P, C), NP), _, _, [], Outs, []) :- !,
    tr_global('$tr_ant', A), ( A = a(AN, ANb) -> true ; AN = none, ANb = singular ),
    tr_relative_out(To, pp(w(P, C)), AN, ANb, RO),
    tr_np_out(To, NP, NO, _, _), append(RO, NO, Outs).
%% ... AND THE PLACE'S PREPOSITION IS `IN', not Italian's `a': `è a Milano',
%% `estoy en Milano' -- the clause the state's copula is written for, with a
%% name for the place (tr_verb_out/4)
tr_comp_out(foreign, pp(w(to, C), name(N)), _, _, [], [o(PT, C)|NPOut], []) :-
    tr_global('$tr_verb', is), tr_state_plain(_), !,
    tr_word_across(w(in, lower), foreign, preposition, PT), tr_np_out(foreign, name(N), NPOut, _, _).
%% ... AND A PHRASE THE VERB GOVERNS (gov/1) TAKES THE PREPOSITION THE VERB BEING
%% WRITTEN TAKES BEFORE A PHRASE, where the lesson states one
%% -- and NONE where the English verb takes its object bare: `la possibilità di
%% incidere sulle scelte' is of influencing the choices (`"incide" takes "su"
%% before the phrase.'), never `influencing on' them
%% (a bare singular noun keeps its preposition, tr_bare_singular/1: it says how, and is no
%% object -- `abbiamo risposto a tema' answered to the point, and taken bare it came out
%% `answered topic' and `hemos contestado tema')
tr_comp_out(english, pp(w(_, _), gov(V, NP)), _, _, [], NPOut, []) :- en_bare_object(V), \+ tr_bare_singular(NP), !,
    tr_np_out(english, NP, NPOut, _, _).
%% THE ONE WHO IS FED IS THE OBJECT OF `FEEDS': `per dare da mangiare al bambino' is to feed the child, and the lesson's
%% `to' before the person came out `to feed to the boy' -- after the verb, and after a purpose that is the verb
tr_comp_out(english, pp(w(to, _), NP), _, _, [], NPOut, []) :-
    tr_global('$tr_verb', V), atom(V), en_bare_person_verb(V), !, tr_np_out(english, NP, NPOut, _, _).
%% ... AND `FOR THE PAST' BEFORE A BARE PLURAL IS `FOR': `Córcega, sacudida desde hace años por los atentados' is shaken
%% for years, and English said `for the past years'; with a count it stays, `for the past three years'
tr_comp_out(english, pp(w('for the past', C), NP), A3, A4, A5, Outs, A7) :-
    NP = np(none, none, [], w(_, _), plural), !,
    tr_comp_out(english, pp(w(for, C), NP), A3, A4, A5, Outs, A7).
tr_comp_out(english, pp(w(P, C), gov(V, NP)), _, _, [], [o(PT, C)|NPOut], []) :- !,
    ( en_governs(V, Q) -> PT = Q ; PT = P ),
    tr_np_out(english, NP, NPOut, _, _).
%% ... AND A PERSON FROM WHOM SOMETHING IS DEMANDED, BOUGHT OR TAKEN IS A PHRASE
%% OF `FROM' IN ENGLISH, where Spanish and Italian say `to': `reclamó a Pujol
%% entre 5.000 y 6.000 millones' demanded between 5.000 and 6.000 million
%% from Pujol (`demanded to Jordi Pujol')
tr_comp_out(english, pp(w(to, C), NP), _, _, [], [o(from, C)|NPOut], []) :-
    tr_global('$tr_verb', V), en_takes_from(V), !,
    tr_np_out(english, NP, NPOut, _, _).
%% ... AND THE PLACE ONE ARRIVES OR STAYS AT IS A PHRASE OF `AT', where the
%% lesson's languages say `to': `arrivammo nel tardo pomeriggio
%% all'Excelsior' is we arrived AT the Excelsior, `i passaporti erano rimasti
%% all'Excelsior' had remained there -- `arrived to', which no English page
%% prints; a city or a country is `in' (`arrivò a Roma', arrived in Rome), and
%% a person keeps the `to' (`la casa rimase ai figli'), and so do a number
%% and a time (`rimase dal 1990 al 1995' is a range)
tr_comp_out(english, pp(w(to, C), NP), _, _, [], [o(P, C)|NPOut], []) :-
    tr_global('$tr_verb', V), atom(V), memberchk(V, [arrives, remains, stays]),
    en_place_np(NP, P), !,
    tr_np_out(english, NP, NPOut, _, _).
%% ... AND THE EVENT ONE IS AT IS A PHRASE OF `AT': `Al processo di Torvajanica smentito Said' was denied AT the
%% trial, and English wrote `to the trial' -- a trial, a hearing, a meeting, a concert, after a verb that does not go
%% there (`va al concerto' goes TO it, tr_motion_verb/1)
tr_comp_out(english, pp(w(to, C), NP), _, _, [], [o(at, C)|NPOut], []) :-
    tr_np_head(NP, np(det(_, _, _), _, _, w(N, _), _)), atom(N), en_event_noun(N),
    \+ ( tr_global('$tr_verb', V), tr_motion_verb(V) ), !,
    tr_np_out(english, NP, NPOut, _, _).
%% (and the event one is IN in the lesson's language: `Segura estuvo presente ... en los Juegos de Salt Lake' was
%% present AT the Games, and it was `in the Games' -- the games in the plural only: `state proseguendo nel cosiddetto
%% gioco del cerino' is continuing in the game, and the first cut wrote `at the so-called game')
tr_comp_out(english, pp(w(in, C), NP), _, _, [], [o(at, C)|NPOut], []) :-
    tr_np_head(NP, np(det(_, _, _), _, _, w(N, _), Num)), atom(N), ( en_event_noun(N) -> true ; N == game, Num == plural ), !,
    tr_np_out(english, NP, NPOut, _, _).
%% AN HOUR AFTER `TO' IS `at', WITH NO ARTICLE: `llegaron a las cinco' arrived AT FIVE, and English wrote `to the five';
%% `entre las 4.30 y las cinco' is BETWEEN 4.30 AND FIVE, where it was `among the 4.30 and the five'. An hour is a count
%% with its noun left out in the feminine (`las horas', `le ore'), a number word of a clock or digits, or a time in
%% digits for the noun itself (`a la 1.30')
tr_comp_out(english, pp(w(to, C), NP), _, _, [], [o(at, C)|Out], []) :- en_clock(NP, Out), !.
%% ... AND AFTER A PREPOSITION OF TIME IT TAKES NONE EITHER: `el avión no partió hasta después de las seis de la tarde'
%% did not depart until after six in the afternoon, and English wrote `until after the six of the afternoon'
tr_comp_out(english, pp(w(P, C), NP), _, _, [], [o(P, C)|Out], []) :- en_clock_preposition(P), en_clock(NP, Out), !.
tr_comp_out(english, pp(w(among, C), co(w(and, AC), NP1, NP2)), _, _, [], Outs, []) :-
    en_clock(NP1, O1), en_clock(NP2, O2), !, append([[o(between, C)], O1, [o(and, AC)], O2], Outs).
%% ... AND A PAIR OF NUMBERS AFTER `AMONG' IS A RANGE: `entre 5.000 y 6.000
%% millones' is between them, and English wrote `among'
tr_comp_out(english, pp(w(among, C), NP), _, _, [], [o(between, C)|NPOut], []) :-
    NP = np(_, nums(_, _, _), _, _, _), !,
    tr_np_out(english, NP, NPOut, _, _).
%% ... AND SO IS A PAIR OF PHRASES JOINED BY `and': `l'intreccio tra le nuove
%% regole e le trattative' is the interweaving BETWEEN the rules and the
%% negotiations, and `tra' is the lesson's word for `among' (said first, as
%% `in mezzo a' would take it otherwise). Two phrases, neither of them a pair
%% itself: among three or more English says `among' still
tr_comp_out(english, pp(w(among, C), NP), _, _, [], [o(between, C)|NPOut], []) :-
    NP = co(w(and, _), A, B), A \= co(_, _, _), B \= co(_, _, _), !,
    tr_np_out(english, NP, NPOut, _, _).
%% ... AND AN AMOUNT AFTER A VERB OF RISING OR FALLING IS WHAT IT CHANGES BY: `il conto sale di circa 130 euro al mese'
%% rises BY about 130 euros, and the lesson's `of' came out `rises of approximately 130 euros'. A phrase with a number
%% in it, after the verbs whose meaning is a change of how much
tr_comp_out(english, pp(w(of, C), NP), _, _, [], [o(by, C)|NPOut], []) :-
    tr_global('$tr_verb', V), atom(V), memberchk(V, [rises, increases, grows, falls, decreases, drops, 'goes up', 'goes down']),
    tr_amount_np(NP), !,
    tr_np_out(english, NP, NPOut, _, _).
%% `LIKE ALL THE YEARS' IS `AS EVERY YEAR': `È una giornata decisiva, come tutti gli anni, ...' -- the word for `like'
%% and all of a unit of time in the plural say it happens each time, and English wrote `like all the years'
tr_comp_out(english, pp(w(like, C), all(_, np(det(article, the, _), none, [], w(U, UC), plural))), _, _, [],
            [o(as, C), o(every, lower), o(U, UC)], []) :-
    atom(U), en_time_noun(U), !.
%% `COMO' AND A PHRASE WITH NO DETERMINER SAY IN WHAT ROLE: `botellas utilizadas como arma' are bottles used AS A
%% WEAPON, `trabaja como profesor' works AS A PROFESSOR, and English wrote `like weapon', a bare singular no English
%% page prints. `as', and the article `a' before a noun in the singular that names no person, whose role takes none
%% (`como presidente del Gobierno' is as president of the Government)
tr_comp_out(english, pp(w(like, C), np(none, none, Adjs, w(N, NC), Nb)), _, _, [], [o(as, C)|NPOut], []) :-
    atom(N), \+ atom_number(N, _), !,
    (   Nb == singular, \+ ( tr_solve(mean(L, N)), tr_holds(person(L)) )
    ->  Det = det(article, a, w(a, lower)) ; Det = none ),
    tr_np_out(english, np(Det, none, Adjs, w(N, NC), Nb), NPOut, _, _).
%% `DE FORMA' AND AN ADJECTIVE SAY HOW: `el sarao transcurrió de forma "intensa y alegre"' went off in an intense and
%% cheerful manner, and English wrote `of "intense and cheerful" form' -- and the Italian writer `in modo', its word
%% for a manner, where it wrote `di forma allegre'
tr_comp_out(english, pp(w(of, C), np(none, none, Adjs, w(form, _), singular)), _, _, [], [o(in, C)|NPOut], []) :-
    Adjs = [_|_], !,
    tr_np_out(english, np(det(article, a, w(a, lower)), none, Adjs, w(manner, lower), singular), NPOut, _, _).
tr_comp_out(foreign, pp(w(of, C), np(none, none, Adjs, w(form, FC), singular)), Noun, Number, Cl, Outs, Advs) :-
    Adjs = [_|_], !,
    tr_comp_out(foreign, pp(w(in, C), np(none, none, Adjs, w(manner, FC), singular)), Noun, Number, Cl, Outs, Advs).
%% ... AND A COUNT OF YEARS AFTER `TO' IS AN AGE: `a 16 anni il conto mensile è di 200 euro in più' -- at 16 the monthly
%% bill is 200 euros more, and English wrote `to 16 years'. A number and the years, nothing else in the phrase
tr_comp_out(english, pp(w(to, C), np(none, w(N, NC), [], w(year, _), plural)), _, _, [], [o(at, C), o(N, NC)], []) :-
    atom(N), atom_number(N, _), !.
%% ... AND A UNIT OF TIME AFTER `TO' AND ITS ARTICLE IS HOW OFTEN: `una famiglia che guadagna 3.500 euro netti al
%% mese' earns 3,500 net euros A MONTH, `deve spendere circa 580 euro al mese' -- English wrote `to the month', which
%% no English page prints. The unit alone with its article, nothing else in the phrase: `al mese di maggio' names one
tr_comp_out(english, pp(w(to, C), np(det(article, the, _), none, [], w(U, UC), singular)), _, _, [], [o(a, C), o(U, UC)], []) :-
    memberchk(U, [month, year, week, day]), !.
%% (and with a bracket after the unit: `circa 580 euro al mese (baby sitter esclusa)' is 580 euros a month)
tr_comp_out(english, pp(w(to, C), app(NP0, K, X)), _, _, [], [o(a, C)|Rest], []) :-
    NP0 = np(det(article, the, _), none, [], w(U, _), singular), memberchk(U, [month, year, week, day]),
    tr_np_out(english, app(NP0, K, X), [o(the, _)|Rest], _, _), !.
%% ... and NONE where the verb written states none and English takes the
%% phrase bare: the preposition belonged to the source verb, never to the
%% meaning -- `se ha convertido en un problema' is `è diventata un problema',
%% and with `en' crossed as it stood it came out `è diventata in un problema'
tr_comp_out(foreign, pp(w(_, _), gov(V, NP)), _, _, [], NPOut, []) :-
    en_bare_object(V), \+ tr_bare_singular(NP),
    \+ ( tr_lexeme_across(V, foreign, VT), atom(VT), tr_solve(take_before(VT, _, phrase)) ), !,
    tr_np_out(foreign, NP, NPOut, _, _).
tr_comp_out(foreign, pp(w(P, C), gov(V, NP)), _, _, [], [o(PT, C)|NPOut], []) :- !,
    (   tr_lexeme_across(V, foreign, VT), atom(VT), tr_solve(take_before(VT, Q, phrase)) -> PT = Q
    ;   tr_word_across(w(P, lower), foreign, preposition, PT)
    ),
    tr_np_out(foreign, NP, NPOut, _, _).
%% ... AND A CITY TAKES THE WORD FOR `TO' WHERE ENGLISH SAYS `IN': `inauguró en
%% Tarragona' is `inaugurò a Tarragona' in Italian, which keeps `in' for a
%% country or a region (`in Catalogna'). The lesson says which names are
%% cities (`"Tarragona" is a city.'); a name it does not say is written as it was
tr_comp_out(foreign, pp(w(in, C), name(N)), _, _, [], [o(PT, C)|NPOut], []) :-
    tr_city_name(N), tr_word_across(w(to, lower), foreign, preposition, PT), !,
    tr_np_out(foreign, name(N), NPOut, _, _).
%% ... AND A DURATION OR A MEASURE AFTER `FOR' TAKES THE WORD THE LESSON BEGINS
%% IT WITH, where it says one (`The word "durante" begins the duration.', `The
%% word "por" begins the measure.'): `ha nuotato per quattro minuti' is `ha
%% nadado durante cuatro minutos' and `per 152 metri' `por 152 metros', where
%% the lesson's word for `for' is `para', a purpose's and a receiver's. A
%% count is what makes a time a duration (`per lunedì' is `para el lunes'),
%% so the phrase has a number or `a' for its determiner; a lesson with no
%% such word (Italian's `per') writes `for' as it always did
tr_comp_out(foreign, pp(w(for, C), NP), _, _, [], [o(PT, C)|NPOut], []) :-
    tr_span_word(NP, PT), !,
    tr_np_out(foreign, NP, NPOut, _, _).
%% THE PRONOUN AFTER `SEGÚN' AND `ENTRE' IS THE SUBJECT'S IN SPANISH: Italian's
%% `secondo me' is `según yo' and not `según mí'. The prepositions are the ones
%% Spanish alone has (`excepto', `incluso' and `salvo' are Italian's too)
tr_comp_out(foreign, pp(w(P, C), pronoun(w(me, PC))), _, _, [], [o(PT, C), o(Y, PC)], []) :-
    tr_word_across(w(P, lower), foreign, preposition, PT), tr_subject_form_preposition(PT),
    once(( tr_solve(mean(Y, i)), tr_class_of(Y, pronoun) )), !.
%% A PREPOSITION THAT CONTRACTS WITH THE ARTICLE IS SAID AGAIN BEFORE THE SECOND OF TWO DEFINITE
%% PHRASES: `los ataques de la artillería y la aviación' are `gli attacchi dell'artiglieria e
%% dell'aviazione', and with one `di' Italian wrote `dell'artiglieria e l'aviazione', the second
%% phrase cut off from what it is of. A lesson that states the preposition's contraction with the
%% article (`"del" is the contraction of "di il".') is one whose phrases take their own
tr_comp_out(foreign, pp(w(P, C), co(K, A, B)), Noun, Number, [], Outs, []) :-
    A = np(det(article, the, _), _, _, _, _), B = np(det(article, the, _), _, _, _, _),
    tr_word_across(w(P, lower), foreign, preposition, PT), atom(PT), tr_prep_contracts(PT), !,
    tr_comp_out(foreign, pp(w(P, C), A), Noun, Number, _, O1, _),
    tr_connector_out(foreign, K, KO),
    tr_comp_out(foreign, pp(w(P, lower), B), Noun, Number, _, O2, _),
    append([O1, KO, O2], Outs).
%% `like' AND THE WORD FOR `ever' IN A CLAUSE THAT DENIES NOTHING ARE `like never
%% before': `Via Krupp ... è frequentata come mai' -- frequented as never before,
%% where it was `like ever' (the lesson's language writes its own word for
%% `never', `como nunca')
tr_comp_out(english, pp(w(like, C), adv(w(ever, AC))), _, _, [], [o(like, C), o(never, AC), o(before, lower)], []) :-
    \+ tr_global('$tr_denied', yes), !.
%% ENGLISH SAYS WHAT IS ON THE INTERNET, A PAGE OR A SITE WITH `on': `En esta página se ofrecen textos' are offered on
%% this page, `En la Red existen páginas' exist on the Net -- `in this page' and `in the Net' were written, the
%% lesson's word for both being `en'
tr_comp_out(english, pp(w(in, C), NP), _, _, [], [o(on, C)|NPOut], []) :-
    tr_on_head(NP, H), en_on_noun(H), !, tr_np_out(english, NP, NPOut, _, _).
%% ... AND WHAT IS ON A FLIGHT OR A VEHICLE ONE TRAVELS IN: `en el vuelo UX-9482 de Air Europa' is on the flight, where
%% `in the flight' was written -- with its determiner (`andar en tren' is by train, not `on train')
tr_comp_out(english, pp(w(in, C), NP), _, _, [], [o(on, C)|NPOut], []) :-
    tr_np_head(NP, np(det(_, _, _), _, _, w(H, _), _)), atom(H), en_on_vehicle(H), !, tr_np_out(english, NP, NPOut, _, _).
%% ... AND A MOMENT WITH `at': `no tenía "nada que añadir en este momento"' had nothing to add at this moment, and
%% `in this moment' was written -- this one, that one or the one, never a moment of something (`Navarro, en un
%% momento de forma excepcional' is in a moment of exceptional form)
tr_comp_out(english, pp(w(in, C), NP), _, _, [], [o(at, C)|NPOut], []) :-
    tr_on_head(NP, moment), NP = np(det(K, D, _), _, _, _, _), ( K == article -> D == the ; memberchk(D, [this, that, these, those]) ), !,
    tr_np_out(english, NP, NPOut, _, _).
tr_comp_out(To, pp(w(P, C), NP), _, _, [], [o(PT, C)|NPOut], []) :- tr_word_across(w(P, lower), To, preposition, PT), tr_np_out(To, NP, NPOut, _, _).
tr_comp_out(To, by(NP), _, _, [], [o(By, lower)|NPOut], []) :-
    tr_by_word(To, By), tr_np_out(To, NP, NPOut, _, _).
%% ... and the second participle after its coordinator, agreeing with the
%% phrase the first is said of
tr_comp_out(To, cpart(C, L, Cs), Noun, Number, [], Outs, []) :- !,
    tr_comp_out(To, cnj(C), Noun, Number, _, COut, _),
    (   To == english
    ->  tr_lexeme_across(L, english, LT), en_participle_of(LT, PP)
    ;   tr_lexeme_across(L, foreign, LT),
        ( tr_gender(Noun, G0), G0 \== none -> G = G0 ; G = masculine ),
        tr_with_gender(G, tr_participle_agreeing(LT, Number, PP))
    ),
    tr_ptc_day_first(To, Cs, DayOut, CsD),
    tr_comps_out(To, CsD, Noun, Number, _, CompOuts0, AdvOuts), append(DayOut, CompOuts0, CompOuts),
    append([COut, [o(PP, lower)], CompOuts, AdvOuts], Outs).
%% ENGLISH PUTS AN ADVERB AFTER THE OTHER COMPLEMENTS, THE LESSON'S LANGUAGE
%% WHERE THE SOURCE HAD IT: `salir así en una familia tan pacífica' written
%% with its adverb last came out `uscire in una famiglia così pacifica
%% così', two words for one and the first in the wrong place
%% (an adverb that comments on the whole clause, after it, is set off by its comma in every language: `Forse non le
%% era piaciuto, chissà' is maybe she had not liked it, who knows, and the comma the reader takes out was lost)
tr_comp_out(english, adv(w('who knows', C)), _, _, [], [], [o(',', comma), o('who knows', C)]) :- !.
tr_comp_out(foreign, adv(w('who knows', C)), _, _, [], [o(',', comma), o(AT, C)], []) :-
    tr_word_across(w('who knows', lower), foreign, adverb, AT), !.
%% (`TOO' AMONG A VERB'S COMPLEMENTS IS `too much', in its place: `si spende troppo per la fisica delle alte energie' is
%% one spends too much on it -- the lesson's `troppo' and `demasiado' are the adverb `too', which English says of an
%% adjective alone, read as its degree, and after the verb English wrote `one spends for the physics ... too')
tr_comp_out(english, adv(w(too, C)), _, _, [], [o('too much', C)], []) :- !.
%% (and `at ease', which says the state the verb is done in, stays in its place: `sentirsi a proprio agio nelle
%% situazioni' is to feel at ease in them, and written last it was `To feel in the situations at ease')
tr_comp_out(english, adv(w('at ease', C)), _, _, [], [o('at ease', C)], []) :- !.
tr_comp_out(english, adv(w(A, C)), _, _, [], [], [o(AT, C)]) :- !, tr_word_across(w(A, lower), english, adverb, AT).
tr_comp_out(foreign, adv(w(A, C)), _, _, [], [o(AT, C)], []) :- tr_word_across(w(A, lower), foreign, adverb, AT).
%% an answer: English's word itself, and the lesson's adverb for it
tr_comp_out(english, ans(w(T, C)), _, _, [], [o(T, C)], []) :- !.
tr_comp_out(foreign, ans(w(T, C)), _, _, [], [o(AT, C)], []) :- tr_word_across(w(T, lower), foreign, adverb, AT).
%% a participle predicated of the subject: English's own form, the lesson's
%% language agreeing with the subject as a passive's does
tr_comp_out(english, pred(L), _, _, [], [o(PP, lower)], []) :- !,
    tr_lexeme_across(L, english, LT), en_reduced_participle(LT, PP).
tr_comp_out(foreign, pred(L), _, Number, [], [o(PP, lower)], []) :- !,
    tr_lexeme_across(L, foreign, LT), tr_participle_agreeing(LT, Number, PP).
tr_comp_out(To, predq(L, C), N, Nb, Cl, [o(PP, C)], A) :- !, tr_comp_out(To, pred(L), N, Nb, Cl, [o(PP, _)], A).
tr_comp_out(_, cvw(Os), _, _, [], Os, []) :- !.            % a second verb, made (tr_cverbs/6)
%% ... and one that follows the perfect's auxiliary, the masculine singular
%% (tr_perfect_preds/2)
tr_comp_out(foreign, predinv(L), _, _, [], [o(PP, lower)], []) :- !,
    tr_lexeme_across(L, foreign, LT), tr_with_gender(masculine, tr_participle_agreeing(LT, singular, PP)).
tr_comp_out(To, predqinv(L, C), N, Nb, Cl, [o(PP, C)], A) :- !, tr_comp_out(To, predinv(L), N, Nb, Cl, [o(PP, _)], A).
%% the source's form, gender and number
tr_comp_out(foreign, predag(L, G, N), _, _, [], [o(PP, lower)], []) :- !,
    tr_lexeme_across(L, foreign, LT), tr_with_gender(G, tr_participle_agreeing(LT, N, PP)).
tr_comp_out(To, predqag(L, C, G, N), N0, Nb, Cl, [o(PP, C)], A) :- !, tr_comp_out(To, predag(L, G, N), N0, Nb, Cl, [o(PP, _)], A).
%% and the marker itself says nothing where it is not used
tr_comp_out(_, pagr(_, _), _, _, [], [], []) :- !.
%% ... and one said of the object, in the object pronoun's gender and number
%% (tr_comps_out/7)
tr_comp_out(foreign, opred(L, G, N), _, _, [], [o(PP, lower)], []) :- !,
    tr_lexeme_across(L, foreign, LT), tr_with_gender(G, tr_participle_agreeing(LT, N, PP)).
tr_comp_out(foreign, oadj(As, G, N), _, _, [], Outs, []) :- !,
    tr_with_gender(G, ( tr_adjectives_out(foreign, As, none, N, AOs), tr_adj_words(AOs, Outs) )).
%% ... which English writes as it writes any adjective: it agrees with nothing
tr_comp_out(english, oadj(As, _, _), Noun, Number, Cl, Outs, Advs) :- !,
    tr_comp_out(english, adj(As), Noun, Number, Cl, Outs, Advs).
%% a time phrase, bare in every language; a conjunction between two
%% complements, by the target's word for it
%% ... AND A BARE TIME TAKES THE LESSON'S WORD FOR A TIME where it has one:
%% `Tres veces negó ...' is three times, and `time' is `tempo' before it is
%% `volta' -- `tre tempi'. A noun the lesson calls a time (`"volta" is a
%% time.') is the one written for an adjunct that names when
%% ... AND A DAY OF THE WEEK ALONE IS `ON' IT IN ENGLISH, with no article:
%% `la apertura de las sucursales los sábados' is the opening on Saturdays,
%% and `el sábado' on Saturday -- `the opening the Saturdays'
tr_comp_out(english, at_time(np(Det, none, [], w(D, C), Nb)), _, _, [], [o(on, lower)|Outs], []) :-
    atom(D), tr_weekday(D), ( Det == none ; Det = det(article, the, _) ), !,
    tr_with_time_noun(tr_np_out(english, np(none, none, [], w(D, C), Nb), Outs, _, _)).
%% ... and a weekday and its part: `trasmessa giovedì sera' was broadcast ON Thursday evening, where it was `broadcast
%% Thursday evening'
tr_comp_out(english, at_time(NP), _, _, [], [o(on, lower)|Outs], []) :-
    NP = app(np(none, none, [], w(D, _), singular), part, np(none, none, [], w(_, _), singular)),
    atom(D), tr_weekday(D), !,
    tr_with_time_noun(tr_np_out(english, NP, Outs, _, _)).
%% ... and a weekday and its date: `dorme giovedì 6 giugno' sleeps ON Thursday, June 6 (app/3's wdate)
tr_comp_out(english, at_time(NP), _, _, [], [o(on, lower)|Outs], []) :-
    NP = app(_, wdate, _), !, tr_np_out(english, NP, Outs, _, _).
%% ... and a date: `tendrá lugar el 4 de junio' takes place ON June 4
%% (with its year too: `la banda che il 7 novembre del settantasette rapì il duca' kidnapped him on November 7, '77)
tr_comp_out(english, at_time(NP), _, _, [], [o(on, lower)|Outs], []) :-
    ( NP = app(NP1, K, _), memberchk(K, [year, yearw]) -> true ; NP1 = NP ),
    NP1 = np(_, w(D, _), [], w(M, _), _), atom(D), tr_digits(D), atom(M), en_month(M), !,
    tr_with_time_noun(tr_np_out(english, NP, Outs, _, _)).
%% ... and a day of the month the source names by `the day' and its number: `el jubilado fallecido el día 13'
%% died ON THE 13TH, where it was `died the day 13' (tr_np_out/5 writes the ordinal)
tr_comp_out(english, at_time(NP), _, _, [], [o(on, lower)|Outs], []) :-
    tr_day_number(NP, _), !, tr_np_out(english, NP, Outs, _, _).
tr_comp_out(To, at_time(NP), _, _, [], Outs, []) :- !, tr_with_time_noun(tr_np_out(To, NP, Outs, _, _)).
tr_comp_out(To, cnj(w(C, CC)), _, _, [], Outs, []) :- !, tr_connector_out(To, w(C, CC), Outs).
%% ... and a clause with its copula left out (gapc/2): the phrase and what is said of it, in the order
%% the source had them -- `the antifouling paints less harmful', `the detergents almost all
%% biodegradable' (`tutti' there is all of them)
tr_comp_out(To, gapc(NP, Ps), _, _, [], Outs, []) :- !,
    tr_np_out(To, NP, NOut, Noun, Number),
    tr_gapc_preds(To, Ps, Noun, Number, POut), append(NOut, POut, Outs).
%% ... and a concession (conc/3): `however strange it may appear', `por extraño que pueda aparecer'
tr_comp_out(english, conc(w(_, C), w(A, _), s(Ak, gap(third, N), g(L0, T, Asp, Neg), Cs)), _, _, [], Outs, []) :- !,
    ( L0 == can -> L = may ; L = L0 ),
    tr_write_nested(english, s(Ak, pronoun(third, N, w(it, lower)), g(L, T, Asp, Neg), Cs), SOut),
    Outs = [o(however, C), o(A, lower)|SOut].
tr_comp_out(foreign, conc(w(_, C), w(A, AC), S), _, _, [], Outs, []) :- !,
    once(tr_solve(begin(CW, cause))),
    tr_word_across(w(A, lower), foreign, adjective, AT), tr_relative_that(R),
    tr_with_mood(sbj, tr_gap_write(foreign, none, S, SOut)),
    Outs = [o(CW, C), o(AT, AC), o(R, lower)|SOut].
%% ... and both ... and (both/2): each language's pair round the two halves
tr_comp_out(To, both(Cs1, Cs2), Noun, Number, [], Outs, []) :- !,
    tr_both_pair(To, B0, P),
    ( B0 == 'so much' -> BO = [o(so, lower), o(much, lower)] ; BO = [o(B0, lower)] ),
    tr_comps_out(To, Cs1, Noun, Number, _, O1, A1), tr_comps_out(To, Cs2, Noun, Number, _, O2, A2),
    append([BO, O1, A1, [o(P, lower)], O2, A2], Outs).
%% ... and not only ... but, each half its complements (nonlyc/3)
tr_comp_out(To, nonlyc(Cs1, Cs2, Also), Noun, Number, [], Outs, []) :- !,
    tr_nonly_words(To, Also, NotO, OnlyO, ButO, AlsoO),
    tr_comps_out(To, Cs1, Noun, Number, _, O1, A1), tr_comps_out(To, Cs2, Noun, Number, _, O2, A2),
    append([NotO, OnlyO, O1, A1, ButO, AlsoO, O2, A2], Outs).
%% ... and the word that says a choice follows (cor/1): `either', `o'
tr_comp_out(To, cor(w(E, C)), _, _, [], [o(T, C)], []) :- !,
    ( To == english -> T = E ; tr_word_across(w(E, lower), To, conjunction, T) ).
%% ... and a second verb joined to the first, in the first one's form:
%% `presentava e dirigeva', `presented and directed'
tr_comp_out(To, cov(w(C, CC), L, T, P, N), _, _, [], Outs, []) :- !,
    tr_connector_out(To, w(C, CC), CO),
    (   To == english
    ->  en_group(L, P, N, T, simple, no, VO, _, _)
    ;   tr_verb_out(foreign, L, [], LT), tr_make(LT, N, T, P, Form), VO = [o(Form, lower)]
    ),
    append(CO, VO, Outs).
%% an infinitive: English's `to' and the base form, the base alone after a
%% modal; the lesson's infinitive of its verb
%% the purpose out: English's `to' and the base, which is what it writes for
%% a plain infinitive too; the lesson's own word and its infinitive
%% a gerund with its complements, and `upon': English's -ing, after `on'
%% for the second; the lesson's gerund, or its word for the moment and the
%% infinitive when it names one
tr_comp_out(To, ger(reflexive(L), Cs), Noun, Number, [], [o(G, lower)|COut], []) :- !,
    tr_lexeme_across(L, To, LT), tr_gerund_out(To, LT, G0),
    ( To == foreign, tr_reflexive_out(R) -> atom_concat(G0, R, G) ; G = G0 ),   % English has no reflexive there
    tr_comps_out(To, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut).
%% ... AND THE GERUND OF `HAVE' BEFORE A PARTICIPLE IS THE PERFECT'S: `avendo
%% mantenuto solo il progetto' is `habiendo mantenido', the lesson's auxiliary
%% and not the verb that means `has' (`teniendo'), and the participle agrees
%% with nobody (tr_with_gender/2: the subject's gender was `mantenida')
tr_comp_out(foreign, ger(has, Cs0), Noun, Number, [], [o(G, lower)|COut], []) :-
    tr_perfect_gerund(Cs0, Cs), tr_lexeme_across(has, foreign, Has),
    tr_auxiliary(has, Aux), Aux \== Has, !,
    tr_gerund_out(foreign, Aux, G),
    tr_with_gender(masculine, tr_comps_out(foreign, Cs, Noun, Number, _, CO, CA)),
    append(CO, CA, COut).
%% ... and the pronouns that stand before a verb are joined to a gerund,
%% as they are to an infinitive: `chiedendogli' (no accent is written: a
%% lesson cannot say where Spanish's `pidiéndole' puts one)
%% -- the verb by its object, as a finite one is (tr_verb_out/4): `sapendo di non
%% essere obbedito' is knowing a thing, `sabiendo', and by the first meaning
%% it came out `conociendo'
tr_comp_out(To, ger(L, Cs), Noun, Number, [], [o(G, lower)|COut], []) :- !,
    tr_verb_out(To, L, Cs, LT), tr_gerund_out(To, LT, G0),
    tr_comps_out(To, Cs, Noun, Number, Cl, CO, CA), append(CO, CA, COut),
    findall(P, member(o(P, _), Cl), Ps), atomic_list_concat([G0|Ps], G).
%% (a reflexive gerund keeps its pronoun joined to the infinitive, as after a
%% preposition: `seguirá describiéndose' is `continuerà a descriversi')
tr_comp_out(foreign, pger(L, Cs), Noun, Number, [], [o(P, lower), o(Inf, lower)|COut], []) :- !,
    tr_verb_takes(P), tr_lexeme_across(L, foreign, LT0),
    ( LT0 = reflexive(LT) -> tr_reflexive_out(R), Ps = [R] ; LT = LT0, Ps = [] ),
    once(tr_solve(infinitive_of(Inf0, LT))), tr_joined_infinitive(Inf0, Ps, Inf),
    tr_comps_out(foreign, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut).
tr_comp_out(english, upon(cl(L, Cls), Cs), Noun, Number, [], [o(on, lower), o(G, lower)|Outs], []) :- !,
    tr_lexeme_across(L, english, LT), en_gerund_of(LT, G),
    findall(o(T, lower), ( member(X, Cls), ( X = dat(w(T, _)) -> true ; X = w(T, _) ) ), Objs),
    tr_comps_out(english, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut), append(Objs, COut, Outs).
tr_comp_out(foreign, upon(cl(L, Cls), Cs), Noun, Number, [], Outs, []) :- !,
    tr_lexeme_across(L, foreign, LT),
    findall(F, ( member(X, Cls), tr_pinf_clitic_out(X, F) ), Ps),
    (   once(tr_solve(begin(M, moment))), once(tr_solve(infinitive_of(Inf0, LT)))
    ->  tr_joined_infinitive(Inf0, Ps, Inf), Head = [o(M, lower), o(Inf, lower)]
    ;   tr_gerund_out(foreign, LT, G), tr_joined_infinitive(G, Ps, GJ), Head = [o(GJ, lower)]
    ),
    tr_comps_out(foreign, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut), append(Head, COut, Outs).
tr_comp_out(english, uponse(L, NP, Cs), Noun, Number, [], [o(on, lower)|Outs], []) :- !,
    tr_lexeme_across(L, english, LT0), ( LT0 = reflexive(LT) -> true ; LT = LT0 ), en_participle_of(LT, Pt),
    tr_np_out(english, NP, NO, _, _),
    tr_comps_out(english, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut),
    append([NO, [o(being, lower), o(Pt, lower)], COut], Outs).
tr_comp_out(foreign, uponse(L, NP, Cs), Noun, Number, [], Outs, []) :- !,
    tr_lexeme_across(L, foreign, LT0), ( LT0 = reflexive(LT) -> true ; LT = LT0 ), tr_reflexive_out(R),
    (   once(tr_solve(begin(M, moment))), once(tr_solve(infinitive_of(Inf0, LT)))
    ->  tr_joined_infinitive(Inf0, [R], Inf), Head = [o(M, lower), o(Inf, lower)]
    ;   tr_gerund_out(foreign, LT, G), tr_joined_infinitive(G, [R], GJ), Head = [o(GJ, lower)]
    ),
    tr_np_out(foreign, NP, NO, _, _),
    tr_comps_out(foreign, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut), append([Head, NO, COut], Outs).
tr_comp_out(english, upons(L, NP, Cs), Noun, Number, [], [o(on, lower)|Outs], []) :- !,
    en_gerund_of(L, G), tr_np_out(english, NP, NO, _, _),
    tr_comps_out(english, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut),
    append([NO, [o(G, lower)], COut], Outs).
tr_comp_out(foreign, upons(L, NP, Cs), Noun, Number, [], Outs, []) :- !,
    tr_lexeme_across(L, foreign, LT0), ( LT0 = reflexive(LT) -> true ; LT = LT0 ),
    (   once(tr_solve(begin(M, moment))), once(tr_solve(infinitive_of(Inf, LT)))
    ->  Head = [o(M, lower), o(Inf, lower)]
    ;   tr_gerund_out(foreign, LT, G), Head = [o(G, lower)]
    ),
    tr_np_out(foreign, NP, NO, _, _),
    tr_comps_out(foreign, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut), append([Head, NO, COut], Outs).
tr_comp_out(english, upon(L, Cs), Noun, Number, [], [o(on, lower), o(G, lower)|COut], []) :- !,
    tr_lexeme_across(L, english, LT), en_gerund_of(LT, G),
    tr_comps_out(english, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut).
tr_comp_out(foreign, upon(L, Cs), Noun, Number, [], Outs, []) :- !,
    tr_lexeme_across(L, foreign, LT),
    (   once(tr_solve(begin(M, moment))), once(tr_solve(infinitive_of(Inf, LT)))
    ->  Head = [o(M, lower), o(Inf, lower)]
    ;   tr_gerund_out(foreign, LT, G), Head = [o(G, lower)]
    ),
    tr_comps_out(foreign, Cs, Noun, Number, _, CO, CA), append(CO, CA, COut), append(Head, COut, Outs).
tr_comp_out(To, voc(NP), _, _, [], Outs, []) :- !, tr_np_out(To, NP, Outs, _, _).     % who is spoken to
tr_comp_out(To, dsh(Inner), _, _, [], Outs, []) :- !, tr_aside_out(To, dashed, Inner, Outs).  % a clause between dashes
tr_comp_out(english, purp(C), N, Nb, Cl, Outs, A) :- !, tr_comp_out(english, C, N, Nb, Cl, Outs, A).
tr_comp_out(foreign, purp(C), N, Nb, Cl, [o(P, lower)|Outs], A) :- !,
    once(tr_solve(begin(P, purpose))), tr_comp_out(foreign, C, N, Nb, Cl, Outs, A).
tr_comp_out(english, purpose(L), _, _, [], [o(to, lower)|Bs], []) :- !,
    tr_lexeme_across(L, english, LT), en_base_words(LT, Bs).
tr_comp_out(english, npurpose(L), _, _, [], [o(not, lower), o(to, lower)|Bs], []) :- !,
    tr_lexeme_across(L, english, LT), en_base_words(LT, Bs).
tr_comp_out(foreign, npurpose(L), _, _, [], [o(P, lower), o(Neg, lower), o(Inf, lower)], []) :- !,
    tr_inf_lexeme(L, LT), once(tr_solve(infinitive_of(Inf, LT))),
    once(( tr_solve(begin(P0, purpose)), P = P0 )),
    once(( tr_solve(mean(N0, not)), tr_class_of(N0, adverb), Neg = N0 )),
    tr_infinitive_verb(L).
tr_comp_out(foreign, purpose(L), _, _, [], [o(P, lower), o(Inf, lower)], []) :- !,
    tr_inf_lexeme(L, LT), once(tr_solve(infinitive_of(Inf, LT))),
    once(( tr_solve(begin(P0, purpose)), P = P0 )),
    tr_infinitive_verb(L).
%% (an infinitive the one before it takes with its word is `to' and the verb, under a modal too:
%% `si potrà tornare a fare il bagno' will be able to return TO swim, and it was `return swim')
tr_comp_out(english, ainf(_, L), _, _, Cl, Outs, A) :-
    tr_modal_verb, \+ tr_verb_ends_in_preposition, !,
    tr_lexeme_across(L, english, LT), en_base_words(LT, Bs), Outs = [o(to, lower)|Bs], Cl = [], A = [].
tr_comp_out(english, ainf(_, L), N, Nb, Cl, Outs, A) :- !, tr_comp_out(english, inf(L), N, Nb, Cl, Outs, A).
tr_comp_out(foreign, ainf(w(P, C), L), _, _, [], [o(PT, C), o(Inf, lower)], []) :- !,
    tr_word_across(w(P, lower), foreign, preposition, PT),
    tr_inf_lexeme(L, LT), once(tr_solve(infinitive_of(Inf, LT))).
tr_comp_out(To, inf(L), _, _, [], Outs, []) :-
    ( To == foreign -> tr_inf_lexeme(L, LT) ; tr_lexeme_across(L, To, LT) ),
    (   To == english
    ->  (   tr_en_prep_gerund(Pr) -> en_gerund_of(LT, G), Outs = [o(Pr, lower), o(G, lower)]
        ;   tr_verb_ends_in_preposition -> en_gerund_of(LT, G), Outs = [o(G, lower)]
        ;   en_base_words(LT, Bs), ( tr_modal_verb -> Outs = Bs ; Outs = [o(to, lower)|Bs] )
        )
    ;   tr_verb_takes_gerund
    ->  tr_gerund_out(foreign, LT, G), Outs = [o(G, lower)], tr_infinitive_verb(L)
    ;   once(tr_solve(infinitive_of(Inf, LT))),
        ( tr_infx_lead(P) -> Outs = [o(P, lower), o(Inf, lower)] ; Outs = [o(Inf, lower)] ),
        tr_infinitive_verb(L)
    ).

tr_comp_out(english, age(NP), _, _, [], Outs, []) :- !, tr_np_out(english, NP, O1, _, _), append(O1, [o(old, lower)], Outs).
tr_comp_out(english, binf(L), _, _, [], Outs, []) :- !, tr_lexeme_across(L, english, LT), en_base_words(LT, Outs).
tr_comp_out(english, hinf(L), Noun, Number, Clitics, [o(how, lower)|Outs], Advs) :-
    tr_comp_out(english, inf(L), Noun, Number, Clitics, Outs, Advs).
%% AN INFINITIVE WITH ITS OWN PRONOUNS OR IN THE PERFECT: English writes
%% `to', `have' and the participle, and its object pronouns after them; the
%% lesson's language joins the pronouns to the infinitive -- its auxiliary's,
%% in the perfect -- with the `e' an Italian infinitive ends in dropped, and
%% the reflexive as its own reflexive pronoun: `riprenderli', `recuperarlos',
%% `essersi persa', `haberse perdido'. English has no pronoun for the
%% reflexive there and writes none.
tr_comp_out(english, infx(L, Asp, Cls), _, _, [], Outs, []) :- !,
    tr_lexeme_across(L, english, LT),
    (   tr_en_prep_gerund(Pr)
    ->  ( Asp == perfect -> en_participle_of(LT, PP), V = [o(Pr, lower), o(having, lower), o(PP, lower)]
        ; en_gerund_of(LT, G), V = [o(Pr, lower), o(G, lower)]
        ), Ger = yes
    ;   Asp == perfect -> en_participle_of(LT, PP), V = [o(have, lower), o(PP, lower)], Ger = no
    %% (the gerund after a verb that ends in its preposition, as inf/1's: `si sono rassegnati a
    %% muoversi' became resigned to MOVING, and it was `to to move')
    ;   tr_verb_ends_in_preposition -> en_gerund_of(LT, G), V = [o(G, lower)], Ger = yes
    ;   en_base(LT, B), V = [o(B, lower)], Ger = no
    ),
    ( ( Ger == yes ; tr_modal_verb ) -> To = [] ; To = [o(to, lower)] ),
    findall(o(T, lower), ( member(W, Cls), ( W = w(T, _) ; W = dat(w(T, _)) ) ), Objs),
    append([To, V, Objs], Outs).
%% (and the word the verb being written takes before an infinitive goes before it, as before a plain one: `accusato
%% di aver ucciso' is `acusado de haber matado', `"acusa" takes "de" before the infinitive.' -- the reader takes the
%% source's word off as the verb's, and written bare it was `acusado haber matado'. Not where the source kept its
%% word as a complement of its own (nprep/1, written just before: tr_infx_kept/0))
tr_comp_out(foreign, infx(L, Asp, Cls0), _, Number, [], Outs, []) :- !,
    tr_lexeme_across(L, foreign, LT),
    %% (the reflexive pronoun of a meaning the lesson states as reflexive, as tr_verb_out/4 writes a clause's:
    %% `to strip' is `desnudarse', `The reflexive verb "desnuda" means "strips".')
    (   atom(LT), \+ memberchk(refl, Cls0), tr_solve(mean_as(LT, L, reflexive)) -> Cls = [refl|Cls0] ; Cls = Cls0 ),
    maplist(tr_enclitic_out, Cls, Ps),
    (   Asp == perfect
    ->  tr_infinitive_auxiliary(LT, Cls, AuxInf), tr_joined_infinitive(AuxInf, Ps, J),
        tr_perfect_participle(LT, Cls, Number, PP), Outs0 = [o(J, lower), o(PP, lower)]
    ;   once(tr_solve(infinitive_of(Inf, LT))), tr_joined_infinitive(Inf, Ps, J), Outs0 = [o(J, lower)]
    ),
    ( tr_infx_lead(P) -> Outs = [o(P, lower)|Outs0] ; Outs = Outs0 ).
tr_comp_out(english, bare(NP), _, _, [], Outs, []) :- !, tr_np_out(english, NP, Outs, _, _).
tr_comp_out(english, opron(dat(W)), N, Nb, Cl, Outs, A) :- !,
    nb_setval('$tr_opron_dat', yes),
    (   tr_comp_out(english, opron(W), N, Nb, Cl, Outs, A) -> nb_setval('$tr_opron_dat', no)
    ;   nb_setval('$tr_opron_dat', no), fail
    ).
%% ... and the pronoun after a reflexive verb is a thing: `me lo apunto' is `I note it'
tr_comp_out(english, opron(w(W, C)), _, _, [], [o(it, C)], []) :-
    memberchk(W, [him, her]), tr_global('$tr_verb', refl(_)), !.
%% ... and after a verb of saying: `A dirlo è Giuseppe Signori' is Signori says IT --
%% what is said, never somebody told (and never a dative: `gli ho chiesto' is I asked HIM)
tr_comp_out(english, opron(w(W, C)), _, _, [], [o(it, C)], []) :-
    memberchk(W, [him, her]), tr_global('$tr_opron_dat', D), D \== yes,
    tr_global('$tr_verb', V), atom(V), en_saying(V), !.
tr_comp_out(english, opron(w(W, C)), _, _, [], [o(T, C)], []) :-
    tr_pronoun_across(english, object, w(W, C), _, _, T0),
    ( tr_global('$tr_denied', yes), en_any_form(T0, T1) -> T = T1 ; T = T0 ).
tr_comp_out(foreign, opron(dat(w(W, C))), _, _, Clitics, Outs, []) :-
    tr_dative_word(W, T), !,
    ( tr_holds(precede(T, verb)) -> Clitics = [o(T, C)], Outs = [] ; Clitics = [], Outs = [o(T, C)] ).
tr_comp_out(foreign, opron(dat(W)), N, Nb, Cl, Outs, A) :- !, tr_comp_out(foreign, opron(W), N, Nb, Cl, Outs, A).
tr_comp_out(foreign, opron(w(W, C)), _, _, Clitics, Outs, []) :-
    tr_pronoun_across(foreign, object, w(W, C), _, _, T),
    ( tr_holds(precede(T, verb)) -> Clitics = [o(T, C)], Outs = [] ; Clitics = [], Outs = [o(T, C)] ).
%% WHAT FOLLOWS AN INFINITIVE IS THE INFINITIVE'S, and a person there is its
%% object: `non era in grado di riconoscere i suoi amici' is `no era capaz de
%% reconocer a sus amigos', and with the copula still the verb being written
%% the word before a person was left out -- a copula's complement is no
%% object (tr_marker/3)
%% ... and it remembers the verb it took the place of, which governs an
%% infinitive joined to it (tr_comps_out/7)
tr_infinitive_verb(L0) :-
    ( L0 = reflexive(L) -> V = refl(L) ; V = L0 ),
    ( tr_global('$tr_verb', V0) -> nb_setval('$tr_inf_governor', gov(V, V0)) ; true ),
    nb_setval('$tr_verb', V).

%% A CLAUSE AFTER A CONNECTING WORD THE LESSON SAYS TAKES THE SUBJUNCTIVE IS
%% WRITTEN IN IT (`"antes de que" takes the subjunctive.'): `passano quattro
%% minuti prima che si producano danni' is `pasan cuatro minutos antes de que se
%% produzcan daños'. The mood is the next clause's to read (tr_write/4)
tr_connector_mood(foreign, CO) :-
    member(o(W, _), CO), atom(W), tr_solve(take(W, subjunctive)), !, nb_setval('$tr_sbj', sbj).
tr_connector_mood(_, _).

%% A CLAUSE WRITTEN INSIDE ANOTHER PUTS BACK WHAT IT SET. tr_write/4 keeps
%% the verb and the subject's gender in globals for what it writes after
%% its complements -- a passive's participle agreeing, a bare base after a
%% modal -- and a `that' clause or a relative clause is written in the
%% middle of the complements, so without this the OUTER clause's
%% participle agreed with the inner clause's subject.
tr_write_nested(To, S, Out) :-
    tr_global('$tr_verb', V), tr_global('$tr_subject_gender', G), tr_global('$tr_that_mood', M),
    (   tr_write(To, statement, S, Out0)
    ->  nb_setval('$tr_verb', V), nb_setval('$tr_subject_gender', G), nb_setval('$tr_that_mood', M), Out = Out0
    ;   nb_setval('$tr_verb', V), nb_setval('$tr_subject_gender', G), nb_setval('$tr_that_mood', M), fail
    ).

%% A CLAUSE OF `THAT' IS IN THE SUBJUNCTIVE WHERE THE VERB OR THE ADJECTIVE IT
%% HANGS ON SAYS SO, in the language it is written in: Spanish's `es injusto
%% que los abogados tengan que soportar' is Italian's `è ingiusto che
%% debbano', and Italian's `credo che sia' Spanish's `creo que es'. The lesson
%% names its own (`"vuole" takes the subjunctive.', `"ingiusto" takes the
%% subjunctive.'), and the clause's tense is then written in the subjunctive
%% the lesson states for it; a lesson that names none writes the indicative
%% ... AND A VERB THE LESSON SAYS TAKES THE DENIAL HAS THE SUBJUNCTIVE ONLY
%% WHEN IT IS DENIED (`"cree" takes the denial.'): Spanish's `creo que es' and
%% `no creo que sea', where Italian's `credo che sia' has it either way
%% ... AND A CLAUSE RIGHT AFTER AN INFINITIVE HANGS ON THE INFINITIVE: `ha consentito di stabilire che la banda
%% uccise il nobile romano' established that it killed him, and with the mood of `permitir', which takes the
%% subjunctive, Spanish wrote `permitido establecer que la pandilla matara'
tr_that_mood(Comps, Neg) :-
    (   memberchk(that(_), Comps),
        (   append(Pre, [that(_)|_], Comps), last(Pre, X), ( X = inf(IL) ; X = pinf(_, IL) ; X = infx(IL, _, _) ), atom(IL)
        ->  tr_lexeme_across(IL, foreign, IT), atom(IT), tr_solve(take(IT, subjunctive))
        ;   tr_matrix_subjunctive(Comps, Neg)
        )
    ->  nb_setval('$tr_that_mood', sbj)
    ;   nb_setval('$tr_that_mood', ind)
    ).
tr_matrix_subjunctive(Comps, Neg) :-
    tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V),
    (   tr_lexeme_across(V, foreign, VT), atom(VT), tr_solve(take(VT, subjunctive)) -> true
    ;   Neg == yes, tr_lexeme_across(V, foreign, VT2), atom(VT2), tr_solve(take(VT2, denial)) -> true
    ;   V == is, member(adj(As), Comps), member(w(AW, _), As), atom(AW), tr_lexeme_here(AW, WL),
        tr_meanings_of(WL, foreign, adjective, [M|_]), tr_solve(take(M, subjunctive)) -> true
    ), !.
%% run a goal with the mood a clause is written in
tr_with_mood(sbj, Goal) :- !,
    nb_setval('$tr_mood', sbj),
    (   call(Goal) -> nb_setval('$tr_mood', ind)
    ;   nb_setval('$tr_mood', ind), fail
    ).
tr_with_mood(_, Goal) :- call(Goal).

tr_global(K, V) :- ( catch(nb_getval(K, V0), _, fail) -> V = V0 ; V = none ).

%% THE RELATIVE WORD OUT. For a subject or an object every language here has
%% one word -- `that', `che', `que' -- the relative the lesson gives that
%% means `that'. After a preposition English writes `which' and a lesson
%% writes the relative it says follows a preposition (`"cui" follows the
%% preposition', Italian's `a cui'); a lesson with none writes the article
%% agreeing with the phrase and then its relative, which is Spanish's `al
%% que', `a la que' once the contraction is made.
tr_relative_out(_, whose, _, _, []) :- !.       % the clause's phrase carries its own word
%% (`in which' after a time is `when': `il giorno in cui si potrà tornare a fare il bagno' is the day
%% when one can swim again, and `the day in which' is no English)
tr_relative_out(english, pp(w(in, C)), Noun, _, [o(when, C)]) :-
    atom(Noun), memberchk(Noun, [day, year, moment, time, period, night, week, month, era, age, century, decade,
                                 morning, afternoon, evening, hour, season, summer, winter, spring, autumn]), !.
%% (and after a preposition a person is `whom': `El hombre con quien habla Juan' is the man with whom Juan speaks,
%% where English wrote `with which')
tr_relative_out(english, pp(w(P, C)), Noun, _, [o(P, C), o(whom, lower)]) :-
    atom(Noun), once(( tr_solve(mean(L, Noun)), tr_holds(person(L)) )), !.
tr_relative_out(english, pp(w(P, C)), _, _, [o(P, C), o(which, lower)]) :- !.
%% (a phrase's clause of `where', rc(Phrase, where, Clause): `where', and the lesson's relative word for it)
tr_relative_out(english, where, _, _, [o(where, lower)]) :- !.
tr_relative_out(english, _, _, _, [o(that, lower)]) :- !.
tr_relative_out(foreign, where, _, _, [o(W, lower)]) :- !,
    (   tr_solve(mean(W0, where)), tr_class_of(W0, conjunction) -> W = W0 ; tr_question_across(foreign, _, where, W) ), !.
tr_relative_out(foreign, pp(w(P, C)), Noun, Number, Outs) :- !,
    tr_word_across(w(P, lower), foreign, preposition, PT),
    (   once(( tr_solve(relative(R0)), tr_holds(follow(R0, preposition)) ))
    ->  Outs = [o(PT, C), o(R0, lower)]
    ;   tr_relative_that(R),
        tr_det_out(foreign, det(article, the, w(the, lower)), Noun, Number, [], DOut),
        append([o(PT, C)|DOut], [o(R, lower)], Outs)
    ).
tr_relative_out(foreign, _, _, _, [o(R, lower)]) :- tr_relative_that(R).

tr_relative_that(R) :- once(( tr_solve(relative(R0)), tr_solve(mean(R0, that)) )), R = R0.

%% the relative that stands after a preposition: English's `which', and the
%% one a lesson says follows a preposition
tr_rel_after_prep(english, which) :- !.
tr_rel_after_prep(foreign, R) :- atom(R), tr_solve(relative(R)), tr_holds(follow(R, preposition)), !.
en_bare_person_verb(feeds).
%% (the infinitives after `makes' whose phrase is the one that does it, and the phrases of `of' after that phrase)
en_causee_infinitive(L) :- atom(L), tr_solve(mean_as(_, L, intransitive)), !.
en_causee_infinitive(L) :- atom(L), tr_solve(mean(FL, L)), atom(FL), tr_unaccusative(FL), !.
tr_en_of_run([PP|Cs0], [PP|Ofs], Cs) :- PP = pp(w(of, _), _), !, tr_en_of_run(Cs0, Ofs, Cs).
tr_en_of_run(Cs, [], Cs).
en_with_adjective(A) :- memberchk(A, [equipped, covered, filled, loaded, endowed, provided, armed, laden, furnished]).
%% (an hour: a count with its noun left out in the feminine, `las cinco', or a time in digits, `la 1.30')
en_clock(np(det(article, the, _), w(N, NC), [], elided(feminine), _), [o(N, NC)]) :- en_hour(N), !.
en_clock(np(det(article, the, _), none, [], w(N, NC), singular), [o(N, NC)]) :- en_clock_digits(N), !.
en_clock_pp(pp(w(to, _), NP)) :- en_clock(NP, _), !.
en_clock_pp(pp(w(P, _), NP)) :- en_clock_preposition(P), en_clock(NP, _), !.
en_clock_pp(pp(w(among, _), co(_, NP1, NP2))) :- en_clock(NP1, _), en_clock(NP2, _), !.
en_clock_preposition(P) :- memberchk(P, [after, before, until, 'until after', since, from]).
%% a span of time: a count of a unit of time with no determiner, `siete horas'
tr_span_np(np(none, Num, [], w(U, _), _)) :- Num \== none, atom(U), memberchk(U, [second, minute, hour, day, week, month, year]), !.
tr_span_np(np(det(determiner, 'a couple of', _), none, [], w(U, _), plural)) :- atom(U), memberchk(U, [second, minute, hour, day, week, month, year]), !.
%% (and the source's span, its noun the lesson's word for a unit: `siete horas')
tr_span_source(Sp) :- tr_span_np(Sp), !.
tr_span_source(np(none, Num, [], w(U0, _), Nb)) :-
    Num \== none, atom(U0), tr_noun_lexeme(english, U0, Nb, _, U), tr_span_np(np(none, Num, [], w(U, lower), Nb)), !.
%% (the shape of an hour's phrase before it is crossed, tr_cross_comps/2's part of the day)
tr_clock_shape(fr(X)) :- !, tr_clock_shape(X).
tr_clock_shape(pp(_, np(det(article, _, _), _, [], _, _))) :- !.
tr_clock_shape(pp(_, co(_, _, _))).
en_hour(N) :- en_clock_digits(N), !.
en_hour(N) :- memberchk(N, [one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve]), !.
en_hour(N) :- atom(N), atom_number(N, H), integer(H), H >= 0, H =< 24, !.
en_clock_digits(N) :-
    atom(N), ( atomic_list_concat([HA, MA], '.', N) ; atomic_list_concat([HA, MA], ':', N) ), !,
    atom_length(MA, 2), atom_number(HA, H), atom_number(MA, M), integer(H), integer(M), H >= 0, H =< 24, M >= 0, M < 60.
%% (the part of the day after an hour is said with its own preposition: `entre las 4.30 y las cinco de la mañana' is IN
%% THE MORNING, `la 1.30 de la madrugada' too, and `las once de la noche' AT NIGHT -- English wrote `of the morning')
%% (the adverbs of a part of the day, and the part each says)
en_part_adverb('in the mornings', morning).      en_part_adverb('in the morning', morning).
en_part_adverb('in the afternoons', afternoon).  en_part_adverb('in the afternoon', afternoon).
en_part_adverb('in the evenings', evening).      en_part_adverb('in the evening', evening).
en_day_part(morning, [in, the, morning]).
en_day_part(dawn, [in, the, morning]).
en_day_part(afternoon, [in, the, afternoon]).
en_day_part(evening, [in, the, evening]).
en_day_part(night, [at, night]).
en_takes_from(V) :- memberchk(V, [demands, requests, claims, buys, steals, takes, hides, withholds]).
en_place_np(name(N), in) :- ( tr_city_name(N) ; tr_country_name(N) ), !.
en_place_np(np(_, _, _, named(_, [w(N, _)]), _), in) :- ( tr_city_name(N) ; tr_country_name(N) ), !.
en_place_np(np(_, _, _, named(_, _), _), at) :- !.
en_place_np(np(_, Num, _, w(N, _), _), at) :-
    Num == none, atom(N), \+ atom_number(N, _), \+ en_calendar_word(N), \+ en_time_noun(N),
    N \== time,                                       % (`Tom llegó a tiempo' arrived on time, never `at time')
    \+ ( tr_solve(mean(L, N)), tr_holds(person(L)) ).
en_event_noun(N) :- memberchk(N, [trial, hearing, meeting, concert, conference, ceremony, funeral, session, summit]).
%% (and an activity English names with no article, as an -ism: `cualquier vínculo de su delegación con el dopaje' is
%% any link with doping, and it was `with the doping')
en_mass_activity(N) :- memberchk(N, [doping]).
%% (the dative of `costs' is a clause of tr_comps_out/7: it asks what follows)
en_bare_dative(costs).
tr_amount_np(np(_, Num, _, _, _)) :- Num \== none, !.
tr_amount_np(adv_num(_, NP)) :- !, tr_amount_np(NP).
tr_subject_form_preposition('según').
tr_subject_form_preposition(entre).
tr_prep_contracts(PT) :-
    tr_word_across(w(the, lower), foreign, article, ArtM), atom(ArtM),
    atomic_list_concat([PT, ArtM], ' ', Full), tr_solve(contraction_of(_, Full)), !.
tr_on_head(np(_, _, _, w(N0, _), _), N) :- atom(N0), downcase_atom(N0, N).
tr_on_head(name(N0), N) :- atom(N0), downcase_atom(N0, N).
tr_on_head(with(NP, _), N) :- tr_on_head(NP, N).
tr_on_head(rel(NP, _, _), N) :- tr_on_head(NP, N).
tr_on_head(rc(NP, _, _), N) :- tr_on_head(NP, N).
%% (... and a flight or a vehicle one travels in, with its determiner: `en el vuelo UX-9482')
%% (never `plane', which a film's shot is too: `elementos contemporáneos que se cuelan en el plano')
en_on_vehicle(N) :- memberchk(N, [flight, aeroplane, airplane, airliner, train, bus, coach, ship, boat]).
%% (... and a beach and the sand: `en la playa de Llevant', `en la arena' are on them)
en_on_noun(N) :- memberchk(N, [internet, net, web, website, webpage, page, site, homepage, 'home page', screen, board, noticeboard,
                                 island, beach, sand, television]).    % `in tv' is on television
tr_span_word(NP, PT) :- tr_counted(NP), tr_span_class(NP, Class), tr_solve(begin(PT, Class)), !.
tr_counted(np(_, Num, _, _, _)) :- Num \== none, !.
tr_counted(np(det(article, a, _), _, _, _, _)).
tr_span_class(NP, duration) :- tr_time_phrase(NP).
tr_span_class(np(_, _, _, W, _), measure) :- tr_noun_of_lesson(W, Noun), tr_holds(measure(Noun)).
tr_city_name(N) :-
    atom(N), ( tr_name_word_out(N, L0) -> true ; L0 = N ), tr_unmark(L0, _, L1, _), downcase_atom(L1, L),
    tr_solve(city(L)), !.
tr_perfect_preds(Cs0, Cs) :- tr_perfect_preds(Cs0, Cs0, Cs).
%% ... unless the source's own form said otherwise (pagr/2) and no pronoun
%% stands before the verb for it to agree with: `ha perso la figlia,
%% annegata in una piscina' is `ahogada', the daughter's
tr_perfect_preds(_, [], []).
tr_perfect_preds(All, [pred(L), pagr(G, N)|Cs0], [Out|Cs]) :- !,
    ( memberchk(opron(_), All) -> Out = predinv(L) ; Out = predag(L, G, N) ),
    tr_perfect_preds(All, Cs0, Cs).
tr_perfect_preds(All, [predq(L, C), pagr(G, N)|Cs0], [Out|Cs]) :- !,
    ( memberchk(opron(_), All) -> Out = predqinv(L, C) ; Out = predqag(L, C, G, N) ),
    tr_perfect_preds(All, Cs0, Cs).
tr_perfect_preds(All, [pred(L)|Cs0], [predinv(L)|Cs]) :- !, tr_perfect_preds(All, Cs0, Cs).
tr_perfect_preds(All, [predq(L, C)|Cs0], [predqinv(L, C)|Cs]) :- !, tr_perfect_preds(All, Cs0, Cs).
tr_perfect_preds(All, [C|Cs0], [C|Cs]) :- tr_perfect_preds(All, Cs0, Cs).
%% the second verb of a clause, written as the clause's verb is (tr_complements0/4's cverb/1): English's past, its
%% third person or its base, the lesson's language its form made for the tense and the person
tr_cverbs(_, _, _, _, [], []).
tr_cverbs(To, T, P, N, [cverb(L)|Cs0], [cvw(Os)|Cs]) :- !, tr_cverb_out(To, L, T, P, N, Os), tr_cverbs(To, T, P, N, Cs0, Cs).
tr_cverbs(To, T, P, N, [C|Cs0], [C|Cs]) :- tr_cverbs(To, T, P, N, Cs0, Cs).
tr_cverb_out(english, L, T, _, _, [o(F, lower)]) :- memberchk(T, [past, imperfect]), !, en_past_of(L, F).
tr_cverb_out(english, L, present, third, singular, [o(L, lower)]) :- !.
tr_cverb_out(english, L, _, _, _, [o(F, lower)]) :- en_base(L, F).
tr_cverb_out(foreign, L, T, P, N, [o(F, lower)]) :- tr_lexeme_across(L, foreign, LT), tr_make(LT, N, T, P, F).
tr_gapc_preds(_, [], _, _, []).
tr_gapc_preds(english, [opron(w(everyone, C))|Ps], Noun, Number, [o(all, C)|Outs]) :- !,
    tr_gapc_preds(english, Ps, Noun, Number, Outs).
tr_gapc_preds(To, [P|Ps], Noun, Number, Outs) :-
    tr_comp_out(To, P, Noun, Number, Cl, O, A), append([Cl, O, A], O1),
    tr_gapc_preds(To, Ps, Noun, Number, Os), append(O1, Os, Outs).
%% (the participle and its phrase may have read as an absolute clause when they agree, `mangiato il
%% pane': after `have' it is the participle and its object)
tr_perfect_gerund([pred(L)|Cs], [pred(L)|Cs]) :- !.
tr_perfect_gerund([abs(L, NP)|Cs], [pred(L), obj(NP)|Cs]).

%% ... AND AN ENGLISH VERB OF SEVERAL WORDS THAT ENDS IN A PREPOSITION TAKES THE
%% GERUND AFTER IT, not `to': `se encargó de llevar el peso del partido' took
%% charge OF CARRYING it, where `of to carry' was what the infinitive was
%% (`is about' is the exception: `stanno per ricorrere' is they are about TO
%% appeal, and `about' there is the verb's own, before an infinitive)
tr_verb_ends_in_preposition :-
    tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V), V \== 'is about',
    atomic_list_concat(Parts, ' ', V), Parts = [_, _|_], last(Parts, W),
    memberchk(W, [of, on, in, for, from, about, at, with, by, to]), !.         % (`si sono rassegnati a muoversi' became resigned to MOVING, never `to to move')

%% ... AND A VERB ENGLISH SAYS WITH A PREPOSITION AND A GERUND where the other language has an infinitive: `accusato
%% di aver ucciso Sara' is accused OF HAVING KILLED her, and with `to' it was `accused to have killed'
tr_en_prep_gerund(P) :-
    (   tr_global('$tr_last_pred', L), L \== none -> en_prep_gerund(L, P)        % after a participle, the participle's
    %% (the clause's own verb takes it for its first infinitive alone: `acusó a la mayoría de buscar por todos los
    %% medios hacer daño' is accused OF SEEKING to do harm, and the second came out `of making')
    ;   \+ tr_global('$tr_inf_seen', yes),
        tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V), en_prep_gerund(V, P)
    ), !.
en_prep_gerund(accuses, of).
en_prep_gerund(suspects, of).
en_prep_gerund(blames, for).

%% English's base form as words: `can' has none, and `be able' says it --
%% `in modo da poter utilizzare il denaro' came out `to can to utilise'
en_base_words(can, [o(be, lower), o(able, lower)]) :- !.
en_base_words(LT, [o(B, lower)]) :- en_base(LT, B).

%% ... and the verb being written takes the GERUND where the other language
%% writes an infinitive: `continua a aumentare' is `continúa aumentando', and
%% the lesson says so, `"continúa" takes the gerund.'
tr_verb_takes_gerund :-
    tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V),
    tr_lexeme_across(V, foreign, VT), atom(VT),
    tr_solve(take(VT, gerund)), !.
%% the word the verb being written takes before an infinitive, where the
%% lesson states one: `"confida" takes "di" before the infinitive.'
tr_verb_takes(P) :- tr_verb_takes(P, infinitive).
tr_verb_takes(P, Class) :-
    tr_global('$tr_verb', V0),
    (   V0 = refl(V) -> atom(V), tr_lexeme_across(reflexive(V), foreign, reflexive(VT))     % the word it was written as
    ;   atom(V0), tr_lexeme_across(V0, foreign, VT)
    ), atom(VT),
    tr_solve(take_before(VT, P, Class)), !.
%% THE WORD A VERB PUTS BEFORE ITS QUESTION is written back only where the English
%% verb of the IR governs a preposition (en_governs/2): `si macera su chi
%% dovesse vendere' is `agonises OVER who', and the lesson that writes it says its
%% own word, `"se atormenta" takes "por" before the question.' A verb that takes
%% its question bare in one language (`chiede chi viene') puts nothing back
tr_wh_preposition(english, P) :-
    tr_wh_inf_verb(V), !, en_governs(V, P).
tr_wh_preposition(foreign, P) :-
    tr_wh_inf_verb(V), !, en_governs(V, _),
    tr_lexeme_across(V, foreign, VT), atom(VT), tr_solve(take_before(VT, P, question)).
tr_wh_preposition(english, P) :-
    tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V), en_governs(V, P), !.
tr_wh_preposition(foreign, P) :-
    tr_global('$tr_verb', V0), ( V0 = refl(V) -> true ; V = V0 ), atom(V), en_governs(V, _),
    tr_verb_takes(P, question).
%% the infinitive standing right before a question word is the verb that
%% takes it: `a macerarsi su chi dovesse vendere' puts `over' before the
%% question for `agonises', not for the verb of the clause (set by tr_write/4)
tr_wh_inf_verb(V) :- tr_global('$tr_wh_verb', V), atom(V), V \== none.
tr_wh_verb_set(Cs) :-
    (   append(_, [I, wh(_, _)|_], Cs), ( I = ainf(_, L0) ; I = inf(L0) ),
        ( L0 = qinf(_, L) -> true ; L = L0 ), atom(L)
    ->  nb_setval('$tr_wh_verb', L)
    ;   nb_setval('$tr_wh_verb', none)
    ).

tr_pinf_clitic_out(dat(w(W, _)), T) :- tr_dative_word(W, T), !.
tr_pinf_clitic_out(dat(W), T) :- !, tr_enclitic_out(W, T).
tr_pinf_clitic_out(W, T) :- tr_enclitic_out(W, T).

%% the lesson's dative for an English pronoun, one that stands before the
%% verb first: `gli' and `loro' are both to them, and `loro' stands after the
%% verb and is never joined to one -- the line that lets `non importa loro'
%% read made the writer's first dative `loro', and `senza chiedergli' came
%% out `chiederloro'
tr_dative_word(W, T) :- tr_solve(mean(T, W)), tr_solve(dative(T)), tr_holds(precede(T, verb)), !.
tr_dative_word(W, T) :- tr_solve(mean(T, W)), tr_solve(dative(T)), !.

tr_enclitic_out(refl, R) :- tr_reflexive_out(R), !.
tr_enclitic_out(dat(w(T, _)), F) :- tr_dative_word(T, F), !.
tr_enclitic_out(dat(W), F) :- !, tr_enclitic_out(W, F).
tr_enclitic_out(w(T, C), F) :- tr_pronoun_across(foreign, object, w(T, C), _, _, F).

%% the infinitive with the pronouns joined, the `e' it ends in dropped first
tr_joined_infinitive(Inf, [], Inf) :- !.
%% a verb of several words takes its pronouns on the first: `darse cuenta',
%% `rendersi conto'
tr_joined_infinitive(Inf, Ps, J) :-
    sub_atom(Inf, B, 1, _, ' '), !,
    sub_atom(Inf, 0, B, _, First), B1 is B + 1, sub_atom(Inf, B1, _, 0, Rest),
    tr_joined_infinitive(First, Ps, J1), atomic_list_concat([J1, ' ', Rest], J).
%% ... AND AN INFINITIVE THAT ENDS IN `R' TAKES THE STRESS MARK ON ITS LAST VOWEL
%% BEFORE TWO PRONOUNS: Spanish's `dártelo', `tomársela', `lavármelo' -- with two
%% pronouns joined the stress falls on the third syllable from the end, which
%% a word of that shape marks; with one (`comerlo', `darte') it falls where it
%% always does and nothing is written. Italian's infinitive ends in `e', dropped
%% before them (`darmelo'), and that branch is the one above
tr_joined_infinitive(Inf, Ps0, J) :-
    (   atom_concat(Stem0, e, Inf) -> Stem = Stem0
    ;   Ps0 = [_, _|_] -> tr_stress_stem(Inf, Stem)
    ;   Stem = Inf
    ),
    tr_cluster_pairs(Ps0, Ps),
    atomic_list_concat([Stem|Ps], J).
%% (by atom_concat/3 and not atom_chars/2: the characters of an atom are its
%% bytes there, and a list with `á' in it for atom_chars/2 to join is a crash)
tr_stress_stem(Inf, Stem) :-
    atom_concat(Pre, r, Inf),
    member(V-A, [a-'á', e-'é', i-'í', o-'ó', u-'ú']), atom_concat(Pre0, V, Pre), !,
    atomic_list_concat([Pre0, A, r], Stem).
tr_stress_stem(Inf, Inf).

%% TWO CLITICS JOINED TO A VERB ARE THEIR CONTRACTION where the lesson states
%% one, blank out: `dir' + `mi' + `lo' is `dirmelo', `dar' + `gli' + `lo'
%% `darglielo' (`"glielo" is the contraction of "gli lo".'), and Spanish's
%% `dar' + `le' + `lo' `darselo'; written plain they were `dirmilo', `darsilo'
tr_cluster_pairs([A, B|Ps], Out) :-
    atom(A), atom(B), atomic_list_concat([A, B], ' ', J), tr_solve(contraction_of(K, J)), !,
    atomic_list_concat(Parts, ' ', K), atomic_list_concat(Parts, Joined),
    tr_cluster_pairs([Joined|Ps], Out).
tr_cluster_pairs([P|Ps], [P|Out]) :- !, tr_cluster_pairs(Ps, Out).
tr_cluster_pairs([], []).

%% the perfect's auxiliary as an infinitive: the copula's where the lesson
%% says the verb or the reflexive builds its perfect with it, and otherwise
%% the infinitive of the auxiliary that means `has'
tr_infinitive_auxiliary(LT, Cls, Inf) :-
    (   tr_solve(auxiliary_of(A, LT)) -> true
    ;   memberchk(refl, Cls), tr_solve(auxiliary_of(A, reflexive)) -> true
    ;   tr_solve(auxiliary(A)), tr_solve(mean(A, has)) -> true
    ),
    once(tr_solve(infinitive_of(Inf, A))).

%% THE PARTICIPLE AFTER A PERFECT INFINITIVE'S AUXILIARY: after the copula's
%% it agrees with the subject the infinitive belongs to -- `esser stati
%% ammanettati', `essere andate' -- where `haber sido esposados' was `esser
%% stato ammanettati', the one participle left in the masculine singular
%% beside the predicate that agreed; after `avere' it never agrees
tr_perfect_participle(LT, Cls, Number, PP) :-
    (   ( tr_solve(auxiliary_of(_, LT)) ; memberchk(refl, Cls), tr_solve(auxiliary_of(_, reflexive)) ),
        ( Number == singular ; Number == plural )
    ->  tr_participle_agreeing(LT, Number, PP)
    ;   once(tr_solve(participle_of(PP, LT)))
    ).

tr_gerund_out(english, LT, G) :- !, en_gerund_of(LT, G).
tr_gerund_out(foreign, LT, G) :- once(tr_solve(gerund_of(G, LT))).

%% the target's word for `by': English's own, or the one its lesson gives
tr_by_word(english, by) :- !.
tr_by_word(foreign, By) :- once(tr_solve(mean(By, by))).

%% the verb group being written is a modal
tr_climbed_pronouns([I|Post], [], I, Post) :- ( I = inf(_) ; I = ainf(_, _) ), !.
tr_climbed_pronouns([opron(P)|Cs], [opron(P)|Ps], I, Post) :- tr_climbed_pronouns(Cs, Ps, I, Post).

%% the verb being written takes its own subject's infinitive: a modal, or one
%% of wanting, trying, beginning and going
tr_same_subject_verb :- tr_modal_verb, !.
tr_same_subject_verb :-
    catch(nb_getval('$tr_verb', V0), _, fail), ( V0 = refl(V) -> true ; V = V0 ),
    memberchk(V, [wants, wishes, needs, tries, hopes, prefers, intends, plans, decides, begins, starts,
                  continues, goes, likes, loves, hates, dares]).

tr_modal_verb :-
    catch(nb_getval('$tr_verb', V0), _, fail), tr_side_here(Side),
    %% (a modal with its reflexive on it is a modal still: `¿Me puedo ir a
    %% casa ahora?' is `Can I go ...', and with `to' before the infinitive it
    %% was `Can I to go')
    ( V0 = refl(V) -> true ; V = V0 ),
    %% (`non fa che' is the lesson's modal for `does nothing but', whose
    %% infinitive is bare in English: `does nothing but increase')
    ( Side == english -> ( en_modal_out(V, _, _) ; V == 'does nothing but' ) ; tr_class_of(V, modal) ).

%% ---- the verb group out ---------------------------------------------------------

%% the lesson's verb in the subject's number, tense and person, the denial
%% and the object pronouns before it; the perfect as the auxiliary that
%% means `has' in that form and the participle, the progressive as the one
%% that means `is' and the gerund
%% the lesson's language puts its reflexive pronoun back, before the verb
%% with the other clitics
%% -- UNLESS ITS OWN VERB IS NOT ONE. Spanish's `quedarse' is reflexive and
%% Italian's `rimanere' is not: `se han quedado en casa' is `sono rimasti a
%% casa', and written back it came out `si sono rimasti'. The lesson says it
%% of the word: `"rimane" is not reflexive.'
%% the reflexive's passive: the reflexive pronoun and the verb in the
%% subject's person and number, `si aumentarono le vendite', `se venden
%% casas' -- the construction's pronoun, which a verb the lesson says is not
%% reflexive still takes
%% AN AFFIRMATIVE COMMAND TAKES ITS PRONOUNS JOINED AFTER IT, and a denied one
%% before it: `corregidme', `correggetemi', and `no me corrijáis'. Spanish
%% writes an accent where the longer word moves the stress (`corrígeme'), and
%% no lesson says where a stress falls, so a singular command with a pronoun
%% comes out without it.
fo_group(reflexive(L), P, N, T, passive, Neg, Clitics, Group) :- !,
    ( tr_reflexive_out(R) -> Cs = [o(R, lower)|Clitics] ; Cs = Clitics ),
    fo_group(L, P, N, T, simple, Neg, Cs, Group).
%% (and its perfect is the reflexive's perfect: `que se han depositado', `che si sono depositati')
fo_group(reflexive(L), P, N, T, passive_perfect, Neg, Clitics, Group) :- !,
    fo_group(reflexive(L), P, N, T, perfect, Neg, Clitics, Group).
fo_group(reflexive(L), P, N, T, A, Neg, Clitics, Group) :-
    atom(L), tr_solve(neg(reflexive(L))), !,
    fo_group(L, P, N, T, A, Neg, Clitics, Group).
%% AN INFINITIVE TAKES ITS REFLEXIVE JOINED AFTER IT, never before like a
%% finite verb's: `nuovi linguaggi in cui immergersi', `los temas de los que
%% ocuparse'. Written with the pronoun among the clitics it came out `en el
%% que se sumergir'
fo_group(reflexive(L), P, N, T, infinitive, no, Clitics, Group) :-
    atom(L), tr_reflexive_out(R), !,
    fo_group(L, P, N, T, infinitive, no, Clitics, Group0),
    append(Pre, [o(Inf0, IC)], Group0),
    tr_joined_infinitive(Inf0, [R], Inf), append(Pre, [o(Inf, IC)], Group).
fo_group(reflexive(L), P, N, T, A, Neg, Clitics, Group) :- !,
    ( tr_reflexive_out(P, N, R) -> Cs = [o(R, lower)|Clitics] ; Cs = Clitics ),
    nb_setval('$tr_refl', yes),
    (   fo_group(L, P, N, T, A, Neg, Cs, Group) -> nb_setval('$tr_refl', no)
    ;   nb_setval('$tr_refl', no), fail
    ).
fo_group(L, P, N, T, A, Neg, Clitics, Group) :-
    (   A == passive
    ->  tr_copula_lexeme(CL), tr_make(CL, N, T, P, CForm),
        tr_participle_agreeing(L, N, PP), VW = [o(CForm, lower), o(PP, lower)]
    ;   A == passive_perfect
    ->  tr_copula_lexeme(CL), tr_perfect_auxiliary(CL, Aux), tr_perfect_tense(T, T1), tr_make(Aux, N, T1, P, CForm),
        tr_participle_agreeing(CL, N, Been), tr_participle_agreeing(L, N, PP),
        VW = [o(CForm, lower), o(Been, lower), o(PP, lower)]
    ;   A == perfect
    ->  fo_perfect_aux(L, Aux), tr_perfect_tense(T, T1), tr_make(Aux, N, T1, P, AuxForm),
        %% built with the copula, the participle agrees with the subject:
        %% `si è sbagliato', `è uscita'
        (   tr_copula_lexeme(Aux) -> tr_participle_agreeing(L, N, PP) ; once(tr_solve(participle_of(PP, L))) ),
        VW = [o(AuxForm, lower), o(PP, lower)]
    ;   A == perfect_has
    ->  tr_auxiliary(has, Aux), tr_perfect_tense(T, T1), tr_make(Aux, N, T1, P, AuxForm), once(tr_solve(participle_of(PP, L))),
        VW = [o(AuxForm, lower), o(PP, lower)]
    ;   A == gerund
    ->  once(tr_solve(gerund_of(G, L))), VW = [o(G, lower)]
    ;   A == infinitive
    ->  once(tr_solve(infinitive_of(Inf, L))), VW = [o(Inf, lower)]
    ;   A == imperative, P == polite
    ->  once(( tr_solve(subjunctive_of(IF, L)), \+ tr_holds(past(IF)) )), VW = [o(IF, lower)]
    ;   A == imperative
    ->  tr_imperative_form(L, N, Neg, IF), VW = [o(IF, lower)]
    ;   A == hortative
    ->  once(tr_solve(hortative_of(IF, L))), VW = [o(IF, lower)]
    ;   A == progressive
    ->  tr_auxiliary(is, Aux), tr_make(Aux, N, T, P, AuxForm), once(tr_solve(gerund_of(G, L))), VW = [o(AuxForm, lower), o(G, lower)]
    ;   tr_make(L, N, T, P, Form), VW = [o(Form, lower)]
    ),
    (   Neg == yes
    ->  tr_negation_word(No),
        ( tr_holds(follow(No, verb)) -> append(Clitics, VW, G1), append(G1, [o(No, lower)], Group)
        ; append([o(No, lower)|Clitics], VW, Group) )
    ;   ( A == imperative ; A == hortative ), Clitics = [_|_]
    ->  VW = [o(IF, IC)], findall(CW, member(o(CW, _), Clitics), CWs),     % (T is the tense)
        atomic_list_concat([IF|CWs], J), Group = [o(J, IC)]
    ;   append(Clitics, VW, Group)
    ).

%% THE PAST OF A PERFECT IS THE PLUPERFECT, the auxiliary in the imperfect:
%% `había votado' is `aveva votato' (the lesson's past of the auxiliary, where
%% it states no imperfect: tr_tense_form/3), never the literary past anterior
%% `ebbe votato' -- which is what the past was, once an imperfect was no
%% past form (`si fu annunciato', `ci ebbero parlato')
tr_perfect_tense(past, imperfect) :- !.
tr_perfect_tense(T, T).

tr_fronts_out(To, Cs, Outs) :- tr_fronts_out(To, Cs, none, singular, Outs).
tr_fronts_out(_, [], _, _, []).
tr_fronts_out(foreign, [at_time(NP), adv(w(ago, C))|Cs], Noun0, Number, Outs) :-
    tr_ago_first, !,
    tr_fronts_out(foreign, [adv(w(ago, C)), at_time(NP)|Cs], Noun0, Number, Outs).
%% (a range of dates, its `until' after `from' English's `to', with `e' between the two too: `già dal
%% 14 aprile e fino al 30 settembre' is from April 14 to September 30, as tr_comps_out/7 writes it)
tr_fronts_out(english, [pp(w(from, C1), NP1), cnj(w(and, _)), pp(w(until, C2), NP2)|Cs], Noun0, Number, Outs) :- !,
    tr_fronts_out(english, [pp(w(from, C1), NP1), pp(w(to, C2), NP2)|Cs], Noun0, Number, Outs).
tr_fronts_out(english, [pp(w(from, C1), NP1), pp(w(until, C2), NP2)|Cs], Noun0, Number, Outs) :- !,
    tr_fronts_out(english, [pp(w(from, C1), NP1), pp(w(to, C2), NP2)|Cs], Noun0, Number, Outs).
%% (an hour and the part of the day after it, as tr_comps_out/7 writes them: `Alle 9 di mattina, ...' is At 9 in the
%% morning, en_day_part/2)
tr_fronts_out(english, [PP1, pp(w(of, C), np(det(article, the, _), none, [], w(D, _), singular))|Cs], Noun0, Number, Outs) :-
    en_clock_pp(PP1), en_day_part(D, Ws), !,
    tr_comp_out(english, PP1, none, Number, _, O1, _), findall(o(X, lower), member(X, Ws), O2), O2 = [o(F, _)|O2r],
    tr_fronts_out(english, Cs, Noun0, Number, Rest), append([O1, [o(F, C)|O2r], Rest], Outs).
%% (an adverb before a gerund keeps the comma the source had after it: `Insomma, a scavare bene ..., qualche incrinatura
%% si riesce a trovarla' is in short, digging well into it, one manages to find some crack)
tr_fronts_out(To, [adv(A), ger(L, GCs)|Cs], Noun0, Number, Outs) :- !,
    tr_fronts_out(To, [adv(A)], Noun0, Number, O1), tr_fronts_out(To, [ger(L, GCs)|Cs], Noun0, Number, O2),
    append([O1, [o(',', comma)], O2], Outs).
tr_fronts_out(To, [C|Cs], Noun0, Number, Outs) :-
    ( C = adj(_) -> Noun = Noun0 ; Noun = none ),                    % only an adjective agrees
    (   To == foreign, tr_perfect_before(C, Cs) -> C = pinf(PP, _), C1 = pinf(PP, has_aux) ; C1 = C ),
    tr_comp_out(To, C1, Noun, Number, _, O1, A1), append(O1, A1, O), tr_note_pred(C1),
    tr_fronts_out(To, Cs, Noun, Number, Os), append(O, Os, Outs).

%% THE PERFECT'S AUXILIARY IS THE LESSON'S TO NAME: `"è" is the auxiliary of
%% the reflexive.' makes Italian's `si è sbagliato' where it wrote `si ha
%% sbagliato', and `"è" is the auxiliary of "esce".' names one verb; the
%% one that means `has' otherwise, as it always was.
fo_perfect_aux(L, Aux) :-
    (   tr_global('$tr_refl', yes), tr_solve(auxiliary_of(A0, reflexive)) -> Aux = A0
    ;   tr_solve(auxiliary_of(A0, L)) -> Aux = A0
    ;   tr_auxiliary(has, Aux)
    ), !.

%% A PARTICIPLE IN A PASSIVE AGREES WITH ITS SUBJECT, and picking the form
%% is what the four `participle_of' rows are for. The gender is the SUBJECT
%% PHRASE's, read out of the global the writer set, and the number comes
%% with it; a form is chosen by asking what the lesson says of the word
%% itself -- `"considerata" is feminine.' -- exactly as an adjective is
%% chosen among the words a meaning gives.
%%
%% THE MASCULINE SINGULAR IS THE FALLBACK and it is stated first by the
%% builder, so a lesson that gives one form writes what it wrote before.
tr_participle_agreeing(L, N, PP) :-
    tr_subject_gender(G),
    findall(P, tr_solve(participle_of(P, L)), Ps0), Ps0 \== [],
    (   member(P, Ps0), tr_participle_is(P, Ps0, G, N) -> PP = P
    ;   Ps0 = [PP|_]
    ), !.
tr_participle_agreeing(L, _, PP) :- once(tr_solve(participle_of(PP, L))).

%% a participle form's own gender and number: the gender the lesson states
%% of the word, and the number by whether it is another form's plural
tr_participle_is(P, Ps, G, N) :-
    ( G == feminine -> tr_holds(feminine(P)) ; \+ tr_holds(feminine(P)) ),
    (   N == plural
    ->  member(S, Ps), S \== P, tr_solve(plural_of(P, S))
    ;   \+ ( member(S, Ps), S \== P, tr_solve(plural_of(P, S)) )
    ).

%% A RELATIVE CLAUSE'S SUBJECT IS THE PHRASE IT SITS ON, AND ITS PARTICIPLE
%% AGREES WITH THAT PHRASE: `i risultati dell'autopsia che verrà effettuata'
%% is the autopsy that will be carried out, and with a gap for a subject the
%% participle agreed with nothing and came out `que será efectuado' -- the
%% phrase's noun's gender is the gap's, for as long as the clause is written
tr_gap_write(To, Noun, S0, Out) :-
    ( Noun \== none, tr_gender(Noun, G0), G0 \== none -> G = G0 ; G = masculine ),
    ( catch(nb_getval('$tr_gap_gender', Old), _, fail) -> true ; Old = masculine ),
    nb_setval('$tr_gap_gender', G),
    tr_collective_gap(To, Noun, S0, S),
    ( tr_write_nested(To, S, Out0) -> R = yes ; R = no ),
    nb_setval('$tr_gap_gender', Old),
    R == yes, Out = Out0.

%% run a goal with the gender a participle must agree with, and put back
%% whatever the enclosing sentence had set -- a reduced relative agrees with
%% its OWN noun, not with the subject of the sentence it sits in
tr_with_gender(G, Goal) :-
    ( catch(nb_getval('$tr_subject_gender', Old), _, fail) -> true ; Old = masculine ),
    nb_setval('$tr_subject_gender', G),
    ( call(Goal) -> R = yes ; R = no ),
    nb_setval('$tr_subject_gender', Old),
    R == yes.

%% the gender of the subject the writer is putting out, set by tr_write/4
tr_subject_gender(G) :- ( catch(nb_getval('$tr_subject_gender', G0), _, fail) -> G = G0 ; G = masculine ).
%% the gender a clause's subject gives what agrees with it: its noun's, and
%% where it has none a pronoun's -- `Ella es alta' is `Lei è alta', where the
%% pronoun gave nothing and it came out `alto' -- and the masculine otherwise
tr_subject_gender_of(gap(_, _), _, SG) :- !,
    ( catch(nb_getval('$tr_gap_gender', SG0), _, fail) -> SG = SG0 ; SG = masculine ).
tr_subject_gender_of(Subject, Noun, SG) :-
    (   Noun \== none, tr_gender(Noun, SG0), SG0 \== none -> SG = SG0
    ;   Subject = pronoun(_, _, w(she, _)) -> SG = feminine
    ;   SG = masculine
    ).
%% ... and where the subject gives none, the gender its own participle or
%% adjective gave in the source (sagr/1, tr_subject_agreement/6)
tr_clause_gender(Subject, Noun, Comps, SG) :-
    tr_subject_gender_of(Subject, Noun, SG0),
    ( SG0 == masculine, tr_genderless_subject(Subject), memberchk(sagr(G), Comps) -> SG = G ; SG = SG0 ).

%% ... AND AN IMPERSONAL SUBJECT'S PARTICIPLE AGREES WITH WHAT WAS DONE: `En
%% Barcelona se ha producido una magnífica coincidencia' is `si è prodotta
%% una magnifica coincidenza' -- Italian builds the impersonal's perfect
%% with the copula (`"è" is the auxiliary of the reflexive.'), and with the
%% gender of a subject that names nobody the participle came out `si è
%% prodotto'. Spanish's perfect is built with `ha' and agrees with nothing,
%% so only a copula's participle ever reads this.
%% ONLY THE IMPERSONAL'S OWN PERFECT, and only its group: `y se situará en
%% torno a ..., tras haber sufrido sucesivos descensos' has an object of the
%% perfect infinitive among the clause's complements, and set for the whole
%% clause its gender reached that participle -- `dopo aver sofferta
%% successive diminuzioni'
tr_impersonal_gender(impersonal, Comps, G) :-
    memberchk(obj(NP), Comps), tr_np_head(NP, np(_, _, _, w(NW, _), N)),
    tr_noun_lexeme(foreign, NW, N, _, Noun), tr_gender(Noun, G), G \== none, !.

%% the word this lesson uses for a reflexive, if it has one
tr_reflexive_out(R) :- tr_solve(reflexive(R)), tr_class_of(R, pronoun), !.
%% ... and the pronoun that means `one' and stands alone, for the impersonal
%% of a reflexive verb where the lesson states no form of its own
%% (tr_write/4): Spanish's `uno se salva'. Asked with its first argument
%% unbound, which walks mean/2 -- once, and only for that clause's shape
tr_one_pronoun(U) :-
    tr_solve(mean(U, one)), atom(U), tr_class_of(U, pronoun),
    \+ tr_impersonal(foreign, U), \+ tr_holds(precede(U, verb)), !.
%% ... in a person: the first and second persons' reflexive is their object
%% pronoun, the one that stands before the verb -- `me he acercado', `mi
%% sono avvicinato' (tr_personal_reflexive/8 reads it)
tr_reflexive_out(P, N, R) :-
    nonvar(P), memberchk(P, [first, second]), tr_personal_object(P, N, E),
    tr_pronoun_across(foreign, object, w(E, lower), _, _, R), tr_holds(precede(R, verb)), !.
tr_reflexive_out(_, _, R) :- tr_reflexive_out(R).

%% the auxiliary that means `has' (the perfect) or `is' (the progressive):
%% the one so meant, and for the perfect the first the lesson names at
%% all, as before a lesson said what its auxiliary meant
tr_auxiliary(has, Aux) :- tr_solve(auxiliary(Aux)), tr_solve(mean(Aux, has)), !.
tr_auxiliary(has, Aux) :- tr_solve(auxiliary(Aux)), tr_solve(mean(Aux, _)), !.
tr_auxiliary(is, Aux) :- tr_solve(auxiliary(Aux)), tr_solve(mean(Aux, is)), !.

%% ENGLISH HAS ONE PAST, and the imperfect a language reads (`existía') is
%% written as it: `there was no consensus'
en_group(L, P, N, imperfect, A, Neg, Statement, Front, Tail) :- !,
    en_group(L, P, N, past, A, Neg, Statement, Front, Tail).
%% English's verb group: the statement's words, and for a question the word
%% that fronts and the words that stay behind the subject. A modal is its
%% own word in the tense (`can', `could'), never `does', and `cannot' denied
en_group(L, _, _, T, simple, Neg, Statement, Front, Tail) :- en_modal_out(L, _, _), !,
    (   L == can, T == future
    ->  %% `can' HAS NO FUTURE, and `will be able to' says it: `le attività
        %% potranno svolgersi' was refused, with nothing to write for `can'
        Front = o(will, lower), Able = [o(be, lower), o(able, lower), o(to, lower)],
        ( Neg == yes -> Tail = [o(not, lower)|Able] ; Tail = Able )
    ;   L == must, T == future
    ->  %% ... AND `must' HAS NO FUTURE EITHER, and `will have to' says it:
        %% `bisognerà leggere le motivazioni' was refused, with nothing to
        %% write for `must' (its past is `had to' below)
        Front = o(will, lower), Have = [o(have, lower), o(to, lower)],
        ( Neg == yes -> Tail = [o(not, lower)|Have] ; Tail = Have )
    ;   en_modal_out(L, T, M),
        (   Neg == yes -> ( M == can -> Front = o(cannot, lower), Tail = [] ; Front = o(M, lower), Tail = [o(not, lower)] )
        ;   Front = o(M, lower), Tail = []
        )
    ),
    Statement = [Front|Tail].
%% ... EXCEPT THE REFLEXIVE OF `calls', WHICH IS THE PASSIVE: `il farmaco si
%% chiama Egibren' is `the medicine is called Egibren', never `the medicine
%% calls Egibren', and `mi chiamo Paolo' `I am called Paolo'
en_group(reflexive(calls), P, N, T, simple, Neg, Statement, Front, Tail) :- !,
    en_group(calls, P, N, T, passive, Neg, Statement, Front, Tail).
%% ENGLISH DROPS IT: there is no reflexive pronoun in `the generals appealed',
%% and writing one would say something the Italian does not.
en_group(reflexive(L), P, N, T, A, Neg, Statement, Front, Tail) :- !,
    en_group(L, P, N, T, A, Neg, Statement, Front, Tail).

%% English's passive: the copula in the subject's person and number and the
%% participle; the perfect passive `has been' and the participle. English
%% has no agreement to make, so the participle is simply the one the lesson
%% gave or -ed makes.
en_group(L, P, N, T, passive, Neg, Statement, Front, Tail) :- !,
    en_participle_of(L, PP),
    (   T == future -> Front = o(will, lower), Be = [o(be, lower)]
    ;   T == conditional -> Front = o(would, lower), Be = [o(be, lower)]
    ;   en_copula_form(P, N, T, C), Front = o(C, lower), Be = []
    ),
    ( Neg == yes -> Not = [o(not, lower)] ; Not = [] ),
    append([Not, Be, [o(PP, lower)]], Tail),
    Statement = [Front|Tail].
en_group(L, P, N, T, passive_perfect, Neg, Statement, Front, Tail) :- !,
    en_perfect_front(P, N, T, Front, Have),
    en_participle_of(L, PP),
    ( Neg == yes -> Not = [o(not, lower)] ; Not = [] ),
    append([Not, Have, [o(been, lower), o(PP, lower)]], Tail),
    Statement = [Front|Tail].

%% the copula's imperative is `be', denied `do not be': `Estate contento.'
%% came out `Is happy.'
en_group(is, _, _, _, imperative, Neg, Statement, Front, Tail) :- !,
    (   Neg == yes -> Front = o(do, lower), Tail = [o(not, lower), o(be, lower)]
    ;   Front = o(be, lower), Tail = []
    ),
    Statement = [Front|Tail].
%% -- and `is' with a gerund after it (`is being careful') is CUT AND THEN
%% REFUSED on purpose: the copula has no progressive this writes, and
%% falling through to the clause below would put the stemmer on `is'
%% A VERB OF SEVERAL WORDS THAT OPENS ON THE COPULA IS THE COPULA'S: `servono
%% nove miliardi' is `nine billions ARE needed', and inflected by its base
%% it was `be needed'
en_group(L, P, N, T, A, Neg, [Front|Tail], Front, Tail) :-
    L \== is, en_phrasal(L, is, Pt), !,
    en_group(is, P, N, T, A, Neg, _, Front, T0), append(T0, [o(Pt, lower)], Tail).
%% (the copula's own progressive, `is being', is the general clause's below:
%% with the cut first, `El comité está siendo presionado' had no English)
%% (and its gerund, `being', the gerund's below: `essendo la spartizione dei finanziamenti un momento cruciale' is the
%% sharing out being a crucial moment, where it was `is')
en_group(is, P, N, T, A, Neg, Statement, Front, Tail) :- A \== progressive, A \== gerund, !,
    ( Neg == yes -> Not = [o(not, lower)] ; Not = [] ),
    (   A == perfect
    ->  en_perfect_front(P, N, T, Front, Have), append([Not, Have, [o(been, lower)]], Tail)
    ;   T == future
    ->  Front = o(will, lower), append(Not, [o(be, lower)], Tail)
    ;   T == conditional
    ->  Front = o(would, lower), append(Not, [o(be, lower)], Tail)
    ;   en_copula_form(P, N, T, C), Front = o(C, lower), Tail = Not
    ),
    Statement = [Front|Tail].
%% ENGLISH'S IMPERATIVE IS THE BASE FORM, and its denial is `do not' --
%% never `does not', because an imperative has no person to agree with.
en_group(L, _, _, _, imperative, Neg, Statement, Front, Tail) :- !,
    en_base(L, B),
    (   Neg == yes
    ->  Front = o(do, lower), Tail = [o(not, lower), o(B, lower)], Statement = [Front|Tail]
    ;   Front = o(B, lower), Tail = [], Statement = [Front]
    ).
%% ... AND ITS COMMAND OF THE FIRST PERSON PLURAL IS `let us' and the base,
%% denied `let us not'
en_group(L, _, _, _, hortative, Neg, Statement, Front, Tail) :- !,
    en_base(L, B), Front = o(let, lower),
    ( Neg == yes -> Tail = [o(us, lower), o(not, lower), o(B, lower)] ; Tail = [o(us, lower), o(B, lower)] ),
    Statement = [Front|Tail].
en_group(L, _, _, _, gerund, Neg, Statement, Front, []) :- !,
    en_gerund_of(L, G), Front = o(G, lower),
    ( Neg == yes -> Statement = [o(not, lower), Front] ; Statement = [Front] ).
%% ... AND ITS INFINITIVE `to' AND THE BASE (a question's `how to tackle'), denied
%% `not to'
en_group(L, _, _, _, infinitive, Neg, Statement, Front, Tail) :- !,
    en_base(L, B),
    (   Neg == yes -> Front = o(not, lower), Tail = [o(to, lower), o(B, lower)]
    ;   Front = o(to, lower), Tail = [o(B, lower)]
    ),
    Statement = [Front|Tail].
%% `MUST' HAS NO PERFECT, AND `HAS HAD TO' SAYS IT: `un equipo que ha debido asimilar 17 nuevos fichajes' is a
%% team that has had to assimilate them, and written as a verb it was `has musted'. The perfect of `have to',
%% in every tense of the perfect (`had had to', `will have had to')
en_group(must, P, N, T, perfect, Neg, Statement, Front, Tail) :- !,
    en_perfect_front(P, N, T, Front, Have),
    ( Neg == yes -> Not = [o(not, lower)] ; Not = [] ),
    append([Not, Have, [o(had, lower), o(to, lower)]], Tail),
    Statement = [Front|Tail].
%% ... AND NEITHER HAS `CAN', WHOSE PERFECT `HAS BEEN ABLE TO' SAYS: `non ho
%% potuto mangiare per un giorno intero' is I have not been able to eat, and
%% written as a verb it was `I have not caned eat'; in every tense of the
%% perfect (`chi avrebbe potuto pensare' is who would have been able to
%% think)
en_group(can, P, N, T, perfect, Neg, Statement, Front, Tail) :- !,
    en_perfect_front(P, N, T, Front, Have),
    ( Neg == yes -> Not = [o(not, lower)] ; Not = [] ),
    append([Not, Have, [o(been, lower), o(able, lower), o(to, lower)]], Tail),
    Statement = [Front|Tail].
en_group(L, P, N, T, A, Neg, Statement, Front, Tail) :-
    en_base(L, B),
    ( Neg == yes -> Not = [o(not, lower)] ; Not = [] ),
    (   A == perfect
    ->  en_perfect_front(P, N, T, Front, Have), en_participle_of(L, PP),
        append([Not, Have, [o(PP, lower)]], Tail), Statement = [Front|Tail]
    ;   A == progressive
    ->  en_gerund_of(L, G),
        (   T == future -> Front = o(will, lower), append(Not, [o(be, lower), o(G, lower)], Tail)
        ;   T == conditional -> Front = o(would, lower), append(Not, [o(be, lower), o(G, lower)], Tail)
        ;   en_copula_form(P, N, T, C), Front = o(C, lower), append(Not, [o(G, lower)], Tail)
        ),
        Statement = [Front|Tail]
    ;   T == future
    ->  Front = o(will, lower), append(Not, [o(B, lower)], Tail), Statement = [Front|Tail]
    ;   T == conditional
    ->  Front = o(would, lower), append(Not, [o(B, lower)], Tail), Statement = [Front|Tail]
    ;   en_do(P, N, T, D), Front = o(D, lower), append(Not, [o(B, lower)], Tail),
        (   Neg == yes -> Statement = [Front|Tail]
        ;   T == past -> en_past_of(L, Past), Statement = [o(Past, lower)]
        ;   P == third, N == singular -> Statement = [o(L, lower)]
        ;   Statement = [o(B, lower)]
        )
    ).

en_copula_form(first, singular, present, am) :- !.
en_copula_form(third, singular, present, is) :- !.
en_copula_form(_, _, present, are) :- !.
en_copula_form(first, singular, past, was) :- !.
en_copula_form(third, singular, past, was) :- !.
en_copula_form(_, _, past, were).

en_have(_, _, past, had) :- !.
en_have(third, singular, _, has) :- !.
en_have(_, _, _, have).

%% the perfect's front in a tense: `has', `had' -- and `will have', `would
%% have', where the lesson's conditional perfect (`avrebbe intascato', what
%% a newspaper says was alleged) came out `has pocketed'
en_perfect_front(_, _, future, o(will, lower), [o(have, lower)]) :- !.
en_perfect_front(_, _, conditional, o(would, lower), [o(have, lower)]) :- !.
en_perfect_front(P, N, T, o(H, lower), []) :- en_have(P, N, T, H).

en_do(_, _, past, did) :- !.
en_do(third, singular, _, does) :- !.
en_do(_, _, _, do).

en_base(has, have) :- !.
en_base(V, B) :- en_phrasal(V, V1, P), !, en_base(V1, B1), atomic_list_concat([B1, P], ' ', B).
en_base(V, B) :- reason_base(V, B).

%% A VERB OF TWO WORDS INFLECTS ITS FIRST: `ends up' is `must end up',
%% `ended up', `ending up' -- where the stemmer took the whole atom and
%% wrote `must ends up'. The lesson gives such a verb as it gives any other,
%% in the third person (`The intransitive verb "finisce" means "ends up".').
en_phrasal(V, V1, P) :- atom(V), sub_atom(V, Bf, 1, _, ' '), !, sub_atom(V, 0, Bf, _, V1), Af is Bf + 1, sub_atom(V, Af, _, 0, P).

%% the past of a verb the lesson gave in the third person: one the lesson
%% stated (`"ate" is the past of "eats"'), `had', or the regular -ed --
%% lived, carried, walked; the participle stated, or the past
en_past_of(V, P) :- tr_solve(past_of(P0, V)), !, P = P0.
en_past_of(has, had) :- !.
en_past_of(does, did) :- !.                      % (`lo hizo', he did it: tr_write/4's `does')
en_past_of(V, P) :- en_phrasal(V, V1, Pt), !, en_past_of(V1, P1), atomic_list_concat([P1, Pt], ' ', P).
en_past_of(V, P) :- en_base(V, B), tr_english_ed(B, P).

%% (`does', which the reader never makes and tr_write/4's `makes' with nothing
%% made does: `lo han hecho' is they have DONE it)
en_participle_of(does, done) :- !.
%% (`can' has none, and `been able' says it after `have', the infinitive
%% after it taking its `to': `di non aver mai potuto incontrare Fellini' is
%% not to have been able to meet him, and it was `not to have caned to
%% meet'; en_group/9 has its perfect)
en_participle_of(can, 'been able') :- !.
en_participle_of(V, PP) :- tr_solve(participle_of(P0, V)), !, PP = P0.
en_participle_of(V, PP) :- en_phrasal(V, V1, Pt), !, en_participle_of(V1, P1), atomic_list_concat([P1, Pt], ' ', PP).
en_participle_of(V, PP) :- en_past_of(V, PP).

tr_english_ed(B, P) :- sub_atom(B, _, 1, 0, e), !, atom_concat(B, d, P).
tr_english_ed(B, P) :- reason_third(B, T), atom_concat(Stem, ies, T), !, atom_concat(Stem, ied, P).
tr_english_ed(B, P) :- atom_concat(B, ed, P).

%% the gerund of a verb the lesson gave in the third person: one the lesson
%% stated (`"running" is the gerund of "runs"'), `being', `having', or the
%% base and -ing by the rule below
en_gerund_of(V, G) :- tr_solve(gerund_of(G0, V)), !, G = G0.
en_gerund_of(is, being) :- !.
en_gerund_of(has, having) :- !.
en_gerund_of(V, G) :- en_phrasal(V, V1, Pt), !, en_gerund_of(V1, G1), atomic_list_concat([G1, Pt], ' ', G).
en_gerund_of(V, G) :- en_base(V, B), tr_english_ing(B, G).

%% -ing on a base: ie becomes y (lying), a final e goes unless another e, a
%% y or an o precedes it (making, seeing, dyeing, hoeing); `being' is its
%% own. A doubled consonant (running) is no rule of this, and is a line of
%% the lesson's -- corpus/build.pl writes one for every verb this rule
%% gets wrong, which is why the rule is the translator's and not copied
tr_english_ing(be, being) :- !.
tr_english_ing(B, G) :- atom_concat(S, ie, B), !, atom_concat(S, ying, G).
tr_english_ing(B, G) :- atom_concat(S, e, B), \+ sub_atom(S, _, 1, 0, e), \+ sub_atom(S, _, 1, 0, y), \+ sub_atom(S, _, 1, 0, o), !, atom_concat(S, ing, G).
tr_english_ing(B, G) :- atom_concat(B, ing, G).

%% ---- assembling the sentence -----------------------------------------------------

en_assemble(statement, _, _, Subject, Statement, _, _, Rest, Outs) :- !,
    tr_concat([Subject, Statement, Rest], Outs).
%% ... AND `WHY' TAKES THE BARE INFINITIVE: `perché celebrare un processo?' is `why
%% celebrate a trial', never `why to celebrate' (`how to tackle' keeps its `to')
en_assemble(question, reason(_), AskedOut, [], _, o(to, lower), Tail, Rest, Outs) :- !,
    tr_concat([AskedOut, Tail, Rest], Outs).
en_assemble(question, Asked, AskedOut, Subject, Statement, Front, Tail, Rest, Outs) :-
    (   Asked = subject(_) -> tr_concat([Subject, Statement, Rest], Outs)
    ;   tr_concat([AskedOut, [Front], Subject, Tail, Rest], Outs)
    ).

fo_assemble(none, _, Subject, Group, Rest, Outs) :- !, tr_concat([Subject, Group, Rest], Outs).
fo_assemble(subject(_), _, Subject, Group, Rest, Outs) :- !, tr_concat([Subject, Group, Rest], Outs).
fo_assemble(_, AskedOut, Subject, Group, Rest, Outs) :- tr_concat([AskedOut, Group, Subject, Rest], Outs).

tr_concat([], []).
tr_concat([L|Ls], Outs) :- tr_concat(Ls, Rest), append(L, Rest, Outs).

%% ---- one word across --------------------------------------------------------------

%% a word's lexeme on this side, its meanings on the other of the class
%% asked for, the first of them
%% THE AGENT'S `by' BELONGS TO THE PASSIVE. Spanish's `por' is `by' after a
%% passive -- read there as by/1, never as a phrase -- and `for', `through'
%% or `because of' everywhere else: `por una lesión' is out for an injury,
%% `optó por una vía' opted for a way, and crossed by its first meaning they
%% came out `da una lesione', `da una via', the agent's `da'. A phrase with
%% a preposition that is no agent crosses by its first meaning that is not
%% `by', when the lesson gives it another.
tr_prep_across(P, PT) :-
    tr_word_across(w(P, lower), english, preposition, PT0),
    (   PT0 == by, tr_side_here(Side), Side == foreign, tr_lexeme(foreign, P, L, _),
        tr_meanings_of(L, english, preposition, Ms), member(PT, Ms), PT \== by
    ->  true
    ;   PT = PT0
    ).

%% the words of `not only ... but (also)': English's own, and a lesson's
%% word for `not', for `only', the partner it names for that word or its
%% `but', and its `also'
tr_nonly_words(To, pl(Also), NotO, OnlyO, ButO, Al) :- !, tr_nonly_words(To, Also, NotO, OnlyO, ButO, Al).
tr_nonly_words(To, c(Also), NotO, OnlyO, [o(',', comma)|ButO], Al) :- !, tr_nonly_words(To, Also, NotO, OnlyO, ButO, Al).
tr_nonly_words(english, Also, [o(not, lower)], [o(only, lower)], [o(but, lower)], Al) :- !,
    ( Also == yes -> Al = [o(also, lower)] ; Also == even -> Al = [o(even, lower)] ; Al = [] ).
tr_nonly_words(foreign, Also, [o(No, lower)], [o(Only, lower)], [o(But, lower)], Al) :-
    tr_negation_word(No), tr_word_across(w(only, lower), foreign, adverb, Only),
    ( tr_solve(partner_of(But, Only)) -> true ; tr_word_across(w(but, lower), foreign, conjunction, But) ),
    (   Also == yes -> tr_word_across(w(also, lower), foreign, adverb, AlW), Al = [o(AlW, lower)]
    ;   Also == even -> tr_word_across(w(even, lower), foreign, adverb, AlW), Al = [o(AlW, lower)]
    ;   Al = []
    ), !.

tr_word_across(w(W, _), To, Class, T) :-
    tr_side_here(Side),
    tr_lexeme(Side, W, L, _), !,
    tr_meanings_of(L, To, Class, [T|_]).
tr_word_across(w(W, upper), _, _, W).

%% THE SAME SIDE ON BOTH ENDS IS THE WORD ITSELF. Every crossing is a
%% lookup from the side a sentence was READ on into the side it is
%% WRITTEN to, and the IR's side is English -- so writing an IR back
%% into English asks a word for its meaning on its own side, and the
%% answer is the word. Without this the lookup would go the other way
%% (mean/2 is the lesson's word to English's) and answer the lesson's
%% word for it. The three across predicates each get the rule, because
%% each is a crossing: a meaning, a pronoun and a question word.
tr_meanings_of(L, To, _, [L]) :- tr_side_here(From), From == To, !.
%% AND A NUMBER IS ITSELF IN EVERY LANGUAGE. `200' is 200 in Italian,
%% Spanish and English alike, so it has no mean/2 row and nothing to look
%% up -- and without this clause the lookup found no meaning at all and the
%% phrase was refused: `il premio da 200 milioni' came back `unknown: []',
%% a shape refusal with no shape missing, where `da due milioni' read.
tr_meanings_of(L, _, _, [L]) :- tr_digits(L), !.

%% the meanings of a lexeme on the other side -- of the class asked for,
%% when the lesson classes any of them (the lesson's language has classes;
%% English words are what their translations are)
tr_meanings_of(L, To, Class, Ms) :-
    tr_side_here(From),
    findall(M, tr_meaning(From, L, M), Ms0), Ms0 \== [],
    %% THE CLASS LINKS ARE ASKED FOR A NOUN AND AN ADJECTIVE ONLY. The
    %% dictionary's links for the other classes are noise to this: `más'
    %% is a preposition meaning `plus', `largo' an adverb meaning `largo',
    %% `dónde' an adverb meaning `whither' -- and the class-first lookup
    %% wrote `We need plus food' where the first meaning had been right
    (   To == foreign, memberchk(Class, [noun, adjective]),
        findall(M, ( member(M, Ms0), tr_solve(mean_as(M, L, Class)) ), Ms4), Ms4 \== []
    ->  Ms = Ms4
    %% ... AND A NUMBER IS A WORD THE LESSON CALLS ONE AND NO NOUN: `tra i
    %% dieci e i venti milioni' came out `entre los decena', because the
    %% dictionary gives `ten' to the noun `decena', a group of ten, before
    %% the number `diez' -- and states `decena' a number as well
    ;   To == foreign, Class == number,
        findall(M, ( member(M, Ms0), tr_solve(mean_as(M, L, number)), \+ tr_solve(mean_as(M, L, noun)) ), Ms9), Ms9 \== []
    ->  Ms = Ms9
    %% ... and when no word means it IN that class, a word that means it in
    %% some class its sentence gave, before a word of the class that means
    %% something else: `el pequeño' is the small one, and `minuto' is a noun
    %% only as a minute
    %% -- and never a word that names NOBODY or a determiner, the filter
    %% below applied here too: `uno dei paesi' crossed as `se de los
    %% países', the impersonal `se' being the first word of the lesson's
    %% that means `one' in any class
    ;   To == foreign, memberchk(Class, [noun, adjective]),
        findall(M, ( member(M, Ms0), tr_solve(mean_as(M, L, _)), \+ tr_solve(impersonal(M)),
                     \+ tr_det_no_head(M) ), Ms5), Ms5 \== []
    ->  Ms = Ms5
    %% ... toward the lesson's side the same link picks among its words:
    %% `minuto' is a noun (a minute) and an adjective meaning `small', and
    %% a noun's place asking for `small' must not take it for the noun
    ;   To == foreign, findall(M, ( member(M, Ms0), tr_class_of(M, Class) ), Ms1), Ms1 \== []
    ->  Ms = Ms1
    %% the meanings the lesson gave THIS word IN THIS CLASS, when its
    %% sentences said so (tr_mean_links/2): `culpable' in an adjective's
    %% place is `guilty', never the noun's `culprit'
    %% -- and only when the FIRST meaning is linked to another class, so a
    %% meaning the lesson gave with no class (`The word "dónde" means
    %% "where"') is never passed over for one the dictionary classed
    %% ... and an ADVERB the same way: `Ora è indispensabile' is now, and
    %% `ora' is first the hour, a meaning the lesson classed a noun
    %% ... and a DEMONSTRATIVE and a DETERMINER, whose links come from the
    %% dictionary's determiner entries: `este' is the noun `east' first and
    %% `estos instrumentos' came out `East instruments', where Italian has
    %% no demonstrative meaning east and the sentence was refused; and
    %% `ninguna' is the pronoun `none' before it is the determiner `no'
    %% ... and a QUESTION WORD is no noun: `la cosa più difficile del mondo'
    %% is the hardest thing, and `cosa' means `what' first, a question word
    %% of the hand lesson's and a meaning with no class, which the rule
    %% below leaves first -- written as a noun it came out `el qué'
    ;   To == english, From == foreign, Class == noun,
        Ms0 = [M1|_], en_question(M1, _),
        findall(M, ( member(M, Ms0), tr_solve(mean_as(L, M, noun)) ), Ms8), Ms8 \== []
    ->  Ms = Ms8
    ;   To == english, From == foreign, memberchk(Class, [noun, adjective, adverb, demonstrative, determiner]),
        Ms0 = [M1|_], tr_solve(mean_as(L, M1, _)), \+ tr_solve(mean_as(L, M1, Class)),
        %% (in the order the lesson gave them IN THAT CLASS: `medio siglo'
        %% is half a century, the dictionary's first adjective line for
        %% `medio', and walked in the order of the word's meanings in any
        %% class it was `middle', a NOUN's meaning first that an adjective
        %% line gives too -- which Italian has no adjective for)
        findall(M, tr_solve(mean_as(L, M, Class)), Ms3a), list_to_set(Ms3a, Ms3), Ms3 \== []
    ->  Ms = Ms3
    %% ... and a PREPOSITION crosses by what the lesson gave it as one:
    %% `come dividendo straordinario' is as a dividend, and `come' is first
    %% `how', from a sentence that named no class -- which is right for
    %% `come possa essere successo' and was written `cómo dividendo'. The
    %% reader read it as a preposition, so the meaning is a preposition's.
    %% -- ONLY WHEN THE FIRST MEANING HAS NO CLASS AT ALL, the hand lesson's
    %% closed word. Where the dictionary put another class first the order
    %% stands, because a preposition is the class the reader is least sure
    %% of: it reads one by its place before a phrase, and a degree word
    %% stands in the same place -- `más despacio' crossed `más' by its
    %% preposition link, `plus', and `Speak more slowly.' came out `Speak
    %% plus slowly.'
    %% -- AND WHEN IT IS A CONJUNCTION'S, which takes a clause and never a
    %% phrase: `nonostante la continua incertezza' is DESPITE it, and
    %% `nonostante' is first `although', from a lesson that reads the
    %% conjunction; with the order standing it went out `although the
    %% continuous uncertainty', which Spanish could not write
    ;   To == english, From == foreign, Class == preposition,
        Ms0 = [M1|_], ( \+ tr_solve(mean_as(L, M1, _)) -> true ; tr_solve(mean_as(L, M1, conjunction)) ),
        findall(M, ( member(M, Ms0), tr_solve(mean_as(L, M, preposition)) ), Ms6), Ms6 \== []
    ->  Ms = Ms6
    %% ... AND A MEANING THE LESSON LINKS TO THE CLASS ASKED IS NEVER PASSED
    %% OVER FOR ITS SHAPE (tr_english_shaped/3): `l'aeronautica militare' is
    %% the military aeronautics, and `aeronautics' ends as a verb's third
    %% person does, so in a noun's place it gave way to the adjective's
    %% `aeronautical' -- wherever the noun's line came first, which is a
    %% fresh store's order; `una laurea in fisica' came out `en físico',
    %% physical, the same way (1.8.20)
    ;   To == english, From == foreign, memberchk(Class, [noun, adjective]),
        Ms0 = [M1|_], tr_solve(mean_as(L, M1, Class)),
        findall(M, ( member(M, Ms0),
                     ( tr_solve(mean_as(L, M, Class)) -> true
                     ; \+ tr_third_shaped(M), \+ tr_determiner(english, w(M, lower), _, _) ) ), Ms7), Ms7 \== []
    ->  Ms = Ms7
    ;   To == english, tr_english_shaped(Class, Ms0, Ms1), Ms1 \== []
    ->  Ms = Ms1
    %% and the mirror of the determiner rule, for the other side: a word
    %% that names NOBODY is no head of a phrase either. Spanish gives `one'
    %% to the impersonal `se' and to `uno', and with no meaning classed a
    %% noun the first won -- `uno de los paises' came out `se de los ...'
    ;   To == foreign, memberchk(Class, [noun, adjective]),
        findall(M, ( member(M, Ms0), \+ tr_solve(impersonal(M)),
                     \+ tr_det_no_head(M) ), Ms2), Ms2 \== []
    ->  Ms = Ms2
    ;   Ms = Ms0
    ).

%% A DETERMINER IS NO HEAD, UNLESS THE LESSON SAYS IT STANDS ALONE. Italian
%% `uno' is the article before `sc' AND the pronoun `one', so the filter
%% above dropped it with the article and kept the impersonal `si': `uno de
%% los violines' came out `Si dei violini'. `The pronoun "uno" does not
%% precede the verb.' is what says it heads a phrase of its own.
tr_det_no_head(M) :-
    tr_determiner(foreign, w(M, lower), _, _), \+ tr_standalone_det(foreign, w(M, lower)).

%% English words are what their translations are, but their shape says
%% something too: a verb a lesson gives is a third person (`eats',
%% `visits'), so in a verb's place a meaning shaped like one comes first,
%% and in a noun's or an adjective's place one that is not -- `visita' means
%% visit and visits, and which one is where the word stands
%% ... A VERB OF SEVERAL WORDS IS SHAPED BY ITS FIRST (en_phrasal/3), when it
%% ends on a particle: `gives credence to' is a third person as `gives' is,
%% and in a verb's place it gave way to `credits' -- a meaning of one word
%% that ends as a third person does -- wherever the dictionary's came after
%% the lesson's, `La sintesi ... accredita la sensazione' as `abona la
%% sensación'. A phrase that ends on a noun (`heads of state') is no verb.
tr_english_shaped(verb, Ms0, Ms) :- !,
    findall(M, ( member(M, Ms0), ( tr_third_shaped(M) ; tr_phrasal_shaped(M) ) ), Ms).
%% ... and a phrase's head is never a DETERMINER, which is what `uno' needs:
%% the lesson says it is an article meaning `a' and a pronoun meaning
%% `one', and nothing in a lesson says which meaning belongs to which
%% class -- so `uno dei paesi' wrote `a of the countries' by taking the
%% first. A meaning that is one of English's own determiners is not a noun
%% and not an adjective; if that leaves nothing, the unfiltered list stands.
tr_english_shaped(Class, Ms0, Ms) :- memberchk(Class, [noun, adjective]), !,
    findall(M, ( member(M, Ms0), \+ tr_third_shaped(M), \+ tr_determiner(english, w(M, lower), _, _) ), Ms).
%% ... AND AN ADVERB'S PLACE WANTS A MEANING THAT IS ONE. `ancora' is an
%% adverb, a noun and a verb in the vocabulary -- anchor, anchors, even --
%% and a lesson says what a word MEANS and what classes it has and never
%% which meaning belongs to which class, so the first one won and `non sono
%% state ancora accertate' came out `have not been evacuated ANCHOR'.
%%
%% THE TEST NEEDS NO ENGLISH WORD LIST, and that is what makes it a rule
%% rather than a table: an English word is an adverb when some word the
%% lesson calls an adverb AND NOTHING ELSE means it. `even' is meant by
%% `perfino' and `persino', which are adverbs and nothing else; `anchor' is
%% meant by `ancora' alone, which is three things. Same shape as the
%% determiner filter above, and it falls back to the unfiltered list the
%% same way, so a lesson too small to hold a witness loses nothing.
tr_english_shaped(adverb, Ms0, Ms) :- !,
    findall(M, ( member(M, Ms0), tr_adverb_witness(M) ), Ms).
tr_english_shaped(_, _, []).
%% -- and never a word in `-us': the stemmer takes the `s' off `previous'
%% and `serious' as off `eats', so `la ronda anterior' was the ANTERIOR
%% round, `previous' being passed over in an adjective's place as a verb's
%% third person. No English verb's base ends in `u'.
tr_third_shaped(M) :- ( M == is ; M == has ; \+ sub_atom(M, _, 2, 0, us), reason_base(M, B), B \== M ), !.
tr_phrasal_shaped(M) :-
    en_phrasal(M, V, P), tr_third_shaped(V),
    atomic_list_concat(Ws, ' ', P), last(Ws, Last), en_particle(Last), !.
en_particle(to).      en_particle(up).       en_particle(out).     en_particle(off).      en_particle(on).
en_particle(in).      en_particle(down).     en_particle(over).    en_particle(away).     en_particle(of).
en_particle(for).     en_particle(with).     en_particle(at).      en_particle(about).    en_particle(back).
en_particle(into).    en_particle(through).  en_particle(from).    en_particle(by).       en_particle(after).
en_particle(around).  en_particle(along).    en_particle(together). en_particle(forward).  en_particle(apart).
en_particle(aside).   en_particle(ahead).

%% a word the lesson calls an adverb and no other open class
tr_adverb_witness(M) :-
    tr_solve(mean(W, M)), tr_class_of(W, adverb),
    \+ tr_class_of(W, noun), \+ tr_class_of(W, verb), \+ tr_class_of(W, adjective), !.

%% the noun's gender first, none next, the first candidate last
tr_agree(english, [M|_], _, M) :- !.
tr_agree(foreign, Ms, Noun, T) :-
    tr_gender(Noun, G),
    (   G \== none, member(T, Ms), tr_gender(T, G1), G1 == G -> true
    ;   member(T, Ms), tr_gender(T, none) -> true
    ;   Ms = [T|_]
    ).

%% feminine, masculine or none -- feminine asked first, so a word the
%% lesson said was feminine is, whatever a rule adds; a denial wins
%% over a rule, so `"problema" is not feminine' beside `Every noun that
%% ends in "a" is feminine' makes the word what the lesson's masculine
%% says of it, the way `The pronoun "él" does not precede the verb' does;
%% and a masculine the lesson STATES wins over the feminine a rule derives
%% (`"mapa" is masculine.' beside the same rule is `el mapa'), unless the
%% lesson states the feminine too -- `el capital' and `la capital' -- when
%% the feminine is asked first, as it was
%% a phrase whose noun is a NAME carries its gender, because no lesson can be
%% asked what a name is
tr_gender(named(G0, _), G) :- !, G = G0.
tr_gender(elided(G0), G) :- !, G = G0.
tr_gender(W, G) :-
    (   W == none -> G = none
    ;   tr_holds(feminine(W)) -> ( tr_stated_gender(W, masculine) -> G = masculine ; G = feminine )
    ;   tr_holds(masculine(W)) -> G = masculine
    ;   G = none
    ).
%% the gender the lesson states of a word as a fact, and no rule's: a named
%% lesson's facts are its own predicates and its rules lesson/2's; a plain
%% lesson's rules are clauses with a body
tr_stated_gender(W, G) :-
    (   tr_fact(feminine(W)) -> G = feminine
    ;   tr_fact(masculine(W)) -> G = masculine
    ;   G = none
    ).
tr_fact(Goal) :-
    tr_language(L),
    (   L == none -> catch(clause(Goal, true), _, fail)
    ;   tr_namespaced(L, Goal, F), functor(F, N, A), lesson_predicate(N, L, A), tr_solve_plain(F)
    ), !.

%% ---- forms: lexemes, number, tense, person ------------------------------------------

%% a word's lexeme on a side -- the form the lesson gave -- and its number:
%% the word itself when the lesson gave it; the singular of a plural the
%% lesson stated; in the lesson's language the singular whose ending rule
%% makes the word; in English a noun the stemmer takes back
%% A NUMBER IN DIGITS IS ITS OWN LEXEME ON EVERY SIDE. It is the one word
%% no lesson gives and none needs to: `200' is 200 in every language, so it
%% is known, it is a number, and it crosses as itself.
tr_lexeme0(_, W, W, singular) :- tr_digits(W), !.
tr_lexeme0(Side, W, W, singular) :- tr_known(Side, W).
tr_lexeme0(english, an, a, singular) :- tr_known(english, a).
tr_lexeme0(Side, W, S, plural) :- tr_solve(plural_of(W, S)), tr_known(Side, S).
tr_lexeme0(foreign, W, S, plural) :- tr_rule_stem(W, plural, S), tr_known(foreign, S), tr_rule_plural(S, W).
tr_lexeme0(english, W, S, plural) :- reason_base(W, S), S \== W, tr_known(english, S).
tr_lexeme0(english, W, S, plural) :- en_irregular_singular(W, S), S \== W, tr_known(english, S).
%% AN ELIDED FORM IS ITS OWN WORD: `l'' is `lo' or `la' with the vowel gone,
%% and everything the lesson says of what it elides is true of it. The
%% lesson names the pair (`"l'" is the elision of "lo"'), so a language
%% that elides nothing has no row here and this clause never fires.
tr_lexeme0(foreign, W, S, N) :- tr_solve(elision_of(W, F)), tr_lexeme(foreign, F, S, N).
%% ... AND SO IS A SHORTENED ONE: `cualquier signo' is `cualquiera' before a
%% noun and `mal estado' is `malo' (`"cualquier" is the apocope of
%% "cualquiera".'), which the writer already wrote (tr_apocope/4) and the
%% reader could not read back: `cualquier' was a word nobody knew.
tr_lexeme0(foreign, W, S, N) :- tr_solve(apocope_of(W, F)), tr_lexeme(foreign, F, S, N).
%% ... AND ITS PLURAL IS THE FULL WORD'S: `quei morti' is those dead, and
%% the lesson says `"quei" is the plural of "quel".' of the shortened form
%% the noun follows -- the plural clause above asks the singular to be known,
%% and `quel' is known only as what it shortens
tr_lexeme0(foreign, W, S, plural) :- tr_solve(plural_of(W, A)), tr_solve(apocope_of(A, F)), tr_lexeme(foreign, F, S, singular).

%% A WORD'S LEXEMES ARE ASKED FOR ONCE A SENTENCE. Every reading asks them
%% again -- the group finder of each word, the phrase reader of each run --
%% and a sentence of thirty-five words asked 204 829 times for about sixty
%% words: all of them are kept, in order, the first time a word is asked
%% for under the lesson that is set, and the store is emptied wherever a
%% text or a sentence starts (tr_memo_reset/0), because a program may
%% change its lesson between two calls.
tr_lexeme(Side, W, L, N) :-
    atom(W), atom(Side), !,
    nb_getval('$tr_language', Lang),
    tr_memo_w(W, lx(Lang, Side, W), L1-N1, tr_lexeme0(Side, W, L1, N1), Sols),
    member(L-N, Sols).
%% A TOKEN HAS NO LEXEME. Some callers hand one over where a word stands
%% (fo_phrase_starts/1 asks tr_subject_pronoun/4 of `w(W, C)'), and through
%% cocolog 2.16 every clause below failed for it: the plural's and the
%% tenses' endings were tried on its writing with atom_concat/3, which no
%% ending matched. Since 3.0.0 atom_concat/3 of a compound raises, as swipl's
%% does, so a compound is turned down here and every reading stays as it was
tr_lexeme(Side, W, L, N) :- \+ compound(W), tr_lexeme0(Side, W, L, N).

%% every solution of Goal as Template, kept under Key until the next reset.
%% A KEY'S LAST ARGUMENT IS A WORD, AND EACH WORD HAS A GLOBAL OF ITS OWN.
%% A global is copied every time it is read, so one table for the whole
%% sentence cost 62 us a lookup at five hundred entries -- more than most of
%% what it saved; a word's own table holds a handful and costs about two.
%% A reset is a new GENERATION, and a table stamped with an older one is
%% empty: a list of the tables a sentence touched missed every table that
%% already existed, and a lesson changed between two calls read stale
%% answers -- the case caught it, `what' still known after its line went.
%%
%% THE LIST IS KEPT BEFORE IT IS MATCHED AGAINST SOLS. A caller may pass a
%% pattern -- tr_is/3 asks for `[_|_]', whether there is any solution at
%% all -- and findall/3 straight into the pattern FAILED for a word with no
%% solution, before the list was kept: a class test that answered no was
%% never kept, and most class tests answer no. Over the three longest
%% sentences of Monte Livata, 127 006 of 151 166 class tests were asked
%% again from the lesson.
%%
%% AND A WORD'S TABLE IS A LIST, searched by memberchk/2. get_assoc/3 is
%% clauses -- 23 inferences to find one key among seventeen -- where
%% memberchk/2 is one call into C. Every key is ground (an atom from a
%% global, or the words a caller checked with ground/1), so unifying a key
%% finds exactly what comparing it found.
tr_memo(Key, Template, Goal, Sols) :-
    functor(Key, _, A), arg(A, Key, W),
    tr_memo_w(W, Key, Template, Goal, Sols).
%% ... with the word given, by the callers that have it in hand (the lexeme,
%% the form, the class and the coordinator tests: 1 800 of the 2 000 calls a
%% hundred thousand inferences of a long sentence make), which saves
%% the functor/3 and arg/3 and the call of tr_memo/4 itself
tr_memo_w(W, Key, Template, Goal, Sols) :-
    atom_concat('$tr_w|', W, G),
    nb_getval('$tr_gen', Gen),
    (   catch(nb_getval(G, g(Gen, M0)), _, fail) -> true ; M0 = [] ),
    (   memberchk(Key-Sols0, M0) -> Sols = Sols0
    ;   findall(Template, Goal, Sols00), tr_distinct(Sols00, Sols0),
        (   catch(nb_getval(G, g(Gen, M2)), _, fail) -> M3 = M2 ; M3 = [] ),
        nb_setval(G, g(Gen, [Key-Sols0|M3])),
        Sols = Sols0
    ).

%% the solutions once each, in the order they came: a form the lesson states
%% in several ways -- `erano' is the plural of `era' and the past of `sono'
%% -- came back once for each, and every reading that walked the forms of a
%% word walked the same one that many times
tr_distinct([], []).
tr_distinct([X|Xs], [X|Ys]) :- tr_without(Xs, X, Zs), tr_distinct(Zs, Ys).
tr_without([], _, []).
tr_without([Y|Ys], X, Zs) :- ( Y == X -> Zs = Zs1 ; Zs = [Y|Zs1] ), tr_without(Ys, X, Zs1).

tr_memo_generation(G) :- ( catch(nb_getval('$tr_gen', G0), _, fail) -> G = G0 ; G = 0 ).

%% the sentence's words hold a word meaning `by', its agent of one word
%% right after it -- a pronoun that stands after a preposition, or a name,
%% which is what both readers ask (tr_lone_agent/2) -- and its participle
%% right after the agent, or after adverbs only: the readers take a lifted
%% adverb and a comma out between the two before they ask, and the comma is
%% out here too. (THE AGENT IS ASKED HERE TOO: with the participle alone,
%% the Bovalino letter's `lontano anni luce dalla politica fatta di
%% immagini' had the note, and the two readers walked its every phrase for
%% 0.36 million inferences to find no agent. AND NOTHING BUT ADVERBS
%% BETWEEN: with a participle anywhere among the four words after the
%% agent, Livata's `invece di andare da una parte è andata dall'altra' had
%% the note -- `una' stands after a preposition, and `andata' is three
%% words on -- and the walk cost that sentence 0.30 million)
tr_agent_first_note(Ws0) :-
    tr_uncomma(Ws0, Ws),
    append(_, [B, A1|After], Ws), B = w(BW, _), atom(BW), tr_means_by(foreign, B),
    tr_lone_agent(A1, _),
    tr_after_adverbs(After, 3, [w(P, _)|_]), atom(P), tr_participle_here(foreign, P, _), !.
tr_after_adverbs(Ws, _, Ws).
tr_after_adverbs([X|Ws], N, Rest) :-
    N > 0, X = w(_, _), tr_is(foreign, X, adverb), N1 is N - 1, tr_after_adverbs(Ws, N1, Rest).
%% ... AND WHETHER A WORD THAT MAY BE A PARTICIPLE BEFORE ITS NOUN STANDS
%% AFTER A DETERMINER, adverbs between, as `un emocionado Bruno Metsu' has
%% it (tr_np/3). The word is looked up as a participle first -- which
%% tr_pre_participles/3 asks for anyway, two or three indexed lookups where
%% its two class tests are misses of a memo that is new every sentence:
%% over Tatoeba's 400 the note cost 0.31 million inferences, and costs 0.12
%% million this way; asking for the determiner first cost 0.49 million
tr_pptc_note(Ws) :-
    append(Before, [w(PW, _)|_], Ws), atom(PW), tr_pptc_form(PW), tr_pre_participles([w(PW, lower)], _, _),
    reverse(Before, Rev), tr_pptc_before(Rev), !.
tr_pptc_form(P) :-
    ( tr_solve(participle_of(P, _)) -> true ; tr_solve(plural_of(P, S)), tr_solve(participle_of(S, _)) ), !.
tr_pptc_before([D|Ws]) :-
    D = w(_, _), ( tr_determiner(foreign, D, _, _) -> true ; tr_is(foreign, D, adverb), tr_pptc_before(Ws) ).

%% (AND THE FLAG OF WHO SAID SO IS MADE HERE, ONCE A PROCESS: the complement
%% reader's key reads it on every call (tr_complements/4), and a global is
%% found by a SCAN from the first one made -- so one that does not exist is
%% a walk past every word's table and an existence_error caught. It existed
%% only once a `según' clause had been read, and over the controls it cost
%% two per cent of the time for a third of a per cent of the inferences:
%% the Bastille letter 19.75 s against 20.16, five alternating pairs, the
%% ranges apart. Made beside the generation, it is near the front.)
tr_memo_reset :-
    tr_memo_generation(G0), G is G0 + 1, nb_setval('$tr_gen', G), nb_setval('$tr_joined', yes),
    ( catch(nb_getval('$tr_language', _), _, fail) -> true ; nb_setval('$tr_language', none) ),
    nb_setval('$tr_first', no), nb_setval('$tr_agent_first', yes),
    nb_setval('$tr_pptc', yes), nb_setval('$tr_whose', yes), nb_setval('$tr_exclamative', yes),
    nb_setval('$tr_small_name', yes),
    ( catch(nb_getval('$tr_said_to', _), _, fail) -> true ; nb_setval('$tr_said_to', none) ),
    ( catch(nb_getval('$tr_denied', _), _, fail) -> true ; nb_setval('$tr_denied', none) ).

%% THE FORM IS TAKEN APART, NEVER MATCHED AGAINST EVERY WORD. A rule-made
%% form -- `casas' by `takes "s" in the plural', `comerá' by `takes "rá" in
%% the future' -- used to be found by walking every lexeme of the lesson
%% and inflecting each to see whether it came out as the form: 3 000
%% words of vocabulary made one sentence cost 2.8 s, and the cost grew
%% with the lesson. The endings a rule can add are the few the rules
%% name, so the form loses each of them in turn and the stem left is
%% looked up, which is an indexed call whatever the lesson's size; the
%% rule is then checked of that stem as before.
tr_rule_stem(W, T, S) :- tr_endings(T, Es), member(E, Es), atom_concat(S, E, W), S \== ''.

%% the endings the lesson's rules give for a tense or the plural: the
%% heads of its take_in/3 rules, plain or under the language.
%%
%% THE HEADS ARE ENUMERATED WITH clause/2 AND NOT CALLED, because calling
%% take_in(_, E, T) leaves the FIRST argument unbound -- and an unbound
%% first argument keys 0 and skips nothing, so the call walked the whole
%% predicate. tr_endings/2 is asked on nearly every inflection, so over a
%% vocabulary that one line was the entire cost of a sentence: measured
%% on one language taught under a name, 11.522 s with the call and
%% 0.264 s with clause/2 -- 43x, against a plain lesson's 0.279 s.
%%
%% TWO READINGS DIED GETTING HERE. A blanket reverse index (1.4.1) gave
%% every arity-2 relation a copy keyed the other way and was WORSE on
%% every axis; and the meta-interpreted rules of a named lesson, which
%% looked like the answer because a plain lesson's rules are real
%% clauses, are innocent -- a store whose rules still go through
%% tr_body/2 reads in 0.234 s once this line is fixed. The mechanism was
%% right from the first probe and both fixes built on it were wrong: the
%% answer was to stop asking the unbound question, not to index it.
tr_endings(T, Es) :-
    tr_language(L),
    ( atom(T) -> tr_memo(en(L, T), Es0, tr_endings0(L, T, Es0), [Es1]), Es = Es1 ; tr_endings0(L, T, Es) ).

tr_endings0(L, T, Es) :-
    (   L == none
    ->  findall(E, catch(clause(take_in(_, E, T), _), error(_, _), fail), Es0)
    ;   findall(E, ( tr_solve_plain(lesson(L, (take_in(_, E, T) :- _)))
                     ; tr_namespaced(L, take_in(_, E, T), F), catch(clause(F, _), error(_, _), fail) ), Es0)
    ),
    findall(E, ( member(E, Es0), atom(E) ), Es1), sort(Es1, Es).

%% a number in digits. EVERY FORM BELOW BEGINS WITH A DIGIT OR A MINUS, and
%% tr_known/2 asks this of every word first, so the first code is asked
%% first: the four tests cost a word like `casa' some twenty inferences, and
%% the ordinal's own six were a fifth of what this version first cost the
%% controls (1.8.21)
%% ... AND A ROMAN NUMERAL IS A NUMBER TOO, its own meaning in every language
%% and written as the source wrote it: `nel IV secolo' is in the IV century,
%% and `nel VI' the sixth with its noun left out. In capitals it had come
%% through as an acronym, a name no phrase could hold, and the sentence was
%% refused. In small letters (`nel vii secolo') only a word no lesson knows:
%% a year: four digits from 1000 to 2100
tr_year_word(Y) :- atom(Y), atom_length(Y, 4), atom_codes(Y, Cs), forall(member(D, Cs), ( D >= 0'0, D =< 0'9 )),
    atom_number(Y, N), N >= 1000, N =< 2100.
%% `di', `ci', `mi', `vi' and `li' are numerals too. ONE CLAUSE, THE FIRST CODE
%% DECIDING: written as a second clause, every word paid a second
%% atom_codes/2 and a clause entry to find it no numeral, and over Tatoeba's
%% 400 that was 0.33 million of the 1.2 this version first cost them -- and
%% the first code is asked against the fourteen numeral letters in ONE call
%% before the walk, which a word that opens on any other letter never enters
tr_digits(W) :- atom(W), atom_codes(W, [C|Cs]),
    (   ( C =< 0'9, C >= 0'0 ; C == 0'- )
    ->  tr_digits0(W, [C|Cs])
    ;   memberchk(C, [0'i, 0'v, 0'x, 0'l, 0'c, 0'd, 0'm, 0'I, 0'V, 0'X, 0'L, 0'C, 0'D, 0'M]),
        Cs = [_|_], tr_roman_codes([C|Cs], Up), tr_roman_valid(Up),
        %% (the stated relations only: tr_form/5 asks tr_known/2, which asks this)
        ( C >= 0'A, C =< 0'Z -> true ; \+ tr_solve(mean(W, _)), \+ tr_solve(plural_of(W, _)), \+ tr_solve(person_of(W, _)) )
    ).
tr_digits0(_, Cs) :- forall(member(C, Cs), ( C >= 0'0, C =< 0'9 )), !.
%% ... and a number as the text wrote it, sign and separators kept
%% (tr_written_number/4): `1.400', `-10', `41,5'
tr_digits0(_, Cs) :- tr_number_run(Cs, Ns, []), Ns == Cs, !.
%% ... and a percentage, the number with its sign: `41,46%', `100%'
tr_digits0(W, _) :- tr_percent(W), !.
%% ... and an ordinal, the number with its sign: `50º', `1ª' -- and English's
%% `50th', `1st', `2nd', `3rd'
tr_digits0(W, _) :- tr_ordinal(W, _).
tr_ordinal(W, N) :-
    atom(W), member(S, ['º', 'ª', th, st, nd, rd]), atom_concat(N, S, W), N \== '',
    atom_codes(N, Cs), forall(member(C, Cs), ( C >= 0'0, C =< 0'9 )), !.
%% (by atom_concat/3: sub_atom/5 is clauses, it walked every position of the
%% word, and tr_known/2 asks this of every word first -- 0.83 million
%% inferences in five sentences of the controls)
tr_percent(W) :- atom(W), atom_concat(N, '%', W), tr_digits(N).
%% a Roman numeral's letters, in either case, and its shape: thousands, then
%% each place as nine, four, or five and ones -- `IV', `VI', `vii', never `il'
tr_roman_code(C, U) :- ( C >= 0'a, C =< 0'z -> U is C - 32 ; U = C ), memberchk(U, [0'I, 0'V, 0'X, 0'L, 0'C, 0'D, 0'M]).
tr_roman_codes([], []).
tr_roman_codes([C|Cs], [U|Us]) :- tr_roman_code(C, U), tr_roman_codes(Cs, Us).
tr_roman_valid(Cs) :-
    tr_rn_repeat(0'M, 3, Cs, R1), tr_rn_place(0'C, 0'D, 0'M, R1, R2),
    tr_rn_place(0'X, 0'L, 0'C, R2, R3), tr_rn_place(0'I, 0'V, 0'X, R3, []).
tr_rn_repeat(C, N, [C|Cs], R) :- N > 0, !, N1 is N - 1, tr_rn_repeat(C, N1, Cs, R).
tr_rn_repeat(_, _, R, R).
tr_rn_place(One, _, Ten, [One, Ten|R], R) :- !.
tr_rn_place(One, Five, _, [One, Five|R], R) :- !.
tr_rn_place(One, Five, _, [Five|Cs], R) :- !, tr_rn_repeat(One, 3, Cs, R).
tr_rn_place(One, _, _, Cs, R) :- tr_rn_repeat(One, 3, Cs, R).

tr_known(_, W) :- tr_digits(W), !.
tr_known(foreign, W) :- tr_solve(mean(W, _)), !.
tr_known(english, E) :- tr_solve(mean(_, E)), !.

%% a word the lesson knows on a side, in any of its forms: a lexeme, a
%% plural, a verb's form, or one of English's own
tr_known_word(Side, W) :- tr_lexeme(Side, W, _, _), !.
tr_known_word(foreign, W) :- tr_form(W, _, _, _, _), !.
tr_known_word(foreign, W) :- tr_solve(participle_of(W, F)), tr_known(foreign, F), !.       % of a verb of the lesson's
tr_known_word(english, W) :- en_verb_form(W, _, _), !.
tr_known_word(english, W) :- en_participle(W, _), !.
tr_known_word(english, W) :- en_gerund(W, _), !.
tr_known_word(english, W) :- ( en_subject(W, _, _) ; en_object(W) ; en_possessive(W) ; en_copula(W, _, _, _) ), !.
tr_known_word(english, W) :- ( en_det(W, _, _) ; en_tonic(W, _) ; en_modal_form(W, _, _) ), !.
tr_known_word(english, whom) :- tr_known(english, who), !.
tr_known_word(foreign, W) :- tr_solve(contraction_of(W, _)), !.
tr_known_word(foreign, W) :- tr_solve(elision_of(W, F)), tr_known_word(foreign, F), !.
tr_known_word(foreign, W) :- ( tr_solve(infinitive_of(W, F)) ; tr_solve(gerund_of(W, F)) ), tr_known(foreign, F), !.
tr_known_word(foreign, W) :- tr_solve(imperative_of(W, F)), tr_imperative_known(F), !.       % `Comed el pan.'
%% ... and a word of several words the lesson states only as beginning the
%% purpose, `in modo da' (a word with a lexeme was known by the first clause)
tr_known_word(foreign, W) :- atom(W), atom_codes(W, Cs), memberchk(0' , Cs), tr_solve(begin(W, purpose)), !.

%% ... every reading of a form, kept once a sentence: 23 915 calls over one
%% sentence of thirty-five words before it was
tr_form(W, L, N, T, P) :-
    atom(W), !,
    nb_getval('$tr_language', Lang),
    tr_memo_w(W, fm(Lang, W), f(L1, N1, T1, P1), tr_form0(W, L1, N1, T1, P1), Sols),
    member(f(L, N, T, P), Sols).
tr_form(W, L, N, T, P) :- tr_form0(W, L, N, T, P).

%% a verb form of the lesson's language, taken apart: the lexeme, the
%% number, the tense, the person. A person form the lesson stated first
%% (`"como" is the first person of "come"'); a third person is a present
%% form, singular or plural, or the past or the future of one, or a stated
%% plural of such a tense form
tr_form0(W, L, N, T, P) :-
    tr_solve(person_of(W, F)), ( tr_solve(first(W)) -> P = first ; tr_solve(second(W)) -> P = second ),
    tr_form_nt(F, L, N, T).
tr_form0(W, L, N, T, third) :- tr_form_nt(W, L, N, T).
%% ... AND A PRESENT SUBJUNCTIVE'S FIRST PERSON IS SPELLED AS ITS THIRD, in
%% both lesson languages: `puede ser que me decapite yo mismo' is that I
%% behead myself, and the lesson states the subjunctive of the third person
%% only (`"decapite" is the subjunctive of "decapita".'), so the only reading
%% had `me' for the object and Italian wrote `mi decapita io stesso', HE
%% beheads me. The first person is a reading AFTER the third -- and ONLY IN
%% A SENTENCE THAT NAMES THE FIRST PERSON, which the controls settled: a
%% reading after the third is still a reading, and wherever the third went
%% the long way or failed on the way to something else the first came in
%% its place. `Non si sa come possa essere successo' came out `No se sabe
%% cómo PUEDO haber pasado', `non so se sia legittimo' `no sé si SOY
%% legítimo', and four more controls the same; a clause of the subjunctive
%% with nobody named is the third person's, as 1.6.15 has it.
tr_form0(W, L, singular, present, first) :-
    tr_global('$tr_first', yes),
    tr_solve(subjunctive_of(W, _)), \+ tr_holds(past(W)),
    tr_form_nt(W, L, singular, present).
%% ... and so is a past subjunctive's: `Yo quisiera dormir' is I would like to sleep (tr_polite_wish/4), and the
%% lesson states `"quisiera" is the past subjunctive of "quiere".' of the third person alone
tr_form0(W, L, singular, imperfect, first) :-
    tr_global('$tr_first', yes),
    tr_solve(subjunctive_of(W, _)), tr_holds(past(W)),
    tr_form_nt(W, L, singular, imperfect).
%% ... and so is an imperfect's or a conditional's, where the lesson states no first person of the form itself:
%% `"Yo bajaba cada día a pasear a los perros"' is I went down every day, and Spanish spells the first person
%% of those tenses as the third -- the vocabulary states `"bajaba" is the imperfect of "baja".' and no first
%% person of `bajaba', so with the first person named (`Yo comía pan', `Yo había comido') the clause had no
%% reading. Italian states its own (`"mangiavo" is the first person of "mangiava".'), so `mangiava' stays the
%% third person's
tr_form0(W, L, singular, T, first) :-
    tr_global('$tr_first', yes),
    \+ tr_solve(subjunctive_of(W, _)),
    tr_form_nt(W, L, singular, T), memberchk(T, [imperfect, conditional]),
    \+ ( tr_solve(person_of(F1, W)), tr_solve(first(F1)) ).
%% ... and a verb form the source cut short: `per lei questo DEV essere un
%% periodo molto stressante' writes `dev' for `dev'' (`"dev" is the apocope
%% of "deve".'), which is the form it is short for
tr_form0(W, L, N, T, P) :- tr_solve(apocope_of(W, F)), atom(F), F \== W, tr_form0(F, L, N, T, P).

%% A NOUN'S PLURAL IS NO VERB'S, WHEN THE VERB HAS ONE OF ITS OWN.
%% `"modifiche" is the plural of "modifica".' is the noun's and
%% `"modificano" is the plural of "modifica".' the verb's -- one relation for
%% both, so the noun's plural was a verb form too, and the title of the law,
%% `"Modifiche al codice di procedura penale, ..."', was THEY modify, with
%% nobody named: `Modifican al código'. A verb's plural is the target of the
%% verb's own forms -- `"modifichiamo" is the first person of "modificano"',
%% `"modificarono" is the past of "modificano"' -- so a stated plural that is
%% the target of none, of a word that is a noun as well and has ANOTHER stated
%% plural that is, is the noun's. The other plural is asked for because a
%% lesson that states a noun and a verb of one spelling and no verb form at
%% all (`costa', `pasa' in the case's small lessons) has nothing to tell
%% the two apart by, and reads as it always did. Asked of a word both classes
%% name only: the classes are the memo's, and person_of(_, W) has no first
%% argument to key on, and walks.
tr_noun_plural_only(W, L) :-
    atom(W), tr_is(foreign, w(L, lower), verb), tr_is(foreign, w(L, lower), noun),
    tr_solve(plural_of(W, L)), \+ tr_verb_marked(W),
    tr_solve(plural_of(P, L)), P \== W, tr_verb_marked(P), !.
tr_verb_marked(W) :- ( tr_solve(person_of(_, W)) ; tr_solve(past_of(_, W)) ; tr_solve(imperfect_of(_, W)) ), !.

%% A TENSE STEP CAN COME BACK TO WHERE IT STARTED, so the forms already
%% stepped through are carried and never stepped through twice. `parar' has
%% the indicative `para' and the subjunctive `pare'; `parir' has the
%% indicative `pare' and the subjunctive `para'. BOTH ROWS ARE TRUE and
%% together they are a two-cycle, which tr_tensed(W, present, F) -- the
%% subjunctive step of 1.6.8 -- walked for ever: `Mira para otro lado.' never
%% finished where its four neighbours cost 0.1 to 0.3 s. The FIRST solution
%% was always instant, so only a caller that asks for all of them saw it.
tr_form_nt(W, L, N, T) :- tr_form_nt(W, L, N, T, [W]).

tr_form_nt(W, W, singular, present, _) :- tr_known(foreign, W).
tr_form_nt(W, L, plural, present, _) :- tr_lexeme(foreign, W, L, plural), \+ tr_noun_plural_only(W, L).
tr_form_nt(W, L, N, T, Seen) :-
    tr_tensed(W, T, F), \+ memberchk(F, Seen),
    tr_form_nt(F, L, N, present, [F|Seen]).
tr_form_nt(W, L, plural, T, Seen) :-
    tr_solve(plural_of(W, F)), tr_tensed(F, T, F0), \+ memberchk(F0, Seen),
    tr_form_nt(F0, L, singular, present, [F0|Seen]).

%% a tense form of a present form: stated, or made by an ending rule
%% -- a form the lesson states as an imperfect is no past, though a hand
%% lesson says `"era" is the past of "è"' beside the vocabulary's
%% `"era" is the imperfect of "è"'
tr_tensed(W, past, F) :- tr_solve(past_of(W, F)), \+ tr_solve(imperfect_of(W, F)).
%% THE IMPERFECT IS A TENSE OF ITS OWN: `existía' is `esisteva', never the
%% preterite `esistette' (`"esisteva" is the imperfect of "esiste".'). English
%% has one past, which its writer makes of it (en_group/9)
tr_tensed(W, imperfect, F) :- tr_solve(imperfect_of(W, F)).
tr_tensed(W, future, F) :- tr_solve(future_of(W, F)).
tr_tensed(W, conditional, F) :- tr_solve(conditional_of(W, F)).
%% A SUBJUNCTIVE IS READ AS THE TENSE IT STANDS FOR AND WRITTEN BACK AS
%% THE INDICATIVE. English marks no subjunctive where `che il militare
%% volesse' wants one, and nothing a lesson says tells which verbs take one
%% -- so the mood is read and dropped, and `volesse' comes back `voleva'.
%% The cost is stated in the header; the alternative is refusing the clause.
tr_tensed(W, present, F) :- tr_solve(subjunctive_of(W, F)), \+ tr_holds(past(W)).
%% ... AND A PAST SUBJUNCTIVE IS AN IMPERFECT, which it stands for: `come se i
%% mascalzoni fossero pochi', `Se avessimo più soldi' are `como si eran' and
%% `si teníamos', not the preterite `fueron', `tuvimos' that the past was once
%% an imperfect was no past form
tr_tensed(W, imperfect, F) :- tr_solve(subjunctive_of(W, F)), tr_holds(past(W)).
tr_tensed(W, T, F) :- ( T = past ; T = future ; T = conditional ), tr_rule_stem(W, T, F), tr_present_form(F), tr_solve(take_in(F, E, T)), atom(E), atom_concat(F, E, W).

%% a present form of one of the lesson's verbs, in either number, for a
%% rule to have made a tense of: the lexeme, or a plural of one
tr_present_form(F) :- tr_known(foreign, F), tr_verb_lexeme(F), !.
tr_present_form(F) :- tr_lexeme(foreign, F, S, plural), tr_verb_lexeme(S), !.

tr_rule_plural(S, P) :- tr_solve(take_in(S, E, plural)), atom(E), atom_concat(S, E, P).

%% a form of the lesson's language MADE: the number, the tense, the person
%% -- number then tense (`comieron' is the past of `comen'), or tense then
%% number (`comerán' is the plural of `comerá'), whichever the lesson
%% states; a person the lesson gave no form for is the third's
%% ... AND A VERB THE CLAUSE'S MATRIX ASKS A SUBJUNCTIVE OF IS WRITTEN AS
%% ONE (tr_that_mood/1): the singular's subjunctive, then its number --
%% `tengan' is the plural of `tenga', as the builder states it
tr_make(L, N, T, P, Form) :-
    tr_global('$tr_mood', sbj), memberchk(T, [present, past, imperfect]),
    ( T == present -> Tn = present ; Tn = past ),
    tr_subjunctive_form(L, Tn, F1), tr_number_form(F1, N, F2),
    tr_person_form(F2, P, Form), !.
tr_make(L, N, T, P, Form) :-
    (   tr_number_form(L, N, F1), tr_tense_form(F1, T, F2)
    ;   T \== present, tr_tense_form(L, T, F1), tr_number_form(F1, N, F2)
    ),
    tr_person_form(F2, P, Form), !.
%% A VERB OF SEVERAL WORDS IS MADE BY ITS FIRST WORD, the rest standing as
%% it is: `fa sapere' is `farà sapere' and `fece sapere' -- the lesson
%% states the forms of `fa' and none of the whole, and `El perro informará'
%% was refused for want of a future of `fa sapere'
tr_make(L, N, T, P, Form) :-
    atom(L), sub_atom(L, B, 1, _, ' '), !,
    sub_atom(L, 0, B, _, First), B1 is B + 1, sub_atom(L, B1, _, 0, Rest),
    tr_make(First, N, T, P, F1), atomic_list_concat([F1, ' ', Rest], Form).

tr_subjunctive_form(L, present, F) :- tr_solve(subjunctive_of(F, L)), \+ tr_holds(past(F)).
tr_subjunctive_form(L, past, F) :- tr_solve(subjunctive_of(F, L)), tr_holds(past(F)).

tr_number_form(F, singular, F).
%% A VERB'S PLURAL IS NEVER A PERSON OF THE SAME FORM. `cuenta' is a noun
%% (an account) and a verb, the lesson states the noun's plural first, and
%% `raccontano' came out `cuentas' -- which is the noun's plural and the
%% verb's own second person. The verb's plural is asked for first among the
%% forms that are no person of it, and any stated plural after that.
%% ... NOR A PARTICIPLE'S PLURAL: `pesa' is `weighs' and the feminine
%% participle of `pendere' as well, the vocabulary states `"pese" is the
%% plural of "pesa".' for the participle first, and `le piedras pesan muy
%% poco' came out `pese molto poco' where Italian says `pesano'
tr_number_form(F, plural, P) :- tr_solve(plural_of(P, F)), \+ tr_solve(person_of(P, F)), \+ tr_solve(participle_of(P, _)), \+ tr_noun_plural_only(P, F), !.
tr_number_form(F, plural, P) :- tr_solve(plural_of(P, F)), !.
tr_number_form(F, plural, P) :- tr_rule_plural(F, P).

tr_tense_form(F, present, F) :- !.
%% the past is a form the lesson does not state as an imperfect, `fu' and
%% not `era' (a hand lesson states both as the past of `è'), where it has one
tr_tense_form(F, past, P) :- tr_solve(past_of(P, F)), \+ tr_solve(imperfect_of(P, F)), !.
tr_tense_form(F, past, P) :- tr_solve(past_of(P, F)), !.
%% the imperfect where the lesson states one, and else the past
tr_tense_form(F, imperfect, P) :- tr_solve(imperfect_of(P, F)), !.
tr_tense_form(F, imperfect, P) :- tr_solve(past_of(P, F)), !.
tr_tense_form(F, future, P) :- tr_solve(future_of(P, F)), !.
tr_tense_form(F, conditional, P) :- tr_solve(conditional_of(P, F)), !.
tr_tense_form(F, T, P) :- tr_solve(take_in(F, E, T)), atom(E), atom_concat(F, E, P), !.

tr_person_form(F, third, F) :- !.
tr_person_form(F, P, Form) :- tr_solve(person_of(Form, F)), G =.. [P, Form], tr_solve(G), !.
tr_person_form(F, _, F).

%% a form in a number: the singular as it is; a plural the lesson stated
%% first, then in the lesson's language the singular with the ending its
%% rule gives, and in English a noun by -s, -es or -ies and anything else
%% unchanged. No rule, no plural: the sentence is refused.
tr_inflect(_, _, S, singular, S) :- !.
%% a plural the lesson stated -- but not, in English, of a word that is the
%% LESSON's too: `"redes" is the plural of "red"' is about the Spanish net,
%% and English's red is red in the plural
%% -- nor of any FORM of the lesson's: `"casen" is the plural of "case"' is
%% Spanish's subjunctive, and English's other cases came out `casen'
tr_inflect(To, _, S, plural, P) :-
    tr_solve(plural_of(P0, S)), \+ ( To == english, ( tr_known(foreign, S) ; tr_stated_word(S) ) ), !, P = P0.
tr_inflect(foreign, _, S, plural, P) :- tr_rule_plural(S, P), !.
%% ... AND A DETERMINER THAT THE LESSON STATES NO PLURAL OF STANDS FOR ITS
%% OWN: `ogni cinque famiglie' and `cada cinco familias' say `each' before a
%% plural as they do before a singular, and with the rule for a noun's plural
%% failing on them the phrase could not be written
tr_inflect(foreign, determiner, S, plural, S) :- !.
%% ... AND A POSSESSIVE THE SAME: Italian's `loro' has one form for every
%% gender and number (`i loro servizi'), the lesson states none, and `Los
%% abogados cobran por sus servicios' -- `sus' read as `their' -- was refused
tr_inflect(foreign, possessive, S, plural, S) :- !.
%% (a determiner that says either number stands for a plural as itself:
%% `tanto per citarne alcuni' is to cite some, where the rule wrote `somes')
tr_inflect(english, noun, S, plural, S) :- en_det(S, _, any), !.
%% -- and a noun of several words with `of' in it takes the ending on the
%% word before `of': `todos los puntos de vista' is all the points of view,
%% where the ending went last, `point of views'
tr_inflect(english, noun, S, plural, P) :-
    sub_atom(S, B, _, A, ' of '), B > 0, !,
    sub_atom(S, 0, B, _, H), sub_atom(S, _, A, 0, T),
    en_plural_noun(H, HP), atomic_list_concat([HP, ' of ', T], P).
tr_inflect(english, noun, S, plural, P) :- !, en_plural_noun(S, P).
tr_inflect(english, _, S, plural, S).

%% ENGLISH'S PLURALS THAT ARE NO ENDING'S: `los hombres y las mujeres' were
%% `the mans and the womans', and `las consejeras' `councilwomans'. A plural
%% is the irregular one where English has one -- the table's, the compounds
%% of `man' and `woman', the Latin `-sis' -- and else -s, -es or -ies
%% (reason_third/2); the reader takes one back to its singular
%% (en_irregular_singular/2: `The men eat' is read, where `men' was no word
%% anybody knew)
en_plural_noun(S, P) :- en_irregular_plural(S, P), !.
en_plural_noun(S, P) :- reason_third(S, P).

en_irregular_plural(S, P) :- en_plural_pair(S, P), !.
en_irregular_plural(S, S) :- en_plural_same(S), !.
en_irregular_plural(S, P) :-
    (   atom_concat(Stem, woman, S) -> atom_concat(Stem, women, P)
    ;   atom_concat(Stem, man, S), Stem \== '', \+ en_not_man(S) -> atom_concat(Stem, men, P)
    ;   atom_concat(Stem, sis, S), Stem \== '', \+ memberchk(S, [chassis, tennis]) -> atom_concat(Stem, ses, P)
    %% ... and a Spanish demonym in `-ño' takes `s' alone, as English writes `Malagueños' (`o' made it `Malagueñoes')
    ;   atom_concat(_, 'ño', S) -> atom_concat(S, s, P)
    %% ... and a noun that ends in one `s' takes `es': `bus', `status', `metropolis'
    %% were `buss', `statuss', `metropoliss'
    ;   atom_concat(_, s, S), \+ atom_concat(_, ss, S) -> atom_concat(S, es, P)
    %% ... and a noun in `o' takes `s', where the verb's rule wrote `es': `8.737
    %% chili di nichel' was `8,737 kiloes', and `gli studi' `the studioes' -- but
    %% for the few English writes with `es' (en_oes_plural/1: potatoes, heroes)
    ;   atom_concat(_, o, S), \+ en_oes_plural(S) -> atom_concat(S, s, P)
    ), !.
en_oes_plural(potato).    en_oes_plural(tomato).    en_oes_plural(hero).
en_oes_plural(echo).      en_oes_plural(veto).      en_oes_plural(torpedo).
en_oes_plural(embargo).   en_oes_plural(mosquito).  en_oes_plural(tornado).
en_oes_plural(volcano).   en_oes_plural(cargo).     en_oes_plural(domino).
en_oes_plural(buffalo).   en_oes_plural(mango).

en_irregular_singular(P, S) :- en_plural_pair(S, P), !.
en_irregular_singular(P, S) :-
    (   atom_concat(Stem, women, P) -> atom_concat(Stem, woman, S)
    ;   atom_concat(Stem, men, P), Stem \== '' -> atom_concat(Stem, man, S), \+ en_not_man(S)
    ), !.
%% ... `crises' is the plural of `crisis' and `buses' of `bus': the reader
%% asks which of the two the lesson knows (tr_lexeme0/4)
en_irregular_singular(P, S) :-
    atom_concat(Stem, ses, P), Stem \== '', ( atom_concat(Stem, sis, S) ; atom_concat(Stem, s, S) ).

en_plural_pair(man, men).           en_plural_pair(woman, women).
en_plural_pair(child, children).    en_plural_pair(person, people).
en_plural_pair(foot, feet).         en_plural_pair(tooth, teeth).
en_plural_pair(mouse, mice).        en_plural_pair(goose, geese).
en_plural_pair(ox, oxen).           en_plural_pair(life, lives).
en_plural_pair(wife, wives).        en_plural_pair(knife, knives).
en_plural_pair(leaf, leaves).       en_plural_pair(half, halves).
en_plural_pair(wolf, wolves).       en_plural_pair(shelf, shelves).
en_plural_pair(thief, thieves).     en_plural_pair(loaf, loaves).
en_plural_pair(calf, calves).       en_plural_pair(self, selves).
en_plural_pair(phenomenon, phenomena).  en_plural_pair(criterion, criteria).
en_plural_pair(graffito, graffiti).    en_plural_pair(quiz, quizzes).
en_plural_pair(lira, lire).
%% nouns the lesson's languages say in the singular and English's verb takes in the plural
en_collective_plural(people).       en_collective_plural(police).
en_collective_plural(employers).    % `la patronal bancaria española aboga ...': the employers advocate
%% THE ADVERBS ENGLISH WRITES LAST STAY INSIDE A QUOTATION THAT CLOSES ON THE LAST
%% COMPLEMENT: `"los clientes valoran muy positivamente la oportunidad de ... el
%% Sábado por la mañana"' opens on the subject and closes on the morning, and the
%% adverb moved after it came out `... Saturday morning" very positively'. Only a
%% quotation that opened before the complements (none of them opens one), whose
%% mark the last of them carries; the mark goes to the last adverb
tr_close_after_advs(CompOuts, Advs, Outs) :-
    Advs = [_|_], append(Pre, [o(W, qclose)], CompOuts), \+ memberchk(o(_, qopen), Pre), !,
    append(AdvPre, [o(A, AC)], Advs), ( AC == lower -> AC1 = qclose ; AC1 = AC ),
    append(Pre, [o(W, lower)|AdvPre], Outs0), append(Outs0, [o(A, AC1)], Outs).
tr_close_after_advs(CompOuts, Advs, Outs) :- append(CompOuts, Advs, Outs).
%% (the phrases of `of' at the head of a list of complements, and the rest)
tr_of_run([PP|Cs0], [PP|Ofs], Cs) :- PP = pp(w(of, _), _), !, tr_of_run(Cs0, Ofs, Cs).
tr_of_run(Cs, [], Cs).

%% (nouns whose plural is their singular, and the words that end in `man' and
%% are no man)
en_plural_same(S) :- memberchk(S, [sheep, fish, deer, series, species, means, aircraft, offspring, salmon, trout,
                                   moose, swine, bison, crossroads, headquarters, barracks, news, physics,
                                   politics, economics, mathematics, athletics, gymnastics, ethics,
                                   data]).    % (`i dati relativi a tutti gli istituti', where it was `the datas')
%% ... and a people's name in `-ese': `130 mila milanesi' are 130 thousand Milanese,
%% and English wrote `Milaneses' (the Chinese, the Japanese, the Lebanese)
en_plural_same(S) :- atom(S), atom_concat(_, ese, S), en_nationality(S).
en_not_man(S) :- memberchk(S, [human, german, roman, norman, shaman, talisman, ottoman, caiman, cayman, pullman, walkman]).

%% ---- English's verb forms ---------------------------------------------------------

%% a verb form of English: the third person the lesson gave, the base form
%% whose third person it gave, a past the lesson stated or -ed makes, and
%% the copula's own; a participle stated, `been', or a regular past
en_verb_form(be, is, present) :- !.
en_verb_form(W, W, present) :- tr_known(english, W), tr_class(english, W, verb).
en_verb_form(W, L, present) :- \+ en_own(W), reason_third(W, L), W \== L, tr_known(english, L), tr_class(english, L, verb).
en_verb_form(W, is, T) :- en_copula(W, _, _, T).
en_verb_form(W, L, past) :- \+ en_own(W), en_past_form(W, L).

%% one of English's own words is never a verb form, whatever the inflector
%% makes of it: `I' is not the base of `is'. `have', `do' and `did' are
%% not here: they are the bases and the past of verbs a lesson may give
en_own(W) :-
    (   en_subject(W, _, _) ; en_object(W) ; en_possessive(W) ; en_preposition(W) ; en_question(W, _)
    ;   en_det(W, _, _) ; en_tonic(W, _) ; en_modal_form(W, _, _)
    ;   memberchk(W, [and, not, will, would, am, are, was, were, be, been, being, a, an, the, there, cannot])
    ), !.

en_past_form(had, has).
en_past_form(W, L) :- tr_solve(past_of(W, L)), tr_known(english, L).
en_past_form(W, L) :- tr_english_ed_base(W, B), reason_third(B, L), tr_known(english, L), tr_class(english, L, verb).

en_participle(been, is).
en_participle(W, L) :- tr_solve(participle_of(W, L)), tr_known(english, L).
en_participle(W, L) :- W \== had, en_past_form(W, L), \+ en_copula(W, _, _, _).

%% a gerund: one the lesson stated (`"running" is the gerund of "runs"'),
%% `being', `having', or -ing taken off -- with the e put back (making),
%% a doubled consonant undoubled (running) or ie for y (lying) -- and the
%% base's third person a verb the lesson gives
en_gerund(W, L) :- tr_solve(gerund_of(W, L0)), tr_known(english, L0), !, L = L0.
en_gerund(being, is) :- !.
en_gerund(having, has) :- !.
en_gerund(W, L) :- \+ en_own(W), tr_english_ing_base(W, B), \+ en_own(B), reason_third(B, L), tr_known(english, L), tr_class(english, L, verb), !.

tr_english_ing_base(W, B) :- atom_concat(B0, ing, W), B0 \== '', tr_english_ing_bases(B0, B).
tr_english_ing_bases(B0, B0).
tr_english_ing_bases(B0, B) :- atom_concat(B0, e, B).
tr_english_ing_bases(B0, B) :- sub_atom(B0, _, 1, 0, C), atom_concat(B, C, B0), sub_atom(B, _, 1, 0, C).   % runn -> run
tr_english_ing_bases(B0, B) :- atom_concat(S, y, B0), atom_concat(S, ie, B).                          % ly -> lie

%% English's modals: the word a lesson gives (`can', `may', `must',
%% `should') and its tenses -- `could' is the past and the conditional of
%% `can', `might' of `may', and `should' is what `must' says in the
%% conditional: `Alguien debería estudiar el fenómeno' is somebody should,
%% where English had no form for it and the sentence was refused; read, a
%% `should' is its own word, and `must' has no past
en_modal_form(can, can, present).      en_modal_form(could, can, past).
en_modal_form(may, may, present).      en_modal_form(might, may, conditional).
en_modal_form(must, must, present).    en_modal_form(should, should, present).
en_modal_out(can, present, can).       en_modal_out(can, past, could).      en_modal_out(can, conditional, could).
en_modal_out(may, present, may).       en_modal_out(may, past, might).      en_modal_out(may, conditional, might).
en_modal_out(must, present, must).     en_modal_out(must, conditional, should).
%% (`must' has no past, and `had to' says it: `los pasos que debían haber dado
%% anteriormente' was refused, with nothing to write for `must')
en_modal_out(must, past, 'had to').
en_modal_out(should, present, should).

%% English's demonstratives and the determiners a lesson may give a word
%% for, each with its lexeme and its number: `these' is `this' in the
%% plural, `many' is `much', `few' is `little', `other' is `another'; `some'
%% is either. (`few' is `little''s plural because the lessons' `poco' is one
%% determiner in both numbers: `muy pocos elementos' is `very few elements'
%% and `molto pochi elementi', where a `few' of its own came out `poco'.)
en_det(this, this, singular).       en_det(these, this, plural).
en_det(that, that, singular).       en_det(those, that, plural).
en_det(another, another, singular). en_det(other, another, plural).
en_det(much, much, singular).       en_det(many, much, plural).
en_det('so much', 'so much', singular). en_det('so many', 'so much', plural).   % `tanti film' are so many films
en_det('too much', 'too much', singular). en_det('too many', 'too much', plural).
en_det('as much', 'as much', singular). en_det('as many', 'as much', plural).
en_det(little, little, singular).   en_det(few, little, plural).
en_det(each, each, singular).       en_det(every, every, singular).
en_det(several, several, plural).   en_det(both, both, plural).
en_det(some, some, any).            en_det(such, such, any).
en_demonstrative(this). en_demonstrative(that).

%% a determiner in the number of its noun: the word of that number with
%% the same lexeme, the one for either, or the word as it is
en_any_form(nothing, anything).    en_any_form(nobody, anybody).    en_any_form('no one', anyone).
en_any_form(none, any).
en_det_number(T, Number, T1) :-
    (   en_det(T, L, _) -> ( en_det(T1, L, Number) -> true ; en_det(T1, L, any) -> true ; T1 = T )
    ;   T1 = T
    ).

%% the pronouns that stand alone, third person, with their number
en_tonic(this, singular).      en_tonic(that, singular).      en_tonic(these, plural).      en_tonic(those, plural).
en_tonic(something, singular). en_tonic(anything, singular).  en_tonic(everything, singular). en_tonic(nothing, singular).
en_tonic(somebody, singular).  en_tonic(anybody, singular).   en_tonic(nobody, singular).   en_tonic(everybody, singular).
en_tonic(someone, singular).   en_tonic(anyone, singular).    en_tonic(everyone, singular).
en_tonic(all, plural).         en_tonic(another, singular).   en_tonic(both, plural).       en_tonic(many, plural).
en_tonic(few, plural).         en_tonic(several, plural).     en_tonic(none, singular).     en_tonic(others, plural).
en_tonic(each, singular).
en_tonic_plural(this, these).  en_tonic_plural(that, those).

%% walked -> walk, lived -> live, carried -> carry: the bases an -ed form may have
tr_english_ed_base(W, B) :- atom_concat(Stem, ied, W), atom_concat(Stem, y, B).
tr_english_ed_base(W, B) :- atom_concat(Stem, ed, W), ( B = Stem ; atom_concat(Stem, e, B) ).

%% ---- what the lesson says ------------------------------------------------------

%% mean(W, E) read from the side the word is on
tr_meaning(foreign, W, E) :- tr_solve(mean(W, E)).
tr_meaning(english, E, W) :- tr_solve(mean(W, E)).

%% what a word is, asked once a sentence for each word and class (tr_memo/4):
%% 47 806 times over the thirty-five words of one sentence before it was kept
tr_is(Side, w(W, _), Class) :-
    atom(W), atom(Side), atom(Class), !,
    nb_getval('$tr_language', Lang),
    tr_memo_w(W, is(Lang, Side, Class, W), x, tr_is0(Side, w(W, lower), Class), [_|_]).
tr_is(Side, w(W, _), Class) :-
    atom(W), atom(Side), var(Class), !,
    nb_getval('$tr_language', Lang),
    tr_memo_w(W, is1(Lang, Side, W), C1, tr_is0(Side, w(W, lower), C1), [Class]).
tr_is(Side, X, Class) :- tr_is0(Side, X, Class).

%% what a word is: English's own tables first, then its lexeme's class --
%% which the lesson says of its own words, and an English word is what
%% any of its translations is
tr_is0(english, w(W, _), preposition) :- en_preposition(W), !.
tr_is0(english, w(W, _), conjunction) :- W == and, !.
tr_is0(english, w(W, _), number) :- en_number(W), !.
%% AN ADVERB, A PREPOSITION AND A CONJUNCTION HAVE NO PLURAL, so the lesson's
%% word is one of them only as ITSELF, or as what it elides -- never as the
%% plural of a word that is one. `The adverb "ora" means "now"' made `ore',
%% the hours, an adverb too, and `sin dalle prime ore' read as `the first
%% ones' and then `now': `desde las primeras ahora'.
%% A VERB'S PLURAL IS NO NOUN'S. `Los protagonistas pasan frente a dos
%% estatuas gigantescas y las figuras levantan sus brazos izquierdos' is the
%% heroes passing: the vocabulary states `"pasan" is the plural of "pasa".'
%% for the verb and `"pasas" is the plural of "pasa".' for the noun, a
%% raisin, and one relation cannot say which is which -- so `los
%% protagonistas pasan' was the leading raisins, the subject of `levantan'.
%% The lesson's plural rule says it: where the singular is a verb as well
%% and a rule makes another plural of it, a stated plural no rule makes is
%% the verb's. (A language whose plurals no suffix rule makes -- Italian's
%% -- has no rule to ask, and reads as before.)
tr_is0(foreign, w(W, _), Class) :-
    Class == noun, atom(W), tr_solve(plural_of(W, S)), tr_solve(verb(S)),
    \+ tr_rule_plural(S, W), tr_rule_plural(S, W2), W2 \== W, !, fail.
tr_is0(foreign, w(W, _), Class) :-
    atom(Class), memberchk(Class, [adverb, preposition, conjunction]), !,
    tr_lexeme(foreign, W, L, singular), tr_class(foreign, L, Class), !.
tr_is0(Side, w(W, _), Class) :- tr_lexeme(Side, W, L, _), tr_class(Side, L, Class), !.

%% A CONJUNCTION THAT JOINS TWO PHRASES COORDINATES THEM: `and', `or',
%% `nor', `but'. The lessons call `que' and `che' conjunctions too -- they
%% mean `that' -- and inside a phrase every test used to be `any
%% conjunction', so `el caldo que el pequeño aprende' split at `que' into two
%% phrases joined by `that'. A relative clause needs that word to be what it
%% is, so a phrase is joined only by a coordinator, known by its English
%% meaning.
tr_coord(_, w(',', _)) :- !.                     % the list comma, however a caller spells its case
tr_coord(english, w(W, _)) :- !, en_coordinator(W).
%% ... AND THE ANSWER IS KEPT FOR THE SENTENCE (tr_memo/4): the phrase reader
%% asks it of every word at every place a phrase can end, and the Bovalino
%% letter's rules ask it there twice more. Asked of the lesson each time,
%% those rules cost Livata's twenty-ninth sentence 3 % more inferences than
%% on 1.8.17; kept, it costs 4 % fewer. (The denial's word is not kept: it is
%% asked once a word, and the memo's own lookup cost more than it saved.)
tr_coord(foreign, w(W, _)) :- atom(W), nb_getval('$tr_language', L), tr_memo_w(W, coord(L, W), x, tr_coord_word(W), [_|_]), !.

%% A CONJUNCTION DOES NOT INFLECT, so the word itself is asked, and an
%% elided one for what it elides. Through tr_lexeme/4 each test walked the
%% plurals and every ending rule of the lesson: ten thousand tests over a
%% Tatoeba run of four hundred sentences, the largest new cost in it.
tr_coord_word(W) :- tr_solve(conjunction(W)), tr_solve(mean(W, E)), en_coordinator(E), !.
tr_coord_word(W) :- tr_solve(elision_of(W, F)), tr_coord_word(F).

%% a coordinator that denies: `ni', `né'
tr_neither_word(C) :- tr_solve(conjunction(C)), tr_solve(mean(C, E)), memberchk(E, [neither, nor]), !.

%% English joins a denied list with `nor' after its `neither'
tr_nor(co(w(_, C), A, B0), co(w(nor, C), A, B)) :- !, tr_nor(B0, B).
tr_nor(X, X).
tr_class(_, W, number) :- tr_digits(W), !.
%% A PERCENTAGE IS A NOUN AS WELL: `il restante 41,46% di Chrysler' is the
%% remaining share, an adjective and the thing it describes -- and read as a
%% count with its noun left out, the adjective had nothing to describe and
%% the phrase was refused. Asked for a class it does not name, the number
%% comes first, as it always did.
tr_class(_, W, noun) :- tr_percent(W), !.
tr_class(foreign, W, C) :- tr_class_of(W, C).
tr_class(english, E, C) :- tr_solve(mean(W, E)), tr_class_of(W, C).
tr_class_of(W, C) :-
    atom(C), !,
    memberchk(C, [article, possessive, verb, noun, adjective, pronoun, preposition, adverb, number, conjunction,
                  auxiliary, modal, demonstrative, determiner]),
    G =.. [C, W], tr_solve(G).
tr_class_of(W, C) :-
    member(C, [article, possessive, verb, noun, adjective, pronoun, preposition, adverb, number, conjunction,
               auxiliary, modal, demonstrative, determiner]),
    G =.. [C, W], tr_solve(G).

%% a subject pronoun, with its person and number: English's own, or the
%% lesson's by what it means. English writes `it' and `you' the same as a
%% subject and as an object, so a pronoun of the lesson's that means one
%% of those is a subject only when no other meaning of it is an object's
%% alone (`lo' means `him' and `it': an object, never a subject; `tú'
%% means `you' and may be either) -- and an object only when no other
%% meaning is a subject's alone (`ella' means `she' and `her', and is both)
tr_subject_pronoun(english, W, P, N) :- en_subject(W, P, N).
tr_subject_pronoun(english, W, third, N) :- en_tonic(W, N).
%% THE PLURAL OF `YOU' IS A SUBJECT TOO: `voi direte elezioni' -- English's `you'
%% is both numbers, and the lesson's `"voi" is the plural of "tu".' says which
%% (asked of a pronoun the class test has passed, as one clause: a clause of its
%% own asked the class first and cost the controls' heaviest sentences 1.1 %)
tr_subject_pronoun(foreign, W, P, N) :-
    tr_class_of(W, pronoun),
    (   tr_solve(mean(W, E)), en_subject(E, P0, N0),
        \+ ( en_object(E), tr_solve(mean(W, O)), en_object(O), \+ en_subject(O, _, _) ),
        ( E == you, tr_plural_you(W) -> P = second, N = plural, ! ; P = P0, N = N0 )
    %% -- A FORM THE LESSON STATES AS A PLURAL IS PLURAL, whatever English
    %% says: `Tutti si sono accorti di lui' is everyone noticing him, and
    %% `tutti' is `everyone', singular in English, so the pronoun was singular
    %% and the plural verb refused it (Tatoeba's `Todos están esperando.' the
    %% same). (In this clause, which has asked whether the word is a pronoun:
    %% a clause of its own asked it again of every word)
    ;   P = third, N = plural, tr_solve(plural_of(W, _)), tr_solve(mean(W, E)), en_tonic(E, _), !
    ).
%% a pronoun that stands alone (`esto', `nadie', `estos'): the third person,
%% in the number of its form
%% ... AND `UNO' STANDING ALONE IS THE PRONOUN `one', a subject: `il paese in cui
%% uno va in galera' -- the country where one goes to jail. The lesson calls it
%% a pronoun that does not precede the verb, and no subject reading took it
%% (`uno che ruba una mela' read as a phrase with its relative clause)
tr_subject_pronoun(foreign, W, third, N) :-
    tr_lexeme(foreign, W, L, N), tr_class_of(L, pronoun),
    (   tr_solve(mean(L, E)), en_tonic(E, _)
    ;   N == singular, tr_solve(mean(L, one)), \+ tr_solve(impersonal(L)), !
    ).
%% a pronoun that is the plural of one meaning `you': by its lexeme, which the sentence keeps
tr_plural_you(W) :- atom(W), tr_lexeme(foreign, W, L, plural), L \== W, tr_solve(mean(L, you)), !.
%% AN IMPERSONAL PRONOUN IS A SUBJECT THAT NAMES NOBODY: `si parla di
%% epurazioni', `se habla de purgas' -- the sentence says that purges are
%% spoken of and never who speaks. The lesson says which word it is (`The
%% impersonal pronoun "si" means "one"'), so the construction travels as
%% data; English has no clitic and writes `one'.
%%
%% A THIRD PERSON SINGULAR WITH NO SUBJECT IS STILL REFUSED, which is the
%% rule this sits beside rather than against: `Estaba cansado' could be
%% anybody, and nothing in it says otherwise. The impersonal word IS that
%% something, which is why the shape reads only with it there.
tr_impersonal(foreign, W) :- tr_lexeme(foreign, W, L, _), tr_class_of(L, pronoun), tr_solve(impersonal(L)), !.
tr_impersonal(english, one).

tr_object_pronoun(english, W, W) :- en_object(W).
tr_object_pronoun(english, W, W) :- en_tonic(W, _).
tr_object_pronoun(foreign, W, E) :-
    tr_class_of(W, pronoun), tr_solve(mean(W, E)), en_object(E),
    \+ ( en_subject(E, _, _), tr_solve(mean(W, S)), en_subject(S, _, _), \+ en_object(S) ).
tr_object_pronoun(foreign, W, E) :- tr_lexeme(foreign, W, L, _), tr_class_of(L, pronoun), tr_solve(mean(L, E)), en_tonic(E, _).
%% A REFLEXIVE THAT STANDS AFTER ITS PREPOSITION IS AN OBJECT PRONOUN TOO:
%% `davanti a sé' is in front of oneself, and read as a noun `itself' the
%% phrase after it ended nowhere, so `non si ha davanti a sé nessun altra
%% scelta' was refused where the same words at the end read. Only one the
%% lesson says does not precede the verb: the clitic `si' is the verb's own
%% (reflexive/1, impersonal/1) and is never an object here.
tr_object_pronoun(foreign, W, E) :-
    tr_class_of(W, pronoun), tr_solve(neg(precede(W, verb))), tr_solve(mean(W, E)), en_reflexive(E).
%% AN ELIDED FORM IS THE WORD IT ELIDES. `La sinistra L'ha attaccata' is
%% `la ha attaccata', and the clitic was read as no pronoun at all, because
%% the clauses above ask tr_class_of/2 of the WORD and an elision has no
%% class of its own -- tr_lexeme/4 reads it, tr_class_of/2 does not.
tr_object_pronoun(foreign, W, E) :-
    tr_solve(elision_of(W, F)), tr_object_pronoun(foreign, F, E).

%% the lesson proved: plain, or under the language it was learned in --
%% its facts, its rules with their bodies, and the library's helpers
tr_solve(G) :- nb_getval('$tr_language', L), tr_lesson(L, G).

tr_lesson(none, G) :- !, tr_solve_plain(G).
tr_lesson(_, G) :- tr_helper(G), !, tr_solve_plain(G).
%% A NUMBER IN DIGITS IS A NUMBER to the lesson's rules as well: `Every
%% number is masculine.' is how a lesson says `il 4%' and `el 2001', and a
%% number written in digits is no word a lesson could have called one. With
%% no gender at all `el 1,4%' went out as `la 1,4%' and `en el 2001' as
%% `nella 2001', the first article the lesson gives for `the'.
tr_lesson(_, number(W)) :- atom(W), tr_digits(W), !.
%% -- AND ONLY A PREDICATE THE LESSON STATED IS CALLED. A relation of which
%% a language states no fact -- no Spanish fact is a `particle_of' or an
%% `elision_of' -- raised `existence_error' the first time a process asked
%% it, and the engine WARMS the whole store before it throws, so another
%% process's declaration is found: 0.8 s on a 352 MB store, once a name,
%% two or three names in every process. The registry learning writes
%% (lesson_predicate/3, declared here, so asking it never raises) says
%% which names the lesson has -- asked as a condition, because a cut here
%% would shut out the rules below: `precede' has facts AND `Every pronoun
%% precedes the verb', and behind a cut `no lo vio' came out `no vio lo'.
tr_lesson(L, G) :-
    functor(G, Name, A), atomic_list_concat([L, ':', Name], N),
    (   lesson_predicate(N, L, A) -> G =.. [_|Args], F =.. [N|Args], catch(F, error(existence_error(procedure, _), _), fail) ).
tr_lesson(L, G) :- lesson(L, (G :- B)), tr_body(L, B).

tr_body(L, (A, B)) :- !, tr_body(L, A), tr_body(L, B).
tr_body(L, \+ G) :- !, \+ tr_body(L, G).
tr_body(_, true) :- !.
tr_body(L, G) :- tr_lesson(L, G).

tr_helper(end_in(_, _)).    tr_helper(end_with(_, _)).
tr_helper(begin_with(_, _)). tr_helper(start_with(_, _)).

%% a lesson that says nothing proves nothing: silence, never an error
tr_solve_plain(Goal) :- catch(Goal, error(existence_error(procedure, _), _), fail).

%% what a rule says, unless the lesson denied it of this word: `Every
%% pronoun precedes the verb. The pronoun "él" does not precede the verb.'
tr_holds(G) :- \+ tr_solve(neg(G)), tr_solve(G).

%% ---- English's own words ----------------------------------------------------------

%% the preposition an English verb governs, where it is not the one the other
%% language's verb has (tr_governed/2): `depends on', `counts on'
en_governs(scatters, across).   % (`organi ... sparsi per la penisola', scattered across it)
en_governs('takes off', from).  % (`despegar ... de Barcelona', took off from it)
en_governs(depends, on).        en_governs(counts, on).         en_governs(relies, on).
en_governs(insists, on).        en_governs(participates, in).   en_governs(consists, of).
en_governs(bets, on).            en_governs(distances, from).    en_governs(prevails, over).      en_governs(ousts, from).
en_governs(believes, in).       en_governs(trusts, in).         en_governs(thinks, of).
en_governs(skimps, on).         % `no se ha escatimado en gastos'
en_governs(agonises, over).       % `si è limitata a macerarsi su chi dovesse vendere'
en_governs(dreams, of).           % `un ataque con el que sueñan los interistas'
en_governs(converts, into).       % `convierte el agua en vino' (`"convierte" takes "en" before the phrase.')
en_governs(endows, with).         % `altre città europee dotate di canali' (tr_of_participle/2)
en_governs(equips, with).
en_governs(covers, with).
en_governs(fills, with).
en_governs(loads, with).
en_governs(plants, with).
en_governs(centres, on).          % `centraron sus peticiones en el cierre de los sábados'
en_governs(describes, as).        % `un régimen calificado de "semilaboral"' (`"califica" takes "de" before the phrase.')
en_governs(defines, as).          % `que se define como "un punto de encuentro"' (`"define" takes "como" before the phrase.')
en_governs(attests, to).          % `il musicista testimonia del suo grande amore per l'Italia'
en_governs(spends, on).           % `spende in svaghi e vacanze per il figlio'
%% (the English verbs that take bare a phrase the lesson's verb governs with a preposition)
en_bare_object(influences).      % `la possibilità di incidere sulle scelte del management'
en_bare_object(becomes).         % `la apertura se ha convertido en el elemento negociador'
en_bare_object(answers).         % `mia moglie Paolinha ha risposto al telefono', answered the phone
en_bare_object('takes into account').   % `Non tengono conto per esempio della mancanza cronica di posti'
en_bare_object(enjoys).           % `goza, también, de una enorme fama internacional', enjoys it (`enjoys, of an enormous')
en_bare_object(hinders).          % `de poner trabas a la pacificación', of hindering it (`hindering to the pacification')
%% ... and a verb of several words that ends in a preposition, which is the phrase's: `il gruppo
%% "Insula", che si occupa della sistemazione dei canali' takes charge of the arrangement, and it
%% was `takes charge of of the arrangement'
en_bare_object(V) :-
    atom(V), atomic_list_concat(Parts, ' ', V), Parts = [_, _|_], last(Parts, W),
    memberchk(W, [of, on, in, for, from, about, at, with, by, to, into]), !.
%% the participles English puts before a phrase as a preposition: `given the situation' (tr_comp_out/7's abso/2)
en_prepositional_participle(given).     en_prepositional_participle(seen).     en_prepositional_participle(granted).
en_prepositional_participle(included).  en_prepositional_participle(excluded).
%% ... and the two whose preposition is their -ing form
en_participle_preposition(included, including).  en_participle_preposition(excluded, excluding).
%% the preposition an English verb takes before the phrase that is its object
%% in the other languages (tr_comp_out/7)
en_object_with(listens, to).    en_object_with(looks, at).      en_object_with(searches, for).
en_object_with(asks, for).      % `chiedeva una copia del mio disco', `ci chiese i documenti': asked us for them

en_subject(i, first, singular).      en_subject(you, second, singular).
en_subject(he, third, singular).     en_subject(she, third, singular).   en_subject(it, third, singular).
en_subject(we, first, plural).       en_subject(they, third, plural).
en_object(me).  en_object(you). en_object(him). en_object(her). en_object(it). en_object(us). en_object(them).
en_possessive(my). en_possessive(your). en_possessive(his). en_possessive(her). en_possessive(its). en_possessive(our). en_possessive(their).
en_copula(am, first, singular, present).   en_copula(is, third, singular, present).   en_copula(are, second, singular, present).
en_copula(are, third, plural, present).     en_copula(was, third, singular, past).     en_copula(were, third, plural, past).
en_preposition(in).  en_preposition(on).  en_preposition(at).   en_preposition(with).  en_preposition(to).
en_preposition(from). en_preposition(of). en_preposition(for).  en_preposition(by).    en_preposition(under).
en_preposition(over). en_preposition(near). en_preposition(behind). en_preposition(before). en_preposition(after).
en_preposition(into). en_preposition(about). en_preposition(between). en_preposition(without).
en_month(W) :- memberchk(W, [january, february, march, april, may, june, july, august, september, october, november, december]).
%% the adjectives of a country, a people or a creed, written with a capital
%% (and a word of two joined by a hyphen that opens on one: `los satanistas hispanohablantes' are the
%% Spanish-speaking satanists)
en_nationality(W) :- atom(W), atomic_list_concat([N, _|_], '-', W), en_nationality(N), !.
en_nationality(W) :-
    memberchk(W, [indian, basque, catalan, spanish, italian, french, german, british, english, american, mexican, chinese,
                  japanese, russian, portuguese, dutch, greek, turkish, arab, swiss, swedish, norwegian, danish, finnish,
                  czech, palestinian, israeli, african, european, argentine, brazilian, colombian, cuban, peruvian,
                  chilean, moroccan, egyptian, lebanese, iraqi, iranian, afghan, korean, canadian, australian, irish,
                  scottish, welsh, belgian, austrian, hungarian, romanian, bulgarian, serbian, croatian, bosnian,
                  albanian, jewish, christian, muslim, catholic, islamic, olympic, roman, tuscan, sicilian, neapolitan,
                  milanese, venetian, galician, andalusian, valencian, asian, bohemian, chechen, lombard, bellunese,
                  corsican, mediterranean, gaullist, nordic]).
%% the days and the months written with a capital, `march' and `may' left out: they are
%% a march and a modal too, and only the lesson knows which was meant
en_calendar_word(W) :- memberchk(W, [monday, tuesday, wednesday, thursday, friday, saturday, sunday,
                                     january, february, april, june, july, august, september, october, november, december]).
%% the times that `last' and `next' go before
en_time_noun(W) :- en_calendar_word(W), !.
en_time_noun(W) :- memberchk(W, [week, month, year, summer, winter, spring, autumn, fall, night, weekend, century, decade, semester, season, may, march]).
en_number(W) :- memberchk(W, [one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve, thirteen, fourteen, fifteen,
                              sixteen, seventeen, eighteen, nineteen, twenty, thirty, forty, fifty, sixty, seventy, eighty, ninety,
                              hundred, thousand, million]).
%% the words no lesson gives and none needs to: they carry a form, not a meaning
en_function(W) :- memberchk(W, [not, does, do, did, will, would, has, have, had, am, are, was, were, be, been, an, there, cannot]).

%% ---- the sentence back as text ---------------------------------------------------

tr_join(To, Kind, Outs0, Stop, Out) :-
    tr_contract(To, Outs0, Outs),
    findall(A, ( member(o(T, C), Outs), tr_word_text(To, T, C, A) ), As0),
    tr_tidy_commas(As0, As1),
    tr_glue(As1, As2), tr_glue_mark(To, As2, As),
    atomic_list_concat(As, ' ', S0),
    tr_cap_head(S0, S1),
    tr_stop_parts(Stop, Before, Inner, StopCode, After),
    atom_codes(S1, Cs), append(Cs, Inner, Cs0),
    %% a sentence that ends in its colon takes no full stop after it: the
    %% text had none, and a piece with no stop is given `.' by tr_upto/4
    ( StopCode == 46, Inner == [], last(Cs, 58) -> Cs1 = Cs0 ; append(Cs0, [StopCode], Cs1) ),     % 58 is `:'
    atom_codes(Out0, Cs1),
    (   To == foreign, Kind == question, once(tr_solve(begin(M, question))), \+ memberchk(o(M, _), Outs) -> atom_concat(M, Out0, Out1)
    %% ... AND AN EXCLAMATION'S, where the lesson has one: `The mark "¡"
    %% begins the exclamation.' -- `Mio dio, che tristezza!' came out with
    %% no opening mark in Spanish
    ;   To == foreign, StopCode == 33, once(tr_solve(begin(M, exclamation))) -> atom_concat(M, Out0, Out1)
    ;   Out1 = Out0
    ),
    %% the marks round a quoted sentence go outside everything, the
    %% question's own opening mark included: `"¿Cómo ...?".'
    atom_codes(Out1, C1), append(Before, C1, C2), append(C2, After, C3), atom_codes(Out, C3).

%% the lesson's opening mark joins the word after it, where a clause after a
%% colon carries one (tr_write/4)
tr_glue_mark(foreign, As0, As) :- once(tr_solve(begin(M, question))), append(Pre, [M, A|Post], As0), !,
    atom_concat(M, A, MA), append(Pre, [MA|Post], As).
tr_glue_mark(_, As, As).

%% a comma at the end, or after another, is dropped: an apposition's closing
%% comma where the sentence ends, or where a clause's comma follows it
tr_tidy_commas([], []).
tr_tidy_commas([',', ','|As], Out) :- !, tr_tidy_commas([','|As], Out).
tr_tidy_commas([','], []) :- !.
tr_tidy_commas([',', ';'|As], Out) :- !, tr_tidy_commas([';'|As], Out).
tr_tidy_commas([A|As], [A|Out]) :- tr_tidy_commas(As, Out).

%% a comma joins the word before it with no space between
tr_glue(['(', A|Rest], Out) :- !, atom_concat('(', A, A1), tr_glue([A1|Rest], Out).
tr_glue([A, ')'|Rest], Out) :- !, atom_concat(A, ')', A1), tr_glue([A1|Rest], Out).
tr_glue([A, ','|Rest], Out) :- !, atom_concat(A, ',', A1), tr_glue([A1|Rest], Out).
tr_glue([A, '...'|Rest], Out) :- !, atom_concat(A, '...', A1), tr_glue([A1|Rest], Out).
tr_glue([A, ';'|Rest], Out) :- !, atom_concat(A, ';', A1), tr_glue([A1|Rest], Out).
tr_glue([A, ':'|Rest], Out) :- !, atom_concat(A, ':', A1), tr_glue([A1|Rest], Out).
tr_glue([A, '”'|Rest], Out) :- !, atom_concat(A, '”', A1), tr_glue([A1|Rest], Out).
tr_glue([A, '"'|Rest], Out) :- !, atom_concat(A, '"', A1), tr_glue([A1|Rest], Out).
tr_glue([A|As], [A|Out]) :- !, tr_glue(As, Out).
tr_glue([], []).

%% a quoted word gets its marks back: both for one word, the opening one on
%% the head of a run and the closing one on its last word
%% A WORD THE LESSON CALLS AN ACRONYM GOES OUT IN CAPITALS: a lesson keeps
%% every word it quotes in small letters, so `"PIB"' is `pib' to it and `la
%% crescita del suo pil' came out `el crecimiento de su pib'. `"pib" is an
%% acronym.' says it, and the marks and the head's capital apply after.
tr_word_text(foreign, T0, C, A) :- atom(T0), tr_solve(acronym(T0)), !, upcase_atom(T0, T), tr_word_text(none, T, C, A).
%% ... AND AN ENGLISH NAME THE SOURCE'S LESSON CALLS ONE: `El COI abrió ayer una investigación' is the IOC, the meaning
%% `The name "coi" means "IOC".' gives, and a lesson keeps a meaning in small letters too, so it came out `The Ioc'.
%% `"ioc" is an acronym.' says it; asked of a word with a capital only, as a name's are
tr_word_text(english, T0, upper, A) :- atom(T0), tr_solve(acronym(T0)), !, upcase_atom(T0, T), tr_word_text(none, T, upper, A).
%% English's I is a capital wherever it stands, and a quotation mark on it
%% leaves it one: the clauses below that put a mark on a word came before
%% the one that makes it a capital, and `", spiega Vittori, "nel corso
%% cercherò di illustrare' was `"i will search' (1.8.28 wrote `"i eat')
tr_word_text(english, i, C, A) :- nonvar(C), memberchk(C, [rep, qboth, qopen, qclose]), !, tr_word_text(english, 'I', C, A).
tr_word_text(_, T, rep, A) :- !, atomic_list_concat([T, ', ', T], A).       % a word said twice
tr_word_text(_, T, qboth, A) :- !, atomic_list_concat(['"', T, '"'], A).
tr_word_text(_, T, qopen, A) :- !, atomic_list_concat(['"', T], A).
tr_word_text(_, T, qclose, A) :- !, atomic_list_concat([T, '"'], A).

tr_word_text(english, i, _, 'I') :- !.
tr_word_text(_, T, upper, A) :- !, tr_cap(T, A).
tr_word_text(_, T, _, T).

%% the sentence's first letter up, past a quotation mark that opens it:
%% `"Gli ho dato riposo'
tr_cap_head(S0, S) :-
    atom_codes(S0, Cs0),
    (   Cs0 = [34|Rest] -> atom_codes(R0, Rest), tr_cap(R0, R), atom_concat('"', R, S)
    ;   Cs0 = [226, 128, 156|Rest] -> atom_codes(R0, Rest), tr_cap(R0, R), atom_concat('“', R, S)
    ;   Cs0 = [8220|Rest] -> atom_codes(R0, Rest), tr_cap(R0, R), atom_concat('“', R, S)
    ;   tr_cap(S0, S)
    ).

%% the first letter up: an ASCII one, or one of U+00E0..U+00FE, the two
%% bytes 195 and 160..190 in UTF-8 (`él' is `Él'); the division sign is
%% no letter
tr_cap(W, C) :- atom_codes(W, [195, B|R]), B >= 160, B =< 190, B =\= 183, !, B1 is B - 32, atom_codes(C, [195, B1|R]).
tr_cap(W, C) :- atom_codes(W, [C0|R]), C0 >= 224, C0 =< 254, C0 =\= 247, rt_chars, !, C1 is C0 - 32, atom_codes(C, [C1|R]).
tr_cap(W, C) :- atom_codes(W, [F|R]), ( F >= 97, F =< 122 -> F1 is F - 32 ; F1 = F ), atom_codes(C, [F1|R]).
